const diffSettings = {
  easy: { maxNum: 10, showVisuals: true, questions: 10 },
  medium: { maxNum: 20, showVisuals: true, questions: 10 },
  hard: { maxNum: 50, showVisuals: false, questions: 15 }
};

// ===== DIFFICULTY SELECTION =====
function selectDifficulty(diff) {
  playSound('click');
  difficulty = diff;
  document.querySelectorAll('.diff-btn').forEach(b => b.classList.remove('selected'));
  document.querySelector(`[data-diff="${diff}"]`).classList.add('selected');
}

// ===== SCREEN MANAGEMENT =====
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.add('hidden'));
  document.getElementById(id).classList.remove('hidden');
}

// ===== START GAME =====
function startGame() {
  initAudio();
  playSound('click');
  const settings = diffSettings[difficulty];
  totalQuestions = settings.questions;
  score = 0;
  lives = maxLives;
  currentQuestion = 0;
  streak = 0;
  bestStreak = 0;
  correctAnswers = 0;

  showScreen('gameScreen');
  updateLives();
  updateScore();
  nextQuestion();
}

// ===== GENERATE PROBLEM =====
function generateProblem() {
  const settings = diffSettings[difficulty];
  const max = settings.maxNum;
  const useAddition = Math.random() > 0.5;
  let a, b, answer, operator;

  if (useAddition) {
    a = Math.floor(Math.random() * max) + 1;
    b = Math.floor(Math.random() * max) + 1;
    answer = a + b;
    operator = '+';
  } else {
    a = Math.floor(Math.random() * max) + 1;
    b = Math.floor(Math.random() * a) + 1; // ensure positive result
    answer = a - b;
    operator = '-';
  }

  return { a, b, answer, operator };
}

// ===== GENERATE CHOICES =====
function generateChoices(correctAnswer) {
  let choices = new Set([correctAnswer]);
  let attempts = 0;
  while (choices.size < 4 && attempts < 100) {
    let offset = Math.floor(Math.random() * 10) - 5;
    if (offset === 0) offset = 1;
    let wrong = correctAnswer + offset;
    if (wrong >= 0) choices.add(wrong);
    attempts++;
  }
  // Fill remaining if needed
  let fill = 1;
  while (choices.size < 4) {
    let wrong = correctAnswer + fill * (Math.random() > 0.5 ? 1 : -1) * Math.ceil(Math.random() * 3);
    if (wrong >= 0) choices.add(wrong);
    fill++;
  }
  return Array.from(choices).sort(() => Math.random() - 0.5);
}

// ===== NEXT QUESTION =====
function nextQuestion() {
  if (currentQuestion >= totalQuestions || lives <= 0) {
    endGame();
    return;
  }

  answered = false;
  currentQuestion++;
  currentProblem = generateProblem();

  document.getElementById('questionNum').textContent = currentQuestion;
  document.getElementById('totalQuestions').textContent = totalQuestions;
  document.getElementById('questionLabel').textContent = `Question ${currentQuestion}`;
  document.getElementById('progressBar').style.width = `${((currentQuestion - 1) / totalQuestions) * 100}%`;

  renderQuestion();
  renderVisuals();
  renderChoices();
  document.getElementById('feedbackMsg').textContent = '';
  document.getElementById('feedbackMsg').className = 'feedback-message';
}

// ===== RENDER QUESTION =====
function renderQuestion() {
  const { a, b, answer, operator } = currentProblem;
  document.getElementById('questionText').innerHTML = `
    <span>${a}</span>
    <span class="operator">${operator}</span>
    <span>${b}</span>
    <span class="equals">=</span>
    <span class="blank">?</span>
  `;
}

// ===== RENDER VISUALS =====
function renderVisuals() {
  const container = document.getElementById('visualAids');
  const settings = diffSettings[difficulty];

  if (!settings.showVisuals) {
    container.innerHTML = '';
    return;
  }

  const emoji = emojis[Math.floor(Math.random() * emojis.length)];
  const { a, b, answer, operator } = currentProblem;

  let html = '';

  if (operator === '+') {
    html += '<div class="visual-group">';
    for (let i = 0; i < a; i++) html += `<span class="visual-item" style="animation-delay:${i * 0.05}s">${emoji}</span>`;
    html += '</div>';
    html += '<div class="visual-group">';
    for (let i = 0; i < b; i++) html += `<span class="visual-item" style="animation-delay:${(a + i) * 0.05}s">${emoji}</span>`;
    html += '</div>';
  } else {
    html += '<div class="visual-group">';
    for (let i = 0; i < a; i++) {
      const crossed = i < b ? 'crossed' : '';
      html += `<span class="visual-item ${crossed}" style="animation-delay:${i * 0.05}s">${emoji}</span>`;
    }
    html += '</div>';
  }

  container.innerHTML = html;
}

// ===== RENDER CHOICES =====
function renderChoices() {
  const grid = document.getElementById('answersGrid');
  const choices = generateChoices(currentProblem.answer);

  grid.innerHTML = choices.map(c => `
    <button class="answer-btn" onclick="checkAnswer(${c}, this)">${c}</button>
  `).join('');
}

// ===== CHECK ANSWER =====
function checkAnswer(selected, btn) {
  if (answered) return;
  answered = true;
  playSound('click');

  const correct = currentProblem.answer;
  const isCorrect = selected === correct;

  // Disable all buttons
  document.querySelectorAll('.answer-btn').forEach(b => {
    b.classList.add('disabled');
    if (parseInt(b.textContent) === correct) {
      b.classList.add('correct');
    }
  });

  const feedback = document.getElementById('feedbackMsg');

  if (isCorrect) {
    btn.classList.add('correct');
    streak++;
    if (streak > bestStreak) bestStreak = streak;
    correctAnswers++;

    let points = 10;
    if (streak >= 5) points = 25;
    else if (streak >= 3) points = 20;
    else if (streak >= 2) points = 15;
    score += points;

    feedback.textContent = getCorrectMessage();
    feedback.className = 'feedback-message correct-msg';

    playSound('correct');
    if (streak >= 3) playSound('streak');

    spawnFloatEmoji(btn, getCorrectEmoji());
    if (streak >= 3) spawnConfetti();

    // Update streak badge
    const badge = document.getElementById('streakBadge');
    if (streak >= 2) {
      badge.textContent = `🔥 ${streak} in a row!`;
      badge.classList.add('visible');
    }
  } else {
    btn.classList.add('wrong');
    streak = 0;
    lives--;
    updateLives();

    feedback.textContent = `Oops! The answer is ${correct}`;
    feedback.className = 'feedback-message wrong-msg';

    playSound('wrong');
    document.getElementById('streakBadge').classList.remove('visible');
  }

  updateScore();

  setTimeout(() => {
    nextQuestion();
  }, isCorrect ? 1200 : 1800);
}

// ===== UPDATE UI =====
function updateScore() {
  document.getElementById('scoreDisplay').textContent = score;
}

function updateLives() {
  const container = document.getElementById('livesContainer');
  let html = '';
  for (let i = 0; i < maxLives; i++) {
    const lost = i >= lives ? 'lost' : '';
    html += `<span class="heart ${lost}">❤️</span>`;
  }
  container.innerHTML = html;
}

// ===== MESSAGES =====
function getCorrectMessage() {
  const msgs = ['Awesome! 🎉', 'Great job! 🌟', 'You\'re amazing! 💪', 'Correct! ✨', 'Brilliant! 🧠', 'Super! 🚀', 'Wonderful! 🎯', 'Perfect! 💎', 'Fantastic! 🏆', 'Amazing! ⭐'];
  return msgs[Math.floor(Math.random() * msgs.length)];
}

function getCorrectEmoji() {
  const emojis = ['⭐', '🌟', '✨', '💫', '🎉', '🎊', '🏅', '💯'];
  return emojis[Math.floor(Math.random() * emojis.length)];
}

// ===== FLOATING EMOJI =====
function spawnFloatEmoji(element, emoji) {
  const rect = element.getBoundingClientRect();
  const el = document.createElement('div');
  el.className = 'float-emoji';
  el.textContent = emoji;
  el.style.left = rect.left + rect.width / 2 - 15 + 'px';
  el.style.top = rect.top - 10 + 'px';
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 1500);
}

// ===== CONFETTI =====
function spawnConfetti() {
  const colors = ['#f093fb', '#f5576c', '#4facfe', '#43e97b', '#fee140', '#fa709a', '#a18cd1'];
  for (let i = 0; i < 30; i++) {
    const piece = document.createElement('div');
    piece.className = 'confetti-piece';
    piece.style.left = Math.random() * 100 + 'vw';
    piece.style.top = '-10px';
    piece.style.width = Math.random() * 10 + 5 + 'px';
    piece.style.height = Math.random() * 10 + 5 + 'px';
    piece.style.background = colors[Math.floor(Math.random() * colors.length)];
    piece.style.borderRadius = Math.random() > 0.5 ? '50%' : '2px';
    piece.style.animationDuration = Math.random() * 2 + 1.5 + 's';
    piece.style.animationDelay = Math.random() * 0.5 + 's';
    document.body.appendChild(piece);
    setTimeout(() => piece.remove(), 4000);
  }
}

// ===== END GAME =====
function endGame() {
  playSound('gameover');
  showScreen('endScreen');

  const accuracy = totalQuestions > 0 ? Math.round((correctAnswers / totalQuestions) * 100) : 0;
  let stars = 0;
  if (accuracy >= 90) stars = 3;
  else if (accuracy >= 70) stars = 2;
  else if (accuracy >= 50) stars = 1;

  // End screen messages
  const endEmoji = document.getElementById('endEmoji');
  const endTitle = document.getElementById('endTitle');
  const endSubtitle = document.getElementById('endSubtitle');

  if (stars === 3) {
    endEmoji.textContent = '🏆';
    endTitle.textContent = 'Perfect Score!';
    endSubtitle.textContent = "You're a math genius!";
    playSound('victory');
    spawnConfetti();
    setTimeout(spawnConfetti, 500);
  } else if (stars === 2) {
    endEmoji.textContent = '🌟';
    endTitle.textContent = 'Great Job!';
    endSubtitle.textContent = "You're getting really good!";
  } else if (stars === 1) {
    endEmoji.textContent = '👍';
    endTitle.textContent = 'Nice Try!';
    endSubtitle.textContent = 'Keep practicing, you\'ll get better!';
  } else {
    endEmoji.textContent = '💪';
    endTitle.textContent = 'Keep Going!';
    endSubtitle.textContent = 'Practice makes perfect!';
  }

  document.getElementById('finalScore').textContent = score;
  document.getElementById('correctCount').textContent = `${correctAnswers}/${totalQuestions}`;
  document.getElementById('bestStreak').textContent = bestStreak;
  document.getElementById('accuracy').textContent = accuracy + '%';

  // Stars
  const starsContainer = document.getElementById('starsContainer');
  let starsHtml = '';
  for (let i = 0; i < 3; i++) {
    const earned = i < stars ? 'earned' : '';
    const delay = i * 0.3;
    starsHtml += `<span class="star ${earned}" style="animation-delay:${delay}s">${i < stars ? '⭐' : '☆'}</span>`;
  }
  starsContainer.innerHTML = starsHtml;
}

// ===== RESTART =====
function restartGame() {
  playSound('click');
  showScreen('startScreen');
}

// ===== KEYBOARD SUPPORT =====
document.addEventListener('keydown', (e) => {
  if (document.getElementById('gameScreen').classList.contains('hidden')) return;
  if (answered) return;

  const keyMap = { '1': 0, '2': 1, '3': 2, '4': 3 };
  const idx = keyMap[e.key];
  if (idx !== undefined) {
    const buttons = document.querySelectorAll('.answer-btn');
    if (buttons[idx]) buttons[idx].click();
  }
});
</script>
</body>
