            floatingTexts.push(new FloatingText(this.x, this.y, '-1 💥', '#ff2222', 40));
            lives = 0;
            endGame();
            return;
        }

        // Score
        combo++;
        comboTimer = 120;
        let multiplier = Math.min(combo, 5);
        let points = this.type.points * multiplier;
        score += points;
        if (score < 0) score = 0;

        floatingTexts.push(new FloatingText(this.x, this.y - 30, `+${points}`, '#ffcc00', 30));
        if (combo >= 3) {
            floatingTexts.push(new FloatingText(this.x, this.y - 60, `${combo}x COMBO!`, '#ff6644', 22));
        }

        // Sliced pieces
        let dir = Math.atan2(mouseY - this.y, mouseX - this.x);
        for (let side = -1; side <= 1; side += 2) {
            slicedPieces.push({
                x: this.x,
                y: this.y,
                vx: Math.cos(dir + side * 1.2) * (3 + Math.random() * 3),
                vy: Math.sin(dir + side * 1.2) * (3 + Math.random() * 3) - 2,
                rotation: this.rotation,
                rotSpeed: side * (0.05 + Math.random() * 0.08),
                size: this.size,
                emoji: this.type.emoji,
                alpha: 1,
                gravity: 0.2,
                side: side
            });
        }

        // Juice particles
        for (let i = 0; i < 12; i++) {
            particles.push(new Particle(this.x, this.y, 'juice'));
        }

        updateUI();
    }
}

// Particle class
class Particle {
    constructor(x, y, type) {
        this.x = x;
        this.y = y;
        this.type = type;
        this.alpha = 1;
        this.life = 1;

        if (type === 'juice') {
            let angle = Math.random() * Math.PI * 2;
            let speed = Math.random() * 6 + 2;
            this.vx = Math.cos(angle) * speed;
            this.vy = Math.sin(angle) * speed;
            this.size = Math.random() * 6 + 2;
            this.gravity = 0.15;
            this.decay = Math.random() * 0.02 + 0.015;
            let colors = ['#ff4466', '#ffcc00', '#44ff66', '#44aaff', '#ff66aa', '#aaff44'];
            this.color = colors[Math.floor(Math.random() * colors.length)];
        } else if (type === 'explosion') {
            let angle = Math.random() * Math.PI * 2;
            let speed = Math.random() * 10 + 3;
            this.vx = Math.cos(angle) * speed;
            this.vy = Math.sin(angle) * speed;
            this.size = Math.random() * 8 + 3;
            this.gravity = 0.1;
            this.decay = Math.random() * 0.02 + 0.01;
            let colors = ['#ff2200', '#ff6600', '#ffcc00', '#ffffff'];
            this.color = colors[Math.floor(Math.random() * colors.length)];
        } else if (type === 'spark') {
            let angle = Math.random() * Math.PI * 2;
            let speed = Math.random() * 4 + 1;
            this.vx = Math.cos(angle) * speed;
            this.vy = Math.sin(angle) * speed - 2;
            this.size = Math.random() * 3 + 1;
            this.gravity = 0.05;
            this.decay = 0.03;
            this.color = '#ffdd44';
        }
    }

    update() {
        this.x += this.vx;
        this.vy += this.gravity;
        this.y += this.vy;
        this.life -= this.decay;
        this.alpha = this.life;
        this.vx *= 0.99;
        return this.life > 0;
    }

    draw() {
        ctx.save();
        ctx.globalAlpha = this.alpha;
        ctx.fillStyle = this.color;
        ctx.shadowColor = this.color;
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size * this.alpha, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
    }
}

// Floating text
class FloatingText {
    constructor(x, y, text, color, size) {
        this.x = x;
        this.y = y;
        this.text = text;
        this.color = color;
        this.size = size;
        this.alpha = 1;
        this.vy = -2;
        this.life = 1;
        this.decay = 0.015;
    }

    update() {
        this.y += this.vy;
        this.vy *= 0.98;
        this.life -= this.decay;
        this.alpha = this.life;
        return this.life > 0;
    }

    draw() {
        ctx.save();
        ctx.globalAlpha = this.alpha;
        ctx.font = `bold ${this.size}px 'Segoe UI', sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = this.color;
        ctx.shadowColor = this.color;
        ctx.shadowBlur = 15;
        ctx.fillText(this.text, this.x, this.y);
        ctx.restore();
    }
}

// Blade trail
class BladeTrail {
    constructor() {
        this.points = [];
        this.maxPoints = 20;
    }

    addPoint(x, y) {
        this.points.push({ x, y, alpha: 1, size: 8 });
        if (this.points.length > this.maxPoints) this.points.shift();
    }

    update() {
        for (let p of this.points) {
            p.alpha *= 0.9;
            p.size *= 0.95;
        }
        this.points = this.points.filter(p => p.alpha > 0.05);
    }

    draw() {
        if (this.points.length < 2) return;

        // Outer glow
        ctx.save();
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        for (let layer = 2; layer >= 0; layer--) {
            ctx.beginPath();
            ctx.moveTo(this.points[0].x, this.points[0].y);
            for (let i = 1; i < this.points.length; i++) {
                ctx.lineTo(this.points[i].x, this.points[i].y);
            }
            ctx.strokeStyle = layer === 0 ? '#ffffff' :
                layer === 1 ? 'rgba(100, 200, 255, 0.6)' : 'rgba(50, 100, 255, 0.2)';
            ctx.lineWidth = layer === 0 ? 3 : layer === 1 ? 8 : 18;
            ctx.shadowColor = '#4488ff';
            ctx.shadowBlur = layer === 0 ? 10 : 20;
            ctx.stroke();
        }

        // Spark tips
        if (this.points.length > 1) {
            let last = this.points[this.points.length - 1];
            let grad = ctx.createRadialGradient(last.x, last.y, 0, last.x, last.y, 20);
            grad.addColorStop(0, 'rgba(200, 230, 255, 0.8)');
            grad.addColorStop(0.5, 'rgba(100, 180, 255, 0.3)');
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.fillRect(last.x - 20, last.y - 20, 40, 40);
        }

        ctx.restore();
    }
}

const blade = new BladeTrail();

// Spawning
function spawnFood() {
    let count = Math.floor(Math.random() * 3) + 1 + Math.floor(difficulty / 3);
    let isBomb = Math.random() < Math.min(0.15 + difficulty * 0.02, 0.35);

    for (let i = 0; i < count; i++) {
        if (isBomb && i === 0) {
            foods.push(new Food(bombTypes[0], true));
        } else {
            let type = foodTypes[Math.floor(Math.random() * foodTypes.length)];
            foods.push(new Food(type, false));
        }
    }
}

// Collision detection
function checkSlice(food) {
    if (food.sliced) return false;
    if (blade.points.length < 2) return false;

    let lastPoint = blade.points[blade.points.length - 1];
    let prevPoint = blade.points[blade.points.length - 2];

    let dx = lastPoint.x - prevPoint.x;
    let dy = lastPoint.y - prevPoint.y;
    let dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < 3) return false;

    // Distance from food center to blade line segment
    let foodDx = food.x - prevPoint.x;
    let foodDy = food.y - prevPoint.y;
    let t = Math.max(0, Math.min(1, (foodDx * dx + foodDy * dy) / (dist * dist)));
    let closestX = prevPoint.x + t * dx;
    let closestY = prevPoint.y + t * dy;
    let distToBlade = Math.sqrt((food.x - closestX) ** 2 + (food.y - closestY) ** 2);

    return distToBlade < food.size * 0.7;
}

// UI Updates
function updateUI() {
    document.getElementById('score-display').textContent = score;
    let heartsStr = '';
    for (let i = 0; i < 3; i++) {
        heartsStr += i < lives ? '❤️' : '🖤';
    }
    document.getElementById('lives-display').textContent = heartsStr;
    document.getElementById('missed-display').textContent = '';

    let comboEl = document.getElementById('combo-display');
    if (combo >= 3) {
        comboEl.textContent = `🔥 ${combo}x COMBO`;
        comboEl.style.opacity = '1';
    } else {
        comboEl.style.opacity = '0';
    }
}

// Input handling
function getPos(e) {
    if (e.touches) {
        return { x: e.touches[0].clientX, y: e.touches[0].clientY };
    }
    return { x: e.clientX, y: e.clientY };
}

function onDown(e) {
    e.preventDefault();
    let pos = getPos(e);
    isMouseDown = true;
    mouseX = pos.x;
    mouseY = pos.y;
    mousePrevX = mouseX;
    mousePrevY = mouseY;
    blade.addPoint(mouseX, mouseY);
}

function onMove(e) {
    e.preventDefault();
    let pos = getPos(e);
    mousePrevX = mouseX;
    mousePrevY = mouseY;
    mouseX = pos.x;
    mouseY = pos.y;

    if (isMouseDown) {
        blade.addPoint(mouseX, mouseY);

        // Check collisions
        for (let food of foods) {
            if (checkSlice(food)) {
                food.slice();
                // Spark particles at slice point
                for (let i = 0; i < 5; i++) {
                    particles.push(new Particle(food.x, food.y, 'spark'));
                }
            }
        }
    }
}

function onUp(e) {
    e.preventDefault();
    isMouseDown = false;
    blade.points = [];
}

canvas.addEventListener('mousedown', onDown);
canvas.addEventListener('mousemove', onMove);
canvas.addEventListener('mouseup', onUp);
canvas.addEventListener('touchstart', onDown, { passive: false });
canvas.addEventListener('touchmove', onMove, { passive: false });
canvas.addEventListener('touchend', onUp, { passive: false });

// Background drawing
function drawBackground() {
    // Dark gradient
    let grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, '#0a0a14');
    grad.addColorStop(0.5, '#0f0a18');
    grad.addColorStop(1, '#0a0a0f');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // Subtle grid
    ctx.save();
    ctx.strokeStyle = 'rgba(40, 30, 60, 0.15)';
    ctx.lineWidth = 0.5;
    let gridSize = 60;
    for (let x = 0; x < W; x += gridSize) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, H);
        ctx.stroke();
    }
    for (let y = 0; y < H; y += gridSize) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(W, y);
        ctx.stroke();
    }
    ctx.restore();

    // Stars
    for (let star of bgStars) {
        star.twinkle += 0.02;
        let alpha = star.alpha * (0.5 + 0.5 * Math.sin(star.twinkle));
        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.fillStyle = '#aabbdd';
        ctx.shadowColor = '#8899cc';
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
    }

    // Vignette
    let vignette = ctx.createRadialGradient(W / 2, H / 2, W * 0.2, W / 2, H / 2, W * 0.8);
    vignette.addColorStop(0, 'transparent');
    vignette.addColorStop(1, 'rgba(0, 0, 0, 0.5)');
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, W, H);
}

// Custom cursor
function drawCursor() {
    if (gameState !== 'playing') return;
    ctx.save();
    ctx.translate(mouseX, mouseY);

    // Outer ring
    ctx.strokeStyle = 'rgba(100, 200, 255, 0.4)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(0, 0, 15, 0, Math.PI * 2);
    ctx.stroke();

    // Crosshair
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(-3, 0);
    ctx.moveTo(3, 0); ctx.lineTo(8, 0);
    ctx.moveTo(0, -8); ctx.lineTo(0, -3);
    ctx.moveTo(0, 3); ctx.lineTo(0, 8);
    ctx.stroke();

    // Center dot
    ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.beginPath();
    ctx.arc(0, 0, 2, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
}

// Game loop
function startGame() {
    gameState = 'playing';
    score = 0;
    lives = 3;
    combo = 0;
    comboTimer = 0;
    foods = [];
    particles = [];
    slicedPieces = [];
    floatingTexts = [];
    blade.points = [];
    spawnTimer = 0;
    spawnInterval = 70;
    difficulty = 1;
    frameCount = 0;
    updateUI();
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('game-over-screen').style.display = 'none';
}

function endGame() {
    gameState = 'gameover';
    if (score > highScore) {
        highScore = score;
        localStorage.setItem('foodNinjaHigh', highScore);
    }
    document.getElementById('final-score').textContent = score;
    document.getElementById('high-score-label').textContent = `Best: ${highScore}`;
    setTimeout(() => {
        document.getElementById('game-over-screen').style.display = 'flex';
    }, 500);
}

function update() {
    frameCount++;

    if (gameState === 'playing') {
        // Difficulty scaling
        difficulty = 1 + Math.floor(score / 15);
        spawnInterval = Math.max(25, 70 - difficulty * 3);

        // Spawn timer
        spawnTimer++;
        if (spawnTimer >= spawnInterval) {
            spawnTimer = 0;
            spawnFood();
        }

        // Combo timer
        if (comboTimer > 0) {
            comboTimer--;
            if (comboTimer <= 0) {
                combo = 0;
                updateUI();
            }
        }

        // Update foods
        for (let i = foods.length - 1; i >= 0; i--) {
            if (!foods[i].update()) {
                foods.splice(i, 1);
            }
        }

        // Update sliced pieces
        for (let i = slicedPieces.length - 1; i >= 0; i--) {
            let p = slicedPieces[i];
            p.x += p.vx;
            p.y += p.vy;
            p.vy += p.gravity;
            p.rotation += p.rotSpeed;
            p.alpha -= 0.012;
            if (p.alpha <= 0) slicedPieces.splice(i, 1);
        }

        // Update particles
        for (let i = particles.length - 1; i >= 0; i--) {
            if (!particles[i].update()) particles.splice(i, 1);
        }

        // Update floating texts
        for (let i = floatingTexts.length - 1; i >= 0; i--) {
            if (!floatingTexts[i].update()) floatingTexts.splice(i, 1);
        }

        // Update blade
        blade.update();

        // Screen shake decay
        if (screenShake > 0) screenShake *= 0.85;
        if (screenShake < 0.5) screenShake = 0;
    }
}

function draw() {
    ctx.save();

    // Screen shake
    if (screenShake > 0 && gameState === 'playing') {
        ctx.translate(
            (Math.random() - 0.5) * screenShake,
            (Math.random() - 0.5) * screenShake
        );
    }

    drawBackground();

    if (gameState === 'playing' || gameState === 'gameover') {
        // Draw sliced pieces
        for (let p of slicedPieces) {
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.rotation);
            ctx.globalAlpha = p.alpha;
            ctx.font = `${p.size}px serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowColor = 'rgba(255,200,100,0.3)';
            ctx.shadowBlur = 10;
            ctx.fillText(p.emoji, 0, 0);
            ctx.restore();
        }

        // Draw foods
        for (let food of foods) {
            food.draw();
        }

        // Draw particles
        for (let p of particles) {
            p.draw();
        }

        // Draw floating texts
        for (let ft of floatingTexts) {
            ft.draw();
        }

        // Draw blade trail
        if (gameState === 'playing') {
            blade.draw();
            drawCursor();
        }
    }

    ctx.restore();
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Button handlers
document.getElementById('startBtn').addEventListener('click', startGame);
document.getElementById('restartBtn').addEventListener('click', startGame);

// Start loop
gameLoop();
</script>
</body>
</html>
