    bird.velocity = 0;
    bird.rotation = 0;
    bird.trail = [];
    pipes = [];
    particles = [];
    pipeTimer = 0;
    score = 0;
    frameCount = 0;
}

function flap() {
    if (gameState === 'menu') {
        gameState = 'playing';
        resetGame();
        bird.velocity = bird.jumpForce;
        bird.flapSpeed = 15;
    } else if (gameState === 'playing') {
        bird.velocity = bird.jumpForce;
        bird.flapSpeed = 15;
        // Add flap particles
        for (let i = 0; i < 5; i++) {
            particles.push({
                x: bird.x,
                y: bird.y + bird.h / 2,
                vx: -Math.random() * 2 - 1,
                vy: Math.random() * 2 + 1,
