<script>
// ===== STOCK DATA =====
const STOCKS = [
  { ticker:'AAPL', name:'Apple Inc.', price:189.84, sector:'Technology', vol:52000000 },
  { ticker:'MSFT', name:'Microsoft Corp.', price:417.88, sector:'Technology', vol:28000000 },
  { ticker:'GOOGL', name:'Alphabet Inc.', price:174.13, sector:'Technology', vol:22000000 },
  { ticker:'AMZN', name:'Amazon.com Inc.', price:186.49, sector:'Consumer', vol:45000000 },
  { ticker:'NVDA', name:'NVIDIA Corp.', price:875.28, sector:'Technology', vol:42000000 },
  { ticker:'META', name:'Meta Platforms', price:505.75, sector:'Technology', vol:18000000 },
  { ticker:'TSLA', name:'Tesla Inc.', price:248.42, sector:'Automotive', vol:95000000 },
  { ticker:'BRK.B', name:'Berkshire Hathaway', price:412.30, sector:'Finance', vol:3500000 },
  { ticker:'JPM', name:'JPMorgan Chase', price:198.47, sector:'Finance', vol:9000000 },
  { ticker:'V', name:'Visa Inc.', price:279.32, sector:'Finance', vol:7000000 },
  { ticker:'JNJ', name:'Johnson & Johnson', price:156.74, sector:'Healthcare', vol:7500000 },
  { ticker:'WMT', name:'Walmart Inc.', price:168.53, sector:'Consumer', vol:8500000 },
  { ticker:'PG', name:'Procter & Gamble', price:162.41, sector:'Consumer', vol:6500000 },
  { ticker:'XOM', name:'Exxon Mobil', price:113.28, sector:'Energy', vol:15000000 },
  { ticker:'DIS', name:'Walt Disney Co.', price:112.47, sector:'Entertainment', vol:11000000 },
  { ticker:'NFLX', name:'Netflix Inc.', price:628.35, sector:'Entertainment', vol:5500000 },
  { ticker:'AMD', name:'AMD Inc.', price:162.73, sector:'Technology', vol:55000000 },
  { ticker:'BA', name:'Boeing Co.', price:178.92, sector:'Industrial', vol:7000000 },
  { ticker:'INTC', name:'Intel Corp.', price:31.24, sector:'Technology', vol:40000000 },
  { ticker:'CRM', name:'Salesforce Inc.', price:272.18, sector:'Technology', vol:5500000 },
];

// ===== STATE =====
let portfolio = { cash: 100000, positions: {} };
let transactions = [];
let selectedTicker = 'AAPL';
let tradeType = 'buy';
let currentTimeframe = 15;
let marketTime = new Date();
let startOfDay = null;
let dayStartCash = 100000;

// Price data storage
const priceData = {};
const volumeData = {};
const candleData = {};
const tickData = {};

// ===== PRICE SIMULATION =====
function initPriceData() {
  STOCKS.forEach(s => {
    const base = s.price;
    const volatility = (Math.random() * 0.02 + 0.005);
    const drift = (Math.random() - 0.48) * 0.0003;

    // Generate initial history (last 200 ticks)
    const candles = [];
    let price = base * (0.95 + Math.random() * 0.05);
    const now = Date.now();

    for (let i = 200; i >= 0; i--) {
      const open = price;
      const change = (Math.random() - 0.48 + drift) * volatility * price;
      const close = open + change;
      const high = Math.max(open, close) + Math.random() * volatility * price * 0.5;
      const low = Math.min(open, close) - Math.random() * volatility * price * 0.5;
      const vol = Math.floor(s.vol * (0.3 + Math.random() * 1.4));

      candles.push({
        time: now - i * 60000,
        open: +open.toFixed(2),
        high: +high.toFixed(2),
        low: +low.toFixed(2),
        close: +close.toFixed(2),
        volume: vol
      });
      price = close;
    }

    priceData[s.ticker] = price;
    candleData[s.ticker] = candles;
    volumeData[s.ticker] = candles.map(c => c.volume);
    tickData[s.ticker] = {
      volatility, drift, base,
      openPrice: candles[0].open,
      prevClose: candles[candles.length - 1].close
    };
  });

  startOfDay = priceData[selectedTicker];
}

function updatePrices() {
  STOCKS.forEach(s => {
    const td = tickData[s.ticker];
    const change = (Math.random() - 0.48 + td.drift) * td.volatility * priceData[s.ticker];
    const newPrice = +(priceData[s.ticker] + change).toFixed(2);
    priceData[s.ticker] = Math.max(newPrice, 0.01);

    // Update last candle
    const candles = candleData[s.ticker];
    const lastCandle = candles[candles.length - 1];
    const now = Date.now();

    if (now - lastCandle.time > 60000) {
      // New candle
      candles.push({
        time: now,
        open: priceData[s.ticker],
        high: priceData[s.ticker],
        low: priceData[s.ticker],
        close: priceData[s.ticker],
        volume: Math.floor(s.vol * (0.3 + Math.random() * 1.4))
      });
      if (candles.length > 300) candles.shift();
    } else {
      lastCandle.close = priceData[s.ticker];
      lastCandle.high = Math.max(lastCandle.high, priceData[s.ticker]);
      lastCandle.low = Math.min(lastCandle.low, priceData[s.ticker]);
      lastCandle.volume += Math.floor(s.vol * 0.001);
    }
  });
}

// ===== NEWS SYSTEM =====
const NEWS_TEMPLATES = [
  { text:'reports stronger than expected quarterly earnings', impact: 'positive' },
  { text:'announces major product launch', impact: 'positive' },
  { text:'raises guidance for next quarter', impact: 'positive' },
  { text:'secures major government contract', impact: 'positive' },
  { text:'expands into new international market', impact: 'positive' },
  { text:'misses earnings expectations', impact: 'negative' },
  { text:'faces regulatory investigation', impact: 'negative' },
  { text:'recalls products due to safety concerns', impact: 'negative' },
  { text:'loses key executive to competitor', impact: 'negative' },
  { text:'downgrades outlook amid market uncertainty', impact: 'negative' },
  { text:'announces stock buyback program', impact: 'positive' },
  { text:'reports supply chain disruptions', impact: 'negative' },
  { text:'partners with major tech company', impact: 'positive' },
  { text:'faces antitrust lawsuit', impact: 'negative' },
  { text:'beats revenue estimates by wide margin', impact: 'positive' },
];

function generateNews() {
  const stock = STOCKS[Math.floor(Math.random() * STOCKS.length)];
  const news = NEWS_TEMPLATES[Math.floor(Math.random() * NEWS_TEMPLATES.length)];
  const impact = Math.random() > 0.5 ? 1 : -1;
  const magnitude = Math.random() * 0.03;

  // Apply impact to stock price
  tickData[stock.ticker].drift += impact * magnitude * 0.1;
  setTimeout(() => { tickData[stock.ticker].drift -= impact * magnitude * 0.1; }, 300000);

  return { ticker: stock.ticker, text: `${stock.ticker} ${news.text}`, impact: news.impact, time: new Date() };
}

let newsItems = [];
function addNews() {
  if (newsItems.length < 10) {
    const news = generateNews();
    newsItems.unshift(news);
  }
}

// ===== UI RENDERING =====
function renderWatchlist() {
  const container = document.getElementById('watchlist');
  const search = document.getElementById('searchInput').value.toLowerCase();

  container.innerHTML = STOCKS
    .filter(s => s.ticker.toLowerCase().includes(search) || s.name.toLowerCase().includes(search))
    .map(s => {
      const price = priceData[s.ticker];
      const td = tickData[s.ticker];
      const change = price - td.openPrice;
      const changePct = (change / td.openPrice) * 100;
      const isUp = change >= 0;
      const isActive = s.ticker === selectedTicker;

      // Mini chart data
      const candles = candleData[s.ticker];
      const miniData = candles.slice(-20).map(c => c.close);
      const miniSvg = generateMiniChart(miniData, isUp);

      return `
        <div class="watchlist-item ${isActive ? 'active' : ''}" onclick="selectStock('${s.ticker}')">
          <div class="wl-info">
            <div class="wl-ticker">${s.ticker}</div>
            <div class="wl-name">${s.name}</div>
          </div>
          <div style="display:flex;align-items:center;gap:8px">
            <svg class="wl-mini-chart" viewBox="0 0 50 24">${miniSvg}</svg>
            <div class="wl-price">
              <div class="wl-price-value">$${price.toFixed(2)}</div>
              <div class="wl-change ${isUp ? 'up' : 'down'}">${isUp ? '+' : ''}${changePct.toFixed(2)}%</div>
            </div>
          </div>
        </div>
      `;
    }).join('');
}

function generateMiniChart(data, isUp) {
  if (data.length < 2) return '';
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const w = 50, h = 24;

  const points = data.map((v, i) => {
    const x = (i / (data.length - 1)) * w;
    const y = h - ((v - min) / range) * (h - 4) - 2;
    return `${x},${y}`;
  });

  const color = isUp ? '#10b981' : '#ef4444';
  return `<polyline points="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>`;
}

function selectStock(ticker) {
  selectedTicker = ticker;
  startOfDay = priceData[ticker];
  updateChartHeader();
  updateOrderSummary();
  renderWatchlist();
  drawChart();
  drawVolume();
}

function updateChartHeader() {
  const s = STOCKS.find(st => st.ticker === selectedTicker);
  const price = priceData[selectedTicker];
  const td = tickData[selectedTicker];
  const change = price - td.openPrice;
  const changePct = (change / td.openPrice) * 100;
  const isUp = change >= 0;

  document.getElementById('chartTicker').textContent = s.ticker;
  document.getElementById('chartName').textContent = s.name;
  document.getElementById('chartPrice').textContent = `$${price.toFixed(2)}`;

  const changeEl = document.getElementById('chartChange');
  changeEl.textContent = `${isUp ? '+' : ''}$${change.toFixed(2)} (${isUp ? '+' : ''}${changePct.toFixed(2)}%)`;
  changeEl.className = `chart-change ${isUp ? 'up' : 'down'}`;
}

// ===== CHART =====
function drawChart() {
  const canvas = document.getElementById('priceChart');
  const container = document.getElementById('chartContainer');
  canvas.width = container.clientWidth * 2;
  canvas.height = container.clientHeight * 2;
  canvas.style.width = container.clientWidth + 'px';
  canvas.style.height = container.clientHeight + 'px';

  const ctx = canvas.getContext('2d');
  ctx.scale(2, 2);
  const W = container.clientWidth;
  const H = container.clientHeight;

  ctx.clearRect(0, 0, W, H);

  const candles = candleData[selectedTicker];
  if (!candles || candles.length < 2) return;

  const padding = { top: 20, right: 60, bottom: 20, left: 10 };
  const chartW = W - padding.left - padding.right;
  const chartH = H - padding.top - padding.bottom;

  const visibleCandles = candles.slice(-Math.min(candles.length, Math.floor(chartW / 8)));
  const allPrices = visibleCandles.flatMap(c => [c.high, c.low]);
  const minPrice = Math.min(...allPrices);
  const maxPrice = Math.max(...allPrices);
  const priceRange = maxPrice - minPrice || 1;

  const candleWidth = Math.max(2, Math.min(8, chartW / visibleCandles.length - 1));
  const gap = (chartW - candleWidth * visibleCandles.length) / (visibleCandles.length + 1);

  // Grid lines
  ctx.strokeStyle = 'rgba(30,42,58,0.5)';
  ctx.lineWidth = 0.5;
  const gridLines = 5;
  for (let i = 0; i <= gridLines; i++) {
    const y = padding.top + (chartH / gridLines) * i;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(W - padding.right, y);
    ctx.stroke();

    const price = maxPrice - (priceRange / gridLines) * i;
    ctx.fillStyle = '#4a5568';
    ctx.font = '10px system-ui';
    ctx.textAlign = 'left';
    ctx.fillText('$' + price.toFixed(2), W - padding.right + 5, y + 3);
  }

  // Candles
  visibleCandles.forEach((c, i) => {
    const x = padding.left + gap + i * (candleWidth + gap);
    const isUp = c.close >= c.open;
    const color = isUp ? '#10b981' : '#ef4444';

    const yHigh = padding.top + ((maxPrice - c.high) / priceRange) * chartH;
    const yLow = padding.top + ((maxPrice - c.low) / priceRange) * chartH;
    const yOpen = padding.top + ((maxPrice - c.open) / priceRange) * chartH;
    const yClose = padding.top + ((maxPrice - c.close) / priceRange) * chartH;

    // Wick
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + candleWidth / 2, yHigh);
    ctx.lineTo(x + candleWidth / 2, yLow);
    ctx.stroke();

    // Body
    const bodyTop = Math.min(yOpen, yClose);
    const bodyHeight = Math.max(1, Math.abs(yClose - yOpen));
    ctx.fillStyle = color;
    ctx.fillRect(x, bodyTop, candleWidth, bodyHeight);
  });

  // Current price line
  const lastCandle = visibleCandles[visibleCandles.length - 1];
  const currentY = padding.top + ((maxPrice - lastCandle.close) / priceRange) * chartH;
  const isUp = lastCandle.close >= lastCandle.open;

  ctx.strokeStyle = isUp ? '#10b981' : '#ef4444';
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(padding.left, currentY);
  ctx.lineTo(W - padding.right, currentY);
  ctx.stroke();
  ctx.setLineDash([]);

  // Price tag
  ctx.fillStyle = isUp ? '#10b981' : '#ef4444';
  const tagW = 58, tagH = 18;
  ctx.fillRect(W - padding.right, currentY - tagH / 2, tagW, tagH);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 10px system-ui';
  ctx.textAlign = 'center';
  ctx.fillText('$' + lastCandle.close.toFixed(2), W - padding.right + tagW / 2, currentY + 4);

  // Moving average
  if (visibleCandles.length >= 20) {
    ctx.strokeStyle = 'rgba(59,130,246,0.6)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    let started = false;
    for (let i = 19; i < visibleCandles.length; i++) {
      let sum = 0;
      for (let j = i - 19; j <= i; j++) sum += visibleCandles[j].close;
      const ma = sum / 20;
      const x = padding.left + gap + i * (candleWidth + gap) + candleWidth / 2;
      const y = padding.top + ((maxPrice - ma) / priceRange) * chartH;
      if (!started) { ctx.moveTo(x, y); started = true; }
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

function drawVolume() {
  const canvas = document.getElementById('volumeChart');
  const container = canvas.parentElement;
  canvas.width = container.clientWidth * 2;
  canvas.height = container.clientHeight * 2;
  canvas.style.width = container.clientWidth + 'px';
  canvas.style.height = container.clientHeight + 'px';

  const ctx = canvas.getContext('2d');
  ctx.scale(2, 2);
  const W = container.clientWidth;
  const H = container.clientHeight;

  ctx.clearRect(0, 0, W, H);

  const candles = candleData[selectedTicker];
  if (!candles) return;

  const visibleCandles = candles.slice(-Math.min(candles.length, Math.floor(W / 8)));
  const maxVol = Math.max(...visibleCandles.map(c => c.volume));
  const padding = { left: 10, right: 60 };
  const chartW = W - padding.left - padding.right;

  const candleWidth = Math.max(2, Math.min(8, chartW / visibleCandles.length - 1));
  const gap = (chartW - candleWidth * visibleCandles.length) / (visibleCandles.length + 1);

  visibleCandles.forEach((c, i) => {
    const x = padding.left + gap + i * (candleWidth + gap);
    const isUp = c.close >= c.open;
    const barH = (c.volume / maxVol) * (H - 10);

    ctx.fillStyle = isUp ? 'rgba(16,185,129,0.4)' : 'rgba(239,68,68,0.4)';
    ctx.fillRect(x, H - barH, candleWidth, barH);
  });
}

// ===== TRADING =====
function setTradeType(type) {
  tradeType = type;
  document.querySelectorAll('.trade-type-btn').forEach(b => b.classList.remove('active'));
  document.querySelector(`.trade-type-btn.${type}`).classList.add('active');

  const btn = document.getElementById('tradeBtn');
  btn.className = `trade-btn ${type}-btn`;
  btn.textContent = `${type === 'buy' ? 'Buy' : 'Sell'} ${selectedTicker}`;
  updateOrderSummary();
}

function setTimeframe(tf) {
  currentTimeframe = tf;
  document.querySelectorAll('.tf-btn').forEach(b => b.classList.remove('active'));
  document.querySelector(`.tf-btn[data-tf="${tf}"]`).classList.add('active');
}

function setQty(q) {
  document.getElementById('quantity').value = q;
  updateOrderSummary();
}

function updateOrderSummary() {
  const price = priceData[selectedTicker];
  const qty = parseInt(document.getElementById('quantity').value) || 0;
  const orderType = document.getElementById('orderType').value;

  // Show/hide limit price
  document.getElementById('limitPriceGroup').style.display = orderType === 'limit' ? 'flex' : 'none';

  document.getElementById('summaryPrice').textContent = `$${price.toFixed(2)}`;
  document.getElementById('summaryQty').textContent = qty;

  let total = price * qty;
  if (orderType === 'limit') {
    const limitPrice = parseFloat(document.getElementById('limitPrice').value);
    if (limitPrice > 0) total = limitPrice * qty;
  }

  document.getElementById('summaryTotal').textContent = `$${total.toFixed(2)}`;

  const btn = document.getElementById('tradeBtn');
  btn.textContent = `${tradeType === 'buy' ? 'Buy' : 'Sell'} ${selectedTicker}`;
}

function executeTrade() {
  const qty = parseInt(document.getElementById('quantity').value);
  if (!qty || qty < 1) { showToast('Please enter a valid quantity', 'error'); return; }

  const price = priceData[selectedTicker];
  const orderType = document.getElementById('orderType').value;
  const total = price * qty;

  if (tradeType === 'buy') {
    if (total > portfolio.cash) {
      showToast('Insufficient funds', 'error');
      return;
    }

    portfolio.cash -= total;
    if (!portfolio.positions[selectedTicker]) {
      portfolio.positions[selectedTicker] = { qty: 0, avgCost: 0, totalCost: 0 };
    }
    const pos = portfolio.positions[selectedTicker];
    pos.totalCost += total;
    pos.qty += qty;
    pos.avgCost = pos.totalCost / pos.qty;

    transactions.unshift({
      type: 'buy', ticker: selectedTicker, qty, price, total,
      time: new Date()
    });

    showToast(`Bought ${qty} ${selectedTicker} @ $${price.toFixed(2)}`, 'success');
  } else {
    const pos = portfolio.positions[selectedTicker];
    if (!pos || pos.qty < qty) {
      showToast(`Insufficient ${selectedTicker} shares`, 'error');
      return;
    }

    portfolio.cash += total;
    pos.totalCost -= pos.avgCost * qty;
    pos.qty -= qty;
    if (pos.qty === 0) delete portfolio.positions[selectedTicker];

    transactions.unshift({
      type: 'sell', ticker: selectedTicker, qty, price, total,
      time: new Date()
    });

    showToast(`Sold ${qty} ${selectedTicker} @ $${price.toFixed(2)}`, 'success');
  }

  updateUI();
  renderPositions();
}

