.header-btns{display:flex;gap:10px}
.btn{padding:8px 18px;border:none;border-radius:25px;cursor:pointer;font-size:14px;font-weight:600;transition:all .3s}
.btn-primary{background:linear-gradient(135deg,#6c3ce0,#9b59b6);color:#fff}
.btn-primary:hover{transform:scale(1.05);box-shadow:0 5px 20px rgba(108,60,224,.5)}
.btn-success{background:linear-gradient(135deg,#27ae60,#2ecc71);color:#fff}
.btn-danger{background:linear-gradient(135deg,#e74c3c,#c0392b);color:#fff}
.btn-warning{background:linear-gradient(135deg,#f39c12,#e67e22);color:#fff}
.btn-info{background:linear-gradient(135deg,#3498db,#2980b9);color:#fff}
.btn-sm{padding:5px 12px;font-size:12px}
.main-container{display:flex;height:calc(100vh - 60px)}
.sidebar{width:280px;background:linear-gradient(180deg,#12123a,#1a1a4e);padding:15px;overflow-y:auto;border-right:1px solid #2a2a6e}
.sidebar h3{color:#9b59b6;margin:15px 0 10px;font-size:14px;text-transform:uppercase;letter-spacing:1px}
.sidebar h3:first-child{margin-top:0}
.scene-list{display:flex;flex-direction:column;gap:8px}
.scene-item{background:#1e1e5a;border:2px solid #2a2a6e;border-radius:10px;padding:10px;cursor:pointer;transition:all .3s;display:flex;align-items:center;gap:10px}
.scene-item:hover,.scene-item.active{border-color:#6c3ce0;background:#2a2a7e}
.scene-thumb{width:60px;height:40px;border-radius:6px;background:#333;overflow:hidden}
.scene-thumb canvas{width:100%;height:100%}
.scene-info{flex:1}
.scene-info .name{font-size:13px;font-weight:600}
.scene-info .dur{font-size:11px;color:#888}
.content-area{flex:1;display:flex;flex-direction:column}
.preview-area{flex:1;display:flex;align-items:center;justify-content:center;background:#000;position:relative;min-height:400px}
#mainCanvas{border-radius:8px;max-width:100%;max-height:100%}
.controls-bar{background:#12123a;padding:10px 20px;display:flex;align-items:center;gap:15px;border-top:1px solid #2a2a6e}
.ctrl-btn{width:40px;height:40px;border-radius:50%;border:none;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;transition:all .3s}
.ctrl-btn:hover{transform:scale(1.1)}
.ctrl-play{background:linear-gradient(135deg,#27ae60,#2ecc71);color:#fff}
.ctrl-pause{background:linear-gradient(135deg,#f39c12,#e67e22);color:#fff}
.ctrl-stop{background:linear-gradient(135deg,#e74c3c,#c0392b);color:#fff}
.ctrl-rec{background:linear-gradient(135deg,#e74c3c,#c0392b);color:#fff;animation:pulse 1.5s infinite}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(231,76,60,.7)}50%{box-shadow:0 0 0 10px rgba(231,76,60,0)}}
.timeline{background:#12123a;padding:15px 20px;border-top:1px solid #2a2a6e}
.timeline-track{height:60px;background:#1a1a4e;border-radius:8px;position:relative;overflow:hidden;margin-top:10px}
.timeline-segment{position:absolute;height:100%;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600;cursor:pointer;transition:all .3s}
.timeline-segment:hover{filter:brightness(1.3)}
.timeline-segment.active{border:2px solid #fff;box-shadow:0 0 10px rgba(255,255,255,.3)}
.timeline-playhead{position:absolute;top:0;width:3px;height:100%;background:#ff6b6b;z-index:10;transition:left .1s}
.timeline-controls{display:flex;align-items:center;gap:10px;margin-top:10px}
.time-display{font-size:13px;color:#aaa;font-family:monospace}
.panel-section{margin-bottom:15px}
.panel-section label{display:block;font-size:12px;color:#aaa;margin-bottom:5px}
.panel-section select,.panel-section input[type="text"],.panel-section input[type="number"]{width:100%;padding:8px;border-radius:6px;border:1px solid #2a2a6e;background:#1a1a4e;color:#fff;font-size:13px}
.color-picker-wrap{display:flex;gap:8px;flex-wrap:wrap}
.color-swatch{width:30px;height:30px;border-radius:50%;cursor:pointer;border:2px solid transparent;transition:all .3s}
.color-swatch:hover,.color-swatch.active{border-color:#fff;transform:scale(1.2)}
.char-customizer{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.char-customizer .full{grid-column:1/-1}
.char-preview{width:100%;height:120px;background:#1a1a4e;border-radius:8px;display:flex;align-items:center;justify-content:center;margin-bottom:10px}
.char-preview canvas{border-radius:8px}
.voice-panel{background:#1a1a4e;border-radius:10px;padding:15px;margin-top:10px}
.voice-wave{height:40px;background:#0a0a2e;border-radius:6px;margin:10px 0;display:flex;align-items:center;justify-content:center;overflow:hidden}
.voice-wave canvas{width:100%;height:100%}
.voice-timer{font-size:24px;text-align:center;font-family:monospace;color:#ff6b6b}
.export-modal{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.8);z-index:1000;align-items:center;justify-content:center}
.export-modal.show{display:flex}
.export-content{background:#1a1a4e;border-radius:15px;padding:30px;max-width:500px;width:90%;text-align:center}
.export-content h2{margin-bottom:20px;color:#9b59b6}
.progress-bar{width:100%;height:20px;background:#0a0a2e;border-radius:10px;overflow:hidden;margin:15px 0}
.progress-fill{height:100%;background:linear-gradient(90deg,#6c3ce0,#9b59b6);border-radius:10px;transition:width .3s;width:0%}
.bg-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.bg-option{height:50px;border-radius:8px;cursor:pointer;border:2px solid transparent;transition:all .3s}
.bg-option:hover,.bg-option.active{border-color:#fff;transform:scale(1.05)}
.tab-bar{display:flex;gap:5px;margin-bottom:15px}
.tab-btn{flex:1;padding:8px;border:none;background:#1a1a4e;color:#aaa;border-radius:6px;cursor:pointer;font-size:12px;transition:all .3s}
.tab-btn.active{background:#6c3ce0;color:#fff}
.prop-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.prop-item{display:flex;flex-direction:column;gap:3px}
.prop-item label{font-size:11px;color:#888}
.prop-item input,.prop-item select{padding:6px;border-radius:4px;border:1px solid #2a2a6e;background:#1a1a4e;color:#fff;font-size:12px}
.sticker-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.sticker-item{height:50px;background:#1a1a4e;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:24px;cursor:pointer;transition:all .3s;border:2px solid transparent}
.sticker-item:hover{border-color:#6c3ce0;transform:scale(1.1)}
.scroll-y{overflow-y:auto;max-height:calc(100vh - 200px)}
.scroll-y::-webkit-scrollbar{width:6px}
.scroll-y::-webkit-scrollbar-track{background:#0a0a2e}
.scroll-y::-webkit-scrollbar-thumb{background:#6c3ce0;border-radius:3px}
.recording-indicator{display:none;align-items:center;gap:8px;padding:8px 15px;background:rgba(231,76,60,.2);border-radius:20px;border:1px solid #e74c3c}
.recording-indicator.active{display:flex}
.rec-dot{width:10px;height:10px;background:#e74c3c;border-radius:50%;animation:pulse 1s infinite}
.toast{position:fixed;bottom:20px;right:20px;padding:12px 24px;border-radius:10px;font-size:14px;z-index:2000;transform:translateY(100px);opacity:0;transition:all .3s}
.toast.show{transform:translateY(0);opacity:1}
.toast.success{background:#27ae60;color:#fff}
.toast.error{background:#e74c3c;color:#fff}
.toast.info{background:#3498db;color:#fff}
@media(max-width:768px){.sidebar{width:200px;font-size:12px}.preview-area{min-height:250px}}
</style>
</head>
<body>

<div class="app-header">
<h1>🎬 Cartoon Video Maker 3D</h1>
<div class="header-btns">
<div class="recording-indicator" id="recIndicator">
<div class="rec-dot"></div>
<span>Recording...</span>
</div>
<button class="btn btn-info btn-sm" onclick="addScene()">➕ Scene</button>
<button class="btn btn-warning btn-sm" onclick="showExport()">📥 Export Video</button>
</div>
</div>

<div class="main-container">
<div class="sidebar">
<div class="tab-bar">
<button class="tab-btn active" onclick="switchTab('scenes')">🎬 Scenes</button>
<button class="tab-btn" onclick="switchTab('characters')">👤 Characters</button>
<button class="tab-btn" onclick="switchTab('voice')">🎤 Voice</button>
<button class="tab-btn" onclick="switchTab('props')">🎨 Props</button>
</div>

<div id="tab-scenes">
<h3>📋 Scenes</h3>
<div class="scene-list" id="sceneList"></div>
</div>

<div id="tab-characters" style="display:none">
<h3>👤 Character Creator</h3>
<div class="char-preview"><canvas id="charPreview" width="150" height="120"></canvas></div>
<div class="char-customizer">
<div class="prop-item">
<label>Skin Color</label>
<div class="color-picker-wrap" id="skinColors"></div>
</div>
<div class="prop-item">
<label>Hair Color</label>
<div class="color-picker-wrap" id="hairColors"></div>
</div>
<div class="prop-item">
<label>Hat Style</label>
<select id="hatStyle" onchange="updateCharPreview()">
<option value="none">No Hat</option>
<option value="cap">Cap</option>
<option value="tophat">Top Hat</option>
<option value="crown">Crown</option>
<option value="beanie">Beanie</option>
</select>
</div>
<div class="prop-item">
<label>Hat Color</label>
<div class="color-picker-wrap" id="hatColors"></div>
</div>
<div class="prop-item">
<label>Body Style</label>
<select id="bodyStyle" onchange="updateCharPreview()">
<option value="round">Round</option>
<option value="tall">Tall</option>
<option value="chubby">Chubby</option>
<option value="thin">Thin</option>
</select>
</div>
<div class="prop-item">
<label>Expression</label>
<select id="expression" onchange="updateCharPreview()">
<option value="happy">Happy</option>
<option value="sad">Sad</option>
<option value="angry">Angry</option>
<option value="surprised">Surprised</option>
<option value="wink">Wink</option>
</select>
</div>
<div class="prop-item full">
<label>Character Name</label>
<input type="text" id="charName" placeholder="Enter name..." value="Hero">
</div>
<div class="prop-item full">
<label>Shirt Color</label>
<div class="color-picker-wrap" id="shirtColors"></div>
</div>
</div>
<button class="btn btn-primary" style="width:100%;margin-top:15px" onclick="addCharacter()">➕ Add Character to Scene</button>
</div>

<div id="tab-voice" style="display:none">
<h3>🎤 Voice Recorder</h3>
<div class="voice-panel">
<button class="btn btn-danger" id="recBtn" onclick="toggleRecording()" style="width:100%;padding:12px">🔴 Start Recording</button>
<div class="voice-timer" id="voiceTimer">00:00</div>
<div class="voice-wave"><canvas id="waveCanvas" width="250" height="40"></canvas></div>
<div class="prop-item">
<label>Voiceover Text (for TTS)</label>
<textarea id="ttsText" rows="3" style="width:100%;padding:8px;border-radius:6px;border:1px solid #2a2a6e;background:#1a1a4e;color:#fff;font-size:13px;resize:vertical" placeholder="Type what the character should say..."></textarea>
</div>
<button class="btn btn-info" style="width:100%;margin-top:10px" onclick="speakText()">🔊 Text to Speech</button>
<div id="voiceList" style="margin-top:15px"></div>
</div>
</div>

<div id="tab-props" style="display:none">
<h3>🎨 Backgrounds</h3>
<div class="bg-grid" id="bgGrid"></div>
<h3>🎭 Stickers</h3>
<div class="sticker-grid" id="stickerGrid"></div>
<h3>✨ Effects</h3>
<div class="prop-grid">
<div class="prop-item">
<label>Animation</label>
<select id="animType" onchange="updateCharPreview()">
<option value="bounce">Bounce</option>
<option value="slide">Slide</option>
<option value="spin">Spin</option>
<option value="fade">Fade</option>
<option value="wave">Wave</option>
<option value="jump">Jump</option>
</select>
</div>
<div class="prop-item">
<label>Speed</label>
<select id="animSpeed">
<option value="slow">Slow</option>
<option value="normal" selected>Normal</option>
<option value="fast">Fast</option>
</select>
</div>
</div>
</div>
</div>

<div class="content-area">
<div class="preview-area">
<canvas id="mainCanvas" width="854" height="480"></canvas>
</div>
<div class="controls-bar">
<button class="ctrl-btn ctrl-stop" onclick="stopAnimation()" title="Stop">⏹</button>
<button class="ctrl-btn ctrl-pause" onclick="pauseAnimation()" title="Pause">⏸</button>
<button class="ctrl-btn ctrl-play" onclick="playAnimation()" title="Play">▶</button>
<button class="ctrl-btn" style="background:#3498db;color:#fff" onclick="prevScene()" title="Previous">⏮</button>
<button class="ctrl-btn" style="background:#3498db;color:#fff" onclick="nextScene()" title="Next">⏭</button>
<div class="time-display" id="timeDisplay">00:00 / 00:00</div>
<div style="flex:1"></div>
<button class="btn btn-sm btn-primary" onclick="duplicateScene()">📋 Duplicate</button>
<button class="btn btn-sm btn-danger" onclick="deleteScene()">🗑️ Delete</button>
</div>
<div class="timeline">
<div style="display:flex;justify-content:space-between;align-items:center">
<span style="font-size:13px;color:#aaa">📅 Timeline</span>
<div style="display:flex;gap:5px">
<button class="btn btn-sm btn-info" onclick="addScene()">+ Add Scene</button>
<button class="btn btn-sm btn-success" onclick="exportVideo()">🎬 Export HD Video</button>
</div>
</div>
<div class="timeline-track" id="timelineTrack">
<div class="timeline-playhead" id="playhead"></div>
</div>
<div class="timeline-controls">
<input type="range" id="timelineSlider" min="0" max="100" value="0" style="flex:1" oninput="seekTimeline(this.value)">
<span class="time-display" id="tlTime">0:00</span>
</div>
</div>
</div>
</div>

<div class="export-modal" id="exportModal">
<div class="export-content">
<h2>🎬 Exporting Video...</h2>
<div class="progress-bar"><div class="progress-fill" id="exportProgress"></div></div>
<p id="exportStatus" style="color:#aaa;font-size:14px">Preparing frames...</p>
<button class="btn btn-primary" onclick="closeExport()" style="margin-top:15px">Close</button>
</div>
</div>

<div class="toast" id="toast"></div>

<script>
const SKIN_COLORS=['#FDBCB4','#D2956A','#8D5524','#C68642','#FFDBAC','#F1C27D','#E0AC69','#FFDFD3'];
const HAIR_COLORS=['#2C1B18','#8B4513','#DAA520','#FFD700','#FF4500','#DC143C','#4169E1','#00CED1','#800080','#FFFFFF'];
const SHIRT_COLORS=['#E74C3C','#3498DB','#2ECC71','#F39C12','#9B59B6','#1ABC9C','#E91E63','#00BCD4'];
const HAT_COLORS=['#E74C3C','#3498DB','#2ECC71','#F39C12','#9B59B6','#000000','#FFFFFF','#FFD700'];
const BG_STYLES=[
{name:'Sunny Park',bg:'linear-gradient(180deg,#87CEEB 0%,#87CEEB 60%,#90EE90 60%,#228B22 100%)'},
{name:'Sunset Beach',bg:'linear-gradient(180deg,#FF6B6B 0%,#FFA07A 30%,#FFD700 60%,#87CEEB 60%,#F4A460 100%)'},
{name:'Night City',bg:'linear-gradient(180deg,#0a0a2e 0%,#1a1a4e 50%,#2d2d6e 100%)'},
{name:'Space',bg:'radial-gradient(ellipse at center,#1a0533 0%,#0a0a2e 50%,#000000 100%)'},
{name:'Forest',bg:'linear-gradient(180deg,#87CEEB 0%,#228B22 50%,#006400 100%)'},
{name:'Snow World',bg:'linear-gradient(180deg,#B0C4DE 0%,#E8E8E8 40%,#FFFFFF 40%,#F0F8FF 100%)'},
{name:'Desert',bg:'linear-gradient(180deg,#FF8C00 0%,#FFD700 50%,#DAA520 50%,#B8860B 100%)'},
{name:'Ocean',bg:'linear-gradient(180deg,#87CEEB 0%,#4169E1 40%,#00008B 100%)'},
{name:'Castle',bg:'linear-gradient(180deg,#2C3E50 0%,#34495E 50%,#7F8C8D 50%,#95A5A6 100%)'}
];
const STICKERS=['😀','😂','🤣','😍','🥰','😎','🤩','😱','👻','💀','🦄','🐉','🌈','⭐','🔥','💎','🎵','🎸','🚀','🌟','❤️','💝','🎉','🎊','🏆','👑','🎭','🎪','🎯','🎲'];

let scenes=[];
let currentSceneIdx=0;
let isPlaying=false;
let isPaused=false;
let animFrame=null;
let animTime=0;
let voiceRecordings=[];
let mediaRecorder=null;
let audioChunks=[];
let recStartTime=0;
let recInterval=null;
let analyser=null;
let audioCtx=null;
let waveAnim=null;
let characters=[];
let sceneChars=[];
let sceneBg=0;
let sceneStickers=[];
let isRecording=false;

function init(){
initColors();
initBgs();
initStickers();
addScene();
updateCharPreview();
renderSceneList();
renderTimeline();
drawMainCanvas();
}

function initColors(){
createColorSwatches('skinColors',SKIN_COLORS,'#2C1B18');
createColorSwatches('hairColors',HAIR_COLORS,'#2C1B18');
createColorSwatches('shirtColors',SHIRT_COLORS,'#2C1B18');
createColorSwatches('hatColors',HAT_COLORS,'#2C1B18');
}

function createColorSwatches(containerId,colors,activeColor){
const container=document.getElementById(containerId);
container.innerHTML='';
colors.forEach(c=>{
const swatch=document.createElement('div');
swatch.className='color-swatch'+(c===activeColor?' active':'');
swatch.style.background=c;
swatch.onclick=()=>{
container.querySelectorAll('.color-swatch').forEach(s=>s.classList.remove('active'));
swatch.classList.add('active');
if(containerId==='skinColors')document.getElementById('skinColor')?.remove();
updateCharPreview();
};
container.appendChild(swatch);
});
}

function initBgs(){
const grid=document.getElementById('bgGrid');
grid.innerHTML='';
BG_STYLES.forEach((bg,i)=>{
const div=document.createElement('div');
div.className='bg-option'+(i===0?' active':'');
div.style.background=bg.bg;
div.title=bg.name;
div.onclick=()=>{
grid.querySelectorAll('.bg-option').forEach(b=>b.classList.remove('active'));
div.classList.add('active');
sceneBg=i;
drawMainCanvas();
};
grid.appendChild(div);
});
}

function initStickers(){
const grid=document.getElementById('stickerGrid');
grid.innerHTML='';
STICKERS.forEach(s=>{
const div=document.createElement('div');
div.className='sticker-item';
div.textContent=s;
div.onclick=()=>{
sceneStickers.push({emoji:s,x:0.5,y:0.3,size:40,rotation:0});
drawMainCanvas();
showToast('Sticker added!','success');
};
grid.appendChild(div);
});
}

function addScene(){
const scene={
id:Date.now(),
name:'Scene '+(scenes.length+1),
duration:5,
bg:sceneBg,
characters:[],
stickers:[...sceneStickers],
voiceover:null,
animation:'bounce'
};
scenes.push(scene);
currentSceneIdx=scenes.length-1;
renderSceneList();
renderTimeline();
drawMainCanvas();
showToast('Scene added!','success');
}

function renderSceneList(){
const list=document.getElementById('sceneList');
list.innerHTML='';
scenes.forEach((s,i)=>{
const div=document.createElement('div');
div.className='scene-item'+(i===currentSceneIdx?' active':'');
div.onclick=()=>{currentSceneIdx=i;renderSceneList();drawMainCanvas();renderTimeline();};
div.innerHTML=`
<div class="scene-thumb"><canvas id="thumb${i}" width="60" height="40"></canvas></div>
<div class="scene-info">
<div class="name">${s.name}</div>
<div class="dur">${s.duration}s | ${s.characters.length} chars</div>
</div>`;
list.appendChild(div);
setTimeout(()=>{
const tc=document.getElementById('thumb'+i);
if(tc)drawThumbnail(tc,s);
},50);
});
}

function drawThumbnail(canvas,scene){
const ctx=canvas.getContext('2d');
const w=canvas.width,h=canvas.height;
ctx.fillStyle='#1a1a4e';
ctx.fillRect(0,0,w,h);
drawBgToCtx(ctx,w,h,scene.bg);
if(scene.characters.length>0){
const c=scene.characters[0];
drawMiniChar(ctx,w/2,h/2,c);
}
}

function drawBgToCtx(ctx,w,h,bgIdx){
const bg=BG_STYLES[bgIdx]||BG_STYLES[0];
const grad=ctx.createLinearGradient(0,0,0,h);
if(bgIdx===0){
grad.addColorStop(0,'#87CEEB');grad.addColorStop(0.6,'#87CEEB');grad.addColorStop(0.6,'#90EE90');grad.addColorStop(1,'#228B22');
}else if(bgIdx===1){
grad.addColorStop(0,'#FF6B6B');grad.addColorStop(0.3,'#FFA07A');grad.addColorStop(0.6,'#FFD700');grad.addColorStop(0.6,'#87CEEB');grad.addColorStop(1,'#F4A460');
}else if(bgIdx===2){
grad.addColorStop(0,'#0a0a2e');grad.addColorStop(0.5,'#1a1a4e');grad.addColorStop(1,'#2d2d6e');
}else if(bgIdx===3){
const rg=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,w);
rg.addColorStop(0,'#1a0533');rg.addColorStop(0.5,'#0a0a2e');rg.addColorStop(1,'#000');
ctx.fillStyle=rg;ctx.fillRect(0,0,w,h);return;
}else if(bgIdx===4){
grad.addColorStop(0,'#87CEEB');grad.addColorStop(0.5,'#228B22');grad.addColorStop(1,'#006400');
}else if(bgIdx===5){
grad.addColorStop(0,'#B0C4DE');grad.addColorStop(0.4,'#E8E8E8');grad.addColorStop(0.4,'#FFFFFF');grad.addColorStop(1,'#F0F8FF');
}else if(bgIdx===6){
grad.addColorStop(0,'#FF8C00');grad.addColorStop(0.5,'#FFD700');grad.addColorStop(0.5,'#DAA520');grad.addColorStop(1,'#B8860B');
}else if(bgIdx===7){
grad.addColorStop(0,'#87CEEB');grad.addColorStop(0.4,'#4169E1');grad.addColorStop(1,'#00008B');
}else if(bgIdx===8){
grad.addColorStop(0,'#2C3E50');grad.addColorStop(0.5,'#34495E');grad.addColorStop(0.5,'#7F8C8D');grad.addColorStop(1,'#95A5A6');
}else{
grad.addColorStop(0,'#87CEEB');grad.addColorStop(1,'#228B22');
}
ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
}

function drawMiniChar(ctx,x,y,char){
ctx.save();
ctx.translate(x,y);
const s=0.5;
ctx.scale(s,s);
const skin=char.skinColor||'#FDBCB4';
const hair=char.hairColor||'#2C1B18';
const shirt=char.shirtColor||'#E74C3C';
const hat=char.hatColor||'#E74C3C';
const hatStyle=char.hatStyle||'none';
const body=char.bodyStyle||'round';
const expr=char.expression||'happy';
const bw=body==='thin'?20:body==='chubby'?35:28;
const bh=body==='tall'?45:body==='thin'?35:30;
ctx.fillStyle=shirt;
ctx.beginPath();ctx.ellipse(0,10,bw,bh,0,0,Math.PI*2);ctx.fill();
ctx.strokeStyle='#333';ctx.lineWidth=1.5;ctx.stroke();
ctx.fillStyle=skin;
ctx.beginPath();ctx.arc(0,-15,18,0,Math.PI*2);ctx.fill();ctx.stroke();
ctx.fillStyle=hair;
ctx.beginPath();ctx.arc(0,-20,19,Math.PI,0);ctx.fill();
ctx.beginPath();ctx.ellipse(-18,-10,6,10,0.3,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.ellipse(18,-10,6,10,-0.3,0,Math.PI*2);ctx.fill();
if(hatStyle==='cap'){
ctx.fillStyle=hat;
ctx.beginPath();ctx.ellipse(0,-28,20,6,0,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(0,-30,18,Math.PI,0);ctx.fill();
ctx.fillStyle=hat;ctx.fillRect(15,-32,12,5);
}else if(hatStyle==='tophat'){
ctx.fillStyle=hat;
ctx.fillRect(-12,-55,24,25);
ctx.fillRect(-16,-32,32,5);
}else if(hatStyle==='crown'){
ctx.fillStyle=hat;
ctx.beginPath();ctx.moveTo(-15,-30);ctx.lineTo(-15,-45);ctx.lineTo(-8,-38);ctx.lineTo(0,-50);ctx.lineTo(8,-38);ctx.lineTo(15,-45);ctx.lineTo(15,-30);ctx.closePath();ctx.fill();
ctx.fillStyle='#FFD700';
ctx.beginPath();ctx.arc(-10,-35,2,0,Math.PI*2);ctx.arc(0,-43,2,0,Math.PI*2);ctx.arc(10,-35,2,0,Math.PI*2);ctx.fill();
}else if(hatStyle==='beanie'){
ctx.fillStyle=hat;
ctx.beginPath();ctx.arc(0,-25,19,Math.PI,0);ctx.fill();
ctx.fillRect(-19,-25,38,8);
}
drawEyes(ctx,expr);
drawMouth(ctx,expr);
ctx.restore();
}

function drawEyes(ctx,expr){
ctx.fillStyle='#333';
if(expr==='wink'){
ctx.beginPath();ctx.arc(-7,-18,3,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(7,-18,3,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(-7,-18,3,0,Math.PI);ctx.stroke();
}else if(expr==='surprised'){
ctx.fillStyle='#fff';
ctx.beginPath();ctx.arc(-7,-18,5,0,Math.PI*2);ctx.fill();ctx.stroke();
ctx.beginPath();ctx.arc(7,-18,5,0,Math.PI*2);ctx.fill();ctx.stroke();
ctx.fillStyle='#333';
ctx.beginPath();ctx.arc(-7,-18,2,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(7,-18,2,0,Math.PI*2);ctx.fill();
}else{
ctx.beginPath();ctx.arc(-7,-18,3,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(7,-18,3,0,Math.PI*2);ctx.fill();
}
}

function drawMouth(ctx,expr){
ctx.strokeStyle='#333';ctx.lineWidth=2;ctx.beginPath();
if(expr==='happy'){ctx.arc(0,-10,6,0,Math.PI);ctx.stroke();
}else if(expr==='sad'){ctx.arc(0,-5,6,Math.PI,0);ctx.stroke();
}else if(expr==='angry'){ctx.moveTo(-5,-10);ctx.lineTo(5,-10);ctx.stroke();
}else if(expr==='surprised'){ctx.beginPath();ctx.ellipse(0,-10,4,5,0,0,Math.PI*2);ctx.stroke();
}else if(expr==='wink'){ctx.arc(0,-10,6,0,Math.PI);ctx.stroke();
}
}

function drawMainCanvas(){
const canvas=document.getElementById('mainCanvas');
const ctx=canvas.getContext('2d');
const w=canvas.width,h=canvas.height;
const scene=scenes[currentSceneIdx];
if(!scene)return;
ctx.clearRect(0,0,w,h);
drawBgToCtx(ctx,w,h,scene.bg);
drawSceneElements(ctx,w,h,scene);
drawSceneChars(ctx,w,h,scene,animTime);
drawStickers(ctx,w,h,scene,animTime);
}

function drawSceneElements(ctx,w,h,scene){
const bg=BG_STYLES[scene.bg]||BG_STYLES[0];
if(scene.bg===0){
drawParkScene(ctx,w,h);
}else if(scene.bg===1){
drawBeachScene(ctx,w,h);
}else if(scene.bg===2){
drawCityScene(ctx,w,h);
}else if(scene.bg===3){
drawSpaceScene(ctx,w,h);
}
}

function drawParkScene(ctx,w,h){
ctx.fillStyle='#87CEEB';ctx.fillRect(0,0,w,h*0.6);
ctx.fillStyle='#90EE90';ctx.fillRect(0,h*0.6,w,h*0.4);
ctx.fillStyle='#FFD700';
ctx.beginPath();ctx.arc(w*0.8,h*0.15,40,0,Math.PI*2);ctx.fill();
ctx.fillStyle='#FFA500';
ctx.beginPath();ctx.arc(w*0.8,h*0.15,50,0,Math.PI*2);ctx.fill();
for(let i=0;i<5;i++){
const tx=w*0.1+i*w*0.2,ty=h*0.45;
ctx.fillStyle='#8B4513';ctx.fillRect(tx-5,ty,10,40);
ctx.fillStyle='#228B22';ctx.beginPath();ctx.arc(tx,ty-10,25,0,Math.PI*2);ctx.fill();
ctx.fillStyle='#32CD32';ctx.beginPath();ctx.arc(tx-8,ty-5,18,0,Math.PI*2);ctx.fill();
}
ctx.fillStyle='#fff';
for(let i=0;i<3;i++){
const cx=w*0.2+i*w*0.3,cy=h*0.1;
ctx.beginPath();ctx.arc(cx,cy,20,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(cx+25,cy-5,25,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(cx+45,cy,18,0,Math.PI*2);ctx.fill();
}
}

function drawBeachScene(ctx,w,h){
ctx.fillStyle='#FF6B6B';ctx.fillRect(0,0,w,h*0.3);
ctx.fillStyle='#FFA07A';ctx.fillRect(0,h*0.3,w,h*0.2);
ctx.fillStyle='#FFD700';ctx.fillRect(0,h*0.5,w,h*0.1);
ctx.fillStyle='#87CEEB';ctx.fillRect(0,h*0.6,w,h*0.4);
ctx.fillStyle='#F4A460';ctx.fillRect(0,h*0.6,w,h*0.4);
ctx.fillStyle='#FFD700';
ctx.beginPath();ctx.arc(w*0.7,h*0.1,50,0,Math.PI*2);ctx.fill();
}

function drawCityScene(ctx,w,h){
for(let i=0;i<8;i++){
const bx=i*w/8,bw=w/8-5,bh=h*0.3+Math.random()*h*0.3;
ctx.fillStyle=`hsl(${220+i*10},30%,${20+Math.random()*20}%)`;
ctx.fillRect(bx,h-bh,bw,bh);
ctx.fillStyle='#FFD700';
for(let wy=h-bh+10;wy<h-10;wy+=20){
for(let wx=bx+5;wx<bx+bw-5;wx+=15){
if(Math.random()>0.3)ctx.fillRect(wx,wy,8,10);
}
}
}
}

function drawSpaceScene(ctx,w,h){
ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);
for(let i=0;i<100;i++){
ctx.fillStyle=`rgba(255,255,255,${Math.random()})`;
ctx.beginPath();ctx.arc(Math.random()*w,Math.random()*h,Math.random()*2,0,Math.PI*2);ctx.fill();
}
ctx.fillStyle='#FF6B6B';
ctx.beginPath();ctx.arc(w*0.2,h*0.3,30,0,Math.PI*2);ctx.fill();
ctx.fillStyle='#4169E1';
ctx.beginPath();ctx.arc(w*0.8,h*0.7,20,0,Math.PI*2);ctx.fill();
}

function drawSceneChars(ctx,w,h,scene,time){
scene.characters.forEach((char,i)=>{
const cx=w*0.2+i*(w*0.6/Math.max(scene.characters.length,1))+w*0.1;
const cy=h*0.65;
drawChar(ctx,cx,cy,char,time,scene.animation);
});
}

function drawChar(ctx,x,y,char,time,anim){
ctx.save();
const speed=anim==='fast'?5:anim==='slow'?0.5:1;
const t=time*speed;
if(anim==='bounce'){
ctx.translate(0,Math.sin(t*3)*15);
}else if(anim==='wave'){
ctx.translate(Math.sin(t*2)*20,0);
}else if(anim==='jump'){
ctx.translate(0,Math.abs(Math.sin(t*2))*-50);
}else if(anim==='slide'){
ctx.translate(Math.sin(t)*30,0);
}else if(anim==='spin'){
ctx.translate(x,y);
ctx.rotate(t*2);
ctx.translate(-x,-y);
}
const skin=char.skinColor||'#FDBCB4';
const hair=char.hairColor||'#2C1B18';
const shirt=char.shirtColor||'#E74C3C';
const hat=char.hatColor||'#E74C3C';
const hatStyle=char.hatStyle||'none';
const body=char.bodyStyle||'round';
const expr=char.expression||'happy';
const bw=body==='thin'?25:body==='chubby'?40:32;
const bh=body==='tall'?55:body==='thin'?45:38;
ctx.strokeStyle='#333';ctx.lineWidth=2;
ctx.fillStyle=shirt;
ctx.beginPath();ctx.ellipse(x,y+10,bw,bh,0,0,Math.PI*2);ctx.fill();ctx.stroke();
ctx.fillStyle=skin;
ctx.beginPath();ctx.arc(x,y-15,22,0,Math.PI*2);ctx.fill();ctx.stroke();
ctx.fillStyle=hair;
ctx.beginPath();ctx.arc(x,y-20,23,Math.PI,0);ctx.fill();
ctx.beginPath();ctx.ellipse(x-22,y-10,8,12,0.3,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.ellipse(x+22,y-10,8,12,-0.3,0,Math.PI*2);ctx.fill();
if(hatStyle==='cap'){
ctx.fillStyle=hat;
ctx.beginPath();ctx.ellipse(x,y-28,24,7,0,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(x,y-30,22,Math.PI,0);ctx.fill();
ctx.fillStyle=hat;ctx.fillRect(x+18,y-34,15,6);
}else if(hatStyle==='tophat'){
ctx.fillStyle=hat;
ctx.fillRect(x-14,y-58,28,28);
ctx.fillRect(x-19,y-32,38,6);
}else if(hatStyle==='crown'){
ctx.fillStyle=hat;
ctx.beginPath();ctx.moveTo(x-17,y-30);ctx.lineTo(x-17,y-48);ctx.lineTo(x-9,y-40);ctx.lineTo(x,y-52);ctx.lineTo(x+9,y-40);ctx.lineTo(x+17,y-48);ctx.lineTo(x+17,y-30);ctx.closePath();ctx.fill();
ctx.fillStyle='#FFD700';
ctx.beginPath();ctx.arc(x-11,y-36,2.5,0,Math.PI*2);ctx.arc(x,y-46,2.5,0,Math.PI*2);ctx.arc(x+11,y-36,2.5,0,Math.PI*2);ctx.fill();
}else if(hatStyle==='beanie'){
ctx.fillStyle=hat;
ctx.beginPath();ctx.arc(x,y-25,22,Math.PI,0);ctx.fill();
ctx.fillRect(x-22,y-25,44,9);
}
ctx.fillStyle='#333';
if(expr==='wink'){
ctx.beginPath();ctx.arc(x-8,y-18,3.5,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(x+8,y-18,3.5,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(x-8,y-18,3.5,0,Math.PI);ctx.stroke();
}else if(expr==='surprised'){
ctx.fillStyle='#fff';
ctx.beginPath();ctx.arc(x-8,y-18,6,0,Math.PI*2);ctx.fill();ctx.stroke();
ctx.beginPath();ctx.arc(x+8,y-18,6,0,Math.PI*2);ctx.fill();ctx.stroke();
ctx.fillStyle='#333';
ctx.beginPath();ctx.arc(x-8,y-18,2.5,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(x+8,y-18,2.5,0,Math.PI*2);ctx.fill();
}else{
ctx.beginPath();ctx.arc(x-8,y-18,3.5,0,Math.PI*2);ctx.fill();
ctx.beginPath();ctx.arc(x+8,y-18,3.5,0,Math.PI*2);ctx.fill();
}
ctx.strokeStyle='#333';ctx.lineWidth=2.5;ctx.beginPath();
if(expr==='happy'){ctx.arc(x,y-10,7,0,Math.PI);ctx.stroke();
}else if(expr==='sad'){ctx.arc(x,y-5,7,Math.PI,0);ctx.stroke();
}else if(expr==='angry'){
ctx.moveTo(x-10,y-24);ctx.lineTo(x-3,y-22);ctx.stroke();
ctx.moveTo(x+10,y-24);ctx.lineTo(x+3,y-22);ctx.stroke();
ctx.moveTo(x-6,y-10);ctx.lineTo(x+6,y-10);ctx.stroke();
}else if(expr==='surprised'){ctx.beginPath();ctx.ellipse(x,y-10,5,6,0,0,Math.PI*2);ctx.stroke();
}else if(expr==='wink'){ctx.arc(x,y-10,7,0,Math.PI);ctx.stroke();
}
ctx.restore();
}

function drawStickers(ctx,w,h,scene,time){
scene.stickers.forEach(s=>{
ctx.save();
ctx.translate(w*s.x,h*s.y);
ctx.rotate(s.rotation+time);
ctx.font=s.size+'px serif';
ctx.textAlign='center';ctx.textBaseline='middle';
ctx.fillText(s.emoji,0,0);
ctx.restore();
});
}

