function renderTimeline(){
const track=document.getElementById('timelineTrack');
const playhead=document.getElementById('playhead');
track.innerHTML='<div class="timeline-playhead" id="playhead"></div>';
const totalDur=scenes.reduce((a,s)=>a+s.duration,0);
let offset=0;
const colors=['#e74c3c','#3498db','#2ecc71','#f39c12','#9b59b6','#1abc9c','#e67e22','#e91e63'];
scenes.forEach((s,i)=>{
const pct=(s.duration/totalDur)*100;
const div=document.createElement('div');
div.className='timeline-segment'+(i===currentSceneIdx?' active':'');
div.style.left=offset+'%';
div.style.width=pct+'%';
div.style.background=colors[i%colors.length];
div.textContent=s.name;
div.onclick=()=>{currentSceneIdx=i;renderTimeline();drawMainCanvas();};
track.appendChild(div);
offset+=pct;
});
updatePlayhead();
}

function updatePlayhead(){
const track=document.getElementById('timelineTrack');
if(!track)return;
const totalDur=scenes.reduce((a,s)=>a+s.duration,0);
const pct=(animTime/totalDur)*100;
const playhead=document.getElementById('playhead');
if(playhead)playhead.style.left=Math.min(pct,100)+'%';
document.getElementById('tlTime').textContent=formatTime(animTime);
}

function formatTime(s){
const m=Math.floor(s/60);
const sec=Math.floor(s%60);
return m+':'+(sec<10?'0':'')+sec;
}

function playAnimation(){
if(isPlaying&&!isPaused){
cancelAnimationFrame(animFrame);
return;
}
isPlaying=true;isPaused=false;
const startTime=performance.now()-animTime*1000;
function animate(now){
if(!isPlaying||isPaused)return;
animTime=(now-startTime)/1000;
const totalDur=scenes.reduce((a,s)=>a+s.duration,0);
if(animTime>=totalDur){
animTime=0;
currentSceneIdx=0;
}
drawMainCanvas();
renderTimeline();
animFrame=requestAnimationFrame(animate);
}
animFrame=requestAnimationFrame(animate);
showToast('Playing...','info');
}

function pauseAnimation(){
isPaused=!isPaused;
showToast(isPaused?'Paused':'Playing','info');
}

function stopAnimation(){
isPlaying=false;isPaused=false;
cancelAnimationFrame(animFrame);
animTime=0;
drawMainCanvas();
renderTimeline();
}

function prevScene(){
if(currentSceneIdx>0){
currentSceneIdx--;
animTime=0;
drawMainCanvas();
renderTimeline();
renderSceneList();
}
}

function nextScene(){
if(currentSceneIdx<scenes.length-1){
currentSceneIdx++;
animTime=0;
drawMainCanvas();
renderTimeline();
renderSceneList();
}
}

function deleteScene(){
if(scenes.length<=1){showToast('Cannot delete last scene!','error');return;}
scenes.splice(currentSceneIdx,1);
if(currentSceneIdx>=scenes.length)currentSceneIdx=scenes.length-1;
animTime=0;
drawMainCanvas();
renderTimeline();
renderSceneList();
showToast('Scene deleted!','success');
}

function duplicateScene(){
const s=scenes[currentSceneIdx];
const dup={...s,id:Date.now(),name:s.name+' (copy)',characters:[...s.characters.map(c=>({...c}))],stickers:[...s.stickers]};
scenes.splice(currentSceneIdx+1,0,dup);
currentSceneIdx++;
renderSceneList();
renderTimeline();
drawMainCanvas();
showToast('Scene duplicated!','success');
}

function seekTimeline(val){
const totalDur=scenes.reduce((a,s)=>a+s.duration,0);
animTime=(val/100)*totalDur;
drawMainCanvas();
renderTimeline();
}

function toggleRecording(){
if(isRecording){
stopRecording();
}else{
startRecording();
}
}

async function startRecording(){
try{
const stream=await navigator.mediaDevices.getUserMedia({audio:true});
audioCtx=new(window.AudioContext||window.webkitAudioContext)();
analyser=audioCtx.createAnalyser();
analyser.fftSize=256;
const source=audioCtx.createMediaStreamSource(stream);
source.connect(analyser);
mediaRecorder=new MediaRecorder(stream);
audioChunks=[];
mediaRecorder.ondataavailable=e=>audioChunks.push(e.data);
mediaRecorder.onstop=()=>{
const blob=new Blob(audioChunks,{type:'audio/webm'});
voiceRecordings.push({blob,name:'Recording '+(voiceRecordings.length+1),duration:recInterval?Math.floor((Date.now()-recStartTime)/1000):0});
renderVoiceList();
stream.getTracks().forEach(t=>t.stop());
};
mediaRecorder.start();
isRecording=true;
document.getElementById('recBtn').textContent='⏹ Stop Recording';
document.getElementById('recIndicator').classList.add('active');
recStartTime=Date.now();
recInterval=setInterval(()=>{
const elapsed=Math.floor((Date.now()-recStartTime)/1000);
document.getElementById('voiceTimer').textContent=formatTimeVid(elapsed);
},1000);
drawWave();
showToast('Recording started!','success');
}catch(e){
