mediaRecorder.stop();
}
isRecording=false;
document.getElementById('recBtn').textContent='🔴 Start Recording';
document.getElementById('recIndicator').classList.remove('active');
if(recInterval)clearInterval(recInterval);
if(waveAnim)cancelAnimationFrame(waveAnim);
showToast('Recording saved!','success');
}

function formatTimeVid(s){
const m=Math.floor(s/60);
const sec=s%60;
return (m<10?'0':'')+m+':'+(sec<10?'0':'')+sec;
}

function drawWave(){
if(!isRecording)return;
const canvas=document.getElementById('waveCanvas');
const ctx=canvas.getContext('2d');
const w=canvas.width,h=canvas.height;
ctx.fillStyle='#0a0a2e';ctx.fillRect(0,0,w,h);
if(analyser){
const data=new Uint8Array(analyser.frequencyBinCount);
analyser.getByteTimeDomainData(data);
ctx.beginPath();
ctx.strokeStyle='#6c3ce0';ctx.lineWidth=2;
const sliceW=w/data.length;
for(let i=0;i<data.length;i++){
const v=data[i]/128.0;
const y=v*h/2;
if(i===0)ctx.moveTo(0,y);else ctx.lineTo(i*sliceW,y);
}
ctx.lineTo(w,h/2);ctx.stroke();
}
waveAnim=requestAnimationFrame(drawWave);
}

