function drawLeagueTable() {
  const grad = ctx.createLinearGradient(0, 0, 0, canvas.height);
  grad.addColorStop(0, '#0a1628');
  grad.addColorStop(1, '#1a237e');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#ffd600';
  ctx.font = 'bold 36px "Segoe UI", Arial';
  ctx.textAlign = 'center';
  const leagueName = selectedLeague === 'liga1' ? 'Liga 1 Indonesia' : 'Liga Internasional';
  ctx.fillText(leagueName, canvas.width / 2, 45);

  sortLeagueTable();

  const tableW = Math.min(900, canvas.width - 40);
  const tableX = canvas.width / 2 - tableW / 2;
  const tableY = 70;
  const rowH = 35;
  const colW = [40, 30, 120, 40, 40, 40, 40, 40, 40, 60]; // pos, badge, name, P, W, D, L, GF, GA, GD, Pts

  // Header
  ctx.fillStyle = 'rgba(255,215,0,0.2)';
  ctx.fillRect(tableX, tableY, tableW, rowH);
  ctx.strokeStyle = '#ffd600';
  ctx.lineWidth = 1;
  ctx.strokeRect(tableX, tableY, tableW, rowH);

  let xOff = tableX;
  const headers = ['#', '', 'Tim', 'M', 'Mn', 'S', 'K', 'GM', 'GK', 'SG', 'Poin'];
  headers.forEach((h, i) => {
    ctx.fillStyle = '#ffd600';
    ctx.font = 'bold 12px "Segoe UI", Arial';
    ctx.textAlign = 'center';
    ctx.fillText(h, xOff + colW[i] / 2, tableY + 22);
    xOff += colW[i];
  });

  // Rows
  leagueTable.forEach((team, i) => {
    const y = tableY + rowH + i * rowH;
    const isPersib = team.name === 'Persib Bandung';
    ctx.fillStyle = isPersib ? 'rgba(255,215,0,0.15)' : i % 2 === 0 ? 'rgba(255,255,255,0.05)' : 'rgba(255,255,255,0.02)';
    ctx.fillRect(tableX, y, tableW, rowH);

    xOff = tableX;

    // Position
    ctx.fillStyle = i < 2 ? '#ffd600' : i < 4 ? '#4caf50' : '#aaa';
    ctx.font = 'bold 13px "Segoe UI", Arial';
    ctx.textAlign = 'center';
    ctx.fillText(i + 1, xOff + colW[0] / 2, y + 22);
    xOff += colW[0];

    // Badge
    ctx.beginPath();
    ctx.arc(xOff + 15, y + rowH / 2, 12, 0, Math.PI * 2);
    ctx.fillStyle = team.color;
    ctx.fill();
    ctx.strokeStyle = team.color2;
    ctx.lineWidth = 1;
    ctx.stroke();
    xOff += colW[1];

    // Name
    ctx.fillStyle = isPersib ? '#ffd600' : '#fff';
    ctx.font = isPersib ? 'bold 13px "Segoe UI", Arial' : '12px "Segoe UI", Arial';
    ctx.textAlign = 'left';
    ctx.fillText(team.name, xOff + 5, y + 22);
    xOff += colW[2];

    // Stats
    const stats = [team.played, team.won, team.drawn, team.lost, team.gf, team.ga, team.gd, team.points];
    stats.forEach((s, si) => {
      ctx.fillStyle = si === 7 ? '#ffd600' : '#ccc';
      ctx.font = '12px "Segoe UI", Arial';
      ctx.textAlign = 'center';
      ctx.fillText(s, xOff + colW[3 + si] / 2, y + 22);
      xOff += colW[3 + si];
    });
  });

  // Legend
  const legendY = tableY + rowH + leagueTable.length * rowH + 15;
  ctx.fillStyle = '#ffd600';
  ctx.font = '10px "Segoe UI", Arial';
  ctx.textAlign = 'left';
  ctx.fillText('🥇 Liga Champions | 🥈 Liga Europa | Persib: Highlighted', tableX, legendY);

  // Next match button
  const btnW = 220, btnH = 40;
  const btnX = canvas.width / 2 - btnW / 2;
  const btnY2 = legendY + 30;

  ctx.fillStyle = 'rgba(255,215,0,0.2)';
  ctx.fillRect(btnX, btnY2, btnW, btnH);
  ctx.strokeStyle = '#ffd600';
  ctx.lineWidth = 2;
  ctx.strokeRect(btnX, btnY2, btnW, btnH);
  ctx.fillStyle = '#ffd600';
  ctx.font = 'bold 18px "Segoe UI", Arial';
  ctx.textAlign = 'center';
  ctx.fillText('⚽ Main Pertandingan Berikutnya', canvas.width / 2, btnY2 + 26);

  // Back button
  ctx.fillStyle = 'rgba(255,255,255,0.1)';
  ctx.fillRect(20, canvas.height - 50, 120, 35);
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1;
  ctx.strokeRect(20, canvas.height - 50, 120, 35);
  ctx.fillStyle = '#fff';
  ctx.font = '16px "Segoe UI", Arial';
  ctx.textAlign = 'center';
  ctx.fillText('← Kembali', 80, canvas.height - 28);
}

