  if (car.fuel <= 0 && Math.abs(car.vx) < 0.5) {
    car.crashed = true;
    car.crashTimer = 2;
    car.vx = -2;
    return;
  }

  // Get wheel positions
  const rearX = car.x - Math.cos(car.angle) * car.wheelBase * 0.45;
  const frontX = car.x + Math.cos(car.angle) * car.wheelBase * 0.45;
  const rearY = car.y + Math.sin(car.angle) * car.wheelBase * 0.3;
  const frontY = car.y - Math.sin(car.angle) * car.wheelBase * 0.3;

  const rearGroundY = getTerrainY(rearX);
  const frontGroundY = getTerrainY(frontX);

  // Check if wheels are on ground
  const rearWheelBottom = rearY + car.wheelSize;
  const frontWheelBottom = frontY + car.wheelSize;

  const rearOnGround = rearWheelBottom >= rearGroundY - 5;
  const frontOnGround = frontWheelBottom >= frontGroundY - 5;
  car.onGround = rearOnGround || frontOnGround;

  // Suspension
  if (rearOnGround) {
    const penetration = rearWheelBottom - rearGroundY;
    const springForce = -penetration * 0.3;
    const damping = -car.vy * 0.1;
    car.vy += (springForce + damping) * dt;
    car.angularVel += penetration * 0.002 * dt;
