canvas.addEventListener('touchcancel', handleTouchEnd, { passive: false });

function handleTouch(e) {
  e.preventDefault();
  if (gameState !== 'playing') return;

  inputs[0] = { accelerate: false, brake: false };
  inputs[1] = { accelerate: false, brake: false };

  for (let touch of e.touches) {
    const tx = touch.clientX;
    const ty = touch.clientY;
    const halfW = W / 2;

    // Player 1 (left side): right half accelerates, left half brakes
    if (tx < halfW) {
      inputs[0].brake = true;
      if (tx > halfW * 0.5) inputs[0].accelerate = true;
    } else {
      // Player 2 (right side): left half accelerates, right half brakes
      inputs[1].accelerate = true;
      if (tx > halfW + halfW * 0.5) inputs[1].brake = true;
    }
  }
}

function handleTouchEnd(e) {
  e.preventDefault();
  if (gameState !== 'playing') return;

  inputs[0] = { accelerate: false, brake: false };
  inputs[1] = { accelerate: false, brake: false };

  for (let touch of e.touches) {
    const tx = touch.clientX;
    const halfW = W / 2;
    if (tx < halfW) {
      inputs[0].brake = true;
      if (tx > halfW * 0.5) inputs[0].accelerate = true;
    } else {
      inputs[1].accelerate = true;
      if (tx > halfW + halfW * 0.5) inputs[1].brake = true;
