  grad.addColorStop(0.3, '#2d3a6e');
  grad.addColorStop(0.6, '#4a6fa1');
  grad.addColorStop(0.85, '#87CEEB');
  grad.addColorStop(1, '#b8e6b8');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Sun
  const sunX = W * 0.8 - (camX * 0.02);
  const sunY = H * 0.15;
  const sunGrad = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, 60);
  sunGrad.addColorStop(0, 'rgba(255,255,200,1)');
  sunGrad.addColorStop(0.3, 'rgba(255,220,100,0.8)');
  sunGrad.addColorStop(1, 'rgba(255,200,50,0)');
  ctx.fillStyle = sunGrad;
  ctx.fillRect(sunX - 80, sunY - 80, 160, 160);

  // Clouds
  for (let cloud of clouds) {
    const cx = cloud.x - camX * 0.1 + performance.now() * cloud.speed * 0.01;
    const screenX = ((cx % (W + 200)) + W + 200) % (W + 200) - 100;
    ctx.fillStyle = `rgba(255,255,255,${cloud.opacity})`;
    ctx.beginPath();
    ctx.ellipse(screenX, cloud.y, cloud.size, cloud.size * 0.5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(screenX - cloud.size * 0.4, cloud.y + 5, cloud.size * 0.6, cloud.size * 0.4, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(screenX + cloud.size * 0.4, cloud.y + 3, cloud.size * 0.5, cloud.size * 0.35, 0, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawTerrain(camX, camY) {
  // Far hills (parallax)
  ctx.fillStyle = '#3a7d44';
  ctx.beginPath();
  ctx.moveTo(0, H);
  for (let px = 0; px <= W; px += 10) {
    const wx = px + camX * 0.3;
    const wy = getTerrainY(wx) * 0.3 + H * 0.3 - camY * 0.2;
    ctx.lineTo(px, wy);
  }
  ctx.lineTo(W, H);
  ctx.closePath();
  ctx.fill();

  // Mid hills
  ctx.fillStyle = '#2d6b35';
  ctx.beginPath();
  ctx.moveTo(0, H);
  for (let px = 0; px <= W; px += 8) {
    const wx = px + camX * 0.6;
    const wy = getTerrainY(wx) * 0.5 + H * 0.15 - camY * 0.1;
    ctx.lineTo(px, wy);
  }
  ctx.lineTo(W, H);
  ctx.closePath();
  ctx.fill();

  // Main terrain
  const startIdx = Math.max(0, Math.floor((camX - 50) / 8));
  const endIdx = Math.min(terrain.length - 1, Math.floor((camX + W + 50) / 8));

  // Terrain fill
  const terrainGrad = ctx.createLinearGradient(0, H * 0.3, 0, H);
  terrainGrad.addColorStop(0, '#4a8c3f');
  terrainGrad.addColorStop(0.15, '#3d7a34');
  terrainGrad.addColorStop(0.4, '#6b4226');
  terrainGrad.addColorStop(0.7, '#5a3520');
  terrainGrad.addColorStop(1, '#4a2a15');

  ctx.fillStyle = terrainGrad;
  ctx.beginPath();
  ctx.moveTo(terrain[startIdx].x - camX, H);

  for (let i = startIdx; i <= endIdx; i++) {
    const sx = terrain[i].x - camX;
    const sy = terrain[i].y - camY;
    ctx.lineTo(sx, sy);
  }

  ctx.lineTo(terrain[endIdx].x - camX, H);
  ctx.closePath();
  ctx.fill();

  // Terrain outline (grass top)
  ctx.strokeStyle = '#5cb85c';
  ctx.lineWidth = 3;
  ctx.beginPath();
  for (let i = startIdx; i <= endIdx; i++) {
    const sx = terrain[i].x - camX;
    const sy = terrain[i].y - camY;
    if (i === startIdx) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  }
  ctx.stroke();

  // Grass tufts
  ctx.strokeStyle = '#6dd66d';
  ctx.lineWidth = 1.5;
  for (let i = startIdx; i <= endIdx; i += 3) {
    const sx = terrain[i].x - camX;
    const sy = terrain[i].y - camY;
    const angle = getTerrainAngle(terrain[i].x);
    for (let g = -2; g <= 2; g++) {
      ctx.beginPath();
      ctx.moveTo(sx + g * 3, sy);
      ctx.lineTo(sx + g * 3 + Math.sin(angle) * 8, sy - 8 - Math.random() * 5);
      ctx.stroke();
    }
  }

  // Trees
  for (let tree of trees) {
    const sx = tree.x - camX;
    const sy = tree.y - camY;
    if (sx < -50 || sx > W + 50) continue;

    // Trunk
    ctx.fillStyle = '#5a3520';
    ctx.fillRect(sx - 3, sy - tree.size, 6, tree.size);

    // Leaves
    ctx.fillStyle = tree.type === 0 ? '#2d8a3e' : tree.type === 1 ? '#1e6b2e' : '#3da84e';
    if (tree.type === 2) {
      // Round tree
      ctx.beginPath();
      ctx.arc(sx, sy - tree.size - 10, tree.size * 0.6, 0, Math.PI * 2);
      ctx.fill();
    } else {
      // Pine tree
      ctx.beginPath();
      ctx.moveTo(sx, sy - tree.size * 2);
      ctx.lineTo(sx - tree.size * 0.5, sy - tree.size * 0.3);
      ctx.lineTo(sx + tree.size * 0.5, sy - tree.size * 0.3);
      ctx.closePath();
      ctx.fill();
    }
  }
}

function drawCar(car, camX, camY, isPlayer1) {
  const sx = car.x - camX;
  const sy = car.y - camY;

  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(car.angle);

  const ct = CAR_TYPES[selectedCar];

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.2)';
  ctx.beginPath();
  ctx.ellipse(0, car.wheelSize + 2, car.bodyW * 0.5, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body
  const bodyGrad = ctx.createLinearGradient(-car.bodyW / 2, -car.bodyH, car.bodyW / 2, 0);
  bodyGrad.addColorStop(0, lightenColor(car.color, 40));
  bodyGrad.addColorStop(0.5, car.color);
  bodyGrad.addColorStop(1, darkenColor(car.color, 40));
  ctx.fillStyle = bodyGrad;

  if (selectedCar === 0) {
    // Jeep body
    ctx.beginPath();
    ctx.roundRect(-car.bodyW / 2, -car.bodyH, car.bodyW, car.bodyH + 5, 5);
    ctx.fill();
    // Cabin
    ctx.fillStyle = darkenColor(car.color, 20);
    ctx.beginPath();
    ctx.roundRect(-car.bodyW * 0.15, -car.bodyH - 15, car.bodyW * 0.5, 18, 4);
    ctx.fill();
    // Windshield
    ctx.fillStyle = 'rgba(150,220,255,0.6)';
    ctx.beginPath();
    ctx.roundRect(car.bodyW * 0.05, -car.bodyH - 13, car.bodyW * 0.2, 14, 2);
    ctx.fill();
    // Roll bar
    ctx.strokeStyle = '#888';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-car.bodyW * 0.2, -car.bodyH - 15);
    ctx.lineTo(-car.bodyW * 0.2, -car.bodyH - 22);
    ctx.lineTo(car.bodyW * 0.25, -car.bodyH - 22);
    ctx.lineTo(car.bodyW * 0.25, -car.bodyH - 15);
    ctx.stroke();
  } else {
    // Sports car body
    ctx.beginPath();
    ctx.moveTo(-car.bodyW / 2, 0);
    ctx.lineTo(-car.bodyW / 2, -car.bodyH * 0.5);
    ctx.lineTo(-car.bodyW * 0.1, -car.bodyH);
    ctx.lineTo(car.bodyW * 0.3, -car.bodyH);
    ctx.lineTo(car.bodyW / 2, -car.bodyH * 0.4);
    ctx.lineTo(car.bodyW / 2, 0);
    ctx.closePath();
    ctx.fill();
    // Windshield
    ctx.fillStyle = 'rgba(150,220,255,0.6)';
    ctx.beginPath();
    ctx.moveTo(car.bodyW * 0.0, -car.bodyH);
    ctx.lineTo(car.bodyW * 0.25, -car.bodyH);
    ctx.lineTo(car.bodyW * 0.3, -car.bodyH * 0.5);
    ctx.lineTo(car.bodyW * 0.05, -car.bodyH * 0.5);
    ctx.closePath();
    ctx.fill();
  }

  // Headlight
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(car.bodyW / 2 - 3, -car.bodyH * 0.3, 3, 0, Math.PI * 2);
  ctx.fill();

  // Taillight
  ctx.fillStyle = '#ff3333';
  ctx.beginPath();
  ctx.arc(-car.bodyW / 2 + 3, -car.bodyH * 0.3, 3, 0, Math.PI * 2);
  ctx.fill();

  // Wheels
  const wheelY = 2;
  // Rear wheel
  drawWheel(-car.wheelBase * 0.4, wheelY, ct.wheelSize, car.crashed ? '#666' : '#222');
  // Front wheel
  drawWheel(car.wheelBase * 0.4, wheelY, ct.wheelSize, car.crashed ? '#666' : '#222');

  // Player indicator
  ctx.restore();

  // Player number badge
  ctx.fillStyle = car.color;
  ctx.beginPath();
  ctx.arc(sx, sy - car.bodyH - 30, 12, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 12px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(isPlayer1 ? '1' : '2', sx, sy - car.bodyH - 30);
}

function drawWheel(x, y, size, color) {
  // Tire
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(x, y, size, 0, Math.PI * 2);
  ctx.fill();

  // Rim
  ctx.fillStyle = '#888';
  ctx.beginPath();
  ctx.arc(x, y, size * 0.55, 0, Math.PI * 2);
  ctx.fill();

  // Spokes
  ctx.strokeStyle = '#666';
  ctx.lineWidth = 1.5;
  for (let a = 0; a < 5; a++) {
    const angle = a * Math.PI * 2 / 5 + (x + y) * 0.05;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(angle) * size * 0.5, y + Math.sin(angle) * size * 0.5);
    ctx.stroke();
  }

  // Hub
  ctx.fillStyle = '#aaa';
  ctx.beginPath();
  ctx.arc(x, y, size * 0.2, 0, Math.PI * 2);
  ctx.fill();
}

function drawCoins(camX, camY) {
  const time = performance.now() * 0.003;
  for (let coin of coins) {
    if (coin.collected) continue;
    const sx = coin.x - camX;
    const sy = coin.y - camY + Math.sin(time + coin.bobOffset) * 5;
    if (sx < -20 || sx > W + 20) continue;

    // Glow
    ctx.fillStyle = 'rgba(241,196,15,0.3)';
    ctx.beginPath();
    ctx.arc(sx, sy, 14, 0, Math.PI * 2);
    ctx.fill();

    // Coin
    ctx.fillStyle = '#f1c40f';
    ctx.beginPath();
    ctx.arc(sx, sy, 10, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#f39c12';
    ctx.beginPath();
    ctx.arc(sx, sy, 7, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#f1c40f';
    ctx.font = 'bold 10px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('$', sx, sy);
  }
}

function drawFuelCans(camX, camY) {
  const time = performance.now() * 0.003;
  for (let fuel of fuelCans) {
    if (fuel.collected) continue;
    const sx = fuel.x - camX;
    const sy = fuel.y - camY + Math.sin(time + fuel.x) * 3;
    if (sx < -20 || sx > W + 20) continue;

    // Glow
    ctx.fillStyle = 'rgba(46,204,113,0.3)';
    ctx.beginPath();
    ctx.arc(sx, sy, 16, 0, Math.PI * 2);
    ctx.fill();

    // Can body
    ctx.fillStyle = '#27ae60';
    ctx.beginPath();
    ctx.roundRect(sx - 8, sy - 10, 16, 18, 3);
    ctx.fill();

    // F label
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 10px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('F', sx, sy + 1);

    // Cap
    ctx.fillStyle = '#c0392b';
    ctx.fillRect(sx - 4, sy - 13, 8, 4);
  }
}

function drawParticles(camX, camY) {
  for (let p of particles) {
    const sx = p.x - camX;
    const sy = p.y - camY;
    const alpha = p.life / p.maxLife;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(sx, sy, p.size * alpha, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawHUD(camX) {
  const p1 = players[0];
  const p2 = players[1];

  // Top bar background
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  ctx.beginPath();
  ctx.roundRect(5, 5, W - 10, 55, 10);
  ctx.fill();

  // Player 1 info (left)
  ctx.fillStyle = p1.color;
  ctx.font = 'bold 14px Arial';
  ctx.textAlign = 'left';
  ctx.fillText('P1', 15, 25);

  // Distance
  ctx.fillStyle = '#fff';
  ctx.font = '12px Arial';
  const dist1 = Math.floor(p1.distance / 100);
  ctx.fillText(`${dist1}m`, 15, 42);

  // Fuel bar P1
  const fuelW1 = 60;
  const fuelH1 = 8;
  const fuelX1 = 55;
  const fuelY1 = 33;
  ctx.fillStyle = '#333';
  ctx.fillRect(fuelX1, fuelY1, fuelW1, fuelH1);
  const fuelPct1 = p1.fuel / p1.fuelCap;
  ctx.fillStyle = fuelPct1 > 0.3 ? '#2ecc71' : '#e74c3c';
  ctx.fillRect(fuelX1, fuelY1, fuelW1 * fuelPct1, fuelH1);
  ctx.strokeStyle = '#555';
  ctx.lineWidth = 1;
  ctx.strokeRect(fuelX1, fuelY1, fuelW1, fuelH1);

  // Coins P1
  ctx.fillStyle = '#f1c40f';
  ctx.font = 'bold 13px Arial';
  ctx.fillText(`🪙 ${p1.coins}`, 15, 55);

  // Player 2 info (right)
  ctx.textAlign = 'right';
  ctx.fillStyle = p2.color;
  ctx.font = 'bold 14px Arial';
  ctx.fillText('P2', W - 15, 25);

  ctx.fillStyle = '#fff';
  ctx.font = '12px Arial';
  const dist2 = Math.floor(p2.distance / 100);
  ctx.fillText(`${dist2}m`, W - 15, 42);

  const fuelX2 = W - 55 - fuelW1;
  ctx.fillStyle = '#333';
  ctx.fillRect(fuelX2, fuelY1, fuelW1, fuelH1);
  const fuelPct2 = p2.fuel / p2.fuelCap;
  ctx.fillStyle = fuelPct2 > 0.3 ? '#2ecc71' : '#e74c3c';
  ctx.fillRect(fuelX2, fuelY1, fuelW1 * fuelPct2, fuelH1);
  ctx.strokeStyle = '#555';
  ctx.strokeRect(fuelX2, fuelY1, fuelW1, fuelH1);

  ctx.fillStyle = '#f1c40f';
  ctx.font = 'bold 13px Arial';
  ctx.fillText(`🪙 ${p2.coins}`, W - 15, 55);

  // Progress bar (center top)
  const barW = W * 0.4;
  const barH = 6;
  const barX = (W - barW) / 2;
  const barY = 15;
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.fillRect(barX, barY, barW, barH);

  const finishX = terrain.length * 8 * 0.5;
  const p1Prog = Math.min(p1.distance / finishX, 1);
  const p2Prog = Math.min(p2.distance / finishX, 1);

  ctx.fillStyle = p1.color;
  ctx.fillRect(barX, barY, barW * p1Prog, barH);
  ctx.fillStyle = p2.color;
  ctx.fillRect(barX, barY + 7, barW * p2Prog, barH);

  // Finish flag
  ctx.fillStyle = '#fff';
  ctx.font = '10px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('🏁', barX + barW, barY + barH + 12);

  // Touch zone indicators
  const halfW = W / 2;
  ctx.fillStyle = 'rgba(255,255,255,0.05)';
  // P1 zones
  ctx.fillStyle = 'rgba(231,76,60,0.08)';
  ctx.fillRect(0, H * 0.5, halfW * 0.5, H * 0.5);
  ctx.fillStyle = 'rgba(52,152,219,0.08)';
  ctx.fillRect(halfW * 0.5, H * 0.5, halfW * 0.5, H * 0.5);
  // P2 zones
  ctx.fillStyle = 'rgba(52,152,219,0.08)';
  ctx.fillRect(halfW, H * 0.5, halfW * 0.5, H * 0.5);
  ctx.fillStyle = 'rgba(231,76,60,0.08)';
  ctx.fillRect(halfW + halfW * 0.5, H * 0.5, halfW * 0.5, H * 0.5);

  // Labels
  ctx.fillStyle = 'rgba(255,255,255,0.15)';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('P1 BRAKE', halfW * 0.25, H * 0.75);
  ctx.fillText('P1 GAS', halfW * 0.75, H * 0.75);
  ctx.fillText('P2 GAS', halfW + halfW * 0.25, H * 0.75);
  ctx.fillText('P2 BRAKE', halfW + halfW * 0.75, H * 0.75);

  // Crash message
  for (let car of players) {
    if (car.crashed) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, H / 2 - 30, W, 60);
      ctx.fillStyle = '#e74c3c';
      ctx.font = 'bold 24px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(`P${car.id + 1} CRASHED!`, W / 2, H / 2 + 8);
    }
  }

  // Finish message
  if (p1.finished || p2.finished) {
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, H / 2 - 25, W, 50);
    ctx.fillStyle = '#f1c40f';
    ctx.font = 'bold 22px Arial';
    ctx.textAlign = 'center';
    let msg = '';
    if (p1.finished && p2.finished) {
      msg = p1.distance > p2.distance ? '🏆 PLAYER 1 WINS!' : p2.distance > p1.distance ? '🏆 PLAYER 2 WINS!' : "🤝 TIE!";
    } else if (p1.finished) {
      msg = p1.distance > p2.distance ? '🏆 PLAYER 1 WINS!' : 'PLAYER 2 WINS!';
    } else {
      msg = p2.distance > p1.distance ? '🏆 PLAYER 2 WINS!' : 'PLAYER 1 WINS!';
    }
    ctx.fillText(msg, W / 2, H / 2 + 8);
  }
}

function lightenColor(hex, amount) {
  let r = parseInt(hex.slice(1, 3), 16);
  let g = parseInt(hex.slice(3, 5), 16);
  let b = parseInt(hex.slice(5, 7), 16);
  r = Math.min(255, r + amount);
  g = Math.min(255, g + amount);
  b = Math.min(255, b + amount);
  return `rgb(${r},${g},${b})`;
}

function darkenColor(hex, amount) {
  let r = parseInt(hex.slice(1, 3), 16);
  let g = parseInt(hex.slice(3, 5), 16);
  let b = parseInt(hex.slice(5, 7), 16);
  r = Math.max(0, r - amount);
  g = Math.max(0, g - amount);
  b = Math.max(0, b - amount);
  return `rgb(${r},${g},${b})`;
}

// Game loop
let lastTime = 0;
let cameraX = 0;
let cameraY = 0;

function gameLoop(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 16.67, 3);
  lastTime = timestamp;

  if (gameState === 'playing') {
    // Update
    for (let i = 0; i < players.length; i++) {
      updateCar(players[i], dt, inputs[i]);
    }
    updateParticles(dt);

    // Camera follows leader
    const leader = players.reduce((a, b) => a.distance > b.distance ? a : b);
    cameraX += (leader.x - W * 0.35 - cameraX) * 0.08 * dt;
    const camTargetY = leader.y - H * 0.4;
    cameraY += (camTargetY - cameraY) * 0.05 * dt;
    cameraY = Math.max(-100, Math.min(200, cameraY));

    // Check game over
    if (players[0].finished && players[1].finished) {
      gameState = 'gameover';
      setTimeout(showGameOver, 1000);
    }
    if (players[0].crashed && players[1].crashed && players[0].crashTimer <= 0 && players[1].crashTimer <= 0) {
      // Both crashed - determine winner by distance
      gameState = 'gameover';
      setTimeout(showGameOver, 500);
    }
  }

  // Draw
  ctx.clearRect(0, 0, W, H);
  drawSky(cameraX, cameraY);
  drawTerrain(cameraX, cameraY);
  drawCoins(cameraX, cameraY);
  drawFuelCans(cameraX, cameraY);
  drawParticles(cameraX, cameraY);

  // Draw cars (sort by Y for proper overlap)
  const sortedPlayers = [...players].sort((a, b) => a.y - b.y);
  for (let car of sortedPlayers) {
    drawCar(car, cameraX, cameraY, car.id === 0);
  }

  drawHUD(cameraX);

  requestAnimationFrame(gameLoop);
}

function showGameOver() {
  const p1 = players[0];
  const p2 = players[1];
  let result = '';

  if (p1.finished && p2.finished) {
    if (p1.distance > p2.distance) result = '🥇 Player 1 Wins!';
    else if (p2.distance > p1.distance) result = '🥇 Player 2 Wins!';
    else result = "🤝 It's a Tie!";
  } else if (p1.finished) {
    result = p1.distance > p2.distance ? '🥇 Player 1 Wins!' : '🥇 Player 2 Wins!';
  } else if (p2.finished) {
    result = p2.distance > p1.distance ? '🥇 Player 2 Wins!' : '🥇 Player 1 Wins!';
  } else {
    if (p1.distance > p2.distance) result = '🥇 Player 1 Wins (Distance)!';
    else result = '🥇 Player 2 Wins (Distance)!';
  }

  result += `<br><span style="font-size:0.8em;color:#aaa">
    P1: ${Math.floor(p1.distance/100)}m | 🪙${p1.coins} | P2: ${Math.floor(p2.distance/100)}m | 🪙${p2.coins}</span>`;

  document.getElementById('result-text').innerHTML = result;
  document.getElementById('game-over').style.display = 'flex';
}

function startGame() {
  document.getElementById('start-screen').style.display = 'none';
  gameState = 'playing';
  generateTerrain();

  players = [
    createPlayer(0, selectedCar, 50, CAR_TYPES[selectedCar].color),
    createPlayer(1, 1 - selectedCar, 50, CAR_TYPES[1 - selectedCar].color)
  ];

  // Set initial Y positions
  players[0].y = getTerrainY(50) - players[0].wheelSize;
  players[1].y = getTerrainY(55) - players[1].wheelSize;

  cameraX = 0;
  cameraY = 0;
  particles = [];
}

function restartGame() {
  document.getElementById('game-over').style.display = 'none';
  gameState = 'playing';
  generateTerrain();

  players = [
    createPlayer(0, selectedCar, 50, CAR_TYPES[selectedCar].color),
    createPlayer(1, 1 - selectedCar, 50, CAR_TYPES[1 - selectedCar].color)
  ];

  players[0].y = getTerrainY(50) - players[0].wheelSize;
  players[1].y = getTerrainY(55) - players[1].wheelSize;

  cameraX = 0;
  cameraY = 0;
  particles = [];
}

function selectCar(idx) {
  selectedCar = idx;
  document.querySelectorAll('.car-option').forEach(el => {
    el.classList.toggle('selected', parseInt(el.dataset.car) === idx);
  });
}

// Draw car previews
function drawCarPreviews() {
  for (let i = 0; i < 2; i++) {
    const pc = document.getElementById(`carPreview${i}`);
    const pctx = pc.getContext('2d');
    pctx.clearRect(0, 0, 100, 60);

    const ct = CAR_TYPES[i];
    const x = 50, y = 35;

    // Body
    pctx.fillStyle = ct.color;
    if (i === 0) {
      pctx.beginPath();
      pctx.roundRect(x - ct.bodyW / 2, y - ct.bodyH, ct.bodyW, ct.bodyH + 5, 5);
      pctx.fill();
      pctx.fillStyle = darkenColor(ct.color, 20);
      pctx.beginPath();
      pctx.roundRect(x - ct.bodyW * 0.15, y - ct.bodyH - 15, ct.bodyW * 0.5, 18, 4);
      pctx.fill();
    } else {
      pctx.beginPath();
      pctx.moveTo(x - ct.bodyW / 2, y);
      pctx.lineTo(x - ct.bodyW / 2, y - ct.bodyH * 0.5);
      pctx.lineTo(x - ct.bodyW * 0.1, y - ct.bodyH);
      pctx.lineTo(x + ct.bodyW * 0.3, y - ct.bodyH);
      pctx.lineTo(x + ct.bodyW / 2, y - ct.bodyH * 0.4);
      pctx.lineTo(x + ct.bodyW / 2, y);
      pctx.closePath();
      pctx.fill();
    }

    // Wheels
    drawWheelOnCtx(pctx, x - ct.wheelBase * 0.4, y + 2, ct.wheelSize);
    drawWheelOnCtx(pctx, x + ct.wheelBase * 0.4, y + 2, ct.wheelSize);
  }
}

function drawWheelOnCtx(pctx, x, y, size) {
  pctx.fillStyle = '#222';
  pctx.beginPath();
  pctx.arc(x, y, size, 0, Math.PI * 2);
  pctx.fill();
  pctx.fillStyle = '#888';
  pctx.beginPath();
  pctx.arc(x, y, size * 0.55, 0, Math.PI * 2);
  pctx.fill();
}

drawCarPreviews();
requestAnimationFrame(gameLoop);
