    sunLight.shadow.camera.near = 0.5;
    sunLight.shadow.camera.far = 500;
    sunLight.shadow.camera.left = -200;
    sunLight.shadow.camera.right = 200;
    sunLight.shadow.camera.top = 200;
    sunLight.shadow.camera.bottom = -200;
    scene.add(sunLight);

    const hemiLight = new THREE.HemisphereLight(0x88aacc, 0x445522, 0.4);
    scene.add(hemiLight);

    createTerrain();
    createBuildings();
    createTrees();
    createWeapons();
    createEnemies(20);
    createSkybox();
    createWeaponModel();

    // Events
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('keyup', onKeyUp);
    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mousedown', onMouseDown);
    document.addEventListener('mouseup', onMouseUp);
    document.addEventListener('contextmenu', e => e.preventDefault());
    window.addEventListener('resize', onResize);

    animate();
}

// ==================== TERRAIN ====================
function createTerrain() {
    const terrainGeo = new THREE.PlaneGeometry(800, 800, 100, 100);
    const vertices = terrainGeo.attributes.position.array;
    for (let i = 0; i < vertices.length; i += 3) {
        const x = vertices[i], y = vertices[i + 1];
        vertices[i + 2] = Math.sin(x * 0.01) * Math.cos(y * 0.01) * 3 +
                          Math.sin(x * 0.03 + y * 0.02) * 1.5 +
                          Math.random() * 0.5;
    }
    terrainGeo.computeVertexNormals();

    const terrainMat = new THREE.MeshStandardMaterial({
        color: 0x4a7c3f, roughness: 0.9, metalness: 0.0
    });
    const terrain = new THREE.Mesh(terrainGeo, terrainMat);
    terrain.rotation.x = -Math.PI / 2;
    terrain.receiveShadow = true;
    scene.add(terrain);

    // Water
    const waterGeo = new THREE.PlaneGeometry(800, 800);
    const waterMat = new THREE.MeshStandardMaterial({
        color: 0x1a5276, transparent: true, opacity: 0.6, roughness: 0.1, metalness: 0.8
    });
    const water = new THREE.Mesh(waterGeo, waterMat);
    water.rotation.x = -Math.PI / 2;
    water.position.y = -2;
    scene.add(water);

    // Roads
    for (let i = -3; i <= 3; i++) {
        const roadGeo = new THREE.PlaneGeometry(800, 12);
        const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
        const road1 = new THREE.Mesh(roadGeo, roadMat);
        road1.rotation.x = -Math.PI / 2;
        road1.position.set(0, 0.05, i * 100);
        road1.receiveShadow = true;
        scene.add(road1);

        const road2 = new THREE.Mesh(roadGeo, roadMat);
        road2.rotation.x = -Math.PI / 2;
        road2.rotation.z = Math.PI / 2;
        road2.position.set(i * 100, 0.05, 0);
        road2.receiveShadow = true;
        scene.add(road2);
    }
}

// ==================== BUILDINGS ====================
function createBuildings() {
    const buildingColors = [0x8B7355, 0xA0522D, 0x696969, 0x808080, 0xCD853F, 0x556B2F];

    for (let i = 0; i < 40; i++) {
        const w = 8 + Math.random() * 20;
        const h = 6 + Math.random() * 25;
        const d = 8 + Math.random() * 20;
        const geo = new THREE.BoxGeometry(w, h, d);
        const color = buildingColors[Math.floor(Math.random() * buildingColors.length)];
        const mat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.7, metalness: 0.1 });
        const building = new THREE.Mesh(geo, mat);

        let bx, bz;
        do {
            bx = (Math.random() - 0.5) * 600;
            bz = (Math.random() - 0.5) * 600;
        } while (Math.abs(bx) < 30 && Math.abs(bz) < 30);

        building.position.set(bx, h / 2, bz);
        building.castShadow = true;
        building.receiveShadow = true;
        scene.add(building);
        buildings.push({ mesh: building, x: bx, z: bz, w: w / 2, d: d / 2, h: h });

        // Windows
        const windowMat = new THREE.MeshStandardMaterial({ color: 0x87CEEB, roughness: 0.1, metalness: 0.5 });
        for (let wy = 3; wy < h - 2; wy += 4) {
            for (let wx = -w / 2 + 2; wx < w / 2 - 1; wx += 3) {
                const winGeo = new THREE.PlaneGeometry(1.5, 2);
                const win = new THREE.Mesh(winGeo, windowMat);
                win.position.set(bx + wx, wy, bz + d / 2 + 0.1);
                scene.add(win);
                const win2 = win.clone();
                win2.position.z = bz - d / 2 - 0.1;
                win2.rotation.y = Math.PI;
                scene.add(win2);
            }
        }

        // Roof
        const roofGeo = new THREE.BoxGeometry(w + 1, 0.5, d + 1);
        const roofMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.8 });
        const roof = new THREE.Mesh(roofGeo, roofMat);
        roof.position.set(bx, h + 0.25, bz);
        roof.castShadow = true;
        scene.add(roof);
    }

    // Crates
    for (let i = 0; i < 30; i++) {
        const crateGeo = new THREE.BoxGeometry(2, 2, 2);
        const crateMat = new THREE.MeshStandardMaterial({ color: 0x8B6914, roughness: 0.8 });
        const crate = new THREE.Mesh(crateGeo, crateMat);
        crate.position.set((Math.random() - 0.5) * 500, 1, (Math.random() - 0.5) * 500);
        crate.rotation.y = Math.random() * Math.PI;
        crate.castShadow = true;
        scene.add(crate);
    }
}

// ==================== TREES ====================
function createTrees() {
    for (let i = 0; i < 150; i++) {
        const treeGroup = new THREE.Group();

        const trunkGeo = new THREE.CylinderGeometry(0.3, 0.5, 4, 8);
        const trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3728, roughness: 0.9 });
        const trunk = new THREE.Mesh(trunkGeo, trunkMat);
        trunk.position.y = 2;
        trunk.castShadow = true;
        treeGroup.add(trunk);

        const leavesGeo = new THREE.SphereGeometry(3, 8, 8);
        const leavesMat = new THREE.MeshStandardMaterial({ color: 0x228B22 + Math.random() * 0x002200, roughness: 0.8 });
        const leaves = new THREE.Mesh(leavesGeo, leavesMat);
        leaves.position.y = 5.5;
        leaves.castShadow = true;
        treeGroup.add(leaves);

        const tx = (Math.random() - 0.5) * 700;
        const tz = (Math.random() - 0.5) * 700;
        treeGroup.position.set(tx, 0, tz);
        scene.add(treeGroup);
    }
}

// ==================== SKYBOX ====================
function createSkybox() {
    // Sun
    const sunGeo = new THREE.SphereGeometry(15, 32, 32);
    const sunMat = new THREE.MeshBasicMaterial({ color: 0xffffcc });
    const sun = new THREE.Mesh(sunGeo, sunMat);
    sun.position.set(200, 300, 100);
    scene.add(sun);

    // Clouds
    for (let i = 0; i < 30; i++) {
        const cloudGroup = new THREE.Group();
        for (let j = 0; j < 5; j++) {
            const cloudGeo = new THREE.SphereGeometry(8 + Math.random() * 12, 8, 8);
            const cloudMat = new THREE.MeshStandardMaterial({ color: 0xffffff, transparent: true, opacity: 0.8 });
            const cloud = new THREE.Mesh(cloudGeo, cloudMat);
            cloud.position.set(j * 10 - 20, Math.random() * 3, Math.random() * 5);
            cloud.scale.y = 0.4;
            cloudGroup.add(cloud);
        }
        cloudGroup.position.set((Math.random() - 0.5) * 800, 80 + Math.random() * 40, (Math.random() - 0.5) * 800);
        scene.add(cloudGroup);
    }
}

