// ==================== ENEMIES ====================
function createEnemies(count) {
    for (let i = 0; i < count; i++) {
        const enemy = createEnemyMesh();
        let ex, ez;
        do {
            ex = (Math.random() - 0.5) * 500;
            ez = (Math.random() - 0.5) * 500;
        } while (Math.abs(ex) < 40 && Math.abs(ez) < 40);

        enemy.position.set(ex, 0, ez);
        enemy.userData = {
            health: 100,
            speed: 2 + Math.random() * 3,
            targetX: ex + (Math.random() - 0.5) * 100,
            targetZ: ez + (Math.random() - 0.5) * 100,
            state: 'patrol', // patrol, chase, attack
            shootTimer: 0,
            lastShot: 0,
            alive: true,
            name: 'Bot_' + (i + 1)
        };
        scene.add(enemy);
        enemies.push(enemy);
    }
}

function createEnemyMesh() {
    const group = new THREE.Group();

    // Body
    const bodyGeo = new THREE.BoxGeometry(0.8, 1.2, 0.5);
    const bodyColors = [0x2d5a27, 0x8B0000, 0x1a1a5e, 0x4a4a4a, 0x654321];
    const bodyMat = new THREE.MeshStandardMaterial({ color: bodyColors[Math.floor(Math.random() * bodyColors.length)], roughness: 0.7 });
    const body = new THREE.Mesh(bodyGeo, bodyMat);
    body.position.y = 1.6;
    body.castShadow = true;
    group.add(body);

    // Head
    const headGeo = new THREE.SphereGeometry(0.25, 8, 8);
    const headMat = new THREE.MeshStandardMaterial({ color: 0xd4a574, roughness: 0.6 });
    const head = new THREE.Mesh(headGeo, headMat);
    head.position.y = 2.45;
    head.castShadow = true;
    group.add(head);

    // Helmet
    const helmetGeo = new THREE.SphereGeometry(0.28, 8, 6, 0, Math.PI * 2, 0, Math.PI / 2);
    const helmetMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.4, metalness: 0.6 });
    const helmet = new THREE.Mesh(helmetGeo, helmetMat);
    helmet.position.y = 2.5;
    group.add(helmet);

    // Legs
    const legGeo = new THREE.BoxGeometry(0.25, 0.9, 0.3);
    const legMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
    const leftLeg = new THREE.Mesh(legGeo, legMat);
    leftLeg.position.set(-0.2, 0.45, 0);
    leftLeg.castShadow = true;
    group.add(leftLeg);

    const rightLeg = new THREE.Mesh(legGeo, legMat);
    rightLeg.position.set(0.2, 0.45, 0);
    rightLeg.castShadow = true;
    group.add(rightLeg);

    // Arms
    const armGeo = new THREE.BoxGeometry(0.2, 0.8, 0.2);
    const leftArm = new THREE.Mesh(armGeo, bodyMat);
    leftArm.position.set(-0.55, 1.6, 0);
    leftArm.castShadow = true;
    group.add(leftArm);

    const rightArm = new THREE.Mesh(armGeo, bodyMat);
    rightArm.position.set(0.55, 1.6, 0);
    rightArm.castShadow = true;
    group.add(rightArm);

    // Gun
    const gunGeo = new THREE.BoxGeometry(0.08, 0.08, 0.5);
    const gunMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.3, metalness: 0.8 });
    const gun = new THREE.Mesh(gunGeo, gunMat);
    gun.position.set(0.55, 1.5, -0.3);
    group.add(gun);

    return group;
}

// ==================== INPUT ====================
function onKeyDown(e) {
    if (!gameStarted) return;
    switch (e.code) {
        case 'KeyW': moveForward = true; break;
        case 'KeyS': moveBackward = true; break;
        case 'KeyA': moveLeft = true; break;
        case 'KeyD': moveRight = true; break;
        case 'ShiftLeft': isSprinting = true; break;
        case 'ControlLeft':
            if (!isScoped) {
                isScoped = true;
                camera.fov = 20;
                camera.updateProjectionMatrix();
                document.getElementById('scope-overlay').style.display = 'block';
                document.getElementById('crosshair').style.display = 'none';
            }
            break;
        case 'KeyR': reload(); break;
        case 'Space':
            if (playerVelocity.y === 0) playerVelocity.y = 8;
            break;
        case 'Digit1': switchWeapon(0); break;
        case 'Digit2': switchWeapon(1); break;
        case 'Digit3': switchWeapon(2); break;
        case 'Digit4': switchWeapon(3); break;
        case 'Digit5': switchWeapon(4); break;
        case 'Digit6': switchWeapon(5); break;
    }
}

function onKeyUp(e) {
    switch (e.code) {
        case 'KeyW': moveForward = false; break;
        case 'KeyS': moveBackward = false; break;
        case 'KeyA': moveLeft = false; break;
        case 'KeyD': moveRight = false; break;
        case 'ShiftLeft': isSprinting = false; break;
        case 'ControlLeft':
            if (isScoped) {
                isScoped = false;
                camera.fov = 75;
                camera.updateProjectionMatrix();
                document.getElementById('scope-overlay').style.display = 'none';
                document.getElementById('crosshair').style.display = 'block';
            }
            break;
    }
}

function onMouseMove(e) {
    if (!gameStarted) return;
    yaw -= e.movementX * 0.002;
    pitch -= e.movementY * 0.002;
    pitch = Math.max(-Math.PI / 2.1, Math.min(Math.PI / 2.1, pitch));
}

function onMouseDown(e) {
    if (!gameStarted) return;
    if (e.button === 0) isShooting = true;
}

function onMouseUp(e) {
    if (e.button === 0) isShooting = false;
}

function onResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// ==================== WEAPON SWITCHING ====================
function switchWeapon(index) {
    if (index === currentWeapon || isReloading) return;
    currentWeapon = index;
    buildWeaponModel(index);
    updateHUD();
}

function reload() {
    if (isReloading) return;
    const w = WEAPONS[currentWeapon];
    if (w.ammo === w.maxAmmo || w.reserve <= 0) return;

    isReloading = true;
    playSound('reload');

    const reloadBar = document.getElementById('reload-bar');
    const reloadFill = document.getElementById('reload-fill');
    reloadBar.style.display = 'block';
    reloadFill.style.width = '0%';

    let progress = 0;
    const reloadInterval = setInterval(() => {
        progress += 50 / w.reloadTime * 100;
        reloadFill.style.width = progress + '%';
        if (progress >= 100) {
            clearInterval(reloadInterval);
            const needed = w.maxAmmo - w.ammo;
            const available = Math.min(needed, w.reserve);
            w.ammo += available;
            w.reserve -= available;
            isReloading = false;
            reloadBar.style.display = 'none';
            updateHUD();
        }
    }, 50);
}

// ==================== SHOOTING ====================
function shoot() {
    const w = WEAPONS[currentWeapon];
    const now = Date.now();
    if (now - lastShot < w.fireRate) return;
    if (w.ammo <= 0) { reload(); return; }
    if (isReloading) return;

    lastShot = now;
    w.ammo--;

    playSound(w.sound);

    // Muzzle flash
    muzzleLight.intensity = 3;
    setTimeout(() => muzzleLight.intensity = 0, 50);

    // Weapon recoil animation
    weaponGroup.position.z += 0.08;
    weaponGroup.rotation.x -= 0.03;
    setTimeout(() => {
        weaponGroup.position.z = -0.5;
        weaponGroup.rotation.x = 0;
    }, 80);

    // Camera recoil
    pitch += 0.01 + Math.random() * 0.01;
    yaw += (Math.random() - 0.5) * 0.005;

    // Create bullet
    const spread = w.spread;
    const direction = new THREE.Vector3(
        (Math.random() - 0.5) * spread,
        (Math.random() - 0.5) * spread,
        -1
    );
    direction.applyQuaternion(camera.quaternion);
    direction.normalize();

    const bulletCount = w.pellets || 1;
    for (let p = 0; p < bulletCount; p++) {
        const bDir = direction.clone();
        if (bulletCount > 1) {
            bDir.x += (Math.random() - 0.5) * 0.1;
            bDir.y += (Math.random() - 0.5) * 0.1;
            bDir.normalize();
        }

        const bulletGeo = new THREE.SphereGeometry(0.05, 4, 4);
        const bulletMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });
        const bullet = new THREE.Mesh(bulletGeo, bulletMat);
        bullet.position.copy(camera.position);
        bullet.position.add(direction.clone().multiplyScalar(1));
        scene.add(bullet);

        // Bullet trail
        const trailGeo = new THREE.CylinderGeometry(0.01, 0.01, 2, 4);
        const trailMat = new THREE.MeshBasicMaterial({ color: 0xffaa00, transparent: true, opacity: 0.5 });
        const trail = new THREE.Mesh(trailGeo, trailMat);
        trail.position.copy(bullet.position);
        trail.lookAt(bullet.position.clone().add(bDir));
        trail.rotateX(Math.PI / 2);
        scene.add(trail);

        bullets.push({
            mesh: bullet, trail: trail,
            direction: bDir,
            speed: 200,
            life: 2,
            damage: w.damage
        });
    }

    // Check enemy hits
    checkHits(bDir, w.damage);

    updateHUD();
}

function checkHits(direction, damage) {
    const raycaster = new THREE.Raycaster();
    raycaster.set(camera.position, direction);

    const enemyMeshes = [];
    enemies.forEach(e => {
        if (e.userData.alive) {
            e.traverse(child => {
                if (child.isMesh) enemyMeshes.push(child);
            });
        }
    });

    const intersects = raycaster.intersectObjects(enemyMeshes, false);
    if (intersects.length > 0) {
        const hit = intersects[0];
        const enemy = hit.object.parent;

        // Find the enemy group
        let enemyGroup = enemy;
        while (enemyGroup.parent && !enemyGroup.userData.alive) {
            enemyGroup = enemyGroup.parent;
        }

        if (enemyGroup.userData.alive) {
            enemyGroup.userData.health -= damage;

            // Hit marker
            const hm = document.getElementById('hit-marker');
            hm.style.display = 'block';
            setTimeout(() => hm.style.display = 'none', 150);
            playSound('hit');

            // Damage flash
            document.getElementById('damage-flash').style.background = 'rgba(255,0,0,0.3)';
            setTimeout(() => document.getElementById('damage-flash').style.background = 'rgba(255,0,0,0)', 100);

            if (enemyGroup.userData.health <= 0) {
                killEnemy(enemyGroup);
            }
        }
    }
}

function killEnemy(enemy) {
    enemy.userData.alive = false;
    kills++;
    alive--;
    playSound('kill');

    // Death animation - fall over
    const fallAnim = () => {
        enemy.rotation.x += 0.05;
        enemy.position.y -= 0.02;
        if (enemy.rotation.x < Math.PI / 2) {
            requestAnimationFrame(fallAnim);
        } else {
            setTimeout(() => {
                scene.remove(enemy);
            }, 3000);
        }
    };
    fallAnim();

    // Kill feed
    const feed = document.getElementById('kill-feed');
    const entry = document.createElement('div');
    entry.className = 'kill-entry';
    entry.innerHTML = `☠️ You killed ${enemy.userData.name}`;
    feed.appendChild(entry);
    setTimeout(() => entry.remove(), 4000);

    document.getElementById('kills').textContent = kills;
    document.getElementById('alive').textContent = alive;

    if (alive <= 1) {
        gameOver(true);
    }
}

// ==================== ENEMY AI ====================
function updateEnemies(delta) {
    const playerPos = camera.position;

    enemies.forEach(enemy => {
        if (!enemy.userData.alive) return;

        const dist = enemy.position.distanceTo(playerPos);
        const ud = enemy.userData;

        // State machine
        if (dist < 50) {
            ud.state = dist < 30 ? 'attack' : 'chase';
        } else {
            ud.state = 'patrol';
        }

        // Movement
        let moveX = 0, moveZ = 0;

        if (ud.state === 'patrol') {
            const dx = ud.targetX - enemy.position.x;
            const dz = ud.targetZ - enemy.position.z;
            const d = Math.sqrt(dx * dx + dz * dz);
            if (d < 2) {
                ud.targetX = enemy.position.x + (Math.random() - 0.5) * 100;
                ud.targetZ = enemy.position.z + (Math.random() - 0.5) * 100;
            } else {
                moveX = (dx / d) * ud.speed * delta;
                moveZ = (dz / d) * ud.speed * delta;
            }
        } else if (ud.state === 'chase') {
            const dx = playerPos.x - enemy.position.x;
            const dz = playerPos.z - enemy.position.z;
            moveX = (dx / dist) * ud.speed * delta * 1.5;
            moveZ = (dz / dist) * ud.speed * delta * 1.5;
        } else if (ud.state === 'attack') {
            // Strafe
            const strafe = Math.sin(Date.now() * 0.002) * ud.speed * delta;
            moveX += strafe;

            // Shoot at player
            if (Date.now() - ud.lastShot > 500 + Math.random() * 500) {
                ud.lastShot = Date.now();
                shootAtPlayer(enemy);
            }
        }

        // Apply movement
        const newX = enemy.position.x + moveX;
        const newZ = enemy.position.z + moveZ;

        // Building collision
        let blocked = false;
        buildings.forEach(b => {
            if (Math.abs(newX - b.x) < b.w + 0.5 && Math.abs(newZ - b.z) < b.d + 0.5) {
                blocked = true;
            }
        });

        if (!blocked) {
            enemy.position.x = newX;
            enemy.position.z = newZ;
        }

        // Face movement direction
        if (Math.abs(moveX) > 0.01 || Math.abs(moveZ) > 0.01) {
            enemy.rotation.y = Math.atan2(moveX, moveZ);
        }

        // Walking animation
        const walkCycle = Math.sin(Date.now() * 0.008) * 0.3;
        if (enemy.children[3]) enemy.children[3].rotation.x = walkCycle;
        if (enemy.children[4]) enemy.children[4].rotation.x = -walkCycle;
        if (enemy.children[5]) enemy.children[5].rotation.x = -walkCycle;
        if (enemy.children[6]) enemy.children[6].rotation.x = walkCycle;

        // Health bar above enemy
        if (!enemy.userData.healthBar) {
            const barGeo = new THREE.PlaneGeometry(1, 0.1);
            const barMat = new THREE.MeshBasicMaterial({ color: 0xff0000, side: THREE.DoubleSide });
            const bar = new THREE.Mesh(barGeo, barMat);
            bar.position.y = 3;
            enemy.add(bar);
            enemy.userData.healthBar = bar;
        }
        enemy.userData.healthBar.material.color.setHSL(ud.health / 100 * 0.33, 1, 0.5);
        enemy.userData.healthBar.lookAt(camera.position);
    });
}

function shootAtPlayer(enemy) {
    const direction = new THREE.Vector3();
    direction.subVectors(camera.position, enemy.position).normalize();

    // Add inaccuracy
    direction.x += (Math.random() - 0.5) * 0.15;
    direction.y += (Math.random() - 0.5) * 0.15;
    direction.z += (Math.random() - 0.5) * 0.15;
    direction.normalize();

    const raycaster = new THREE.Raycaster(enemy.position.clone().add(new THREE.Vector3(0, 2, 0)), direction);
    const intersects = raycaster.intersectObject(camera, false);

    if (Math.random() < 0.15) { // 15% hit chance
        const damage = 5 + Math.random() * 10;
        takeDamage(damage);
    }

    // Enemy bullet trail
    const trailGeo = new THREE.CylinderGeometry(0.005, 0.005, 3, 4);
    const trailMat = new THREE.MeshBasicMaterial({ color: 0xff4444, transparent: true, opacity: 0.4 });
    const trail = new THREE.Mesh(trailGeo, trailMat);
    trail.position.copy(enemy.position).add(new THREE.Vector3(0, 1.5, 0));
    trail.lookAt(trail.position.clone().add(direction));
    trail.rotateX(Math.PI / 2);
    scene.add(trail);
    setTimeout(() => scene.remove(trail), 100);
}

function takeDamage(amount) {
    if (armor > 0) {
        const armorAbsorb = Math.min(armor, amount * 0.6);
        armor -= armorAbsorb;
        amount -= armorAbsorb;
    }
    health -= amount;
    health = Math.max(0, health);

    document.getElementById('damage-flash').style.background = 'rgba(255,0,0,0.4)';
    setTimeout(() => document.getElementById('damage-flash').style.background = 'rgba(255,0,0,0)', 150);

    updateHUD();

    if (health <= 0) {
        gameOver(false);
    }
}

// ==================== BULLET UPDATE ====================
function updateBullets(delta) {
    for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.life -= delta;
        b.mesh.position.add(b.direction.clone().multiplyScalar(b.speed * delta));
        b.trail.position.copy(b.mesh.position);
        b.trail.lookAt(b.mesh.position.clone().add(b.direction));
        b.trail.rotateX(Math.PI / 2);

        if (b.life <= 0) {
            scene.remove(b.mesh);
            scene.remove(b.trail);
            bullets.splice(i, 1);
        }
    }
}

// ==================== PLAYER MOVEMENT ====================
function updatePlayer(delta) {
    const speed = isSprinting ? 15 : 8;

    const forward = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
    const right = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));

    const moveDir = new THREE.Vector3();
    if (moveForward) moveDir.add(forward);
    if (moveBackward) moveDir.sub(forward);
    if (moveRight) moveDir.add(right);
    if (moveLeft) moveDir.sub(right);

    if (moveDir.length() > 0) moveDir.normalize();

    playerVelocity.x = moveDir.x * speed;
    playerVelocity.z = moveDir.z * speed;

    // Gravity
    playerVelocity.y -= 20 * delta;

    const newX = camera.position.x + playerVelocity.x * delta;
    const newY = camera.position.y + playerVelocity.y * delta;
    const newZ = camera.position.z + playerVelocity.z * delta;

    // Building collision
    let canMoveX = true, canMoveZ = true;
    buildings.forEach(b => {
        if (Math.abs(newX - b.x) < b.w + 0.5 && Math.abs(camera.position.z - b.z) < b.d + 0.5) canMoveX = false;
        if (Math.abs(camera.position.x - b.x) < b.w + 0.5 && Math.abs(newZ - b.z) < b.d + 0.5) canMoveZ = false;
    });

    camera.position.x = canMoveX ? newX : camera.position.x;
    camera.position.z = canMoveZ ? newZ : camera.position.z;
    camera.position.y = Math.max(2, newY);

    // Rotation
    camera.rotation.order = 'YXZ';
    camera.rotation.y = yaw;
    camera.rotation.x = pitch;

    // Step sound
    if (moveDir.length() > 0) {
        stepTimer += delta * (isSprinting ? 12 : 8);
        if (stepTimer > 1) {
            stepTimer = 0;
            playSound('step');
        }
    }

    // Weapon bob
    if (moveDir.length() > 0) {
        const bobSpeed = isSprinting ? 10 : 6;
        const bobAmount = isSprinting ? 0.015 : 0.008;
        weaponGroup.position.y = -0.25 + Math.sin(Date.now() * 0.001 * bobSpeed) * bobAmount;
        weaponGroup.position.x = 0.3 + Math.cos(Date.now() * 0.001 * bobSpeed * 0.5) * bobAmount * 0.5;
    }
}

// ==================== HUD UPDATE ====================
function updateHUD() {
    const w = WEAPONS[currentWeapon];
    document.getElementById('weapon-name').textContent = w.name;
    document.getElementById('ammo-count').innerHTML = `<span class="current">${w.ammo}</span> / <span class="reserve">${w.reserve}</span>`;
    document.getElementById('health-fill').style.width = health + '%';
    document.getElementById('armor-fill').style.width = armor + '%';

    // Health color
    const hf = document.getElementById('health-fill');
    if (health > 60) hf.style.background = 'linear-gradient(90deg, #00cc00, #00ff00)';
    else if (health > 30) hf.style.background = 'linear-gradient(90deg, #ffaa00, #ffcc00)';
    else hf.style.background = 'linear-gradient(90deg, #ff0000, #ff4444)';

    // Weapon slots
    for (let i = 1; i <= 6; i++) {
        document.getElementById('slot' + i).className = 'weapon-slot' + (i - 1 === currentWeapon ? ' active' : '');
    }
}

// ==================== MINIMAP ====================
function updateMinimap() {
    const canvas = document.getElementById('minimap-canvas');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, 180, 180);

    // Background
    ctx.fillStyle = 'rgba(0,50,0,0.8)';
    ctx.fillRect(0, 0, 180, 180);

    const scale = 0.3;
    const cx = 90, cy = 90;

    // Buildings
    ctx.fillStyle = 'rgba(100,100,100,0.6)';
    buildings.forEach(b => {
        const bx = cx + (b.x - camera.position.x) * scale;
        const bz = cy + (b.z - camera.position.z) * scale;
        if (bx > -20 && bx < 200 && bz > -20 && bz < 200) {
            ctx.fillRect(bx - b.w * scale, bz - b.d * scale, b.w * 2 * scale, b.d * 2 * scale);
        }
    });

    // Enemies
    enemies.forEach(e => {
        if (!e.userData.alive) return;
        const ex = cx + (e.position.x - camera.position.x) * scale;
        const ez = cy + (e.position.z - camera.position.z) * scale;
        if (ex > 0 && ex < 180 && ez > 0 && ez < 180) {
            ctx.fillStyle = '#ff3333';
            ctx.beginPath();
            ctx.arc(ex, ez, 3, 0, Math.PI * 2);
            ctx.fill();
        }
    });

    // Player
    ctx.fillStyle = '#00ff00';
    ctx.beginPath();
    ctx.arc(cx, cy, 4, 0, Math.PI * 2);
    ctx.fill();

    // Player direction
    ctx.strokeStyle = '#00ff00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx - Math.sin(yaw) * 12, cy - Math.cos(yaw) * 12);
    ctx.stroke();

    // Border
    ctx.strokeStyle = '#ff6600';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(90, 90, 88, 0, Math.PI * 2);
    ctx.stroke();
}

// ==================== GAME OVER ====================
function gameOver(won) {
    gameStarted = false;
    document.exitPointerLock();
    const go = document.getElementById('game-over');
    go.style.display = 'flex';
    document.getElementById('go-title').textContent = won ? '🏆 BOOYAH!' : '💀 ELIMINATED';
    document.getElementById('go-kills').textContent = kills;
    document.getElementById('go-pos').textContent = '#' + alive;
}

// ==================== ANIMATION LOOP ====================
function animate() {
    requestAnimationFrame(animate);

    if (!gameStarted) {
        renderer.render(scene, camera);
        return;
    }

    const delta = Math.min(clock.getDelta(), 0.05);

    updatePlayer(delta);
    updateBullets(delta);
    updateEnemies(delta);

    // Auto fire
    if (isShooting && WEAPONS[currentWeapon].auto) {
        shoot();
    }

    // Auto reload
    if (WEAPONS[currentWeapon].ammo === 0 && !isReloading) {
        reload();
    }

    // Respawn enemies
    if (alive < 5 && Math.random() < 0.005) {
        const enemy = createEnemyMesh();
        enemy.position.set((Math.random() - 0.5) * 400, 0, (Math.random() - 0.5) * 400);
        enemy.userData = {
            health: 100, speed: 2 + Math.random() * 3,
            targetX: enemy.position.x, targetZ: enemy.position.z,
            state: 'patrol', shootTimer: 0, lastShot: 0,
            alive: true, name: 'Bot_' + (Math.floor(Math.random() * 999))
        };
        scene.add(enemy);
        enemies.push(enemy);
        alive++;
        document.getElementById('alive').textContent = alive;
    }

    updateMinimap();

    // FPS counter
    frameCount++;
    const now = performance.now();
    if (now - lastFpsTime > 1000) {
        document.getElementById('fps-counter').textContent = 'FPS: ' + frameCount;
        frameCount = 0;
        lastFpsTime = now;
    }

    renderer.render(scene, camera);
}

// ==================== START ====================
document.getElementById('startBtn').addEventListener('click', () => {
    initAudio();
    init();
    gameStarted = true;
    document.getElementById('blocker').style.display = 'none';
    renderer.domElement.requestPointerLock();
    updateHUD();
});

document.addEventListener('pointerlockchange', () => {
    if (document.pointerLockElement === renderer.domElement) {
        gameStarted = true;
        document.getElementById('blocker').style.display = 'none';
    } else if (gameStarted && health > 0) {
        document.getElementById('blocker').style.display = 'flex';
    }
});
</script>
</body>
</html>
