.level-btn:hover { background: rgba(139,94,60,0.35); transform: scale(1.05); }
.level-btn.completed { background: rgba(139,94,60,0.3); border-color: rgba(244,201,122,0.3); }
.level-btn.locked { opacity: 0.3; cursor: not-allowed; }

.hint-text {
  color: rgba(244,201,122,0.4);
