function rotateConnections(conns, times) {
  let c = [...conns];
  for (let i = 0; i < (times % 4); i++) {
    c = [c[3], c[0], c[1], c[2]];
  }
  return c;
}

function loadLevel(idx) {
  const lvl = LEVELS[idx];
  const rows = lvl.grid.length;
  const cols = lvl.grid[0].length;
  grid = [];

  for (let r = 0; r < rows; r++) {
    grid[r] = [];
    for (let c = 0; c < cols; c++) {
      if (lvl.grid[r][c] === 1) {
        const typeIdx = Math.floor(Math.random() * 4);
        const types = ['straight', 'corner', 'tJunction', 'cross'];
        const type = types[typeIdx];
        const baseConns = TILE_TYPES[type];
        const rot = lvl.rotations[r] ? lvl.rotations[r][c] : 0;
        const conns = rotateConnections(baseConns, rot);
        grid[r][c] = {
          type: type,
          connections: conns,
          rotation: rot,
          baseConns: baseConns,
          animRot: 0,
          targetRot: rot,
          isStart: (r === lvl.start.y && c === lvl.start.x),
          isEnd: (r === lvl.end.y && c === lvl.end.x),
          isPath: true,
          highlight: 0,
        };
      } else {
        grid[r][c] = {
          type: 'empty',
          connections: [0, 0, 0, 0],
          rotation: 0,
          baseConns: [0, 0, 0, 0],
          animRot: 0,
          targetRot: 0,
          isStart: false,
          isEnd: false,
          isPath: false,
          highlight: 0,
        };
      }
    }
  }

  destination = { ...lvl.end };
  ball = { 
    x: lvl.start.x, 
    y: lvl.start.y, 
    targetX: lvl.start.x, 
    targetY: lvl.start.y, 
    progress: 1, 
    rolling: false,
    path: [],
    pathIndex: 0,
  };
  moves = 0;
  particles = [];
  gameState = 'playing';

  document.getElementById('hudLevel').textContent = idx + 1;
  document.getElementById('hudMoves').textContent = '0';
  document.getElementById('hudPar').textContent = lvl.par;
  document.getElementById('hud').style.display = 'flex';
  document.getElementById('uiOverlay').classList.remove('active');
  document.getElementById('mainMenu').style.display = 'none';
  document.getElementById('levelSelectScreen').style.display = 'none';
  document.getElementById('levelComplete').style.display = 'none';
  document.getElementById('gameOver').style.display = 'none';

  resize();
}

function getTileAt(mx, my) {
  const rect = canvas.getBoundingClientRect();
  const x = mx - rect.left;
  const y = my - rect.top;

  const rows = grid.length;
  const cols = grid[0].length;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const tx = gridOffsetX + c * tileSize;
      const ty = gridOffsetY + r * tileSize;
      if (x >= tx && x <= tx + tileSize && y >= ty && y <= ty + tileSize) {
        return { r, c };
      }
    }
  }
  return null;
}

function canConnect(tileA, dirA, tileB, dirB) {
  if (!tileA || !tileB) return false;
  if (dirA < 0 || dirA > 3 || dirB < 0 || dirB > 3) return false;
  return tileA.connections[dirA] === 1 && tileB.connections[dirB] === 1;
}

function getOppositeDir(dir) {
  return (dir + 2) % 4;
}

function findPath() {
  const rows = grid.length;
  const cols = grid[0].length;

  // Find start tile
  let startTile = null;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c].isStart) {
        startTile = { r, c };
        break;
      }
    }
  }
  if (!startTile) return [];

  const visited = new Set();
  const queue = [{ r: startTile.r, c: startTile.c, path: [{ r: startTile.r, c: startTile.c }] }];
  visited.add(`${startTile.r},${startTile.c}`);

  const dirs = [[-1, 0, 0, 2], [0, 1, 1, 3], [1, 0, 2, 0], [0, -1, 3, 1]]; // dr, dc, outDir, inDir

  while (queue.length > 0) {
    const curr = queue.shift();
    const tile = grid[curr.r][curr.c];

    for (const [dr, dc, outDir, inDir] of dirs) {
      const nr = curr.r + dr;
      const nc = curr.c + dc;

      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
      if (visited.has(`${nr},${nc}`)) continue;

      const neighbor = grid[nr][nc];
      if (!neighbor.isPath) continue;

      if (canConnect(tile, outDir, neighbor, inDir)) {
        const newPath = [...curr.path, { r: nr, c: nc }];
        visited.add(`${nr},${nc}`);

        if (nr === destination.y && nc === destination.x) {
          return newPath;
        }

        queue.push({ r: nr, c: nc, path: newPath });
      }
    }
  }

  return [];
}

function startBallRoll() {
  const path = findPath();
  if (path.length < 2) return;

  ball.path = path;
  ball.pathIndex = 0;
  ball.x = path[0].r;
  ball.y = path[0].c;
  ball.targetX = path[1].r;
  ball.targetY = path[1].c;
  ball.progress = 0;
  ball.rolling = true;

  gameState = 'animating';
}

function updateBall() {
  if (!ball.rolling) return;

  ball.progress += 0.025;

  if (ball.progress >= 1) {
    ball.progress = 0;
    ball.x = ball.targetX;
    ball.y = ball.targetY;
    ball.pathIndex++;

    if (ball.pathIndex >= ball.path.length - 1) {
      ball.rolling = false;
      gameState = 'complete';

      const lvl = LEVELS[currentLevel];
      const stars = moves <= lvl.par ? 3 : moves <= lvl.par + 3 ? 2 : 1;

      completedLevels[currentLevel] = Math.max(completedLevels[currentLevel] || 0, stars);

      // Celebration particles
      for (let i = 0; i < 60; i++) {
        particles.push({
          x: W / 2,
          y: H / 2,
          vx: (Math.random() - 0.5) * 12,
          vy: (Math.random() - 0.5) * 12 - 3,
          life: 1,
          decay: 0.008 + Math.random() * 0.012,
          size: 3 + Math.random() * 5,
          color: ['#f4c97a', '#d4a056', '#8B5E3C', '#c9956b', '#e8c88a'][Math.floor(Math.random() * 5)],
          type: 'confetti',
        });
      }

      setTimeout(() => {
        if (currentLevel >= LEVELS.length - 1) {
          showGameOver();
        } else {
          showLevelComplete(stars);
        }
      }, 1500);

      return;
    }

    ball.targetX = ball.path[ball.pathIndex].r;
    ball.targetY = ball.path[ball.pathIndex].c;
  }
}

function rotateTile(r, c) {
  if (gameState !== 'playing') return;
  const tile = grid[r][c];
  if (!tile.isPath) return;

  tile.rotation = (tile.rotation + 1) % 4;
  tile.connections = rotateConnections(tile.baseConns, tile.rotation);
  tile.targetRot = tile.rotation;
  tile.highlight = 1;

  moves++;
  document.getElementById('hudMoves').textContent = moves;

  // Check if there's a valid path now
  const path = findPath();
  if (path.length >= 2) {
    startBallRoll();
  }
}

function showMainMenu() {
