}

// Drawing functions
function drawWoodTexture(x, y, w, h, baseColor, grainColor, highlight) {
  // Base wood color
  ctx.fillStyle = baseColor;
  ctx.fillRect(x, y, w, h);

  // Wood grain lines
  ctx.save();
  ctx.globalAlpha = 0.15;
  for (let i = 0; i < 8; i++) {
    const gy = y + (h / 8) * i + Math.sin(i * 2.5) * 3;
    ctx.strokeStyle = grainColor;
    ctx.lineWidth = 1 + Math.random();
    ctx.beginPath();
    ctx.moveTo(x, gy);
    for (let gx = x; gx <= x + w; gx += 5) {
      ctx.lineTo(gx, gy + Math.sin(gx * 0.05 + i) * 2);
    }
    ctx.stroke();
  }
  ctx.restore();

  // Highlight
  if (highlight > 0) {
    ctx.save();
    ctx.globalAlpha = highlight * 0.3;
    ctx.fillStyle = '#f4c97a';
    ctx.fillRect(x, y, w, h);
    ctx.restore();
  }
}

function drawTile(r, c, tile) {
  const x = gridOffsetX + c * tileSize;
  const y = gridOffsetY + r * tileSize;
  const s = tileSize;
  const pad = s * 0.08;
  const inner = s - pad * 2;

  // Shadow
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.4)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 3;

  // Tile background (wooden board)
  const grad = ctx.createLinearGradient(x, y, x + s, y + s);
  grad.addColorStop(0, '#6B4226');
  grad.addColorStop(0.5, '#7A4E30');
  grad.addColorStop(1, '#5C3A1E');
  ctx.fillStyle = grad;

  const radius = s * 0.06;
  ctx.beginPath();
  ctx.roundRect(x + pad * 0.5, y + pad * 0.5, inner + pad, inner + pad, radius);
  ctx.fill();
  ctx.restore();

  if (!tile.isPath) {
    // Draw subtle grid pattern for empty cells
    ctx.save();
    ctx.globalAlpha = 0.05;
    ctx.strokeStyle = '#f4c97a';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(x + pad * 0.5, y + pad * 0.5, inner + pad, inner + pad, radius);
    ctx.stroke();
    ctx.restore();
    return;
  }

  // Draw wooden path on tile
  const pathColor = tile.isStart ? '#8B6914' : tile.isEnd ? '#8B6914' : '#5C3A1E';
  const pathHighlight = '#A07830';

  ctx.save();
  ctx.beginPath();
  ctx.roundRect(x + pad * 0.5, y + pad * 0.5, inner + pad, inner + pad, radius);
  ctx.clip();

  // Draw the path connections
  const cx = x + s / 2;
  const cy = y + s / 2;
  const pathWidth = s * 0.22;

  const connections = tile.connections;

  // Draw each connection
  for (let dir = 0; dir < 4; dir++) {
    if (connections[dir] === 0) continue;

    ctx.fillStyle = pathColor;
    ctx.strokeStyle = '#4A2E15';
    ctx.lineWidth = 1.5;

    if (dir === 0) { // top
      ctx.fillRect(cx - pathWidth / 2, y + pad * 0.5, pathWidth, cy - y - pad * 0.5);
      ctx.strokeRect(cx - pathWidth / 2, y + pad * 0.5, pathWidth, cy - y - pad * 0.5);
    } else if (dir === 1) { // right
      ctx.fillRect(cx, cy - pathWidth / 2, x + s - pad * 0.5 - cx, pathWidth);
      ctx.strokeRect(cx, cy - pathWidth / 2, x + s - pad * 0.5 - cx, pathWidth);
    } else if (dir === 2) { // bottom
      ctx.fillRect(cx - pathWidth / 2, cy, pathWidth, y + s - pad * 0.5 - cy);
      ctx.strokeRect(cx - pathWidth / 2, cy, pathWidth, y + s - pad * 0.5 - cy);
    } else if (dir === 3) { // left
      ctx.fillRect(x + pad * 0.5, cy - pathWidth / 2, cx - x - pad * 0.5, pathWidth);
      ctx.strokeRect(x + pad * 0.5, cy - pathWidth / 2, cx - x - pad * 0.5, pathWidth);
    }
  }

  // Center circle
  ctx.beginPath();
  ctx.arc(cx, cy, pathWidth * 0.7, 0, Math.PI * 2);
  ctx.fillStyle = pathColor;
  ctx.fill();
  ctx.strokeStyle = '#4A2E15';
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // Wood grain on path
  ctx.globalAlpha = 0.1;
  for (let i = 0; i < 3; i++) {
    ctx.strokeStyle = pathHighlight;
    ctx.lineWidth = 0.5;
    const gy = cy - pathWidth + (pathWidth * 2 / 3) * i;
    ctx.beginPath();
    ctx.moveTo(x + pad, gy);
    ctx.lineTo(x + s - pad, gy + Math.sin(i) * 2);
    ctx.stroke();
  }

  ctx.restore();

  // Start marker
  if (tile.isStart) {
    ctx.save();
    const glow = 0.5 + Math.sin(animFrame * 0.05) * 0.3;
    ctx.globalAlpha = glow;
    ctx.fillStyle = '#f4c97a';
    ctx.beginPath();
    ctx.arc(cx, cy, s * 0.12, 0, Math.PI * 2);
    ctx.fill();

    ctx.globalAlpha = 1;
    ctx.fillStyle = '#5C3A1E';
    ctx.font = `bold ${s * 0.18}px Inter`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('S', cx, cy);
    ctx.restore();
  }

  // End marker
  if (tile.isEnd) {
    ctx.save();
    const glow = 0.5 + Math.sin(animFrame * 0.05) * 0.3;
    ctx.globalAlpha = glow;
    ctx.fillStyle = '#f4c97a';
    ctx.beginPath();
    ctx.arc(cx, cy, s * 0.12, 0, Math.PI * 2);
    ctx.fill();

    ctx.globalAlpha = 1;
    ctx.fillStyle = '#5C3A1E';
    ctx.font = `bold ${s * 0.18}px Inter`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('E', cx, cy);
    ctx.restore();
  }

  // Highlight effect
  if (tile.highlight > 0) {
    ctx.save();
    ctx.globalAlpha = tile.highlight * 0.4;
    ctx.strokeStyle = '#f4c97a';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.roundRect(x + pad * 0.5, y + pad * 0.5, inner + pad, inner + pad, radius);
    ctx.stroke();
    ctx.restore();
    tile.highlight *= 0.92;
    if (tile.highlight < 0.01) tile.highlight = 0;
  }
}

function drawBall() {
  if (gameState === 'menu') return;

  const rows = grid.length;
  const cols = grid[0].length;

  let bx, by;

  if (ball.rolling && ball.pathIndex < ball.path.length) {
    const fromR = ball.path[ball.pathIndex - 1] ? ball.path[ball.pathIndex - 1].r : ball.x;
    const fromC = ball.path[ball.pathIndex - 1] ? ball.path[ball.pathIndex - 1].c : ball.y;

    bx = gridOffsetX + fromC * tileSize + tileSize / 2 + (ball.targetX - fromR) * tileSize * ball.progress;
    by = gridOffsetY + fromC * tileSize + tileSize / 2 + (ball.targetY - fromC) * tileSize * ball.progress;

    // Wait, this is wrong. Let me fix the ball position calculation.
    const from = ball.path[ball.pathIndex - 1] || { r: ball.x, c: ball.y };
    const to = ball.path[ball.pathIndex];

    bx = gridOffsetX + from.c * tileSize + tileSize / 2 + (to.c - from.c) * tileSize * ball.progress;
    by = gridOffsetY + from.r * tileSize + tileSize / 2 + (to.r - from.r) * tileSize * ball.progress;
  } else {
    bx = gridOffsetX + ball.y * tileSize + tileSize / 2;
    by = gridOffsetY + ball.x * tileSize + tileSize / 2;
  }

  const ballRadius = tileSize * 0.15;

  // Ball shadow
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.5)';
  ctx.shadowBlur = 10;
  ctx.shadowOffsetY = 4;

  // Ball gradient
  const ballGrad = ctx.createRadialGradient(bx - ballRadius * 0.3, by - ballRadius * 0.3, 0, bx, by, ballRadius);
  ballGrad.addColorStop(0, '#d4a056');
  ballGrad.addColorStop(0.5, '#8B5E3C');
  ballGrad.addColorStop(1, '#5C3A1E');

  ctx.fillStyle = ballGrad;
  ctx.beginPath();
  ctx.arc(bx, by, ballRadius, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Ball highlight
  ctx.save();
  ctx.globalAlpha = 0.4;
  ctx.fillStyle = '#f4c97a';
  ctx.beginPath();
  ctx.arc(bx - ballRadius * 0.25, by - ballRadius * 0.25, ballRadius * 0.35, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Wood grain on ball
  ctx.save();
  ctx.globalAlpha = 0.15;
  ctx.strokeStyle = '#4A2E15';
  ctx.lineWidth = 1;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.arc(bx, by, ballRadius * (0.3 + Math.abs(i) * 0.2), -0.5, 0.5);
    ctx.stroke();
  }
  ctx.restore();
}

function drawParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.15;
    p.life -= p.decay;

    if (p.life <= 0) {
      particles.splice(i, 1);
      continue;
    }

    ctx.save();
    ctx.globalAlpha = p.life;

    if (p.type === 'confetti') {
      ctx.fillStyle = p.color;
      ctx.translate(p.x, p.y);
      ctx.rotate(p.life * 5);
      ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.6);
    } else {
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }
}

function drawBackground() {
  // Dark wood background
  const bgGrad = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, W * 0.7);
  bgGrad.addColorStop(0, '#2a1a0a');
  bgGrad.addColorStop(1, '#1a0e05');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, W, H);

  // Subtle wood grain on background
  ctx.save();
  ctx.globalAlpha = 0.03;
  for (let i = 0; i < 20; i++) {
    const gy = (H / 20) * i;
    ctx.strokeStyle = '#f4c97a';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, gy);
    for (let x = 0; x <= W; x += 10) {
      ctx.lineTo(x, gy + Math.sin(x * 0.01 + i * 0.5) * 3);
    }
    ctx.stroke();
  }
  ctx.restore();
}

function drawGrid() {
  const rows = grid.length;
  const cols = grid[0].length;

  // Draw subtle grid lines
  ctx.save();
  ctx.globalAlpha = 0.05;
  ctx.strokeStyle = '#f4c97a';
  ctx.lineWidth = 1;

  for (let r = 0; r <= rows; r++) {
    const y = gridOffsetY + r * tileSize;
    ctx.beginPath();
    ctx.moveTo(gridOffsetX, y);
    ctx.lineTo(gridOffsetX + cols * tileSize, y);
    ctx.stroke();
  }
  for (let c = 0; c <= cols; c++) {
    const x = gridOffsetX + c * tileSize;
    ctx.beginPath();
    ctx.moveTo(x, gridOffsetY);
    ctx.lineTo(x, gridOffsetY + rows * tileSize);
    ctx.stroke();
  }
  ctx.restore();

  // Draw tiles
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      drawTile(r, c, grid[r][c]);
    }
  }
}

function drawHoverEffect(mx, my) {
  if (gameState !== 'playing') return;

  const tile = getTileAt(mx, my);
  if (tile && grid[tile.r][tile.c].isPath) {
    const x = gridOffsetX + tile.c * tileSize;
    const y = gridOffsetY + tile.r * tileSize;
    const s = tileSize;
    const pad = s * 0.08;
    const inner = s - pad * 2;

    ctx.save();
    ctx.globalAlpha = 0.15 + Math.sin(animFrame * 0.08) * 0.05;
    ctx.strokeStyle = '#f4c97a';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.roundRect(x + pad * 0.5, y + pad * 0.5, inner + pad, inner + pad, s * 0.06);
    ctx.stroke();
    ctx.restore();
  }
}

// Main game loop
let mouseX = 0, mouseY = 0;

canvas.addEventListener('mousemove', (e) => {
  mouseX = e.clientX;
  mouseY = e.clientY;
});

canvas.addEventListener('click', (e) => {
  const tile = getTileAt(e.clientX, e.clientY);
  if (tile) {
    rotateTile(tile.r, tile.c);
  }
});

canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  const touch = e.touches[0];
  const tile = getTileAt(touch.clientX, touch.clientY);
  if (tile) {
    rotateTile(tile.r, tile.c);
  }
}, { passive: false });

function gameLoop() {
  animFrame++;

  resize();
  drawBackground();
  drawGrid();
  updateBall();
  drawBall();
  drawParticles();
  drawHoverEffect(mouseX, mouseY);

  requestAnimationFrame(gameLoop);
}

// Initialize
showMainMenu();
gameLoop();
</script>
