<script>
  // Audio context for sound effects
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  let audioCtx = null;

  function initAudio() {
    if (!audioCtx) {
      audioCtx = new AudioCtx();
    }
  }

  function playSound(type) {
    if (!audioCtx) return;
    try {
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.connect(gain);
      gain.connect(audioCtx.destination);

      const now = audioCtx.currentTime;

      if (type === 'place') {
        osc.type = 'square';
        osc.frequency.setValueAtTime(600, now);
        osc.frequency.exponentialRampToValueAtTime(900, now + 0.08);
        gain.gain.setValueAtTime(0.12, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
        osc.start(now);
        osc.stop(now + 0.15);
      } else if (type === 'win') {
        osc.type = 'square';
        const notes = [523, 659, 784, 1047];
        notes.forEach((freq, i) => {
          osc.frequency.setValueAtTime(freq, now + i * 0.12);
        });
        gain.gain.setValueAtTime(0.15, now);
        gain.gain.setValueAtTime(0.15, now + 0.4);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
        osc.start(now);
        osc.stop(now + 0.6);
      } else if (type === 'draw') {
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(300, now);
        osc.frequency.linearRampToValueAtTime(200, now + 0.3);
        gain.gain.setValueAtTime(0.12, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
        osc.start(now);
        osc.stop(now + 0.4);
      } else if (type === 'click') {
        osc.type = 'square';
        osc.frequency.setValueAtTime(800, now);
        gain.gain.setValueAtTime(0.08, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
        osc.start(now);
        osc.stop(now + 0.05);
      }
    } catch(e) {}
  }

  // Game state
  let board = Array(9).fill(null);
  let currentPlayer = 'X';
  let gameActive = true;
  let scores = { X: 0, O: 0, draw: 0 };
  let vsCPU = true;
  let cpuDifficulty = 'medium'; // easy, medium, hard
  let cpuThinking = false;

  const winPatterns = [
    [0,1,2],[3,4,5],[6,7,8],
    [0,3,6],[1,4,7],[2,5,8],
    [0,4,8],[2,4,6]
  ];

  // Build stars
  function createStars() {
    const container = document.getElementById('stars');
    for (let i = 0; i < 80; i++) {
      const star = document.createElement('div');
      star.className = 'star';
      star.style.left = Math.random() * 100 + '%';
      star.style.top = Math.random() * 100 + '%';
      star.style.setProperty('--duration', (1 + Math.random() * 3) + 's');
      star.style.setProperty('--max-opacity', (0.3 + Math.random() * 0.7));
      star.style.animationDelay = Math.random() * 3 + 's';
      star.style.width = (1 + Math.random() * 2) + 'px';
      star.style.height = star.style.width;
      container.appendChild(star);
    }
  }
  createStars();

  // Build board
  function buildBoard() {
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';
    for (let i = 0; i < 9; i++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.index = i;
      cell.addEventListener('click', () => handleCellClick(i));
      boardEl.appendChild(cell);
    }
  }
  buildBoard();

  function handleCellClick(index) {
    initAudio();
    if (!gameActive || board[index] || cpuThinking) return;

    makeMove(index, currentPlayer);

    if (gameActive && vsCPU && currentPlayer === 'O') {
      cpuThinking = true;
      updateTurnIndicator();
      setTimeout(() => {
        cpuMove();
        cpuThinking = false;
      }, 300 + Math.random() * 400);
    }
  }

  function makeMove(index, player) {
    board[index] = player;
    const cells = document.querySelectorAll('.cell');
    const cell = cells[index];
    cell.classList.add('taken');

    const mark = document.createElement('span');
    mark.className = 'mark ' + (player === 'X' ? 'x-mark' : 'o-mark');
    mark.textContent = player;
    cell.appendChild(mark);

    playSound('place');
    spawnParticles(cell, player);

    const winResult = checkWin(board, player);
    if (winResult) {
      gameActive = false;
      highlightWin(winResult);
      scores[player]++;
      updateScores();
      showMessage(`${player} WINS!`, 'win');
      playSound('win');
      return;
    }

    if (board.every(c => c !== null)) {
      gameActive = false;
      scores.draw++;
      updateScores();
      showMessage("IT'S A DRAW!", 'draw');
      playSound('draw');
      return;
    }

    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
    updateTurnIndicator();
  }

  function checkWin(b, player) {
    for (const pattern of winPatterns) {
      if (pattern.every(i => b[i] === player)) {
        return pattern;
      }
    }
    return null;
  }

  function highlightWin(pattern) {
    const cells = document.querySelectorAll('.cell');
    pattern.forEach(i => {
      cells[i].classList.add('winning-cell');
    });

    // Draw win line
    drawWinLine(pattern);
  }

  function drawWinLine(pattern) {
    const wrapper = document.getElementById('boardWrapper');
    const cells = document.querySelectorAll('.cell');
    const wrapperRect = wrapper.getBoundingClientRect();

    const getCenter = (idx) => {
      const rect = cells[idx].getBoundingClientRect();
      return {
        x: rect.left + rect.width / 2 - wrapperRect.left,
        y: rect.top + rect.height / 2 - wrapperRect.top
      };
    };

    const start = getCenter(pattern[0]);
    const end = getCenter(pattern[2]);

    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const length = Math.sqrt(dx * dx + dy * dy);
    const angle = Math.atan2(dy, dx) * 180 / Math.PI;

    const line = document.createElement('div');
    line.className = 'win-line';
    line.style.width = (length + 20) + 'px';
    line.style.height = '4px';
    line.style.left = (start.x - 10) + 'px';
    line.style.top = (start.y - 2) + 'px';
    line.style.transformOrigin = '0 50%';
    line.style.transform = `rotate(${angle}deg)`;

    wrapper.appendChild(line);
  }

  function updateTurnIndicator() {
    const el = document.getElementById('turnIndicator');
    if (!gameActive) return;
    el.className = 'turn-indicator turn-' + currentPlayer.toLowerCase();
    const label = vsCPU && currentPlayer === 'O' ? "CPU THINKING..." : `▶ PLAYER ${currentPlayer}'S TURN ◀`;
    el.textContent = label;
  }

  function showMessage(text, type) {
    const el = document.getElementById('message');
    el.textContent = text;
    el.className = 'message ' + (type === 'win' ? 'win-msg' : 'draw-msg');
  }

  function updateScores() {
    document.getElementById('scoreX').textContent = scores.X;
    document.getElementById('scoreO').textContent = scores.O;
    document.getElementById('scoreDraw').textContent = scores.draw;
  }

  function restartGame() {
    playSound('click');
    board = Array(9).fill(null);
    currentPlayer = 'X';
    gameActive = true;
    cpuThinking = false;

    const cells = document.querySelectorAll('.cell');
    cells.forEach(c => {
      c.classList.remove('taken', 'winning-cell');
      c.innerHTML = '';
    });

    // Remove win lines
    const lines = document.querySelectorAll('.win-line');
    lines.forEach(l => l.remove());

    document.getElementById('message').textContent = '';
    document.getElementById('message').className = 'message';
    updateTurnIndicator();
  }

  function resetScores() {
    playSound('click');
    scores = { X: 0, O: 0, draw: 0 };
    updateScores();
    restartGame();
  }

  function toggleMode() {
    playSound('click');
    vsCPU = !vsCPU;
    const btn = document.querySelector('.btn-mode');
    btn.textContent = vsCPU ? 'MODE: VS CPU' : 'MODE: VS PLAYER';
    document.getElementById('modeLabel').textContent = vsCPU ? 'CPU: MEDIUM' : '2 PLAYERS';
    resetScores();
  }

  // CPU AI
  function cpuMove() {
    if (!gameActive) return;

    let move;
    if (cpuDifficulty === 'easy') {
      move = cpuEasy();
    } else if (cpuDifficulty === 'medium') {
      move = cpuMedium();
    } else {
      move = cpuHard();
    }

    if (move !== null && move !== undefined) {
      makeMove(move, 'O');
    }
  }

  function cpuEasy() {
    // Random move
    const available = board.map((v, i) => v === null ? i : null).filter(v => v !== null);
    return available[Math.floor(Math.random() * available.length)];
  }

  function cpuMedium() {
    // 60% chance of optimal, 40% random
    if (Math.random() < 0.6) {
      return cpuHard();
    }
    return cpuEasy();
  }

  function cpuHard() {
    // Minimax
    let bestScore = -Infinity;
    let bestMove = null;

    for (let i = 0; i < 9; i++) {
      if (board[i] === null) {
        board[i] = 'O';
        let score = minimax(board, 0, false, -Infinity, Infinity);
        board[i] = null;
        if (score > bestScore) {
          bestScore = score;
          bestMove = i;
        }
      }
    }
    return bestMove;
  }

  function minimax(b, depth, isMaximizing, alpha, beta) {
    if (checkWin(b, 'O')) return 10 - depth;
    if (checkWin(b, 'X')) return depth - 10;
    if (b.every(c => c !== null)) return 0;

    if (isMaximizing) {
      let maxEval = -Infinity;
      for (let i = 0; i < 9; i++) {
        if (b[i] === null) {
          b[i] = 'O';
          let eval_ = minimax(b, depth + 1, false, alpha, beta);
          b[i] = null;
          maxEval = Math.max(maxEval, eval_);
          alpha = Math.max(alpha, eval_);
          if (beta <= alpha) break;
        }
      }
      return maxEval;
    } else {
      let minEval = Infinity;
      for (let i = 0; i < 9; i++) {
        if (b[i] === null) {
          b[i] = 'X';
          let eval_ = minimax(b, depth + 1, true, alpha, beta);
          b[i] = null;
          minEval = Math.min(minEval, eval_);
          beta = Math.min(beta, eval_);
          if (beta <= alpha) break;
        }
      }
      return minEval;
    }
  }

  // Particle effects
  function spawnParticles(cell, player) {
    const rect = cell.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const color = player === 'X' ? '#ff00ff' : '#ffff00';

    for (let i = 0; i < 8; i++) {
      const particle = document.createElement('div');
      particle.className = 'particle';
      particle.style.left = cx + 'px';
      particle.style.top = cy + 'px';
      particle.style.background = color;
      particle.style.boxShadow = `0 0 6px ${color}`;
      const angle = (Math.PI * 2 / 8) * i;
      const dist = 30 + Math.random() * 40;
      particle.style.setProperty('--tx', Math.cos(angle) * dist + 'px');
      particle.style.setProperty('--ty', Math.sin(angle) * dist + 'px');
      document.body.appendChild(particle);
      setTimeout(() => particle.remove(), 1000);
    }
  }

  // Cycle CPU difficulty on mode toggle for variety
  const difficulties = ['EASY', 'MEDIUM', 'HARD'];
  let diffIndex = 1;
  const origToggle = toggleMode;

  // Override to cycle difficulty
  function toggleMode() {
    playSound('click');
    vsCPU = !vsCPU;
    const btn = document.querySelector('.btn-mode');
    btn.textContent = vsCPU ? 'MODE: VS CPU' : 'MODE: VS PLAYER';
    document.getElementById('modeLabel').textContent = vsCPU ? `CPU: ${difficulties[diffIndex]}` : '2 PLAYERS';
    resetScores();

    if (vsCPU) {
      diffIndex = (diffIndex + 1) % difficulties.length;
      cpuDifficulty = difficulties[diffIndex].toLowerCase();
    }
  }

  // Keyboard support
  document.addEventListener('keydown', (e) => {
    const keyMap = {
      '1': 0, '2': 1, '3': 2,
      '4': 3, '5': 4, '6': 5,
      '7': 6, '8': 7, '9': 8,
      'a': 0, 's': 1, 'd': 2,
      'f': 3, 'g': 4, 'h': 5,
      'j': 6, 'k': 7, 'l': 8,
      'r': null // restart
    };

    if (e.key.toLowerCase() === 'r') {
      restartGame();
      return;
    }

    const idx = keyMap[e.key.toLowerCase()];
    if (idx !== undefined && idx !== null) {
      handleCellClick(idx);
    }
  });
</script>

