            // Default: dig right if no direction
            dx = 1;
        }
        digBlock(player.x + dx, player.y + dy);
    }

    updateEnemies(dt);
    updateParticles();
    updateCamera();

    // Screen shake
    if (shakeTimer > 0) shakeTimer--;
}

function render() {
    ctx.save();

    // Screen shake
    if (shakeTimer > 0) {
        const sx = (Math.random() - 0.5) * shakeIntensity;
        const sy = (Math.random() - 0.5) * shakeIntensity;
        ctx.translate(sx, sy);
    }

    drawBackground();
    drawTorches();
    drawEnemies();
    drawPlayer();
    drawParticles();
    drawMinimap();

    // Depth indicator
    const depthMeters = (player.y - 2) * 2;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(10, canvas.height - 30, 150, 20);
    ctx.fillStyle = '#aaa';
    ctx.font = '12px Courier New';
    ctx.fillText(`⬇ ${depthMeters}m deep`, 16, canvas.height - 15);

    // HP and Energy display
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(10, canvas.height - 55, 150, 22);
    ctx.fillStyle = '#4c4';
    ctx.fillRect(14, canvas.height - 52, 142 * (player.hp / player.maxHp), 8);
    ctx.fillStyle = '#48f';
    ctx.fillRect(14, canvas.height - 42, 142 * (player.energy / player.maxEnergy), 8);
    ctx.fillStyle = '#fff';
    ctx.font = '9px Courier New';
    ctx.fillText(`HP ${player.hp}/${player.maxHp}`, 14, canvas.height - 45);
    ctx.fillText(`EN ${player.energy}/${player.maxEnergy}`, 14, canvas.height - 35);

    ctx.restore();
}

function gameLoop(timestamp) {
    const dt = Math.min((timestamp - lastTime) / 1000, 0.05);
    lastTime = timestamp;

    update(dt);
    render();

    requestAnimationFrame(gameLoop);
}

