  border: 2px solid rgba(100, 200, 255, 0.3);
}

.mode-dream::before {
  background: radial-gradient(ellipse at 30% 50%, rgba(100, 200, 255, 0.3), transparent 70%);
}

.mode-chaos {
  background: linear-gradient(145deg, rgba(255, 100, 100, 0.15), rgba(255, 165, 0, 0.1));
  border: 2px solid rgba(255, 100, 100, 0.3);
}

.mode-chaos::before {
  background: radial-gradient(ellipse at 70% 50%, rgba(255, 100, 100, 0.3), transparent 70%);
}

.mode-symphony {
  background: linear-gradient(145deg, rgba(255, 215, 0, 0.15), rgba(255, 107, 202, 0.1));
  border: 2px solid rgba(255, 215, 0, 0.3);
}

.mode-symphony::before {
  background: radial-gradient(ellipse at 50% 50%, rgba(255, 215, 0, 0.3), transparent 70%);
}

.mode-icon {
  font-size: 4rem;
  margin-bottom: 15px;
  display: block;
}

.mode-name {
  font-family: 'Cinzel Decorative', cursive;
  font-size: 1.3rem;
  margin-bottom: 10px;
  color: #fff;
}

.mode-desc {
  font-size: 0.9rem;
  color: #c0b0e0;
  line-height: 1.5;
}

.mode-tag {
  display: inline-block;
  margin-top: 15px;
  padding: 5px 15px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.mode-dream .mode-tag { background: rgba(100, 200, 255, 0.2); color: var(--glow-blue); border: 1px solid rgba(100, 200, 255, 0.3); }
.mode-chaos .mode-tag { background: rgba(255, 100, 100, 0.2); color: #ff6b6b; border: 1px solid rgba(255, 100, 100, 0.3); }
.mode-symphony .mode-tag { background: rgba(255, 215, 0, 0.2); color: var(--glow-gold); border: 1px solid rgba(255, 215, 0, 0.3); }

/* ===== PLAYABLE GAME ===== */
#playGame {
  background: radial-gradient(ellipse at 50% 50%, #1a1040 0%, #0a0a1a 70%);
  display: none;
}

.game-canvas-container {
  position: relative;
  width: 100%;
  max-width: 900px;
  border-radius: 20px;
  overflow: hidden;
  border: 2px solid rgba(180, 107, 252, 0.3);
  box-shadow: 0 0 40px rgba(180, 107, 252, 0.2);
}

#gameCanvas {
  display: block;
  width: 100%;
  height: 500px;
  background: #0a0a2a;
}

.game-hud {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  background: rgba(10, 10, 26, 0.9);
  border-bottom: 1px solid rgba(180, 107, 252, 0.2);
}

.hud-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  color: #c0b0e0;
}

.hud-item span { color: var(--glow-gold); font-weight: 700; }

.emotion-bar {
  display: flex;
  gap: 8px;
}

.emotion-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.2);
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  background: rgba(255, 255, 255, 0.05);
}

.emotion-btn:hover, .emotion-btn.active {
  transform: scale(1.2);
  box-shadow: 0 0 15px currentColor;
}

.emotion-btn.joy { color: #ffd700; border-color: rgba(255, 215, 0, 0.4); }
.emotion-btn.sadness { color: #6bc5ff; border-color: rgba(107, 197, 255, 0.4); }
.emotion-btn.anger { color: #ff6b6b; border-color: rgba(255, 107, 107, 0.4); }
.emotion-btn.curiosity { color: #b46bfc; border-color: rgba(180, 107, 252, 0.4); }

.game-controls-hint {
  text-align: center;
  margin-top: 15px;
  font-size: 0.85rem;
  color: #8070a0;
}

.game-controls-hint kbd {
  background: rgba(180, 107, 252, 0.2);
  border: 1px solid rgba(180, 107, 252, 0.3);
  border-radius: 5px;
  padding: 2px 8px;
  margin: 0 3px;
  font-family: 'Quicksand', sans-serif;
  color: #c0b0e0;
}

/* ===== SUPPORT / QR ===== */
#support {
  background: radial-gradient(ellipse at 50% 50%, #1a1040 0%, #0a0a1a 70%);
  display: none;
}

.support-container {
  text-align: center;
  max-width: 600px;
}

.thank-you-text {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-style: italic;
  color: #ffd700;
  margin-bottom: 10px;
  text-shadow: 0 0 20px rgba(255, 215, 0, 0.4);
}

.support-subtitle {
  color: #c0b0e0;
  margin-bottom: 30px;
  font-size: 1rem;
}

.qr-frame {
  position: relative;
  display: inline-block;
  padding: 20px;
  background: linear-gradient(135deg, rgba(255, 215, 0, 0.1), rgba(255, 165, 0, 0.05));
  border: 3px solid rgba(255, 215, 0, 0.4);
  border-radius: 20px;
  margin-bottom: 30px;
  box-shadow: 0 0 40px rgba(255, 215, 0, 0.15), inset 0 0 40px rgba(255, 215, 0, 0.05);
}

.qr-frame::before, .qr-frame::after {
  content: '✦';
  position: absolute;
  color: var(--glow-gold);
  font-size: 1.5rem;
  animation: sparkle 2s ease-in-out infinite;
}

.qr-frame::before { top: -12px; left: 50%; transform: translateX(-50%); }
.qr-frame::after { bottom: -12px; left: 50%; transform: translateX(-50%); }

.qr-code {
  width: 200px;
  height: 200px;
  background: #fff;
  border-radius: 10px;
  padding: 10px;
}

.qr-code canvas {
  width: 100%;
  height: 100%;
}

.support-message {
  color: #a080d0;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-top: 20px;
}

/* ===== SOCIAL LINKS ===== */
#social {
  background: radial-gradient(ellipse at 50% 50%, #1a1040 0%, #0a0a1a 70%);
  display: none;
}

.social-container {
  max-width: 800px;
  width: 100%;
  padding: 20px;
}

.social-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 15px;
  margin-top: 20px;
}

.social-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 20px;
  background: linear-gradient(145deg, rgba(30, 20, 60, 0.8), rgba(15, 10, 40, 0.8));
  border: 1px solid rgba(180, 107, 252, 0.2);
  border-radius: 15px;
  text-decoration: none;
  color: #c0b0e0;
  transition: all 0.3s ease;
  font-size: 0.85rem;
}

.social-link:hover {
  transform: translateY(-3px);
  border-color: var(--glow-purple);
  box-shadow: 0 5px 20px rgba(180, 107, 252, 0.2);
  color: #fff;
}

.social-icon {
  font-size: 1.5rem;
  flex-shrink: 0;
}

.social-platform {
  font-weight: 700;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--glow-purple);
}

/* ===== FOLLOW BANNER ===== */
.follow-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background: linear-gradient(135deg, rgba(255, 215, 0, 0.15), rgba(255, 107, 202, 0.15));
  border-top: 2px solid rgba(255, 215, 0, 0.3);
  padding: 12px 20px;
  text-align: center;
  z-index: 1000;
  backdrop-filter: blur(15px);
  animation: bannerPulse 3s ease-in-out infinite;
}

@keyframes bannerPulse {
  0%, 100% { box-shadow: 0 -5px 20px rgba(255, 215, 0, 0.1); }
  50% { box-shadow: 0 -5px 30px rgba(255, 215, 0, 0.25); }
}

.follow-banner-text {
  font-family: 'Quicksand', sans-serif;
  font-weight: 700;
  font-size: 0.95rem;
  background: linear-gradient(135deg, #ffd700, #ff6bca);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.follow-banner-text .emoji {
  -webkit-text-fill-color: initial;
}

/* ===== BACK BUTTON ===== */
.back-btn {
  position: absolute;
  top: 20px;
  left: 20px;
  padding: 10px 25px;
  background: rgba(30, 20, 60, 0.8);
  border: 1px solid rgba(180, 107, 252, 0.3);
  border-radius: 25px;
  color: #c0b0e0;
  font-family: 'Quicksand', sans-serif;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  z-index: 10;
  font-size: 0.9rem;
}

.back-btn:hover {
  background: rgba(180, 107, 252, 0.2);
  border-color: var(--glow-purple);
  color: #fff;
}

/* ===== NAV DOTS ===== */
.nav-dots {
  position: fixed;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 12px;
  z-index: 100;
}

.nav-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(180, 107, 252, 0.3);
  border: 1px solid rgba(180, 107, 252, 0.5);
  cursor: pointer;
  transition: all 0.3s ease;
}

.nav-dot:hover, .nav-dot.active {
  background: var(--glow-gold);
  border-color: var(--glow-gold);
  box-shadow: 0 0 10px rgba(255, 215, 0, 0.5);
  transform: scale(1.3);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .characters-grid { grid-template-columns: repeat(2, 1fr); gap: 15px; }
  .modes-container { grid-template-columns: 1fr; }
  .shop-grid { grid-template-columns: repeat(2, 1fr); }
  .game-canvas-container { width: 95%; }
  #gameCanvas { height: 350px; }
  .nav-dots { right: 8px; }
  .nav-dot { width: 8px; height: 8px; }
  .social-grid { grid-template-columns: 1fr; }
}

/* ===== ANIMATIONS ===== */
.fade-in {
  animation: fadeIn 0.6s ease forwards;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.slide-up {
  animation: slideUp 0.5s ease forwards;
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(40px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Floating hearts for support section */
.floating-heart {
  position: absolute;
  font-size: 1.5rem;
  animation: floatHeart 4s ease-in-out infinite;
  pointer-events: none;
  opacity: 0.6;
}

@keyframes floatHeart {
  0%, 100% { transform: translateY(0) rotate(0deg); opacity: 0.4; }
  50% { transform: translateY(-20px) rotate(15deg); opacity: 0.8; }
}

/* Notification toast */
.toast {
  position: fixed;
  top: 20px;
  right: 20px;
  padding: 15px 25px;
  background: linear-gradient(135deg, rgba(30, 20, 60, 0.95), rgba(15, 10, 40, 0.95));
  border: 1px solid rgba(255, 215, 0, 0.4);
  border-radius: 15px;
  color: var(--glow-gold);
  font-weight: 600;
  z-index: 2000;
  animation: toastIn 0.4s ease, toastOut 0.4s ease 2.5s forwards;
  backdrop-filter: blur(10px);
  box-shadow: 0 5px 25px rgba(255, 215, 0, 0.2);
}

@keyframes toastIn {
  from { opacity: 0; transform: translateX(100px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes toastOut {
  from { opacity: 1; transform: translateX(0); }
  to { opacity: 0; transform: translateX(100px); }
}

/* Loading screen */
#loadingScreen {
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: var(--bg-deep);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  transition: opacity 0.8s ease;
}

#loadingScreen.hidden {
  opacity: 0;
  pointer-events: none;
}

.loading-spinner {
  width: 60px;
  height: 60px;
  border: 3px solid rgba(180, 107, 252, 0.2);
  border-top-color: var(--glow-gold);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 20px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.loading-text {
  font-family: 'Cinzel Decorative', cursive;
  color: #ffd700;
  font-size: 1.2rem;
  animation: loadPulse 1.5s ease-in-out infinite;
}

@keyframes loadPulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

/* Shopkeeper NPC */
.shopkeeper {
  text-align: center;
  margin-bottom: 25px;
}

.shopkeeper-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 215, 0, 0.3), rgba(255, 165, 0, 0.1));
  margin: 0 auto 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
  border: 2px solid rgba(255, 215, 0, 0.3);
  animation: characterIdle 3s ease-in-out infinite;
}

.shopkeeper-name {
  font-family: 'Cinzel Decorative', cursive;
  color: var(--glow-gold);
  font-size: 0.9rem;
}

.shopkeeper-speech {
  font-style: italic;
  color: #a080d0;
  font-size: 0.85rem;
  margin-top: 5px;
  padding: 8px 15px;
  background: rgba(180, 107, 252, 0.1);
  border-radius: 15px;
  display: inline-block;
  border: 1px solid rgba(180, 107, 252, 0.2);
}
</style>
</head>
