  justify-content: center;
  gap: 8px;
  padding: 0 16px 16px;
}

/* Game Screens */
.game-screen { display: none; }
.game-screen.active { display: block; }

/* Main Menu */
#menu-screen {
  width: 400px; height: 300px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}
.menu-content {
  padding: 20px;
  text-align: center;
}
.menu-title {
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 4px;
  color: #000080;
  letter-spacing: 1px;
}
.menu-subtitle {
  font-size: 10px;
  color: #808080;
  margin-bottom: 20px;
}
.menu-cat-art {
  font-size: 48px;
  margin: 10px 0;
}
.menu-buttons {
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
  margin-top: 16px;
}

/* Cat Raising Screen */
#raise-screen {
  width: 520px; height: 420px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}
.raise-layout {
  display: flex;
  gap: 8px;
  padding: 8px;
  height: calc(100% - 28px);
}
.raise-left {
  width: 200px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.raise-right {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cat-display {
  text-align: center;
  padding: 10px;
}
.cat-sprite {
  font-size: 64px;
  line-height: 1;
  margin: 8px 0;
}
.cat-name {
  font-weight: bold;
  font-size: 13px;
}
.cat-breed {
  font-size: 10px;
  color: #808080;
}
.cat-level-badge {
  display: inline-block;
  background: #000080;
  color: white;
  padding: 1px 6px;
  font-size: 10px;
  font-weight: bold;
  margin-top: 4px;
}

.stat-bar-container {
  margin: 4px 0;
}
.stat-bar-label {
  font-size: 10px;
  margin-bottom: 2px;
  display: flex;
  justify-content: space-between;
}
.stat-bar {
  height: 14px;
  background: #fff;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
  position: relative;
}
.stat-bar-fill {
  height: 100%;
  transition: width 0.3s;
}
.stat-bar-fill.hp { background: #ff0000; }
.stat-bar-fill.exp { background: #008000; }
.stat-bar-fill.hunger { background: #ff8c00; }
.stat-bar-fill.happiness { background: #ff69b4; }
.stat-bar-fill.energy { background: #00bfff; }

.action-buttons {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.action-buttons .btn-95 {
  text-align: left;
  padding: 6px 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.action-buttons .btn-95 .action-cost {
  font-size: 9px;
  color: #808080;
}

.log-panel {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.log-header {
  font-weight: bold;
  font-size: 11px;
  margin-bottom: 4px;
}
.log-content {
  flex: 1;
  overflow-y: auto;
  background: #fff;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
  padding: 4px;
  font-size: 10px;
  line-height: 1.5;
}
.log-content .log-entry { margin-bottom: 2px; }
.log-content .log-good { color: #008000; }
.log-content .log-bad { color: #ff0000; }
.log-content .log-info { color: #000080; }
.log-content .log-treat { color: #ff8c00; }

.treats-display {
  display: flex;
  align-items: center;
  gap: 4px;
  font-weight: bold;
  font-size: 12px;
  padding: 4px 8px;
  background: #ffffcc;
  border: 1px solid #808080;
}

/* Battle Screen */
#battle-screen {
  width: 560px; height: 440px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}
.battle-layout {
  display: flex;
  flex-direction: column;
  padding: 8px;
  height: calc(100% - 28px);
  gap: 6px;
}
.battle-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.floor-display {
  font-weight: bold;
  font-size: 12px;
  background: #000080;
  color: white;
  padding: 2px 8px;
}
.battle-arena {
  flex: 1;
  display: flex;
  gap: 8px;
  min-height: 0;
}
.battle-side {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.battle-vs {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: bold;
  color: #ff0000;
  text-shadow: 1px 1px 0 #fff;
}
.battle-cat-info {
  padding: 6px;
  background: #fff;
  border: 1px solid #808080;
}
.battle-cat-name {
  font-weight: bold;
  font-size: 11px;
  margin-bottom: 2px;
}
.battle-cat-sprite {
  font-size: 40px;
  text-align: center;
  margin: 4px 0;
}
.battle-hp-bar {
  height: 10px;
  background: #fff;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
  margin: 2px 0;
}
.battle-hp-fill {
  height: 100%;
  background: #00aa00;
  transition: width 0.3s;
}
.battle-hp-fill.low { background: #ff8c00; }
.battle-hp-fill.danger { background: #ff0000; }
.battle-stats {
  font-size: 9px;
  color: #404040;
}
.battle-log {
  height: 60px;
  background: #fff;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
  padding: 4px;
  overflow-y: auto;
  font-size: 10px;
  line-height: 1.4;
}
.battle-actions {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.battle-actions .btn-95 { flex: 1; min-width: 80px; text-align: center; }

/* Inventory Screen */
#inventory-screen {
  width: 360px; height: 300px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}
.inv-layout {
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: calc(100% - 28px);
}
.inv-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  flex: 1;
}
.inv-slot {
  background: #fff;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff;
  padding: 6px;
  text-align: center;
  cursor: pointer;
  min-height: 60px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.inv-slot:hover { background: #ffffcc; }
.inv-slot-icon { font-size: 24px; }
.inv-slot-name { font-size: 9px; margin-top: 2px; }
.inv-slot-count { font-size: 9px; color: #808080; }

/* Cat Selection */
#select-screen {
  width: 420px; height: 360px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}
.select-layout {
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: calc(100% - 28px);
}
.select-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  flex: 1;
}
.select-cat-card {
  background: #fff;
  border: 1px solid #808080;
  padding: 8px;
  text-align: center;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.select-cat-card:hover { background: #ffffcc; }
.select-cat-card.selected {
  background: #000080;
  color: white;
  border-color: #000080;
}
.select-cat-sprite { font-size: 36px; }
.select-cat-name { font-weight: bold; font-size: 10px; }
.select-cat-breed { font-size: 9px; color: #808080; }
.select-cat-card.selected .select-cat-breed { color: #ccc; }

/* Scrollbar styling for Win95 feel */
::-webkit-scrollbar { width: 16px; }
::-webkit-scrollbar-track { background: #c0c0c0; border: 1px solid #808080; }
::-webkit-scrollbar-thumb {
  background: #c0c0c0;
  border-top: 2px solid #fff;
  border-left: 2px solid #fff;
  border-right: 2px solid #404040;
  border-bottom: 2px solid #404040;
}
::-webkit-scrollbar-button { background: #c0c0c0; border: 1px solid #808080; height: 16px; }

/* Animations */
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  75% { transform: translateX(4px); }
}
@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}
.shake { animation: shake 0.3s ease-in-out; }
.bounce { animation: bounce 0.5s ease-in-out; }

@keyframes flash {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}
.flash { animation: flash 0.2s ease-in-out 3; }

/* Tooltip */
.tooltip {
  position: absolute;
  background: #ffffcc;
  border: 1px solid #000;
  padding: 4px 6px;
  font-size: 10px;
  z-index: 2000;
  pointer-events: none;
  white-space: nowrap;
}

/* Status effects */
.status-effect {
  display: inline-block;
  font-size: 9px;
  padding: 1px 4px;
  margin: 1px;
  border: 1px solid #808080;
  background: #e0e0e0;
}
.status-effect.buff { background: #90ee90; }
.status-effect.debuff { background: #ffb6c1; }

/* Tab control */
.tab-control {
  display: flex;
  gap: 0;
  margin-bottom: 4px;
}
.tab-btn {
  background: #c0c0c0;
  border-top: 2px solid #fff;
  border-left: 2px solid #fff;
  border-right: 2px solid #404040;
  border-bottom: 1px solid #c0c0c0;
  padding: 3px 10px;
  font-size: 11px;
  cursor: pointer;
  font-family: inherit;
  position: relative;
  top: 1px;
}
.tab-btn.active {
  background: #fff;
  border-bottom: 1px solid #fff;
  z-index: 1;
}
.tab-content {
  background: #fff;
  border: 1px solid #808080;
  padding: 8px;
  min-height: 100px;
}

/* Progress bar for dungeon */
.dungeon-progress {
  display: flex;
  gap: 2px;
  margin: 4px 0;
}
.dungeon-floor {
  width: 16px; height: 16px;
  background: #808080;
