  font-size: 8px;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
}
.dungeon-floor.cleared { background: #008000; }
.dungeon-floor.current { background: #000080; }
.dungeon-floor.boss { background: #800000; }
</style>
</head>
