// ==================== WINDOW MANAGEMENT ====================
function closeWindow(id) {
  document.getElementById(id).style.display = 'none';
  updateTaskbar();
}

function showDialog(title, message) {
  const overlay = document.createElement('div');
  overlay.className = 'dialog-overlay';
  overlay.id = 'dialog-' + Date.now();
  overlay.innerHTML = `
    <div class="dialog-box" style="min-width:300px;">
      <div class="title-bar">
        <span class="title-bar-text">💬 ${title}</span>
        <div class="title-bar-controls">
          <button onclick="this.closest('.dialog-overlay').remove()">×</button>
        </div>
      </div>
      <div class="dialog-content">
        <div class="dialog-icon">😺</div>
        <div class="dialog-text"><p style="white-space:pre-line;">${message}</p></div>
      </div>
      <div class="dialog-buttons">
        <button class="btn-95" onclick="this.closest('.dialog-overlay').remove()">OK</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });
}

function updateTaskbar() {
  const container = document.getElementById('taskbar-windows');
  container.innerHTML = '';
  const screens = ['menu-screen', 'select-screen', 'raise-screen', 'battle-screen', 'shop-screen'];
  screens.forEach(id => {
    const el = document.getElementById(id);
    if (el && el.style.display !== 'none') {
      const btn = document.createElement('button');
      btn.className = 'btn-95';
      btn.style.cssText = 'flex:1; font-size:10px; padding:2px 6px; text-align:left;';
      const titles = { 'menu-screen': '🐱 Menu', 'select-screen': '🐱 Choose Cat', 'raise-screen': '🐱 Cat Raising', 'battle-screen': '⚔️ Battle', 'shop-screen': '🏪 Shop' };
      btn.textContent = titles[id] || id;
      btn.onclick = () => { el.style.display = el.style.display === 'none' ? 'block' : 'none'; updateTaskbar(); };
      container.appendChild(btn);
    }
  });
}

function toggleStartMenu() {
  const menu = document.getElementById('start-menu');
  menu.style.display = menu.style.display === 'block' ? 'none' : 'block';
}

function hideStartMenu() {
  document.getElementById('start-menu').style.display = 'none';
}

// Close start menu when clicking outside
document.addEventListener('click', (e) => {
  const menu = document.getElementById('start-menu');
  const btn = document.getElementById('start-btn');
  if (menu.style.display === 'block' && !menu.contains(e.target) && !btn.contains(e.target)) {
    hideStartMenu();
  }
});

// Clock
function updateClock() {
  const now = new Date();
  let h = now.getHours();
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  document.getElementById('taskbar-clock').textContent = h + ':' + String(now.getMinutes()).padStart(2, '0') + ' ' + ampm;
}
setInterval(updateClock, 1000);
updateClock();

// ==================== GAME INIT ====================
function startNewGame() {
  gameState = {
    cat: null,
    treats: 15,
    floor: 1,
    maxFloor: 10,
    enemiesCleared: 0,
    enemiesPerFloor: 3,
    inBattle: false,
    currentEnemy: null,
    battleLog: [],
    totalWins: 0,
    totalDeaths: 0,
    highFloor: 1,
  };
  closeWindow('menu-screen');
  closeWindow('raise-screen');
  closeWindow('battle-screen');
  closeWindow('shop-screen');
  showCatSelection();
}

function showCatSelection() {
  const grid = document.getElementById('select-grid');
  grid.innerHTML = '';
  selectedCatIndex = -1;
  document.getElementById('confirm-cat-btn').disabled = true;

  BREEDS.forEach((breed, i) => {
    const card = document.createElement('div');
    card.className = 'select-cat-card';
    card.innerHTML = `
      <div class="select-cat-sprite">${breed.sprite}</div>
      <div class="select-cat-name">${breed.name}</div>
      <div class="select-cat-breed">${breed.desc}</div>
    `;
    card.onclick = () => {
      document.querySelectorAll('.select-cat-card').forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
      selectedCatIndex = i;
      document.getElementById('confirm-cat-btn').disabled = false;
    };
    grid.appendChild(card);
  });

  document.getElementById('select-screen').style.display = 'block';
  updateTaskbar();
}

function confirmCatSelection() {
  if (selectedCatIndex < 0) return;
  const breed = BREEDS[selectedCatIndex];
  gameState.cat = {
    name: generateCatName(),
    breed: breed.name,
    sprite: breed.sprite,
    level: 1,
    exp: 0,
    expToNext: 30,
    hp: breed.baseHp,
    maxHp: breed.baseHp,
    atk: breed.baseAtk,
    def: breed.baseDef,
    spd: breed.baseSpd,
    atkBonus: 0,
    defBonus: 0,
    spdBonus: 0,
    hunger: 70,
    happiness: 80,
    energy: 80,
    treats: gameState.treats,
    wins: 0,
    kills: 0,
    items: [],
  };
  gameState.treats = 0;
  closeWindow('select-screen');
  showRaisingScreen();
}

function generateCatName() {
  const prefixes = ['Whiskers', 'Mittens', 'Shadow', 'Luna', 'Mochi', 'Noodle', 'Patches', 'Smokey', 'Cleo', 'Felix', 'Garfield', 'Salem', 'Tama', 'Maru', 'Milo', 'Oliver', 'Leo', 'Bella', 'Loki', 'Nala'];
  return prefixes[Math.floor(Math.random() * prefixes.length)];
}

// ==================== RAISING SCREEN ====================
function showRaisingScreen() {
  updateRaiseUI();
  addLog('info', `${gameState.cat.name} the ${gameState.cat.breed} is ready for adventure!`);
  addLog('info', `You have ${gameState.treats} treats. Use them wisely!`);
  document.getElementById('raise-screen').style.display = 'block';
  updateTaskbar();
  updateTowerProgress();
}

function updateRaiseUI() {
  const cat = gameState.cat;
  if (!cat) return;

  document.getElementById('raise-title').textContent = `🐱 ${cat.name} - ${cat.breed}`;
  document.getElementById('raise-cat-name').textContent = cat.name;
  document.getElementById('raise-cat-breed').textContent = cat.breed;
  document.getElementById('raise-cat-sprite').textContent = cat.sprite;
  document.getElementById('raise-cat-level').textContent = cat.level;

  const hpPct = (cat.hp / cat.maxHp) * 100;
  document.getElementById('raise-hp-bar').style.width = hpPct + '%';
  document.getElementById('raise-hp-text').textContent = `${cat.hp}/${cat.maxHp}`;

  const expPct = (cat.exp / cat.expToNext) * 100;
  document.getElementById('raise-exp-bar').style.width = expPct + '%';
  document.getElementById('raise-exp-text').textContent = `${cat.exp}/${cat.expToNext}`;

  document.getElementById('raise-treats').textContent = cat.treats;

  updateStatsTab();
  updateItemsTab();
  updateTowerProgress();
}

function updateStatsTab() {
  const cat = gameState.cat;
  if (!cat) return;
  const totalAtk = cat.atk + cat.atkBonus;
  const totalDef = cat.def + cat.defBonus;
  const totalSpd = cat.spd + cat.spdBonus;

  document.getElementById('stats-content').innerHTML = `
    <div style="display:grid; grid-template-columns: 1fr 1fr; gap:4px 12px;">
      <div>❤️ Max HP:</div><div>${cat.maxHp}</div>
      <div>⚔️ Attack:</div><div>${totalAtk} ${cat.atkBonus > 0 ? '(+' + cat.atkBonus + ')' : ''}</div>
      <div>🛡️ Defense:</div><div>${totalDef} ${cat.defBonus > 0 ? '(+' + cat.defBonus + ')' : ''}</div>
      <div>💨 Speed:</div><div>${totalSpd} ${cat.spdBonus > 0 ? '(+' + cat.spdBonus + ')' : ''}</div>
      <div>📊 Level:</div><div>${cat.level}</div>
      <div>🏆 Wins:</div><div>${cat.wins}</div>
      <div>💀 Kills:</div><div>${cat.kills}</div>
      <div>🐟 Treats:</div><div>${cat.treats}</div>
      <div>😋 Hunger:</div><div>${cat.hunger}%</div>
      <div>😊 Happiness:</div><div>${cat.happiness}%</div>
      <div>⚡ Energy:</div><div>${cat.energy}%</div>
    </div>
  `;
}

function updateItemsTab() {
  const cat = gameState.cat;
  if (!cat) return;
  if (cat.items.length === 0) {
    document.getElementById('items-content').innerHTML = '<div style="color:#808080; text-align:center; padding:20px;">No items yet. Visit the shop!</div>';
    return;
  }
  let html = '';
  cat.items.forEach((item, i) => {
    html += `<div style="display:flex; justify-content:space-between; padding:2px 0; border-bottom:1px solid #eee;">
      <span>${item.icon} ${item.name}</span>
      <span style="color:#808080;">x${item.count}</span>
    </div>`;
  });
  document.getElementById('items-content').innerHTML = html;
}

function updateTowerProgress() {
  const container = document.getElementById('tower-progress');
  container.innerHTML = '';
  for (let i = 1; i <= gameState.maxFloor; i++) {
    const floor = document.createElement('div');
    floor.className = 'dungeon-floor';
    floor.textContent = i;
    if (i < gameState.floor) floor.classList.add('cleared');
    else if (i === gameState.floor) floor.classList.add('current');
    if (i % 5 === 0) floor.classList.add('boss');
    container.appendChild(floor);
  }
  document.getElementById('tower-info').textContent = `Floor ${gameState.floor}/${gameState.maxFloor} - ${gameState.floor % 5 === 0 ? '⚠️ BOSS FLOOR!' : 'Enter the tower to battle!'}`;
}

function switchTab(tab) {
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.tab-content').forEach(c => c.style.display = 'none');
  event.target.classList.add('active');
  document.getElementById('tab-' + tab).style.display = tab === 'log' ? 'flex' : 'block';
}

function addLog(type, message) {
  const log = document.getElementById('raise-log');
  const entry = document.createElement('div');
  entry.className = 'log-entry log-' + type;
  entry.textContent = '> ' + message;
  log.appendChild(entry);
  log.scrollTop = log.scrollHeight;
}

// ==================== RAISING ACTIONS ====================
function raiseAction(action) {
  const cat = gameState.cat;
  if (!cat) return;

  switch (action) {
    case 'feed':
      if (cat.treats > 0) {
        cat.treats--;
        cat.hunger = Math.min(100, cat.hunger + 25);
        cat.hp = Math.min(cat.maxHp, cat.hp + 5);
        addLog('good', `Fed ${cat.name} treats! Hunger +25, HP +5`);
      } else {
        addLog('bad', `No treats left! Visit the shop.`);
      }
      break;

    case 'play':
      if (cat.energy >= 10) {
        cat.energy -= 10;
        cat.happiness = Math.min(100, cat.happiness + 20);
        cat.exp += 3;
        addLog('info', `Played with ${cat.name}! Happiness +20, EXP +3`);
      } else {
        addLog('bad', `${cat.name} is too tired to play!`);
      }
      break;

    case 'train':
      if (cat.energy >= 20) {
        cat.energy -= 20;
        cat.atk += 1;
        cat.def += 1;
        cat.exp += 5;
        addLog('good', `Trained ${cat.name}! ATK +1, DEF +1, EXP +5`);
      } else {
        addLog('bad', `${cat.name} is too tired to train!`);
      }
      break;

    case 'rest':
      cat.energy = Math.min(100, cat.energy + 30);
      cat.hunger = Math.max(0, cat.hunger - 10);
      addLog('info', `${cat.name} took a nap. Energy +30, Hunger -10`);
      break;

    case 'shop':
      closeWindow('raise-screen');
      showShop();
      return;
  }

  // Check level up
  checkLevelUp();

  // Random events
  if (Math.random() < 0.15) {
    randomEvent();
  }

  updateRaiseUI();
}

function checkLevelUp() {
  const cat = gameState.cat;
  while (cat.exp >= cat.expToNext) {
    cat.exp -= cat.expToNext;
    cat.level++;
    cat.expToNext = Math.floor(cat.expToNext * 1.5);
    cat.maxHp += 8;
    cat.hp = cat.maxHp;
    cat.atk += 2;
    cat.def += 1;
    cat.spd += 1;
    addLog('good', `🎉 ${cat.name} leveled up to Level ${cat.level}!`);
  }
}

function randomEvent() {
  const cat = gameState.cat;
  const events = [
    { msg: `${cat.name} found a lost mouse toy! Happiness +10`, effect: () => { cat.happiness = Math.min(100, cat.happiness + 10); } },
    { msg: `${cat.name} caught a butterfly! EXP +5`, effect: () => { cat.exp += 5; } },
    { msg: `${cat.name} chased a laser pointer! Energy -10`, effect: () => { cat.energy = Math.max(0, cat.energy - 10); } },
    { msg: `${cat.name} knocked over a vase! Treats -2`, effect: () => { cat.treats = Math.max(0, cat.treats - 2); } },
    { msg: `${cat.name} had a great dream! HP fully restored`, effect: () => { cat.hp = cat.maxHp; } },
    { msg: `${cat.name} discovered a hidden stash! Treats +3`, effect: () => { cat.treats += 3; } },
    { msg: `${cat.name} practiced meowing! ATK +1`, effect: () => { cat.atk += 1; } },
    { msg: `${cat.name} sunbathed all day! Happiness +15, Energy +10`, effect: () => { cat.happiness = Math.min(100, cat.happiness + 15); cat.energy = Math.min(100, cat.energy + 10); } },
  ];
  const event = events[Math.floor(Math.random() * events.length)];
  event.effect();
  addLog('info', event.msg);
}

// ==================== SHOP ====================
function showShop() {
  document.getElementById('shop-treats').textContent = gameState.cat.treats;
  const grid = document.getElementById('shop-grid');
  grid.innerHTML = '';

  SHOP_ITEMS.forEach(item => {
    const slot = document.createElement('div');
    slot.className = 'inv-slot';
    slot.innerHTML = `
      <div class="inv-slot-icon">${item.icon}</div>
      <div class="inv-slot-name">${item.name}</div>
      <div class="inv-slot-count">🐟 ${item.cost}</div>
    `;
    slot.onclick = () => buyItem(item);
    grid.appendChild(slot);
  });

  document.getElementById('shop-screen').style.display = 'block';
  updateTaskbar();
}

function buyItem(item) {
  const cat = gameState.cat;
  if (cat.treats >= item.cost) {
    cat.treats -= item.cost;
    item.effect(cat);

    // Track items
    const existing = cat.items.find(i => i.name === item.name);
    if (existing) {
      existing.count++;
    } else {
      cat.items.push({ name: item.name, icon: item.icon, count: 1 });
    }

    addLog('good', `Bought ${item.name} for ${item.cost} treats!`);
    document.getElementById('shop-treats').textContent = cat.treats;
    updateRaiseUI();
  } else {
    showDialog('Not Enough Treats', `You need ${item.cost} treats but only have ${cat.treats}.`);
  }
}

// ==================== DUNGEON / BATTLE ====================
function startDungeon() {
  const cat = gameState.cat;
  if (!cat) return;

  if (cat.energy < 10) {
    showDialog('Too Tired!', `${cat.name} is too tired to enter the Cat Tower. Let them rest first!`);
    return;
  }

  if (cat.hunger < 10) {
    showDialog('Too Hungry!', `${cat.name} is too hungry to battle. Feed them first!`);
    return;
  }

  if (cat.hp < cat.maxHp * 0.3) {
    showDialog('Too Injured!', `${cat.name} is too injured. Heal them first!`);
    return;
  }

  gameState.floor = 1;
  gameState.enemiesCleared = 0;
  gameState.enemiesPerFloor = 3;
  closeWindow('raise-screen');
  startBattle();
}

function startBattle() {
  const cat = gameState.cat;
  if (!cat) return;

  gameState.inBattle = true;
  gameState.battleLog = [];

  // Generate enemy
  const isBossFloor = gameState.floor % 5 === 0;
  const enemy = generateEnemy(isBossFloor);
  gameState.currentEnemy = enemy;

  // Update battle UI
  document.getElementById('battle-title').textContent = `⚔️ Battle - Floor ${gameState.floor}`;
  document.getElementById('battle-floor').textContent = `Floor ${gameState.floor}`;
  document.getElementById('battle-enemies-left').textContent = `Enemies remaining: ${gameState.enemiesPerFloor - gameState.enemiesCleared}`;

  // Player side
  document.getElementById('battle-player-name').textContent = `${cat.name} (Lv.${cat.level})`;
  document.getElementById('battle-player-sprite').textContent = cat.sprite;
  updateBattleHP('player');
  document.getElementById('battle-player-stats').textContent =
    `ATK:${cat.atk + cat.atkBonus} DEF:${cat.def + cat.defBonus} SPD:${cat.spd + cat.spdBonus}`;

  // Enemy side
  document.getElementById('battle-enemy-name').textContent = `${enemy.name} (Lv.${enemy.level})`;
  document.getElementById('battle-enemy-sprite').textContent = enemy.sprite;
  updateBattleHP('enemy');
  document.getElementById('battle-enemy-stats').textContent =
    `ATK:${enemy.atk} DEF:${enemy.def} SPD:${enemy.spd}`;

  document.getElementById('battle-log').innerHTML = '';
  addBattleLog(`A wild ${enemy.name} appears!`);

  // Enable/disable flee based on speed
  const totalSpd = cat.spd + cat.spdBonus;
  const fleeBtn = document.querySelector('.battle-actions .btn-95:last-child');
  fleeBtn.disabled = totalSpd < enemy.spd && gameState.floor > 1;

  battleTurn = 'player';
  document.getElementById('battle-actions').style.pointerEvents = 'auto';

  document.getElementById('battle-screen').style.display = 'block';
  updateTaskbar();
}

function generateEnemy(isBoss) {
  const floor = gameState.floor;
  let pool, name, sprite, baseHp, baseAtk, baseDef, baseSpd;

  if (isBoss) {
    const boss = BOSS_BREEDS[Math.min(Math.floor((floor - 1) / 5), BOSS_BREEDS.length - 1)];
    name = boss.name;
    sprite = boss.sprite;
    baseHp = boss.baseHp;
    baseAtk = boss.baseAtk;
    baseDef = boss.baseDef;
    baseSpd = boss.baseSpd;
  } else {
    const enemy = ENEMY_BREEDS[Math.floor(Math.random() * ENEMY_BREEDS.length)];
    name = enemy.name;
    sprite = enemy.sprite;
    baseHp = enemy.baseHp;
    baseAtk = enemy.baseAtk;
    baseDef = enemy.baseDef;
    baseSpd = enemy.baseSpd;
  }

  const level = Math.max(1, Math.floor(floor * 0.8) + Math.floor(Math.random() * 3));
  const scale = 1 + (level - 1) * 0.15;

  return {
    name, sprite,
    level,
    hp: Math.floor(baseHp * scale),
    maxHp: Math.floor(baseHp * scale),
    atk: Math.floor(baseAtk * scale),
    def: Math.floor(baseDef * scale),
    spd: Math.floor(baseSpd * scale),
    isBoss,
  };
}

function updateBattleHP(side) {
  const cat = gameState.cat;
  const enemy = gameState.currentEnemy;

  if (side === 'player') {
    const pct = (cat.hp / cat.maxHp) * 100;
    const bar = document.getElementById('battle-player-hp');
    bar.style.width = pct + '%';
    bar.className = 'battle-hp-fill' + (pct < 25 ? ' danger' : pct < 50 ? ' low' : '');
    document.getElementById('battle-player-hp-text').textContent = `${cat.hp}/${cat.maxHp}`;
  } else {
    const pct = (enemy.hp / enemy.maxHp) * 100;
    const bar = document.getElementById('battle-enemy-hp');
    bar.style.width = pct + '%';
