  if (!candy.attached && candy.y > H / s - 20 * s && candy.x > 20 * s && candy.x < W / s - 20 * s) {
    // Let it bounce, but if it goes way off, fail
  }
}

function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.1;
    p.life -= 0.02;
    if (p.life <= 0) particles.splice(i, 1);
  }
}

function updateBubbles() {
  for (let b of bubbles) {
    b.y -= b.speed;
    b.x += Math.sin(b.wobble) * 0.3;
    b.wobble += 0.02;
    if (b.y < -10) {
      b.y = H / scale + 10;
      b.x = Math.random() * 400;
    }
  }
}

// Drawing functions
function drawBackground() {
  let s = scale;
  // Gradient background
  let grad = ctx.createLinearGradient(0, 0, 0, H / s);
  grad.addColorStop(0, '#2d1b69');
  grad.addColorStop(0.5, '#1a0a2e');
  grad.addColorStop(1, '#0d0520');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W / s, H / s);

  // Background stars
  let time = Date.now() * 0.001;
  for (let bs of bgStars) {
    let alpha = 0.3 + 0.7 * Math.abs(Math.sin(time + bs.twinkle));
    ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
    ctx.beginPath();
    ctx.arc(bs.x * s, bs.y * s, bs.r * s, 0, Math.PI * 2);
