  }

  // Floor
  let floorY = H / s - 10 * s;
  let floorGrad = ctx.createLinearGradient(0, floorY, 0, H / s);
  floorGrad.addColorStop(0, '#4a2d8a');
  floorGrad.addColorStop(1, '#2d1b69');
  ctx.fillStyle = floorGrad;
  ctx.fillRect(0, floorY, W / s, 10 * s);
}

function drawRope(rope) {
  if (rope.cut || rope.points.length < 2) return;

  ctx.strokeStyle = '#8B6914';
  ctx.lineWidth = 4 * scale;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  ctx.beginPath();
  ctx.moveTo(rope.points[0].x, rope.points[0].y);
  for (let i = 1; i < rope.points.length; i++) {
    ctx.lineTo(rope.points[i].x, rope.points[i].y);
  }
  ctx.stroke();

  // Highlight
  ctx.strokeStyle = '#C4A035';
  ctx.lineWidth = 2 * scale;
  ctx.beginPath();
  ctx.moveTo(rope.points[0].x, rope.points[0].y);
  for (let i = 1; i < rope.points.length; i++) {
    ctx.lineTo(rope.points[i].x, rope.points[i].y);
  }
  ctx.stroke();

  // Anchor point
  ctx.fillStyle = '#666';
  ctx.beginPath();
  ctx.arc(rope.anchorX, rope.anchorY, 8 * scale, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#888';
  ctx.beginPath();
  ctx.arc(rope.anchorX, rope.anchorY, 5 * scale, 0, Math.PI * 2);
  ctx.fill();

  // Nail detail
  ctx.fillStyle = '#aaa';
  ctx.beginPath();
  ctx.arc(rope.anchorX - 1 * scale, rope.anchorY - 1 * scale, 2 * scale, 0, Math.PI * 2);
