}

function drawCutRopeEnd(rope) {
  if (!rope.cut || rope.points.length < 2) return;
  let last = rope.points[rope.points.length - 1];
  ctx.fillStyle = '#8B6914';
  ctx.beginPath();
  ctx.arc(last.x, last.y, 3 * scale, 0, Math.PI * 2);
  ctx.fill();
}

function drawStar(star, time) {
  if (star.collected) return;

  let s = scale;
  star.angle += 0.02;
  let pulse = 1 + Math.sin(time * 3 + star.angle) * 0.1;
  let r = star.r * pulse;

  // Glow
  let glowGrad = ctx.createRadialGradient(star.x, star.y, 0, star.x, star.y, r * 2.5);
  glowGrad.addColorStop(0, 'rgba(255, 215, 0, 0.3)');
  glowGrad.addColorStop(1, 'rgba(255, 215, 0, 0)');
  ctx.fillStyle = glowGrad;
  ctx.beginPath();
  ctx.arc(star.x, star.y, r * 2.5, 0, Math.PI * 2);
  ctx.fill();

  // Star shape
  ctx.save();
  ctx.translate(star.x, star.y);
  ctx.rotate(star.angle * 0.3);

  ctx.fillStyle = '#FFD700';
  ctx.strokeStyle = '#B8860B';
  ctx.lineWidth = 2 * s;
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    let angle = (i * 4 * Math.PI / 5) - Math.PI / 2;
    let x = Math.cos(angle) * r;
    let y = Math.sin(angle) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // Inner highlight
  ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
  ctx.beginPath();
  ctx.arc(-r * 0.15, -r * 0.15, r * 0.35, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

function drawCandy(time) {
  if (candy.eaten) return;

  let s = scale;

  // Trail
  for (let i = 0; i < candy.trail.length; i++) {
    let t = candy.trail[i];
    if (t.life > 0) {
      ctx.fillStyle = `rgba(255, 100, 100, ${t.life * 0.3})`;
      ctx.beginPath();
      ctx.arc(t.x, t.y, candy.r * t.life * 0.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Candy glow
  let glowGrad = ctx.createRadialGradient(candy.x, candy.y, 0, candy.x, candy.y, candy.r * 2);
  glowGrad.addColorStop(0, 'rgba(255, 50, 50, 0.2)');
  glowGrad.addColorStop(1, 'rgba(255, 50, 50, 0)');
  ctx.fillStyle = glowGrad;
  ctx.beginPath();
  ctx.arc(candy.x, candy.y, candy.r * 2, 0, Math.PI * 2);
  ctx.fill();

  // Candy body
  let candyGrad = ctx.createRadialGradient(
    candy.x - candy.r * 0.3, candy.y - candy.r * 0.3, 0,
    candy.x, candy.y, candy.r
  );
  candyGrad.addColorStop(0, '#FF6B6B');
  candyGrad.addColorStop(0.7, '#E53935');
  candyGrad.addColorStop(1, '#B71C1C');
  ctx.fillStyle = candyGrad;
  ctx.beginPath();
  ctx.arc(candy.x, candy.y, candy.r, 0, Math.PI * 2);
  ctx.fill();

  // Candy wrapper (stripes)
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
  ctx.lineWidth = 2 * s;
  ctx.beginPath();
  ctx.arc(candy.x, candy.y, candy.r * 0.6, -0.5, 0.5);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(candy.x, candy.y, candy.r * 0.6, Math.PI - 0.5, Math.PI + 0.5);
  ctx.stroke();

  // Highlight
  ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
  ctx.beginPath();
  ctx.arc(candy.x - candy.r * 0.25, candy.y - candy.r * 0.25, candy.r * 0.3, 0, Math.PI * 2);
  ctx.fill();

  // Candy string
  if (candy.attached && candy.ropeIndex >= 0 && ropes[candy.ropeIndex]) {
    let rope = ropes[candy.ropeIndex];
    let closestDist = Infinity;
    let closestPoint = null;
    for (let p of rope.points) {
      let dx = candy.x - p.x;
      let dy = candy.y - p.y;
      let d = dx * dx + dy * dy;
      if (d < closestDist) {
        closestDist = d;
        closestPoint = p;
      }
    }
    if (closestPoint) {
      ctx.strokeStyle = '#8B6914';
      ctx.lineWidth = 2 * s;
      ctx.beginPath();
      ctx.moveTo(candy.x, candy.y);
      ctx.lineTo(closestPoint.x, closestPoint.y);
      ctx.stroke();
    }
  }
}

function drawOmNom(time) {
  let s = scale;
  let bounce = omNomBounce > 0 ? Math.sin(omNomBounce * Math.PI) * 10 * s : 0;

  let x = omNom.x;
  let y = omNom.y + bounce;
  let r = omNom.r;

  // Shadow
  ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
  ctx.beginPath();
  ctx.ellipse(x, y + r + 5 * s, r * 0.8, 5 * s, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body
  let bodyGrad = ctx.createRadialGradient(x - r * 0.2, y - r * 0.2, 0, x, y, r);
  bodyGrad.addColorStop(0, '#76FF03');
  bodyGrad.addColorStop(0.6, '#64DD17');
  bodyGrad.addColorStop(1, '#33691E');
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();

  // Outline
  ctx.strokeStyle = '#1B5E20';
  ctx.lineWidth = 2 * s;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
