  // Tongue
  if (mouthOpen > 0.3) {
    ctx.fillStyle = '#FF5252';
    ctx.beginPath();
    ctx.ellipse(x, y + r * 0.15 + mouthH * 0.4, mouthW * 0.5, mouthH * 0.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // Teeth
  if (mouthOpen > 0.2) {
    ctx.fillStyle = '#fff';
    let toothW = mouthW * 0.2;
    let toothH = mouthH * 0.4;
    ctx.fillRect(x - toothW * 1.5, y + r * 0.15 - mouthH * 0.5, toothW, toothH);
    ctx.fillRect(x + toothW * 0.5, y + r * 0.15 - mouthH * 0.5, toothW, toothH);
  }

  // Eyes
  let eyeSpacing = r * 0.35;
  let eyeY = y - r * 0.2;
  let eyeR = r * 0.22;

  // Eye whites
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.ellipse(x - eyeSpacing, eyeY, eyeR, eyeR * 1.1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(x + eyeSpacing, eyeY, eyeR, eyeR * 1.1, 0, 0, Math.PI * 2);
  ctx.fill();

  // Pupils - look toward candy
  let lookX = 0, lookY = 0;
  if (!candy.eaten) {
    let dx = candy.x - x;
    let dy = candy.y - y;
    let dist = Math.sqrt(dx * dx + dy * dy);
    if (dist > 0) {
      lookX = (dx / dist) * eyeR * 0.3;
      lookY = (dy / dist) * eyeR * 0.3;
