  ctx.fillStyle = '#1a1a1a';
  ctx.beginPath();
  ctx.arc(x - eyeSpacing + lookX, eyeY + lookY, eyeR * 0.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x + eyeSpacing + lookX, eyeY + lookY, eyeR * 0.5, 0, Math.PI * 2);
  ctx.fill();

  // Eye shine
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(x - eyeSpacing + lookX - eyeR * 0.15, eyeY + lookY - eyeR * 0.2, eyeR * 0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x + eyeSpacing + lookX - eyeR * 0.15, eyeY + lookY - eyeR * 0.2, eyeR * 0.2, 0, Math.PI * 2);
