  ctx.arc(x - eyeSpacing, eyeY - eyeR * 1.3, eyeR * 0.8, Math.PI + 0.3, -0.3);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(x + eyeSpacing, eyeY - eyeR * 1.3, eyeR * 0.8, Math.PI + 0.3, -0.3);
