  ctx.fillStyle = '#76FF03';
  ctx.beginPath();
  ctx.arc(x - r * 0.3, y - r * 1.8, 4 * s, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x + r * 0.3, y - r * 1.8, 4 * s, 0, Math.PI * 2);
  ctx.fill();
}

function drawParticles() {
  for (let p of particles) {
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r * scale, 0, Math.PI * 2);
    ctx.fill();
  }
