// Cutting logic
function checkCut(x1, y1, x2, y2) {
  for (let i = ropes.length - 1; i >= 0; i--) {
    let rope = ropes[i];
    if (rope.cut) continue;

    for (let j = 0; j < rope.points.length - 1; j++) {
      let p1 = rope.points[j];
      let p2 = rope.points[j + 1];

      // Check if line segment intersects cut line
      if (lineIntersects(x1, y1, x2, y2, p1.x, p1.y, p2.x, p2.y)) {
        rope.cut = true;

        // Add momentum to rope end
        let lastP = rope.points[rope.points.length - 1];
        lastP.oldX = lastP.x - (lastP.x - lastP.oldX) * 0.5;
        lastP.oldY = lastP.y - (lastP.y - lastP.oldY) * 0.5;

        // Check if candy is attached to this rope
        if (candy.attached && candy.ropeIndex === i) {
          // Find the point closest to candy and attach candy to it
          let minDist = Infinity;
          let closestIdx = 0;
          for (let k = 0; k < rope.points.length; k++) {
            let dx = candy.x - rope.points[k].x;
            let dy = candy.y - rope.points[k].y;
            let d = dx * dx + dy * dy;
            if (d < minDist) {
              minDist = d;
              closestIdx = k;
            }
          }
          // Give candy a push away from the cut
          let cutDirX = x2 - x1;
          let cutDirY = y2 - y1;
          let cutLen = Math.sqrt(cutDirX * cutDirX + cutDirY * cutDirY);
          if (cutLen > 0) {
            candy.vx += (cutDirX / cutLen) * 3 * scale;
            candy.vy += (cutDirY / cutLen) * 3 * scale;
          }
        }

        // Cut particles
        let cutX = (p1.x + p2.x) / 2;
        let cutY = (p1.y + p2.y) / 2;
        for (let k = 0; k < 6; k++) {
          particles.push({
            x: cutX, y: cutY,
            vx: (Math.random() - 0.5) * 4,
            vy: (Math.random() - 0.5) * 4,
            life: 1,
            color: '#C4A035',
            r: Math.random() * 3 + 1
          });
        }
        break;
      }
    }
  }
}

function lineIntersects(x1, y1, x2, y2, x3, y3, x4, y4) {
  let denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (Math.abs(denom) < 0.001) return false;
  let t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
  let u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;
  return t >= 0 && t <= 1 && u >= 0 && u <= 1;
}

// Input handling
function getPos(e) {
  let rect = canvas.getBoundingClientRect();
  let scaleX = (W / scale) / rect.width;
  let scaleY = (H / scale) / rect.height;
  let clientX, clientY;
  if (e.touches) {
    clientX = e.touches[0].clientX;
    clientY = e.touches[0].clientY;
  } else {
    clientX = e.clientX;
    clientY = e.clientY;
  }
  return {
    x: (clientX - rect.left) * scaleX,
    y: (clientY - rect.top) * scaleY
  };
}

canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  let pos = getPos(e);
  touchStartX = pos.x;
  touchStartY = pos.y;
  touchCurrentX = pos.x;
  touchCurrentY = pos.y;
  isTouching = true;
  document.getElementById('hint-text').style.display = 'none';
});

canvas.addEventListener('touchmove', (e) => {
  e.preventDefault();
  if (!isTouching) return;
  let pos = getPos(e);
  touchCurrentX = pos.x;
  touchCurrentY = pos.y;
  checkCut(touchStartX, touchStartY, touchCurrentX, touchCurrentY);
  touchStartX = touchCurrentX;
  touchStartY = touchCurrentY;
});

canvas.addEventListener('touchend', (e) => {
  e.preventDefault();
  isTouching = false;
});

canvas.addEventListener('mousedown', (e) => {
  let pos = getPos(e);
  touchStartX = pos.x;
  touchStartY = pos.y;
  touchCurrentX = pos.x;
  touchCurrentY = pos.y;
  isTouching = true;
  document.getElementById('hint-text').style.display = 'none';
});

canvas.addEventListener('mousemove', (e) => {
  if (!isTouching) return;
  let pos = getPos(e);
  touchCurrentX = pos.x;
  touchCurrentY = pos.y;
  checkCut(touchStartX, touchStartY, touchCurrentX, touchCurrentY);
  touchStartX = touchCurrentX;
  touchStartY = touchCurrentY;
});

canvas.addEventListener('mouseup', () => {
  isTouching = false;
});

// Main game loop
function update(time) {
  let s = scale;

  // Update physics
  for (let rope of ropes) {
    updateRope(rope);
  }
  updateCandy();
  updateParticles();
  updateBubbles();

  // Om Nom bounce decay
  if (omNomBounce > 0) {
    omNomBounce -= 0.02;
    if (omNomBounce < 0) omNomBounce = 0;
  }

  // Draw
  ctx.clearRect(0, 0, W / s, H / s);
  drawBackground();

  // Draw ropes
  for (let rope of ropes) {
    drawRope(rope);
    drawCutRopeEnd(rope);
  }

  // Draw stars
  for (let star of stars) {
    drawStar(star, time * 0.001);
  }

  // Draw candy
  drawCandy(time * 0.001);

  // Draw Om Nom
  drawOmNom(time * 0.001);

  // Draw particles
  drawParticles();

  // Draw cut line
  drawCutLine();

  requestAnimationFrame(update);
}

function resetLevel() {
  initLevel();
}

// Start
initLevel();
requestAnimationFrame(update);
</script>
