// ==================== ZONE SYSTEM ====================
function updateZone(dt) {
    GAME.zone.shrinkTimer -= dt;

    if (GAME.zone.shrinkTimer <= 0) {
        GAME.zone.phase++;
        GAME.zone.targetRadius = Math.max(50, GAME.zone.radius * 0.6);
        GAME.zone.shrinkTimer = 45 - GAME.zone.phase * 5;

        // Move zone center slightly
        GAME.zone.x += (Math.random() - 0.5) * 100;
        GAME.zone.z += (Math.random() - 0.5) * 100;
    }

    // Shrink zone
    if (GAME.zone.radius > GAME.zone.targetRadius) {
        GAME.zone.radius -= dt * 2;
    }

    // Visual zone
    updateZoneVisual();
}

let zoneVisual;
function createZoneVisual() {
    const geo = new THREE.CylinderGeometry(GAME.zone.radius, GAME.zone.radius, 100, 64, 1, true);
    const mat = new THREE.MeshBasicMaterial({
        color: 0x0066ff,
        transparent: true,
        opacity: 0.15,
        side: THREE.DoubleSide
    });
    zoneVisual = new THREE.Mesh(geo, mat);
    zoneVisual.position.set(GAME.zone.x, 50, GAME.zone.z);
    GAME.scene.add(zoneVisual);

    // Zone border
    const borderGeo = new THREE.CylinderGeometry(GAME.zone.radius, GAME.zone.radius, 0.5, 64);
    const borderMat = new THREE.MeshBasicMaterial({ color: 0x0066ff, transparent: true, opacity: 0.5 });
    const border = new THREE.Mesh(borderGeo, borderMat);
    border.position.set(GAME.zone.x, 0.25, GAME.zone.z);
    GAME.scene.add(border);
}

function updateZoneVisual() {
    if (zoneVisual) {
        zoneVisual.geometry.dispose();
        zoneVisual.geometry = new THREE.CylinderGeometry(GAME.zone.radius, GAME.zone.radius, 100, 64, 1, true);
        zoneVisual.position.set(GAME.zone.x, 50, GAME.zone.z);
    }
}

// ==================== MINIMAP ====================
function updateMinimap() {
    const canvas = document.getElementById('minimap-canvas');
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;

    ctx.fillStyle = '#1a3a1a';
    ctx.fillRect(0, 0, w, h);

    const scale = w / GAME.mapSize;
    const cx = w / 2;
    const cy = h / 2;

    // Zone circle
    ctx.strokeStyle = '#0066ff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx + GAME.zone.x * scale, cy + GAME.zone.z * scale, GAME.zone.radius * scale, 0, Math.PI * 2);
    ctx.stroke();

    // Buildings
    ctx.fillStyle = '#666';
    for (const b of GAME.buildings) {
        const bx = cx + b.position.x * scale;
        const bz = cy + b.position.z * scale;
        ctx.fillRect(bx - 2, bz - 2, 4, 4);
    }

    // Enemies (red dots)
    ctx.fillStyle = '#ff3333';
    for (const e of GAME.enemies) {
        if (!e.alive) continue;
        const ex = cx + e.mesh.position.x * scale;
        const ez = cy + e.mesh.position.z * scale;
        const dist = e.mesh.position.distanceTo(GAME.camera.position);
        if (dist < 100) {
            ctx.beginPath();
            ctx.arc(ex, ez, 2, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    // Player (white triangle)
    const px = cx + GAME.camera.position.x * scale;
    const py = cy + GAME.camera.position.z * scale;

    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-GAME.player.yaw);
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.moveTo(0, -4);
    ctx.lineTo(-3, 3);
    ctx.lineTo(3, 3);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
}

