// ==================== LOOT PICKUP ====================
function checkLootPickup() {
    const playerPos = GAME.camera.position;
    let nearestLoot = null;
    let nearestDist = 3;

    for (const loot of GAME.lootItems) {
        if (loot.userData.collected) continue;
        const dist = playerPos.distanceTo(loot.position);
        if (dist < nearestDist) {
            nearestDist = dist;
            nearestLoot = loot;
        }
    }

    const popup = document.getElementById('loot-popup');

    if (nearestLoot) {
        nearestLoot.userData.lootName = nearestLoot.userData.lootType;
        popup.style.display = 'block';
        popup.innerHTML = `[F] Pick up ${nearestLoot.userData.lootType.replace('_', ' ').toUpperCase()}`;
        GAME.lootNearby = nearestLoot;

        // Animate loot
        nearestLoot.position.y = Math.sin(Date.now() * 0.003) * 0.1 + 0.2;
        nearestLoot.rotation.y += 0.02;
    } else {
        popup.style.display = 'none';
        GAME.lootNearby = null;
    }
}

function pickupLoot() {
    if (!GAME.lootNearby) return;

    const loot = GAME.lootNearby;
    const type = loot.userData.lootType;

    audio.playPickup();

    switch(type) {
        case 'health':
            GAME.player.heal(25);
            break;
        case 'armor':
            GAME.player.addArmor(50);
            break;
        case 'rifle_ammo':
            GAME.weapons.rifle.reserve += 30;
            break;
        case 'shotgun_ammo':
            GAME.weapons.shotgun.reserve += 16;
            break;
        case 'sniper_ammo':
            GAME.weapons.sniper.reserve += 10;
            break;
        case 'rifle':
            GAME.currentWeapon = 'rifle';
            GAME.weapons.rifle.ammo = GAME.weapons.rifle.maxAmmo;
            break;
        case 'shotgun':
            GAME.currentWeapon = 'shotgun';
            GAME.weapons.shotgun.ammo = GAME.weapons.shotgun.maxAmmo;
            break;
        case 'sniper':
            GAME.currentWeapon = 'sniper';
            GAME.weapons.sniper.ammo = GAME.weapons.sniper.maxAmmo;
            break;
    }

    loot.userData.collected = true;
    GAME.scene.remove(loot);
    GAME.lootItems = GAME.lootItems.filter(l => l !== loot);

    updateHUD();
}

