// ==================== BOT VS BOT COMBAT ====================
function updateBotCombat(dt) {
    for (let i = 0; i < GAME.enemies.length; i++) {
        if (!GAME.enemies[i].alive) continue;

        for (let j = i + 1; j < GAME.enemies.length; j++) {
            if (!GAME.enemies[j].alive) continue;

            const dist = GAME.enemies[i].mesh.position.distanceTo(GAME.enemies[j].mesh.position);
            if (dist < 50 && Math.random() < 0.001) {
                // Bot vs bot combat
                GAME.enemies[i].state = 'attack';
                GAME.enemies[j].state = 'attack';
                GAME.enemies[i].target = GAME.enemies[j].mesh.position;
                GAME.enemies[j].target = GAME.enemies[i].mesh.position;
            }
        }
    }
}

// ==================== PARTICLES UPDATE ====================
function updateParticles(dt) {
    for (let i = GAME.particles.length - 1; i >= 0; i--) {
        const p = GAME.particles[i];
        p.userData.life -= dt;

        if (p.userData.life <= 0) {
            GAME.scene.remove(p);
            GAME.particles.splice(i, 1);
            continue;
        }

        p.position.add(p.userData.velocity.clone().multiplyScalar(dt));
        p.userData.velocity.y -= 9.8 * dt;
        p.material.opacity = p.userData.life;
        p.material.transparent = true;
    }
}

// ==================== INPUT HANDLING ====================
function setupInput() {
    document.addEventListener('keydown', (e) => {
        switch(e.code) {
            case 'KeyW': GAME.moveForward = true; break;
            case 'KeyS': GAME.moveBackward = true; break;
            case 'KeyA': GAME.moveLeft = true; break;
            case 'KeyD': GAME.moveRight = true; break;
            case 'ShiftLeft': GAME.isSprinting = true; break;
            case 'Space':
                e.preventDefault();
                GAME.isJumping = true;
                break;
            case 'KeyR': reload(); break;
            case 'KeyF': pickupLoot(); break;
            case 'Digit1':
                GAME.currentWeapon = 'rifle';
                GAME.isScoped = false;
                GAME.camera.fov = 70;
                GAME.camera.updateProjectionMatrix();
                updateHUD();
                break;
            case 'Digit2':
                GAME.currentWeapon = 'shotgun';
                GAME.isScoped = false;
                GAME.camera.fov = 70;
                GAME.camera.updateProjectionMatrix();
                updateHUD();
                break;
            case 'Digit3':
                GAME.currentWeapon = 'sniper';
                break;
            case 'Mouse0':
                if (GAME.currentWeapon === 'sniper') {
                    GAME.isScoped = !GAME.isScoped;
                    GAME.camera.fov = GAME.isScoped ? 30 : 70;
                    GAME.camera.updateProjectionMatrix();
                }
                break;
        }
    });

    document.addEventListener('keyup', (e) => {
        switch(e.code) {
            case 'KeyW': GAME.moveForward = false; break;
            case 'KeyS': GAME.moveBackward = false; break;
            case 'KeyA': GAME.moveLeft = false; break;
            case 'KeyD': GAME.moveRight = false; break;
            case 'ShiftLeft': GAME.isSprinting = false; break;
            case 'Space': GAME.isJumping = false; break;
        }
    });

    document.addEventListener('mousedown', (e) => {
        if (e.button === 0) {
            GAME.mouseDown = true;
            if (GAME.currentWeapon === 'sniper' && GAME.isScoped) {
                shoot();
            } else if (GAME.currentWeapon !== 'sniper') {
                shoot();
            }
        }
    });

    document.addEventListener('mouseup', (e) => {
        if (e.button === 0) {
            GAME.mouseDown = false;
            if (GAME.currentWeapon === 'sniper' && GAME.isScoped) {
                // Stop auto fire for sniper when scoped
            }
        }
    });

    document.addEventListener('mousemove', (e) => {
        if (!GAME.gameStarted) return;

        GAME.yaw -= e.movementX * GAME.sensitivity;
        GAME.pitch -= e.movementY * GAME.sensitivity;
        GAME.pitch = Math.max(-Math.PI/2 + 0.1, Math.min(Math.PI/2 - 0.1, GAME.pitch));
    });

    document.addEventListener('wheel', (e) => {
        if (!GAME.gameStarted) return;
        // Zoom for sniper
        if (GAME.currentWeapon === 'sniper') {
            GAME.camera.fov = Math.max(15, Math.min(70, GAME.camera.fov + e.deltaY * 0.05));
            GAME.camera.updateProjectionMatrix();
        }
    });

    document.addEventListener('pointerlockchange', () => {
        if (!document.pointerLockElement && GAME.gameStarted && !GAME.gameOver) {
            document.getElementById('blocker').style.display = 'flex';
        }
    });
}

