    // Hemisphere
    const hemi = new THREE.HemisphereLight(0x87CEEB, 0x3a7d32, 0.6);
    GAME.scene.add(hemi);

    // Sun
    const sun = new THREE.DirectionalLight(0xffeedd, 1.2);
    sun.position.set(200, 300, 100);
    sun.castShadow = true;
    sun.shadow.mapSize.width = 2048;
    sun.shadow.mapSize.height = 2048;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 800;
    sun.shadow.camera.left = -300;
    sun.shadow.camera.right = 300;
    sun.shadow.camera.top = 300;
    sun.shadow.camera.bottom = -300;
    sun.shadow.bias = -0.001;
    GAME.scene.add(sun);

    // Fog
    GAME.scene.fog = new THREE.FogExp2(0x88bbee, 0.0008);
}

function createSky() {
    const skyGeo = new THREE.SphereGeometry(1500, 32, 32);
    const skyMat = new THREE.ShaderMaterial({
        uniforms: {
            topColor: { value: new THREE.Color(0x0077ff) },
            bottomColor: { value: new THREE.Color(0x88bbee) },
            offset: { value: 20 },
            exponent: { value: 0.6 }
        },
        vertexShader: `
            varying vec3 vWorldPosition;
            void main() {
                vec4 worldPosition = modelMatrix * vec4(position, 1.0);
                vWorldPosition = worldPosition.xyz;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 topColor;
            uniform vec3 bottomColor;
            uniform float offset;
            uniform float exponent;
            varying vec3 vWorldPosition;
            void main() {
                float h = normalize(vWorldPosition + offset).y;
                gl_FragColor = vec4(mix(bottomColor, topColor, max(pow(max(h, 0.0), exponent), 0.0)), 1.0);
            }
        `,
        side: THREE.BackSide
    });

    const sky = new THREE.Mesh(skyGeo, skyMat);
    GAME.scene.add(sky);

    // Sun sphere
    const sunGeo = new THREE.SphereGeometry(20, 16, 16);
    const sunMat = new THREE.MeshBasicMaterial({ color: 0xffffee });
    const sunMesh = new THREE.Mesh(sunGeo, sunMat);
    sunMesh.position.set(200, 300, 100);
    GAME.scene.add(sunMesh);
}

// ==================== GAME INITIALIZATION ====================
function init() {
    // Loading
    const loadFill = document.getElementById('loading-fill');
    let loadProgress = 0;

    const loadInterval = setInterval(() => {
        loadProgress += Math.random() * 15;
        if (loadProgress >= 100) {
            loadProgress = 100;
            clearInterval(loadInterval);

            setTimeout(() => {
                document.getElementById('loading').style.display = 'none';
                setupGame();
            }, 500);
        }
        loadFill.style.width = loadProgress + '%';
    }, 100);
}

function setupGame() {
    // Scene
    GAME.scene = new THREE.Scene();

    // Renderer
    GAME.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    GAME.renderer.setSize(GAME.width, GAME.height);
    GAME.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    GAME.renderer.shadowMap.enabled = true;
    GAME.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    GAME.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    GAME.renderer.toneMappingExposure = 1.0;
    document.body.appendChild(GAME.renderer.domElement);

    // Clock
    GAME.clock = new THREE.Clock();

    // Audio
    audio = new AudioSystem();

    // Lighting
    setupLighting();
    createSky();

    // Terrain
    const terrain = createTerrain();
    GAME.scene.add(terrain);

    // Roads
    const roads = createRoads();
    GAME.scene.add(roads);

    // Water
    const waters = createWater();
    waters.forEach(w => GAME.scene.add(w));

    // Buildings
    const buildingPositions = [
        { x: 50, z: 50, w: 15, d: 12, h: 8 },
        { x: -80, z: 30, w: 10, d: 10, h: 6 },
        { x: 120, z: -60, w: 20, d: 15, h: 10 },
        { x: -150, z: -100, w: 12, d: 12, h: 7 },
        { x: 200, z: 150, w: 18, d: 14, h: 9 },
        { x: -200, z: 200, w: 14, d: 10, h: 8 },
        { x: 300, z: -200, w: 16, d: 16, h: 12 },
        { x: -300, z: -300, w: 12, d: 12, h: 6 },
        { x: 400, z: 300, w: 22, d: 18, h: 14 },
        { x: -400, z: 400, w: 10, d: 10, h: 5 },
        { x: 500, z: -100, w: 15, d: 12, h: 8 },
        { x: -500, z: 100, w: 18, d: 14, h: 10 },
        { x: 100, z: 400, w: 12, d: 10, h: 7 },
        { x: -100, z: -400, w: 14, d: 14, h: 9 },
        { x: 600, z: 500, w: 20, d: 16, h: 11 },
        { x: -600, z: -500, w: 16, d: 12, h: 8 },
    ];

    for (const bp of buildingPositions) {
        const building = createBuilding(bp.x, bp.z, bp.w, bp.d, bp.h);
        GAME.scene.add(building);
        GAME.buildings.push(building);
    }

    // Trees
    for (let i = 0; i < 400; i++) {
        const x = (Math.random() - 0.5) * GAME.mapSize * 0.85;
        const z = (Math.random() - 0.5) * GAME.mapSize * 0.85;

        // Don't place trees on roads
        let onRoad = false;
        if (Math.abs(x % 600) < 15 || Math.abs(z % 600) < 15) onRoad = true;
        if (Math.sqrt(x*x + z*z) > 490 && Math.sqrt(x*x + z*z) < 510) onRoad = true;

        if (!onRoad) {
            const tree = createTree(x, z);
            GAME.scene.add(tree);
            GAME.trees.push(tree);
        }
    }

    // Rocks
    for (let i = 0; i < 150; i++) {
        const x = (Math.random() - 0.5) * GAME.mapSize * 0.85;
        const z = (Math.random() - 0.5) * GAME.mapSize * 0.85;
        const rock = createRock(x, z);
        GAME.scene.add(rock);
        GAME.rocks.push(rock);
    }

    // Environment details
    createEnvironment();

    // Player
    GAME.player = new Player();
    GAME.scene.add(GAME.player.camera);

    // Enemies
    for (let i = 0; i < 49; i++) {
        const enemy = new Enemy(i + 1);
        GAME.enemies.push(enemy);
    }

    // Zone
    createZoneVisual();

    // Loot
    spawnLoot();

    // Input
    setupInput();

    // Resize
    window.addEventListener('resize', () => {
        GAME.width = window.innerWidth;
        GAME.height = window.innerHeight;
        GAME.renderer.setSize(GAME.width, GAME.height);
        GAME.player.camera.aspect = GAME.width / GAME.height;
        GAME.player.camera.updateProjectionMatrix();
    });

    // Game loop
    GAME.gameStarted = true;
    document.getElementById('blocker').style.display = 'none';
    document.getElementById('hud').style.display = 'block';

    animate();
}

// ==================== GAME LOOP ====================
function animate() {
    requestAnimationFrame(animate);

    if (!GAME.gameStarted || GAME.gameOver) return;

    const dt = Math.min(GAME.clock.getDelta(), 0.05);

    // Update player
    GAME.player.update(dt);

    // Update enemies
    for (const enemy of GAME.enemies) {
        enemy.update(dt, GAME.player.camera.position);
    }

    // Bot vs bot
    updateBotCombat(dt);

    // Update zone
    updateZone(dt);

    // Update particles
    updateParticles(dt);

    // Check loot pickup
    checkLootPickup();

    // Update minimap
    updateMinimap();

    // Update HUD
    updateHUD();

    // Render
    GAME.renderer.render(GAME.scene, GAME.player.camera);
}

// ==================== START ====================
document.getElementById('playBtn').addEventListener('click', () => {
    document.body.requestPointerLock();
    audio.ctx.resume();
});

