function initMath(container) {
let score = 0;
let streak = 0;
let timeLeft = 60;
let timer = null;
let currentAnswer = 0;
let difficulty = 'easy';

container.innerHTML = `
<div class="math-container">
<h3 style="margin-bottom:12px">Cool Math Challenge</h3>
<div class="math-level">
<button class="math-level-btn active" onclick="setMathDiff('easy',this)">Easy</button>
