window.setTemplate = function(t, btn) {
currentTemplate = t;
document.querySelectorAll('.template-btn').forEach(b => b.classList.remove('active'));
btn.classList.add('active');
drawTemplate(t);
};

drawTemplate(currentTemplate);

canvas.addEventListener('mousedown', e => { isDrawing = true; paint(e); });
canvas.addEventListener('mousemove', e => { if (isDrawing) paint(e); });
canvas.addEventListener('mouseup', () => isDrawing = false);
canvas.addEventListener('mouseleave', () => isDrawing = false);
canvas.addEventListener('touchstart', e => { e.preventDefault(); isDrawing = true; paintTouch(e); }, { passive: false });
canvas.addEventListener('touchmove', e => { e.preventDefault(); if (isDrawing) paintTouch(e); }, { passive: false });
canvas.addEventListener('touchend', () => isDrawing = false);

function paint(e) {
const rect = canvas.getBoundingClientRect();
const x = (e.clientX - rect.left) * (canvas.width / rect.width);
const y = (e.clientY - rect.top) * (canvas.height / rect.height);
ctx.fillStyle = currentColor;
ctx.beginPath();
ctx.arc(x, y, 8, 0, Math.PI * 2);
ctx.fill();
}

function paintTouch(e) {
const rect = canvas.getBoundingClientRect();
const x = (e.touches[0].clientX - rect.left) * (canvas.width / rect.width);
const y = (e.touches[0].clientY - rect.top) * (canvas.height / rect.height);
ctx.fillStyle = currentColor;
ctx.beginPath();
ctx.arc(x, y, 8, 0, Math.PI * 2);
ctx.fill();
}

window.clearCanvas = function() {
drawTemplate(currentTemplate);
};

window.downloadCanvas = function() {
const link = document.createElement('a');
link.download = 'my-coloring.png';
link.href = canvas.toDataURL();
link.click();
notify('Image saved!', 'success');
};
}

