function initDrawing(container) {
let currentColor = '#000000';
let brushSize = 5;
let isDrawing = false;
let tool = 'brush';

container.innerHTML = `
<div class="drawing-container">
<h3 style="margin-bottom:12px">✏️ Drawing Challenge</h3>
