<button class="drawing-tool" onclick="downloadDrawCanvas()">💾 Save</button>
</div>
<canvas id="drawingCanvas" width="500" height="400"></canvas>
</div>`;

const palette = document.getElementById('drawPalette');
const colors = ['#000000','#FFFFFF','#FF0000','#FF6600','#FFCC00','#33CC00','#0099FF','#6633FF','#FF33CC','#8B4513','#00CED1','#FF69B4'];
colors.forEach(c => {
const swatch = document.createElement('div');
swatch.className = 'color-swatch' + (c === currentColor ? ' active' : '');
swatch.style.background = c;
if (c === '#FFFFFF') swatch.style.border = '3px solid #ccc';
swatch.onclick = () => {
currentColor = c;
document.querySelectorAll('#drawPalette .color-swatch').forEach(s => s.classList.remove('active'));
swatch.classList.add('active');
};
palette.appendChild(swatch);
});

const canvas = document.getElementById('drawingCanvas');
const ctx = canvas.getContext('2d');
ctx.fillStyle = '#fff';
ctx.fillRect(0, 0, canvas.width, canvas.height);
ctx.lineCap = 'round';
ctx.lineJoin = 'round';

let startX, startY;

canvas.addEventListener('mousedown', e => {
isDrawing = true;
const rect = canvas.getBoundingClientRect();
startX = (e.clientX - rect.left) * (canvas.width / rect.width);
startY = (e.clientY - rect.top) * (canvas.height / rect.height);
if (tool === 'line') {
ctx.beginPath();
ctx.moveTo(startX, startY);
}
});
canvas.addEventListener('mousemove', e => {
if (!isDrawing) return;
const rect = canvas.getBoundingClientRect();
const x = (e.clientX - rect.left) * (canvas.width / rect.width);
const y = (e.clientY - rect.top) * (canvas.height / rect.height);
if (tool === 'brush' || tool === 'eraser') {
ctx.beginPath();
ctx.moveTo(startX, startY);
ctx.lineTo(x, y);
ctx.strokeStyle = tool === 'eraser' ? '#fff' : currentColor;
ctx.lineWidth = tool === 'eraser' ? brushSize * 3 : brushSize;
ctx.stroke();
startX = x;
startY = y;
}
});
canvas.addEventListener('mouseup', () => { isDrawing = false; });
canvas.addEventListener('mouseleave', () => isDrawing = false);

canvas.addEventListener('touchstart', e => { e.preventDefault(); isDrawing = true; const rect = canvas.getBoundingClientRect(); startX = (e.touches[0].clientX - rect.left) * (canvas.width / rect.width); startY = (e.touches[0].clientY - rect.top) * (canvas.height / rect.height); }, { passive: false });
canvas.addEventListener('touchmove', e => { e.preventDefault(); if (!isDrawing) return; const rect = canvas.getBoundingClientRect(); const x = (e.touches[0].clientX - rect.left) * (canvas.width / rect.width); const y = (e.touches[0].clientY - rect.top) * (canvas.height / rect.height); ctx.beginPath(); ctx.moveTo(startX, startY); ctx.lineTo(x, y); ctx.strokeStyle = tool === 'eraser' ? '#fff' : currentColor; ctx.lineWidth = tool === 'eraser' ? brushSize * 3 : brushSize; ctx.stroke(); startX = x; startY = y; }, { passive: false });
canvas.addEventListener('touchend', () => isDrawing = false);

window.setTool = function(t, btn) {
tool = t;
document.querySelectorAll('.drawing-tool').forEach(b => b.classList.remove('active'));
btn.classList.add('active');
};
window.clearDrawCanvas = function() {
ctx.fillStyle = '#fff';
ctx.fillRect(0, 0, canvas.width, canvas.height);
};
window.downloadDrawCanvas = function() {
const link = document.createElement('a');
link.download = 'my-drawing.png';
link.href = canvas.toDataURL();
link.click();
notify('Drawing saved!', 'success');
};
}

