function initAuction(container) {
const items = [
{ icon: '👑', name: 'Golden Crown', desc: 'A magnificent crown adorned with jewels', minBid: 50, maxBid: 200 },
{ icon: '🗡️', name: 'Magic Sword', desc: 'A legendary sword with enchanted blade', minBid: 100, maxBid: 400 },
{ icon: '📜', name: 'Ancient Scroll', desc: 'Contains forgotten knowledge and spells', minBid: 30, maxBid: 150 },
{ icon: '💎', name: 'Diamond Gem', desc: 'A rare and sparkling diamond', minBid: 200, maxBid: 800 },
{ icon: '🏺', name: 'Golden Goblet', desc: 'An ornate golden drinking vessel', minBid: 80, maxBid: 300 },
{ icon: '🧪', name: 'Potion of Wisdom', desc: 'Grants temporary knowledge boost', minBid: 60, maxBid: 250 }
];

let currentItem = 0;
let currentBid = 0;
let timeLeft = 15;
let timer = null;
let wonItems = [];
let gold = 500;

function showItem() {
if (currentItem >= items.length) {
container.innerHTML = `
<div class="auction-container">
<h3>🏷️ Auction Complete!</h3>
<p style="margin:16px 0">You won ${wonItems.length} items!</p>
<div class="auction-history">
${wonItems.map(i => `<div class="auction-history-item">${i.icon} ${i.name} - Won for ${i.wonBid}</div>`).join('')}
</div>
<p style="margin-top:16px">Remaining Gold: <strong style="color:var(--gold)">${gold}</strong></p>
<button class="play-btn" onclick="initAuction(document.getElementById('modalBody'))" style="margin-top:16px">🔄 New Auction</button>
</div>`;
return;
}

const item = items[currentItem];
currentBid = item.minBid;
timeLeft = 15;

container.innerHTML = `
<div class="auction-container">
<h3>🏷️ Auction Simulator</h3>
<div class="auction-item">
<div class="auction-item-icon">${item.icon}</div>
<div class="auction-item-name">${item.name}</div>
<div class="auction-item-desc">${item.desc}</div>
<div class="auction-timer" id="auctionTimer">⏱️ ${timeLeft}s</div>
<div class="auction-bid">
<input type="number" id="auctionInput" value="${currentBid}" min="${item.minBid}" step="10">
<button class="play-btn" onclick="placeBid()">💰 Bid</button>
</div>
<div style="margin-top:12px;font-size:.85rem;color:#888">Your Gold: <span style="color:var(--gold)">${gold}</span></div>
</div>
<div class="auction-history" id="auctionHistory"></div>
<button class="play-btn" onclick="initAuction(document.getElementById('modalBody'))" style="margin-top:16px;background:var(--gradient2)">🔄 New Auction</button>
</div>`;

if (timer) clearInterval(timer);
timer = setInterval(() => {
timeLeft--;
const el = document.getElementById('auctionTimer');
if (el) el.textContent = '⏱️ ' + timeLeft + 's';
if (timeLeft <= 0) {
clearInterval(timer);
if (currentBid > 0) {
if (currentBid <= gold) {
wonItems.push({ name: item.name, icon: item.icon, wonBid: currentBid });
gold -= currentBid;
notify('🎉 You won ' + item.name + '!', 'success');
} else {
notify('❌ Not enough gold!', 'error');
}
}
currentItem++;
setTimeout(showItem, 1500);
}
}, 1000);
}

window.placeBid = function() {
const input = document.getElementById('auctionInput');
const bid = parseInt(input.value);
const item = items[currentItem];
if (isNaN(bid) || bid < item.minBid) {
notify('Bid must be at least ' + item.minBid, 'error');
return;
}
if (bid > gold) {
notify('Not enough gold!', 'error');
return;
}
currentBid = bid;
input.value = bid;
notify('Bid placed: ' + bid, 'info');
};

showItem();
}

