<div class="progress-bar" id="progressBar"></div>

<div class="presentation" id="presentation">

  <!-- SLIDE 1: Title -->
  <div class="slide slide-1 active" data-slide="1">
    <div class="title-decoration"></div>
    <div class="title-content">
      <div class="title-badge">Présentation Éducative</div>
      <h1 class="title-main">
        L'Apprentissage du<br>
        <span class="highlight">Français</span> en<br>
        Milieu Rural
      </h1>
      <p class="title-sub">Enjeux, défis et perspectives pour une éducation linguistique inclusive</p>
      <div class="title-meta">
        <div class="title-meta-item">
          <svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
          Éducation & Développement
        </div>
        <div class="title-meta-item">
          <svg viewBox="0 0 24 24"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z"/></svg>
