    platforms.push({ x: 0, y: levelHeight - 40, w: levelWidth, h: 40, type: 'ground' });

    // Walls
    platforms.push({ x: -20, y: 0, w: 20, h: levelHeight, type: 'wall' });
    platforms.push({ x: levelWidth, y: 0, w: 20, h: levelHeight, type: 'wall' });

    const difficulty = Math.min(lvl / 200, 1);

    if (lvl <= 5) {
        // Tutorial levels - simple platforms
        generateSimpleLevel(lvl);
    } else if (lvl <= 30) {
        generateBasicLevel(lvl);
    } else if (lvl <= 80) {
        generateMediumLevel(lvl);
    } else if (lvl <= 150) {
        generateHardLevel(lvl);
    } else {
        generateExpertLevel(lvl);
    }

    // Exit portal
    const exitX = levelWidth - 100;
    const exitY = 100;
    exitPortal = { x: exitX, y: exitY, w: 40, h: 60, active: true, pulse: 0 };
    platforms.push({ x: exitX - 20, y: exitY + 60, w: 80, h: 20, type: 'ground' });

    // Player start
    player.x = 80;
    player.y = levelHeight - 100;
    player.vx = 0;
    player.vy = 0;
    player.onGround = false;
    player.alive = true;
    player.recording = false;
    player.replaying = false;
    player.recordedMoves = [];
    player.replayData = [];
    player.replayIndex = 0;
    player.invincible = 0;
    player.hasDoubleJump = lvl >= 10;
    player.doubleJump = false;

    generateStars();
    generateFog();

    levelTimer = 0;
}

function generateSimpleLevel(lvl) {
    const count = 3 + lvl;
    for (let i = 0; i < count; i++) {
        const px = 200 + i * (levelWidth - 400) / count;
        const py = levelHeight - 100 - Math.random() * 200;
        const pw = 80 + Math.random() * 60;
        platforms.push({ x: px, y: py, w: pw, h: 16, type: 'platform' });
    }
    // Add some spikes for difficulty
    if (lvl > 2) {
        for (let i = 0; i < lvl - 1; i++) {
            hazards.push({
                x: 300 + i * (levelWidth - 600) / (lvl - 1),
                y: levelHeight - 56,
                w: 30, h: 16, type: 'spike'
            });
        }
    }
}

function generateBasicLevel(lvl) {
    const count = 5 + Math.floor(lvl / 3);
    for (let i = 0; i < count; i++) {
        const px = 150 + i * (levelWidth - 300) / count;
        const py = 150 + Math.random() * (levelHeight - 300);
        const pw = 60 + Math.random() * 80;
        platforms.push({ x: px, y: py, w: pw, h: 16, type: 'platform' });
    }
    // Enemies
    const enemyCount = Math.min(Math.floor(lvl / 5), 4);
    for (let i = 0; i < enemyCount; i++) {
        const ep = platforms[Math.floor(Math.random() * platforms.length)];
        if (ep && ep.type === 'platform') {
            enemies.push({
                x: ep.x + ep.w / 2,
                y: ep.y - 24,
                w: 24, h: 24,
                vx: 1,
                hp: 1,
                type: 'walker',
                platform: ep,
                alive: true,
                animTimer: 0
            });
        }
    }
    // Spikes
    if (lvl > 8) {
        const spikeCount = Math.floor(lvl / 8);
        for (let i = 0; i < spikeCount; i++) {
            hazards.push({
                x: 200 + Math.random() * (levelWidth - 400),
                y: levelHeight - 56,
                w: 24 + Math.random() * 24, h: 16, type: 'spike'
            });
        }
    }
    // Collectibles
    const colCount = Math.min(Math.floor(lvl / 4), 5);
    for (let i = 0; i < colCount; i++) {
        collectibles.push({
            x: 200 + Math.random() * (levelWidth - 400),
            y: 100 + Math.random() * (levelHeight - 250),
            w: 12, h: 12,
            collected: false,
            pulse: Math.random() * Math.PI * 2
        });
    }
}

function generateMediumLevel(lvl) {
    const count = 8 + Math.floor(lvl / 4);
    for (let i = 0; i < count; i++) {
        const px = 100 + i * (levelWidth - 200) / count;
        const py = 100 + Math.random() * (levelHeight - 250);
        const pw = 50 + Math.random() * 70;
        const type = Math.random() < 0.2 ? 'moving' : 'platform';
        if (type === 'moving') {
            movingPlatforms.push({
                x: px, y: py, w: pw, h: 16,
                startX: px, startY: py,
                moveX: Math.random() < 0.5 ? 100 : 0,
                moveY: Math.random() < 0.5 ? 80 : 0,
                speed: 0.5 + Math.random() * 1,
                phase: Math.random() * Math.PI * 2,
                type: 'moving'
            });
            platforms.push({ x: px, y: py, w: pw, h: 16, type: 'moving' });
        } else {
            platforms.push({ x: px, y: py, w: pw, h: 16, type: 'platform' });
        }
    }
    // Enemies
    const enemyCount = Math.min(Math.floor(lvl / 4), 6);
    for (let i = 0; i < enemyCount; i++) {
        const ep = platforms[Math.floor(Math.random() * platforms.length)];
        if (ep && ep.type === 'platform') {
            enemies.push({
                x: ep.x + ep.w / 2, y: ep.y - 24,
                w: 24, h: 24, vx: (Math.random() < 0.5 ? 1 : -1) * (1 + lvl * 0.01),
                hp: 1, type: 'walker', platform: ep, alive: true, animTimer: 0
            });
        }
    }
    // Spikes
    const spikeCount = Math.floor(lvl / 5);
    for (let i = 0; i < spikeCount; i++) {
        hazards.push({
            x: 150 + Math.random() * (levelWidth - 300),
            y: levelHeight - 56,
            w: 20 + Math.random() * 30, h: 16, type: 'spike'
        });
    }
    // Collectibles
    const colCount = Math.min(Math.floor(lvl / 3), 6);
    for (let i = 0; i < colCount; i++) {
        collectibles.push({
            x: 150 + Math.random() * (levelWidth - 300),
            y: 80 + Math.random() * (levelHeight - 230),
            w: 12, h: 12, collected: false,
            pulse: Math.random() * Math.PI * 2
        });
    }
    // Switches
    if (lvl > 20) {
        switches.push({
            x: 300 + Math.random() * (levelWidth - 600),
            y: levelHeight - 60,
            w: 20, h: 20, pressed: false,
            targetDoor: null
        });
        doors.push({
            x: switches[0].x + 200,
            y: levelHeight - 100,
            w: 20, h: 40, open: false
        });
        platforms.push({ x: switches[0].x + 200, y: levelHeight - 100, w: 20, h: 40, type: 'door' });
    }
}

function generateHardLevel(lvl) {
    const count = 10 + Math.floor(lvl / 3);
    for (let i = 0; i < count; i++) {
        const px = 80 + i * (levelWidth - 160) / count;
        const py = 80 + Math.random() * (levelHeight - 220);
        const pw = 40 + Math.random() * 60;
        const type = Math.random() < 0.3 ? 'moving' : (Math.random() < 0.15 ? 'crumble' : 'platform');
        const plat = { x: px, y: py, w: pw, h: 16, type: type };
        if (type === 'crumble') {
            plat.crumbleTimer = 0;
            plat.crumbling = false;
            plat.visible = true;
        }
        if (type === 'moving') {
            plat.startX = px;
            plat.startY = py;
            plat.moveX = Math.random() < 0.5 ? 80 + Math.random() * 80 : 0;
            plat.moveY = Math.random() < 0.5 ? 60 + Math.random() * 60 : 0;
            plat.speed = 0.8 + Math.random() * 1.2;
            plat.phase = Math.random() * Math.PI * 2;
        }
        platforms.push(plat);
    }
    // Enemies - more aggressive
    const enemyCount = Math.min(Math.floor(lvl / 3), 8);
    for (let i = 0; i < enemyCount; i++) {
        const ep = platforms[Math.floor(Math.random() * platforms.length)];
        if (ep && ep.type !== 'wall') {
            const etype = Math.random() < 0.3 ? 'flyer' : 'walker';
            if (etype === 'flyer') {
                enemies.push({
                    x: ep.x + ep.w / 2, y: ep.y - 60,
                    w: 24, h: 24, vx: 1.5,
                    hp: 1, type: 'flyer',
                    baseY: ep.y - 60,
                    alive: true, animTimer: 0, phase: Math.random() * Math.PI * 2
                });
            } else {
                enemies.push({
                    x: ep.x + ep.w / 2, y: ep.y - 24,
                    w: 24, h: 24, vx: (Math.random() < 0.5 ? 1 : -1) * (1.5 + lvl * 0.01),
                    hp: 1, type: 'walker', platform: ep, alive: true, animTimer: 0
                });
            }
        }
    }
    // Hazards
    const spikeCount = Math.floor(lvl / 4);
    for (let i = 0; i < spikeCount; i++) {
        hazards.push({
            x: 100 + Math.random() * (levelWidth - 200),
            y: levelHeight - 56,
            w: 16 + Math.random() * 40, h: 16, type: 'spike'
        });
    }
    // Lava pits
    if (lvl > 40) {
        const lavaCount = Math.floor(lvl / 20);
        for (let i = 0; i < lavaCount; i++) {
            const lx = 200 + i * (levelWidth - 400) / lavaCount;
            hazards.push({
                x: lx, y: levelHeight - 30,
                w: 60 + Math.random() * 40, h: 30, type: 'lava'
            });
            platforms.push({ x: lx + 60 + Math.random() * 40, y: levelHeight - 30, w: 60, h: 30, type: 'ground' });
        }
    }
    // Collectibles
    const colCount = Math.min(Math.floor(lvl / 3), 8);
    for (let i = 0; i < colCount; i++) {
        collectibles.push({
            x: 100 + Math.random() * (levelWidth - 200),
            y: 60 + Math.random() * (levelHeight - 200),
            w: 12, h: 12, collected: false,
            pulse: Math.random() * Math.PI * 2
        });
    }
    // Switches and doors
    if (lvl > 30) {
        const switchCount = Math.min(Math.floor(lvl / 20), 3);
        for (let i = 0; i < switchCount; i++) {
            switches.push({
                x: 200 + i * 300 + Math.random() * 100,
                y: levelHeight - 60,
                w: 20, h: 20, pressed: false,
                targetDoor: doors.length
            });
            doors.push({ x: switches[i].x + 150 + Math.random() * 100, y: levelHeight - 100, w: 20, h: 40, open: false });
            platforms.push({ x: switches[i].x + 150 + Math.random() * 100, y: levelHeight - 100, w: 20, h: 40, type: 'door' });
        }
    }
}

function generateExpertLevel(lvl) {
    const count = 12 + Math.floor(lvl / 2);
    for (let i = 0; i < count; i++) {
        const px = 60 + i * (levelWidth - 120) / count;
        const py = 60 + Math.random() * (levelHeight - 200);
        const pw = 30 + Math.random() * 50;
        const r = Math.random();
        let type = 'platform';
        if (r < 0.3) type = 'moving';
        else if (r < 0.5) type = 'crumble';
        const plat = { x: px, y: py, w: pw, h: 16, type: type };
        if (type === 'crumble') {
            plat.crumbleTimer = 0; plat.crumbling = false; plat.visible = true;
        }
        if (type === 'moving') {
            plat.startX = px; plat.startY = py;
            plat.moveX = 60 + Math.random() * 100;
            plat.moveY = 40 + Math.random() * 80;
            plat.speed = 1 + Math.random() * 1.5;
            plat.phase = Math.random() * Math.PI * 2;
        }
