    }
    // Many enemies
    const enemyCount = Math.min(Math.floor(lvl / 2), 10);
    for (let i = 0; i < enemyCount; i++) {
        const ep = platforms[Math.floor(Math.random() * platforms.length)];
        if (ep && ep.type !== 'wall') {
            const etype = Math.random() < 0.5 ? 'flyer' : 'walker';
