                    baseY: ep.y - 50, alive: true, animTimer: 0, phase: Math.random() * Math.PI * 2
                });
            } else {
                enemies.push({
                    x: ep.x + ep.w / 2, y: ep.y - 24,
                    w: 24, h: 24, vx: (Math.random() < 0.5 ? 1 : -1) * (2 + lvl * 0.01),
                    hp: 1, type: 'walker', platform: ep, alive: true, animTimer: 0
                });
            }
        }
    }
    // Many hazards
    const spikeCount = Math.floor(lvl / 3);
    for (let i = 0; i < spikeCount; i++) {
        hazards.push({
            x: 80 + Math.random() * (levelWidth - 160),
            y: levelHeight - 56,
            w: 12 + Math.random() * 48, h: 16, type: 'spike'
        });
    }
    // Lava
    const lavaCount = Math.floor(lvl / 15);
    for (let i = 0; i < lavaCount; i++) {
        const lx = 150 + i * (levelWidth - 300) / lavaCount;
