            y: levelHeight - 60,
            w: 20, h: 20, pressed: false,
            targetDoor: doors.length
        });
        doors.push({ x: switches[i].x + 120 + Math.random() * 80, y: levelHeight - 100, w: 20, h: 40, open: false });
        platforms.push({ x: switches[i].x + 120 + Math.random() * 80, y: levelHeight - 100, w: 20, h: 40, type: 'door' });
