}

// Particle system
function spawnParticles(x, y, color, count, speed, life) {
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * speed;
        particles.push({
            x, y,
            vx: Math.cos(angle) * spd,
            vy: Math.sin(angle) * spd,
            life: life || 30 + Math.random() * 20,
            maxLife: life || 30 + Math.random() * 20,
            color: color || '#0ff',
            size: Math.random() * 3 + 1
        });
    }
}

// Collision detection
function rectCollide(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function pointInRect(px, py, r) {
    return px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h;
}

// Update physics
function updatePlayer(dt) {
    if (!player.alive) return;

    const gravity = 0.6;
    const moveSpeed = 4;
    const jumpForce = -12;
    const friction = 0.85;

    // Input
    let moveX = 0;
    if (keys['ArrowLeft'] || keys['KeyA']) moveX = -1;
    if (keys['ArrowRight'] || keys['KeyD']) moveX = 1;

    // Crouch
    player.crouching = (keys['ArrowDown'] || keys['KeyS']) && player.onGround;
    const currentH = player.crouching ? 16 : 32;

    if (!player.replaying) {
        player.vx += moveX * 0.8;
        player.vx *= friction;
        if (Math.abs(player.vx) > moveSpeed) player.vx = moveSpeed * Math.sign(player.vx);
        if (Math.abs(player.vx) < 0.1) player.vx = 0;

        if (moveX !== 0) player.facing = moveX;

        // Jump
        if ((keys['Space'] || keys['ArrowUp'] || keys['KeyW']) && !player.jumping) {
            if (player.onGround) {
                player.vy = jumpForce;
                player.onGround = false;
                player.jumping = true;
                player.doubleJump = false;
                playSound('jump');
                spawnParticles(player.x + player.w / 2, player.y + player.h, '#0ff', 5, 2, 15);
            } else if (player.hasDoubleJump && !player.doubleJump) {
                player.vy = jumpForce * 0.8;
                player.doubleJump = true;
                playSound('jump');
                spawnParticles(player.x + player.w / 2, player.y + player.h, '#88f', 8, 3, 20);
            }
        }
        if (!(keys['Space'] || keys['ArrowUp'] || keys['KeyW'])) {
            player.jumping = false;
            if (player.vy < -3) player.vy *= 0.9;
        }

        // Record movement
        if (player.recording) {
            player.recordedMoves.push({
                x: player.x, y: player.y,
                vx: player.vx, vy: player.vy,
                facing: player.facing,
                crouching: player.crouching,
                onGround: player.onGround,
                jumping: player.jumping,
                doubleJump: player.doubleJump
            });
        }

        // Record replay trigger
        if (keys['KeyT'] && player.recordedMoves.length > 0 && !player.replaying) {
            player.replaying = true;
            player.replayData = [...player.recordedMoves];
            player.replayIndex = 0;
            playSound('replay');
            spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#f0f', 15, 4, 25);
        }
    }

    // Replay shadow
    if (player.replaying && player.replayIndex < player.replayData.length) {
        const move = player.replayData[player.replayIndex];
        player.x = move.x;
        player.y = move.y;
        player.vx = move.vx;
        player.vy = move.vy;
        player.facing = move.facing;
        player.crouching = move.crouching;
        player.onGround = move.onGround;
        player.jumping = move.jumping;
        player.doubleJump = move.doubleJump;
        player.replayIndex++;
    }

    // Apply gravity
    player.vy += gravity;
    if (player.vy > 15) player.vy = 15;

    // Move X
    player.x += player.vx;

    // Collision X
    for (const p of platforms) {
        if (p.type === 'door' && doors.find(d => d === p) && doors.find(d => d === p).open) continue;
        if (p.type === 'crumble' && !p.visible) continue;
        if (rectCollide(player, p)) {
            if (player.vx > 0) player.x = p.x - player.w;
            else if (player.vx < 0) player.x = p.x + p.w;
            player.vx = 0;
        }
    }

    // Move Y
    player.y += player.vy;
    player.onGround = false;

    // Collision Y
    for (const p of platforms) {
        if (p.type === 'door' && doors.find(d => d === p) && doors.find(d => d === p).open) continue;
        if (p.type === 'crumble' && !p.visible) continue;
        if (rectCollide(player, p)) {
            if (player.vy > 0) {
                player.y = p.y - player.h;
                player.vy = 0;
                player.onGround = true;
                player.doubleJump = false;
                if (player.vy > 5) {
                    playSound('land');
                    spawnParticles(player.x + player.w / 2, player.y + player.h, '#0ff', 3, 2, 10);
                }
                // Moving platform carry
                if (p.type === 'moving' && p.startX !== undefined) {
                    player.x += Math.cos(p.phase) * p.moveX * p.speed * 0.02;
                }
            } else if (player.vy < 0) {
                player.y = p.y + p.h;
                player.vy = 0;
            }
        }
    }

    // Moving platforms update
    for (const mp of platforms.filter(p => p.type === 'moving')) {
        mp.phase += mp.speed * 0.02;
        mp.x = mp.startX + Math.sin(mp.phase) * mp.moveX;
        mp.y = mp.startY + Math.sin(mp.phase * 0.7) * mp.moveY;
    }

    // Crumble platforms
    for (const cp of platforms.filter(p => p.type === 'crumble')) {
        if (cp.crumbling) {
            cp.crumbleTimer++;
            if (cp.crumbleTimer > 30) {
                cp.visible = false;
                spawnParticles(cp.x + cp.w / 2, cp.y + cp.h / 2, '#884', 8, 3, 20);
            }
        }
        if (player.onGround && player.y + player.h >= cp.y && player.y + player.h <= cp.y + 8 &&
            player.x + player.w > cp.x && player.x < cp.x + cp.w) {
            if (!cp.crumbling) cp.crumbling = true;
        }
    }

    // Enemies update
    for (const e of enemies) {
        if (!e.alive) continue;
        e.animTimer += 0.1;
        if (e.type === 'walker' && e.platform) {
            e.x += e.vx;
            if (e.x <= e.platform.x || e.x + e.w >= e.platform.x + e.platform.w) {
                e.vx *= -1;
            }
        } else if (e.type === 'flyer') {
            e.x += e.vx;
            e.y = e.baseY + Math.sin(e.animTimer + e.phase) * 30;
            if (e.x < 0 || e.x > levelWidth) e.vx *= -1;
        }

        // Player collision with enemy
        if (player.alive && rectCollide(player, e)) {
            if (player.vy > 0 && player.y + player.h - 8 < e.y + e.h / 2) {
                // Stomp
                e.hp--;
                player.vy = -8;
                playSound('enemyDie');
                spawnParticles(e.x + e.w / 2, e.y + e.h / 2, '#f44', 10, 4, 25);
                if (e.hp <= 0) {
                    e.alive = false;
                    spawnParticles(e.x + e.w / 2, e.y + e.h / 2, '#f88', 15, 5, 30);
                }
            } else if (player.invincible <= 0) {
                killPlayer();
            }
        }
    }

    // Hazards
    for (const h of hazards) {
        if (rectCollide(player, h)) {
            if (h.type === 'spike' || h.type === 'lava') {
                killPlayer();
            }
        }
    }

    // Collectibles
    for (const c of collectibles) {
        if (c.collected) continue;
        c.pulse += 0.05;
        if (rectCollide(player, { x: c.x - 4, y: c.y - 4, w: c.w + 8, h: c.h + 8 })) {
            c.collected = true;
            playSound('portal');
            spawnParticles(c.x + c.w / 2, c.y + c.h / 2, '#ff0', 10, 3, 20);
        }
    }

    // Switches
    for (const s of switches) {
        if (rectCollide(player, s)) {
            s.pressed = true;
            playSound('switch');
            spawnParticles(s.x + s.w / 2, s.y + s.h / 2, '#0f0', 10, 3, 20);
            if (s.targetDoor !== null && doors[s.targetDoor]) {
                doors[s.targetDoor].open = true;
            }
        }
    }

    // Exit portal
    if (exitPortal && rectCollide(player, exitPortal)) {
        winLevel();
    }

    // Fall death
    if (player.y > levelHeight + 100) {
        killPlayer();
    }

    // Trail
    player.trail.push({ x: player.x + player.w / 2, y: player.y + player.h / 2, alpha: 1 });
    if (player.trail.length > 15) player.trail.shift();
    player.trail.forEach(t => t.alpha -= 0.07);

    // Invincibility
    if (player.invincible > 0) player.invincible--;

    // Glow
    player.glowIntensity = Math.max(0, player.glowIntensity - 0.02);
    if (player.recording) player.glowIntensity = Math.min(1, player.glowIntensity + 0.05);

    // Step sound
    if (player.onGround && Math.abs(player.vx) > 1) {
        if (Math.random() < 0.1) playSound('step');
    }

    // Animation
    player.animTimer += Math.abs(player.vx) * 0.1;
    player.animFrame = Math.floor(player.animTimer) % 4;
}

function killPlayer() {
    if (player.invincible > 0) return;
    player.alive = false;
    deaths++;
    playSound('death');
    spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#f44', 20, 5, 30);
    setTimeout(() => {
        document.getElementById('deathScreen').style.display = 'flex';
    }, 500);
}

function winLevel() {
    if (gameState !== 'playing') return;
    gameState = 'win';
    playSound('win');
    completedLevels.add(currentLevel);
    if (currentLevel >= unlockedLevel) unlockedLevel = currentLevel + 1;
    document.getElementById('winText').textContent = `Level ${currentLevel} complete! Deaths: ${deaths}`;
    document.getElementById('winScreen').style.display = 'flex';
}

function nextLevel() {
    document.getElementById('winScreen').style.display = 'none';
    currentLevel++;
    if (currentLevel > 200) currentLevel = 200;
    loadLevel(currentLevel);
}

function retryLevel() {
    document.getElementById('deathScreen').style.display = 'none';
    loadLevel(currentLevel);
}

function loadLevel(lvl) {
    currentLevel = lvl;
    gameState = 'playing';
    document.getElementById('deathScreen').style.display = 'none';
    document.getElementById('winScreen').style.display = 'none';
    generateLevel(lvl);
    updateHUD();
}

function updateHUD() {
    document.getElementById('hudLevel').textContent = `Level ${currentLevel}`;
    document.getElementById('hudDeaths').textContent = `Deaths: ${deaths}`;
    document.getElementById('hudClones').textContent = `Clones: ${shadows.length}`;
    document.getElementById('hudTimer').textContent = `Time: ${Math.floor(levelTimer)}s`;
}

// Camera
function updateCamera() {
    const targetX = player.x - W / 2 + player.w / 2;
    const targetY = player.y - H / 2 + player.h / 2;
    camera.x += (targetX - camera.x) * 0.08;
    camera.y += (targetY - camera.y) * 0.08;
    camera.x = Math.max(0, Math.min(camera.x, levelWidth - W));
    camera.y = Math.max(0, Math.min(camera.y, levelHeight - H));
}

// Drawing
function draw() {
    ctx.fillStyle = '#050510';
    ctx.fillRect(0, 0, W, H);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    // Background gradient
    const grad = ctx.createLinearGradient(camera.x, camera.y, camera.x, camera.y + H);
    grad.addColorStop(0, '#0a0a2e');
    grad.addColorStop(0.5, '#050515');
    grad.addColorStop(1, '#020208');
    ctx.fillStyle = grad;
    ctx.fillRect(camera.x, camera.y, W, H);

    // Stars
    for (const s of bgStars) {
        const twinkle = Math.sin(levelTimer * s.twinkleSpeed * 60) * 0.3 + 0.7;
        ctx.fillStyle = `rgba(200, 220, 255, ${s.alpha * twinkle})`;
        ctx.fillRect(s.x, s.y, s.size, s.size);
    }

    // Fog
    for (const f of fogParticles) {
        f.drift += 0.003;
        f.x += f.speed;
        if (f.x > levelWidth + 100) f.x = -100;
        const fogGrad = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.size);
        fogGrad.addColorStop(0, `rgba(100, 120, 180, ${f.alpha})`);
        fogGrad.addColorStop(1, 'rgba(100, 120, 180, 0)');
        ctx.fillStyle = fogGrad;
        ctx.fillRect(f.x - f.size, f.y - f.size, f.size * 2, f.size * 2);
    }

    // Platforms
    for (const p of platforms) {
        if (p.type === 'door' && doors.find(d => d === p) && doors.find(d => d === p).open) continue;
        if (p.type === 'crumble' && !p.visible) continue;

        if (p.x + p.w < camera.x - 50 || p.x > camera.x + W + 50) continue;
        if (p.y + p.h < camera.y - 50 || p.y > camera.y + H + 50) continue;

        if (p.type === 'ground') {
            const grd = ctx.createLinearGradient(p.x, p.y, p.x, p.y + p.h);
            grd.addColorStop(0, '#1a1a3a');
            grd.addColorStop(1, '#0a0a1a');
            ctx.fillStyle = grd;
            ctx.fillRect(p.x, p.y, p.w, p.h);
            ctx.strokeStyle = '#2a2a5a';
            ctx.lineWidth = 1;
            ctx.strokeRect(p.x, p.y, p.w, p.h);
        } else if (p.type === 'moving') {
            ctx.shadowColor = '#0ff';
            ctx.shadowBlur = 10;
            ctx.fillStyle = '#0a2a3a';
            ctx.fillRect(p.x, p.y, p.w, p.h);
            ctx.strokeStyle = '#0ff';
            ctx.lineWidth = 1;
            ctx.strokeRect(p.x, p.y, p.w, p.h);
            ctx.shadowBlur = 0;
        } else if (p.type === 'crumble') {
            const shake = p.crumbling ? Math.sin(p.crumbleTimer * 2) * 2 : 0;
            ctx.fillStyle = p.crumbling ? `rgba(100, 80, 40, ${1 - p.crumbleTimer / 30})` : '#2a1a0a';
            ctx.fillRect(p.x + shake, p.y, p.w, p.h);
            ctx.strokeStyle = '#4a3a1a';
            ctx.lineWidth = 1;
            ctx.strokeRect(p.x + shake, p.y, p.w, p.h);
        } else {
            ctx.fillStyle = '#151530';
            ctx.fillRect(p.x, p.y, p.w, p.h);
            ctx.strokeStyle = '#252550';
            ctx.lineWidth = 1;
            ctx.strokeRect(p.x, p.y, p.w, p.h);
        }
    }

    // Hazards
    for (const h of hazards) {
        if (h.type === 'spike') {
            ctx.fillStyle = '#f44';
            ctx.shadowColor = '#f44';
            ctx.shadowBlur = 8;
            const spikeCount = Math.floor(h.w / 10);
            for (let i = 0; i < spikeCount; i++) {
                ctx.beginPath();
                ctx.moveTo(h.x + i * 10, h.y + h.h);
                ctx.lineTo(h.x + i * 10 + 5, h.y);
                ctx.lineTo(h.x + i * 10 + 10, h.y + h.h);
                ctx.fill();
            }
            ctx.shadowBlur = 0;
        } else if (h.type === 'lava') {
            ctx.fillStyle = '#f80';
            ctx.shadowColor = '#f80';
            ctx.shadowBlur = 15;
            ctx.fillRect(h.x, h.y, h.w, h.h);
            // Lava bubbles
            for (let i = 0; i < 3; i++) {
                const bx = h.x + Math.sin(levelTimer * 2 + i) * h.w * 0.3 + h.w * 0.5;
                const by = h.y + Math.sin(levelTimer * 3 + i * 2) * 5;
                ctx.fillStyle = '#ff0';
                ctx.beginPath();
                ctx.arc(bx, by, 3, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.shadowBlur = 0;
        }
    }

    // Collectibles
    for (const c of collectibles) {
        if (c.collected) continue;
        const pulse = Math.sin(c.pulse) * 0.3 + 0.7;
        ctx.shadowColor = '#ff0';
        ctx.shadowBlur = 15 * pulse;
        ctx.fillStyle = `rgba(255, 255, 0, ${pulse})`;
        ctx.beginPath();
        ctx.arc(c.x + c.w / 2, c.y + c.h / 2, c.w / 2 + Math.sin(c.pulse) * 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;
    }

    // Switches
    for (const s of switches) {
        ctx.fillStyle = s.pressed ? '#0f0' : '#f80';
        ctx.shadowColor = s.pressed ? '#0f0' : '#f80';
        ctx.shadowBlur = 10;
        ctx.fillRect(s.x, s.y, s.w, s.h);
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#000';
        ctx.font = '10px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(s.pressed ? 'ON' : 'OFF', s.x + s.w / 2, s.y + s.h / 2 + 4);
    }

    // Doors
    for (const d of doors) {
        if (d.open) continue;
        ctx.fillStyle = '#444';
        ctx.fillRect(d.x, d.y, d.w, d.h);
        ctx.strokeStyle = '#888';
        ctx.lineWidth = 1;
        ctx.strokeRect(d.x, d.y, d.w, d.h);
    }

    // Exit portal
    if (exitPortal) {
        exitPortal.pulse += 0.05;
        const pulse = Math.sin(exitPortal.pulse) * 0.3 + 0.7;
        ctx.shadowColor = '#0ff';
        ctx.shadowBlur = 20 * pulse;
        const portalGrad = ctx.createRadialGradient(
            exitPortal.x + exitPortal.w / 2, exitPortal.y + exitPortal.h / 2, 0,
            exitPortal.x + exitPortal.w / 2, exitPortal.y + exitPortal.h / 2, 30
        );
        portalGrad.addColorStop(0, `rgba(0, 255, 255, ${pulse})`);
        portalGrad.addColorStop(0.5, `rgba(0, 150, 255, ${pulse * 0.5})`);
        portalGrad.addColorStop(1, 'rgba(0, 100, 255, 0)');
        ctx.fillStyle = portalGrad;
        ctx.fillRect(exitPortal.x - 10, exitPortal.y - 10, exitPortal.w + 20, exitPortal.h + 20);
        ctx.shadowBlur = 0;
    }

    // Shadows (clones)
    for (const s of shadows) {
        if (!s.alive) continue;
        const alpha = s.life / s.maxLife;
        ctx.globalAlpha = alpha * 0.6;
        ctx.fillStyle = '#f0f';
        ctx.shadowColor = '#f0f';
        ctx.shadowBlur = 10;
        drawCharacter(s.x, s.y, s.w, s.h, s.facing, s.animFrame, '#f0f');
        ctx.shadowBlur = 0;
        ctx.globalAlpha = 1;
    }

    // Player trail
    for (let i = 0; i < player.trail.length; i++) {
        const t = player.trail[i];
        if (t.alpha <= 0) continue;
        ctx.globalAlpha = t.alpha * 0.3;
        ctx.fillStyle = player.recording ? '#f0f' : '#0ff';
        ctx.beginPath();
        ctx.arc(t.x, t.y, 3, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Enemies
    for (const e of enemies) {
        if (!e.alive) continue;
        ctx.fillStyle = '#f44';
        ctx.shadowColor = '#f44';
        ctx.shadowBlur = 8;
        drawCharacter(e.x, e.y, e.w, e.h, e.vx > 0 ? 1 : -1, Math.floor(e.animTimer) % 4, '#f44');
        ctx.shadowBlur = 0;
    }

    // Player
    if (player.alive) {
        const blink = player.invincible > 0 && Math.floor(player.invincible / 3) % 2;
        if (!blink) {
            const glow = player.recording ? '#f0f' : '#0ff';
            ctx.shadowColor = glow;
            ctx.shadowBlur = 15 + player.glowIntensity * 10;
            drawCharacter(player.x, player.y, player.w, player.h, player.facing, player.animFrame, glow);
            ctx.shadowBlur = 0;
        }
    }

    // Particles
    for (const p of particles) {
        const alpha = p.life / p.maxLife;
        ctx.globalAlpha = alpha;
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
    }
    ctx.globalAlpha = 1;

    ctx.restore();

    // Recording indicator
    if (player.recording) {
        ctx.fillStyle = 'rgba(255, 0, 255, 0.1)';
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = '#f0f';
        ctx.font = '16px monospace';
        ctx.textAlign = 'center';
        ctx.shadowColor = '#f0f';
        ctx.shadowBlur = 10;
        ctx.fillText('● RECORDING - Press T to replay', W / 2, 40);
        ctx.shadowBlur = 0;
    }

    // Pause screen
    if (gameState === 'paused') {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = '#0ff';
        ctx.font = '36px monospace';
        ctx.textAlign = 'center';
        ctx.shadowColor = '#0ff';
        ctx.shadowBlur = 20;
        ctx.fillText('PAUSED', W / 2, H / 2);
        ctx.shadowBlur = 0;
        ctx.font = '16px monospace';
        ctx.fillStyle = '#888';
        ctx.fillText('Press P to resume', W / 2, H / 2 + 40);
    }
}

function drawCharacter(x, y, w, h, facing, frame, color) {
    ctx.fillStyle = color;

    // Body
    const bodyH = h;
    ctx.fillRect(x + w / 2 - 4, y + 4, 8, bodyH - 12);

    // Head
    ctx.fillRect(x + w / 2 - 5, y, 10, 10);

    // Eyes
    ctx.fillStyle = '#fff';
    const eyeX = facing > 0 ? x + w / 2 + 1 : x + w / 2 - 5;
    ctx.fillRect(eyeX, y + 3, 3, 3);

    // Legs animation
    const legOffset = Math.sin(frame * Math.PI / 2) * 3;
    ctx.fillStyle = color;
    ctx.fillRect(x + w / 2 - 4, y + bodyH - 8, 3, 8 + legOffset);
    ctx.fillRect(x + w / 2 + 1, y + bodyH - 8, 3, 8 - legOffset);

    // Arms
    const armOffset = Math.sin(frame * Math.PI / 2) * 4;
    ctx.fillRect(x + w / 2 - 8, y + 8 + armOffset, 4, 8);
    ctx.fillRect(x + w / 2 + 4, y + 8 - armOffset, 4, 8);

    // Glow effect
    ctx.shadowColor = color;
    ctx.shadowBlur = 5;
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.fillRect(x + w / 2 - 2, y + 2, 4, 4);
    ctx.shadowBlur = 0;
}

// Update particles
function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.05;
        p.life--;
        if (p.life <= 0) particles.splice(i, 1);
    }
}

// Update shadows
function updateShadows() {
    for (let i = shadows.length - 1; i >= 0; i--) {
        const s = shadows[i];
        s.life--;
        if (s.life <= 0) {
            shadows.splice(i, 1);
        }
    }
}

// Create shadow clone
function createShadowClone() {
    if (player.recordedMoves.length < 2) return;
    shadows.push({
        x: player.x,
        y: player.y,
        w: player.w,
        h: player.h,
        vx: player.vx,
        vy: player.vy,
        facing: player.facing,
        animFrame: player.animFrame,
        life: player.recordedMoves.length,
        maxLife: player.recordedMoves.length,
        alive: true,
        moves: [...player.recordedMoves],
        moveIndex: 0
    });
    player.replaying = true;
    player.replayData = player.recordedMoves;
    player.replayIndex = 0;
    player.recordedMoves = [];
    playSound('replay');
    spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#f0f', 20, 5, 30);
}

// Game loop
let lastTime = 0;
let frameCount = 0;

function gameLoop(timestamp) {
    const dt = Math.min((timestamp - lastTime) / 1000, 0.05);
    lastTime = timestamp;
    frameCount++;

    if (gameState === 'playing') {
        levelTimer += dt;

        // Record trigger
        if (keys['KeyR'] && !player.recording && !player.replaying) {
            player.recording = true;
            player.recordedMoves = [];
            playSound('record');
        }
        if (keys['KeyR'] && player.recording) {
            player.recording = false;
            if (player.recordedMoves.length > 0) {
                createShadowClone();
            }
        }

        updatePlayer(dt);
        updateCamera();
        updateParticles();
        updateShadows();

        // Update shadow clones
        for (const s of shadows) {
            if (s.moveIndex < s.moves.length) {
                const m = s.moves[s.moveIndex];
                s.x = m.x;
                s.y = m.y;
                s.vx = m.vx;
                s.vy = m.vy;
                s.facing = m.facing;
                s.animFrame = Math.floor(s.moveIndex / 3) % 4;
                s.moveIndex++;
            }
        }

        if (frameCount % 10 === 0) updateHUD();
    }

    draw();
    requestAnimationFrame(gameLoop);
}

// UI Functions
function startGame() {
    initAudio();
    document.getElementById('titleScreen').style.display = 'none';
    loadLevel(1);
    startMusic();
}

function showLevelSelect() {
    initAudio();
    document.getElementById('titleScreen').style.display = 'none';
    document.getElementById('levelSelect').style.display = 'flex';
    document.getElementById('deathScreen').style.display = 'none';
    document.getElementById('winScreen').style.display = 'none';
    buildLevelGrid();
}

function showTitle() {
    document.getElementById('levelSelect').style.display = 'none';
    document.getElementById('titleScreen').style.display = 'flex';
}

let selectedLevel = 1;
function buildLevelGrid() {
    const grid = document.getElementById('levelGrid');
    grid.innerHTML = '';
    for (let i = 1; i <= 200; i++) {
        const btn = document.createElement('button');
        btn.className = 'levelBtn';
        if (completedLevels.has(i)) btn.classList.add('completed');
        if (i === selectedLevel) btn.classList.add('current');
        btn.textContent = i;
        btn.onclick = () => {
            selectedLevel = i;
            document.querySelectorAll('.levelBtn').forEach(b => b.classList.remove('current'));
            btn.classList.add('current');
        };
        grid.appendChild(btn);
    }
}

function startFromGrid() {
    loadLevel(selectedLevel);
    document.getElementById('levelSelect').style.display = 'none';
    startMusic();
}

// Save/Load
function saveProgress() {
    try {
        localStorage.setItem('shadowTime', JSON.stringify({
            completed: [...completedLevels],
            unlocked: unlockedLevel,
            deaths: deaths
        }));
    } catch (e) {}
}

function loadProgress() {
    try {
        const data = JSON.parse(localStorage.getItem('shadowTime'));
        if (data) {
            completedLevels = new Set(data.completed || []);
            unlockedLevel = data.unlocked || 1;
            deaths = data.deaths || 0;
        }
    } catch (e) {}
}

loadProgress();
requestAnimationFrame(gameLoop);
</script>
</body>
