     padding: 2rem;
     background: var(--bg);
     color: var(--text);
     font-family: 'Courier New', Courier, monospace;
     line-height: 1.6;
     overflow-x: hidden;
   }
   .ascii-container {
     max-width: 900px;
     margin: 0 auto;
     padding: 2rem;
     border: 1px solid #222;
     background: #08080c;
     box-shadow: 0 0 40px rgba(0,0,0,0.8);
     position: relative;
   }
   .ascii-container::before {
     content: '';
     position: absolute;
     top: 0; left: 0; right: 0; bottom: 0;
     background: radial-gradient(circle at 50% 0%, rgba(74,158,255,0.05) 0%, transparent 70%);
     pointer-events: none;
   }
   pre {
     margin: 0;
     white-space: pre-wrap;
     word-wrap: break-word;
     font-size: 14px;
     letter-spacing: 0.5px;
   }
   .highlight { color: var(--accent); text-shadow: 0 0 8px var(--glow); }
   .dim { color: var(--dim); }
   .breath { animation: pulse 4s ease-in-out infinite; }
   @keyframes pulse {
     0%, 100% { opacity: 0.6; text-shadow: 0 0 4px var(--glow); }
     50% { opacity: 1; text-shadow: 0 0 12px var(--glow); }
   }
   .fade-in {
     animation: fadeIn 2s ease-out forwards;
     opacity: 0;
   }
   @keyframes fadeIn {
     to { opacity: 1; }
   }
   /* Decorative ASCII borders */
   .border-top, .border-bottom {
     text-align: center;
     color: var(--dim);
     margin: 1rem 0;
     font-size: 12px;
   }
