<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>艾瑟兰编年史 - Chronicles of Aethelrand</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
@font-face{font-family:'GameFont';src:local('Georgia'),local('SimSun'),local('serif')}
:root{
--parchment:#2a1f14;--parchment-light:#3d2e1e;--parchment-lighter:#5a4530;
--gold:#d4a843;--gold-dim:#8a6d2b;--red:#c0392b;--green:#27ae60;
--blue:#2980b9;--purple:#8e44ad;--white:#e8dcc8;--dim:#7a6b5a;
--border:#6b5535;--shadow:rgba(0,0,0,0.6);
}
html,body{height:100%;overflow:hidden;background:#1a120b;color:var(--white);font-family:'GameFont',Georgia,serif;font-size:14px}
#game-container{display:grid;grid-template-columns:220px 1fr 260px;grid-template-rows:48px 1fr 180px;height:100vh;gap:2px;background:#0d0906}
#top-bar{grid-column:1/-1;background:linear-gradient(180deg,#3d2e1e,#2a1f14);border-bottom:2px solid var(--border);display:flex;align-items:center;padding:0 16px;gap:20px;font-size:13px}
#top-bar .title{color:var(--gold);font-size:16px;font-weight:bold;letter-spacing:2px}
#top-bar .info{display:flex;gap:14px;align-items:center}
#top-bar .info span{color:var(--dim)}
#top-bar .info b{color:var(--white)}
#left-panel{background:var(--parchment);border-right:2px solid var(--border);overflow-y:auto;padding:8px}
#center-panel{background:var(--parchment);display:flex;flex-direction:column;overflow:hidden}
#right-panel{background:var(--parchment);border-left:2px solid var(--border);overflow-y:auto;padding:8px}
#bottom-panel{grid-column:1/-1;background:var(--parchment);border-top:2px solid var(--border);display:flex;flex-direction:column}
#event-log{flex:1;overflow-y:auto;padding:10px 14px;font-size:13px;line-height:1.7}
#event-log .log-entry{margin-bottom:6px;padding:4px 8px;border-left:2px solid var(--border);padding-left:10px}
#event-log .log-combat{border-left-color:var(--red);color:#e8c8a0}
#event-log .log-quest{border-left-color:var(--gold);color:#f0d890}
#event-log .log-explore{border-left-color:var(--green);color:#a0d8b0}
#event-log .log-system{border-left-color:var(--blue);color:#a0c0d8}
#event-log .log-achievement{border-left-color:var(--purple);color:#d0a0e0}
#event-log .log-shop{border-left-color:#e67e22;color:#e8c8a0}
#cmd-bar{display:flex;gap:8px;padding:8px 14px;background:var(--parchment-light);border-top:1px solid var(--border)}
#cmd-input{flex:1;background:#1a120b;border:1px solid var(--border);color:var(--white);padding:8px 12px;font-family:inherit;font-size:13px;outline:none}
#cmd-input:focus{border-color:var(--gold)}
#cmd-input::placeholder{color:var(--dim)}
.btn{background:var(--parchment-lighter);border:1px solid var(--border);color:var(--white);padding:6px 14px;cursor:pointer;font-family:inherit;font-size:12px;transition:all .2s}
.btn:hover{background:var(--gold-dim);border-color:var(--gold)}
.btn:active{transform:scale(0.97)}
.btn-gold{background:linear-gradient(135deg,#5a4530,#3d2e1e);border-color:var(--gold);color:var(--gold)}
.btn-gold:hover{background:linear-gradient(135deg,#6b5540,#4d3e2e)}
.btn-red{border-color:var(--red);color:var(--red)}
.btn-red:hover{background:rgba(192,57,43,0.2)}
