.btn-green:hover{background:rgba(39,174,96,0.2)}
.panel-title{color:var(--gold);font-size:13px;font-weight:bold;padding:6px 8px;border-bottom:1px solid var(--border);margin-bottom:6px;display:flex;align-items:center;gap:6px}
.stat-row{display:flex;justify-content:space-between;padding:3px 8px;font-size:12px;border-bottom:1px solid rgba(107,85,53,0.3)}
.stat-row .label{color:var(--dim)}
.stat-row .value{color:var(--white);font-weight:bold}
.stat-bar{height:8px;background:#1a120b;border-radius:4px;margin:2px 8px;overflow:hidden}
.stat-bar-fill{height:100%;border-radius:4px;transition:width .5s}
.hp-bar{background:linear-gradient(90deg,#c0392b,#e74c3c)}
.mp-bar{background:linear-gradient(90deg,#2980b9,#3498db)}
.xp-bar{background:linear-gradient(90deg,#27ae60,#2ecc71)}
.st-bar{background:linear-gradient(90deg,#d4a843,#f39c12)}
.map-container{background:#1a120b;border:1px solid var(--border);padding:8px;font-family:monospace;font-size:11px;line-height:1.4;white-space:pre;color:var(--dim);overflow:auto;margin-bottom:8px;min-height:120px}
.map-container .loc{color:var(--gold)}
.map-container .visited{color:var(--green)}
.map-container .path{color:#4a3a2a}
.equip-slot{padding:4px 8px;margin:2px 0;background:var(--parchment-light);border:1px solid var(--border);font-size:11px;display:flex;justify-content:space-between;cursor:pointer;transition:all .2s}
.equip-slot:hover{border-color:var(--gold)}
.equip-slot .slot-name{color:var(--dim)}
.equip-slot .slot-item{color:var(--white)}
.rarity-common{color:#b0b0b0}
.rarity-uncommon{color:#27ae60}
.rarity-rare{color:#2980b9}
.rarity-epic{color:#8e44ad}
.rarity-legendary{color:#d4a843;text-shadow:0 0 8px rgba(212,168,67,0.5)}
.quest-item{padding:6px 8px;margin:4px 0;background:var(--parchment-light);border:1px solid var(--border);font-size:11px;cursor:pointer}
.quest-item:hover{border-color:var(--gold)}
.quest-item .q-title{font-weight:bold;margin-bottom:2px}
.quest-item .q-desc{color:var(--dim);font-size:10px}
.quest-item .q-progress{color:var(--gold);font-size:10px;margin-top:2px}
.achievement-item{display:flex;align-items:center;gap:6px;padding:4px 8px;margin:2px 0;font-size:11px}
.achievement-item.earned{color:var(--gold)}
.achievement-item.locked{color:var(--dim);opacity:0.5}
.collection-item{display:inline-block;padding:4px 8px;margin:2px;background:var(--parchment-light);border:1px solid var(--border);font-size:11px;cursor:pointer}
.collection-item.found{border-color:var(--gold);color:var(--gold)}
.collection-item.not-found{color:var(--dim);opacity:0.4}
#combat-overlay{display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(10,6,3,0.95);z-index:100;flex-direction:column}
#combat-overlay.active{display:flex}
#combat-header{background:linear-gradient(180deg,#3d2e1e,#2a1f14);border-bottom:2px solid var(--red);padding:10px 20px;display:flex;justify-content:space-between;align-items:center}
#combat-header h2{color:var(--red);font-size:18px}
#combat-body{flex:1;display:flex;overflow:hidden}
#combat-scene{flex:1;display:flex;flex-direction:column;padding:16px;overflow-y:auto}
#combat-enemies{display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin-bottom:16px}
.enemy-card{background:var(--parchment-light);border:2px solid var(--border);padding:10px;width:160px;text-align:center;transition:all .3s}
.enemy-card.targeted{border-color:var(--red);box-shadow:0 0 12px rgba(192,57,43,0.4)}
.enemy-card.dead{opacity:0.3;filter:grayscale(1)}
.enemy-card .enemy-name{font-weight:bold;margin-bottom:4px}
.enemy-card .enemy-icon{font-size:32px;margin:6px 0}
.enemy-card .enemy-hp{height:6px;background:#1a120b;border-radius:3px;overflow:hidden;margin-top:4px}
.enemy-card .enemy-hp-fill{height:100%;background:var(--red);border-radius:3px;transition:width .5s}
#combat-player-side{background:var(--parchment-light);border:1px solid var(--border);padding:12px;width:280px;overflow-y:auto}
#combat-log{height:120px;overflow-y:auto;padding:8px;background:#1a120b;border-top:1px solid var(--border);font-size:12px;line-height:1.6}
#combat-actions{display:flex;gap:6px;padding:10px 16px;background:var(--parchment-light);border-top:1px solid var(--border);flex-wrap:wrap}
#combat-actions .btn{min-width:80px;text-align:center}
.status-effect{display:inline-block;padding:2px 6px;margin:1px;border-radius:3px;font-size:10px;font-weight:bold}
.status-buff{background:rgba(39,174,96,0.2);color:var(--green);border:1px solid var(--green)}
.status-debuff{background:rgba(192,57,43,0.2);color:var(--red);border:1px solid var(--red)}
.status-neutral{background:rgba(41,128,185,0.2);color:var(--blue);border:1px solid var(--blue)}
.tab-bar{display:flex;gap:2px;margin-bottom:8px}
.tab-bar .tab{padding:4px 10px;background:var(--parchment-light);border:1px solid var(--border);cursor:pointer;font-size:11px;color:var(--dim);transition:all .2s}
.tab-bar .tab.active{background:var(--parchment-lighter);color:var(--gold);border-color:var(--gold)}
.tab-bar .tab:hover{color:var(--white)}
.skill-tree{padding:4px}
.skill-node{display:flex;align-items:center;gap:8px;padding:4px 8px;margin:2px 0;background:var(--parchment-light);border:1px solid var(--border);font-size:11px;cursor:pointer;transition:all .2s}
.skill-node:hover{border-color:var(--gold)}
.skill-node.unlocked{border-color:var(--green);background:rgba(39,174,96,0.1)}
.skill-node.locked{opacity:0.4;cursor:not-allowed}
.skill-node .skill-icon{font-size:16px}
.skill-node .skill-info{flex:1}
.skill-node .skill-name{font-weight:bold;font-size:11px}
.skill-node .skill-desc{color:var(--dim);font-size:10px}
.skill-node .skill-cost{color:var(--gold);font-size:10px}
.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:4px}
.inv-slot{aspect-ratio:1;background:var(--parchment-light);border:1px solid var(--border);display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;font-size:10px;transition:all .2s;position:relative}
.inv-slot:hover{border-color:var(--gold)}
.inv-slot .inv-icon{font-size:20px}
.inv-slot .inv-name{font-size:8px;color:var(--dim);text-align:center;overflow:hidden;max-height:16px}
.inv-slot .inv-count{position:absolute;top:2px;right:4px;font-size:9px;color:var(--gold);font-weight:bold}
.tooltip{position:fixed;background:#1a120b;border:2px solid var(--gold);padding:10px;z-index:200;max-width:280px;font-size:12px;pointer-events:none;display:none}
.tooltip .tt-title{color:var(--gold);font-weight:bold;font-size:13px;margin-bottom:4px}
.tooltip .tt-rarity{font-size:11px;margin-bottom:4px}
.tooltip .tt-desc{color:var(--dim);font-size:11px;margin-bottom:6px}
.tooltip .tt-stats{color:var(--white);font-size:11px}
.tooltip .tt-stats span{color:var(--green)}
.notification{position:fixed;top:60px;right:20px;background:var(--parchment-light);border:2px solid var(--gold);padding:12px 20px;z-index:300;animation:slideIn 0.3s ease,fadeOut 0.5s ease 2.5s forwards;font-size:13px;max-width:300px}
@keyframes slideIn{from{transform:translateX(100px);opacity:0}to{transform:translateX(0);opacity:1}}
@keyframes fadeOut{to{opacity:0;transform:translateY(-20px)}}
.faction-row{display:flex;justify-content:space-between;align-items:center;padding:4px 8px;margin:2px 0;font-size:11px}
.faction-name{display:flex;align-items:center;gap:6px}
.faction-rep{width:80px;height:6px;background:#1a120b;border-radius:3px;overflow:hidden}
.faction-rep-fill{height:100%;border-radius:3px;transition:width .5s}
.weather-display{font-size:24px;margin:4px 0}
.time-display{font-size:11px;color:var(--dim);margin:2px 0}
::-webkit-scrollbar{width:6px}
::-webkit-scrollbar-track{background:var(--parchment)}
::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px}
::-webkit-scrollbar-thumb:hover{background:var(--gold-dim)}
.combat-initiative{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:8px}
.initiative-item{padding:3px 8px;background:var(--parchment-light);border:1px solid var(--border);font-size:10px;text-align:center}
.initiative-item.current{border-color:var(--gold);background:rgba(212,168,67,0.15);color:var(--gold)}
.initiative-item.player-init{border-color:var(--green)}
.initiative-item.enemy-init{border-color:var(--red)}
.damage-num{position:absolute;font-weight:bold;font-size:16px;animation:dmgFloat 1s ease forwards;pointer-events:none;z-index:50}
@keyframes dmgFloat{0%{opacity:1;transform:translateY(0)}100%{opacity:0;transform:translateY(-40px)}}
.shake{animation:shake 0.3s ease}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}
</style>
</head>
<body>
