// ==================== UTILITY FUNCTIONS ====================
function rng(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function shuffle(arr) { return [...arr].sort(() => Math.random() - 0.5); }

function getStat(statId) {
  const s = G.state;
  let val = s.player.baseStats[statId];
  // Equipment bonuses
  for (const slot in s.player.equipment) {
    const item = s.player.equipment[slot];
    if (item && item['base' + statId.charAt(0).toUpperCase() + statId.slice(1)]) {
      val += item['base' + statId.charAt(0).toUpperCase() + statId.slice(1)];
    }
  }
  // Skill bonuses
  if (s.unlockedSkills.includes('war_cry')) val += Math.floor(s.player.baseStats[statId] * 0.1);
  return Math.max(1, val);
}

function getEffectiveStat(statId) {
  let val = getStat(statId);
  // Weather effect
  const weather = WEATHER_TYPES.find(w => w.id === G.state.weather);
  if (weather && weather.effect[statId]) {
    val = Math.max(1, val + weather.effect[statId]);
  }
  return val;
}

function getAttackPower() {
  const str = getStat('str');
  const agi = getStat('agi');
  let atk = Math.floor(str * 2 + agi * 0.5);
  // Weapon bonus
  const weapon = G.state.player.equipment.weapon;
  if (weapon) atk += weapon.baseAtk || 0;
  return atk;
}

function getDefense() {
  const vit = getStat('vit');
  const def = Math.floor(vit * 1.5);
  // Armor bonus
  const armor = G.state.player.equipment.chest;
  if (armor) def += armor.baseDef || 0;
  return def;
}

function getCritChance() {
  const lck = getStat('lck');
  const agi = getStat('agi');
  let crit = 5 + lck * 1.5 + agi * 0.3;
  const weapon = G.state.player.equipment.weapon;
  if (weapon && weapon.enchant === 'lightning') crit += 8;
  return Math.min(80, crit);
}

function getDodgeChance() {
  const agi = getStat('agi');
  return Math.min(60, agi * 1.5);
}

function getExpForLevel(level) { return Math.floor(50 * Math.pow(1.5, level - 1)); }

function getShopPrice(basePrice) {
  const fluct = G.state.marketFluctuation;
  return Math.max(1, Math.floor(basePrice * fluct));
}

function getLocationInfo(locId) {
  for (const c of WORLD.continents) {
    for (const r of c.regions) {
      for (const l of r.locations) {
        if (l.id === locId) return { loc: l, region: r, continent: c };
      }
    }
  }
  return null;
}

function getRegionLocations(regionId) {
  for (const c of WORLD.continents) {
    for (const r of c.regions) {
      if (r.id === regionId) return { region: r, continent: c, locations: r.locations };
    }
  }
  return null;
}

// ==================== UI RENDERING ====================
function renderAll() {
