function renderTopBar() {
  const s = G.state;
  const dateStr = `历元${s.date.year}年 ${SEASONS[s.date.season]} ${s.date.day}日`;
  const timeStr = `${String(s.date.hour).padStart(2, '0')}:00`;
  const weather = WEATHER_TYPES.find(w => w.id === s.weather);
  const locInfo = getLocationInfo(s.player.location);

  document.getElementById('display-date').textContent = dateStr;
  document.getElementById('display-time').textContent = timeStr;
  document.getElementById('weather-display').textContent = weather ? weather.icon : '☀️';
  document.getElementById('display-location').textContent = locInfo ? `${locInfo.loc.icon} ${locInfo.loc.name}` : '未知';
  document.getElementById('display-gold').textContent = s.gold;
  document.getElementById('display-level').textContent = `Lv.${s.player.level}`;
  document.getElementById('display-hp').textContent = `${s.player.hp}/${s.player.maxHp}`;
  document.getElementById('display-mp').textContent = `${s.player.mp}/${s.player.maxMp}`;
}

function renderStats() {
  const s = G.state;
  const p = s.player;
  const hpPct = (p.hp / p.maxHp * 100).toFixed(0);
  const mpPct = (p.mp / p.maxMp * 100).toFixed(0);
  const xpPct = (p.exp / p.expToNext * 100).toFixed(0);
  const stPct = (p.stamina / p.maxStamina * 100).toFixed(0);

  let html = `
    <div class="stat-row"><span class="label">❤️ HP</span><span class="value">${p.hp}/${p.maxHp}</span></div>
    <div class="stat-bar"><div class="stat-bar-fill hp-bar" style="width:${hpPct}%"></div></div>
    <div class="stat-row"><span class="label">💎 MP</span><span class="value">${p.mp}/${p.maxMp}</span></div>
    <div class="stat-bar"><div class="stat-bar-fill mp-bar" style="width:${mpPct}%"></div></div>
    <div class="stat-row"><span class="label">⭐ EXP</span><span class="value">${p.exp}/${p.expToNext}</span></div>
    <div class="stat-bar"><div class="stat-bar-fill xp-bar" style="width:${xpPct}%"></div></div>
    <div class="stat-row"><span class="label">⚡ 体力</span><span class="value">${p.stamina}/${p.maxStamina}</span></div>
    <div class="stat-bar"><div class="stat-bar-fill st-bar" style="width:${stPct}%"></div></div>
    <div style="margin-top:8px">`;

  for (const attr of ATTRIBUTES) {
    const val = getStat(attr.id);
    html += `<div class="stat-row"><span class="label">${attr.icon} ${attr.name}</span><span class="value">${val}</span></div>`;
  }

  html += `</div>
    <div class="stat-row"><span class="label">⚔️ 攻击</span><span class="value">${getAttackPower()}</span></div>
    <div class="stat-row"><span class="label">🛡️ 防御</span><span class="value">${getDefense()}</span></div>
    <div class="stat-row"><span class="label">🎯 暴击</span><span class="value">${getCritChance().toFixed(1)}%</span></div>
    <div class="stat-row"><span class="label">💨 闪避</span><span class="value">${getDodgeChance().toFixed(1)}%</span></div>
    <div class="stat-row"><span class="label">🍀 幸运</span><span class="value">${getStat('lck')}</span></div>
  `;

  document.getElementById('stats-panel').innerHTML = html;
}

function renderEquipment() {
  const s = G.state;
  const slots = ['weapon', 'chest', 'ring', 'neck', 'feet'];
  const slotNames = { weapon: '🗡️ 武器', chest: '🛡️ 护甲', ring: '💍 戒指', neck: '📿 护符', feet: '👢 靴子' };

  let html = '';
  for (const slot of slots) {
