    const rarityClass = item ? RARITIES.find(r => r.id === item.rarity)?.color || '' : '';
    html += `<div class="equip-slot" onclick="unequipItem('${slot}')">
      <span class="slot-name">${slotNames[slot]}</span>
      <span class="slot-item ${rarityClass}">${item ? item.name : '空'}</span>
    </div>`;
  }
  document.getElementById('equip-panel').innerHTML = html;
}

function renderSkillTree() {
  let html = '<div class="tab-bar">';
  for (const tree of SKILL_TREES) {
    const unlocked = tree.skills.filter(s => G.state.unlockedSkills.includes(s.id)).length;
    html += `<div class="tab ${unlocked > 0 ? 'active' : ''}" onclick="showSkillTree('${tree.id}')">${tree.icon} ${tree.name} (${unlocked}/${tree.skills.length})</div>`;
  }
  html += '</div>';
  html += '<div class="skill-tree" id="skill-tree-content"></div>';
  document.getElementById('skill-panel').innerHTML = html;
  showSkillTree(SKILL_TREES[0].id);
}

function showSkillTree(treeId) {
  const tree = SKILL_TREES.find(t => t.id === treeId);
  if (!tree) return;

  let html = `<div style="color:var(--gold);font-size:12px;margin-bottom:6px">${tree.icon} ${tree.name} - 技能点: ${G.state.player.skillPoints}</div>`;

  for (const skill of tree.skills) {
    const unlocked = G.state.unlockedSkills.includes(skill.id);
    const reqMet = !skill.req || G.state.unlockedSkills.includes(skill.req);
    const canUnlock = !unlocked && reqMet && G.state.player.skillPoints >= 1;
    const cls = unlocked ? 'unlocked' : (canUnlock ? '' : 'locked');

    html += `<div class="skill-node ${cls}" onclick="${canUnlock ? `unlockSkill('${skill.id}')` : ''}">
      <span class="skill-icon">${skill.icon}</span>
      <div class="skill-info">
        <div class="skill-name">${skill.name} ${unlocked ? '✅' : ''}</div>
        <div class="skill-desc">${skill.desc}</div>
      </div>
      <span class="skill-cost">${unlocked ? '已学' : '1SP'}</span>
    </div>`;
  }

  document.getElementById('skill-tree-content').innerHTML = html;
}

function unlockSkill(skillId) {
  if (G.state.player.skillPoints < 1) {
    addLog('技能点不足！升级或休息可获得技能点。', 'system');
    return;
  }
  const skill = SKILL_TREES.flatMap(t => t.skills).find(s => s.id === skillId);
  if (!skill || G.state.unlockedSkills.includes(skillId)) return;

  G.state.unlockedSkills.push(skillId);
  G.state.player.skillPoints--;
  addLog(`🌟 习得技能: ${skill.icon} ${skill.name} - ${skill.desc}`, 'quest');
  checkAchievements();
  renderAll();
}

function renderMap() {
  const s = G.state;
  const view = G.currentView;
  let mapHtml = '';

  if (view.region === null) {
    // Continent view
    mapHtml += `<span style="color:var(--gold)">🌍 大陆选择</span>\n\n`;
    for (let i = 0; i < WORLD.continents.length; i++) {
      const c = WORLD.continents[i];
      mapHtml += `  ${c.icon} ${c.name} [${c.regions.map(r => r.icon).join(' ')}]\n`;
      mapHtml += `  ${'─'.repeat(c.name.length + 4)}\n`;
      for (const r of c.regions) {
        mapHtml += `    → ${r.icon} ${r.name}\n`;
      }
    }
    mapHtml += `\n<span style="color:var(--dim)">输入: 前往[地区名] 或 点击地图</span>`;
    document.getElementById('map-level').textContent = '大陆';
  } else {
    // Region view
    const regionData = getRegionLocations(view.region);
    if (!regionData) return;

    mapHtml += `<span style="color:var(--gold)">${regionData.continent.icon} ${regionData.continent.name} → ${regionData.region.icon} ${regionData.region.name}</span>\n\n`;
    mapHtml += `  危险度: ${'⚠️'.repeat(regionData.region.locations.reduce((a, l) => a + l.danger, 0) / regionData.region.locations.length)}\n\n`;

    for (const loc of regionData.locations) {
      const visited = s.visitedLocations[loc.id];
      const current = loc.id === s.player.location;
      const prefix = current ? '📍' : (visited ? '✓' : '?');
      const cls = current ? 'loc' : (visited ? 'visited' : 'path');
      mapHtml += `  ${prefix} <span class="${cls}">${loc.icon} ${loc.name}</span> [危险:${'⚠️'.repeat(loc.danger)}]\n`;
      mapHtml += `    ${loc.desc}\n`;
      mapHtml += `    连接: ${loc.connections.map(c => {
        const cl = getLocationInfo(c);
        return cl ? cl.loc.name : c;
      }).join(' → ')}\n`;
    }
    mapHtml += `\n<span style="color:var(--dim)">输入: 前往[地点名] 或 返回[地区名]</span>`;
    document.getElementById('map-level').textContent = regionData.region.name;
  }

  document.getElementById('map-display').innerHTML = mapHtml;
}

function renderInventory() {
  const s = G.state;
  const maxSlots = 20;
  const maxWeight = 40;
  let weight = 0;
  for (const item of s.inventory) {
    weight += item.weight || 1;
  }

  document.getElementById('inv-count').textContent = `${s.inventory.length}/${maxSlots} | 负重: ${weight}/${maxWeight}`;

  let html = '<div class="inventory-grid">';
  for (let i = 0; i < maxSlots; i++) {
    const item = s.inventory[i];
    if (item) {
      const rarityClass = RARITIES.find(r => r.id === item.rarity)?.color || '';
      html += `<div class="inv-slot" onclick="useItem(${i})" onmouseenter="showTooltip(event, ${i})" onmouseleave="hideTooltip()">
        <span class="inv-icon">${item.icon}</span>
        <span class="inv-name ${rarityClass}">${item.name}</span>
        ${item.count > 1 ? `<span class="inv-count">x${item.count}</span>` : ''}
      </div>`;
    } else {
      html += '<div class="inv-slot"></div>';
    }
  }
  html += '</div>';
  document.getElementById('inv-panel').innerHTML = html;
}

function renderQuests() {
  const s = G.state;
  let html = '';

  const activeQuests = s.currentQuests.filter(q => !q.completed);
  const completedQuests = s.currentQuests.filter(q => q.completed);

  if (activeQuests.length === 0 && completedQuests.length === 0 && s.completedQuests.length === 0) {
    html = '<div style="color:var(--dim);font-size:11px;padding:8px">暂无任务</div>';
  } else {
    for (const q of activeQuests) {
      const questDef = QUEST_TEMPLATES.find(t => t.id === q.id);
      if (!questDef) continue;
      const progress = questDef.steps.filter(step => step.check(s)).length;
      const total = questDef.steps.length;
      const typeColors = { main: 'var(--gold)', side: 'var(--green)', bounty: 'var(--red)', hidden: 'var(--purple)' };
      const typeIcons = { main: '📜', side: '📋', bounty: '🎯', hidden: '🔮' };

      html += `<div class="quest-item" onclick="showQuestDetail('${q.id}')">
        <div class="q-title">${typeIcons[q.type] || '📋'} ${questDef.name} <span style="color:${typeColors[q.type]};font-size:10px">[${q.type}]</span></div>
        <div class="q-desc">${questDef.desc}</div>
        <div class="q-progress">进度: ${progress}/${total} - ${questDef.steps[progress]?.text || '完成!'}</div>
      </div>`;
    }

    if (completedQuests.length > 0) {
      html += '<div style="color:var(--dim);font-size:10px;margin-top:4px">已完成:</div>';
      for (const q of completedQuests.slice(0, 3)) {
        const questDef = QUEST_TEMPLATES.find(t => t.id === q.id);
        if (questDef) html += `<div style="color:var(--dim);font-size:10px;padding:2px 8px">✅ ${questDef.name}</div>`;
      }
    }
  }
  document.getElementById('quest-panel').innerHTML = html;
}

function renderFactions() {
  const s = G.state;
  let html = '';
  for (const f of FACTIONS) {
    const rep = s.factionRep[f.id] || 0;
    const repPct = Math.min(100, rep);
