function showTooltip(event, invIndex) {
  const item = G.state.inventory[invIndex];
  if (!item) return;
  const tt = document.getElementById('tooltip');
  const rarity = RARITIES.find(r => r.id === item.rarity);
  let statsHtml = '';
  if (item.baseAtk) statsHtml += `<div>攻击 +<span>${item.baseAtk}</span></div>`;
  if (item.baseDef) statsHtml += `<div>防御 +<span>${item.baseDef}</span></div>`;
  if (item.baseStr) statsHtml += `<div>力量 +<span>${item.baseStr}</span></div>`;
  if (item.baseAgi) statsHtml += `<div>敏捷 +<span>${item.baseAgi}</span></div>`;
  if (item.baseInt) statsHtml += `<div>智力 +<span>${item.baseInt}</span></div>`;
  if (item.baseVit) statsHtml += `<div>体质 +<span>${item.baseVit}</span></div>`;
  if (item.baseLck) statsHtml += `<div>幸运 +<span>${item.baseLck}</span></div>`;
  if (item.enchant) statsHtml += `<div>附魔: ${item.enchant}</div>`;

  tt.innerHTML = `
    <div class="tt-title">${item.icon} ${item.name}</div>
    <div class="tt-rarity ${rarity?.color || ''}">${rarity?.name || ''}</div>
    <div class="tt-desc">${item.desc}</div>
    ${statsHtml ? `<div class="tt-stats">${statsHtml}</div>` : ''}
    ${item.price ? `<div style="color:var(--gold);font-size:11px;margin-top:4px">价格: ${getShopPrice(item.price)} 金</div>` : ''}
  `;
  tt.style.display = 'block';
  tt.style.left = event.clientX + 10 + 'px';
  tt.style.top = event.clientY + 10 + 'px';
}

function hideTooltip() {
  document.getElementById('tooltip').style.display = 'none';
}

function addLog(text, type = 'system') {
  const log = document.getElementById('event-log');
  const entry = document.createElement('div');
  entry.className = `log-entry log-${type}`;
  entry.innerHTML = text;
  log.appendChild(entry);
  log.scrollTop = log.scrollHeight;

  // Also add to bottom panel
  const bottomLog = document.getElementById('event-log-bottom');
  const bEntry = document.createElement('div');
  bEntry.className = `log-entry log-${type}`;
  bEntry.innerHTML = text;
  bottomLog.appendChild(bEntry);
  bottomLog.scrollTop = bottomLog.scrollHeight;
}

function showNotification(text, type = 'info') {
  const n = document.createElement('div');
  n.className = 'notification';
  n.style.borderColor = type === 'achievement' ? 'var(--purple)' : (type === 'danger' ? 'var(--red)' : 'var(--gold)');
  n.textContent = text;
  document.body.appendChild(n);
  setTimeout(() => n.remove(), 3000);
}

// ==================== TIME & WEATHER ====================
function advanceTime(hours = 1) {
  const s = G.state;
  s.date.hour += hours;
  s.totalPlayTime += hours;

  while (s.date.hour >= 24) {
    s.date.hour -= 24;
    s.date.day++;

    // Season change every 30 days
    if (s.date.day > 30) {
      s.date.day = 1;
      s.date.season = (s.date.season + 1) % 4;
      addLog(`🌸 季节更替: ${SEASONS[s.date.season]}来临`, 'system');
    }

    // Weather change
    if (Math.random() < 0.3) {
      changeWeather();
    }

    // Market fluctuation
    if (Math.random() < 0.2) {
      G.state.marketFluctuation = clamp(G.state.marketFluctuation + (Math.random() - 0.5) * 0.3, 0.5, 2.0);
      addLog('💰 市场物价发生波动', 'shop');
    }
  }

  // Stamina regen
  s.player.stamina = Math.min(s.player.maxStamina, s.player.stamina + hours * 5);

  // HP/MP regen at inn/rest
  renderAll();
}

function changeWeather() {
  const s = G.state;
  const newWeather = pick(WEATHER_TYPES);
  s.weather = newWeather.id;
  s.weatherExperienced.add(newWeather.id);
  addLog(`${newWeather.icon} 天气变为: ${newWeather.name}`, 'system');
}

// ==================== MOVEMENT & EXPLORATION ====================
function moveToLocation(locId) {
  const s = G.state;
  const locInfo = getLocationInfo(locId);
  if (!locInfo) {
    addLog('❌ 无法到达该地点', 'system');
    return;
  }

  // Check if connected
  const currentLoc = getLocationInfo(s.player.location);
  if (currentLoc && !currentLoc.loc.connections.includes(locId)) {
    addLog(`❌ 无法直接从 ${currentLoc.loc.name} 前往 ${locInfo.loc.name}`, 'system');
    return;
  }

  s.player.location = locId;
  s.visitedLocations[locId] = true;

  // Random encounter chance
  const encounterChance = 0.15 + locInfo.loc.danger * 0.05;
  if (Math.random() < encounterChance && locInfo.loc.type !== 'city') {
    addLog(`⚠️ 在 ${locInfo.loc.name} 遭遇了敌人！`, 'combat');
    startCombat(locId);
  } else {
    addLog(`${locInfo.loc.icon} 到达: ${locInfo.loc.name}`, 'explore');

    // Location effects
    if (locInfo.loc.shop) {
      addLog('🏪 这里有商店可以购物', 'shop');
    }
    if (locInfo.loc.inn) {
      addLog('🏨 这里有旅馆可以休息', 'system');
    }
    if (locInfo.loc.herb && Math.random() < 0.4) {
      const herb = { ...ITEM_TEMPLATES.materials.find(m => m.id === 'herb'), rarity: 'common', count: 1, weight: 0.5 };
      addItem(herb);
      addLog(`🌿 发现了草药！`, 'explore');
    }
    if (locInfo.loc.hidden && Math.random() < 0.2) {
      addLog('🔮 似乎有什么隐藏的东西...', 'explore');
      if (Math.random() < 0.3) {
        const gold = rng(10, 50);
        s.gold += gold;
        addLog(`💰 发现了 ${gold} 金币！`, 'explore');
      }
    }
    if (locInfo.loc.treasure && Math.random() < 0.15) {
      addLog('💎 似乎有宝藏的线索...', 'explore');
    }
    if (locInfo.loc.dungeon) {
      addLog('🕳️ 这里似乎是地下城入口', 'explore');
    }
  }

  advanceTime(1);
  checkQuests();
  checkAchievements();
  renderAll();
}

function moveToRegion(regionId) {
  const s = G.state;
  const regionData = getRegionLocations(regionId);
  if (!regionData) {
    addLog('❌ 无法到达该地区', 'system');
    return;
  }

  // Find a location in the region to move to
  const firstLoc = regionData.region.locations[0];
  s.player.region = regionId;
  s.player.location = firstLoc.id;
  s.visitedLocations[firstLoc.id] = true;

  addLog(`🗺️ 前往 ${regionData.region.icon} ${regionData.region.name}`, 'explore');
  advanceTime(2);
  checkQuests();
  renderAll();
}

// ==================== INVENTORY SYSTEM ====================
function addItem(item) {
  const s = G.state;
  const maxSlots = 20;
  let weight = 0;
  for (const i of s.inventory) weight += i.weight || 1;

  if (s.inventory.length >= maxSlots) {
    addLog('❌ 背包已满！', 'system');
    return false;
  }
  if (weight + (item.weight || 1) > 40) {
    addLog('❌ 负重已达上限！', 'system');
    return false;
  }

  // Stack consumables
  if (item.type === 'consumable' || item.type === 'material') {
    const existing = s.inventory.find(i => i.id === item.id && i.rarity === item.rarity);
    if (existing) {
      existing.count = (existing.count || 1) + 1;
    } else {
      s.inventory.push({ ...item, count: 1 });
    }
  } else {
    s.inventory.push({ ...item, count: 1 });
  }

  s.stats.itemsCollected++;
  if (s.collection[item.id]) {
    s.collection[item.id]++;
  } else {
    s.collection[item.id] = 1;
  }

  checkAchievements();
  return true;
}

function removeItem(index) {
  const item = G.state.inventory.splice(index, 1)[0];
  if (item.type === 'material' || item.type === 'consumable') {
    // Check if any other of same id exists
    const exists = G.state.inventory.find(i => i.id === item.id && i.rarity === item.rarity);
    if (!exists && G.state.collection[item.id]) {
      G.state.collection[item.id]--;
      if (G.state.collection[item.id] <= 0) delete G.state.collection[item.id];
    }
  }
  return item;
}

function equipItem(index) {
  const item = G.state.inventory[index];
  if (!item) return;
  if (item.type !== 'weapon' && item.type !== 'armor' && item.type !== 'accessory') {
    addLog('❌ 无法装备该物品', 'system');
    return;
  }

  const slot = item.slot;
  const oldItem = G.state.player.equipment[slot];
  G.state.player.equipment[slot] = { ...item };
  removeItem(index);

  if (oldItem) {
    addItem(oldItem);
  }

  addLog(`⚔️ 装备了 ${item.icon} ${item.name}`, 'system');
  checkAchievements();
  renderAll();
}

function unequipItem(slot) {
  const item = G.state.player.equipment[slot];
  if (!item) return;

  if (addItem({ ...item })) {
    G.state.player.equipment[slot] = null;
    addLog(`卸下了 ${item.icon} ${item.name}`, 'system');
    renderAll();
  }
}

function useItem(index) {
  const item = G.state.inventory[index];
  if (!item) return;

  const s = G.state;

  if (item.type === 'consumable') {
    if (item.effect.type === 'heal') {
      s.player.hp = Math.min(s.player.maxHp, s.player.hp + item.effect.value);
      addLog(`🧪 使用 ${item.name}，恢复 ${item.effect.value} HP`, 'system');
    } else if (item.effect.type === 'mana') {
      s.player.mp = Math.min(s.player.maxMp, s.player.mp + item.effect.value);
      addLog(`💧 使用 ${item.name}，恢复 ${item.effect.value} MP`, 'system');
    } else if (item.effect.type === 'cure') {
      addLog(`💊 使用 ${item.name}`, 'system');
    } else if (item.effect.type === 'full_heal') {
      s.player.hp = s.player.maxHp;
      s.player.mp = s.player.maxMp;
      addLog(`✨ 使用 ${item.name}，完全恢复！`, 'system');
    }

    if (item.count > 1) {
      item.count--;
    } else {
      removeItem(index);
    }
  } else if (item.type === 'weapon' || item.type === 'armor' || item.type === 'accessory') {
    equipItem(index);
  } else if (item.type === 'material') {
    // Sell materials
    const price = getShopPrice(item.price || 5);
    s.gold += price;
    s.stats.goldEarned += price;
    removeItem(index);
    addLog(`💰 出售 ${item.name} 获得 ${price} 金币`, 'shop');
  }

  renderAll();
}

// ==================== SHOP SYSTEM ====================
function openShop() {
  const s = G.state;
  const locInfo = getLocationInfo(s.player.location);
  if (!locInfo || !locInfo.loc.shop) {
    addLog('❌ 这里没有商店', 'system');
    return;
  }

  let shopItems = [];
  // Generate shop items based on location danger level
  const danger = locInfo.loc.danger;
  const weaponPool = ITEM_TEMPLATES.weapons.filter(w => w.baseAtk <= danger * 5 + 5);
  const armorPool = ITEM_TEMPLATES.armor.filter(a => a.baseDef <= danger * 4 + 4);
  const accPool = ITEM_TEMPLATES.accessories;
  const consPool = ITEM_TEMPLATES.consumables;

  shopItems.push(...shuffle(weaponPool).slice(0, 2).map(w => ({ ...w, rarity: 'common', price: w.baseAtk * 8 })));
  shopItems.push(...shuffle(armorPool).slice(0, 2).map(a => ({ ...a, rarity: 'common', price: a.baseDef * 10 })));
  shopItems.push(...shuffle(accPool).slice(0, 2).map(a => ({ ...a, rarity: 'common', price: 50 })));
  shopItems.push(...consPool.map(c => ({ ...c, rarity: 'common', price: c.price || 10 })));

  // Randomly add higher rarity items
  if (Math.random() < 0.3) {
    const rarity = pick(RARITIES.slice(1, 3));
    const item = pick(shopItems);
    if (item) {
      item.rarity = rarity.id;
      item.price = Math.floor(item.price * rarity.mult);
    }
  }

  let msg = `🏪 ${locInfo.loc.name} 商店:\n`;
  for (let i = 0; i < shopItems.length; i++) {
    const item = shopItems[i];
    const rarity = RARITIES.find(r => r.id === item.rarity);
    const price = getShopPrice(item.price);
    msg += `  ${i + 1}. ${item.icon} ${item.name} [${rarity.name}] - ${price}金\n`;
  }
  msg += `\n输入: 购买[编号] 或 离开`;
  addLog(msg, 'shop');
}

function buyItem(index) {
  const s = G.state;
  const locInfo = getLocationInfo(s.player.location);
  if (!locInfo || !locInfo.loc.shop) return;

  const danger = locInfo.loc.danger;
  let shopItems = [];
  const weaponPool = ITEM_TEMPLATES.weapons.filter(w => w.baseAtk <= danger * 5 + 5);
  const armorPool = ITEM_TEMPLATES.armor.filter(a => a.baseDef <= danger * 4 + 4);
  const accPool = ITEM_TEMPLATES.accessories;
  const consPool = ITEM_TEMPLATES.consumables;

  shopItems.push(...weaponPool.slice(0, 2).map(w => ({ ...w, rarity: 'common', price: w.baseAtk * 8 })));
  shopItems.push(...armorPool.slice(0, 2).map(a => ({ ...a, rarity: 'common', price: a.baseDef * 10 })));
  shopItems.push(...accPool.slice(0, 2).map(a => ({ ...a, rarity: 'common', price: 50 })));
  shopItems.push(...consPool.map(c => ({ ...c, rarity: 'common', price: c.price || 10 })));

  if (index < 0 || index >= shopItems.length) return;

  const item = shopItems[index];
  const price = getShopPrice(item.price);

  if (s.gold < price) {
    addLog(`❌ 金币不足！需要 ${price} 金`, 'system');
    return;
  }

  // Determine actual rarity
  let actualRarity = item.rarity;
  if (Math.random() < 0.15) {
    actualRarity = pick(RARITIES.slice(1, 4)).id;
  }

  item.rarity = actualRarity;
  const priceMult = RARITIES.find(r => r.id === actualRarity)?.mult || 1;
  const finalPrice = Math.floor(price * priceMult);

  if (s.gold < finalPrice) {
    addLog(`❌ 金币不足！需要 ${finalPrice} 金`, 'system');
    return;
  }

  s.gold -= finalPrice;
  const newItem = { ...item, weight: item.weight || 1 };
  if (addItem(newItem)) {
    addLog(`🛒 购买了 ${item.icon} ${item.name} [${RARITIES.find(r => r.id === actualRarity)?.name}] 花费 ${finalPrice} 金`, 'shop');
    checkAchievements();
    renderAll();
  }
}

function restAtInn() {
  const s = G.state;
  const locInfo = getLocationInfo(s.player.location);
  if (!locInfo || !locInfo.loc.inn) return;

  const cost = 10 + s.player.level * 5;
  if (s.gold < cost) {
    addLog(`❌ 住宿费不足！需要 ${cost} 金`, 'system');
    return;
  }

  s.gold -= cost;
  s.player.hp = s.player.maxHp;
  s.player.mp = s.player.maxMp;
  s.player.stamina = s.player.maxStamina;
  advanceTime(8);
  addLog(`🏨 在旅馆休息了一晚，完全恢复！花费 ${cost} 金`, 'system');
  renderAll();
}

// ==================== QUEST SYSTEM ====================
function checkQuests() {
  const s = G.state;
  for (const q of s.currentQuests) {
    if (q.completed) continue;
    const questDef = QUEST_TEMPLATES.find(t => t.id === q.id);
    if (!questDef) continue;

    let allComplete = true;
    for (const step of questDef.steps) {
      if (!step.check(s)) {
        allComplete = false;
        break;
      }
    }

    if (allComplete) {
      q.completed = true;
      completeQuest(q, questDef);
    }
  }
}

function completeQuest(quest, questDef) {
  const s = G.state;
  addLog(`📜 任务完成: ${questDef.name}`, 'quest');

  if (questDef.rewards.exp) {
    gainExp(questDef.rewards.exp);
    addLog(`⭐ 获得 ${questDef.rewards.exp} 经验值`, 'quest');
  }
  if (questDef.rewards.gold) {
    s.gold += questDef.rewards.gold;
    s.stats.goldEarned += questDef.rewards.gold;
    addLog(`💰 获得 ${questDef.rewards.gold} 金币`, 'quest');
  }
  if (questDef.rewards.item) {
    const item = ITEM_TEMPLATES[questDef.rewards.item === 'weapon' ? 'weapons' : 'armor'].find(i => i.id === questDef.rewards.item);
    if (item) {
      const newItem = { ...item, rarity: 'uncommon', weight: 1 };
      if (addItem(newItem)) {
        addLog(`🎁 获得物品: ${item.icon} ${item.name}`, 'quest');
      }
    }
  }
  if (questDef.rewards.rep) {
    for (const [faction, amount] of Object.entries(questDef.rewards.rep)) {
      s.factionRep[faction] = (s.factionRep[faction] || 0) + amount;
      addLog(`🏛️ ${FACTIONS.find(f => f.id === faction)?.name} 声望 +${amount}`, 'quest');
    }
  }

  s.completedQuests.push(quest.id);
  checkAchievements();
  renderAll();
}

function startQuest(questId) {
  const questDef = QUEST_TEMPLATES.find(t => t.id === questId);
  if (!questDef) return;

  if (G.state.currentQuests.find(q => q.id === questId && !q.completed)) {
    addLog('❌ 该任务已在进行中', 'system');
    return;
  }
  if (G.state.completedQuests.includes(questId)) {
    addLog('❌ 该任务已完成', 'system');
    return;
  }

  G.state.currentQuests.push({ id: questId, completed: false });
  addLog(`📜 接受任务: ${questDef.name} - ${questDef.desc}`, 'quest');
  checkQuests();
  renderAll();
}

function showQuestDetail(questId) {
  const questDef = QUEST_TEMPLATES.find(t => t.id === questId);
  if (!questDef) return;

  const quest = G.state.currentQuests.find(q => q.id === questId);
  const progress = questDef.steps.filter(step => step.check(G.state)).length;

  let msg = `📜 ${questDef.name}\n`;
  msg += `描述: ${questDef.desc}\n`;
  msg += `类型: ${questDef.type}\n`;
  msg += `步骤:\n`;
  for (const step of questDef.steps) {
    const done = step.check(G.state);
    msg += `  ${done ? '✅' : '⬜'} ${step.text}\n`;
  }
  addLog(msg, 'quest');
}

// ==================== COMBAT SYSTEM ====================
function startCombat(locationId) {
  const s = G.state;
  const locInfo = getLocationInfo(locationId);
  if (!locInfo) return;

  const danger = locInfo.loc.danger;
  const enemyCount = Math.min(5, Math.max(1, Math.floor(danger / 3) + rng(0, 2)));
  const enemies = [];

  for (let i = 0; i < enemyCount; i++) {
    const tier = Math.max(1, Math.min(ENEMY_TEMPLATES.length - 1, danger + rng(-1, 1)));
    const template = ENEMY_TEMPLATES.filter(e => e.tier <= tier && !e.boss)[0];
    if (!template) continue;

    const levelScale = 1 + (danger - 1) * 0.1;
    enemies.push({
      ...template,
      currentHp: Math.floor(template.hp * levelScale),
      maxHp: Math.floor(template.hp * levelScale),
      currentAtk: Math.floor(template.atk * levelScale),
      currentDef: Math.floor(template.def * levelScale),
      statusEffects: [],
      frozen: false,
      stunned: false,
      poisoned: 0,
      slowed: 0
    });
  }

  if (enemies.length === 0) return;

  G.combat = {
    enemies: enemies,
    playerTurn: true,
    turn: 1,
    log: [],
    locationId: locationId,
    targetedEnemy: 0
  };

  document.getElementById('combat-overlay').classList.add('active');
  renderCombat();
  addLog(`⚔️ 战斗开始！遭遇了 ${enemies.map(e => `${e.icon} ${e.name}`).join(', ')}`, 'combat');
}

function renderCombat() {
  const c = G.combat;
  const s = G.state;

  // Initiative order
  let initiativeHtml = '';
  const allActors = [
    { name: '玩家', isPlayer: true, agi: getStat('agi'), current: c.playerTurn },
    ...c.enemies.map((e, i) => ({ name: e.name, isPlayer: false, agi: e.currentAgi || e.agi, index: i, current: !c.playerTurn && c.turn === 1 }))
  ];

  // Sort by agility
  allActors.sort((a, b) => b.agi - a.agi);

  for (const actor of allActors) {
    const cls = actor.isPlayer ? 'player-init' : 'enemy-init';
    const currentCls = actor.current ? 'current' : '';
    initiativeHtml += `<div class="initiative-item ${cls} ${currentCls}">${actor.isPlayer ? '👤' : c.enemies[actor.index]?.icon || '❓'} ${actor.name}</div>`;
  }
  document.getElementById('combat-initiative').innerHTML = initiativeHtml;

  // Enemies
  let enemiesHtml = '';
  for (let i = 0; i < c.enemies.length; i++) {
    const e = c.enemies[i];
    if (e.currentHp <= 0) continue;
    const hpPct = (e.currentHp / e.maxHp * 100).toFixed(0);
    const targeted = c.targetedEnemy === i ? 'targeted' : '';
    const statusHtml = e.statusEffects.map(se => `<span class="status-effect ${se.type === 'debuff' ? 'status-debuff' : 'status-buff'}">${se.icon} ${se.name}</span>`).join('');

    enemiesHtml += `<div class="enemy-card ${targeted}" onclick="selectEnemy(${i})">
      <div class="enemy-name">${e.icon} ${e.name}</div>
      <div style="font-size:10px;color:var(--dim)">${ELEMENTS[e.element]?.icon || ''} ${ELEMENTS[e.element]?.name || ''}</div>
      <div style="font-size:11px;margin:4px 0">HP: ${e.currentHp}/${e.maxHp}</div>
      <div class="enemy-hp"><div class="enemy-hp-fill" style="width:${hpPct}%"></div></div>
      <div style="margin-top:4px">${statusHtml}</div>
      <div style="font-size:10px;color:var(--dim);margin-top:2px">ATK:${e.currentAtk} DEF:${e.currentDef}</div>
    </div>`;
  }
  document.getElementById('combat-enemies').innerHTML = enemiesHtml;

  // Player side
  let playerHtml = `
    <div style="text-align:center;margin-bottom:8px">
      <div style="font-size:16px;font-weight:bold">👤 ${s.player.name}</div>
      <div style="font-size:11px;color:var(--dim)">Lv.${s.player.level}</div>
    </div>
    <div class="stat-row"><span class="label">❤️ HP</span><span class="value">${s.player.hp}/${s.player.maxHp}</span></div>
    <div class="stat-bar"><div class="stat-bar-fill hp-bar" style="width:${(s.player.hp/s.player.maxHp*100).toFixed(0)}%"></div></div>
    <div class="stat-row"><span class="label">💎 MP</span><span class="value">${s.player.mp}/${s.player.maxMp}</span></div>
    <div class="stat-bar"><div class="stat-bar-fill mp-bar" style="width:${(s.player.mp/s.player.maxMp*100).toFixed(0)}%"></div></div>
    <div class="stat-row"><span class="label">⚡ 体力</span><span class="value">${s.player.stamina}/${s.player.maxStamina}</span></div>
    <div class="stat-bar"><div class="stat-bar-fill st-bar" style="width:${(s.player.stamina/s.player.maxStamina*100).toFixed(0)}%"></div></div>
    <div style="margin-top:8px">
      <div class="stat-row"><span class="label">⚔️ 攻击</span><span class="value">${getAttackPower()}</span></div>
      <div class="stat-row"><span class="label">🛡️ 防御</span><span class="value">${getDefense()}</span></div>
      <div class="stat-row"><span class="label">🎯 暴击</span><span class="value">${getCritChance().toFixed(1)}%</span></div>
      <div class="stat-row"><span class="label">💨 闪避</span><span class="value">${getDodgeChance().toFixed(1)}%</span></div>
    </div>
    <div style="margin-top:8px">
      <div style="color:var(--gold);font-size:11px;margin-bottom:4px">已学技能:</div>
  `;
  for (const skillId of s.unlockedSkills) {
    const skill = SKILL_TREES.flatMap(t => t.skills).find(sk => sk.id === skillId);
    if (skill) {
      playerHtml += `<div style="font-size:10px;padding:2px 4px;margin:1px 0;background:var(--parchment);border:1px solid var(--border)">${skill.icon} ${skill.name} (${skill.cost}MP)</div>`;
    }
  }
  playerHtml += '</div>';
  document.getElementById('combat-player-side').innerHTML = playerHtml;

  // Combat log
  let logHtml = '';
  for (const entry of c.log.slice(-20)) {
    logHtml += `<div style="margin-bottom:2px">${entry}</div>`;
  }
  document.getElementById('combat-log').innerHTML = logHtml;
  document.getElementById('combat-log').scrollTop = document.getElementById('combat-log').scrollHeight;

  // Actions
  renderCombatActions();
}

function renderCombatActions() {
  const c = G.combat;
  const s = G.state;

  if (!c.playerTurn) {
    document.getElementById('combat-actions').innerHTML = '<div style="color:var(--dim);padding:10px">敌方回合...</div>';
    return;
  }

  let html = `<button class="btn btn-red" onclick="combatAttack()">⚔️ 攻击</button>`;
  html += `<button class="btn btn-green" onclick="combatDefend()">🛡️ 防御</button>`;
  html += `<button class="btn" onclick="combatFlee()">🏃 逃跑</button>`;

  // Skill buttons
  for (const skillId of s.unlockedSkills) {
    const skill = SKILL_TREES.flatMap(t => t.skills).find(sk => sk.id === skillId);
    if (skill) {
      const canUse = s.player.mp >= skill.cost;
      html += `<button class="btn ${canUse ? 'btn-gold' : ''}" onclick="combatSkill('${skillId}')" ${canUse ? '' : 'disabled'}>${skill.icon} ${skill.name} (${skill.cost}MP)</button>`;
    }
  }

  // Item buttons
  const consumables = s.inventory.filter(i => i.type === 'consumable');
  if (consumables.length > 0) {
    html += '<button class="btn" onclick="combatUseItem()">🧪 物品</button>';
  }

  document.getElementById('combat-actions').innerHTML = html;
}

function selectEnemy(index) {
  G.combat.targetedEnemy = index;
  renderCombat();
}

function combatAttack() {
  const c = G.combat;
  const s = G.state;
  const target = c.enemies[c.targetedEnemy];

  if (!target || target.currentHp <= 0) {
    // Auto-select first alive enemy
    const aliveIdx = c.enemies.findIndex(e => e.currentHp > 0);
    if (aliveIdx === -1) return;
    c.targetedEnemy = aliveIdx;
    combatAttack();
    return;
  }

  const atk = getAttackPower();
  const def = target.currentDef;
  let damage = Math.max(1, atk - Math.floor(def * 0.5) + rng(-3, 3));

  // Crit check
  const critChance = getCritChance();
  let isCrit = Math.random() * 100 < critChance;
  if (isCrit) damage = Math.floor(damage * 1.8);

  // Element effectiveness
  const playerElement = 'physical';
  if (ELEMENTS[playerElement]?.strong === target.element) {
    damage = Math.floor(damage * 1.3);
  } else if (ELEMENTS[playerElement]?.weak === target.element) {
    damage = Math.floor(damage * 0.7);
  }

  target.currentHp = Math.max(0, target.currentHp - damage);

  let logMsg = `⚔️ 你${isCrit ? ' [暴击!]' : ''}对 ${target.icon} ${target.name} 造成 ${damage} 点伤害`;
  if (target.currentHp <= 0) {
    logMsg += ' 💀 击杀!';
    c.stats = c.stats || {};
    c.stats.kills = c.stats.kills || {};
    c.stats.kills[target.id] = (c.stats.kills[target.id] || 0) + 1;
  }
  c.log.push(logMsg);

  renderCombat();

  if (target.currentHp <= 0) {
    // Check if all enemies defeated
    const allDead = c.enemies.every(e => e.currentHp <= 0);
    if (allDead) {
      setTimeout(() => endCombat(true), 500);
    }
  }
}

function combatDefend() {
  G.combat.playerDefending = true;
  G.combat.log.push('🛡️ 你进入防御姿态，本回合受到伤害减半');
  G.combat.playerTurn = false;
  renderCombat();
  setTimeout(() => enemyTurn(), 800);
}

function combatSkill(skillId) {
  const s = G.state;
  const c = G.combat;
  const skill = SKILL_TREES.flatMap(t => t.skills).find(sk => sk.id === skillId);
  if (!skill || s.player.mp < skill.cost) return;

  s.player.mp -= skill.cost;
  const effect = skill.effect;

  if (effect.type === 'damage' || effect.type === 'execute') {
    const target = c.enemies.find(e => e.currentHp > 0);
    if (!target) return;

    let damage = Math.floor(getStat(effect.attr) * effect.mult);
    const def = target.currentDef;
    damage = Math.max(1, damage - Math.floor(def * 0.3) + rng(-2, 2));

    if (effect.type === 'execute' && target.currentHp > target.maxHp * 0.5) {
      damage = Math.floor(damage * 0.5);
    }

    target.currentHp = Math.max(0, target.currentHp - damage);
    c.log.push(`${skill.icon} 你使用 ${skill.name}，对 ${target.icon} ${target.name} 造成 ${damage} 点伤害`);

    if (effect.type === 'damage_stun' && target.currentHp > 0) {
      target.stunned = true;
      c.log.push(`  💫 ${target.name} 被眩晕！`);
    }

    if (target.currentHp <= 0) {
      c.stats = c.stats || {};
      c.stats.kills = c.stats.kills || {};
      c.stats.kills[target.id] = (c.stats.kills[target.id] || 0) + 1;
    }

  } else if (effect.type === 'magic_damage' || effect.type === 'magic_damage_slow') {
    const target = c.enemies.find(e => e.currentHp > 0);
    if (!target) return;

    let damage = Math.floor(getStat(effect.attr) * effect.mult);
    const def = target.currentDef;
    damage = Math.max(1, damage - Math.floor(def * 0.2) + rng(-2, 2));

    // Element effectiveness
    const elem = ELEMENTS[effect.element];
    if (elem) {
      if (elem.strong === target.element) damage = Math.floor(damage * 1.5);
      else if (elem.weak === target.element) damage = Math.floor(damage * 0.5);
    }

    target.currentHp = Math.max(0, target.currentHp - damage);
    c.log.push(`${skill.icon} 你使用 ${skill.name}，对 ${target.icon} ${target.name} 造成 ${damage} 点${elem?.name || ''}伤害`);

    if (effect.type === 'magic_damage_slow') {
      target.slowed = 2;
      c.log.push(`  ❄️ ${target.name} 被减速！`);
    }

    if (target.currentHp <= 0) {
      c.stats = c.stats || {};
      c.stats.kills = c.stats.kills || {};
      c.stats.kills[target.id] = (c.stats.kills[target.id] || 0) + 1;
    }

  } else if (effect.type === 'aoe_magic') {
    let totalDamage = 0;
    for (const e of c.enemies) {
      if (e.currentHp <= 0) continue;
      let damage = Math.floor(getStat(effect.attr) * effect.mult);
      const def = e.currentDef;
      damage = Math.max(1, damage - Math.floor(def * 0.2) + rng(-2, 2));

      const elem = ELEMENTS[effect.element];
      if (elem) {
        if (elem.strong === e.element) damage = Math.floor(damage * 1.5);
        else if (elem.weak === e.element) damage = Math.floor(damage * 0.5);
      }

      e.currentHp = Math.max(0, e.currentHp - damage);
      totalDamage += damage;
      if (e.currentHp <= 0) {
        c.stats = c.stats || {};
        c.stats.kills = c.stats.kills || {};
        c.stats.kills[e.id] = (c.stats.kills[e.id] || 0) + 1;
      }
    }
    c.log.push(`${skill.icon} 你使用 ${skill.name}，对全体造成 ${totalDamage} 点伤害`);

  } else if (effect.type === 'poison') {
    const target = c.enemies.find(e => e.currentHp > 0);
    if (target) {
      target.poisoned = effect.duration;
      c.log.push(`${skill.icon} 你使用 ${skill.name}，对 ${target.icon} ${target.name} 施加中毒`);
    }

  } else if (effect.type === 'buff' || effect.type === 'buff_self') {
    c.log.push(`${skill.icon} 你使用 ${skill.name}，获得增益效果`);

  } else if (effect.type === 'freeze_all') {
    for (const e of c.enemies) {
      if (e.currentHp > 0) e.frozen = effect.duration;
    }
    c.log.push(`${skill.icon} 你使用 ${skill.name}，冻结所有敌人！`);

  } else if (effect.type === 'vanish') {
    c.log.push(`${skill.icon} 你使用 ${skill.name}，进入隐身状态`);
  }

  c.playerTurn = false;
  renderCombat();
  setTimeout(() => enemyTurn(), 800);
}

function combatUseItem() {
  const s = G.state;
  const consumables = s.inventory.filter(i => i.type === 'consumable');
  if (consumables.length === 0) return;

  // Use first available consumable
  const item = consumables[0];
  const idx = s.inventory.indexOf(item);

  if (item.effect.type === 'heal') {
    s.player.hp = Math.min(s.player.maxHp, s.player.hp + item.effect.value);
    G.combat.log.push(`🧪 使用 ${item.name}，恢复 ${item.effect.value} HP`);
  } else if (item.effect.type === 'mana') {
    s.player.mp = Math.min(s.player.maxMp, s.player.mp + item.effect.value);
    G.combat.log.push(`💧 使用 ${item.name}，恢复 ${item.effect.value} MP`);
  } else if (item.effect.type === 'full_heal') {
    s.player.hp = s.player.maxHp;
    s.player.mp = s.player.maxMp;
    G.combat.log.push(`✨ 使用 ${item.name}，完全恢复！`);
  }

  if (item.count > 1) item.count--;
  else removeItem(idx);

  G.combat.playerTurn = false;
  renderCombat();
  setTimeout(() => enemyTurn(), 800);
}

function combatFlee() {
  const c = G.combat;
  const agi = getStat('agi');
  const fleeChance = 30 + agi * 2;

  if (Math.random() * 100 < fleeChance) {
    c.log.push('🏃 你成功逃离了战斗！');
    addLog('🏃 成功逃离战斗', 'system');
    setTimeout(() => endCombat(false), 500);
  } else {
    c.log.push('❌ 逃跑失败！');
    c.playerTurn = false;
    renderCombat();
    setTimeout(() => enemyTurn(), 800);
  }
}

function enemyTurn() {
  const c = G.combat;
  const s = G.state;

  for (const enemy of c.enemies) {
    if (enemy.currentHp <= 0) continue;
    if (enemy.frozen > 0) {
      enemy.frozen--;
      c.log.push(`❄️ ${enemy.icon} ${enemy.name} 被冻结，无法行动`);
      continue;
    }
    if (enemy.stunned) {
      enemy.stunned = false;
      c.log.push(`💫 ${enemy.icon} ${enemy.name} 被眩晕，无法行动`);
      continue;
    }

    // Poison tick
    if (enemy.poisoned > 0) {
      enemy.poisoned--;
      enemy.currentHp = Math.max(0, enemy.currentHp - 5);
      c.log.push(`☠️ ${enemy.icon} ${enemy.name} 受到中毒伤害: 5`);
      if (enemy.currentHp <= 0) {
        c.stats = c.stats || {};
        c.stats.kills = c.stats.kills || {};
        c.stats.kills[enemy.id] = (c.stats.kills[enemy.id] || 0) + 1;
      }
      continue;
    }

    // Enemy AI decision
    const action = enemyAI(enemy, s, c);
    if (action) {
      c.log.push(action);
    }
  }

  // Check if player died
  if (s.player.hp <= 0) {
    setTimeout(() => endCombat(false), 500);
    return;
  }

  // Check if all enemies dead
  const allDead = c.enemies.every(e => e.currentHp <= 0);
  if (allDead) {
    setTimeout(() => endCombat(true), 500);
    return;
  }

  c.playerTurn = true;
  c.turn++;
  renderCombat();
}

function enemyAI(enemy, player, combat) {
  const agi = getStat('agi');
  const dodgeChance = getDodgeChance();

  // Check if player will dodge
  if (Math.random() * 100 < dodgeChance) {
    return `${enemy.icon} ${enemy.name} 的攻击被你的闪避躲开了！`;
  }

  let damage = Math.max(1, enemy.currentAtk - Math.floor(getDefense() * 0.5) + rng(-2, 2));

  if (combat.playerDefending) {
    damage = Math.floor(damage * 0.5);
    combat.playerDefending = false;
  }

  // Boss special attacks
  if (enemy.boss && Math.random() < 0.3) {
    damage = Math.floor(damage * 1.5);
    return `${enemy.icon} ${enemy.name} 发动强力攻击，造成 ${damage} 点伤害！`;
  }

  player.hp = Math.max(0, player.hp - damage);
  return `${enemy.icon} ${enemy.name} 攻击你，造成 ${damage} 点伤害`;
}

function endCombat(won) {
  const c = G.combat;
  const s = G.state;

  document.getElementById('combat-overlay').classList.remove('active');

  if (won) {
    let totalExp = 0;
    let totalGold = 0;

    for (const enemy of c.enemies) {
      totalExp += enemy.exp;
      totalGold += Math.floor(enemy.exp * 0.5);

      // Drops
      for (const dropId of enemy.drops) {
        if (Math.random() < 0.4) {
          const dropItem = Object.values(ITEM_TEMPLATES).flat().find(i => i.id === dropId);
          if (dropItem) {
            const rarity = Math.random() < 0.05 ? 'rare' : (Math.random() < 0.15 ? 'uncommon' : 'common');
            const newItem = { ...dropItem, rarity, weight: 0.5 };
            if (addItem(newItem)) {
              addLog(`🎁 掉落: ${dropItem.icon} ${dropItem.name} [${RARITIES.find(r => r.id === rarity)?.name}]`, 'explore');
            }
          }
        }
      }
    }

    s.gold += totalGold;
    s.stats.goldEarned += totalGold;
    s.stats.battlesWon++;

    addLog(`🎉 战斗胜利！获得 ${totalExp} 经验值，${totalGold} 金币`, 'combat');
    gainExp(totalExp);

    // Update player stats for quests
    for (const enemy of c.enemies) {
      s.stats.kills[enemy.id] = (s.stats.kills[enemy.id] || 0) + 1;
    }

  } else {
    s.stats.battlesLost++;
    addLog('💀 战斗失败... 你被击败了', 'combat');
    s.player.hp = Math.floor(s.player.maxHp * 0.3);
    s.player.mp = Math.floor(s.player.maxMp * 0.3);
    s.gold = Math.max(0, s.gold - Math.floor(s.gold * 0.1));
  }

  advanceTime(1);
  checkQuests();
  checkAchievements();
  renderAll();
}

function gainExp(amount) {
  const s = G.state;
  s.player.exp += amount;

  while (s.player.exp >= s.player.expToNext) {
    s.player.exp -= s.player.expToNext;
    s.player.level++;
    s.player.expToNext = getExpForLevel(s.player.level);
    s.player.skillPoints++;

    // Stat growth
    s.player.baseStr = (s.player.baseStr || s.player.baseStats.str) + rng(1, 2);
    s.player.baseAgi = (s.player.baseAgi || s.player.baseStats.agi) + rng(1, 2);
    s.player.baseInt = (s.player.baseInt || s.player.baseStats.int) + rng(1, 2);
    s.player.baseVit = (s.player.baseVit || s.player.baseStats.vit) + rng(1, 2);
    s.player.baseLck = (s.player.baseLck || s.player.baseStats.lck) + rng(0, 1);

    s.player.maxHp = 80 + s.player.level * 20 + s.player.baseVit * 5;
    s.player.maxMp = 30 + s.player.level * 10 + s.player.baseInt * 5;
    s.player.maxStamina = 80 + s.player.level * 10;
    s.player.hp = s.player.maxHp;
    s.player.mp = s.player.maxMp;

    addLog(`⭐ 升级！达到 Lv.${s.player.level}！获得 1 技能点`, 'quest');
  }
}

