  padding: 10px 20px;
  background: linear-gradient(180deg, rgba(10,10,20,0.95), rgba(10,10,20,0.7));
  border-bottom: 1px solid #2a1a4a;
  z-index: 10;
  flex-shrink: 0;
}

.hud-left, .hud-right { display: flex; align-items: center; gap: 15px; }

.crystal-slot {
  width: 40px;
  height: 40px;
  border: 2px solid #3a2a5a;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  background: rgba(10,10,20,0.8);
  transition: all 0.5s;
  position: relative;
}

.crystal-slot.found {
  border-color: #f0c040;
  box-shadow: 0 0 15px #f0c04066;
  animation: crystalGlow 2s ease-in-out infinite;
}

@keyframes crystalGlow {
  0%, 100% { box-shadow: 0 0 10px #f0c04044; }
  50% { box-shadow: 0 0 25px #f0c04088; }
}

.crystal-slot .crystal-label {
  position: absolute;
  bottom: -18px;
  font-size: 0.55rem;
  color: #665588;
  white-space: nowrap;
  font-family: 'Cinzel', serif;
  letter-spacing: 1px;
}

.crystal-slot.found .crystal-label { color: #f0c040; }

.hud-stat {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'Cinzel', serif;
  font-size: 0.85rem;
}

.stat-icon { font-size: 1.1rem; }

.stat-bar-container {
  width: 100px;
  height: 10px;
  background: #1a1a2a;
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid #3a2a5a;
}

.stat-bar {
  height: 100%;
  border-radius: 5px;
  transition: width 0.5s;
}

.health-bar { background: linear-gradient(90deg, #aa2222, #ff4444); }
.mana-bar { background: linear-gradient(90deg, #2244aa, #4488ff); }

/* Main Content Area */
#main-area {
  flex: 1;
  display: flex;
  overflow: hidden;
  position: relative;
}

/* Map View */
#map-view {
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
}

#map-container {
  flex: 1;
  position: relative;
  overflow: hidden;
  background: #0d0d18;
}

#world-map {
  width: 100%;
  height: 100%;
  position: relative;
}

.map-region {
  position: absolute;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.4s;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 2px solid transparent;
  overflow: hidden;
}

.map-region::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 10px;
  opacity: 0.3;
  transition: opacity 0.4s;
}

.map-region:hover::before { opacity: 0.5; }
.map-region:hover { transform: scale(1.05); z-index: 5; }

.map-region.locked {
  opacity: 0.3;
  cursor: not-allowed;
  filter: grayscale(0.8);
}
.map-region.locked:hover { transform: none; }

.map-region.current {
  border-color: #f0c040;
  box-shadow: 0 0 20px #f0c04044;
}

.map-region.cleared {
  border-color: #44aa44;
}

.region-icon { font-size: 2rem; z-index: 2; }
.region-name {
  font-family: 'Cinzel', serif;
  font-size: 0.7rem;
  z-index: 2;
  margin-top: 4px;
  text-shadow: 0 0 10px rgba(0,0,0,0.8);
  letter-spacing: 1px;
}

.region-crystal-indicator {
  position: absolute;
  top: 5px;
  right: 5px;
  font-size: 0.9rem;
  z-index: 2;
}

/* Region Backgrounds */
.region-forest { background: linear-gradient(135deg, #0a1a0a, #1a2a1a); left: 5%; top: 15%; width: 28%; height: 35%; }
.region-forest::before { background: linear-gradient(135deg, #0a2a0a, #0a3a0a); }

.region-mountains { background: linear-gradient(135deg, #1a0a0a, #2a1a0a); left: 40%; top: 8%; width: 25%; height: 30%; }
.region-mountains::before { background: linear-gradient(135deg, #2a1a0a, #3a2a0a); }

.region-temple { background: linear-gradient(135deg, #0a0a2a, #0a1a3a); left: 70%; top: 20%; width: 25%; height: 35%; }
.region-temple::before { background: linear-gradient(135deg, #0a1a4a, #0a2a5a); }

.region-caves { background: linear-gradient(135deg, #1a1a0a, #2a2a1a); left: 10%; top: 55%; width: 30%; height: 35%; }
.region-caves::before { background: linear-gradient(135deg, #2a2a0a, #3a3a1a); }

.region-storm { background: linear-gradient(135deg, #1a0a2a, #2a1a3a); left: 48%; top: 50%; width: 42%; height: 40%; }
.region-storm::before { background: linear-gradient(135deg, #2a1a4a, #3a2a5a); }

/* Story Panel */
#story-panel {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(0deg, rgba(10,10,20,0.98), rgba(10,10,20,0.85));
  border-top: 1px solid #2a1a4a;
  padding: 15px 20px;
  max-height: 40%;
  overflow-y: auto;
  z-index: 10;
  transition: max-height 0.5s;
}

#story-text {
  font-size: clamp(0.85rem, 1.5vw, 1rem);
  line-height: 1.7;
  color: #c0b0a0;
}

#story-text .speaker {
  font-family: 'Cinzel', serif;
  color: #f0c040;
  font-weight: bold;
}

#story-text .narration { color: #a09080; font-style: italic; }

#story-text .action-text { color: #88aaff; }

.story-choices {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 12px;
}

.choice-btn {
  font-family: 'MedievalSharp', cursive;
  font-size: 0.9rem;
  padding: 8px 18px;
  background: rgba(30,20,50,0.8);
  color: #c0b0a0;
  border: 1px solid #3a2a5a;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.3s;
}

.choice-btn:hover {
  background: rgba(50,30,80,0.8);
  border-color: #f0c040;
  color: #f0c040;
}

/* Scene View (for encounters/puzzles) */
#scene-view {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 20;
  background: rgba(5,5,15,0.95);
}

#scene-view.active { display: flex; }

.scene-title {
  font-family: 'Cinzel Decorative', serif;
  font-size: clamp(1.2rem, 3vw, 2rem);
  color: #f0c040;
  text-shadow: 0 0 20px #f0c04044;
  margin-bottom: 20px;
  text-align: center;
}

.scene-content {
  max-width: 600px;
  width: 90%;
  text-align: center;
}

.scene-description {
  font-size: 1rem;
  line-height: 1.8;
  color: #b0a090;
  margin-bottom: 20px;
}

/* Puzzle: Memory */
.memory-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  max-width: 320px;
  margin: 0 auto;
}

.memory-card {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a1a4a, #1a0a3a);
  border: 2px solid #3a2a5a;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  cursor: pointer;
  transition: all 0.3s;
  user-select: none;
}

.memory-card:hover { border-color: #f0c040; }
.memory-card.flipped { background: linear-gradient(135deg, #3a2a6a, #2a1a5a); border-color: #f0c040; }
.memory-card.matched { background: linear-gradient(135deg, #1a3a1a, #0a2a0a); border-color: #44aa44; }

/* Puzzle: Runes */
.rune-puzzle {
  display: flex;
  gap: 15px;
  justify-content: center;
  flex-wrap: wrap;
  margin: 20px 0;
}

.rune-stone {
  width: 70px;
  height: 90px;
  background: linear-gradient(180deg, #2a2a3a, #1a1a2a);
  border: 2px solid #4a3a6a;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  cursor: pointer;
  transition: all 0.3s;
  user-select: none;
}

.rune-stone:hover { border-color: #f0c040; transform: translateY(-5px); }
.rune-stone.selected { border-color: #f0c040; box-shadow: 0 0 15px #f0c04044; }
.rune-stone.correct { border-color: #44aa44; background: linear-gradient(180deg, #1a3a1a, #0a2a0a); }
.rune-stone.wrong { border-color: #aa2222; animation: shake 0.5s; }

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-8px); }
  75% { transform: translateX(8px); }
}

/* Combat */
.combat-arena {
  display: flex;
  align-items: center;
  justify-content: space-around;
  width: 100%;
  max-width: 500px;
  margin: 20px 0;
}

.combatant {
  text-align: center;
}

.combatant-sprite {
  font-size: 3.5rem;
  margin-bottom: 10px;
  transition: transform 0.3s;
}

.combatant-sprite.attacking {
  animation: attackAnim 0.5s;
}

@keyframes attackAnim {
  0% { transform: translateX(0); }
  30% { transform: translateX(30px); }
  60% { transform: translateX(-10px); }
  100% { transform: translateX(0); }
}

.combatant-sprite.hit {
  animation: hitAnim 0.5s;
}

@keyframes hitAnim {
  0%, 100% { filter: none; }
  25% { filter: brightness(3) hue-rotate(180deg); transform: translateX(-5px); }
  50% { filter: brightness(3) hue-rotate(180deg); transform: translateX(5px); }
}

.combat-hp-bar {
  width: 120px;
  height: 8px;
  background: #1a1a2a;
  border-radius: 4px;
  overflow: hidden;
  margin: 5px auto;
}

.combat-hp-fill {
  height: 100%;
  background: linear-gradient(90deg, #aa2222, #ff4444);
  border-radius: 4px;
  transition: width 0.5s;
}

.combat-actions {
  display: flex;
  gap: 10px;
  justify-content: center;
  margin-top: 15px;
}

.combat-btn {
  font-family: 'Cinzel', serif;
  font-size: 0.85rem;
  padding: 10px 20px;
  background: linear-gradient(135deg, #2a1a4a, #1a0a3a);
  color: #f0c040;
  border: 1px solid #3a2a5a;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.3s;
}

.combat-btn:hover {
  border-color: #f0c040;
  box-shadow: 0 0 10px #f0c04044;
}

.combat-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Crystal Collection Animation */
.crystal-collect {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 200;
  text-align: center;
  display: none;
}

.crystal-collect.active { display: block; }

.crystal-collect-icon {
  font-size: 5rem;
  animation: crystalSpin 1s ease-out;
}

@keyframes crystalSpin {
  0% { transform: scale(0) rotate(0deg); opacity: 0; }
  50% { transform: scale(1.5) rotate(180deg); opacity: 1; }
  100% { transform: scale(1) rotate(360deg); opacity: 1; }
}

.crystal-collect-text {
  font-family: 'Cinzel Decorative', serif;
  font-size: 1.5rem;
  color: #f0c040;
  text-shadow: 0 0 20px #f0c04088;
  margin-top: 15px;
  animation: fadeInUp 0.5s ease-out 0.5s both;
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Victory Screen */
#victory-screen {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at center, #1a1a0a 0%, #0a0a0f 70%);
  z-index: 300;
  text-align: center;
  padding: 20px;
}

#victory-screen.active { display: flex; }

.victory-title {
  font-family: 'Cinzel Decorative', serif;
  font-size: clamp(1.5rem, 4vw, 3rem);
  color: #f0c040;
  text-shadow: 0 0 30px #f0c04088, 0 0 60px #f0c04044;
  margin-bottom: 20px;
}

.victory-text {
  max-width: 500px;
  font-size: 1rem;
  line-height: 1.8;
  color: #c0b0a0;
  margin-bottom: 30px;
}

.victory-crystals {
  display: flex;
  gap: 15px;
  margin-bottom: 30px;
}

.victory-crystal {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  animation: victoryPulse 2s ease-in-out infinite;
  border: 2px solid #f0c040;
  box-shadow: 0 0 20px #f0c04044;
}

@keyframes victoryPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.1); }
}

/* Back button */
.back-btn {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 15;
  font-family: 'Cinzel', serif;
  font-size: 0.8rem;
  padding: 6px 14px;
  background: rgba(20,15,30,0.8);
  color: #8877aa;
  border: 1px solid #3a2a5a;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.3s;
}

.back-btn:hover { color: #f0c040; border-color: #f0c040; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: #0a0a0f; }
::-webkit-scrollbar-thumb { background: #3a2a5a; border-radius: 3px; }

/* Notification */
.notification {
  position: fixed;
  top: 60px;
  right: 20px;
  padding: 12px 20px;
  background: rgba(20,15,30,0.95);
  border: 1px solid #3a2a5a;
  border-radius: 8px;
  font-family: 'Cinzel', serif;
  font-size: 0.85rem;
  color: #f0c040;
  z-index: 100;
  animation: notifSlide 0.3s ease-out, notifFade 0.5s ease-in 2s forwards;
}

@keyframes notifSlide {
  from { transform: translateX(100px); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes notifFade {
  to { opacity: 0; transform: translateX(50px); }
}

/* Lightning effect */
.lightning {
  position: absolute;
  inset: 0;
  background: rgba(200, 200, 255, 0.1);
  pointer-events: none;
  z-index: 50;
  animation: lightningFlash 0.15s ease-out;
}

@keyframes lightningFlash {
  0% { opacity: 1; }
  100% { opacity: 0; }
}

/* Darkness overlay */
#darkness-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  transition: background 2s;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(0,0,0,0.7) 100%);
}

#darkness-overlay.light {
  background: radial-gradient(ellipse at center, transparent 60%, rgba(0,0,0,0.2) 100%);
}

/* Responsive */
@media (max-width: 600px) {
  .map-region { font-size: 0.6rem; }
  .region-icon { font-size: 1.5rem; }
  .region-name { font-size: 0.55rem; }
  .crystal-slot { width: 32px; height: 32px; font-size: 1rem; }
  .stat-bar-container { width: 60px; }
  .memory-grid { grid-template-columns: repeat(4, 1fr); gap: 5px; }
  .memory-card { font-size: 1.1rem; }
  .rune-stone { width: 55px; height: 70px; font-size: 1.5rem; }
}
</style>
</head>
<body>
<div id="game-container">
  <!-- Particles -->
  <div id="particles"></div>

  <!-- Title Screen -->
  <div id="title-screen">
    <div class="title-glow">Eldoria</div>
    <div class="subtitle">The Sacred Crystals</div>
    <div class="lore-box">
      Long ago, there was a peaceful kingdom called <span class="highlight">Eldoria</span>. The people lived in harmony, and the land was full of life. One dark night, an evil sorcerer known as <span class="highlight">Dark Lord Vexar</span> attacked the kingdom using forbidden magic. The king was killed, the land was destroyed, and darkness spread everywhere.<br><br>
      Before the kingdom fell, the ancient guardians hid <span class="highlight">five Sacred Crystals</span> across the world. These crystals are the only hope to restore Eldoria.<br><br>
      <em>You are the last guardian. The quest begins now.</em>
    </div>
    <button class="btn" onclick="startGame()">Begin the Quest</button>
  </div>

  <!-- Game Screen -->
  <div id="game-screen">
    <!-- HUD -->
    <div id="hud">
      <div class="hud-left">
        <div class="hud-stat">
          <span class="stat-icon">❤️</span>
          <div class="stat-bar-container">
            <div class="stat-bar health-bar" id="health-bar" style="width:100%"></div>
          </div>
          <span id="health-text">100</span>
        </div>
        <div class="hud-stat">
          <span class="stat-icon">💎</span>
          <div class="stat-bar-container">
            <div class="stat-bar mana-bar" id="mana-bar" style="width:100%"></div>
          </div>
          <span id="mana-text">100</span>
        </div>
      </div>
      <div class="hud-right" id="crystal-slots"></div>
    </div>

    <!-- Main Area -->
    <div id="main-area">
      <!-- Map View -->
      <div id="map-view">
        <div id="map-container">
          <div id="world-map">
            <div class="map-region region-forest" data-region="forest" onclick="enterRegion('forest')">
              <div class="region-crystal-indicator" id="forest-crystal">🔒</div>
              <div class="region-icon">🌲</div>
              <div class="region-name">Darkwood Forest</div>
            </div>
            <div class="map-region region-mountains" data-region="mountains" onclick="enterRegion('mountains')">
              <div class="region-crystal-indicator" id="mountains-crystal">🔒</div>
              <div class="region-icon">🌋</div>
              <div class="region-name">Burning Mountains</div>
            </div>
            <div class="map-region region-temple" data-region="temple" onclick="enterRegion('temple')">
              <div class="region-crystal-indicator" id="temple-crystal">🔒</div>
              <div class="region-icon">🏛️</div>
              <div class="region-name">Sunken Temple</div>
            </div>
            <div class="map-region region-caves" data-region="caves" onclick="enterRegion('caves')">
              <div class="region-crystal-indicator" id="caves-crystal">🔒</div>
              <div class="region-icon">⛏️</div>
              <div class="region-name">Crystal Caves</div>
            </div>
            <div class="map-region region-storm" data-region="storm" onclick="enterRegion('storm')">
              <div class="region-crystal-indicator" id="storm-crystal">🔒</div>
              <div class="region-icon">⛈️</div>
              <div class="region-name">Storm Peaks</div>
            </div>
          </div>
          <div id="darkness-overlay"></div>
        </div>

        <!-- Story Panel -->
        <div id="story-panel">
          <div id="story-text">
            <span class="narration">You stand at the edge of the ruined kingdom. The sky is choked with dark clouds, and the land stretches before you, scarred by Vexar's magic. The five Sacred Crystals must be found before the darkness consumes all of Eldoria.</span>
          </div>
          <div class="story-choices" id="story-choices"></div>
        </div>
      </div>

      <!-- Scene View -->
      <div id="scene-view">
        <button class="back-btn" onclick="exitScene()">← Return to Map</button>
        <div class="scene-content" id="scene-content"></div>
      </div>
    </div>
  </div>

  <!-- Crystal Collection Animation -->
  <div class="crystal-collect" id="crystal-collect">
    <div class="crystal-collect-icon" id="collect-icon">💎</div>
    <div class="crystal-collect-text" id="collect-text">Crystal Found!</div>
  </div>

  <!-- Victory Screen -->
  <div id="victory-screen">
    <div class="victory-title">✦ Eldoria is Restored ✦</div>
    <div class="victory-crystals">
      <div class="victory-crystal">🌲</div>
      <div class="victory-crystal">🌋</div>
      <div class="victory-crystal">🏛️</div>
      <div class="victory-crystal">⛏️</div>
      <div class="victory-crystal">⛈️</div>
    </div>
    <div class="victory-text">
      With all five Sacred Crystals united, a brilliant light erupted across Eldoria. The dark clouds parted, sunlight flooded the land, and the ruins began to heal. Vexar's sorcery shattered like glass, and the ancient kingdom was reborn.<br><br>
      The people emerged from hiding, weeping with joy as the flowers bloomed and rivers ran clear once more. You, the last guardian, had saved them all.<br><br>
      <em>Eldoria lives again, thanks to your courage.</em>
    </div>
    <button class="btn" onclick="location.reload()">Play Again</button>
  </div>
</div>

<script>
// Game State
const state = {
  health: 100,
  maxHealth: 100,
  mana: 100,
  maxMana: 100,
  crystals: { forest: false, mountains: false, temple: false, caves: false, storm: false },
  currentRegion: null,
  visitedRegions: [],
  storyStep: 0,
  gameStarted: false
};

const crystalNames = {
  forest: 'Crystal of Light',
  mountains: 'Crystal of Fire',
  temple: 'Crystal of Water',
  caves: 'Crystal of Earth',
  storm: 'Crystal of Wind'
};

const crystalIcons = {
  forest: '💚',
  mountains: '🔴',
  temple: '🔵',
  caves: '🟡',
  storm: '⚪'
};

// Story data
const stories = {
  forest: {
    intro: `<span class="narration">You enter the Darkwood Forest. Ancient trees twist like skeletal fingers against the bruised sky. The air is thick with a malevolent energy — Vexar's dark magic seeps from the soil itself. Somewhere in this forest, the <span class="highlight">Crystal of Light</span> waits.</span>`,
    choices: [
      { text: '🔦 Venture deeper into the forest', action: () => forestPuzzle() },
      { text: '🧘 Meditate to sense the crystal', action: () => forestMeditate() }
