// Initialize
function startGame() {
  document.getElementById('title-screen').classList.add('hidden');
  setTimeout(() => {
    document.getElementById('title-screen').style.display = 'none';
    document.getElementById('game-screen').classList.add('active');
    state.gameStarted = true;
    updateHUD();
    updateCrystalSlots();
    createParticles();
    updateDarkness();
  }, 1000);
}

function createParticles() {
  const container = document.getElementById('particles');
  const colors = ['#f0c040', '#8877aa', '#4488ff', '#ff4444', '#44aa44'];
  for (let i = 0; i < 30; i++) {
    const p = document.createElement('div');
    p.className = 'particle';
    const size = Math.random() * 4 + 1;
    p.style.width = size + 'px';
    p.style.height = size + 'px';
    p.style.left = Math.random() * 100 + '%';
    p.style.top = (100 + Math.random() * 20) + '%';
    p.style.background = colors[Math.floor(Math.random() * colors.length)];
    p.style.animationDuration = (Math.random() * 10 + 8) + 's';
    p.style.animationDelay = (Math.random() * 10) + 's';
    container.appendChild(p);
  }
}

function updateHUD() {
  document.getElementById('health-bar').style.width = (state.health / state.maxHealth * 100) + '%';
  document.getElementById('mana-bar').style.width = (state.mana / state.maxMana * 100) + '%';
  document.getElementById('health-text').textContent = state.health;
  document.getElementById('mana-text').textContent = state.mana;
}

function updateCrystalSlots() {
  const container = document.getElementById('crystal-slots');
  container.innerHTML = '';
  const regions = ['forest', 'mountains', 'temple', 'caves', 'storm'];
  regions.forEach(r => {
    const slot = document.createElement('div');
    slot.className = 'crystal-slot' + (state.crystals[r] ? ' found' : '');
    slot.innerHTML = state.crystals[r] ? crystalIcons[r] : '🔒';
    const label = document.createElement('span');
    label.className = 'crystal-label';
    label.textContent = crystalNames[r].split(' of ')[1];
    slot.appendChild(label);
    container.appendChild(slot);
  });
}

function updateDarkness() {
  const found = Object.values(state.crystals).filter(v => v).length;
  const overlay = document.getElementById('darkness-overlay');
  if (found >= 3) {
    overlay.classList.add('light');
  }
  if (found >= 5) {
    showVictory();
  }
}

function enterRegion(region) {
  if (state.crystals[region]) {
    showNotification('Crystal already collected!');
    return;
  }
  state.currentRegion = region;
  const story = stories[region];
  showStory(story.intro);
  showChoices(story.choices);
}

function showStory(text) {
  document.getElementById('story-text').innerHTML = text;
  document.getElementById('story-choices').innerHTML = '';
}

function showChoices(choices) {
  const container = document.getElementById('story-choices');
  container.innerHTML = '';
  choices.forEach(choice => {
    const btn = document.createElement('button');
    btn.className = 'choice-btn';
    btn.textContent = choice.text;
    btn.onclick = choice.action;
    container.appendChild(btn);
  });
}

function showNotification(text) {
  const notif = document.createElement('div');
  notif.className = 'notification';
  notif.textContent = text;
  document.body.appendChild(notif);
  setTimeout(() => notif.remove(), 3000);
}

function heal(amount) {
  state.health = Math.min(state.maxHealth, state.health + amount);
  state.mana = Math.min(state.maxMana, state.mana + Math.floor(amount / 2));
  updateHUD();
}

function damage(amount) {
  state.health = Math.max(0, state.health - amount);
  updateHUD();
  if (state.health <= 0) {
    showStory(`<span class="narration">Darkness consumes you... But the ancient guardians will not let their quest end here. A warm light envelops you, restoring your strength. You rise again, stronger and more determined.</span>`);
    setTimeout(() => {
      state.health = 50;
      state.mana = 50;
      updateHUD();
      showNotification('Revived by ancient magic!');
    }, 2000);
  }
}

