function showScene(type, region) {
  document.getElementById('scene-view').classList.add('active');
  const content = document.getElementById('scene-content');
  content.innerHTML = '';

  if (type === 'memory') {
    content.innerHTML = `
      <div class="scene-title">🌲 The Ancient Altar</div>
      <div class="scene-description">Match all pairs of runes to break the enchantment protecting the Crystal of Light!</div>
      <div class="memory-grid" id="memory-grid"></div>
      <div id="memory-status" style="margin-top:15px; font-family:'Cinzel',serif; color:#8877aa;"></div>
    `;
  } else if (type === 'rune') {
    content.innerHTML = `
      <div class="scene-title">🔥 The Fire Rune Chamber</div>
      <div class="scene-description">Click the runes in the correct order to open the chamber door!</div>
      <div class="rune-puzzle" id="rune-puzzle"></div>
      <div id="rune-status" style="margin-top:15px; font-family:'Cinzel',serif; color:#8877aa;"></div>
    `;
  } else if (type === 'combat') {
    content.innerHTML = `
      <div class="scene-title">⚔️ Battle!</div>
      <div class="combat-arena" id="combat-arena"></div>
      <div class="combat-actions" id="combat-actions"></div>
      <div id="combat-log" style="margin-top:15px; font-size:0.85rem; color:#8877aa; text-align:center;"></div>
    `;
  }
}

function exitScene() {
  document.getElementById('scene-view').classList.remove('active');
  state.currentRegion = null;
}

// Memory Game
function initMemoryGame() {
  const symbols = ['🌿', '🌿', '🌸', '🌸', '🍃', '🍃', '🌺', '🌺', '🌻', '🌻', '🍂', '🍂', '🌾', '🌾', '🍀', '🍀'];
  let cards = symbols.sort(() => Math.random() - 0.5);
  let flipped = [];
  let matched = 0;
  const grid = document.getElementById('memory-grid');

  cards.forEach((sym, i) => {
    const card = document.createElement('div');
    card.className = 'memory-card';
    card.dataset.symbol = sym;
    card.dataset.index = i;
    card.textContent = '?';
    card.onclick = () => {
      if (flipped.length >= 2 || card.classList.contains('flipped') || card.classList.contains('matched')) return;
      card.classList.add('flipped');
      card.textContent = sym;
      flipped.push(card);

      if (flipped.length === 2) {
        if (flipped[0].dataset.symbol === flipped[1].dataset.symbol) {
          flipped.forEach(c => c.classList.add('matched'));
          flipped = [];
          matched += 2;
          document.getElementById('memory-status').textContent = `Pairs found: ${matched / 2} / 8`;
          if (matched === 16) {
            setTimeout(() => collectCrystal('forest'), 800);
          }
        } else {
          setTimeout(() => {
            flipped.forEach(c => {
              c.classList.remove('flipped');
              c.textContent = '?';
            });
            flipped = [];
          }, 800);
        }
      }
    };
    grid.appendChild(card);
  });
}

// Rune Puzzle
function runePuzzle(type, region) {
  showScene('rune', region);
  const runes = ['🔥', '💧', '🌍', '💨', '☀️', '🌙'];
  const correctOrder = runes.sort(() => Math.random() - 0.5).slice(0, 4);
  const displayOrder = [...correctOrder].sort(() => Math.random() - 0.5);
  let playerOrder = [];
  let attempts = 0;

  const puzzle = document.getElementById('rune-puzzle');
  displayOrder.forEach((rune, i) => {
    const stone = document.createElement('div');
    stone.className = 'rune-stone';
    stone.textContent = rune;
    stone.onclick = () => {
      if (stone.classList.contains('correct')) return;
      stone.classList.add('selected');
      playerOrder.push(rune);

      const idx = playerOrder.length - 1;
      if (playerOrder[idx] === correctOrder[idx]) {
        stone.classList.remove('selected');
        stone.classList.add('correct');
        if (playerOrder.length === 4) {
          document.getElementById('rune-status').textContent = 'The door opens!';
          setTimeout(() => collectCrystal(region), 1000);
        }
      } else {
        stone.classList.remove('selected');
        stone.classList.add('wrong');
        attempts++;
        document.getElementById('rune-status').textContent = `Incorrect! Attempts: ${attempts}`;
        setTimeout(() => {
          stone.classList.remove('wrong');
          playerOrder = [];
        }, 500);
      }
    };
    puzzle.appendChild(stone);
  });
}

// Combat System
function startCombat(enemy) {
  showScene('combat', state.currentRegion);
  let playerHP, playerMaxHP, enemyHP, enemyMaxHP, enemyName, enemySprite, enemyDamage;

  if (enemy === 'dragon') {
    enemyName = 'Shadow Dragon';
    enemySprite = '🐉';
    enemyMaxHP = 60;
    enemyHP = 60;
    enemyDamage = 15;
    playerMaxHP = state.health;
  } else if (enemy === 'golem') {
    enemyName = 'Stone Golem';
    enemySprite = '🗿';
    enemyMaxHP = 50;
    enemyHP = 50;
    enemyDamage = 12;
    playerMaxHP = state.health;
  }
  playerHP = playerMaxHP;

  function renderCombat() {
    const arena = document.getElementById('combat-arena');
    arena.innerHTML = `
      <div class="combatant">
        <div class="combatant-sprite" id="player-sprite">🧙</div>
        <div style="font-family:'Cinzel',serif; font-size:0.8rem; color:#f0c040;">You</div>
        <div class="combat-hp-bar"><div class="combat-hp-fill" style="width:${playerHP/playerMaxHP*100}%"></div></div>
        <div style="font-size:0.75rem; color:#8877aa;">${playerHP}/${playerMaxHP}</div>
      </div>
      <div style="font-size:2rem; color:#444;">⚔️</div>
      <div class="combatant">
        <div class="combatant-sprite" id="enemy-sprite">${enemySprite}</div>
        <div style="font-family:'Cinzel',serif; font-size:0.8rem; color:#ff4444;">${enemyName}</div>
        <div class="combat-hp-bar"><div class="combat-hp-fill" style="width:${enemyHP/enemyMaxHP*100}%"></div></div>
        <div style="font-size:0.75rem; color:#8877aa;">${enemyHP}/${enemyMaxHP}</div>
      </div>
    `;
  }

  renderCombat();

  const actions = document.getElementById('combat-actions');
  actions.innerHTML = `
    <button class="combat-btn" onclick="combatAttack()">⚔️ Attack</button>
    <button class="combat-btn" onclick="combatDefend()">🛡️ Defend</button>
    <button class="combat-btn" onclick="combatMagic()">✨ Magic</button>
  `;

  window.combatState = { playerHP, playerMaxHP, enemyHP, enemyMaxHP, enemyName, enemySprite, enemyDamage, playerDefending: false };
}

function combatAttack() {
  const cs = window.combatState;
  const dmg = Math.floor(Math.random() * 12) + 8;
  cs.enemyHP = Math.max(0, cs.enemyHP - dmg);
  logCombat(`You strike ${cs.enemyName} for ${dmg} damage!`);
  animateSprite('player-sprite', 'attacking');
  setTimeout(() => animateSprite('enemy-sprite', 'hit'), 300);
  renderCombat();
  checkCombatEnd();
}

function combatDefend() {
  const cs = window.combatState;
  cs.playerDefending = true;
  logCombat('You raise your guard!');
  setTimeout(() => enemyTurn(), 600);
}

function combatMagic() {
  const cs = window.combatState;
  if (state.mana < 20) {
    logCombat('Not enough mana!');
    return;
  }
  state.mana -= 20;
  updateHUD();
  const dmg = Math.floor(Math.random() * 15) + 15;
  cs.enemyHP = Math.max(0, cs.enemyHP - dmg);
  logCombat(`You unleash magic on ${cs.enemyName} for ${dmg} damage!`);
  animateSprite('player-sprite', 'attacking');
  setTimeout(() => animateSprite('enemy-sprite', 'hit'), 300);
  renderCombat();
  checkCombatEnd();
}

function enemyTurn() {
  const cs = window.combatState;
  let dmg = Math.floor(Math.random() * cs.enemyDamage) + 5;
  if (cs.playerDefending) {
    dmg = Math.floor(dmg / 2);
    cs.playerDefending = false;
  }
  cs.playerHP = Math.max(0, cs.playerHP - dmg);
  logCombat(`${cs.enemyName} attacks for ${dmg} damage!`);
  animateSprite('enemy-sprite', 'attacking');
  setTimeout(() => animateSprite('player-sprite', 'hit'), 300);
  renderCombat();
  checkCombatEnd();
}

function checkCombatEnd() {
  const cs = window.combatState;
  if (cs.enemyHP <= 0) {
    logCombat(`🎉 ${cs.enemyName} has been defeated!`);
    document.getElementById('combat-actions').innerHTML = '';
    setTimeout(() => {
      exitScene();
      if (state.currentRegion === 'mountains') {
        runePuzzle('fire', 'mountains');
      } else if (state.currentRegion === 'caves') {
        runePuzzle('earth', 'caves');
      }
    }, 2000);
  } else if (cs.playerHP <= 0) {
    logCombat('💀 You have been defeated...');
    document.getElementById('combat-actions').innerHTML = '';
    setTimeout(() => {
      exitScene();
      state.health = 30;
      state.mana = 30;
      updateHUD();
      showStory(`<span class="narration">Darkness takes you... But the ancient guardians will not let their quest end here. You awaken at the entrance, battered but alive. The quest continues.</span>`);
    }, 2000);
  } else {
    setTimeout(() => enemyTurn(), 800);
  }
}

function animateSprite(id, anim) {
  const el = document.getElementById(id);
  if (el) {
    el.classList.add(anim);
    setTimeout(() => el.classList.remove(anim), 500);
  }
}

function logCombat(text) {
