game.cropsPlanted++;
game.score += 10;
}
break;
case 'water':
if (type === TILE_PLANTED || type === TILE_WATERED || type === TILE_FERTILIZED || type === TILE_GROWN) {
if (!field.watered) {
field.type = TILE_WATERED;
