}

function updateTractor() {
const t = game.tractor;
let moveX = 0, moveY = 0;

if (keys['arrowleft'] || keys['a']) { moveX = -1; t.dir = 3; }
if (keys['arrowright'] || keys['d']) { moveX = 1; t.dir = 1; }
if (keys['arrowup'] || keys['w']) { moveY = -1; t.dir = 0; }
if (keys['arrowdown'] || keys['s']) { moveY = 1; t.dir = 2; }

const speed = Math.sqrt(moveX * moveX + moveY * moveY) > 0 ? t.maxSpeed : 0;
t.speed = speed;

if (speed > 0) {
const newX = t.x + moveX * speed * 0.15;
const newY = t.y + moveY * speed * 0.15;

const checkX = Math.floor(newX);
const checkY = Math.floor(newY);

if (checkX >= 0 && checkX < COLS && checkY >= 0 && checkY < ROWS) {
const tile = game.fields[checkY][checkX];
if (tile.type !== TILE_TREE && tile.type !== TILE_WATER && tile.type !== TILE_BARN) {
t.x = newX;
t.y = newY;
}
}
}

// Fuel consumption
if (speed > 0) {
game.fuel = Math.max(0, game.fuel - 0.005);
}

// Check for auto-use when on correct tile
if (keys[' ']) {
useTool();
}
}

function updateCrops() {
for (let y = 0; y < ROWS; y++) {
for (let x = 0; x < COLS; x++) {
const field = game.fields[y][x];
if (field.type === TILE_PLANTED || field.type === TILE_WATERED || field.type === TILE_FERTILIZED) {
field.growthStage += 0.005;
if (field.watered) field.growthStage += 0.003;
if (field.fertilized) field.growthStage += 0.005;

if (field.growthStage >= CROP_GROW_TIME[field.cropType] || field.growthStage >= 5) {
field.type = TILE_GROWN;
field.growthStage = 5;
addParticles(x * TILE + TILE/2, y * TILE + TILE/2, '#228B22', 4);
} else if (field.growthStage >= 3 && field.type === TILE_PLANTED) {
field.type = TILE_WATERED;
} else if (field.growthStage >= 2 && field.type === TILE_WATERED) {
field.type = TILE_FERTILIZED;
}
}
}
}
}

function updateParticles() {
game.particles = game.particles.filter(p => {
p.x += p.vx;
p.y += p.vy;
p.vy += 0.1;
p.life--;
return p.life > 0;
});
game.floatingTexts = game.floatingTexts.filter(ft => {
ft.y += ft.vy;
ft.life--;
return ft.life > 0;
});
}

function updateClouds() {
game.clouds.forEach(c => {
c.x += c.speed;
if (c.x > canvas.width + 100) c.x = -c.w;
});
}

function updateWeather() {
game.weatherTimer++;
