y: -10,
speed: 3 + Math.random() * 3,
life: 100
});
}
game.rainDrops = game.rainDrops.filter(r => {
r.y += r.speed;
r.life--;
return r.life > 0 && r.y < canvas.height;
});
}

function drawTile(x, y, field) {
const px = x * TILE;
const py = y * TILE;

switch (field.type) {
case TILE_GRASS:
ctx.fillStyle = '#4a7c3f';
