ctx.fillStyle = '#3d6b34';
for (let i = 0; i < 3; i++) {
const gx = px + ((x * 7 + y * 13 + i * 11) % 30) + 5;
const gy = py + ((x * 11 + y * 7 + i * 17) % 30) + 5;
ctx.fillRect(gx, gy, 2, 4);
}
break;

case TILE_SOIL:
ctx.fillStyle = '#8B6914';
ctx.fillRect(px, py, TILE, TILE);
ctx.fillStyle = '#7a5c12';
for (let i = 0; i < 4; i++) {
const sx = px + ((x * 5 + y * 11 + i * 13) % 32) + 4;
const sy = py + ((x * 9 + y * 5 + i * 7) % 32) + 4;
ctx.fillRect(sx, sy, 8, 2);
}
break;

case TILE_PLANTED:
ctx.fillStyle = '#8B6914';
ctx.fillRect(px, py, TILE, TILE);
// Seeds
ctx.fillStyle = '#228B22';
const seedColor = CROP_COLORS[field.cropType] || '#FFD700';
for (let i = 0; i < 3; i++) {
const sx = px + 8 + i * 10;
const sy = py + 15 + (i % 2) * 8;
ctx.beginPath();
ctx.arc(sx, sy, 3, 0, Math.PI * 2);
ctx.fillStyle = seedColor;
ctx.fill();
}
break;

case TILE_WATERED:
ctx.fillStyle = '#8B6914';
ctx.fillRect(px, py, TILE, TILE);
ctx.fillStyle = 'rgba(68, 136, 255, 0.3)';
ctx.fillRect(px + 2, py + 2, TILE - 4, TILE - 4);
ctx.fillStyle = '#228B22';
const sw = CROP_COLORS[field.cropType] || '#FFD700';
for (let i = 0; i < 3; i++) {
const sx = px + 8 + i * 10;
const sy = py + 12 + (i % 2) * 8;
ctx.beginPath();
ctx.arc(sx, sy, 4, 0, Math.PI * 2);
ctx.fillStyle = sw;
ctx.fill();
}
break;

case TILE_FERTILIZED:
ctx.fillStyle = '#8B6914';
ctx.fillRect(px, py, TILE, TILE);
ctx.fillStyle = 'rgba(255, 215, 0, 0.2)';
ctx.fillRect(px + 2, py + 2, TILE - 4, TILE - 4);
const fw = CROP_COLORS[field.cropType] || '#FFD700';
for (let i = 0; i < 3; i++) {
const sx = px + 8 + i * 10;
const sy = py + 10 + (i % 2) * 8;
ctx.beginPath();
ctx.arc(sx, sy, 5, 0, Math.PI * 2);
ctx.fillStyle = fw;
ctx.fill();
}
break;

case TILE_GROWN:
ctx.fillStyle = '#8B6914';
ctx.fillRect(px, py, TILE, TILE);
const gw = CROP_COLORS[field.cropType] || '#FFD700';
// Full crop
const cx = px + TILE / 2;
const cy = py + TILE / 2;
ctx.fillStyle = '#228B22';
ctx.fillRect(cx - 2, cy - 5, 4, 15);
ctx.beginPath();
ctx.arc(cx, cy - 5, 8, 0, Math.PI * 2);
ctx.fillStyle = gw;
ctx.fill();
ctx.strokeStyle = '#1a6b1a';
ctx.lineWidth = 1;
ctx.stroke();
// Glow
ctx.beginPath();
ctx.arc(cx, cy - 5, 12, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(255, 215, 0, 0.15)';
ctx.fill();
break;

case TILE_HARVESTED:
ctx.fillStyle = '#8B6914';
ctx.fillRect(px, py, TILE, TILE);
ctx.fillStyle = '#7a5c12';
for (let i = 0; i < 2; i++) {
ctx.fillRect(px + 10 + i * 15, py + 20, 6, 3);
}
break;

case TILE_BARN:
ctx.fillStyle = '#8B0000';
ctx.fillRect(px, py, TILE, TILE);
ctx.fillStyle = '#a00000';
ctx.fillRect(px + 2, py + 2, TILE - 4, TILE - 4);
// Barn door
ctx.fillStyle = '#654321';
ctx.fillRect(px + TILE/2 - 5, py + TILE - 15, 10, 13);
break;

case TILE_PATH:
ctx.fillStyle = '#c4a45a';
ctx.fillRect(px, py, TILE, TILE);
ctx.fillStyle = '#b89848';
ctx.fillRect(px + 5, py + 5, TILE - 10, TILE - 10);
break;

case TILE_TREE:
ctx.fillStyle = '#4a7c3f';
ctx.fillRect(px, py, TILE, TILE);
// Trunk
ctx.fillStyle = '#654321';
ctx.fillRect(px + 16, py + 20, 8, 20);
// Canopy
ctx.beginPath();
ctx.arc(px + 20, py + 16, 14, 0, Math.PI * 2);
ctx.fillStyle = '#2d5a1e';
ctx.fill();
ctx.beginPath();
ctx.arc(px + 16, py + 12, 10, 0, Math.PI * 2);
ctx.fillStyle = '#3a7a28';
ctx.fill();
break;

case TILE_WATER:
ctx.fillStyle = '#2266aa';
ctx.fillRect(px, py, TILE, TILE);
ctx.fillStyle = 'rgba(100, 180, 255, 0.4)';
const waveOffset = Date.now() / 500;
ctx.fillRect(px + 5, py + 10 + Math.sin(waveOffset) * 3, 30, 3);
ctx.fillRect(px + 10, py + 25 + Math.sin(waveOffset + 1) * 3, 25, 3);
break;
}
}

function drawTractor() {
const t = game.tractor;
const px = t.x * TILE;
const py = t.y * TILE;
const cx = px + TILE / 2;
const cy = py + TILE / 2;

ctx.save();
ctx.translate(cx, cy);
ctx.rotate(t.dir * Math.PI / 2);

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.fillRect(-16, -12, 32, 30);

// Body
ctx.fillStyle = '#cc3333';
ctx.fillRect(-14, -10, 28, 22);
ctx.fillStyle = '#dd4444';
ctx.fillRect(-12, -8, 24, 18);

// Cabin
ctx.fillStyle = '#222';
ctx.fillRect(-6, -10, 14, 12);
ctx.fillStyle = '#88ccff';
ctx.fillRect(-4, -9, 10, 8);

// Wheels
ctx.fillStyle = '#333';
ctx.fillRect(-16, -12, 6, 8);
ctx.fillRect(-16, 6, 6, 8);
ctx.fillRect(10, -12, 6, 8);
ctx.fillRect(10, 6, 6, 8);

// Wheel details
ctx.fillStyle = '#555';
ctx.fillRect(-15, -11, 4, 6);
ctx.fillRect(-15, 7, 4, 6);
ctx.fillRect(11, -11, 4, 6);
ctx.fillRect(11, 7, 4, 6);

// Exhaust
if (t.speed > 0) {
ctx.fillStyle = 'rgba(100,100,100,0.5)';
for (let i = 0; i < 3; i++) {
ctx.beginPath();
ctx.arc(18 + i * 5, -5 + Math.sin(Date.now() / 100 + i) * 2, 2 + i, 0, Math.PI * 2);
ctx.fill();
}
}

ctx.restore();
}

function drawParticles() {
game.particles.forEach(p => {
const alpha = p.life / p.maxLife;
ctx.globalAlpha = alpha;
ctx.fillStyle = p.color;
ctx.beginPath();
ctx.arc(p.x, p.y, p.size * alpha, 0, Math.PI * 2);
ctx.fill();
});
ctx.globalAlpha = 1;
}

function drawFloatingTexts() {
game.floatingTexts.forEach(ft => {
const alpha = ft.life / 60;
ctx.globalAlpha = alpha;
ctx.fillStyle = ft.color;
ctx.font = 'bold 14px Arial';
ctx.textAlign = 'center';
ctx.strokeStyle = '#000';
ctx.lineWidth = 3;
ctx.strokeText(ft.text, ft.x + TILE/2, ft.y);
ctx.fillText(ft.text, ft.x + TILE/2, ft.y);
});
ctx.globalAlpha = 1;
}

function drawClouds() {
game.clouds.forEach(c => {
ctx.fillStyle = game.weather === 'rain' ? 'rgba(80,80,100,0.7)' : 'rgba(255,255,255,0.6)';
ctx.beginPath();
ctx.ellipse(c.x, c.y, c.w / 2, 15, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(c.x - c.w * 0.25, c.y + 5, c.w * 0.3, 12, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(c.x + c.w * 0.25, c.y + 3, c.w * 0.35, 13, 0, 0, Math.PI * 2);
ctx.fill();
});
}

function drawRain() {
ctx.strokeStyle = 'rgba(150, 180, 255, 0.4)';
ctx.lineWidth = 1;
game.rainDrops.forEach(r => {
ctx.beginPath();
ctx.moveTo(r.x, r.y);
ctx.lineTo(r.x - 1, r.y + 8);
ctx.stroke();
});
}

function drawMinimap() {
miniCtx.fillStyle = '#2d5a1e';
miniCtx.fillRect(0, 0, 160, 120);

const scaleX = 160 / COLS;
const scaleY = 120 / ROWS;

for (let y = 0; y < ROWS; y++) {
for (let x = 0; x < COLS; x++) {
const field = game.fields[y][x];
switch (field.type) {
case TILE_GRASS: miniCtx.fillStyle = '#4a7c3f'; break;
case TILE_SOIL: miniCtx.fillStyle = '#8B6914'; break;
case TILE_PLANTED: miniCtx.fillStyle = '#228B22'; break;
case TILE_WATERED: miniCtx.fillStyle = '#4488FF'; break;
case TILE_FERTILIZED: miniCtx.fillStyle = '#FFD700'; break;
case TILE_GROWN: miniCtx.fillStyle = '#FFA500'; break;
case TILE_HARVESTED: miniCtx.fillStyle = '#a08050'; break;
case TILE_BARN: miniCtx.fillStyle = '#8B0000'; break;
case TILE_PATH: miniCtx.fillStyle = '#c4a45a'; break;
case TILE_TREE: miniCtx.fillStyle = '#1a4a10'; break;
case TILE_WATER: miniCtx.fillStyle = '#2266aa'; break;
default: miniCtx.fillStyle = '#4a7c3f';
}
miniCtx.fillRect(x * scaleX, y * scaleY, scaleX + 0.5, scaleY + 0.5);
}
}

// Tractor
miniCtx.fillStyle = '#ff0000';
miniCtx.fillRect(game.tractor.x * scaleX - 2, game.tractor.y * scaleY - 2, 5, 5);
}

function drawBackground() {
// Sky gradient at top
const grad = ctx.createLinearGradient(0, 0, 0, 30);
grad.addColorStop(0, '#87CEEB');
grad.addColorStop(1, 'transparent');
ctx.fillStyle = grad;
ctx.fillRect(0, 0, canvas.width, 30);
}

function drawDayNightOverlay() {
const dayProgress = game.dayTimer / game.dayLength;
let alpha = 0;
if (dayProgress > 0.8) {
alpha = (dayProgress - 0.8) / 0.2 * 0.3;
}
if (alpha > 0) {
ctx.fillStyle = `rgba(0, 0, 40, ${alpha})`;
ctx.fillRect(0, 0, canvas.width, canvas.height);
}
}

let lastTime = 0;
function gameLoop(timestamp) {
if (!game.running) return;

const dt = timestamp - lastTime;
lastTime = timestamp;

game.dayTimer += dt / 1000;
if (game.dayTimer >= game.dayLength) {
endDay();
return;
}

updateTractor();
updateCrops();
updateParticles();
updateClouds();
updateWeather();

// Screen shake
game.shakeX = (Math.random() - 0.5) * 2;
game.shakeY = (Math.random() - 0.5) * 2;

ctx.save();
ctx.translate(game.shakeX, game.shakeY);

drawBackground();
drawClouds();

// Draw tiles
for (let y = 0; y < ROWS; y++) {
for (let x = 0; x < COLS; x++) {
drawTile(x, y, game.fields[y][x]);
}
}

drawParticles();
drawTractor();
drawFloatingTexts();
drawRain();
drawDayNightOverlay();

ctx.restore();

drawMinimap();

requestAnimationFrame(gameLoop);
}

// Initial render
ctx.fillStyle = '#4a7c3f';
ctx.fillRect(0, 0, canvas.width, canvas.height);
ctx.fillStyle = '#f0e6d0';
ctx.font = '24px Arial';
ctx.textAlign = 'center';
ctx.fillText('🚜 Tractor Farm Simulator', canvas.width/2, canvas.height/2);
</script>
</body>
