/* Notification */
.notification { position: fixed; top: 60px; left: 50%; transform: translateX(-50%); background: #1a1a2e; border: 1px solid #4dabf7; border-radius: 12px; padding: 10px 20px; font-size: 0.85em; z-index: 300; animation: slideDown 0.3s ease, fadeOut 0.3s ease 2s forwards; white-space: nowrap; }
@keyframes slideDown { from { top: 40px; opacity: 0; } to { top: 60px; opacity: 1; } }
@keyframes fadeOut { to { opacity: 0; transform: translateX(-50%) translateY(-10px); } }

/* Achievements */
.achievement { background: #1a1a2e; border-radius: 12px; padding: 12px; margin-bottom: 8px; display: flex; align-items: center; gap: 10px; border: 1px solid #2a2a4a; }
.achievement.unlocked { border-color: #ffa500; }
.achievement .ach-icon { font-size: 1.5em; }
.achievement .ach-name { font-weight: 700; font-size: 0.85em; }
.achievement .ach-desc { color: #888; font-size: 0.7em; }
.achievement.locked { opacity: 0.4; }

/* Scrollbar */
::-webkit-scrollbar { width: 4px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #333; border-radius: 2px; }

/* Level up animation */
@keyframes levelUp { 0% { transform: scale(1); } 50% { transform: scale(1.1); } 100% { transform: scale(1); } }
.level-up-anim { animation: levelUp 0.5s ease; }

/* Tab content */
.tab-content { display: none; }
.tab-content.active { display: block; }

/* Inventory */
.inv-item { display: flex; align-items: center; gap: 10px; padding: 10px; background: #1a1a2e; border-radius: 10px; margin-bottom: 6px; }
.inv-icon { font-size: 1.5em; }
.inv-name { flex: 1; font-size: 0.85em; font-weight: 600; }
.inv-qty { color: #888; font-size: 0.8em; }

/* Education */
.edu-card { background: #1a1a2e; border-radius: 14px; padding: 16px; margin-bottom: 10px; border: 1px solid #2a2a4a; cursor: pointer; }
.edu-card .edu-icon { font-size: 1.5em; }
.edu-card .edu-name { font-weight: 700; margin: 4px 0; }
.edu-card .edu-cost { color: #ffa500; font-size: 0.85em; }
.edu-card .edu-bonus { color: #69db7c; font-size: 0.75em; margin-top: 4px; }

/* Random event banner */
.event-banner { background: linear-gradient(135deg, #2a1a3e, #1a2a3e); border-radius: 14px; padding: 16px; margin-bottom: 12px; border: 1px solid #3a3a5a; }
.event-banner .event-banner-title { font-weight: 700; margin-bottom: 6px; }
.event-banner .event-banner-desc { color: #aaa; font-size: 0.85em; line-height: 1.4; }
.event-banner .event-banner-choices { display: flex; gap: 8px; margin-top: 10px; }
.event-banner .event-banner-choices button { flex: 1; padding: 10px; border-radius: 10px; border: none; font-weight: 700; font-size: 0.85em; cursor: pointer; }
</style>
</head>
