}

function startGame() {
  const name = document.getElementById('player-name').value.trim() || 'Alex';
  const gender = document.querySelector('.gender-btn.selected').dataset.gender;
  const birthplace = document.getElementById('birthplace').value;
  const str = parseInt(document.getElementById('alloc-str').value);
  const int = parseInt(document.getElementById('alloc-int').value);
  const cha = parseInt(document.getElementById('alloc-cha').value);
  const hp = parseInt(document.getElementById('alloc-hp').value);

  G = {
    name, gender, birthplace,
    age: 0,
    money: 100,
    level: 1,
    xp: 0,
    xpNeeded: 100,
    stats: {
      health: hp * 10,
      intelligence: int * 10,
      charisma: cha * 10,
      strength: str * 10,
      happiness: 70,
      energy: 100
    },
    career: null,
    careerLevel: 0,
    careerXP: 0,
    relationships: JSON.parse(JSON.stringify(RELATIONSHIPS)),
    education: [],
    inventory: [],
    achievements: JSON.parse(JSON.stringify(ACHIEVEMENTS)),
    events: [],
    totalEarned: 0,
    totalSpent: 0,
    gamesPlayed: 0,
    isAlive: true,
    isMarried: false,
    hasPartner: false,
    year: 2024
  };

