function updateUI() {
  document.getElementById('display-name').textContent = G.name;
  document.getElementById('display-age').textContent = `Âge: ${G.age} ans`;
  document.getElementById('display-money').textContent = formatMoney(G.money);
  document.getElementById('display-level').textContent = `Nv.${G.level}`;

  // Stats
  const stats = G.stats;
  updateStatBar('health', stats.health);
  updateStatBar('intelligence', stats.intelligence);
  updateStatBar('charisma', stats.charisma);
  updateStatBar('strength', stats.strength);
  updateStatBar('happiness', stats.happiness);
  updateStatBar('energy', stats.energy);

  // XP
  const xpPct = Math.min(100, (G.xp / G.xpNeeded) * 100);
  document.getElementById('xp-bar').style.width = xpPct + '%';
  document.getElementById('xp-current').textContent = `${G.xp} XP`;
  document.getElementById('xp-next').textContent = `${G.xpNeeded} XP`;

  // Career info
  if (G.career) {
    const c = CAREERS.find(c => c.id === G.career);
    document.getElementById('current-job').textContent = c ? c.name : 'Sans emploi';
    const salary = c ? Math.round(c.salary * (1 + G.careerLevel * 0.1)) : 0;
    document.getElementById('current-salary').textContent = formatMoney(salary) + '/an';
    document.getElementById('current-level').textContent = G.careerLevel;
  } else {
    document.getElementById('current-job').textContent = 'Sans emploi';
    document.getElementById('current-salary').textContent = '0€';
    document.getElementById('current-level').textContent = '0';
  }

  // Energy check for activities
  document.querySelectorAll('.activity-card').forEach(card => {
    if (G.stats.energy < 10 && !card.onclick.toString().includes('sleep')) {
      card.classList.add('disabled');
    } else {
      card.classList.remove('disabled');
    }
  });

  // Check achievements
  checkAchievements();
}

function updateStatBar(stat, value) {
  value = Math.max(0, Math.min(100, value));
  document.getElementById('bar-' + stat).style.width = value + '%';
  document.getElementById('val-' + stat).textContent = Math.round(value);
}

function formatMoney(n) {
  if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M€';
  if (n >= 1000) return (n / 1000).toFixed(1) + 'k€';
  return Math.round(n) + '€';
}

function switchTab(tab) {
  document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('tab-' + tab).classList.add('active');
  event.currentTarget.classList.add('active');
}

function addLog(ageText, text, cls, extra) {
  const log = document.getElementById('event-log');
  const div = document.createElement('div');
  div.className = 'event-item';
  div.innerHTML = `<span class="${ageText}">[${ageText.replace('event-age','')}]</span> <span class="${cls}">${text}</span>`;
  log.insertBefore(div, log.firstChild);
  if (log.children.length > 50) log.removeChild(log.lastChild);
}

function doActivity(type) {
  if (!G.isAlive) return;

  switch(type) {
    case 'work':
      if (G.stats.energy < 20) { notify('Pas assez d\'énergie !'); return; }
      if (!G.career) { notify('Vous n\'avez pas de travail !'); return; }
      G.stats.energy -= 20;
      const c = CAREERS.find(c => c.id === G.career);
      const salary = c ? Math.round(c.salary * (1 + G.careerLevel * 0.1) / 52) : 0;
      const bonus = Math.round(salary * (G.stats.intelligence / 100) * 0.1);
      const earned = salary + bonus;
      G.money += earned;
      G.totalEarned += earned;
      G.careerXP += 10 + Math.round(G.stats.intelligence / 10);
      G.xp += 15;
      G.stats.happiness = Math.max(0, G.stats.happiness - 2);
      if (G.careerXP >= 100) {
        G.careerXP -= 100;
        G.careerLevel++;
        notify(`🎉 Promotion ! Niveau ${G.careerLevel}`);
        addLog('event-age', `Promotion au niveau ${G.careerLevel} !`, 'event-positive', '');
      }
      addLog('event-age', `Travail : +${formatMoney(earned)}`, 'event-positive', '');
      gainXP(15);
      break;

    case 'study':
      if (G.stats.energy < 15) { notify('Pas assez d\'énergie !'); return; }
      if (G.age < 5) { notify('Trop jeune !'); return; }
      G.stats.energy -= 15;
      const intGain = 2 + Math.round(Math.random() * 3);
      G.stats.intelligence = Math.min(100, G.stats.intelligence + intGain);
      G.xp += 10;
      G.stats.happiness = Math.max(0, G.stats.happiness - 1);
      addLog('event-age', `Étude : +${intGain} Intelligence`, 'event-positive', '');
      gainXP(10);
      break;

    case 'exercise':
      if (G.stats.energy < 20) { notify('Pas assez d\'énergie !'); return; }
      G.stats.energy -= 20;
      const strGain = 1 + Math.round(Math.random() * 2);
      const hpGain = 1 + Math.round(Math.random() * 2);
      G.stats.strength = Math.min(100, G.stats.strength + strGain);
      G.stats.health = Math.min(100, G.stats.health + hpGain);
      G.stats.happiness = Math.min(100, G.stats.happiness + 2);
      G.xp += 8;
      addLog('event-age', `Sport : +${strGain} Force, +${hpGain} Santé`, 'event-positive', '');
      gainXP(8);
      break;

    case 'social':
      if (G.stats.energy < 10) { notify('Pas assez d\'énergie !'); return; }
      if (G.money < 10) { notify('Pas assez d\'argent !'); return; }
      G.stats.energy -= 10;
      G.money -= 10;
      const chaGain = 1 + Math.round(Math.random() * 2);
      G.stats.charisma = Math.min(100, G.stats.charisma + chaGain);
      G.stats.happiness = Math.min(100, G.stats.happiness + 5);
      G.relationships.find(r => r.id === 'amis').affinity = Math.min(100, G.relationships.find(r => r.id === 'amis').affinity + 3);
      G.xp += 5;
      addLog('event-age', `Social : +${chaGain} Charisme, +5 Bonheur`, 'event-positive', '');
      gainXP(5);
      break;

    case 'meditate':
      if (G.stats.energy < 5) { notify('Trop fatigué...'); return; }
      G.stats.energy -= 5;
      G.stats.happiness = Math.min(100, G.stats.happiness + 3);
      G.stats.health = Math.min(100, G.stats.health + 1);
      G.xp += 3;
      addLog('event-age', 'Méditation : +3 Bonheur', 'event-neutral', '');
      gainXP(3);
      break;

    case 'sleep':
      G.stats.energy = 100;
      G.age++;
      G.year++;
      G.stats.happiness = Math.min(100, G.stats.happiness + 2);
      // Random age event
      checkAgeEvents();
      // Career salary
      if (G.career) {
        const c = CAREERS.find(c => c.id === G.career);
        const salary = c ? Math.round(c.salary * (1 + G.careerLevel * 0.1)) : 0;
        G.money += salary;
        G.totalEarned += salary;
        addLog('event-age', `Salaire annuel : +${formatMoney(salary)}`, 'event-positive', '');
      }
      addLog('event-age', `Joyeux anniversaire ! ${G.age} ans. +100 Énergie`, 'event-neutral', '');
      // Random event chance
      if (Math.random() < 0.35) {
        setTimeout(() => showRandomEvent(), 500);
      }
      break;
  }
  updateUI();
}

function checkAgeEvents() {
  // Education check
  EDUCATION.forEach(edu => {
    if (G.age >= edu.age && !G.education.includes(edu.id)) {
      // Auto-enroll in free education
      if (edu.cost === 0) {
        G.education.push(edu.id);
        applyEduBonus(edu);
        addLog('event-age', `🎓 ${edu.name} complété !`, 'event-positive', '');
      }
    }
  });

  // Partner chance
  if (G.age >= 16 && !G.hasPartner && Math.random() < 0.15) {
    G.hasPartner = true;
    G.relationships.find(r => r.id === 'amour').affinity = 50;
    addLog('event-age', '❤️ Vous avez trouvé l\'amour !', 'event-positive', '');
    notify('❤️ Nouvelle relation !');
  }

  // Marriage chance
  if (G.age >= 20 && G.hasPartner && !G.isMarried && G.relationships.find(r => r.id === 'amour').affinity >= 70 && Math.random() < 0.1) {
    G.isMarried = true;
    G.relationships.find(r => r.id === 'amour').affinity = 100;
    addLog('event-age', '💒 Vous vous êtes marié(e) !', 'event-positive', '');
    notify('💒 Mariage !');
  }

  // Death chance (very old)
  if (G.age >= 80) {
    const deathChance = (G.age - 80) * 0.02;
    if (Math.random() < deathChance) {
      G.isAlive = false;
      showModal('⚰️', 'Décès', `${G.name} est décédé(e) à l'âge de ${G.age} ans.\n\nArgent total gagné : ${formatMoney(G.totalEarned)}\nNiveau atteint : ${G.level}`, [{ text: 'Recommencer', action: () => location.reload() }]);
    }
  }

  // Health decline with age
  if (G.age > 50) {
    G.stats.health = Math.max(0, G.stats.health - (G.age - 50) * 0.5);
  }
}

function applyEduBonus(edu) {
  Object.keys(edu.bonus).forEach(stat => {
    G.stats[stat] = Math.min(100, G.stats[stat] + edu.bonus[stat]);
  });
}

