function showModal(icon, title, text, choices) {
  document.getElementById('modal-icon').textContent = icon;
  document.getElementById('modal-title').textContent = title;
  document.getElementById('modal-text').textContent = text;
  const choicesDiv = document.getElementById('modal-choices');
  choicesDiv.innerHTML = '';
  choices.forEach(c => {
    const btn = document.createElement('button');
    btn.className = 'btn btn-primary btn-sm';
    btn.textContent = c.text;
    btn.onclick = c.action;
    choicesDiv.appendChild(btn);
  });
  document.getElementById('modal-overlay').classList.add('active');
}

function closeModal() {
  document.getElementById('modal-overlay').classList.remove('active');
}

function gainXP(amount) {
  G.xp += amount;
  while (G.xp >= G.xpNeeded) {
    G.xp -= G.xpNeeded;
    G.level++;
    G.xpNeeded = Math.round(G.xpNeeded * 1.3);
    G.stats.energy = Math.min(100, G.stats.energy + 20);
    G.stats.happiness = Math.min(100, G.stats.happiness + 5);
    notify(`⭐ Niveau ${G.level} ! +20 Énergie`);
    addLog('event-age', `🎉 Niveau ${G.level} atteint !`, 'event-positive', '');
  }
}

function checkAchievements() {
  ACHIEVEMENTS.forEach(ach => {
    if (ach.unlocked) return;
    let unlocked = false;
    switch(ach.id) {
      case 'first_job': if (G.career) unlocked = true; break;
      case 'rich': if (G.money >= 1000000) unlocked = true; break;
      case 'fit': if (G.stats.strength >= 100) unlocked = true; break;
      case 'genius': if (G.stats.intelligence >= 100) unlocked = true; break;
      case 'charming': if (G.stats.charisma >= 100) unlocked = true; break;
      case 'love': if (G.hasPartner) unlocked = true; break;
      case 'married': if (G.isMarried) unlocked = true; break;
      case 'travel': if (G.inventory.filter(i => i.category === 'fun').length >= 3) unlocked = true; break;
      case 'old': if (G.age >= 80) unlocked = true; break;
      case 'dead': if (!G.isAlive) unlocked = true; break;
      case 'ceo': if (G.career === 'pdg') unlocked = true; break;
      case 'education': if (G.education.includes('master')) unlocked = true; break;
    }
    if (unlocked) {
      ach.unlocked = true;
      notify(`🏆 Réalisation : ${ach.name}`);
      addLog('event-age', `🏆 ${ach.name}`, 'event-positive', '');
    }
  });
}

function renderCareers() {
  const list = document.getElementById('career-list');
  list.innerHTML = '';
  CAREERS.forEach(c => {
    const isCurrent = G.career === c.id;
    const canApply = checkCareerReq(c);
    const div = document.createElement('div');
    div.className = `career-card ${isCurrent ? 'current' : ''}`;
    div.innerHTML = `
      <div style="display:flex;align-items:center;gap:10px;">
        <span class="career-icon">${c.icon}</span>
        <div style="flex:1;">
          <div class="career-name">${c.name}</div>
          <div class="career-salary">${formatMoney(c.salary)}/an</div>
          <div class="career-req">Req: ${Object.keys(c.req).map(k => `${k.charAt(0).toUpperCase()+k.slice(1)} ≥ ${c.req[k]}`).join(', ')}</div>
          ${isCurrent ? `<div class="career-level">⭐ Niveau ${G.careerLevel}</div>` : ''}
        </div>
      </div>
    `;
    if (!isCurrent) {
      div.onclick = () => applyCareer(c);
      if (!canApply) {
        div.style.opacity = '0.5';
      }
    }
    list.appendChild(div);
  });
}

function checkCareerReq(career) {
  for (let key in career.req) {
    if ((G.stats[key] || 0) < career.req[key]) return false;
  }
  return true;
}

function applyCareer(career) {
  if (!checkCareerReq(career)) {
    notify('Conditions non remplies !');
    return;
  }
  G.career = career.id;
  G.careerLevel = 0;
  G.careerXP = 0;
  addLog('event-age', `💼 Nouveau travail : ${career.name}`, 'event-positive', '');
  notify(`💼 ${career.name} !`);
  renderCareers();
  updateUI();
}

function renderRelations() {
