function interactRelation(id, type) {
  if (G.stats.energy < 10) { notify('Pas assez d\'énergie !'); return; }
  G.stats.energy -= 10;
  const r = G.relationships.find(r => r.id === id);
  if (type === 'talk') {
    r.affinity = Math.min(100, r.affinity + 3);
    G.stats.happiness = Math.min(100, G.stats.happiness + 2);
    G.xp += 3;
    addLog('event-age', `💬 Discussion avec ${r.name}`, 'event-neutral', '');
  } else if (type === 'gift') {
    if (G.money < 20) { notify('Pas assez d\'argent !'); return; }
    G.money -= 20;
    r.affinity = Math.min(100, r.affinity + 8);
    G.stats.happiness = Math.min(100, G.stats.happiness + 3);
    G.xp += 5;
    addLog('event-age', `🎁 Cadeau à ${r.name}`, 'event-positive', '');
  }
  gainXP(3);
  renderRelations();
  updateUI();
}

function renderShop() {
  const list = document.getElementById('shop-list');
  list.innerHTML = '';
  SHOP_ITEMS.filter(i => i.category !== 'property' && i.category !== 'edu').forEach(item => {
