      </div>
    `;
    list.appendChild(div);
  });
}

function buyItem(id) {
  const item = SHOP_ITEMS.find(i => i.id === id);
  if (!item || G.money < item.price) return;
  G.money -= item.price;
  G.totalSpent += item.price;
  Object.keys(item.effect).forEach(k => {
    if (k === 'money') G.money += item.effect[k];
    else if (G.stats[k] !== undefined) G.stats[k] = Math.max(0, Math.min(100, G.stats[k] + item.effect[k]));
  });
  if (!G.inventory.find(i => i.id === id)) {
    G.inventory.push({ ...item, qty: 1 });
  } else {
    const inv = G.inventory.find(i => i.id === id);
    inv.qty++;
  }
  addLog('event-age', `🛒 Acheté ${item.name}`, 'event-neutral', '');
  notify(`🛒 ${item.name} acheté !`);
  renderShop();
  renderInventory();
  updateUI();
}

function renderEdu() {
  const list = document.getElementById('edu-list');
  list.innerHTML = '';
  EDUCATION.forEach(edu => {
    const done = G.education.includes(edu.id);
    const div = document.createElement('div');
    div.className = 'edu-card';
    div.innerHTML = `
      <div style="display:flex;align-items:center;gap:10px;">
