          <div class="edu-name">${edu.name} ${done ? '✅' : ''}</div>
          <div class="edu-cost">${edu.cost === 0 ? 'Gratuit' : edu.cost + '€'}</div>
          <div class="edu-bonus">Bonus: ${Object.keys(edu.bonus).map(k => `+${edu.bonus[k]} ${k}`).join(', ')}</div>
          <div style="color:#888;font-size:0.7em;">Disponible à ${edu.age} ans</div>
        </div>
      </div>
    `;
    if (!done && G.age >= edu.age) {
      div.onclick = () => enrollEdu(edu);
    } else if (!done) {
      div.style.opacity = '0.4';
    }
    list.appendChild(div);
  });
}

function enrollEdu(edu) {
  if (G.money < edu.cost) { notify('Pas assez d\'argent !'); return; }
  if (G.education.includes(edu.id)) { notify('Déjà obtenu !'); return; }
  G.money -= edu.cost;
  G.totalSpent += edu.cost;
  G.education.push(edu.id);
  applyEduBonus(edu);
  G.xp += 30;
  addLog('event-age', `🎓 ${edu.name} complété !`, 'event-positive', '');
  notify(`🎓 ${edu.name} !`);
  gainXP(30);
  renderEdu();
  updateUI();
}

function renderInventory() {
  const list = document.getElementById('inventory-list');
  list.innerHTML = '';
  if (G.inventory.length === 0) {
    list.innerHTML = '<div style="color:#888;text-align:center;padding:20px;">Aucun bien possédé</div>';
    return;
