// ==================== TRACK GENERATION ====================
function generateTrack(trackDef) {
  const segs = [];
  const totalSegs = trackDef.segments;
  for (let i = 0; i < totalSegs; i++) {
    const t = i / totalSegs;
    let curve = 0;
    let hill = 0;
    // Generate interesting curves
    const curveVal = Math.sin(t * Math.PI * trackDef.curve * 2) * trackDef.curve * 3;
    const curveVal2 = Math.sin(t * Math.PI * trackDef.curve * 5) * trackDef.curve * 1.5;
    curve = curveVal + curveVal2;
    // Hills
    hill = Math.sin(t * Math.PI * 3) * 20 + Math.sin(t * Math.PI * 7) * 10;
    segs.push({
      index: i,
      curve: curve,
      y: hill,
      z: i * (trackDef.length / totalSegs),
      sprites: [],
      cars: [],
    });
  }
  // Add scenery sprites
  for (let i = 0; i < totalSegs; i++) {
    const seg = segs[i];
    const t = i / totalSegs;
    if (Math.random() < 0.15) {
      const side = Math.random() < 0.5 ? -1 : 1;
      const offset = 2 + Math.random() * 4;
      let spriteType;
      switch (trackDef.scenery) {
        case 'city': spriteType = Math.random() < 0.5 ? 'building' : 'lamp'; break;
        case 'desert': spriteType = Math.random() < 0.5 ? 'cactus' : 'rock'; break;
        case 'mountain': spriteType = Math.random() < 0.5 ? 'tree' : 'rock'; break;
        case 'neon': spriteType = Math.random() < 0.5 ? 'neon_sign' : 'pillar'; break;
        default: spriteType = 'tree';
      }
      seg.sprites.push({ type: spriteType, side: side, offset: offset });
    }
  }
  return segs;
}

