// ==================== INPUT ====================
const keys = {};
window.addEventListener('keydown', e => { keys[e.code] = true; e.preventDefault(); });
window.addEventListener('keyup', e => { keys[e.code] = false; e.preventDefault(); });

// ==================== UPDATE ====================
function update(dt) {
  if (gameState !== 'racing') return;

  // Countdown
  if (!raceStarted) {
    countdownTimer -= dt;
    const cdEl = document.getElementById('hud-countdown');
    if (countdownTimer > 0) {
      cdEl.textContent = Math.ceil(countdownTimer);
      cdEl.style.color = '#fff';
    } else if (countdownTimer > -1) {
      cdEl.textContent = 'GO!';
      cdEl.style.color = '#00ff00';
      raceStarted = true;
      startEngine();
    } else {
      cdEl.textContent = '';
    }
    return;
  }

  raceTime += dt;

  // Day/night cycle
  dayNight = 0.2 + Math.sin(raceTime * 0.05) * 0.3;

  // Player input
  const accelInput = keys['ArrowUp'] || keys['KeyW'] ? 1 : 0;
  const brakeInput = keys['ArrowDown'] || keys['KeyS'] ? 1 : 0;
  const steerInput = (keys['ArrowLeft'] || keys['KeyA'] ? -1 : 0) + (keys['ArrowRight'] || keys['KeyD'] ? 1 : 0);
  const handbrake = keys['ShiftLeft'] || keys['ShiftRight'];
  const boostInput = keys['Space'];

  // Acceleration
  if (accelInput) {
    player.speed += player.accel * (1 + player.speed / player.maxSpeed * 0.5);
  }
  if (brakeInput) {
    player.speed -= 1.5;
  }
  // Friction
  player.speed *= (1 - 0.005 - (weather.type === 'rain' ? 0.005 : 0));
  player.speed = Math.max(-30, Math.min(player.maxSpeed, player.speed));

  // Boost
  if (boostInput && player.boost > 0) {
    player.speed = Math.min(player.speed + 2, player.maxSpeed * 1.3);
    player.boost -= 30 * dt;
    if (Math.random() < 0.3) {
      particles.push({
        x: player.x, y: 0, z: player.z - 2,
        vx: (Math.random() - 0.5) * 2, vy: Math.random() * 2,
        life: 0.5, color: '#ff6600', size: 3
      });
    }
  } else {
    player.boost = Math.min(player.maxBoost, player.boost + player.boostRegen * dt);
  }

  // Steering
  const steerSpeed = 0.04 + player.speed * 0.0001;
  const gripFactor = handbrake ? 0.02 : player.grip;
  if (steerInput !== 0) {
    player.steerAngle += steerInput * steerSpeed * dt * 60;
    player.steerAngle = Math.max(-1, Math.min(1, player.steerAngle));
  } else {
    player.steerAngle *= 0.9;
  }

  // Drifting
  player.isDrifting = handbrake && Math.abs(player.speed) > 50 && Math.abs(player.steerAngle) > 0.3;
  if (player.isDrifting) {
    player.driftAngle += player.steerAngle * 0.03;
    player.driftAngle = Math.max(-0.5, Math.min(0.5, player.driftAngle));
    player.speed *= 0.995;
    driftTimer += dt;
    if (driftTimer > 0.5) {
      const points = Math.floor(Math.abs(player.driftAngle) * Math.abs(player.speed) * dt * 10);
      driftScore += points;
      driftModeScore += points;
      lastDriftScore = points;
      if (Math.random() < 0.2) {
        particles.push({
          x: player.x + (Math.random() - 0.5) * 0.5, y: 0, z: player.z - 1,
          vx: (Math.random() - 0.5) * 1, vy: Math.random(),
          life: 1, color: '#ffcc00', size: 2
        });
      }
    }
  } else {
    if (driftActive && driftTimer > 0.5) {
      // Score drift
    }
    player.driftAngle *= 0.9;
    driftTimer = 0;
    driftActive = false;
  }

  // Apply steering to position
  const currentSeg = getSegment(player.z);
  player.x += player.steerAngle * player.speed * 0.003 * (player.isDrifting ? 1.5 : 1);
  // Curve effect
  player.x -= currentSeg.curve * player.speed * 0.00005;
  // Drift angle effect
  if (player.isDrifting) {
    player.x += player.driftAngle * player.speed * 0.001;
  }

  // Clamp to track
  const trackWidth = 2.5;
  if (Math.abs(player.x) > trackWidth) {
    player.speed *= 0.95;
    if (Math.abs(player.x) > trackWidth + 1) {
      player.speed *= 0.9;
      player.durability -= 5 * dt;
      screenShake = Math.max(screenShake, 2);
    }
    player.x = Math.max(-trackWidth - 2, Math.min(trackWidth + 2, player.x));
  }

  // Move forward
  player.z += player.speed * dt * 10;
  const totalLength = track.length * (track[0] ? track[0].z + (track[1] ? track[1].z - track[0].z : 0) : 0);
  if (player.z >= totalLength) {
    player.z -= totalLength;
    player.lap++;
    if (lapTimes.length > 0) {
      lapTimes.push(raceTime - lapTimes[lapTimes.length - 1]);
    } else {
      lapTimes.push(raceTime);
    }
    currentLap = player.lap + 1;
    document.getElementById('hud-lap-num').textContent = Math.min(currentLap, 3);
    if (player.lap >= 3) {
      player.finished = true;
      finishRace();
    }
  }

  // AI update
  for (let ai of aiCars) {
    if (ai.finished) continue;
    const aiSeg = getSegment(ai.z);
    // Follow track
    ai.speed += ai.accel * dt * 60;
    ai.speed = Math.min(ai.speed, ai.maxSpeed * ai.skill);
    ai.speed *= (1 - 0.003);
    // Steering
    ai.targetX += (Math.random() - 0.5) * 0.02;
    ai.targetX = Math.max(-1.5, Math.min(1.5, ai.targetX));
    ai.x += (ai.targetX - ai.x) * 0.02;
    ai.x -= aiSeg.curve * ai.speed * 0.00004;
    // Move
    ai.z += ai.speed * dt * 10;
    const aiTotalLength = track.length * (track[0] ? track[0].z + (track[1] ? track[1].z - track[0].z : 0) : 0);
    if (ai.z >= aiTotalLength) {
      ai.z -= aiTotalLength;
      ai.lap++;
      if (ai.lap >= 3) ai.finished = true;
    }
    // Elimination mode
    if (selectedMode === 'elimination' && player.lap > ai.lap && !ai.finished) {
      // AI behind player gets eliminated
    }
  }

  // Collision detection
  for (let ai of aiCars) {
    if (ai.finished) continue;
    const dz = Math.abs(player.z - ai.z);
    const dx = Math.abs(player.x - ai.x);
    if (dz < 3 && dx < 1) {
      player.speed *= 0.8;
      ai.speed *= 0.8;
      player.durability -= 3;
      screenShake = Math.max(screenShake, 5);
      playNoise(0.2, 0.15);
      // Push apart
      const pushDir = player.x > ai.x ? 1 : -1;
      player.x += pushDir * 0.3;
      ai.x -= pushDir * 0.3;
      // Collision particles
      for (let i = 0; i < 5; i++) {
        particles.push({
          x: (player.x + ai.x) / 2, y: 0, z: player.z,
          vx: (Math.random() - 0.5) * 5, vy: Math.random() * 3,
          life: 0.5, color: '#ff4400', size: 3
        });
      }
    }
  }

  // Elimination check
  if (selectedMode === 'elimination') {
    const sortedAI = [...aiCars].filter(a => !a.finished).sort((a, b) => {
      const aPos = a.lap * totalLength + a.z;
      const bPos = b.lap * totalLength + b.z;
      return bPos - aPos;
    });
    if (sortedAI.length > 0) {
      sortedAI[sortedAI.length - 1].finished = true;
      playTone(200, 0.3, 'square', 0.1);
    }
  }

  // Position calculation
  const totalTrackLen = totalLength;
  let pos = 1;
  for (let ai of aiCars) {
    const playerPos = player.lap * totalTrackLen + player.z;
    const aiPos = ai.lap * totalTrackLen + ai.z;
    if (aiPos > playerPos) pos++;
  }
  player.position = pos;

  // Weather particles
  if (weather.type === 'rain') {
    for (let i = 0; i < 3; i++) {
      weather.particles.push({
        x: player.x + (Math.random() - 0.5) * 10,
        y: 5,
        z: player.z + Math.random() * 5,
        vy: -10 - Math.random() * 5,
        life: 1
      });
    }
  }
  weather.particles = weather.particles.filter(p => {
    p.y += p.vy * dt;
    p.life -= dt;
    return p.life > 0 && p.y > -1;
  });

  // Update particles
  particles = particles.filter(p => {
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.life -= dt;
    return p.life > 0;
  });

  // Screen shake decay
  screenShake *= 0.9;

  // Durability check
  if (player.durability <= 0) {
    player.durability = 0;
    player.finished = true;
    finishRace();
  }

  // Update HUD
  updateHUD();
  updateEngine(Math.abs(player.speed));
}

function getSegment(z) {
  const totalLength = track.length * (track[0] ? track[0].z + (track[1] ? track[1].z - track[0].z : 0) : 0);
  const normalizedZ = ((z % totalLength) + totalLength) % totalLength;
  const segIndex = Math.floor(normalizedZ / (totalLength / track.length)) % track.length;
  return track[segIndex] || track[0];
}

function updateHUD() {
  document.getElementById('hud-speed-val').textContent = Math.floor(Math.abs(player.speed));
  document.getElementById('hud-gear').textContent = getGear(player.speed);
  document.getElementById('hud-pos-val').textContent = player.position;
  const suffixes = ['st', 'nd', 'rd', 'th', 'th', 'th'];
  document.getElementById('hud-pos-suffix').textContent = suffixes[player.position - 1] || 'th';
  const mins = Math.floor(raceTime / 60);
  const secs = Math.floor(raceTime % 60);
  const ms = Math.floor((raceTime % 1) * 1000);
  document.getElementById('hud-time').textContent =
    `${mins.toString().padStart(2,'0')}:${secs.toString().padStart(2,'0')}.${ms.toString().padStart(3,'0')}`;
  document.getElementById('hud-boost-fill').style.width = (player.boost / player.maxBoost * 100) + '%';
  document.getElementById('hud-damage-fill').style.width = (player.durability / player.maxDurability * 100) + '%';
  const driftEl = document.getElementById('hud-drift');
  const driftScoreEl = document.getElementById('hud-drift-score');
  if (driftActive && driftTimer > 0.5) {
    driftEl.classList.add('active');
    driftScoreEl.classList.add('active');
    driftScoreEl.textContent = '+' + lastDriftScore;
  } else {
    driftEl.classList.remove('active');
    driftScoreEl.classList.remove('active');
  }
}

function getGear(speed) {
  const s = Math.abs(speed);
  if (s < 10) return 'N';
  if (s < 40) return '1';
  if (s < 80) return '2';
  if (s < 130) return '3';
  if (s < 180) return '4';
  if (s < 230) return '5';
  return '6';
}

function finishRace() {
  raceFinished = true;
  stopEngine();
  playTone(440, 0.5, 'sine', 0.15);
  setTimeout(() => playTone(554, 0.5, 'sine', 0.15), 200);
  setTimeout(() => playTone(659, 0.8, 'sine', 0.15), 400);
  setTimeout(() => showResults(), 1500);
}

function showResults() {
  gameState = 'results';
  document.getElementById('hud').classList.add('hidden');
  document.getElementById('results-screen').classList.remove('hidden');
  const suffixes = ['st', 'nd', 'rd', 'th', 'th', 'th'];
  document.getElementById('results-pos').textContent = player.position + (suffixes[player.position - 1] || 'th');
  const reward = Math.max(100, (4 - player.position) * 200 + Math.floor(driftModeScore / 10));
  money += reward;
  xp += reward;
  level = Math.floor(xp / 1000) + 1;
  document.getElementById('results-reward').textContent = `+$${reward} | XP: ${xp} | Level ${level}`;
  let timesHTML = '';
  lapTimes.forEach((t, i) => {
    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);
    const ms = Math.floor((t % 1) * 1000);
    timesHTML += `<div>Lap ${i + 1}: ${m.toString().padStart(2,'0')}:${s.toString().padStart(2,'0')}.${ms.toString().padStart(3,'0')}</div>`;
  });
  if (selectedMode === 'drift') {
    timesHTML = `<div>Drift Score: ${driftModeScore}</div>`;
  }
  document.getElementById('results-times').innerHTML = timesHTML;
}

// ==================== RENDERING ====================
function render() {
  ctx.clearRect(0, 0, W, H);

  // Sky gradient
  const skyGrad = ctx.createLinearGradient(0, 0, 0, H * 0.5);
  if (dayNight < 0.5) {
    skyGrad.addColorStop(0, '#0a0a2e');
    skyGrad.addColorStop(1, '#1a1a3e');
  } else {
    skyGrad.addColorStop(0, '#1a3a5c');
    skyGrad.addColorStop(1, '#4a8ab5');
  }
  ctx.fillStyle = skyGrad;
  ctx.fillRect(0, 0, W, H);

  // Stars (night)
  if (dayNight < 0.5) {
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 50; i++) {
      const sx = (Math.sin(i * 127.1) * 0.5 + 0.5) * W;
      const sy = (Math.cos(i * 311.7) * 0.5 + 0.5) * H * 0.4;
      const brightness = Math.sin(raceTime * 2 + i) * 0.5 + 0.5;
      ctx.globalAlpha = brightness * 0.8;
      ctx.fillRect(sx, sy, 2, 2);
    }
    ctx.globalAlpha = 1;
  }

  // Render road
  renderRoad();

  // Render particles
  renderParticles();

  // Weather
  if (weather.type === 'rain') {
    ctx.strokeStyle = 'rgba(150,180,255,0.3)';
    ctx.lineWidth = 1;
    for (let p of weather.particles) {
      const screenPos = worldToScreen(p.x, p.y, p.z);
      if (screenPos) {
        ctx.beginPath();
        ctx.moveTo(screenPos.x, screenPos.y);
        ctx.lineTo(screenPos.x - 2, screenPos.y + 10);
        ctx.stroke();
      }
    }
  }

  // Vignette
  const vigGrad = ctx.createRadialGradient(W/2, H/2, W*0.3, W/2, H/2, W*0.7);
  vigGrad.addColorStop(0, 'rgba(0,0,0,0)');
  vigGrad.addColorStop(1, 'rgba(0,0,0,0.5)');
  ctx.fillStyle = vigGrad;
  ctx.fillRect(0, 0, W, H);
}

function renderRoad() {
  const totalLength = track.length * (track[0] ? track[0].z + (track[1] ? track[1].z - track[0].z : 0) : 0);
  const segLength = totalLength / track.length;
  const cameraHeight = 1.5;
  const cameraDepth = 1 / Math.tan((80 / 2) * Math.PI / 180);
  const drawDistance = 200;
  const trackWidth = 2.5;

  // Collect visible segments
  const segments = [];
  const playerSegIndex = Math.floor(((player.z % totalLength) + totalLength) % totalLength / segLength) % track.length;

  for (let n = 0; n < drawDistance; n++) {
    const segIndex = (playerSegIndex + n) % track.length;
    const seg = track[segIndex];
    const zWorld = seg.z + (segIndex >= playerSegIndex ? 0 : totalLength) - player.z;
    if (zWorld <= 1) continue;
    segments.push({ seg, zWorld, index: segIndex, n });
  }

  // Sort back to front
  segments.sort((a, b) => b.zWorld - a.zWorld);

  let prevScreenX = 0, prevScreenY = 0, prevScreenW = 0;

  for (let item of segments) {
    const { seg, zWorld, index, n } = item;
    const curveOffset = seg.curve * n * n * 0.001;

    // Project
    const scale = cameraDepth / zWorld;
    const screenX = W / 2 + (0 - player.x - curveOffset) * scale * W / 2;
    const screenY = H / 2 - (seg.y - cameraHeight) * scale * H / 2;
    const screenW = trackWidth * scale * W / 2;

    if (screenY <= 0 || screenY >= H) continue;

    // Road color
    const isEven = Math.floor(index / 3) % 2 === 0;
    const roadColor = isEven ? '#333' : '#3a3a3a';
    const rumbleColor = isEven ? '#ff0040' : '#fff';
    const grassColor = isEven ? '#1a4a1a' : '#1a5a1a';

    // Grass
    ctx.fillStyle = grassColor;
    ctx.fillRect(0, screenY, W, prevScreenY ? screenY - prevScreenY : H);

    // Road
    if (prevScreenW > 0) {
      // Rumble strips
      ctx.fillStyle = rumbleColor;
      drawTrapezoid(prevScreenX, prevScreenY, prevScreenW * 1.15, screenX, screenY, screenW * 1.15);
      // Road surface
      ctx.fillStyle = roadColor;
      drawTrapezoid(prevScreenX, prevScreenY, prevScreenW, screenX, screenY, screenW);
      // Lane markings
      if (isEven) {
        ctx.fillStyle = 'rgba(255,255,255,0.5)';
        const laneW = screenW * 0.02;
        drawTrapezoid(prevScreenX - laneW * 2, prevScreenY, laneW, screenX - laneW * 2, screenY, laneW);
        drawTrapezoid(prevScreenX + laneW * 2, prevScreenY, laneW, screenX + laneW * 2, screenY, laneW);
      }
      // Center line
      if (n % 4 < 2) {
        ctx.fillStyle = '#ffcc00';
        const clw = screenW * 0.015;
        drawTrapezoid(prevScreenX - clw, prevScreenY, clw * 2, screenX - clw, screenY, clw * 2);
      }
    }

    // Sprites
    for (let sprite of seg.sprites) {
      const spriteX = screenX + sprite.side * sprite.offset * scale * W / 2;
      const spriteY = screenY;
      const spriteScale = scale * 200;
      if (spriteScale > 0.01 && spriteScale < 5) {
        drawSprite(sprite.type, spriteX, spriteY, spriteScale);
      }
    }

    prevScreenX = screenX;
    prevScreenY = screenY;
    prevScreenW = screenW;
  }

  // Render AI cars
  for (let ai of aiCars) {
    if (ai.finished) continue;
    const aiSegIndex = Math.floor(((ai.z % totalLength) + totalLength) % totalLength / segLength) % track.length;
    const zWorld = ai.z + (aiSegIndex >= playerSegIndex ? 0 : totalLength) - player.z;
    if (zWorld <= 0 || zWorld > drawDistance * segLength) continue;
    const scale = cameraDepth / zWorld;
    const curveOffset = track[aiSegIndex].curve * Math.floor(zWorld / segLength) * Math.floor(zWorld / segLength) * 0.001;
    const screenX = W / 2 + (ai.x - player.x - curveOffset) * scale * W / 2;
    const screenY = H / 2 - (track[aiSegIndex].y - cameraHeight) * scale * H / 2;
    const screenW = ai.width * scale * W / 2;
    const screenH = ai.height * scale * H / 2;
    if (screenW > 2 && screenY > 0 && screenY < H) {
      drawCarSprite(screenX, screenY, screenW, screenH, ai.color, false);
    }
  }

  // Render player car
  const playerScreenW = 80;
  const playerScreenH = 40;
  const playerScreenX = W / 2 + player.steerAngle * 30;
  const playerScreenY = H - 120;
  drawCarSprite(playerScreenX, playerScreenY, playerScreenW, playerScreenH, player.color, true);

  // Drift smoke
  if (player.isDrifting) {
    ctx.fillStyle = 'rgba(200,200,200,0.3)';
    for (let i = 0; i < 3; i++) {
      const sx = playerScreenX + (Math.random() - 0.5) * 60;
      const sy = playerScreenY + 20 + Math.random() * 10;
      ctx.beginPath();
      ctx.arc(sx, sy, 5 + Math.random() * 10, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Minimap
  renderMinimap();
}

function drawTrapezoid(x1, y1, w1, x2, y2, w2) {
  ctx.beginPath();
  ctx.moveTo(x1 - w1, y1);
  ctx.lineTo(x1 + w1, y1);
  ctx.lineTo(x2 + w2, y2);
  ctx.lineTo(x2 - w2, y2);
  ctx.closePath();
  ctx.fill();
}

function drawCarSprite(x, y, w, h, color, isPlayer) {
  ctx.save();
  ctx.translate(x, y);
  if (isPlayer) {
    ctx.rotate(player.steerAngle * 0.15);
  }
  // Car body
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(-w * 0.5, h * 0.3);
  ctx.lineTo(-w * 0.45, -h * 0.5);
  ctx.lineTo(w * 0.45, -h * 0.5);
  ctx.lineTo(w * 0.5, h * 0.3);
  ctx.lineTo(w * 0.4, h * 0.5);
  ctx.lineTo(-w * 0.4, h * 0.5);
  ctx.closePath();
  ctx.fill();
  // Windshield
  ctx.fillStyle = 'rgba(100,150,255,0.6)';
  ctx.fillRect(-w * 0.3, -h * 0.4, w * 0.6, h * 0.25);
  // Headlights
  ctx.fillStyle = '#ffff00';
  ctx.fillRect(-w * 0.35, -h * 0.45, w * 0.1, h * 0.08);
  ctx.fillRect(w * 0.25, -h * 0.45, w * 0.1, h * 0.08);
  // Tail lights
  ctx.fillStyle = '#ff0000';
  ctx.fillRect(-w * 0.35, h * 0.35, w * 0.1, h * 0.08);
  ctx.fillRect(w * 0.25, h * 0.35, w * 0.1, h * 0.08);
  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.fillRect(-w * 0.45, h * 0.45, w * 0.9, h * 0.1);
  ctx.restore();
}

function drawSprite(type, x, y, scale) {
  if (scale < 0.05 || scale > 3) return;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  switch (type) {
    case 'building':
      ctx.fillStyle = '#2a2a3a';
      ctx.fillRect(-15, -60, 30, 60);
      ctx.fillStyle = '#4a4a6a';
      ctx.fillRect(-12, -55, 8, 8);
      ctx.fillRect(2, -55, 8, 8);
      ctx.fillRect(-12, -40, 8, 8);
      ctx.fillRect(2, -40, 8, 8);
      if (dayNight < 0.5) {
        ctx.fillStyle = '#ffff88';
        ctx.fillRect(-12, -55, 8, 8);
        ctx.fillRect(2, -40, 8, 8);
      }
      break;
    case 'lamp':
      ctx.fillStyle = '#555';
      ctx.fillRect(-2, -50, 4, 50);
      ctx.fillStyle = '#ffcc00';
      ctx.beginPath();
      ctx.arc(0, -52, 5, 0, Math.PI * 2);
      ctx.fill();
      if (dayNight < 0.5) {
        ctx.fillStyle = 'rgba(255,200,0,0.1)';
        ctx.beginPath();
        ctx.arc(0, -52, 20, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    case 'cactus':
      ctx.fillStyle = '#2a6a2a';
      ctx.fillRect(-3, -30, 6, 30);
      ctx.fillRect(-12, -20, 9, 4);
      ctx.fillRect(-12, -24, 4, 8);
      ctx.fillRect(3, -15, 9, 4);
      ctx.fillRect(7, -19, 4, 8);
      break;
    case 'rock':
      ctx.fillStyle = '#6a5a4a';
      ctx.beginPath();
      ctx.arc(0, -5, 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#7a6a5a';
      ctx.beginPath();
      ctx.arc(2, -7, 6, 0, Math.PI * 2);
      ctx.fill();
      break;
    case 'tree':
      ctx.fillStyle = '#4a3a2a';
      ctx.fillRect(-3, -20, 6, 20);
      ctx.fillStyle = '#2a5a2a';
      ctx.beginPath();
      ctx.arc(0, -25, 12, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#3a6a3a';
      ctx.beginPath();
      ctx.arc(-2, -28, 8, 0, Math.PI * 2);
      ctx.fill();
      break;
    case 'neon_sign':
      ctx.fillStyle = '#333';
      ctx.fillRect(-2, -40, 4, 40);
      ctx.fillStyle = '#ff00ff';
      ctx.fillRect(-10, -45, 20, 10);
      ctx.fillStyle = '#00ffff';
      ctx.fillRect(-8, -43, 16, 6);
      ctx.fillStyle = 'rgba(255,0,255,0.15)';
      ctx.beginPath();
      ctx.arc(0, -40, 25, 0, Math.PI * 2);
      ctx.fill();
      break;
    case 'pillar':
      ctx.fillStyle = '#444';
      ctx.fillRect(-4, -30, 8, 30);
      ctx.fillStyle = '#ff0040';
      ctx.fillRect(-6, -32, 12, 4);
      break;
  }
  ctx.restore();
}

function renderParticles() {
  for (let p of particles) {
    const screenPos = worldToScreen(p.x, p.y, p.z);
    if (!screenPos) continue;
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(screenPos.x, screenPos.y, p.size * (screenPos.scale || 1), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function worldToScreen(wx, wy, wz) {
  const totalLength = track.length * (track[0] ? track[0].z + (track[1] ? track[1].z - track[0].z : 0) : 0);
  const segLength = totalLength / track.length;
  const cameraHeight = 1.5;
  const cameraDepth = 1 / Math.tan((80 / 2) * Math.PI / 180);
  const playerSegIndex = Math.floor(((player.z % totalLength) + totalLength) % totalLength / segLength) % track.length;
  const relZ = wz - player.z;
  const zWorld = relZ > 0 ? relZ : relZ + totalLength;
  if (zWorld <= 1 || zWorld > 2000) return null;
  const segIndex = Math.floor(((wz % totalLength) + totalLength) % totalLength / segLength) % track.length;
  const seg = track[segIndex];
  const n = Math.floor(zWorld / segLength);
  const curveOffset = seg.curve * n * n * 0.001;
  const scale = cameraDepth / zWorld;
  return {
    x: W / 2 + (wx - player.x - curveOffset) * scale * W / 2,
    y: H / 2 - (wy - cameraHeight) * scale * H / 2,
    scale: scale
  };
}

function renderMinimap() {
  minimapCtx.clearRect(0, 0, 160, 160);
  minimapCtx.fillStyle = 'rgba(0,0,0,0.7)';
  minimapCtx.fillRect(0, 0, 160, 160);
  minimapCtx.strokeStyle = '#444';
  minimapCtx.lineWidth = 2;

  // Draw track outline
  const totalLength = track.length * (track[0] ? track[0].z + (track[1] ? track[1].z - track[0].z : 0) : 0);
  const segLength = totalLength / track.length;
  minimapCtx.beginPath();
  let firstX = 80, firstY = 80;
  for (let i = 0; i < track.length; i += 5) {
    const seg = track[i];
    const n = i;
    const cx = Math.sin(n * 0.02) * 30 + seg.curve * 5;
    const cy = Math.cos(n * 0.02) * 30;
    const mx = 80 + cx;
    const my = 80 + cy;
    if (i === 0) minimapCtx.moveTo(mx, my);
    else minimapCtx.lineTo(mx, my);
  }
  minimapCtx.closePath();
  minimapCtx.stroke();

  // AI dots
  for (let ai of aiCars) {
    const aiSegIndex = Math.floor(((ai.z % totalLength) + totalLength) % totalLength / segLength) % track.length;
    const n = aiSegIndex;
    const cx = Math.sin(n * 0.02) * 30 + track[aiSegIndex].curve * 5;
    const cy = Math.cos(n * 0.02) * 30;
    minimapCtx.fillStyle = ai.color;
    minimapCtx.beginPath();
    minimapCtx.arc(80 + cx, 80 + cy, 3, 0, Math.PI * 2);
    minimapCtx.fill();
  }

  // Player dot
  const playerSegIndex = Math.floor(((player.z % totalLength) + totalLength) % totalLength / segLength) % track.length;
  const n = playerSegIndex;
  const pcx = Math.sin(n * 0.02) * 30 + track[playerSegIndex].curve * 5;
  const pcy = Math.cos(n * 0.02) * 30;
  minimapCtx.fillStyle = '#fff';
  minimapCtx.beginPath();
  minimapCtx.arc(80 + pcx, 80 + pcy, 4, 0, Math.PI * 2);
  minimapCtx.fill();
  minimapCtx.strokeStyle = '#ff0040';
  minimapCtx.lineWidth = 2;
  minimapCtx.stroke();
}

