function renderUpgrades() {
  const list = document.getElementById('upgrade-list');
  const upgradeDefs = [
    { key: 'engine', name: 'Engine', max: 5, baseCost: 200 },
    { key: 'turbo', name: 'Turbo', max: 5, baseCost: 300 },
    { key: 'tires', name: 'Tires', max: 5, baseCost: 150 },
    { key: 'brakes', name: 'Brakes', max: 5, baseCost: 150 },
    { key: 'armor', name: 'Armor', max: 5, baseCost: 250 },
    { key: 'nitro', name: 'Nitro', max: 5, baseCost: 400 },
  ];
  list.innerHTML = '';
  upgradeDefs.forEach(upg => {
    const cost = upg.baseCost * (upgrades[upg.key] + 1);
    const div = document.createElement('div');
    div.className = 'upgrade-item';
    div.onclick = () => {
      if (upgrades[upg.key] < upg.max && money >= cost) {
        money -= cost;
        upgrades[upg.key]++;
        renderUpgrades();
      }
    };
    div.innerHTML = `
      <div class="upg-name">${upg.name}</div>
      <div class="upg-level">${'■'.repeat(upgrades[upg.key])}${'□'.repeat(upg.max - upgrades[upg.key])}</div>
      <div class="upg-cost">${upgrades[upg.key] >= upg.max ? 'MAX' : '$' + cost}</div>
    `;
    list.appendChild(div);
  });
}

