<script>
// ============================================================
// TEMPLE RUNNER - Complete Endless Runner Game
// ============================================================

// --- CONFIGURATION / TUNABLE PARAMETERS ---
const CFG = {
  // Lane & movement
  LANE_WIDTH: 2.5,
  LANE_COUNT: 3,
  PLAYER_SPEED: 12,
  SPEED_INCREMENT: 0.3,        // speed increase per second
  MAX_SPEED: 28,
  JUMP_VELOCITY: 10,
