  RENDER_DISTANCE: 120,
  HORIZON_Y: 0.35,            // fraction of canvas height

  // Obstacles
  OBSTACLE_SPAWN_RATE: 0.4,   // per segment
  OBSTACLE_TYPES: ['barrier_low', 'barrier_high', 'pillar', 'moving_barrier'],
  MOVING_OBSTACLE_SPEED: 2,

  // Coins
  COIN_SPAWN_RATE: 0.6,
  COIN_GAP: 3,

  // Power-ups
  POWERUP_SPAWN_RATE: 0.08,
  POWERUP_TYPES: ['magnet', 'jet', 'hoverboard'],
  DEFAULT_POWERUP_DURATION: { magnet: 8, jet: 5, hoverboard: 10 },
  DEFAULT_POWERUP_COOLDOWN: { magnet: 15, jet: 20, hoverboard: 25 },

  // Chaser
  CHASER_SPEED: 0.15,         // speed at which chaser closes in (distance per second)
  CHASER_START_DISTANCE: 60,
  CHASER_MAX_SPEED: 0.3,

  // Scoring
  SCORE_PER_METER: 1,
  COIN_VALUE: 1,

  // Colors
  COLORS: {
    ground: '#3a2a1a',
    groundAlt: '#4a3a2a',
    wall: '#5a4a3a',
    wallTop: '#6a5a4a',
    sky: '#1a1a3a',
    skyGrad: '#2a2a5a',
    player: '#40a0ff',
    playerAlt: '#2080dd',
    coin: '#f0c040',
    obstacle: '#c04040',
    obstacleLow: '#e08040',
    obstacleHigh: '#a040a0',
    powerup: '#40e040',
    chaser: '#ff2020',
  }
};

// --- SAVE DATA SCHEMA ---
const DEFAULT_SAVE = {
  coins: 0,
  totalCoins: 0,
  highScore: 0,
  upgrades: {
    magnetDuration: 0,
    magnetCooldown: 0,
    jetDuration: 0,
    jetCooldown: 0,
    hoverboardDuration: 0,
    hoverboardCooldown: 0,
    coinMultiplier: 0,
    startingSpeed: 0,
    magnetRange: 0,
  },
  skins: {
    owned: ['default'],
    equipped: 'default',
  },
  totalGamesPlayed: 0,
};

// --- SHOP DATA ---
const SHOP_DATA = {
  powerups: [
    { id: 'magnetDuration', name: 'Magnet Duration', desc: 'Extend magnet pickup range time', cost: 50, maxLevel: 10, perLevel: 1, icon: '🧲' },
    { id: 'magnetCooldown', name: 'Magnet Cooldown', desc: 'Reduce magnet cooldown', cost: 40, maxLevel: 5, perLevel: -2, icon: '⏱️' },
    { id: 'jetDuration', name: 'Jet Duration', desc: 'Extend jetpack flight time', cost: 60, maxLevel: 10, perLevel: 1, icon: '🚀' },
    { id: 'jetCooldown', name: 'Jet Cooldown', desc: 'Reduce jetpack cooldown', cost: 50, maxLevel: 5, perLevel: -3, icon: '⏱️' },
    { id: 'hoverboardDuration', name: 'Hoverboard Duration', desc: 'Extend hoverboard time', cost: 55, maxLevel: 10, perLevel: 1, icon: '🛹' },
    { id: 'hoverboardCooldown', name: 'Hoverboard Cooldown', desc: 'Reduce hoverboard cooldown', cost: 45, maxLevel: 5, perLevel: -3, icon: '⏱️' },
    { id: 'magnetRange', name: 'Magnet Range', desc: 'Increase coin pickup range', cost: 80, maxLevel: 5, perLevel: 2, icon: '📏' },
  ],
  passives: [
    { id: 'coinMultiplier', name: 'Coin Multiplier', desc: 'Multiply coins earned', cost: 100, maxLevel: 5, perLevel: 1, icon: '💰' },
    { id: 'startingSpeed', name: 'Starting Speed', desc: 'Begin with higher speed', cost: 75, maxLevel: 5, perLevel: 2, icon: '⚡' },
  ],
  skins: [
    { id: 'default', name: 'Classic', cost: 0, color: '#40a0ff', altColor: '#2080dd' },
    { id: 'red', name: 'Blaze', cost: 100, color: '#ff4040', altColor: '#cc2020' },
    { id: 'green', name: 'Forest', cost: 100, color: '#40c040', altColor: '#20a020' },
    { id: 'purple', name: 'Royal', cost: 150, color: '#a040ff', altColor: '#8020dd' },
    { id: 'gold', name: 'Golden', cost: 300, color: '#f0c040', altColor: '#d0a020' },
    { id: 'cyan', name: 'Neon', cost: 200, color: '#40ffff', altColor: '#20dddd' },
    { id: 'pink', name: 'Cherry', cost: 150, color: '#ff60a0', altColor: '#dd4080' },
    { id: 'dark', name: 'Shadow', cost: 250, color: '#404040', altColor: '#202020' },
    { id: 'white', name: 'Ghost', cost: 200, color: '#e0e0e0', altColor: '#b0b0b0' },
  ]
};

// ============================================================
// SAVE MANAGER
// ============================================================
const SaveManager = {
  key: 'templeRunnerSave',

  load() {
    try {
      const data = localStorage.getItem(this.key);
      if (data) {
        const saved = JSON.parse(data);
        // Merge with defaults to handle new fields
        return { ...DEFAULT_SAVE, ...saved, upgrades: { ...DEFAULT_SAVE.upgrades, ...saved.upgrades }, skins: { ...DEFAULT_SAVE.skins, ...saved.skins } };
      }
    } catch (e) { console.warn('Failed to load save:', e); }
    return JSON.parse(JSON.stringify(DEFAULT_SAVE));
  },

  save(data) {
    try { localStorage.setItem(this.key, JSON.stringify(data)); }
    catch (e) { console.warn('Failed to save:', e); }
  },

  addCoins(amount) {
    SaveManager.data.coins += amount;
    SaveManager.data.totalCoins += amount;
    SaveManager.save(SaveManager.data);
  },

  spendCoins(amount) {
    if (SaveManager.data.coins >= amount) {
      SaveManager.data.coins -= amount;
      SaveManager.save(SaveManager.data);
      return true;
    }
    return false;
  },

  unlockSkin(skinId) {
    if (!SaveManager.data.skins.owned.includes(skinId)) {
      SaveManager.data.skins.owned.push(skinId);
      SaveManager.save(SaveManager.data);
    }
  },

  equipSkin(skinId) {
    if (SaveManager.data.skins.owned.includes(skinId)) {
      SaveManager.data.skins.equipped = skinId;
      SaveManager.save(SaveManager.data);
    }
  },

  upgradeStat(statId, amount) {
    SaveManager.data.upgrades[statId] = (SaveManager.data.upgrades[statId] || 0) + amount;
    SaveManager.save(SaveManager.data);
  },

  getUpgrade(statId) {
    return SaveManager.data.upgrades[statId] || 0;
  },

  getSkin() {
    return SaveManager.data.skins.equipped || 'default';
  },

  getSkinData(skinId) {
    return SHOP_DATA.skins.find(s => s.id === skinId) || SHOP_DATA.skins[0];
  }
};

// ============================================================
// INPUT MANAGER (Desktop + Mobile)
// ============================================================
const InputManager = {
  keys: {},
  touchStartX: 0,
  touchStartY: 0,
  touchStartTime: 0,
  isTouching: false,
  lastSwipe: null,

  init() {
    window.addEventListener('keydown', e => {
      this.keys[e.code] = true;
      if (['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space'].includes(e.code)) e.preventDefault();
    });
    window.addEventListener('keyup', e => { this.keys[e.code] = false; });

    const canvas = document.getElementById('gameCanvas');
    canvas.addEventListener('touchstart', e => {
      e.preventDefault();
      const t = e.touches[0];
      this.touchStartX = t.clientX;
      this.touchStartY = t.clientY;
      this.touchStartTime = Date.now();
      this.isTouching = true;
    }, { passive: false });

    canvas.addEventListener('touchend', e => {
      e.preventDefault();
      if (!this.isTouching) return;
      this.isTouching = false;
      const t = e.changedTouches[0];
      const dx = t.clientX - this.touchStartX;
      const dy = t.clientY - this.touchStartY;
      const dt = Date.now() - this.touchStartTime;
      const minSwipe = 30;

      if (dt < 500) {
        if (Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > minSwipe) {
          this.lastSwipe = dx > 0 ? 'right' : 'left';
        } else if (Math.abs(dy) > minSwipe) {
          this.lastSwipe = dy < 0 ? 'up' : 'down';
        }
      }
    }, { passive: false });

    canvas.addEventListener('touchmove', e => e.preventDefault(), { passive: false });
  },

  isPressed(action) {
    switch (action) {
      case 'left': return this.keys['ArrowLeft'] || this.keys['KeyA'];
      case 'right': return this.keys['ArrowRight'] || this.keys['KeyD'];
      case 'jump': return this.keys['ArrowUp'] || this.keys['KeyW'] || this.keys['Space'];
      case 'slide': return this.keys['ArrowDown'] || this.keys['KeyS'];
      default: return false;
    }
  },

  getSwipe() {
    const swipe = this.lastSwipe;
    this.lastSwipe = null;
    return swipe;
  }
};

// ============================================================
// OBJECT POOL
// ============================================================
class ObjectPool {
  constructor(factory, resetFn, initialSize = 20) {
    this.factory = factory;
    this.resetFn = resetFn;
    this.pool = [];
    this.active = [];
    for (let i = 0; i < initialSize; i++) {
      const obj = factory();
      this.pool.push(obj);
    }
  }

  acquire() {
    let obj = this.pool.length > 0 ? this.pool.pop() : this.factory();
    this.active.push(obj);
    return obj;
  }

  release(obj) {
    const idx = this.active.indexOf(obj);
    if (idx >= 0) {
      this.active.splice(idx, 1);
      this.resetFn(obj);
      this.pool.push(obj);
    }
  }

  releaseAll() {
    for (const obj of this.active) {
      this.resetFn(obj);
      this.pool.push(obj);
    }
    this.active.length = 0;
  }

  update(dt) {
    for (let i = this.active.length - 1; i >= 0; i--) {
      const obj = this.active[i];
      obj.update(dt);
      if (obj.dead) {
        this.release(obj);
      }
    }
  }
}

// ============================================================
// 3D MATH HELPERS
// ============================================================
const Math3D = {
  project(x, y, z, camX, camY, camZ, fov, viewW, viewH) {
    const relX = x - camX;
    const relY = y - camY;
    const relZ = z - camZ;
    if (relZ <= 0.1) return null;
    const scale = fov / relZ;
    return {
      x: viewW / 2 + relX * scale,
      y: viewH * CFG.HORIZON_Y - relY * scale,
      scale: scale,
      z: relZ
    };
  },

  lerp(a, b, t) { return a + (b - a) * t; },

  clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
};

// ============================================================
// RENDERER (Canvas 2D with pseudo-3D)
// ============================================================
const Renderer = {
  canvas: null,
  ctx: null,
  w: 0,
  h: 0,

  init() {
    this.canvas = document.getElementById('gameCanvas');
    this.ctx = this.canvas.getContext('2d');
    this.resize();
    window.addEventListener('resize', () => this.resize());
  },

  resize() {
    this.w = window.innerWidth;
    this.h = window.innerHeight;
    this.canvas.width = this.w;
    this.canvas.height = this.h;
  },

  clear() {
    // Sky gradient
    const grad = this.ctx.createLinearGradient(0, 0, 0, this.h);
    grad.addColorStop(0, '#0a0a2a');
    grad.addColorStop(CFG.HORIZON_Y, '#1a1a4a');
    grad.addColorStop(CFG.HORIZON_Y + 0.1, '#2a2a3a');
    grad.addColorStop(1, '#1a1a1a');
    this.ctx.fillStyle = grad;
    this.ctx.fillRect(0, 0, this.w, this.h);

    // Stars
    this.ctx.fillStyle = '#ffffff';
    for (let i = 0; i < 50; i++) {
      const sx = (i * 137.5 + this.w * 0.1) % this.w;
      const sy = (i * 97.3) % (this.h * CFG.HORIZON_Y);
      const ss = 0.5 + (i % 3) * 0.5;
      this.ctx.globalAlpha = 0.3 + (i % 5) * 0.1;
      this.ctx.fillRect(sx, sy, ss, ss);
    }
    this.ctx.globalAlpha = 1;
  },

  drawSegment(seg) {
    const ctx = this.ctx;
    const camX = seg.playerX || 0;
    const camY = 3;
    const camZ = seg.playerZ || 0;
    const fov = 300;
    const lw = CFG.LANE_WIDTH;

    for (let i = 0; i < seg.pieces.length; i++) {
      const p = seg.pieces[i];
      const z = p.z;
      if (z < 1 || z > CFG.RENDER_DISTANCE) continue;

      const p0 = Math3D.project(-lw * 1.5, 0, z, camX, camY, camZ, fov, this.w, this.h);
      const p1 = Math3D.project(lw * 1.5, 0, z, camX, camY, camZ, fov, this.w, this.h);
      const p0t = Math3D.project(-lw * 1.5, 0.3, z, camX, camY, camZ, fov, this.w, this.h);
      const p1t = Math3D.project(lw * 1.5, 0.3, z, camX, camY, camZ, fov, this.w, this.h);

      if (!p0 || !p1) continue;

      // Ground
      const alpha = Math.max(0, 1 - z / CFG.RENDER_DISTANCE);
      ctx.globalAlpha = alpha;

      // Ground
      ctx.fillStyle = seg.index % 2 === 0 ? CFG.COLORS.ground : CFG.COLORS.groundAlt;
      ctx.beginPath();
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
      ctx.lineTo(p1.x + 200, p1.y + 200);
      ctx.lineTo(p0.x - 200, p0.y + 200);
      ctx.fill();

      // Lanes
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      for (let l = -1; l <= 1; l++) {
        const lp0 = Math3D.project(l * lw - lw * 0.5, 0.01, z, camX, camY, camZ, fov, this.w, this.h);
        const lp1 = Math3D.project(l * lw + lw * 0.5, 0.01, z, camX, camY, camZ, fov, this.w, this.h);
        if (lp0 && lp1) {
          ctx.beginPath();
          ctx.moveTo(lp0.x, lp0.y);
          ctx.lineTo(lp1.x, lp1.y);
          ctx.stroke();
        }
      }

      // Walls
      const wallH = 3;
      const wp0b = Math3D.project(-lw * 1.8, 0, z, camX, camY, camZ, fov, this.w, this.h);
      const wp1b = Math3D.project(lw * 1.8, 0, z, camX, camY, camZ, fov, this.w, this.h);
      const wp0t = Math3D.project(-lw * 1.8, wallH, z, camX, camY, camZ, fov, this.w, this.h);
      const wp1t = Math3D.project(lw * 1.8, wallH, z, camX, camY, camZ, fov, this.w, this.h);

      if (wp0b && wp1b && wp0t && wp1t) {
        // Left wall
        ctx.fillStyle = CFG.COLORS.wall;
        ctx.beginPath();
        ctx.moveTo(wp0b.x, wp0b.y);
        ctx.lineTo(wp0t.x, wp0t.y);
        ctx.lineTo(wp1t.x - 400, wp1t.y);
        ctx.lineTo(wp1b.x - 400, wp1b.y);
        ctx.fill();

        // Right wall
        ctx.beginPath();
        ctx.moveTo(wp1b.x, wp1b.y);
        ctx.lineTo(wp1t.x, wp1t.y);
        ctx.lineTo(wp0t.x + 400, wp0t.y);
        ctx.lineTo(wp0b.x + 400, wp0b.y);
        ctx.fill();

        // Wall top
        ctx.fillStyle = CFG.COLORS.wallTop;
        ctx.beginPath();
        ctx.moveTo(wp0t.x, wp0t.y);
        ctx.lineTo(wp1t.x, wp1t.y);
        ctx.lineTo(wp1t.x - 400, wp1t.y);
        ctx.lineTo(wp0t.x + 400, wp0t.y);
        ctx.fill();
      }

      // Lane markers (dashed)
      if (i % 2 === 0) {
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.lineWidth = 2;
        for (let l = -1; l <= 1; l++) {
          const lp0 = Math3D.project(l * lw, 0.02, z, camX, camY, camZ, fov, this.w, this.h);
          const lp1 = Math3D.project(l * lw, 0.02, z + 2, camX, camY, camZ, fov, this.w, this.h);
          if (lp0 && lp1) {
            ctx.beginPath();
            ctx.moveTo(lp0.x, lp0.y);
            ctx.lineTo(lp1.x, lp1.y);
            ctx.stroke();
          }
        }
      }

      ctx.globalAlpha = 1;
    }
  },

  drawObject3D(obj) {
    const ctx = this.ctx;
    const camX = obj.playerX || 0;
    const camY = 3;
    const camZ = obj.playerZ || 0;
    const fov = 300;
    const laneW = CFG.LANE_WIDTH;

    const laneX = obj.lane * laneW;
    const px = Math3D.project(laneX, obj.y || 0, obj.z, camX, camY, camZ, fov, this.w, this.h);
    if (!px || px.z < 0.5 || px.z > CFG.RENDER_DISTANCE) return;

    const s = px.scale;

    ctx.globalAlpha = Math.max(0, 1 - px.z / CFG.RENDER_DISTANCE);

    if (obj.type === 'coin') {
      const bob = Math.sin(Date.now() * 0.005 + obj.z) * 0.3;
      const cy = (obj.y || 0) + bob;
      const cp = Math3D.project(laneX, cy, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (!cp) return;
      const r = 0.3 * cp.scale;
      if (r < 0.5) return;

      ctx.fillStyle = CFG.COLORS.coin;
      ctx.beginPath();
      ctx.arc(cp.x, cp.y, Math.max(2, r), 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#d0a020';
      ctx.lineWidth = Math.max(1, r * 0.2);
      ctx.stroke();

      // Shine
      ctx.fillStyle = 'rgba(255,255,200,0.6)';
      ctx.beginPath();
      ctx.arc(cp.x - r * 0.3, cp.y - r * 0.3, Math.max(1, r * 0.3), 0, Math.PI * 2);
      ctx.fill();
    }
    else if (obj.type === 'barrier_low') {
      const hp = Math3D.project(laneX, 0.5, obj.z, camX, camY, camZ, fov, this.w, this.h);
      const tp = Math3D.project(laneX, 1.2, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (!hp || !tp) return;
      const hw = 1.2 * hp.scale;
      const hh = Math.abs(hp.y - tp.y);

      ctx.fillStyle = CFG.COLORS.obstacleLow;
      ctx.fillRect(hp.x - hw, tp.y, hw * 2, hh);
      ctx.strokeStyle = '#a06020';
      ctx.lineWidth = Math.max(1, hw * 0.1);
      ctx.strokeRect(hp.x - hw, tp.y, hw * 2, hh);

      // Stripes
      ctx.fillStyle = '#805010';
      for (let i = -1; i <= 1; i++) {
        ctx.fillRect(hp.x - hw + i * hw * 0.6, tp.y, hw * 0.3, hh);
      }
    }
    else if (obj.type === 'barrier_high') {
      const bp = Math3D.project(laneX, 1.5, obj.z, camX, camY, camZ, fov, this.w, this.h);
      const tp = Math3D.project(laneX, 3.0, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (!bp || !tp) return;
      const hw = 1.2 * bp.scale;
      const hh = Math.abs(bp.y - tp.y);

      ctx.fillStyle = CFG.COLORS.obstacleHigh;
      ctx.fillRect(bp.x - hw, tp.y, hw * 2, hh);
      ctx.strokeStyle = '#802080';
      ctx.lineWidth = Math.max(1, hw * 0.1);
      ctx.strokeRect(bp.x - hw, tp.y, hw * 2, hh);
    }
    else if (obj.type === 'pillar') {
      const bp = Math3D.project(laneX, 0, obj.z, camX, camY, camZ, fov, this.w, this.h);
      const tp = Math3D.project(laneX, 3.5, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (!bp || !tp) return;
      const pw = 0.8 * bp.scale;

      ctx.fillStyle = CFG.COLORS.obstacle;
      ctx.fillRect(bp.x - pw, tp.y, pw * 2, Math.abs(bp.y - tp.y));
      ctx.strokeStyle = '#802020';
      ctx.lineWidth = Math.max(1, pw * 0.15);
      ctx.strokeRect(bp.x - pw, tp.y, pw * 2, Math.abs(bp.y - tp.y));

      // Decorative bands
      for (let i = 0; i < 3; i++) {
        const by = tp.y + (Math.abs(bp.y - tp.y) / 4) * (i + 0.5);
        ctx.fillStyle = '#802020';
        ctx.fillRect(bp.x - pw, by - pw * 0.15, pw * 2, pw * 0.3);
      }
    }
    else if (obj.type === 'moving_barrier') {
      const mp = Math3D.project(laneX, 0.8, obj.z, camX, camY, camZ, fov, this.w, this.h);
      const tp = Math3D.project(laneX, 2.0, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (!mp || !tp) return;
      const hw = 1.5 * mp.scale;
      const hh = Math.abs(mp.y - tp.y);

      ctx.fillStyle = '#ff6040';
      ctx.fillRect(mp.x - hw, tp.y, hw * 2, hh);
      ctx.strokeStyle = '#cc4020';
      ctx.lineWidth = Math.max(1, hw * 0.1);
      ctx.strokeRect(mp.x - hw, tp.y, hw * 2, hh);

      // Warning stripes
      ctx.fillStyle = '#cc4020';
      for (let i = -1; i <= 1; i++) {
        ctx.fillRect(mp.x - hw + i * hw * 0.7, tp.y, hw * 0.4, hh);
      }
    }
    else if (obj.type === 'powerup') {
      const pp = Math3D.project(laneX, (obj.y || 0) + 0.5 + Math.sin(Date.now() * 0.004) * 0.2, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (!pp) return;
      const r = 0.4 * pp.scale;
      if (r < 1) return;

      const colors = { magnet: '#40a0ff', jet: '#ff8040', hoverboard: '#40ff80' };
      ctx.fillStyle = colors[obj.subtype] || '#40e040';
      ctx.beginPath();
      ctx.arc(pp.x, pp.y, Math.max(3, r), 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = Math.max(1, r * 0.2);
      ctx.stroke();

      // Glow
      ctx.fillStyle = (colors[obj.subtype] || '#40e040') + '40';
      ctx.beginPath();
      ctx.arc(pp.x, pp.y, Math.max(5, r * 2), 0, Math.PI * 2);
      ctx.fill();
    }
    else if (obj.type === 'player') {
      this.drawPlayer(obj);
    }
    else if (obj.type === 'chaser') {
      this.drawChaser(obj);
    }

    ctx.globalAlpha = 1;
  },

  drawPlayer(obj) {
    const ctx = this.ctx;
    const camX = obj.playerX || 0;
    const camY = 3;
    const camZ = obj.playerZ || 0;
    const fov = 300;
    const laneX = obj.lane * CFG.LANE_WIDTH;
    const skin = SaveManager.getSkinData(SaveManager.getSkin());

    let py = obj.y || 0;
    let scale = obj.scale || 1;

    // Jump animation
    const isJumping = obj.isJumping;
    const isSliding = obj.isSliding;

    const pp = Math3D.project(laneX, py + (isSliding ? 0.5 : 1.5) * scale, obj.z, camX, camY, camZ, fov, this.w, this.h);
    if (!pp || pp.z < 0.5) return;

    const s = pp.scale * scale * 1.2;
    const w = Math.max(4, s * 0.6);
    const h = Math.max(6, s * 1.2);

    if (isSliding) {
      // Sliding pose - shorter and wider
      ctx.fillStyle = skin.color;
      ctx.fillRect(pp.x - w, pp.y - h * 0.4, w * 2, h * 0.5);
      ctx.fillStyle = skin.altColor;
      ctx.fillRect(pp.x - w * 0.5, pp.y - h * 0.6, w, h * 0.3);
    } else {
      // Body
      ctx.fillStyle = skin.color;
      ctx.fillRect(pp.x - w * 0.7, pp.y - h, w * 1.4, h * 0.6);

      // Head
      ctx.fillStyle = skin.altColor;
      ctx.beginPath();
      ctx.arc(pp.x, pp.y - h * 1.1, w * 0.5, 0, Math.PI * 2);
      ctx.fill();

      // Legs (animated)
      const legAnim = Math.sin(Date.now() * 0.015) * w * 0.4;
      ctx.fillStyle = skin.color;
      ctx.fillRect(pp.x - w * 0.5 + legAnim, pp.y - h * 0.4, w * 0.3, h * 0.5);
      ctx.fillRect(pp.x + w * 0.2 - legAnim, pp.y - h * 0.4, w * 0.3, h * 0.5);

      // Arms
      const armAnim = Math.sin(Date.now() * 0.015 + Math.PI) * w * 0.3;
      ctx.fillStyle = skin.altColor;
      ctx.fillRect(pp.x - w * 1.0 + armAnim, pp.y - h * 0.85, w * 0.3, h * 0.4);
      ctx.fillRect(pp.x + w * 0.7 - armAnim, pp.y - h * 0.85, w * 0.3, h * 0.4);
    }

    // Hoverboard effect
    if (obj.hasHoverboard) {
      const hb = Math3D.project(laneX, py + 0.1, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (hb) {
        ctx.fillStyle = '#40ff80';
        ctx.beginPath();
        ctx.ellipse(hb.x, hb.y, w * 1.5, w * 0.3, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#40ff8060';
        ctx.beginPath();
        ctx.ellipse(hb.x, hb.y + 2, w * 2, w * 0.5, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Jetpack effect
    if (obj.hasJetpack) {
      const jp = Math3D.project(laneX, py + 0.8, obj.z, camX, camY, camZ, fov, this.w, this.h);
      if (jp) {
        const flicker = Math.random() * 0.5 + 0.5;
        ctx.fillStyle = `rgba(255, 100, 20, ${flicker})`;
        ctx.beginPath();
        ctx.moveTo(jp.x - w * 0.3, jp.y);
        ctx.lineTo(jp.x, jp.y + w * 2 * flicker);
        ctx.lineTo(jp.x + w * 0.3, jp.y);
        ctx.fill();
      }
    }
  },

  drawChaser(obj) {
    const ctx = this.ctx;
    const camX = obj.playerX || 0;
    const camY = 3;
    const camZ = obj.playerZ || 0;
    const fov = 300;
    const laneX = obj.lane * CFG.LANE_WIDTH;

    const cp = Math3D.project(laneX, 1.5, obj.z, camX, camY, camZ, fov, this.w, this.h);
    if (!cp || cp.z < 0.5) return;

    const s = cp.scale * 1.5;
    const w = Math.max(4, s * 0.7);
    const h = Math.max(6, s * 1.4);

    // Shadowy figure
    ctx.fillStyle = '#2a0000';
    ctx.fillRect(cp.x - w, cp.y - h, w * 2, h);

    // Glowing eyes
    ctx.fillStyle = '#ff0000';
    ctx.beginPath();
    ctx.arc(cp.x - w * 0.3, cp.y - h * 0.85, Math.max(2, w * 0.2), 0, Math.PI * 2);
    ctx.arc(cp.x + w * 0.3, cp.y - h * 0.85, Math.max(2, w * 0.2), 0, Math.PI * 2);
    ctx.fill();

    // Glow
    ctx.fillStyle = 'rgba(255, 0, 0, 0.2)';
    ctx.beginPath();
    ctx.arc(cp.x, cp.y - h * 0.5, w * 2, 0, Math.PI * 2);
    ctx.fill();

    // Aura
    ctx.fillStyle = 'rgba(100, 0, 0, 0.15)';
    ctx.beginPath();
    ctx.arc(cp.x, cp.y - h * 0.3, w * 3, 0, Math.PI * 2);
    ctx.fill();
  },

  drawParticles(particles) {
    const ctx = this.ctx;
    for (const p of particles) {
      ctx.globalAlpha = p.life;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, Math.max(1, p.size), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
};

// ============================================================
// PARTICLE SYSTEM
// ============================================================
const ParticleSystem = {
  particles: [],

  emit(x, y, count, color, speed, life) {
    for (let i = 0; i < count; i++) {
      this.particles.push({
        x, y,
        vx: (Math.random() - 0.5) * speed,
        vy: (Math.random() - 0.5) * speed - speed * 0.5,
        color,
        size: 2 + Math.random() * 3,
        life: life || 1,
        maxLife: life || 1,
      });
    }
  },

  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 10 * dt;
      p.life -= dt / (p.maxLife || 1);
      if (p.life <= 0) this.particles.splice(i, 1);
    }
  },

  draw() {
    Renderer.drawParticles(this.particles);
  }
};

// ============================================================
// SEGMENT MANAGER
// ============================================================
const SegmentManager = {
  segments: [],
  segmentPool: [],
  nextSegmentZ: 0,
  seed: 0,

  init() {
    this.segments = [];
    this.segmentPool = [];
    this.nextSegmentZ = 0;
    this.seed = Math.random() * 10000;
    // Pre-spawn segments
    for (let i = 0; i < 15; i++) {
      this.spawnSegment();
    }
  },

  reset() {
    this.segments = [];
    this.segmentPool = [];
    this.nextSegmentZ = 0;
    this.seed = Math.random() * 10000;
    for (let i = 0; i < 15; i++) {
      this.spawnSegment();
    }
  },

  spawnSegment() {
    const seg = {
      index: this.nextSegmentZ / CFG.SEGMENT_LENGTH,
      z: this.nextSegmentZ,
      pieces: [],
      obstacles: [],
      coins: [],
      powerups: [],
      movingObstacles: [],
    };

    // Create ground pieces
    const numPieces = 4;
    for (let i = 0; i < numPieces; i++) {
      seg.pieces.push({ z: seg.z + i * (CFG.SEGMENT_LENGTH / numPieces) });
    }

    // Generate content
    this.seed = (this.seed * 16807 + 7) % 2147483647;
    const r = this.seed / 2147483647;

    // Obstacles
    if (r < CFG.OBSTACLE_SPAWN_RATE && seg.z > 10) {
      const lane = Math.floor(Math.random() * 3) - 1;
      const types = CFG.OBSTACLE_TYPES;
      const type = types[Math.floor(Math.random() * types.length)];
      seg.obstacles.push({
        type, lane, z: seg.z + CFG.SEGMENT_LENGTH * 0.5,
        active: true
      });

      // Moving obstacles
      if (type === 'moving_barrier' && seg.z > 20) {
        seg.movingObstacles.push({
          type: 'moving_barrier',
          lane: lane,
          z: seg.z + CFG.SEGMENT_LENGTH * 0.5,
          active: true,
          targetLane: (lane + (Math.random() > 0.5 ? 1 : -1) + 3) % 3 - 1,
          moveSpeed: CFG.MOVING_OBSTACLE_SPEED,
          moveTimer: 0,
          moving: false,
        });
      }
    }

    // Coins
    if (r > (1 - CFG.COIN_SPAWN_RATE) && seg.z > 5) {
      const lane = Math.floor(Math.random() * 3) - 1;
      const count = 3 + Math.floor(Math.random() * 5);
      for (let i = 0; i < count; i++) {
        seg.coins.push({
          lane, z: seg.z + i * CFG.COIN_GAP,
          active: true, collected: false
        });
      }
    }

    // Power-ups
    if (r > (1 - CFG.POWERUP_SPAWN_RATE) && seg.z > 30) {
      const lane = Math.floor(Math.random() * 3) - 1;
      const type = CFG.POWERUP_TYPES[Math.floor(Math.random() * CFG.POWERUP_TYPES.length)];
      seg.powerups.push({
        type: 'powerup', subtype: type, lane, z: seg.z + CFG.SEGMENT_LENGTH * 0.5,
        active: true, collected: false
      });
    }

    this.segments.push(seg);
    this.nextSegmentZ += CFG.SEGMENT_LENGTH;
  },

  update(playerZ) {
    // Spawn new segments ahead
    while (this.nextSegmentZ < playerZ + CFG.RENDER_DISTANCE) {
      this.spawnSegment();
    }

    // Remove segments behind
    while (this.segments.length > 0 && this.segments[0].z + CFG.SEGMENT_LENGTH < playerZ - 10) {
      this.segments.shift();
    }
  },

  getAllObjects(playerZ) {
    const objects = [];
    for (const seg of this.segments) {
      for (const obs of seg.obstacles) {
        if (obs.active && Math.abs(obs.z - playerZ) < CFG.RENDER_DISTANCE) {
          objects.push(obs);
        }
      }
      for (const coin of seg.coins) {
        if (coin.active && !coin.collected && Math.abs(coin.z - playerZ) < CFG.RENDER_DISTANCE) {
          objects.push(coin);
        }
      }
      for (const pu of seg.powerups) {
        if (pu.active && !pu.collected && Math.abs(pu.z - playerZ) < CFG.RENDER_DISTANCE) {
          objects.push(pu);
      }
      }
      for (const mob of seg.movingObstacles) {
        if (mob.active && Math.abs(mob.z - playerZ) < CFG.RENDER_DISTANCE) {
          objects.push(mob);
        }
      }
    }
    return objects;
  }
};

