const Player = {
  lane: 0,              // -1, 0, 1
  targetLane: 0,
  x: 0,
  y: 0,
  vy: 0,
  z: 0,
  isJumping: false,
  isSliding: false,
  slideTimer: 0,
  speed: CFG.PLAYER_SPEED,
  baseSpeed: CFG.PLAYER_SPEED,
  scale: 1,
  hasMagnet: false,
  magnetTimer: 0,
  magnetCooldown: 0,
  magnetRange: 3,
  hasJetpack: false,
  jetTimer: 0,
  jetCooldown: 0,
  hasHoverboard: false,
  hoverTimer: 0,
  hoverCooldown: 0,
  invincible: false,
  invincibleTimer: 0,

  init() {
    this.lane = 0;
    this.targetLane = 0;
    this.x = 0;
    this.y = 0;
    this.vy = 0;
    this.z = 0;
    this.isJumping = false;
    this.isSliding = false;
    this.slideTimer = 0;
    this.speed = CFG.PLAYER_SPEED + SaveManager.getUpgrade('startingSpeed') * 2;
    this.baseSpeed = this.speed;
    this.scale = 1;
    this.hasMagnet = false;
    this.magnetTimer = 0;
    this.magnetCooldown = CFG.DEFAULT_POWERUP_COOLDOWN.magnet - SaveManager.getUpgrade('magnetCooldown') * 2;
    this.magnetRange = 3 + SaveManager.getUpgrade('magnetRange') * 2;
    this.hasJetpack = false;
    this.jetTimer = 0;
    this.jetCooldown = CFG.DEFAULT_POWERUP_COOLDOWN.jet - SaveManager.getUpgrade('jetCooldown') * 3;
    this.hasHoverboard = false;
    this.hoverTimer = 0;
    this.hoverCooldown = CFG.DEFAULT_POWERUP_COOLDOWN.hoverboard - SaveManager.getUpgrade('hoverboardCooldown') * 3;
    this.invincible = false;
    this.invincibleTimer = 0;
  },

  update(dt) {
    // Speed increase over time
    this.speed = Math.min(CFG.MAX_SPEED, this.baseSpeed + CFG.SPEED_INCREMENT * this.z * 0.01);

    // Forward movement
    this.z += this.speed * dt;

    // Lane switching
    const laneTarget = this.targetLane * CFG.LANE_WIDTH;
    this.x = Math3D.lerp(this.x, laneTarget, CFG.LANE_SWITCH_SPEED * dt);
    if (Math.abs(this.x - laneTarget) < 0.01) this.x = laneTarget;

    // Jump physics
    if (this.isJumping) {
      this.vy += CFG.GRAVITY * dt;
      this.y += this.vy * dt;
      if (this.y <= 0) {
        this.y = 0;
        this.vy = 0;
        this.isJumping = false;
      }
    }

    // Slide
    if (this.isSliding) {
      this.slideTimer -= dt;
      if (this.slideTimer <= 0) {
        this.isSliding = false;
      }
    }

    // Power-up timers
    if (this.hasMagnet) {
      this.magnetTimer -= dt;
      if (this.magnetTimer <= 0) {
        this.hasMagnet = false;
        this.magnetCooldown = CFG.DEFAULT_POWERUP_COOLDOWN.magnet - SaveManager.getUpgrade('magnetCooldown') * 2;
      }
    }
    if (this.hasJetpack) {
      this.jetTimer -= dt;
      if (this.jetTimer <= 0) {
        this.hasJetpack = false;
        this.jetCooldown = CFG.DEFAULT_POWERUP_COOLDOWN.jet - SaveManager.getUpgrade('jetCooldown') * 3;
      }
    }
    if (this.hasHoverboard) {
      this.hoverTimer -= dt;
      if (this.hoverTimer <= 0) {
        this.hasHoverboard = false;
        this.hoverCooldown = CFG.DEFAULT_POWERUP_COOLDOWN.hoverboard - SaveManager.getUpgrade('hoverboardCooldown') * 3;
      }
    }

    // Cooldowns
    if (this.magnetCooldown > 0) this.magnetCooldown -= dt;
    if (this.jetCooldown > 0) this.jetCooldown -= dt;
    if (this.hoverCooldown > 0) this.hoverCooldown -= dt;
    if (this.invincibleTimer > 0) {
      this.invincibleTimer -= dt;
      if (this.invincibleTimer <= 0) this.invincible = false;
    }
  },

  switchLane(direction) {
    const newLane = this.targetLane + direction;
    if (newLane >= -1 && newLane <= 1) {
      this.targetLane = newLane;
    }
  },

  jump() {
    if (!this.isJumping && !this.isSliding) {
      this.isJumping = true;
      this.vy = CFG.JUMP_VELOCITY;
    }
  },

  slide() {
    if (!this.isJumping && !this.isSliding) {
      this.isSliding = true;
      this.slideTimer = CFG.SLIDE_DURATION;
    }
  },

  activatePowerup(type) {
    switch (type) {
      case 'magnet':
        this.hasMagnet = true;
        this.magnetTimer = CFG.DEFAULT_POWERUP_DURATION.magnet + SaveManager.getUpgrade('magnetDuration');
        break;
      case 'jet':
        this.hasJetpack = true;
        this.jetTimer = CFG.DEFAULT_POWERUP_DURATION.jet + SaveManager.getUpgrade('jetDuration');
        this.isJumping = true;
        this.vy = 5;
        break;
      case 'hoverboard':
        this.hasHoverboard = true;
        this.hoverTimer = CFG.DEFAULT_POWERUP_DURATION.hoverboard + SaveManager.getUpgrade('hoverboardDuration');
        this.invincible = true;
        this.invincibleTimer = this.hoverTimer;
        break;
    }
  },

  getHitbox() {
    const hw = 0.4;
    const hh = this.isSliding ? 0.5 : 1.5;
    const hy = this.isSliding ? 0.3 : (this.y + 0.75);
    return { x: this.x, y: hy, z: this.z, w: hw, h: hh };
  },

  checkCollision(other) {
    const hb = this.getHitbox();
    const otherLaneW = CFG.LANE_WIDTH;
    const ox = other.lane * otherLaneW;

    // Z overlap
    const zOverlap = Math.abs(other.z - this.z) < 1.0;
    if (!zOverlap) return false;

    // Lane overlap
    if (Math.abs(ox - this.x) > otherLaneW * 0.8) return false;

    // Y overlap
    if (other.type === 'barrier_low') {
      // Can jump over low barriers
      return this.y < 1.0;
    } else if (other.type === 'barrier_high') {
      // Can slide under high barriers (they block the upper part)
      return this.y > 1.5;
    } else if (other.type === 'pillar') {
      return true;
    } else if (other.type === 'moving_barrier') {
      return this.y < 2.0;
    }
    return false;
  }
};

// ============================================================
// CHASER
// ============================================================
const Chaser = {
  distance: CFG.CHASER_START_DISTANCE,
  speed: CFG.CHASER_SPEED,
  active: false,

  reset() {
    this.distance = CFG.CHASER_START_DISTANCE;
    this.speed = CFG.CHASER_SPEED;
    this.active = true;
  },

  update(dt) {
    if (!this.active) return;

    // Chaser slowly closes the gap
    this.distance -= this.speed * dt;

    // Gradually increase chaser speed
    this.speed = Math.min(CFG.CHASER_MAX_SPEED, this.speed + dt * 0.005);

    if (this.distance <= 0) {
      this.distance = 0;
      Game.gameOver();
    }
  },

  getZ() {
    return Player.z - this.distance;
  }
};

