const Shop = {
  currentTab: 'powerups',

  showTab(tab) {
    this.currentTab = tab;
    document.querySelectorAll('.shop-tab').forEach(t => t.classList.remove('active'));
    event.target.classList.add('active');
    this.render();
  },

  render() {
    const content = document.getElementById('shop-content');
    document.getElementById('shop-coins').textContent = SaveManager.data.coins;

    if (this.currentTab === 'powerups') {
      content.innerHTML = SHOP_DATA.powerups.map(item => {
        const level = SaveManager.getUpgrade(item.id);
        const maxed = level >= item.maxLevel;
        const cost = item.cost * (level + 1);
        const canAfford = SaveManager.data.coins >= cost;
        return `<div class="shop-item">
          <div class="shop-item-info">
            <div class="shop-item-name">${item.icon} ${item.name} <span style="color:#888;font-size:12px;">Lv.${level}/${item.maxLevel}</span></div>
            <div class="shop-item-desc">${item.desc}</div>
            <div class="shop-item-cost">🪙 ${cost}</div>
          </div>
          <button class="buy-btn" ${(!canAfford || maxed) ? 'disabled' : ''} onclick="Shop.buyUpgrade('${item.id}', ${cost})">${maxed ? 'MAX' : 'Buy'}</button>
        </div>`;
      }).join('');
    }
    else if (this.currentTab === 'passives') {
      content.innerHTML = SHOP_DATA.passives.map(item => {
        const level = SaveManager.getUpgrade(item.id);
        const maxed = level >= item.maxLevel;
        const cost = item.cost * (level + 1);
        const canAfford = SaveManager.data.coins >= cost;
        const effect = item.perLevel > 0 ? `+${item.perLevel} per level` : `${item.perLevel} per level`;
        return `<div class="shop-item">
          <div class="shop-item-info">
            <div class="shop-item-name">${item.icon} ${item.name} <span style="color:#888;font-size:12px;">Lv.${level}/${item.maxLevel}</span></div>
            <div class="shop-item-desc">${item.desc} (${effect})</div>
            <div class="shop-item-cost">🪙 ${cost}</div>
          </div>
          <button class="buy-btn" ${(!canAfford || maxed) ? 'disabled' : ''} onclick="Shop.buyUpgrade('${item.id}', ${cost})">${maxed ? 'MAX' : 'Buy'}</button>
        </div>`;
      }).join('');
    }
    else if (this.currentTab === 'skins') {
      const equipped = SaveManager.getSkin();
      content.innerHTML = `<div class="skin-grid">${SHOP_DATA.skins.map(skin => {
        const owned = SaveManager.data.skins.owned.includes(skin.id);
        const selected = equipped === skin.id;
        const canAfford = SaveManager.data.coins >= skin.cost;
        return `<div class="skin-item ${owned ? 'owned' : ''} ${selected ? 'selected' : ''}" onclick="Shop.handleSkin('${skin.id}', ${skin.cost})">
          <div class="skin-preview" style="background:linear-gradient(135deg,${skin.color},${skin.altColor})"></div>
          <div class="skin-name">${skin.name}</div>
          <div style="color:${owned ? '#40e040' : '#f0c040'};font-size:12px;margin-top:4px;">${owned ? (selected ? '✓ Equipped' : 'Owned') : `🪙 ${skin.cost}`}</div>
        </div>`;
      }).join('')}</div>`;
    }
  },

  buyUpgrade(statId, cost) {
    if (SaveManager.spendCoins(cost)) {
      SaveManager.upgradeStat(statId, 1);
      this.render();
    }
  },

  handleSkin(skinId, cost) {
    const owned = SaveManager.data.skins.owned.includes(skinId);
    if (!owned) {
      if (SaveManager.spendCoins(cost)) {
        SaveManager.unlockSkin(skinId);
        SaveManager.equipSkin(skinId);
        this.render();
      }
    } else {
      SaveManager.equipSkin(skinId);
      this.render();
    }
  }
};

