const Game = {
  state: 'menu', // menu, playing, gameover
  score: 0,
  coins: 0,
  sessionCoins: 0,
  lastTime: 0,
  powerupBar: null,

  init() {
    Renderer.init();
    InputManager.init();
    SaveManager.data = SaveManager.load();
    this.powerupBar = document.getElementById('powerup-bar');
    this.updateHUD();
  },

  start() {
    this.state = 'playing';
    this.score = 0;
    this.coins = 0;
    this.sessionCoins = 0;
    Player.init();
    SegmentManager.reset();
    Chaser.reset();
    ParticleSystem.particles = [];

    document.getElementById('menu-screen').classList.add('hidden');
    document.getElementById('gameover-screen').classList.add('hidden');
    document.getElementById('shop-screen').classList.add('hidden');
    document.getElementById('hud').classList.remove('hidden');
    document.getElementById('controls-hint').classList.remove('hidden');
    this.powerupBar.classList.remove('hidden');
    this.updatePowerupBar();

    this.lastTime = performance.now();
    requestAnimationFrame(t => this.loop(t));
  },

  gameOver() {
    this.state = 'gameover';
    SaveManager.data.totalGamesPlayed++;

    // Save coins
    SaveManager.addCoins(this.sessionCoins);

    // Update high score
    if (this.score > SaveManager.data.highScore) {
      SaveManager.data.highScore = this.score;
    }
    SaveManager.save(SaveManager.data);

    document.getElementById('hud').classList.add('hidden');
    document.getElementById('controls-hint').classList.add('hidden');
    this.powerupBar.classList.add('hidden');
    document.getElementById('final-score').textContent = Math.floor(this.score);
    document.getElementById('final-coins').textContent = this.sessionCoins;
    document.getElementById('gameover-screen').classList.remove('hidden');
  },

  toMenu() {
    this.state = 'menu';
    document.getElementById('gameover-screen').classList.add('hidden');
    document.getElementById('shop-screen').classList.add('hidden');
    document.getElementById('menu-screen').classList.remove('hidden');
  },

  openShop() {
    document.getElementById('menu-screen').classList.add('hidden');
    document.getElementById('gameover-screen').classList.add('hidden');
    document.getElementById('shop-screen').classList.remove('hidden');
    Shop.render();
  },

  closeShop() {
    document.getElementById('shop-screen').classList.add('hidden');
    if (this.state === 'gameover') {
      document.getElementById('gameover-screen').classList.remove('hidden');
    } else {
      document.getElementById('menu-screen').classList.remove('hidden');
    }
  },

  updateHUD() {
    document.getElementById('score-display').textContent = Math.floor(this.score);
    document.getElementById('coin-display').textContent = this.sessionCoins;
    document.getElementById('speed-display').textContent = (Player.speed / CFG.PLAYER_SPEED).toFixed(1) + 'x';
  },

  updatePowerupBar() {
    let html = '';
    const powerups = [
      { key: 'magnet', icon: '🧲', timer: Player.magnetTimer, cooldown: Player.magnetCooldown, active: Player.hasMagnet, ready: !Player.hasMagnet && Player.magnetCooldown <= 0 },
      { key: 'jet', icon: '🚀', timer: Player.jetTimer, cooldown: Player.jetCooldown, active: Player.hasJetpack, ready: !Player.hasJetpack && Player.jetCooldown <= 0 },
      { key: 'hoverboard', icon: '🛹', timer: Player.hoverTimer, cooldown: Player.hoverCooldown, active: Player.hasHoverboard, ready: !Player.hasHoverboard && Player.hoverCooldown <= 0 },
    ];

    for (const pu of powerups) {
      if (pu.active || pu.ready) {
        const maxDuration = CFG.DEFAULT_POWERUP_DURATION[pu.key] + SaveManager.getUpgrade(pu.key + 'Duration');
        const pct = pu.active ? (pu.timer / maxDuration * 100) : 100;
        const color = pu.active ? '#40e040' : '#808080';
        html += `<div class="powerup-indicator" title="${pu.key}">
          ${pu.icon}
          <div class="powerup-timer">
            <div class="powerup-timer-fill" style="width:${pct}%;background:${color}"></div>
          </div>
        </div>`;
      }
    }
    this.powerupBar.innerHTML = html;
  },

  loop(timestamp) {
    if (this.state !== 'playing') return;

    const dt = Math.min(0.05, (timestamp - this.lastTime) / 1000);
    this.lastTime = timestamp;

    // Update
    Player.update(dt);
    SegmentManager.update(Player.z);
    Chaser.update(dt);
    ParticleSystem.update(dt);

    // Score
    this.score += Player.speed * dt * CFG.SCORE_PER_METER;

    // Coin collection with magnet
    const allObjects = SegmentManager.getAllObjects(Player.z);
    for (const obj of allObjects) {
      if (obj.collected || !obj.active) continue;

      const objLaneW = CFG.LANE_WIDTH;
      const objX = obj.lane * objLaneW;
      const dz = Math.abs(obj.z - Player.z);
      const dx = Math.abs(objX - Player.x);

      // Magnet effect
      if (Player.hasMagnet && obj.type === 'coin' && dz < 8 && dx < this.magnetRange) {
        // Pull coin toward player (handled visually by just collecting)
        obj.collected = true;
        this.sessionCoins += CFG.COIN_VALUE * (1 + SaveManager.getUpgrade('coinMultiplier'));
        const pp = Math3D.project(objX, obj.y || 0.5, obj.z, Player.x, 3, Player.z, 300, Renderer.w, Renderer.h);
        if (pp) {
          ParticleSystem.emit(pp.x, pp.y, 5, '#f0c040', 3, 0.5);
        }
        continue;
      }

      if (obj.type === 'coin') {
        if (dz < 1.0 && dx < 0.8) {
          obj.collected = true;
          this.sessionCoins += CFG.COIN_VALUE * (1 + SaveManager.getUpgrade('coinMultiplier'));
          const pp = Math3D.project(objX, obj.y || 0.5, obj.z, Player.x, 3, Player.z, 300, Renderer.w, Renderer.h);
          if (pp) ParticleSystem.emit(pp.x, pp.y, 5, '#f0c040', 3, 0.5);
        }
      }
      else if (obj.type === 'powerup') {
        if (dz < 1.5 && dx < 1.0 && !Player.invincible) {
          obj.collected = true;
          Player.activatePowerup(obj.subtype);
          const pp = Math3D.project(objX, 1, obj.z, Player.x, 3, Player.z, 300, Renderer.w, Renderer.h);
          if (pp) ParticleSystem.emit(pp.x, pp.y, 15, '#40ff40', 5, 1);
        }
      }
      else if (obj.type === 'barrier_low' || obj.type === 'barrier_high' || obj.type === 'pillar' || obj.type === 'moving_barrier') {
        if (dz < 1.2 && dx < 0.9 && Player.checkCollision(obj)) {
          if (Player.hasHoverboard) {
            // Hoverboard absorbs hit
            obj.active = false;
            Player.hasHoverboard = false;
            Player.invincible = false;
            const pp = Math3D.project(objX, 1, obj.z, Player.x, 3, Player.z, 300, Renderer.w, Renderer.h);
            if (pp) ParticleSystem.emit(pp.x, pp.y, 20, '#40ff80', 6, 1);
          } else if (!Player.invincible) {
            // Hit obstacle
            obj.active = false;
            this.gameOver();
            return;
          }
        }
      }
    }

    // Input handling
    const swipe = InputManager.getSwipe();
    if (swipe === 'left') Player.switchLane(-1);
    else if (swipe === 'right') Player.switchLane(1);
    else if (swipe === 'up') Player.jump();
    else if (swipe === 'down') Player.slide();

    if (InputManager.isPressed('left')) Player.switchLane(-1);
    if (InputManager.isPressed('right')) Player.switchLane(1);
    if (InputManager.isPressed('jump')) Player.jump();
    if (InputManager.isPressed('slide')) Player.slide();

    // Render
    Renderer.clear();

    // Draw segments
    for (const seg of SegmentManager.segments) {
      Renderer.drawSegment(seg);
    }

    // Collect all drawable objects and sort by Z (far to near)
    const drawables = [];

    // Player
    drawables.push({ type: 'player', z: Player.z, playerX: Player.x, playerZ: Player.z, lane: Player.targetLane, y: Player.y, isJumping: Player.isJumping, isSliding: Player.isSliding, hasHoverboard: Player.hasHoverboard, hasJetpack: Player.hasJetpack, scale: 1 });

    // Chaser
    if (Chaser.active) {
      drawables.push({ type: 'chaser', z: Chaser.getZ(), playerX: 0, playerZ: Player.z, lane: 0, y: 1.5 });
    }

    // All segment objects
    for (const seg of SegmentManager.segments) {
      for (const obs of seg.obstacles) {
        if (obs.active) drawables.push({ ...obs, playerX: Player.x, playerZ: Player.z });
      }
      for (const coin of seg.coins) {
        if (coin.active && !coin.collected) drawables.push({ ...coin, playerX: Player.x, playerZ: Player.z });
      }
      for (const pu of seg.powerups) {
        if (pu.active && !pu.collected) drawables.push({ ...pu, playerX: Player.x, playerZ: Player.z });
      }
      for (const mob of seg.movingObstacles) {
        if (mob.active) drawables.push({ ...mob, playerX: Player.x, playerZ: Player.z });
      }
    }

    // Sort far to near
    drawables.sort((a, b) => b.z - a.z);

    // Draw
    for (const obj of drawables) {
      Renderer.drawObject3D(obj);
    }

    // Draw particles
    ParticleSystem.draw();

    // Update UI
    this.updateHUD();
    this.updatePowerupBar();

    requestAnimationFrame(t => this.loop(t));
  }
};

// ============================================================
// INITIALIZATION
// ============================================================
window.addEventListener('load', () => {
  Game.init();
});
</script>
