<title>Pixel RPG - Terraria Style</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #000; overflow: hidden; display: flex; justify-content: center; align-items: center; height: 100vh; font-family: monospace; }
canvas { image-rendering: pixelated; image-rendering: crisp-edges; cursor: crosshair; }
#ui { position: absolute; top: 10px; left: 10px; color: white; pointer-events: none; }
#hotbar { position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%); display: flex; gap: 2px; }
.slot { width: 48px; height: 48px; background: rgba(0,0,0,0.7); border: 2px solid #555; display: flex; align-items: center; justify-content: center; position: relative; }
.slot.active { border-color: #fff; }
.slot canvas { width: 40px; height: 40px; }
.slot .count { position: absolute; bottom: 1px; right: 3px; font-size: 10px; color: #fff; text-shadow: 1px 1px 0 #000; }
#stats { position: absolute; top: 10px; left: 10px; color: white; font-size: 14px; text-shadow: 1px 1px 0 #000; }
.bar-container { width: 200px; height: 16px; background: #333; border: 2px solid #555; margin: 3px 0; position: relative; }
.bar-fill { height: 100%; transition: width 0.3s; }
.bar-text { position: absolute; top: 0; left: 0; width: 100%; text-align: center; font-size: 11px; line-height: 16px; color: white; text-shadow: 1px 1px 0 #000; }
#inventory { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); background: rgba(20,20,40,0.95); border: 3px solid #888; padding: 15px; display: none; }
#inventory h3 { color: #ffcc00; margin-bottom: 10px; text-align: center; }
.inv-grid { display: grid; grid-template-columns: repeat(10, 44px); gap: 3px; }
.inv-slot { width: 44px; height: 44px; background: rgba(0,0,0,0.5); border: 2px solid #444; display: flex; align-items: center; justify-content: center; cursor: pointer; position: relative; }
.inv-slot:hover { border-color: #aaa; }
.inv-slot canvas { width: 36px; height: 36px; }
.inv-slot .count { position: absolute; bottom: 1px; right: 3px; font-size: 10px; color: #fff; }
#msg { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); color: #ffcc00; font-size: 24px; text-shadow: 2px 2px 0 #000; pointer-events: none; opacity: 0; transition: opacity 0.3s; }
#controls { position: absolute; top: 10px; right: 10px; color: #aaa; font-size: 11px; text-align: right; text-shadow: 1px 1px 0 #000; pointer-events: none; }
</style>
</head>
<body>
<canvas id="game"></canvas>
<div id="stats"></div>
<div id="hotbar"></div>
<div id="inventory"><h3>Inventory</h3><div class="inv-grid" id="invGrid"></div></div>
<div id="msg"></div>
<div id="controls">
WASD/Arrows: Move & Jump<br>
Left Click: Mine/Attack<br>
Right Click: Place<br>
E: Inventory<br>
1-9: Hotbar<br>
Space: Attack
</div>
<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = 960, H = 540;
canvas.width = W; canvas.height = H;
canvas.style.width = W + 'px'; canvas.style.height = H + 'px';

const TILE = 16;
const WORLD_W = 500, WORLD_H = 120;
const GRAVITY = 0.45;
const PLAYER_SPEED = 3.5;
const JUMP_FORCE = -8.5;

// Block types
const BLOCKS = {
  AIR: 0, GRASS: 1, DIRT: 2, STONE: 3, WOOD: 4, LEAVES: 5,
  COAL_ORE: 6, IRON_ORE: 7, GOLD_ORE: 8, DIAMOND_ORE: 9,
  PLANKS: 10, BRICK: 11, SAND: 12, SNOW: 13, BEDROCK: 14,
  TORCH: 15, CACTUS: 16, FLOWER_RED: 17, FLOWER_YELLOW: 18,
  MUSHROOM: 19, COPPER_ORE: 20
};

const BLOCK_COLORS = {
  [BLOCKS.AIR]: null,
  [BLOCKS.GRASS]: { top: '#4a8c2a', body: '#6b4226', side: '#5a7a35' },
  [BLOCKS.DIRT]: { color: '#6b4226' },
  [BLOCKS.STONE]: { color: '#7a7a7a' },
  [BLOCKS.WOOD]: { color: '#5c3a1e' },
  [BLOCKS.LEAVES]: { color: '#2d6b1e', transparent: true },
  [BLOCKS.COAL_ORE]: { color: '#555', spots: '#111' },
  [BLOCKS.IRON_ORE]: { color: '#7a7a7a', spots: '#b8860b' },
  [BLOCKS.GOLD_ORE]: { color: '#7a7a7a', spots: '#ffd700' },
  [BLOCKS.DIAMOND_ORE]: { color: '#7a7a7a', spots: '#00e5ff' },
  [BLOCKS.PLANKS]: { color: '#8b6914' },
  [BLOCKS.BRICK]: { color: '#a0522d' },
  [BLOCKS.SAND]: { color: '#e8d686' },
  [BLOCKS.SNOW]: { color: '#f0f0ff' },
  [BLOCKS.BEDROCK]: { color: '#333' },
  [BLOCKS.TORCH]: { color: '#ffaa00', glow: true },
  [BLOCKS.CACTUS]: { color: '#2d8b2d' },
  [BLOCKS.FLOWER_RED]: { color: '#ff3333', transparent: true },
  [BLOCKS.FLOWER_YELLOW]: { color: '#ffdd00', transparent: true },
  [BLOCKS.MUSHROOM]: { color: '#cc4444', transparent: true },
  [BLOCKS.COPPER_ORE]: { color: '#7a7a7a', spots: '#b87333' }
};

const BLOCK_NAMES = {
  [BLOCKS.GRASS]: 'Grass', [BLOCKS.DIRT]: 'Dirt', [BLOCKS.STONE]: 'Stone',
  [BLOCKS.WOOD]: 'Wood', [BLOCKS.PLANKS]: 'Planks', [BLOCKS.BRICK]: 'Brick',
  [BLOCKS.SAND]: 'Sand', [BLOCKS.TORCH]: 'Torch', [BLOCKS.CACTUS]: 'Cactus'
};

const BLOCK_HARDNESS = {
  [BLOCKS.GRASS]: 3, [BLOCKS.DIRT]: 2, [BLOCKS.STONE]: 8, [BLOCKS.WOOD]: 5,
  [BLOCKS.LEAVES]: 1, [BLOCKS.COAL_ORE]: 10, [BLOCKS.IRON_ORE]: 12,
  [BLOCKS.GOLD_ORE]: 15, [BLOCKS.DIAMOND_ORE]: 20, [BLOCKS.PLANKS]: 3,
  [BLOCKS.BRICK]: 10, [BLOCKS.SAND]: 1, [BLOCKS.SNOW]: 1,
  [BLOCKS.BEDROCK]: 999, [BLOCKS.TORCH]: 0, [BLOCKS.CACTUS]: 2,
  [BLOCKS.FLOWER_RED]: 0, [BLOCKS.FLOWER_YELLOW]: 0, [BLOCKS.MUSHROOM]: 0,
  [BLOCKS.COPPER_ORE]: 8
};

// Game state
let world = [];
let camera = { x: 0, y: 0 };
let player = {
  x: 250 * TILE, y: 0, w: 12, h: 28,
  vx: 0, vy: 0, onGround: false,
  hp: 100, maxHp: 100,
  xp: 0, level: 1, nextXp: 50,
  attack: 10, defense: 2,
  facing: 1, mining: null, mineProgress: 0,
  attackCooldown: 0, invincible: 0,
  hotbar: new Array(9).fill(null),
  inventory: new Array(40).fill(null),
  selectedSlot: 0
};

let enemies = [];
let particles = [];
let projectiles = [];
let time = 0;
let dayTime = 0;
let dayLength = 3600;
let keys = {};
let mouse = { x: 0, y: 0, left: false, right: false };
let showInventory = false;
let messages = [];
let spawnTimer = 0;
let worldSeed = Math.random() * 99999;

// Simple noise function
function noise(x, seed) {
  let n = Math.sin(x * 127.1 + seed * 311.7) * 43758.5453;
  return n - Math.floor(n);
}

function smoothNoise(x, seed) {
  let ix = Math.floor(x);
  let fx = x - ix;
  fx = fx * fx * (3 - 2 * fx);
  return noise(ix, seed) * (1 - fx) + noise(ix + 1, seed) * fx;
}

function terrainHeight(x) {
  let h = 40;
  h += smoothNoise(x * 0.02, worldSeed) * 15;
  h += smoothNoise(x * 0.05, worldSeed + 100) * 8;
  h += smoothNoise(x * 0.1, worldSeed + 200) * 3;
  return Math.floor(h);
}

function generateWorld() {
  world = [];
  for (let x = 0; x < WORLD_W; x++) {
    world[x] = new Array(WORLD_H).fill(BLOCKS.AIR);
  }

  for (let x = 0; x < WORLD_W; x++) {
    let surfaceY = terrainHeight(x);
    let biome = getBiome(x);

    for (let y = surfaceY; y < WORLD_H; y++) {
      if (y === surfaceY) {
        if (biome === 'desert') world[x][y] = BLOCKS.SAND;
        else if (biome === 'snow') world[x][y] = BLOCKS.SNOW;
        else world[x][y] = BLOCKS.GRASS;
      } else if (y < surfaceY + 5) {
        if (biome === 'desert') world[x][y] = BLOCKS.SAND;
        else if (biome === 'snow') world[x][y] = BLOCKS.SNOW;
        else world[x][y] = BLOCKS.DIRT;
      } else {
        if (y > surfaceY + 30 && Math.random() < 0.02) {
          world[x][y] = BLOCKS.DIAMOND_ORE;
        } else if (y > surfaceY + 20 && Math.random() < 0.04) {
          world[x][y] = BLOCKS.GOLD_ORE;
        } else if (y > surfaceY + 10 && Math.random() < 0.06) {
          world[x][y] = BLOCKS.IRON_ORE;
        } else if (y > surfaceY + 5 && Math.random() < 0.08) {
          world[x][y] = BLOCKS.COAL_ORE;
        } else if (y > surfaceY + 3 && Math.random() < 0.05) {
          world[x][y] = BLOCKS.COPPER_ORE;
        } else {
          world[x][y] = BLOCKS.STONE;
        }
      }

      // Caves
      if (y > surfaceY + 3 && y < WORLD_H - 2) {
        let cave = smoothNoise(x * 0.08, y * 0.08 + worldSeed + 500);
        let cave2 = smoothNoise(x * 0.12, y * 0.12 + worldSeed + 600);
        if (cave > 0.55 && cave2 > 0.5) {
          world[x][y] = BLOCKS.AIR;
        }
      }
    }

    // Bedrock at bottom
    for (let y = WORLD_H - 3; y < WORLD_H; y++) {
      world[x][y] = BLOCKS.BEDROCK;
    }

    // Trees
    if (x > 5 && x < WORLD_W - 5 && Math.random() < 0.06) {
      let biome = getBiome(x);
      if (biome === 'forest' || biome === 'plains') {
        let treeH = 5 + Math.floor(Math.random() * 4);
        let sy = surfaceY;
        if (world[x][sy] === BLOCKS.GRASS) {
          for (let ty = 1; ty <= treeH; ty++) {
            if (sy - ty >= 0) world[x][sy - ty] = BLOCKS.WOOD;
          }
          // Leaves
          for (let lx = -2; lx <= 2; lx++) {
            for (let ly = -3; ly <= -1; ly++) {
              let wx = x + lx, wy = sy - treeH + ly;
              if (wx >= 0 && wx < WORLD_W && wy >= 0 && wy < WORLD_H) {
                if (world[wx][wy] === BLOCKS.AIR && Math.abs(lx) + Math.abs(ly) < 5) {
                  world[wx][wy] = BLOCKS.LEAVES;
                }
              }
            }
          }
        }
      }
    }

    // Flowers
    if (Math.random() < 0.03) {
      let sy = surfaceY;
      if (sy > 0 && world[x][sy] === BLOCKS.GRASS && world[x][sy - 1] === BLOCKS.AIR) {
        world[x][sy - 1] = Math.random() < 0.5 ? BLOCKS.FLOWER_RED : BLOCKS.FLOWER_YELLOW;
      }
    }

    // Mushrooms in caves
    if (Math.random() < 0.005) {
      let sy = surfaceY;
      for (let y = sy + 5; y < sy + 20; y++) {
        if (world[x][y] === BLOCKS.AIR && world[x][y + 1] !== BLOCKS.AIR) {
          world[x][y] = BLOCKS.MUSHROOM;
          break;
        }
      }
    }
  }

  // Place player
  let spawnX = Math.floor(WORLD_W / 2);
  let spawnY = terrainHeight(spawnX);
  player.x = spawnX * TILE;
  player.y = (spawnY - 3) * TILE;
}

function getBiome(x) {
  let t = smoothNoise(x * 0.005, worldSeed + 700);
  if (t < 0.3) return 'forest';
  if (t < 0.5) return 'plains';
  if (t < 0.7) return 'desert';
  return 'snow';
}

function getBlock(x, y) {
  if (x < 0 || x >= WORLD_W || y < 0 || y >= WORLD_H) return BLOCKS.BEDROCK;
  return world[x][y];
}

function setBlock(x, y, type) {
  if (x < 0 || x >= WORLD_W || y < 0 || y >= WORLD_H) return;
  world[x][y] = type;
}

function isSolid(x, y) {
  let b = getBlock(x, y);
  return b !== BLOCKS.AIR && !BLOCK_COLORS[b]?.transparent;
}

function isTransparent(x, y) {
  let b = getBlock(x, y);
  return b !== BLOCKS.AIR && BLOCK_COLORS[b]?.transparent;
}

// Player physics
function updatePlayer() {
  // Movement
  let moveX = 0;
  if (keys['KeyA'] || keys['ArrowLeft']) moveX = -1;
  if (keys['KeyD'] || keys['ArrowRight']) moveX = 1;

  player.vx = moveX * PLAYER_SPEED;
  if (moveX !== 0) player.facing = moveX;

  // Jump
  if ((keys['KeyW'] || keys['ArrowUp'] || keys['Space'] && player.attackCooldown <= 0) && player.onGround) {
    player.vy = JUMP_FORCE;
    player.onGround = false;
  }

  // Attack
  if (player.attackCooldown > 0) player.attackCooldown--;

  if ((keys['Space'] || mouse.left) && player.attackCooldown <= 0) {
    performAttack();
  }

  // Gravity
  player.vy += GRAVITY;
  if (player.vy > 12) player.vy = 12;

  // Horizontal collision
  player.x += player.vx;
  resolveCollisionX();

  // Vertical collision
  player.y += player.vy;
  player.onGround = false;
  resolveCollisionY();

  // World bounds
  player.x = Math.max(0, Math.min(player.x, (WORLD_W - 1) * TILE));
  if (player.y > WORLD_H * TILE) {
    player.hp = 0;
    respawnPlayer();
  }

  if (player.invincible > 0) player.invincible--;

  // Mining
  if (mouse.left && !showInventory) {
    let wx = Math.floor((mouse.x + camera.x) / TILE);
    let wy = Math.floor((mouse.y + camera.y) / TILE);
    let dx = wx * TILE + TILE / 2 - (player.x + player.w / 2);
    let dy = wy * TILE + TILE / 2 - (player.y + player.h / 2);
    let dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < 6 * TILE && isSolid(wx, wy)) {
      let key = wx + ',' + wy;
      if (player.mining === key) {
        player.mineProgress++;
        let hardness = BLOCK_HARDNESS[getBlock(wx, wy)] || 1;
        if (player.mineProgress >= hardness * 3) {
          let block = getBlock(wx, wy);
          if (block !== BLOCKS.AIR && BLOCK_HARDNESS[block] < 999) {
            // Drop item
            let drop = block;
            if (Math.random() < 0.3 && [BLOCKS.FLOWER_RED, BLOCKS.FLOWER_YELLOW, BLOCKS.MUSHROOM].includes(block)) {
              drop = block;
            }
            addToInventory(drop, 1);
            spawnParticles(wx * TILE + 8, wy * TILE + 8, BLOCK_COLORS[block]?.color || '#888', 8);
            showMessage(BLOCK_NAMES[block] || 'Block', 1000);
          }
          setBlock(wx, wy, BLOCKS.AIR);
          player.mineProgress = 0;
          player.mining = null;
        }
      } else {
        player.mining = key;
        player.mineProgress = 0;
      }
    } else {
      player.mining = null;
      player.mineProgress = 0;
    }
  } else {
    player.mining = null;
    player.mineProgress = 0;
  }

  // Placing blocks
  if (mouse.right && !showInventory) {
    let wx = Math.floor((mouse.x + camera.x) / TILE);
    let wy = Math.floor((mouse.y + camera.y) / TILE);
    let dx = wx * TILE + TILE / 2 - (player.x + player.w / 2);
    let dy = wy * TILE + TILE / 2 - (player.y + player.h / 2);
    let dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < 6 * TILE && getBlock(wx, wy) === BLOCKS.AIR) {
      // Check not placing inside player
      let px1 = Math.floor(player.x / TILE), px2 = Math.floor((player.x + player.w) / TILE);
      let py1 = Math.floor(player.y / TILE), py2 = Math.floor((player.y + player.h) / TILE);
      if (!(wx >= px1 && wx <= px2 && wy >= py1 && wy <= py2)) {
        let item = player.hotbar[player.selectedSlot];
        if (item && item.count > 0) {
          setBlock(wx, wy, item.type);
          item.count--;
          if (item.count <= 0) player.hotbar[player.selectedSlot] = null;
          spawnParticles(wx * TILE + 8, wy * TILE + 8, '#aaa', 4);
        }
      }
    }
    mouse.right = false; // Only place on click
  }

  // Invincibility frames
  if (player.invincible > 0) player.invincible--;
}

function performAttack() {
  player.attackCooldown = 15;
  let reach = 5 * TILE;
  let hit = false;

  // Check enemies
  for (let e of enemies) {
    let dx = (e.x + e.w / 2) - (player.x + player.w / 2);
    let dy = (e.y + e.h / 2) - (player.y + player.h / 2);
    let dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < reach) {
      let dmg = player.attack + Math.floor(Math.random() * 5);
      e.hp -= dmg;
      e.knockback = player.facing * 6;
      e.hitFlash = 8;
      spawnParticles(e.x + e.w / 2, e.y + e.h / 2, '#ff0', 6);
      hit = true;
      if (e.hp <= 0) {
        let xpGain = e.xpValue;
        player.xp += xpGain;
        spawnParticles(e.x + e.w / 2, e.y + e.h / 2, e.color || '#f00', 15);
        showMessage(`+${xpGain} XP`, 1000);
        checkLevelUp();
      }
    }
  }

  // Sword swing particles
  let sx = player.x + player.w / 2 + player.facing * 20;
  let sy = player.y + player.h / 2;
  for (let i = 0; i < 5; i++) {
    particles.push({
      x: sx, y: sy,
      vx: player.facing * (2 + Math.random() * 3),
      vy: -2 + Math.random() * 4,
      life: 15, maxLife: 15,
      color: '#fff', size: 3
    });
  }
}

function checkLevelUp() {
  while (player.xp >= player.nextXp) {
    player.xp -= player.nextXp;
    player.level++;
    player.maxHp += 15;
    player.hp = player.maxHp;
    player.attack += 3;
    player.defense += 1;
    player.nextXp = Math.floor(player.nextXp * 1.5);
    showMessage(`Level Up! Level ${player.level}!`, 2500);
    spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#ffcc00', 30);
  }
}

function resolveCollisionX() {
  let x1 = Math.floor(player.x / TILE);
  let x2 = Math.floor((player.x + player.w) / TILE);
  let y1 = Math.floor(player.y / TILE);
  let y2 = Math.floor((player.y + player.h - 1) / TILE);

  for (let x = x1; x <= x2; x++) {
    for (let y = y1; y <= y2; y++) {
      if (isSolid(x, y)) {
        if (player.vx > 0) player.x = x * TILE - player.w - 0.01;
        else if (player.vx < 0) player.x = (x + 1) * TILE + 0.01;
        player.vx = 0;
      }
    }
  }
}

function resolveCollisionY() {
  let x1 = Math.floor(player.x / TILE);
  let x2 = Math.floor((player.x + player.w - 1) / TILE);
  let y1 = Math.floor(player.y / TILE);
  let y2 = Math.floor((player.y + player.h) / TILE);

  for (let x = x1; x <= x2; x++) {
    for (let y = y1; y <= y2; y++) {
      if (isSolid(x, y)) {
        if (player.vy > 0) {
          player.y = y * TILE - player.h - 0.01;
          player.onGround = true;
        } else if (player.vy < 0) {
          player.y = (y + 1) * TILE + 0.01;
        }
        player.vy = 0;
      }
    }
  }
}

function respawnPlayer() {
  let spawnX = Math.floor(WORLD_W / 2);
  let spawnY = terrainHeight(spawnX);
  player.x = spawnX * TILE;
  player.y = (spawnY - 3) * TILE;
  player.hp = player.maxHp;
  player.vy = 0;
  player.invincible = 120;
  showMessage('You died!', 2000);
}

// Inventory
function addToInventory(type, count) {
  // Stack first
  for (let i = 0; i < player.inventory.length; i++) {
    if (player.inventory[i] && player.inventory[i].type === type && player.inventory[i].count < 64) {
      player.inventory[i].count += count;
      return true;
    }
  }
  // New slot
  for (let i = 0; i < player.inventory.length; i++) {
    if (!player.inventory[i]) {
      player.inventory[i] = { type, count };
      return true;
    }
  }
  return false;
}

function removeFromHotbar(slot) {
  if (player.hotbar[slot]) {
    let item = player.hotbar[slot];
    player.hotbar[slot] = null;
    addToInventory(item.type, item.count);
  }
}

// Enemies
function spawnEnemy() {
  let side = Math.random() < 0.5 ? -1 : 1;
  let spawnX = player.x + side * (W / 2 + Math.random() * 200);
  let spawnTileX = Math.floor(spawnX / TILE);
  if (spawnTileX < 1 || spawnTileX >= WORLD_W - 1) return;

  let spawnY = 0;
  for (let y = 0; y < WORLD_H; y++) {
    if (isSolid(spawnTileX, y)) { spawnY = (y - 1) * TILE; break; }
  }

  let biome = getBiome(spawnTileX);
  let type;
  let r = Math.random();
  if (spawnY > (terrainHeight(spawnTileX) + 15) * TILE) {
    type = r < 0.5 ? 'skeleton' : 'bat';
  } else if (biome === 'desert') {
    type = r < 0.6 ? 'cactus_slime' : 'scorpion';
  } else if (biome === 'snow') {
    type = r < 0.5 ? 'ice_slime' : 'yeti';
  } else {
    type = r < 0.4 ? 'slime' : r < 0.7 ? 'zombie' : 'skeleton';
  }

  let enemy = {
    x: spawnX, y: spawnY, w: 14, h: 16,
    vx: 0, vy: 0, hp: 20, maxHp: 20,
    type, attack: 5, speed: 1, xpValue: 10,
    onGround: false, hitFlash: 0, knockback: 0,
    color: '#f44', aiTimer: 0, aiState: 'idle',
    jumpTimer: 0
  };

  switch (type) {
    case 'slime':
      enemy.hp = 15; enemy.maxHp = 15; enemy.color = '#4a4'; enemy.xpValue = 8;
      enemy.h = 14; enemy.w = 14;
      break;
    case 'zombie':
      enemy.hp = 30; enemy.maxHp = 30; enemy.color = '#4a4'; enemy.xpValue = 15;
      enemy.attack = 8; enemy.speed = 1.2; enemy.h = 26; enemy.w = 12;
      break;
    case 'skeleton':
      enemy.hp = 25; enemy.maxHp = 25; enemy.color = '#ddd'; enemy.xpValue = 20;
      enemy.attack = 10; enemy.speed = 1.5; enemy.h = 24; enemy.w = 12;
      break;
    case 'bat':
      enemy.hp = 10; enemy.maxHp = 10; enemy.color = '#84a'; enemy.xpValue = 5;
      enemy.flying = true; enemy.speed = 2; enemy.h = 10; enemy.w = 12;
      break;
    case 'cactus_slime':
      enemy.hp = 20; enemy.maxHp = 20; enemy.color = '#2a2'; enemy.xpValue = 12;
      enemy.h = 14; enemy.w = 14; enemy.attack = 6;
      break;
    case 'scorpion':
      enemy.hp = 25; enemy.maxHp = 25; enemy.color = '#a82'; enemy.xpValue = 18;
      enemy.attack = 12; enemy.speed = 1.8; enemy.h = 12; enemy.w = 16;
      break;
    case 'ice_slime':
      enemy.hp = 18; enemy.maxHp = 18; enemy.color = '#8cf'; enemy.xpValue = 10;
      enemy.h = 14; enemy.w = 14;
      break;
    case 'yeti':
      enemy.hp = 50; enemy.maxHp = 50; enemy.color = '#eef'; enemy.xpValue = 35;
      enemy.attack = 15; enemy.speed = 1.3; enemy.h = 28; enemy.w = 14;
      break;
  }

  enemies.push(enemy);
}

function updateEnemies() {
  // Spawn
  spawnTimer++;
  let maxEnemies = 15;
  if (spawnTimer > 180 && enemies.length < maxEnemies) {
    spawnEnemy();
    spawnTimer = 0;
  }

  // Despawn far enemies
  enemies = enemies.filter(e => {
    let dx = e.x - player.x;
    return Math.abs(dx) < W * 1.5;
  });

  for (let e of enemies) {
    if (e.hitFlash > 0) e.hitFlash--;

    let dx = player.x - e.x;
    let dy = player.y - e.y;
    let dist = Math.sqrt(dx * dx + dy * dy);

    e.aiTimer++;

    // AI
    if (e.flying) {
      e.vx = (dx > 0 ? 1 : -1) * e.speed * 0.8;
      e.vy = Math.sin(e.aiTimer * 0.05) * 1.5;
    } else {
      // Movement
      if (dist < 300) {
        e.vx = (dx > 0 ? 1 : -1) * e.speed;
        // Jump over obstacles
        let aheadX = Math.floor((e.x + (dx > 0 ? e.w + 2 : -2)) / TILE);
        let belowY = Math.floor((e.y + e.h + 2) / TILE);
        if (isSolid(aheadX, belowY) && e.onGround) {
          e.vy = -7;
          e.onGround = false;
        }
        // Jump gaps
        let gapX = Math.floor((e.x + (dx > 0 ? e.w + 4 : -4)) / TILE);
        let gapY = Math.floor((e.y + e.h + 2) / TILE);
        if (!isSolid(gapX, gapY) && e.onGround && Math.random() < 0.05) {
          e.vy = -7;
          e.onGround = false;
        }
      } else {
        // Wander
        if (e.aiTimer % 120 === 0) {
          e.vx = (Math.random() - 0.5) * e.speed * 2;
        }
      }

      // Gravity
      e.vy += GRAVITY;
      if (e.vy > 10) e.vy = 10;
    }

    // Apply knockback
    if (e.knockback !== 0) {
      e.vx = e.knockback;
      e.knockback *= 0.7;
      if (Math.abs(e.knockback) < 0.5) e.knockback = 0;
    }

    // Move X
    e.x += e.vx;
    // Collision X
    let ex1 = Math.floor(e.x / TILE), ex2 = Math.floor((e.x + e.w) / TILE);
    let ey1 = Math.floor(e.y / TILE), ey2 = Math.floor((e.y + e.h - 1) / TILE);
    for (let x = ex1; x <= ex2; x++) {
      for (let y = ey1; y <= ey2; y++) {
        if (isSolid(x, y)) {
          if (e.vx > 0) e.x = x * TILE - e.w - 0.01;
          else e.x = (x + 1) * TILE + 0.01;
          e.vx = 0;
        }
      }
    }

    // Move Y
    e.y += e.vy;
    e.onGround = false;
    // Collision Y
    ex1 = Math.floor(e.x / TILE); ex2 = Math.floor((e.x + e.w - 1) / TILE);
    ey1 = Math.floor(e.y / TILE); ey2 = Math.floor((e.y + e.h) / TILE);
    for (let x = ex1; x <= ex2; x++) {
      for (let y = ey1; y <= ey2; y++) {
        if (isSolid(x, y)) {
          if (e.vy > 0) { e.y = y * TILE - e.h - 0.01; e.onGround = true; }
          else if (e.vy < 0) { e.y = (y + 1) * TILE + 0.01; }
          e.vy = 0;
        }
      }
    }

    // Damage player
    if (player.invincible <= 0 && !e.flying) {
      if (rectsOverlap(player, e)) {
        let dmg = Math.max(1, e.attack - player.defense);
        player.hp -= dmg;
        player.invincible = 30;
        player.vx = (player.x < e.x ? 1 : -1) * 5;
        player.vy = -3;
        spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#f00', 5);
        if (player.hp <= 0) {
          player.hp = 0;
          respawnPlayer();
        }
      }
    }

    // Fall death
    if (e.y > WORLD_H * TILE) e.hp = 0;
  }

  enemies = enemies.filter(e => e.hp > 0);
}

function rectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

// Particles
function spawnParticles(x, y, color, count) {
  for (let i = 0; i < count; i++) {
    particles.push({
      x, y,
      vx: (Math.random() - 0.5) * 4,
      vy: (Math.random() - 0.5) * 4 - 2,
      life: 20 + Math.random() * 20,
      maxLife: 40,
      color,
      size: 2 + Math.random() * 3
    });
  }
}

function updateParticles() {
  for (let p of particles) {
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.15;
    p.life--;
  }
  particles = particles.filter(p => p.life > 0);
}

// Day/Night
function updateDayNight() {
  dayTime++;
  if (dayTime >= dayLength) dayTime = 0;
}

function getSkyColor() {
  let t = dayTime / dayLength;
  if (t < 0.25) return lerpColor('#1a0a3e', '#87CEEB', t * 4);
  if (t < 0.5) return '#87CEEB';
  if (t < 0.6) return lerpColor('#87CEEB', '#ff6b35', (t - 0.5) * 10);
  if (t < 0.75) return lerpColor('#ff6b35', '#1a0a3e', (t - 0.6) * 6.67);
  return '#1a0a3e';
}

function getAmbientLight() {
  let t = dayTime / dayLength;
  if (t < 0.2) return 0.3 + t * 3.5;
  if (t < 0.5) return 1.0;
  if (t < 0.7) return 1.0 - (t - 0.5) * 1.5;
  return 0.25;
}

function lerpColor(a, b, t) {
  let ar = parseInt(a.slice(1, 3), 16), ag = parseInt(a.slice(3, 5), 16), ab = parseInt(a.slice(5, 7), 16);
  let br = parseInt(b.slice(1, 3), 16), bg = parseInt(b.slice(3, 5), 16), bb = parseInt(b.slice(5, 7), 16);
  let r = Math.floor(ar + (br - ar) * t);
  let g = Math.floor(ag + (bg - ag) * t);
  let bl = Math.floor(ab + (bb - ab) * t);
  return `rgb(${r},${g},${bl})`;
}

// Rendering
function drawPixel(x, y, w, h, color) {
  ctx.fillStyle = color;
  ctx.fillRect(Math.floor(x - camera.x), Math.floor(y - camera.y), w, h);
}

function drawBlock(x, y, type) {
  let sx = Math.floor(x * TILE - camera.x);
  let sy = Math.floor(y * TILE - camera.y);
  if (sx < -TILE || sx > W + TILE || sy < -TILE || sy > H + TILE) return;

  let colors = BLOCK_COLORS[type];
  if (!colors) return;

  if (colors.glow) {
    ctx.fillStyle = '#ff8800';
    ctx.fillRect(sx + 6, sy + 2, 4, 12);
    ctx.fillStyle = '#ffcc00';
    ctx.fillRect(sx + 5, sy, 6, 4);
    // Glow effect
    let grd = ctx.createRadialGradient(sx + 8, sy + 4, 2, sx + 8, sy + 4, 60);
    grd.addColorStop(0, 'rgba(255,200,50,0.3)');
    grd.addColorStop(1, 'rgba(255,200,50,0)');
    ctx.fillStyle = grd;
    ctx.fillRect(sx - 52, sy - 56, 120, 120);
    return;
  }

  if (colors.transparent) {
    ctx.fillStyle = colors.color;
    ctx.fillRect(sx, sy, TILE, TILE);
    // Pixel art details
    if (type === BLOCKS.LEAVES) {
      ctx.fillStyle = '#3a8a28';
      for (let i = 0; i < 6; i++) {
        let px = (i * 7 + x * 3) % 14;
        let py = (i * 11 + y * 5) % 14;
        ctx.fillRect(sx + px, sy + py, 2, 2);
      }
    } else if (type === BLOCKS.FLOWER_RED || type === BLOCKS.FLOWER_YELLOW) {
      ctx.fillStyle = '#2a8a2a';
      ctx.fillRect(sx + 7, sy + 6, 2, 10);
      ctx.fillStyle = colors.color;
      ctx.fillRect(sx + 4, sy + 2, 8, 6);
      ctx.fillStyle = '#ff0';
      ctx.fillRect(sx + 6, sy + 4, 4, 4);
    } else if (type === BLOCKS.MUSHROOM) {
      ctx.fillStyle = '#ddd';
      ctx.fillRect(sx + 7, sy + 6, 2, 10);
      ctx.fillStyle = '#cc2222';
      ctx.fillRect(sx + 3, sy + 2, 10, 6);
      ctx.fillStyle = '#fff';
      ctx.fillRect(sx + 5, sy + 3, 2, 2);
      ctx.fillRect(sx + 9, sy + 4, 2, 2);
    }
    return;
  }

  // Solid blocks
  if (type === BLOCKS.GRASS) {
    ctx.fillStyle = colors.top;
    ctx.fillRect(sx, sy, TILE, 3);
    ctx.fillStyle = colors.body;
    ctx.fillRect(sx, sy + 3, TILE, TILE - 3);
    // Grass detail
    ctx.fillStyle = '#5a9a35';
    for (let i = 0; i < 3; i++) {
      ctx.fillRect(sx + (i * 5 + x) % 14, sy, 2, 2);
    }
  } else if (colors.spots) {
    ctx.fillStyle = colors.color;
    ctx.fillRect(sx, sy, TILE, TILE);
    ctx.fillStyle = colors.spots;
    for (let i = 0; i < 4; i++) {
      let px = ((i * 7 + x * 3 + y * 5) % 10) + 2;
      let py = ((i * 11 + x * 7 + y * 3) % 10) + 2;
      ctx.fillRect(sx + px, sy + py, 3, 3);
    }
  } else {
    ctx.fillStyle = colors.color;
    ctx.fillRect(sx, sy, TILE, TILE);
    // Brick pattern
    if (type === BLOCKS.BRICK) {
      ctx.fillStyle = '#8b4513';
      ctx.fillRect(sx, sy + 7, TILE, 1);
      ctx.fillRect(sx + 7, sy, 1, 7);
      ctx.fillRect(sx + 3, sy + 8, 1, 8);
      ctx.fillRect(sx + 11, sy + 8, 1, 8);
    }
    // Wood grain
    if (type === BLOCKS.WOOD) {
      ctx.fillStyle = '#4a2e14';
      ctx.fillRect(sx + 4, sy, 1, TILE);
      ctx.fillRect(sx + 10, sy, 1, TILE);
    }
    // Plank lines
    if (type === BLOCKS.PLANKS) {
      ctx.fillStyle = '#6b5010';
      ctx.fillRect(sx, sy + 7, TILE, 1);
      ctx.fillRect(sx, sy + 15, TILE, 1);
    }
  }

  // Block shading
  ctx.fillStyle = 'rgba(0,0,0,0.1)';
  ctx.fillRect(sx, sy + TILE - 1, TILE, 1);
  ctx.fillRect(sx + TILE - 1, sy, 1, TILE);
  ctx.fillStyle = 'rgba(255,255,255,0.05)';
  ctx.fillRect(sx, sy, TILE, 1);
  ctx.fillRect(sx, sy, 1, TILE);
}

function drawPlayer() {
  let sx = player.x - camera.x;
  let sy = player.y - camera.y;

  if (player.invincible > 0 && Math.floor(player.invincible / 3) % 2 === 0) return;

  // Body
  ctx.fillStyle = '#4488cc';
  ctx.fillRect(sx + 2, sy + 8, 8, 12);

  // Head
  ctx.fillStyle = '#ffcc88';
  ctx.fillRect(sx + 2, sy, 8, 8);

  // Hair
  ctx.fillStyle = '#553322';
  ctx.fillRect(sx + 2, sy, 8, 3);
  ctx.fillRect(sx + (player.facing > 0 ? 6 : 2), sy + 1, 2, 4);

  // Eyes
  ctx.fillStyle = '#fff';
  ctx.fillRect(sx + (player.facing > 0 ? 6 : 3), sy + 4, 2, 2);
  ctx.fillStyle = '#224';
  ctx.fillRect(sx + (player.facing > 0 ? 7 : 3), sy + 4, 1, 2);

  // Legs
  ctx.fillStyle = '#444488';
  let legOffset = player.onGround && Math.abs(player.vx) > 0.5 ? Math.sin(time * 0.3) * 2 : 0;
  ctx.fillRect(sx + 2, sy + 20, 3, 8 + legOffset);
  ctx.fillRect(sx + 7, sy + 20, 3, 8 - legOffset);

  // Shoes
  ctx.fillStyle = '#553322';
  ctx.fillRect(sx + 1, sy + 26 + legOffset, 5, 2);
  ctx.fillRect(sx + 6, sy + 26 - legOffset, 5, 2);

  // Arms
  ctx.fillStyle = '#ffcc88';
  let armSwing = Math.sin(time * 0.2) * 2;
  ctx.fillRect(sx - 1, sy + 10 + armSwing, 3, 8);
  ctx.fillRect(sx + 10, sy + 10 - armSwing, 3, 8);

  // Sword
  if (player.attackCooldown > 10) {
    ctx.fillStyle = '#ccc';
    let swordAngle = player.facing > 0 ? -0.5 : 0.5;
    ctx.save();
    ctx.translate(sx + (player.facing > 0 ? 13 : -1), sy + 12);
    ctx.rotate(swordAngle);
    ctx.fillRect(0, -1, 14, 2);
    ctx.fillStyle = '#8b6914';
    ctx.fillRect(-2, -2, 4, 4);
    ctx.restore();
  } else {
    // Resting sword
    ctx.fillStyle = '#aaa';
    ctx.fillRect(sx + (player.facing > 0 ? 11 : -5), sy + 14, 2, 10);
    ctx.fillStyle = '#8b6914';
    ctx.fillRect(sx + (player.facing > 0 ? 10 : -6), sy + 13, 4, 2);
  }
}

function drawEnemy(e) {
  let sx = e.x - camera.x;
  let sy = e.y - camera.y;

  if (sx < -50 || sx > W + 50 || sy < -50 || sy > H + 50) return;

  // Hit flash
  if (e.hitFlash > 0) {
    ctx.fillStyle = '#fff';
    ctx.fillRect(sx - 2, sy - 2, e.w + 4, e.h + 4);
  }

  switch (e.type) {
    case 'slime':
    case 'cactus_slime':
    case 'ice_slime':
      let squish = 1 + Math.sin(time * 0.1) * 0.1;
      ctx.fillStyle = e.color;
      ctx.fillRect(sx, sy + 2, e.w, e.h - 2);
      ctx.fillRect(sx + 2, sy, e.w - 4, e.h);
      // Eyes
      ctx.fillStyle = '#fff';
      ctx.fillRect(sx + 3, sy + 4, 3, 3);
      ctx.fillRect(sx + e.w - 6, sy + 4, 3, 3);
      ctx.fillStyle = '#000';
      ctx.fillRect(sx + 4, sy + 5, 2, 2);
      ctx.fillRect(sx + e.w - 5, sy + 5, 2, 2);
      break;

    case 'zombie':
      ctx.fillStyle = '#4a4';
      ctx.fillRect(sx + 2, sy + 6, 8, 14);
      ctx.fillStyle = '#ffcc88';
      ctx.fillRect(sx + 2, sy, 8, 8);
      ctx.fillStyle = '#333';
      ctx.fillRect(sx + 3, sy + 3, 2, 2);
      ctx.fillRect(sx + 7, sy + 3, 2, 2);
      ctx.fillStyle = '#4a4';
      ctx.fillRect(sx + 1, sy + 20, 4, 6);
      ctx.fillRect(sx + 7, sy + 20, 4, 6);
      // Arms reaching
      ctx.fillStyle = '#ffcc88';
      ctx.fillRect(sx + (e.vx > 0 ? 10 : -4), sy + 8, 4, 6);
      break;

    case 'skeleton':
      ctx.fillStyle = '#ddd';
      ctx.fillRect(sx + 2, sy + 4, 8, 12);
      ctx.fillStyle = '#eee';
      ctx.fillRect(sx + 2, sy, 8, 8);
      ctx.fillStyle = '#000';
      ctx.fillRect(sx + 3, sy + 3, 2, 3);
      ctx.fillRect(sx + 7, sy + 3, 2, 3);
      ctx.fillStyle = '#ddd';
      ctx.fillRect(sx + 1, sy + 16, 3, 8);
      ctx.fillRect(sx + 8, sy + 16, 3, 8);
      // Ribs
      ctx.fillStyle = '#ccc';
      ctx.fillRect(sx + 3, sy + 7, 6, 1);
      ctx.fillRect(sx + 3, sy + 10, 6, 1);
      break;

    case 'bat':
      ctx.fillStyle = e.color;
      ctx.fillRect(sx + 4, sy + 2, 6, 6);
      let wingFlap = Math.sin(time * 0.3) * 4;
      ctx.fillRect(sx, sy + wingFlap, 5, 4);
      ctx.fillRect(sx + 9, sy - wingFlap, 5, 4);
      ctx.fillStyle = '#f00';
      ctx.fillRect(sx + 5, sy + 3, 1, 1);
      ctx.fillRect(sx + 8, sy + 3, 1, 1);
      break;

    case 'scorpion':
      ctx.fillStyle = e.color;
      ctx.fillRect(sx, sy + 4, e.w, 6);
      ctx.fillRect(sx + 2, sy, 8, 6);
      // Tail
      ctx.fillRect(sx + e.w - 2, sy - 4, 2, 6);
      ctx.fillRect(sx + e.w, sy - 6, 2, 4);
      // Stinger
      ctx.fillStyle = '#f00';
      ctx.fillRect(sx + e.w, sy - 8, 2, 3);
      // Eyes
      ctx.fillStyle = '#ff0';
      ctx.fillRect(sx + 3, sy + 2, 2, 2);
      break;

    case 'yeti':
      ctx.fillStyle = '#eef';
      ctx.fillRect(sx + 1, sy + 6, 12, 16);
      ctx.fillStyle = '#fff';
      ctx.fillRect(sx + 1, sy, 12, 10);
      ctx.fillStyle = '#333';
      ctx.fillRect(sx + 3, sy + 4, 2, 2);
      ctx.fillRect(sx + 9, sy + 4, 2, 2);
      ctx.fillStyle = '#eef';
      ctx.fillRect(sx, sy + 22, 5, 6);
      ctx.fillRect(sx + 9, sy + 22, 5, 6);
      // Fur detail
      ctx.fillStyle = '#dde';
      for (let i = 0; i < 5; i++) {
        ctx.fillRect(sx + (i * 3 + 1) % 12, sy + 8 + (i % 3) * 3, 2, 2);
      }
      break;
  }

  // Health bar
  if (e.hp < e.maxHp) {
    ctx.fillStyle = '#333';
    ctx.fillRect(sx, sy - 8, e.w, 4);
    ctx.fillStyle = '#f00';
    ctx.fillRect(sx, sy - 8, e.w * (e.hp / e.maxHp), 4);
  }
}

function drawMiningProgress() {
  if (player.mining && player.mineProgress > 0) {
    let [wx, wy] = player.mining.split(',').map(Number);
    let sx = wx * TILE - camera.x;
    let sy = wy * TILE - camera.y;
    let hardness = BLOCK_HARDNESS[getBlock(wx, wy)] || 1;
    let progress = player.mineProgress / (hardness * 3);

    ctx.fillStyle = `rgba(0,0,0,${progress * 0.5})`;
    ctx.fillRect(sx, sy, TILE, TILE);

    // Crack lines
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    let cracks = Math.floor(progress * 5);
    for (let i = 0; i < cracks; i++) {
      ctx.beginPath();
      ctx.moveTo(sx + TILE / 2, sy + TILE / 2);
      ctx.lineTo(sx + (i * 7 % TILE), sy + (i * 11 % TILE));
      ctx.stroke();
    }
  }
}

function drawHUD() {
  // Stats
  let statsEl = document.getElementById('stats');
  let nightAlpha = getAmbientLight();
  let hpPct = (player.hp / player.maxHp * 100).toFixed(0);
  let xpPct = (player.xp / player.nextXp * 100).toFixed(0);

  statsEl.innerHTML = `
    <div style="margin-bottom:4px;">❤️ HP: ${hpPct}%</div>
    <div class="bar-container"><div class="bar-fill" style="width:${hpPct}%;background:#e44;"></div><div class="bar-text">${player.hp}/${player.maxHp}</div></div>
    <div style="margin-bottom:4px;margin-top:4px;">⭐ XP: ${xpPct}% (Lv.${player.level})</div>
    <div class="bar-container"><div class="bar-fill" style="width:${xpPct}%;background:#4ae;"></div><div class="bar-text">${player.xp}/${player.nextXp}</div></div>
    <div style="margin-top:4px;font-size:12px;">⚔️ ${player.attack} | 🛡️ ${player.defense}</div>
    <div style="font-size:11px;color:#aaa;">${getBiomeName()}</div>
  `;

  // Hotbar
  let hotbarEl = document.getElementById('hotbar');
  hotbarEl.innerHTML = '';
  for (let i = 0; i < 9; i++) {
    let slot = document.createElement('div');
    slot.className = 'slot' + (i === player.selectedSlot ? ' active' : '');
    let item = player.hotbar[i];
    if (item) {
      let c = document.createElement('canvas');
      c.width = 16; c.height = 16;
      let cctx = c.getContext('2d');
      let colors = BLOCK_COLORS[item.type];
      if (colors) {
        cctx.fillStyle = colors.color || colors.top || '#888';
        cctx.fillRect(2, 2, 12, 12);
        if (colors.spots) {
          cctx.fillStyle = colors.spots;
          cctx.fillRect(4, 4, 3, 3);
          cctx.fillRect(9, 8, 3, 3);
        }
      }
      slot.appendChild(c);
      let count = document.createElement('div');
      count.className = 'count';
      count.textContent = item.count;
      slot.appendChild(count);
    }
    hotbarEl.appendChild(slot);
  }
}

function getBiomeName() {
  let px = Math.floor(player.x / TILE);
  return getBiome(px).charAt(0).toUpperCase() + getBiome(px).slice(1);
}

function showMessage(text, duration) {
  let msgEl = document.getElementById('msg');
  msgEl.textContent = text;
  msgEl.style.opacity = 1;
  setTimeout(() => { msgEl.style.opacity = 0; }, duration || 1500);
}

// Background
function drawBackground() {
  let skyColor = getSkyColor();
  ctx.fillStyle = skyColor;
  ctx.fillRect(0, 0, W, H);

  // Stars at night
  let nightness = 1 - getAmbientLight();
  if (nightness > 0.3) {
    ctx.fillStyle = `rgba(255,255,255,${nightness})`;
    for (let i = 0; i < 50; i++) {
      let sx = (noise(i, 42) * W + time * 0.02 * (i % 3 + 1)) % W;
      let sy = noise(i, 99) * H * 0.5;
      let size = (noise(i, 77) * 2) + 0.5;
      ctx.fillRect(sx, sy, size, size);
    }
  }

  // Sun/Moon
  let t = dayTime / dayLength;
  let celestialAngle = t * Math.PI * 2 - Math.PI / 2;
  let celestialX = W / 2 + Math.cos(celestialAngle) * W * 0.4;
  let celestialY = H * 0.4 + Math.sin(celestialAngle) * H * 0.35;

  if (t < 0.5) {
    // Sun
    ctx.fillStyle = '#ffe44d';
    ctx.beginPath();
    ctx.arc(celestialX, celestialY, 25, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,228,77,0.2)';
    ctx.beginPath();
    ctx.arc(celestialX, celestialY, 40, 0, Math.PI * 2);
    ctx.fill();
  } else {
    // Moon
    ctx.fillStyle = '#ddeeff';
    ctx.beginPath();
    ctx.arc(celestialX, celestialY, 20, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#cdd';
    ctx.beginPath();
    ctx.arc(celestialX - 5, celestialY - 3, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(celestialX + 6, celestialY + 4, 3, 0, Math.PI * 2);
