  ctx.fillStyle = `rgba(255,255,255,${0.3 + nightness * 0.3})`;
  for (let i = 0; i < 8; i++) {
    let cx = (noise(i, 200) * W * 1.5 + time * 0.3 * (i % 2 + 1)) % (W + 200) - 100;
    let cy = 30 + noise(i, 300) * 80;
    let cw = 60 + noise(i, 400) * 80;
