  let parallax1 = camera.x * 0.1;
  ctx.fillStyle = `rgba(${80 + nightness * 40},${100 + nightness * 30},${120 + nightness * 20},0.8)`;
  ctx.beginPath();
  ctx.moveTo(0, H);
  for (let x = 0; x <= W; x += 20) {
    let h = 200 + Math.sin((x + parallax1) * 0.005) * 60 + Math.sin((x + parallax1) * 0.012) * 30;
    ctx.lineTo(x, H - h);
  }
  ctx.lineTo(W, H);
  ctx.fill();

  // Hills (parallax)
  let parallax2 = camera.x * 0.3;
  ctx.fillStyle = `rgba(${60 + nightness * 30},${90 + nightness * 25},${50 + nightness * 20},0.9)`;
