    // Second red stripe
    const stripe3Geo = new THREE.CylinderGeometry(MISSILE_RADIUS * 0.87, MISSILE_RADIUS * 0.87, 0.2, 32);
    const stripe3 = new THREE.Mesh(stripe3Geo, stripeMat1);
    stripe3.position.y = MISSILE_LENGTH * 0.25;
