    const emblemMat = new THREE.MeshStandardMaterial({
        color: 0xffffff, roughness: 0.5, metalness: 0.3, side: THREE.DoubleSide
    });
    for (let i = 0; i < 4; i++) {
        const emblem = new THREE.Mesh(emblemGeo, emblemMat);
