        emblem.position.set(
            Math.cos(angle) * MISSILE_RADIUS * 0.86,
            MISSILE_LENGTH * 0.1,
            Math.sin(angle) * MISSILE_RADIUS * 0.86
        );
        emblem.lookAt(0, MISSILE_LENGTH * 0.1, 0);
        missileGroup.add(emblem);
    }

    // Four large stabilizing fins
    const finMat = new THREE.MeshStandardMaterial({
        color: 0x3a4a2a, roughness: 0.5, metalness: 0.5
