    // Nozzle ring
    const ringGeo = new THREE.TorusGeometry(MISSILE_RADIUS * 0.6, 0.05, 8, 32);
    const ringMat = new THREE.MeshStandardMaterial({
        color: 0x444444, roughness: 0.3, metalness: 0.8
    });
