    missileGroup.add(ring);

    // Engine glow (initially off)
    const glowGeo = new THREE.ConeGeometry(MISSILE_RADIUS * 0.5, 3, 32, 1, true);
    const glowMat = new THREE.MeshBasicMaterial({
        color: 0xff6600, transparent: true, opacity: 0, side: THREE.DoubleSide
