    glow.position.y = -MISSILE_LENGTH * 0.35 - 1.5;
    glow.name = 'engineGlow';
    missileGroup.add(glow);

    // Heat glow on nose (plasma effect)
    const plasmaGeo = new THREE.SphereGeometry(MISSILE_RADIUS * 1.2, 32, 32);
    const plasmaMat = new THREE.MeshBasicMaterial({
        color: 0xff4400, transparent: true, opacity: 0
    });
    const plasma = new THREE.Mesh(plasmaGeo, plasmaMat);
    plasma.position.y = MISSILE_LENGTH * 0.4;
    plasma.name = 'plasma';
    missileGroup.add(plasma);

    // Position missile on launch pad
    missileGroup.position.set(0, LAUNCH_PAD_Y, -5);
    missileGroup.castShadow = true;

    scene.add(missileGroup);
}

// ============ PARTICLE SYSTEMS ============
function createExhaustParticles() {
    const count = 500;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    const lifetimes = new Float32Array(count);

    for (let i = 0; i < count; i++) {
        positions[i * 3] = 0;
        positions[i * 3 + 1] = -100;
        positions[i * 3 + 2] = 0;
        colors[i * 3] = 1;
        colors[i * 3 + 1] = 0.5;
        colors[i * 3 + 2] = 0;
        sizes[i] = 0;
        lifetimes[i] = 0;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

    const material = new THREE.ShaderMaterial({
        uniforms: {
            uTime: { value: 0 }
        },
        vertexShader: `
            attribute float size;
            attribute vec3 color;
            varying vec3 vColor;
            varying float vAlpha;
            void main() {
                vColor = color;
                vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
                gl_PointSize = size * (200.0 / -mvPosition.z);
                gl_Position = projectionMatrix * mvPosition;
                vAlpha = smoothstep(0.0, 1.0, size / 3.0);
            }
        `,
        fragmentShader: `
            varying vec3 vColor;
            varying float vAlpha;
            void main() {
                float d = length(gl_PointCoord - vec2(0.5));
                if (d > 0.5) discard;
                float alpha = smoothstep(0.5, 0.0, d) * vAlpha;
                gl_FragColor = vec4(vColor, alpha);
            }
        `,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending
    });

    const points = new THREE.Points(geometry, material);
    points.name = 'exhaustParticles';
    scene.add(points);

    // Initialize particle data
    for (let i = 0; i < count; i++) {
        exhaustParticles.push({
            active: false,
            life: 0,
            maxLife: 0,
            position: new THREE.Vector3(),
            velocity: new THREE.Vector3(),
            size: 0,
            color: new THREE.Vector3()
        });
    }
}

