function spawnExhaustParticle(pos, vel, size, color) {
    for (let i = 0; i < exhaustParticles.length; i++) {
        if (!exhaustParticles[i].active) {
            const p = exhaustParticles[i];
            p.active = true;
            p.life = 0;
            p.maxLife = 0.5 + Math.random() * 0.5;
            p.position.copy(pos);
            p.velocity.copy(vel);
            p.size = size;
            p.color.copy(color);
            return;
        }
    }
}

