function updateParticles(dt) {
    // Exhaust
    const exhaustGeo = scene.getObjectByName('exhaustParticles');
    if (exhaustGeo) {
        const posArr = exhaustGeo.geometry.attributes.position.array;
        const colArr = exhaustGeo.geometry.attributes.color.array;
        const sizeArr = exhaustGeo.geometry.attributes.size.array;

        for (let i = 0; i < exhaustParticles.length; i++) {
            const p = exhaustParticles[i];
            if (p.active) {
                p.life += dt;
                if (p.life >= p.maxLife) {
                    p.active = false;
                    posArr[i * 3 + 1] = -100;
                    sizeArr[i] = 0;
                } else {
                    p.position.add(p.velocity.clone().multiplyScalar(dt));
                    p.velocity.y -= 2 * dt; // slight upward drift
                    p.size = Math.max(0, p.size - dt * 2);

                    posArr[i * 3] = p.position.x;
                    posArr[i * 3 + 1] = p.position.y;
                    posArr[i * 3 + 2] = p.position.z;

                    const t = p.life / p.maxLife;
                    colArr[i * 3] = 1.0;
                    colArr[i * 3 + 1] = 0.8 - t * 0.6;
                    colArr[i * 3 + 2] = 0.1 - t * 0.1;

                    sizeArr[i] = p.size;
                }
            }
        }
        exhaustGeo.geometry.attributes.position.needsUpdate = true;
        exhaustGeo.geometry.attributes.color.needsUpdate = true;
        exhaustGeo.geometry.attributes.size.needsUpdate = true;
    }

    // Smoke
    const smokeGeo = scene.getObjectByName('smokeParticles');
    if (smokeGeo) {
        const posArr = smokeGeo.geometry.attributes.position.array;
        const colArr = smokeGeo.geometry.attributes.color.array;
        const sizeArr = smokeGeo.geometry.attributes.size.array;

        for (let i = 0; i < smokeParticles.length; i++) {
            const p = smokeParticles[i];
            if (p.active) {
                p.life += dt;
                if (p.life >= p.maxLife) {
                    p.active = false;
                    posArr[i * 3 + 1] = -100;
                    sizeArr[i] = 0;
                } else {
                    p.position.add(p.velocity.clone().multiplyScalar(dt));
                    p.velocity.x += (Math.random() - 0.5) * 0.5 * dt;
                    p.velocity.z += (Math.random() - 0.5) * 0.5 * dt;
                    p.velocity.y *= 0.99;
                    p.size = Math.min(p.size + dt * 3, 8);

                    const t = p.life / p.maxLife;
                    const gray = 0.6 - t * 0.3;

                    posArr[i * 3] = p.position.x;
                    posArr[i * 3 + 1] = p.position.y;
                    posArr[i * 3 + 2] = p.position.z;

                    colArr[i * 3] = gray;
                    colArr[i * 3 + 1] = gray;
                    colArr[i * 3 + 2] = gray + 0.05;

                    sizeArr[i] = p.size * (1 - t * 0.5);
                }
            }
        }
        smokeGeo.geometry.attributes.position.needsUpdate = true;
        smokeGeo.geometry.attributes.color.needsUpdate = true;
        smokeGeo.geometry.attributes.size.needsUpdate = true;
    }

    // Dust
    const dustGeo = scene.getObjectByName('dustParticles');
    if (dustGeo) {
        const posArr = dustGeo.geometry.attributes.position.array;
        const colArr = dustGeo.geometry.attributes.color.array;
        const sizeArr = dustGeo.geometry.attributes.size.array;

        for (let i = 0; i < dustParticles.length; i++) {
            const p = dustParticles[i];
            if (p.active) {
                p.life += dt;
                if (p.life >= p.maxLife) {
                    p.active = false;
                    posArr[i * 3 + 1] = -100;
                    sizeArr[i] = 0;
                } else {
                    p.position.add(p.velocity.clone().multiplyScalar(dt));
                    p.velocity.y -= 3 * dt;
                    p.velocity.multiplyScalar(0.98);
                    p.size = Math.max(0, p.size - dt);

                    const t = p.life / p.maxLife;

                    posArr[i * 3] = p.position.x;
                    posArr[i * 3 + 1] = p.position.y;
                    posArr[i * 3 + 2] = p.position.z;

                    colArr[i * 3] = 0.6 - t * 0.2;
                    colArr[i * 3 + 1] = 0.55 - t * 0.15;
                    colArr[i * 3 + 2] = 0.4 - t * 0.1;

                    sizeArr[i] = p.size;
                }
            }
        }
        dustGeo.geometry.attributes.position.needsUpdate = true;
        dustGeo.geometry.attributes.color.needsUpdate = true;
        dustGeo.geometry.attributes.size.needsUpdate = true;
    }
}

// ============ SKY & ATMOSPHERE ============
function createSky() {
    // Dawn sky gradient
    const skyGeo = new THREE.SphereGeometry(400, 32, 32);
    const skyMat = new THREE.ShaderMaterial({
        uniforms: {
            uSunPos: { value: new THREE.Vector3(200, 50, -100) }
        },
        vertexShader: `
            varying vec3 vWorldPosition;
            void main() {
                vec4 worldPos = modelMatrix * vec4(position, 1.0);
                vWorldPosition = worldPos.xyz;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 uSunPos;
            varying vec3 vWorldPosition;

            void main() {
                vec3 dir = normalize(vWorldPosition);
                float y = dir.y * 0.5 + 0.5;

                // Dawn colors
                vec3 bottomColor = vec3(0.85, 0.45, 0.2);
                vec3 midColor = vec3(0.6, 0.35, 0.25);
                vec3 topColor = vec3(0.15, 0.1, 0.25);

                vec3 sky = mix(bottomColor, midColor, smoothstep(0.0, 0.3, y));
                sky = mix(sky, topColor, smoothstep(0.3, 0.8, y));

                // Sun glow
                vec3 sunDir = normalize(uSunPos);
                float sunDot = max(dot(dir, sunDir), 0.0);
                vec3 sunColor = vec3(1.0, 0.7, 0.3);
                sky += sunColor * pow(sunDot, 64.0) * 2.0;
                sky += sunColor * pow(sunDot, 8.0) * 0.3;
                sky += vec3(1.0, 0.5, 0.2) * pow(sunDot, 3.0) * 0.15;

                // Horizon haze
                float horizonHaze = exp(-abs(dir.y) * 3.0);
                sky = mix(sky, vec3(0.9, 0.7, 0.5), horizonHaze * 0.3);

                gl_FragColor = vec4(sky, 1.0);
            }
        `,
        side: THREE.BackSide
    });

    const sky = new THREE.Mesh(skyGeo, skyMat);
    scene.add(sky);
}

