// ============ CAMERA SYSTEM ============
function updateCamera(dt) {
    if (!launchStarted && cameraMode === 0) {
        // Bunker interior view - door opening
        const t = Math.min(1, simTime / 5);
        const eased = t * t * (3 - 2 * t);

        const startX = 0, startY = LAUNCH_PAD_Y + 3, startZ = 8;
        const endX = 0, endY = LAUNCH_PAD_Y + 8, endZ = 25;

        cameraPositions[0] = {
            x: startX + (endX - startX) * eased,
            y: startY + (endY - startY) * eased,
            z: startZ + (endZ - startZ) * eased
        };

        cameraPositions[1] = {
            x: 0, y: LAUNCH_PAD_Y + 5, z: -5
        };

        document.getElementById('cameraLabel').textContent = 'CAMERA: BUNKER INTERIOR - DOOR OPENING';
        return;
    }

    if (!launchStarted) return;

    const elapsed = simTime - launchTime;

    // Camera mode transitions
    if (elapsed < 1) {
        // Low angle close-up as missile emerges
        cameraMode = 1;
        document.getElementById('cameraLabel').textContent = 'CAMERA: LOW ANGLE CLOSE-UP';
    } else if (elapsed < 4) {
        // Chase camera from behind
        cameraMode = 2;
        document.getElementById('cameraLabel').textContent = 'CAMERA: CHASE VIEW';
    } else if (elapsed < 7) {
        // FPV / missile eye view
        cameraMode = 3;
        document.getElementById('cameraLabel').textContent = 'CAMERA: MISSILE FPV';
    } else if (elapsed < 10) {
        // Side profile tracking
        cameraMode = 4;
        document.getElementById('cameraLabel').textContent = 'CAMERA: SIDE PROFILE TRACKING';
    } else if (elapsed < 13) {
        // Top-down world view
        cameraMode = 5;
        document.getElementById('cameraLabel').textContent = 'CAMERA: TOP-DOWN WORLD VIEW';
    } else if (elapsed < 16) {
        // Orbiting camera
        cameraMode = 6;
        document.getElementById('cameraLabel').textContent = 'CAMERA: ORBITING VIEW';
    } else {
        // Wide shot from distance
        cameraMode = 7;
        document.getElementById('cameraLabel').textContent = 'CAMERA: DISTANCE WIDE SHOT';
    }

    const missileWorldPos = new THREE.Vector3();
    missile.getWorldPosition(missileWorldPos);

    switch (cameraMode) {
        case 1: // Low angle close-up
            {
                const t = Math.min(1, elapsed / 1);
                const eased = t * t * (3 - 2 * t);
                targetCamPos.set(
                    8 - eased * 3,
                    LAUNCH_PAD_Y + 2 + eased * 5,
                    12 - eased * 5
                );
                targetCamLook.set(0, LAUNCH_PAD_Y + 3, -5);
            }
            break;

        case 2: // Chase camera
            {
                const chaseOffset = new THREE.Vector3(3, -8, 15);
                chaseOffset.y += elapsed * 2;
                chaseOffset.z += elapsed * 3;
                targetCamPos.copy(missileWorldPos).add(chaseOffset);
                targetCamLook.copy(missileWorldPos).add(new THREE.Vector3(0, 20, 0));
            }
            break;

        case 3: // FPV
            {
                const fpvOffset = new THREE.Vector3(0, MISSILE_LENGTH * 0.5, 0.5);
                targetCamPos.copy(missileWorldPos).add(fpvOffset);
                targetCamLook.copy(missileWorldPos).add(new THREE.Vector3(0, 50 + elapsed * 10, 0));
            }
            break;

        case 4: // Side profile
            {
                const sideOffset = new THREE.Vector3(20, 5, 0);
                targetCamPos.copy(missileWorldPos).add(sideOffset);
                targetCamLook.copy(missileWorldPos);
            }
            break;

        case 5: // Top-down
            {
                const topOffset = new THREE.Vector3(0, 150, 30);
                targetCamPos.copy(missileWorldPos).add(topOffset);
                targetCamLook.copy(missileWorldPos);
            }
            break;

        case 6: // Orbiting
            {
                const orbitAngle = elapsed * 0.5;
                const orbitRadius = 25;
                targetCamPos.set(
                    missileWorldPos.x + Math.cos(orbitAngle) * orbitRadius,
                    missileWorldPos.y + 10,
                    missileWorldPos.z + Math.sin(orbitAngle) * orbitRadius
                );
                targetCamLook.copy(missileWorldPos);
            }
            break;

        case 7: // Wide shot
            {
                const wideOffset = new THREE.Vector3(80, 60, 80);
                targetCamPos.copy(missileWorldPos).add(wideOffset);
                targetCamLook.copy(missileWorldPos);
            }
            break;
    }
}

function smoothCameraTransition(dt) {
    const smoothSpeed = 3;
    currentCamPos.x += (targetCamPos.x - currentCamPos.x) * smoothSpeed * dt;
    currentCamPos.y += (targetCamPos.y - currentCamPos.y) * smoothSpeed * dt;
    currentCamPos.z += (targetCamPos.z - currentCamPos.z) * smoothSpeed * dt;

    currentCamLook.x += (targetCamLook.x - currentCamLook.x) * smoothSpeed * dt;
    currentCamLook.y += (targetCamLook.y - currentCamLook.y) * smoothSpeed * dt;
    currentCamLook.z += (targetCamLook.z - currentCamLook.z) * smoothSpeed * dt;

    // Apply shake
    if (shakeAmount > 0) {
        camera.position.x = currentCamPos.x + (Math.random() - 0.5) * shakeAmount;
        camera.position.y = currentCamPos.y + (Math.random() - 0.5) * shakeAmount;
        camera.position.z = currentCamPos.z + (Math.random() - 0.5) * shakeAmount;
    } else {
        camera.position.copy(currentCamPos);
    }

    camera.lookAt(currentCamLook.x, currentCamLook.y, currentCamLook.z);
}

// ============ MISSILE PHYSICS ============
function updateMissilePhysics(dt) {
    if (!launchStarted) return;

    const elapsed = simTime - launchTime;

    // Acceleration profile - hypersonic acceleration
    // Initial slow acceleration, then rapid increase
    let acceleration;
    if (elapsed < 0.5) {
        acceleration = 50; // Initial ignition
    } else if (elapsed < 2) {
        acceleration = 200 + (elapsed - 0.5) * 500;
    } else if (elapsed < 5) {
        acceleration = 1000 + (elapsed - 2) * 800;
    } else if (elapsed < 10) {
        acceleration = 3000 + (elapsed - 5) * 400;
    } else {
        acceleration = 5000 - (elapsed - 10) * 100; // Gradual decrease
    }

    acceleration = Math.max(50, acceleration);

    missileVelocity += acceleration * dt;
    missileAltitude += missileVelocity * dt;

    // Update missile position
    missileGroup.position.y = LAUNCH_PAD_Y + missileAltitude;

    // Slight trajectory adjustments (realistic)
    const lateralDrift = Math.sin(elapsed * 0.3) * 0.5;
    missileGroup.position.x = lateralDrift;

    // Fins vibrate
    missileGroup.children.forEach(child => {
        if (child.name && child.name.startsWith('fin_')) {
            child.rotation.z = Math.sin(elapsed * 50) * 0.02;
        }
    });

    // Missile slight tilt based on lateral movement
    missileGroup.rotation.z = Math.cos(elapsed * 0.3) * 0.03;

    // Update engine glow
    const glow = missileGroup.getObjectByName('engineGlow');
    if (glow) {
        const glowIntensity = Math.min(1, elapsed / 1);
        glow.material.opacity = glowIntensity * (0.7 + Math.sin(elapsed * 30) * 0.3);
        glow.scale.set(
            1 + Math.sin(elapsed * 20) * 0.1,
            1 + elapsed * 0.3,
            1 + Math.sin(elapsed * 20) * 0.1
        );
    }

    // Plasma effect on nose cone at high speeds
    const plasma = missileGroup.getObjectByName('plasma');
    if (plasma) {
        const mach = missileVelocity / 340;
        if (mach > 2) {
            const plasmaIntensity = Math.min(1, (mach - 2) / 10);
            plasma.material.opacity = plasmaIntensity * 0.5;
            plasma.scale.setScalar(1 + plasmaIntensity * 0.5);

            // Color shifts from orange to white-hot at extreme speeds
            if (mach > 8) {
                plasma.material.color.setHex(0xffaa44);
            } else {
                plasma.material.color.setHex(0xff4400);
            }
        }
    }

    // Engine light intensity
    const engineLight = scene.getObjectByName('engineLight');
    if (engineLight) {
        const lightIntensity = Math.min(10, elapsed * 5);
        engineLight.intensity = lightIntensity;
        engineLight.position.copy(missileGroup.position);
        engineLight.position.y -= 2;
    }

    // Spawn exhaust particles
    if (elapsed > 0.3 && elapsed < 30) {
        const spawnRate = Math.min(20, 5 + elapsed * 2);
        for (let i = 0; i < spawnRate; i++) {
            const nozzlePos = new THREE.Vector3(
                missileGroup.position.x + (Math.random() - 0.5) * 0.3,
                missileGroup.position.y - MISSILE_LENGTH * 0.39 - 0.5,
                missileGroup.position.z + (Math.random() - 0.5) * 0.3
            );

            const vel = new THREE.Vector3(
                (Math.random() - 0.5) * 5,
                -15 - Math.random() * 10,
                (Math.random() - 0.5) * 5
            );

            const size = 1 + Math.random() * 2;
            const color = new THREE.Vector3(
                1,
                0.5 + Math.random() * 0.5,
                Math.random() * 0.2
            );

            spawnExhaustParticle(nozzlePos, vel, size, color);
        }

        // Smoke particles
        const smokeRate = Math.min(10, 3 + elapsed);
        for (let i = 0; i < smokeRate; i++) {
            const smokePos = new THREE.Vector3(
                missileGroup.position.x + (Math.random() - 0.5) * 2,
                missileGroup.position.y - MISSILE_LENGTH * 0.39 - 3 - Math.random() * 5,
                missileGroup.position.z + (Math.random() - 0.5) * 2
            );

            const smokeVel = new THREE.Vector3(
                (Math.random() - 0.5) * 3,
                -2 - Math.random() * 3,
                (Math.random() - 0.5) * 3
            );

            spawnSmokeParticle(smokePos, smokeVel, 2 + Math.random() * 3);
        }
    }

    // Dust particles at launch
    if (elapsed > 0.3 && elapsed < 3) {
        const dustRate = Math.max(0, 15 - elapsed * 5);
        for (let i = 0; i < dustRate; i++) {
            const dustPos = new THREE.Vector3(
                missileGroup.position.x + (Math.random() - 0.5) * 10,
                LAUNCH_PAD_Y + Math.random() * 2,
                missileGroup.position.z + (Math.random() - 0.5) * 10
            );

            const dustVel = new THREE.Vector3(
                (Math.random() - 0.5) * 15,
                Math.random() * 8,
                (Math.random() - 0.5) * 15
            );

            spawnDustParticle(dustPos, dustVel, 2 + Math.random() * 4);
        }
    }

    // Shake intensity based on velocity
    shakeAmount = Math.min(0.5, elapsed * 0.1) * (missileVelocity / 5000);

    // Update HUD
    const mach = missileVelocity / 340.3;
    document.getElementById('hudAlt').textContent = `ALTITUDE: ${Math.floor(missileAltitude)} m`;
    document.getElementById('hudSpeed').textContent = `SPEED: ${Math.floor(missileVelocity)} m/s`;
    document.getElementById('hudMach').textContent = `MACH: ${mach.toFixed(2)}`;
    document.getElementById('hudTime').textContent = `T+${elapsed.toFixed(1)}s`;

    // Progress bar
    const progress = Math.min(100, (elapsed / 30) * 100);
    document.getElementById('progressBar').style.width = progress + '%';
}

// ============ ENVIRONMENT DETAILS ============
function createRockDetails() {
    const rockMat = new THREE.MeshStandardMaterial({
        color: 0x555544, roughness: 0.9, metalness: 0.1
    });

    for (let i = 0; i < 50; i++) {
        const x = (Math.random() - 0.5) * 300;
        const z = (Math.random() - 0.5) * 300;
        const h = getTerrainHeight(x, z);

        // Skip near bunker
        if (Math.sqrt(x * x + (z + 30) * (z + 30)) < 20) continue;

        const size = 0.5 + Math.random() * 3;
        const rockGeo = new THREE.DodecahedronGeometry(size, 1);

        // Deform vertices for natural look
        const verts = rockGeo.attributes.position.array;
        for (let j = 0; j < verts.length; j += 3) {
            verts[j] += (Math.random() - 0.5) * size * 0.3;
            verts[j + 1] += (Math.random() - 0.5) * size * 0.3;
            verts[j + 2] += (Math.random() - 0.5) * size * 0.3;
        }
        rockGeo.computeVertexNormals();

        const rock = new THREE.Mesh(rockGeo, rockMat);
        rock.position.set(x, h + size * 0.3, z);
        rock.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
        rock.castShadow = true;
        rock.receiveShadow = true;
        scene.add(rock);
    }
}

function createLaunchFlame() {
    // Large flame cone at launch
    const flameGeo = new THREE.ConeGeometry(3, 15, 32, 1, true);
    const flameMat = new THREE.MeshBasicMaterial({
        color: 0xff4400,
