    flame.position.set(0, LAUNCH_PAD_Y - 8, -5);
    flame.name = 'launchFlame';
    scene.add(flame);

    // Inner flame
    const innerFlameGeo = new THREE.ConeGeometry(1.5, 10, 32, 1, true);
    const innerFlameMat = new THREE.MeshBasicMaterial({
        color: 0xffff00,
        transparent: true,
        opacity: 0,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending
    });
    const innerFlame = new THREE.Mesh(innerFlameGeo, innerFlameMat);
    innerFlame.position.set(0, LAUNCH_PAD_Y - 5, -5);
    innerFlame.name = 'innerFlame';
    scene.add(innerFlame);

    return { flame, innerFlame };
}

let launchFlame;

// ============ INITIALIZATION ============
function init() {
    scene = new THREE.Scene();
