    clock = new THREE.Clock();

    // Initialize camera positions
    for (let i = 0; i < 10; i++) {
        cameraPositions.push({ x: 0, y: 0, z: 0 });
    }

    currentCamPos.set(0, LAUNCH_PAD_Y + 3, 8);
    targetCamPos.set(0, LAUNCH_PAD_Y + 3, 8);
