        renderer.setSize(window.innerWidth, window.innerHeight);
    });
}

// ============ ANIMATION LOOP ============
function animate() {
    requestAnimationFrame(animate);

    const dt = Math.min(clock.getDelta(), 0.05);
    simTime += dt;

    // Door opening animation
    if (bunker) {
        const door = bunker.getObjectByName('door');
        if (door) {
            if (!launchStarted) {
                doorOpen += doorOpenSpeed;
                doorOpen = Math.min(1, doorOpen);
                door.rotation.y = -doorOpen * Math.PI / 2;
                door.position.z = 5 + doorOpen * 5;
            } else {
                door.rotation.y = -Math.PI / 2;
                door.position.z = 10;
            }
        }
    }

    // Launch sequence
    if (!launchStarted && simTime > 5) {
        launchStarted = true;
        launchTime = simTime;

        if (soundCtx) {
            // Trigger boom sound
            boomSound.gain.gain.setTargetAtTime(1, soundCtx.currentTime, 0.01);

            // Show launch flame
            const flame = scene.getObjectByName('launchFlame');
            const innerFlame = scene.getObjectByName('innerFlame');
            if (flame) flame.material.opacity = 0.8;
            if (innerFlame) innerFlame.material.opacity = 1;
        }
    }

    // Update launch flame
    if (launchFlame) {
        const elapsed = simTime - launchTime;
        if (elapsed > 0 && elapsed < 3) {
            const flame = scene.getObjectByName('launchFlame');
            const innerFlame = scene.getObjectByName('innerFlame');
            const intensity = Math.max(0, 1 - elapsed / 3);
            if (flame) flame.material.opacity = intensity * 0.8;
            if (innerFlame) innerFlame.material.opacity = intensity;

            flame.scale.y = 1 + Math.sin(elapsed * 30) * 0.2;
            innerFlame.scale.y = 1 + Math.sin(elapsed * 40) * 0.15;
        } else {
            const flame = scene.getObjectByName('launchFlame');
            const innerFlame = scene.getObjectByName('innerFlame');
            if (flame) flame.material.opacity = 0;
            if (innerFlame) innerFlame.material.opacity = 0;
        }
    }

    // Update missile physics
    updateMissilePhysics(dt);

    // Update particles
    updateParticles(dt);

    // Update camera
    updateCamera(dt);
    smoothCameraTransition(dt);

    // Update audio
    updateAudio(simTime);

    // Animate god rays
    scene.children.forEach(child => {
        if (child.name && child.name.startsWith('godRay')) {
            child.material.opacity = 0.02 + Math.sin(simTime * 0.5) * 0.01;
            child.rotation.z += dt * 0.02;
