    }
    // Knight attacks
    for (const [dr, dc] of [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]]) {
        const nr = row + dr, nc = col + dc;
        if (inBounds(nr, nc) && brd[nr][nc] === byColor + 'N') return true;
    }
    // King attacks
    for (let dr = -1; dr <= 1; dr++)
        for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = row + dr, nc = col + dc;
            if (inBounds(nr, nc) && brd[nr][nc] === byColor + 'K') return true;
        }
    // Sliding pieces (Rook/Queen for straight, Bishop/Queen for diagonal)
    const straightDirs = [[0,1],[0,-1],[1,0],[-1,0]];
    const diagDirs = [[1,1],[1,-1],[-1,1],[-1,-1]];
    for (const [dr, dc] of straightDirs) {
        for (let i = 1; i < 8; i++) {
            const nr = row + dr*i, nc = col + dc*i;
            if (!inBounds(nr, nc)) break;
            if (brd[nr][nc]) {
                if (brd[nr][nc] === byColor + 'R' || brd[nr][nc] === byColor + 'Q') return true;
                break;
            }
        }
    }
    for (const [dr, dc] of diagDirs) {
        for (let i = 1; i < 8; i++) {
            const nr = row + dr*i, nc = col + dc*i;
            if (!inBounds(nr, nc)) break;
            if (brd[nr][nc]) {
                if (brd[nr][nc] === byColor + 'B' || brd[nr][nc] === byColor + 'Q') return true;
                break;
            }
        }
    }
    return false;
}

function isInCheck(color, brd) {
    const king = findKing(color, brd);
    if (!king) return false;
    const enemy = color === WHITE ? BLACK : WHITE;
    return isAttackedBy(king[0], king[1], enemy, brd);
}

function getRawMoves(row, col, brd, cRights, epTarget) {
    const piece = brd[row][col];
    if (!piece) return [];
    const color = piece[0];
    const type = piece[1];
    const moves = [];
    const enemy = color === WHITE ? BLACK : WHITE;

    function addMove(r, c) {
        if (inBounds(r, c)) {
            const target = brd[r][c];
            if (!target || target[0] !== color) moves.push([r, c]);
        }
    }

    if (type === 'P') {
        const dir = color === WHITE ? -1 : 1;
        const startRow = color === WHITE ? 6 : 1;
        // Forward
        if (inBounds(row+dir, col) && !brd[row+dir][col]) {
            moves.push([row+dir, col]);
            if (row === startRow && !brd[row+2*dir][col])
                moves.push([row+2*dir, col]);
        }
        // Captures
        for (const dc of [-1, 1]) {
            const nr = row+dir, nc = col+dc;
            if (inBounds(nr, nc)) {
                if (brd[nr][nc] && brd[nr][nc][0] === enemy)
                    moves.push([nr, nc]);
                if (epTarget && epTarget[0] === nr && epTarget[1] === nc)
                    moves.push([nr, nc]);
            }
        }
    }
    else if (type === 'N') {
        for (const [dr, dc] of [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]])
            addMove(row+dr, col+dc);
    }
    else if (type === 'K') {
        for (let dr = -1; dr <= 1; dr++)
            for (let dc = -1; dc <= 1; dc++) {
                if (dr === 0 && dc === 0) continue;
                addMove(row+dr, col+dc);
            }
        // Castling
        if (cRights) {
            const homeRow = color === WHITE ? 7 : 0;
            if (row === homeRow && col === 4) {
                // Kingside
                if (cRights[color+'K'] && !brd[homeRow][5] && !brd[homeRow][6] &&
                    brd[homeRow][7] === color+'R') {
                    if (!isAttackedBy(homeRow, 4, enemy, brd) &&
                        !isAttackedBy(homeRow, 5, enemy, brd) &&
                        !isAttackedBy(homeRow, 6, enemy, brd))
                        moves.push([homeRow, 6]);
                }
                // Queenside
                if (cRights[color+'Q'] && !brd[homeRow][3] && !brd[homeRow][2] && !brd[homeRow][1] &&
                    brd[homeRow][0] === color+'R') {
                    if (!isAttackedBy(homeRow, 4, enemy, brd) &&
                        !isAttackedBy(homeRow, 3, enemy, brd) &&
                        !isAttackedBy(homeRow, 2, enemy, brd))
                        moves.push([homeRow, 2]);
                }
            }
        }
    }
    else {
        const dirs = [];
        if (type === 'R' || type === 'Q')
            dirs.push([0,1],[0,-1],[1,0],[-1,0]);
        if (type === 'B' || type === 'Q')
            dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);
        for (const [dr, dc] of dirs) {
            for (let i = 1; i < 8; i++) {
                const nr = row+dr*i, nc = col+dc*i;
                if (!inBounds(nr, nc)) break;
                if (brd[nr][nc]) {
                    if (brd[nr][nc][0] === enemy) moves.push([nr, nc]);
                    break;
                }
                moves.push([nr, nc]);
            }
        }
    }
    return moves;
}

function getLegalMoves(row, col) {
    const piece = board[row][col];
    if (!piece) return [];
    const color = piece[0];
    const raw = getRawMoves(row, col, board, castlingRights, enPassantTarget);
    const legal = [];
    for (const [tr, tc] of raw) {
        const testBoard = board.map(r => [...r]);
        // Simulate move
        testBoard[tr][tc] = testBoard[row][col];
        testBoard[row][col] = null;
        // En passant capture
        if (piece[1] === 'P' && enPassantTarget && tr === enPassantTarget[0] && tc === enPassantTarget[1]) {
            const capturedRow = color === WHITE ? tr + 1 : tr - 1;
            testBoard[capturedRow][tc] = null;
        }
        if (!isInCheck(color, testBoard)) legal.push([tr, tc]);
    }
    return legal;
}

function hasAnyLegalMoves(color) {
    for (let r = 0; r < 8; r++)
        for (let c = 0; c < 8; c++)
            if (board[r][c] && board[r][c][0] === color && getLegalMoves(r, c).length > 0)
                return true;
    return false;
}

// ============ THREE.JS SCENE ============
let scene, camera, renderer, raycaster, mouse;
let boardGroup, piecesGroup, highlightsGroup, previewGroup;
let pieceMeshes = {};
let selectedMesh = null;
let highlightMeshes = [];
let cameraAngle = 0;
let cameraTargetAngle = 0;
let boardFlipped = false;
let movePreview = null;
let promotionCallback = null;

const SQUARE_SIZE = 1;
const BOARD_OFFSET = 3.5;

function initThree() {
    scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x1a1a2e, 0.015);

    camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 10, 8);
    camera.lookAt(0, 0, 0);

    renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.insertBefore(renderer.domElement, document.body.firstChild);

    // Lights
    const ambientLight = new THREE.AmbientLight(0x404060, 0.6);
    scene.add(ambientLight);

    const mainLight = new THREE.DirectionalLight(0xffeedd, 1.2);
    mainLight.position.set(5, 15, 5);
    mainLight.castShadow = true;
    mainLight.shadow.mapSize.set(2048, 2048);
    mainLight.shadow.camera.near = 0.5;
    mainLight.shadow.camera.far = 50;
    mainLight.shadow.camera.left = -10;
    mainLight.shadow.camera.right = 10;
    mainLight.shadow.camera.top = 10;
    mainLight.shadow.camera.bottom = -10;
    scene.add(mainLight);

    const fillLight = new THREE.DirectionalLight(0x6688cc, 0.4);
    fillLight.position.set(-5, 8, -5);
    scene.add(fillLight);

    const rimLight = new THREE.PointLight(0xff6644, 0.5, 30);
    rimLight.position.set(-8, 5, 8);
    scene.add(rimLight);

    // Board
    boardGroup = new THREE.Group();
    piecesGroup = new THREE.Group();
    highlightsGroup = new THREE.Group();
    previewGroup = new THREE.Group();
    scene.add(boardGroup);
    scene.add(piecesGroup);
    scene.add(highlightsGroup);
    scene.add(previewGroup);

    createBoard();
    createPieces();
    updatePiecePositions();

    raycaster = new THREE.Raycaster();
    mouse = new THREE.Vector2();

    renderer.domElement.addEventListener('click', onMouseClick);
    renderer.domElement.addEventListener('mousemove', onMouseMove);
    window.addEventListener('resize', onResize);
}

function createBoard() {
    // Board base
    const baseGeo = new THREE.BoxGeometry(9, 0.3, 9);
    const baseMat = new THREE.MeshStandardMaterial({
        color: 0x2a1a0a, roughness: 0.6, metalness: 0.1
    });
    const base = new THREE.Mesh(baseGeo, baseMat);
    base.position.y = -0.15;
    base.receiveShadow = true;
    boardGroup.add(base);

    // Border
    const borderGeo = new THREE.BoxGeometry(9.4, 0.5, 9.4);
    const borderMat = new THREE.MeshStandardMaterial({
        color: 0x3d2817, roughness: 0.4, metalness: 0.2
    });
    const border = new THREE.Mesh(borderGeo, borderMat);
    border.position.y = -0.25;
    border.receiveShadow = true;
    boardGroup.add(border);

    // Squares
    for (let r = 0; r < 8; r++) {
        for (let c = 0; c < 8; c++) {
            const isLight = (r + c) % 2 === 0;
            const geo = new THREE.BoxGeometry(SQUARE_SIZE, 0.15, SQUARE_SIZE);
            const mat = new THREE.MeshStandardMaterial({
                color: isLight ? 0xf0d9b5 : 0xb58863,
                roughness: 0.7, metalness: 0.05
            });
            const square = new THREE.Mesh(geo, mat);
            square.position.set(
                (c - BOARD_OFFSET) * SQUARE_SIZE,
                0.075,
                (r - BOARD_OFFSET) * SQUARE_SIZE
            );
            square.receiveShadow = true;
            square.userData = { row: r, col: c, isSquare: true };
            boardGroup.add(square);
        }
    }

    // Coordinate labels
    const files = ['a','b','c','d','e','f','g','h'];
    const labelsGroup = new THREE.Group();
    for (let i = 0; i < 8; i++) {
        // File labels (bottom)
        addLabel(boardGroup, files[i], (i - 3.5) * SQUARE_SIZE, -0.6, 4.2, 0.3);
        addLabel(boardGroup, files[i], (i - 3.5) * SQUARE_SIZE, -0.6, -4.2, 0.3);
        // Rank labels (left)
        addLabel(boardGroup, String(8 - i), -4.2, -0.6, (i - 3.5) * SQUARE_SIZE, 0.3);
        addLabel(boardGroup, String(8 - i), 4.2, -0.6, (i - 3.5) * SQUARE_SIZE, 0.3);
    }
}

function addLabel(parent, text, x, y, z, size) {
    const canvas = document.createElement('canvas');
    canvas.width = 64; canvas.height = 64;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#8B7355';
    ctx.font = 'bold 48px serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 32, 32);
    const texture = new THREE.CanvasTexture(canvas);
    const mat = new THREE.SpriteMaterial({ map: texture, transparent: true });
    const sprite = new THREE.Sprite(mat);
    sprite.position.set(x, y, z);
    sprite.scale.set(size, size, 1);
    parent.add(sprite);
}

function createPieceMesh(type, color) {
    const group = new THREE.Group();
    const isWhite = color === WHITE;
    const mainColor = isWhite ? 0xf5f5f0 : 0x2a2a2a;
    const accentColor = isWhite ? 0xe8e0d0 : 0x3a3a3a;
    const mat = new THREE.MeshStandardMaterial({
        color: mainColor, roughness: 0.3, metalness: 0.4
    });
    const accentMat = new THREE.MeshStandardMaterial({
        color: accentColor, roughness: 0.2, metalness: 0.5
    });

    const scale = 0.45;

    switch(type) {
        case 'P': {
            // Pawn
            const base = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.4, 0.15, 16), mat);
            base.position.y = 0.075;
            const body = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.32, 0.5, 16), mat);
            body.position.y = 0.4;
            const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.25, 16, 16), mat);
            shoulder.position.y = 0.7;
            const head = new THREE.Mesh(new THREE.SphereGeometry(0.18, 16, 16), mat);
            head.position.y = 0.92;
            group.add(base, body, shoulder, head);
            break;
        }
        case 'R': {
            // Rook
            const base = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.42, 0.15, 16), mat);
            base.position.y = 0.075;
            const body = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.35, 0.6, 16), mat);
            body.position.y = 0.45;
            const top = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.3, 0.2, 16), mat);
            top.position.y = 0.85;
            // Crenellations
            for (let i = 0; i < 4; i++) {
                const angle = (i / 4) * Math.PI * 2;
                const cren = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.18, 0.12), mat);
                cren.position.set(Math.cos(angle) * 0.22, 1.04, Math.sin(angle) * 0.22);
                group.add(cren);
            }
            group.add(base, body, top);
            break;
        }
        case 'N': {
            // Knight - horse head shape
            const base = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.42, 0.15, 16), mat);
            base.position.y = 0.075;
            const body = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.35, 0.4, 16), mat);
            body.position.y = 0.35;
            // Main head shape
            const headGeo = new THREE.BoxGeometry(0.35, 0.5, 0.45);
            const head = new THREE.Mesh(headGeo, mat);
            head.position.set(0, 0.85, -0.05);
            head.rotation.x = -0.2;
            // Snout
            const snout = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.25, 0.35), mat);
            snout.position.set(0, 0.7, -0.28);
            // Ear
            const ear = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.2, 8), mat);
            ear.position.set(0, 1.2, 0.05);
            // Mane
            const mane = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.4, 0.3), accentMat);
            mane.position.set(0.15, 0.95, 0.05);
            mane.rotation.z = 0.3;
            group.add(base, body, head, snout, ear, mane);
            break;
        }
        case 'B': {
            // Bishop
            const base = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.42, 0.15, 16), mat);
            base.position.y = 0.075;
            const body = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.33, 0.7, 16), mat);
            body.position.y = 0.5;
            const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.22, 16, 16), mat);
            shoulder.position.y = 0.88;
            const head = new THREE.Mesh(new THREE.SphereGeometry(0.15, 16, 16), mat);
            head.position.y = 1.05;
            head.scale.y = 1.4;
            const knob = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 8), accentMat);
            knob.position.y = 1.25;
            group.add(base, body, shoulder, head, knob);
            break;
        }
        case 'Q': {
            // Queen
            const base = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.45, 0.15, 16), mat);
            base.position.y = 0.075;
            const body = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.38, 0.8, 16), mat);
            body.position.y = 0.55;
            const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.28, 16, 16), mat);
            shoulder.position.y = 1.0;
            const crown = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.28, 0.15, 16), mat);
            crown.position.y = 1.18;
            // Crown points
            for (let i = 0; i < 5; i++) {
                const angle = (i / 5) * Math.PI * 2;
                const point = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 8), accentMat);
                point.position.set(Math.cos(angle) * 0.28, 1.3, Math.sin(angle) * 0.28);
                group.add(point);
            }
            const orb = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 8), accentMat);
            orb.position.y = 1.35;
            group.add(base, body, shoulder, crown, orb);
            break;
        }
        case 'K': {
            // King
            const base = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.45, 0.15, 16), mat);
            base.position.y = 0.075;
            const body = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.4, 0.9, 16), mat);
            body.position.y = 0.6;
            const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.3, 16, 16), mat);
            shoulder.position.y = 1.1;
            const crown = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.3, 0.12, 16), mat);
            crown.position.y = 1.28;
            // Cross
            const crossV = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.35, 0.08), accentMat);
            crossV.position.y = 1.52;
            const crossH = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.08, 0.08), accentMat);
            crossH.position.y = 1.58;
            group.add(base, body, shoulder, crown, crossV, crossH);
            break;
        }
    }

    group.scale.setScalar(scale);
    group.traverse(child => {
        if (child.isMesh) {
            child.castShadow = true;
            child.receiveShadow = true;
        }
    });
    return group;
}

function createPieces() {
    // Clear existing
    while (piecesGroup.children.length) piecesGroup.remove(piecesGroup.children[0]);
    pieceMeshes = {};

    for (let r = 0; r < 8; r++) {
        for (let c = 0; c < 8; c++) {
            const piece = board[r][c];
            if (piece) {
                const type = piece[1];
                const color = piece[0];
                const mesh = createPieceMesh(type, color);
                mesh.userData = { row: r, col: c, piece: piece };
                piecesGroup.add(mesh);
                pieceMeshes[`${r},${c}`] = mesh;
            }
        }
    }
}

function getSquarePos(row, col) {
    return new THREE.Vector3(
        (col - BOARD_OFFSET) * SQUARE_SIZE,
        0,
        (row - BOARD_OFFSET) * SQUARE_SIZE
    );
}

function updatePiecePositions() {
    // Sync piece meshes with board state
    const newMeshes = {};
    for (let r = 0; r < 8; r++) {
        for (let c = 0; c < 8; c++) {
            const key = `${r},${c}`;
            if (pieceMeshes[key]) {
                const mesh = pieceMeshes[key];
                const pos = getSquarePos(r, c);
                mesh.position.copy(pos);
                mesh.position.y = 0;
                newMeshes[key] = mesh;
            }
        }
    }
    pieceMeshes = newMeshes;
}

function animatePieceMove(fromRow, fromCol, toRow, toCol, callback) {
    const key = `${fromRow},${fromCol}`;
    const mesh = pieceMeshes[key];
    if (!mesh) { if (callback) callback(); return; }

    const startPos = mesh.position.clone();
    const endPos = getSquarePos(toRow, toCol);
    const midPoint = new THREE.Vector3(
        (startPos.x + endPos.x) / 2,
        1.5,
        (startPos.z + endPos.z) / 2
    );

    const duration = 400;
    const startTime = performance.now();

    animating = true;

    function animate(time) {
        const elapsed = time - startTime;
        const t = Math.min(elapsed / duration, 1);
        const eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

        // Arc movement
        mesh.position.lerpVectors(startPos, endPos, eased);
        const arcHeight = Math.sin(eased * Math.PI) * 1.2;
        mesh.position.y = arcHeight;

        // Slight rotation during move
        mesh.rotation.y = eased * Math.PI * 0.1;

        if (t < 1) {
            requestAnimationFrame(animate);
        } else {
            mesh.position.copy(endPos);
            mesh.position.y = 0;
            mesh.rotation.y = 0;
            animating = false;
            if (callback) callback();
        }
    }
    requestAnimationFrame(animate);
}

function animateCapture(capturedRow, capturedCol, callback) {
    const key = `${capturedRow},${capturedCol}`;
    const mesh = pieceMeshes[key];
    if (!mesh) { if (callback) callback(); return; }

    const startTime = performance.now();
    const duration = 300;

    function animate(time) {
        const elapsed = time - startTime;
        const t = Math.min(elapsed / duration, 1);
        const eased = 1 - Math.pow(1 - t, 3);

        mesh.scale.setScalar(0.45 * (1 - eased));
        mesh.position.y = eased * 0.5;
        mesh.rotation.y += 0.2;

        if (t < 1) {
            requestAnimationFrame(animate);
        } else {
            piecesGroup.remove(mesh);
            delete pieceMeshes[key];
            if (callback) callback();
        }
    }
    requestAnimationFrame(animate);
}

function showLegalMoves(moves) {
    clearHighlights();
    for (const [r, c] of moves) {
        const pos = getSquarePos(r, c);
        const isCapture = board[r][c] !== null;
        const geo = isCapture
            ? new THREE.RingGeometry(0.3, 0.45, 32)
            : new THREE.CircleGeometry(0.15, 16);
        const mat = new THREE.MeshBasicMaterial({
            color: isCapture ? 0xff4444 : 0x44ff44,
            transparent: true, opacity: 0.6, side: THREE.DoubleSide
        });
        const marker = new THREE.Mesh(geo, mat);
        marker.rotation.x = -Math.PI / 2;
        marker.position.set(pos.x, 0.18, pos.z);
        highlightsGroup.add(marker);
        highlightMeshes.push(marker);
    }
}

function showSelectedHighlight(row, col) {
    clearHighlights();
    const pos = getSquarePos(row, col);
    const geo = new THREE.BoxGeometry(SQUARE_SIZE - 0.05, 0.05, SQUARE_SIZE - 0.05);
    const mat = new THREE.MeshBasicMaterial({
        color: 0x4488ff, transparent: true, opacity: 0.5
    });
    const marker = new THREE.Mesh(geo, mat);
    marker.position.set(pos.x, 0.17, pos.z);
    highlightsGroup.add(marker);
    highlightMeshes.push(marker);
}

function clearHighlights() {
    for (const m of highlightMeshes) {
        highlightsGroup.remove(m);
        m.geometry.dispose();
        m.material.dispose();
    }
    highlightMeshes = [];
}

// ============ GAME LOGIC ============
function executeMove(fromRow, fromCol, toRow, toCol, promotionType) {
    const piece = board[fromRow][fromCol];
    const color = piece[0];
    const type = piece[1];
    const captured = board[toRow][toCol];

    // Save state for undo
    const state = {
        from: [fromRow, fromCol],
        to: [toRow, toCol],
        piece: piece,
        captured: captured,
        castlingRights: { ...castlingRights },
        enPassantTarget: enPassantTarget ? [...enPassantTarget] : null,
        halfMoveClock: halfMoveClock
    };

    // Handle en passant capture
    let epCapture = false;
    if (type === 'P' && enPassantTarget && toRow === enPassantTarget[0] && toCol === enPassantTarget[1]) {
        const capturedRow = color === WHITE ? toRow + 1 : toRow - 1;
        state.epCaptured = board[capturedRow][toCol];
        board[capturedRow][toCol] = null;
        epCapture = true;
    }

    // Handle castling
    let castled = false;
    if (type === 'K' && Math.abs(toCol - fromCol) === 2) {
        castled = true;
        const homeRow = color === WHITE ? 7 : 0;
        if (toCol === 6) { // Kingside
            board[homeRow][5] = board[homeRow][7];
            board[homeRow][7] = null;
            state.rookFrom = [homeRow, 7];
            state.rookTo = [homeRow, 5];
        } else { // Queenside
            board[homeRow][3] = board[homeRow][0];
            board[homeRow][0] = null;
            state.rookFrom = [homeRow, 0];
            state.rookTo = [homeRow, 3];
        }
    }

    // Update castling rights
    if (type === 'K') {
        castlingRights[color + 'K'] = false;
        castlingRights[color + 'Q'] = false;
    }
    if (type === 'R') {
        if (fromCol === 0) castlingRights[color + 'Q'] = false;
        if (fromCol === 7) castlingRights[color + 'K'] = false;
    }
    // If rook is captured
    if (toRow === 0 && toCol === 0) castlingRights.bQ = false;
    if (toRow === 0 && toCol === 7) castlingRights.bK = false;
    if (toRow === 7 && toCol === 0) castlingRights.wQ = false;
    if (toRow === 7 && toCol === 7) castlingRights.wK = false;

    // Move piece
    board[toRow][toCol] = piece;
    board[fromRow][fromCol] = null;

    // Pawn promotion
    if (type === 'P' && (toRow === 0 || toRow === 7)) {
        if (promotionType) {
            board[toRow][toCol] = color + promotionType;
        } else {
            // Show promotion dialog
            showPromotionDialog(color, toRow, toCol, state);
            return;
        }
    }

    // Update en passant target
    enPassantTarget = null;
    if (type === 'P' && Math.abs(toRow - fromRow) === 2) {
        enPassantTarget = [(fromRow + toRow) / 2, fromCol];
    }

    // Captured pieces
    if (captured) {
        if (captured[0] === WHITE) capturedWhite.push(captured);
        else capturedBlack.push(captured);
    }

    moveHistory.push(state);
    clearHighlights();

    // Animate
    animatePieceMove(fromRow, fromCol, toRow, toCol, () => {
        if (captured || epCapture) {
            if (captured) animateCapture(toRow, toCol, () => {
                updateBoardUI();
                switchTurn();
            });
            else {
                updateBoardUI();
                switchTurn();
            }
        } else {
            updateBoardUI();
            switchTurn();
        }
    });
}

function showPromotionDialog(color, row, col, state) {
    const overlay = document.getElementById('promotion-overlay');
    const choices = document.getElementById('promotion-choices');
    choices.innerHTML = '';

    const pieces = ['Q', 'R', 'B', 'N'];
    const symbols = { Q: '♕', R: '♖', B: '♗', N: '♘' };

    for (const p of pieces) {
        const btn = document.createElement('button');
        btn.className = 'promo-btn';
        btn.textContent = symbols[p];
        btn.onclick = () => {
            board[row][col] = color + p;
            overlay.classList.remove('active');
            moveHistory.push(state);
            updateBoardUI();
            switchTurn();
        };
        choices.appendChild(btn);
    }
    overlay.classList.add('active');
}

function switchTurn() {
    currentTurn = currentTurn === WHITE ? BLACK : WHITE;
    selectedSquare = null;
    legalMoves = [];
    clearHighlights();

    // Check for checkmate/stalemate
    const inCheck = isInCheck(currentTurn, board);
    const hasLegal = hasAnyLegalMoves(currentTurn);

    if (!hasLegal) {
        gameOver = true;
        if (inCheck) {
            const winner = currentTurn === WHITE ? 'Black' : 'White';
            document.getElementById('status').textContent = `Checkmate! ${winner} wins!`;
        } else {
            document.getElementById('status').textContent = 'Stalemate! Draw!';
        }
        return;
    }

    if (inCheck) {
        document.getElementById('check-flash').style.borderColor = '#ff4444';
        setTimeout(() => {
            document.getElementById('check-flash').style.borderColor = 'transparent';
        }, 500);
        document.getElementById('status').textContent =
            (currentTurn === WHITE ? 'White' : 'Black') + ' is in Check!';
    } else {
        document.getElementById('status').textContent =
            (currentTurn === WHITE ? 'White' : 'Black') + "'s Turn";
    }

    updateUI();
}

function updateBoardUI() {
    createPieces();
    updateCapturedUI();
}

function updateCapturedUI() {
    document.getElementById('captured-white').textContent =
        capturedWhite.map(p => {
            const sym = { K: '♔', Q: '♕', R: '♖', B: '♗', N: '♘', P: '♙' };
            return sym[p[1]] || '';
        }).join(' ');
    document.getElementById('captured-black').textContent =
        capturedBlack.map(p => {
            const sym = { K: '♚', Q: '♛', R: '♜', B: '♝', N: '♞', P: '♟' };
            return sym[p[1]] || '';
        }).join(' ');
}

function updateUI() {
    if (!gameOver) {
        document.getElementById('status').textContent =
            (currentTurn === WHITE ? 'White' : 'Black') + "'s Turn";
    }
}

// ============ INPUT HANDLING ============
function onMouseClick(event) {
    if (animating || gameOver) return;

    mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

    raycaster.setFromCamera(mouse, camera);

    // Check piece intersections first
    const pieceIntersects = raycaster.intersectObjects(piecesGroup.children, true);
    let clickedPiece = null;
    let clickedPieceGroup = null;
    for (const hit of pieceIntersects) {
        let obj = hit.object;
        while (obj.parent && obj.parent !== piecesGroup) obj = obj.parent;
        if (obj.userData && obj.userData.row !== undefined) {
            clickedPiece = obj;
            break;
        }
    }

    // Check board square intersections
    const squareIntersects = raycaster.intersectObjects(boardGroup.children);
    let clickedSquare = null;
    for (const hit of squareIntersects) {
        if (hit.object.userData && hit.object.userData.isSquare) {
            clickedSquare = hit.object.userData;
            break;
        }
    }

    if (clickedPiece) {
        const row = clickedPiece.userData.row;
        const col = clickedPiece.userData.col;
        const piece = board[row][col];

        if (piece && piece[0] === currentTurn) {
            // Select piece
            selectedSquare = [row, col];
            legalMoves = getLegalMoves(row, col);
            showSelectedHighlight(row, col);
            showLegalMoves(legalMoves);
            return;
        } else if (selectedSquare && clickedPiece) {
            // Try to capture
            const [sr, sc] = selectedSquare;
            if (legalMoves.some(m => m[0] === row && m[1] === col)) {
                executeMove(sr, sc, row, col);
            }
            return;
        }
    }

    if (clickedSquare && selectedSquare) {
        const [sr, sc] = selectedSquare;
        const tr = clickedSquare.row;
        const tc = clickedSquare.col;

        if (legalMoves.some(m => m[0] === tr && m[1] === tc)) {
            executeMove(sr, sc, tr, tc);
        } else {
            selectedSquare = null;
            legalMoves = [];
            clearHighlights();
        }
    }
}

function onMouseMove(event) {
    mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

    raycaster.setFromCamera(mouse, camera);
    const intersects = raycaster.intersectObjects(boardGroup.children);

    // Reset board square colors
    for (const child of boardGroup.children) {
        if (child.userData && child.userData.isSquare && child.material) {
            const r = child.userData.row;
            const c = child.userData.col;
            const isLight = (r + c) % 2 === 0;
            child.material.color.setHex(isLight ? 0xf0d9b5 : 0xb58863);
        }
    }

    // Highlight hovered square
    if (intersects.length > 0 && intersects[0].object.userData.isSquare) {
        const { row, col } = intersects[0].object.userData;
        const isLight = (row + col) % 2 === 0;
        intersects[0].object.material.color.setHex(0xffee88);
    }
}

function onResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// ============ CONTROLS ============
function resetGame() {
    initBoard();
    createPieces();
    updatePiecePositions();
    clearHighlights();
}

function undoMove() {
    if (moveHistory.length === 0 || animating) return;

    const state = moveHistory.pop();
    const [fr, fc] = state.from;
    const [tr, tc] = state.to;

    // Restore piece
    board[fr][fc] = state.piece;
    board[tr][tc] = state.captured;

    // Restore en passant capture
    if (state.epCaptured) {
        const capturedRow = state.piece[0] === WHITE ? tr + 1 : tr - 1;
        board[capturedRow][tc] = state.epCaptured;
        // Remove from captured lists
        const capturedArr = state.epCaptured[0] === WHITE ? capturedWhite : capturedBlack;
        if (capturedArr.length > 0) capturedArr.pop();
    }

    // Restore castling
    if (state.rookFrom) {
        board[state.rookFrom[0]][state.rookFrom[1]] = board[state.rookTo[0]][state.rookTo[1]];
        board[state.rookTo[0]][state.rookTo[1]] = null;
    }

    // Restore castling rights
    castlingRights = { ...state.castlingRights };
    enPassantTarget = state.enPassantTarget;
    halfMoveClock = state.halfMoveClock;

    // Restore captured pieces
    if (state.captured) {
        const arr = state.captured[0] === WHITE ? capturedWhite : capturedBlack;
        if (arr.length > 0) arr.pop();
    }

    selectedSquare = null;
    legalMoves = [];
    clearHighlights();
    createPieces();
    updatePiecePositions();
    updateCapturedUI();
    currentTurn = currentTurn === WHITE ? BLACK : WHITE;
    updateUI();
    gameOver = false;
    document.getElementById('check-flash').style.borderColor = 'transparent';
}

function flipBoard() {
    boardFlipped = !boardFlipped;
    const targetY = boardFlipped ? 10 : 10;
    const targetZ = boardFlipped ? -8 : 8;
    const targetLookAt = boardFlipped ? new THREE.Vector3(0, 0, 0) : new THREE.Vector3(0, 0, 0);

    const startPos = camera.position.clone();
    const startLookAt = new THREE.Vector3(0, 0, 0);
    const endPos = new THREE.Vector3(0, targetY, targetZ);
    const duration = 800;
    const startTime = performance.now();

    function animate(time) {
        const elapsed = time - startTime;
        const t = Math.min(elapsed / duration, 1);
        const eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

        camera.position.lerpVectors(startPos, endPos, eased);
        camera.lookAt(0, 0, 0);

        if (t < 1) requestAnimationFrame(animate);
    }
    requestAnimationFrame(animate);
}

// ============ ANIMATION LOOP ============
function animate() {
    requestAnimationFrame(animate);

    // Subtle piece breathing animation
    const time = performance.now() * 0.001;
    for (const key in pieceMeshes) {
        const mesh = pieceMeshes[key];
        if (mesh && !animating) {
            mesh.position.y = Math.sin(time * 2 + parseInt(key) * 0.5) * 0.02;
        }
    }

    // Pulse legal move markers
    for (const m of highlightMeshes) {
        m.material.opacity = 0.4 + Math.sin(time * 3) * 0.2;
    }

    renderer.render(scene, camera);
}

// ============ INIT ============
initBoard();
initThree();
animate();
</script>
