length: 20 + Math.random() * 40
});
}

// Rebar sticking out
for (let i = 0; i < 2; i++) {
decorations.push({
x: Math.random() * W,
y: baseY - 50 - Math.random() * 50,
type: 'rebar',
length: 30 + Math.random() * 20
});
}

// Exit ladder at top
platforms.push({ x: W / 2 - 30, y: baseY - floorHeight + 20, w: 60, h: 16, type: 'ground' });
collectibles.push({ x: W / 2, y: baseY - floorHeight - 10, collected: false, bobOffset: 0, type: 'ladder', value: 100, emoji: '🪜' });
}

function startGame() {
initAudio();
document.getElementById('startScreen').classList.add('hidden');
document.getElementById('gameOverScreen').classList.add('hidden');
document.getElementById('winScreen').classList.add('hidden');

game.score = 0;
game.lives = 3;
game.floor = 1;
game.cameraY = 0;
game.targetCameraY = 0;
game.particles = [];
game.floatingTexts = [];
game.time = 0;
game.invincible = 0;

player.x = 400;
player.y = H - 140;
player.vx = 0;
player.vy = 0;
player.onGround = false;
player.sliding = false;

generateFloor(game.floor);
game.state = 'playing';
updateUI();
}

function updateUI() {
document.getElementById('scoreDisplay').textContent = '🏆 Punti: ' + game.score;
document.getElementById('floorDisplay').textContent = '🏗️ Piano: ' + game.floor + '/' + game.maxFloor;
document.getElementById('livesDisplay').textContent = '❤️ Vite: ' + game.lives;
}

function spawnParticles(x, y, color, count, spread) {
for (let i = 0; i < count; i++) {
game.particles.push({
x: x, y: y,
vx: (Math.random() - 0.5) * spread,
vy: (Math.random() - 0.5) * spread - 2,
life: 30 + Math.random() * 30,
maxLife: 60,
color: color,
size: 2 + Math.random() * 4
});
}
}

function spawnFloatingText(x, y, text, color) {
game.floatingTexts.push({ x, y, text, color, life: 60, vy: -2 });
}

function getMovingPlatformY(mp) {
if (mp.dir === 'h') return mp.origY;
return mp.origY + Math.sin(game.time * 0.02 * mp.speed + mp.phase) * mp.range;
}

function getMovingPlatformX(mp) {
if (mp.dir === 'v') return mp.origX;
return mp.origX + Math.sin(game.time * 0.02 * mp.speed + mp.phase) * mp.range;
}

function getAllPlatforms() {
let all = [...platforms];
movingPlatforms.forEach(mp => {
all.push({
x: getMovingPlatformX(mp),
y: getMovingPlatformY(mp),
w: mp.w, h: mp.h, type: mp.type
});
});
return all;
}

function update() {
if (game.state !== 'playing') return;

game.time++;
let moveLeft = keys['ArrowLeft'] || keys['KeyA'] || touchLeft;
let moveRight = keys['ArrowRight'] || keys['KeyD'] || touchRight;
let jump = keys['Space'] || keys['ArrowUp'] || keys['KeyW'] || touchJump;
let slide = keys['ArrowDown'] || keys['KeyS'] || touchSlide;

// Player movement
let accel = player.onGround ? 0.8 : 0.5;
let friction = player.onGround ? 0.85 : 0.95;

if (moveLeft) { player.vx -= accel; player.facing = -1; }
if (moveRight) { player.vx += accel; player.facing = 1; }

player.vx *= friction;
if (Math.abs(player.vx) > 6) player.vx = 6 * Math.sign(player.vx);

// Jump
if (jump && player.onGround && !player.sliding) {
player.vy = -12;
player.onGround = false;
player.jumping = true;
playJump();
}

// Slide
if (slide && player.onGround && !player.sliding) {
player.sliding = true;
player.slideTimer = 30;
player.h = 22;
player.y += 18;
playSound(200, 0.1, 'triangle', 0.05);
}

if (player.sliding) {
player.slideTimer--;
if (player.slideTimer <= 0) {
player.sliding = false;
player.h = 40;
player.y -= 18;
}
}

// Gravity
player.vy += 0.6;
if (player.vy > 15) player.vy = 15;

// Move
player.x += player.vx;
player.y += player.vy;

// Screen wrap
if (player.x < -20) player.x = W + 20;
if (player.x > W + 20) player.x = -20;

// Collision with platforms
let allPlatforms = getAllPlatforms();
player.onGround = false;

for (let p of allPlatforms) {
if (player.x + player.w / 2 > p.x && player.x - player.w / 2 < p.x + p.w) {
if (player.vy >= 0 && player.y + player.h / 2 >= p.y && player.y + player.h / 2 <= p.y + p.h + player.vy + 2) {
player.y = p.y - player.h / 2;
player.vy = 0;
player.onGround = true;
player.jumping = false;

// Moving platform carry
if (p.type === 'moving') {
let mp = movingPlatforms.find(m =>
Math.abs(getMovingPlatformX(m) - p.x) < 2 && Math.abs(getMovingPlatformY(m) - p.y) < 2
);
if (mp && mp.dir === 'h') {
player.x += Math.cos(game.time * 0.02 * mp.speed + mp.phase) * mp.speed * mp.range * 0.02;
}
}
}
}
}

// Collectibles
for (let c of collectibles) {
if (c.collected) continue;
let bobY = c.y + Math.sin(game.time * 0.05 + c.bobOffset) * 5;
let dx = player.x - c.x;
let dy = player.y - bobY;
if (Math.abs(dx) < 25 && Math.abs(dy) < 25) {
c.collected = true;
game.score += c.value;
playCollect();
spawnParticles(c.x, bobY, '#ffdd00', 10, 4);
spawnFloatingText(c.x, bobY, '+' + c.value, '#ffdd00');

if (c.type === 'ladder') {
if (game.floor >= game.maxFloor) {
game.state = 'win';
playWin();
document.getElementById('winScore').textContent = 'Punti: ' + game.score;
document.getElementById('winScreen').classList.remove('hidden');
return;
} else {
game.floor++;
game.score += 500;
spawnFloatingText(W / 2, H / 2, 'Piano ' + game.floor + '! +500', '#44ff44');
setTimeout(() => {
player.x = 400;
player.y = H - 140;
player.vx = 0;
player.vy = 0;
generateFloor(game.floor);
updateUI();
}, 1000);
}
}
}
}

// Hazards
if (game.invincible > 0) {
game.invincible--;
} else {
for (let h of hazards) {
if (h.type === 'fallingBrick') {
h.timer--;
if (h.timer <= 0 && h.active) {
h.y += 3;
h.active = false;
}
if (!h.active && h.y > player.y - 50 && h.y < player.y + 50) {
h.active = true;
h.y = player.y - 200 - Math.random() * 100;
h.timer = 60 + Math.random() * 120;
}
if (!h.active) {
let dx = player.x - h.x;
let dy = player.y - h.y;
if (Math.abs(dx) < 20 && Math.abs(dy) < 25) {
hitPlayer();
h.active = true;
h.y = player.y - 200;
h.timer = 60;
}
}
} else if (h.type === 'crane') {
h.x += h.speed * h.dir;
if (h.x < -80 || h.x > W + 80) h.dir *= -1;
let dx = player.x - h.x;
let dy = player.y - h.y;
if (Math.abs(dx) < 40 && Math.abs(dy) < 20) {
hitPlayer();
}
}
}
}

// Fall death
let lowestPlatform = Math.max(...platforms.map(p => p.y));
if (player.y > lowestPlatform + 200) {
hitPlayer(true);
}

// Camera
let targetCamY = player.y - H * 0.6;
if (targetCamY < 0) targetCamY = 0;
game.targetCameraY = targetCamY;
game.cameraY += (game.targetCameraY - game.cameraY) * 0.08;

// Screen shake
if (game.shakeTime > 0) {
game.shakeTime--;
game.shakeX = (Math.random() - 0.5) * game.shakeTime * 0.8;
game.shakeY = (Math.random() - 0.5) * game.shakeTime * 0.8;
} else {
game.shakeX = 0;
game.shakeY = 0;
}

// Update particles
game.particles = game.particles.filter(p => {
p.x += p.vx;
p.y += p.vy;
p.vy += 0.1;
p.life--;
return p.life > 0;
});

// Update floating texts
game.floatingTexts = game.floatingTexts.filter(t => {
t.y += t.vy;
t.life--;
return t.life > 0;
});

// Animation
player.animTimer++;
if (player.animTimer > 8) {
player.animTimer = 0;
player.animFrame = (player.animFrame + 1) % 4;
}

updateUI();
}

function hitPlayer(fell = false) {
if (game.invincible > 0) return;
game.lives--;
game.invincible = 90;
game.shakeTime = 15;
playHit();
spawnParticles(player.x, player.y, '#ff4444', 15, 6);

if (fell) {
// Respawn on nearest platform
let nearest = platforms.reduce((best, p) => {
let d = Math.abs(p.y - player.y);
return d < best.d ? { p, d } : best;
}, { p: platforms[0], d: Infinity });
player.x = best.p.x + best.p.w / 2;
player.y = best.p.y - 50;
player.vy = 0;
player.vx = 0;
}

if (game.lives <= 0) {
game.state = 'gameover';
playFall();
document.getElementById('finalScore').textContent = 'Punti: ' + game.score;
document.getElementById('gameOverScreen').classList.remove('hidden');
}
}

function draw() {
ctx.save();
ctx.translate(game.shakeX, game.shakeY);

// Sky gradient based on floor
let skyGrad = ctx.createLinearGradient(0, 0, 0, H);
let hue = 200 + game.floor * 5;
skyGrad.addColorStop(0, `hsl(${hue}, 60%, ${Math.max(20, 40 - game.floor * 2)}%)`);
skyGrad.addColorStop(1, `hsl(${hue + 20}, 40%, ${Math.max(10, 25 - game.floor)})`);
ctx.fillStyle = skyGrad;
ctx.fillRect(-10, -10, W + 20, H + 20);

// Background buildings
drawBackground();

ctx.save();
ctx.translate(0, -game.cameraY);

// Draw decorations (behind platforms)
for (let d of decorations) {
if (d.type === 'pipe') {
ctx.fillStyle = '#888';
ctx.fillRect(d.x, d.y, 6, d.length);
ctx.fillStyle = '#666';
ctx.fillRect(d.x - 2, d.y, 10, 8);
} else if (d.type === 'bar') {
ctx.strokeStyle = '#999';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.moveTo(d.x, d.y);
ctx.lineTo(d.x, d.y - d.length);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(d.x - 5, d.y - d.length + 5);
ctx.lineTo(d.x + 5, d.y - d.length + 5);
ctx.stroke();
} else if (d.type === 'rebar') {
ctx.strokeStyle = '#aa6633';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(d.x, d.y);
ctx.lineTo(d.x, d.y - d.length);
