}
}
}

// Draw platforms
for (let p of platforms) {
if (p.type === 'ground') {
// Concrete floor
ctx.fillStyle = '#777';
ctx.fillRect(p.x, p.y, p.w, p.h);
ctx.fillStyle = '#888';
ctx.fillRect(p.x, p.y, p.w, 4);
// Grid lines
ctx.strokeStyle = '#666';
ctx.lineWidth = 1;
for (let gx = p.x; gx < p.x + p.w; gx += 40) {
