// Wood grain
ctx.strokeStyle = '#a07020';
ctx.lineWidth = 1;
for (let i = 0; i < p.w; i += 15) {
ctx.beginPath();
ctx.moveTo(p.x + i, p.y + 4);
ctx.lineTo(p.x + i + 8, p.y + p.h - 4);
ctx.stroke();
}
// Support beams
ctx.fillStyle = '#8B6914';
ctx.fillRect(p.x + 5, p.y + p.h, 6, 12);
ctx.fillRect(p.x + p.w - 11, p.y + p.h, 6, 12);
} else if (p.type === 'scaffold') {
// Scaffolding
ctx.fillStyle = '#aaa';
ctx.fillRect(p.x, p.y, p.w, p.h);
ctx.fillStyle = '#999';
ctx.fillRect(p.x, p.y, p.w, 3);
// Cross braces
ctx.strokeStyle = '#bbb';
ctx.lineWidth = 2;
for (let i = 0; i < p.w; i += 30) {
ctx.beginPath();
ctx.moveTo(p.x + i, p.y);
ctx.lineTo(p.x + i + 15, p.y + p.h);
ctx.stroke();
}
} else if (p.type === 'moving') {
ctx.fillStyle = '#4488ff';
ctx.fillRect(p.x, p.y, p.w, p.h);
ctx.fillStyle = '#66aaff';
ctx.fillRect(p.x, p.y, p.w, 3);
// Arrow indicators
ctx.fillStyle = '#fff';
ctx.font = '10px Arial';
ctx.textAlign = 'center';
