}

// Draw hazards
for (let h of hazards) {
if (h.type === 'fallingBrick') {
ctx.fillStyle = h.active ? '#cc4444' : '#aa3333';
ctx.fillRect(h.x - h.w / 2, h.y - h.h / 2, h.w, h.h);
ctx.strokeStyle = '#882222';
ctx.lineWidth = 1;
ctx.strokeRect(h.x - h.w / 2, h.y - h.h / 2, h.w, h.h);
// Brick pattern
ctx.strokeStyle = '#882222';
ctx.beginPath();
ctx.moveTo(h.x - h.w / 2, h.y);
ctx.lineTo(h.x + h.w / 2, h.y);
ctx.stroke();
// Warning
if (h.active) {
ctx.fillStyle = '#ff0';
ctx.font = '12px Arial';
ctx.textAlign = 'center';
ctx.fillText('⚠', h.x, h.y - 20);
}
} else if (h.type === 'hole') {
ctx.fillStyle = '#222';
ctx.fillRect(h.x, h.y - 4, h.w, h.h + 8);
