ctx.fillRect(h.x + i + 6, h.y + h.h, 6, 4);
}
} else if (h.type === 'crane') {
// Crane hook
ctx.fillStyle = '#ff4444';
ctx.fillRect(h.x - h.w / 2, h.y - h.h / 2, h.w, h.h);
ctx.fillStyle = '#cc3333';
ctx.fillRect(h.x - h.w / 2 + 4, h.y - h.h / 2 + 4, h.w - 8, h.h - 8);
// Hook
ctx.fillStyle = '#888';
ctx.beginPath();
ctx.arc(h.x, h.y + h.h / 2 + 5, 6, 0, Math.PI);
ctx.stroke();
}
}

// Draw player
drawPlayer();

// Draw particles
for (let p of game.particles) {
let alpha = p.life / p.maxLife;
ctx.globalAlpha = alpha;
ctx.fillStyle = p.color;
ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
}
ctx.globalAlpha = 1;

// Draw floating texts
for (let t of game.floatingTexts) {
let alpha = t.life / 60;
ctx.globalAlpha = alpha;
ctx.fillStyle = t.color;
ctx.font = 'bold 18px Arial';
ctx.textAlign = 'center';
ctx.fillText(t.text, t.x, t.y);
