ctx.fillRect(mmX, fy - 1, mmW, 2);
}

// Border
ctx.strokeStyle = '#ff8c00';
ctx.lineWidth = 1;
ctx.strokeRect(mmX, mmY, mmW, mmH);
}

function gameLoop() {
update();
draw();
requestAnimationFrame(gameLoop);
}

// Start
gameLoop();
