// ==================== GAME STATE ====================
let state = {
  lang: 'fr',
  numPlayers: 4,
  categories: [],
  mode: 'hotseat',
  players: [],
  imposterIndex: -1,
  secretWord: '',
  currentRound: 1,
  maxRounds: 3,
  currentPlayerIndex: 0,
  messages: [],
  votes: {},
  eliminatedPlayers: [],
  discussionTimer: null,
  discussionTimeLeft: 60,
  gamePhase: 'setup',
  scores: { crewmate: 0, imposter: 0 }
};

// ==================== UTILITY ====================
function t(key) { return TRANSLATIONS[state.lang][key] || key; }

function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
}

function setLang(lang, btn) {
  state.lang = lang;
  document.querySelectorAll('.lang-btn').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
  updateAllTranslations();
  renderCategoryGrid();
}

function updateAllTranslations() {
  document.querySelectorAll('[data-t]').forEach(el => {
    const key = el.getAttribute('data-t');
    if (TRANSLATIONS[state.lang][key]) {
      el.textContent = TRANSLATIONS[state.lang][key];
    }
  });
  const sub = document.getElementById('title-subtitle');
  if (sub) sub.textContent = t('subtitle');
}

function changePlayers(delta) {
  state.numPlayers = Math.max(3, Math.min(10, state.numPlayers + delta));
  document.getElementById('player-count-display').textContent = state.numPlayers;
}

function setMode(mode, btn) {
  state.mode = mode;
  document.querySelectorAll('.option-btn[data-mode]').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
}

// ==================== CATEGORY GRID ====================
function renderCategoryGrid() {
  const grid = document.getElementById('category-grid');
  grid.innerHTML = '';
  for (const [key, info] of Object.entries(CATEGORY_INFO)) {
    const name = info['name_' + state.lang];
    const btn = document.createElement('button');
    btn.className = 'cat-btn' + (state.categories.includes(key) ? ' selected' : '');
    btn.innerHTML = `<span class="cat-emoji">${info.emoji}</span>${name}`;
    btn.onclick = () => toggleCategory(key, btn);
    btn.dataset.cat = key;
    grid.appendChild(btn);
  }
}

function toggleCategory(cat, btn) {
  const idx = state.categories.indexOf(cat);
  if (idx >= 0) {
    state.categories.splice(idx, 1);
    btn.classList.remove('selected');
  } else {
    state.categories.push(cat);
    btn.classList.add('selected');
  }
}

// ==================== START GAME ====================
function startGame() {
  if (state.categories.length === 0) {
    alert(t('selectCategory'));
    return;
  }

  state.currentRound = 1;
  state.scores = { crewmate: 0, imposter: 0 };
  setupRound();
}

function setupRound() {
  state.eliminatedPlayers = [];
  state.messages = [];
  state.votes = {};

  // Build combined word list from selected categories
  let allWords = [];
  for (const cat of state.categories) {
    if (WORDS[state.lang][cat]) {
      allWords = allWords.concat(WORDS[state.lang][cat]);
    }
  }

  if (allWords.length < 2) {
    alert(t('noWords'));
    return;
  }

  // Pick secret word
  state.secretWord = allWords[Math.floor(Math.random() * allWords.length)];

  // Pick imposter
  state.imposterIndex = Math.floor(Math.random() * state.numPlayers);

  // Create players
  state.players = [];
  const colors = ['#e94560','#4ecdc4','#ffe66d','#a78bfa','#f97316','#06b6d4','#84cc16','#ec4899','#f43f5e','#14b8a6'];
  const avatars = ['🎭','🕵️','👤','🦊','🐱','🐶','🦁','🐼','🐸','🐵'];
  for (let i = 0; i < state.numPlayers; i++) {
    state.players.push({
      id: i,
      name: state.lang === 'fr' ? `Joueur ${i+1}` : state.lang === 'es' ? `Jugador ${i+1}` : `Player ${i+1}`,
      color: colors[i % colors.length],
      avatar: avatars[i % avatars.length],
      word: i === state.imposterIndex ? null : state.secretWord,
      isImposter: i === state.imposterIndex,
      eliminated: false
    });
  }

  state.currentPlayerIndex = 0;
  state.gamePhase = 'reveal';
  showRevealScreen();
}

// ==================== REVEAL SCREEN ====================
function showRevealScreen() {
  showScreen('screen-reveal');
  const player = state.players[state.currentPlayerIndex];
  const card = document.getElementById('reveal-card');

  const phaseLabel = document.getElementById('reveal-phase-label');
  phaseLabel.textContent = t('reveal').replace('{n}', state.currentRound) + ' — ' + t('reveal');

  if (state.mode === 'hotseat' && state.currentPlayerIndex > 0) {
    const prevPlayer = state.players[state.currentPlayerIndex - 1];
    card.innerHTML = `
      <div class="player-label">${t('revealSub').replace('{player}', prevPlayer.name)}</div>
      <div style="font-size:3em;margin:20px 0;">📱</div>
      <p style="color:var(--text-dim);margin-bottom:20px;">${state.currentPlayerIndex > 1 ? 'Passez l\'appareil à ' + player.name : ''}</p>
      <button class="btn btn-primary" onclick="showPlayerCard()">${player.name} — ${t('yourTurn')}</button>
    `;
  } else {
    showPlayerCard();
  }
}

function showPlayerCard() {
  const player = state.players[state.currentPlayerIndex];
  const card = document.getElementById('reveal-card');

  let wordHTML = '';
  if (player.isImposter) {
    wordHTML = `<div class="imposter-word">🎭 ${t('imposter')}</div>`;
  } else {
    wordHTML = `<div class="secret-word">${player.word}</div>`;
  }

  const catNames = state.categories.map(c => CATEGORY_INFO[c]['name_' + state.lang]).join(', ');

  card.innerHTML = `
    <div class="player-label">${t('reveal').replace('{n}', state.currentRound)}</div>
    <div class="player-number">${player.avatar} ${player.name}</div>
    ${wordHTML}
    <div class="category-label">📂 ${catNames}</div>
    <span class="role-badge ${player.isImposter ? 'imposter' : 'crewmate'}">
      ${player.isImposter ? '🎭 ' + t('imposter') : '✅ ' + t('crewmate')}
    </span>
    <div style="margin-top:24px;">
      <button class="btn btn-primary" onclick="nextReveal()">
        ${state.currentPlayerIndex < state.numPlayers - 1 ? '➡️ Suivant' : '🚀 Commencer la discussion'}
      </button>
    </div>
  `;
}

function nextReveal() {
  state.currentPlayerIndex++;
  if (state.currentPlayerIndex >= state.numPlayers) {
    // All players have seen their cards
    startDiscussion();
  } else {
    showRevealScreen();
  }
}

// ==================== DISCUSSION ====================
function startDiscussion() {
  state.gamePhase = 'discussion';
  showScreen('screen-discussion');

  document.getElementById('discussion-box').innerHTML = '';
  document.getElementById('msg-input').value = '';

  // Add system message
  addSystemMessage(`${t('discussionSub')}`);

  // Render players
  renderPlayersGrid();

  // Start timer
  state.discussionTimeLeft = state.numPlayers * 10;
  updateTimerBar();
  if (state.discussionTimer) clearInterval(state.discussionTimer);
  state.discussionTimer = setInterval(() => {
    state.discussionTimeLeft--;
    updateTimerBar();
    if (state.discussionTimeLeft <= 0) {
      clearInterval(state.discussionTimer);
      startVoting();
    }
  }, 1000);

  // AI messages if in AI mode
  if (state.mode === 'ai') {
    setTimeout(() => generateAIMessages(), 1500);
  }
}

function updateTimerBar() {
  const total = state.numPlayers * 10;
  const pct = (state.discussionTimeLeft / total) * 100;
  document.getElementById('discussion-timer').style.width = pct + '%';
}

function renderPlayersGrid() {
  const grid = document.getElementById('players-grid');
  grid.innerHTML = '';
  state.players.forEach(p => {
    const card = document.createElement('div');
    card.className = 'player-card' + (p.eliminated ? ' eliminated' : '');
    card.innerHTML = `
      <div class="p-avatar" style="background:${p.color}">${p.avatar}</div>
      <div class="p-name">${p.name}</div>
      <div class="p-status">${p.eliminated ? '❌ ' + t('eliminated') : '🟢 ' + t('remaining')}</div>
    `;
    grid.appendChild(card);
  });
}

function addSystemMessage(text) {
  const box = document.getElementById('discussion-box');
  const msg = document.createElement('div');
  msg.className = 'msg';
  msg.style.textAlign = 'center';
  msg.style.color = 'var(--text-dim)';
  msg.style.fontStyle = 'italic';
  msg.style.fontSize = '0.85em';
  msg.textContent = text;
  box.appendChild(msg);
  box.scrollTop = box.scrollHeight;
}

function addMessage(author, text, isSelf) {
  const box = document.getElementById('discussion-box');
  const msg = document.createElement('div');
  msg.className = 'msg ' + (isSelf ? 'self' : 'other');
  msg.innerHTML = `<div class="msg-author">${author}</div>${text}`;
  box.appendChild(msg);
  box.scrollTop = box.scrollHeight;
}

function sendMessage() {
  const input = document.getElementById('msg-input');
  const text = input.value.trim();
  if (!text) return;

  const player = state.players.find(p => !p.eliminated);
  if (player) {
    addMessage(player.name, text, true);
    state.messages.push({ author: player.name, text, isSelf: true });
  }
  input.value = '';

  // AI responses
  if (state.mode === 'ai') {
    setTimeout(() => generateAIMessage(), 1000 + Math.random() * 2000);
  }
}

function generateAIMessages() {
  const alivePlayers = state.players.filter(p => !p.eliminated && p.id !== 0);
  let delay = 2000;

  alivePlayers.forEach((p, i) => {
    setTimeout(() => {
      const msg = generateAIChatMessage(p);
      addMessage(p.name, msg, false);
      state.messages.push({ author: p.name, text: msg, isSelf: false });
    }, delay + i * 2500);
  });
}

function generateAIMessage() {
  const alivePlayers = state.players.filter(p => !p.eliminated && p.id !== 0);
  if (alivePlayers.length === 0) return;

  const p = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
  const msg = generateAIChatMessage(p);
  addMessage(p.name, msg, false);
  state.messages.push({ author: p.name, text: msg, isSelf: false });
}

function generateAIChatMessage(player) {
  const imposter = state.players[state.imposterIndex];
  const isImposterAI = player.isImposter;

  if (isImposterAI) {
    // Imposter tries to blend in
    const imposterLines = [
