  document.getElementById('vote-results').classList.add('hidden');
  document.getElementById('btn-start-vote').classList.add('hidden');

  const alivePlayers = state.players.filter(p => !p.eliminated);
  const grid = document.getElementById('vote-grid');
  grid.innerHTML = '';

  document.getElementById('vote-title').textContent = t('voteTitle');
  document.getElementById('vote-subtitle').textContent = `${alivePlayers.length} ${t('remaining')}`;

  alivePlayers.forEach(p => {
    const card = document.createElement('div');
    card.className = 'player-card';
    card.innerHTML = `
      <div class="p-avatar" style="background:${p.color}">${p.avatar}</div>
      <div class="p-name">${p.name}</div>
      <div class="p-status">🗳️ Voter</div>
    `;
    card.onclick = () => castVote(p);
    grid.appendChild(card);
  });

  // AI votes
  if (state.mode === 'ai') {
    setTimeout(() => {
      const aiPlayers = alivePlayers.filter(p => p.id !== 0);
      aiPlayers.forEach(p => {
        const voteTarget = aiVoteTarget(p, alivePlayers);
        state.votes[p.id] = voteTarget.id;
      });
    }, 1000);
  }
}

function castVote(victim) {
  // Player votes
  const alivePlayers = state.players.filter(p => !p.eliminated && p.id !== 0);
  state.votes[0] = victim.id;

  // AI votes
  if (state.mode === 'ai') {
    alivePlayers.forEach(p => {
      if (!state.votes[p.id]) {
        const voteTarget = aiVoteTarget(p, alivePlayers);
        state.votes[p.id] = voteTarget.id;
      }
    });
  }

  // Calculate results
  const voteCounts = {};
  state.players.filter(p => !p.eliminated).forEach(p => {
    const vote = state.votes[p.id];
    if (vote !== undefined) {
      voteCounts[vote] = (voteCounts[vote] || 0) + 1;
    }
  });

  // Find max votes
  let maxVotes = 0;
  let votedOut = null;
  for (const [pid, count] of Object.entries(voteCounts)) {
    if (count > maxVotes) {
      maxVotes = count;
      votedOut = state.players[parseInt(pid)];
    }
  }

  // Show results
  showVoteResults(voteCounts, votedOut, maxVotes);
}

function aiVoteTarget(aiPlayer, alivePlayers) {
  // AI votes randomly but slightly smarter
  // Imposter AI votes for crewmates
  // Crewmate AI votes randomly (with slight bias against suspicious players)
  const candidates = alivePlayers.filter(p => p.id !== aiPlayer.id);
  return candidates[Math.floor(Math.random() * candidates.length)];
}

function showVoteResults(voteCounts, votedOut, maxVotes) {
  const resultsDiv = document.getElementById('vote-results');
  resultsDiv.classList.remove('hidden');

  const alivePlayers = state.players.filter(p => !p.eliminated);
  const totalVotes = alivePlayers.length;

  let html = '';
  alivePlayers.forEach(p => {
    const count = voteCounts[p.id] || 0;
    const pct = (count / totalVotes) * 100;
    const isWinner = p === votedOut;
    html += `
      <div class="vote-bar-row">
        <div class="vote-name">${p.avatar} ${p.name}</div>
        <div class="vote-bar-bg">
          <div class="vote-bar-fill ${isWinner ? 'winner' : 'loser'}" style="width:${Math.max(pct, 5)}%">
            ${count} ${t('eliminated_players')}
          </div>
        </div>
      </div>
    `;
  });

  resultsDiv.innerHTML = html;

  // Show next button
  const btnRow = document.createElement('div');
  btnRow.style.marginTop = '20px';
  btnRow.style.textAlign = 'center';

  if (votedOut) {
    votedOut.eliminated = true;
