  setTimeout(() => {
    resultsDiv.scrollIntoView({ behavior: 'smooth' });
  }, 100);
}

// ==================== IMPOSTER REVEAL ====================
function showImposterReveal() {
  showScreen('screen-imposter-reveal');
  const imposter = state.players[state.imposterIndex];
  const votedOut = state.eliminatedPlayers[state.eliminatedPlayers.length - 1];
  const box = document.getElementById('imposter-reveal-box');

