      <button class="btn btn-outline" onclick="showScreen('screen-setup')">📋 ${t('menu')}</button>
    </div>
  `;

  if (isCrewmateWin) spawnConfetti();
}

// ==================== CONFETTI ====================
function spawnConfetti() {
  const container = document.createElement('div');
  container.className = 'confetti';
  document.body.appendChild(container);

  const colors = ['#e94560','#4ecdc4','#ffe66d','#a78bfa','#f97316','#06b6d4','#84cc16','#ec4899'];

  for (let i = 0; i < 50; i++) {
