  .story-card .story-text .highlight {
    color: var(--accent-gold);
  }

  .phrase-history {
    margin-top: 30px;
  }

  .phrase-history h3 {
    font-family: 'Playfair Display', serif;
    font-size: 1.3em;
    color: var(--text-secondary);
    margin-bottom: 15px;
    text-align: center;
  }

  .phrase-item {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 14px 18px;
