  .restart-btn {
    width: 100%;
    padding: 16px;
    border: 2px solid var(--accent-purple);
    border-radius: 14px;
    font-size: 1em;
    font-weight: 600;
    font-family: 'Inter', sans-serif;
    cursor: pointer;
    transition: all 0.3s;
    background: transparent;
    color: var(--accent-purple);
    margin-top: 15px;
  }

  .restart-btn:hover {
    background: var(--accent-purple);
    color: var(--bg-dark);
    transform: translateY(-2px);
  }

  .share-btn {
    width: 100%;
    padding: 16px;
    border: none;
    border-radius: 14px;
    font-size: 1em;
    font-weight: 600;
    font-family: 'Inter', sans-serif;
    cursor: pointer;
