  /* ===== RESPONSIVE ===== */
  @media (max-width: 600px) {
    .container { padding: 15px; }
    .title { font-size: 2em; }
    .setup-section { padding: 25px; }
    .phrase-card { padding: 25px; }
    .phrase-card .revealed-text { font-size: 1.3em; }
    .story-card { padding: 25px; }
    .story-card .story-text { font-size: 1.3em; }
  }

  /* ===== SCROLLBAR ===== */
  ::-webkit-scrollbar { width: 6px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: var(--accent-purple); border-radius: 3px; }
</style>
</head>
