  const restartBtn = document.getElementById('restartBtn');

  // ===== INIT =====
  function init() {
    updatePlayerCount();
    generatePlayerInputs();
  }

  function updatePlayerCount() {
    countDisplay.textContent = playerCount;
    aiCount.textContent = playerCount - 1;
  }

  function generatePlayerInputs() {
    playerInputs.innerHTML = '';
    for (let i = 0; i < playerCount; i++) {
      const div = document.createElement('div');
      div.className = 'player-name-input';
      div.style.animationDelay = `${i * 0.1}s`;
      const color = playerColors[i % playerColors.length];
      const emoji = playerEmojis[i % playerEmojis.length];
      const isUser = i === 0;
      div.innerHTML = `
        <div class="player-avatar" style="background:${color}22; color:${color};">${emoji}</div>
        <span class="player-label">${i + 1}</span>
        <input type="text" id="playerName${i}" placeholder="${isUser ? 'Votre nom' : 'Nom du joueur ' + (i + 1)}"
          value="${isUser ? 'Vous' : 'Joueur ' + (i + 1)}" maxlength="20">
      `;
      playerInputs.appendChild(div);
    }
  }

  // ===== EVENT LISTENERS =====
  decreaseBtn.addEventListener('click', () => {
    if (playerCount > 2) {
      playerCount--;
      updatePlayerCount();
      generatePlayerInputs();
    }
  });

  increaseBtn.addEventListener('click', () => {
    if (playerCount < 10) {
      playerCount++;
      updatePlayerCount();
      generatePlayerInputs();
    }
  });

  startBtn.addEventListener('click', startGame);
  submitBtn.addEventListener('click', submitPhrase);
  phraseInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submitPhrase();
    }
  });
  shareBtn.addEventListener('click', copyStory);
  restartBtn.addEventListener('click', restartGame);

  // ===== GAME LOGIC =====
  function startGame() {
    players = [];
    phrases = [];
    currentTurn = 0;

    for (let i = 0; i < playerCount; i++) {
      const input = document.getElementById(`playerName${i}`);
      const name = input.value.trim() || `Joueur ${i + 1}`;
      players.push({
        name: name,
        isAI: i !== 0,
        color: playerColors[i % playerColors.length],
        emoji: playerEmojis[i % playerEmojis.length]
      });
    }

    showScreen('gameScreen');
    nextTurn();
  }

  function showScreen(screenId) {
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
    document.getElementById(screenId).classList.add('active');
  }

  function nextTurn() {
    if (currentTurn >= playerCount) {
      revealStory();
      return;
    }

    const player = players[currentTurn];
    const progress = ((currentTurn) / playerCount) * 100;
    progressBar.style.width = progress + '%';
    turnText.textContent = `Tour ${currentTurn + 1} sur ${playerCount}`;
    cardNumber.textContent = `Phrase ${currentTurn + 1}`;
    cardPlayer.textContent = player.emoji + ' ' + player.name;

    // Reset card
    cardContent.innerHTML = '';
    phraseCard.classList.remove('revealed');

    if (player.isAI) {
      // AI turn
      isAI = true;
      inputArea.style.display = 'none';
      showAIThinking();
    } else {
      // Human turn
      isAI = false;
      inputArea.style.display = 'block';
      inputLabel.textContent = `À vous (${player.name}) d'écrire la suite !`;
      phraseInput.value = '';
      phraseInput.focus();
      submitBtn.disabled = true;

      // Enable/disable submit based on input
      phraseInput.addEventListener('input', () => {
        submitBtn.disabled = phraseInput.value.trim().length === 0;
      }, { once: true });
    }
  }

  function showAIThinking() {
    const thinkingText = aiThinkingTexts[Math.floor(Math.random() * aiThinkingTexts.length)];
    cardContent.innerHTML = `
      <div class="ai-thinking">
        <div class="brain-icon">🤖</div>
        <p class="thinking-text">${thinkingText}</p>
        <div class="thinking-dots">
          <span></span><span></span><span></span>
        </div>
      </div>
    `;

    const delay = 1200 + Math.random() * 1500;
    setTimeout(() => {
      const aiPhrase = aiPhrases[Math.floor(Math.random() * aiPhrases.length)];
      phrases.push({ player: players[currentTurn], text: aiPhrase });
      revealPhrase(aiPhrase);
    }, delay);
  }

  function revealPhrase(text) {
    cardContent.innerHTML = `<div class="revealed-text">${text}</div>`;
    phraseCard.classList.add('revealed');

    if (isAI) {
      setTimeout(() => {
        currentTurn++;
        nextTurn();
      }, 1500);
    }
  }

  function submitPhrase() {
    const text = phraseInput.value.trim();
    if (!text) return;

    phrases.push({ player: players[currentTurn], text: text });
    revealPhrase(text);

    submitBtn.disabled = true;
    phraseInput.disabled = true;

    setTimeout(() => {
      currentTurn++;
      nextTurn();
    }, 1500);
  }

  function revealStory() {
    progressBar.style.width = '100%';
    showScreen('revealScreen');
    launchConfetti();

    // Build full story
    const fullText = phrases.map(p => p.text).join(' ');
    storyText.innerHTML = `<span class="highlight">${fullText}</span>`;

    // Build phrase list
    phraseList.innerHTML = '';
    phrases.forEach((p, i) => {
      const item = document.createElement('div');
      item.className = 'phrase-item';
      item.style.animationDelay = `${i * 0.1}s`;
      item.innerHTML = `
        <div class="phrase-num" style="background:${p.player.color};">${i + 1}</div>
        <div>
          <div class="phrase-content">${p.text}</div>
          <div class="phrase-author">${p.player.emoji} ${p.player.name}${p.player.isAI ? ' (IA)' : ''}</div>
        </div>
      `;
      phraseList.appendChild(item);
    });
  }

  function copyStory() {
    const fullText = phrases.map(p => p.text).join(' ');
    const authorLines = phrases.map((p, i) => `${i + 1}. ${p.text} — ${p.player.name}${p.player.isAI ? ' (IA)' : ''}`).join('\n');
    const textToCopy = `📝 Cadavre Exquis\n\n${fullText}\n\n---\n${authorLines}`;

    navigator.clipboard.writeText(textToCopy).then(() => {
      shareBtn.textContent = '✅ Copié !';
      setTimeout(() => {
        shareBtn.textContent = '📋 Copier l\'histoire';
      }, 2000);
    }).catch(() => {
      // Fallback
      const ta = document.createElement('textarea');
      ta.value = textToCopy;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
      shareBtn.textContent = '✅ Copié !';
      setTimeout(() => {
        shareBtn.textContent = '📋 Copier l\'histoire';
      }, 2000);
    });
  }

  function restartGame() {
    currentTurn = 0;
    phrases = [];
    players = [];
    showScreen('welcomeScreen');
  }

  // ===== CONFETTI =====
  function launchConfetti() {
    const container = document.getElementById('confettiContainer');
    container.innerHTML = '';
    const colors = ['#ff6b9d', '#c084fc', '#60a5fa', '#fbbf24', '#34d399', '#f97316', '#ec4899'];

    for (let i = 0; i < 80; i++) {
      const piece = document.createElement('div');
      piece.className = 'confetti-piece';
      piece.style.left = Math.random() * 100 + '%';
      piece.style.background = colors[Math.floor(Math.random() * colors.length)];
      piece.style.width = (Math.random() * 8 + 5) + 'px';
      piece.style.height = (Math.random() * 8 + 5) + 'px';
      piece.style.borderRadius = Math.random() > 0.5 ? '50%' : '2px';
      piece.style.animationDuration = (Math.random() * 2 + 2) + 's';
      piece.style.animationDelay = (Math.random() * 1.5) + 's';
      container.appendChild(piece);
    }

    setTimeout(() => { container.innerHTML = ''; }, 5000);
  }

  // ===== START =====
  init();
</script>

</body>
</html>
