// ============ MAP SELECTION ============
function selectMap(el) {
document.querySelectorAll('.map-btn').forEach(b => b.classList.remove('active'));
el.classList.add('active');
selectedMap = el.dataset.map;
}

// ============ WORLD GENERATION ============
function generateWorld() {
buildings = [];
trees = [];
vehicles = [];
pickups = [];
enemies = [];

const seed = Math.random() * 10000;
function seededRandom(x, y) {
let h = x * 374761393 + y * 668265263 + seed;
h = (h ^ (h >> 13)) * 1274126177;
return ((h ^ (h >> 16)) & 0x7fffffff) / 0x7fffffff;
}

// Buildings
const buildingCount = selectedMap === 'city' ? 120 : selectedMap === 'desert' ? 40 : 60;
for (let i = 0; i < buildingCount; i++) {
const bx = (seededRandom(i, 0) - 0.5) * MAP_SIZE * 0.85;
const bz = (seededRandom(i, 1) - 0.5) * MAP_SIZE * 0.85;
const bw = 15 + seededRandom(i, 2) * 35;
const bd = 15 + seededRandom(i, 3) * 35;
const bh = selectedMap === 'city' ? 30 + seededRandom(i, 4) * 80 :
selectedMap === 'desert' ? 10 + seededRandom(i, 4) * 40 :
15 + seededRandom(i, 4) * 50;
buildings.push({ x: bx, z: bz, w: bw, d: bd, h: bh, color: generateBuildingColor() });
}

// Trees
const treeCount = selectedMap === 'forest' ? 300 : selectedMap === 'desert' ? 30 : 100;
for (let i = 0; i < treeCount; i++) {
const tx = (seededRandom(i + 100, 0) - 0.5) * MAP_SIZE * 0.9;
const tz = (seededRandom(i + 100, 1) - 0.5) * MAP_SIZE * 0.9;
trees.push({
x: tx, z: tz,
height: 8 + seededRandom(i + 100, 2) * 15,
radius: 2 + seededRandom(i + 100, 3) * 4,
type: seededRandom(i + 100, 4) > 0.5 ? 'pine' : 'oak'
});
}

// Vehicles
const vehicleCount = 15;
const vTypes = ['car', 'bike', 'truck'];
for (let i = 0; i < vehicleCount; i++) {
const vx = (seededRandom(i + 200, 0) - 0.5) * MAP_SIZE * 0.8;
const vz = (seededRandom(i + 200, 1) - 0.5) * MAP_SIZE * 0.8;
vehicles.push({
x: vx, z: vz, type: vTypes[Math.floor(seededRandom(i + 200, 2) * 3)],
health: 200, occupied: false, speed: 0, rotation: seededRandom(i + 200, 3) * Math.PI * 2
});
}

// Pickups
const pickupTypes = ['ar', 'smg', 'sg', 'sniper', 'dmr', 'pistol', 'medkit', 'shield', 'ammo'];
for (let i = 0; i < 80; i++) {
const px = (seededRandom(i + 300, 0) - 0.5) * MAP_SIZE * 0.85;
const pz = (seededRandom(i + 300, 1) - 0.5) * MAP_SIZE * 0.85;
const pt = pickupTypes[Math.floor(seededRandom(i + 300, 2) * pickupTypes.length)];
pickups.push({ x: px, z: pz, type: pt, active: true });
}

// Enemies
const enemyCount = 99;
for (let i = 0; i < enemyCount; i++) {
const ex = (seededRandom(i + 400, 0) - 0.5) * MAP_SIZE * 0.85;
const ez = (seededRandom(i + 400, 1) - 0.5) * MAP_SIZE * 0.85;
const ew = pickupTypes[Math.floor(seededRandom(i + 400, 2) * 5)];
enemies.push({
x: ex, z: ez, y: 0,
vx: 0, vz: 0,
health: 100, shield: Math.floor(seededRandom(i + 400, 3) * 50),
rotation: seededRandom(i + 400, 4) * Math.PI * 2,
weapon: ew,
alive: true,
speed: 0.06 + seededRandom(i + 400, 5) * 0.04,
state: 'wander', // wander, chase, flee, search
targetX: ex + (Math.random() - 0.5) * 200,
targetZ: ez + (Math.random() - 0.5) * 200,
lastShot: 0,
detectionRange: 150 + seededRandom(i + 400, 6) * 100,
aiTimer: 0,
color: `hsl(${Math.floor(seededRandom(i + 400, 7) * 360)}, 60%, 40%)`,
name: 'Bot_' + (i + 1)
});
}

// Player starting position
player.x = (seededRandom(9999, 0) - 0.5) * MAP_SIZE * 0.6;
player.z = (seededRandom(9999, 1) - 0.5) * MAP_SIZE * 0.6;
player.weapons = [
{ ...WEAPONS.pistol, ammo: 15, reserve: 60 },
{ ...WEAPONS.ar, ammo: 30, reserve: 120 }
];
}

function generateBuildingColor() {
const colors = {
city: ['#3a3a4a', '#4a4a5a', '#2a2a3a', '#5a5a6a', '#3d3d4d', '#454555'],
desert: ['#c4a35a', '#b8944a', '#d4b36a', '#a8843a', '#c8a860'],
forest: ['#2a4a2a', '#3a5a3a', '#1a3a1a', '#4a6a4a']
};
const palette = colors[selectedMap];
return palette[Math.floor(Math.random() * palette.length)];
}

// ============ TERRAIN HEIGHT ============
function getTerrainHeight(x, z) {
return 0; // Flat terrain for simplicity
}

// ============ COLLISION ============
function checkBuildingCollision(x, z, radius) {
for (const b of buildings) {
const hw = b.w / 2 + radius;
const hd = b.d / 2 + radius;
if (x > b.x - hw && x < b.x + hw && z > b.z - hd && z < b.z + hd) {
return true;
}
}
return false;
}

function checkTreeCollision(x, z, radius) {
for (const t of trees) {
const dx = x - t.x;
const dz = z - t.z;
const dist = Math.sqrt(dx * dx + dz * dz);
if (dist < t.radius + radius) return true;
}
return false;
}

// ============ 3D RENDERING ============
function project(x, y, z) {
const dx = x - camera.x;
const dy = y - camera.y;
const dz = z - camera.z;

const cosR = Math.cos(-camera.rotation);
const sinR = Math.sin(-camera.rotation);
const cosP = Math.cos(-camera.pitch);
const sinP = Math.sin(-camera.pitch);

let rx = dx * cosR - dz * sinR;
let rz = dx * sinR + dz * cosR;
let ry = dy;

let ry2 = ry * cosP - rz * sinP;
let rz2 = ry * sinP + rz * cosP;

if (rz2 <= 0.1) return null;

const fov = player.scoped ? 30 : player.fov;
const scale = (fov / 2) / Math.tan((fov * Math.PI / 360) * 0.5);
const sx = W / 2 + (rx * scale) / rz2 * W / 2;
const sy = H / 2 - (ry2 * scale) / rz2 * H / 2;

return { x: sx, y: sy, z: rz2, scale: scale / rz2 };
}

function drawSky() {
const skyGrad = ctx.createLinearGradient(0, 0, 0, H * 0.6);
if (selectedMap === 'desert') {
skyGrad.addColorStop(0, '#1a0a2e');
skyGrad.addColorStop(0.3, '#4a2040');
skyGrad.addColorStop(0.6, '#d4804a');
skyGrad.addColorStop(1, '#f0c080');
} else if (selectedMap === 'forest') {
skyGrad.addColorStop(0, '#0a1a2e');
skyGrad.addColorStop(0.4, '#1a3a5e');
skyGrad.addColorStop(0.7, '#4a7a9e');
skyGrad.addColorStop(1, '#8ab0c0');
} else {
skyGrad.addColorStop(0, '#0a0a1e');
skyGrad.addColorStop(0.3, '#1a2a4e');
skyGrad.addColorStop(0.6, '#3a5a8e');
skyGrad.addColorStop(1, '#7a9ab0');
}
ctx.fillStyle = skyGrad;
ctx.fillRect(0, 0, W, H);

// Sun/Moon
const sunAngle = camera.rotation * 0.3;
const sunX = W / 2 + Math.cos(sunAngle) * W * 0.3;
const sunY = H * 0.15 + Math.sin(sunAngle * 0.5) * H * 0.05;
const sunGrad = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, 80);
if (selectedMap === 'desert') {
sunGrad.addColorStop(0, 'rgba(255,200,100,1)');
sunGrad.addColorStop(0.3, 'rgba(255,150,50,0.5)');
sunGrad.addColorStop(1, 'rgba(255,100,0,0)');
} else {
sunGrad.addColorStop(0, 'rgba(255,255,200,1)');
sunGrad.addColorStop(0.3, 'rgba(255,220,150,0.4)');
sunGrad.addColorStop(1, 'rgba(255,200,100,0)');
}
ctx.fillStyle = sunGrad;
ctx.fillRect(sunX - 100, sunY - 100, 200, 200);

// Clouds
ctx.fillStyle = 'rgba(255,255,255,0.08)';
for (let i = 0; i < 8; i++) {
const cx = ((i * 300 + performance.now() * 0.005) % (W + 200)) - 100;
const cy = 50 + i * 30 + Math.sin(i * 2) * 20;
ctx.beginPath();
ctx.ellipse(cx, cy, 100 + i * 20, 20 + i * 5, 0, 0, Math.PI * 2);
ctx.fill();
}
}

function drawGround() {
const groundColors = {
city: '#2a2a2a',
desert: '#c4a35a',
forest: '#2a4a2a'
};

// Draw ground as large quad
const corners = [
project(-WORLD_HALF, 0, -WORLD_HALF),
project(WORLD_HALF, 0, -WORLD_HALF),
project(WORLD_HALF, 0, WORLD_HALF),
project(-WORLD_HALF, 0, WORLD_HALF)
];

if (corners.some(c => !c)) return;

ctx.fillStyle = groundColors[selectedMap];
ctx.beginPath();
ctx.moveTo(corners[0].x, corners[0].y);
for (let i = 1; i < 4; i++) ctx.lineTo(corners[i].x, corners[i].y);
ctx.closePath();
ctx.fill();

// Grid lines on ground
ctx.strokeStyle = 'rgba(255,255,255,0.03)';
ctx.lineWidth = 1;
const gridSize = 50;
for (let gx = -WORLD_HALF; gx <= WORLD_HALF; gx += gridSize) {
const p1 = project(gx, 0, -WORLD_HALF);
const p2 = project(gx, 0, WORLD_HALF);
if (p1 && p2) {
ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
}
}
for (let gz = -WORLD_HALF; gz <= WORLD_HALF; gz += gridSize) {
const p1 = project(-WORLD_HALF, 0, gz);
const p2 = project(WORLD_HALF, 0, gz);
if (p1 && p2) {
ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
}
}
}

function drawBuilding(b) {
const corners = [
{ x: b.x - b.w / 2, z: b.z - b.d / 2 },
{ x: b.x + b.w / 2, z: b.z - b.d / 2 },
{ x: b.x + b.w / 2, z: b.z + b.d / 2 },
{ x: b.x - b.w / 2, z: b.z + b.d / 2 }
];

const bottom = corners.map(c => project(c.x, 0, c.z));
const top = corners.map(c => project(c.x, b.h, c.z));

if (bottom.some(p => !p) || top.some(p => !p)) return;

// Check if building is behind camera
const avgZ = bottom.reduce((s, p) => s + p.z, 0) / 4;
if (avgZ < 0.5) return;

// Draw sides
for (let i = 0; i < 4; i++) {
const next = (i + 1) % 4;
const faceColor = shadeColor(b.color, -20 + i * 10);
ctx.fillStyle = faceColor;
ctx.beginPath();
ctx.moveTo(bottom[i].x, bottom[i].y);
ctx.lineTo(bottom[next].x, bottom[next].y);
ctx.lineTo(top[next].x, top[next].y);
ctx.lineTo(top[i].x, top[i].y);
ctx.closePath();
ctx.fill();

ctx.strokeStyle = 'rgba(0,0,0,0.3)';
ctx.lineWidth = 1;
ctx.stroke();
}

// Top
ctx.fillStyle = shadeColor(b.color, 20);
ctx.beginPath();
ctx.moveTo(top[0].x, top[0].y);
for (let i = 1; i < 4; i++) ctx.lineTo(top[i].x, top[i].y);
ctx.closePath();
ctx.fill();
ctx.strokeStyle = 'rgba(0,0,0,0.2)';
ctx.stroke();

// Windows
if (b.h > 20) {
const windowRows = Math.floor(b.h / 12);
const windowCols = Math.floor(b.w / 10);
for (let row = 0; row < windowRows; row++) {
for (let col = 0; col < windowCols; col++) {
const wx = b.x - b.w / 2 + 5 + col * 10;
const wy = 5 + row * 12;
const wz = b.z - b.d / 2 + 1;
const wp = project(wx, wy, wz);
if (wp && wp.z > 0.5) {
const ws = Math.max(2, 4 * wp.scale);
ctx.fillStyle = Math.random() > 0.3 ? 'rgba(255,220,100,0.6)' : 'rgba(100,150,200,0.3)';
ctx.fillRect(wp.x - ws / 2, wp.y - ws, ws, ws * 1.5);
}
}
}
}
}

function shadeColor(color, amount) {
let r = parseInt(color.slice(1, 3), 16) + amount;
let g = parseInt(color.slice(3, 5), 16) + amount;
let b = parseInt(color.slice(5, 7), 16) + amount;
r = Math.max(0, Math.min(255, r));
g = Math.max(0, Math.min(255, g));
b = Math.max(0, Math.min(255, b));
return `rgb(${r},${g},${b})`;
}

function drawTree(t) {
const base = project(t.x, 0, t.z);
const top = project(t.x, t.height, t.z);
if (!base || !top) return;
if (base.z < 0.5) return;

const s = base.scale;

// Trunk
ctx.fillStyle = '#4a3520';
ctx.fillRect(base.x - 3 * s * 10, base.y - 15 * s * 10, 6 * s * 10, 15 * s * 10);

// Foliage
const foliageColor = selectedMap === 'forest' ? '#1a5a1a' :
selectedMap === 'desert' ? '#6a8a3a' : '#2a6a2a';
ctx.fillStyle = foliageColor;

if (t.type === 'pine') {
ctx.beginPath();
ctx.moveTo(base.x, top.y);
ctx.lineTo(base.x - 15 * s * 10, base.y - 10 * s * 10);
ctx.lineTo(base.x + 15 * s * 10, base.y - 10 * s * 10);
ctx.closePath();
ctx.fill();
} else {
ctx.beginPath();
ctx.arc(base.x, top.y + 5 * s * 10, 12 * s * 10, 0, Math.PI * 2);
ctx.fill();
}
}

function drawVehicle(v) {
const p = project(v.x, 1, v.z);
if (!p || p.z < 0.5) return;

const s = p.scale * 15;
const cos = Math.cos(v.rotation);
const sin = Math.sin(v.rotation);

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(p.x, p.y + 5 * s, s * 2, s * 0.8, 0, 0, Math.PI * 2);
ctx.fill();

// Body
const bodyColor = v.occupied ? '#ff6b00' : '#444';
ctx.fillStyle = bodyColor;

if (v.type === 'car') {
ctx.fillRect(p.x - s * 1.5, p.y - s * 2, s * 3, s * 1.2);
ctx.fillStyle = '#333';
ctx.fillRect(p.x - s * 1, p.y - s * 2.8, s * 2, s * 0.8);
} else if (v.type === 'bike') {
ctx.fillRect(p.x - s * 0.3, p.y - s * 1.5, s * 0.6, s * 1);
} else {
ctx.fillRect(p.x - s * 2, p.y - s * 2.5, s * 4, s * 1.5);
ctx.fillStyle = '#333';
ctx.fillRect(p.x - s * 1.5, p.y - s * 3.5, s * 3, s * 1);
}

// Wheels
ctx.fillStyle = '#111';
const wheelPositions = v.type === 'car' ?
[[-1.2, -0.3], [1.2, -0.3], [-1.2, 0.5], [1.2, 0.5]] :
[[-0.8, -0.3], [0.8, -0.3]];
wheelPositions.forEach(([wx, wz]) => {
const wxp = p.x + wx * s * cos - wz * s * sin;
const wzp = p.x + wx * s * sin + wz * s * cos;
const wpp = project(v.x + (wxp - p.x) / (p.scale * 15), 0, v.z + (wzp - p.x) / (p.scale * 15) * Math.tan(camera.rotation));
if (wpp) ctx.fillRect(wpp.x - 3, wpp.y - 2, 6, 4);
});
}

function drawPickup(p) {
if (!p.active) return;
const proj = project(p.x, 1.5, p.z);
if (!proj || proj.z < 0.5) return;

const s = proj.scale * 15;
const bob = Math.sin(performance.now() * 0.003 + p.x) * 5;

const colors = {
ar: '#ff6b00', smg: '#00b4d8', sg: '#ff4444',
sniper: '#ff9500', dmr: '#cc44ff', pistol: '#aaa',
medkit: '#00ff00', shield: '#0088ff', ammo: '#ffaa00'
};

ctx.fillStyle = colors[p.type] || '#fff';
ctx.shadowColor = colors[p.type] || '#fff';
ctx.shadowBlur = 15;

if (p.type.includes('kit') || p.type === 'shield') {
ctx.fillRect(proj.x - s * 0.5, proj.y - s * 0.5 + bob, s, s);
ctx.fillStyle = '#fff';
ctx.fillRect(proj.x - s * 0.1, proj.y - s * 0.15 + bob, s * 0.2, s * 0.7);
ctx.fillRect(proj.x - s * 0.35, proj.y - s * 0.15 + bob, s * 0.7, s * 0.2);
} else {
ctx.fillRect(proj.x - s * 0.4, proj.y - s * 0.15 + bob, s * 0.8, s * 0.3);
}
ctx.shadowBlur = 0;
}

function drawEnemy(e) {
if (!e.alive) return;
const proj = project(e.x, 2, e.z);
if (!proj || proj.z < 0.5) return;

const s = proj.scale * 15;
const dx = player.x - e.x;
const dz = player.z - e.z;
const dist = Math.sqrt(dx * dx + dz * dz);

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(proj.x, proj.y + 3 * s, s * 0.8, s * 0.3, 0, 0, Math.PI * 2);
ctx.fill();

// Body
ctx.fillStyle = e.color;
ctx.fillRect(proj.x - s * 0.4, proj.y - s * 2, s * 0.8, s * 1.5);

// Head
ctx.fillStyle = '#d4a574';
ctx.beginPath();
ctx.arc(proj.x, proj.y - s * 2.5, s * 0.4, 0, Math.PI * 2);
ctx.fill();

// Weapon
ctx.fillStyle = '#333';
ctx.fillRect(proj.x + s * 0.3, proj.y - s * 1.5, s * 0.8, s * 0.15);

// Health bar
if (dist < 200) {
const barW = s * 1.2;
const barH = 3;
const barX = proj.x - barW / 2;
const barY = proj.y - s * 3.2;
ctx.fillStyle = 'rgba(0,0,0,0.5)';
ctx.fillRect(barX, barY, barW, barH);
ctx.fillStyle = e.health > 50 ? '#00ff00' : e.health > 25 ? '#ffaa00' : '#ff0000';
ctx.fillRect(barX, barY, barW * (e.health / 100), barH);
if (e.shield > 0) {
ctx.fillStyle = '#0088ff';
ctx.fillRect(barX, barY - 4, barW * (e.shield / 100), 2);
}
}
}

function drawBullet(b) {
const proj = project(b.x, b.y, b.z);
if (!proj || proj.z < 0.5) return;
const s = proj.scale * 15;

ctx.fillStyle = '#ff0';
ctx.shadowColor = '#ff0';
ctx.shadowBlur = 10;
ctx.beginPath();
ctx.arc(proj.x, proj.y, Math.max(2, s * 0.3), 0, Math.PI * 2);
ctx.fill();
ctx.shadowBlur = 0;
}

function drawParticle(p) {
const proj = project(p.x, p.y, p.z);
if (!proj || proj.z < 0.5) return;
const s = proj.scale * 15;

ctx.fillStyle = p.color;
ctx.globalAlpha = p.life;
ctx.beginPath();
ctx.arc(proj.x, proj.y, Math.max(1, s * p.size), 0, Math.PI * 2);
ctx.fill();
ctx.globalAlpha = 1;
}

function drawExplosion(exp) {
const proj = project(exp.x, exp.y, exp.z);
if (!proj || proj.z < 0.5) return;
const s = proj.scale * 15;
const radius = exp.radius * exp.progress;

const grad = ctx.createRadialGradient(proj.x, proj.y, 0, proj.x, proj.y, radius * s);
grad.addColorStop(0, 'rgba(255,255,200,0.8)');
grad.addColorStop(0.3, 'rgba(255,150,0,0.6)');
grad.addColorStop(0.6, 'rgba(255,50,0,0.4)');
grad.addColorStop(1, 'rgba(100,0,0,0)');

ctx.fillStyle = grad;
ctx.beginPath();
ctx.arc(proj.x, proj.y, radius * s, 0, Math.PI * 2);
ctx.fill();
}

function drawZone() {
const zoneProj = project(zone.x, 0, zone.y);
if (!zoneProj) return;

// Draw zone circle
const segments = 64;
const zoneRadius = zone.radius;

ctx.strokeStyle = 'rgba(255,50,50,0.6)';
ctx.lineWidth = 3;
ctx.setLineDash([10, 5]);
ctx.beginPath();

for (let i = 0; i <= segments; i++) {
const angle = (i / segments) * Math.PI * 2;
const zx = zone.x + Math.cos(angle) * zoneRadius;
const zz = zone.y + Math.sin(angle) * zoneRadius;
const p = project(zx, 0, zz);
if (p) {
if (i === 0) ctx.moveTo(p.x, p.y);
else ctx.lineTo(p.x, p.y);
}
}
ctx.closePath();
ctx.stroke();
ctx.setLineDash([]);

// Zone damage area (outside)
ctx.fillStyle = 'rgba(255,0,0,0.08)';
ctx.beginPath();
for (let i = 0; i <= segments; i++) {
const angle = (i / segments) * Math.PI * 2;
const zx = zone.x + Math.cos(angle) * zoneRadius;
const zz = zone.y + Math.sin(angle) * zoneRadius;
const p = project(zx, 0, zz);
if (p) {
if (i === 0) ctx.moveTo(p.x, p.y);
else ctx.lineTo(p.x, p.y);
}
}
ctx.closePath();
ctx.fill();
}

// ============ PLAYER RENDERING ============
function drawPlayerWeapon() {
const weapon = player.weapons[player.currentWeapon];
if (!weapon) return;

const recoil = player.reloading ? Math.sin(player.reloadTimer / weapon.reloadTime * Math.PI) * 20 : 0;
const sway = Math.sin(performance.now() * 0.002) * 2;

const wx = W * 0.65 + sway;
const wy = H * 0.75 + recoil;

ctx.save();
ctx.translate(wx, wy);

// Gun body
ctx.fillStyle = '#333';
ctx.fillRect(0, -8, 80, 16);
ctx.fillStyle = '#444';
ctx.fillRect(10, -12, 40, 6);

// Barrel
ctx.fillStyle = '#222';
ctx.fillRect(60, -6, 30, 12);

// Magazine
ctx.fillStyle = '#2a2a2a';
ctx.fillRect(25, 8, 12, 20);

// Grip
ctx.fillStyle = '#3a3a3a';
ctx.fillRect(15, 8, 10, 25);

// Muzzle flash
if (Date.now() - player.lastShot < 50 && !player.reloading) {
ctx.fillStyle = '#ffaa00';
ctx.shadowColor = '#ff6600';
ctx.shadowBlur = 30;
ctx.beginPath();
ctx.arc(95, 0, 15 + Math.random() * 10, 0, Math.PI * 2);
ctx.fill();
ctx.shadowBlur = 0;
}

ctx.restore();
}

// ============ MINIMAP ============
function drawMinimap() {
const mc = document.getElementById('minimap-canvas');
const mctx = mc.getContext('2d');
mctx.clearRect(0, 0, 180, 180);

const scale = 180 / MAP_SIZE;
const cx = 90;
const cy = 90;

// Background
mctx.fillStyle = selectedMap === 'desert' ? '#3a3020' :
selectedMap === 'forest' ? '#1a2a1a' : '#1a1a2a';
mctx.fillRect(0, 0, 180, 180);

// Buildings
mctx.fillStyle = 'rgba(100,100,120,0.6)';
buildings.forEach(b => {
const bx = cx + b.x * scale;
const bz = cy + b.z * scale;
const bw = b.w * scale;
const bd = b.d * scale;
if (bx > -10 && bx < 190 && bz > -10 && bz < 190) {
mctx.fillRect(bx - bw / 2, bz - bd / 2, bw, bd);
}
});

// Zone
mctx.strokeStyle = 'rgba(255,50,50,0.8)';
mctx.lineWidth = 2;
mctx.beginPath();
const zr = zone.radius * scale;
mctx.arc(cx, cy, zr, 0, Math.PI * 2);
mctx.stroke();

// Enemies (red dots)
mctx.fillStyle = '#ff4444';
enemies.forEach(e => {
if (!e.alive) return;
const dx = e.x - player.x;
const dz = e.z - player.z;
const dist = Math.sqrt(dx * dx + dz * dz);
if (dist < 150) {
const ex = cx + e.x * scale;
const ez = cy + e.z * scale;
mctx.beginPath();
mctx.arc(ex, ez, 2, 0, Math.PI * 2);
mctx.fill();
}
});

// Vehicles
mctx.fillStyle = '#ffaa00';
vehicles.forEach(v => {
const vx = cx + v.x * scale;
const vz = cy + v.z * scale;
if (vx > 0 && vx < 180 && vz > 0 && vz < 180) {
mctx.fillRect(vx - 2, vz - 2, 4, 4);
}
});

// Player (center)
mctx.fillStyle = '#00ff00';
mctx.beginPath();
mctx.arc(cx, cy, 4, 0, Math.PI * 2);
mctx.fill();

// Player direction
mctx.strokeStyle = '#00ff00';
mctx.lineWidth = 2;
mctx.beginPath();
mctx.moveTo(cx, cy);
mctx.lineTo(cx + Math.sin(player.rotation) * -12, cy + Math.cos(player.rotation) * -12);
mctx.stroke();

// Border
mctx.strokeStyle = 'rgba(255,255,255,0.2)';
mctx.lineWidth = 2;
mctx.beginPath();
mctx.arc(90, 90, 88, 0, Math.PI * 2);
mctx.stroke();
}

// ============ SHOOTING ============
function shoot() {
const weapon = player.weapons[player.currentWeapon];
if (!weapon || player.reloading) return;
if (weapon.ammo <= 0) {
reload();
return;
}
if (Date.now() - player.lastShot < weapon.fireRate) return;

player.lastShot = Date.now();
weapon.ammo--;

const pellets = weapon.pellets || 1;
for (let p = 0; p < pellets; p++) {
const spreadX = (Math.random() - 0.5) * weapon.spread;
const spreadY = (Math.random() - 0.5) * weapon.spread;

const bullet = {
x: player.x,
y: player.z,
z: 2,
vx: Math.sin(player.rotation + spreadX) * 2,
vy: spreadY,
vz: Math.cos(player.rotation + spreadX) * 2,
damage: weapon.damage,
range: weapon.range,
distance: 0,
owner: 'player'
};
bullets.push(bullet);

// Muzzle particles
for (let i = 0; i < 5; i++) {
particles.push({
x: player.x + Math.sin(player.rotation) * 2,
y: 2 + Math.random() * 0.5,
z: player.z + Math.cos(player.rotation) * 2,
vx: Math.sin(player.rotation) * 0.3 + (Math.random() - 0.5) * 0.2,
vy: (Math.random() - 0.5) * 0.1,
vz: Math.cos(player.rotation) * 0.3 + (Math.random() - 0.5) * 0.2,
life: 1,
decay: 0.05 + Math.random() * 0.05,
size: 2 + Math.random() * 3,
color: '#ffaa00'
});
}
}

// Update ammo display
document.getElementById('current-ammo').textContent = weapon.ammo;
document.getElementById('weapon-name').textContent = weapon.name;

if (weapon.ammo === 0) reload();
}

function reload() {
const weapon = player.weapons[player.currentWeapon];
if (!weapon || player.reloading) return;
if (weapon.reserve <= 0) return;

player.reloading = true;
player.reloadTimer = 0;

setTimeout(() => {
const needed = weapon.maxAmmo - weapon.ammo;
const available = Math.min(needed, weapon.reserve);
weapon.ammo += available;
weapon.reserve -= available;
player.reloading = false;
document.getElementById('current-ammo').textContent = weapon.ammo;
document.getElementById('reserve-ammo').textContent = '/ ' + weapon.reserve;
}, weapon.reloadTime);
}

function bulletHitCheck(bullet) {
// Check enemy hits
for (const e of enemies) {
if (!e.alive) continue;
const dx = bullet.x - e.x;
const dz = bullet.z - e.z;
const dist = Math.sqrt(dx * dx + dz * dz);

if (dist < 2) {
const dmg = bullet.damage * (1 - dist / 5);
if (e.shield > 0) {
const shieldDmg = Math.min(e.shield, dmg);
e.shield -= shieldDmg;
e.health -= (dmg - shieldDmg);
} else {
e.health -= dmg;
}

// Hit marker
showHitMarker();

// Hit particles
for (let i = 0; i < 8; i++) {
particles.push({
x: e.x, y: 2, z: e.z,
vx: (Math.random() - 0.5) * 0.3,
vy: Math.random() * 0.2,
vz: (Math.random() - 0.5) * 0.3,
life: 1, decay: 0.03,
size: 2 + Math.random() * 2,
color: '#ff0000'
});
}

if (e.health <= 0) {
e.alive = false;
player.kills++;
addKillFeed('You', e.name);
updateAliveCount();

// Drop pickup
const dropTypes = ['ar', 'smg', 'sg', 'sniper', 'dmr', 'medkit', 'shield', 'ammo'];
const dropType = dropTypes[Math.floor(Math.random() * dropTypes.length)];
pickups.push({ x: e.x, z: e.z, type: dropType, active: true });
}

return true;
}
}

// Check building collision
for (const b of buildings) {
if (bullet.x > b.x - b.w / 2 && bullet.x < b.x + b.w / 2 &&
bullet.z > b.z - b.d / 2 && bullet.z < b.z + b.d / 2 &&
bullet.y > 0 && bullet.y < b.h) {
// Impact particles
for (let i = 0; i < 5; i++) {
particles.push({
x: bullet.x, y: bullet.y, z: bullet.z,
vx: (Math.random() - 0.5) * 0.2,
vy: Math.random() * 0.1,
vz: (Math.random() - 0.5) * 0.2,
life: 1, decay: 0.04,
size: 1 + Math.random() * 2,
color: '#aaa'
});
}
return true;
}
}

return false;
}

function showHitMarker() {
const hm = document.getElementById('hit-marker');
hm.style.display = 'block';
setTimeout(() => hm.style.display = 'none', 100);
}

function addKillFeed(killer, victim) {
const feed = document.getElementById('kill-feed');
const msg = document.createElement('div');
msg.className = 'kill-msg';
msg.textContent = `${killer} eliminated ${victim}`;
feed.appendChild(msg);
setTimeout(() => msg.remove(), 4000);
}

function updateAliveCount() {
const alive = enemies.filter(e => e.alive).length + (player.alive ? 1 : 0);
document.getElementById('alive-num').textContent = alive;
if (alive <= 1) {
gameOver(player.alive);
}
}

function gameOver(won) {
player.alive = false;
gameRunning = false;
const go = document.getElementById('game-over');
go.style.display = 'flex';
document.getElementById('go-title').textContent = won ? '🏆 BOOYAH!' : 'GAME OVER';
document.getElementById('go-title').style.color = won ? '#ff6b00' : '#ff4444';
document.getElementById('go-stats').innerHTML =
`Rank: <span>#${enemies.filter(e => e.alive).length + 1}</span><br>` +
`Kills: <span>${player.kills}</span><br>` +
`Damage Dealt: <span>${Math.floor(player.kills * 25 + Math.random() * 100)}</span>`;
}

// ============ AI UPDATE ============
function updateEnemies() {
enemies.forEach(e => {
if (!e.alive) return;

const dx = player.x - e.x;
const dz = player.z - e.z;
const distToPlayer = Math.sqrt(dx * dx + dz * dz);

// Zone damage
const distToZone = Math.sqrt((e.x - zone.x) ** 2 + (e.z - zone.y) ** 2);
if (distToZone > zone.radius) {
e.health -= zone.damage * 0.01;
if (e.health <= 0) {
e.alive = false;
addKillFeed('Zone', e.name);
updateAliveCount();
}
}

// AI state machine
e.aiTimer++;

if (distToPlayer < e.detectionRange && player.alive) {
e.state = 'chase';
} else if (e.aiTimer % 200 === 0) {
e.state = 'wander';
e.targetX = e.x + (Math.random() - 0.5) * 300;
e.targetZ = e.z + (Math.random() - 0.5) * 300;
}

// Flee from nearby explosions
explosions.forEach(exp => {
const expDist = Math.sqrt((e.x - exp.x) ** 2 + (e.z - exp.z) ** 2);
if (expDist < 50) {
e.state = 'flee';
e.targetX = e.x + (e.x - exp.x) * 2;
e.targetZ = e.z + (e.z - exp.z) * 2;
}
});

// Movement
let targetX, targetZ;
if (e.state === 'chase') {
targetX = player.x;
targetZ = player.z;
e.rotation = Math.atan2(dx, dz);

// Shoot at player
if (distToPlayer < 150 && e.alive) {
const weapon = WEAPONS[e.weapon] || WEAPONS.ar;
if (Date.now() - e.lastShot > weapon.fireRate * 2) {
e.lastShot = Date.now();
const spread = (Math.random() - 0.5) * 0.1;
bullets.push({
x: e.x, y: 2, z: e.z,
vx: Math.sin(e.rotation + spread) * 1.5,
vy: spread,
vz: Math.cos(e.rotation + spread) * 1.5,
damage: weapon.damage * 0.5,
range: weapon.range * 0.7,
distance: 0,
owner: 'enemy',
enemyRef: e
});
}
}
} else if (e.state === 'flee') {
targetX = e.targetX;
targetZ = e.targetZ;
e.rotation = Math.atan2(targetX - e.x, targetZ - e.z);
} else {
targetX = e.targetX;
targetZ = e.targetZ;
e.rotation = Math.atan2(targetX - e.x, targetZ - e.z);
}

const moveX = targetX - e.x;
const moveZ = targetZ - e.z;
const moveDist = Math.sqrt(moveX * moveX + moveZ * moveZ);

if (moveDist > 2) {
const speed = e.state === 'flee' ? e.speed * 1.5 : e.speed;
const nx = e.x + (moveX / moveDist) * speed;
const nz = e.z + (moveZ / moveDist) * speed;

if (!checkBuildingCollision(nx, nz, 1) && !checkTreeCollision(nx, nz, 1)) {
e.x = nx;
e.z = nz;
}
}

// Keep in bounds
e.x = Math.max(-WORLD_HALF + 10, Math.min(WORLD_HALF - 10, e.x));
e.z = Math.max(-WORLD_HALF + 10, Math.min(WORLD_HALF - 10, e.z));
});
}

function updateBullets() {
for (let i = bullets.length - 1; i >= 0; i--) {
const b = bullets[i];
b.x += b.vx;
b.y += b.vz;
b.z += b.vy;
b.distance += Math.sqrt(b.vx * b.vx + b.vz * b.vz);

if (b.distance > b.range || b.y < 0 || b.y > 100) {
bullets.splice(i, 1);
continue;
}

if (bulletHitCheck(b)) {
bullets.splice(i, 1);
continue;
}

// Player hit by enemy bullet
if (b.owner === 'enemy' && player.alive) {
const dx = b.x - player.x;
const dz = b.z - player.z;
const dist = Math.sqrt(dx * dx + dz * dz);
if (dist < 1.5) {
let dmg = b.damage;
if (player.shield > 0) {
const shieldDmg = Math.min(player.shield, dmg);
player.shield -= shieldDmg;
player.health -= (dmg - shieldDmg);
} else {
player.health -= dmg;
}
document.getElementById('damage-overlay').style.border = '8px solid rgba(255,0,0,0.5)';
setTimeout(() => document.getElementById('damage-overlay').style.border = '0px solid rgba(255,0,0,0)', 200);

if (player.health <= 0) {
player.health = 0;
gameOver(false);
}
bullets.splice(i, 1);
}
}
}
}

function updateParticles() {
for (let i = particles.length - 1; i >= 0; i--) {
const p = particles[i];
p.x += p.vx;
p.y += p.vy;
p.z += p.vz;
p.vy -= 0.005;
p.life -= p.decay;
if (p.life <= 0) particles.splice(i, 1);
}
}

function updateExplosions() {
for (let i = explosions.length - 1; i >= 0; i--) {
const exp = explosions[i];
exp.progress += 0.03;
if (exp.progress >= 1) {
explosions.splice(i, 1);
}
}
}

// ============ ZONE UPDATE ============
function updateZone() {
zone.shrinkTimer -= 1 / 60;

if (zone.shrinkTimer <= 0) {
zone.currentPhase++;
zone.targetRadius = Math.max(50, zone.radius * 0.6);
zone.shrinkTimer = 25 + zone.currentPhase * 10;

// Move zone center slightly
zone.x += (Math.random() - 0.5) * 200;
zone.y += (Math.random() - 0.5) * 200;
zone.x = Math.max(-WORLD_HALF + zone.targetRadius, Math.min(WORLD_HALF - zone.targetRadius, zone.x));
zone.y = Math.max(-WORLD_HALF + zone.targetRadius, Math.min(WORLD_HALF - zone.targetRadius, zone.y));
}

if (zone.radius > zone.targetRadius) {
zone.radius -= 0.05;
zone.damage = zone.currentPhase * 2;
}

// Zone timer display
const timerSec = Math.max(0, Math.ceil(zone.shrinkTimer));
const timerMin = Math.floor(timerSec / 60);
const timerS = timerSec % 60;
document.getElementById('zone-timer').textContent =
zone.radius > zone.targetRadius ?
`ZONE SHRINKING!` :
`ZONE SHRINKING IN ${timerMin}:${timerS.toString().padStart(2, '0')}`;

// Player zone damage
const distToZone = Math.sqrt((player.x - zone.x) ** 2 + (player.z - zone.y) ** 2);
if (distToZone > zone.radius && player.alive) {
player.health -= zone.damage * 0.02;
if (player.health <= 0) {
player.health = 0;
gameOver(false);
}
}
}

// ============ VEHICLE UPDATE ============
function updateVehicle() {
if (player.inVehicle) {
const v = player.inVehicle;
v.speed *= 0.98;

if (keys['w'] || keys['arrowup']) v.speed = Math.min(v.speed + 0.02, 0.4);
if (keys['s'] || keys['arrowdown']) v.speed = Math.max(v.speed - 0.01, -0.15);
if (keys['a'] || keys['arrowleft']) v.rotation -= 0.03 * Math.abs(v.speed);
if (keys['d'] || keys['arrowright']) v.rotation += 0.03 * Math.abs(v.speed);

v.x += Math.sin(v.rotation) * v.speed;
v.z += Math.cos(v.rotation) * v.speed;
v.x = Math.max(-WORLD_HALF, Math.min(WORLD_HALF, v.x));
v.z = Math.max(-WORLD_HALF, Math.min(WORLD_HALF, v.z));

player.x = v.x;
player.z = v.z;
player.rotation = v.rotation;

document.getElementById('vehicle-hud').style.display = 'block';
document.getElementById('vehicle-speed').textContent = Math.floor(Math.abs(v.speed) * 300);
} else {
document.getElementById('vehicle-hud').style.display = 'none';
}
}

function enterVehicle() {
if (player.inVehicle) {
player.inVehicle.occupied = false;
player.inVehicle = null;
return;
}

let closest = null;
let closestDist = 10;
vehicles.forEach(v => {
const dx = v.x - player.x;
const dz = v.z - player.z;
const dist = Math.sqrt(dx * dx + dz * dz);
if (dist < closestDist) {
closest = v;
closestDist = dist;
}
});

if (closest) {
player.inVehicle = closest;
closest.occupied = true;
}
}

// ============ PICKUP UPDATE ============
function updatePickups() {
nearbyPickup = null;
pickups.forEach(p => {
if (!p.active) return;
const dx = p.x - player.x;
const dz = p.z - player.z;
const dist = Math.sqrt(dx * dx + dz * dz);

if (dist < 5) {
nearbyPickup = p;
}
});

const prompt = document.getElementById('pickup-prompt');
if (nearbyPickup) {
prompt.style.display = 'block';
prompt.textContent = `Press [E] to pickup ${nearbyPickup.type.toUpperCase()}`;
} else {
prompt.style.display = 'none';
}
}

function pickupItem() {
if (!nearbyPickup) return;
const p = nearbyPickup;

if (['ar', 'smg', 'sg', 'sniper', 'dmr', 'pistol'].includes(p.type)) {
const wpn = { ...WEAPONS[p.type], ammo: WEAPONS[p.type].maxAmmo, reserve: WEAPONS[p.type].reserve };
if (player.weapons.length < 3) {
player.weapons.push(wpn);
} else {
player.weapons[player.currentWeapon] = wpn;
}
document.getElementById('weapon-name').textContent = wpn.name;
document.getElementById('current-ammo').textContent = wpn.ammo;
document.getElementById('reserve-ammo').textContent = '/ ' + wpn.reserve;
} else if (p.type === 'medkit') {
player.health = Math.min(100, player.health + 50);
} else if (p.type === 'shield') {
player.shield = Math.min(100, player.shield + 50);
} else if (p.type === 'ammo') {
player.weapons.forEach(w => { w.reserve += w.reserve; });
}

p.active = false;
}

// ============ INPUT ============
document.addEventListener('keydown', e => {
keys[e.key.toLowerCase()] = true;

if (e.key === 'e' || e.key === 'E') {
if (player.inVehicle) enterVehicle();
else pickupItem();
}

if (e.key === 'r' || e.key === 'R') reload();

if (e.key === '1') { player.currentWeapon = 0; updateWeaponUI(); }
if (e.key === '2') { player.currentWeapon = 1; updateWeaponUI(); }
if (e.key === '3') { player.currentWeapon = 2; updateWeaponUI(); }

if ((e.key === 'q' || e.key === 'Q') && player.weapons.length > 1) {
player.currentWeapon = (player.currentWeapon + 1) % player.weapons.length;
updateWeaponUI();
}
});

document.addEventListener('keyup', e => {
keys[e.key.toLowerCase()] = false;
});

document.addEventListener('mousedown', e => {
mouseDown = true;
});

document.addEventListener('mouseup', e => {
mouseDown = false;
});

document.addEventListener('mousemove', e => {
if (!gameRunning) return;
mouseX = e.clientX;
mouseY = e.clientY;

const dx = e.movementX || 0;
const dy = e.movementY || 0;

player.rotation -= dx * 0.002;
player.pitch = Math.max(-0.5, Math.min(0.5, player.pitch - dy * 0.002));

camera.rotation = player.rotation;
camera.pitch = player.pitch;
});

document.addEventListener('wheel', e => {
if (!gameRunning) return;
if (e.deltaY > 0) {
player.fov = Math.min(90, player.fov + 5);
} else {
player.fov = Math.max(30, player.fov - 5);
}
player.scoped = player.fov < 45;
document.getElementById('scope-overlay').style.display = player.scoped ? 'block' : 'none';
});

function updateWeaponUI() {
const weapon = player.weapons[player.currentWeapon];
if (!weapon) return;
document.getElementById('weapon-name').textContent = weapon.name;
document.getElementById('current-ammo').textContent = weapon.ammo;
document.getElementById('reserve-ammo').textContent = '/ ' + weapon.reserve;

for (let i = 1; i <= 3; i++) {
const slot = document.getElementById('slot-' + i);
slot.classList.toggle('active', i - 1 === player.currentWeapon);
}
}

// ============ PLAYER UPDATE ============
function updatePlayer() {
if (!player.alive) return;

if (player.inVehicle) {
updateVehicle();
return;
}

const speed = player.speed;
let moveX = 0, moveZ = 0;

if (keys['w'] || keys['arrowup']) {
moveX += Math.sin(player.rotation) * speed;
moveZ += Math.cos(player.rotation) * speed;
}
if (keys['s'] || keys['arrowdown']) {
moveX -= Math.sin(player.rotation) * speed;
moveZ -= Math.cos(player.rotation) * speed;
}
if (keys['a'] || keys['arrowleft']) {
moveX += Math.sin(player.rotation - Math.PI / 2) * speed;
moveZ += Math.cos(player.rotation - Math.PI / 2) * speed;
}
if (keys['d'] || keys['arrowright']) {
moveX += Math.sin(player.rotation + Math.PI / 2) * speed;
moveZ += Math.cos(player.rotation + Math.PI / 2) * speed;
}

// Sprint
if (keys['shift']) {
moveX *= 1.6;
moveZ *= 1.6;
}

const newX = player.x + moveX;
const newZ = player.z + moveZ;

if (!checkBuildingCollision(newX, player.z, 1) && !checkTreeCollision(newX, player.z, 1)) {
player.x = newX;
}
if (!checkBuildingCollision(player.x, newZ, 1) && !checkTreeCollision(player.x, newZ, 1)) {
player.z = newZ;
}

// Bounds
player.x = Math.max(-WORLD_HALF + 5, Math.min(WORLD_HALF - 5, player.x));
player.z = Math.max(-WORLD_HALF + 5, Math.min(WORLD_HALF - 5, player.z));

// Camera follow
camera.x = player.x - Math.sin(player.rotation) * 8;
