<script>
// ============================================================
// BR ROYALE - Complete Battle Royale Game
// ============================================================

const WORLD_W = 8000, WORLD_H = 8000;
const TILE = 40;
const CANVAS = document.getElementById('game');
const CTX = CANVAS.getContext('2d');
const WEATHER_CANVAS = document.getElementById('weather-canvas');
const WCTX = WEATHER_CANVAS.getContext('2d');
const MINIMAP_CANVAS = document.getElementById('minimap-canvas');
const MCTX = MINIMAP_CANVAS.getContext('2d');

let W, H;
function resize() {
  W = CANVAS.width = window.innerWidth;
  H = CANVAS.height = window.innerHeight;
  WEATHER_CANVAS.width = W; WEATHER_CANVAS.height = H;
}
resize();
window.addEventListener('resize', resize);

// ============================================================
// GAME STATE
// ============================================================
let gameRunning = false;
let gameTime = 0;
let camera = { x: 0, y: 0, zoom: 1 };
let keys = {};
let mouse = { x: W/2, y: H/2, down: false, worldX: 0, worldY: 0 };
let entities = [];
let bullets = [];
let particles = [];
let lootItems = [];
let vehicles = [];
let buildings = [];
let trees = [];
let zone = {
  phase: 0,
  targetX: WORLD_W/2, targetY: WORLD_H/2,
  targetRadius: WORLD_W * 0.4,
  currentX: WORLD_W/2, currentY: WORLD_H/2,
  currentRadius: WORLD_W * 0.5,
  shrinkTimer: 0,
  shrinkDuration: 30,
  damage: 0.4,
  phases: [
    { radius: WORLD_W*0.5, duration: 60, damage: 0.4 },
    { radius: WORLD_W*0.35, duration: 45, damage: 1.0 },
    { radius: WORLD_W*0.22, duration: 40, damage: 2.0 },
    { radius: WORLD_W*0.14, duration: 35, damage: 4.0 },
    { radius: WORLD_W*0.08, duration: 30, damage: 6.0 },
    { radius: WORLD_W*0.05, duration: 25, damage: 8.0 },
    { radius: WORLD_W*0.03, duration: 20, damage: 12.0 },
    { radius: WORLD_W*0.015, duration: 15, damage: 16.0 },
    { radius: WORLD_W*0.005, duration: 10, damage: 20.0 },
  ]
};
let weather = { type: 'clear', timer: 0, intensity: 0, raindrops: [], fogDensity: 0 };
let killFeed = [];
let totalKills = 0;
let playerStats = { kills: 0, damageDealt: 0, timeAlive: 0 };
let redZone = { active: false, timer: 0, bombs: [], duration: 15, cooldown: 45 };

// ============================================================
// WEAPON DEFINITIONS
// ============================================================
const WEAPONS = {
  pistol: { name:'P1911', type:'pistol', damage:15, fireRate:300, magSize:7, reloadTime:1500, range:400, spread:0.04, bulletSpeed:25, auto:false, recoil:[0.03,0.02], sound:'pistol' },
  smg: { name:'UMP45', type:'smg', damage:12, fireRate:75, magSize:30, reloadTime:2200, range:350, spread:0.06, bulletSpeed:22, auto:true, recoil:[0.02,0.015], sound:'smg' },
  ar: { name:'M416', type:'ar', damage:18, fireRate:85, magSize:30, reloadTime:2500, range:600, spread:0.035, bulletSpeed:30, auto:true, recoil:[0.025,0.02], sound:'ar' },
  dmr: { name:'SKS', type:'dmr', damage:35, fireRate:300, magSize:10, reloadTime:2800, range:800, spread:0.015, bulletSpeed:40, auto:false, recoil:[0.06,0.04], sound:'dmr' },
  sniper: { name:'AWM', type:'sniper', damage:80, fireRate:1500, magSize:5, reloadTime:3500, range:1200, spread:0.005, bulletSpeed:50, auto:false, recoil:[0.12,0.08], sound:'sniper' },
  shotgun: { name:'S686', type:'shotgun', damage:14, fireRate:800, magSize:2, reloadTime:2500, range:150, spread:0.15, bulletSpeed:20, pellets:8, auto:false, recoil:[0.08,0.06], sound:'shotgun' },
  lmg: { name:'M249', type:'lmg', damage:16, fireRate:60, magSize:100, reloadTime:4000, range:500, spread:0.05, bulletSpeed:28, auto:true, recoil:[0.03,0.025], sound:'lmg' },
  melee: { name:'Sickle', type:'melee', damage:25, fireRate:600, magSize:999, reloadTime:0, range:60, spread:0, bulletSpeed:0, auto:false, recoil:[0,0], sound:'melee' },
};

const ARMOR = [
  { name:'Level 1 Vest', reduction:0.3, maxHp:100 },
  { name:'Level 2 Vest', reduction:0.4, maxHp:150 },
  { name:'Level 3 Vest', reduction:0.55, maxHp:200 },
];
const HELMETS = [
  { name:'Level 1 Helmet', reduction:0.3 },
  { name:'Level 2 Helmet', reduction:0.4 },
  { name:'Level 3 Helmet', reduction:0.55 },
];

const BIOMES = {
  urban: { color:'#4a4a5a', ground:'#3a3a4a', buildingDensity:0.15, treeDensity:0.02 },
  forest: { color:'#2a4a1a', ground:'#1a3a0a', buildingDensity:0.02, treeDensity:0.2 },
  desert: { color:'#c4a44a', ground:'#b4943a', buildingDensity:0.05, treeDensity:0.01 },
  coastal: { color:'#5a8a9a', ground:'#4a7a8a', buildingDensity:0.08, treeDensity:0.05 },
  mountains: { color:'#6a6a6a', ground:'#5a5a5a', buildingDensity:0.03, treeDensity:0.08 },
};

// ============================================================
// AUDIO SYSTEM (Web Audio API)
// ============================================================
let audioCtx;
function initAudio() {
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
}

function playSound(type, x, y, vol=0.3) {
  if (!audioCtx) return;
  const dx = x - camera.x + W/2;
  const dy = y - camera.y + H/2;
  const dist = Math.sqrt(dx*dx + dy*dy);
  const distVol = Math.max(0, 1 - dist / 1500) * vol;
  if (distVol < 0.01) return;

  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const panner = audioCtx.createStereoPanner();

  panner.pan = Math.max(-1, Math.min(1, dx / 800));
  gain.gain.value = distVol;

  switch(type) {
    case 'pistol':
      osc.type = 'sawtooth'; osc.frequency.value = 200;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
      break;
    case 'smg':
      osc.type = 'square'; osc.frequency.value = 300;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.08);
      break;
    case 'ar':
      osc.type = 'sawtooth'; osc.frequency.value = 150;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.12);
      break;
    case 'sniper':
      osc.type = 'sawtooth'; osc.frequency.value = 100;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.3);
      break;
    case 'shotgun':
      osc.type = 'sawtooth'; osc.frequency.value = 80;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.2);
      break;
    case 'dmr':
      osc.type = 'sawtooth'; osc.frequency.value = 180;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.15);
      break;
    case 'lmg':
      osc.type = 'square'; osc.frequency.value = 250;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.15);
      break;
    case 'hit':
      osc.type = 'sine'; osc.frequency.value = 800;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.05);
      break;
    case 'pickup':
      osc.type = 'sine'; osc.frequency.value = 600;
      osc.frequency.exponentialRampToValueAtTime(900, audioCtx.currentTime + 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.15);
      break;
    case 'explosion':
      osc.type = 'sawtooth'; osc.frequency.value = 50;
      osc.frequency.exponentialRampToValueAtTime(10, audioCtx.currentTime + 0.5);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.5);
      break;
    case 'reload':
      osc.type = 'sine'; osc.frequency.value = 400;
      osc.frequency.value = 500;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.2);
      break;
    case 'melee':
      osc.type = 'sine'; osc.frequency.value = 300;
      osc.frequency.exponentialRampToValueAtTime(100, audioCtx.currentTime + 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
      break;
    default:
      osc.type = 'sine'; osc.frequency.value = 440;
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
  }

  osc.connect(panner);
  panner.connect(gain);
  gain.connect(audioCtx.destination);
  osc.start();
  osc.stop(audioCtx.currentTime + 0.5);
}

// ============================================================
// ENTITY SYSTEM
// ============================================================
class Entity {
  constructor(x, y, radius) {
    this.x = x; this.y = y;
    this.radius = radius;
    this.vx = 0; this.vy = 0;
    this.angle = 0;
    this.hp = 100; this.maxHp = 100;
    this.boost = 0; this.maxBoost = 100;
    this.speed = 3;
    this.sprintSpeed = 5;
    this.crouching = false;
    this.prone = false;
    this.alive = true;
    this.inVehicle = null;
    this.weapons = [];
    this.currentWeapon = 0;
    this.armor = null;
    this.helmet = null;
    this.backpack = 0;
    this.inventory = [];
    this.ammo = {};
    this.lastShot = 0;
    this.reloading = false;
    this.reloadStart = 0;
    this.kills = 0;
    this.name = '';
    this.isPlayer = false;
    this.isBot = false;
    this.stance = 'standing';
    this.bleedTimer = 0;
    this.dbno = false;
    this.lastDamage = 0;
    this.hitFlash = 0;
    this.grenadeCooldown = 0;
    this.smokeCooldown = 0;
    this.lastGrenadeTime = 0;
    this.lastSmokeTime = 0;
  }

  getWeapon() {
    if (this.currentWeapon < this.weapons.length) return this.weapons[this.currentWeapon];
    return WEAPONS.melee;
  }

  getAmmoType() {
    const w = this.getWeapon();
    if (w.type === 'sniper') return '556mm';
    if (w.type === 'dmr') return '762mm';
    if (w.type === 'shotgun') return '12ga';
    if (w.type === 'pistol') return '9mm';
    return '556mm';
  }

  takeDamage(amount, source, hitZone='body') {
    if (!this.alive) return;
    let multiplier = 1;
    if (hitZone === 'head') multiplier = 2.5;
    else if (hitZone === 'limb') multiplier = 0.75;

    let actualDamage = amount * multiplier;

    if (this.armor) actualDamage *= (1 - this.armor.reduction);
    if (this.helmet && hitZone === 'head') actualDamage *= (1 - this.helmet.reduction * 0.5);

    this.hp -= actualDamage;
    if (source && source.isPlayer) {
      source.lastDamage = actualDamage;
      source.lastDamageTime = Date.now();
    }

    if (this.isPlayer) {
      this.hitFlash = 10;
      showDamageIndicator(Math.round(actualDamage));
    }

    if (this.hp <= 0) {
      if (!this.dbno) {
        this.dbno = true;
        this.bleedTimer = 90;
        this.hp = 0;
        if (source) {
          source.kills++;
          totalKills++;
          addKillFeed(source.name, this.name);
        }
      } else {
        this.alive = false;
        this.dbno = false;
        if (source && source.isPlayer) {
          playerStats.kills++;
          playerStats.damageDealt += amount;
        }
        spawnLootDeath(this);
      }
    }
  }

  update(dt) {
    if (!this.alive) return;

    if (this.inVehicle) {
      this.x = this.inVehicle.x;
      this.y = this.inVehicle.y;
      return;
    }

    // Boost regen
    if (this.boost > 0 && this.hp < this.maxHp) {
      this.boost -= dt * 2;
      this.hp = Math.min(this.maxHp, this.hp + dt * 1.5);
    }

    // Reload
    if (this.reloading) {
      const w = this.getWeapon();
      if (Date.now() - this.reloadStart >= w.reloadTime) {
        this.reloading = false;
      }
    }

    // Grenade cooldown
    if (this.grenadeCooldown > 0) this.grenadeCooldown -= dt;
    if (this.smokeCooldown > 0) this.smokeCooldown -= dt;

    // Bleed
    if (this.dbno) {
      this.bleedTimer -= dt;
      if (this.bleedTimer <= 0) {
        this.alive = false;
        spawnLootDeath(this);
      }
    }

    if (this.hitFlash > 0) this.hitFlash--;

    // Physics
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vx *= 0.85;
    this.vy *= 0.85;

    // World bounds
    this.x = Math.max(this.radius, Math.min(WORLD_W - this.radius, this.x));
    this.y = Math.max(this.radius, Math.min(WORLD_H - this.radius, this.y));

    // Building collision
    for (const b of buildings) {
      if (rectCircleColliding(b, this)) {
        resolveCollision(b, this);
      }
    }

    // Tree collision
    for (const t of trees) {
      const dx = this.x - t.x;
      const dy = this.y - t.y;
      const dist = Math.sqrt(dx*dx + dy*dy);
      if (dist < this.radius + t.radius) {
        const angle = Math.atan2(dy, dx);
        this.x = t.x + Math.cos(angle) * (this.radius + t.radius);
        this.y = t.y + Math.sin(angle) * (this.radius + t.radius);
      }
    }
  }

  shoot(targetX, targetY) {
    const w = this.getWeapon();
    const now = Date.now();
    if (this.reloading) return;
    if (now - this.lastShot < w.fireRate) return;
    if (this.inVehicle) return;

    this.lastShot = now;
    playSound(w.sound, this.x, this.y, 0.4);

    const pellets = w.pellets || 1;
    for (let p = 0; p < pellets; p++) {
      const spread = (Math.random() - 0.5) * w.spread;
      const angle = this.angle + spread;
      bullets.push({
        x: this.x + Math.cos(this.angle) * 20,
        y: this.y + Math.sin(this.angle) * 20,
        vx: Math.cos(angle) * w.bulletSpeed,
        vy: Math.sin(angle) * w.bulletSpeed,
        damage: w.damage,
        owner: this,
        range: w.range,
        traveled: 0,
        hitZone: Math.random() < 0.15 ? 'head' : (Math.random() < 0.3 ? 'limb' : 'body'),
        life: 2,
      });
    }

    // Recoil
    this.angle += (Math.random() - 0.5) * w.recoil[0] + w.recoil[1] * 0.3;
  }

  meleeAttack() {
    const w = WEAPONS.melee;
    const now = Date.now();
    if (now - this.lastShot < w.fireRate) return;
    this.lastShot = now;
    playSound('melee', this.x, this.y, 0.3);

    for (const e of entities) {
      if (!e.alive || e === this || e.inVehicle) continue;
      const dx = e.x - this.x;
      const dy = e.y - this.y;
      const dist = Math.sqrt(dx*dx + dy*dy);
      if (dist < w.range + e.radius) {
        e.takeDamage(w.damage, this);
        playSound('hit', e.x, e.y, 0.2);
      }
    }
  }

  throwGrenade() {
    if (this.grenadeCooldown > 0) return;
    this.grenadeCooldown = 3;
    this.lastGrenadeTime = Date.now();
    playSound('explosion', this.x, this.y, 0.5);

    const angle = this.angle;
    const grenade = {
      x: this.x + Math.cos(angle) * 10,
      y: this.y + Math.sin(angle) * 10,
      vx: Math.cos(angle) * 8,
      vy: Math.sin(angle) * 8,
      owner: this,
      timer: 2,
      radius: 8,
      type: 'frag',
    };
    bullets.push(grenade);
  }

  throwSmoke() {
    if (this.smokeCooldown > 0) return;
    this.smokeCooldown = 8;
    this.lastSmokeTime = Date.now();

    const angle = this.angle;
    const smoke = {
      x: this.x + Math.cos(angle) * 10,
      y: this.y + Math.sin(angle) * 10,
      vx: Math.cos(angle) * 5,
      vy: Math.sin(angle) * 5,
      timer: 15,
      radius: 40,
      type: 'smoke',
    };
    bullets.push(smoke);
  }

  revive(target) {
    if (!target.dbno) return;
    target.dbno = false;
    target.bleedTimer = 0;
    target.hp = 30;
    target.alive = true;
    addKillFeed(this.name, target.name + ' (revived)');
  }
}

// ============================================================
// VEHICLE SYSTEM
// ============================================================
class Vehicle {
  constructor(x, y, type) {
    this.x = x; this.y = y;
    this.type = type;
    this.angle = Math.random() * Math.PI * 2;
    this.speed = 0;
    this.maxSpeed = type === 'motorcycle' ? 10 : (type === 'jeep' ? 7 : 5);
    this.acceleration = type === 'motorcycle' ? 0.15 : 0.08;
    this.hp = type === 'armored' ? 500 : (type === 'jet' ? 300 : 200);
    this.maxHp = this.hp;
    this.fuel = 100;
    this.maxFuel = 100;
    this.occupants = [];
    this.radius = type === 'truck' ? 25 : (type === 'boat' ? 18 : 15);
    this.w = type === 'truck' ? 50 : (type === 'boat' ? 40 : 30);
    this.h = type === 'truck' ? 24 : (type === 'boat' ? 20 : 16);
    this.tires = [{x:0,y:0,hp:100},{x:0,y:0,hp:100},{x:0,y:0,hp:100},{x:0,y:0,hp:100}];
    this.smoking = false;
    this.onFire = false;
    this.isBoat = (type === 'boat' || type === 'jetski');
  }

  update(dt) {
    if (this.hp <= 0) {
      if (!this.exploded) {
        this.exploded = true;
        playSound('explosion', this.x, this.y, 0.8);
        for (let i = 0; i < 20; i++) {
          particles.push(createParticle(this.x, this.y, '#ff4400', 3));
        }
      }
      return;
    }

    this.x += Math.cos(this.angle) * this.speed * dt;
    this.y += Math.sin(this.angle) * this.speed * dt;
    this.speed *= 0.98;

    // Fuel consumption
    if (Math.abs(this.speed) > 0.1) {
      this.fuel -= dt * (this.type === 'jet' ? 0.3 : 0.05);
    }

    if (this.fuel <= 0) {
      this.fuel = 0;
      this.speed *= 0.95;
    }

    // Smoke/fire from damage
    if (this.hp < this.maxHp * 0.3) {
      this.smoking = true;
      if (this.hp < this.maxHp * 0.1) this.onFire = true;
    }

    // Building collision
    for (const b of buildings) {
      if (rectCircleColliding(b, this)) {
        resolveCollision(b, this);
        this.speed *= 0.5;
        this.hp -= Math.abs(this.speed) * 2;
      }
    }

    // World bounds
    this.x = Math.max(this.radius, Math.min(WORLD_W - this.radius, this.x));
    this.y = Math.max(this.radius, Math.min(WORLD_H - this.radius, this.y));

    // Update occupants
    for (const occ of this.occupants) {
      occ.x = this.x;
      occ.y = this.y;
      occ.angle = this.angle;
    }
  }
}

// ============================================================
// LOOT SYSTEM
// ============================================================
class LootItem {
  constructor(x, y, type, data) {
    this.x = x; this.y = y;
    this.type = type;
    this.data = data;
    this.radius = 12;
    this.bobOffset = Math.random() * Math.PI * 2;
    this.pickedUp = false;

    // Rarity colors
    const rarities = { common: '#888', uncommon: '#44aa44', rare: '#4488ff', epic: '#aa44ff', legendary: '#ffaa00' };
    this.color = rarities[data.rarity || 'common'] || '#888';
  }
}

// ============================================================
// WORLD GENERATION
// ============================================================
function generateWorld() {
  buildings = [];
  trees = [];
  lootItems = [];
  vehicles = [];

  // Generate buildings per biome
  const biomes = ['urban', 'forest', 'desert', 'coastal', 'mountains'];
  for (let bx = 0; bx < 8; bx++) {
    for (let by = 0; by < 8; by++) {
      const biome = biomes[(bx * 8 + by) % biomes.length];
      const bData = BIOMES[biome];
      const baseX = bx * WORLD_W / 8;
      const baseY = by * WORLD_H / 8;

      // Buildings
      const numBuildings = Math.floor(bData.buildingDensity * 200);
      for (let i = 0; i < numBuildings; i++) {
        const bw = 40 + Math.random() * 80;
        const bh = 40 + Math.random() * 80;
        const bx2 = baseX + Math.random() * (WORLD_W / 8 - bw);
        const by2 = baseY + Math.random() * (WORLD_H / 8 - bh);
        buildings.push({
          x: bx2, y: by2, w: bw, h: bh,
          biome: biome,
          lootTier: Math.random() < 0.2 ? 'epic' : (Math.random() < 0.4 ? 'rare' : 'common'),
          hasLoot: Math.random() < 0.8,
        });
      }

      // Trees
      const numTrees = Math.floor(bData.treeDensity * 300);
      for (let i = 0; i < numTrees; i++) {
        trees.push({
          x: baseX + Math.random() * (WORLD_W / 8),
          y: baseY + Math.random() * (WORLD_H / 8),
          radius: 8 + Math.random() * 12,
          height: 20 + Math.random() * 30,
          biome: biome,
        });
      }
    }
  }

  // POIs
  const poiNames = ['Military Base', 'City Center', 'Airfield', 'Hospital', 'Farms',
    'Industrial Zone', 'Harbor', 'Suburbs', 'Mountain Outpost', 'Desert Town',
    'Coastal Village', 'Forest Camp', 'Prison', 'School', 'Shopping Mall',
    'Gas Station', 'Warehouse', 'Bunker', 'Lighthouse', 'Watchtower'];
  for (let i = 0; i < 18; i++) {
    const px = 200 + Math.random() * (WORLD_W - 400);
    const py = 200 + Math.random() * (WORLD_H - 400);
    const pw = 80 + Math.random() * 120;
    const ph = 80 + Math.random() * 120;
    buildings.push({
      x: px, y: py, w: pw, h: ph,
      biome: 'urban',
      lootTier: 'epic',
      hasLoot: true,
      isPOI: true,
      name: poiNames[i],
    });
  }

  // Generate loot
  const weaponTypes = Object.keys(WEAPONS);
  const armorTypes = ARMOR;
  const helmetTypes = HELMETS;
  const consumableTypes = [
    { name:'Bandage', type:'heal', value:15, rarity:'common' },
    { name:'Med Kit', type:'heal', value:75, rarity:'uncommon' },
    { name:'Energy Drink', type:'boost', value:40, rarity:'common' },
    { name:'Painkillers', type:'boost', value:60, rarity:'uncommon' },
    { name:'First Aid', type:'heal', value:50, rarity:'rare' },
  ];
  const ammoTypes = [
    { name:'9mm', type:'9mm', qty:30, rarity:'common' },
    { name:'5.56mm', type:'556mm', qty:30, rarity:'common' },
    { name:'7.62mm', type:'762mm', qty:20, rarity:'uncommon' },
    { name:'12 Gauge', type:'12ga', qty:10, rarity:'common' },
    { name:'Sniper Rounds', type:'sniper', qty:10, rarity:'rare' },
  ];
  const attachmentTypes = [
    { name:'Red Dot', type:'scope', level:1, rarity:'common' },
    { name:'Holo Sight', type:'scope', level:2, rarity:'common' },
    { name:'2x Scope', type:'scope', level:3, rarity:'uncommon' },
    { name:'4x Scope', type:'scope', level:4, rarity:'rare' },
    { name:'8x Scope', type:'scope', level:5, rarity:'epic' },
    { name:'15x Scope', type:'scope', level:6, rarity:'legendary' },
    { name:'Compensator', type:'muzzle', rarity:'uncommon' },
    { name:'Suppressor', type:'muzzle', rarity:'rare' },
    { name:'Flash Hider', type:'muzzle', rarity:'common' },
    { name:'Vertical Grip', type:'grip', rarity:'common' },
    { name:'Angled Grip', type:'grip', rarity:'common' },
    { name:'Extended Mag', type:'mag', rarity:'uncommon' },
    { name:'Quickdraw Mag', type:'mag', rarity:'rare' },
    { name:'Tactical Stock', type:'stock', rarity:'uncommon' },
    { name:'Canted Sight', type:'canted', rarity:'uncommon' },
  ];
  const throwableTypes = [
    { name:'Frag Grenade', type:'frag', rarity:'common' },
    { name:'Smoke Grenade', type:'smoke', rarity:'common' },
    { name:'Stun Grenade', type:'stun', rarity:'uncommon' },
    { name:'Molotov', type:'molotov', rarity:'rare' },
  ];

  // Loot in buildings
  for (const b of buildings) {
    if (!b.hasLoot) continue;
    const numItems = 3 + Math.floor(Math.random() * 8);
    for (let i = 0; i < numItems; i++) {
      const roll = Math.random();
      let item;
      if (roll < 0.15) {
        const wt = weaponTypes[Math.floor(Math.random() * weaponTypes.length)];
        item = new LootItem(b.x + Math.random() * b.w, b.y + Math.random() * b.h, 'weapon', {
          key: wt, ...WEAPONS[wt], rarity: b.lootTier
        });
      } else if (roll < 0.25) {
        const at = attachmentTypes[Math.floor(Math.random() * attachmentTypes.length)];
        item = new LootItem(b.x + Math.random() * b.w, b.y + Math.random() * b.h, 'attachment', at);
      } else if (roll < 0.35) {
        const arm = armorTypes[Math.floor(Math.random() * armorTypes.length)];
        item = new LootItem(b.x + Math.random() * b.w, b.y + Math.random() * b.h, 'armor', arm);
      } else if (roll < 0.42) {
        const hel = helmetTypes[Math.floor(Math.random() * helmetTypes.length)];
        item = new LootItem(b.x + Math.random() * b.w, b.y + Math.random() * b.h, 'helmet', hel);
      } else if (roll < 0.6) {
        const cons = consumableTypes[Math.floor(Math.random() * consumableTypes.length)];
        item = new LootItem(b.x + Math.random() * b.w, b.y + Math.random() * b.h, 'consumable', cons);
      } else if (roll < 0.78) {
        const am = ammoTypes[Math.floor(Math.random() * ammoTypes.length)];
        item = new LootItem(b.x + Math.random() * b.w, b.y + Math.random() * b.h, 'ammo', am);
      } else if (roll < 0.88) {
        const th = throwableTypes[Math.floor(Math.random() * throwableTypes.length)];
        item = new LootItem(b.x + Math.random() * b.w, b.y + Math.random() * b.h, 'throwable', th);
      } else {
        continue;
      }
      if (item) lootItems.push(item);
    }
  }

  // Ground loot
  for (let i = 0; i < 200; i++) {
    const lx = Math.random() * WORLD_W;
    const ly = Math.random() * WORLD_H;
    const roll = Math.random();
    let item;
    if (roll < 0.3) {
      const cons = consumableTypes[Math.floor(Math.random() * consumableTypes.length)];
      item = new LootItem(lx, ly, 'consumable', cons);
    } else if (roll < 0.5) {
      const am = ammoTypes[Math.floor(Math.random() * ammoTypes.length)];
      item = new LootItem(lx, ly, 'ammo', am);
    } else if (roll < 0.6) {
      const at = attachmentTypes[Math.floor(Math.random() * attachmentTypes.length)];
      item = new LootItem(lx, ly, 'attachment', at);
    } else if (roll < 0.7) {
      const arm = armorTypes[Math.floor(Math.random() * armorTypes.length)];
      item = new LootItem(lx, ly, 'armor', arm);
    } else if (roll < 0.75) {
      const hel = helmetTypes[Math.floor(Math.random() * helmetTypes.length)];
      item = new LootItem(lx, ly, 'helmet', hel);
    }
    if (item) lootItems.push(item);
  }

  // Air drops
  for (let i = 0; i < 8; i++) {
    const ax = 300 + Math.random() * (WORLD_W - 600);
    const ay = 300 + Math.random() * (WORLD_H - 600);
    const wt = weaponTypes[Math.floor(Math.random() * weaponTypes.length)];
    lootItems.push(new LootItem(ax, ay, 'weapon', {
      key: wt, ...WEAPONS[wt], rarity: 'legendary'
    }));
    // Smoke trail visual
    particles.push({
      x: ax, y: ay, vx: 0, vy: -0.5, life: 999, maxLife: 999,
      type: 'smoke_trail', radius: 20, color: '#aaa'
    });
  }

  // Vehicles
  const vehicleTypes = ['jeep', 'sedan', 'buggy', 'motorcycle', 'truck', 'boat', 'jetski', 'armored'];
  for (let i = 0; i < 30; i++) {
    const vt = vehicleTypes[Math.floor(Math.random() * vehicleTypes.length)];
    const vx = 200 + Math.random() * (WORLD_W - 400);
    const vy = 200 + Math.random() * (WORLD_H - 400);
    vehicles.push(new Vehicle(vx, vy, vt));
  }
}

