function createBot(name, x, y) {
  const bot = new Entity(x, y, 14);
  bot.name = name;
  bot.isBot = true;
  bot.maxHp = 100;
  bot.hp = 100;

  // Give random weapons
  const numWeapons = 1 + Math.floor(Math.random() * 3);
  const weaponTypes = Object.keys(WEAPONS);
  for (let i = 0; i < numWeapons; i++) {
    const wt = weaponTypes[Math.floor(Math.random() * weaponTypes.length)];
    bot.weapons.push({ ...WEAPONS[wt], ammo: WEAPONS[wt].magSize, maxAmmo: WEAPONS[wt].magSize });
  }
  bot.currentWeapon = 0;

  // Random armor
  if (Math.random() < 0.6) {
    bot.armor = ARMOR[Math.floor(Math.random() * ARMOR.length)];
  }
  if (Math.random() < 0.5) {
    bot.helmet = HELMETS[Math.floor(Math.random() * HELMETS.length)];
  }

  // AI state
  bot.aiState = 'wander';
  bot.aiTarget = null;
  bot.aiTimer = 0;
  bot.aiMoveAngle = Math.random() * Math.PI * 2;
  bot.aiShootTimer = 0;
  bot.aiRecoil = 0;
  bot.aiAccuracy = 0.6 + Math.random() * 0.3;

  return bot;
}

function updateBotAI(bot, dt) {
  if (!bot.alive || bot.inVehicle) return;

  bot.aiTimer -= dt;

  // Find nearest player or bot
  let nearest = null;
  let nearestDist = 600;
  for (const e of entities) {
    if (!e.alive || e === bot) continue;
    const dx = e.x - bot.x;
    const dy = e.y - bot.y;
    const dist = Math.sqrt(dx*dx + dy*dy);
    if (dist < nearestDist) {
      nearestDist = dist;
      nearest = e;
    }
  }

  // Zone awareness
  const dxZ = zone.currentX - bot.x;
  const dyZ = zone.currentY - bot.y;
  const distToZone = Math.sqrt(dxZ*dxZ + dyZ*dyZ);

  // State machine
  if (nearest && nearestDist < 500) {
    bot.aiState = 'combat';
    bot.aiTarget = nearest;
  } else if (distToZone > zone.currentRadius * 0.8) {
    bot.aiState = 'move_to_zone';
  } else if (bot.aiTimer <= 0) {
    bot.aiState = 'wander';
    bot.aiTimer = 3 + Math.random() * 5;
    bot.aiMoveAngle = Math.random() * Math.PI * 2;
  }

  switch(bot.aiState) {
    case 'wander':
      bot.vx = Math.cos(bot.aiMoveAngle) * bot.speed * 0.5;
      bot.vy = Math.sin(bot.aiMoveAngle) * bot.speed * 0.5;
      bot.angle = bot.aiMoveAngle;
      break;

    case 'move_to_zone':
      const angleToZone = Math.atan2(dyZ, dxZ);
      bot.vx = Math.cos(angleToZone) * bot.sprintSpeed;
      bot.vy = Math.sin(angleToZone) * bot.sprintSpeed;
      bot.angle = angleToZone;
      break;

    case 'combat':
      if (!bot.aiTarget || !bot.aiTarget.alive) {
        bot.aiState = 'wander';
        bot.aiTimer = 2;
        break;
      }

      const tdx = bot.aiTarget.x - bot.x;
      const tdy = bot.aiTarget.y - bot.y;
      const tdist = Math.sqrt(tdx*tdx + tdy*tdy);
      const targetAngle = Math.atan2(tdy, tdx);

      // Aim with some inaccuracy
      const aimError = (1 - bot.aiAccuracy) * 0.3;
      bot.angle = targetAngle + (Math.random() - 0.5) * aimError;

      // Movement
      if (tdist > 200) {
        bot.vx = Math.cos(targetAngle) * bot.sprintSpeed;
        bot.vy = Math.sin(targetAngle) * bot.sprintSpeed;
      } else if (tdist < 100) {
        bot.vx = -Math.cos(targetAngle) * bot.speed;
        bot.vy = -Math.sin(targetAngle) * bot.speed;
      } else {
        // Strafe
        bot.vx = Math.cos(targetAngle + Math.PI/2) * bot.speed * (Math.random() > 0.5 ? 1 : -1);
        bot.vy = Math.sin(targetAngle + Math.PI/2) * bot.speed * (Math.random() > 0.5 ? 1 : -1);
      }

      // Shoot
      if (tdist < bot.getWeapon().range && bot.aiTarget.alive) {
        if (Math.random() < 0.3) {
          bot.shoot(bot.aiTarget.x, bot.aiTarget.y);
        }
      }

      // Use cover
      if (Math.random() < 0.01 && tdist < 300) {
        bot.crouching = !bot.crouching;
      }
      break;
  }

  // Use consumables
  if (bot.hp < 50 && Math.random() < 0.02) {
    // Find and use bandage
    for (const item of lootItems) {
      if (item.type === 'consumable' && item.data.type === 'heal') {
        const dx = item.x - bot.x;
        const dy = item.y - bot.y;
        if (Math.sqrt(dx*dx + dy*dy) < 30) {
          bot.hp = Math.min(bot.maxHp, bot.hp + item.data.value);
          item.pickedUp = true;
          break;
        }
      }
    }
  }

  // Pick up nearby loot
  for (const item of lootItems) {
    if (item.pickedUp) continue;
    const dx = item.x - bot.x;
    const dy = item.y - bot.y;
    if (Math.sqrt(dx*dx + dy*dy) < 25) {
      applyLoot(bot, item);
      item.pickedUp = true;
    }
  }
}

