// UTILITY FUNCTIONS
// ============================================================
function rectCircleColliding(rect, circle) {
  const closestX = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
  const closestY = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
  const dx = circle.x - closestX;
  const dy = circle.y - closestY;
  return (dx * dx + dy * dy) < (circle.radius * circle.radius);
}

function resolveCollision(rect, circle) {
  const cx = rect.x + rect.w / 2;
  const cy = rect.y + rect.h / 2;
  const dx = circle.x - cx;
  const dy = circle.y - cy;
  const dist = Math.sqrt(dx*dx + dy*dy);
  if (dist === 0) return;
  const nx = dx / dist;
  const ny = dy / dist;
  const overlap = circle.radius - dist + Math.max(rect.w, rect.h) * 0.5;
  if (overlap > 0) {
    circle.x += nx * overlap * 0.5;
    circle.y += ny * overlap * 0.5;
  }
}

function showDamageIndicator(amount) {
  const el = document.getElementById('damage-indicator');
  el.textContent = amount;
  el.style.opacity = 1;
  setTimeout(() => el.style.opacity = 0, 500);
}

function addKillFeed(killer, victim) {
