}

function createParticle(x, y, color, size) {
  return {
    x, y,
    vx: (Math.random() - 0.5) * 4,
    vy: (Math.random() - 0.5) * 4,
    life: 0.5 + Math.random() * 0.5,
    maxLife: 0.5 + Math.random() * 0.5,
    color: color,
    radius: size || 2,
    type: 'particle',
  };
}

function spawnLootDeath(entity) {
  // Drop some loot
  for (const w of entity.weapons) {
    lootItems.push(new LootItem(entity.x + (Math.random()-0.5)*30, entity.y + (Math.random()-0.5)*30, 'weapon', {
      key: w.key, ...w, rarity: 'rare'
    }));
  }
  if (entity.armor) {
    lootItems.push(new LootItem(entity.x + (Math.random()-0.5)*30, entity.y + (Math.random()-0.5)*30, 'armor', entity.armor));
  }
  if (entity.helmet) {
    lootItems.push(new LootItem(entity.x + (Math.random()-0.5)*30, entity.y + (Math.random()-0.5)*30, 'helmet', entity.helmet));
  }
}

function applyLoot(entity, item) {
  item.pickedUp = true;
  playSound('pickup', item.x, item.y, 0.2);

  switch(item.type) {
    case 'weapon':
      if (entity.weapons.length < 5) {
        entity.weapons.push({ ...item.data, ammo: item.data.magSize, maxAmmo: item.data.magSize });
      } else {
        entity.weapons[entity.currentWeapon] = { ...item.data, ammo: item.data.magSize, maxAmmo: item.data.magSize };
      }
      break;
    case 'armor':
      if (!entity.armor || item.data.reduction > entity.armor.reduction) {
        entity.armor = item.data;
        entity.maxHp = item.data.maxHp;
        entity.hp = Math.min(entity.hp, entity.maxHp);
      }
      break;
    case 'helmet':
      if (!entity.helmet || item.data.reduction > entity.helmet.reduction) {
        entity.helmet = item.data;
      }
      break;
    case 'consumable':
      if (item.data.type === 'heal') {
        entity.hp = Math.min(entity.maxHp, entity.hp + item.data.value);
      } else if (item.data.type === 'boost') {
        entity.boost = Math.min(entity.maxBoost, entity.boost + item.data.value);
      }
      break;
    case 'ammo':
      entity.ammo[item.data.type] = (entity.ammo[item.data.type] || 0) + item.data.qty;
      break;
    case 'attachment':
      // Applied to current weapon
      if (entity.weapons.length > 0) {
        entity.weapons[entity.currentWeapon][item.data.type] = item.data;
      }
      break;
    case 'throwable':
      // Stored in inventory
      entity.inventory.push(item.data);
      break;
  }
}

// ============================================================
// PLAYER
// ============================================================
let player;

function createPlayer() {
  player = new Entity(WORLD_W/2, WORLD_H/2, 14);
  player.isPlayer = true;
  player.name = 'You';
  player.maxHp = 100;
  player.hp = 100;
  player.weapons.push({ ...WEAPONS.pistol, ammo: 7, maxAmmo: 7 });
  player.currentWeapon = 0;
  return player;
}

function updatePlayer(dt) {
  if (!player.alive) return;

  const sprinting = keys['ShiftLeft'] || keys['ShiftRight'];
  const crouching = keys['KeyC'];
  const prone = keys['ControlLeft'] || keys['ControlRight'];

  player.crouching = crouching;
  player.prone = prone;

  if (prone) {
    player.radius = 8;
    player.speed = 1.5;
  } else if (crouching) {
    player.radius = 12;
    player.speed = 2;
  } else if (sprinting) {
    player.radius = 14;
    player.speed = player.sprintSpeed;
  } else {
    player.radius = 14;
    player.speed = 3;
  }

  // Movement
  let mx = 0, my = 0;
  if (keys['KeyW']) my -= 1;
  if (keys['KeyS']) my += 1;
  if (keys['KeyA']) mx -= 1;
  if (keys['KeyD']) mx += 1;

  if (mx !== 0 || my !== 0) {
    const len = Math.sqrt(mx*mx + my*my);
    mx /= len; my /= len;
    player.vx += mx * player.speed * 0.3;
    player.vy += my * player.speed * 0.3;
  }

  player.vx = Math.max(-player.speed, Math.min(player.speed, player.vx));
  player.vy = Math.max(-player.speed, Math.min(player.speed, player.vy));

  // Aim
  mouse.worldX = mouse.x - W/2 + camera.x;
  mouse.worldY = mouse.y - H/2 + camera.y;
  player.angle = Math.atan2(mouse.worldY - player.y, mouse.worldX - player.x);

  // Shooting
  if (mouse.down) {
    const w = player.getWeapon();
    if (w.type === 'melee') {
      player.meleeAttack();
    } else if (!w.auto || Date.now() - player.lastShot >= w.fireRate) {
      player.shoot(mouse.worldX, mouse.worldY);
    }
  }

  // Reload
  if (keys['KeyR'] && !player.reloading) {
    const w = player.getWeapon();
    if (w.type !== 'melee' && player.weapons[player.currentWeapon].ammo < player.weapons[player.currentWeapon].maxAmmo) {
      player.reloading = true;
      player.reloadStart = Date.now();
      playSound('reload', player.x, player.y, 0.2);
    }
  }

  // Auto-reload
  if (player.reloading) {
    const w = player.getWeapon();
    if (Date.now() - player.reloadStart >= w.reloadTime) {
      player.reloading = false;
    }
  }

  // Grenade
  if (keys['KeyQ'] && Date.now() - player.lastGrenadeTime > 1000) {
    player.throwGrenade();
  }

  // Smoke
  if (keys['KeyT'] && Date.now() - player.lastSmokeTime > 1000) {
    player.throwSmoke();
  }

  // Weapon switching
  for (let i = 1; i <= 5; i++) {
    if (keys['Digit' + i] && i - 1 < player.weapons.length) {
      player.currentWeapon = i - 1;
    }
  }

  // Pickup / interact
  if (keys['KeyE']) {
    for (const item of lootItems) {
      if (item.pickedUp) continue;
      const dx = item.x - player.x;
      const dy = item.y - player.y;
      if (Math.sqrt(dx*dx + dy*dy) < 35) {
        applyLoot(player, item);
        const popup = document.getElementById('loot-popup');
        popup.textContent = `Picked up ${item.data.name}`;
        popup.style.display = 'block';
        setTimeout(() => popup.style.display = 'none', 1500);
        break;
      }
    }
    keys['KeyE'] = false;
  }

  // Vehicle enter/exit
  if (keys['KeyF']) {
    if (player.inVehicle) {
      // Exit
      player.inVehicle.occupants = player.inVehicle.occupants.filter(o => o !== player);
      player.x = player.inVehicle.x + Math.cos(player.inVehicle.angle + Math.PI/2) * 25;
      player.y = player.inVehicle.y + Math.sin(player.inVehicle.angle + Math.PI/2) * 25;
      player.inVehicle = null;
    } else {
      // Enter nearest vehicle
      for (const v of vehicles) {
        const dx = v.x - player.x;
        const dy = v.y - player.y;
        if (Math.sqrt(dx*dx + dy*dy) < 40 && v.hp > 0 && !v.occupants.includes(player)) {
          player.inVehicle = v;
          v.occupants.push(player);
          break;
        }
      }
    }
    keys['KeyF'] = false;
  }

  // Inventory toggle
  if (keys['KeyI']) {
    const panel = document.getElementById('inventory-panel');
    panel.style.display = panel.style.display === 'block' ? 'none' : 'block';
    keys['KeyI'] = false;
  }

  // Zone damage
  const dxZ = player.x - zone.currentX;
  const dyZ = player.y - zone.currentY;
  const distToZone = Math.sqrt(dxZ*dxZ + dyZ*dyZ);
  if (distToZone > zone.currentRadius) {
    player.takeDamage(zone.damage * dt, null);
  }

  // Boost passive regen
  if (player.boost > 0) {
    player.boost -= dt * 2;
    if (player.hp < player.maxHp) {
      player.hp = Math.min(player.maxHp, player.hp + dt * 1.5);
    }
  }
}

// ============================================================
// ZONE SYSTEM
// ============================================================
function updateZone(dt) {
  const phase = zone.phases[zone.phase];
  if (!phase) return;

  zone.shrinkTimer += dt;

  if (zone.shrinkTimer >= zone.shrinkDuration) {
    zone.shrinkTimer = 0;
    zone.phase++;
    if (zone.phase >= zone.phases.length) {
      // Final phase - keep shrinking
      zone.currentRadius = Math.max(50, zone.currentRadius - dt * 5);
      zone.damage = zone.phases[zone.phases.length - 1].damage;
    } else {
      const nextPhase = zone.phases[zone.phase];
      zone.targetRadius = nextPhase.radius;
      zone.damage = nextPhase.damage;
      zone.shrinkDuration = 30;
      showMessage(`ZONE PHASE ${zone.phase + 1}`, 3000);
    }
  }

  // Shrink toward target
  const lerpSpeed = dt * 0.3;
  zone.currentRadius += (zone.targetRadius - zone.currentRadius) * lerpSpeed;
  zone.currentX += (zone.targetX - zone.currentX) * lerpSpeed;
  zone.currentY += (zone.targetY - zone.currentY) * lerpSpeed;

  // Update zone timer display
  const remaining = Math.max(0, zone.shrinkDuration - zone.shrinkTimer);
  document.getElementById('zone-timer').textContent =
    `ZONE PHASE ${zone.phase + 1} • ${Math.ceil(remaining)}s • DMG: ${zone.damage}/s`;
}

function showMessage(text, duration=2000) {
  const el = document.getElementById('message');
  el.textContent = text;
  el.style.display = 'block';
  setTimeout(() => el.style.display = 'none', duration);
}

// ============================================================
// RED ZONE SYSTEM
// ============================================================
function updateRedZone(dt) {
  redZone.timer -= dt;

  if (redZone.timer <= 0 && !redZone.active) {
    if (Math.random() < 0.3) {
      redZone.active = true;
      redZone.timer = redZone.duration;
      const rx = 200 + Math.random() * (WORLD_W - 400);
      const ry = 200 + Math.random() * (WORLD_H - 400);
      const rr = 100 + Math.random() * 150;
      redZone.bombs.push({ x: rx, y: ry, radius: rr, timer: 5, exploded: false });
      showMessage('⚠ ARTILLERY WARNING ⚠', 3000);
    } else {
      redZone.timer = redZone.cooldown;
    }
  } else if (redZone.active) {
    redZone.timer -= dt;
    if (redZone.timer <= 0) {
      redZone.active = false;
      redZone.bombs = [];
      redZone.timer = redZone.cooldown;
    }
  }

  // Bomb impacts
  for (const bomb of redZone.bombs) {
    if (!bomb.exploded && bomb.timer <= 0) {
      bomb.exploded = true;
      playSound('explosion', bomb.x, bomb.y, 0.6);
      for (let i = 0; i < 15; i++) {
        particles.push(createParticle(bomb.x, bomb.y, '#ff6600', 4));
      }
      // Damage entities in radius
      for (const e of entities) {
        if (!e.alive || e.inVehicle) continue;
        const dx = e.x - bomb.x;
        const dy = e.y - bomb.y;
        if (Math.sqrt(dx*dx + dy*dy) < bomb.radius) {
          // Check if in building (protection)
          let inBuilding = false;
          for (const b of buildings) {
            if (e.x > b.x && e.x < b.x + b.w && e.y > b.y && e.y < b.y + b.h) {
              inBuilding = true;
              break;
            }
          }
          if (!inBuilding) {
            e.takeDamage(50, null);
          }
        }
      }
    }
  }
}

// ============================================================
// WEATHER SYSTEM
// ============================================================
function updateWeather(dt) {
  weather.timer -= dt;
  if (weather.timer <= 0) {
    const types = ['clear', 'clear', 'clear', 'rain', 'fog', 'storm'];
    weather.type = types[Math.floor(Math.random() * types.length)];
    weather.timer = 30 + Math.random() * 60;
    weather.intensity = 0.3 + Math.random() * 0.7;
  }

  // Rain drops
  if (weather.type === 'rain' || weather.type === 'storm') {
    for (let i = 0; i < 5; i++) {
      weather.raindrops.push({
        x: camera.x + (Math.random() - 0.5) * W * 1.5,
        y: camera.y + (Math.random() - 0.5) * H * 1.5,
        speed: 15 + Math.random() * 10,
        length: 10 + Math.random() * 15,
      });
    }
  }

  // Update raindrops
  weather.raindrops = weather.raindrops.filter(r => {
    r.y += r.speed * dt * 60;
    r.x += r.speed * 0.3 * dt * 60;
    return r.y < camera.y + H;
  });

  // Fog
  if (weather.type === 'fog' || weather.type === 'storm') {
    weather.fogDensity = weather.intensity * 0.5;
  } else {
    weather.fogDensity *= 0.95;
  }
}

function renderWeather() {
  WCTX.clearRect(0, 0, W, H);

  if (weather.type === 'rain' || weather.type === 'storm') {
    WCTX.strokeStyle = `rgba(150,180,220,${weather.intensity * 0.4})`;
    WCTX.lineWidth = 1;
    for (const r of weather.raindrops) {
      WCTX.beginPath();
      WCTX.moveTo(r.x - camera.x + W/2, r.y - camera.y + H/2);
      WCTX.lineTo(r.x - camera.x + W/2 + 3, r.y - camera.y + H/2 + r.length);
      WCTX.stroke();
    }
  }

  if (weather.fogDensity > 0.05) {
    WCTX.fillStyle = `rgba(180,190,200,${weather.fogDensity * 0.3})`;
    WCTX.fillRect(0, 0, W, H);
  }
}

// ============================================================
// RENDERING
// ============================================================
function getBiomeColor(x, y) {
  const biomeIdx = ((Math.floor(x / (WORLD_W/8)) * 8 + Math.floor(y / (WORLD_H/8))) % 5);
  const biomes = ['urban', 'forest', 'desert', 'coastal', 'mountains'];
  return BIOMES[biomes[biomeIdx]].ground;
}

function render() {
  CTX.clearRect(0, 0, W, H);

  // Camera follow player
  if (player) {
    const targetX = player.inVehicle ? player.inVehicle.x : player.x;
    const targetY = player.inVehicle ? player.inVehicle.y : player.y;
    camera.x += (targetX - camera.x) * 0.1;
    camera.y += (targetY - camera.y) * 0.1;
  }

  CTX.save();
  CTX.translate(W/2 - camera.x, H/2 - camera.y);

  // Draw ground
  const startTileX = Math.floor((camera.x - W/2) / TILE);
  const startTileY = Math.floor((camera.y - H/2) / TILE);
  const endTileX = Math.ceil((camera.x + W/2) / TILE);
  const endTileY = Math.ceil((camera.y + H/2) / TILE);

  for (let tx = startTileX; tx < endTileX; tx++) {
    for (let ty = startTileY; ty < endTileY; ty++) {
      if (tx < 0 || tx >= WORLD_W/TILE || ty < 0 || ty >= WORLD_H/TILE) continue;
      const x = tx * TILE;
      const y = ty * TILE;
      CTX.fillStyle = getBiomeColor(x, y);
      CTX.fillRect(x, y, TILE, TILE);
    }
  }

  // Grid lines (subtle)
  CTX.strokeStyle = 'rgba(255,255,255,0.03)';
  CTX.lineWidth = 0.5;
  for (let tx = startTileX; tx < endTileX; tx++) {
    CTX.beginPath();
    CTX.moveTo(tx * TILE, startTileY * TILE);
    CTX.lineTo(tx * TILE, endTileY * TILE);
    CTX.stroke();
  }
  for (let ty = startTileY; ty < endTileY; ty++) {
    CTX.beginPath();
    CTX.moveTo(startTileX * TILE, ty * TILE);
    CTX.lineTo(endTileX * TILE, ty * TILE);
    CTX.stroke();
  }

  // Draw buildings
  for (const b of buildings) {
    if (b.x + b.w < camera.x - W/2 || b.x > camera.x + W/2 ||
        b.y + b.h < camera.y - H/2 || b.y > camera.y + H/2) continue;

    const biome = BIOMES[b.biome];
    CTX.fillStyle = b.isPOI ? '#5a5a6a' : biome.color;
    CTX.fillRect(b.x, b.y, b.w, b.h);

    CTX.strokeStyle = 'rgba(0,0,0,0.3)';
    CTX.lineWidth = 2;
    CTX.strokeRect(b.x, b.y, b.w, b.h);

    // Roof detail
    CTX.fillStyle = 'rgba(0,0,0,0.1)';
    CTX.fillRect(b.x + 4, b.y + 4, b.w - 8, b.h - 8);

    // POI label
    if (b.isPOI) {
      CTX.fillStyle = 'rgba(255,255,255,0.7)';
      CTX.font = '10px Arial';
      CTX.textAlign = 'center';
      CTX.fillText(b.name, b.x + b.w/2, b.y - 5);
    }
  }

  // Draw trees
  for (const t of trees) {
    if (t.x < camera.x - W/2 - 50 || t.x > camera.x + W/2 + 50 ||
        t.y < camera.y - H/2 - 50 || t.y > camera.y + H/2 + 50) continue;

    // Shadow
    CTX.fillStyle = 'rgba(0,0,0,0.2)';
    CTX.beginPath();
    CTX.ellipse(t.x + 5, t.y + 5, t.radius, t.radius * 0.7, 0, 0, Math.PI * 2);
    CTX.fill();

    // Tree
    const biome = BIOMES[t.biome];
    CTX.fillStyle = biome === BIOMES.desert ? '#8a7a3a' : (biome === BIOMES.coastal ? '#3a6a4a' : '#2a5a1a');
    CTX.beginPath();
    CTX.arc(t.x, t.y, t.radius, 0, Math.PI * 2);
    CTX.fill();

    CTX.strokeStyle = 'rgba(0,0,0,0.2)';
    CTX.lineWidth = 1;
    CTX.stroke();
  }

  // Draw vehicles
  for (const v of vehicles) {
    if (v.hp <= 0) continue;
    if (v.x < camera.x - W/2 - 100 || v.x > camera.x + W/2 + 100 ||
        v.y < camera.y - H/2 - 100 || v.y > camera.y + H/2 + 100) continue;

    CTX.save();
    CTX.translate(v.x, v.y);
    CTX.rotate(v.angle);

    // Vehicle body
    const colors = {
      jeep: '#4a5a3a', sedan: '#3a4a5a', buggy: '#5a4a3a',
      motorcycle: '#2a2a2a', truck: '#4a4a4a', boat: '#5a6a7a',
      jetski: '#6a7a8a', armored: '#3a3a3a'
    };
    CTX.fillStyle = colors[v.type] || '#4a4a4a';
    CTX.fillRect(-v.w/2, -v.h/2, v.w, v.h);

    CTX.strokeStyle = 'rgba(0,0,0,0.4)';
    CTX.lineWidth = 2;
    CTX.strokeRect(-v.w/2, -v.h/2, v.w, v.h);

    // Windshield
    CTX.fillStyle = 'rgba(150,200,255,0.3)';
    CTX.fillRect(v.w/2 - 10, -v.h/2 + 3, 8, v.h - 6);

    // Damage indicators
    if (v.smoking) {
      CTX.fillStyle = 'rgba(100,100,100,0.5)';
      CTX.beginPath();
      CTX.arc(-v.w/4, -v.h/4, 8, 0, Math.PI * 2);
      CTX.fill();
    }
    if (v.onFire) {
      CTX.fillStyle = 'rgba(255,100,0,0.6)';
      CTX.beginPath();
      CTX.arc(v.w/4, v.h/4, 10, 0, Math.PI * 2);
      CTX.fill();
    }

    CTX.restore();

    // HP bar
    if (v.hp < v.maxHp) {
      CTX.fillStyle = 'rgba(0,0,0,0.5)';
      CTX.fillRect(v.x - 20, v.y - v.h/2 - 10, 40, 4);
      CTX.fillStyle = v.hp > v.maxHp * 0.5 ? '#44aa44' : (v.hp > v.maxHp * 0.25 ? '#aaaa44' : '#aa4444');
      CTX.fillRect(v.x - 20, v.y - v.h/2 - 10, 40 * (v.hp / v.maxHp), 4);
    }
  }

  // Draw loot items
  const time = Date.now() / 1000;
  for (const item of lootItems) {
    if (item.pickedUp) continue;
    if (item.x < camera.x - W/2 - 20 || item.x > camera.x + W/2 + 20 ||
        item.y < camera.y - H/2 - 20 || item.y > camera.y + H/2 + 20) continue;

    const bob = Math.sin(time * 3 + item.bobOffset) * 3;

    // Glow
    CTX.fillStyle = item.color + '33';
    CTX.beginPath();
    CTX.arc(item.x, item.y + bob, 18, 0, Math.PI * 2);
    CTX.fill();

    // Item
    CTX.fillStyle = item.color;
    CTX.beginPath();
    CTX.arc(item.x, item.y + bob, 8, 0, Math.PI * 2);
    CTX.fill();

    CTX.strokeStyle = item.color;
    CTX.lineWidth = 2;
    CTX.beginPath();
    CTX.arc(item.x, item.y + bob, 8, 0, Math.PI * 2);
    CTX.stroke();

    // Icon
    CTX.fillStyle = '#fff';
    CTX.font = '8px Arial';
    CTX.textAlign = 'center';
    const icons = { weapon: '🔫', armor: '🛡️', helmet: '⛑️', consumable: '💊', ammo: '📦', attachment: '🔧', throwable: '💣' };
    CTX.fillText(icons[item.type] || '?', item.x, item.y + bob + 3);
  }

  // Draw smoke trails
  for (const p of particles) {
    if (p.type === 'smoke_trail') {
      CTX.fillStyle = 'rgba(180,180,180,0.4)';
      CTX.beginPath();
      CTX.arc(p.x, p.y, p.radius + Math.sin(time * 2) * 5, 0, Math.PI * 2);
      CTX.fill();
    }
  }

  // Draw entities
  const sortedEntities = [...entities].sort((a, b) => a.y - b.y);
  for (const e of sortedEntities) {
    if (!e.alive && !e.dbno) continue;
    if (e.x < camera.x - W/2 - 50 || e.x > camera.x + W/2 + 50 ||
        e.y < camera.y - H/2 - 50 || e.y > camera.y + H/2 + 50) continue;

    CTX.save();
    CTX.translate(e.x, e.y);

    if (e.dbno) {
      CTX.globalAlpha = 0.6;
      // Knocked down
      CTX.fillStyle = '#ff4444';
      CTX.beginPath();
      CTX.ellipse(0, 0, e.radius + 5, e.radius * 0.5, 0, 0, Math.PI * 2);
      CTX.fill();

      // Bleed timer
      CTX.fillStyle = '#fff';
      CTX.font = '10px Arial';
      CTX.textAlign = 'center';
      CTX.fillText(Math.ceil(e.bleedTimer) + 's', 0, -e.radius - 10);
    } else {
      // Shadow
      CTX.fillStyle = 'rgba(0,0,0,0.2)';
      CTX.beginPath();
      CTX.ellipse(2, 2, e.radius, e.radius * 0.6, 0, 0, Math.PI * 2);
      CTX.fill();

      // Body
      const bodyColor = e.isPlayer ? '#44aaff' : (e.isBot ? '#ff6644' : '#aaa');
      CTX.fillStyle = e.hitFlash > 0 ? '#ff4444' : bodyColor;
      CTX.beginPath();
      CTX.arc(0, 0, e.radius, 0, Math.PI * 2);
      CTX.fill();

      CTX.strokeStyle = 'rgba(0,0,0,0.3)';
      CTX.lineWidth = 2;
      CTX.stroke();

      // Direction indicator
      CTX.strokeStyle = '#fff';
      CTX.lineWidth = 2;
      CTX.beginPath();
      CTX.moveTo(Math.cos(e.angle) * e.radius, Math.sin(e.angle) * e.radius);
      CTX.lineTo(Math.cos(e.angle) * (e.radius + 10), Math.sin(e.angle) * (e.radius + 10));
      CTX.stroke();

      // Weapon
      const w = e.getWeapon();
      if (w.type !== 'melee') {
        CTX.strokeStyle = '#888';
        CTX.lineWidth = 3;
        CTX.beginPath();
        CTX.moveTo(Math.cos(e.angle) * 5, Math.sin(e.angle) * 5);
        CTX.lineTo(Math.cos(e.angle) * 22, Math.sin(e.angle) * 22);
        CTX.stroke();
      }

      // Name
      CTX.fillStyle = '#fff';
      CTX.font = '10px Arial';
      CTX.textAlign = 'center';
      CTX.fillText(e.name, 0, -e.radius - 12);

      // HP bar
      const barW = 30;
      CTX.fillStyle = 'rgba(0,0,0,0.5)';
      CTX.fillRect(-barW/2, -e.radius - 8, barW, 3);
      const hpRatio = e.hp / e.maxHp;
      CTX.fillStyle = hpRatio > 0.5 ? '#44aa44' : (hpRatio > 0.25 ? '#aaaa44' : '#aa4444');
      CTX.fillRect(-barW/2, -e.radius - 8, barW * hpRatio, 3);
    }

    CTX.restore();
  }

  // Draw bullets
  for (const b of bullets) {
    if (b.type === 'frag' || b.type === 'smoke') {
      if (b.type === 'frag') {
        CTX.fillStyle = '#333';
        CTX.beginPath();
        CTX.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
        CTX.fill();
        CTX.strokeStyle = '#666';
        CTX.lineWidth = 1;
        CTX.stroke();
      } else {
        CTX.fillStyle = 'rgba(200,200,200,0.5)';
        CTX.beginPath();
        CTX.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
        CTX.fill();
      }
    } else {
      CTX.fillStyle = '#ffaa00';
      CTX.beginPath();
      CTX.arc(b.x, b.y, 2, 0, Math.PI * 2);
      CTX.fill();

      // Trail
      CTX.strokeStyle = 'rgba(255,170,0,0.3)';
      CTX.lineWidth = 1;
      CTX.beginPath();
      CTX.moveTo(b.x, b.y);
      CTX.lineTo(b.x - b.vx * 3, b.y - b.vy * 3);
      CTX.stroke();
    }
  }

  // Draw particles
  for (const p of particles) {
    if (p.type === 'smoke_trail') continue;
    const alpha = p.life / p.maxLife;
    CTX.fillStyle = p.color + Math.floor(alpha * 255).toString(16).padStart(2, '0');
    CTX.beginPath();
    CTX.arc(p.x, p.y, p.radius * alpha, 0, Math.PI * 2);
    CTX.fill();
  }

  // Draw zone
  CTX.strokeStyle = 'rgba(50,100,255,0.6)';
  CTX.lineWidth = 3;
  CTX.setLineDash([10, 5]);
  CTX.beginPath();
  CTX.arc(zone.currentX, zone.currentY, zone.currentRadius, 0, Math.PI * 2);
  CTX.stroke();
  CTX.setLineDash([]);

  // Zone fill (outside area)
  CTX.fillStyle = 'rgba(50,100,255,0.08)';
  CTX.beginPath();
  CTX.rect(camera.x - W, camera.y - H, W * 3, H * 3);
  CTX.arc(zone.currentX, zone.currentY, zone.currentRadius, 0, Math.PI * 2, true);
  CTX.fill();

  // Red zone indicators
  for (const bomb of redZone.bombs) {
    if (!bomb.exploded) {
      CTX.strokeStyle = 'rgba(255,50,50,0.6)';
      CTX.lineWidth = 2;
      CTX.setLineDash([5, 5]);
      CTX.beginPath();
      CTX.arc(bomb.x, bomb.y, bomb.radius, 0, Math.PI * 2);
      CTX.stroke();
      CTX.setLineDash([]);

      // Warning
      CTX.fillStyle = 'rgba(255,50,50,0.8)';
      CTX.font = '12px Arial';
      CTX.textAlign = 'center';
      CTX.fillText(`⚠ ${Math.ceil(bomb.timer)}s`, bomb.x, bomb.y - bomb.radius - 10);
    }
  }

  CTX.restore();

  // Weather overlay
  renderWeather();

  // Minimap
  renderMinimap();

  // HUD updates
  updateHUD();
}

function renderMinimap() {
  MCTX.clearRect(0, 0, 180, 180);

  // Background
  MCTX.fillStyle = '#1a2a1a';
  MCTX.fillRect(0, 0, 180, 180);

  const scale = 180 / WORLD_W;

  // Zone
  MCTX.strokeStyle = 'rgba(50,100,255,0.8)';
  MCTX.lineWidth = 1;
  MCTX.beginPath();
  MCTX.arc(zone.currentX * scale, zone.currentY * scale, zone.currentRadius * scale, 0, Math.PI * 2);
  MCTX.stroke();

  // Buildings
  MCTX.fillStyle = 'rgba(100,100,120,0.5)';
  for (const b of buildings) {
    if (b.isPOI) {
      MCTX.fillStyle = 'rgba(255,200,50,0.6)';
      MCTX.fillRect(b.x * scale, b.y * scale, Math.max(2, b.w * scale), Math.max(2, b.h * scale));
    } else {
      MCTX.fillStyle = 'rgba(80,80,100,0.4)';
      MCTX.fillRect(b.x * scale, b.y * scale, Math.max(1, b.w * scale), Math.max(1, b.h * scale));
    }
  }

  // Entities
  for (const e of entities) {
    if (!e.alive) continue;
    if (e.isPlayer) {
      MCTX.fillStyle = '#44aaff';
      MCTX.beginPath();
      MCTX.arc(e.x * scale, e.y * scale, 3, 0, Math.PI * 2);
      MCTX.fill();
    } else if (e.isBot) {
      MCTX.fillStyle = '#ff6644';
      MCTX.beginPath();
      MCTX.arc(e.x * scale, e.y * scale, 2, 0, Math.PI * 2);
      MCTX.fill();
    }
  }

  // Vehicles
  MCTX.fillStyle = '#888';
  for (const v of vehicles) {
    if (v.hp > 0) {
      MCTX.fillRect(v.x * scale - 1, v.y * scale - 1, 2, 2);
    }
  }

  // Player direction
  if (player && player.alive) {
    MCTX.strokeStyle = '#44aaff';
    MCTX.lineWidth = 1;
    MCTX.beginPath();
    MCTX.moveTo(player.x * scale, player.y * scale);
    MCTX.lineTo(
      player.x * scale + Math.cos(player.angle) * 8,
      player.y * scale + Math.sin(player.angle) * 8
    );
    MCTX.stroke();
  }

  // Viewport
  MCTX.strokeStyle = 'rgba(255,255,255,0.3)';
  MCTX.lineWidth = 1;
  MCTX.strokeRect(
    (camera.x - W/2) * scale,
    (camera.y - H/2) * scale,
    W * scale, H * scale
  );
}

function updateHUD() {
  if (!player) return;

  document.getElementById('alive-count').textContent = entities.filter(e => e.alive).length;

  const hpRatio = Math.max(0, player.hp / player.maxHp) * 100;
  document.getElementById('health-bar').style.width = hpRatio + '%';

  const boostRatio = (player.boost / player.maxBoost) * 100;
  document.getElementById('boost-bar').style.width = boostRatio + '%';

  // Weapon slots
  const slotsEl = document.getElementById('weapon-slots');
  slotsEl.innerHTML = '';
  for (let i = 0; i < 5; i++) {
    const slot = document.createElement('div');
    slot.className = 'weapon-slot' + (i === player.currentWeapon ? ' active' : '');
    slot.id = 'weapon-slot-' + i;
    if (i < player.weapons.length) {
      const w = player.weapons[i];
      slot.innerHTML = `<span class="weapon-name">${w.name}</span><span class="ammo-count">${w.ammo}/${w.maxAmmo}</span>`;
    } else {
      slot.innerHTML = `<span class="weapon-name" style="color:#555">Empty</span>`;
    }
    slotsEl.appendChild(slot);
  }
}

// ============================================================
// BULLET UPDATE
// ============================================================
function updateBullets(dt) {
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];

    if (b.type === 'frag' || b.type === 'smoke') {
      b.x += b.vx * dt * 60;
      b.y += b.vy * dt * 60;
      b.vx *= 0.95;
      b.vy *= 0.95;
      b.timer -= dt;

      if (b.type === 'frag' && b.timer <= 0) {
        // Explosion
        playSound('explosion', b.x, b.y, 0.5);
        for (let j = 0; j < 20; j++) {
          particles.push(createParticle(b.x, b.y, j < 10 ? '#ff6600' : '#ffaa00', 3));
        }
        // Damage
        for (const e of entities) {
          if (!e.alive) continue;
          const dx = e.x - b.x;
          const dy = e.y - b.y;
          const dist = Math.sqrt(dx*dx + dy*dy);
          if (dist < 80) {
            const dmg = 80 * (1 - dist / 80);
            e.takeDamage(dmg, b.owner);
          }
        }
        bullets.splice(i, 1);
        continue;
      }

      if (b.type === 'smoke' && b.timer <= 0) {
        // Create persistent smoke cloud
        for (let j = 0; j < 10; j++) {
          particles.push({
            x: b.x + (Math.random()-0.5) * 30,
            y: b.y + (Math.random()-0.5) * 30,
            vx: (Math.random()-0.5) * 0.5,
            vy: (Math.random()-0.5) * 0.5,
            life: 10 + Math.random() * 5,
            maxLife: 15,
            radius: 15 + Math.random() * 10,
            color: 'rgba(180,180,180,0.3)',
            type: 'smoke_cloud',
          });
        }
        bullets.splice(i, 1);
        continue;
      }

      if (b.timer <= 0) {
        bullets.splice(i, 1);
        continue;
      }
      continue;
    }

    // Regular bullets
    b.x += b.vx * dt * 60;
    b.y += b.vy * dt * 60;
    b.traveled += Math.sqrt(b.vx*b.vx + b.vy*b.vy) * dt * 60;

    if (b.traveled > b.range || b.life <= 0) {
      bullets.splice(i, 1);
      continue;
    }

    // Building collision
    let hitBuilding = false;
    for (const bld of buildings) {
      if (b.x > bld.x && b.x < bld.x + bld.w && b.y > bld.y && b.y < bld.y + bld.h) {
        // Impact particle
        particles.push(createParticle(b.x, b.y, '#aaa', 2));
        hitBuilding = true;
        break;
      }
    }
    if (hitBuilding) {
      bullets.splice(i, 1);
      continue;
    }

    // Entity collision
    let hitEntity = false;
    for (const e of entities) {
      if (!e.alive || e === b.owner || e.inVehicle) continue;
      const dx = e.x - b.x;
      const dy = e.y - b.y;
      if (Math.sqrt(dx*dx + dy*dy) < e.radius + 3) {
        e.takeDamage(b.damage, b.owner, b.hitZone);
        playSound('hit', e.x, e.y, 0.15);

        // Hit marker for player
        if (b.owner.isPlayer) {
          const hm = document.getElementById('hit-marker');
          hm.classList.add('show');
          setTimeout(() => hm.classList.remove('show'), 100);
        }

        // Blood particle
        for (let j = 0; j < 3; j++) {
          particles.push(createParticle(b.x, b.y, '#ff0000', 2));
        }

        hitEntity = true;
        break;
      }
    }
    if (hitEntity) {
      bullets.splice(i, 1);
      continue;
    }

    // World bounds
    if (b.x < 0 || b.x > WORLD_W || b.y < 0 || b.y > WORLD_H) {
      bullets.splice(i, 1);
    }
  }
}

// ============================================================
// PARTICLE UPDATE
// ============================================================
function updateParticles(dt) {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx * dt * 60;
    p.y += p.vy * dt * 60;
    p.life -= dt;

    if (p.type === 'smoke_cloud') {
      p.radius += dt * 2;
      p.vx *= 0.99;
      p.vy *= 0.99;
    }

    if (p.life <= 0) {
      particles.splice(i, 1);
    }
  }
}

// ============================================================
// VEHICLE UPDATE
// ============================================================
function updateVehicles(dt) {
  for (const v of vehicles) {
    v.update(dt);

    // Vehicle combat
    for (const occ of v.occupants) {
      if (occ.isPlayer && mouse.down) {
        const w = occ.getWeapon();
        if (w.type !== 'melee' && Date.now() - occ.lastShot >= w.fireRate) {
          occ.shoot(v.x + Math.cos(v.angle) * 20, v.y + Math.sin(v.angle) * 20);
        }
      }
    }
  }
}

// ============================================================
// INPUT HANDLING
// ============================================================
window.addEventListener('keydown', e => {
  keys[e.code] = true;
  e.preventDefault();
});
window.addEventListener('keyup', e => {
  keys[e.code] = false;
});
window.addEventListener('mousemove', e => {
  mouse.x = e.clientX;
  mouse.y = e.clientY;
});
window.addEventListener('mousedown', e => {
  mouse.down = true;
});
window.addEventListener('mouseup', e => {
  mouse.down = false;
});
window.addEventListener('contextmenu', e => e.preventDefault());

// ============================================================
// GAME LOOP
// ============================================================
let lastTime = 0;

function gameLoop(timestamp) {
  if (!gameRunning) return;

  const dt = Math.min((timestamp - lastTime) / 1000, 0.05);
  lastTime = timestamp;
  gameTime += dt;

  // Update
  updatePlayer(dt);
  updateZone(dt);
  updateRedZone(dt);
  updateWeather(dt);
  updateBullets(dt);
  updateParticles(dt);
  updateVehicles(dt);

  // Update bots
  for (const bot of entities) {
    if (bot.isBot && bot.alive) {
      updateBotAI(bot, dt);
      bot.update(dt);
    }
  }

  // Update player
  if (player.alive) {
    player.update(dt);
    playerStats.timeAlive += dt;
  }

  // Check win/lose
  const aliveCount = entities.filter(e => e.alive).length;
  if (!player.alive) {
    showDeathScreen();
    gameRunning = false;
    return;
  }
  if (aliveCount <= 1 && player.alive) {
    showMessage('🏆 VICTORY ROYALE! 🏆', 5000);
    setTimeout(() => {
      showDeathScreen(true);
      gameRunning = false;
    }, 5000);
  }

  // Render
  render();

  requestAnimationFrame(gameLoop);
}

function showDeathScreen(victory = false) {
  const screen = document.getElementById('death-screen');
  screen.style.display = 'flex';
  document.getElementById('death-title').textContent = victory ? '🏆 VICTORY ROYALE!' : 'ELIMINATED';
  document.getElementById('death-title').style.color = victory ? '#ffaa00' : '#ff4444';
  document.getElementById('death-reason').textContent = victory ?
    'You are the last one standing!' :
    (player.dbno ? 'Bled out after being knocked down.' : 'You were eliminated.');
  document.getElementById('death-stats').innerHTML =
    `Kills: ${playerStats.kills} • Damage Dealt: ${Math.round(playerStats.damageDealt)} • Time: ${Math.floor(playerStats.timeAlive)}s • Placement: #${entities.filter(e => e.alive).length}`;
}

// ============================================================
// START GAME
// ============================================================
function startGame() {
  document.getElementById('start-screen').style.display = 'none';
  initAudio();

  generateWorld();
  createPlayer();

  // Create bots
  const botNames = ['Shadow', 'Viper', 'Ghost', 'Storm', 'Blaze', 'Frost', 'Thunder', 'Hawk',
    'Wolf', 'Eagle', 'Snake', 'Cobra', 'Phoenix', 'Titan', 'Raven', 'Shadow',
    'Nova', 'Apex', 'Crimson', 'Iron', 'Steel', 'Blade', 'Venom', 'Rogue',
    'Phantom', 'Spectre', 'Wraith', 'Reaper', 'Havoc', 'Chaos', 'Fury',
    'Raptor', 'Falcon', 'Panther', 'Lynx', 'Jaguar', 'Tiger', 'Bear', 'Lion',
    'Eagle', 'Hawk', 'Osprey', 'Condor', 'Vulture', 'Raven', 'Crow', 'Magpie',
    'Sparrow', 'Finch', 'Wren', 'Thrush', 'Robin', 'Jay', 'Lark', 'Dove'];

  for (let i = 0; i < 59; i++) {
    const bx = 200 + Math.random() * (WORLD_W - 400);
    const by = 200 + Math.random() * (WORLD_H - 400);
    entities.push(createBot(botNames[i % botNames.length], bx, by));
  }
  entities.push(player);

  gameRunning = true;
  lastTime = performance.now();
  showMessage('DROP IN! Collect weapons and survive!', 3000);
  requestAnimationFrame(gameLoop);
}

// ============================================================
// INITIAL RENDER
// ============================================================
function renderStartScreen() {
  CTX.fillStyle = '#0a0a1a';
  CTX.fillRect(0, 0, W, H);

  // Animated background
  const time = Date.now() / 1000;
  for (let i = 0; i < 50; i++) {
    const x = (Math.sin(time + i * 0.5) * 0.5 + 0.5) * W;
    const y = (Math.cos(time * 0.7 + i * 0.3) * 0.5 + 0.5) * H;
    CTX.fillStyle = `rgba(255,68,68,${0.02 + Math.sin(time + i) * 0.01})`;
    CTX.beginPath();
    CTX.arc(x, y, 2 + Math.sin(time + i) * 1, 0, Math.PI * 2);
    CTX.fill();
  }

  requestAnimationFrame(renderStartScreen);
}
renderStartScreen();
