<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const minimapCanvas = document.getElementById('minimap');
const minimapCtx = minimapCanvas.getContext('2d');
const speedLinesCanvas = document.getElementById('speed-lines');
const speedLinesCtx = speedLinesCanvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
speedLinesCanvas.width = window.innerWidth;
speedLinesCanvas.height = window.innerHeight;

window.addEventListener('resize', () => {
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
speedLinesCanvas.width = window.innerWidth;
speedLinesCanvas.height = window.innerHeight;
});

// Track definition - a circuit path
const trackPoints = [];
const trackWidth = 120;
const numTrackPoints = 200;
const trackRadiusX = 1200;
const trackRadiusY = 800;
const trackOffsetX = 1500;
const trackOffsetY = 1000;

for (let i = 0; i < numTrackPoints; i++) {
const t = (i / numTrackPoints) * Math.PI * 2;
const x = trackOffsetX + Math.cos(t) * trackRadiusX + Math.cos(t * 2) * 200 + Math.sin(t * 3) * 100;
const y = trackOffsetY + Math.sin(t) * trackRadiusY + Math.sin(t * 2) * 150 + Math.cos(t * 3) * 80;
trackPoints.push({ x, y });
}

// Calculate track normals and cumulative distance
const trackData = [];
let totalTrackLength = 0;
for (let i = 0; i < numTrackPoints; i++) {
const next = trackPoints[(i + 1) % numTrackPoints];
const prev = trackPoints[(i - 1 + numTrackPoints) % numTrackPoints];
const dx = next.x - prev.x;
const dy = next.y - prev.y;
const len = Math.sqrt(dx * dx + dy * dy);
const nx = -dy / len;
const ny = dx / len;
totalTrackLength += len;
trackData.push({
x: trackPoints[i].x, y: trackPoints[i].y,
nx, ny, len, angle: Math.atan2(dy, dx)
});
}

// Power-up types
const POWERUP_TYPES = [
{ name: 'missile', color: '#f00', icon: '🚀', desc: 'Missile' },
{ name: 'shield', color: '#0ff', icon: '🛡️', desc: 'Bouclier' },
{ name: 'boost', color: '#0f0', icon: '⚡', desc: 'Turbo' },
{ name: 'mine', color: '#ff0', icon: '💣', desc: 'Mine' },
{ name: 'oil', color: '#888', icon: '🛢️', desc: 'Huile' },
{ name: 'shield2', color: '#f0f', icon: '🔮', desc: 'Anti-missile' }
];

// Kart colors
const KART_COLORS = [
{ body: '#e00', accent: '#fff', name: 'Rouge' },
{ body: '#00e', accent: '#fff', name: 'Bleu' },
{ body: '#0a0', accent: '#fff', name: 'Vert' },
{ body: '#fa0', accent: '#000', name: 'Orange' },
{ body: '#f0f', accent: '#fff', name: 'Violet' },
{ body: '#0ff', accent: '#000', name: 'Cyan' },
{ body: '#ff0', accent: '#000', name: 'Jaune' }
];

// Game state
let gameState = 'menu'; // menu, countdown, racing, finished
let gameTime = 0;
let totalLaps = 3;
let playerKart = null;
let aiKarts = [];
let projectiles = [];
let powerups = [];
let mines = [];
let particles = [];
let oilSpots = [];
let explosions = [];
let camera = { x: 0, y: 0 };
let keys = {};
let lastTime = 0;
let countdownTimer = 0;
let raceStartTime = 0;
let finishOrder = [];
let screenShake = 0;
let turboMode = false;
let turboTimer = 0;
let invincibleTimer = 0;
let antiMissileTimer = 0;

// Track power-up spawn points
const powerupSpawnPoints = [];
for (let i = 0; i < 20; i++) {
const idx = Math.floor((i / 20) * numTrackPoints);
powerupSpawnPoints.push({
trackIdx: idx,
offset: (Math.random() - 0.5) * trackWidth * 0.6,
type: POWERUP_TYPES[Math.floor(Math.random() * POWERUP_TYPES.length)],
respawnTime: 0
});
}

function createKart(colorIdx, isPlayer) {
const startIdx = 0;
const td = trackData[startIdx];
const offset = (isPlayer ? 0 : (colorIdx - 1) * 30) * td.nx;
const offset2 = (isPlayer ? 0 : (colorIdx - 1) * 30) * td.ny;
return {
x: td.x + offset,
y: td.y + offset2,
angle: td.angle,
speed: 0,
maxSpeed: isPlayer ? 12 : 10 + Math.random() * 2,
accel: 0.15,
turnSpeed: 0.04,
trackIdx: startIdx,
trackProgress: 0,
lap: 0,
position: 1,
color: KART_COLORS[colorIdx],
isPlayer,
powerups: [],
currentPowerup: null,
projectileCooldown: 0,
hitTimer: 0,
spinTimer: 0,
boostTimer: 0,
alive: true,
aiTargetIdx: 5 + Math.floor(Math.random() * 10),
aiSkill: 0.7 + Math.random() * 0.3,
lastTrackIdx: startIdx,
crossedStart: false
};
}

function initGame() {
playerKart = createKart(0, true);
aiKarts = [];
for (let i = 1; i < 7; i++) {
aiKarts.push(createKart(i, false));
}
projectiles = [];
powerups = [];
mines = [];
particles = [];
oilSpots = [];
explosions = [];
finishOrder = [];
gameTime = 0;
turboMode = false;
turboTimer = 0;
invincibleTimer = 0;
antiMissileTimer = 0;
screenShake = 0;

// Spawn initial power-ups
for (let i = 0; i < 10; i++) {
const sp = powerupSpawnPoints[i];
const td = trackData[sp.trackIdx];
powerups.push({
x: sp.x || (td.x + sp.offset * td.nx),
y: sp.y || (td.y + sp.offset * td.ny),
type: sp.type,
active: true,
trackIdx: sp.trackIdx,
offset: sp.offset,
respawnTime: 0
});
}
}

function getClosestTrackIndex(x, y) {
let minDist = Infinity;
let bestIdx = 0;
for (let i = 0; i < numTrackPoints; i++) {
const dx = x - trackData[i].x;
const dy = y - trackData[i].y;
const dist = dx * dx + dy * dy;
if (dist < minDist) {
minDist = dist;
bestIdx = i;
}
}
return bestIdx;
}

function isOnTrack(x, y) {
const idx = getClosestTrackIndex(x, y);
const td = trackData[idx];
const dx = x - td.x;
const dy = y - td.y;
const dist = Math.sqrt(dx * dx + dy * dy);
return dist < trackWidth * 0.7;
}

function getTrackPosition(kart) {
const idx = getClosestTrackIndex(kart.x, kart.y);
const td = trackData[idx];
const dx = kart.x - td.x;
const dy = kart.y - td.y;
const dist = Math.sqrt(dx * dx + dy * dy);
return { idx, dist, onTrack: dist < trackWidth * 0.7 };
}

function updateKart(kart, dt) {
if (!kart.alive) return;

if (kart.spinTimer > 0) {
kart.spinTimer -= dt;
kart.angle += 0.3;
kart.speed *= 0.95;
if (kart.spinTimer <= 0) kart.speed = 2;
return;
}

if (kart.hitTimer > 0) kart.hitTimer -= dt;
if (kart.projectileCooldown > 0) kart.projectileCooldown -= dt;
if (kart.boostTimer > 0) {
kart.boostTimer -= dt;
kart.speed = Math.min(kart.speed + 0.2, kart.maxSpeed * 1.5);
}

const currentMaxSpeed = kart.boostTimer > 0 ? kart.maxSpeed * 1.5 : kart.maxSpeed;

if (kart.isPlayer) {
// Player controls
if (keys['ArrowUp'] || keys['w']) {
kart.speed = Math.min(kart.speed + kart.accel, currentMaxSpeed);
}
if (keys['ArrowDown'] || keys['s']) {
kart.speed = Math.max(kart.speed - kart.accel * 1.5, -currentMaxSpeed * 0.3);
}
if (keys['ArrowLeft'] || keys['a']) {
kart.angle -= kart.turnSpeed * (0.5 + Math.abs(kart.speed) / currentMaxSpeed * 0.5);
}
if (keys['ArrowRight'] || keys['d']) {
kart.angle += kart.turnSpeed * (0.5 + Math.abs(kart.speed) / currentMaxSpeed * 0.5);
}

if (keys['Shift']) {
turboMode = true;
turboTimer += dt;
if (turboTimer > 3) {
turboTimer = 0;
kart.speed = Math.min(kart.speed + 5, currentMaxSpeed * 1.8);
screenShake = 5;
}
} else {
turboMode = false;
turboTimer = 0;
}
} else {
// AI logic
updateAI(kart, dt);
}

// Off-track penalty
const pos = getTrackPosition(kart);
if (!pos.onTrack && kart.speed > 3) {
kart.speed *= 0.96;
}

// Oil spot collision
for (const oil of oilSpots) {
const dx = kart.x - oil.x;
const dy = kart.y - oil.y;
const dist = Math.sqrt(dx * dx + dy * dy);
if (dist < 30) {
kart.spinTimer = 1.5;
kart.speed *= 0.3;
oil.life -= dt;
if (oil.life <= 0) oil.active = false;
}
}

// Move
kart.x += Math.cos(kart.angle) * kart.speed;
kart.y += Math.sin(kart.angle) * kart.speed;

// Update track progress
kart.lastTrackIdx = kart.trackIdx;
kart.trackIdx = pos.idx;

// Lap detection
const startIdx = 0;
if (kart.lastTrackIdx > numTrackPoints * 0.9 && kart.trackIdx < numTrackPoints * 0.1) {
kart.lap++;
if (kart.lap >= totalLaps && !finishOrder.includes(kart)) {
finishOrder.push(kart);
if (kart.isPlayer) {
gameState = 'finished';
showMessage('🏁 ARRIVÉE !\nPosition: ' + finishOrder.indexOf(kart) + '/8');
}
}
}

// Collect power-ups
if (kart.currentPowerup === null) {
for (const pu of powerups) {
if (!pu.active) continue;
const dx = kart.x - pu.x;
const dy = kart.y - pu.y;
if (Math.sqrt(dx * dx + dy * dy) < 35) {
pu.active = false;
pu.respawnTime = 8;
kart.currentPowerup = pu.type;
break;
}
}
}

// Check mines
for (const mine of mines) {
if (!mine.active) continue;
const dx = kart.x - mine.x;
const dy = kart.y - mine.y;
if (Math.sqrt(dx * dx + dy * dy) < 25) {
mine.active = false;
explosion(mine.x, mine.y, 60);
if (kart.isPlayer) {
kart.spinTimer = 2;
kart.speed *= 0.2;
screenShake = 10;
} else {
kart.spinTimer = 2;
kart.speed *= 0.2;
}
}
}

// Update projectiles
for (const proj of projectiles) {
proj.x += Math.cos(proj.angle) * proj.speed;
proj.y += Math.sin(proj.angle) * proj.speed;
proj.life -= dt;

for (const other of [...aiKarts, ...(kart.isPlayer ? [playerKart] : [])]) {
if (other === kart || !other.alive) continue;
const dx = other.x - proj.x;
const dy = other.y - proj.y;
if (Math.sqrt(dx * dx + dy * dy) < 25) {
proj.life = 0;
if (invincibleTimer > 0 || antiMissileTimer > 0) {
// Shielded
particles.push({ x: proj.x, y: proj.y, vx: 0, vy: 0, life: 0.5, color: '#0ff', size: 20 });
} else {
explosion(proj.x, proj.y, 40);
other.spinTimer = 1.5;
other.speed *= 0.3;
screenShake = 5;
}
break;
}
}
}
projectiles = projectiles.filter(p => p.life > 0);

// Update particles
for (const p of particles) {
p.x += p.vx;
p.y += p.vy;
p.life -= dt;
p.vx *= 0.98;
p.vy *= 0.98;
}
particles = particles.filter(p => p.life > 0);

// Update oil
for (const oil of oilSpots) {
if (oil.active) oil.life -= dt;
}
oilSpots = oilSpots.filter(o => o.life > 0);

// Update mines
for (const mine of mines) {
if (mine.active) {
mine.timer -= dt;
if (mine.timer <= 0) {
mine.active = false;
explosion(mine.x, mine.y, 50);
}
}
}
mines = mines.filter(m => m.active);

// Update explosions
for (const exp of explosions) {
exp.radius += 3;
exp.life -= dt;
}
explosions = explosions.filter(e => e.life > 0);

// Respawn power-ups
for (const pu of powerups) {
if (!pu.active) {
pu.respawnTime -= dt;
if (pu.respawnTime <= 0) {
pu.active = true;
}
}
}

// Invincibility timers
if (invincibleTimer > 0) invincibleTimer -= dt;
if (antiMissileTimer > 0) antiMissileTimer -= dt;

// Speed particles
if (Math.abs(kart.speed) > 8) {
for (let i = 0; i < 2; i++) {
particles.push({
x: kart.x - Math.cos(kart.angle) * 20 + (Math.random() - 0.5) * 10,
y: kart.y - Math.sin(kart.angle) * 20 + (Math.random() - 0.5) * 10,
vx: -Math.cos(kart.angle) * 3 + (Math.random() - 0.5) * 2,
vy: -Math.sin(kart.angle) * 3 + (Math.random() - 0.5) * 2,
life: 0.5,
color: turboMode ? '#0ff' : '#f80',
size: 3 + Math.random() * 3
});
}
}
}

function updateAI(kart, dt) {
const targetIdx = kart.aiTargetIdx;
const td = trackData[targetIdx];

// Predict position ahead
const aheadIdx = (targetIdx + 15) % numTrackPoints;
const aheadTd = trackData[aheadIdx];

const targetX = aheadTd.x;
const targetY = aheadTd.y;

const dx = targetX - kart.x;
const dy = targetY - kart.y;
const targetAngle = Math.atan2(dy, dx);

let angleDiff = targetAngle - kart.angle;
while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

kart.angle += Math.sign(angleDiff) * Math.min(Math.abs(angleDiff), kart.turnSpeed * kart.aiSkill * (0.5 + Math.abs(kart.speed) / kart.maxSpeed * 0.5));

// Speed control
const distToTarget = Math.sqrt(dx * dx + dy * dy);
const desiredSpeed = kart.maxSpeed * (distToTarget > 200 ? 1 : 0.7);

if (kart.speed < desiredSpeed) {
kart.speed = Math.min(kart.speed + kart.accel * kart.aiSkill, desiredSpeed);
} else {
kart.speed = Math.max(kart.speed - kart.accel * 0.5, desiredSpeed * 0.8);
}

// Use power-ups
if (kart.currentPowerup && kart.projectileCooldown <= 0) {
useAIPowerup(kart);
}

// Avoid other karts
for (const other of [...aiKarts, playerKart]) {
if (other === kart || !other.alive) continue;
const odx = other.x - kart.x;
const ody = other.y - kart.y;
const odist = Math.sqrt(odx * odx + ody * ody);
if (odist < 80 && odist > 0) {
const avoidAngle = Math.atan2(ody, odx);
kart.angle += (avoidAngle - kart.angle) * 0.05;
}
}

// Random skill variation
if (Math.random() < 0.01) {
kart.aiTargetIdx = (kart.aiTargetIdx + Math.floor(Math.random() * 20 - 10) + numTrackPoints) % numTrackPoints;
}
}

function useAIPowerup(kart) {
const type = kart.currentPowerup.name;
if (type === 'missile') {
const target = playerKart;
const angle = Math.atan2(target.y - kart.y, target.x - kart.x);
projectiles.push({
x: kart.x, y: kart.y,
angle: angle,
speed: 8,
life: 3,
owner: kart
});
kart.projectileCooldown = 1;
kart.currentPowerup = null;
} else if (type === 'mine') {
mines.push({
x: kart.x, y: kart.y,
life: 10,
active: true,
timer: 3
});
kart.currentPowerup = null;
} else if (type === 'boost') {
kart.boostTimer = 3;
kart.currentPowerup = null;
} else if (type === 'shield') {
invincibleTimer = 5;
kart.currentPowerup = null;
} else if (type === 'oil') {
oilSpots.push({
x: kart.x + Math.cos(kart.angle) * 50,
y: kart.y + Math.sin(kart.angle) * 50,
life: 8,
active: true
});
kart.currentPowerup = null;
} else if (type === 'shield2') {
antiMissileTimer = 5;
kart.currentPowerup = null;
}
}

function shoot() {
if (playerKart.currentPowerup === null) return;
const type = playerKart.currentPowerup.name;

if (type === 'missile') {
// Find nearest opponent
let nearest = null;
let nearDist = Infinity;
for (const ai of aiKarts) {
if (!ai.alive) continue;
const d = Math.sqrt((ai.x - playerKart.x) ** 2 + (ai.y - playerKart.y) ** 2);
if (d < nearDist) {
nearDist = d;
nearest = ai;
}
}
if (nearest) {
const angle = Math.atan2(nearest.y - playerKart.y, nearest.x - playerKart.x);
projectiles.push({
x: playerKart.x, y: playerKart.y,
angle: angle,
speed: 10,
life: 4,
owner: playerKart
});
playerKart.projectileCooldown = 0.5;
}
playerKart.currentPowerup = null;
} else if (type === 'mine') {
const angle = playerKart.angle;
mines.push({
x: playerKart.x + Math.cos(angle) * 40,
y: playerKart.y + Math.sin(angle) * 40,
life: 10,
active: true,
timer: 2
});
playerKart.currentPowerup = null;
} else if (type === 'boost') {
playerKart.boostTimer = 4;
playerKart.currentPowerup = null;
} else if (type === 'shield') {
invincibleTimer = 6;
playerKart.currentPowerup = null;
} else if (type === 'oil') {
const angle = playerKart.angle;
for (let i = -2; i <= 2; i++) {
const a = angle + i * 0.3;
oilSpots.push({
x: playerKart.x + Math.cos(a) * 60,
y: playerKart.y + Math.sin(a) * 60,
life: 10,
active: true
});
}
playerKart.currentPowerup = null;
} else if (type === 'shield2') {
antiMissileTimer = 6;
playerKart.currentPowerup = null;
}
}

function explosion(x, y, radius) {
explosions.push({ x, y, radius: 10, life: 0.5 });
for (let i = 0; i < 20; i++) {
const angle = Math.random() * Math.PI * 2;
const speed = Math.random() * 5 + 2;
particles.push({
x, y,
vx: Math.cos(angle) * speed,
vy: Math.sin(angle) * speed,
life: 1 + Math.random(),
color: ['#f00', '#ff0', '#f80', '#fff'][Math.floor(Math.random() * 4)],
size: 2 + Math.random() * 4
});
}
screenShake = Math.max(screenShake, radius / 10);
}

function showMessage(text) {
const msg = document.getElementById('message');
msg.textContent = text;
msg.style.display = 'block';
setTimeout(() => { msg.style.display = 'none'; }, 3000);
}

function updatePositions() {
const allKarts = [playerKart, ...aiKarts];
allKarts.sort((a, b) => {
if (a.lap !== b.lap) return b.lap - a.lap;
if (b.lap >= totalLaps && a.lap >= totalLaps) return 0;
return b.trackIdx - a.trackIdx;
});
allKarts.forEach((k, i) => k.position = i + 1);
}

function drawTrack() {
// Draw track surface
ctx.beginPath();
for (let i = 0; i <= numTrackPoints; i++) {
const idx = i % numTrackPoints;
const td = trackData[idx];
const lx = td.x + td.nx * trackWidth * 0.5;
const ly = td.y + td.ny * trackWidth * 0.5;
if (i === 0) ctx.moveTo(lx, ly);
else ctx.lineTo(lx, ly);
}
ctx.closePath();
ctx.strokeStyle = '#555';
ctx.lineWidth = trackWidth;
ctx.lineCap = 'round';
ctx.lineJoin = 'round';
ctx.stroke();

// Track surface
ctx.beginPath();
for (let i = 0; i <= numTrackPoints; i++) {
const idx = i % numTrackPoints;
const td = trackData[idx];
const lx = td.x + td.nx * trackWidth * 0.48;
const ly = td.y + td.ny * trackWidth * 0.48;
if (i === 0) ctx.moveTo(lx, ly);
else ctx.lineTo(lx, ly);
}
ctx.closePath();
ctx.strokeStyle = '#3a3a3a';
ctx.lineWidth = trackWidth * 0.96;
ctx.stroke();

// Center dashed line
ctx.setLineDash([20, 20]);
ctx.beginPath();
for (let i = 0; i <= numTrackPoints; i++) {
const idx = i % numTrackPoints;
const td = trackData[idx];
if (i === 0) ctx.moveTo(td.x, td.y);
else ctx.lineTo(td.x, td.y);
}
ctx.closePath();
ctx.strokeStyle = '#555';
ctx.lineWidth = 2;
ctx.stroke();
ctx.setLineDash([]);

// Track borders
for (let side = -1; side <= 1; side += 2) {
ctx.beginPath();
for (let i = 0; i <= numTrackPoints; i++) {
const idx = i % numTrackPoints;
const td = trackData[idx];
const lx = td.x + td.nx * trackWidth * 0.5 * side;
const ly = td.y + td.ny * trackWidth * 0.5 * side;
if (i === 0) ctx.moveTo(lx, ly);
else ctx.lineTo(lx, ly);
}
ctx.closePath();
ctx.strokeStyle = side === -1 ? '#fff' : '#fff';
ctx.lineWidth = 4;
ctx.stroke();
}

// Start/finish line
const startTd = trackData[0];
ctx.beginPath();
ctx.moveTo(
startTd.x + startTd.nx * trackWidth * 0.5,
startTd.y + startTd.ny * trackWidth * 0.5
);
ctx.lineTo(
startTd.x - startTd.nx * trackWidth * 0.5,
startTd.y - startTd.ny * trackWidth * 0.5
);
ctx.strokeStyle = '#fff';
ctx.lineWidth = 6;
ctx.stroke();

// Checkered pattern on start line
for (let i = -5; i <= 5; i++) {
const cx = startTd.x + startTd.nx * i * 10;
const cy = startTd.y + startTd.ny * i * 10;
ctx.fillStyle = i % 2 === 0 ? '#fff' : '#000';
ctx.fillRect(cx - 5, cy - 5, 10, 10);
}

// Grass
ctx.fillStyle = '#2a5a1a';
ctx.fillRect(0, 0, canvas.width, canvas.height);

// Grass texture
ctx.fillStyle = '#255515';
for (let i = 0; i < 200; i++) {
const gx = ((i * 137.5) % canvas.width + camera.x * 0.3) % canvas.width;
const gy = ((i * 251.3) % canvas.height + camera.y * 0.3) % canvas.height;
ctx.fillRect(gx, gy, 3, 8);
}
}

function drawKart(kart) {
if (!kart.alive) return;

const screenX = kart.x - camera.x + canvas.width / 2;
const screenY = kart.y - camera.y + canvas.height / 2;

// Skip if off screen
if (screenX < -50 || screenX > canvas.width + 50 || screenY < -50 || screenY > canvas.height + 50) return;

ctx.save();
ctx.translate(screenX, screenY);
ctx.rotate(kart.angle);

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(3, 3, 18, 10, 0, 0, Math.PI * 2);
ctx.fill();

// Kart body
const bodyColor = kart.hitTimer > 0 ? '#fff' : kart.color.body;
ctx.fillStyle = bodyColor;
ctx.beginPath();
ctx.roundRect(-18, -10, 36, 20, 5);
ctx.fill();

// Accent stripe
ctx.fillStyle = kart.color.accent;
ctx.fillRect(-5, -10, 10, 20);

// Front
ctx.fillStyle = bodyColor;
ctx.beginPath();
ctx.moveTo(18, -8);
ctx.lineTo(25, 0);
ctx.lineTo(18, 8);
ctx.fill();

// Wheels
ctx.fillStyle = '#222';
ctx.fillRect(-14, -14, 10, 5);
ctx.fillRect(-14, 9, 10, 5);
ctx.fillRect(8, -14, 10, 5);
ctx.fillRect(8, 9, 10, 5);

// Driver helmet
ctx.fillStyle = kart.color.accent;
ctx.beginPath();
ctx.arc(0, 0, 6, 0, Math.PI * 2);
ctx.fill();

// Shield effect
if (invincibleTimer > 0 && kart.isPlayer) {
ctx.strokeStyle = '#0ff';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.arc(0, 0, 22, 0, Math.PI * 2);
ctx.stroke();
}

if (antiMissileTimer > 0 && kart.isPlayer) {
ctx.strokeStyle = '#f0f';
ctx.lineWidth = 2;
ctx.setLineDash([5, 5]);
ctx.beginPath();
ctx.arc(0, 0, 25, 0, Math.PI * 2);
ctx.stroke();
ctx.setLineDash([]);
}

// Boost effect
if (kart.boostTimer > 0) {
ctx.fillStyle = '#f80';
ctx.beginPath();
ctx.moveTo(-25, -5);
ctx.lineTo(-35 - Math.random() * 10, 0);
ctx.lineTo(-25, 5);
ctx.fill();
}

ctx.restore();

// Position indicator for AI
if (!kart.isPlayer) {
ctx.fillStyle = kart.color.body;
ctx.beginPath();
ctx.arc(screenX, screenY - 28, 4, 0, Math.PI * 2);
ctx.fill();
}
}

function drawPowerups() {
for (const pu of powerups) {
if (!pu.active) continue;
const screenX = pu.x - camera.x + canvas.width / 2;
const screenY = pu.y - camera.y + canvas.height / 2;

if (screenX < -30 || screenX > canvas.width + 30 || screenY < -30 || screenY > canvas.height + 30) continue;

const pulse = Math.sin(gameTime * 5) * 0.2 + 0.8;

// Glow
ctx.beginPath();
ctx.arc(screenX, screenY, 20 * pulse, 0, Math.PI * 2);
ctx.fillStyle = pu.type.color + '33';
ctx.fill();

// Orb
ctx.beginPath();
ctx.arc(screenX, screenY, 12, 0, Math.PI * 2);
ctx.fillStyle = pu.type.color;
ctx.fill();
ctx.strokeStyle = '#fff';
ctx.lineWidth = 2;
ctx.stroke();

// Icon
ctx.fillStyle = '#fff';
ctx.font = '14px Arial';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText(pu.type.icon, screenX, screenY);
}
}

function drawProjectiles() {
for (const proj of projectiles) {
const screenX = proj.x - camera.x + canvas.width / 2;
const screenY = proj.y - camera.y + canvas.height / 2;

ctx.beginPath();
ctx.arc(screenX, screenY, 5, 0, Math.PI * 2);
ctx.fillStyle = '#f00';
ctx.fill();
ctx.beginPath();
ctx.arc(screenX, screenY, 8, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(255,100,0,0.3)';
ctx.fill();
}
}

function drawMines() {
for (const mine of mines) {
if (!mine.active) continue;
const screenX = mine.x - camera.x + canvas.width / 2;
const screenY = mine.y - camera.y + canvas.height / 2;

const pulse = Math.sin(gameTime * 8) * 0.3 + 0.7;
ctx.beginPath();
ctx.arc(screenX, screenY, 10 * pulse, 0, Math.PI * 2);
ctx.fillStyle = '#ff0';
ctx.fill();
ctx.strokeStyle = '#f80';
ctx.lineWidth = 2;
ctx.stroke();

ctx.fillStyle = '#000';
ctx.font = '10px Arial';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText('💣', screenX, screenY);
}
}

function drawOilSpots() {
for (const oil of oilSpots) {
if (!oil.active) continue;
const screenX = oil.x - camera.x + canvas.width / 2;
const screenY = oil.y - camera.y + canvas.height / 2;

ctx.beginPath();
ctx.arc(screenX, screenY, 20, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(50,50,50,0.5)';
ctx.fill();
ctx.strokeStyle = 'rgba(80,80,80,0.5)';
ctx.lineWidth = 1;
ctx.stroke();
}
}

function drawParticles() {
for (const p of particles) {
const screenX = p.x - camera.x + canvas.width / 2;
const screenY = p.y - camera.y + canvas.height / 2;
ctx.globalAlpha = p.life;
ctx.beginPath();
ctx.arc(screenX, screenY, p.size, 0, Math.PI * 2);
ctx.fillStyle = p.color;
ctx.fill();
}
ctx.globalAlpha = 1;
}

function drawExplosions() {
for (const exp of explosions) {
const screenX = exp.x - camera.x + canvas.width / 2;
const screenY = exp.y - camera.y + canvas.height / 2;
ctx.beginPath();
ctx.arc(screenX, screenY, exp.radius, 0, Math.PI * 2);
ctx.fillStyle = `rgba(255, ${Math.floor(100 + exp.life * 100)}, 0, ${exp.life})`;
ctx.fill();
}
}

function drawMinimap() {
minimapCtx.fillStyle = '#1a3a0a';
minimapCtx.fillRect(0, 0, 180, 180);

// Draw track on minimap
const mapScale = 0.06;
const mapOffsetX = 90;
const mapOffsetY = 90;

minimapCtx.beginPath();
for (let i = 0; i <= numTrackPoints; i++) {
const idx = i % numTrackPoints;
const td = trackData[idx];
const mx = td.x * mapScale + mapOffsetX;
const my = td.y * mapScale + mapOffsetY;
if (i === 0) minimapCtx.moveTo(mx, my);
else minimapCtx.lineTo(mx, my);
}
minimapCtx.closePath();
minimapCtx.strokeStyle = '#666';
minimapCtx.lineWidth = 4;
minimapCtx.stroke();

// Draw karts
const allKarts = [playerKart, ...aiKarts];
for (const kart of allKarts) {
const mx = kart.x * mapScale + mapOffsetX;
const my = kart.y * mapScale + mapOffsetY;
minimapCtx.beginPath();
minimapCtx.arc(mx, my, kart.isPlayer ? 4 : 3, 0, Math.PI * 2);
minimapCtx.fillStyle = kart.isPlayer ? '#0ff' : kart.color.body;
minimapCtx.fill();
}
}

function updateHUD() {
document.getElementById('speed-val').textContent = Math.abs(Math.round(playerKart.speed * 20));
document.getElementById('pos-val').textContent = playerKart.position;

const elapsed = Math.floor(gameTime);
const mins = Math.floor(elapsed / 60);
const secs = elapsed % 60;
document.getElementById('time-val').textContent = `${mins}:${secs.toString().padStart(2, '0')}`;

document.getElementById('lap-hud-val').textContent = `${Math.min(playerKart.lap + 1, totalLaps)}/${totalLaps}`;
document.getElementById('lap-val').textContent = `${Math.min(playerKart.lap + 1, totalLaps)} / ${totalLaps}`;

// Power-up display
for (let i = 1; i <= 3; i++) {
