slot.classList.remove('active');
}
}

// Leaderboard
const allKarts = [playerKart, ...aiKarts];
allKarts.sort((a, b) => a.position - b.position);
const lbRows = document.getElementById('lb-rows');
lbRows.innerHTML = '';
for (const kart of allKarts) {
const row = document.createElement('div');
row.className = 'lb-row' + (kart.isPlayer ? ' player' : '');
row.innerHTML = `<span>${kart.position}. ${kart.color.name}</span><span>L${Math.min(kart.lap + 1, totalLaps)}</span>`;
lbRows.appendChild(row);
}

// Speed lines effect
if (turboMode || playerKart.boostTimer > 0) {
speedLinesCanvas.style.opacity = '0.3';
speedLinesCtx.clearRect(0, 0, speedLinesCanvas.width, speedLinesCanvas.height);
speedLinesCtx.strokeStyle = '#0ff';
speedLinesCtx.lineWidth = 1;
for (let i = 0; i < 10; i++) {
const x = Math.random() * speedLinesCanvas.width;
const y = Math.random() * speedLinesCanvas.height;
speedLinesCtx.beginPath();
speedLinesCtx.moveTo(x, y);
speedLinesCtx.lineTo(x + (Math.random() - 0.5) * 20, y + 50 + Math.random() * 50);
speedLinesCtx.stroke();
}
} else {
speedLinesCanvas.style.opacity = '0';
}
}

function gameLoop(timestamp) {
const dt = Math.min((timestamp - lastTime) / 1000, 0.05);
lastTime = timestamp;

if (gameState === 'racing') {
gameTime += dt;

// Update all karts
updateKart(playerKart, dt);
for (const ai of aiKarts) {
updateKart(ai, dt);
}

updatePositions();

// Camera follow player
camera.x += (playerKart.x - camera.x) * 0.1;
camera.y += (playerKart.y - camera.y) * 0.1;

// Screen shake
if (screenShake > 0) screenShake *= 0.9;

// Draw
ctx.save();
if (screenShake > 0.5) {
ctx.translate(
(Math.random() - 0.5) * screenShake * 2,
(Math.random() - 0.5) * screenShake * 2
);
}

drawTrack();
drawOilSpots();
drawMines();
drawPowerups();
drawProjectiles();
drawParticles();
drawExplosions();

// Draw AI karts
for (const ai of aiKarts) drawKart(ai);
drawKart(playerKart);

ctx.restore();

drawMinimap();
updateHUD();

} else if (gameState === 'countdown') {
countdownTimer -= dt;
const cdEl = document.getElementById('countdown');
cdEl.style.display = 'block';
if (countdownTimer > 3) {
cdEl.textContent = '3';
cdEl.style.color = '#f00';
} else if (countdownTimer > 2) {
cdEl.textContent = '2';
cdEl.style.color = '#fa0';
} else if (countdownTimer > 1) {
cdEl.textContent = '1';
cdEl.style.color = '#0f0';
} else if (countdownTimer > 0) {
cdEl.textContent = 'PARTI !';
cdEl.style.color = '#0ff';
} else {
cdEl.style.display = 'none';
gameState = 'racing';
raceStartTime = gameTime;
}

// Still draw the scene
ctx.fillStyle = '#2a5a1a';
ctx.fillRect(0, 0, canvas.width, canvas.height);
drawTrack();
for (const ai of aiKarts) drawKart(ai);
drawKart(playerKart);
drawMinimap();

} else if (gameState === 'finished') {
ctx.fillStyle = 'rgba(0,0,0,0.5)';
ctx.fillRect(0, 0, canvas.width, canvas.height);

ctx.fillStyle = '#fff';
ctx.font = 'bold 40px Arial';
ctx.textAlign = 'center';
ctx.fillText('COURSE TERMINÉE', canvas.width / 2, canvas.height / 2 - 40);
ctx.font = '24px Arial';
ctx.fillText('Position: ' + playerKart.position + '/8', canvas.width / 2, canvas.height / 2 + 10);
ctx.font = '18px Arial';
ctx.fillStyle = '#aaa';
ctx.fillText('Appuyez sur ESPACE pour rejouer', canvas.width / 2, canvas.height / 2 + 50);

if (keys[' ']) {
initGame();
gameState = 'countdown';
countdownTimer = 3;
}
} else if (gameState === 'menu') {
// Animated background
ctx.fillStyle = '#0a0a2e';
ctx.fillRect(0, 0, canvas.width, canvas.height);

// Animated particles
for (let i = 0; i < 50; i++) {
const x = (i * 137.5 + gameTime * 50) % canvas.width;
const y = (i * 251.3) % canvas.height;
ctx.beginPath();
ctx.arc(x, y, 2, 0, Math.PI * 2);
ctx.fillStyle = `hsla(${(i * 30 + gameTime * 50) % 360}, 100%, 50%, 0.5)`;
ctx.fill();
}
}

requestAnimationFrame(gameLoop);
}

// Input handling
document.addEventListener('keydown', (e) => {
keys[e.key] = true;
if (e.key === ' ' && gameState === 'racing' && playerKart.currentPowerup) {
shoot();
e.preventDefault();
}
if (e.key === ' ') e.preventDefault();
});

document.addEventListener('keyup', (e) => {
keys[e.key] = false;
});

document.getElementById('start-btn').addEventListener('click', () => {
document.getElementById('start-screen').style.display = 'none';
initGame();
gameState = 'countdown';
countdownTimer = 3;
});

// Polyfill for roundRect
if (!CanvasRenderingContext2D.prototype.roundRect) {
CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
if (typeof r === 'number') r = [r, r, r, r];
this.moveTo(x + r[0], y);
this.lineTo(x + w - r[1], y);
this.quadraticCurveTo(x + w, y, x + w, y + r[1]);
this.lineTo(x + w, y + h - r[2]);
this.quadraticCurveTo(x + w, y + h, x + w - r[2], y + h);
this.lineTo(x + r[3], y + h);
this.quadraticCurveTo(x, y + h, x, y + h - r[3]);
this.lineTo(x, y + r[0]);
this.quadraticCurveTo(x, y, x + r[0], y);
this.closePath();
};
}

lastTime = performance.now();
requestAnimationFrame(gameLoop);
</script>
