<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const W = 900;
const H = 550;
canvas.width = W;
canvas.height = H;

// Game state
let gameState = 'menu'; // menu, playing, ended
let gameTime = 0;
let roundTimer = 90;
let timerText = '90';

// Particles
let particles = [];
let screenShake = { x: 0, y: 0, intensity: 0 };
let flashAlpha = 0;
let flashColor = '#fff';

// Keys
