#startScreen, #gameOverScreen, #winScreen { position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; flex-direction: column; justify-content: center; align-items: center; z-index: 20; background: rgba(0,0,0,0.85); color: white; }
#startScreen h1 { font-size: 48px; color: #e52521; text-shadow: 3px 3px 0 #7a1210; margin-bottom: 10px; }
#startScreen h2 { font-size: 20px; color: #fbd000; margin-bottom: 30px; }
.btn { padding: 15px 40px; font-size: 22px; background: #e52521; color: white; border: none; border-radius: 8px; cursor: pointer; margin: 8px; font-weight: bold; text-shadow: 1px 1px 0 #7a1210; transition: transform 0.1s; }
.btn:hover { transform: scale(1.05); background: #ff3333; }
.controls { font-size: 14px; color: #aaa; margin-top: 20px; text-align: center; line-height: 1.8; }
#gameOverScreen h1 { font-size: 42px; color: #e52521; margin-bottom: 15px; }
#winScreen h1 { font-size: 42px; color: #fbd000; margin-bottom: 15px; }
#finalScore { font-size: 24px; color: white; margin-bottom: 20px; }
.hidden { display: none !important; }
</style>
</head>
<body>

<div id="ui">
    <span>MARIO <br><span id="scoreDisplay">000000</span></span>
    <span>COINS <br>🪙<span id="coinDisplay">00</span></span>
    <span>WORLD <br>1-1</span>
    <span>TIME <br><span id="timeDisplay">400</span></span>
    <span>LIVES <br><span id="livesDisplay">3</span></span>
</div>

<canvas id="gameCanvas"></canvas>

<div id="startScreen">
    <h1>SUPER MARIO</h1>
    <h2>HTML5 Edition</h2>
    <button class="btn" onclick="startGame()">START GAME</button>
    <div class="controls">
        <strong>Controls:</strong><br>
        Arrow Keys / WASD - Move & Jump<br>
        Space - Jump (hold for higher)<br>
        Shift - Run
    </div>
</div>

<div id="gameOverScreen" class="hidden">
    <h1>GAME OVER</h1>
    <div id="finalScore">Score: 0</div>
    <button class="btn" onclick="restartGame()">TRY AGAIN</button>
</div>

<div id="winScreen" class="hidden">
    <h1>🎉 YOU WIN! 🎉</h1>
    <div id="winScore">Score: 0</div>
    <button class="btn" onclick="restartGame()">PLAY AGAIN</button>
</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Responsive canvas
const GAME_WIDTH = 800;
const GAME_HEIGHT = 500;
canvas.width = GAME_WIDTH;
canvas.height = GAME_HEIGHT;

// Scale canvas to fit screen
function resizeCanvas() {
    const scale = Math.min(window.innerWidth / GAME_WIDTH, window.innerHeight / GAME_HEIGHT);
    canvas.style.width = (GAME_WIDTH * scale) + 'px';
    canvas.style.height = (GAME_HEIGHT * scale) + 'px';
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

// Audio context
let audioCtx;
function initAudio() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
}

function playSound(freq, duration, type = 'square', volume = 0.15) {
    if (!audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
    gain.gain.setValueAtTime(volume, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + duration);
}

function playJumpSound() { playSound(400, 0.1); setTimeout(() => playSound(600, 0.1), 50); }
function playCoinSound() { playSound(988, 0.08); setTimeout(() => playSound(1319, 0.15), 80); }
function playStompSound() { playSound(200, 0.15, 'sawtooth', 0.2); }
function playBumpSound() { playSound(150, 0.1, 'triangle', 0.2); }
function playPowerupSound() { for(let i=0;i<5;i++) setTimeout(()=>playSound(400+i*100,0.1),i*60); }
function playDeathSound() { playSound(400,0.15); setTimeout(()=>playSound(300,0.15),150); setTimeout(()=>playSound(200,0.3),300); }
function playBreakSound() { playSound(300, 0.05, 'sawtooth', 0.15); }
function playFlagSound() { let f=523; for(let i=0;i<8;i++){setTimeout(()=>playSound(f,0.15),i*100);f*=1.12;} }
function playGameOverSound() { [392,349,330,262,294,262].forEach((f,i)=>setTimeout(()=>playSound(f,0.3,'square',0.12),i*250)); }

// Game state
let gameState = 'start'; // start, playing, gameover, win
let score = 0;
let coins = 0;
let lives = 3;
let timeLeft = 400;
let timeTimer = null;
let cameraX = 0;
let screenShake = 0;
let particles = [];
let floatingTexts = [];
let lastTime = 0;
let deltaTime = 0;

// Input
const keys = {};
window.addEventListener('keydown', e => { keys[e.code] = true; e.preventDefault(); });
window.addEventListener('keyup', e => { keys[e.code] = false; e.preventDefault(); });

// Level data
const TILE = 32;
const LEVEL_WIDTH = 220;
const LEVEL_HEIGHT = 16;

// Tile types
const EMPTY = 0, GROUND = 1, BRICK = 2, QUESTION = 3, PIPE_TL = 4, PIPE_TR = 5, PIPE_BL = 6, PIPE_BR = 7, HARD = 8, INVISIBLE = 9, FLAG_POLE = 10, FLAG_TOP = 11;

// Level map generation
function generateLevel() {
    let map = [];
    for (let y = 0; y < LEVEL_HEIGHT; y++) {
        map[y] = new Array(LEVEL_WIDTH).fill(EMPTY);
    }

    // Ground
    for (let x = 0; x < LEVEL_WIDTH; x++) {
        map[14][x] = GROUND;
        map[15][x] = GROUND;
    }

    // Gaps
    const gaps = [[68,70],[86,88],[153,155]];
    gaps.forEach(([s,e]) => {
        for(let x=s;x<=e;x++){map[14][x]=EMPTY;map[15][x]=EMPTY;}
    });

    // Question blocks with coins/powerups
    const questionBlocks = [
        [16,10,'coin'],[21,10,'powerup'],[23,10,'coin'],[22,6,'coin'],
        [78,10,'coin'],[94,10,'coin'],[106,10,'powerup'],[109,10,'coin'],
        [112,10,'coin'],[129,10,'coin'],[130,10,'coin'],[170,10,'powerup']
    ];
    questionBlocks.forEach(([x,y,type]) => {
        if(y<LEVEL_HEIGHT && x<LEVEL_WIDTH) map[y][x] = QUESTION;
    });

    // Brick blocks
    const bricks = [
        [20,10],[22,10],[24,10],
        [77,10],[79,10],[80,10],
        [91,10],[92,10],[93,10],[95,10],
        [100,6],[101,6],[102,6],[103,6],[104,6],[105,6],
        [118,10],[119,10],[120,10],
        [128,10],[131,10],
        [168,10],[169,10],[171,10]
    ];
    bricks.forEach(([x,y]) => {
        if(y<LEVEL_HEIGHT && x<LEVEL_WIDTH) map[y][x] = BRICK;
    });

    // Pipes
    const pipes = [
        [28,12,2],[38,11,3],[46,10,4],[57,11,3],[163,12,2],[179,12,2]
    ];
    pipes.forEach(([x,y,h]) => {
        for(let i=0;i<h;i++){
            if(y+i<LEVEL_HEIGHT){
                map[y+i][x] = i===0 ? PIPE_TL : PIPE_BL;
                map[y+i][x+1] = i===0 ? PIPE_TR : PIPE_BR;
            }
        }
    });

    // Stairs (end of level)
    for(let i=0;i<8;i++){
        for(let j=0;j<=i;j++){
            map[13-j][134+i] = HARD;
        }
    }
    // Descending stairs
    for(let i=0;i<8;i++){
        for(let j=0;j<=i;j++){
            map[13-j][148-i] = HARD;
        }
    }
    // Final stairs to flag
    for(let i=0;i<9;i++){
        for(let j=0;j<=i;j++){
            map[13-j][155+i] = HARD;
        }
    }

    // Flag pole
    map[5][164] = FLAG_TOP;
    for(let y=6;y<=13;y++) map[y][164] = FLAG_POLE;

    return map;
}

let levelMap = [];

// Entities
let player = null;
let enemies = [];
let coinEntities = [];
let powerupEntities = [];
let mushrooms = [];

class Player {
    constructor(x, y) {
        this.x = x; this.y = y;
        this.w = 24; this.h = 32;
        this.vx = 0; this.vy = 0;
        this.speed = 0.4;
        this.runSpeed = 0.6;
        this.maxSpeed = 3.5;
        this.runMaxSpeed = 5.5;
        this.jumpForce = -9;
        this.gravity = 0.45;
        this.friction = 0.85;
        this.onGround = false;
        this.facing = 1;
        this.state = 'small'; // small, big
        this.invincible = 0;
        this.animFrame = 0;
        this.animTimer = 0;
        this.dead = false;
        this.deathTimer = 0;
        this.won = false;
        this.flagSlide = false;
        this.flagY = 0;
        this.crouching = false;
        this.wasJumpHeld = false;
        this.jumpHeld = false;
    }

    update() {
        if (this.dead) {
            this.deathTimer++;
            this.vy += this.gravity;
            this.y += this.vy;
            if (this.deathTimer > 90) {
                lives--;
                if (lives <= 0) {
                    gameState = 'gameover';
                    document.getElementById('gameOverScreen').classList.remove('hidden');
                    document.getElementById('finalScore').textContent = 'Score: ' + score;
                    playGameOverSound();
                } else {
                    resetLevel();
                }
            }
            return;
        }

        if (this.won) {
            if (this.flagSlide) {
                if (this.y < 13 * TILE - this.h) {
                    this.y += 2;
                } else {
                    this.flagSlide = false;
                    this.x = 164 * TILE - this.w;
                    this.vx = 2;
                }
            } else {
                this.x += this.vx;
                this.vx *= 0.9;
                if (this.x > 170 * TILE) {
                    gameState = 'win';
                    document.getElementById('winScreen').classList.remove('hidden');
                    document.getElementById('winScore').textContent = 'Score: ' + score;
                    playFlagSound();
                }
            }
            return;
        }

        // Input
        let moveLeft = keys['ArrowLeft'] || keys['KeyA'];
        let moveRight = keys['ArrowRight'] || keys['KeyD'];
        let jumpKey = keys['Space'] || keys['ArrowUp'] || keys['KeyW'];
        let runKey = keys['ShiftLeft'] || keys['ShiftRight'];

        let currentMaxSpeed = runKey ? this.runMaxSpeed : this.maxSpeed;
        let currentAccel = runKey ? this.runSpeed : this.speed;

        if (moveLeft) {
            this.vx -= currentAccel;
            this.facing = -1;
        }
        if (moveRight) {
            this.vx += currentAccel;
            this.facing = 1;
        }

        if (!moveLeft && !moveRight) {
            this.vx *= this.friction;
            if (Math.abs(this.vx) < 0.1) this.vx = 0;
        }

        this.vx = Math.max(-currentMaxSpeed, Math.min(currentMaxSpeed, this.vx));

        // Jump
        if (jumpKey && this.onGround && !this.wasJumpHeld) {
            this.vy = this.jumpForce;
            this.onGround = false;
            this.wasJumpHeld = true;
            playJumpSound();
        }
        if (!jumpKey) {
            this.wasJumpHeld = false;
            if (this.vy < this.jumpForce * 0.5) {
                this.vy = this.jumpForce * 0.5;
            }
        }

        // Gravity
        this.vy += this.gravity;
        if (this.vy > 12) this.vy = 12;

        // Move X
        this.x += this.vx;
        this.resolveCollisionX();

        // Move Y
        this.y += this.vy;
        this.onGround = false;
        this.resolveCollisionY();

        // Prevent going left of camera
        if (this.x < cameraX) { this.x = cameraX; this.vx = 0; }

        // Fall death
        if (this.y > LEVEL_HEIGHT * TILE + 50) {
            this.die();
        }

        // Invincibility timer
        if (this.invincible > 0) this.invincible--;

        // Animation
        this.animTimer++;
        if (Math.abs(this.vx) > 0.5 && this.onGround) {
            if (this.animTimer % (Math.abs(this.vx) > 3 ? 4 : 6) === 0) {
                this.animFrame = (this.animFrame + 1) % 3;
            }
        } else if (this.onGround) {
            this.animFrame = 0;
        }

        // Coin collection
        for (let i = coinEntities.length - 1; i >= 0; i--) {
            let c = coinEntities[i];
            if (!c.collected && this.overlaps(c)) {
                c.collected = true;
                coins++;
                score += 200;
                playCoinSound();
                addFloatingText(c.x, c.y, '200');
                spawnParticles(c.x + 8, c.y + 8, '#fbd000', 5);
                if (coins % 100 === 0) { lives++; playPowerupSound(); }
            }
        }

        // Powerup collection
        for (let i = mushrooms.length - 1; i >= 0; i--) {
            let m = mushrooms[i];
            if (this.overlaps(m) && !m.active) {
                m.active = true;
                if (this.state === 'small') {
                    this.state = 'big';
                    this.h = 48;
                    this.y -= 16;
                }
                score += 1000;
                playPowerupSound();
                addFloatingText(m.x, m.y, '1000');
            }
        }

        // Enemy collision
        for (let e of enemies) {
            if (e.dead || e.squished) continue;
            if (this.overlaps(e)) {
                if (this.vy > 0 && this.y + this.h - this.vy <= e.y + e.h * 0.5) {
                    // Stomp
                    e.squishTimer = 30;
                    e.squished = true;
                    e.h = 8;
                    this.vy = -7;
                    score += 100;
                    playStompSound();
                    addFloatingText(e.x, e.y, '100');
                    spawnParticles(e.x + e.w/2, e.y, '#8B4513', 3);
                } else if (this.invincible <= 0) {
                    if (this.state === 'big') {
                        this.state = 'small';
                        this.h = 32;
                        this.y += 16;
                        this.invincible = 90;
                        playBumpSound();
                    } else {
                        this.die();
                    }
                }
            }
        }

        // Flag pole
        if (this.x + this.w > 164 * TILE && this.x < 164 * TILE + TILE && !this.won) {
            this.won = true;
            this.flagSlide = true;
            this.vx = 0;
            this.y = 5 * TILE;
            score += Math.max(0, Math.floor((13 * TILE - this.y) / TILE) * 100);
            playFlagSound();
        }
    }

    die() {
        if (this.dead) return;
        this.dead = true;
        this.vy = -8;
        this.vx = 0;
        playDeathSound();
        screenShake = 15;
    }

    resolveCollisionX() {
        let left = Math.floor(this.x / TILE);
        let right = Math.floor((this.x + this.w - 1) / TILE);
        let top = Math.floor(this.y / TILE);
        let bottom = Math.floor((this.y + this.h - 1) / TILE);

        for (let y = top; y <= bottom; y++) {
            for (let x = left; x <= right; x++) {
                if (y < 0 || y >= LEVEL_HEIGHT || x < 0 || x >= LEVEL_WIDTH) continue;
                let tile = levelMap[y][x];
                if (tile !== EMPTY && tile !== INVISIBLE && tile !== FLAG_POLE && tile !== FLAG_TOP) {
                    if (this.vx > 0) {
                        this.x = x * TILE - this.w;
                        this.vx = 0;
                    } else if (this.vx < 0) {
                        this.x = (x + 1) * TILE;
                        this.vx = 0;
                    }
                }
            }
        }
    }

    resolveCollisionY() {
        let left = Math.floor(this.x / TILE);
        let right = Math.floor((this.x + this.w - 1) / TILE);
        let top = Math.floor(this.y / TILE);
        let bottom = Math.floor((this.y + this.h - 1) / TILE);

        for (let y = top; y <= bottom; y++) {
            for (let x = left; x <= right; x++) {
                if (y < 0 || y >= LEVEL_HEIGHT || x < 0 || x >= LEVEL_WIDTH) continue;
                let tile = levelMap[y][x];
                if (tile !== EMPTY && tile !== INVISIBLE && tile !== FLAG_POLE && tile !== FLAG_TOP) {
                    if (this.vy > 0) {
                        this.y = y * TILE - this.h;
                        this.vy = 0;
                        this.onGround = true;
                    } else if (this.vy < 0) {
                        this.y = (y + 1) * TILE;
                        this.vy = 0;
                        // Hit block from below
                        if (tile === BRICK) {
                            if (this.state === 'big') {
                                levelMap[y][x] = EMPTY;
                                playBreakSound();
                                score += 50;
                                spawnParticles(x * TILE + 16, y * TILE + 16, '#c84c0c', 8);
                                screenShake = 5;
                            } else {
                                playBumpSound();
                                spawnParticles(x * TILE + 16, y * TILE + 16, '#c84c0c', 3);
                            }
                        } else if (tile === QUESTION) {
                            levelMap[y][x] = HARD;
                            let content = getQuestionContent(y, x);
                            if (content === 'coin') {
                                coins++;
                                score += 200;
                                playCoinSound();
                                addFloatingText(x * TILE, y * TILE - 20, '200');
                                spawnParticles(x * TILE + 16, y * TILE, '#fbd000', 5);
                            } else if (content === 'powerup') {
                                mushrooms.push({
                                    x: x * TILE, y: (y - 1) * TILE,
                                    w: 24, h: 24, vx: 2, vy: 0,
                                    active: false, activeTimer: 0
                                });
                                playPowerupSound();
                            }
                            playBumpSound();
                            spawnParticles(x * TILE + 16, y * TILE + 16, '#fbd000', 3);
                        }
                    }
                }
            }
        }
    }

    overlaps(entity) {
        return this.x < entity.x + entity.w && this.x + this.w > entity.x &&
               this.y < entity.y + entity.h && this.y + this.h > entity.y;
    }

    draw() {
        if (this.dead && this.deathTimer > 10) return;
        if (this.invincible > 0 && Math.floor(this.invincible / 3) % 2 === 0) return;

        let sx = this.x - cameraX;
        let sy = this.y;

        ctx.save();
        ctx.translate(sx + this.w/2, sy + this.h);
        ctx.scale(this.facing, 1);

        if (this.state === 'big') {
            // Big Mario
            // Hat
            ctx.fillStyle = '#e52521';
            ctx.fillRect(-12, -48, 24, 8);
            ctx.fillRect(-10, -52, 20, 6);
            // Face
            ctx.fillStyle = '#fbb';
            ctx.fillRect(-10, -40, 20, 12);
            // Eyes
            ctx.fillStyle = '#000';
            ctx.fillRect(2, -38, 4, 4);
            // Mustache
            ctx.fillStyle = '#4a2800';
            ctx.fillRect(-2, -32, 14, 3);
            // Body
            ctx.fillStyle = '#e52521';
            ctx.fillRect(-12, -28, 24, 12);
            // Overalls
            ctx.fillStyle = '#0050d4';
            ctx.fillRect(-12, -20, 24, 12);
            // Buttons
            ctx.fillStyle = '#fbd000';
            ctx.fillRect(-4, -18, 3, 3);
            ctx.fillRect(4, -18, 3, 3);
            // Legs
            if (!this.onGround) {
                ctx.fillStyle = '#0050d4';
                ctx.fillRect(-12, -8, 10, 8);
                ctx.fillRect(2, -12, 10, 8);
                // Shoes
                ctx.fillStyle = '#6b3300';
                ctx.fillRect(-14, -2, 12, 4);
                ctx.fillRect(4, -6, 12, 4);
            } else if (Math.abs(this.vx) > 0.5) {
                let legOff = this.animFrame === 1 ? 4 : 0;
                ctx.fillStyle = '#0050d4';
                ctx.fillRect(-12, -8 + legOff, 10, 8);
                ctx.fillRect(2, -8 - legOff, 10, 8);
                ctx.fillStyle = '#6b3300';
                ctx.fillRect(-14, -2 + legOff, 12, 4);
                ctx.fillRect(4, -2 - legOff, 12, 4);
            } else {
                ctx.fillStyle = '#0050d4';
                ctx.fillRect(-12, -8, 10, 8);
                ctx.fillRect(2, -8, 10, 8);
                ctx.fillStyle = '#6b3300';
                ctx.fillRect(-14, -2, 12, 4);
                ctx.fillRect(4, -2, 12, 4);
            }
        } else {
            // Small Mario
            // Hat
            ctx.fillStyle = '#e52521';
            ctx.fillRect(-10, -32, 20, 6);
            ctx.fillRect(-8, -36, 16, 5);
            // Face
            ctx.fillStyle = '#fbb';
            ctx.fillRect(-8, -26, 16, 10);
            // Eyes
            ctx.fillStyle = '#000';
            ctx.fillRect(2, -24, 3, 3);
            // Mustache
            ctx.fillStyle = '#4a2800';
            ctx.fillRect(-2, -19, 12, 2);
            // Body
            ctx.fillStyle = '#e52521';
            ctx.fillRect(-10, -16, 20, 8);
            // Overalls
            ctx.fillStyle = '#0050d4';
            ctx.fillRect(-10, -8, 20, 8);
            // Buttons
            ctx.fillStyle = '#fbd000';
            ctx.fillRect(-3, -7, 2, 2);
            ctx.fillRect(3, -7, 2, 2);
            // Shoes
            if (!this.onGround) {
                ctx.fillStyle = '#6b3300';
                ctx.fillRect(-12, -2, 10, 4);
                ctx.fillRect(2, -4, 10, 4);
            } else if (Math.abs(this.vx) > 0.5) {
                let legOff = this.animFrame === 1 ? 2 : 0;
                ctx.fillStyle = '#6b3300';
                ctx.fillRect(-12, -2 + legOff, 10, 4);
                ctx.fillRect(2, -2 - legOff, 10, 4);
            } else {
                ctx.fillStyle = '#6b3300';
                ctx.fillRect(-12, -2, 10, 4);
                ctx.fillRect(2, -2, 10, 4);
            }
        }

        ctx.restore();
    }
}

function getQuestionContent(y, x) {
    // Simple mapping - could be more complex
    if (x === 21 || x === 106 || x === 170) return 'powerup';
    return 'coin';
}

// Enemy class
class Enemy {
    constructor(x, y, type = 'goomba') {
        this.x = x; this.y = y;
        this.type = type;
        this.startX = x;
        this.vx = -1;
        this.vy = 0;
        this.w = type === 'goomba' ? 28 : 28;
        this.h = type === 'goomba' ? 28 : 32;
        this.dead = false;
        this.squished = false;
        this.squishTimer = 0;
        this.animFrame = 0;
        this.animTimer = 0;
        this.patrolDist = 80 + Math.random() * 60;
    }

    update() {
        if (this.dead) return;

        if (this.squished) {
            this.squishTimer--;
            if (this.squishTimer <= 0) this.dead = true;
            return;
        }

        this.vy += 0.4;
        this.x += this.vx;
        this.y += this.vy;

        // Simple ground collision
        let bottom = Math.floor((this.y + this.h) / TILE);
        let left = Math.floor(this.x / TILE);
        let right = Math.floor((this.x + this.w - 1) / TILE);

        this.onGround = false;
        for (let x = left; x <= right; x++) {
            if (bottom >= 0 && bottom < LEVEL_HEIGHT && x >= 0 && x < LEVEL_WIDTH) {
                if (levelMap[bottom][x] !== EMPTY && levelMap[bottom][x] !== INVISIBLE) {
                    this.y = bottom * TILE - this.h;
                    this.vy = 0;
                    this.onGround = true;
                }
