        let side = this.vx > 0 ? Math.floor((this.x + this.w) / TILE) : Math.floor(this.x / TILE);
        let midY = Math.floor((this.y + this.h/2) / TILE);
        if (midY >= 0 && midY < LEVEL_HEIGHT && side >= 0 && side < LEVEL_WIDTH) {
            if (levelMap[midY][side] !== EMPTY && levelMap[midY][side] !== INVISIBLE) {
                this.vx *= -1;
            }
        }

        // Edge detection - turn around at edges
        if (this.onGround) {
            let checkX = this.vx > 0 ? Math.floor((this.x + this.w + 2) / TILE) : Math.floor((this.x - 2) / TILE);
            let checkY = Math.floor((this.y + this.h + 2) / TILE);
            if (checkY < LEVEL_HEIGHT && checkX >= 0 && checkX < LEVEL_WIDTH) {
                if (levelMap[checkY][checkX] === EMPTY || levelMap[checkY][checkX] === INVISIBLE) {
                    this.vx *= -1;
                }
            }
        }

        // Animation
        this.animTimer++;
        if (this.animTimer % 12 === 0) this.animFrame = (this.animFrame + 1) % 2;

        // Remove if too far from camera
        if (this.x < cameraX - 200 || this.x > cameraX + GAME_WIDTH + 200) {
            this.dead = true;
        }
    }

    draw() {
