}

// Drawing functions
function drawTile(x, y, type) {
    let sx = x * TILE - cameraX;
    let sy = y * TILE;

    if (sx < -TILE || sx > GAME_WIDTH + TILE) return;

    switch(type) {
        case GROUND:
            ctx.fillStyle = '#c84c0c';
            ctx.fillRect(sx, sy, TILE, TILE);
            ctx.fillStyle = '#e09060';
            ctx.fillRect(sx + 2, sy + 2, TILE - 4, TILE - 4);
            ctx.fillStyle = '#c84c0c';
            ctx.fillRect(sx + 4, sy + 4, TILE - 8, TILE - 8);
            // Brick pattern
            ctx.strokeStyle = '#a03000';
            ctx.lineWidth = 1;
            ctx.strokeRect(sx, sy, TILE, TILE);
            break;

        case BRICK:
            ctx.fillStyle = '#c84c0c';
            ctx.fillRect(sx, sy, TILE, TILE);
            ctx.fillStyle = '#e09060';
            ctx.fillRect(sx + 1, sy + 1, 14, 14);
            ctx.fillRect(sx + 17, sy + 1, 14, 14);
            ctx.fillRect(sx + 1, sy + 17, 14, 14);
            ctx.fillRect(sx + 17, sy + 17, 14, 14);
            ctx.strokeStyle = '#8B3000';
            ctx.lineWidth = 1;
            ctx.strokeRect(sx, sy, TILE, TILE);
