            let pulse = Math.sin(Date.now() / 200) * 0.15 + 0.85;
            ctx.fillStyle = '#fbd000';
            ctx.fillRect(sx, sy, TILE, TILE);
            ctx.fillStyle = '#c8a000';
            ctx.fillRect(sx + 2, sy + 2, TILE - 4, TILE - 4);
            ctx.fillStyle = '#fbd000';
            ctx.fillRect(sx + 4, sy + 4, TILE - 8, TILE - 8);
            // Question mark
            ctx.fillStyle = '#8B6914';
            ctx.font = 'bold 18px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('?', sx + 16, sy + 24);
            break;

        case HARD:
            ctx.fillStyle = '#8B8B8B';
            ctx.fillRect(sx, sy, TILE, TILE);
            ctx.fillStyle = '#A0A0A0';
            ctx.fillRect(sx + 2, sy + 2, TILE - 4, TILE - 4);
            ctx.fillStyle = '#C0C0C0';
            ctx.fillRect(sx + 4, sy + 4, TILE - 8, TILE - 8);
            ctx.strokeStyle = '#666';
            ctx.lineWidth = 1;
            ctx.strokeRect(sx, sy, TILE, TILE);
            break;

        case PIPE_TL:
            ctx.fillStyle = '#00a800';
            ctx.fillRect(sx - 2, sy, TILE + 2, TILE);
            ctx.fillStyle = '#00d800';
            ctx.fillRect(sx, sy + 2, TILE - 4, TILE - 4);
            ctx.fillStyle = '#50ff50';
            ctx.fillRect(sx + 4, sy + 4, 6, TILE - 8);
            break;

        case PIPE_TR:
            ctx.fillStyle = '#00a800';
            ctx.fillRect(sx, sy, TILE + 2, TILE);
            ctx.fillStyle = '#00d800';
            ctx.fillRect(sx + 2, sy + 2, TILE - 4, TILE - 4);
            ctx.fillStyle = '#008800';
            ctx.fillRect(sx + TILE - 6, sy + 4, 4, TILE - 8);
            break;

        case PIPE_BL:
        case PIPE_BR:
            ctx.fillStyle = '#00a800';
            ctx.fillRect(sx, sy, TILE, TILE);
            ctx.fillStyle = '#00d800';
            ctx.fillRect(sx + 2, sy, TILE - 4, TILE);
            ctx.fillStyle = '#50ff50';
            ctx.fillRect(sx + 4, sy, 6, TILE);
            break;

        case FLAG_POLE:
            ctx.fillStyle = '#888';
            ctx.fillRect(sx + 14, sy, 4, TILE);
            break;

        case FLAG_TOP:
            ctx.fillStyle = '#888';
            ctx.fillRect(sx + 14, sy + 8, 4, TILE - 8);
            // Ball on top
            ctx.fillStyle = '#228B22';
            ctx.beginPath();
            ctx.arc(sx + 16, sy + 8, 6, 0, Math.PI * 2);
            ctx.fill();
            // Flag
            ctx.fillStyle = '#e52521';
            ctx.beginPath();
            ctx.moveTo(sx + 14, sy + 8);
            ctx.lineTo(sx - 16, sy + 16);
            ctx.lineTo(sx + 14, sy + 24);
            ctx.fill();
            break;
    }
}

function drawBackground() {
    // Sky gradient
    let grad = ctx.createLinearGradient(0, 0, 0, GAME_HEIGHT);
    grad.addColorStop(0, '#5c94fc');
    grad.addColorStop(0.7, '#87CEEB');
    grad.addColorStop(1, '#b8d8f0');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // Clouds (parallax)
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 20; i++) {
        let cx = (i * 350 + 100) - cameraX * 0.2;
        if (cx < -200) cx += 20 * 350;
        let cy = 40 + (i % 3) * 50;
        drawCloud(cx, cy, 1 + (i % 3));
