}

// Main game loop
function gameLoop(timestamp) {
    deltaTime = Math.min((timestamp - lastTime) / 16.67, 3);
    lastTime = timestamp;

    if (gameState === 'playing') {
        player.update();
        updateEnemies();
        updateMushrooms();
        updateParticles();
        updateFloatingTexts();

        // Camera follow
        let targetCamX = player.x - GAME_WIDTH / 3;
        cameraX += (targetCamX - cameraX) * 0.1;
        cameraX = Math.max(0, Math.min(cameraX, LEVEL_WIDTH * TILE - GAME_WIDTH));

        // Screen shake
        if (screenShake > 0) {
            screenShake--;
        }

        updateUI();
    }

    // Render
    ctx.save();
    if (screenShake > 0) {
        ctx.translate(
            (Math.random() - 0.5) * screenShake,
            (Math.random() - 0.5) * screenShake
        );
    }

    drawBackground();

    // Draw tiles
    let startTile = Math.max(0, Math.floor(cameraX / TILE) - 1);
    let endTile = Math.min(LEVEL_WIDTH, Math.ceil((cameraX + GAME_WIDTH) / TILE) + 1);

    for (let y = 0; y < LEVEL_HEIGHT; y++) {
        for (let x = startTile; x < endTile; x++) {
            if (levelMap[y][x] !== EMPTY) {
                drawTile(x, y, levelMap[y][x]);
            }
        }
    }

    // Draw entities
    for (let c of coinEntities) drawCoin(c);
    for (let m of mushrooms) drawMushroom(m);
    for (let e of enemies) e.draw();
    if (player) player.draw();
    drawParticles();
    drawFloatingTexts();

    ctx.restore();

    requestAnimationFrame(gameLoop);
}

// Initialize
