.controls-info { color: #666; font-size: 0.85em; margin-top: 25px; text-align: center; line-height: 1.8; }
.controls-info span { color: #0ff; }
#mobile-controls { position: absolute; bottom: 20px; left: 0; width: 100%; display: none; justify-content: space-between; padding: 0 20px; z-index: 5; }
.mobile-btn { width: 60px; height: 60px; border-radius: 50%; border: 2px solid rgba(0,255,255,0.4); background: rgba(0,255,255,0.1); color: #0ff; font-size: 1.5em; display: flex; justify-content: center; align-items: center; user-select: none; -webkit-user-select: none; }
.mobile-btn:active { background: rgba(0,255,255,0.4); }
.dpad { display: grid; grid-template-columns: 60px 60px 60px; grid-template-rows: 60px 60px; gap: 5px; }
.attack-btns { display: flex; flex-direction: column; gap: 10px; }
</style>
</head>
<body>
<canvas id="gameCanvas"></canvas>
<div id="ui-overlay">
<div id="start-screen">
<h1>SHADOW SHIFT</h1>
<h2>⚡ INFINITE RUN ⚡</h2>
<button class="btn" onclick="startGame()">START RUN</button>
<div class="controls-info">
<span>← →</span> or <span>A D</span> — Change Lanes<br>
<span>↑</span> or <span>W</span> — Jump &nbsp; <span>↓</span> or <span>S</span> — Slide<br>
<span>SPACE</span> — Attack &nbsp; <span>SHIFT</span> — Charge Attack<br>
<span>P</span> — Special Ability<br>
<span>Swipe</span> on mobile
</div>
</div>
<div id="gameover-screen" style="display:none;">
<h1>GAME OVER</h1>
<div class="score-display">Score: <span id="final-score">0</span></div>
<div class="stats">Distance: <span id="final-distance">0</span>m</div>
<div class="stats">Enemies Defeated: <span id="final-enemies">0</span></div>
<div class="stats">Boss Defeated: <span id="final-boss">No</span></div>
<button class="btn" onclick="startGame()">RUN AGAIN</button>
<button class="btn red" onclick="showMenu()">MENU</button>
</div>
</div>
<div id="mobile-controls">
<div class="dpad">
<div style="grid-column:2;grid-row:1"><div class="mobile-btn" id="btn-up">▲</div></div>
<div style="grid-column:1;grid-row:2"><div class="mobile-btn" id="btn-left">◄</div></div>
<div style="grid-column:2;grid-row:2"><div class="mobile-btn" id="btn-down">▼</div></div>
<div style="grid-column:3;grid-row:2"><div class="mobile-btn" id="btn-right">►</div></div>
</div>
<div class="attack-btns">
<div class="mobile-btn" id="btn-attack" style="border-color:rgba(255,100,0,0.5);color:#f80;">⚔</div>
<div class="mobile-btn" id="btn-special" style="border-color:rgba(255,0,255,0.5);color:#f0f;">✦</div>
</div>
</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let W, H;
function resize() {
    W = canvas.width = Math.min(window.innerWidth, 600);
    H = canvas.height = Math.min(window.innerHeight, 900);
}
resize();
window.addEventListener('resize', resize);

// Game State
const STATE = { MENU: 0, RUNNING: 1, TRANSFORMING: 2, COMBAT: 3, BOSS: 4, GAMEOVER: 5, TIME_SLOW: 6 };
let gameState = STATE.MENU;
let score = 0;
let distance = 0;
let speed = 5;
let maxSpeed = 14;
let enemiesDefeated = 0;
let bossDefeated = false;
let transformDistance = 800;
let bossDistance = 3000;
let timeSlowTimer = 0;
let shakeTimer = 0;
let shakeIntensity = 0;
let comboCount = 0;
let comboTimer = 0;
let transformProgress = 0;
let transformFlash = 0;
let difficultyMultiplier = 1;

// Player
const player = {
    lane: 1, // 0, 1, 2
    x: 0, targetX: 0,
    y: 0,
    width: 40, height: 60,
    jumping: false, jumpVel: 0, jumpHeight: 0,
    sliding: false, slideTimer: 0,
    transformed: false,
    transformTimer: 0,
    energy: 100,
    maxEnergy: 100,
    powerMeter: 0,
    maxPower: 100,
    health: 100,
    maxHealth: 100,
    attacking: false,
    attackTimer: 0,
    chargeAttack: false,
    chargeTimer: 0,
    specialReady: false,
    invincible: false,
    invincibleTimer: 0,
    trail: [],
    color: '#0ff',
    glowColor: '#0ff'
};

// Road
const roadWidth = 300;
const laneWidth = roadWidth / 3;
const horizonY = H * 0.3;
let roadOffset = 0;

// Obstacles
let obstacles = [];
let enemies = [];
let particles = [];
let projectiles = [];
let pickups = [];
let boss = null;
let bossPhase = 0;
let bossTimer = 0;
let bossProjectiles = [];
let floatingTexts = [];

// Input
const keys = {};
let touchStartX = 0, touchStartY = 0, touchStartTime = 0;
let mobileControls = false;

// Audio context for sound effects
let audioCtx = null;
function initAudio() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
}

function playSound(freq, duration, type = 'square', volume = 0.15) {
    if (!audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
    gain.gain.setValueAtTime(volume, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + duration);
}

function playHitSound() { playSound(200, 0.15, 'sawtooth', 0.2); }
function playJumpSound() { playSound(400, 0.1, 'sine', 0.1); }
function playTransformSound() { 
    playSound(100, 0.5, 'sawtooth', 0.2); 
    setTimeout(() => playSound(300, 0.3, 'sine', 0.15), 100);
    setTimeout(() => playSound(600, 0.4, 'sine', 0.1), 200);
}
function playExplosionSound() { 
    playSound(80, 0.4, 'sawtooth', 0.25); 
    playSound(60, 0.3, 'square', 0.15);
}
function playPickupSound() { playSound(800, 0.15, 'sine', 0.12); }
function playBossSound() { playSound(50, 0.8, 'sawtooth', 0.2); }

// Utility functions
function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function rand(min, max) { return Math.random() * (max - min) + min; }
function randInt(min, max) { return Math.floor(rand(min, max + 1)); }
function dist(x1, y1, x2, y2) { return Math.sqrt((x2-x1)**2 + (y2-y1)**2); }

function getLaneX(lane) {
    const roadLeft = (W - roadWidth) / 2;
    return roadLeft + lane * laneWidth + laneWidth / 2;
}

function spawnObstacle() {
    const lane = randInt(0, 2);
    const types = ['barrier', 'car', 'trap'];
    const type = types[randInt(0, types.length - 1)];
    obstacles.push({
        lane, type,
        x: getLaneX(lane),
        y: -50,
        width: type === 'car' ? 45 : 50,
        height: type === 'car' ? 80 : 30,
        color: type === 'barrier' ? '#f80' : type === 'car' ? '#f44' : '#ff0',
        passed: false
    });
}

function spawnEnemy() {
    const lane = randInt(0, 2);
    const types = ['drone', 'armored', 'flying', 'speed'];
    const type = types[randInt(0, Math.min(types.length - 1, Math.floor(distance / 1500) + 1))];
    let hp = type === 'armored' ? 3 : 1;
    let speedMod = type === 'speed' ? 1.5 : 1;
    let width = type === 'flying' ? 35 : 40;
    let height = type === 'flying' ? 30 : 50;
    let yOffset = type === 'flying' ? -80 : 0;
    enemies.push({
        lane, type,
        x: getLaneX(lane),
        y: -50 + yOffset,
        baseY: -50 + yOffset,
        width, height,
        hp, maxHp: hp,
        speed: speedMod * (2 + distance / 5000),
        color: type === 'drone' ? '#f44' : type === 'armored' ? '#888' : type === 'flying' ? '#f0f' : '#ff0',
        hit: false,
        hitTimer: 0,
        attackTimer: rand(60, 180),
        flyingAngle: 0
    });
}

function spawnPickup(x, y, type) {
    pickups.push({ x, y, type, width: 25, height: 25, bobPhase: rand(0, Math.PI * 2), life: 300 });
}

function spawnParticles(x, y, color, count, spread, speed) {
    for (let i = 0; i < count; i++) {
        const angle = rand(0, Math.PI * 2);
        const spd = rand(speed * 0.3, speed);
        particles.push({
            x, y,
            vx: Math.cos(angle) * spd * spread,
            vy: Math.sin(angle) * spd * spread - 2,
            life: rand(20, 50),
            maxLife: 50,
            color,
            size: rand(2, 6)
        });
    }
}

function addFloatingText(x, y, text, color) {
    floatingTexts.push({ x, y, text, color, life: 60, vy: -2 });
}

function initBoss() {
    boss = {
        x: W / 2,
        y: H * 0.2,
        width: 100,
        height: 120,
        hp: 50,
        maxHp: 50,
        phase: 1,
        attackTimer: 60,
        moveTimer: 0,
        targetX: W / 2,
        targetY: H * 0.2,
        rageMode: false,
        rageTimer: 0,
        shieldActive: false,
        shieldTimer: 0,
        weakPointExposed: false,
        weakPointTimer: 0,
        color: '#f0f',
        name: 'AMY THE DESTROYER'
    };
    bossProjectiles = [];
    bossPhase = 1;
    bossTimer = 0;
    playBossSound();
}

function resetGame() {
    player.lane = 1;
    player.x = getLaneX(1);
    player.targetX = player.x;
    player.y = H * 0.75;
    player.jumping = false;
    player.jumpVel = 0;
    player.jumpHeight = 0;
    player.sliding = false;
    player.slideTimer = 0;
    player.transformed = false;
    player.transformTimer = 0;
    player.energy = 100;
    player.powerMeter = 0;
    player.health = 100;
    player.attacking = false;
    player.attackTimer = 0;
    player.chargeAttack = false;
    player.chargeTimer = 0;
    player.specialReady = false;
    player.invincible = false;
    player.invincibleTimer = 0;
    player.trail = [];
    player.color = '#0ff';
    player.glowColor = '#0ff';

    score = 0;
    distance = 0;
    speed = 5;
    enemiesDefeated = 0;
    bossDefeated = false;
    transformDistance = 800;
    bossDistance = 3000;
    timeSlowTimer = 0;
    shakeTimer = 0;
    comboCount = 0;
    comboTimer = 0;
    transformProgress = 0;
    transformFlash = 0;
    difficultyMultiplier = 1;

    obstacles = [];
    enemies = [];
    particles = [];
    projectiles = [];
    pickups = [];
    boss = null;
    bossProjectiles = [];
    floatingTexts = [];

    roadOffset = 0;
}

function startGame() {
    initAudio();
    resetGame();
    gameState = STATE.RUNNING;
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('gameover-screen').style.display = 'none';
    mobileControls = window.innerWidth < 768;
    document.getElementById('mobile-controls').style.display = mobileControls ? 'flex' : 'none';
}

function showMenu() {
    gameState = STATE.MENU;
    document.getElementById('start-screen').style.display = 'flex';
    document.getElementById('gameover-screen').style.display = 'none';
    document.getElementById('mobile-controls').style.display = 'none';
}

function gameOver() {
    gameState = STATE.GAMEOVER;
    document.getElementById('final-score').textContent = Math.floor(score);
    document.getElementById('final-distance').textContent = Math.floor(distance);
    document.getElementById('final-enemies').textContent = enemiesDefeated;
    document.getElementById('final-boss').textContent = bossDefeated ? 'Yes!' : 'No';
    document.getElementById('gameover-screen').style.display = 'flex';
    document.getElementById('mobile-controls').style.display = 'none';
}

// Input handling
document.addEventListener('keydown', e => {
    keys[e.code] = true;
    if (gameState === STATE.RUNNING || gameState === STATE.COMBAT || gameState === STATE.BOSS) {
        if (e.code === 'ArrowLeft' || e.code === 'KeyA') moveLeft();
        if (e.code === 'ArrowRight' || e.code === 'KeyD') moveRight();
        if (e.code === 'ArrowUp' || e.code === 'KeyW') jump();
        if (e.code === 'ArrowDown' || e.code === 'KeyS') slide();
        if (e.code === 'Space') attack();
        if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') chargeAttack();
        if (e.code === 'KeyP') useSpecial();
    }
    if (gameState === STATE.MENU && e.code === 'Enter') startGame();
    if (gameState === STATE.GAMEOVER && e.code === 'Enter') startGame();
    e.preventDefault();
});

document.addEventListener('keyup', e => {
    keys[e.code] = false;
    if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        player.chargeAttack = false;
        if (player.chargeTimer > 30) {
            performChargedAttack();
        }
        player.chargeTimer = 0;
    }
});

// Touch handling
canvas.addEventListener('touchstart', e => {
    e.preventDefault();
    const t = e.touches[0];
    touchStartX = t.clientX;
    touchStartY = t.clientY;
    touchStartTime = Date.now();
});

canvas.addEventListener('touchmove', e => e.preventDefault());

canvas.addEventListener('touchend', e => {
    e.preventDefault();
    if (gameState === STATE.MENU || gameState === STATE.GAMEOVER) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStartX;
    const dy = t.clientY - touchStartY;
    const dt = Date.now() - touchStartTime;

    if (dt < 300 && Math.abs(dx) > 30 && Math.abs(dx) > Math.abs(dy)) {
        if (dx < 0) moveLeft(); else moveRight();
    } else if (dt < 300 && Math.abs(dy) > 30 && Math.abs(dy) > Math.abs(dx)) {
        if (dy < 0) jump(); else slide();
    } else if (dt < 200 && Math.abs(dx) < 20 && Math.abs(dy) < 20) {
        attack();
    }
});

// Mobile button controls
function setupMobileBtn(id, action) {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.addEventListener('touchstart', e => { e.preventDefault(); action(); });
    btn.addEventListener('mousedown', e => { e.preventDefault(); action(); });
}

setupMobileBtn('btn-left', moveLeft);
setupMobileBtn('btn-right', moveRight);
setupMobileBtn('btn-up', jump);
setupMobileBtn('btn-down', slide);
setupMobileBtn('btn-attack', attack);
setupMobileBtn('btn-special', useSpecial);

function moveLeft() {
    if (player.lane > 0) {
        player.lane--;
        player.targetX = getLaneX(player.lane);
    }
}

function moveRight() {
    if (player.lane < 2) {
        player.lane++;
        player.targetX = getLaneX(player.lane);
    }
}

function jump() {
    if (!player.jumping && !player.sliding) {
        player.jumping = true;
        player.jumpVel = -15;
        playJumpSound();
    }
}

function slide() {
    if (!player.jumping && !player.sliding) {
        player.sliding = true;
        player.slideTimer = 40;
    }
}

function attack() {
    if (player.attacking || !player.transformed) return;
    player.attacking = true;
    player.attackTimer = 15;
    playHitSound();

    // Check hit on enemies in range
    const attackRange = 80;
    const attackWidth = 50;
    enemies.forEach(enemy => {
        if (enemy.hp <= 0) return;
        const ex = enemy.x, ey = enemy.y + (enemy.type === 'flying' ? -40 : 0);
        const px = player.x, py = player.y;
        if (dist(px, py, ex, ey) < attackRange + enemy.width / 2) {
            if (player.lane === enemy.lane || dist(px, py, ex, ey) < attackRange) {
                enemy.hp--;
                enemy.hit = true;
                enemy.hitTimer = 10;
                spawnParticles(ex, ey, '#ff0', 8, 1, 4);
                playHitSound();

                if (enemy.hp <= 0) {
                    destroyEnemy(enemy);
                }
            }
        }
    });
}

function chargeAttack() {
    if (!player.transformed || player.chargeAttack) return;
    player.chargeAttack = true;
    player.chargeTimer = 0;
}

function performChargedAttack() {
    if (player.chargeTimer < 30) return;
    player.attacking = true;
    player.attackTimer = 25;
    playExplosionSound();

    const attackRange = 120;
    enemies.forEach(enemy => {
        if (enemy.hp <= 0) return;
        const ex = enemy.x, ey = enemy.y + (enemy.type === 'flying' ? -40 : 0);
        if (dist(player.x, player.y, ex, ey) < attackRange) {
            const dmg = enemy.type === 'armored' ? 2 : 3;
            enemy.hp -= dmg;
            enemy.hit = true;
            enemy.hitTimer = 15;
            spawnParticles(ex, ey, '#f80', 20, 1.5, 6);
            shakeTimer = 10;
            shakeIntensity = 5;

            if (enemy.hp <= 0) {
                destroyEnemy(enemy);
            }
        }
    });
}

function useSpecial() {
    if (!player.specialReady) return;
    player.specialReady = false;
    player.powerMeter = 0;
    player.invincible = true;
    player.invincibleTimer = 180;
    timeSlowTimer = 180;
    shakeTimer = 20;
    shakeIntensity = 8;
    playTransformSound();

    // Destroy all enemies on screen
    enemies.forEach(enemy => {
        if (enemy.hp > 0) {
            spawnParticles(enemy.x, enemy.y, '#f0f', 15, 1, 5);
            enemy.hp = 0;
            enemiesDefeated++;
            score += 500;
        }
    });

    addFloatingText(W / 2, H / 2, '⚡ SHADOW SHIFT ⚡', '#f0f');

    // Clear boss projectiles
    bossProjectiles = [];
}

function destroyEnemy(enemy) {
    spawnParticles(enemy.x, enemy.y, enemy.color, 25, 1.5, 6);
    playExplosionSound();
    shakeTimer = 8;
    shakeIntensity = 4;
    enemiesDefeated++;
    score += enemy.type === 'armored' ? 300 : enemy.type === 'flying' ? 200 : 100;

    comboCount++;
    comboTimer = 120;
    if (comboCount > 1) {
        score += comboCount * 50;
        addFloatingText(enemy.x, enemy.y - 30, `x${comboCount} COMBO!`, '#ff0');
    }

    player.energy = Math.min(player.maxEnergy, player.energy + 15);
    player.powerMeter = Math.min(player.maxPower, player.powerMeter + 20);

    if (player.powerMeter >= player.maxPower) {
        player.specialReady = true;
        addFloatingText(player.x, player.y - 50, '⚡ SPECIAL READY [P]', '#f0f');
    }

    // Drop pickup
    if (Math.random() < 0.3) {
        const types = ['health', 'energy', 'score'];
        spawnPickup(enemy.x, enemy.y, types[randInt(0, 2)]);
    }
}

// Update functions
function updatePlayer() {
    // Smooth lane transition
    player.x = lerp(player.x, player.targetX, 0.2);

    // Jump physics
    if (player.jumping) {
        player.jumpVel += 0.8;
        player.jumpHeight += player.jumpVel;
        if (player.jumpHeight >= 0) {
            player.jumpHeight = 0;
            player.jumping = false;
            player.jumpVel = 0;
        }
    }

    // Slide
    if (player.sliding) {
        player.slideTimer--;
        if (player.slideTimer <= 0) player.sliding = false;
    }

    // Attack animation
    if (player.attacking) {
        player.attackTimer--;
        if (player.attackTimer <= 0) player.attacking = false;
    }

    // Charge attack
    if (player.chargeAttack) {
        player.chargeTimer++;
    }

    // Invincibility
    if (player.invincible) {
        player.invincibleTimer--;
        if (player.invincibleTimer <= 0) player.invincible = false;
    }

    // Trail
    player.trail.push({ x: player.x, y: player.y, alpha: 1 });
    if (player.trail.length > 15) player.trail.shift();
    player.trail.forEach(t => t.alpha -= 0.07);

    // Energy drain when transformed
    if (player.transformed) {
        player.energy -= 0.05 * difficultyMultiplier;
        if (player.energy <= 0) {
            player.energy = 0;
            player.transformed = false;
            player.transformTimer = 300; // Cooldown
            player.color = '#0ff';
            player.glowColor = '#0ff';
            addFloatingText(player.x, player.y - 60, 'FORM LOST!', '#f44');
            playHitSound();
        }
    }

    // Transform cooldown
    if (!player.transformed && player.transformTimer > 0) {
        player.transformTimer--;
    }

    // Combo timer
    if (comboTimer > 0) {
        comboTimer--;
        if (comboTimer <= 0) comboCount = 0;
    }
}

function updateObstacles(dt) {
    const spd = speed * (timeSlowTimer > 0 ? 0.3 : 1);

    obstacles.forEach(obs => {
        obs.y += spd;

        // Collision with player
        if (!obs.passed) {
            const pBottom = player.y + player.height / 2;
            const pTop = player.y - player.height / 2 + (player.jumping ? player.jumpHeight : 0);
            const pLeft = player.x - player.width / 2;
            const pRight = player.x + player.width / 2;

            const oLeft = obs.x - obs.width / 2;
            const oRight = obs.x + obs.width / 2;
            const oTop = obs.y - obs.height / 2;
            const oBottom = obs.y + obs.height / 2;

            if (pRight > oLeft && pLeft < oRight && pBottom > oTop && pTop < oBottom) {
                if (player.invincible) {
                    // Smash through obstacles
                    obs.passed = true;
                    score += 50;
                    spawnParticles(obs.x, obs.y, '#ff0', 10, 1, 3);
                } else if (player.sliding && obs.type === 'barrier') {
                    // Can slide under barriers
                    // No collision
                } else if (player.jumping && obs.type === 'trap') {
                    // Can jump over traps
                } else {
                    player.health -= 20;
                    obs.passed = true;
                    shakeTimer = 15;
                    shakeIntensity = 8;
                    playHitSound();
                    spawnParticles(player.x, player.y, '#f44', 15, 1, 4);

                    if (player.health <= 0) {
                        gameOver();
                    }
                }
            }
        }

        if (obs.y > H + 50 && !obs.passed) {
            obs.passed = true;
            score += 10;
        }
    });

    obstacles = obstacles.filter(o => o.y < H + 100);
}

function updateEnemies(dt) {
    const spd = speed * (timeSlowTimer > 0 ? 0.3 : 1);

    enemies.forEach(enemy => {
        if (enemy.hp <= 0) return;

        enemy.y += spd + enemy.speed * 0.5;
        enemy.hitTimer = Math.max(0, enemy.hitTimer - 1);

        // Flying enemies bob up and down
        if (enemy.type === 'flying') {
            enemy.flyingAngle += 0.05;
            enemy.y = enemy.baseY + Math.sin(enemy.flyingAngle) * 30;
        }

        // Enemy attack
        enemy.attackTimer--;
        if (enemy.attackTimer <= 0 && enemy.y > H * 0.2 && enemy.y < H * 0.6) {
            enemy.attackTimer = rand(60, 150);

            // Shoot projectile at player
            if (enemy.type === 'drone' || enemy.type === 'armored') {
                bossProjectiles.push({
                    x: enemy.x,
                    y: enemy.y + 20,
                    vx: (player.x - enemy.x) * 0.02,
                    vy: 4,
                    width: 12,
                    height: 12,
                    color: '#f44',
                    life: 200
                });
            }
        }

        // Collision with player
        if (player.invincible) return;
        const pBottom = player.y + player.height / 2;
        const pTop = player.y - player.height / 2 + (player.jumping ? player.jumpHeight : 0);
        const pLeft = player.x - player.width / 2;
        const pRight = player.x + player.width / 2;

        const eBottom = enemy.y + enemy.height / 2;
        const eTop = enemy.y - enemy.height / 2;
        const eLeft = enemy.x - enemy.width / 2;
        const eRight = enemy.x + enemy.width / 2;

        if (pRight > eLeft && pLeft < eRight && pBottom > eTop && pTop < eBottom) {
            player.health -= 15;
            shakeTimer = 10;
            shakeIntensity = 5;
            playHitSound();
            spawnParticles(player.x, player.y, '#f44', 10, 1, 3);

            if (player.health <= 0) {
                gameOver();
            }
        }

        if (enemy.y > H + 100) {
            enemy.hp = 0;
        }
    });

    enemies = enemies.filter(e => e.hp > 0 || e.y < H + 100);
}

function updateBoss(dt) {
    if (!boss) return;

    const spd = speed * (timeSlowTimer > 0 ? 0.3 : 1);
    bossTimer++;

    // Movement
    boss.moveTimer++;
    if (boss.moveTimer > 90) {
        boss.moveTimer = 0;
        boss.targetX = rand(W * 0.2, W * 0.8);
        boss.targetY = rand(H * 0.1, H * 0.35);
    }

    boss.x = lerp(boss.x, boss.targetX, 0.03);
    boss.y = lerp(boss.y, boss.targetY, 0.03);

    // Rage mode
    if (boss.hp < boss.maxHp * 0.3 && !boss.rageMode) {
        boss.rageMode = true;
        boss.rageTimer = 600;
        boss.color = '#f00';
        addFloatingText(W / 2, H * 0.15, '⚠ RAGE MODE ⚠', '#f00');
        shakeTimer = 30;
        shakeIntensity = 10;
    }

    if (boss.rageMode) {
        boss.rageTimer--;
        if (boss.rageTimer <= 0) {
            boss.rageMode = false;
            boss.color = '#f0f';
        }
    }

    // Shield
    boss.shieldTimer--;
    if (boss.shieldTimer <= 0) {
        boss.shieldActive = !boss.shieldActive;
        boss.shieldTimer = rand(120, 300);
    }

    // Weak point
    boss.weakPointTimer--;
    if (boss.weakPointTimer <= 0) {
        boss.weakPointExposed = !boss.weakPointExposed;
        boss.weakPointTimer = boss.weakPointExposed ? rand(60, 120) : rand(120, 240);
    }

    // Attack patterns
    boss.attackTimer--;
    const attackSpeed = boss.rageMode ? 30 : 60;
    if (boss.attackTimer <= 0) {
        boss.attackTimer = attackSpeed;

        const pattern = randInt(0, 3);

        if (pattern === 0) {
            // Spread shot
            for (let i = -2; i <= 2; i++) {
                bossProjectiles.push({
                    x: boss.x,
                    y: boss.y + boss.height / 2,
                    vx: i * 2,
                    vy: 5,
                    width: 10,
                    height: 10,
                    color: '#f0f',
                    life: 200
                });
            }
        } else if (pattern === 1) {
            // Aimed shot
            bossProjectiles.push({
                x: boss.x,
                y: boss.y + boss.height / 2,
                vx: (player.x - boss.x) * 0.03,
                vy: 6,
                width: 14,
                height: 14,
                color: '#f44',
                life: 200
            });
        } else if (pattern === 2) {
            // Summon minions
            for (let i = 0; i < 2; i++) {
                const lane = randInt(0, 2);
                enemies.push({
                    lane, type: 'drone',
                    x: getLaneX(lane),
                    y: boss.y + 50,
                    baseY: boss.y + 50,
                    width: 35, height: 45,
                    hp: 1, maxHp: 1,
                    speed: 2,
                    color: '#f0f',
                    hit: false, hitTimer: 0,
                    attackTimer: rand(60, 120),
                    flyingAngle: rand(0, Math.PI * 2)
                });
            }
        } else {
            // Ring of projectiles
            for (let i = 0; i < 8; i++) {
                const angle = (i / 8) * Math.PI * 2;
                bossProjectiles.push({
                    x: boss.x,
                    y: boss.y,
                    vx: Math.cos(angle) * 3,
                    vy: Math.sin(angle) * 3 + 3,
                    width: 8,
                    height: 8,
                    color: '#ff0',
                    life: 180
                });
            }
        }
    }

    // Check if player attacks boss
    if (player.attacking && !player.chargeAttack) {
        const bBottom = boss.y + boss.height / 2;
        const bTop = boss.y - boss.height / 2;
        const bLeft = boss.x - boss.width / 2;
        const bRight = boss.x + boss.width / 2;

        const pBottom = player.y + player.height / 2;
        const pTop = player.y - player.height / 2 + (player.jumping ? player.jumpHeight : 0);
        const pLeft = player.x - player.width / 2;
        const pRight = player.x + player.width / 2;

        if (pRight > bLeft && pLeft < bRight && pBottom > bTop && pTop < bBottom) {
            if (boss.weakPointExposed && !boss.shieldActive) {
                boss.hp -= 2;
                spawnParticles(boss.x, boss.y, '#ff0', 15, 1, 5);
                shakeTimer = 8;
                shakeIntensity = 4;
                playHitSound();
                addFloatingText(boss.x, boss.y - 60, '-2!', '#ff0');

                if (boss.hp <= 0) {
                    defeatBoss();
                }
            } else if (!boss.shieldActive) {
                boss.hp -= 1;
                spawnParticles(boss.x, boss.y, '#f80', 8, 1, 3);
                playHitSound();
                if (boss.hp <= 0) defeatBoss();
            } else {
                spawnParticles(boss.x, boss.y, '#0ff', 10, 1, 3);
                playHitSound();
            }
        }
    }

    // Charged attack on boss
    if (player.attacking && player.chargeAttack && player.chargeTimer > 30) {
        if (dist(player.x, player.y, boss.x, boss.y) < 150) {
            if (boss.weakPointExposed && !boss.shieldActive) {
                boss.hp -= 5;
                spawnParticles(boss.x, boss.y, '#f80', 25, 1.5, 7);
                shakeTimer = 15;
                shakeIntensity = 8;
                playExplosionSound();
                addFloatingText(boss.x, boss.y - 60, '-5!', '#f80');
                if (boss.hp <= 0) defeatBoss();
            }
        }
    }

    // Update boss projectiles
    bossProjectiles.forEach(proj => {
        proj.x += proj.vx;
        proj.y += proj.vy;
        proj.life--;

        // Hit player
        if (dist(proj.x, proj.y, player.x, player.y) < 25 && !player.invincible) {
            player.health -= 10;
            proj.life = 0;
            shakeTimer = 8;
            shakeIntensity = 4;
            playHitSound();
            spawnParticles(player.x, player.y, '#f44', 8, 1, 3);

            if (player.health <= 0) gameOver();
        }
    });

    bossProjectiles = bossProjectiles.filter(p => p.life > 0);
}

function defeatBoss() {
    bossDefeated = true;
    spawnParticles(boss.x, boss.y, '#f0f', 50, 2, 8);
    spawnParticles(boss.x, boss.y, '#ff0', 30, 1.5, 6);
    spawnParticles(boss.x, boss.y, '#0ff', 40, 2, 10);
    playExplosionSound();
    shakeTimer = 40;
    shakeIntensity = 12;
    score += 5000;
    addFloatingText(W / 2, H / 2, '🏆 BOSS DEFEATED! 🏆', '#ff0');

    // Reset boss-related state
    boss = null;
    bossProjectiles = [];
    enemies = [];

    // Unlock permanent bonus
    transformDistance = 600;
    bossDistance = 2500;

    // Heal player
    player.health = Math.min(player.maxHealth, player.health + 50);
    player.energy = player.maxEnergy;

    // Speed up
    speed = Math.min(maxSpeed, speed + 1);
}

function updatePickups() {
    pickups.forEach(p => {
        p.bobPhase += 0.05;
        p.life--;

        if (dist(p.x, p.y, player.x, player.y) < 35) {
            if (p.type === 'health') {
                player.health = Math.min(player.maxHealth, player.health + 25);
                addFloatingText(p.x, p.y, '+25 HP', '#0f0');
            } else if (p.type === 'energy') {
                player.energy = Math.min(player.maxEnergy, player.energy + 30);
                addFloatingText(p.x, p.y, '+30 Energy', '#0ff');
            } else if (p.type === 'score') {
                score += 200;
                addFloatingText(p.x, p.y, '+200', '#ff0');
            }
            playPickupSound();
            spawnParticles(p.x, p.y, '#0f0', 10, 1, 3);
            p.life = 0;
        }
    });

    pickups = pickups.filter(p => p.life > 0);
}

function updateParticles() {
    particles.forEach(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.1;
        p.life--;
        p.size *= 0.97;
    });
    particles = particles.filter(p => p.life > 0);
}

function updateFloatingTexts() {
    floatingTexts.forEach(ft => {
        ft.y += ft.vy;
        ft.life--;
    });
    floatingTexts = floatingTexts.filter(ft => ft.life > 0);
}

function updateProjectiles() {
    projectiles.forEach(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.life--;
    });
    projectiles = projectiles.filter(p => p.life > 0);
}

// Spawning
let spawnTimer = 0;
let enemySpawnTimer = 0;
let obstacleSpawnTimer = 0;

function updateSpawning() {
    spawnTimer++;
    const spawnRate = Math.max(20, 60 - distance / 500);

    if (spawnTimer >= spawnRate) {
        spawnTimer = 0;
        spawnObstacle();
    }

    // Spawn enemies after transformation
    if (player.transformed) {
        enemySpawnTimer++;
        const enemyRate = Math.max(30, 90 - distance / 1000);
        if (enemySpawnTimer >= enemyRate) {
            enemySpawnTimer = 0;
            spawnEnemy();
        }
    }

    // Spawn pickups
    if (Math.random() < 0.002) {
        const lane = randInt(0, 2);
        const types = ['health', 'energy', 'score'];
        spawnPickup(getLaneX(lane), -30, types[randInt(0, 2)]);
    }
}

// Rendering
function drawBackground() {
    // Sky gradient
    const skyGrad = ctx.createLinearGradient(0, 0, 0, H);
    if (player.transformed) {
        skyGrad.addColorStop(0, '#0a0020');
        skyGrad.addColorStop(0.5, '#1a0040');
        skyGrad.addColorStop(1, '#0a0030');
    } else {
        skyGrad.addColorStop(0, '#0a0a2e');
        skyGrad.addColorStop(0.5, '#16213e');
        skyGrad.addColorStop(1, '#0a0a2e');
    }
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, W, H);

    // Stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 50; i++) {
        const sx = (i * 137.5 + distance * 0.01) % W;
        const sy = (i * 97.3) % (horizonY);
        const brightness = 0.3 + Math.sin(Date.now() * 0.003 + i) * 0.3;
        ctx.globalAlpha = brightness;
        ctx.fillRect(sx, sy, 1.5, 1.5);
    }
    ctx.globalAlpha = 1;

    // City silhouette
    ctx.fillStyle = '#0a0a1a';
    for (let i = 0; i < 20; i++) {
        const bx = (i * 40 + distance * 0.05) % (W + 80) - 40;
        const bh = 30 + Math.sin(i * 2.5) * 40 + 50;
        const bw = 20 + Math.sin(i * 1.7) * 15;
        ctx.fillRect(bx, horizonY - bh + 20, bw, bh + 50);

        // Windows
        ctx.fillStyle = Math.random() > 0.5 ? '#ff0' : '#0ff';
        ctx.globalAlpha = 0.3;
        for (let wy = 0; wy < bh - 10; wy += 12) {
            for (let wx = 4; wx < bw - 4; wx += 10) {
                if (Math.sin(i * 3 + wy + wx) > 0) {
                    ctx.fillRect(bx + wx, horizonY - bh + 25 + wy, 4, 6);
                }
            }
        }
        ctx.globalAlpha = 1;
        ctx.fillStyle = '#0a0a1a';
    }
}

function drawRoad() {
    const roadLeft = (W - roadWidth) / 2;
    const perspective = 0.85;

    // Road surface
    const roadGrad = ctx.createLinearGradient(0, horizonY, 0, H);
    roadGrad.addColorStop(0, '#1a1a2e');
    roadGrad.addColorStop(1, '#0f0f23');
    ctx.fillStyle = roadGrad;
    ctx.beginPath();
    ctx.moveTo(W / 2 - 5, horizonY);
    ctx.lineTo(W / 2 + 5, horizonY);
    ctx.lineTo(W / 2 + roadWidth / 2 * 2, H);
    ctx.lineTo(W / 2 - roadWidth / 2 * 2, H);
    ctx.fill();

    // Lane dividers
    roadOffset = (roadOffset + speed * (timeSlowTimer > 0 ? 0.3 : 1)) % 40;

    ctx.strokeStyle = player.transformed ? 'rgba(255,0,255,0.4)' : 'rgba(0,255,255,0.3)';
    ctx.lineWidth = 2;
    ctx.setLineDash([20, 20]);
    ctx.lineDashOffset = -roadOffset;

    for (let i = 1; i < 3; i++) {
        const x = roadLeft + i * laneWidth;
        ctx.beginPath();
        ctx.moveTo(x, horizonY);
        ctx.lineTo(x, H);
        ctx.stroke();
    }
    ctx.setLineDash([]);

    // Road edges (neon)
    ctx.strokeStyle = player.transformed ? '#f0f' : '#0ff';
    ctx.lineWidth = 3;
    ctx.shadowColor = player.transformed ? '#f0f' : '#0ff';
    ctx.shadowBlur = 15;

    ctx.beginPath();
    ctx.moveTo(roadLeft, horizonY);
    ctx.lineTo(roadLeft, H);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(roadLeft + roadWidth, horizonY);
    ctx.lineTo(roadLeft + roadWidth, H);
    ctx.stroke();

    ctx.shadowBlur = 0;

    // Grid lines on road
    ctx.strokeStyle = player.transformed ? 'rgba(255,0,255,0.1)' : 'rgba(0,255,255,0.08)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 15; i++) {
        const y = horizonY + (H - horizonY) * (i / 15);
        const spread = (y - horizonY) / (H - horizonY);
        const lx = W / 2 - roadWidth / 2 * spread * 2;
        const rx = W / 2 + roadWidth / 2 * spread * 2;
        ctx.beginPath();
        ctx.moveTo(lx, y);
        ctx.lineTo(rx, y);
        ctx.stroke();
    }
}

function drawPlayer() {
    const px = player.x;
    const py = player.y + player.jumpHeight;
    const pw = player.width;
    const ph = player.sliding ? player.height * 0.4 : player.height;

    // Trail
    player.trail.forEach(t => {
        if (t.alpha > 0) {
            ctx.globalAlpha = t.alpha * 0.3;
            ctx.fillStyle = player.glowColor;
            ctx.fillRect(t.x - pw / 2, t.y - ph / 2, pw, ph);
        }
    });
    ctx.globalAlpha = 1;

    // Glow
    ctx.shadowColor = player.glowColor;
    ctx.shadowBlur = player.invincible ? 30 : 15;

    // Body
    if (player.transformed) {
        // Transformed form - energy warrior
        const bodyGrad = ctx.createLinearGradient(px - pw / 2, py - ph / 2, px + pw / 2, py + ph / 2);
        bodyGrad.addColorStop(0, '#f0f');
        bodyGrad.addColorStop(0.5, '#80f');
        bodyGrad.addColorStop(1, '#f0f');
        ctx.fillStyle = bodyGrad;

        // Main body
        ctx.beginPath();
        ctx.moveTo(px, py - ph / 2);
        ctx.lineTo(px + pw / 2, py - ph / 6);
        ctx.lineTo(px + pw / 3, py + ph / 2);
        ctx.lineTo(px - pw / 3, py + ph / 2);
        ctx.lineTo(px - pw / 2, py - ph / 6);
        ctx.closePath();
        ctx.fill();

        // Energy aura
        ctx.strokeStyle = player.glowColor;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5 + Math.sin(Date.now() * 0.01) * 0.3;
        ctx.beginPath();
        ctx.arc(px, py, pw, 0, Math.PI * 2);
        ctx.stroke();
        ctx.globalAlpha = 1;

        // Eyes
        ctx.fillStyle = '#fff';
        ctx.fillRect(px - 8, py - ph / 4, 6, 4);
        ctx.fillRect(px + 2, py - ph / 4, 6, 4);
    } else {
        // Normal form
        ctx.fillStyle = '#0ff';
        ctx.fillRect(px - pw / 2, py - ph / 2, pw, ph);

        // Visor
        ctx.fillStyle = '#fff';
        ctx.fillRect(px - 10, py - ph / 3, 20, 6);

        // Running animation
        const runFrame = Math.sin(Date.now() * 0.015) * 5;
        ctx.fillStyle = '#08f';
        ctx.fillRect(px - 12, py + ph / 2 - 5, 8, 10 + runFrame);
        ctx.fillRect(px + 4, py + ph / 2 - 5, 8, 10 - runFrame);
    }

    // Attack visual
    if (player.attacking) {
        const attackProgress = 1 - player.attackTimer / 15;
        const attackAngle = attackProgress * Math.PI;

        ctx.strokeStyle = player.chargeAttack ? '#f80' : '#ff0';
        ctx.lineWidth = player.chargeAttack ? 5 : 3;
        ctx.shadowColor = player.chargeAttack ? '#f80' : '#ff0';
        ctx.shadowBlur = 20;

        ctx.beginPath();
        ctx.arc(px + pw / 2, py, 30 + (player.chargeAttack ? attackProgress * 40 : 0), -attackAngle, attackAngle);
        ctx.stroke();

        if (player.chargeAttack && player.chargeTimer > 30) {
            ctx.strokeStyle = '#ff0';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(px + pw / 2, py, 50 + attackProgress * 30, -attackAngle * 0.8, attackAngle * 0.8);
            ctx.stroke();
        }
    }

    // Invincibility visual
    if (player.invincible) {
        ctx.strokeStyle = `rgba(255,0,255,${0.5 + Math.sin(Date.now() * 0.02) * 0.3})`;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(px, py, pw + 10 + Math.sin(Date.now() * 0.01) * 5, 0, Math.PI * 2);
        ctx.stroke();
    }

    ctx.shadowBlur = 0;
}

function drawObstacles() {
    obstacles.forEach(obs => {
        ctx.shadowColor = obs.color;
        ctx.shadowBlur = 10;

        if (obs.type === 'barrier') {
            ctx.fillStyle = '#f80';
            ctx.fillRect(obs.x - obs.width / 2, obs.y - obs.height / 2, obs.width, obs.height);
            // Stripes
            ctx.fillStyle = '#000';
            for (let i = 0; i < 3; i++) {
                ctx.fillRect(obs.x - obs.width / 2 + 5 + i * 15, obs.y - obs.height / 2, 8, obs.height);
            }
        } else if (obs.type === 'car') {
            ctx.fillStyle = '#f44';
            ctx.fillRect(obs.x - obs.width / 2, obs.y - obs.height / 2, obs.width, obs.height);
            // Windshield
            ctx.fillStyle = '#0af';
            ctx.fillRect(obs.x - obs.width / 2 + 5, obs.y - obs.height / 2 + 5, obs.width - 10, 15);
            // Tail lights
            ctx.fillStyle = '#ff0';
            ctx.fillRect(obs.x - obs.width / 2 + 3, obs.y + obs.height / 2 - 8, 8, 5);
            ctx.fillRect(obs.x + obs.width / 2 - 11, obs.y + obs.height / 2 - 8, 8, 5);
        } else if (obs.type === 'trap') {
            ctx.fillStyle = '#ff0';
            // Spikes
            for (let i = 0; i < 4; i++) {
                ctx.beginPath();
                ctx.moveTo(obs.x - 15 + i * 10, obs.y + obs.height / 2);
                ctx.lineTo(obs.x - 10 + i * 10, obs.y - obs.height / 2);
                ctx.lineTo(obs.x - 5 + i * 10, obs.y + obs.height / 2);
                ctx.fill();
            }
        }

        ctx.shadowBlur = 0;
    });
}

function drawEnemies() {
    enemies.forEach(enemy => {
        if (enemy.hp <= 0) return;

        const ex = enemy.x;
        const ey = enemy.y + (enemy.type === 'flying' ? -40 : 0);

        ctx.shadowColor = enemy.hit ? '#fff' : enemy.color;
        ctx.shadowBlur = enemy.hit ? 20 : 10;
        ctx.fillStyle = enemy.hit ? '#fff' : enemy.color;

        if (enemy.type === 'drone') {
            // Diamond shape
            ctx.beginPath();
            ctx.moveTo(ex, ey - enemy.height / 2);
            ctx.lineTo(ex + enemy.width / 2, ey);
            ctx.lineTo(ex, ey + enemy.height / 2);
            ctx.lineTo(ex - enemy.width / 2, ey);
            ctx.closePath();
            ctx.fill();
            // Eye
            ctx.fillStyle = '#f00';
            ctx.fillRect(ex - 4, ey - 3, 8, 6);
        } else if (enemy.type === 'armored') {
            // Hexagonal shape
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (i / 6) * Math.PI * 2 - Math.PI / 2;
                const r = enemy.width / 2;
                ctx.lineTo(ex + Math.cos(angle) * r, ey + Math.sin(angle) * r);
            }
            ctx.closePath();
            ctx.fill();
            // HP indicator
            ctx.fillStyle = '#0f0';
            for (let i = 0; i < enemy.hp; i++) {
                ctx.fillRect(ex - 10 + i * 8, ey - enemy.height / 2 - 10, 5, 4);
            }
        } else if (enemy.type === 'flying') {
            // Bat-like shape
            ctx.beginPath();
            ctx.moveTo(ex, ey + enemy.height / 2);
            ctx.lineTo(ex + enemy.width / 2, ey - enemy.height / 4);
            ctx.lineTo(ex + enemy.width / 3, ey);
            ctx.lineTo(ex + enemy.width / 2, ey - enemy.height / 2);
            ctx.lineTo(ex, ey - enemy.height / 3);
            ctx.lineTo(ex - enemy.width / 2, ey - enemy.height / 2);
            ctx.lineTo(ex - enemy.width / 3, ey);
            ctx.lineTo(ex - enemy.width / 2, ey - enemy.height / 4);
            ctx.closePath();
            ctx.fill();
            // Eyes
            ctx.fillStyle = '#ff0';
            ctx.fillRect(ex - 6, ey - 5, 4, 4);
            ctx.fillRect(ex + 2, ey - 5, 4, 4);
        } else if (enemy.type === 'speed') {
            // Arrow shape
            ctx.beginPath();
            ctx.moveTo(ex, ey - enemy.height / 2);
            ctx.lineTo(ex + enemy.width / 2, ey + enemy.height / 2);
            ctx.lineTo(ex, ey + enemy.height / 4);
            ctx.lineTo(ex - enemy.width / 2, ey + enemy.height / 2);
            ctx.closePath();
            ctx.fill();
        }

        ctx.shadowBlur = 0;
    });
}

function drawBoss() {
    if (!boss) return;

    const bx = boss.x;
    const by = boss.y;

    // Shield
    if (boss.shieldActive) {
        ctx.strokeStyle = `rgba(0,255,255,${0.5 + Math.sin(Date.now() * 0.01) * 0.3})`;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(bx, by, boss.width / 2 + 15, 0, Math.PI * 2);
        ctx.stroke();
    }

    // Weak point indicator
    if (boss.weakPointExposed) {
        ctx.strokeStyle = '#ff0';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(bx, by, boss.width / 2 + 5, 0, Math.PI * 2);
        ctx.stroke();
    }

    // Boss body
    ctx.shadowColor = boss.color;
    ctx.shadowBlur = 20;

    const bodyGrad = ctx.createRadialGradient(bx, by, 10, bx, by, boss.width / 2);
    bodyGrad.addColorStop(0, boss.color);
    bodyGrad.addColorStop(1, '#200');
    ctx.fillStyle = bodyGrad;

    // Main body
    ctx.beginPath();
    ctx.moveTo(bx, by - boss.height / 2);
    ctx.lineTo(bx + boss.width / 2, by - boss.height / 4);
    ctx.lineTo(bx + boss.width / 2, by + boss.height / 4);
    ctx.lineTo(bx + boss.width / 3, by + boss.height / 2);
    ctx.lineTo(bx - boss.width / 3, by + boss.height / 2);
    ctx.lineTo(bx - boss.width / 2, by + boss.height / 4);
    ctx.lineTo(bx - boss.width / 2, by - boss.height / 4);
    ctx.closePath();
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(bx - 15, by - 10, 8, 0, Math.PI * 2);
    ctx.arc(bx + 15, by - 10, 8, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = boss.rageMode ? '#f00' : '#f0f';
    ctx.beginPath();
    ctx.arc(bx - 15, by - 10, 4, 0, Math.PI * 2);
    ctx.arc(bx + 15, by - 10, 4, 0, Math.PI * 2);
    ctx.fill();

    // Crown/horns
    ctx.fillStyle = boss.color;
    for (let i = -1; i <= 1; i++) {
        ctx.beginPath();
        ctx.moveTo(bx + i * 20 - 5, by - boss.height / 2);
        ctx.lineTo(bx + i * 20, by - boss.height / 2 - 20);
        ctx.lineTo(bx + i * 20 + 5, by - boss.height / 2);
        ctx.fill();
    }

    ctx.shadowBlur = 0;

    // Boss name
    ctx.fillStyle = '#f0f';
    ctx.font = 'bold 14px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(boss.name, bx, by - boss.height / 2 - 30);

    // Boss HP bar
    const barWidth = 200;
    const barHeight = 12;
    const barX = bx - barWidth / 2;
    const barY = by - boss.height / 2 - 20;

    ctx.fillStyle = '#300';
    ctx.fillRect(barX, barY, barWidth, barHeight);

    const hpRatio = boss.hp / boss.maxHp;
    const hpColor = hpRatio > 0.5 ? '#f0f' : hpRatio > 0.3 ? '#f80' : '#f00';
    ctx.fillStyle = hpColor;
    ctx.fillRect(barX, barY, barWidth * hpRatio, barHeight);

    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.strokeRect(barX, barY, barWidth, barHeight);

    // Rage mode indicator
    if (boss.rageMode) {
        ctx.fillStyle = '#f00';
        ctx.font = 'bold 12px Arial';
        ctx.fillText('🔥 RAGE MODE 🔥', bx, barY - 5);
    }
}

function drawBossProjectiles() {
    bossProjectiles.forEach(proj => {
        ctx.shadowColor = proj.color;
        ctx.shadowBlur = 10;
        ctx.fillStyle = proj.color;
        ctx.beginPath();
        ctx.arc(proj.x, proj.y, proj.width / 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;
    });
}

function drawPickups() {
    pickups.forEach(p => {
        const bob = Math.sin(p.bobPhase) * 5;
        const alpha = p.life < 60 ? p.life / 60 : 1;

        ctx.globalAlpha = alpha;
        ctx.shadowColor = p.type === 'health' ? '#0f0' : p.type === 'energy' ? '#0ff' : '#ff0';
        ctx.shadowBlur = 10;

        if (p.type === 'health') {
            ctx.fillStyle = '#0f0';
            ctx.fillRect(p.x - 10, p.y - 4 + bob, 20, 8);
            ctx.fillRect(p.x - 4, p.y - 10 + bob, 8, 20);
        } else if (p.type === 'energy') {
            ctx.fillStyle = '#0ff';
            ctx.beginPath();
            ctx.moveTo(p.x, p.y - 12 + bob);
            ctx.lineTo(p.x + 5, p.y - 2 + bob);
            ctx.lineTo(p.x, p.y + 2 + bob);
            ctx.lineTo(p.x + 3, p.y + 12 + bob);
            ctx.lineTo(p.x - 7, p.y + 2 + bob);
            ctx.lineTo(p.x - 2, p.y - 2 + bob);
            ctx.lineTo(p.x - 5, p.y - 12 + bob);
            ctx.closePath();
            ctx.fill();
        } else {
            ctx.fillStyle = '#ff0';
            ctx.beginPath();
            ctx.arc(p.x, p.y + bob, 10, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#000';
            ctx.font = 'bold 10px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('$', p.x, p.y + 4 + bob);
        }

        ctx.shadowBlur = 0;
        ctx.globalAlpha = 1;
    });
}

function drawParticles() {
    particles.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
    });
    ctx.globalAlpha = 1;
}

function drawFloatingTexts() {
    floatingTexts.forEach(ft => {
        ctx.globalAlpha = ft.life / 60;
        ctx.fillStyle = ft.color;
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.shadowColor = ft.color;
        ctx.shadowBlur = 10;
        ctx.fillText(ft.text, ft.x, ft.y);
        ctx.shadowBlur = 0;
    });
    ctx.globalAlpha = 1;
}

function drawHUD() {
    const padding = 15;

    // Score
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 20px Arial';
    ctx.textAlign = 'left';
    ctx.fillText(`SCORE: ${Math.floor(score)}`, padding, 30);

    // Distance
    ctx.fillStyle = '#aaa';
    ctx.font = '14px Arial';
    ctx.fillText(`${Math.floor(distance)}m`, padding, 50);

    // Combo
    if (comboCount > 1) {
        ctx.fillStyle = '#ff0';
        ctx.font = 'bold 16px Arial';
        ctx.fillText(`COMBO x${comboCount}`, padding, 70);
    }

    // Health bar
    const hbX = W - padding - 150;
    const hbY = 15;
    const hbW = 150;
    const hbH = 14;

    ctx.fillStyle = '#300';
    ctx.fillRect(hbX, hbY, hbW, hbH);
    const healthRatio = player.health / player.maxHealth;
    ctx.fillStyle = healthRatio > 0.5 ? '#0f0' : healthRatio > 0.25 ? '#f80' : '#f00';
    ctx.fillRect(hbX, hbY, hbW * healthRatio, hbH);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.strokeRect(hbX, hbY, hbW, hbH);

    ctx.fillStyle = '#fff';
    ctx.font = '10px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(`HP ${Math.ceil(player.health)}/${player.maxHealth}`, hbX + hbW / 2, hbY + 11);

    // Energy bar
    const ebY = hbY + 22;
    ctx.fillStyle = '#003';
    ctx.fillRect(hbX, ebY, hbW, hbH);
    const energyRatio = player.energy / player.maxEnergy;
    ctx.fillStyle = player.transformed ? '#f0f' : '#0ff';
    ctx.fillRect(hbX, ebY, hbW * energyRatio, hbH);
    ctx.strokeRect(hbX, ebY, hbW, hbH);

    ctx.fillStyle = '#fff';
    ctx.fillText(player.transformed ? 'ENERGY' : 'TRANSFORM', hbX + hbW / 2, ebY + 11);

    // Power meter
    const pbY = ebY + 22;
    ctx.fillStyle = '#202';
    ctx.fillRect(hbX, pbY, hbW, hbH);
    const powerRatio = player.powerMeter / player.maxPower;
    ctx.fillStyle = player.specialReady ? '#ff0' : '#f0f';
    ctx.fillRect(hbX, pbY, hbW * powerRatio, hbH);
    ctx.strokeRect(hbX, pbY, hbW, hbH);

    ctx.fillStyle = player.specialReady ? '#ff0' : '#fff';
    ctx.fillText(player.specialReady ? '⚡ SPECIAL [P] ⚡' : 'POWER', hbX + hbW / 2, pbY + 11);

    // Transform progress
    if (!player.transformed && player.transformTimer <= 0) {
        const tp = Math.min(1, distance / transformDistance);
        const tpY = pbY + 22;
        ctx.fillStyle = '#111';
        ctx.fillRect(hbX, tpY, hbW, 8);
        ctx.fillStyle = '#0ff';
        ctx.fillRect(hbX, tpY, hbW * tp, 8);
        ctx.fillStyle = '#888';
        ctx.font = '9px Arial';
        ctx.fillText(`TRANSFORM ${Math.floor(tp * 100)}%`, hbX + hbW / 2, tpY + 8);
    }

    // Speed indicator
    ctx.fillStyle = '#666';
    ctx.font = '12px Arial';
    ctx.textAlign = 'right';
    ctx.fillText(`SPEED: ${speed.toFixed(1)}`, W - padding, H - 20);

    // State indicator
    if (player.transformed) {
        ctx.fillStyle = '#f0f';
        ctx.font = 'bold 14px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('⚡ TRANSFORMED ⚡', W / 2, 25);
    }

    if (timeSlowTimer > 0) {
        ctx.fillStyle = '#f0f';
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.globalAlpha = 0.5 + Math.sin(Date.now() * 0.01) * 0.3;
        ctx.fillText('⏳ TIME SLOW ⏳', W / 2, H / 2 - 50);
        ctx.globalAlpha = 1;
    }

    // Boss warning
    if (gameState === STATE.BOSS && boss) {
        ctx.fillStyle = '#f00';
        ctx.font = 'bold 24px Arial';
        ctx.textAlign = 'center';
        ctx.globalAlpha = 0.5 + Math.sin(Date.now() * 0.005) * 0.3;
        ctx.fillText('⚠ BOSS ARENA ⚠', W / 2, 60);
        ctx.globalAlpha = 1;
    }
}

function drawTransformEffect() {
    if (transformFlash > 0) {
        ctx.globalAlpha = transformFlash / 30;
        ctx.fillStyle = '#fff';
        ctx.fillRect(0, 0, W, H);
        ctx.globalAlpha = 1;
        transformFlash--;
    }

    if (gameState === STATE.TRANSFORMING) {
        transformProgress += 0.02;
        transformFlash = 15;

        // Swirling particles
        for (let i = 0; i < 5; i++) {
            const angle = transformProgress * 3 + i * Math.PI * 2 / 5;
            const r = 100 + Math.sin(transformProgress * 5 + i) * 50;
            const px = W / 2 + Math.cos(angle) * r;
            const py = H / 2 + Math.sin(angle) * r;
            ctx.fillStyle = '#f0f';
            ctx.beginPath();
            ctx.arc(px, py, 5, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.fillStyle = '#fff';
        ctx.font = 'bold 30px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('SHIFTS!', W / 2, H / 2);

        if (transformProgress >= 1) {
            player.transformed = true;
            player.glowColor = '#f0f';
            player.color = '#f0f';
            gameState = STATE.COMBAT;
        }
    }
}

// Main game loop
let lastTime = 0;
function gameLoop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;

    // Screen shake
    ctx.save();
    if (shakeTimer > 0) {
        shakeTimer--;
        const sx = (Math.random() - 0.5) * shakeIntensity;
        const sy = (Math.random() - 0.5) * shakeIntensity;
        ctx.translate(sx, sy);
    }

    // Clear
    ctx.clearRect(-10, -10, W + 20, H + 20);

    // Draw background
    drawBackground();
    drawRoad();

    if (gameState === STATE.MENU) {
        // Animated menu background
        drawPlayer();
        drawParticles();

        // Spawn some ambient particles
        if (Math.random() < 0.1) {
            spawnParticles(rand(0, W), rand(0, H), '#0ff', 1, 0.5, 2);
        }
    } else if (gameState === STATE.RUNNING || gameState === STATE.COMBAT || gameState === STATE.BOSS) {
        // Update
        updatePlayer();

        if (gameState === STATE.RUNNING) {
            distance += speed * 0.1;
            speed = Math.min(maxSpeed, 5 + distance / 1000);
            difficultyMultiplier = 1 + distance / 5000;

            updateObstacles(dt);
            updateSpawning();

            // Check transform
            if (distance >= transformDistance && !player.transformed && player.transformTimer <= 0) {
                gameState = STATE.TRANSFORMING;
                transformProgress = 0;
                transformFlash = 30;
                player.transformed = false;
                playTransformSound();
            }
        }

        if (gameState === STATE.COMBAT || gameState === STATE.BOSS) {
            distance += speed * 0.1;
            speed = Math.min(maxSpeed, 6 + distance / 800);
            difficultyMultiplier = 1 + distance / 4000;

            updateObstacles(dt);
            updateEnemies(dt);
            updatePickups();
            updateSpawning();

            // Check boss
            if (distance >= bossDistance && !boss && !bossDefeated) {
                gameState = STATE.BOSS;
                initBoss();
            }

            if (gameState === STATE.BOSS) {
                updateBoss(dt);
            }

            // Time slow
            if (timeSlowTimer > 0) timeSlowTimer--;
        }

        updateParticles();
        updateFloatingTexts();

        // Draw game elements
        drawObstacles();
        drawEnemies();
        drawBoss();
        drawBossProjectiles();
        drawPickups();
        drawPlayer();
        drawParticles();
        drawFloatingTexts();
        drawTransformEffect();
        drawHUD();

        // Time slow overlay
        if (timeSlowTimer > 0) {
            ctx.fillStyle = `rgba(255,0,255,${0.05 + Math.sin(Date.now() * 0.005) * 0.03})`;
            ctx.fillRect(0, 0, W, H);
        }
    } else if (gameState === STATE.GAMEOVER) {
        drawObstacles();
        drawEnemies();
        drawBoss();
        drawParticles();
        drawPlayer();
    }

    ctx.restore();

    requestAnimationFrame(gameLoop);
}

// Ambient particles for menu
function menuLoop() {
    if (gameState === STATE.MENU) {
        if (Math.random() < 0.15) {
            spawnParticles(rand(0, W), rand(0, H), Math.random() > 0.5 ? '#0ff' : '#f0f', 1, 0.5, 2);
        }
        updateParticles();
    }
}

setInterval(menuLoop, 16);

// Start the game loop
requestAnimationFrame(gameLoop);
</script>
