// ============ AUDIO SYSTEM ============
const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

function playSound(type, volume = 0.3) {
const osc = audioCtx.createOscillator();
const gain = audioCtx.createGain();
const filter = audioCtx.createBiquadFilter();
osc.connect(filter);
filter.connect(gain);
gain.connect(audioCtx.destination);

const now = audioCtx.currentTime;

switch(type) {
case 'rifle':
osc.type = 'sawtooth';
osc.frequency.setValueAtTime(150, now);
osc.frequency.exponentialRampToValueAtTime(50, now + 0.1);
filter.type = 'lowpass';
filter.frequency.setValueAtTime(3000, now);
filter.frequency.exponentialRampToValueAtTime(200, now + 0.15);
gain.gain.setValueAtTime(volume, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
osc.start(now);
osc.stop(now + 0.15);
// Add noise burst
const noise = audioCtx.createBufferSource();
const buf = audioCtx.createBuffer(1, audioCtx.sampleRate * 0.08, audioCtx.sampleRate);
const data = buf.getChannelData(0);
for(let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (audioCtx.sampleRate * 0.02));
noise.buffer = buf;
const ng = audioCtx.createGain();
const nf = audioCtx.createBiquadFilter();
nf.type = 'bandpass'; nf.frequency.value = 1000;
noise.connect(nf); nf.connect(ng); ng.connect(audioCtx.destination);
ng.gain.setValueAtTime(volume * 0.8, now);
ng.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
noise.start(now);
break;
case 'pistol':
osc.type = 'square';
osc.frequency.setValueAtTime(200, now);
osc.frequency.exponentialRampToValueAtTime(80, now + 0.08);
filter.type = 'lowpass';
filter.frequency.setValueAtTime(2000, now);
filter.frequency.exponentialRampToValueAtTime(100, now + 0.1);
gain.gain.setValueAtTime(volume * 0.7, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
osc.start(now);
osc.stop(now + 0.1);
break;
case 'shotgun':
osc.type = 'sawtooth';
osc.frequency.setValueAtTime(100, now);
osc.frequency.exponentialRampToValueAtTime(30, now + 0.2);
filter.type = 'lowpass';
filter.frequency.setValueAtTime(2000, now);
filter.frequency.exponentialRampToValueAtTime(100, now + 0.25);
gain.gain.setValueAtTime(volume * 1.2, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);
osc.start(now);
osc.stop(now + 0.25);
break;
case 'hit':
osc.type = 'sine';
osc.frequency.setValueAtTime(800, now);
osc.frequency.exponentialRampToValueAtTime(200, now + 0.1);
gain.gain.setValueAtTime(volume * 0.3, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
osc.start(now);
osc.stop(now + 0.1);
break;
case 'enemyDie':
osc.type = 'sawtooth';
osc.frequency.setValueAtTime(400, now);
osc.frequency.exponentialRampToValueAtTime(50, now + 0.5);
gain.gain.setValueAtTime(volume * 0.5, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
osc.start(now);
osc.stop(now + 0.5);
break;
case 'reload':
osc.type = 'sine';
osc.frequency.setValueAtTime(600, now);
osc.frequency.setValueAtTime(800, now + 0.1);
osc.frequency.setValueAtTime(500, now + 0.2);
gain.gain.setValueAtTime(volume * 0.2, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
osc.start(now);
osc.stop(now + 0.3);
break;
case 'pickup':
osc.type = 'sine';
osc.frequency.setValueAtTime(400, now);
osc.frequency.setValueAtTime(600, now + 0.1);
osc.frequency.setValueAtTime(800, now + 0.2);
gain.gain.setValueAtTime(volume * 0.3, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
osc.start(now);
osc.stop(now + 0.3);
break;
case 'geiger':
osc.type = 'square';
osc.frequency.setValueAtTime(2000 + Math.random() * 1000, now);
gain.gain.setValueAtTime(volume * 0.05, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.02);
osc.start(now);
osc.stop(now + 0.02);
break;
case 'hurt':
osc.type = 'sawtooth';
osc.frequency.setValueAtTime(200, now);
osc.frequency.exponentialRampToValueAtTime(100, now + 0.2);
gain.gain.setValueAtTime(volume * 0.4, now);
gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
osc.start(now);
osc.stop(now + 0.2);
break;
case 'step':
const stepNoise = audioCtx.createBufferSource();
const stepBuf = audioCtx.createBuffer(1, audioCtx.sampleRate * 0.05, audioCtx.sampleRate);
const stepData = stepBuf.getChannelData(0);
for(let i = 0; i < stepData.length; i++) stepData[i] = (Math.random() * 2 - 1) * Math.exp(-i / (audioCtx.sampleRate * 0.01)) * 0.3;
stepNoise.buffer = stepBuf;
const sg = audioCtx.createGain();
const sf = audioCtx.createBiquadFilter();
sf.type = 'lowpass'; sf.frequency.value = 500;
stepNoise.connect(sf); sf.connect(sg); sg.connect(audioCtx.destination);
sg.gain.setValueAtTime(volume * 0.15, now);
stepNoise.start(now);
break;
}
}

