function createTunnelSegment(x, z, length, width, height, direction) {
const group = new THREE.Group();
group.position.set(x, 0, z);

// Floor
const floorGeo = new THREE.PlaneGeometry(width, length);
const floor = new THREE.Mesh(floorGeo, concreteMat);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
group.add(floor);

// Ceiling
const ceiling = new THREE.Mesh(floorGeo, darkConcreteMat);
ceiling.rotation.x = Math.PI / 2;
ceiling.position.y = height;
group.add(ceiling);

// Walls
const wallGeo = new THREE.PlaneGeometry(length, height);
const leftWall = new THREE.Mesh(wallGeo, concreteMat);
leftWall.position.set(-width / 2, height / 2, 0);
leftWall.rotation.y = Math.PI / 2;
leftWall.receiveShadow = true;
group.add(leftWall);

const rightWall = new THREE.Mesh(wallGeo, concreteMat);
rightWall.position.set(width / 2, height / 2, 0);
rightWall.rotation.y = -Math.PI / 2;
rightWall.receiveShadow = true;
group.add(rightWall);

// Add details
if (Math.random() > 0.5) {
// Pipes on ceiling
for (let i = 0; i < 3; i++) {
const pipeGeo = new THREE.CylinderGeometry(0.05, 0.05, length * 0.8);
const pipe = new THREE.Mesh(pipeGeo, rustMat);
pipe.rotation.x = Math.PI / 2;
pipe.position.set((Math.random() - 0.5) * width * 0.5, height - 0.1, (Math.random() - 0.5) * length * 0.5);
group.add(pipe);
}
}

// Tiles on walls
if (Math.random() > 0.4) {
const tileGeo = new THREE.PlaneGeometry(0.5, 0.5);
for (let wy = 0; wy < height - 1; wy += 0.6) {
for (let tz = -length / 2 + 0.5; tz < length / 2; tz += 0.6) {
if (Math.random() > 0.3) {
const tile = new THREE.Mesh(tileGeo, tileMat);
tile.position.set(-width / 2 + 0.01, wy + 1, tz);
tile.rotation.y = Math.PI / 2;
group.add(tile);
const tile2 = tile.clone();
tile2.position.x = width / 2 - 0.01;
tile2.rotation.y = -Math.PI / 2;
group.add(tile2);
}
}
}
}

// Random debris
if (Math.random() > 0.5) {
for (let i = 0; i < 5; i++) {
const debrisGeo = new THREE.BoxGeometry(
0.1 + Math.random() * 0.3,
0.1 + Math.random() * 0.3,
0.1 + Math.random() * 0.3
);
const debris = new THREE.Mesh(debrisGeo, darkConcreteMat);
debris.position.set(
(Math.random() - 0.5) * width * 0.8,
0.05,
(Math.random() - 0.5) * length * 0.8
);
debris.rotation.set(Math.random(), Math.random(), Math.random());
group.add(debris);
}
}

// Radiation patches
if (currentZone >= 3) {
const radGeo = new THREE.PlaneGeometry(2, 2);
const radMat = new THREE.MeshStandardMaterial({
color: 0x00ff00, emissive: 0x00ff00, emissiveIntensity: 0.2,
transparent: true, opacity: 0.3
});
const radPatch = new THREE.Mesh(radGeo, radMat);
radPatch.rotation.x = -Math.PI / 2;
radPatch.position.set((Math.random() - 0.5) * width * 0.5, 0.01, (Math.random() - 0.5) * length * 0.5);
group.add(radPatch);
}

scene.add(group);
tunnelSegments.push(group);
return { x, z, length, width, height, direction, group };
}

function buildMetroMap() {
// Main tunnel going forward
let cx = 0, cz = 0;
const directions = ['z', 'x', 'z', 'x', 'z', 'x', 'z', 'x', 'z'];

for (let i = 0; i < 20; i++) {
const dir = directions[i % directions.length];
const length = 15 + Math.random() * 20;
const width = 4 + Math.random() * 2;
const height = 3 + Math.random() * 1.5;

if (dir === 'z') {
createTunnelSegment(cx, cz, length, width, height, 'z');
cz += length;
} else {
createTunnelSegment(cx, cz, length, width, height, 'x');
cx += length;
}
}

// Branch tunnels
for (let i = 0; i < 8; i++) {
const parentIdx = Math.floor(Math.random() * tunnelSegments.length);
const parent = tunnelSegments[parentIdx];
const branchDir = Math.random() > 0.5 ? 'x' : 'z';
const bx = parent.group.position.x + (branchDir === 'x' ? (Math.random() > 0.5 ? parent.width / 2 : -parent.width / 2) : 0);
const bz = parent.group.position.z + (branchDir === 'z' ? (Math.random() > 0.5 ? parent.length / 2 : -parent.length / 2) : 0);
const bLen = 8 + Math.random() * 12;
const bWidth = 3 + Math.random() * 2;
const bHeight = 2.5 + Math.random();
createTunnelSegment(bx, bz, bLen, bWidth, bHeight, branchDir);
}

// Station platforms (wider sections)
for (let i = 0; i < 3; i++) {
const sx = (Math.random() - 0.5) * 60;
const sz = (Math.random() - 0.5) * 60;
const platformGeo = new THREE.BoxGeometry(12, 0.3, 20);
const platform = new THREE.Mesh(platformGeo, concreteMat);
platform.position.set(sx, 0.15, sz);
platform.receiveShadow = true;
scene.add(platform);

// Station lights
for (let lx = -4; lx <= 4; lx += 4) {
for (let lz = -8; lz <= 8; lz += 4) {
const light = new THREE.PointLight(0xffaa44, 0.5, 10);
light.position.set(sx + lx, 2.5, sz + lz);
scene.add(light);
}
}

// Benches
for (let b = 0; b < 3; b++) {
const benchGeo = new THREE.BoxGeometry(2, 0.5, 0.5);
const bench = new THREE.Mesh(benchGeo, rustMat);
bench.position.set(sx + (b - 1) * 4, 0.55, sz - 6);
scene.add(bench);
}

// Pillars
for (let px = -4; px <= 4; px += 4) {
for (let pz = -6; pz <= 6; pz += 6) {
const pillarGeo = new THREE.CylinderGeometry(0.2, 0.2, 3);
const pillar = new THREE.Mesh(pillarGeo, concreteMat);
pillar.position.set(sx + px, 1.5, sz + pz);
pillar.castShadow = true;
scene.add(pillar);
}
}
}

// Escape tunnel at the end
const escapeX = cx + 10;
const escapeZ = cz;
createTunnelSegment(escapeX, escapeZ, 30, 6, 4, 'z');

// Escape marker
const escapeGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.1, 8);
const escapeMesh = new THREE.Mesh(escapeGeo, escapeMat);
escapeMesh.position.set(escapeX, 0.5, escapeZ + 15);
scene.add(escapeMesh);

const escapeLight = new THREE.PointLight(0x00ff88, 2, 15);
escapeLight.position.set(escapeX, 3, escapeZ + 15);
scene.add(escapeLight);

// Add a sign
const signGeo = new THREE.BoxGeometry(2, 0.6, 0.1);
const signMat = new THREE.MeshStandardMaterial({ color: 0x00ff88, emissive: 0x00ff88, emissiveIntensity: 0.5 });
const sign = new THREE.Mesh(signGeo, signMat);
sign.position.set(escapeX, 2.5, escapeZ + 15);
scene.add(sign);

// Spawn pickups
spawnPickups();

// Spawn enemies
spawnEnemies();
}

