const grip = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.08, 0.035), new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.7 }));
grip.position.set(0.3, -0.32, -0.15);
grip.rotation.x = 0.15;
weaponGroup.add(grip);

} else { // Sawn-Off
const body = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.06, 0.35), new THREE.MeshStandardMaterial({ color: 0x3a2a1a, roughness: 0.7, metalness: 0.4 }));
body.position.set(0.3, -0.25, -0.35);
weaponGroup.add(body);

const barrel1 = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.2, 8), metalMat);
barrel1.rotation.x = Math.PI / 2;
barrel1.position.set(0.28, -0.24, -0.55);
weaponGroup.add(barrel1);

const barrel2 = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.2, 8), metalMat);
barrel2.rotation.x = Math.PI / 2;
barrel2.position.set(0.32, -0.24, -0.55);
weaponGroup.add(barrel2);

const stock = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.05, 0.2), new THREE.MeshStandardMaterial({ color: 0x4a3520, roughness: 0.8 }));
stock.position.set(0.3, -0.24, -0.1);
weaponGroup.add(stock);
}

weaponGroup.position.set(0.25, -0.3, -0.5);
}

buildWeaponModel();

// ============ PLAYER CONTROLS ============
const keys = {};
let mouseX = 0, mouseY = 0;
let yaw = 0, pitch = 0;
let isLocked = false;
let velocityY = 0;
let isGrounded = true;
let weaponBob = 0;
let isReloading = false;
let reloadTimer = 0;
let lastFireTime = 0;
let muzzleFlash = null;

document.addEventListener('keydown', e => { keys[e.code] = true; });
document.addEventListener('keyup', e => { keys[e.code] = false; });

document.addEventListener('mousemove', e => {
if (!isLocked) return;
yaw -= e.movementX * 0.002;
pitch -= e.movementY * 0.002;
pitch = Math.max(-Math.PI / 2.2, Math.min(Math.PI / 2.2, pitch));
});

document.addEventListener('mousedown', e => {
if (!isLocked || STATE.gameOver) return;
if (e.button === 0) shoot();
});

document.addEventListener('pointerlockchange', () => {
isLocked = document.pointerLockElement === renderer.domElement;
if (isLocked && STATE.gameActive) {
document.getElementById('blocker').style.display = 'none';
} else if (!isLocked && STATE.gameActive && !STATE.gameOver) {
document.getElementById('blocker').style.display = 'flex';
}
});

// ============ SHOOTING ============
const raycaster = new THREE.Raycaster();

function shoot() {
const w = WEAPONS[STATE.currentWeapon];
const now = performance.now();

if (isReloading) return;
if (w.ammo <= 0) {
reload();
return;
}
if (now - lastFireTime < w.fireRate) return;

lastFireTime = now;
w.ammo--;

playSound(w.sound, 0.3);

// Weapon recoil
weaponGroup.position.z += 0.05;
weaponGroup.rotation.x -= 0.05;

// Muzzle flash
if (!muzzleFlash) {
const mfGeo = new THREE.SphereGeometry(0.05, 6, 6);
const mfMat = new THREE.MeshStandardMaterial({ color: 0xffaa00, emissive: 0xffaa00, emissiveIntensity: 3 });
muzzleFlash = new THREE.Mesh(mfGeo, mfMat);
muzzleFlash.position.set(0.3, -0.22, -1.0);
weaponGroup.add(muzzleFlash);
}
muzzleFlash.visible = true;
setTimeout(() => { if (muzzleFlash) muzzleFlash.visible = false; }, 50);

// Raycast
raycaster.setFromCamera({ x: 0, y: 0 }, camera);
raycaster.far = 100;

const spread = new THREE.Vector2(
(Math.random() - 0.5) * w.spread,
(Math.random() - 0.5) * w.spread
);
raycaster.ray.direction.applyEuler(new THREE.Euler(spread.y, spread.x, 0));

// Check enemy hits
let hitEnemy = false;
for (const enemy of enemies) {
if (!enemy.alive) continue;
const enemyWorldPos = new THREE.Vector3();
enemy.group.getWorldPosition(enemyWorldPos);

const toEnemy = enemyWorldPos.clone().sub(camera.position);
const dot = toEnemy.dot(raycaster.ray.direction);
if (dot < 0) continue;

const closest = camera.position.clone().add(raycaster.ray.direction.clone().multiplyScalar(dot));
const dist = closest.distanceTo(enemyWorldPos);

if (dist < 0.8 && dot < 50) {
const dmg = w.damage * (0.8 + Math.random() * 0.4);
enemy.health -= dmg;
playSound('hit', 0.2);

// Blood particles
createBloodParticles(enemyWorldPos);

if (enemy.health <= 0) {
enemy.alive = false;
enemy.group.visible = false;
STATE.kills++;
document.getElementById('kills').textContent = STATE.kills;
playSound('enemyDie', 0.3);
showMessage('Enemy eliminated');

// Drop ammo
if (Math.random() > 0.5) {
const dropGeo = new THREE.BoxGeometry(0.3, 0.3, 0.3);
const dropMat = new THREE.MeshStandardMaterial({ color: 0xffaa00, emissive: 0xffaa00, emissiveIntensity: 0.3 });
const drop = new THREE.Mesh(dropGeo, dropMat);
drop.position.copy(enemyWorldPos);
drop.position.y = 0.5;
scene.add(drop);
pickups.push({ mesh: drop, type: 'ammo', x: enemyWorldPos.x, z: enemyWorldPos.z, collected: false });
}
}
hitEnemy = true;
break;
}
}

// Bullet impact particles
if (!hitEnemy) {
const impactPoint = raycaster.ray.origin.clone().add(raycaster.ray.direction.clone().multiplyScalar(20));
createImpactParticles(impactPoint);
}

// Auto fire
if (w.auto && keys['Mouse0']) {
setTimeout(() => { if (keys['Mouse0'] && !isReloading) shoot(); }, w.fireRate);
}

updateHUD();
}

function reload() {
const w = WEAPONS[STATE.currentWeapon];
if (w.ammo === w.maxAmmo || w.reserve <= 0) return;
if (isReloading) return;

isReloading = true;
reloadTimer = w.reloadTime;
playSound('reload', 0.2);
showMessage('Reloading...');
}

function createBloodParticles(pos) {
for (let i = 0; i < 8; i++) {
const geo = new THREE.BoxGeometry(0.03, 0.03, 0.03);
const mat = new THREE.MeshStandardMaterial({ color: 0x880000 });
const p = new THREE.Mesh(geo, mat);
p.position.copy(pos);
scene.add(p);
particles.push({
mesh: p,
velocity: new THREE.Vector3((Math.random() - 0.5) * 2, Math.random() * 2, (Math.random() - 0.5) * 2),
life: 1.0,
});
}
}

function createImpactParticles(pos) {
for (let i = 0; i < 4; i++) {
const geo = new THREE.BoxGeometry(0.02, 0.02, 0.02);
const mat = new THREE.MeshStandardMaterial({ color: 0x888888 });
const p = new THREE.Mesh(geo, mat);
p.position.copy(pos);
scene.add(p);
particles.push({
mesh: p,
velocity: new THREE.Vector3((Math.random() - 0.5) * 1, Math.random(), (Math.random() - 0.5) * 1),
life: 0.5,
});
}
}

// ============ HUD ============
function updateHUD() {
const w = WEAPONS[STATE.currentWeapon];
document.getElementById('health-bar').style.width = (STATE.health / STATE.maxHealth * 100) + '%';
document.getElementById('ammo-display').innerHTML = `${w.ammo} <span class="reserve">/ ${w.reserve}</span>`;
document.getElementById('weapon-name').textContent = w.name;
document.getElementById('radiation-bar').style.width = (STATE.radiation / STATE.maxRadiation * 100) + '%';
document.getElementById('radiation-value').textContent = Math.floor(STATE.radiation) + ' mSv';

const radVal = Math.floor(STATE.radiation);
const radEl = document.getElementById('radiation-value');
if (radVal < 20) { radEl.style.color = '#00ff00'; }
else if (radVal < 50) { radEl.style.color = '#ffff00'; }
else { radEl.style.color = '#ff0000'; }

const geigerEl = document.getElementById('geiger-value');
if (STATE.radiation < 10) { geigerEl.textContent = 'NORMAL'; geigerEl.style.color = '#00ff00'; }
else if (STATE.radiation < 30) { geigerEl.textContent = 'ELEVATED'; geigerEl.style.color = '#ffff00'; }
else if (STATE.radiation < 60) { geigerEl.textContent = 'DANGEROUS'; geigerEl.style.color = '#ff8800'; }
else { geigerEl.textContent = 'LETHAL'; geigerEl.style.color = '#ff0000'; }

document.getElementById('antirad-count').textContent = STATE.antirads;
document.getElementById('bandage-count').textContent = STATE.bandages;
document.getElementById('ammo-pack-count').textContent = STATE.ammoPacks;
}

function showMessage(text) {
const el = document.getElementById('message');
el.textContent = text;
el.style.opacity = 1;
setTimeout(() => { el.style.opacity = 0; }, 2000);
}

function showZoneName(name) {
const el = document.getElementById('zone-name');
el.textContent = name;
el.style.opacity = 1;
setTimeout(() => { el.style.opacity = 0; }, 3000);
}

// ============ MINIMAP ============
const minimapCanvas = document.getElementById('minimap-canvas');
const minimapCtx = minimapCanvas.getContext('2d');

function drawMinimap() {
minimapCtx.fillStyle = 'rgba(0,0,0,0.8)';
minimapCtx.fillRect(0, 0, 150, 150);

const scale = 0.5;
const cx = 75, cy = 75;

// Draw tunnel segments
minimapCtx.strokeStyle = '#333';
minimapCtx.lineWidth = 2;
for (const seg of tunnelSegments) {
const sx = cx + (seg.x - camera.position.x) * scale;
const sz = cy + (seg.z - camera.position.z) * scale;

if (sx < -20 || sx > 170 || sz < -20 || sz > 170) continue;

const dir = seg.direction === 'z' ? seg.length : seg.width;
const perp = seg.direction === 'z' ? seg.width : seg.length;

minimapCtx.beginPath();
if (seg.direction === 'z') {
minimapCtx.rect(sx - dir / 2 * scale, sz - perp / 2 * scale, dir * scale, perp * scale);
} else {
minimapCtx.rect(sx - perp / 2 * scale, sz - dir / 2 * scale, perp * scale, dir * scale);
}
minimapCtx.stroke();
}

// Draw enemies
for (const enemy of enemies) {
if (!enemy.alive) continue;
const ex = cx + (enemy.x - camera.position.x) * scale;
const ez = cy + (enemy.z - camera.position.z) * scale;
if (ex < 0 || ex > 150 || ez < 0 || ez > 150) continue;

minimapCtx.fillStyle = '#ff0000';
minimapCtx.beginPath();
minimapCtx.arc(ex, ez, 2, 0, Math.PI * 2);
minimapCtx.fill();
}

// Draw pickups
for (const pickup of pickups) {
if (pickup.collected) continue;
const px = cx + (pickup.x - camera.position.x) * scale;
const pz = cy + (pickup.z - camera.position.z) * scale;
if (px < 0 || px > 150 || pz < 0 || pz > 150) continue;

minimapCtx.fillStyle = '#00ff00';
minimapCtx.beginPath();
minimapCtx.arc(px, pz, 2, 0, Math.PI * 2);
minimapCtx.fill();
}

// Player
minimapCtx.fillStyle = '#00ff00';
minimapCtx.beginPath();
minimapCtx.arc(cx, cy, 3, 0, Math.PI * 2);
minimapCtx.fill();

// Player direction
const dirX = Math.sin(yaw) * 10;
const dirZ = Math.cos(yaw) * 10;
minimapCtx.strokeStyle = '#00ff00';
minimapCtx.lineWidth = 1;
minimapCtx.beginPath();
minimapCtx.moveTo(cx, cy);
minimapCtx.lineTo(cx - dirX, cy - dirZ);
minimapCtx.stroke();
}

// ============ GAME LOGIC ============
function updatePlayer(dt) {
if (STATE.gameOver) return;

const speed = STATE.sprinting ? 8 : (STATE.crouching ? 2 : 4);
const forward = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
const right = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));

const moveDir = new THREE.Vector3();
if (keys['KeyW']) moveDir.add(forward);
if (keys['KeyS']) moveDir.sub(forward);
if (keys['KeyA']) moveDir.sub(right);
if (keys['KeyD']) moveDir.add(right);

if (moveDir.length() > 0) {
moveDir.normalize().multiplyScalar(speed * dt);
camera.position.add(moveDir);

// Walking sound
if (STATE.sprinting) {
weaponBob += dt * 12;
} else {
weaponBob += dt * 8;
}

if (Math.random() < dt * (STATE.sprinting ? 8 : 4)) {
playSound('step', 0.1);
}
}

// Jump
if (keys['Space'] && isGrounded) {
velocityY = 5;
isGrounded = false;
}

velocityY -= 12 * dt;
camera.position.y += velocityY * dt;

if (camera.position.y <= 1.7) {
camera.position.y = 1.7;
velocityY = 0;
isGrounded = true;
}

// Crouch
if (keys['KeyC']) {
STATE.crouching = true;
camera.position.y = Math.min(camera.position.y, 1.2);
} else {
STATE.crouching = false;
}

// Sprint
STATE.sprinting = keys['ShiftLeft'] || keys['ShiftRight'];

// Clamp to map bounds
camera.position.x = Math.max(-100, Math.min(100, camera.position.x));
camera.position.z = Math.max(-100, Math.min(100, camera.position.z));

// Camera rotation
camera.rotation.order = 'YXZ';
camera.rotation.y = yaw;
camera.rotation.x = pitch;

// Weapon bob
const bobX = Math.sin(weaponBob) * 0.015;
const bobY = Math.abs(Math.cos(weaponBob)) * 0.01;
weaponGroup.position.x = 0.25 + bobX;
weaponGroup.position.y = -0.3 + bobY + (STATE.crouching ? -0.1 : 0);

// Weapon recoil recovery
weaponGroup.position.z += (-0.5 - weaponGroup.position.z) * 0.1;
weaponGroup.rotation.x += (0 - weaponGroup.rotation.x) * 0.1;

// Flashlight toggle
if (keys['KeyF']) {
keys['KeyF'] = false;
STATE.flashlightOn = !STATE.flashlightOn;
const fl = camera.children.find(c => c.isSpotLight);
if (fl) fl.intensity = STATE.flashlightOn ? 1.5 : 0;
}

// Weapon switch
if (keys['Digit1']) { keys['Digit1'] = false; switchWeapon(0); }
if (keys['Digit2']) { keys['Digit2'] = false; switchWeapon(1); }
if (keys['Digit3']) { keys['Digit3'] = false; switchWeapon(2); }

// Reload
if (keys['KeyR']) {
keys['KeyR'] = false;
reload();
}

// Use items
if (keys['KeyQ']) {
keys['KeyQ'] = false;
if (STATE.antirads > 0) {
STATE.antirads--;
STATE.radiation = Math.max(0, STATE.radiation - 30);
showMessage('Antirad used');
playSound('pickup', 0.2);
updateHUD();
}
}
if (keys['KeyG']) {
keys['KeyG'] = false;
if (STATE.bandages > 0 && STATE.health < STATE.maxHealth) {
STATE.bandages--;
STATE.health = Math.min(STATE.maxHealth, STATE.health + 30);
showMessage('Bandage used');
playSound('pickup', 0.2);
updateHUD();
}
}

// Reload timer
if (isReloading) {
reloadTimer -= dt * 1000;
if (reloadTimer <= 0) {
isReloading = false;
const w = WEAPONS[STATE.currentWeapon];
const needed = w.maxAmmo - w.ammo;
const available = Math.min(needed, w.reserve);
w.ammo += available;
w.reserve -= available;
updateHUD();
}
}

// Check zone
checkZone();

// Check pickup collection
for (const pickup of pickups) {
if (pickup.collected) continue;
const dx = camera.position.x - pickup.x;
const dz = camera.position.z - pickup.z;
const dist = Math.sqrt(dx * dx + dz * dz);
if (dist < 1.5) {
pickup.collected = true;
scene.remove(pickup.mesh);
playSound('pickup', 0.2);

switch(pickup.type) {
case 'health':
STATE.health = Math.min(STATE.maxHealth, STATE.health + 25);
showMessage('+25 Health');
break;
case 'antirad':
STATE.antirads++;
showMessage('+1 Antirad');
break;
case 'ammo':
const w = WEAPONS[STATE.currentWeapon];
w.reserve += w.maxAmmo;
showMessage('+Ammo');
break;
case 'bandage':
STATE.bandages++;
showMessage('+1 Bandage');
break;
}
updateHUD();
}
}

// Check escape
if (!STATE.enteredEscape) {
const escapeX = camera.position.x;
const escapeZ = camera.position.z;
// Check if player is near the end of the map
if (Math.abs(camera.position.x) > 80 && Math.abs(camera.position.z) > 80) {
STATE.enteredEscape = true;
showZoneName('SURFACE - YOU ESCAPED!');
setTimeout(() => {
STATE.won = true;
STATE.gameOver = true;
document.getElementById('win-screen').style.display = 'flex';
document.exitPointerLock();
}, 3000);
}
}
}

function switchWeapon(idx) {
if (idx === STATE.currentWeapon) return;
STATE.currentWeapon = idx;
buildWeaponModel();
updateHUD();
showMessage(WEAPONS[idx].name);
}

function checkZone() {
const dist = Math.sqrt(camera.position.x * camera.position.x + camera.position.z * camera.position.z);
const newZone = Math.min(4, Math.floor(dist / 40));

if (newZone !== currentZone) {
currentZone = newZone;
showZoneName(zoneNames[currentZone]);
document.getElementById('objective').textContent =
currentZone === 0 ? 'Find the escape tunnel to the surface' :
currentZone === 1 ? 'Navigate through the tunnels' :
currentZone === 2 ? 'Beware of radiation' :
currentZone === 3 ? 'Radiation levels critical! Use antirads!' :
'Find the escape route!';

// Increase radiation in later zones
if (currentZone >= 2) {
STATE.radiation += 2;
}
}

// Radiation damage
if (STATE.radiation > 0) {
STATE.health -= STATE.radiation * 0.01;
}

// Radiation natural increase in later zones
if (currentZone >= 2 && Math.random() < 0.01) {
STATE.radiation = Math.min(STATE.maxRadiation, STATE.radiation + 1);
playSound('geiger', 0.1);
}

if (STATE.health <= 0) {
STATE.health = 0;
STATE.gameOver = true;
document.getElementById('game-over').style.display = 'flex';
document.exitPointerLock();
}

// Damage overlay
if (STATE.health < 30) {
const overlay = document.getElementById('damage-overlay');
const intensity = (30 - STATE.health) / 30;
overlay.style.border = `${intensity * 15}px solid rgba(255,0,0,${intensity * 0.5})`;
}

// Update compass
const compassDir = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
const compassIdx = Math.round(((yaw + Math.PI) / (Math.PI * 2)) * 7) % 8;
document.getElementById('compass').textContent = compassDir[compassIdx];
}

function updateEnemies(dt) {
for (const enemy of enemies) {
if (!enemy.alive) continue;

const dx = camera.position.x - enemy.x;
const dz = camera.position.z - enemy.z;
const dist = Math.sqrt(dx * dx + dz * dz);

// Alert if player is close or shooting
if (dist < 20) {
enemy.alerted = true;
}

if (enemy.alerted) {
// Move toward player
if (dist > enemy.attackRange) {
const moveX = (dx / dist) * enemy.speed * dt;
const moveZ = (dz / dist) * enemy.speed * dt;
enemy.x += moveX;
enemy.z += moveZ;

// Simple collision with tunnel walls
enemy.x = Math.max(-95, Math.min(95, enemy.x));
enemy.z = Math.max(-95, Math.min(95, enemy.z));
}

// Attack
enemy.attackCooldown -= dt;
if (dist < enemy.attackRange && enemy.attackCooldown <= 0) {
STATE.health -= enemy.damage;
enemy.attackCooldown = 1.5;
playSound('hurt', 0.3);
document.getElementById('damage-overlay').style.border = '20px solid rgba(255,0,0,0.5)';
setTimeout(() => {
document.getElementById('damage-overlay').style.border = '0px solid rgba(255,0,0,0)';
}, 200);
updateHUD();
}

// Update group position
enemy.group.position.x = enemy.x;
enemy.group.position.z = enemy.z;

// Face player
enemy.group.lookAt(new THREE.Vector3(camera.position.x, 0.9, camera.position.z));

// Walking animation
const walkCycle = Math.sin(performance.now() * 0.005 * enemy.speed) * 0.3;
enemy.group.children[0].rotation.z = walkCycle;
} else {
// Patrol
enemy.patrolAngle += dt * 0.5;
const targetX = enemy.patrolCenter.x + Math.cos(enemy.patrolAngle) * enemy.patrolRadius;
const targetZ = enemy.patrolCenter.z + Math.sin(enemy.patrolAngle) * enemy.patrolRadius;

const pdx = targetX - enemy.x;
const pdz = targetZ - enemy.z;
const pdist = Math.sqrt(pdx * pdx + pdz * pdz);

if (pdist > 0.5) {
enemy.x += (pdx / pdist) * enemy.speed * 0.3 * dt;
enemy.z += (pdz / pdist) * enemy.speed * 0.3 * dt;
}

enemy.group.position.x = enemy.x;
enemy.group.position.z = enemy.z;
enemy.group.lookAt(new THREE.Vector3(targetX, 0.9, targetZ));
}
}
}

function updateParticles(dt) {
for (let i = particles.length - 1; i >= 0; i--) {
const p = particles[i];
p.mesh.position.add(p.velocity.clone().multiplyScalar(dt));
p.velocity.y -= 5 * dt;
p.life -= dt * 2;
p.mesh.material.opacity = p.life;
p.mesh.material.transparent = true;

if (p.life <= 0) {
scene.remove(p.mesh);
particles.splice(i, 1);
}
}
}

function updateFlickeringLights(time) {
for (const ls of lightSources) {
ls.light.intensity = ls.baseIntensity * (0.7 + 0.3 * Math.sin(time * ls.flickerSpeed + ls.flickerPhase));
}
}

function updateDust(time) {
const positions = dust.geometry.attributes.position.array;
for (let i = 0; i < positions.length; i += 3) {
positions[i] += Math.sin(time + i) * 0.002;
positions[i + 1] += Math.cos(time * 0.5 + i) * 0.001;
positions[i + 2] += Math.cos(time + i) * 0.002;
}
dust.geometry.attributes.position.needsUpdate = true;
}

// ============ GAME LOOP ============
const clock = new THREE.Clock();

function animate() {
requestAnimationFrame(animate);

const dt = Math.min(clock.getDelta(), 0.05);
const time = clock.getElapsedTime();

if (STATE.gameActive && !STATE.gameOver) {
updatePlayer(dt);
updateEnemies(dt);
updateParticles(dt);
updateFlickeringLights(time);
updateDust(time);
drawMinimap();
updateHUD();

// Radiation bar color
const radPct = STATE.radiation / STATE.maxRadiation;
const radBar = document.getElementById('radiation-bar');
if (radPct < 0.3) radBar.style.background = '#00ff00';
else if (radPct < 0.6) radBar.style.background = 'linear-gradient(90deg, #00ff00, #ffff00)';
else radBar.style.background = 'linear-gradient(90deg, #ffff00, #ff0000)';
}

renderer.render(scene, camera);
}

// ============ INIT ============
function initGame() {
// Clear scene
while (scene.children.length > 0) scene.remove(scene.children[0]);

// Re-add camera
scene.add(camera);

// Reset state
STATE.health = 100;
STATE.radiation = 0;
STATE.kills = 0;
STATE.currentWeapon = 0;
STATE.gameActive = true;
STATE.gameOver = false;
STATE.won = false;
STATE.enteredEscape = false;
STATE.antirads = 2;
STATE.bandages = 3;
STATE.ammoPacks = 1;
currentZone = 0;

WEAPONS[0].ammo = 30; WEAPONS[0].reserve = 120;
WEAPONS[1].ammo = 18; WEAPONS[1].reserve = 90;
WEAPONS[2].ammo = 2; WEAPONS[2].reserve = 10;

isReloading = false;
yaw = 0; pitch = 0;
camera.position.set(0, 1.7, 0);

// Rebuild
buildMetroMap();
setupLighting();
buildWeaponModel();
updateHUD();

document.getElementById('game-over').style.display = 'none';
document.getElementById('win-screen').style.display = 'none';

showZoneName('STATION PLATFORM');
showMessage('Find your way to the surface...');
}

// Blocker click
document.getElementById('blocker').addEventListener('click', () => {
renderer.domElement.requestPointerLock();
