    ctx.moveTo(-8, 16);
    ctx.lineTo(-10 - legOffset - jumpLegSpread, 24);
    ctx.stroke();

    // Right leg
    ctx.beginPath();
    ctx.moveTo(8, 16);
    ctx.lineTo(10 + legOffset + jumpLegSpread, 24);
    ctx.stroke();

    // Feet
    ctx.fillStyle = '#FFFF00';
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1.5;

    ctx.beginPath();
    ctx.ellipse(-10 - legOffset - jumpLegSpread, 25, 5, 3, -0.3, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.beginPath();
    ctx.ellipse(10 + legOffset + jumpLegSpread, 25, 5, 3, 0.3, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.restore();
}

function drawParticles() {
    for (let p of particles) {
