<script>
// ==================== DATA LAYER ====================
const DB = {
  get(key) { try { return JSON.parse(localStorage.getItem('mojo_' + key)) || []; } catch { return []; } },
  set(key, val) { localStorage.setItem('mojo_' + key, JSON.stringify(val)); },
  getObj(key) { try { return JSON.parse(localStorage.getItem('mojo_' + key)) || {}; } catch { return {}; } },
  setObj(key, val) { localStorage.setItem('mojo_' + key, JSON.stringify(val)); }
};

// ==================== STATE ====================
let currentProduct = null;
let currentCategory = 'all';
let sortMode = 'newest';
let isAdminLoggedIn = false;
let unlockedProducts = DB.getObj('unlocked');
let purchasedProducts = DB.getObj('purchased');
let myPostedProducts = DB.getObj('myProducts');

// ==================== INIT ====================
function init() {
  if (DB.get('products').length === 0) loadSampleProducts();
  renderProducts();
}

function loadSampleProducts() {
  const samples = [
    { id: genId(), name: 'iPhone 15 Pro Max', category: 'electronics', price: 129999, stock: 5, phone: '9876543210', address: '123, Connaught Place, New Delhi', sellerName: 'Rahul Sharma', image: '', badge: 'hot', status: 'approved', date: Date.now() - 86400000 },
    { id: genId(), name: 'Nike Air Jordan 1', category: 'fashion', price: 12999, stock: 12, phone: '9876543211', address: '45, Linking Road, Bandra, Mumbai', sellerName: 'Priya Patel', image: '', badge: 'new', status: 'approved', date: Date.now() - 72000000 },
    { id: genId(), name: 'Samsung Galaxy S24 Ultra', category: 'electronics', price: 109999, stock: 3, phone: '9876543212', address: '78, Anna Salai, Chennai', sellerName: 'Arun Kumar', image: '', badge: 'hot', status: 'approved', date: Date.now() - 60000000 },
    { id: genId(), name: 'Organic Honey 1kg', category: 'food', price: 450, stock: 50, phone: '9876543213', address: '12, MG Road, Bangalore', sellerName: 'Meena Devi', image: '', badge: 'new', status: 'approved', date: Date.now() - 50000000 },
    { id: genId(), name: 'Yoga Mat Premium', category: 'sports', price: 899, stock: 25, phone: '9876543214', address: '56, Park Street, Kolkata', sellerName: 'Suresh Iyer', image: '', badge: '', status: 'approved', date: Date.now() - 40000000 },
    { id: genId(), name: 'LED Desk Lamp', category: 'home', price: 699, stock: 30, phone: '9876543215', address: '89, FC Road, Pune', sellerName: 'Anita Desai', image: '', badge: 'new', status: 'approved', date: Date.now() - 30000000 },
    { id: genId(), name: 'Bluetooth Speaker JBL', category: 'electronics', price: 3499, stock: 8, phone: '9876543216', address: '34, Sector 18, Noida', sellerName: 'Vikram Singh', image: '', badge: 'hot', status: 'approved', date: Date.now() - 20000000 },
    { id: genId(), name: 'Silk Saree Collection', category: 'fashion', price: 2999, stock: 15, phone: '9876543217', address: '67, Tilak Road, Jaipur', sellerName: 'Kavita Joshi', image: '', badge: '', status: 'approved', date: Date.now() - 10000000 }
  ];
  DB.set('products', samples);
}

function genId() { return 'p_' + Date.now().toString(36) + Math.random().toString(36).substr(2, 5); }

// ==================== NAVIGATION ====================
function showPage(page) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.header-btn').forEach(b => b.classList.remove('active'));

  if (page === 'home') {
    document.getElementById('pageHome').classList.add('active');
    document.getElementById('navHome').classList.add('active');
    renderProducts();
  } else if (page === 'mymarket') {
    document.getElementById('pageMyMarket').classList.add('active');
    document.getElementById('navMy').classList.add('active');
    renderMyMarket();
  } else if (page === 'admin') {
    document.getElementById('pageAdmin').classList.add('active');
    document.getElementById('navAdmin').classList.add('active');
    if (isAdminLoggedIn) renderAdmin();
  }
}

// ==================== PRODUCT RENDERING ====================
function getApprovedProducts() {
  return DB.get('products').filter(p => p.status === 'approved');
}

function renderProducts() {
  let products = getApprovedProducts();
  const search = document.getElementById('searchInput').value.toLowerCase();

  if (currentCategory !== 'all') {
    products = products.filter(p => p.category === currentCategory);
  }
  if (search) {
    products = products.filter(p => p.name.toLowerCase().includes(search) || p.sellerName.toLowerCase().includes(search));
  }

  if (sortMode === 'priceLow') products.sort((a, b) => a.price - b.price);
  else if (sortMode === 'priceHigh') products.sort((a, b) => b.price - a.price);
  else products.sort((a, b) => b.date - a.date);

  const grid = document.getElementById('productGrid');
  const empty = document.getElementById('emptyState');

  if (products.length === 0) {
    grid.innerHTML = '';
    empty.style.display = 'block';
    return;
  }
  empty.style.display = 'none';

  grid.innerHTML = products.map(p => {
    const stockClass = p.stock <= 3 ? 'low' : p.stock === 0 ? 'out' : '';
    const stockText = p.stock === 0 ? 'Out of Stock' : p.stock <= 3 ? `Only ${p.stock} left!` : `${p.stock} in stock`;
    const badgeHTML = p.badge === 'hot' ? '<div class="product-badge badge-hot">🔥 Hot</div>' : 
                      p.badge === 'new' ? '<div class="product-badge badge-new">✨ New</div>' : '';
    const imgHTML = p.image ? `<img src="${p.image}" alt="${p.name}">` : '<div class="placeholder-icon">📦</div>';

    return `<div class="product-card">
      <div class="product-img">${imgHTML}${badgeHTML}</div>
      <div class="product-info">
        <div class="product-name" title="${p.name}">${p.name}</div>
        <div class="product-price">₹${p.price.toLocaleString('en-IN')}</div>
        <div class="product-stock"><span class="stock-dot ${stockClass}"></span>${stockText}</div>
        <button class="view-btn" onclick="openDetail('${p.id}')">👁️ View Full Details</button>
      </div>
    </div>`;
  }).join('');
}

function filterProducts() { renderProducts(); }

function filterCategory(cat, el) {
  currentCategory = cat;
  document.querySelectorAll('.category-pill').forEach(p => p.classList.remove('active'));
  if (el) el.classList.add('active');
  renderProducts();
}

function toggleSort() {
  const modes = ['newest', 'priceLow', 'priceHigh'];
  const labels = ['🕐 Newest', '💰 Price: Low', '💰 Price: High'];
  const idx = modes.indexOf(sortMode);
  sortMode = modes[(idx + 1) % modes.length];
  showToast(labels[(idx + 1) % modes.length], 'info');
  renderProducts();
}

// ==================== PRODUCT DETAIL ====================
