  if (!product) return;

  currentProduct = product;
  const isUnlocked = unlockedProducts[productId];

  document.getElementById('detailTitle').textContent = product.name;

  const imgHTML = product.image ? `<img src="${product.image}" style="width:100%;height:200px;object-fit:cover;border-radius:16px;margin-bottom:16px" alt="${product.name}">` : 
