      <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px">
        <span style="font-size:28px;font-weight:900;color:var(--accent)">₹${product.price.toLocaleString('en-IN')}</span>
        <span style="background:rgba(0,201,167,0.15);padding:4px 12px;border-radius:8px;font-size:12px;color:var(--accent);font-weight:600">✓ Paid</span>
      </div>
      <div class="unlocked-details">
        <h3>✅ Seller Details Unlocked</h3>
        <div class="detail-row">
          <div class="detail-icon phone">👤</div>
          <div class="detail-text"><strong>${product.sellerName}</strong>Seller</div>
        </div>
        <div class="detail-row">
          <div class="detail-icon phone">📞</div>
          <div class="detail-text"><strong>${product.phone}</strong>Phone Number</div>
        </div>
        <div class="detail-row">
          <div class="detail-icon address">📍</div>
          <div class="detail-text"><strong>${product.address}</strong>Address</div>
        </div>
        <div class="call-msg-btns">
          <a href="tel:${product.phone}" class="call-btn">📞 Call Seller</a>
          <a href="https://wa.me/${product.phone}?text=Hi! I'm interested in ${encodeURIComponent(product.name)} on Mojocreate" target="_blank" class="msg-btn">💬 WhatsApp</a>
        </div>
      </div>
