// ==================== PAYMENT ====================
function openPayment(productId) {
  closeModal('detailModal');
  currentProduct = productId;

  // Generate QR code
  generateQR();

  document.getElementById('paymentOTP').value = '';
  document.getElementById('paymentOTP').disabled = false;
  document.getElementById('paymentOTP').classList.remove('verified');
  document.getElementById('verifyPayBtn').disabled = true;
  document.getElementById('paymentStatus').innerHTML = '';

  openModal('paymentModal');
}

function generateQR() {
  const canvas = document.getElementById('qrCanvas');
  const ctx = canvas.getContext('2d');
  const size = 180;
  canvas.width = size;
  canvas.height = size;

  // Generate a deterministic pattern based on product ID
  const seed = currentProduct ? currentProduct.length : 42;
  const cellSize = 6;
  const cells = Math.floor(size / cellSize);

  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, size, size);

  // QR-like pattern
  ctx.fillStyle = '#1a1a2e';

  // Position detection patterns (corners)
  function drawFinderPattern(x, y) {
    ctx.fillRect(x, y, 7 * cellSize, 7 * cellSize);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(x + cellSize, y + cellSize, 5 * cellSize, 5 * cellSize);
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(x + 2 * cellSize, y + 2 * cellSize, 3 * cellSize, 3 * cellSize);
  }

  drawFinderPattern(6, 6);
  drawFinderPattern(size - 48, 6);
  drawFinderPattern(6, size - 48);

  // Data area
  let rng = seed;
  function nextRng() { rng = (rng * 1103515245 + 12345) & 0x7fffffff; return rng; }

  for (let i = 0; i < cells; i++) {
    for (let j = 0; j < cells; j++) {
      if (isFinderArea(i, j, cells, size)) continue;
      if (nextRng() % 3 !== 0) {
        ctx.fillRect(i * cellSize, j * cellSize, cellSize - 1, cellSize - 1);
      }
    }
  }
}

function isFinderArea(i, j, cells, size) {
  const cs = 7;
  const cellSize = size / cells;
  if (i < cs && j < cs) return true;
  if (i >= cells - cs && j < cs) return true;
  if (i < cs && j >= cells - cs) return true;
  return false;
}

function checkOTP() {
  const otp = document.getElementById('paymentOTP').value;
  document.getElementById('verifyPayBtn').disabled = otp.length !== 6;
}

function verifyPayment() {
  const otp = document.getElementById('paymentOTP').value;
  const statusEl = document.getElementById('paymentStatus');

  if (otp === '123456') {
    // Success
    document.getElementById('paymentOTP').classList.add('verified');
    document.getElementById('paymentOTP').disabled = true;
    document.getElementById('verifyPayBtn').disabled = true;
    document.getElementById('verifyPayBtn').textContent = '✅ Payment Verified!';

    statusEl.innerHTML = `
      <div style="text-align:center;padding:16px;background:rgba(0,201,167,0.1);border-radius:14px;margin-top:16px;border:1px solid rgba(0,201,167,0.3)">
        <div style="font-size:40px;margin-bottom:8px">✅</div>
        <h3 style="color:var(--accent);margin-bottom:4px">Payment Successful!</h3>
        <p style="color:var(--text2);font-size:13px">₹1 payment confirmed. Unlocking seller details...</p>
      </div>
    `;

    // Save unlock
    unlockedProducts[currentProduct] = { date: Date.now(), product: currentProduct };
    DB.setObj('unlocked', unlockedProducts);

    // Save purchase
    if (!purchasedProducts[currentProduct]) {
      purchasedProducts[currentProduct] = { date: Date.now(), product: currentProduct };
      DB.setObj('purchased', purchasedProducts);
    }

    // Record payment
    const payments = DB.get('payments');
    payments.push({ id: genId(), productId: currentProduct, amount: 1, date: Date.now(), status: 'completed' });
    DB.set('payments', payments);

    // Confetti
    createConfetti();

    showToast('🎉 Payment Successful! Details unlocked!', 'success');

    setTimeout(() => {
      closeModal('paymentModal');
      openDetail(currentProduct);
    }, 1500);
  } else {
    statusEl.innerHTML = `
      <div style="text-align:center;padding:12px;background:rgba(255,101,132,0.1);border-radius:10px;margin-top:12px;border:1px solid rgba(255,101,132,0.2)">
        <p style="color:var(--secondary);font-size:13px">❌ Invalid OTP. Please try again.</p>
        <p style="color:var(--text2);font-size:11px;margin-top:4px">Demo OTP: 123456</p>
      </div>
    `;
    showToast('Invalid OTP! Try 123456', 'error');
  }
}

// ==================== SELL PRODUCT ====================
function openSellModal() {
  document.getElementById('sellForm').reset();
  document.getElementById('imagePreview').style.display = 'none';
  document.getElementById('uploadPlaceholder').style.display = 'block';
  document.getElementById('imageUpload').classList.remove('has-image');
  openModal('sellModal');
}

function previewImage(event) {
  const file = event.target.files[0];
  if (!file) return;

  // Compress image
  const reader = new FileReader();
  reader.onload = function(e) {
    const img = new Image();
    img.onload = function() {
      const canvas = document.createElement('canvas');
      const maxSize = 400;
      let w = img.width, h = img.height;
      if (w > h) { if (w > maxSize) { h *= maxSize / w; w = maxSize; } }
      else { if (h > maxSize) { w *= maxSize / h; h = maxSize; } }
      canvas.width = w;
      canvas.height = h;
      canvas.getContext('2d').drawImage(img, 0, 0, w, h);
      const compressed = canvas.toDataURL('image/jpeg', 0.7);

      document.getElementById('imagePreview').src = compressed;
      document.getElementById('imagePreview').style.display = 'block';
      document.getElementById('uploadPlaceholder').style.display = 'none';
      document.getElementById('imageUpload').classList.add('has-image');
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function submitProduct(event) {
  event.preventDefault();

  const imagePreview = document.getElementById('imagePreview');
  const image = imagePreview.style.display !== 'none' ? imagePreview.src : '';

  const product = {
    id: genId(),
    name: document.getElementById('prodName').value.trim(),
    category: document.getElementById('prodCategory').value,
    price: parseInt(document.getElementById('prodPrice').value),
    stock: parseInt(document.getElementById('prodStock').value),
    phone: document.getElementById('prodPhone').value.trim(),
    address: document.getElementById('prodAddress').value.trim(),
    sellerName: document.getElementById('prodSellerName').value.trim(),
    image: image,
    badge: 'new',
    status: 'pending',
    date: Date.now()
  };

  const products = DB.get('products');
  products.push(product);
  DB.set('products', products);

  myPostedProducts[product.id] = { date: Date.now(), product: product.id };
  DB.setObj('myProducts', myPostedProducts);

  closeModal('sellModal');
  showToast('📤 Product submitted for approval!', 'success');
}

// ==================== MY MARKET ====================
function renderMyMarket() {
  const postedDiv = document.getElementById('myPostedProducts');
  const purchasedDiv = document.getElementById('myPurchasedProducts');

  const myIds = Object.keys(myPostedProducts);
  const products = DB.get('products');

  if (myIds.length === 0) {
    postedDiv.innerHTML = `<div class="empty-state"><div class="empty-icon">📭</div><h3>No Products Posted</h3><p>Tap the Sell button to list your first product</p></div>`;
  } else {
    postedDiv.innerHTML = `<div style="margin-bottom:20px">${myIds.map(id => {
      const p = products.find(pr => pr.id === id);
      if (!p) return '';
      const statusBadge = p.status === 'approved' ? '<span class="status-badge status-approved">Approved</span>' :
                          p.status === 'rejected' ? '<span class="status-badge status-rejected">Rejected</span>' :
                          '<span class="status-badge status-pending">Pending</span>';
      return `<div class="my-product-card">
