            ${statusBadge}
            <div class="mp-actions">
              <button class="action-btn edit" onclick="openEditModal('${p.id}')">✏️ Edit</button>
              <button class="action-btn delete" onclick="deleteMyProduct('${p.id}')">🗑️ Delete</button>
            </div>
          </div>
        </div>
      </div>`;
    }).join('')}</div>`;
  }

  const purchasedIds = Object.keys(purchasedProducts);
  if (purchasedIds.length === 0) {
    purchasedDiv.innerHTML = `<div class="empty-state"><div class="empty-icon">💳</div><h3>No Purchases Yet</h3><p>Pay ₹1 to unlock seller details</p></div>`;
  } else {
    purchasedDiv.innerHTML = purchasedIds.map(id => {
      const p = products.find(pr => pr.id === id);
      if (!p) return '';
      return `<div class="my-product-card">
        ${p.image ? `<img src="${p.image}" class="mp-img" alt="${p.name}">` : '<div class="mp-img" style="display:flex;align-items:center;justify-content:center;font-size:24px;background:var(--card2)">📦</div>'}
        <div class="mp-info">
          <div class="mp-name">${p.name}</div>
          <div class="mp-price">₹${p.price.toLocaleString('en-IN')}</div>
