  document.getElementById('myPurchasedProducts').style.display = tab === 'purchased' ? 'block' : 'none';
}

// ==================== EDIT / DELETE ====================
function openEditModal(productId) {
  const product = DB.get('products').find(p => p.id === productId);
  if (!product) return;

  document.getElementById('editId').value = productId;
  document.getElementById('editName').value = product.name;
  document.getElementById('editPrice').value = product.price;
  document.getElementById('editStock').value = product.stock;
  document.getElementById('editPhone').value = product.phone;
  document.getElementById('editAddress').value = product.address;

  openModal('editModal');
}

function saveEdit(event) {
  event.preventDefault();
  const id = document.getElementById('editId').value;
  const products = DB.get('products');
  const idx = products.findIndex(p => p.id === id);
  if (idx === -1) return;

  products[idx].name = document.getElementById('editName').value.trim();
  products[idx].price = parseInt(document.getElementById('editPrice').value);
  products[idx].stock = parseInt(document.getElementById('editStock').value);
  products[idx].phone = document.getElementById('editPhone').value.trim();
  products[idx].address = document.getElementById('editAddress').value.trim();

  DB.set('products', products);
  closeModal('editModal');
  showToast('✅ Product updated successfully!', 'success');
  renderProducts();
}

function deleteMyProduct(productId) {
  if (!confirm('Are you sure you want to delete this product?')) return;

  let products = DB.get('products');
  products = products.filter(p => p.id !== productId);
  DB.set('products', products);

  delete myPostedProducts[productId];
  DB.setObj('myProducts', myPostedProducts);

  showToast('🗑️ Product deleted', 'info');
  renderMyMarket();
}

