    <div class="stat-card"><div class="stat-num">${pending}</div><div class="stat-label">Pending</div></div>
    <div class="stat-card"><div class="stat-num">₹${totalRevenue}</div><div class="stat-label">Revenue</div></div>
    <div class="stat-card"><div class="stat-num">${payments.length}</div><div class="stat-label">Payments</div></div>
    <div class="stat-card"><div class="stat-num">${rejected}</div><div class="stat-label">Rejected</div></div>
