                                p.status === 'rejected' ? '<span class="status-badge status-rejected">Rejected</span>' :
                                '<span class="status-badge status-pending">Pending</span>';
            const imgHTML = p.image ? `<img src="${p.image}" class="thumb" alt="${p.name}">` : '<div class="thumb" style="display:flex;align-items:center;justify-content:center;font-size:16px;background:var(--card2)">📦</div>';
            return `<tr>
              <td>${imgHTML}</td>
              <td><strong>${p.name}</strong><br><span style="font-size:11px;color:var(--text2)">${p.category}</span></td>
              <td style="color:var(--accent);font-weight:700">₹${p.price.toLocaleString('en-IN')}</td>
              <td>${p.stock}</td>
