              <td>${statusBadge}</td>
              <td>
                <div class="action-btns">
                  ${p.status === 'pending' ? `<button class="action-btn approve" onclick="adminAction('${p.id}','approve')">✓</button><button class="action-btn reject" onclick="adminAction('${p.id}','reject')">✕</button>` : ''}
                  <button class="action-btn edit" onclick="adminEdit('${p.id}')">✏️</button>
                  <button class="action-btn delete" onclick="adminDelete('${p.id}')">🗑️</button>
                </div>
