function adminAction(productId, action) {
  const products = DB.get('products');
  const idx = products.findIndex(p => p.id === productId);
  if (idx === -1) return;

  products[idx].status = action === 'approve' ? 'approved' : 'rejected';
  DB.set('products', products);

  const msg = action === 'approve' ? '✅ Product approved!' : '❌ Product rejected!';
  showToast(msg, action === 'approve' ? 'success' : 'error');
  renderAdmin();
  renderProducts();
}

function adminEdit(productId) {
  const product = DB.get('products').find(p => p.id === productId);
  if (!product) return;

  const newPrice = prompt('Enter new price (₹):', product.price);
  if (newPrice === null) return;
  const newStock = prompt('Enter new stock:', product.stock);
  if (newStock === null) return;

  const products = DB.get('products');
  const idx = products.findIndex(p => p.id === productId);
  if (idx === -1) return;

  products[idx].price = parseInt(newPrice) || product.price;
  products[idx].stock = parseInt(newStock) || product.stock;

  DB.set('products', products);
  showToast('✅ Product updated!', 'success');
  renderAdmin();
  renderProducts();
}

function adminDelete(productId) {
  if (!confirm('Are you sure you want to delete this product?')) return;

  let products = DB.get('products');
  products = products.filter(p => p.id !== productId);
  DB.set('products', products);

  showToast('🗑️ Product deleted by admin', 'info');
  renderAdmin();
  renderProducts();
}

function renderAdminPayments() {
  const payments = DB.get('payments');
  const products = DB.get('products');

  document.getElementById('adminPaymentsTab').innerHTML = payments.length === 0 ?
    `<div class="empty-state"><div class="empty-icon">💰</div><h3>No Payments Yet</h3></div>` :
