    payments.map(p => {
      const prod = products.find(pr => pr.id === p.productId);
      return `<div class="payment-item">
        <div class="pi-avatar">💳</div>
        <div class="pi-info">
          <div class="pi-name">${prod ? prod.name : 'Unknown Product'}</div>
          <div class="pi-date">${new Date(p.date).toLocaleString('en-IN')}</div>
          ${prod ? `<div style="font-size:11px;color:var(--text2)">Seller: ${prod.sellerName} | ${prod.phone}</div>` : ''}
        </div>
        <div class="pi-amount">₹${p.amount}</div>
      </div>`;
    }).join('');
}

function renderAdminUsers() {
  const products = DB.get('products');
  const sellers = [...new Set(products.map(p => p.sellerName))];

  document.getElementById('adminUsersTab').innerHTML = sellers.length === 0 ?
    `<div class="empty-state"><div class="empty-icon">👥</div><h3>No Users Yet</h3></div>` :
    sellers.map(name => {
      const userProducts = products.filter(p => p.sellerName === name);
      const firstProduct = userProducts[0];
      return `<div class="payment-item">
        <div class="pi-avatar">👤</div>
        <div class="pi-info">
          <div class="pi-name">${name}</div>
          <div class="pi-date">${userProducts.length} product(s) • Phone: ${firstProduct ? firstProduct.phone : 'N/A'}</div>
          ${firstProduct ? `<div style="font-size:11px;color:var(--text2)">Address: ${firstProduct.address}</div>` : ''}
        </div>
      </div>`;
    }).join('');
}

// ==================== MODALS ====================
function openModal(id) {
  document.getElementById(id).classList.add('show');
  document.body.style.overflow = 'hidden';
}

function closeModal(id) {
  document.getElementById(id).classList.remove('show');
  document.body.style.overflow = '';
}

// Close modal on overlay click
document.querySelectorAll('.modal-overlay').forEach(overlay => {
  overlay.addEventListener('click', function(e) {
    if (e.target === this) {
      this.classList.remove('show');
      document.body.style.overflow = '';
    }
  });
});

// ==================== TOAST ====================
function showToast(message, type = 'info') {
  const toast = document.getElementById('toast');
  toast.textContent = message;
  toast.className = `toast ${type} show`;
  setTimeout(() => toast.classList.remove('show'), 3000);
}

// ==================== CONFETTI ====================
function createConfetti() {
  const container = document.createElement('div');
  container.className = 'confetti-container';
  document.body.appendChild(container);

  const colors = ['#6C63FF', '#FF6584', '#00C9A7', '#FFB800', '#ff416c', '#ff4b2b'];
  for (let i = 0; i < 50; i++) {
    const confetti = document.createElement('div');
    confetti.className = 'confetti';
    confetti.style.left = Math.random() * 100 + '%';
    confetti.style.background = colors[Math.floor(Math.random() * colors.length)];
    confetti.style.animationDelay = Math.random() * 2 + 's';
    confetti.style.animationDuration = (Math.random() * 2 + 2) + 's';
    confetti.style.width = (Math.random() * 8 + 4) + 'px';
    confetti.style.height = (Math.random() * 8 + 4) + 'px';
    confetti.style.borderRadius = Math.random() > 0.5 ? '50%' : '0';
    container.appendChild(confetti);
  }

  setTimeout(() => container.remove(), 4000);
}

// ==================== KEYBOARD ====================
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    document.querySelectorAll('.modal-overlay.show').forEach(m => {
      m.classList.remove('show');
    });
    document.body.style.overflow = '';
  }
});

// ==================== INIT ====================
init();
</script>
</body>
</html>
