  }

  .order-bubble::after {
    content: '';
    position: absolute;
    bottom: -8px;
    left: 50%;
    transform: translateX(-50%);
    width: 0;
    height: 0;
    border-left: 8px solid transparent;
    border-right: 8px solid transparent;
    border-top: 8px solid #333;
  }

  .patience-bar {
    width: 60px;
    height: 6px;
    background: #333;
    border-radius: 3px;
    margin-top: 5px;
    overflow: hidden;
  }

  .patience-fill {
    height: 100%;
    background: #44ff44;
    border-radius: 3px;
    transition: width 0.3s, background 0.3s;
  }

  /* Cooking Area */
  #cookingArea {
    background: linear-gradient(180deg, #654321, #3E1F09);
    padding: 10px;
    display: flex;
    gap: 15px;
    justify-content: center;
    align-items: stretch;
    min-height: 220px;
    border-top: 4px solid #8B6914;
  }

  .station {
    background: #DEB887;
    border-radius: 15px;
    padding: 10px;
    border: 3px solid #8B6914;
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    min-width: 140px;
    flex: 1;
  }

  .station-title {
    font-size: 0.9em;
    font-weight: 700;
    color: #3E1F09;
    margin-bottom: 5px;
  }

  /* Frying Station */
  #fryingStation {
    background: #4a3000;
    border-color: #FFD700;
  }

  .pan {
    width: 100px;
    height: 30px;
    background: #333;
    border-radius: 0 0 50px 50px;
    position: relative;
    margin-top: 10px;
    border: 3px solid #555;
  }

  .oil {
    position: absolute;
    top: 5px;
    left: 10px;
    right: 10px;
    bottom: 5px;
    background: radial-gradient(ellipse, #FFD700, #FF8C00);
    border-radius: 0 0 40px 40px;
    transition: background 0.5s;
  }

  .oil.hot { background: radial-gradient(ellipse, #ff4444, #ff0000); }
  .oil.cold { background: radial-gradient(ellipse, #88ccff, #4488cc); }

  .falafel-in-oil {
    position: absolute;
    top: -5px;
    display: flex;
    gap: 5px;
  }

  .falafel-piece {
    width: 20px;
    height: 20px;
    background: #8B6914;
    border-radius: 50%;
    border: 2px solid #5C3317;
    transition: background 0.5s;
  }

  .falafel-piece.frying { background: #DAA520; }
  .falafel-piece.done { background: #8B4513; box-shadow: 0 0 10px #FFD700; }
  .falafel-piece.burnt { background: #1a1a1a; }

  .fry-btn {
    margin-top: 10px;
    padding: 8px 20px;
    background: linear-gradient(180deg, #FFD700, #FF8C00);
    border: 2px solid #B8650A;
    border-radius: 10px;
    font-family: 'Cairo', sans-serif;
    font-weight: 700;
    font-size: 0.9em;
    cursor: pointer;
    color: #3E1F09;
  }

  .fry-btn:active { transform: scale(0.9); }

  .fry-progress {
    width: 80px;
    height: 8px;
    background: #333;
    border-radius: 4px;
    margin-top: 5px;
    overflow: hidden;
  }

  .fry-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, #44ff44, #FFD700, #ff4444);
    border-radius: 4px;
    transition: width 0.1s;
  }

  /* Assembly Station */
  #assemblyStation {
    background: #FFF8DC;
    border-color: #DEB887;
  }

  .sandwich-slot {
    width: 90px;
    height: 50px;
    background: #DEB887;
    border-radius: 10px;
    border: 2px dashed #8B6914;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 5px 0;
    font-size: 0.8em;
    color: #8B6914;
    flex-wrap: wrap;
    gap: 2px;
    padding: 3px;
  }

  .sandwich-slot .ingredient {
    font-size: 1.2em;
  }

  .ingredient-btn {
    padding: 4px 8px;
    margin: 2px;
    border: 2px solid #8B6914;
    border-radius: 8px;
    background: #fff;
    font-family: 'Cairo', sans-serif;
    font-size: 0.75em;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s;
  }

  .ingredient-btn:hover { background: #FFD700; transform: scale(1.1); }
  .ingredient-btn:active { transform: scale(0.9); }

  .serve-btn {
    padding: 8px 20px;
    background: linear-gradient(180deg, #44ff44, #228B22);
    border: 2px solid #006400;
    border-radius: 10px;
    font-family: 'Cairo', sans-serif;
    font-weight: 700;
    font-size: 0.9em;
    cursor: pointer;
    color: #fff;
    margin-top: 5px;
  }

  .serve-btn:active { transform: scale(0.9); }

  .serve-btn:disabled {
    background: #888;
    border-color: #555;
    cursor: not-allowed;
  }

  /* Ingredients Display */
  .ingredient-count {
    font-size: 0.7em;
    color: #8B6914;
  }

  /* Flies */
  .fly {
    position: absolute;
    font-size: 1.5em;
    cursor: pointer;
    z-index: 50;
    animation: flyAround 2s ease-in-out infinite;
    transition: transform 0.1s;
  }

  .fly:hover { transform: scale(1.5); }

  @keyframes flyAround {
    0% { transform: translate(0, 0) rotate(0deg); }
    25% { transform: translate(30px, -20px) rotate(10deg); }
    50% { transform: translate(-10px, -40px) rotate(-5deg); }
    75% { transform: translate(-30px, -10px) rotate(8deg); }
    100% { transform: translate(0, 0) rotate(0deg); }
  }

  /* Smoke */
  .smoke {
    position: absolute;
    width: 10px;
    height: 10px;
    background: rgba(200,200,200,0.5);
    border-radius: 50%;
    animation: smokeRise 1s ease-out forwards;
    pointer-events: none;
  }

  @keyframes smokeRise {
    to { transform: translateY(-50px); opacity: 0; }
  }

  /* Floating Text */
  .float-text {
    position: absolute;
    font-weight: 900;
    font-size: 1.5em;
    pointer-events: none;
    animation: floatUp 1s ease-out forwards;
    z-index: 200;
    text-shadow: 2px 2px 0 #000;
  }

  @keyframes floatUp {
    0% { transform: translateY(0); opacity: 1; }
    100% { transform: translateY(-80px); opacity: 0; }
  }

  /* Level Complete */
  #levelComplete {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.85);
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    z-index: 300;
  }

  #levelComplete h2 {
    font-size: 3em;
    color: #FFD700;
    text-shadow: 3px 3px 0 #8B4513;
    margin-bottom: 20px;
  }

  .level-stats {
    background: rgba(255,255,255,0.1);
    border-radius: 15px;
    padding: 20px 40px;
    margin-bottom: 20px;
    text-align: center;
  }

  .level-stats p {
    color: #fff;
    font-size: 1.3em;
    margin: 5px 0;
  }

  .stars {
    font-size: 3em;
    margin: 10px 0;
  }

  /* Upgrades Screen */
  #upgradesScreen {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, #2C1810, #1a0a00);
    display: none;
    flex-direction: column;
    align-items: center;
    z-index: 200;
    padding: 20px;
    overflow-y: auto;
  }

  #upgradesScreen h2 {
    color: #FFD700;
    font-size: 2.5em;
    margin-bottom: 20px;
    text-shadow: 2px 2px 0 #8B4513;
  }

  .upgrade-card {
    background: linear-gradient(180deg, #3E1F09, #2C1810);
    border: 3px solid #8B6914;
    border-radius: 15px;
    padding: 15px 25px;
    margin: 8px;
    width: 90%;
    max-width: 400px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: #fff;
  }

  .upgrade-info { flex: 1; }
  .upgrade-name { font-size: 1.2em; font-weight: 700; }
  .upgrade-desc { font-size: 0.85em; color: #ccc; }
  .upgrade-level { font-size: 0.8em; color: #FFD700; }

  .upgrade-buy {
    padding: 8px 20px;
    background: linear-gradient(180deg, #FFD700, #FF8C00);
    border: 2px solid #B8650A;
    border-radius: 10px;
    font-family: 'Cairo', sans-serif;
    font-weight: 700;
    cursor: pointer;
    color: #3E1F09;
    white-space: nowrap;
  }

  .upgrade-buy:disabled {
    background: #555;
    border-color: #333;
    color: #888;
    cursor: not-allowed;
  }

  .btn-back {
    margin-top: 20px;
    padding: 10px 40px;
    background: linear-gradient(180deg, #ff6666, #cc0000);
    color: #fff;
    border: 2px solid #990000;
    border-radius: 10px;
    font-family: 'Cairo', sans-serif;
    font-weight: 700;
    font-size: 1.1em;
    cursor: pointer;
  }

  /* Help Screen */
  #helpScreen {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.9);
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    z-index: 250;
    padding: 20px;
    overflow-y: auto;
  }

  #helpScreen h2 {
    color: #FFD700;
    font-size: 2.5em;
    margin-bottom: 20px;
  }

  .help-text {
    color: #fff;
    font-size: 1.1em;
    max-width: 500px;
    text-align: center;
    line-height: 1.8;
    margin-bottom: 10px;
  }

  .help-text span { color: #FFD700; font-weight: 700; }

  /* Chickpea Soaking */
  .soak-area {
    width: 100%;
    height: 60px;
    background: linear-gradient(180deg, #87CEEB, #4682B4);
    border-radius: 10px;
    position: relative;
    overflow: hidden;
    margin-top: 5px;
  }

  .chickpea {
    position: absolute;
    width: 15px;
    height: 15px;
    background: #DAA520;
    border-radius: 50%;
    border: 1px solid #B8860B;
  }

  .soak-label {
    position: absolute;
    bottom: 5px;
    left: 50%;
    transform: translateX(-50%);
    color: #fff;
    font-size: 0.7em;
    font-weight: 700;
    text-shadow: 1px 1px 2px #000;
  }

  /* Notification */
  .notification {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: rgba(0,0,0,0.9);
    color: #FFD700;
    padding: 15px 30px;
    border-radius: 15px;
    font-size: 1.5em;
    font-weight: 700;
    z-index: 400;
    animation: notifPop 2s ease forwards;
    text-align: center;
    border: 3px solid #FFD700;
  }

  @keyframes notifPop {
    0% { transform: translate(-50%, -50%) scale(0); opacity: 0; }
    15% { transform: translate(-50%, -50%) scale(1.2); opacity: 1; }
    25% { transform: translate(-50%, -50%) scale(1); }
    75% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
    100% { transform: translate(-50%, -50%) scale(0.8); opacity: 0; }
  }

  /* Combo */
  #comboDisplay {
    position: absolute;
    top: 60px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 2em;
    font-weight: 900;
    color: #FFD700;
    text-shadow: 2px 2px 0 #ff4444;
    z-index: 50;
    display: none;
    animation: comboPulse 0.5s ease;
  }

  @keyframes comboPulse {
    0% { transform: translateX(-50%) scale(1.5); }
    100% { transform: translateX(-50%) scale(1); }
  }

  /* Responsive */
  @media (max-width: 600px) {
    #mainMenu .title { font-size: 2.5em; }
    .menu-falafel { font-size: 4em; }
    .station { min-width: 100px; padding: 5px; }
    .customer { min-width: 90px; }
    .customer-body { width: 60px; height: 80px; }
    .pan { width: 80px; height: 25px; }
  }

  /* Steam effect */
  .steam {
    position: absolute;
    width: 8px;
    height: 20px;
    background: rgba(255,255,255,0.3);
    border-radius: 50%;
    animation: steamRise 1.5s ease-out forwards;
    pointer-events: none;
  }

  @keyframes steamRise {
    0% { transform: translateY(0) scaleX(1); opacity: 0.6; }
    100% { transform: translateY(-40px) scaleX(2); opacity: 0; }
  }

  /* Fire effect */
  .fire-particle {
    position: absolute;
    width: 6px;
    height: 6px;
    background: #ff4400;
    border-radius: 50%;
    animation: fireUp 0.8s ease-out forwards;
    pointer-events: none;
  }

  @keyframes fireUp {
    0% { transform: translateY(0) scale(1); opacity: 1; }
    100% { transform: translateY(-30px) scale(0); opacity: 0; }
  }

  .level-badge {
    background: #FFD700;
    color: #3E1F09;
    padding: 2px 12px;
    border-radius: 10px;
    font-weight: 900;
    font-size: 0.9em;
  }

  /* Chickpea soak progress */
  .soak-progress-bar {
    width: 100%;
    height: 12px;
    background: #333;
    border-radius: 6px;
    margin-top: 5px;
    overflow: hidden;
    border: 1px solid #8B6914;
  }

  .soak-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, #4682B4, #87CEEB);
    border-radius: 6px;
    transition: width 0.3s;
  }

  .soak-btn {
    padding: 5px 15px;
    background: linear-gradient(180deg, #4682B4, #191970);
    border: 2px solid #000080;
    border-radius: 8px;
    font-family: 'Cairo', sans-serif;
    font-weight: 700;
    font-size: 0.8em;
    cursor: pointer;
    color: #fff;
    margin-top: 3px;
  }

  .soak-btn:disabled {
    background: #555;
    border-color: #333;
    cursor: not-allowed;
  }

  .spice-selector {
    display: flex;
    gap: 3px;
    flex-wrap: wrap;
    justify-content: center;
    margin-top: 3px;
  }

  .spice-btn {
    padding: 2px 6px;
    font-size: 0.7em;
    border: 1px solid #8B6914;
    border-radius: 5px;
    background: #FFF8DC;
    cursor: pointer;
    font-family: 'Cairo', sans-serif;
    font-weight: 700;
  }

  .spice-btn:hover { background: #FFD700; }
  .spice-btn.selected { background: #FFD700; border-color: #B8650A; }

  .empty-slot {
    color: #aaa;
    font-style: italic;
    font-size: 0.8em;
  }
</style>
</head>
<body>
<div id="gameContainer">
  <!-- Main Menu -->
  <div id="mainMenu">
    <div class="menu-falafel">🧆</div>
    <div class="title">ملك الفلافل</div>
    <div class="subtitle">🏆 أطيب فلافل في مصر! 🏆</div>
    <button class="btn btn-play" onclick="startGame()">🎮 ابدأ اللعب</button>
    <button class="btn btn-upgrades" onclick="showUpgrades()">🔧 الترقية</button>
    <button class="btn btn-help" onclick="showHelp()">❓ طريقة اللعب</button>
    <div style="color:#fff; margin-top:20px; font-size:0.9em;">
      💰 الرصيد: <span id="menuMoney">0</span> | 🏆 أعلى مستوى: <span id="menuLevel">1</span>
    </div>
  </div>

  <!-- Game Screen -->
  <div id="gameScreen">
    <div id="topBar">
      <div class="stat">
        <span class="stat-icon">🏆</span>
        <span class="level-badge" id="levelDisplay">مستوى 1</span>
      </div>
      <div class="stat">
        <span class="stat-icon">⏱️</span>
        <div id="timerBar"><div id="timerFill" style="width:100%"></div></div>
      </div>
      <div class="stat">
        <span class="stat-icon">💰</span>
        <span class="stat-value" id="moneyDisplay">0</span>
      </div>
      <div class="stat">
        <span class="stat-icon">⭐</span>
        <span class="stat-value" id="scoreDisplay">0</span>
      </div>
      <div class="stat">
        <span class="stat-icon">👥</span>
        <span class="stat-value" id="servedDisplay">0/0</span>
      </div>
    </div>

    <div id="comboDisplay"></div>

    <div id="customerQueue">
      <div id="customersContainer"></div>
    </div>

    <div id="cookingArea">
      <!-- Frying Station -->
      <div class="station" id="fryingStation">
        <div class="station-title">🍳 قلي الفلافل</div>
        <div class="pan">
          <div class="oil" id="oil"></div>
          <div class="falafel-in-oil" id="falafelInOil"></div>
        </div>
        <div class="fry-progress">
          <div class="fry-progress-fill" id="fryProgressFill" style="width:0%"></div>
        </div>
        <div style="font-size:0.7em; color:#ccc; margin-top:2px;" id="fryStatus">اضغط للقلي</div>
        <button class="fry-btn" id="fryBtn" onclick="startFrying()">🧆 اقلي!</button>
        <div class="ingredient-count" id="falafelCount">فلافل جاهزة: 0</div>
      </div>

      <!-- Assembly Station -->
      <div class="station" id="assemblyStation">
        <div class="station-title">🥖 تجهيز الساندوتش</div>
        <div class="sandwich-slot" id="sandwichSlot">
          <span class="empty-slot">اضغط على المكونات</span>
        </div>
        <div class="spice-selector" id="spiceSelector">
          <button class="spice-btn" onclick="toggleSpice(this, 'كزبرة')">🌿 كزبرة</button>
          <button class="spice-btn" onclick="toggleSpice(this, 'كمون')">🫙 كمون</button>
          <button class="spice-btn" onclick="toggleSpice(this, 'ثوم')">🧄 ثوم</button>
          <button class="spice-btn" onclick="toggleSpice(this, 'حار')">🌶️ حار</button>
        </div>
        <div style="display:flex; flex-wrap:wrap; justify-content:center; gap:3px; margin-top:5px;">
          <button class="ingredient-btn" onclick="addIngredient('خبز')">🥖 خبز</button>
          <button class="ingredient-btn" onclick="addIngredient('فلافل')">🧆 فلافل</button>
          <button class="ingredient-btn" onclick="addIngredient('طحينة')">🥄 طحينة</button>
          <button class="ingredient-btn" onclick="addIngredient('سلطة')">🥗 سلطة</button>
          <button class="ingredient-btn" onclick="addIngredient('مخلل')">🥒 مخلل</button>
          <button class="ingredient-btn" onclick="addIngredient('صلصة')">🫙 صوص</button>
        </div>
        <button class="serve-btn" id="serveBtn" onclick="serveSandwich()" disabled>🍽️ قدّم!</button>
        <button class="ingredient-btn" onclick="clearSandwich()" style="background:#ffcccc; margin-top:3px;">🗑️ نظّف</button>
      </div>

      <!-- Chickpea Soak Station -->
      <div class="station" id="soakStation">
        <div class="station-title">💧 نقع الحمص</div>
        <div class="soak-area" id="soakArea">
          <div class="soak-label">نقع الحمص</div>
        </div>
        <div class="soak-progress-bar">
          <div class="soak-progress-fill" id="soakProgressFill" style="width:0%"></div>
        </div>
        <div style="font-size:0.75em; color:#333; margin-top:3px;" id="soakStatus">جاهز للنقع</div>
        <button class="soak-btn" id="soakBtn" onclick="startSoaking()">💧 انقع!</button>
        <div class="ingredient-count" id="chickpeaCount">حمص جاهز: 0</div>
      </div>
    </div>
  </div>

  <!-- Level Complete -->
  <div id="levelComplete">
    <h2 id="levelTitle">🎉 أحسنت!</h2>
    <div class="stars" id="starsDisplay">⭐⭐⭐</div>
    <div class="level-stats">
      <p>💰 الأرباح: <span id="levelMoney">0</span></p>
      <p>⭐ النقاط: <span id="levelScore">0</span></p>
      <p>👥 الزبائن: <span id="levelServed">0</span></p>
      <p>🔥 كومبو: <span id="levelCombo">0</span></p>
    </div>
    <button class="btn btn-play" onclick="nextLevel()">➡️ المستوى التالي</button>
    <button class="btn btn-upgrades" onclick="showUpgrades()" style="margin-top:5px;">🔧 الترقية</button>
  </div>

  <!-- Upgrades Screen -->
  <div id="upgradesScreen">
    <h2>🔧 ترقية المطعم</h2>
    <div id="upgradesList"></div>
    <button class="btn-back" onclick="hideUpgrades()">↩️ رجوع</button>
  </div>

  <!-- Help Screen -->
  <div id="helpScreen">
    <h2>❓ طريقة اللعب</h2>
    <div class="help-text">
      <span>🧆 قلي الفلافل:</span> اضغط "اقلي" لوضع الفلافل في الزيت. راقب شريط التقدم!<br>
      <span>🫘 نقع الحمص:</span> انقع الحمص أولاً حتى يكون جاهزاً للفلافل.<br>
      <span>🥖 تجهيز الساندوتش:</span> أضف المكونات حسب طلب الزبون (خبز، فلافل، طحينة، سلطة، مخلل، صوص).<br>
      <span>🍽️ التقديم:</span> قدّم الساندوتش للزبون الصحيح.<br>
      <span>🪰 الذباب:</span> اضغط على الذباب لطرده!<br>
      <span>🔥 الكومبو:</span> قدّم طلبات متتالية بسرعة للحصول على مضاعفات!<br>
      <span>⏱️ الوقت:</span> كل زبون له صبر محدود - قدّمه قبل ما يغضب!<br>
      <span>💡 نصيحة:</span> ارفع مستوى مقلاه ونقع الحمص عشان تلعب أسرع!
    </div>
    <button class="btn-back" onclick="hideHelp()">↩️ رجوع</button>
  </div>
</div>

<script>
// ============ GAME STATE ============
const G = {
  money: 0,
  score: 0,
  level: 1,
  maxLevel: 1,
  served: 0,
  totalServed: 0,
  combo: 0,
  maxCombo: 0,
  levelTimer: 0,
  maxLevelTime: 60,
  customers: [],
  falafelReady: 0,
  chickpeaReady: 0,
  soaking: false,
  soakProgress: 0,
  frying: false,
  fryProgress: 0,
  currentSandwich: [],
  selectedSpices: [],
  flyInterval: null,
  customerInterval: null,
  gameInterval: null,
  timerInterval: null,
  upgrades: {
    fryer: 1,
    soakSpeed: 1,
    patience: 1,
