    maxLevel: 3,
    apply: () => {}
  }
];

// ============ ORDERS ============
const ORDERS = [
  { name: 'فلافل عادي', items: ['خبز', 'فلافل', 'طحينة'], price: 5 },
  { name: 'فلافل سلطات', items: ['خبز', 'فلافل', 'سلطة', 'مخلل'], price: 7 },
  { name: 'فلافل كامل', items: ['خبز', 'فلافل', 'طحينة', 'سلطة', 'مخلل', 'صلصة'], price: 10 },
  { name: 'فلافل طحينة', items: ['خبز', 'فلافل', 'طحينة', 'صلصة'], price: 8 },
  { name: 'فلافل خضار', items: ['خبز', 'فلافل', 'سلطة', 'مخلل'], price: 6 },
  { name: 'فلافل كلاسيك', items: ['خبز', 'فلافل', 'طحينة', 'سلطة'], price: 9 },
];

const CUSTOMER_HATS = ['👒', '🧢', '👑', '🎩', '🧑‍🦱', '👨', '👩', '🧕', '👳', '🤠'];
const SHIRTS = ['#4169E1', '#DC143C', '#228B22', '#FF8C00', '#9370DB', '#20B2AA', '#FF6347', '#FFD700'];

// ============ INIT ============
function init() {
  loadGame();
  updateMenuDisplay();
}

function loadGame() {
  try {
    const saved = localStorage.getItem('falafelKing');
    if (saved) {
      const data = JSON.parse(saved);
      G.money = data.money || 0;
      G.level = data.level || 1;
      G.maxLevel = data.maxLevel || 1;
      G.totalServed = data.totalServed || 0;
      G.upgrades = data.upgrades || G.upgrades;
    }
  } catch(e) {}
}

function saveGame() {
  try {
    localStorage.setItem('falafelKing', JSON.stringify({
      money: G.money,
      level: G.level,
      maxLevel: G.maxLevel,
      totalServed: G.totalServed,
      upgrades: G.upgrades
    }));
  } catch(e) {}
}

function updateMenuDisplay() {
  document.getElementById('menuMoney').textContent = G.money;
  document.getElementById('menuLevel').textContent = G.maxLevel;
}

// ============ GAME START ============
function startGame() {
  document.getElementById('mainMenu').style.display = 'none';
  document.getElementById('gameScreen').style.display = 'flex';
  document.getElementById('levelComplete').style.display = 'none';

  G.levelTimer = G.maxLevelTime;
  G.served = 0;
  G.combo = 0;
  G.maxCombo = 0;
  G.customers = [];
  G.falafelReady = 0;
  G.chickpeaReady = 0;
  G.currentSandwich = [];
  G.selectedSpices = [];
  G.frying = false;
  G.fryProgress = 0;
  G.soaking = false;
  G.soakProgress = 0;

  startLevel();
}

function startLevel() {
  G.maxLevelTime = 45 + G.level * 10;
  G.levelTimer = G.maxLevelTime;

  document.getElementById('levelDisplay').textContent = 'مستوى ' + G.level;
  document.getElementById('servedDisplay').textContent = '0/' + (5 + G.level * 2);

  // Reset stations
  updateFalafelCount();
  updateChickpeaCount();
  updateSandwichDisplay();
  updateSoakUI();
  updateFryUI();

  // Clear existing intervals
  clearAllIntervals();

  // Start customer spawning
  spawnCustomer();
  G.customerInterval = setInterval(() => {
    if (G.customers.length < 3 + Math.floor(G.level / 2)) {
      spawnCustomer();
    }
  }, Math.max(2000, 5000 - G.level * 300));

  // Start timer
  G.timerInterval = setInterval(() => {
    G.levelTimer -= 0.1;
    const pct = Math.max(0, (G.levelTimer / G.maxLevelTime) * 100);
    document.getElementById('timerFill').style.width = pct + '%';

    if (G.levelTimer <= 0) {
      endLevel();
    }
  }, 100);

  // Game loop
  G.gameInterval = setInterval(gameLoop, 50);

  // Fly spawning
  if (G.level >= 2) {
    G.flyInterval = setInterval(spawnFly, Math.max(3000, 8000 - G.level * 500));
  }

  showNotification('🎮 المستوى ' + G.level + '!');
}

function clearAllIntervals() {
  clearInterval(G.customerInterval);
  clearInterval(G.timerInterval);
  clearInterval(G.gameInterval);
  clearInterval(G.flyInterval);
}

// ============ GAME LOOP ============
function gameLoop() {
  // Update soaking
  if (G.soaking) {
    const speed = 1 + (G.upgrades.soakSpeed - 1) * 0.3;
    G.soakProgress += speed;
    if (G.soakProgress >= 100) {
      G.soakProgress = 100;
      G.soaking = false;
      G.chickpeaReady += 3;
      updateChickpeaCount();
      showNotification('💧 الحمص جاهز! +3');
    }
    updateSoakUI();
  }

  // Update frying
  if (G.frying) {
    const speed = 0.8 + (G.upgrades.fryer - 1) * 0.2;
    G.fryProgress += speed;
    if (G.fryProgress >= 100) {
      G.fryProgress = 100;
      G.frying = false;
      G.falafelReady += 2;
      updateFalafelCount();
      showNotification('🧆 فلافل جاهزة! +2');
    }
    updateFryUI();
  }

  // Update customer patience
  G.customers.forEach((c, i) => {
    c.patience -= 0.15;
    const patienceMult = 1 + (G.upgrades.patience - 1) * 0.2;
    c.patience -= 0.05 * patienceMult;

    if (c.patience <= 0) {
      c.angry = true;
      G.combo = 0;
      updateComboDisplay();
    }

    if (c.patience < 0) {
      // Customer leaves angry
      G.customers.splice(i, 1);
      renderCustomers();
    }

    // Update patience bar
    const bar = document.getElementById('patience-' + c.id);
    if (bar) {
      const pct = Math.max(0, c.patience);
      bar.style.width = pct + '%';
      if (pct > 60) bar.style.background = '#44ff44';
      else if (pct > 30) bar.style.background = '#ffaa00';
      else bar.style.background = '#ff4444';
    }

    // Update mouth
    const body = document.getElementById('body-' + c.id);
    if (body) {
      if (c.angry) body.classList.add('angry');
      else if (c.happy) body.classList.add('happy');
    }
  });
}

// ============ CUSTOMERS ============
let customerId = 0;

function spawnCustomer() {
  const order = ORDERS[Math.floor(Math.random() * Math.min(ORDERS.length, 2 + G.level))];
  const customer = {
    id: customerId++,
    order: order,
    patience: 100,
    angry: false,
    happy: false,
    hat: CUSTOMER_HATS[Math.floor(Math.random() * CUSTOMER_HATS.length)],
    shirt: SHIRTS[Math.floor(Math.random() * SHIRTS.length)]
  };
  G.customers.push(customer);
  renderCustomers();
}

function renderCustomers() {
  const container = document.getElementById('customersContainer');
  container.innerHTML = '';

  G.customers.forEach(c => {
    const div = document.createElement('div');
    div.className = 'customer';
    div.id = 'customer-' + c.id;

    const orderText = c.order.items.map(i => getIngredientEmoji(i)).join(' + ');

    div.innerHTML = `
      <div class="order-bubble">${order.name}<br><small>${orderText}</small></div>
      <div class="customer-body" id="body-${c.id}">
        <div class="customer-hat">${c.hat}</div>
        <div class="customer-eyes">
          <div class="eye"></div>
          <div class="eye"></div>
        </div>
        <div class="customer-mouth"></div>
      </div>
      <div class="customer-shirt" style="background:${c.shirt}"></div>
      <div class="patience-bar">
        <div class="patience-fill" id="patience-${c.id}" style="width:${c.patience}%"></div>
      </div>
    `;

    container.appendChild(div);
  });

  // Scroll to show newest
  container.scrollLeft = container.scrollWidth;

  // Update served count
  const needed = 5 + G.level * 2;
  document.getElementById('servedDisplay').textContent = G.served + '/' + needed;
}

function getIngredientEmoji(ing) {
  const map = {
    'خبز': '🥖', 'فلافل': '🧆', 'طحينة': '🥄',
    'سلطة': '🥗', 'مخلل': '🥒', 'صلصة': '🫙',
    'كزبرة': '🌿', 'كمون': '🫙', 'ثوم': '🧄', 'حار': '🌶️'
  };
  return map[ing] || '🔸';
}

// ============ FRYING ============
function startFrying() {
  if (G.frying || G.chickpeaReady < 1) {
    if (G.chickpeaReady < 1) showNotification('💧 محتاج حمص أولاً!');
    return;
  }

  G.chickpeaReady -= 1;
  G.frying = true;
  G.fryProgress = 0;
  updateFalafelCount();
  updateFryUI();
}

function updateFryUI() {
  const oil = document.getElementById('oil');
  const fill = document.getElementById('fryProgressFill');
  const status = document.getElementById('fryStatus');
  const btn = document.getElementById('fryBtn');

  fill.style.width = G.fryProgress + '%';

  if (G.frying) {
    const pct = G.fryProgress;
    if (pct < 30) {
      oil.className = 'oil cold';
      status.textContent = 'الزيت بارد...';
    } else if (pct < 70) {
      oil.className = 'oil';
      status.textContent = '🧆 بقت جاهزة!';
    } else if (pct < 95) {
      oil.className = 'oil';
      status.textContent = '✅ تمام!';
    } else {
      oil.className = 'oil hot';
      status.textContent = '⚠️ هتحترق!';
    }
    btn.textContent = '⏳ جاري القلي...';
    btn.disabled = true;
  } else {
    oil.className = 'oil';
    status.textContent = 'اضغط للقلي';
    btn.textContent = '🧆 اقلي!';
    btn.disabled = false;
  }
}

// ============ CHICKPEA SOAKING ============
function startSoaking() {
  if (G.soaking) return;

  G.soaking = true;
  G.soakProgress = 0;
  updateSoakUI();
}

function updateSoakUI() {
  const fill = document.getElementById('soakProgressFill');
  const status = document.getElementById('soakStatus');
  const btn = document.getElementById('soakBtn');
  const area = document.getElementById('soakArea');

  fill.style.width = G.soakProgress + '%';

  if (G.soaking) {
    const pct = G.soakProgress;
    status.textContent = 'جاري النقع... ' + Math.floor(pct) + '%';
    btn.textContent = '⏳ جاري...';
    btn.disabled = true;

    // Add chickpea visuals
    area.innerHTML = '<div class="soak-label">نقع الحمص ' + Math.floor(pct) + '%</div>';
    const numChickpeas = Math.floor(pct / 10);
    for (let i = 0; i < numChickpeas; i++) {
      const cp = document.createElement('div');
      cp.className = 'chickpea';
      cp.style.left = (10 + Math.random() * 70) + 'px';
      cp.style.top = (5 + Math.random() * 35) + 'px';
      cp.style.opacity = 0.5 + (pct / 200);
      area.appendChild(cp);
    }
  } else {
    status.textContent = G.chickpeaReady > 0 ? 'حمص جاهز! 💧' : 'جاهز للنقع';
    btn.textContent = '💧 انقع!';
    btn.disabled = false;
    area.innerHTML = '<div class="soak-label">نقع الحمص</div>';
  }
}

function updateChickpeaCount() {
  document.getElementById('chickpeaCount').textContent = 'حمص جاهز: ' + G.chickpeaReady;
}

// ============ ASSEMBLY ============
function addIngredient(ing) {
  if (G.currentSandwich.length >= 8) return;

  if (ing === 'فلافل' && G.falafelReady < 1) {
    showNotification('🧆 محتاج فلافل! اقلي أولاً');
    return;
  }

  G.currentSandwich.push(ing);
  if (ing === 'فلافل') G.falafelReady -= 1;
  updateFalafelCount();
  updateSandwichDisplay();
}

function clearSandwich() {
  // Return falafel
  G.falafelReady += G.currentSandwich.filter(i => i === 'فلافل').length;
  G.currentSandwich = [];
  G.selectedSpices = [];
  updateFalafelCount();
  updateSandwichDisplay();
  document.querySelectorAll('.spice-btn').forEach(b => b.classList.remove('selected'));
}

function toggleSpice(btn, spice) {
  btn.classList.toggle('selected');
  if (G.selectedSpices.includes(spice)) {
    G.selectedSpices = G.selectedSpices.filter(s => s !== spice);
  } else {
    G.selectedSpices.push(spice);
  }
}

function updateSandwichDisplay() {
  const slot = document.getElementById('sandwichSlot');
  const serveBtn = document.getElementById('serveBtn');

  if (G.currentSandwich.length === 0) {
    slot.innerHTML = '<span class="empty-slot">اضغط على المكونات</span>';
    serveBtn.disabled = true;
    return;
  }

  slot.innerHTML = G.currentSandwich.map(i => `<span class="ingredient">${getIngredientEmoji(i)}</span>`).join('');

  // Check if sandwich has at least خبز and فلافل
  const hasBread = G.currentSandwich.includes('خبز');
  const hasFalafel = G.currentSandwich.includes('فلافل');
  serveBtn.disabled = !(hasBread && hasFalafel);
}

// ============ SERVING ============
function serveSandwich() {
  if (G.currentSandwich.length === 0) return;

  // Find matching customer
  let bestMatch = null;
  let bestScore = -1;

  G.customers.forEach(c => {
    if (c.angry) return;

    const orderItems = c.order.items;
    let matchCount = 0;

    orderItems.forEach(item => {
      if (G.currentSandwich.includes(item)) matchCount++;
    });

    // Bonus for spices
    const spiceBonus = G.selectedSpices.length * 0.1 * G.upgrades.spice;
    const score = matchCount + spiceBonus;

    if (score > bestScore) {
      bestScore = score;
      bestMatch = c;
    }
  });

  if (!bestMatch) {
    showNotification('🤷 مفيش زبون محتاج!');
    return;
  }

  // Calculate earnings
  const orderItems = bestMatch.order.items;
  let matchCount = 0;
  orderItems.forEach(item => {
    if (G.currentSandwich.includes(item)) matchCount++;
  });

  const accuracy = matchCount / orderItems.length;
  const basePrice = bestMatch.order.price;
  const spiceBonus = G.selectedSpices.length * 2 * G.upgrades.spice;
  const comboMult = 1 + G.combo * 0.2;
  const earned = Math.round((basePrice * accuracy + spiceBonus) * comboMult);

  // Update combo
  if (accuracy >= 0.7) {
    G.combo++;
    G.maxCombo = Math.max(G.maxCombo, G.combo);
  } else {
    G.combo = 0;
  }

  G.money += earned;
  G.score += Math.round(earned * (accuracy * 10));
  G.served++;
  G.totalServed++;

  // Mark customer happy
  bestMatch.happy = true;
  bestMatch.patience = 0;

  // Remove customer after delay
  const idx = G.customers.indexOf(bestMatch);
  setTimeout(() => {
    G.customers.splice(idx, 1);
    renderCustomers();
  }, 500);

  // Show floating text
  showFloatText('+' + earned + '💰', '#FFD700');
  if (G.combo > 1) showFloatText('🔥 كومبو x' + G.combo + '!', '#ff4444');

  updateComboDisplay();
  updateDisplay();
  updateFalafelCount();

  // Clear sandwich
  G.currentSandwich = [];
  G.selectedSpices = [];
  document.querySelectorAll('.spice-btn').forEach(b => b.classList.remove('selected'));
  updateSandwichDisplay();
  renderCustomers();

  // Check level complete
  if (G.served >= 5 + G.level * 2) {
    endLevel();
  }
}

function updateComboDisplay() {
  const el = document.getElementById('comboDisplay');
  if (G.combo >= 3) {
    el.style.display = 'block';
    el.textContent = '🔥 كومبو x' + G.combo + '!';
    el.style.animation = 'none';
    el.offsetHeight;
    el.style.animation = 'comboPulse 0.5s ease';
  } else {
    el.style.display = 'none';
  }
}

function updateDisplay() {
  document.getElementById('moneyDisplay').textContent = G.money;
  document.getElementById('scoreDisplay').textContent = G.score;
}

// ============ FLIES ============
function spawnFly() {
  const queue = document.getElementById('customerQueue');
  const fly = document.createElement('div');
  fly.className = 'fly';
  fly.textContent = '🪰';
  fly.style.left = (10 + Math.random() * 80) + '%';
  fly.style.top = (10 + Math.random() * 60) + '%';
  fly.onclick = function() {
    this.style.transform = 'scale(2) rotate(360deg)';
    this.style.opacity = '0';
    setTimeout(() => this.remove(), 200);
    showFloatText('💥 طردت الذبابة!', '#44ff44');
  };
  queue.appendChild(fly);

  setTimeout(() => {
    if (fly.parentNode) fly.remove();
  }, 8000);
}

// ============ LEVEL END ============
function endLevel() {
  clearAllIntervals();

  const needed = 5 + G.level * 2;
  const accuracy = G.served / Math.max(1, needed);

  let stars = '⭐';
  if (accuracy >= 0.5) stars = '⭐⭐';
  if (accuracy >= 0.8) stars = '⭐⭐⭐';

  document.getElementById('levelTitle').textContent = G.served >= needed ? '🎉 أحسنت!' : '⏰ انتهى الوقت!';
  document.getElementById('starsDisplay').textContent = stars;
  document.getElementById('levelMoney').textContent = G.money;
  document.getElementById('levelScore').textContent = G.score;
  document.getElementById('levelServed').textContent = G.served + '/' + needed;
  document.getElementById('levelCombo').textContent = G.maxCombo;

  if (G.served >= needed) {
    G.maxLevel = Math.max(G.maxLevel, G.level + 1);
    G.level++;
  }

  saveGame();
  updateMenuDisplay();

  document.getElementById('levelComplete').style.display = 'flex';
}

function nextLevel() {
  document.getElementById('levelComplete').style.display = 'none';
  startLevel();
}

// ============ UPGRADES ============
function showUpgrades() {
  document.getElementById('mainMenu').style.display = 'none';
  document.getElementById('gameScreen').style.display = 'none';
  document.getElementById('levelComplete').style.display = 'none';
  document.getElementById('upgradesScreen').style.display = 'flex';
  renderUpgrades();
}

function hideUpgrades() {
  document.getElementById('upgradesScreen').style.display = 'none';
  document.getElementById('mainMenu').style.display = 'flex';
  updateMenuDisplay();
}

function renderUpgrades() {
  const list = document.getElementById('upgradesList');
  list.innerHTML = '';

  UPGRADES.forEach(u => {
    const level = G.upgrades[u.id];
    const cost = Math.round(u.baseCost * Math.pow(u.costMult, level - 1));
    const maxed = level >= u.maxLevel;

    const card = document.createElement('div');
    card.className = 'upgrade-card';
    card.innerHTML = `
      <div class="upgrade-info">
        <div class="upgrade-name">${u.name}</div>
        <div class="upgrade-desc">${u.desc}</div>
        <div class="upgrade-level">المستوى ${level}/${u.maxLevel}</div>
      </div>
      <button class="upgrade-buy" ${maxed || G.money < cost ? 'disabled' : ''} 
        onclick="buyUpgrade('${u.id}')">
        ${maxed ? '✅ كامل' : cost + ' 💰'}
      </button>
    `;
    list.appendChild(card);
  });
}

function buyUpgrade(id) {
  const u = UPGRADES.find(up => up.id === id);
  if (!u) return;

  const level = G.upgrades[id];
  const cost = Math.round(u.baseCost * Math.pow(u.costMult, level - 1));

  if (G.money >= cost && level < u.maxLevel) {
    G.money -= cost;
    G.upgrades[id]++;
    saveGame();
    renderUpgrades();
    updateMenuDisplay();
    showNotification('🔧 ' + u.name + ' - مستوى ' + G.upgrades[id] + '!');
  }
}

// ============ HELP ============
function showHelp() {
  document.getElementById('mainMenu').style.display = 'none';
  document.getElementById('helpScreen').style.display = 'flex';
}

function hideHelp() {
  document.getElementById('helpScreen').style.display = 'none';
  document.getElementById('mainMenu').style.display = 'flex';
}

// ============ EFFECTS ============
function showFloatText(text, color) {
  const el = document.createElement('div');
  el.className = 'float-text';
  el.textContent = text;
  el.style.color = color;
  el.style.left = (30 + Math.random() * 40) + '%';
  el.style.top = '40%';
  document.getElementById('gameScreen').appendChild(el);
  setTimeout(() => el.remove(), 1000);
}

function showNotification(text) {
  const el = document.createElement('div');
  el.className = 'notification';
  el.textContent = text;
  document.getElementById('gameContainer').appendChild(el);
  setTimeout(() => el.remove(), 2000);
}

// ============ START ============
init();
</script>
</body>
</html>
