        let x = 100 + Math.random() * (MAP_SIZE - 200);
        let y = 100 + Math.random() * (MAP_SIZE - 200);
        // Don't place loot inside buildings
        let inBuilding = false;
        for (let b of buildings) {
            if (x > b.x && x < b.x + b.w && y > b.y && y < b.y + b.h) { inBuilding = true; break; }
        }
        if (!inBuilding) spawnLoot(x, y);
    }
