function spawnLoot(x, y) {
    let rand = Math.random();
    let cumulative = 0;
    for (let lt of LOOT_TYPES) {
        cumulative += lt.chance;
        if (rand <= cumulative) {
            loot.push({ x, y, ...lt, pickupRadius: 30, bobOffset: Math.random() * Math.PI * 2 });
            return;
        }
    }
}

