    for (let i = 0; i < BOT_COUNT; i++) {
        let bx, by;
        do {
            bx = 200 + Math.random() * (MAP_SIZE - 400);
            by = 200 + Math.random() * (MAP_SIZE - 400);
        } while (Math.hypot(bx - players[0].x, by - players[0].y) < 400 || Math.hypot(bx - players[1].x, by - players[1].y) < 400);
