function gameLoop(timestamp) {
    if (!gameRunning) return;
    let dt = Math.min(timestamp - lastTime, 50);
    lastTime = timestamp;
    gameTime += dt;

    update(dt);
    render();

    requestAnimationFrame(gameLoop);
}

function update(dt) {
    let dtSec = dt / 1000;

    // Storm
    storm.shrinkTimer += dt;
    if (storm.shrinkTimer >= storm.nextShrink) {
        storm.targetRadius = Math.max(100, storm.targetRadius - STORM_SHRINK_AMOUNT);
        storm.nextShrink = 25000;
        storm.shrinkTimer = 0;
    }
    if (storm.radius > storm.targetRadius) {
        storm.radius -= dtSec * 15;
    }

    // Update players
    for (let p of players) {
        if (!p.alive) continue;
        updatePlayer(p, dt);
    }

    // Update bots
    for (let b of bots) {
        if (!b.alive) continue;
        updateBot(b, dt);
    }

    // Update bullets
    for (let i = bullets.length - 1; i >= 0; i--) {
        let b = bullets[i];
        b.x += b.vx * dtSec;
        b.y += b.vy * dtSec;
        b.life -= dt;
        b.dist += Math.hypot(b.vx * dtSec, b.vy * dtSec);

        // Hit obstacles
        let hitObstacle = false;
        for (let o of obstacles) {
            if (o.isTree || o.isRock) continue;
            if (b.x > o.x && b.x < o.x + o.w && b.y > o.y && b.y < o.y + o.h) {
                hitObstacle = true;
                spawnParticles(b.x, b.y, '#aaa', 3);
                break;
            }
        }

        // Hit trees
        for (let t of trees) {
            if (Math.hypot(b.x - t.x, b.y - t.y) < t.r) {
                hitObstacle = true;
                spawnParticles(b.x, b.y, '#4a2', 3);
                t.health--;
                if (t.health <= 0) {
                    let idx = trees.indexOf(t);
                    if (idx > -1) trees.splice(idx, 1);
                    let oIdx = obstacles.findIndex(o => o.treeRef === t);
                    if (oIdx > -1) obstacles.splice(oIdx, 1);
                }
                break;
            }
        }

        // Hit rocks
        for (let r of rocks) {
            if (Math.hypot(b.x - r.x, b.y - r.y) < r.r) {
                hitObstacle = true;
                spawnParticles(b.x, b.y, '#888', 3);
                r.health--;
                if (r.health <= 0) {
                    let idx = rocks.indexOf(r);
                    if (idx > -1) rocks.splice(idx, 1);
                    let oIdx = obstacles.findIndex(o => o.rockRef === r);
                    if (oIdx > -1) obstacles.splice(oIdx, 1);
                }
                break;
            }
        }

        // Hit players/bots
        let allEntities = [...players, ...bots];
        for (let e of allEntities) {
            if (!e.alive || e.id === b.ownerId) continue;
            if (Math.hypot(b.x - e.x, b.y - e.y) < e.radius + 4) {
                let dmg = b.damage;
                if (e.armor > 0) {
                    let armorDmg = Math.min(e.armor, dmg * 0.6);
                    e.armor -= armorDmg;
                    dmg -= armorDmg;
                }
                e.health -= dmg;
                e.hitFlash = 100;
                spawnParticles(b.x, b.y, '#f00', 5);

                if (e.health <= 0) {
                    e.alive = false;
                    e.health = 0;
                    b.owner.kills++;
                    if (b.ownerId === 1) totalKills.p1++;
                    if (b.ownerId === 2) totalKills.p2++;
                    aliveCount--;
                    killFeed.push({ text: `${b.owner.name} eliminated ${e.name}`, time: 5000, color: b.owner.color });
                    spawnParticles(e.x, e.y, '#f00', 15);
                    // Drop loot
                    for (let w of e.weapons) {
                        if (w.weapon !== 'fists') {
                            loot.push({ x: e.x + (Math.random()-0.5)*30, y: e.y + (Math.random()-0.5)*30, type: 'weapon', weapon: w.weapon, color: w.color, pickupRadius: 30, bobOffset: Math.random()*Math.PI*2 });
                        }
                    }
                    if (e.ammo9mm) loot.push({ x: e.x + (Math.random()-0.5)*20, y: e.y + (Math.random()-0.5)*20, type: 'ammo9mm', ammo: 15, color: '#ff0', pickupRadius: 25, bobOffset: 0 });
                    if (e.ammo556) loot.push({ x: e.x + (Math.random()-0.5)*20, y: e.y + (Math.random()-0.5)*20, type: 'ammo556', ammo: 15, color: '#0f0', pickupRadius: 25, bobOffset: 0 });
                    if (e.ammo762) loot.push({ x: e.x + (Math.random()-0.5)*20, y: e.y + (Math.random()-0.5)*20, type: 'ammo762', ammo: 10, color: '#f00', pickupRadius: 25, bobOffset: 0 });
                    if (e.ammoShotgun) loot.push({ x: e.x + (Math.random()-0.5)*20, y: e.y + (Math.random()-0.5)*20, type: 'ammoshotgun', ammo: 5, color: '#fa0', pickupRadius: 25, bobOffset: 0 });
                }
                hitObstacle = true;
                break;
            }
        }

        if (hitObstacle || b.life <= 0 || b.dist > b.range) {
            bullets.splice(i, 1);
        }
    }

    // Clean up bullets
    bullets = bullets.filter(b => b.life > 0);

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.vx * dtSec;
        p.y += p.vy * dtSec;
        p.life -= dt;
        p.vx *= 0.95;
        p.vy *= 0.95;
        if (p.life <= 0) particles.splice(i, 1);
    }

    // Storm damage
    for (let p of [...players, ...bots]) {
        if (!p.alive) continue;
        let distToStorm = Math.hypot(p.x - storm.x, p.y - storm.y);
        if (distToStorm > storm.radius) {
            p.health -= STORM_DAMAGE * dtSec;
            if (p.health <= 0) {
                p.alive = false;
                p.health = 0;
                aliveCount--;
                killFeed.push({ text: `${p.name} was eliminated by the storm`, time: 5000, color: '#0af' });
            }
        }
    }

    // Kill feed timer
    for (let i = killFeed.length - 1; i >= 0; i--) {
        killFeed[i].time -= dt;
        if (killFeed[i].time <= 0) killFeed.splice(i, 1);
    }

    // Check win/lose
    let alivePlayers = players.filter(p => p.alive).length;
    let aliveBots = bots.filter(b => b.alive).length;

    if (alivePlayers === 0 && gameRunning) {
        gameRunning = false;
        let goScreen = document.getElementById('game-over-screen');
        goScreen.style.display = 'flex';
        document.getElementById('go-title').textContent = 'DEFEAT';
        document.getElementById('go-title').style.color = '#f44';
        document.getElementById('go-stats').textContent = `Eliminated ${totalKills.p1 + totalKills.p2} enemies`;
        document.getElementById('go-kills').textContent = `Player 1: ${totalKills.p1} | Player 2: ${totalKills.p2}`;
    }

    if (aliveBots === 0 && alivePlayers > 0 && gameRunning) {
        gameRunning = false;
        let goScreen = document.getElementById('game-over-screen');
        goScreen.style.display = 'flex';
        document.getElementById('go-title').textContent = 'WINNER WINNER CHICKEN DINNER!';
        document.getElementById('go-title').style.color = '#ff8800';
        document.getElementById('go-stats').textContent = `Total eliminations: ${totalKills.p1 + totalKills.p2}`;
        document.getElementById('go-kills').textContent = `Player 1: ${totalKills.p1} | Player 2: ${totalKills.p2}`;
    }
}

function updatePlayer(p, dt) {
    let moveX = 0, moveY = 0;
    let speed = p.speed;

    if (p.id === 1) {
        if (keys['w']) moveY -= 1;
        if (keys['s']) moveY += 1;
        if (keys['a']) moveX -= 1;
        if (keys['d']) moveX += 1;
        p.sprint = keys['shift'];
        if (p.sprint) speed *= 1.4;

        // Weapon switch
        if (keys['1']) p.currentWeapon = 0;
        if (keys['2'] && p.weapons.length > 1) p.currentWeapon = 1;
        if (keys['3'] && p.weapons.length > 2) p.currentWeapon = 2;
        if (keys['4'] && p.weapons.length > 3) p.currentWeapon = 3;

        // Reload
        if (keys['r'] && !p.reloading) startReload(p);

        // Use medkit
        if (keys['f'] && p.medkitCooldown <= 0) {
            let medkit = p.weapons.find(w => w.weapon === 'medkit');
            if (medkit) {
                p.health = Math.min(p.maxHealth, p.health + 75);
                p.medkitCooldown = 5000;
                let idx = p.weapons.indexOf(medkit);
                if (idx > -1) p.weapons.splice(idx, 1);
                spawnParticles(p.x, p.y, '#0f0', 8);
            }
        }

        // Pickup
        if (keys['e']) tryPickup(p);

        // Aim
        let worldMouseX = mouse.x + camera.x;
        let worldMouseY = mouse.y + camera.y;
        p.angle = Math.atan2(worldMouseY - p.y, worldMouseY - p.y);
        p.angle = Math.atan2(worldMouseY - p.y, worldMouseX - p.x);

        // Shoot
        let now = performance.now();
        let weapon = p.weapons[p.currentWeapon];
        if (mouse.down && now - p.lastShot > weapon.fireRate && !p.reloading) {
            if (weapon.ammoType === null || weapon.currentAmmo > 0) {
                shoot(p, weapon);
                p.lastShot = now;
            }
        }
    } else if (p.id === 2) {
        if (keys['arrowup']) moveY -= 1;
        if (keys['arrowdown']) moveY += 1;
        if (keys['arrowleft']) moveX -= 1;
        if (keys['arrowright']) moveX += 1;
        p.sprint = keys['shift'];
        if (p.sprint) speed *= 1.4;

        if (keys['6'] && p.weapons.length > 1) p.currentWeapon = 1;
        if (keys['7'] && p.weapons.length > 2) p.currentWeapon = 2;
        if (keys['8'] && p.weapons.length > 3) p.currentWeapon = 3;

        if (keys['r'] && !p.reloading) startReload(p);

        if (keys['f'] && p.medkitCooldown <= 0) {
            let medkit = p.weapons.find(w => w.weapon === 'medkit');
            if (medkit) {
                p.health = Math.min(p.maxHealth, p.health + 75);
                p.medkitCooldown = 5000;
                let idx = p.weapons.indexOf(medkit);
                if (idx > -1) p.weapons.splice(idx, 1);
                spawnParticles(p.x, p.y, '#0f0', 8);
            }
        }

        if (keys['0'] || keys['numpad0']) tryPickup(p);

        let worldMouseX2 = mouse2.x + camera.x;
        let worldMouseY2 = mouse2.y + camera.y;
        p.angle = Math.atan2(worldMouseY2 - p.y, worldMouseX2 - p.x);

        let now = performance.now();
        let weapon = p.weapons[p.currentWeapon];
        if (mouse2.down && now - p.lastShot > weapon.fireRate && !p.reloading) {
            if (weapon.ammoType === null || weapon.currentAmmo > 0) {
                shoot(p, weapon);
                p.lastShot = now;
            }
        }
    }

    // Normalize movement
    if (moveX !== 0 || moveY !== 0) {
        let len = Math.hypot(moveX, moveY);
        moveX /= len;
        moveY /= len;
    }

    // Collision with obstacles
    let newX = p.x + moveX * speed * (dt / 16);
    let newY = p.y + moveY * speed * (dt / 16);

    let canMoveX = true, canMoveY = true;
    for (let o of obstacles) {
        if (o.isTree || o.isRock) continue;
        if (newX + p.radius > o.x && newX - p.radius < o.x + o.w &&
            p.y + p.radius > o.y && p.y - p.radius < o.y + o.h) {
            canMoveX = false;
        }
        if (p.x + p.radius > o.x && p.x - p.radius < o.x + o.w &&
            newY + p.radius > o.y && newY - p.radius < o.y + o.h) {
            canMoveY = false;
        }
    }

    if (canMoveX) p.x = newX;
    if (canMoveY) p.y = newY;

    // Map bounds
    p.x = Math.max(p.radius, Math.min(MAP_SIZE - p.radius, p.x));
    p.y = Math.max(p.radius, Math.min(MAP_SIZE - p.radius, p.y));

    // Reload
    if (p.reloading) {
        let weapon = p.weapons[p.currentWeapon];
        if (performance.now() - p.reloadStart >= weapon.reloadTime) {
            finishReload(p);
        }
    }

    if (p.medkitCooldown > 0) p.medkitCooldown -= dt;
    if (p.hitFlash > 0) p.hitFlash -= dt;
}

function updateBot(b, dt) {
    b.botTimer -= dt;
    b.medkitCooldown -= dt;

    // Find nearest target
    let nearestTarget = null;
    let nearestDist = Infinity;
    let allEntities = [...players, ...bots];
    for (let e of allEntities) {
        if (!e.alive || e.id === b.id) continue;
        let d = Math.hypot(e.x - b.x, e.y - b.y);
        if (d < nearestDist) { nearestDist = d; nearestTarget = e; }
    }

    // Check storm
    let distToStorm = Math.hypot(b.x - storm.x, b.y - storm.y);
    let inStorm = distToStorm > storm.radius;

    if (inStorm) {
        b.botState = 'flee';
        b.botDir = Math.atan2(storm.y - b.y, storm.x - b.x);
    } else if (nearestTarget && nearestDist < 500) {
        b.botState = 'attack';
        b.botTarget = nearestTarget;
    } else if (nearestTarget && nearestDist < 800) {
        b.botState = 'approach';
        b.botTarget = nearestTarget;
    } else {
        b.botState = 'wander';
    }

    // Use medkit if low health
    if (b.health < 40 && b.medkitCooldown <= 0) {
        let medkit = b.weapons.find(w => w.weapon === 'medkit');
        if (medkit) {
            b.health = Math.min(b.maxHealth, b.health + 75);
            b.medkitCooldown = 5000;
            let idx = b.weapons.indexOf(medkit);
            if (idx > -1) b.weapons.splice(idx, 1);
        }
    }

    let speed = b.speed * (b.botState === 'flee' ? 1.3 : 1);
    let moveX = 0, moveY = 0;

    if (b.botState === 'wander') {
        if (b.botTimer <= 0) {
            b.botDir = Math.random() * Math.PI * 2;
            b.botTimer = 2000 + Math.random() * 3000;
        }
        moveX = Math.cos(b.botDir);
        moveY = Math.sin(b.botDir);
    } else if (b.botState === 'approach' && b.botTarget) {
        let angle = Math.atan2(b.botTarget.y - b.y, b.botTarget.x - b.x);
        b.angle = angle;
        if (nearestDist > 200) {
            moveX = Math.cos(angle);
            moveY = Math.sin(angle);
        }
    } else if (b.botState === 'attack' && b.botTarget) {
        let angle = Math.atan2(b.botTarget.y - b.y, b.botTarget.x - b.x);
        b.angle = angle;
        // Strafe
        let strafeAngle = angle + (Math.sin(gameTime / 500 + b.id) > 0 ? Math.PI/2 : -Math.PI/2);
        moveX = Math.cos(strafeAngle) * 0.5;
        moveY = Math.sin(strafeAngle) * 0.5;

        // Shoot
        b.botShootTimer -= dt;
        if (b.botShootTimer <= 0 && nearestDist < 400) {
            let weapon = b.weapons[b.currentWeapon];
            if (weapon.ammoType === null || weapon.currentAmmo > 0) {
                shoot(b, weapon);
                b.botShootTimer = weapon.fireRate * (1.5 + Math.random());
            }
        }
    } else if (b.botState === 'flee') {
        moveX = Math.cos(b.botDir);
        moveY = Math.sin(b.botDir);
    }

    // Collision
    let newX = b.x + moveX * speed * (dt / 16);
    let newY = b.y + moveY * speed * (dt / 16);
    let canMoveX = true, canMoveY = true;
    for (let o of obstacles) {
        if (o.isTree || o.isRock) continue;
        if (newX + b.radius > o.x && newX - b.radius < o.x + o.w &&
            b.y + b.radius > o.y && b.y - b.radius < o.y + o.h) canMoveX = false;
        if (b.x + b.radius > o.x && b.x - b.radius < o.x + o.w &&
            newY + b.radius > o.y && newY - b.radius < o.y + o.h) canMoveY = false;
    }
    if (canMoveX) b.x = newX;
    if (canMoveY) b.y = newY;
    b.x = Math.max(b.radius, Math.min(MAP_SIZE - b.radius, b.x));
    b.y = Math.max(b.radius, Math.min(MAP_SIZE - b.radius, b.y));

    // Pick up loot
    for (let i = loot.length - 1; i >= 0; i--) {
        let l = loot[i];
        if (Math.hypot(l.x - b.x, l.y - b.y) < l.pickupRadius + b.radius) {
            if (l.type === 'weapon') {
                if (b.weapons.length < 4) {
                    let w = { ...WEAPONS[l.weapon], currentAmmo: WEAPONS[l.weapon].maxAmmo, inInventory: true };
                    b.weapons.push(w);
                    b.currentWeapon = b.weapons.length - 1;
                } else {
                    // Swap with fists
                    let fistIdx = b.weapons.findIndex(w => w.weapon === 'fists');
                    if (fistIdx > -1) {
                        b.weapons[fistIdx] = { ...WEAPONS[l.weapon], currentAmmo: WEAPONS[l.weapon].maxAmmo, inInventory: true };
                    }
                }
                loot.splice(i, 1);
            } else if (l.type.startsWith('ammo')) {
                let ammoType = l.type.replace('ammo', '').toLowerCase();
                let weapon = b.weapons.find(w => w.ammoType === ammoType);
                if (weapon) {
                    weapon.currentAmmo = Math.min(weapon.maxAmmo * 2, weapon.currentAmmo + l.ammo);
                }
                loot.splice(i, 1);
            } else if (l.type === 'health') {
                b.health = Math.min(b.maxHealth, b.health + l.amount);
                loot.splice(i, 1);
            } else if (l.type === 'armor') {
                b.armor = Math.min(b.maxArmor, b.armor + l.amount);
                loot.splice(i, 1);
            } else if (l.type === 'medkit') {
                b.weapons.push({ ...WEAPONS.medkit || { name: 'Medkit', weapon: 'medkit', color: '#fff' }, inInventory: true });
                loot.splice(i, 1);
            }
        }
    }
}

function shoot(p, weapon) {
    let pellets = weapon.pellets || 1;
    for (let i = 0; i < pellets; i++) {
        let spread = (Math.random() - 0.5) * weapon.spread * 2;
        let angle = p.angle + spread;
        bullets.push({
            x: p.x + Math.cos(p.angle) * 20,
            y: p.y + Math.sin(p.angle) * 20,
            vx: Math.cos(angle) * weapon.bulletSpeed,
            vy: Math.sin(angle) * weapon.bulletSpeed,
            damage: weapon.damage,
            ownerId: p.id,
            owner: p,
            life: 1000,
            range: weapon.range,
            dist: 0,
            color: weapon.color
        });
    }
    if (weapon.ammoType !== null) {
        weapon.currentAmmo--;
    }
    // Muzzle flash
    spawnParticles(p.x + Math.cos(p.angle) * 22, p.y + Math.sin(p.angle) * 22, '#ff0', 3);
}

function startReload(p) {
    let weapon = p.weapons[p.currentWeapon];
    if (weapon.ammoType === null || weapon.currentAmmo >= weapon.maxAmmo) return;
    p.reloading = true;
    p.reloadStart = performance.now();
}

function finishReload(p) {
    let weapon = p.weapons[p.currentWeapon];
    if (weapon.ammoType !== null) {
        weapon.currentAmmo = weapon.maxAmmo;
    }
    p.reloading = false;
}

function tryPickup(p) {
    for (let i = loot.length - 1; i >= 0; i--) {
        let l = loot[i];
        if (Math.hypot(l.x - p.x, l.y - p.y) < l.pickupRadius + p.radius + 10) {
            if (l.type === 'weapon') {
                if (p.weapons.length < 4) {
                    let w = { ...WEAPONS[l.weapon], currentAmmo: WEAPONS[l.weapon].maxAmmo, inInventory: true };
                    p.weapons.push(w);
                    p.currentWeapon = p.weapons.length - 1;
                } else {
                    let idx = p.weapons.findIndex(w => w.weapon === 'fists');
                    if (idx > -1) {
                        p.weapons[idx] = { ...WEAPONS[l.weapon], currentAmmo: WEAPONS[l.weapon].maxAmmo, inInventory: true };
                    }
                }
                loot.splice(i, 1);
            } else if (l.type.startsWith('ammo')) {
                let ammoType = l.type.replace('ammo', '').toLowerCase();
                let weapon = p.weapons.find(w => w.ammoType === ammoType);
                if (weapon) {
                    weapon.currentAmmo = Math.min(weapon.maxAmmo * 2, weapon.currentAmmo + l.ammo);
                }
                loot.splice(i, 1);
            } else if (l.type === 'health' && p.health < p.maxHealth) {
                p.health = Math.min(p.maxHealth, p.health + l.amount);
                loot.splice(i, 1);
            } else if (l.type === 'armor' && p.armor < p.maxArmor) {
                p.armor = Math.min(p.maxArmor, p.armor + l.amount);
                loot.splice(i, 1);
            } else if (l.type === 'medkit') {
                p.weapons.push({ name: 'Medkit', weapon: 'medkit', color: '#fff', inInventory: true });
                loot.splice(i, 1);
            }
            break;
        }
    }
}

function spawnParticles(x, y, color, count) {
    for (let i = 0; i < count; i++) {
        let angle = Math.random() * Math.PI * 2;
        let speed = 1 + Math.random() * 4;
        particles.push({
            x, y,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            life: 300 + Math.random() * 500,
            color,
            size: 2 + Math.random() * 3
        });
    }
}

function render() {
    // Camera
    let focusX = 0, focusY = 0, focusCount = 0;
    for (let p of players) {
        if (p.alive) { focusX += p.x; focusY += p.y; focusCount++; }
    }
    if (focusCount > 0) {
        focusX /= focusCount;
        focusY /= focusCount;
    }
    camera.x = focusX - canvas.width / 2;
    camera.y = focusY - canvas.height / 2;
    camera.x = Math.max(0, Math.min(MAP_SIZE - canvas.width, camera.x));
    camera.y = Math.max(0, Math.min(MAP_SIZE - canvas.height, camera.y));

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    // Ground
    ctx.fillStyle = '#3a5a2a';
    ctx.fillRect(0, 0, MAP_SIZE, MAP_SIZE);

    // Grid
    ctx.strokeStyle = '#3f6030';
    ctx.lineWidth = 0.5;
    let startTileX = Math.floor(camera.x / TILE_SIZE) * TILE_SIZE;
    let startTileY = Math.floor(camera.y / TILE_SIZE) * TILE_SIZE;
    for (let x = startTileX; x < camera.x + canvas.width + TILE_SIZE; x += TILE_SIZE) {
        ctx.beginPath(); ctx.moveTo(x, camera.y); ctx.lineTo(x, camera.y + canvas.height); ctx.stroke();
    }
    for (let y = startTileY; y < camera.y + canvas.height + TILE_SIZE; y += TILE_SIZE) {
        ctx.beginPath(); ctx.moveTo(camera.x, y); ctx.lineTo(camera.x + canvas.width, y); ctx.stroke();
    }

    // Map border
    ctx.strokeStyle = '#ff0000';
    ctx.lineWidth = 4;
    ctx.strokeRect(0, 0, MAP_SIZE, MAP_SIZE);

    // Buildings
    for (let b of buildings) {
        ctx.fillStyle = b.color;
        ctx.fillRect(b.x, b.y, b.w, b.h);
        ctx.strokeStyle = '#555';
        ctx.lineWidth = 2;
        ctx.strokeRect(b.x, b.y, b.w, b.h);
        // Roof detail
        ctx.fillStyle = 'rgba(0,0,0,0.2)';
        ctx.fillRect(b.x + 5, b.y + 5, b.w - 10, b.h - 10);
    }

    // Loot
    let time = performance.now();
    for (let l of loot) {
        let bob = Math.sin(time / 300 + l.bobOffset) * 3;
        ctx.save();
        ctx.translate(l.x, l.y + bob);

        // Glow
        ctx.shadowColor = l.color;
        ctx.shadowBlur = 10;

        if (l.type === 'weapon') {
            ctx.fillStyle = l.color;
            ctx.fillRect(-10, -4, 20, 8);
            ctx.fillStyle = '#fff';
            ctx.font = '8px Arial';
            ctx.textAlign = 'center';
            ctx.fillText(WEAPONS[l.weapon]?.name || 'Weapon', 0, -10);
        } else if (l.type.startsWith('ammo')) {
            ctx.fillStyle = l.color;
            ctx.fillRect(-6, -4, 12, 8);
        } else if (l.type === 'health') {
            ctx.fillStyle = '#f44';
            ctx.fillRect(-8, -3, 16, 6);
            ctx.fillStyle = '#fff';
            ctx.fillRect(-2, -6, 4, 12);
            ctx.fillRect(-6, -2, 12, 4);
        } else if (l.type === 'armor') {
            ctx.fillStyle = '#44f';
            ctx.beginPath();
            ctx.arc(0, 0, 8, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#fff';
            ctx.font = '10px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('A', 0, 4);
        } else if (l.type === 'medkit') {
            ctx.fillStyle = '#fff';
            ctx.fillRect(-8, -6, 16, 12);
            ctx.fillStyle = '#f00';
            ctx.fillRect(-2, -5, 4, 10);
            ctx.fillRect(-5, -2, 10, 4);
        }

        ctx.restore();
    }

    // Trees
    for (let t of trees) {
        ctx.fillStyle = '#2a4a1a';
        ctx.beginPath();
        ctx.arc(t.x, t.y, t.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#3a6a2a';
        ctx.beginPath();
        ctx.arc(t.x - 3, t.y - 3, t.r * 0.7, 0, Math.PI * 2);
        ctx.fill();
    }

    // Rocks
    for (let r of rocks) {
        ctx.fillStyle = '#666';
        ctx.beginPath();
        ctx.arc(r.x, r.y, r.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#777';
        ctx.beginPath();
        ctx.arc(r.x - 3, r.y - 3, r.r * 0.6, 0, Math.PI * 2);
        ctx.fill();
    }

    // Bullets
    for (let b of bullets) {
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 3, 0, Math.PI * 2);
        ctx.fill();
        // Trail
        ctx.strokeStyle = b.color + '66';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(b.x, b.y);
        ctx.lineTo(b.x - b.vx * 3, b.y - b.vy * 3);
        ctx.stroke();
    }

    // Particles
    for (let p of particles) {
        ctx.globalAlpha = p.life / 800;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.globalAlpha = 1;

    // All entities (bots + players)
    let allEntities = [...bots, ...players];
    for (let e of allEntities) {
        if (!e.alive) continue;

        // Shadow
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.beginPath();
        ctx.ellipse(e.x + 3, e.y + 5, e.radius, e.radius * 0.6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Body
        ctx.fillStyle = e.hitFlash > 0 ? '#fff' : e.color;
        ctx.beginPath();
        ctx.arc(e.x, e.y, e.radius, 0, Math.PI * 2);
        ctx.fill();

        // Outline
        ctx.strokeStyle = e.team === 'team' ? '#fff' : '#333';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Weapon
        let weapon = e.weapons[e.currentWeapon];
        if (weapon) {
            ctx.strokeStyle = weapon.color;
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(e.x + Math.cos(e.angle) * 8, e.y + Math.sin(e.angle) * 8);
            ctx.lineTo(e.x + Math.cos(e.angle) * 28, e.y + Math.sin(e.angle) * 28);
            ctx.stroke();
        }

        // Health bar
        let barW = 36, barH = 5;
        let barX = e.x - barW/2, barY = e.y - e.radius - 14;

        // Armor bar
        if (e.armor > 0) {
            ctx.fillStyle = '#333';
            ctx.fillRect(barX, barY - 8, barW, barH);
            ctx.fillStyle = '#44f';
            ctx.fillRect(barX, barY - 8, barW * (e.armor / e.maxArmor), barH);
        }

        // Health bar
        ctx.fillStyle = '#333';
        ctx.fillRect(barX, barY, barW, barH);
        let healthPct = e.health / e.maxHealth;
        ctx.fillStyle = healthPct > 0.5 ? '#4f4' : healthPct > 0.25 ? '#ff4' : '#f44';
        ctx.fillRect(barX, barY, barW * healthPct, barH);

        // Reload bar
        if (e.reloading) {
            let weapon = e.weapons[e.currentWeapon];
            let progress = (performance.now() - e.reloadStart) / weapon.reloadTime;
            ctx.fillStyle = '#333';
            ctx.fillRect(barX, barY + 6, barW, 3);
            ctx.fillStyle = '#ff0';
            ctx.fillRect(barX, barY + 6, barW * progress, 3);
        }

        // Name
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 11px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(e.name, e.x, barY - 12);

        // Team indicator for players
        if (e.team === 'team') {
            ctx.fillStyle = e.color;
            ctx.beginPath();
            ctx.arc(e.x, e.y - e.radius - 4, 4, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    // Storm
    ctx.save();
    ctx.beginPath();
    ctx.rect(camera.x - 10, camera.y - 10, canvas.width + 20, canvas.height + 20);
    ctx.arc(storm.x, storm.y, storm.radius, 0, Math.PI * 2, true);
    ctx.fillStyle = 'rgba(0, 100, 255, 0.15)';
    ctx.fill();

    // Storm border
    ctx.beginPath();
    ctx.arc(storm.x, storm.y, storm.radius, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(0, 150, 255, 0.6)';
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.restore();

    ctx.restore();

    // HUD
    renderHUD();
}

function renderHUD() {
    let p1 = players[0];
    let p2 = players[1];

    // Bottom HUD - Player 1
    if (p1.alive) {
        renderPlayerHUD(p1, 20, canvas.height - 120, 1);
    }

    // Bottom HUD - Player 2
    if (p2.alive) {
        renderPlayerHUD(p2, canvas.width / 2 + 20, canvas.height - 120, 2);
    }

    // Kill feed
    ctx.textAlign = 'right';
    for (let i = 0; i < killFeed.length; i++) {
        let kf = killFeed[i];
        ctx.globalAlpha = Math.min(1, kf.time / 1000);
        ctx.fillStyle = kf.color;
        ctx.font = 'bold 14px Arial';
        ctx.fillText(kf.text, canvas.width - 20, 60 + i * 22);
    }
    ctx.globalAlpha = 1;

    // Minimap
    let mmSize = 180;
    let mmX = canvas.width - mmSize - 15;
    let mmY = 15;
    let mmScale = mmSize / MAP_SIZE;

    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(mmX - 2, mmY - 2, mmSize + 4, mmSize + 4);
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 1;
    ctx.strokeRect(mmX - 2, mmY - 2, mmSize + 4, mmSize + 4);

    // Minimap background
    ctx.fillStyle = '#2a4a1a';
    ctx.fillRect(mmX, mmY, mmSize, mmSize);

    // Storm on minimap
    ctx.beginPath();
    ctx.arc(mmX + storm.x * mmScale, mmY + storm.y * mmScale, storm.radius * mmScale, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(0, 150, 255, 0.8)';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Buildings on minimap
    ctx.fillStyle = '#555';
    for (let b of buildings) {
        ctx.fillRect(mmX + b.x * mmScale, mmY + b.y * mmScale, Math.max(2, b.w * mmScale), Math.max(2, b.h * mmScale));
    }

    // Players on minimap
    for (let p of players) {
        if (!p.alive) continue;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(mmX + p.x * mmScale, mmY + p.y * mmScale, 3, 0, Math.PI * 2);
        ctx.fill();
    }

    // Bots on minimap
    for (let b of bots) {
        if (!b.alive) continue;
        ctx.fillStyle = '#f44';
        ctx.beginPath();
        ctx.arc(mmX + b.x * mmScale, mmY + b.y * mmScale, 2, 0, Math.PI * 2);
        ctx.fill();
    }

    // Alive count
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 12px Arial';
    ctx.textAlign = 'center';
    let alivePlayers = players.filter(p => p.alive).length;
    let aliveBots = bots.filter(b => b.alive).length;
    ctx.fillText(`Alive: ${alivePlayers + aliveBots}`, mmX + mmSize/2, mmY + mmSize + 15);

    // Top center - Timer
    let minutes = Math.floor(gameTime / 60000);
    let seconds = Math.floor((gameTime % 60000) / 1000);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 18px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(`${minutes}:${seconds.toString().padStart(2, '0')}`, canvas.width / 2, 25);

    // Storm warning
    if (Math.hypot((p1.alive ? p1.x : 0) - storm.x, (p1.alive ? p1.y : 0) - storm.y) > storm.radius) {
        ctx.fillStyle = '#f44';
        ctx.font = 'bold 16px Arial';
        ctx.fillText('⚠ STORM WARNING - Get to the safe zone!', canvas.width / 2, 50);
    }

    // Weapon slots
    for (let p of players) {
        if (!p.alive) continue;
        let slotY = p.id === 1 ? canvas.height - 130 : canvas.height - 130;
        let slotX = p.id === 1 ? 20 : canvas.width / 2 + 20;
        for (let i = 0; i < p.weapons.length; i++) {
            let w = p.weapons[i];
            let sx = slotX + i * 70;
            let sy = canvas.height - 60;
