            this.state = 'chase';
        } else if (dist > this.chaseRange * 1.5) {
            this.state = 'patrol';
        }

        // Re-compute A* path periodically
        this.pathTimer++;
        if (this.pathTimer >= this.pathUpdateRate) {
            this.pathTimer = 0;
            if (this.state === 'chase') {
                this.path = this.aStar(
                    Math.floor(this.x / TILE_SIZE),
                    Math.floor(this.y / TILE_SIZE),
                    player.gridX,
                    player.gridY
                );
            }
        }

        // Move based on current state
        if (this.state === 'chase' && this.path.length > 1) {
            this.moveAlongPath(player);
        } else {
            this.patrolMove();
        }

        // Update grid position
        this.gridX = Math.floor(this.x / TILE_SIZE);
        this.gridY = Math.floor(this.y / TILE_SIZE);
    }

    // --- A* PATHFINDING ALGORITHM ---
    // Returns an array of {x, y} grid coordinates from start to goal
    aStar(startX, startY, goalX, goalY) {
        // Priority queue (simple array, sorted)
        let openSet = [{
            x: startX, y: startY,
            g: 0, h: 0, f: 0,
            parent: null
        }];
        let closedSet = new Set();
        let cameFrom = {};
        let gScore = {};

        let key = (x, y) => `${x},${y}`;
        gScore[key(startX, startY)] = 0;

        while (openSet.length > 0) {
            // Find node with lowest f score
            let lowestIdx = 0;
            for (let i = 1; i < openSet.length; i++) {
                if (openSet[i].f < openSet[lowestIdx].f) lowestIdx = i;
            }
            let current = openSet[lowestIdx];

            // Goal reached?
            if (current.x === goalX && current.y === goalY) {
                // Reconstruct path
                let path = [];
                let node = current;
                while (node) {
                    path.unshift({ x: node.x, y: node.y });
                    node = node.parent;
                }
                return path;
            }

            // Move current from open to closed
            openSet.splice(lowestIdx, 1);
            closedSet.add(key(current.x, current.y));

            // Check 4 neighbors (up, down, left, right)
            let neighbors = [
                { x: current.x, y: current.y - 1 },
                { x: current.x, y: current.y + 1 },
                { x: current.x - 1, y: current.y },
                { x: current.x + 1, y: current.y },
            ];

            for (let neighbor of neighbors) {
                let nk = key(neighbor.x, neighbor.y);

                // Skip if out of bounds, wall, or already evaluated
                if (neighbor.x < 0 || neighbor.x >= COLS ||
                    neighbor.y < 0 || neighbor.y >= ROWS) continue;
                if (currentMap[neighbor.y][neighbor.x] === TILE_WALL) continue;
                if (closedSet.has(nk)) continue;

                // Manhattan distance heuristic
                let h = Math.abs(neighbor.x - goalX) + Math.abs(neighbor.y - goalY);
                let g = current.g + 1; // Cost to move to neighbor

                // Check if we already found a better path to this neighbor
                if (gScore[nk] !== undefined && g >= gScore[nk]) continue;

                gScore[nk] = g;
                openSet.push({
                    x: neighbor.x, y: neighbor.y,
                    g: g, h: h, f: g + h,
                    parent: current
                });
            }
        }

        // No path found
        return [];
    }

    // Move along the pre-computed A* path
    moveAlongPath(player) {
        if (this.path.length < 2) return;

        let target = this.path[1];
        let targetX = target.x * TILE_SIZE + TILE_SIZE / 2;
        let targetY = target.y * TILE_SIZE + TILE_SIZE / 2;

        let dx = targetX - this.x;
        let dy = targetY - this.y;
        let dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < this.speed) {
            // Reached the next tile, advance path
            this.x = targetX;
            this.y = targetY;
            this.path.shift();
        } else {
            // Move toward target
            this.x += (dx / dist) * this.speed;
            this.y += (dy / dist) * this.speed;
        }
    }

    // Patrol movement between fixed waypoints
    patrolMove() {
        let target = this.patrolPoints[this.patrolIndex];
        let targetX = target.x * TILE_SIZE + TILE_SIZE / 2;
        let targetY = target.y * TILE_SIZE + TILE_SIZE / 2;

        let dx = targetX - this.x;
        let dy = targetY - this.y;
        let dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < this.speed) {
            // Reached patrol point, move to next
            this.x = targetX;
            this.y = targetY;
            this.patrolIndex = (this.patrolIndex + 1) % this.patrolPoints.length;
        } else {
            this.x += (dx / dist) * this.speed * 0.7;
            this.y += (dy / dist) * this.speed * 0.7;
        }
    }

    draw() {
        // Draw A* path visualization (faint line)
        if (this.path.length > 1 && this.state === 'chase') {
            ctx.beginPath();
            ctx.moveTo(this.x, this.y);
            for (let i = 1; i < this.path.length; i++) {
                ctx.lineTo(
                    this.path[i].x * TILE_SIZE + TILE_SIZE / 2,
                    this.path[i].y * TILE_SIZE + TILE_SIZE / 2
                );
            }
            ctx.strokeStyle = this.color.replace(')', ', 0.25)').replace('rgb', 'rgba');
            ctx.lineWidth = 2;
            ctx.setLineDash([4, 4]);
            ctx.stroke();
            ctx.setLineDash([]);

            // Draw path nodes
            for (let i = 1; i < this.path.length; i++) {
                let px = this.path[i].x * TILE_SIZE + TILE_SIZE / 2;
                let py = this.path[i].y * TILE_SIZE + TILE_SIZE / 2;
                ctx.beginPath();
                ctx.arc(px, py, 2, 0, Math.PI * 2);
                ctx.fillStyle = this.color.replace(')', ', 0.3)').replace('rgb', 'rgba');
                ctx.fill();
            }
        }

        // Draw chase range indicator (subtle)
        if (this.state === 'chase') {
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.chaseRange, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 50, 50, 0.15)';
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        // Draw enemy body
        let pulse = Math.sin(this.animPhase) * 2;

        // Glow
        let gradient = ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.radius + 6 + pulse);
        gradient.addColorStop(0, this.color.replace(')', ', 0.3)').replace('rgb', 'rgba'));
        gradient.addColorStop(1, this.color.replace(')', ', 0)'));
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius + 6 + pulse, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();

        // Body
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius + pulse * 0.5, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // Eyes
        let eyeAngle = Math.atan2(player.y - this.y, player.x - this.x);
        let eyeOff = 3;
        for (let side = -1; side <= 1; side += 2) {
            let ex = this.x + Math.cos(eyeAngle) * eyeOff + Math.cos(eyeAngle + Math.PI/2) * side * 3;
            let ey = this.y + Math.sin(eyeAngle) * eyeOff + Math.sin(eyeAngle + Math.PI/2) * side * 3;
            ctx.beginPath();
            ctx.arc(ex, ey, 2.5, 0, Math.PI * 2);
            ctx.fillStyle = '#fff';
            ctx.fill();
            ctx.beginPath();
            ctx.arc(ex + Math.cos(eyeAngle) * 1, ey + Math.sin(eyeAngle) * 1, 1.2, 0, Math.PI * 2);
            ctx.fillStyle = '#111';
            ctx.fill();
        }

        // State label
        ctx.font = 'bold 9px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = this.state === 'chase' ? '#ff4444' : '#888';
        ctx.fillText(this.state === 'chase' ? '!' : '?', this.x, this.y - this.radius - 6);
    }
}

// ============================================================
//  GEM CLASS
//  Collectible items on the map
// ============================================================
class Gem {
    constructor(gridX, gridY) {
        this.gridX = gridX;
        this.gridY = gridY;
        this.x = gridX * TILE_SIZE + TILE_SIZE / 2;
        this.y = gridY * TILE_SIZE + TILE_SIZE / 2;
        this.radius = 8;
        this.collected = false;
        this.animPhase = Math.random() * Math.PI * 2;
    }

    update() {
        this.animPhase += 0.08;
    }

    draw() {
        if (this.collected) return;

        let bob = Math.sin(this.animPhase) * 3;
        let y = this.y + bob;

        // Glow
        let gradient = ctx.createRadialGradient(this.x, y, 0, this.x, y, this.radius + 8);
        gradient.addColorStop(0, 'rgba(255, 215, 0, 0.4)');
        gradient.addColorStop(1, 'rgba(255, 215, 0, 0)');
        ctx.beginPath();
        ctx.arc(this.x, y, this.radius + 8, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();

        // Diamond shape
        ctx.save();
        ctx.translate(this.x, y);
        ctx.rotate(this.animPhase * 0.3);
        ctx.beginPath();
        ctx.moveTo(0, -this.radius);
        ctx.lineTo(this.radius * 0.7, 0);
        ctx.lineTo(0, this.radius);
        ctx.lineTo(-this.radius * 0.7, 0);
        ctx.closePath();
        ctx.fillStyle = '#ffd700';
        ctx.fill();
        ctx.strokeStyle = '#ffaa00';
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // Highlight
        ctx.beginPath();
        ctx.moveTo(0, -this.radius * 0.5);
        ctx.lineTo(this.radius * 0.3, 0);
        ctx.lineTo(0, 0);
        ctx.closePath();
        ctx.fillStyle = 'rgba(255,255,255,0.5)';
        ctx.fill();
        ctx.restore();
    }
}

// ============================================================
//  PARTICLE SYSTEM
//  Visual effects for collection and hits
// ============================================================
class Particle {
    constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.color = color;
        this.vx = (Math.random() - 0.5) * 4;
        this.vy = (Math.random() - 0.5) * 4;
        this.life = 1;
        this.decay = 0.02 + Math.random() * 0.03;
        this.size = 2 + Math.random() * 3;
    }

    update() {
        this.x += this.vx;
        this.y += this.vy;
        this.life -= this.decay;
        this.vx *= 0.98;
        this.vy *= 0.98;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size * this.life, 0, Math.PI * 2);
        ctx.fillStyle = this.color.replace(')', `, ${this.life})`).replace('rgb', 'rgba');
        ctx.fill();
    }
}

function spawnParticles(x, y, color, count) {
    for (let i = 0; i < count; i++) {
        particles.push(new Particle(x, y, color));
    }
}

// ============================================================
//  GAME INITIALIZATION
// ============================================================
function initLevel(levelNum) {
    let mapIdx = (levelNum - 1) % maps.length;
    // Deep copy the map
    currentMap = maps[mapIdx].map(row => [...row]);

    // Find spawn point
    playerSpawn = { x: 1, y: 1 };
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            if (currentMap[r][c] === TILE_SPAWN) {
                playerSpawn = { x: c, y: r };
            }
        }
    }

    // Create player
    player = new Player(playerSpawn.x, playerSpawn.y);

    // Create enemies with patrol routes
    enemies = [];
    let enemyConfigs = [
        { x: 18, y: 1, patrol: [{x:18,y:1},{x:18,y:13},{x:10,y:13},{x:10,y:1}], color: 'rgb(255, 80, 80)', name: 'Chaser' },
        { x: 1, y: 13, patrol: [{x:1,y:13},{x:5,y:13},{x:5,y:7},{x:1,y:7}], color: 'rgb(200, 60, 255)', name: 'Patrol' },
        { x: 18, y: 7, patrol: [{x:18,y:7},{x:14,y:7},{x:14,y:3},{x:18,y:3}], color: 'rgb(255, 160, 40)', name: 'Stalker' },
    ];
    // Add more enemies for higher levels
    if (levelNum >= 2) {
        enemyConfigs.push({ x: 9, y: 1, patrol: [{x:9,y:1},{x:9,y:5},{x:15,y:5},{x:15,y:1}], color: 'rgb(80, 255, 80)', name: 'Hunter' });
    }
    if (levelNum >= 3) {
        enemyConfigs.push({ x: 1, y: 7, patrol: [{x:1,y:7},{x:1,y:3},{x:5,y:3},{x:5,y:7}], color: 'rgb(255, 100, 200)', name: 'Shadow' });
        enemyConfigs.push({ x: 18, y: 13, patrol: [{x:18,y:13},{x:14,y:13},{x:14,y:9},{x:18,y:9}], color: 'rgb(100, 200, 255)', name: 'Ghost' });
    }

    enemyConfigs.forEach(cfg => {
        enemies.push(new Enemy(cfg.x, cfg.y, cfg.patrol, cfg.color, cfg.name));
    });

    // Place gems in empty spots
    gems = [];
    let emptySpots = [];
    for (let r = 1; r < ROWS - 1; r++) {
        for (let c = 1; c < COLS - 1; c++) {
            if (currentMap[r][c] === TILE_EMPTY) {
                // Avoid placing too close to enemies
                let tooClose = false;
                for (let e of enemyConfigs) {
                    if (Math.abs(c - e.x) < 3 && Math.abs(r - e.y) < 3) {
                        tooClose = true;
                        break;
                    }
                }
                if (!tooClose) emptySpots.push({ x: c, y: r });
            }
        }
    }

    // Shuffle and pick gem locations
    for (let i = emptySpots.length - 1; i > 0; i--) {
        let j = Math.floor(Math.random() * (i + 1));
        [emptySpots[i], emptySpots[j]] = [emptySpots[j], emptySpots[i]];
    }

    let numGems = 3 + levelNum; // More gems per level
    totalGems = Math.min(numGems, emptySpots.length);
    gemsCollected = 0;

    for (let i = 0; i < totalGems; i++) {
        gems.push(new Gem(emptySpots[i].x, emptySpots[i].y));
    }

    // Reset state
    particles = [];
    visiblePath = [];
    gameOver = false;
    gameWon = false;
    gameRunning = true;
    document.getElementById('overlay').classList.remove('show');
    updateHUD();
}

// ============================================================
//  HUD UPDATE
// ============================================================
function updateHUD() {
    document.getElementById('scoreDisplay').textContent = score;
    document.getElementById('levelDisplay').textContent = level;
    document.getElementById('gemDisplay').textContent = `${gemsCollected}/${totalGems}`;
    document.getElementById('livesDisplay').textContent = '❤️'.repeat(Math.max(0, lives));
}

// ============================================================
//  DRAW MAP
// ============================================================
function drawMap() {
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            let x = c * TILE_SIZE;
            let y = r * TILE_SIZE;

            if (currentMap[r][c] === TILE_WALL) {
                // Wall with 3D effect
                let gradient = ctx.createLinearGradient(x, y, x, y + TILE_SIZE);
                gradient.addColorStop(0, '#4a4a6a');
                gradient.addColorStop(1, '#2a2a4a');
                ctx.fillStyle = gradient;
                ctx.fillRect(x, y, TILE_SIZE, TILE_SIZE);

                // Wall highlight
                ctx.fillStyle = 'rgba(255,255,255,0.08)';
                ctx.fillRect(x, y, TILE_SIZE, 2);
                ctx.fillRect(x, y, 2, TILE_SIZE);

                // Wall shadow
                ctx.fillStyle = 'rgba(0,0,0,0.3)';
                ctx.fillRect(x, y + TILE_SIZE - 2, TILE_SIZE, 2);
                ctx.fillRect(x + TILE_SIZE - 2, y, 2, TILE_SIZE);
            } else {
                // Floor
                ctx.fillStyle = (r + c) % 2 === 0 ? '#1a1a2e' : '#16162a';
                ctx.fillRect(x, y, TILE_SIZE, TILE_SIZE);

                // Subtle grid lines
                ctx.strokeStyle = 'rgba(255,255,255,0.03)';
                ctx.lineWidth = 0.5;
                ctx.strokeRect(x, y, TILE_SIZE, TILE_SIZE);
            }
        }
    }
}

// ============================================================
//  COLLISION DETECTION
// ============================================================
function checkEntityCollisions() {
    // Player vs Gems
    for (let gem of gems) {
        if (gem.collected) continue;
        let dx = player.x - gem.x;
        let dy = player.y - gem.y;
        let dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < player.radius + gem.radius) {
            gem.collected = true;
            gemsCollected++;
            score += 100;
            spawnParticles(gem.x, gem.y, 'rgb(255, 215, 0)', 15);
            updateHUD();

            // Check win condition
            if (gemsCollected >= totalGems) {
                winLevel();
            }
        }
    }

    // Player vs Enemies
    if (player.invincible <= 0) {
        for (let enemy of enemies) {
            let dx = player.x - enemy.x;
            let dy = player.y - enemy.y;
            let dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < player.radius + enemy.radius) {
                lives--;
                player.invincible = 90; // 1.5 seconds at 60fps
                player.hitCooldown = 90;
                spawnParticles(player.x, player.y, 'rgb(255, 50, 50)', 20);
                updateHUD();

                if (lives <= 0) {
                    endGame(false);
                }
            }
        }
    }
}

// ============================================================
//  GAME END / WIN
// ============================================================
function endGame(won) {
    gameRunning = false;
    gameOver = !won;
    gameWon = won;

    let overlay = document.getElementById('overlay');
    let title = document.getElementById('overlayTitle');
    let msg = document.getElementById('overlayMsg');

    if (won) {
        title.textContent = '🎉 LEVEL COMPLETE!';
        title.className = 'win';
        msg.textContent = `Score: ${score} | Gems: ${gemsCollected}/${totalGems}`;
    } else {
        title.textContent = '💀 GAME OVER';
        title.className = 'lose';
        msg.textContent = `You reached Level ${level} with Score: ${score}`;
    }

    overlay.classList.add('show');
}

function winLevel() {
    score += 500; // Bonus for completing level
    level++;
    updateHUD();

    // Small delay then next level
    setTimeout(() => {
        initLevel(level);
    }, 1000);
}

function restartGame() {
    score = 0;
    lives = 3;
    level = 1;
    initLevel(level);
}

// ============================================================
//  MAIN GAME LOOP
// ============================================================
let player;

function gameLoop(timestamp) {
    requestAnimationFrame(gameLoop);

    if (!gameRunning) {
        // Still draw the scene frozen
        drawMap();
        gems.forEach(g => g.draw());
        enemies.forEach(e => e.draw());
        player.draw();
        return;
    }

    animFrame++;

    // Update
    player.update();
    enemies.forEach(e => e.update(player));
    gems.forEach(g => g.update());
    particles.forEach(p => p.update());
    particles = particles.filter(p => p.life > 0);

    checkEntityCollisions();

    // --- RENDER ---
    ctx.clearRect(0, 0, CANVAS_W, CANVAS_H);

    // Draw map
    drawMap();

    // Draw gems
    gems.forEach(g => g.draw());

    // Draw particles
    particles.forEach(p => p.draw());

    // Draw enemies
    enemies.forEach(e => e.draw());

    // Draw player
    player.draw();

    // Draw minimap
    drawMinimap();
}

// ============================================================
//  MINIMAP
// ============================================================
function drawMinimap() {
    let mapW = 120;
    let mapH = 90;
    let mapX = CANVAS_W - mapW - 10;
    let mapY = 10;
    let cellW = mapW / COLS;
    let cellH = mapH / ROWS;

    // Background
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.strokeStyle = 'rgba(100,100,200,0.4)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(mapX - 2, mapY - 2, mapW + 4, mapH + 4, 4);
    ctx.fill();
    ctx.stroke();

    // Draw map cells
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            if (currentMap[r][c] === TILE_WALL) {
                ctx.fillStyle = '#4a4a6a';
                ctx.fillRect(mapX + c * cellW, mapY + r * cellH, cellW + 0.5, cellH + 0.5);
            }
        }
    }

    // Draw gems on minimap
    for (let gem of gems) {
        if (gem.collected) continue;
        ctx.fillStyle = '#ffd700';
        ctx.fillRect(mapX + gem.gridX * cellW + 1, mapY + gem.gridY * cellH + 1, cellW - 1, cellH - 1);
    }

    // Draw enemies on minimap
    for (let enemy of enemies) {
        ctx.fillStyle = enemy.state === 'chase' ? '#ff4444' : '#ff8888';
        ctx.beginPath();
        ctx.arc(mapX + enemy.gridX * cellW + cellW/2, mapY + enemy.gridY * cellH + cellH/2, 2, 0, Math.PI * 2);
        ctx.fill();
    }

    // Draw player on minimap
    ctx.fillStyle = '#3388ff';
    ctx.beginPath();
    ctx.arc(mapX + player.gridX * cellW + cellW/2, mapY + player.gridY * cellH + cellH/2, 3, 0, Math.PI * 2);
    ctx.fill();
}

// ============================================================
//  START
// ============================================================
initLevel(1);
requestAnimationFrame(gameLoop);
