  width: 100%; height: 100%;
  pointer-events: none;
  z-index: 1001;
  overflow: hidden;
}

.confetti {
  position: absolute;
  width: 10px;
  height: 10px;
  top: -10px;
  animation: confettiFall linear forwards;
}

@keyframes confettiFall {
  0% { transform: translateY(0) rotate(0deg); opacity: 1; }
  100% { transform: translateY(100vh) rotate(720deg); opacity: 0; }
}

/* Hint overlay */
.hint-overlay {
  display: none;
  position: absolute;
  top: 8px; left: 8px;
  right: 8px; bottom: 8px;
  border-radius: 16px;
  z-index: 10;
  pointer-events: none;
  animation: hintFade 2s ease forwards;
}

.hint-overlay.active { display: block; }

.hint-overlay img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 16px;
  opacity: 0.8;
}

@keyframes hintFade {
  0% { opacity: 0; }
  20% { opacity: 0.8; }
  80% { opacity: 0.8; }
  100% { opacity: 0; }
}

/* Responsive */
@media (max-width: 500px) {
  h1 { font-size: 1.5rem; }
  .stats-bar { gap: 20px; }
  .stat-value { font-size: 1.2rem; }
}
</style>
