<body>

<h1>🧩 Photo Puzzle</h1>
<p class="subtitle">Upload a photo and solve the puzzle!</p>

<!-- Upload Area -->
<div class="upload-area" id="uploadArea">
  <div class="icon">📷</div>
  <p>Tap to choose a photo from your gallery</p>
  <input type="file" id="fileInput" accept="image/*">
</div>

<!-- Game Controls -->
<div class="game-controls" id="gameControls">
  <button class="btn btn-shuffle" id="shuffleBtn">🔀 Shuffle</button>
  <button class="btn btn-hint" id="hintBtn">💡 Hint</button>
  <div class="size-selector">
    <span>Size:</span>
    <button class="size-btn active" data-size="3">3×3</button>
    <button class="size-btn" data-size="4">4×4</button>
    <button class="size-btn" data-size="5">5×5</button>
  </div>
