<div class="puzzle-container" id="puzzleContainer">
  <div class="puzzle-board" id="puzzleBoard"></div>
</div>

<!-- Preview -->
<div class="preview-area" id="previewArea">
  <div class="preview-label">Original Photo</div>
  <img class="preview-img" id="previewImg" src="" alt="Preview">
</div>

<!-- Win Overlay -->
<div class="win-overlay" id="winOverlay">
  <div class="win-content">
    <div class="trophy">🏆</div>
    <h2>Puzzle Solved!</h2>
    <p id="winMoves">Moves: 0</p>
    <p id="winTime">Time: 0:00</p>
    <button class="btn btn-shuffle" id="playAgainBtn">🔄 Play Again</button>
  </div>
</div>

<!-- Confetti Container -->
<div class="confetti-container" id="confettiContainer"></div>

<script>
(function() {
  // State
  let gridSize = 3;
  let tiles = [];
  let emptyIndex;
  let moves = 0;
  let timerInterval = null;
  let seconds = 0;
  let gameStarted = false;
  let imageSrc = null;
  let isAnimating = false;

  // DOM
  const uploadArea = document.getElementById('uploadArea');
  const fileInput = document.getElementById('fileInput');
  const gameControls = document.getElementById('gameControls');
  const statsBar = document.getElementById('statsBar');
  const puzzleContainer = document.getElementById('puzzleContainer');
  const puzzleBoard = document.getElementById('puzzleBoard');
  const previewArea = document.getElementById('previewArea');
  const previewImg = document.getElementById('previewImg');
  const moveCount = document.getElementById('moveCount');
  const timerEl = document.getElementById('timer');
  const gridSizeEl = document.getElementById('gridSize');
  const winOverlay = document.getElementById('winOverlay');
  const confettiContainer = document.getElementById('confettiContainer');
  const hintBtn = document.getElementById('hintBtn');

  // Upload handling
  uploadArea.addEventListener('click', () => fileInput.click());

  fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      imageSrc = ev.target.result;
      previewImg.src = imageSrc;
      startGame();
    };
    reader.readAsDataURL(file);
  });

  // Drag & drop
  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = '#4facfe';
    uploadArea.style.background = 'rgba(79,172,254,0.15)';
  });

  uploadArea.addEventListener('dragleave', () => {
    uploadArea.style.borderColor = 'rgba(255,255,255,0.3)';
    uploadArea.style.background = 'rgba(255,255,255,0.05)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.3)';
    uploadArea.style.background = 'rgba(255,255,255,0.05)';
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        imageSrc = ev.target.result;
        previewImg.src = imageSrc;
        startGame();
      };
      reader.readAsDataURL(file);
    }
  });

  // Size buttons
  document.querySelectorAll('.size-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.size-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      gridSize = parseInt(btn.dataset.size);
      gridSizeEl.textContent = gridSize + '×' + gridSize;
      if (imageSrc) startGame();
    });
  });

  // Shuffle button
  document.getElementById('shuffleBtn').addEventListener('click', () => {
    if (!imageSrc) return;
    shuffleTiles();
    resetStats();
    startTimer();
  });

  // Hint button
  hintBtn.addEventListener('click', () => {
    if (!imageSrc) return;
    showHint();
  });

  // New photo button
  document.getElementById('newBtn').addEventListener('click', () => {
    fileInput.click();
  });

  // Play again
  document.getElementById('playAgainBtn').addEventListener('click', () => {
    winOverlay.classList.remove('active');
    confettiContainer.innerHTML = '';
    shuffleTiles();
    resetStats();
    startTimer();
  });

  function startGame() {
    uploadArea.style.display = 'none';
    gameControls.classList.add('active');
    statsBar.classList.add('active');
    puzzleContainer.classList.add('active');
    previewArea.classList.add('active');

    gridSizeEl.textContent = gridSize + '×' + gridSize;
    createPuzzle();
    shuffleTiles();
  }

  function createPuzzle() {
    const totalTiles = gridSize * gridSize;
    tiles = [];
    for (let i = 0; i < totalTiles; i++) {
      tiles.push(i);
    }
    emptyIndex = totalTiles - 1;
    renderBoard();
  }

  function renderBoard() {
    const boardSize = Math.min(window.innerWidth * 0.85, 450);
    puzzleBoard.style.width = boardSize + 'px';
    puzzleBoard.style.height = boardSize + 'px';
    puzzleBoard.style.gridTemplateColumns = `repeat(${gridSize}, 1fr)`;
    puzzleBoard.style.gridTemplateRows = `repeat(${gridSize}, 1fr)`;

    puzzleBoard.innerHTML = '';

    tiles.forEach((tileVal, index) => {
      const tile = document.createElement('div');
      tile.className = 'tile';
      tile.style.width = '100%';
      tile.style.height = '100%';

      if (tileVal === -1) {
        // Empty tile
        tile.classList.add('empty');
      } else {
        // Calculate position in original image
        const row = Math.floor((tileVal) / gridSize);
        const col = (tileVal) % gridSize;
        const bgX = (col / (gridSize - 1)) * 100;
        const bgY = (row / (gridSize - 1)) * 100;

        tile.style.backgroundImage = `url(${imageSrc})`;
        tile.style.backgroundPosition = `${bgX}% ${bgY}%`;
        tile.style.backgroundSize = `${gridSize * 100}%`;

        // Show number
        const num = document.createElement('span');
        num.className = 'tile-number';
        num.textContent = tileVal;
        tile.appendChild(num);

        // Check if in correct position
        if (tileVal === index) {
          tile.classList.add('correct');
        }

        tile.addEventListener('click', () => handleTileClick(index));
      }

      puzzleBoard.appendChild(tile);
    });
  }

  function handleTileClick(index) {
    if (!gameStarted) {
      gameStarted = true;
      startTimer();
    }

    if (isAdjacent(index, emptyIndex)) {
      // Swap
      tiles[emptyIndex] = tiles[index];
      tiles[index] = -1;
      emptyIndex = index;
      moves++;
      moveCount.textContent = moves;

      renderBoard();
      checkWin();
    }
  }

  function isAdjacent(idx1, idx2) {
    const row1 = Math.floor(idx1 / gridSize);
    const col1 = idx1 % gridSize;
    const row2 = Math.floor(idx2 / gridSize);
    const col2 = idx2 % gridSize;
    return (Math.abs(row1 - row2) + Math.abs(col1 - col2)) === 1;
  }

  function shuffleTiles() {
    // Reset
    const totalTiles = gridSize * gridSize;
    tiles = [];
    for (let i = 0; i < totalTiles; i++) {
      tiles.push(i);
    }
    emptyIndex = totalTiles - 1;

    // Perform random valid moves to ensure solvability
    const totalMoves = gridSize * gridSize * 20;
    let lastMove = -1;

    for (let i = 0; i < totalMoves; i++) {
      const neighbors = getNeighbors(emptyIndex);
      // Avoid undoing the last move
      const filtered = neighbors.filter(n => n !== lastMove);
      const pick = filtered[Math.floor(Math.random() * filtered.length)];

      tiles[emptyIndex] = tiles[pick];
      tiles[pick] = -1;
      lastMove = emptyIndex;
      emptyIndex = pick;
    }

    moves = 0;
    moveCount.textContent = '0';
    gameStarted = false;
    resetTimer();
    renderBoard();
  }

  function getNeighbors(index) {
    const row = Math.floor(index / gridSize);
    const col = index % gridSize;
    const neighbors = [];

    if (row > 0) neighbors.push(index - gridSize);
    if (row < gridSize - 1) neighbors.push(index + gridSize);
    if (col > 0) neighbors.push(index - 1);
    if (col < gridSize - 1) neighbors.push(index + 1);

    return neighbors;
  }

  function checkWin() {
    for (let i = 0; i < tiles.length - 1; i++) {
      if (tiles[i] !== i) return;
    }
    // Win!
    stopTimer();
    setTimeout(() => {
      showWin();
    }, 300);
  }

  function showWin() {
    document.getElementById('winMoves').textContent = `Moves: ${moves}`;
    document.getElementById('winTime').textContent = `Time: ${formatTime(seconds)}`;
    winOverlay.classList.add('active');
    launchConfetti();
  }

  function launchConfetti() {
    confettiContainer.innerHTML = '';
    const colors = ['#f093fb', '#f5576c', '#4facfe', '#00f2fe', '#43e97b', '#fee140', '#fa709a'];

    for (let i = 0; i < 80; i++) {
      const confetti = document.createElement('div');
      confetti.className = 'confetti';
      confetti.style.left = Math.random() * 100 + '%';
      confetti.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
      confetti.style.width = (Math.random() * 10 + 5) + 'px';
      confetti.style.height = (Math.random() * 10 + 5) + 'px';
      confetti.style.borderRadius = Math.random() > 0.5 ? '50%' : '2px';
      confetti.style.animationDuration = (Math.random() * 2 + 2) + 's';
      confetti.style.animationDelay = (Math.random() * 1.5) + 's';
      confettiContainer.appendChild(confetti);
    }

    setTimeout(() => { confettiContainer.innerHTML = ''; }, 5000);
  }

  function showHint() {
    // Create a temporary overlay showing the solved puzzle
    const hintOverlay = document.createElement('div');
    hintOverlay.className = 'hint-overlay active';

    const img = document.createElement('img');
    img.src = imageSrc;
    img.style.objectFit = 'cover';
    img.style.width = '100%';
    img.style.height = '100%';
    img.style.borderRadius = '12px';

    hintOverlay.appendChild(img);
    puzzleContainer.appendChild(hintOverlay);

    setTimeout(() => {
      hintOverlay.remove();
    }, 2000);
  }

  // Timer
  function startTimer() {
    if (timerInterval) return;
    timerInterval = setInterval(() => {
      seconds++;
      timerEl.textContent = formatTime(seconds);
    }, 1000);
  }

  function stopTimer() {
    clearInterval(timerInterval);
    timerInterval = null;
  }

  function resetTimer() {
    stopTimer();
    seconds = 0;
    timerEl.textContent = '0:00';
  }

  function resetStats() {
    moves = 0;
    moveCount.textContent = '0';
    resetTimer();
    gameStarted = false;
  }

  function formatTime(s) {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return mins + ':' + (secs < 10 ? '0' : '') + secs;
  }

  // Handle window resize
  window.addEventListener('resize', () => {
    if (imageSrc) renderBoard();
  });

  // Keyboard support
  document.addEventListener('keydown', (e) => {
    if (!imageSrc) return;

    let targetIndex = -1;
    const row = Math.floor(emptyIndex / gridSize);
    const col = emptyIndex % gridSize;

    switch(e.key) {
      case 'ArrowUp':
        if (row < gridSize - 1) targetIndex = emptyIndex + gridSize;
        break;
      case 'ArrowDown':
        if (row > 0) targetIndex = emptyIndex - gridSize;
        break;
      case 'ArrowLeft':
        if (col < gridSize - 1) targetIndex = emptyIndex + 1;
        break;
      case 'ArrowRight':
        if (col > 0) targetIndex = emptyIndex - 1;
        break;
    }

    if (targetIndex >= 0) {
      e.preventDefault();
      handleTileClick(targetIndex);
    }
  });
})();
</script>
