    border: 1px solid rgba(255,255,255,0.2);
  }

  .btn:hover { transform: translateY(-2px); filter: brightness(1.1); }
  .btn:active { transform: translateY(0); }

  .moves-display {
    font-size: 14px;
    color: rgba(255,255,255,0.7);
    text-align: center;
    font-weight: 600;
  }

  .moves-display span { color: #ffa751; font-size: 18px; }

  .target-display {
    font-size: 13px;
    color: rgba(255,255,255,0.5);
    text-align: center;
  }

  .target-display span { color: #69db7c; font-size: 16px; font-weight: 700; }

  .progress-bar {
    width: 100%;
    max-width: 480px;
    height: 8px;
    background: rgba(255,255,255,0.1);
    border-radius: 4px;
    overflow: hidden;
  }

  .progress-fill {
    height: 100%;
    background: linear-gradient(to right, #ff6b9d, #ffa751, #ffe259, #69db7c);
    border-radius: 4px;
    transition: width 0.5s ease;
  }

  .overlay {
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0,0,0,0.7);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    backdrop-filter: blur(5px);
    animation: fadeIn 0.3s ease;
  }

  @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

  .modal {
    background: linear-gradient(145deg, #2d1b69, #1a0533);
    border-radius: 24px;
    padding: 30px;
    text-align: center;
    border: 1px solid rgba(255,255,255,0.15);
    box-shadow: 0 20px 60px rgba(0,0,0,0.5);
    max-width: 320px;
    width: 90%;
    animation: modalPop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  @keyframes modalPop {
    from { transform: scale(0.5); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
  }

  .modal h2 {
    font-size: 28px;
    margin-bottom: 10px;
    background: linear-gradient(to right, #ff6b9d, #ffa751);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .modal p { color: rgba(255,255,255,0.7); margin-bottom: 20px; font-size: 15px; }
  .modal .final-score { font-size: 42px; font-weight: 900; color: #ffe259; margin: 10px 0; }

  .no-moves-msg {
    color: rgba(255,255,255,0.6);
    font-size: 13px;
    text-align: center;
    min-height: 20px;
  }

  @media (max-width: 400px) {
    .title { font-size: 18px; }
    .score-panel { padding: 6px 14px; min-width: 90px; }
    .score-panel .value { font-size: 22px; }
    .score-panel .label { font-size: 9px; }
    .board { gap: 2px; }
    .board-wrapper { padding: 5px; border-radius: 14px; }
    .candy { border-radius: 10px; }
  }
</style>
</head>
<body>

<div class="game-container">
  <div class="header">
    <div class="score-panel">
      <div class="label">Score</div>
      <div class="value" id="score">0</div>
    </div>
    <div class="title">🍬 CANDY CRUSH</div>
    <div class="score-panel">
      <div class="label">Moves</div>
      <div class="value" id="moves">30</div>
    </div>
  </div>

  <div class="target-display">Target: <span id="target">2000</span></div>
  <div class="progress-bar"><div class="progress-fill" id="progress" style="width:0%"></div></div>

  <div class="board-wrapper">
    <div class="board" id="board"></div>
  </div>

  <div class="no-moves-msg" id="noMovesMsg"></div>

  <div class="controls">
    <button class="btn btn-secondary" onclick="showHint()">💡 Hint</button>
    <button class="btn btn-primary" onclick="resetGame()">🔄 New Game</button>
  </div>
</div>

<script>
const ROWS = 8, COLS = 8, NUM_COLORS = 6;
const COLORS = ['red','orange','yellow','green','blue','purple'];
const COLOR_MAP = { 0:'red', 1:'orange', 2:'yellow', 3:'green', 4:'blue', 5:'purple' };
const CANDY_ICONS = ['🔴','🟠','🟡','🟢','🔵','🟣'];

let grid = [];
let candyElements = [];
let selectedCandy = null;
let isProcessing = false;
let score = 0;
let moves = 30;
let targetScore = 2000;
let comboCount = 0;
let hintPair = null;

const boardEl = document.getElementById('board');
const scoreEl = document.getElementById('score');
const movesEl = document.getElementById('moves');
const targetEl = document.getElementById('target');
const progressEl = document.getElementById('progress');
const noMovesMsg = document.getElementById('noMovesMsg');

function init() {
  boardEl.innerHTML = '';
  grid = [];
  candyElements = [];
  selectedCandy = null;
  isProcessing = false;
  score = 0;
  moves = 30;
  targetScore = 2000;
  comboCount = 0;
  hintPair = null;

  scoreEl.textContent = '0';
  movesEl.textContent = '30';
  targetEl.textContent = '2000';
  progressEl.style.width = '0%';
  noMovesMsg.textContent = '';

  for (let r = 0; r < ROWS; r++) {
    grid[r] = [];
    candyElements[r] = [];
    for (let c = 0; c < COLS; c++) {
      let color;
      do {
        color = Math.floor(Math.random() * NUM_COLORS);
      } while (
        (c >= 2 && grid[r][c-1] === color && grid[r][c-2] === color) ||
        (r >= 2 && grid[r-1][c] === color && grid[r-2][c] === color)
      );
      grid[r][c] = { color, type: 'normal', stripedH: false, stripedV: false, wrapped: false, bomb: false };
      createCandyElement(r, c);
    }
  }

  // Ensure no initial matches
  let hasMatches = findMatches().length > 0;
  if (hasMatches) {
    init();
    return;
  }

  // Ensure at least one valid move
  if (!hasValidMoves()) {
    shuffleBoard();
  }
}

function createCandyElement(r, c) {
  const cell = document.createElement('div');
  cell.className = 'cell';
  cell.style.gridColumn = c + 1;
  cell.style.gridRow = r + 1;
  boardEl.appendChild(cell);

  const candy = document.createElement('div');
  candy.className = `candy candy-${COLOR_MAP[grid[r][c].color]}`;
  candy.dataset.row = r;
  candy.dataset.col = c;
  candy.style.width = `calc((100% - ${COLS - 1} * 3px) / ${COLS})`;
  candy.style.height = `calc((100% - ROWS - 1 * 3px) / ${ROWS})`;

  // Fix: set proper dimensions
  const cellSize = boardEl.offsetWidth / COLS;
  candy.style.width = `${cellSize - 3}px`;
  candy.style.height = `${cellSize - 3}px`;
  candy.style.fontSize = `${cellSize * 0.45}px`;
  candy.style.top = `${3 + r * (cellSize + 3)}px`;
  candy.style.left = `${3 + c * (cellSize + 3)}px`;

  candy.addEventListener('click', () => onCandyClick(r, c));
  candy.addEventListener('touchstart', (e) => { e.preventDefault(); onCandyClick(r, c); }, { passive: false });

  boardEl.appendChild(candy);
  candyElements[r][c] = candy;
}

function updateCandyPosition(r, c) {
  const candy = candyElements[r][c];
  if (!candy) return;
  const cellSize = (boardEl.offsetWidth - 6) / COLS;
  candy.style.top = `${3 + r * (cellSize + 3)}px`;
  candy.style.left = `${3 + c * (cellSize + 3)}px`;
  candy.style.width = `${cellSize - 3}px`;
  candy.style.height = `${cellSize - 3}px`;
  candy.style.fontSize = `${cellSize * 0.45}px`;
}

function onCandyClick(r, c) {
  if (isProcessing) return;
  if (hintPair) clearHint();

  if (!selectedCandy) {
    selectedCandy = { r, c };
    candyElements[r][c].classList.add('selected');
  } else {
    const sr = selectedCandy.r, sc = selectedCandy.c;
    candyElements[sr][sc].classList.remove('selected');

    if (sr === r && sc === c) {
      selectedCandy = null;
      return;
    }

    const dr = Math.abs(sr - r), dc = Math.abs(sc - c);
    if ((dr === 1 && dc === 0) || (dr === 0 && dc === 1)) {
      selectedCandy = null;
      trySwap(sr, sc, r, c);
    } else {
      selectedCandy = { r, c };
      candyElements[r][c].classList.add('selected');
    }
  }
}

async function trySwap(r1, c1, r2, c2) {
  isProcessing = true;

  // Animate swap
  await animateSwap(r1, c1, r2, c2);

  // Swap in grid
  const temp = grid[r1][c1];
  grid[r1][c1] = grid[r2][c2];
  grid[r2][c2] = temp;

  // Swap in elements array
  const tempEl = candyElements[r1][c1];
  candyElements[r1][c1] = candyElements[r2][c2];
  candyElements[r2][c2] = tempEl;

  candyElements[r1][c1].dataset.row = r1;
  candyElements[r1][c1].dataset.col = c1;
  candyElements[r2][c2].dataset.row = r2;
  candyElements[r2][c2].dataset.col = c2;

  const matches = findMatches();

  if (matches.length > 0) {
    moves--;
    movesEl.textContent = moves;
    comboCount = 0;
    await processMatches();
  } else {
    // Swap back
    await animateSwap(r1, c1, r2, c2);
    const tempG = grid[r1][c1];
    grid[r1][c1] = grid[r2][c2];
    grid[r2][c2] = tempG;
    const tempE = candyElements[r1][c1];
    candyElements[r1][c1] = candyElements[r2][c2];
    candyElements[r2][c2] = tempE;
    candyElements[r1][c1].dataset.row = r1;
    candyElements[r1][c1].dataset.col = c1;
    candyElements[r2][c2].dataset.row = r2;
    candyElements[r2][c2].dataset.col = c2;
  }

  isProcessing = false;

  if (moves <= 0) {
    setTimeout(() => showEndModal(), 500);
  } else if (!hasValidMoves()) {
    noMovesMsg.textContent = 'No valid moves! Shuffling...';
    setTimeout(() => {
      shuffleBoard();
      noMovesMsg.textContent = '';
    }, 1000);
  }
}

function animateSwap(r1, c1, r2, c2) {
  return new Promise(resolve => {
    const el1 = candyElements[r1][c1];
    const el2 = candyElements[r2][c2];

    el1.classList.add('swapping');
    el2.classList.add('swapping');

    const cellSize = (boardEl.offsetWidth - 6) / COLS;
    el1.style.top = `${3 + r2 * (cellSize + 3)}px`;
    el1.style.left = `${3 + c2 * (cellSize + 3)}px`;
    el2.style.top = `${3 + r1 * (cellSize + 3)}px`;
    el2.style.left = `${3 + c1 * (cellSize + 3)}px`;

    setTimeout(() => {
      el1.classList.remove('swapping');
      el2.classList.remove('swapping');
      resolve();
    }, 200);
  });
}

function findMatches() {
  const matched = new Set();

  // Horizontal matches
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS - 2; c++) {
      if (grid[r][c].color === grid[r][c+1].color && grid[r][c].color === grid[r][c+2].color) {
        let end = c + 2;
        while (end + 1 < COLS && grid[r][end+1].color === grid[r][c].color) end++;
        for (let i = c; i <= end; i++) matched.add(`${r},${i}`);
        c = end;
      }
    }
  }

  // Vertical matches
  for (let c = 0; c < COLS; c++) {
    for (let r = 0; r < ROWS - 2; r++) {
      if (grid[r][c].color === grid[r+1][c].color && grid[r][c].color === grid[r+2][c].color) {
        let end = r + 2;
        while (end + 1 < ROWS && grid[end+1][c].color === grid[r][c].color) end++;
        for (let i = r; i <= end; i++) matched.add(`${i},${c}`);
        r = end;
      }
    }
  }

  return Array.from(matched).map(s => {
    const [r, c] = s.split(',').map(Number);
    return { r, c };
  });
}

async function processMatches() {
  let matches = findMatches();

  while (matches.length > 0) {
    comboCount++;
    const points = matches.length * 10 * comboCount;
    score += points;
    scoreEl.textContent = score;
    updateProgress();

    // Show combo text
    if (comboCount > 1) {
      showComboText(comboCount);
    }

    // Determine special candy creation
    const matchMap = {};
    matches.forEach(m => { matchMap[`${m.r},${m.c}`] = true; });

    // Find groups for special candy creation
    const groups = findMatchGroups(matches);

    // Create special candies
    for (const group of groups) {
      if (group.length >= 4) {
        const center = group[Math.floor(group.length / 2)];
        grid[center.r][center.c] = {
          color: grid[center.r][center.c].color,
          type: 'wrapped',
          stripedH: false, stripedV: false, wrapped: false, bomb: false
        };
      }
    }

    // Activate special candy effects
    const toRemove = new Set(matches.map(m => `${m.r},${m.c}`));
    const newMatches = [];

    for (const m of matches) {
      const cell = grid[m.r][m.c];
      if (cell.stripedH) {
        for (let c = 0; c < COLS; c++) toRemove.add(`${m.r},${c}`);
      }
      if (cell.stripedV) {
        for (let r = 0; r < ROWS; r++) toRemove.add(`${r},${m.c}`);
      }
      if (cell.bomb) {
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            const nr = m.r + dr, nc = m.c + dc;
            if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS) {
              toRemove.add(`${nr},${nc}`);
            }
          }
        }
      }
    }

    // Animate removal
    for (const key of toRemove) {
      const [r, c] = key.split(',').map(Number);
      if (candyElements[r] && candyElements[r][c]) {
        candyElements[r][c].classList.add('matched');
        spawnParticles(r, c, COLORS[grid[r][c].color]);
      }
    }

    await delay(350);

    // Remove matched candies
    for (const key of toRemove) {
      const [r, c] = key.split(',').map(Number);
      if (candyElements[r] && candyElements[r][c]) {
        candyElements[r][c].remove();
        candyElements[r][c] = null;
      }
      grid[r][c] = null;
    }

    // Drop candies
    await dropCandies();

    // Fill empty spaces
    await fillEmpty();

    matches = findMatches();
  }
}

function findMatchGroups(matches) {
  const groups = [];
  const visited = new Set();

  for (const m of matches) {
    const key = `${m.r},${m.c}`;
    if (visited.has(key)) continue;

    const group = [];
    const color = grid[m.r][m.c].color;
    const queue = [m];
    visited.add(key);

    while (queue.length > 0) {
      const current = queue.shift();
      group.push(current);

      const neighbors = [
        { r: current.r - 1, c: current.c },
        { r: current.r + 1, c: current.c },
        { r: current.r, c: current.c - 1 },
        { r: current.r, c: current.c + 1 }
      ];

      for (const n of neighbors) {
        const nKey = `${n.r},${n.c}`;
        if (n.r >= 0 && n.r < ROWS && n.c >= 0 && n.c < COLS &&
            !visited.has(nKey) && grid[n.r] && grid[n.r][n.c] &&
            grid[n.r][n.c].color === color && matches.some(mm => mm.r === n.r && mm.c === n.c)) {
          visited.add(nKey);
          queue.push(n);
        }
      }
    }

    groups.push(group);
  }

  return groups;
}

async function dropCandies() {
  let moved = false;

  for (let c = 0; c < COLS; c++) {
    for (let r = ROWS - 1; r >= 0; r--) {
      if (grid[r][c] === null) {
        // Find nearest candy above
        for (let rr = r - 1; rr >= 0; rr--) {
          if (grid[rr][c] !== null) {
            grid[r][c] = grid[rr][c];
            grid[rr][c] = null;

            if (candyElements[rr][c]) {
              candyElements[r][c] = candyElements[rr][c];
              candyElements[rr][c] = null;
              candyElements[r][c].dataset.row = r;
              candyElements[r][c].classList.add('dropping');
              updateCandyPosition(r, c);
              setTimeout(() => candyElements[r][c].classList.remove('dropping'), 300);
            }
            moved = true;
            break;
          }
        }
      }
    }
  }

  if (moved) await delay(300);
}

async function fillEmpty() {
  const cellSize = (boardEl.offsetWidth - 6) / COLS;

  for (let c = 0; c < COLS; c++) {
    for (let r = 0; r < ROWS; r++) {
      if (grid[r][c] === null) {
        const color = Math.floor(Math.random() * NUM_COLORS);
        grid[r][c] = { color, type: 'normal', stripedH: false, stripedV: false, wrapped: false, bomb: false };

        const candy = document.createElement('div');
        candy.className = `candy candy-${COLOR_MAP[color]}`;
        candy.dataset.row = r;
        candy.dataset.col = c;
        candy.style.width = `${cellSize - 3}px`;
        candy.style.height = `${cellSize - 3}px`;
        candy.style.fontSize = `${cellSize * 0.45}px`;
        candy.style.top = `${3 + r * (cellSize + 3)}px`;
        candy.style.left = `${3 + c * (cellSize + 3)}px`;
        candy.style.opacity = '0';
        candy.style.transform = 'scale(0.5)';

        candy.addEventListener('click', () => onCandyClick(r, c));
        candy.addEventListener('touchstart', (e) => { e.preventDefault(); onCandyClick(r, c); }, { passive: false });

        boardEl.appendChild(candy);
        candyElements[r][c] = candy;

        // Animate in
        requestAnimationFrame(() => {
          candy.style.transition = 'all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
          candy.style.opacity = '1';
          candy.style.transform = 'scale(1)';
          setTimeout(() => {
            candy.style.transition = 'transform 0.15s ease, filter 0.15s ease';
          }, 300);
        });
      }
    }
  }

  await delay(350);
}

function spawnParticles(r, c, color) {
  const boardRect = boardEl.getBoundingClientRect();
  const cellSize = (boardEl.offsetWidth - 6) / COLS;
  const cx = 3 + c * (cellSize + 3) + cellSize / 2;
  const cy = 3 + r * (cellSize + 3) + cellSize / 2;

  const colorMap = {
    red: '#ff4757', orange: '#ffa502', yellow: '#ffd32a',
    green: '#2ed573', blue: '#54a0ff', purple: '#a55eea'
  };

  for (let i = 0; i < 6; i++) {
    const p = document.createElement('div');
    p.className = 'particle';
    p.style.background = colorMap[color] || '#fff';
    p.style.left = `${cx}px`;
    p.style.top = `${cy}px`;
    const angle = (Math.PI * 2 / 6) * i + Math.random() * 0.5;
    const dist = 30 + Math.random() * 40;
    p.style.setProperty('--tx', `${Math.cos(angle) * dist}px`);
    p.style.setProperty('--ty', `${Math.sin(angle) * dist}px`);
    boardEl.appendChild(p);
    setTimeout(() => p.remove(), 600);
  }
}

function showComboText(combo) {
  const ct = document.createElement('div');
  ct.className = 'combo-text';
  ct.textContent = combo >= 4 ? `🔥 ${combo}x COMBO!` : combo >= 3 ? `⚡ ${combo}x COMBO!` : `✨ ${combo}x COMBO!`;
  ct.style.left = '50%';
  ct.style.top = '50%';
  ct.style.transform = 'translate(-50%, -50%)';
  boardEl.appendChild(ct);
  setTimeout(() => ct.remove(), 1000);
}

function hasValidMoves() {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      // Try swap right
      if (c + 1 < COLS) {
        swapGrid(r, c, r, c + 1);
        if (findMatches().length > 0) { swapGrid(r, c, r, c + 1); return true; }
        swapGrid(r, c, r, c + 1);
      }
      // Try swap down
      if (r + 1 < ROWS) {
        swapGrid(r, c, r + 1, c);
        if (findMatches().length > 0) { swapGrid(r, c, r + 1, c); return true; }
        swapGrid(r, c, r + 1, c);
      }
    }
  }
  return false;
}

function swapGrid(r1, c1, r2, c2) {
  const temp = grid[r1][c1];
  grid[r1][c1] = grid[r2][c2];
  grid[r2][c2] = temp;
}

function findHint() {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (c + 1 < COLS) {
        swapGrid(r, c, r, c + 1);
        if (findMatches().length > 0) { swapGrid(r, c, r, c + 1); return { r1: r, c1: c, r2: r, c2: c + 1 }; }
        swapGrid(r, c, r, c + 1);
      }
      if (r + 1 < ROWS) {
        swapGrid(r, c, r + 1, c);
        if (findMatches().length > 0) { swapGrid(r, c, r + 1, c); return { r1: r, c1: c, r2: r + 1, c2: c }; }
        swapGrid(r, c, r + 1, c);
      }
    }
  }
  return null;
}

function showHint() {
  if (isProcessing) return;
  clearHint();
  const hint = findHint();
  if (hint) {
    hintPair = hint;
    candyElements[hint.r1][hint.c1].classList.add('hint');
    candyElements[hint.r2][hint.c2].classList.add('hint');
    setTimeout(clearHint, 3000);
  }
}

function clearHint() {
  if (hintPair) {
    if (candyElements[hintPair.r1] && candyElements[hintPair.r1][hintPair.c1])
      candyElements[hintPair.r1][hintPair.c1].classList.remove('hint');
    if (candyElements[hintPair.r2] && candyElements[hintPair.r2][hintPair.c2])
      candyElements[hintPair.r2][hintPair.c2].classList.remove('hint');
  }
  hintPair = null;
}

function shuffleBoard() {
  // Fisher-Yates shuffle of the grid
  const cells = [];
  for (let r = 0; r < ROWS; r++)
    for (let c = 0; c < COLS; c++)
      cells.push({ r, c, ...grid[r][c] });

  for (let i = cells.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [cells[i], cells[j]] = [cells[j], cells[i]];
  }

  // Remove old elements
  for (let r = 0; r < ROWS; r++)
    for (let c = 0; c < COLS; c++)
      if (candyElements[r][c]) candyElements[r][c].remove();

  // Rebuild
  for (let i = 0; i < cells.length; i++) {
    const { r, c } = cells[i];
    grid[r][c] = { color: cells[i].color, type: 'normal', stripedH: false, stripedV: false, wrapped: false, bomb: false };
    createCandyElement(r, c);
  }

  // Ensure no matches and valid moves
  let hasMatches = findMatches().length > 0;
  if (hasMatches) { shuffleBoard(); return; }
  if (!hasValidMoves()) { shuffleBoard(); }
}

function updateProgress() {
  const pct = Math.min(100, (score / targetScore) * 100);
  progressEl.style.width = `${pct}%`;

  if (score >= targetScore) {
    targetScore = Math.floor(targetScore * 1.5);
    targetEl.textContent = targetScore;
    progressEl.style.width = '0%';
    showComboText('🎉 Level Up!');
  }
}

function showEndModal() {
  const overlay = document.createElement('div');
  overlay.className = 'overlay';
  overlay.innerHTML = `
    <div class="modal">
      <h2>${score >= targetScore ? '🎉 Amazing!' : '🍬 Game Over'}</h2>
      <p>${score >= targetScore ? 'You crushed the target!' : 'Try again to reach the target!'}</p>
      <div class="final-score">${score}</div>
      <p>Target: ${targetScore}</p>
      <button class="btn btn-primary" onclick="this.closest('.overlay').remove(); resetGame();" style="width:100%;margin-top:10px;">Play Again</button>
    </div>
  `;
  document.body.appendChild(overlay);
}

function resetGame() {
  const overlay = document.querySelector('.overlay');
  if (overlay) overlay.remove();
  init();
}

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Handle resize
window.addEventListener('resize', () => {
  const cellSize = (boardEl.offsetWidth - 6) / COLS;
  for (let r = 0; r < ROWS; r++) {
