<body>
<h1>🧩 PUZZLE</h1>
<p id="subtitle">Drag pieces to the board to complete the image</p>
<div id="game-container">
  <div>
    <p style="text-align:center;color:#666;margin-bottom:8px;font-size:0.85rem;">BOARD</p>
    <div id="board"></div>
  </div>
  <div>
    <p style="text-align:center;color:#666;margin-bottom:8px;font-size:0.85rem;">PIECES</p>
    <div id="pieces-tray"></div>
  </div>
</div>
<div id="moves">Moves: <span id="move-count">0</span></div>
<div id="btn-row">
  <button onclick="initGame()">New Puzzle</button>
  <button onclick="showPreview()">Preview</button>
</div>
<div id="win-overlay">
  <h2>🎉 You Win!</h2>
  <p id="win-text">Completed in 0 moves!</p>
  <button onclick="closeWin(); initGame();">Play Again</button>
</div>
<canvas id="preview-canvas" width="360" height="360"></canvas>
<div id="drag-ghost"></div>

<script>
const SIZE = 3;
const CELL = 120;
const TRAY_CELL = 100;
let pieces = [];
let moves = 0;
let placedPieces = new Set();

const canvas = document.getElementById('preview-canvas');
const ctx = canvas.getContext('2d');
const ghost = document.getElementById('drag-ghost');

function generateImage() {
  ctx.clearRect(0, 0, 360, 360);

  // Background gradient
  const grad = ctx.createLinearGradient(0, 0, 360, 360);
  grad.addColorStop(0, '#0f3460');
  grad.addColorStop(0.5, '#1a1a4e');
  grad.addColorStop(1, '#16213e');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 360, 360);

  // Draw decorative shapes
  const colors = ['#e94560', '#4ecca3', '#f5c518', '#00b4d8', '#9b5de5', '#f15bb5', '#fee440', '#00f5d4', '#8ac926'];

  // Circles
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    const x = Math.random() * 360;
    const y = Math.random() * 360;
    const r = 20 + Math.random() * 40;
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)] + '44';
    ctx.fill();
    ctx.strokeStyle = colors[Math.floor(Math.random() * colors.length)] + '88';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // Rectangles
  for (let i = 0; i < 6; i++) {
    ctx.save();
    ctx.translate(Math.random() * 360, Math.random() * 360);
    ctx.rotate(Math.random() * Math.PI);
    ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)] + '33';
    ctx.fillRect(-30, -20, 60, 40);
    ctx.restore();
  }

  // Lines
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.random() * 360, Math.random() * 360);
    ctx.lineTo(Math.random() * 360, Math.random() * 360);
    ctx.strokeStyle = colors[Math.floor(Math.random() * colors.length)] + '55';
    ctx.lineWidth = 2 + Math.random() * 3;
    ctx.stroke();
  }

  // Stars
  for (let i = 0; i < 12; i++) {
    drawStar(ctx, Math.random() * 360, Math.random() * 360, 3 + Math.random() * 5, colors[Math.floor(Math.random() * colors.length)] + '66');
  }

  // Grid lines
  ctx.strokeStyle = '#ffffff0a';
  ctx.lineWidth = 1;
  for (let i = 0; i <= 3; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 120, 0);
    ctx.lineTo(i * 120, 360);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * 120);
    ctx.lineTo(360, i * 120);
    ctx.stroke();
  }

  // Numbers on each cell
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const idx = r * SIZE + c;
      ctx.fillStyle = '#ffffff33';
      ctx.font = 'bold 28px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(idx + 1, c * 120 + 60, r * 120 + 60);
    }
  }
}

function drawStar(ctx, cx, cy, size, color) {
  const spikes = 5;
  const outerR = size;
  const innerR = size * 0.4;
  ctx.beginPath();
  for (let i = 0; i < spikes * 2; i++) {
    const r = i % 2 === 0 ? outerR : innerR;
    const angle = (Math.PI * i) / spikes - Math.PI / 2;
    const x = cx + Math.cos(angle) * r;
    const y = cy + Math.sin(angle) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
}

function createPieceCanvas(row, col) {
  const c = document.createElement('canvas');
  c.width = CELL;
  c.height = CELL;
  const cctx = c.getContext('2d');
  cctx.drawImage(canvas, col * CELL, row * CELL, CELL, CELL, 0, 0, CELL, CELL);
  return c;
}

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function initGame() {
  moves = 0;
  placedPieces.clear();
  document.getElementById('move-count').textContent = '0';
  document.getElementById('win-overlay').classList.remove('show');

  generateImage();

  // Create pieces data
  pieces = [];
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      pieces.push({
        id: r * SIZE + c,
        correctRow: r,
        correctCol: c,
        canvas: createPieceCanvas(r, c)
      });
    }
  }

  // Shuffle pieces
  shuffle(pieces);

  // Build board
  const board = document.getElementById('board');
  board.innerHTML = '';
  for (let i = 0; i < SIZE * SIZE; i++) {
    const slot = document.createElement('div');
    slot.className = 'slot';
    slot.dataset.index = i;
    slot.dataset.row = Math.floor(i / SIZE);
    slot.dataset.col = i % SIZE;
    board.appendChild(slot);
  }

  // Build tray
  const tray = document.getElementById('pieces-tray');
  tray.innerHTML = '';
  for (let i = 0; i < SIZE * SIZE; i++) {
    const slot = document.createElement('div');
    slot.className = 'tray-slot';
    slot.dataset.trayIndex = i;
    const piece = pieces[i];
    const img = document.createElement('canvas');
    img.width = TRAY_CELL;
    img.height = TRAY_CELL;
    const ictx = img.getContext('2d');
    ictx.drawImage(piece.canvas, 0, 0, CELL, CELL, 0, 0, TRAY_CELL, TRAY_CELL);
    img.className = 'piece';
    img.dataset.pieceId = piece.id;
    img.draggable = false;
    slot.appendChild(img);
    tray.appendChild(slot);
  }

  setupDragAndDrop();
}

function setupDragAndDrop() {
  const allPieces = document.querySelectorAll('.piece');
  const allSlots = document.querySelectorAll('.slot');
  let draggedPiece = null;
  let draggedFrom = null;
  let offsetX = 0, offsetY = 0;

  allPieces.forEach(piece => {
    piece.addEventListener('mousedown', (e) => {
      e.preventDefault();
      draggedPiece = piece;
      draggedFrom = piece.parentElement;

      const rect = piece.getBoundingClientRect();
      offsetX = e.clientX - rect.left;
      offsetY = e.clientY - rect.top;

      ghost.style.width = CELL + 'px';
      ghost.style.height = CELL + 'px';
      ghost.style.backgroundImage = `url(${piece.toDataURL()})`;
      ghost.style.backgroundSize = 'cover';
      ghost.style.display = 'block';
      ghost.style.left = (e.clientX - offsetX) + 'px';
      ghost.style.top = (e.clientY - offsetY) + 'px';

      piece.style.opacity = '0.3';
    });
  });

  document.addEventListener('mousemove', (e) => {
    if (!draggedPiece) return;
    ghost.style.left = (e.clientX - offsetX) + 'px';
    ghost.style.top = (e.clientY - offsetY) + 'px';

    // Highlight drop targets
    allSlots.forEach(slot => {
      const rect = slot.getBoundingClientRect();
      if (e.clientX >= rect.left && e.clientX <= rect.right &&
          e.clientY >= rect.top && e.clientY <= rect.bottom) {
        slot.classList.add('drag-over');
      } else {
        slot.classList.remove('drag-over');
      }
    });
  });

  document.addEventListener('mouseup', (e) => {
    if (!draggedPiece) return;

    let dropped = false;
    const slots = document.querySelectorAll('.slot');

    slots.forEach(slot => {
      slot.classList.remove('drag-over');
      const rect = slot.getBoundingClientRect();
      if (e.clientX >= rect.left && e.clientX <= rect.right &&
          e.clientY >= rect.top && e.clientY <= rect.bottom) {

        const pieceId = parseInt(draggedPiece.dataset.pieceId);
        const pieceData = pieces.find(p => p.id === pieceId);
        const slotRow = parseInt(slot.dataset.row);
        const slotCol = parseInt(slot.dataset.col);

        // If slot already has a piece, move it back to tray
        if (slot.children.length > 0) {
          const existingPiece = slot.children[0];
          const existingId = parseInt(existingPiece.dataset.pieceId);
          const existingData = pieces.find(p => p.id === existingId);
          returnToTray(existingPiece);
          placedPieces.delete(existingId);
          if (existingData.correctRow === slotRow && existingData.correctCol === slotCol) {
            // It was correct, remove correct class
            existingPiece.classList.remove('correct');
          }
        }

        // Place the dragged piece
        slot.innerHTML = '';
        draggedPiece.style.opacity = '1';
        draggedPiece.style.position = 'static';
        draggedPiece.style.width = '114px';
        draggedPiece.style.height = '114px';
        draggedPiece.style.margin = '0 auto';
        draggedPiece.dataset.pieceId = pieceId;
        slot.appendChild(draggedPiece);

        moves++;
        document.getElementById('move-count').textContent = moves;

        // Check if correct
        if (pieceData.correctRow === slotRow && pieceData.correctCol === slotCol) {
          draggedPiece.classList.add('correct');
          placedPieces.add(pieceId);
        } else {
          draggedPiece.classList.remove('correct');
          placedPieces.delete(pieceId);
        }

        // Remove from tray
        if (draggedFrom && draggedFrom.classList.contains('tray-slot')) {
          draggedFrom.innerHTML = '';
        }

        dropped = true;
      }
    });

    if (!dropped) {
      draggedPiece.style.opacity = '1';
      if (draggedFrom && draggedFrom.classList.contains('tray-slot')) {
        draggedPiece.style.position = 'static';
        draggedPiece.style.width = '94px';
        draggedPiece.style.height = '94px';
        draggedPiece.style.margin = '0 auto';
      }
    }

    ghost.style.display = 'none';
    draggedPiece = null;
    draggedFrom = null;

    // Check win
    if (placedPieces.size === SIZE * SIZE) {
      setTimeout(() => {
        document.getElementById('win-text').textContent = `Completed in ${moves} moves!`;
        document.getElementById('win-overlay').classList.add('show');
      }, 300);
    }
  });
}

function returnToTray(pieceEl) {
  const tray = document.getElementById('pieces-tray');
  const emptySlots = tray.querySelectorAll('.tray-slot:empty');
  if (emptySlots.length > 0) {
    const slot = emptySlots[0];
    pieceEl.style.position = 'static';
    pieceEl.style.width = '94px';
    pieceEl.style.height = '94px';
    pieceEl.style.margin = '0 auto';
    slot.appendChild(pieceEl);
  }
}

function showPreview() {
  const overlay = document.getElementById('win-overlay');
  overlay.querySelector('h2').textContent = '🖼️ Preview';
  overlay.querySelector('p').textContent = 'This is the completed puzzle';
  overlay.querySelector('button').textContent = 'Close';
  overlay.querySelector('button').onclick = closeWin;
  overlay.classList.add('show');
}

function closeWin() {
  document.getElementById('win-overlay').classList.remove('show');
  // Reset button behavior
  const btn = document.querySelector('#win-overlay button');
  btn.textContent = 'Play Again';
  btn.onclick = () => { closeWin(); initGame(); };
}

initGame();
</script>
</body>
</html>

