  chateau:      { letters: 'CHATEAU',      row: 3, col: 2, dir: 'v', number: 3 },
  alleman:      { letters: 'ALLEMAN',      row: 3, col: 9, dir: 'v', number: 4 },
  royans:       { letters: 'ROYANS',       row: 3, col: 10, dir: 'v', number: 5 },
};

let currentWord = null;
let currentCell = null;

function buildGrid() {
  const gridEl = document.getElementById('grid');
  gridEl.innerHTML = '';
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.row = r;
      cell.dataset.col = c;

      const data = gridData[r][c];
      if (!data) {
        cell.classList.add('black');
      } else {
        cell.classList.add('white');
        const input = document.createElement('input');
        input.type = 'text';
        input.maxLength = 1;
        input.dataset.row = r;
