  clearMessage();
}

function onKeydown(e) {
  const input = e.target;
  const r = parseInt(input.dataset.row);
  const c = parseInt(input.dataset.col);

  if (e.key === 'Backspace' && !input.value) {
    e.preventDefault();
    moveFocus(r, c, -1);
  } else if (e.key === 'ArrowRight') {
    e.preventDefault();
    moveFocus(r, c, 1);
  } else if (e.key === 'ArrowLeft') {
    e.preventDefault();
    moveFocus(r, c, -1);
  } else if (e.key === 'ArrowDown') {
    e.preventDefault();
    moveFocus(r, c, COLS);
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    moveFocus(r, c, -COLS);
  }
}

function moveFocus(r, c, step) {
  let nr = r, nc = c + step;
  if (step === COLS || step === -COLS) {
    nr = r + (step > 0 ? 1 : -1);
    nc = c;
  }
  // Find next white cell in current word direction
  const word = getWordForCell(r, c);
  if (word) {
    const wordR = word.row;
    const wordC = word.col;
    const isH = word.dir === 'h';
    const wordLen = word.letters.length;
    const currentPos = isH ? (c - wordC) : (r - wordR);

    let newPos = currentPos + (step > 0 ? 1 : -1);
    if (newPos < 0) newPos = 0;
    if (newPos >= wordLen) newPos = wordLen - 1;

    const targetR = isH ? wordR : wordR + newPos;
    const targetC = isH ? wordC + newPos : wordC;

    const input = getInput(targetR, targetC);
    if (input) {
      input.focus();
      // If going backwards and current has value, clear it
      if (step < 0 && input.value) {
        // Don't clear, just move
      }
    }
  }
}

function getWordForCell(r, c) {
  for (const key in words) {
    const w = words[key];
    const isH = w.dir === 'h';
    if (isH && r === w.row && c >= w.col && c < w.col + w.letters.length) return w;
    if (!isH && c === w.col && r >= w.row && r < w.row + w.letters.length) return w;
  }
  return null;
}

function onFocus(e) {
  const input = e.target;
  const r = parseInt(input.dataset.row);
  const c = parseInt(input.dataset.col);
