    // Toggle direction if word already selected
    if (currentWord === word) {
      // Select the other word that shares this cell
      const others = Object.values(words).filter(w => w !== word);
      for (const o of others) {
        const isH = o.dir === 'h';
        if (isH && r === o.row && c >= o.col && c < o.col + o.letters.length) {
          currentWord = o;
          highlightWord(r, c);
          return;
        }
        if (!isH && c === o.col && r >= o.row && r < o.row + o.letters.length) {
          currentWord = o;
          highlightWord(r, c);
          return;
        }
      }
    }
    currentWord = word;
    highlightWord(r, c);
  }
}

function highlightWord(r, c) {
  // Clear all highlights
  document.querySelectorAll('.cell').forEach(cell => cell.classList.remove('highlight'));
  document.querySelectorAll('.clue-item').forEach(item => item.classList.remove('active'));

  const word = getWordForCell(r, c);
  if (!word) return;
  currentWord = word;

  // Highlight cells
  const isH = word.dir === 'h';
  for (let i = 0; i < word.letters.length; i++) {
    const cr = isH ? word.row : word.row + i;
    const cc = isH ? word.col + i : word.col;
    const cell = getCell(cr, cc);
    if (cell) cell.classList.add('highlight');
  }

  // Highlight clue
  const clueItem = document.querySelector(`.clue-item[data-word="${word.letters.toLowerCase()}"]`);
  if (clueItem) clueItem.classList.add('active');
}

function selectWord(name) {
  const word = words[name];
  if (!word) return;
  currentWord = word;
  highlightWord(word.row, word.col);
  const input = getInput(word.row, word.col);
  if (input) input.focus();
}

function checkAnswers() {
  let allCorrect = true;
  let filled = 0;
  let total = 0;

  document.querySelectorAll('.cell.white input').forEach(input => {
    total++;
    const val = input.value.toUpperCase();
    const answer = input.dataset.answer;
    input.classList.remove('correct', 'wrong');

    if (val) {
      filled++;
      if (val === answer) {
        input.classList.add('correct');
      } else {
        input.classList.add('wrong');
        allCorrect = false;
      }
    } else {
      allCorrect = false;
    }
  });

  const msg = document.getElementById('message');
  if (allCorrect && filled === total) {
    msg.textContent = '🎉 Félicitations ! Tous les mots sont corrects !';
    msg.className = 'message success';
  } else if (filled === 0) {
    msg.textContent = 'Remplissez d\'abord les cases...';
    msg.className = 'message info';
  } else {
    const wrongCount = document.querySelectorAll('.cell.white input.wrong').length;
    const emptyCount = total - filled;
    msg.textContent = `${wrongCount} erreur${wrongCount > 1 ? 's' : ''} et ${emptyCount} case${emptyCount > 1 ? 's' : ''} vide${emptyCount > 1 ? 's' : ''}`;
    msg.className = 'message error';
  }
}

function giveHint() {
  const word = currentWord;
  if (!word) {
    document.getElementById('message').textContent = 'Cliquez sur un mot ou une case d\'abord.';
    document.getElementById('message').className = 'message info';
    return;
  }
  const isH = word.dir === 'h';
  // Find first empty or wrong cell in the word
  for (let i = 0; i < word.letters.length; i++) {
    const r = isH ? word.row : word.row + i;
    const c = isH ? word.col + i : word.col;
    const input = getInput(r, c);
