            enemy.radius = 20; enemy.speed = 0.8 + wave * 0.05; enemy.health = 3 + Math.floor(wave / 3); enemy.maxHealth = enemy.health; enemy.score = 300;
            break;
        case 'shooter':
            enemy.radius = 15; enemy.speed = 1; enemy.health = 2; enemy.maxHealth = 2; enemy.score = 250;
            enemy.fireRate = Math.max(60, 120 - wave * 5);
            break;
    }

    enemies.push(enemy);
}

function spawnPowerup(x, y) {
    if (Math.random() > 0.15) return;
    const types = ['health', 'rapid', 'spread', 'shield'];
    powerups.push({
        x, y,
        type: types[Math.floor(Math.random() * types.length)],
        radius: 10,
        pulse: 0,
        life: 600
    });
}

function createExplosion(x, y, count, color, speed = 4) {
    for (let i = 0; i < count; i++) {
        const angle = (Math.PI * 2 / count) * i + Math.random() * 0.5;
        const spd = Math.random() * speed + 1;
        particles.push({
            x, y,
            vx: Math.cos(angle) * spd,
            vy: Math.sin(angle) * spd,
            life: 1,
            decay: Math.random() * 0.03 + 0.015,
            size: Math.random() * 4 + 1,
            color: color || `hsl(${Math.random() * 20}, 100%, ${50 + Math.random() * 30}%)`
        });
    }
}

function announceWave() {
    const el = document.getElementById('wave-announce');
    el.textContent = `WAVE ${wave}`;
    el.style.opacity = '1';
    el.style.transition = 'none';
    setTimeout(() => {
        el.style.transition = 'opacity 1.5s';
        el.style.opacity = '0';
