}

function resetGame() {
    player.x = canvas.width / 2;
    player.y = canvas.height / 2;
    player.vx = 0; player.vy = 0;
    player.health = 100;
    player.dashCooldown = 0;
    player.invincible = 0;
    player.trail = [];
    bullets = [];
    enemies = [];
    particles = [];
