}

function updateUI() {
    document.getElementById('score-display').textContent = `SCORE: ${score}`;
    document.getElementById('wave-number').textContent = `WAVE ${wave}`;
    document.getElementById('health-bar').style.width = `${Math.max(0, player.health)}%`;

