}

document.getElementById('start-btn').addEventListener('click', startGame);

// Game loop
let lastTime = 0;
let shootTimer = 0;

function update(dt) {
    if (!gameRunning) return;

    // Player movement
    let mx = 0, my = 0;
    if (keys['w'] || keys['arrowup']) my -= 1;
    if (keys['s'] || keys['arrowdown']) my += 1;
    if (keys['a'] || keys['arrowleft']) mx -= 1;
    if (keys['d'] || keys['arrowright']) mx += 1;

    if (mx || my) {
        const len = Math.sqrt(mx * mx + my * my);
        mx /= len; my /= len;
    }

    const spd = player.dashTimer > 0 ? player.speed * 3 : player.speed;
    player.vx += mx * spd * 0.3;
    player.vy += my * spd * 0.3;
    player.vx *= 0.88;
    player.vy *= 0.88;

    if (player.dashTimer > 0) player.dashTimer--;
    if (player.dashCooldown > 0) player.dashCooldown--;
    if (player.invincible > 0) player.invincible--;

    player.x += player.vx;
    player.y += player.vy;
    player.x = Math.max(player.radius, Math.min(canvas.width - player.radius, player.x));
    player.y = Math.max(player.radius, Math.min(canvas.height - player.radius, player.y));

    player.angle = Math.atan2(mouse.y - player.y, mouse.x - player.x);

    // Dash
    if (keys[' '] && player.dashCooldown <= 0) {
        player.dashTimer = 8;
        player.dashCooldown = 60;
        player.invincible = 10;
        playDash();
        createExplosion(player.x, player.y, 8, '#ff4444', 3);
    }

    // Trail
    player.trail.push({ x: player.x, y: player.y, life: 1 });
    if (player.trail.length > 15) player.trail.shift();
    player.trail.forEach(t => t.life -= 0.07);

    // Shooting
    shootTimer += dt;
    const rate = powerupActive === 'rapid' ? player.fireRate * 0.4 : player.fireRate;
    if (mouse.down && shootTimer >= rate) {
        shootTimer = 0;
        playShoot();

        const spread = powerupActive === 'spread';
        const angles = spread ? [player.angle - 0.2, player.angle, player.angle + 0.2] : [player.angle];

        angles.forEach(a => {
            bullets.push({
                x: player.x + Math.cos(a) * 20,
                y: player.y + Math.sin(a) * 20,
                vx: Math.cos(a) * 10,
                vy: Math.sin(a) * 10,
                life: 80,
                radius: 3,
                damage: 1
            });
        });
    }

    // Combo timer
    if (comboTimer > 0) {
        comboTimer--;
        if (comboTimer <= 0) combo = 0;
    }

    // Powerup timer
    if (powerupTimer > 0) {
        powerupTimer--;
        if (powerupTimer <= 0) powerupActive = null;
    }

    // Wave management
    waveTimer--;
    if (waveTimer <= 0 && waveEnemiesLeft <= 0) {
        wave++;
        waveTimer = 180;
        waveEnemiesLeft = 5 + wave * 3;
        announceWave();
        playSound(500, 0.3, 'sine', 0.06);
    }
    if (waveEnemiesLeft > 0 && waveTimer <= 90) {
        spawnEnemy();
        waveEnemiesLeft--;
    }

    // Update bullets
    bullets.forEach(b => {
        b.x += b.vx;
        b.y += b.vy;
        b.life--;
    });
    bullets = bullets.filter(b => b.life > 0 && b.x > -20 && b.x < canvas.width + 20 && b.y > -20 && b.y < canvas.height + 20);

    // Update enemies
    enemies.forEach(e => {
        const dx = player.x - e.x;
        const dy = player.y - e.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        e.angle = Math.atan2(dy, dx);

        if (e.type === 'shooter') {
            if (dist > 200) {
                e.x += (dx / dist) * e.speed;
                e.y += (dy / dist) * e.speed;
            } else if (dist < 150) {
                e.x -= (dx / dist) * e.speed;
                e.y -= (dy / dist) * e.speed;
            }
            e.fireTimer++;
            if (e.fireTimer >= e.fireRate) {
                e.fireTimer = 0;
                const bSpeed = 5;
                bullets.push({
                    x: e.x, y: e.y,
                    vx: Math.cos(e.angle) * bSpeed,
                    vy: Math.sin(e.angle) * bSpeed,
                    life: 100,
                    radius: 4,
                    damage: -1,
                    enemy: true
                });
                playSound(200, 0.1, 'sawtooth', 0.03);
            }
        } else {
            e.x += (dx / dist) * e.speed;
            e.y += (dy / dist) * e.speed;
        }

        if (e.flashTimer > 0) e.flashTimer--;
    });

    // Bullet-enemy collision
    bullets.forEach(b => {
        if (b.enemy) return;
        enemies.forEach(e => {
            const dx = b.x - e.x;
            const dy = b.y - e.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < b.radius + e.radius) {
                e.health -= b.damage;
                e.flashTimer = 5;
                b.life = 0;
                playHit();
                createExplosion(b.x, b.y, 5, '#ff4444', 2);

                if (e.health <= 0) {
                    combo++;
                    comboTimer = 120;
                    const points = e.score * (1 + Math.floor(combo / 5));
                    score += points;
                    createExplosion(e.x, e.y, e.type === 'tank' ? 25 : 15, null, e.type === 'tank' ? 6 : 4);
                    playExplosion();
                    shakeAmount = e.type === 'tank' ? 8 : 4;
                    spawnPowerup(e.x, e.y);
                }
            }
        });
    });

    // Enemy bullet - player collision
    bullets.forEach(b => {
        if (!b.enemy) return;
        const dx = b.x - player.x;
        const dy = b.y - player.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < b.radius + player.radius && player.invincible <= 0) {
            const dmg = powerupActive === 'shield' ? 5 : 15;
            player.health -= dmg;
            b.life = 0;
            player.invincible = 20;
            shakeAmount = 5;
            playHit();
            createExplosion(player.x, player.y, 8, '#ff0000', 3);
        }
    });

    // Enemy-player collision
    enemies.forEach(e => {
        const dx = e.x - player.x;
        const dy = e.y - player.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < e.radius + player.radius && player.invincible <= 0) {
            const dmg = powerupActive === 'shield' ? 10 : 25;
            player.health -= dmg;
            player.invincible = 30;
            shakeAmount = 6;
            playHit();
            createExplosion(player.x, player.y, 10, '#ff0000', 3);
            e.health -= 2;
        }
    });

    enemies = enemies.filter(e => e.health > 0);

    // Powerup collection
    powerups.forEach(p => {
        p.pulse += 0.05;
        p.life--;
        const dx = p.x - player.x;
        const dy = p.y - player.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < p.radius + player.radius + 10) {
            p.life = 0;
            playPowerup();
            switch(p.type) {
                case 'health':
                    player.health = Math.min(player.maxHealth, player.health + 30);
                    break;
                case 'rapid':
                    powerupActive = 'rapid';
                    powerupTimer = 600;
                    break;
                case 'spread':
                    powerupActive = 'spread';
                    powerupTimer = 600;
                    break;
                case 'shield':
                    powerupActive = 'shield';
                    powerupTimer = 480;
                    break;
            }
            createExplosion(p.x, p.y, 12, '#ffff00', 3);
        }
    });
    powerups = powerups.filter(p => p.life > 0);

    // Update particles
    particles.forEach(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.vx *= 0.97;
        p.vy *= 0.97;
        p.life -= p.decay;
    });
    particles = particles.filter(p => p.life > 0);

    // Background particles
    bgParticles.forEach(p => {
        p.y += p.speed;
        if (p.y > canvas.height) { p.y = 0; p.x = Math.random() * canvas.width; }
    });

    // Screen shake
    if (shakeAmount > 0) shakeAmount *= 0.9;
    if (shakeAmount < 0.1) shakeAmount = 0;

    // Check death
    if (player.health <= 0) {
        gameRunning = false;
        createExplosion(player.x, player.y, 40, '#ff0000', 8);
        playExplosion();
        setTimeout(() => {
            document.getElementById('start-screen').style.display = 'flex';
            document.querySelector('#start-screen h1').textContent = 'GAME OVER';
            document.querySelector('#start-screen .subtitle').textContent = `FINAL SCORE: ${score} — WAVE ${wave}`;
            document.getElementById('start-btn').textContent = 'RETRY';
        }, 1500);
    }

    updateUI();
}

function draw() {
    ctx.save();

    // Screen shake
    if (shakeAmount > 0) {
        ctx.translate(
            (Math.random() - 0.5) * shakeAmount * 2,
            (Math.random() - 0.5) * shakeAmount * 2
        );
    }

    // Background
    const bgGrad = ctx.createRadialGradient(canvas.width/2, canvas.height/2, 0, canvas.width/2, canvas.height/2, canvas.width * 0.7);
    bgGrad.addColorStop(0, '#1a0000');
    bgGrad.addColorStop(1, '#050000');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(-10, -10, canvas.width + 20, canvas.height + 20);

    // Grid lines
    ctx.strokeStyle = 'rgba(255, 0, 0, 0.04)';
    ctx.lineWidth = 1;
    const gridSize = 60;
    for (let x = 0; x < canvas.width; x += gridSize) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height); ctx.stroke();
    }
    for (let y = 0; y < canvas.height; y += gridSize) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(canvas.width, y); ctx.stroke();
    }

    // Background particles
    bgParticles.forEach(p => {
        ctx.fillStyle = `rgba(255, 0, 0, ${p.alpha})`;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
    });

    // Powerups
    powerups.forEach(p => {
        const pulseSize = p.radius + Math.sin(p.pulse) * 3;
        const colors = { health: '#ff4444', rapid: '#ff8800', spread: '#ff0088', shield: '#8844ff' };
        const c = colors[p.type];

        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.pulse);

        ctx.shadowColor = c;
        ctx.shadowBlur = 15;
        ctx.strokeStyle = c;
        ctx.lineWidth = 2;
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const a = (Math.PI * 2 / 6) * i;
            const px = Math.cos(a) * pulseSize;
            const py = Math.sin(a) * pulseSize;
            i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
        }
        ctx.closePath();
        ctx.stroke();

        ctx.fillStyle = c;
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const icons = { health: '+', rapid: '»', spread: '»»', shield: '◇' };
        ctx.fillText(icons[p.type], 0, 0);

        ctx.restore();
    });

    // Player trail
    player.trail.forEach((t, i) => {
        if (t.life <= 0) return;
        ctx.fillStyle = `rgba(255, 0, 0, ${t.life * 0.3})`;
        ctx.beginPath();
        ctx.arc(t.x, t.y, player.radius * t.life * 0.5, 0, Math.PI * 2);
        ctx.fill();
    });

    // Player
    if (gameRunning || player.health > 0) {
        ctx.save();
        ctx.translate(player.x, player.y);
        ctx.rotate(player.angle);

        if (player.invincible > 0 && Math.floor(player.invincible / 3) % 2 === 0) {
            ctx.globalAlpha = 0.4;
        }

        // Glow
        ctx.shadowColor = '#ff0000';
        ctx.shadowBlur = 20;

        // Ship body
        ctx.fillStyle = '#ff0000';
        ctx.beginPath();
        ctx.moveTo(18, 0);
        ctx.lineTo(-12, -10);
        ctx.lineTo(-6, 0);
        ctx.lineTo(-12, 10);
        ctx.closePath();
        ctx.fill();

        ctx.fillStyle = '#ff4444';
        ctx.beginPath();
        ctx.moveTo(18, 0);
        ctx.lineTo(-6, -5);
        ctx.lineTo(-6, 5);
        ctx.closePath();
        ctx.fill();

        // Engine glow
        ctx.fillStyle = '#ff6644';
        ctx.beginPath();
        ctx.arc(-8, 0, 4 + Math.random() * 2, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();

        // Shield effect
        if (powerupActive === 'shield') {
            ctx.strokeStyle = `rgba(136, 68, 255, ${0.3 + Math.sin(Date.now() * 0.01) * 0.2})`;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(player.x, player.y, player.radius + 10, 0, Math.PI * 2);
            ctx.stroke();
        }
    }

    // Bullets
    bullets.forEach(b => {
        if (b.enemy) {
            ctx.fillStyle = '#ff4400';
            ctx.shadowColor = '#ff4400';
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
        } else {
            ctx.fillStyle = '#ff2222';
            ctx.shadowColor = '#ff0000';
            ctx.shadowBlur = 12;
            ctx.beginPath();
            ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
            ctx.fill();

            // Bullet trail
            ctx.strokeStyle = 'rgba(255, 0, 0, 0.4)';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(b.x, b.y);
            ctx.lineTo(b.x - b.vx * 2, b.y - b.vy * 2);
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
    });

    // Enemies
    enemies.forEach(e => {
        ctx.save();
        ctx.translate(e.x, e.y);
        ctx.rotate(e.angle);

        const flash = e.flashTimer > 0;
        const baseColor = flash ? '#ffffff' : (e.type === 'tank' ? '#880000' : e.type === 'fast' ? '#ff4400' : e.type === 'shooter' ? '#cc0033' : '#ff0000');
        const lightColor = flash ? '#ffcccc' : (e.type === 'tank' ? '#aa2222' : e.type === 'fast' ? '#ff6644' : e.type === 'shooter' ? '#ee2244' : '#ff3333');

        ctx.shadowColor = baseColor;
        ctx.shadowBlur = 15;

        // Body
        ctx.fillStyle = baseColor;
        if (e.type === 'tank') {
            ctx.beginPath();
            ctx.arc(0, 0, e.radius, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = lightColor;
            ctx.beginPath();
            ctx.arc(0, 0, e.radius * 0.6, 0, Math.PI * 2);
            ctx.fill();
        } else if (e.type === 'fast') {
            ctx.beginPath();
            ctx.moveTo(e.radius, 0);
            ctx.lineTo(-e.radius * 0.7, -e.radius * 0.6);
            ctx.lineTo(-e.radius * 0.4, 0);
            ctx.lineTo(-e.radius * 0.7, e.radius * 0.6);
            ctx.closePath();
            ctx.fill();
        } else if (e.type === 'shooter') {
            ctx.fillRect(-e.radius, -e.radius, e.radius * 2, e.radius * 2);
            ctx.fillStyle = lightColor;
            ctx.fillRect(-e.radius * 0.5, -e.radius * 0.5, e.radius, e.radius);
        } else {
            ctx.beginPath();
            ctx.moveTo(e.radius, 0);
            ctx.lineTo(-e.radius * 0.6, -e.radius * 0.7);
            ctx.lineTo(-e.radius * 0.3, 0);
            ctx.lineTo(-e.radius * 0.6, e.radius * 0.7);
            ctx.closePath();
            ctx.fill();
        }

        // Health bar for tanks
        if (e.type === 'tank' && e.health < e.maxHealth) {
            ctx.rotate(-e.angle);
            const barW = e.radius * 2;
            ctx.fillStyle = '#330000';
            ctx.fillRect(-barW/2, -e.radius - 10, barW, 4);
            ctx.fillStyle = '#ff0000';
            ctx.fillRect(-barW/2, -e.radius - 10, barW * (e.health / e.maxHealth), 4);
        }

        ctx.restore();
    });

    // Particles
    particles.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;

    // Custom cursor
    if (gameRunning) {
        ctx.strokeStyle = '#ff0000';
        ctx.lineWidth = 1.5;
        ctx.shadowColor = '#ff0000';
        ctx.shadowBlur = 8;
        const cs = 12;
        ctx.beginPath();
        ctx.moveTo(mouse.x - cs, mouse.y); ctx.lineTo(mouse.x - cs/3, mouse.y);
        ctx.moveTo(mouse.x + cs/3, mouse.y); ctx.lineTo(mouse.x + cs, mouse.y);
        ctx.moveTo(mouse.x, mouse.y - cs); ctx.lineTo(mouse.x, mouse.y - cs/3);
        ctx.moveTo(mouse.x, mouse.y + cs/3); ctx.lineTo(mouse.x, mouse.y + cs);
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(mouse.x, mouse.y, 3, 0, Math.PI * 2);
        ctx.stroke();
        ctx.shadowBlur = 0;
    }

    // Vignette
    const vigGrad = ctx.createRadialGradient(canvas.width/2, canvas.height/2, canvas.height * 0.3, canvas.width/2, canvas.height/2, canvas.width * 0.8);
    vigGrad.addColorStop(0, 'transparent');
    vigGrad.addColorStop(1, 'rgba(0, 0, 0, 0.5)');
    ctx.fillStyle = vigGrad;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.restore();
}

function gameLoop(timestamp) {
    const dt = Math.min(timestamp - lastTime, 33);
    lastTime = timestamp;

    update(dt);
    draw();

    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
