let musicEnabled = false;
let currentScene = 0;
let sceneNames = ['🌸 Garden', '🌅 Sunset Beach', '🌙 Moonlit Park', '🌺 Flower Field'];

const scenes = [
{ sky1: '#87CEEB', sky2: '#E0F7FA', ground: '#4CAF50', ground2: '#388E3C', flowers: true, stars: false, sun: true, water: false, fireflies: false, snow: false },
{ sky1: '#FF6B35', sky2: '#FFD700', ground: '#F4D03F', ground2: '#E8C840', flowers: false, stars: false, sun: true, water: true, fireflies: false, snow: false },
{ sky1: '#0a0a2e', sky2: '#1a1a4e', ground: '#2d5a27', ground2: '#1e3d1a', flowers: false, stars: true, sun: false, water: false, fireflies: true, snow: false },
{ sky1: '#FFB6C1', sky2: '#FFC0CB', ground: '#90EE90', ground2: '#76C776', flowers: true, stars: false, sun: true, water: false, fireflies: false, snow: false }
];

let hearts = [];
let musicNotes = [];
let particles = [];
let firefliesArr = [];
let petals = [];

for (let i = 0; i < 30; i++) {
firefliesArr.push({ x: Math.random() * 900, y: Math.random() * 400 + 100, size: Math.random() * 3 + 1, speed: Math.random() * 0.5 + 0.2, angle: Math.random() * Math.PI * 2 });
}

for (let i = 0; i < 20; i++) {
petals.push({ x: Math.random() * 900, y: Math.random() * 600, size: Math.random() * 4 + 2, speedX: Math.random() * 1 - 0.5, speedY: Math.random() * 1 + 0.5, rotation: Math.random() * Math.PI * 2, rotSpeed: Math.random() * 0.03 - 0.015 });
}

function drawBackground() {
const scene = scenes[currentScene];

// Sky gradient
let skyGrad = ctx.createLinearGradient(0, 0, 0, 400);
skyGrad.addColorStop(0, scene.sky1);
skyGrad.addColorStop(1, scene.sky2);
ctx.fillStyle = skyGrad;
ctx.fillRect(0, 0, 900, 400);

// Stars
if (scene.stars) {
for (let i = 0; i < 80; i++) {
let twinkle = Math.sin(time * 3 + i) * 0.5 + 0.5;
ctx.fillStyle = `rgba(255,255,255,${twinkle})`;
ctx.beginPath();
ctx.arc((i * 137.5) % 900, (i * 73.1) % 350, Math.random() * 1.5 + 0.5, 0, Math.PI * 2);
ctx.fill();
}
}

// Moon or Sun
if (scene.sun) {
if (currentScene === 2) {
// Moon
ctx.fillStyle = '#FFFACD';
ctx.beginPath();
ctx.arc(750, 80, 35, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#0a0a2e';
ctx.beginPath();
ctx.arc(765, 70, 30, 0, Math.PI * 2);
ctx.fill();
} else {
// Sun
let sunGrad = ctx.createRadialGradient(100, 80, 10, 100, 80, 60);
sunGrad.addColorStop(0, '#FFFDE7');
sunGrad.addColorStop(0.5, '#FFD700');
sunGrad.addColorStop(1, 'rgba(255,215,0,0)');
ctx.fillStyle = sunGrad;
ctx.beginPath();
ctx.arc(100, 80, 60, 0, Math.PI * 2);
ctx.fill();

ctx.fillStyle = '#FFF176';
ctx.beginPath();
ctx.arc(100, 80, 25, 0, Math.PI * 2);
ctx.fill();
}
}

// Clouds
for (let i = 0; i < 5; i++) {
let cx = (i * 200 + time * 15) % 1000 - 50;
let cy = 50 + i * 30;
drawCloud(cx, cy, 0.7 + i * 0.1);
}

// Water
if (scene.water) {
let waterGrad = ctx.createLinearGradient(0, 380, 0, 420);
waterGrad.addColorStop(0, 'rgba(30,144,255,0.6)');
waterGrad.addColorStop(1, 'rgba(30,144,255,0.3)');
ctx.fillStyle = waterGrad;
ctx.fillRect(0, 380, 900, 40);
for (let i = 0; i < 10; i++) {
ctx.strokeStyle = `rgba(255,255,255,${0.2 + Math.sin(time * 2 + i) * 0.15})`;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(i * 100 + Math.sin(time + i) * 10, 395 + Math.sin(time * 1.5 + i) * 3);
ctx.lineTo(i * 100 + 80 + Math.sin(time + i + 1) * 10, 395 + Math.sin(time * 1.5 + i + 1) * 3);
ctx.stroke();
}
}

// Ground
let groundGrad = ctx.createLinearGradient(0, 400, 0, 600);
groundGrad.addColorStop(0, scene.ground);
groundGrad.addColorStop(1, scene.ground2);
ctx.fillStyle = groundGrad;
ctx.beginPath();
ctx.moveTo(0, 420);
for (let x = 0; x <= 900; x += 50) {
ctx.lineTo(x, 420 + Math.sin(x * 0.02 + time * 0.5) * 5);
}
ctx.lineTo(900, 600);
ctx.lineTo(0, 600);
ctx.closePath();
ctx.fill();

// Grass blades
for (let i = 0; i < 60; i++) {
let gx = i * 15 + Math.sin(i) * 5;
let gy = 430 + Math.sin(gx * 0.05) * 3;
ctx.strokeStyle = scene.ground;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(gx, gy);
ctx.quadraticCurveTo(gx + Math.sin(time * 2 + i) * 5, gy - 15, gx + Math.sin(time * 2 + i) * 8, gy - 25);
ctx.stroke();
}

// Flowers
if (scene.flowers) {
for (let i = 0; i < 15; i++) {
let fx = (i * 65 + 30) % 900;
let fy = 440 + Math.sin(fx * 0.03) * 5;
drawFlower(fx, fy, ['#FF69B4', '#FF1493', '#FF6347', '#FFD700', '#FF4500'][i % 5], i);
}
}

// Trees
for (let i = 0; i < 4; i++) {
let tx = 80 + i * 220;
let ty = 380;
drawTree(tx, ty, currentScene);
}

// Fireflies
if (scene.fireflies) {
firefliesArr.forEach(f => {
f.x += Math.sin(time + f.angle) * f.speed;
f.y += Math.cos(time * 0.7 + f.angle) * f.speed;
f.angle += 0.02;
if (f.x < 0) f.x = 900;
if (f.x > 900) f.x = 0;
if (f.y < 200) f.y = 400;
if (f.y > 450) f.y = 200;
let glow = Math.sin(time * 4 + f.angle) * 0.5 + 0.5;
ctx.fillStyle = `rgba(255,255,100,${glow})`;
ctx.beginPath();
ctx.arc(f.x, f.y, f.size, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = `rgba(255,255,100,${glow * 0.3})`;
ctx.beginPath();
ctx.arc(f.x, f.y, f.size * 3, 0, Math.PI * 2);
ctx.fill();
});
}

// Falling petals
if (scene.flowers) {
petals.forEach(p => {
p.x += p.speedX + Math.sin(time + p.y * 0.01) * 0.5;
p.y += p.speedY;
p.rotation += p.rotSpeed;
if (p.y > 600) { p.y = -10; p.x = Math.random() * 900; }
if (p.x > 900) p.x = 0;
if (p.x < 0) p.x = 900;
ctx.save();
ctx.translate(p.x, p.y);
ctx.rotate(p.rotation);
ctx.fillStyle = '#FFB7C5';
ctx.beginPath();
ctx.ellipse(0, 0, p.size, p.size * 0.6, 0, 0, Math.PI * 2);
ctx.fill();
ctx.restore();
});
}

// Ground flowers (small)
for (let i = 0; i < 25; i++) {
let gx = (i * 37 + 10) % 900;
let gy = 500 + Math.sin(gx * 0.05) * 10;
ctx.fillStyle = ['#FF69B4', '#FFD700', '#FF6347', '#FFFFFF', '#DDA0DD'][i % 5];
ctx.beginPath();
ctx.arc(gx, gy, 3, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#228B22';
ctx.fillRect(gx - 0.5, gy, 1, 8);
}
}

function drawCloud(x, y, scale) {
ctx.fillStyle = 'rgba(255,255,255,0.8)';
ctx.beginPath();
ctx.arc(x, y, 20 * scale, 0, Math.PI * 2);
ctx.arc(x + 20 * scale, y - 10 * scale, 25 * scale, 0, Math.PI * 2);
ctx.arc(x + 45 * scale, y, 20 * scale, 0, Math.PI * 2);
ctx.arc(x + 20 * scale, y + 5 * scale, 18 * scale, 0, Math.PI * 2);
ctx.fill();
}

function drawFlower(x, y, color, idx) {
ctx.strokeStyle = '#228B22';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x, y);
ctx.lineTo(x, y + 20);
ctx.stroke();

for (let p = 0; p < 5; p++) {
let angle = (p / 5) * Math.PI * 2 + time * 0.5;
ctx.fillStyle = color;
ctx.beginPath();
ctx.ellipse(x + Math.cos(angle) * 6, y + Math.sin(angle) * 6, 5, 3, angle, 0, Math.PI * 2);
ctx.fill();
}
ctx.fillStyle = '#FFD700';
ctx.beginPath();
ctx.arc(x, y, 3, 0, Math.PI * 2);
ctx.fill();
}

function drawTree(x, y, sceneIdx) {
// Trunk
ctx.fillStyle = '#8B4513';
ctx.fillRect(x - 10, y - 60, 20, 60);

// Leaves
let leafColor = sceneIdx === 2 ? '#1a4a1a' : '#2E7D32';
ctx.fillStyle = leafColor;
ctx.beginPath();
ctx.arc(x, y - 80, 35, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(x - 20, y - 60, 25, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(x + 20, y - 60, 25, 0, Math.PI * 2);
ctx.fill();

if (scenes[currentScene].flowers) {
for (let i = 0; i < 6; i++) {
let fx = x + Math.cos(i * 1.05) * 20;
let fy = y - 75 + Math.sin(i * 1.05) * 15;
ctx.fillStyle = ['#FF69B4', '#FF1493', '#FFD700'][i % 3];
ctx.beginPath();
ctx.arc(fx, fy, 3, 0, Math.PI * 2);
ctx.fill();
}
}
}

function drawBoy(x, y, t) {
let dancePhase = Math.sin(t * 3);
let dancePhase2 = Math.cos(t * 3);
let bounce = Math.abs(Math.sin(t * 3)) * 8;

ctx.save();
ctx.translate(x, y - bounce);

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.2)';
ctx.beginPath();
ctx.ellipse(0, 0, 25, 8, 0, 0, Math.PI * 2);
ctx.fill();

// Legs
ctx.strokeStyle = '#1a237e';
ctx.lineWidth = 6;
ctx.lineCap = 'round';

// Left leg
ctx.beginPath();
ctx.moveTo(-8, -30);
ctx.lineTo(-8 + dancePhase * 15, -10);
ctx.lineTo(-8 + dancePhase * 15 - dancePhase2 * 5, 0);
ctx.stroke();

// Right leg
ctx.beginPath();
ctx.moveTo(8, -30);
ctx.lineTo(8 - dancePhase * 15, -10);
ctx.lineTo(8 - dancePhase * 15 + dancePhase2 * 5, 0);
ctx.stroke();

// Shoes
ctx.fillStyle = '#333';
ctx.beginPath();
ctx.ellipse(-8 + dancePhase * 15 - dancePhase2 * 5, 2, 7, 4, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(8 - dancePhase * 15 + dancePhase2 * 5, 2, 7, 4, 0, 0, Math.PI * 2);
ctx.fill();

// Body (shirt)
ctx.fillStyle = '#FF6B35';
ctx.beginPath();
ctx.moveTo(-15, -30);
ctx.lineTo(15, -30);
ctx.lineTo(12, -65);
ctx.lineTo(-12, -65);
ctx.closePath();
ctx.fill();

// Shirt detail
ctx.strokeStyle = '#E65100';
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(0, -30);
ctx.lineTo(0, -65);
ctx.stroke();

// Arms
ctx.strokeStyle = '#D2691E';
ctx.lineWidth = 5;

// Left arm (reaching toward girl)
ctx.beginPath();
ctx.moveTo(-12, -58);
ctx.lineTo(-25 + dancePhase2 * 10, -50 + dancePhase * 5);
ctx.stroke();

// Right arm
ctx.beginPath();
ctx.moveTo(12, -58);
ctx.lineTo(25 - dancePhase2 * 10, -50 - dancePhase * 5);
ctx.stroke();

// Hands
ctx.fillStyle = '#D2691E';
ctx.beginPath();
ctx.arc(-25 + dancePhase2 * 10, -50 + dancePhase * 5, 4, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(25 - dancePhase2 * 10, -50 - dancePhase * 5, 4, 0, Math.PI * 2);
ctx.fill();

// Head
ctx.fillStyle = '#D2691E';
ctx.beginPath();
ctx.arc(0, -78, 14, 0, Math.PI * 2);
ctx.fill();

// Hair
ctx.fillStyle = '#1a1a1a';
ctx.beginPath();
ctx.arc(0, -82, 14, Math.PI, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(0, -88, 12, 6, 0, 0, Math.PI * 2);
ctx.fill();

// Eyes
ctx.fillStyle = 'white';
ctx.beginPath();
ctx.ellipse(-5, -78, 4, 3, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(5, -78, 4, 3, 0, 0, Math.PI * 2);
ctx.fill();

ctx.fillStyle = '#1a1a1a';
ctx.beginPath();
ctx.arc(-4, -78, 2, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(6, -78, 2, 0, Math.PI * 2);
ctx.fill();

// Smile
ctx.strokeStyle = '#8B4513';
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(0, -74, 6, 0.1, Math.PI - 0.1);
ctx.stroke();

// Eyebrows
ctx.strokeStyle = '#1a1a1a';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(-9, -83);
ctx.lineTo(-2, -84);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(2, -84);
ctx.lineTo(9, -83);
ctx.stroke();

ctx.restore();
}

function drawGirl(x, y, t) {
let dancePhase = Math.sin(t * 3);
let dancePhase2 = Math.cos(t * 3);
let bounce = Math.abs(Math.sin(t * 3)) * 8;

ctx.save();
ctx.translate(x, y - bounce);

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.2)';
ctx.beginPath();
ctx.ellipse(0, 0, 25, 8, 0, 0, Math.PI * 2);
