ctx.moveTo(6, -30);
ctx.lineTo(6 - dancePhase * 12, -10);
ctx.lineTo(6 - dancePhase * 12 + dancePhase2 * 4, 0);
ctx.stroke();

// Shoes (heels)
ctx.fillStyle = '#FF1493';
ctx.beginPath();
ctx.ellipse(-6 + dancePhase * 12 - dancePhase2 * 4, 2, 5, 3, 0, 0, Math.PI * 2);
