// Right arm (raised)
ctx.beginPath();
ctx.moveTo(10, -60);
ctx.lineTo(22 + dancePhase2 * 8, -75 - dancePhase * 8);
ctx.stroke();

// Hands
ctx.fillStyle = '#F5DEB3';
ctx.beginPath();
ctx.arc(-22 - dancePhase2 * 8, -52 + dancePhase * 5, 3.5, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(22 + dancePhase2 * 8, -75 - dancePhase * 8, 3.5, 0, Math.PI * 2);
ctx.fill();

// Head
ctx.fillStyle = '#F5DEB3';
ctx.beginPath();
ctx.arc(0, -80, 13, 0, Math.PI * 2);
ctx.fill();

// Hair (long flowing)
ctx.fillStyle = '#1a1a1a';
ctx.beginPath();
ctx.arc(0, -85, 14, Math.PI, Math.PI * 2);
ctx.fill();

// Long hair flowing
ctx.beginPath();
ctx.moveTo(-14, -85);
ctx.quadraticCurveTo(-18, -60 + Math.sin(t * 2) * 5, -15, -45);
ctx.quadraticCurveTo(-12, -40, -10, -45);
ctx.quadraticCurveTo(-10, -60, -10, -85);
ctx.fill();

ctx.beginPath();
ctx.moveTo(14, -85);
ctx.quadraticCurveTo(18, -60 + Math.cos(t * 2) * 5, 15, -45);
ctx.quadraticCurveTo(12, -40, 10, -45);
ctx.quadraticCurveTo(10, -60, 10, -85);
ctx.fill();

// Hair accessory
ctx.fillStyle = '#FF1493';
ctx.beginPath();
ctx.arc(10, -88, 4, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#FF69B4';
ctx.beginPath();
ctx.arc(10, -88, 2, 0, Math.PI * 2);
ctx.fill();

// Eyes
ctx.fillStyle = 'white';
ctx.beginPath();
ctx.ellipse(-4, -80, 4, 3.5, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(5, -80, 4, 3.5, 0, 0, Math.PI * 2);
ctx.fill();

ctx.fillStyle = '#1a1a1a';
ctx.beginPath();
ctx.arc(-3, -80, 2, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(6, -80, 2, 0, Math.PI * 2);
ctx.fill();

// Eyelashes
ctx.strokeStyle = '#1a1a1a';
ctx.lineWidth = 1;
for (let i = -1; i <= 1; i++) {
ctx.beginPath();
ctx.moveTo(-7, -82 + i * 2);
ctx.lineTo(-9, -84 + i * 2);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(8, -82 + i * 2);
ctx.lineTo(10, -84 + i * 2);
ctx.stroke();
}

// Blush
ctx.fillStyle = 'rgba(255,100,100,0.3)';
ctx.beginPath();
ctx.ellipse(-8, -76, 4, 2.5, 0, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.ellipse(8, -76, 4, 2.5, 0, 0, Math.PI * 2);
ctx.fill();

// Smile
ctx.strokeStyle = '#C0392B';
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(0, -76, 5, 0.2, Math.PI - 0.2);
ctx.stroke();

ctx.restore();
}

function drawHearts() {
if (!heartsEnabled) return;

if (Math.random() < 0.03) {
hearts.push({
x: 350 + Math.random() * 200,
y: 350,
size: Math.random() * 10 + 5,
speed: Math.random() * 1.5 + 0.5,
opacity: 1,
wobble: Math.random() * Math.PI * 2
});
}

hearts.forEach((h, i) => {
h.y -= h.speed;
h.x += Math.sin(h.wobble + time * 2) * 0.5;
h.opacity -= 0.005;

if (h.opacity <= 0) {
hearts.splice(i, 1);
return;
}

ctx.save();
ctx.translate(h.x, h.y);
ctx.fillStyle = `rgba(255,${100 + Math.sin(time * 3 + i) * 50},150,${h.opacity})`;
ctx.beginPath();
let s = h.size;
ctx.moveTo(0, s * 0.3);
ctx.bezierCurveTo(-s * 0.5, -s * 0.3, -s, s * 0.1, 0, s);
ctx.bezierCurveTo(s, s * 0.1, s * 0.5, -s * 0.3, 0, s * 0.3);
ctx.fill();
ctx.restore();
});
}

function drawMusicNotes() {
if (musicEnabled && Math.random() < 0.05) {
musicNotes.push({
x: 300 + Math.random() * 300,
y: 300,
size: Math.random() * 8 + 6,
speed: Math.random() * 1 + 0.5,
opacity: 1,
type: Math.random() > 0.5 ? '♪' : '♫'
});
}

musicNotes.forEach((n, i) => {
n.y -= n.speed;
n.opacity -= 0.008;

if (n.opacity <= 0) {
musicNotes.splice(i, 1);
return;
}

ctx.save();
ctx.translate(n.x, n.y);
ctx.fillStyle = `rgba(255,215,0,${n.opacity})`;
ctx.font = `${n.size * 2}px serif`;
ctx.fillText(n.type, 0, 0);
ctx.restore();
});
}

function drawSpotlight() {
let grad = ctx.createRadialGradient(450, 300, 20, 450, 300, 250);
grad.addColorStop(0, 'rgba(255,255,255,0.08)');
grad.addColorStop(1, 'rgba(255,255,255,0)');
ctx.fillStyle = grad;
ctx.beginPath();
ctx.arc(450, 300, 250, 0, Math.PI * 2);
ctx.fill();
}

function drawSparkles() {
for (let i = 0; i < 15; i++) {
let sx = 350 + Math.sin(time * 2 + i * 0.7) * 120;
let sy = 250 + Math.cos(time * 1.5 + i * 0.5) * 100;
let sparkle = Math.sin(time * 5 + i) * 0.5 + 0.5;

ctx.fillStyle = `rgba(255,255,255,${sparkle * 0.8})`;
ctx.save();
ctx.translate(sx, sy);
ctx.rotate(time * 2 + i);

// 4-point star
ctx.beginPath();
for (let p = 0; p < 4; p++) {
let angle = (p / 4) * Math.PI * 2;
ctx.lineTo(Math.cos(angle) * 6, Math.sin(angle) * 6);
let midAngle = angle + Math.PI / 4;
ctx.lineTo(Math.cos(midAngle) * 2, Math.sin(midAngle) * 2);
}
ctx.closePath();
ctx.fill();
ctx.restore();
}
}

function drawGroundShadow() {
ctx.fillStyle = 'rgba(0,0,0,0.15)';
ctx.beginPath();
ctx.ellipse(450, 440, 100, 15, 0, 0, Math.PI * 2);
ctx.fill();
}

function animate() {
time += 0.016;
ctx.clearRect(0, 0, 900, 600);

drawBackground();
drawSpotlight();
drawSparkles();
drawGroundShadow();

// Draw couple dancing
let boyX = 400;
let girlX = 500;
let baseY = 435;

drawBoy(boyX, baseY, time);
drawGirl(girlX, baseY, time);

// Draw them holding hands (visual connection)
let handY = baseY - 55 + Math.abs(Math.sin(time * 3)) * -8;
let handX = 450 + Math.sin(time * 3) * 5;
ctx.strokeStyle = 'rgba(255,255,255,0.5)';
ctx.lineWidth = 2;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(boyX + 25 - Math.cos(time * 3) * 10, handY);
ctx.lineTo(girlX - 22 - Math.cos(time * 3) * 8, handY);
ctx.stroke();
ctx.setLineDash([]);

// Heart between them
let heartSize = 8 + Math.sin(time * 4) * 3;
ctx.fillStyle = `rgba(255,${50 + Math.sin(time * 3) * 30},100,${0.6 + Math.sin(time * 3) * 0.3})`;
ctx.save();
ctx.translate(handX, handY - 20);
ctx.beginPath();
ctx.moveTo(0, heartSize * 0.3);
ctx.bezierCurveTo(-heartSize * 0.5, -heartSize * 0.3, -heartSize, heartSize * 0.1, 0, heartSize);
ctx.bezierCurveTo(heartSize, heartSize * 0.1, heartSize * 0.5, -heartSize * 0.3, 0, heartSize * 0.3);
ctx.fill();
ctx.restore();

drawHearts();
drawMusicNotes();

// Scene indicator
ctx.fillStyle = 'rgba(0,0,0,0.5)';
ctx.fillRect(350, 560, 200, 30);
ctx.fillStyle = 'white';
ctx.font = '14px sans-serif';
ctx.textAlign = 'center';
ctx.fillText(sceneNames[currentScene], 450, 580);

requestAnimationFrame(animate);
}

function toggleMusic() {
musicEnabled = !musicEnabled;
}

function changeScene() {
currentScene = (currentScene + 1) % scenes.length;
}

function toggleHearts() {
heartsEnabled = !heartsEnabled;
}

animate();
</script>
</body>
