</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Responsive sizing
let W, H;
function resize() {
W = canvas.width = Math.min(window.innerWidth, 500);
H = canvas.height = Math.min(window.innerHeight, 800);
}
resize();
window.addEventListener('resize', resize);

// Game state
let gameState = 'start'; // start, playing, over
let score = 0;
let coins = 0;
let totalCoins = 0;
let speed = 6;
let maxSpeed = 16;
let distance = 0;
let frameCount = 0;

// Perspective constants
const VANISH_Y = 0.35; // vanishing point Y ratio
const ROAD_WIDTH_BOTTOM = 0.85;
const ROAD_WIDTH_TOP = 0.08;
const LANE_COUNT = 3;

// Player
const player = {
lane: 1, // 0, 1, 2
targetLane: 1,
x: 0,
y: 0,
z: 100, // player fixed z position
width: 40,
height: 70,
jumping: false,
jumpVel: 0,
jumpHeight: 0,
sliding: false,
slideTimer: 0,
slideDuration: 30,
animFrame: 0,
animTimer: 0,
invincible: 0,
};

// Arrays
let obstacles = [];
let coinItems = [];
let particles = [];
let trackLines = [];
let buildings = [];
let clouds = [];

// Colors
const COLORS = {
sky1: '#0f0c29',
sky2: '#302b63',
sky3: '#24243e',
road: '#3a3a4a',
roadLine: '#555566',
rail: '#666677',
player: '#00ff88',
playerDark: '#00aa55',
obstacleTrain: '#cc3333',
obstacleBarrier: '#ff8800',
coin: '#ffd700',
};

function getLaneX(lane, z) {
const t = Math.max(0, Math.min(1, z / 2000));
const roadW = W * (ROAD_WIDTH_BOTTOM + (ROAD_WIDTH_TOP - ROAD_WIDTH_BOTTOM) * t);
const centerX = W / 2;
const laneWidth = roadW / LANE_COUNT;
const laneOffset = (lane - 1) * laneWidth;
return centerX + laneOffset;
}

function getRoadY(z) {
const t = Math.max(0, Math.min(1, z / 2000));
return H * VANISH_Y + (H - H * VANISH_Y) * t;
}

function getScale(z) {
const t = Math.max(0, Math.min(1, z / 2000));
return 0.1 + 0.9 * t;
}

function project(x, y, z) {
const scale = getScale(z);
const roadY = getRoadY(z);
const laneX = getLaneX(x, z);
return {
x: laneX,
y: roadY + (H - roadY) * (1 - scale) - y * scale,
scale: scale,
};
}

// Initialize background elements
function initBuildings() {
buildings = [];
for (let i = 0; i < 20; i++) {
buildings.push({
x: Math.random() < 0.5 ? -1 : 1,
z: Math.random() * 2000,
width: 30 + Math.random() * 60,
height: 80 + Math.random() * 200,
color: `hsl(${220 + Math.random()*40}, 30%, ${15 + Math.random()*15}%)`,
windows: Math.floor(Math.random() * 4) + 2,
});
}
}

function initClouds() {
clouds = [];
for (let i = 0; i < 8; i++) {
clouds.push({
x: Math.random() * W,
y: 20 + Math.random() * 80,
size: 20 + Math.random() * 40,
speed: 0.2 + Math.random() * 0.3,
});
}
}

function resetGame() {
score = 0;
coins = 0;
speed = 6;
distance = 0;
frameCount = 0;
player.lane = 1;
player.targetLane = 1;
player.x = 1;
player.jumping = false;
player.jumpVel = 0;
player.jumpHeight = 0;
player.sliding = false;
player.slideTimer = 0;
player.invincible = 0;
obstacles = [];
coinItems = [];
particles = [];
initBuildings();
initClouds();
}

// Spawn obstacles
function spawnObstacle() {
const lane = Math.floor(Math.random() * 3);
const type = Math.random();
if (type < 0.5) {
// Train
obstacles.push({
type: 'train',
lane: lane,
z: 2000,
width: 50,
height: 80,
color: ['#cc3333', '#3366cc', '#33aa33', '#cc8833', '#8833cc'][Math.floor(Math.random()*5)],
});
} else if (type < 0.75) {
// Low barrier (must jump)
obstacles.push({
type: 'barrier_low',
lane: lane,
z: 2000,
width: 45,
height: 30,
color: '#ff8800',
});
} else {
// High barrier (must slide)
obstacles.push({
type: 'barrier_high',
lane: lane,
z: 2000,
width: 45,
height: 55,
color: '#ff4444',
});
}
}

function spawnCoin() {
const lane = Math.floor(Math.random() * 3);
const count = 3 + Math.floor(Math.random() * 5);
for (let i = 0; i < count; i++) {
coinItems.push({
lane: lane,
z: 2000 + i * 60,
collected: false,
bobOffset: Math.random() * Math.PI * 2,
});
}
}

// Input handling
const keys = {};
window.addEventListener('keydown', (e) => {
if (gameState !== 'playing') return;
switch(e.key) {
case 'ArrowLeft':
case 'a':
if (player.targetLane > 0) player.targetLane--;
e.preventDefault();
break;
case 'ArrowRight':
case 'd':
if (player.targetLane < 2) player.targetLane++;
e.preventDefault();
break;
case 'ArrowUp':
case 'w':
case ' ':
if (!player.jumping) {
player.jumping = true;
player.jumpVel = -14;
}
e.preventDefault();
break;
case 'ArrowDown':
case 's':
if (!player.sliding && !player.jumping) {
player.sliding = true;
player.slideTimer = player.slideDuration;
}
e.preventDefault();
break;
}
});

// Touch controls
let touchStartX = 0, touchStartY = 0;
canvas.addEventListener('touchstart', (e) => {
touchStartX = e.touches[0].clientX;
touchStartY = e.touches[0].clientY;
e.preventDefault();
});
canvas.addEventListener('touchend', (e) => {
if (gameState !== 'playing') return;
const dx = e.changedTouches[0].clientX - touchStartX;
const dy = e.changedTouches[0].clientY - touchStartY;
const absDx = Math.abs(dx);
const absDy = Math.abs(dy);
if (absDx < 10 && absDy < 10) return;
if (absDx > absDy) {
if (dx > 30 && player.targetLane < 2) player.targetLane++;
else if (dx < -30 && player.targetLane > 0) player.targetLane--;
} else {
if (dy < -30 && !player.jumping) {
player.jumping = true;
player.jumpVel = -14;
} else if (dy > 30 && !player.sliding && !player.jumping) {
player.sliding = true;
player.slideTimer = player.slideDuration;
}
}
e.preventDefault();
});

// Buttons
document.getElementById('startBtn').addEventListener('click', () => {
resetGame();
gameState = 'playing';
document.getElementById('start-screen').style.display = 'none';
});
document.getElementById('restartBtn').addEventListener('click', () => {
resetGame();
gameState = 'playing';
document.getElementById('game-over-screen').style.display = 'none';
});

// Particles
function addParticles(x, y, color, count) {
for (let i = 0; i < count; i++) {
particles.push({
x: x,
y: y,
vx: (Math.random() - 0.5) * 8,
vy: (Math.random() - 0.5) * 8 - 3,
life: 30 + Math.random() * 20,
maxLife: 50,
color: color,
size: 2 + Math.random() * 4,
});
}
}

// Collision detection
function checkCollision(obs) {
const playerLane = player.targetLane;
if (obs.lane !== playerLane) return false;

const playerZ = player.z;
const obsZ = obs.z;
const depth = 80;

if (Math.abs(obsZ - playerZ) > depth) return false;

if (obs.type === 'barrier_low' && player.jumping && player.jumpHeight > 35) return false;
if (obs.type === 'barrier_high' && player.sliding) return false;

return true;
}

function checkCoinCollision(coin) {
if (coin.collected) return false;
if (coin.lane !== player.targetLane) return false;
if (Math.abs(coin.z - player.z) > 50) return false;
return true;
}

// Update
function update() {
if (gameState !== 'playing') return;

frameCount++;
distance += speed;
score = Math.floor(distance / 10);

// Increase speed
speed = Math.min(maxSpeed, 6 + distance / 2000);

// Player lane interpolation
player.x += (player.targetLane - player.x) * 0.2;

// Jump physics
if (player.jumping) {
player.jumpHeight += player.jumpVel;
player.jumpVel += 0.7;
if (player.jumpHeight <= 0) {
player.jumpHeight = 0;
player.jumping = false;
player.jumpVel = 0;
}
}

// Slide
if (player.sliding) {
player.slideTimer--;
if (player.slideTimer <= 0) {
player.sliding = false;
}
}

// Animation
player.animTimer++;
if (player.animTimer > 5) {
player.animTimer = 0;
player.animFrame = (player.animFrame + 1) % 4;
}

if (player.invincible > 0) player.invincible--;

// Spawn obstacles
if (frameCount % Math.max(20, 60 - Math.floor(distance / 500)) === 0) {
spawnObstacle();
}
if (frameCount % 80 === 0) {
spawnCoin();
}

// Update obstacles
for (let i = obstacles.length - 1; i >= 0; i--) {
obstacles[i].z -= speed;
if (obstacles[i].z < -100) {
obstacles.splice(i, 1);
continue;
}
if (player.invincible <= 0 && checkCollision(obstacles[i])) {
gameState = 'over';
document.getElementById('game-over-screen').style.display = 'flex';
document.getElementById('final-score').textContent = score;
document.getElementById('final-coins').textContent = '🪙 ' + coins;
addParticles(W / 2, H * 0.7, '#ff4444', 30);
return;
}
}

// Update coins
for (let i = coinItems.length - 1; i >= 0; i--) {
coinItems[i].z -= speed;
if (coinItems[i].z < -100) {
coinItems.splice(i, 1);
continue;
}
if (checkCoinCollision(coinItems[i])) {
coinItems[i].collected = true;
coins++;
totalCoins++;
const p = project(coinItems[i].lane, 0, coinItems[i].z);
addParticles(p.x, p.y, '#ffd700', 8);
}
}

// Update particles
for (let i = particles.length - 1; i >= 0; i--) {
particles[i].x += particles[i].vx;
particles[i].y += particles[i].vy;
particles[i].vy += 0.2;
particles[i].life--;
if (particles[i].life <= 0) particles.splice(i, 1);
}

// Update buildings
buildings.forEach(b => {
b.z -= speed;
if (b.z < -200) {
b.z += 2000;
b.width = 30 + Math.random() * 60;
b.height = 80 + Math.random() * 200;
b.color = `hsl(${220 + Math.random()*40}, 30%, ${15 + Math.random()*15}%)`;
}
});

// Update clouds
clouds.forEach(c => {
c.x += c.speed;
if (c.x > W + 50) c.x = -50;
});

// UI
document.getElementById('score-display').textContent = score;
document.getElementById('coin-display').textContent = '🪙 ' + coins;
}

// Draw
function draw() {
// Sky gradient
const skyGrad = ctx.createLinearGradient(0, 0, 0, H * VANISH_Y);
skyGrad.addColorStop(0, '#0f0c29');
skyGrad.addColorStop(0.5, '#302b63');
skyGrad.addColorStop(1, '#24243e');
ctx.fillStyle = skyGrad;
ctx.fillRect(0, 0, W, H);

// Stars
ctx.fillStyle = '#ffffff';
for (let i = 0; i < 50; i++) {
const sx = (i * 137.5 + frameCount * 0.01) % W;
const sy = (i * 73.1) % (H * VANISH_Y);
const twinkle = 0.3 + 0.7 * Math.sin(frameCount * 0.05 + i);
ctx.globalAlpha = twinkle * 0.6;
ctx.fillRect(sx, sy, 1.5, 1.5);
}
ctx.globalAlpha = 1;

// Clouds
ctx.fillStyle = 'rgba(255,255,255,0.08)';
clouds.forEach(c => {
ctx.beginPath();
ctx.ellipse(c.x, c.y, c.size, c.size * 0.4, 0, 0, Math.PI * 2);
ctx.fill();
});

// Ground
const groundGrad = ctx.createLinearGradient(0, H * VANISH_Y, 0, H);
groundGrad.addColorStop(0, '#1a1a2e');
groundGrad.addColorStop(1, '#2a2a3e');
ctx.fillStyle = groundGrad;
ctx.fillRect(0, H * VANISH_Y, W, H);

// Road
ctx.beginPath();
const topL = W / 2 - W * ROAD_WIDTH_TOP / 2;
const topR = W / 2 + W * ROAD_WIDTH_TOP / 2;
const botL = W / 2 - W * ROAD_WIDTH_BOTTOM / 2;
const botR = W / 2 + W * ROAD_WIDTH_BOTTOM / 2;
ctx.moveTo(topL, H * VANISH_Y);
ctx.lineTo(topR, H * VANISH_Y);
ctx.lineTo(botR, H);
ctx.lineTo(botL, H);
ctx.closePath();
ctx.fillStyle = '#2d2d3d';
ctx.fill();

// Road edge lines
ctx.strokeStyle = '#444466';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(topL, H * VANISH_Y);
ctx.lineTo(botL, H);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(topR, H * VANISH_Y);
ctx.lineTo(botR, H);
ctx.stroke();

// Lane dividers
for (let l = 1; l < LANE_COUNT; l++) {
ctx.strokeStyle = 'rgba(100,100,140,0.4)';
ctx.lineWidth = 1;
ctx.setLineDash([20, 20]);
ctx.lineDashOffset = -distance % 40;
ctx.beginPath();
const tl = W / 2 + (l - 1.5) * W * ROAD_WIDTH_TOP / LANE_COUNT;
const bl = W / 2 + (l - 1.5) * W * ROAD_WIDTH_BOTTOM / LANE_COUNT;
ctx.moveTo(tl, H * VANISH_Y);
ctx.lineTo(bl, H);
ctx.stroke();
ctx.setLineDash([]);
}

// Track ties (horizontal lines)
for (let z = 0; z < 2000; z += 80) {
const adjustedZ = (z - distance % 80 + 2000) % 2000;
const scale = getScale(adjustedZ);
const roadY = getRoadY(adjustedZ);
const w = W * (ROAD_WIDTH_BOTTOM + (ROAD_WIDTH_TOP - ROAD_WIDTH_BOTTOM) * (adjustedZ / 2000));
ctx.strokeStyle = `rgba(80,80,100,${scale * 0.5})`;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(W / 2 - w / 2, roadY);
ctx.lineTo(W / 2 + w / 2, roadY);
ctx.stroke();
}

// Draw buildings
buildings.forEach(b => {
const scale = getScale(b.z);
const roadY = getRoadY(b.z);
const bx = b.x > 0 ? W / 2 + W * ROAD_WIDTH_BOTTOM / 2 + b.width * scale / 2 : W / 2 - W * ROAD_WIDTH_BOTTOM / 2 - b.width * scale / 2;
const by = roadY - b.height * scale;
const bw = b.width * scale;
const bh = b.height * scale;

if (by + bh < H * VANISH_Y || by > H) return;

ctx.fillStyle = b.color;
ctx.fillRect(bx - bw / 2, by, bw, bh);

// Windows
const winRows = Math.floor(bh / 15);
const winCols = b.windows;
for (let r = 0; r < winRows; r++) {
for (let c = 0; c < winCols; c++) {
const wx = bx - bw / 2 + (c + 0.5) * bw / winCols - 2;
const wy = by + 5 + r * 15;
const lit = Math.sin(b.z * 0.01 + r * 3 + c * 7 + frameCount * 0.005) > 0.3;
ctx.fillStyle = lit ? '#ffdd44' : '#222233';
ctx.globalAlpha = lit ? 0.8 : 0.5;
ctx.fillRect(wx, wy, 4, 6);
}
}
ctx.globalAlpha = 1;
});

// Sort obstacles and coins by z (far first)
const allEntities = [
...obstacles.map(o => ({...o, entityType: 'obstacle'})),
...coinItems.filter(c => !c.collected).map(c => ({...c, entityType: 'coin'})),
];
allEntities.sort((a, b) => b.z - a.z);

// Draw entities
allEntities.forEach(entity => {
const z = entity.z;
if (z < -50 || z > 2000) return;
const scale = getScale(z);
const roadY = getRoadY(z);
const laneX = getLaneX(entity.lane, z);

if (entity.entityType === 'obstacle') {
drawObstacle(entity, laneX, roadY, scale);
} else {
drawCoin(entity, laneX, roadY, scale);
}
});

// Draw player
drawPlayer();

// Draw particles
particles.forEach(p => {
ctx.globalAlpha = p.life / p.maxLife;
ctx.fillStyle = p.color;
ctx.beginPath();
ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
ctx.fill();
});
ctx.globalAlpha = 1;

// Speed lines effect
if (speed > 8) {
ctx.strokeStyle = `rgba(255,255,255,${(speed - 8) * 0.02})`;
ctx.lineWidth = 1;
for (let i = 0; i < 5; i++) {
const lx = Math.random() * W;
const ly = H * VANISH_Y + Math.random() * (H - H * VANISH_Y);
ctx.beginPath();
ctx.moveTo(lx, ly);
ctx.lineTo(lx + (lx - W/2) * 0.1, ly + 30 + speed * 3);
ctx.stroke();
}
}
}

function drawObstacle(obs, laneX, roadY, scale) {
const w = obs.width * scale;
const h = obs.height * scale;

if (obs.type === 'train') {
// Train body
const trainGrad = ctx.createLinearGradient(laneX - w/2, roadY - h, laneX + w/2, roadY);
trainGrad.addColorStop(0, obs.color);
trainGrad.addColorStop(1, shadeColor(obs.color, -30));
ctx.fillStyle = trainGrad;

// Rounded rectangle
const r = 4 * scale;
ctx.beginPath();
ctx.moveTo(laneX - w/2 + r, roadY - h);
ctx.lineTo(laneX + w/2 - r, roadY - h);
ctx.quadraticCurveTo(laneX + w/2, roadY - h, laneX + w/2, roadY - h + r);
ctx.lineTo(laneX + w/2, roadY);
ctx.lineTo(laneX - w/2, roadY);
ctx.lineTo(laneX - w/2, roadY - h + r);
ctx.quadraticCurveTo(laneX - w/2, roadY - h, laneX - w/2 + r, roadY - h);
ctx.closePath();
ctx.fill();

// Train stripe
ctx.fillStyle = 'rgba(255,255,255,0.2)';
ctx.fillRect(laneX - w/2, roadY - h * 0.6, w, h * 0.08);

// Windows
ctx.fillStyle = '#88ccff';
const winW = w * 0.2;
const winH = h * 0.2;
for (let i = 0; i < 3; i++) {
const wx = laneX - w/2 + w * 0.15 + i * w * 0.3;
ctx.fillRect(wx, roadY - h * 0.85, winW, winH);
}

// Wheels
ctx.fillStyle = '#333';
ctx.fillRect(laneX - w/2 + 2, roadY - 5 * scale, w * 0.2, 5 * scale);
ctx.fillRect(laneX + w/2 - w * 0.2 - 2, roadY - 5 * scale, w * 0.2, 5 * scale);

} else if (obs.type === 'barrier_low') {
// Low barrier (jump over)
ctx.fillStyle = obs.color;
ctx.fillRect(laneX - w/2, roadY - h, w, h);

// Stripes
ctx.fillStyle = '#333';
for (let i = 0; i < 4; i++) {
const sx = laneX - w/2 + i * w / 4;
ctx.beginPath();
ctx.moveTo(sx, roadY - h);
ctx.lineTo(sx + w/8, roadY - h);
ctx.lineTo(sx - w/8, roadY);
ctx.lineTo(sx - w/4, roadY);
ctx.closePath();
ctx.fill();
}

// Posts
ctx.fillStyle = '#888';
ctx.fillRect(laneX - w/2 + 2, roadY - h - 10 * scale, 4 * scale, 10 * scale);
ctx.fillRect(laneX + w/2 - 6 * scale, roadY - h - 10 * scale, 4 * scale, 10 * scale);

} else if (obs.type === 'barrier_high') {
// High barrier (slide under)
// Posts
ctx.fillStyle = '#888';
ctx.fillRect(laneX - w/2 + 2, roadY - h - 10 * scale, 4 * scale, 10 * scale);
ctx.fillRect(laneX + w/2 - 6 * scale, roadY - h - 10 * scale, 4 * scale, 10 * scale);

// Top bar
ctx.fillStyle = obs.color;
ctx.fillRect(laneX - w/2, roadY - h, w, h * 0.35);

// Warning stripes
ctx.fillStyle = '#333';
for (let i = 0; i < 5; i++) {
const sx = laneX - w/2 + i * w / 5;
ctx.beginPath();
ctx.moveTo(sx, roadY - h);
ctx.lineTo(sx + w/10, roadY - h);
ctx.lineTo(sx, roadY - h + h * 0.35);
ctx.lineTo(sx - w/10, roadY - h + h * 0.35);
ctx.closePath();
ctx.fill();
}
}
}

function drawCoin(coin, laneX, roadY, scale) {
const bob = Math.sin(frameCount * 0.1 + coin.bobOffset) * 5 * scale;
const cy = roadY - 25 * scale + bob;
const cr = 8 * scale;

// Glow
ctx.fillStyle = 'rgba(255,215,0,0.2)';
ctx.beginPath();
ctx.arc(laneX, cy, cr * 2, 0, Math.PI * 2);
ctx.fill();

// Coin body
const coinGrad = ctx.createRadialGradient(laneX - cr * 0.3, cy - cr * 0.3, 0, laneX, cy, cr);
coinGrad.addColorStop(0, '#fff44f');
coinGrad.addColorStop(0.5, '#ffd700');
coinGrad.addColorStop(1, '#cc9900');
ctx.fillStyle = coinGrad;
ctx.beginPath();
ctx.arc(laneX, cy, cr, 0, Math.PI * 2);
ctx.fill();

// $ symbol
ctx.fillStyle = '#aa7700';
ctx.font = `bold ${Math.max(6, 10 * scale)}px Arial`;
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText('$', laneX, cy + 1);
}

function drawPlayer() {
const px = getLaneX(player.x, player.z);
const py = getRoadY(player.z);
const scale = getScale(player.z);

const jumpOffset = player.jumpHeight * scale;
const baseY = py - jumpOffset;

const isSliding = player.sliding;
const pw = 30 * scale;
const ph = isSliding ? 30 * scale : 60 * scale;

// Shadow
ctx.fillStyle = 'rgba(0,0,0,0.3)';
ctx.beginPath();
ctx.ellipse(px, py + 2, pw * 0.8, 6 * scale, 0, 0, Math.PI * 2);
ctx.fill();

// Body
const bodyGrad = ctx.createLinearGradient(px - pw/2, baseY - ph, px + pw/2, baseY);
bodyGrad.addColorStop(0, '#00ff88');
bodyGrad.addColorStop(1, '#00aa55');
ctx.fillStyle = bodyGrad;

if (isSliding) {
// Sliding pose
ctx.beginPath();
ctx.roundRect(px - pw/2, baseY - ph, pw, ph, 8 * scale);
ctx.fill();
} else {
// Standing pose
ctx.beginPath();
ctx.roundRect(px - pw/2, baseY - ph, pw, ph * 0.7, 6 * scale);
ctx.fill();

// Head
const headR = 12 * scale;
ctx.fillStyle = '#ffcc88';
ctx.beginPath();
ctx.arc(px, baseY - ph - headR + 5 * scale, headR, 0, Math.PI * 2);
ctx.fill();

// Hair
ctx.fillStyle = '#333';
ctx.beginPath();
ctx.arc(px, baseY - ph - headR + 2 * scale, headR, Math.PI, Math.PI * 2);
ctx.fill();

// Legs animation
const legOffset = Math.sin(player.animFrame * Math.PI / 2) * 8 * scale;
ctx.fillStyle = '#2244aa';
if (!player.jumping) {
ctx.fillRect(px - 8 * scale, baseY - ph * 0.3, 6 * scale, ph * 0.35 + legOffset);
ctx.fillRect(px + 2 * scale, baseY - ph * 0.3, 6 * scale, ph * 0.35 - legOffset);
} else {
// Jumping pose - legs tucked
ctx.fillRect(px - 8 * scale, baseY - ph * 0.2, 6 * scale, ph * 0.25);
ctx.fillRect(px + 2 * scale, baseY - ph * 0.2, 6 * scale, ph * 0.25);
}

// Arms
ctx.strokeStyle = '#ffcc88';
ctx.lineWidth = 4 * scale;
ctx.lineCap = 'round';
const armSwing = Math.sin(player.animFrame * Math.PI / 2) * 15;
ctx.beginPath();
ctx.moveTo(px - pw/2, baseY - ph * 0.6);
ctx.lineTo(px - pw/2 - 10 * scale, baseY - ph * 0.4 + armSwing * scale);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(px + pw/2, baseY - ph * 0.6);
ctx.lineTo(px + pw/2 + 10 * scale, baseY - ph * 0.4 - armSwing * scale);
ctx.stroke();
}

// Invincibility flash
if (player.invincible > 0 && Math.floor(frameCount / 3) % 2 === 0) {
ctx.globalAlpha = 0.3;
ctx.fillStyle = '#fff';
ctx.beginPath();
ctx.roundRect(px - pw/2, baseY - ph, pw, ph, 8 * scale);
ctx.fill();
ctx.globalAlpha = 1;
}
}

function shadeColor(color, percent) {
const num = parseInt(color.replace('#', ''), 16);
const amt = Math.round(2.55 * percent);
const R = Math.max(0, Math.min(255, (num >> 16) + amt));
const G = Math.max(0, Math.min(255, (num >> 8 & 0x00FF) + amt));
const B = Math.max(0, Math.min(255, (num & 0x0000FF) + amt));
return `rgb(${R},${G},${B})`;
}

// Game loop
function gameLoop() {
update();
draw();
requestAnimationFrame(gameLoop);
}

initBuildings();
initClouds();
gameLoop();
</script>
