// ==================== TERRAIN ====================
function noise2D(x, z) {
const n = Math.sin(x * 12.9898 + z * 78.233) * 43758.5453;
return n - Math.floor(n);
}

function smoothNoise(x, z, scale) {
const sx = x / scale, sz = z / scale;
const ix = Math.floor(sx), iz = Math.floor(sz);
const fx = sx - ix, fz = sz - iz;
const a = noise2D(ix, iz);
const b = noise2D(ix + 1, iz);
const c = noise2D(ix, iz + 1);
const d = noise2D(ix + 1, iz + 1);
const ux = fx * fx * (3 - 2 * fx);
const uz = fz * fz * (3 - 2 * fz);
return a + (b - a) * ux + (c - a) * uz + (a - b - c + d) * ux * uz;
}

function fbm(x, z, octaves) {
let val = 0, amp = 1, freq = 1, max = 0;
for (let i = 0; i < octaves; i++) {
val += smoothNoise(x * freq, z * freq, 1) * amp;
max += amp;
amp *= 0.5;
freq *= 2;
}
return val / max;
}

function getTerrainHeight(x, z) {
let h = fbm(x, z, 6) * 30;
// Hills along roads
const roadZ = Math.abs(z);
const roadX = Math.abs(x);
if (roadZ < 12) h += Math.max(0, (1 - roadZ / 12)) * 2;
if (roadX < 12 && Math.abs(z) > 200) h += Math.max(0, (1 - roadX / 12)) * 5;
// Steep hills near certain areas
if (z < -300 && z > -600 && x > -50 && x < 50) {
const t = (z + 300) / 300;
h += Math.sin(t * Math.PI) * 25;
}
// Hills near factory
if (z > 600 && z < 900) {
h += Math.max(0, 1 - Math.abs(z - 750) / 150) * 15;
}
return h;
}

function createTerrain() {
const geo = new THREE.PlaneGeometry(terrainSize, terrainSize, terrainRes, terrainRes);
geo.rotateX(-Math.PI / 2);
const pos = geo.attributes.position;
const colors = new Float32Array(pos.count * 3);

for (let i = 0; i < pos.count; i++) {
const x = pos.getX(i);
const z = pos.getZ(i);
const h = getTerrainHeight(x, z);
pos.setY(i, h);

// Color based on height and position
const isRoad = isOnRoad(x, z);
if (isRoad) {
colors[i * 3] = 0.25; colors[i * 3 + 1] = 0.22; colors[i * 3 + 2] = 0.18;
} else if (h < 2) {
colors[i * 3] = 0.15 + Math.random() * 0.05;
colors[i * 3 + 1] = 0.35 + Math.random() * 0.1;
colors[i * 3 + 2] = 0.08;
} else if (h < 10) {
colors[i * 3] = 0.12 + Math.random() * 0.08;
colors[i * 3 + 1] = 0.3 + Math.random() * 0.12;
colors[i * 3 + 2] = 0.06 + Math.random() * 0.04;
} else {
colors[i * 3] = 0.2 + Math.random() * 0.1;
colors[i * 3 + 1] = 0.25 + Math.random() * 0.08;
colors[i * 3 + 2] = 0.1 + Math.random() * 0.05;
}
}

geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
geo.computeVertexNormals();

const mat = new THREE.MeshStandardMaterial({
vertexColors: true, roughness: 0.9, metalness: 0.0
});

terrainMesh = new THREE.Mesh(geo, mat);
terrainMesh.receiveShadow = true;
scene.add(terrainMesh);
}

function isOnRoad(x, z) {
// Main road from plantation to factory
const mainRoad = Math.abs(z) < 8 && Math.abs(x) < 10;
// Branch roads
const branch1 = Math.abs(x + 100) < 6 && Math.abs(z + 200) < 150;
const branch2 = Math.abs(x - 120) < 6 && Math.abs(z - 100) < 100;
// Hill road
const hillRoad = Math.abs(x) < 8 && z > -600 && z < -300;
return mainRoad || branch1 || branch2 || hillRoad;
}

