}

// ==================== LOAD/UNLOAD ====================
function handleLoadUnload() {
if (GameState.missionStage === 0 && GameState.load < GameState.maxLoad) {
const amount = Math.min(2, GameState.maxLoad - GameState.load);
GameState.load += amount;
createPalmBunches();
showNotification(`✅ Memuat ${amount} ton tandan sawit`);
if (GameState.load >= GameState.maxLoad) {
GameState.missionStage = 1;
document.getElementById('mission-title').textContent = '🚛 Berangkat ke Pabrik!';
document.getElementById('mission-dist').textContent = `Jarak: ${(GameState.distanceToFactory / 1000).toFixed(1)} km`;
}
} else if (GameState.missionStage === 2 && GameState.load > 0) {
const amount = GameState.load;
GameState.load = 0;
GameState.money += amount * 250000;
GameState.totalDeliveries++;
createPalmBunches();
showNotification(`💰 Terjual ${amount} ton = Rp ${(amount * 250000).toLocaleString('id-ID')}`);
GameState.missionStage = 0;
document.getElementById('mission-title').textContent = '📍 Kembali ke Perkebunan untuk Muat';
document.getElementById('mission-dist').textContent = `Jarak: ${(GameState.distanceToPlantation / 1000).toFixed(1)} km | Total: ${GameState.totalDeliveries} pengiriman`;
updateMoneyDisplay();
}
}

// ==================== UPGRADES ====================
const upgrades = [
{ id: 'engine', name: 'Mesin Turbo', desc: 'Tenaga lebih besar, akselerasi lebih cepat', maxLevel: 5, baseCost: 1500000, costMult: 1.8 },
{ id: 'suspension', name: 'Suspensi Off-Road', desc: 'Stabilitas di jalan berlumpur dan tanjakan', maxLevel: 5, baseCost: 800000, costMult: 1.6 },
{ id: 'brake', name: 'Rem Hidrolik', desc: 'Daya rem lebih kuat untuk turunan', maxLevel: 5, baseCost: 600000, costMult: 1.5 },
{ id: 'fueltank', name: 'Tangki Bahan Bakar', desc: 'Kapasitas bahan bakar +20L per level', maxLevel: 5, baseCost: 500000, costMult: 1.4 },
{ id: 'tire', name: 'Ban Off-Road', desc: 'Traksi lebih baik di jalan berlumpur', maxLevel: 5, baseCost: 700000, costMult: 1.6 },
{ id: 'turbo', name: 'Turbo Charger', desc: 'Boost tenaga ekstra di kecepatan tinggi', maxLevel: 3, baseCost: 3000000, costMult: 2.0 },
];

function getUpgradeCost(upgrade) {
const level = GameState[upgrade.id + 'Level'];
return Math.floor(upgrade.baseCost * Math.pow(upgrade.costMult, level));
}

function toggleUpgrade() {
const menu = document.getElementById('upgrade-menu');
menu.classList.toggle('active');
if (menu.classList.contains('active')) {
renderUpgradeList();
}
}

function renderUpgradeList() {
const list = document.getElementById('upgrade-list');
list.innerHTML = '';

upgrades.forEach(upg => {
const level = GameState[upg.id + 'Level'];
const cost = getUpgradeCost(upg);
const isMaxed = level >= upg.maxLevel;
const canAfford = GameState.money >= cost;

const item = document.createElement('div');
item.className = 'upgrade-item';
item.innerHTML = `
<div class="upgrade-info">
<h3>${upg.name} <span style="color:#FF9800;">Lv.${level}/${upg.maxLevel}</span></h3>
<p>${upg.desc}</p>
</div>
<button class="upgrade-btn ${isMaxed ? 'maxed' : ''}" 
onclick="buyUpgrade('${upg.id}')" ${!canAfford || isMaxed ? 'disabled' : ''}>
${isMaxed ? 'MAX' : `Rp ${cost.toLocaleString('id-ID')}`}
</button>
`;
list.appendChild(item);
});
}

function buyUpgrade(id) {
const upg = upgrades.find(u => u.id === id);
const level = GameState[id + 'Level'];
if (level >= upg.maxLevel) return;

const cost = getUpgradeCost(upg);
if (GameState.money < cost) {
showNotification('❌ Uang tidak cukup!');
return;
}

GameState.money -= cost;
GameState[id + 'Level']++;
updateMoneyDisplay();
renderUpgradeList();
showNotification(`✅ ${upg.name} ditingkatkan ke Lv.${GameState[id + 'Level']}!`);
}

// ==================== WEATHER ====================
function updateWeather(dt) {
GameState.weatherTimer += dt;

if (GameState.weatherTimer > 30 + Math.random() * 60) {
GameState.weatherTimer = 0;
const r = Math.random();
if (r < 0.3) {
GameState.weather = 'clear';
GameState.rainIntensity = 0;
GameState.fogDensity = 0.001;
GameState.temperature = 30 + Math.random() * 5;
} else if (r < 0.6) {
GameState.weather = 'cloudy';
GameState.rainIntensity = 0.1;
GameState.fogDensity = 0.003;
GameState.temperature = 28 + Math.random() * 3;
} else if (r < 0.85) {
GameState.weather = 'rain';
GameState.rainIntensity = 0.5;
GameState.fogDensity = 0.005;
GameState.temperature = 24 + Math.random() * 3;
} else {
GameState.weather = 'storm';
GameState.rainIntensity = 1.0;
GameState.fogDensity = 0.01;
GameState.temperature = 20 + Math.random() * 3;
}

const weatherNames = { clear: '☀️ Cerah', cloudy: '⛅ Berawan', rain: '🌧️ Hujan', storm: '⛈️ Badai' };
document.getElementById('weather-display').textContent = weatherNames[GameState.weather];
document.getElementById('temp-display').textContent = `${Math.floor(GameState.temperature)}°C`;

if (GameState.weather === 'rain' || GameState.weather === 'storm') {
rainSystem.visible = true;
rainSystem.material.opacity = GameState.rainIntensity * 0.5;
} else {
rainSystem.visible = false;
}
}

// Traction based on weather and terrain
let baseTraction = 100;
if (GameState.weather === 'rain') baseTraction -= 25;
if (GameState.weather === 'storm') baseTraction -= 45;
if (GameState.load > 10) baseTraction -= 10;
if (GameState.tireLevel > 1) baseTraction += (GameState.tireLevel - 1) * 8;

// Check if on road
const onRoad = isOnRoad(GameState.truckPos.x, GameState.truckPos.z);
if (!onRoad) baseTraction -= 30;

// Check slope
const h1 = getTerrainHeight(GameState.truckPos.x, GameState.truckPos.z);
const h2 = getTerrainHeight(GameState.truckPos.x, GameState.truckPos.z + 1);
const slope = Math.atan2(h2 - h1, 1) * (180 / Math.PI);
if (slope > 10) baseTraction -= slope * 0.5;

GameState.traction = Math.max(20, Math.min(100, baseTraction));
}

// ==================== TRUCK PHYSICS ====================
function updateTruckPhysics(dt) {
const enginePower = 15 + GameState.engineLevel * 5 + GameState.turboLevel * 8;
const brakePower = 20 + GameState.brakeLevel * 8;
const suspensionStiffness = 0.5 + GameState.suspensionLevel * 0.2;
const fuelConsumption = 0.01 + GameState.load * 0.005 + (GameState.engineLevel > 3 ? 0.005 : 0);
const maxSpeed = 40 + GameState.engineLevel * 5;

// Input
let throttle = 0;
let steer = 0;

if (GameState.keys['s']) throttle = 1;
if (GameState.keys['w']) throttle = -1;
if (GameState.keys['a']) steer = 1;
if (GameState.keys['d']) steer = -1;
if (GameState.keys['shift'] && GameState.keys['z']) GameState.isReversing = true;
else GameState.isReversing = false;

GameState.handbrake = GameState.keys[' '] || false;

// Acceleration
let accel = throttle * enginePower * 0.01;
if (GameState.isReversing) accel *= 0.5;

// Apply traction
const tractionFactor = GameState.traction / 100;
accel *= (0.5 + tractionFactor * 0.5);

// Gravity on slope
const h1 = getTerrainHeight(GameState.truckPos.x, GameState.truckPos.z);
const h2 = getTerrainHeight(GameState.truckPos.x, GameState.truckPos.z + 1);
const slope = Math.atan2(h2 - h1, 1);
accel -= slope * 9.8 * 0.3;

// Speed
GameState.speed += accel * dt * 60;
GameState.speed *= 0.98; // Friction

// Handbrake
if (GameState.handbrake) {
GameState.speed *= 0.92;
}

// Max speed
GameState.speed = Math.max(-maxSpeed * 0.3, Math.min(maxSpeed, GameState.speed));

// RPM
GameState.rpm = Math.abs(GameState.speed) / maxSpeed * 4000 + 800;
if (GameState.speed < 0) GameState.rpm = Math.abs(GameState.speed) / maxSpeed * 3000 + 600;

// Steering
const steerAmount = steer * 2.5 * dt * (1 - Math.abs(GameState.speed) / maxSpeed * 0.5);
GameState.truckRot += steerAmount;

// Move truck
const moveSpeed = GameState.speed * dt;
const dx = Math.sin(GameState.truckRot) * moveSpeed;
const dz = Math.cos(GameState.truckRot) * moveSpeed;

GameState.truckPos.x += dx;
GameState.truckPos.z += dz;

// Terrain following
const terrainH = getTerrainHeight(GameState.truckPos.x, GameState.truckPos.z);
const suspensionOffset = Math.sin(Date.now() * 0.005) * (GameState.suspensionLevel < 3 ? 0.15 : 0.05);
GameState.truckPos.y = terrainH + 0.5 + suspensionOffset;

// Clamp to terrain bounds
GameState.truckPos.x = Math.max(-terrainSize / 2 + 20, Math.min(terrainSize / 2 - 20, GameState.truckPos.x));
GameState.truckPos.z = Math.max(-terrainSize / 2 + 20, Math.min(terrainSize / 2 - 20, GameState.truckPos.z));

// Fuel consumption
if (Math.abs(GameState.speed) > 0.1) {
GameState.fuel -= fuelConsumption * dt * 60;
}
GameState.fuel = Math.max(0, GameState.fuel);

if (GameState.fuel <= 0) {
GameState.speed *= 0.95;
if (GameState.speed < 0.1) GameState.speed = 0;
}

// Distance
GameState.distance += Math.abs(moveSpeed);

// Mission logic
if (GameState.missionStage === 1) {
const distToFactory = Math.sqrt(
Math.pow(GameState.truckPos.x - 0, 2) +
Math.pow(GameState.truckPos.z - 800, 2)
);
GameState.distanceToFactory = distToFactory;
document.getElementById('mission-dist').textContent = `Jarak ke Pabrik: ${(distToFactory / 1000).toFixed(1)} km`;

if (distToFactory < 30) {
GameState.missionStage = 2;
document.getElementById('mission-title').textContent = '🏭 Sampai di Pabrik! Tekan E untuk bongkar';
document.getElementById('mission-dist').textContent = `Beban: ${GameState.load} ton`;
}
} else if (GameState.missionStage === 0) {
const distToPlantation = Math.sqrt(
Math.pow(GameState.truckPos.x - 0, 2) +
Math.pow(GameState.truckPos.z - (-400), 2)
);
GameState.distanceToPlantation = distToPlantation;
document.getElementById('mission-dist').textContent = `Jarak ke Perkebunan: ${(distToPlantation / 1000).toFixed(1)} km`;
}

// Update truck mesh
truckGroup.position.copy(GameState.truckPos);
truckGroup.rotation.y = GameState.truckRot;

// Wheel rotation
wheels.forEach(w => {
w.rotation.x += GameState.speed * dt * 0.5;
});

// Front wheel steering
wheels[0].rotation.y = steer * 0.3;
wheels[1].rotation.y = steer * 0.3;

// Cab tilt for suspension effect
const cabTilt = -accel * 0.02;
truckCab.rotation.x = cabTilt;
}

// ==================== CAMERA ====================
function updateCamera() {
const truckPos = GameState.truckPos.clone();
const truckRot = GameState.truckRot;

if (GameState.cameraMode === 0) {
// Third person
const camDist = 18;
const camHeight = 10;
const camX = truckPos.x - Math.sin(truckRot) * camDist;
const camZ = truckPos.z - Math.cos(truckRot) * camDist;
const camY = truckPos.y + camHeight;

camera.position.lerp(new THREE.Vector3(camX, camY, camZ), 0.05);
const lookTarget = new THREE.Vector3(
truckPos.x + Math.sin(truckRot) * 10,
truckPos.y + 3,
truckPos.z + Math.cos(truckRot) * 10
);
camera.lookAt(lookTarget);
} else if (GameState.cameraMode === 1) {
// Cabin camera
const cabOffset = new THREE.Vector3(0, 2.5, 3.5);
cabOffset.applyAxisAngle(new THREE.Vector3(0, 1, 0), truckRot);
const camPos = truckPos.clone().add(cabOffset);
camera.position.lerp(camPos, 0.1);

const lookDir = new THREE.Vector3(
Math.sin(truckRot) * 20,
1,
Math.cos(truckRot) * 20
);
camera.lookAt(truckPos.clone().add(lookDir));
} else {
// Top-down
camera.position.lerp(new THREE.Vector3(truckPos.x, truckPos.y + 50, truckPos.z + 0.1), 0.05);
camera.lookAt(truckPos);
}
}

// ==================== RAIN UPDATE ====================
function updateRain(dt) {
if (!rainSystem.visible) return;

const positions = rainParticles.geometry.attributes.position.array;
const velocities = rainParticles.geometry.userData.velocities;

for (let i = 0; i < positions.length / 3; i++) {
positions[i * 3 + 1] -= velocities[i] * 30 * dt * GameState.rainIntensity;

if (positions[i * 3 + 1] < 0) {
positions[i * 3 + 1] = 80 + Math.random() * 20;
positions[i * 3] = GameState.truckPos.x + (Math.random() - 0.5) * 200;
positions[i * 3 + 2] = GameState.truckPos.z + (Math.random() - 0.5) * 200;
}
}

rainParticles.geometry.attributes.position.needsUpdate = true;
}

// ==================== MINIMAP ====================
function updateMinimap() {
const ctx = minimapCtx;
const w = 160, h = 160;
ctx.fillStyle = '#2a4a1a';
ctx.fillRect(0, 0, w, h);

const scale = w / 1000;
const cx = w / 2, cy = h / 2;

// Draw roads
ctx.strokeStyle = '#555';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.moveTo(cx, cy + 400 * scale);
ctx.lineTo(cx, cy - 400 * scale);
ctx.stroke();

// Factory
ctx.fillStyle = '#888';
ctx.fillRect(cx - 10, cy + 800 * scale - 10, 20, 20);

// Plantation
ctx.fillStyle = '#998866';
ctx.fillRect(cx - 10, cy - 400 * scale - 10, 20, 20);

// Truck
const tx = cx + GameState.truckPos.x * scale;
const ty = cy + GameState.truckPos.z * scale;
ctx.fillStyle = '#ff3300';
ctx.beginPath();
ctx.arc(tx, ty, 4, 0, Math.PI * 2);
ctx.fill();

// Truck direction
ctx.strokeStyle = '#ff3300';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(tx, ty);
ctx.lineTo(
tx + Math.sin(GameState.truckRot) * 10,
ty + Math.cos(GameState.truckRot) * 10
);
ctx.stroke();

// Palm trees dots
ctx.fillStyle = '#1a5a1a';
palmTrees.forEach((tree, i) => {
if (i % 5 === 0) {
const px = cx + tree.position.x * scale;
const py = cy + tree.position.z * scale;
if (px > 0 && px < w && py > 0 && py < h) {
ctx.fillRect(px - 1, py - 1, 2, 2);
}
}
});
}

// ==================== HUD UPDATE ====================
function updateHUD() {
document.getElementById('speed-display').textContent = Math.abs(Math.floor(GameState.speed));
document.getElementById('rpm-display').textContent = Math.floor(GameState.rpm);
document.getElementById('rpm-bar').style.width = `${(GameState.rpm / 5000) * 100}%`;
document.getElementById('fuel-bar').style.width = `${(GameState.fuel / GameState.maxFuel) * 100}%`;
document.getElementById('fuel-display').textContent = Math.floor(GameState.fuel);
document.getElementById('load-bar').style.width = `${(GameState.load / GameState.maxLoad) * 100}%`;
document.getElementById('traction-bar').style.width = `${GameState.traction}%`;
document.getElementById('traction-display').textContent = `${Math.floor(GameState.traction)}%`;

if (GameState.fuel < 15) {
document.getElementById('fuel-bar').style.background = 'linear-gradient(90deg, #ff0000, #ff4444)';
}
}

function updateMoneyDisplay() {
document.getElementById('money-display').textContent = `Rp ${GameState.money.toLocaleString('id-ID')}`;
}

// ==================== NOTIFICATION ====================
function showNotification(text) {
const notif = document.getElementById('notification');
notif.textContent = text;
notif.classList.add('show');
setTimeout(() => notif.classList.remove('show'), 3000);
}

// ==================== ENVIRONMENT UPDATE ====================
function updateEnvironment(dt) {
// Day/night cycle
GameState.dayTime += dt * 0.005;
if (GameState.dayTime > 1) GameState.dayTime -= 1;

const sunAngle = GameState.dayTime * Math.PI * 2;
const sunY = Math.sin(sunAngle);
GameState.sunLight.position.set(100, 150 * sunY + 50, 80);

// Sky color
const skyColor = new THREE.Color();
if (sunY > 0.3) {
skyColor.setHex(0x87CEEB);
} else if (sunY > 0) {
skyColor.setHex(0xff9966);
} else {
skyColor.setHex(0x111133);
}
scene.background = skyColor;
scene.fog.color = skyColor;

const sky = scene.getObjectByName('sky');
if (sky) sky.material.color = skyColor;

// Ambient light intensity
const ambientIntensity = Math.max(0.1, sunY * 0.6 + 0.3);
scene.children.forEach(child => {
if (child.isAmbientLight) child.intensity = ambientIntensity;
});

// Fog
scene.fog.density = GameState.fogDensity;

// Palm tree sway
const time = Date.now() * 0.001;
palmTrees.forEach(tree => {
const sway = Math.sin(time * tree.userData.swaySpeed + tree.userData.swayOffset) * 0.02 * (GameState.weather === 'storm' ? 3 : 1);
tree.rotation.z = sway;
tree.rotation.x = sway * 0.5;
});

// Rain effect on visibility
if (GameState.weather === 'storm') {
renderer.toneMappingExposure = 0.7;
} else if (GameState.weather === 'rain') {
renderer.toneMappingExposure = 0.85;
} else {
renderer.toneMappingExposure = 1.0;
}
}

// ==================== GAME LOOP ====================
function animate() {
requestAnimationFrame(animate);

if (!GameState.started) return;

const dt = Math.min(clock.getDelta(), 0.05);

updateWeather(dt);
updateTruckPhysics(dt);
updateCamera();
updateRain(dt);
updateEnvironment(dt);
updateHUD();
updateMinimap();

renderer.render(scene, camera);
}

// ==================== START GAME ====================
function startGame() {
document.getElementById('start-screen').style.display = 'none';
document.getElementById('hud').style.display = 'block';
GameState.started = true;
init();
showNotification('🌴 Selamat datang di Perkebunan Sawit! Tekan E untuk memuat tandan');
}
</script>
