for (let i = 0; i < sData.length; i++) sData[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / sData.length, 1.5);
sNoise.buffer = sBuf;
const sg = audioCtx.createGain();
sg.gain.setValueAtTime(0.5, audioCtx.currentTime);
sg.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.2);
sNoise.connect(sg);
sg.connect(audioCtx.destination);
sNoise.start();
break;
case 'sniper':
const snNoise = audioCtx.createBufferSource();
const snBuf = audioCtx.createBuffer(1, audioCtx.sampleRate * 0.3, audioCtx.sampleRate);
const snData = snBuf.getChannelData(0);
for (let i = 0; i < snData.length; i++) snData[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / snData.length, 3);
snNoise.buffer = snBuf;
const snG = audioCtx.createGain();
snG.gain.setValueAtTime(0.4, audioCtx.currentTime);
snG.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.3);
snNoise.connect(snG);
snG.connect(audioCtx.destination);
snNoise.start();
break;
case 'hit':
osc.type = 'sine';
osc.frequency.setValueAtTime(800, audioCtx.currentTime);
osc.frequency.exponentialRampToValueAtTime(200, audioCtx.currentTime + 0.1);
gain.gain.setValueAtTime(0.15, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
osc.start(); osc.stop(audioCtx.currentTime + 0.1);
break;
case 'kill':
osc.type = 'square';
osc.frequency.setValueAtTime(600, audioCtx.currentTime);
osc.frequency.setValueAtTime(800, audioCtx.currentTime + 0.1);
osc.frequency.setValueAtTime(1000, audioCtx.currentTime + 0.2);
gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.3);
osc.start(); osc.stop(audioCtx.currentTime + 0.3);
break;
case 'damage':
osc.type = 'sawtooth';
osc.frequency.setValueAtTime(150, audioCtx.currentTime);
osc.frequency.exponentialRampToValueAtTime(50, audioCtx.currentTime + 0.2);
gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.2);
osc.start(); osc.stop(audioCtx.currentTime + 0.2);
break;
case 'reload':
osc.type = 'sine';
osc.frequency.setValueAtTime(400, audioCtx.currentTime);
osc.frequency.setValueAtTime(600, audioCtx.currentTime + 0.15);
osc.frequency.setValueAtTime(800, audioCtx.currentTime + 0.3);
gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.4);
osc.start(); osc.stop(audioCtx.currentTime + 0.4);
break;
case 'empty':
osc.type = 'sine';
osc.frequency.setValueAtTime(300, audioCtx.currentTime);
gain.gain.setValueAtTime(0.05, audioCtx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.05);
osc.start(); osc.stop(audioCtx.currentTime + 0.05);
break;
case 'footstep':
const fBuf = audioCtx.createBuffer(1, audioCtx.sampleRate * 0.05, audioCtx.sampleRate);
const fData = fBuf.getChannelData(0);
for (let i = 0; i < fData.length; i++) fData[i] = (Math.random() * 2 - 1) * 0.3 * Math.pow(1 - i / fData.length, 4);
const fNoise = audioCtx.createBufferSource();
fNoise.buffer = fBuf;
const fGain = audioCtx.createGain();
fGain.gain.setValueAtTime(0.08, audioCtx.currentTime);
fNoise.connect(fGain);
fGain.connect(audioCtx.destination);
fNoise.start();
break;
}
}

