color: 0x88bbdd, roughness: 0.1, metalness: 0.8,
emissive: 0x223344, emissiveIntensity: 0.3
});
const floors = Math.floor(h / 4);
for (let f = 0; f < floors; f++) {
for (let side = 0; side < 4; side++) {
const winCount = Math.floor(w / 5);
for (let wi = 0; wi < winCount; wi++) {
const win = new THREE.Mesh(new THREE.PlaneGeometry(2, 2.5), windowMat);
const wx = x - w/2 + 2.5 + wi * 5;
const wy = 3 + f * 4;
if (side === 0) { win.position.set(wx, wy, z + d/2 + 0.01); }
else if (side === 1) { win.position.set(wx, wy, z - d/2 - 0.01); win.rotation.y = Math.PI; }
else if (side === 2) {
win.position.set(x + w/2 + 0.01, wy, z - d/2 + 2.5 + wi * 5);
win.rotation.y = Math.PI / 2;
} else {
win.position.set(x - w/2 - 0.01, wy, z - d/2 + 2.5 + wi * 5);
win.rotation.y = -Math.PI / 2;
}
scene.add(win);
}
}
