class Enemy {
constructor(x, z, type) {
this.type = type || 'soldier';
this.health = type === 'heavy' ? 200 : type === 'elite' ? 150 : 100;
this.maxHealth = this.health;
this.speed = type === 'heavy' ? 0.04 : type === 'elite' ? 0.08 : 0.06;
this.damage = type === 'heavy' ? 20 : type === 'elite' ? 15 : 10;
this.fireRate = type === 'heavy' ? 800 : type === 'elite' ? 300 : 500;
this.detectionRange = type === 'elite' ? 60 : 40;
this.aimAccuracy = type === 'elite' ? 0.05 : type === 'heavy' ? 0.15 : 0.1;
this.lastShot = 0;
this.state = 'patrol';
this.patrolTarget = new THREE.Vector3(
x + (Math.random() - 0.5) * 40,
0,
z + (Math.random() - 0.5) * 40
);
this.alertTimer = 0;
this.searchTimer = 0;
this.isDead = false;
this.deathTimer = 0;
this.staggerTimer = 0;
this.lastKnownPlayerPos = null;

// Body
const bodyColor = type === 'heavy' ? 0x334433 : type === 'elite' ? 0x443344 : 0x556655;
this.group = new THREE.Group();

// Torso
const torso = new THREE.Mesh(
new THREE.BoxGeometry(0.8, 1.2, 0.5),
new THREE.MeshStandardMaterial({ color: bodyColor, roughness: 0.7 })
);
torso.position.y = 1.4;
torso.castShadow = true;
this.group.add(torso);

// Head
const head = new THREE.Mesh(
new THREE.SphereGeometry(0.25, 8, 8),
new THREE.MeshStandardMaterial({ color: 0xddaa88, roughness: 0.6 })
);
head.position.y = 2.25;
head.castShadow = true;
this.group.add(head);

// Helmet
const helmet = new THREE.Mesh(
new THREE.SphereGeometry(0.3, 8, 6, 0, Math.PI * 2, 0, Math.PI / 2),
new THREE.MeshStandardMaterial({ color: 0x334433, roughness: 0.5 })
);
helmet.position.y = 2.3;
this.group.add(helmet);

// Legs
const legMat = new THREE.MeshStandardMaterial({ color: 0x445544, roughness: 0.8 });
this.leftLeg = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.9, 0.3), legMat);
this.leftLeg.position.set(-0.2, 0.45, 0);
this.leftLeg.castShadow = true;
this.group.add(this.leftLeg);

this.rightLeg = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.9, 0.3), legMat);
this.rightLeg.position.set(0.2, 0.45, 0);
this.rightLeg.castShadow = true;
this.group.add(this.rightLeg);

// Arms
const armMat = new THREE.MeshStandardMaterial({ color: bodyColor, roughness: 0.7 });
this.leftArm = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), armMat);
this.leftArm.position.set(-0.55, 1.3, 0);
this.group.add(this.leftArm);

this.rightArm = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), armMat);
this.rightArm.position.set(0.55, 1.3, 0);
this.group.add(this.rightArm);

// Weapon
const gun = new THREE.Mesh(
new THREE.BoxGeometry(0.1, 0.1, 0.8),
new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.8 })
);
gun.position.set(0.55, 1.2, -0.4);
this.group.add(gun);

this.group.position.set(x, 0, z);
scene.add(this.group);

this.position = new THREE.Vector3(x, 0, z);
this.rotation = 0;
this.walkCycle = Math.random() * Math.PI * 2;
}

update(delta, time) {
if (this.isDead) {
this.deathTimer += delta;
if (this.deathTimer < 0.5) {
this.group.rotation.x += delta * 3;
this.group.position.y -= delta * 2;
}
if (this.deathTimer > 3) return true;
return false;
}

const distToPlayer = this.position.distanceTo(camera.position);
const canSeePlayer = this.canSeePlayer();

// State machine
switch (this.state) {
case 'patrol':
this.patrol(time);
if (canSeePlayer && distToPlayer < this.detectionRange) {
this.state = 'alert';
this.alertTimer = 2;
this.lastKnownPlayerPos = camera.position.clone();
playSound('damage');
}
break;

case 'alert':
this.alertTimer -= delta;
if (canSeePlayer) {
this.lastKnownPlayerPos = camera.position.clone();
this.state = 'chase';
} else if (this.alertTimer <= 0) {
this.state = 'search';
this.searchTimer = 5;
}
break;

case 'chase':
if (!canSeePlayer) {
this.lastKnownPlayerPos = camera.position.clone();
this.state = 'search';
this.searchTimer = 5;
} else {
this.chasePlayer(time);
if (distToPlayer < 30) {
this.state = 'combat';
}
}
break;

case 'search':
this.searchTimer -= delta;
if (this.searchTimer <= 0) {
this.state = 'patrol';
} else if (canSeePlayer) {
this.state = 'combat';
}
break;

case 'combat':
if (!canSeePlayer) {
this.lastKnownPlayerPos = camera.position.clone();
this.state = 'search';
this.searchTimer = 3;
} else {
this.combat(time, distToPlayer);
if (distToPlayer > 50) {
this.state = 'chase';
}
}
break;
}

// Update position
this.group.position.copy(this.position);
this.group.rotation.y = this.rotation;

// Walk animation
if (this.state === 'patrol' || this.state === 'chase') {
this.walkCycle += delta * 8;
this.leftLeg.rotation.x = Math.sin(this.walkCycle) * 0.5;
this.rightLeg.rotation.x = -Math.sin(this.walkCycle) * 0.5;
this.leftArm.rotation.x = -Math.sin(this.walkCycle) * 0.3;
this.rightArm.rotation.x = Math.sin(this.walkCycle) * 0.3;
} else {
this.leftLeg.rotation.x *= 0.9;
this.rightLeg.rotation.x *= 0.9;
this.leftArm.rotation.x *= 0.9;
this.rightArm.rotation.x *= 0.9;
}

return false;
}

canSeePlayer() {
const dir = new THREE.Vector3().subVectors(camera.position, this.position).normalize();
const raycaster = new THREE.Raycaster(this.position.clone().add(new THREE.Vector3(0, 1.5, 0)), dir, 0, 80);
const intersects = raycaster.intersectObjects(mapObjects.map(o => o.mesh));
if (intersects.length > 0) {
const dist = intersects[0].distance;
const toPlayer = this.position.distanceTo(camera.position);
return dist > toPlayer - 1;
}
return true;
}

patrol(time) {
const dir = new THREE.Vector3().subVectors(this.patrolTarget, this.position);
dir.y = 0;
if (dir.length() < 2) {
this.patrolTarget.set(
this.position.x + (Math.random() - 0.5) * 40,
0,
this.position.z + (Math.random() - 0.5) * 40
);
}
dir.normalize();
this.rotation = Math.atan2(dir.x, dir.z);
this.position.x += dir.x * this.speed * 0.5;
this.position.z += dir.z * this.speed * 0.5;
this.clampPosition();
}

chasePlayer(time) {
if (!this.lastKnownPlayerPos) return;
const dir = new THREE.Vector3().subVectors(this.lastKnownPlayerPos, this.position);
dir.y = 0;
dir.normalize();
this.rotation = Math.atan2(dir.x, dir.z);
this.position.x += dir.x * this.speed;
this.position.z += dir.z * this.speed;
this.clampPosition();
}

combat(time, dist) {
const dir = new THREE.Vector3().subVectors(camera.position, this.position);
dir.y = 0;
dir.normalize();
this.rotation = Math.atan2(dir.x, dir.z);

// Strafe
const strafeDir = new THREE.Vector3(-dir.z, 0, dir.x);
const strafeAmount = Math.sin(time * 2) * 0.5;
this.position.x += strafeDir.x * strafeAmount * this.speed;
this.position.z += strafeDir.z * strafeAmount * this.speed;

// Shoot
const now = performance.now();
if (now - this.lastShot > this.fireRate) {
this.lastShot = now;
this.shootAtPlayer();
}
}

shootAtPlayer() {
const dir = new THREE.Vector3().subVectors(camera.position, this.position);
dir.y += (Math.random() - 0.5) * this.aimAccuracy * 5;
dir.x += (Math.random() - 0.5) * this.aimAccuracy * 5;
dir.z += (Math.random() - 0.5) * this.aimAccuracy * 5;
dir.normalize();

const raycaster = new THREE.Raycaster(
this.position.clone().add(new THREE.Vector3(0, 1.5, 0)),
dir, 0, 60
);

const intersects = raycaster.intersectObject(ground);
if (intersects.length > 0) {
// Muzzle flash
const flash = new THREE.PointLight(0xff6600, 2, 5);
flash.position.copy(this.position).add(new THREE.Vector3(0, 1.5, 0));
scene.add(flash);
setTimeout(() => scene.remove(flash), 50);

// Check if hits player
const playerPos = camera.position.clone();
const toPlayer = new THREE.Vector3().subVectors(playerPos, this.position.clone().add(new THREE.Vector3(0, 1.5, 0)));
const projected = toPlayer.dot(dir);
if (projected > 0) {
const closest = this.position.clone().add(new THREE.Vector3(0, 1.5, 0)).add(dir.clone().multiplyScalar(projected));
if (closest.distanceTo(playerPos) < 1.5) {
takeDamage(this.damage);
}
}
}
}

clampPosition() {
const limit = mapSize - 5;
this.position.x = Math.max(-limit, Math.min(limit, this.position.x));
this.position.z = Math.max(-limit, Math.min(limit, this.position.z));
}

takeDamage(amount) {
if (this.isDead) return;
this.health -= amount;
this.staggerTimer = 0.2;

if (this.health <= 0) {
this.isDead = true;
this.deathTimer = 0;
kills++;
playSound('kill');
addKillFeed('You', this.type);
document.getElementById('kill-count-display').textContent = kills;
}
}

remove() {
scene.remove(this.group);
}
}

let enemies = [];

function spawnEnemies() {
const positions = [
{ x: -40, z: -40, type: 'soldier' },
{ x: 40, z: -40, type: 'soldier' },
{ x: -40, z: 40, type: 'soldier' },
{ x: 40, z: 40, type: 'soldier' },
{ x: 0, z: -50, type: 'elite' },
{ x: 0, z: 50, type: 'elite' },
{ x: -50, z: 0, type: 'heavy' },
{ x: 50, z: 0, type: 'heavy' },
{ x: -60, z: -60, type: 'soldier' },
{ x: 60, z: -60, type: 'soldier' },
{ x: -60, z: 60, type: 'soldier' },
{ x: 60, z: 60, type: 'soldier' },
{ x: -20, z: -70, type: 'elite' },
{ x: 20, z: 70, type: 'elite' },
{ x: -70, z: 20, type: 'heavy' },
{ x: 70, z: -20, type: 'heavy' },
{ x: 0, z: -80, type: 'soldier' },
{ x: 0, z: 80, type: 'soldier' },
{ x: -80, z: 0, type: 'soldier' },
{ x: 80, z: 0, type: 'soldier' },
];

positions.forEach(p => {
enemies.push(new Enemy(p.x, p.z, p.type));
});
}

spawnEnemies();

// ============ BULLETS ============
const bullets = [];
const bulletGeo = new THREE.SphereGeometry(0.05, 4, 4);
const bulletMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });

function shootBullet() {
const weapon = weapons[currentWeapon];
const now = performance.now();

if (isReloading) return;
if (now - lastShot < weapon.fireRate) return;
if (weapon.ammo <= 0) {
playSound('empty');
reload();
return;
}

lastShot = now;
weapon.ammo--;

playSound(weapon.sound);

// Muzzle flash
if (weapon.muzzleFlash) {
const flash = new THREE.PointLight(0xff6600, 3, 10);
flash.position.copy(camera.position);
scene.add(flash);
setTimeout(() => scene.remove(flash), 50);
}

// Recoil
player.pitch += weapon.recoil * (Math.random() * 0.5 + 0.5);

const pellets = weapon.pellets || 1;
for (let p = 0; p < pellets; p++) {
const dir = new THREE.Vector3(0, 0, -1);
dir.applyQuaternion(camera.quaternion);
dir.x += (Math.random() - 0.5) * weapon.spread;
dir.y += (Math.random() - 0.5) * weapon.spread;
dir.z += (Math.random() - 0.5) * weapon.spread;
dir.normalize();

const bullet = new THREE.Mesh(bulletGeo, bulletMat);
bullet.position.copy(camera.position);
scene.add(bullet);

bullets.push({
mesh: bullet,
direction: dir.clone(),
speed: 2,
life: 2,
damage: weapon.damage,
origin: camera.position.clone()
});
}

updateHUD();
}

function updateBullets(delta) {
for (let i = bullets.length - 1; i >= 0; i--) {
const b = bullets[i];
b.mesh.position.add(b.direction.clone().multiplyScalar(b.speed));
b.life -= delta;

// Check enemy hits
let hit = false;
for (const enemy of enemies) {
if (enemy.isDead) continue;
const dist = b.mesh.position.distanceTo(enemy.position.clone().add(new THREE.Vector3(0, 1.5, 0)));
if (dist < 1.2) {
enemy.takeDamage(b.damage);
hit = true;
playSound('hit');
showHitMarker();
break;
}
}

// Check wall hits
if (!hit) {
for (const obj of mapObjects) {
const box = new THREE.Box3().setFromObject(obj.mesh);
if (box.containsPoint(b.mesh.position)) {
hit = true;
break;
}
}
}

if (hit || b.life <= 0) {
scene.remove(b.mesh);
bullets.splice(i, 1);
}
}
}

// ============ PLAYER CONTROLS ============
const keys = {};
let isLocked = false;

document.addEventListener('keydown', (e) => {
keys[e.code] = true;

if (e.code === 'KeyR') reload();
if (e.code === 'Digit1') switchWeapon(0);
if (e.code === 'Digit2') switchWeapon(1);
if (e.code === 'Digit3') switchWeapon(2);
});

document.addEventListener('keyup', (e) => {
keys[e.code] = false;
});

document.addEventListener('mousemove', (e) => {
if (!isLocked) return;
player.yaw -= e.movementX * 0.002;
player.pitch -= e.movementY * 0.002;
player.pitch = Math.max(-Math.PI / 2 + 0.1, Math.min(Math.PI / 2 - 0.1, player.pitch));
});

document.addEventListener('mousedown', (e) => {
if (!isLocked) return;
if (e.button === 0) shootBullet();
if (e.button === 2) {
isAiming = true;
// Zoom for sniper
if (currentWeapon === 2) {
camera.fov = 30;
camera.updateProjectionMatrix();
}
}
});

document.addEventListener('mouseup', (e) => {
if (e.button === 2) {
isAiming = false;
if (currentWeapon === 2) {
camera.fov = 75;
camera.updateProjectionMatrix();
}
}
});

document.addEventListener('contextmenu', (e) => e.preventDefault());

// Pointer lock
const blocker = document.getElementById('blocker');
const startBtn = document.getElementById('startBtn');

startBtn.addEventListener('click', () => {
renderer.domElement.requestPointerLock();
});

document.addEventListener('pointerlockchange', () => {
isLocked = document.pointerLockElement === renderer.domElement;
blocker.style.display = isLocked ? 'none' : 'flex';
});

// ============ RELOAD ============
function reload() {
const weapon = weapons[currentWeapon];
if (isReloading || weapon.ammo === weapon.maxAmmo || weapon.reserve <= 0) return;

isReloading = true;
playSound('reload');
document.getElementById('reload-indicator').style.display = 'block';

setTimeout(() => {
const needed = weapon.maxAmmo - weapon.ammo;
const available = Math.min(needed, weapon.reserve);
weapon.ammo += available;
weapon.reserve -= available;
isReloading = false;
document.getElementById('reload-indicator').style.display = 'none';
updateHUD();
}, weapon.reloadTime);
}

function switchWeapon(index) {
if (index === currentWeapon || isReloading) return;
currentWeapon = index;
isAiming = false;
camera.fov = 75;
camera.updateProjectionMatrix();

document.querySelectorAll('#weapon-slots .slot').forEach((s, i) => {
s.classList.toggle('active', i === index);
});

document.getElementById('weapon-name').textContent = weapons[index].name;
updateHUD();
}

// ============ COLLISION ============
function checkCollision(pos, radius) {
for (const obj of mapObjects) {
if (obj.height === undefined) continue;
if (pos.y > obj.height) continue;

const closestX = Math.max(obj.minX, Math.min(pos.x, obj.maxX));
const closestZ = Math.max(obj.minZ, Math.min(pos.z, obj.maxZ));
const distX = pos.x - closestX;
const distZ = pos.z - closestZ;

if (distX * distX + distZ * distZ < radius * radius) {
return true;
}
}
return false;
}

// ============ DAMAGE ============
function takeDamage(amount) {
player.health -= amount;
playSound('damage');

const overlay = document.getElementById('damage-overlay');
overlay.style.border = '20px solid rgba(255,0,0,0.4)';
setTimeout(() => {
overlay.style.border = '0px solid rgba(255,0,0,0)';
}, 200);

if (player.health <= 0) {
player.health = 0;
gameOver();
}
updateHUD();
}

function showHitMarker() {
const hm = document.getElementById('hit-marker');
hm.style.opacity = '1';
setTimeout(() => { hm.style.opacity = '0'; }, 150);
}

function addKillFeed(killer, victim) {
const feed = document.getElementById('kill-feed');
const entry = document.createElement('div');
entry.className = 'kill-entry';
entry.innerHTML = `<span style="color:#ff4400">${killer}</span> eliminated <span style="color:#aaa">${victim}</span>`;
feed.appendChild(entry);
setTimeout(() => entry.remove(), 3000);
}

function gameOver() {
document.getElementById('game-over').style.display = 'flex';
document.getElementById('final-kills').textContent = kills;
document.getElementById('final-deaths').textContent = deaths;
document.exitPointerLock();
}

// ============ HUD ============
function updateHUD() {
const weapon = weapons[currentWeapon];
document.getElementById('ammo-current').textContent = weapon.ammo;
document.getElementById('ammo-reserve').textContent = weapon.reserve;
document.getElementById('hp-val').textContent = Math.max(0, player.health);
document.getElementById('health-fill').style.width = Math.max(0, player.health) + '%';

if (player.health < 30) {
document.getElementById('health-fill').style.background = '#ff0000';
} else {
document.getElementById('health-fill').style.background = 'linear-gradient(90deg, #ff0000, #00ff00)';
}
}

// ============ MINIMAP ============
const minimapCanvas = document.getElementById('minimap-canvas');
const minimapCtx = minimapCanvas.getContext('2d');

function updateMinimap() {
minimapCtx.clearRect(0, 0, 180, 180);

// Background
minimapCtx.fillStyle = 'rgba(0,30,0,0.7)';
minimapCtx.fillRect(0, 0, 180, 180);

const scale = 0.8;
const cx = 90;
const cy = 90;

// Buildings
minimapCtx.fillStyle = 'rgba(100,100,100,0.8)';
for (const obj of mapObjects) {
if (!obj.height) continue;
const bx = cx + ((obj.minX + obj.maxX) / 2 - player.position.x) * scale;
const bz = cy + ((obj.minZ + obj.maxZ) / 2 - player.position.z) * scale;
const bw = (obj.maxX - obj.minX) * scale;
const bd = (obj.maxZ - obj.minZ) * scale;
if (bx > -20 && bx < 200 && bz > -20 && bz < 200) {
minimapCtx.fillRect(bx - bw/2, bz - bd/2, bw, bd);
}
}

// Enemies
for (const enemy of enemies) {
if (enemy.isDead) continue;
const ex = cx + (enemy.position.x - player.position.x) * scale;
const ez = cy + (enemy.position.z - player.position.z) * scale;
if (ex > 0 && ex < 180 && ez > 0 && ez < 180) {
minimapCtx.fillStyle = enemy.type === 'heavy' ? '#ff4444' : enemy.type === 'elite' ? '#ff8800' : '#ff0000';
minimapCtx.beginPath();
minimapCtx.arc(ex, ez, 3, 0, Math.PI * 2);
minimapCtx.fill();
}
}

// Player
minimapCtx.fillStyle = '#00ff00';
minimapCtx.beginPath();
minimapCtx.arc(cx, cy, 4, 0, Math.PI * 2);
minimapCtx.fill();

// Player direction
const dirX = cx + Math.sin(player.yaw) * -10;
const dirZ = cy + Math.cos(player.yaw) * -10;
minimapCtx.strokeStyle = '#00ff00';
minimapCtx.lineWidth = 2;
minimapCtx.beginPath();
minimapCtx.moveTo(cx, cy);
minimapCtx.lineTo(dirX, dirZ);
minimapCtx.stroke();
}

// ============ GAME LOOP ============
let lastTime = performance.now();
let fps = 0;
let frameCount = 0;
let fpsTime = 0;
let footstepTimer = 0;

function gameLoop() {
requestAnimationFrame(gameLoop);

const now = performance.now();
const delta = Math.min((now - lastTime) / 1000, 0.05);
lastTime = now;

// FPS counter
frameCount++;
fpsTime += delta;
if (fpsTime >= 1) {
fps = Math.round(frameCount / fpsTime);
document.getElementById('fps-counter').textContent = fps + ' FPS';
frameCount = 0;
fpsTime = 0;
}

if (!isLocked) {
renderer.render(scene, camera);
return;
}

const time = now / 1000;

// ============ PLAYER MOVEMENT ============
isSprinting = keys['ShiftLeft'] && stamina > 0 && !isCrouching;
isCrouching = keys['KeyC'];

const moveSpeed = isCrouching ? player.crouchSpeed : isSprinting ? player.sprintSpeed : player.speed;

// Stamina
if (isSprinting) {
stamina = Math.max(0, stamina - delta * 30);
} else {
stamina = Math.min(100, stamina + delta * 15);
}
document.getElementById('stamina-fill').style.width = stamina + '%';

// Movement direction
const forward = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));

const moveDir = new THREE.Vector3();
if (keys['KeyW']) moveDir.add(forward);
if (keys['KeyS']) moveDir.sub(forward);
if (keys['KeyA']) moveDir.sub(right);
if (keys['KeyD']) moveDir.add(right);

if (moveDir.length() > 0) {
moveDir.normalize();

const newPos = camera.position.clone();
newPos.x += moveDir.x * moveSpeed;
newPos.z += moveDir.z * moveSpeed;

// Collision check
if (!checkCollision(newPos, player.radius)) {
camera.position.x = newPos.x;
camera.position.z = newPos.z;
} else {
// Try sliding
const slideX = camera.position.clone();
slideX.x += moveDir.x * moveSpeed;
if (!checkCollision(slideX, player.radius)) {
camera.position.x = slideX.x;
}

const slideZ = camera.position.clone();
slideZ.z += moveDir.z * moveSpeed;
if (!checkCollision(slideZ, player.radius)) {
camera.position.z = slideZ.z;
}
}

// Footsteps
footstepTimer += delta;
if (footstepTimer > (isSprinting ? 0.3 : 0.5)) {
footstepTimer = 0;
playSound('footstep');
}
}

// Jump
if (keys['Space'] && player.onGround) {
player.velocity.y = player.jumpForce;
player.onGround = false;
}

// Gravity
player.velocity.y -= 0.01;
camera.position.y += player.velocity.y;

const targetHeight = isCrouching ? player.crouchHeight : player.height;
camera.position.y += (targetHeight - camera.position.y) * 0.1;

if (camera.position.y <= targetHeight) {
camera.position.y = targetHeight;
player.velocity.y = 0;
player.onGround = true;
}

// Clamp to map
camera.position.x = Math.max(-mapSize + 2, Math.min(mapSize - 2, camera.position.x));
camera.position.z = Math.max(-mapSize + 2, Math.min(mapSize - 2, camera.position.z));

// Camera rotation
camera.rotation.order = 'YXZ';
camera.rotation.y = player.yaw;
camera.rotation.x = player.pitch;

// Auto fire
const weapon = weapons[currentWeapon];
if (keys['Mouse0'] && weapon.auto) {
shootBullet();
}

// ============ UPDATE ENEMIES ============
for (let i = enemies.length - 1; i >= 0; i--) {
const dead = enemies[i].update(delta, time);
if (dead) {
enemies[i].remove();
enemies.splice(i, 1);
}
}

// ============ UPDATE BULLETS ============
updateBullets(delta);

// ============ UPDATE MINIMAP ============
updateMinimap();

// ============ RENDER ============
renderer.render(scene, camera);
}

// ============ RESIZE ============
window.addEventListener('resize', () => {
camera.aspect = window.innerWidth / window.innerHeight;
camera.updateProjectionMatrix();
renderer.setSize(window.innerWidth, window.innerHeight);
});

// ============ START ============
updateHUD();
gameLoop();
</script>
</body>
</html>
