    background: rgba(100, 80, 255, 0.2);
    color: #9988ff;
    border-color: rgba(100, 80, 255, 0.3);
  }

  .memory-indicator {
    font-size: 10px;
    color: #ffaa33;
    margin-left: 8px;
    opacity: 0;
    transition: opacity 0.2s;
  }

  .memory-indicator.show { opacity: 1; }

  @keyframes ripple {
    to { transform: scale(4); opacity: 0; }
  }

  .ripple {
    position: absolute;
    border-radius: 50%;
    background: rgba(255,255,255,0.15);
    width: 40px; height: 40px;
    transform: scale(0);
    animation: ripple 0.5s ease-out;
    pointer-events: none;
  }
</style>
</head>
<body>

<div class="calculator">
  <div class="header">
    <h1>Scientific Calc</h1>
    <div class="mode-toggle">
      <button class="mode-btn active" onclick="setMode('standard')">Standard</button>
      <button class="mode-btn" onclick="setMode('scientific')">Scientific</button>
      <button class="mode-btn" onclick="setMode('logical')">Logical</button>
    </div>
  </div>

  <div class="display">
    <div class="expression" id="expression"></div>
    <div class="result" id="result">0</div>
    <div class="base-display" id="baseDisplay"></div>
  </div>

  <!-- STANDARD PANEL -->
  <div class="panel active" id="panel-standard">
    <div class="btn-grid standard-grid">
      <button class="btn-clear" onclick="clearAll()">AC</button>
      <button class="btn-clear" onclick="deleteLast()">⌫</button>
      <button class="btn-function" onclick="inputParenthesis()"> ( ) </button>
      <button class="btn-operator" onclick="inputOperator('÷')">÷</button>

      <button class="btn-number" onclick="inputNumber('7')">7</button>
      <button class="btn-number" onclick="inputNumber('8')">8</button>
      <button class="btn-number" onclick="inputNumber('9')">9</button>
      <button class="btn-operator" onclick="inputOperator('×')">×</button>

      <button class="btn-number" onclick="inputNumber('4')">4</button>
      <button class="btn-number" onclick="inputNumber('5')">5</button>
      <button class="btn-number" onclick="inputNumber('6')">6</button>
      <button class="btn-operator" onclick="inputOperator('−')">−</button>

      <button class="btn-number" onclick="inputNumber('1')">1</button>
      <button class="btn-number" onclick="inputNumber('2')">2</button>
      <button class="btn-number" onclick="inputNumber('3')">3</button>
      <button class="btn-operator" onclick="inputOperator('+')">+</button>

      <button class="btn-function" onclick="inputPercent()">%</button>
      <button class="btn-number" onclick="inputNumber('0')">0</button>
      <button class="btn-number" onclick="inputDecimal()">.</button>
      <button class="btn-equals" onclick="calculate()">=</button>
    </div>
  </div>

  <!-- SCIENTIFIC PANEL -->
  <div class="panel" id="panel-scientific">
    <div class="angle-toggle">
      <button class="angle-btn active-angle" id="btnDeg" onclick="setAngleMode('deg')">DEG</button>
      <button class="angle-btn" id="btnRad" onclick="setAngleMode('rad')">RAD</button>
      <button class="angle-btn" id="btnGrad" onclick="setAngleMode('grad')">GRAD</button>
    </div>
    <div class="btn-grid scientific-grid">
      <button class="btn-function" onclick="inputFunction('sin')">sin</button>
      <button class="btn-function" onclick="inputFunction('cos')">cos</button>
      <button class="btn-function" onclick="inputFunction('tan')">tan</button>
      <button class="btn-function" onclick="inputFunction('log')">log</button>
      <button class="btn-function" onclick="inputFunction('ln')">ln</button>

      <button class="btn-function" onclick="inputFunction('asin')">sin⁻¹</button>
      <button class="btn-function" onclick="inputFunction('acos')">cos⁻¹</button>
      <button class="btn-function" onclick="inputFunction('atan')">tan⁻¹</button>
      <button class="btn-function" onclick="inputFunction('sqrt')">√</button>
      <button class="btn-function" onclick="inputFunction('cbrt')">∛</button>

      <button class="btn-function" onclick="inputOperator('^')">xʸ</button>
      <button class="btn-function" onclick="inputFunction('square')">x²</button>
      <button class="btn-function" onclick="inputFunction('cube')">x³</button>
      <button class="btn-function" onclick="inputFunction('exp')">eˣ</button>
      <button class="btn-function" onclick="inputFunction('tenpow')">10ˣ</button>

      <button class="btn-function" onclick="inputConstant('pi')">π</button>
      <button class="btn-function" onclick="inputConstant('e')">e</button>
      <button class="btn-function" onclick="inputFunction('fact')">n!</button>
      <button class="btn-function" onclick="inputFunction('inv')">1/x</button>
      <button class="btn-function" onclick="inputFunction('abs')">|x|</button>

      <button class="btn-function" onclick="inputParenthesis()"> ( ) </button>
      <button class="btn-clear" onclick="clearAll()">AC</button>
      <button class="btn-clear" onclick="deleteLast()">⌫</button>
      <button class="btn-operator" onclick="inputOperator('÷')">÷</button>
      <button class="btn-operator" onclick="inputOperator('×')">×</button>

      <button class="btn-number" onclick="inputNumber('7')">7</button>
      <button class="btn-number" onclick="inputNumber('8')">8</button>
      <button class="btn-number" onclick="inputNumber('9')">9</button>
      <button class="btn-operator" onclick="inputOperator('−')">−</button>
      <button class="btn-operator" onclick="inputOperator('+')">+</button>

      <button class="btn-number" onclick="inputNumber('4')">4</button>
      <button class="btn-number" onclick="inputNumber('5')">5</button>
      <button class="btn-number" onclick="inputNumber('6')">6</button>
      <button class="btn-function" onclick="inputPercent()">%</button>
      <button class="btn-function" onclick="inputFunction('negate')">±</button>

      <button class="btn-number" onclick="inputNumber('1')">1</button>
      <button class="btn-number" onclick="inputNumber('2')">2</button>
      <button class="btn-number" onclick="inputNumber('3')">3</button>
      <button class="btn-operator" onclick="memoryStore()">MS</button>
      <button class="btn-operator" onclick="memoryRecall()">MR</button>

      <button class="btn-number" onclick="inputNumber('0')">0</button>
      <button class="btn-number" onclick="inputDecimal()">.</button>
      <button class="btn-function" onclick="inputFunction('negate')">±</button>
      <button class="btn-equals span-2" onclick="calculate()">=</button>
    </div>
  </div>

  <!-- LOGICAL PANEL -->
  <div class="panel" id="panel-logical">
    <div class="angle-toggle">
      <button class="angle-btn active-angle active-base" id="btnDec" onclick="setBase('dec')">DEC</button>
      <button class="angle-btn" id="btnBin" onclick="setBase('bin')">BIN</button>
      <button class="angle-btn" id="btnOct" onclick="setBase('oct')">OCT</button>
      <button class="angle-btn" id="btnHex" onclick="setBase('hex')">HEX</button>
    </div>
    <div class="btn-grid logical-grid">
      <button class="btn-logical" onclick="logicalOp('AND')">AND</button>
      <button class="btn-logical" onclick="logicalOp('OR')">OR</button>
      <button class="btn-logical" onclick="logicalOp('XOR')">XOR</button>
      <button class="btn-logical" onclick="logicalOp('NOT')">NOT</button>

      <button class="btn-logical" onclick="logicalOp('<<')">«</button>
      <button class="btn-logical" onclick="logicalOp('>>')">»</button>
      <button class="btn-logical" onclick="logicalOp('NAND')">NAND</button>
      <button class="btn-logical" onclick="logicalOp('NOR')">NOR</button>

      <button class="btn-clear" onclick="clearAll()">AC</button>
      <button class="btn-clear" onclick="deleteLast()">⌫</button>
      <button class="btn-operator" onclick="inputOperator('÷')">÷</button>
      <button class="btn-operator" onclick="inputOperator('×')">×</button>

      <button class="btn-number" onclick="inputNumber('7')">7</button>
      <button class="btn-number" onclick="inputNumber('8')">8</button>
      <button class="btn-number" onclick="inputNumber('9')">9</button>
      <button class="btn-operator" onclick="inputOperator('−')">−</button>

      <button class="btn-number" onclick="inputNumber('4')">4</button>
      <button class="btn-number" onclick="inputNumber('5')">5</button>
      <button class="btn-number" onclick="inputNumber('6')">6</button>
      <button class="btn-operator" onclick="inputOperator('+')">+</button>

      <button class="btn-number" onclick="inputNumber('1')">1</button>
      <button class="btn-number" onclick="inputNumber('2')">2</button>
      <button class="btn-number" onclick="inputNumber('3')">3</button>
      <button class="btn-function" onclick="inputPercent()">%</button>

      <button class="btn-number" onclick="inputNumber('0')">0</button>
      <button class="btn-function" onclick="inputFunction('negate')">±</button>
      <button class="btn-function" onclick="inputFunction('hexInput')">0x</button>
      <button class="btn-equals" onclick="calculate()">=</button>
    </div>
  </div>
</div>

<script>
  let expression = '';
  let displayExpr = '';
  let currentResult = '0';
  let memory = 0;
  let angleMode = 'deg';
  let currentBase = 'dec';
  let justCalculated = false;
  let openParens = 0;

  const exprEl = document.getElementById('expression');
  const resultEl = document.getElementById('result');
  const baseEl = document.getElementById('baseDisplay');

  function updateDisplay() {
    exprEl.textContent = displayExpr;
    resultEl.textContent = currentResult;
    resultEl.classList.remove('error');
    updateBaseDisplay();
  }

  function updateBaseDisplay() {
    if (currentBase === 'dec') {
      const num = parseFloat(currentResult);
      if (!isNaN(num) && Number.isInteger(num) && num >= 0 && num < Math.pow(2, 32)) {
        baseEl.textContent = `BIN: ${num.toString(2)}  OCT: ${num.toString(8)}  HEX: ${num.toString(16).toUpperCase()}`;
      } else {
        baseEl.textContent = '';
      }
    } else if (currentBase === 'bin') {
      const num = parseInt(currentResult, 2);
      if (!isNaN(num)) {
        baseEl.textContent = `DEC: ${num}  HEX: ${num.toString(16).toUpperCase()}`;
      } else {
        baseEl.textContent = '';
      }
    } else if (currentBase === 'oct') {
      const num = parseInt(currentResult, 8);
      if (!isNaN(num)) {
        baseEl.textContent = `DEC: ${num}  HEX: ${num.toString(16).toUpperCase()}`;
      } else {
        baseEl.textContent = '';
      }
    } else if (currentBase === 'hex') {
      const num = parseInt(currentResult, 16);
      if (!isNaN(num)) {
        baseEl.textContent = `DEC: ${num}  BIN: ${num.toString(2)}`;
      } else {
        baseEl.textContent = '';
      }
    }
  }

  function setMode(mode) {
    document.querySelectorAll('.mode-btn').forEach(b => b.classList.remove('active'));
    event.target.classList.add('active');
    document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
    document.getElementById('panel-' + mode).classList.add('active');
  }

  function setAngleMode(mode) {
    angleMode = mode;
    document.querySelectorAll('.angle-btn').forEach(b => b.classList.remove('active-angle'));
    document.getElementById('btn' + mode.charAt(0).toUpperCase() + mode.slice(1)).classList.add('active-angle');
  }

  function setBase(base) {
    currentBase = base;
    document.querySelectorAll('.angle-btn').forEach(b => b.classList.remove('active-angle'));
    document.getElementById('btn' + base.charAt(0).toUpperCase() + base.slice(1)).classList.add('active-angle');
    updateBaseDisplay();
  }

  function toRadians(val) {
    if (angleMode === 'deg') return val * Math.PI / 180;
    if (angleMode === 'grad') return val * Math.PI / 200;
    return val;
  }

  function fromRadians(val) {
    if (angleMode === 'deg') return val * 180 / Math.PI;
    if (angleMode === 'grad') return val * 200 / Math.PI;
    return val;
  }

  function factorial(n) {
    if (n < 0) return NaN;
    if (n === 0 || n === 1) return 1;
    if (n > 170) return Infinity;
    if (!Number.isInteger(n)) return gamma(n + 1);
    let result = 1;
    for (let i = 2; i <= n; i++) result *= i;
    return result;
  }

  function gamma(z) {
    if (z < 0.5) return Math.PI / (Math.sin(Math.PI * z) * gamma(1 - z));
    z -= 1;
    const g = 7;
    const c = [0.99999999999980993,676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-0.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];
    let x = c[0];
    for (let i = 1; i < g + 2; i++) x += c[i] / (z + i);
    const t = z + g + 0.5;
    return Math.sqrt(2 * Math.PI) * Math.pow(t, z + 0.5) * Math.exp(-t) * x;
  }

  function inputNumber(num) {
    if (justCalculated) {
      expression = '';
      displayExpr = '';
      justCalculated = false;
    }
    expression += num;
    displayExpr += num;
    updateDisplay();
  }

  function inputDecimal() {
    if (justCalculated) {
      expression = '0';
      displayExpr = '0';
      justCalculated = false;
    }
    expression += '.';
    displayExpr += '.';
    updateDisplay();
  }

  function inputOperator(op) {
    if (justCalculated) {
      expression = currentResult;
      displayExpr = currentResult;
      justCalculated = false;
    }
    expression += ' ' + op + ' ';
    displayExpr += ' ' + op + ' ';
    updateDisplay();
  }

  function inputPercent() {
    expression += '/100';
    displayExpr += '%';
    updateDisplay();
  }

  function inputParenthesis() {
    if (justCalculated) {
      expression = '';
      displayExpr = '';
      justCalculated = false;
    }
    const lastChar = expression.trim().slice(-1);
    if (openParens > 0 && (lastChar === ' ' || lastChar === '' || isNaN(lastChar))) {
      // Check if we need implicit multiplication
    }
    expression += '(';
    displayExpr += '(';
    openParens++;
    updateDisplay();
  }

  function inputFunction(fn) {
    if (justCalculated) {
      justCalculated = false;
    }

    switch(fn) {
      case 'sin':
        expression += 'sin(';
        displayExpr += 'sin(';
        break;
      case 'cos':
        expression += 'cos(';
        displayExpr += 'cos(';
        break;
      case 'tan':
        expression += 'tan(';
        displayExpr += 'tan(';
        break;
      case 'asin':
        expression += 'asin(';
        displayExpr += 'sin⁻¹(';
        break;
      case 'acos':
        expression += 'acos(';
        displayExpr += 'cos⁻¹(';
        break;
      case 'atan':
        expression += 'atan(';
        displayExpr += 'tan⁻¹(';
        break;
      case 'log':
        expression += 'log10(';
        displayExpr += 'log(';
        break;
      case 'ln':
        expression += 'ln(';
        displayExpr += 'ln(';
        break;
      case 'sqrt':
        expression += 'sqrt(';
        displayExpr += '√(';
        break;
      case 'cbrt':
        expression += 'cbrt(';
        displayExpr += '∛(';
        break;
      case 'square':
        expression += ' ** 2';
        displayExpr += '²';
        break;
      case 'cube':
        expression += ' ** 3';
        displayExpr += '³';
        break;
      case 'exp':
        expression += 'exp(';
        displayExpr += 'e^(';
        break;
      case 'tenpow':
        expression += '10 ** (';
        displayExpr += '10^(';
        break;
      case 'fact':
        expression += 'fact(';
        displayExpr += 'fact(';
        break;
      case 'inv':
        expression = '(1/(' + expression + '))';
        displayExpr = '1/(' + displayExpr + ')';
        updateDisplay();
        return;
      case 'abs':
        expression += 'abs(';
        displayExpr += '|';
        break;
      case 'negate':
        if (expression.startsWith('-')) {
          expression = expression.slice(1);
          displayExpr = displayExpr.slice(1);
        } else {
          expression = '(-' + expression;
          displayExpr = '(-' + displayExpr;
        }
        updateDisplay();
        return;
      case 'hexInput':
        expression += '0x';
        displayExpr += '0x';
        break;
    }
    updateDisplay();
  }

  function inputConstant(c) {
    if (justCalculated) {
      expression = '';
      displayExpr = '';
      justCalculated = false;
    }
    if (c === 'pi') {
      expression += 'PI';
      displayExpr += 'π';
    } else if (c === 'e') {
      expression += 'E';
      displayExpr += 'e';
    }
    updateDisplay();
  }

  function logicalOp(op) {
    if (justCalculated) {
      justCalculated = false;
    }

    if (op === 'NOT') {
      expression = 'NOT(' + expression + ')';
      displayExpr = 'NOT(' + displayExpr + ')';
    } else if (op === '<<') {
      expression += ' << ';
      displayExpr += ' << ';
    } else if (op === '>>') {
      expression += ' >> ';
      displayExpr += ' >> ';
    } else {
      expression += ' ' + op + ' ';
      displayExpr += ' ' + op + ' ';
    }
    updateDisplay();
  }

  function memoryStore() {
    memory = parseFloat(currentResult) || 0;
  }

  function memoryRecall() {
    if (justCalculated) {
      expression = '';
      displayExpr = '';
      justCalculated = false;
    }
    expression += memory.toString();
    displayExpr += memory.toString();
    updateDisplay();
  }

  function clearAll() {
    expression = '';
    displayExpr = '';
    currentResult = '0';
    openParens = 0;
    justCalculated = false;
    updateDisplay();
  }

  function deleteLast() {
    if (justCalculated) {
      clearAll();
      return;
    }

    // Handle multi-character tokens
    const tokens = ['sin(', 'cos(', 'tan(', 'asin(', 'acos(', 'atan(', 'log10(', 'ln(', 'sqrt(', 'cbrt(', 'exp(', '10 ** (', 'fact(', 'abs(', '0x'];
    for (const token of tokens) {
      if (expression.endsWith(token)) {
        expression = expression.slice(0, -token.length);
        displayExpr = displayExpr.slice(0, -token.length);
        updateDisplay();
        return;
      }
    }

    if (expression.endsWith(' ** ')) {
      expression = expression.slice(0, -4);
      displayExpr = displayExpr.slice(0, -4);
    } else if (expression.endsWith(' **')) {
      expression = expression.slice(0, -2);
      displayExpr = displayExpr.slice(0, -2);
    } else if (expression.endsWith(' ** 2')) {
      expression = expression.slice(0, -5);
      displayExpr = displayExpr.slice(0, -1);
    } else if (expression.endsWith(' ** 3')) {
      expression = expression.slice(0, -5);
      displayExpr = displayExpr.slice(0, -1);
    } else if (expression.endsWith(' << ')) {
      expression = expression.slice(0, -4);
      displayExpr = displayExpr.slice(0, -4);
    } else if (expression.endsWith(' >> ')) {
      expression = expression.slice(0, -4);
      displayExpr = displayExpr.slice(0, -4);
    } else if (expression.endsWith(' AND ')) {
      expression = expression.slice(0, -5);
      displayExpr = displayExpr.slice(0, -5);
    } else if (expression.endsWith(' OR ')) {
      expression = expression.slice(0, -4);
      displayExpr = displayExpr.slice(0, -4);
    } else if (expression.endsWith(' XOR ')) {
      expression = expression.slice(0, -5);
      displayExpr = displayExpr.slice(0, -5);
    } else if (expression.endsWith(' NAND ')) {
      expression = expression.slice(0, -6);
      displayExpr = displayExpr.slice(0, -6);
    } else if (expression.endsWith(' NOR ')) {
      expression = expression.slice(0, -5);
      displayExpr = displayExpr.slice(0, -5);
    } else if (expression.endsWith(' + ')) {
      expression = expression.slice(0, -3);
      displayExpr = displayExpr.slice(0, -3);
    } else if (expression.endsWith(' − ')) {
      expression = expression.slice(0, -3);
      displayExpr = displayExpr.slice(0, -3);
    } else if (expression.endsWith(' × ')) {
      expression = expression.slice(0, -3);
      displayExpr = displayExpr.slice(0, -3);
    } else if (expression.endsWith(' ÷ ')) {
      expression = expression.slice(0, -3);
      displayExpr = displayExpr.slice(0, -3);
    } else if (expression.endsWith('/100')) {
      expression = expression.slice(0, -4);
      displayExpr = displayExpr.slice(0, -1);
    } else if (expression.endsWith('(')) {
      expression = expression.slice(0, -1);
      displayExpr = displayExpr.slice(0, -1);
      openParens = Math.max(0, openParens - 1);
    } else if (expression.endsWith(')')) {
      expression = expression.slice(0, -1);
      displayExpr = displayExpr.slice(0, -1);
    } else if (expression.endsWith('PI')) {
      expression = expression.slice(0, -2);
      displayExpr = displayExpr.slice(0, -1);
    } else if (expression.endsWith('E')) {
      expression = expression.slice(0, -1);
      displayExpr = displayExpr.slice(0, -1);
    } else {
      expression = expression.slice(0, -1);
      displayExpr = displayExpr.slice(0, -1);
    }

    if (expression.trim() === '') {
      currentResult = '0';
    }
    updateDisplay();
  }

  function evaluateExpression(expr) {
    // Replace display symbols with JS operators
    let e = expr;

    // Handle 0x hex prefix
    e = e.replace(/0x([0-9a-fA-F]+)/g, (match, hex) => parseInt(hex, 16).toString());

    // Handle bitwise operators
    e = e.replace(/<< /g, ' << ');
    e = e.replace(/ >> /g, ' >> ');
    e = e.replace(/ AND /g, '&');
    e = e.replace(/ OR /g, '|');
    e = e.replace(/ XOR /g, '^');
    e = e.replace(/ NAND /g, ' ~& ');
    e = e.replace(/ NOR /g, ' ~| ');

    // Handle NOT
    e = e.replace(/NOT\(/g, 'NOT_(');

    // Replace math functions
    e = e.replace(/sin\(/g, 'M.sin(');
    e = e.replace(/cos\(/g, 'M.cos(');
    e = e.replace(/tan\(/g, 'M.tan(');
    e = e.replace(/asin\(/g, 'M.asin(');
    e = e.replace(/acos\(/g, 'M.acos(');
    e = e.replace(/atan\(/g, 'M.atan(');
    e = e.replace(/log10\(/g, 'M.log10(');
    e = e.replace(/ln\(/g, 'M.ln(');
    e = e.replace(/sqrt\(/g, 'M.sqrt(');
    e = e.replace(/cbrt\(/g, 'M.cbrt(');
    e = e.replace(/exp\(/g, 'M.exp(');
    e = e.replace(/fact\(/g, 'M.fact(');
    e = e.replace(/abs\(/g, 'M.abs(');

    e = e.replace(/PI/g, 'Math.PI');
    e = e.replace(/\bE\b/g, 'Math.E');

    // Handle power
    e = e.replace(/\*\*/g, '**');

    // Handle NOT_ for bitwise NOT
    e = e.replace(/NOT_\(/g, '(~(');

    // Handle implicit multiplication: 2( -> 2*(
    e = e.replace(/(\d)\(/g, '$1*(');
    e = e.replace(/\)(\d)/g, ')*$1');
    e = e.replace(/\)\(/g, ')*(');

    // Handle factorial: number! -> fact(number)
    e = e.replace(/(\d+)!/g, 'M.fact($1)');

    try {
      const M = {
        sin: (x) => Math.sin(toRadians(x)),
        cos: (x) => Math.cos(toRadians(x)),
        tan: (x) => Math.tan(toRadians(x)),
        asin: (x) => fromRadians(Math.asin(x)),
        acos: (x) => fromRadians(Math.acos(x)),
        atan: (x) => fromRadians(Math.atan(x)),
        log10: (x) => Math.log10(x),
        ln: (x) => Math.log(x),
        sqrt: (x) => Math.sqrt(x),
        cbrt: (x) => Math.cbrt(x),
        exp: (x) => Math.exp(x),
        fact: (x) => factorial(x),
        abs: (x) => Math.abs(x),
      };

      // Safe evaluation using Function constructor
      const fn = new Function('M', 'return (' + e + ')');
      const result = fn(M);
      return result;
    } catch (err) {
      throw new Error('Invalid expression');
    }
  }

  function calculate() {
    if (!expression.trim()) return;

    // Close open parentheses
    let expr = expression;
    let disp = displayExpr;
    for (let i = 0; i < openParens; i++) {
      expr += ')';
      disp += ')';
    }

    try {
      const result = evaluateExpression(expr);

      if (isNaN(result)) {
        currentResult = 'NaN';
        resultEl.classList.add('error');
      } else if (!isFinite(result)) {
        currentResult = result > 0 ? '∞' : '-∞';
        resultEl.classList.add('error');
      } else {
        // Format result
        let formatted;
        if (Number.isInteger(result) && Math.abs(result) < Math.pow(10, 16)) {
          formatted = result.toString();
        } else {
          formatted = parseFloat(result.toPrecision(12)).toString();
        }
        currentResult = formatted;
        resultEl.classList.remove('error');
      }

      displayExpr = disp;
      justCalculated = true;
      openParens = 0;
      updateDisplay();
    } catch (err) {
      currentResult = 'Error';
      resultEl.classList.add('error');
      updateDisplay();
    }
  }

  // Keyboard support
  document.addEventListener('keydown', (e) => {
    e.preventDefault();
    const key = e.key;

    if (key >= '0' && key <= '9') inputNumber(key);
    else if (key === '.') inputDecimal();
    else if (key === '+') inputOperator('+');
    else if (key === '-') inputOperator('−');
    else if (key === '*') inputOperator('×');
    else if (key === '/') inputOperator('÷');
    else if (key === '%') inputPercent();
    else if (key === '(' || key === ')') inputParenthesis();
    else if (key === 'Enter' || key === '=') calculate();
    else if (key === 'Backspace') deleteLast();
    else if (key === 'Escape' || key === 'c' || key === 'C') clearAll();
  });

  updateDisplay();
