</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// ==================== GAME CONFIG ====================
const CONFIG = {
WORLD_SIZE: 2000,
BUILDING_COUNT: 400,
PEDESTRIAN_COUNT: 60,
TRAFFIC_COUNT: 30,
POLICE_COUNT: 5,
TREE_COUNT: 200,
CAR_TYPES: ['sedan', 'sports', 'truck', 'suv'],
MISSIONS: [
{ name: "First Blood", desc: "Rob the convenience store on 5th Ave", type: "robbery", reward: 5000, pos: {x: 80, z: -80} },
{ name: "Street Race", desc: "Win the race through downtown", type: "race", reward: 10000, pos: {x: -60, z: 60} },
{ name: "Package Delivery", desc: "Deliver the package to the docks", type: "delivery", reward: 7500, pos: {x: -150, z: -200} },
{ name: "Heist", desc: "Plan and execute the bank heist", type: "heist", reward: 50000, pos: {x: 0, z: 0} },
{ name: "Bounty Hunter", desc: "Eliminate the wanted criminal", type: "bounty", reward: 15000, pos: {x: 120, z: 120} },
{ name: "Smuggler Run", desc: "Transport contraband to the safehouse", type: "delivery", reward: 12000, pos: {x: -100, z: 180} },
{ name: "Street Rumble", desc: "Win the underground fight", type: "combat", reward: 8000, pos: {x: 160, z: -160} },
{ name: "Highway Robbery", desc: "Stop and rob the armored truck", type: "robbery", reward: 20000, pos: {x: -200, z: -100} }
],
DISTRICTS: [
{ name: "Downtown", x: 0, z: 0, color: 0x888899, buildingHeight: 40, density: 0.8 },
{ name: "Suburbs", x: 200, z: 200, color: 0x99aa88, buildingHeight: 12, density: 0.3 },
{ name: "Industrial", x: -200, z: -100, color: 0x777777, buildingHeight: 20, density: 0.5 },
{ name: "Beach", x: 0, z: -250, color: 0xddcc88, buildingHeight: 8, density: 0.2 },
{ name: "Countryside", x: 250, z: -200, color: 0x66aa44, buildingHeight: 5, density: 0.1 }
]
};

// ==================== GAME STATE ====================
const state = {
health: 100,
armor: 0,
money: 1000,
wantedLevel: 0,
wantedTimer: 0,
inVehicle: null,
currentMission: 0,
missionComplete: false,
dayTime: 0.3,
weather: 'clear',
weatherTimer: 0,
speed: 0,
isPaused: false,
isSprinting: false,
isGrounded: true,
weapons: [
{ name: 'Fist', ammo: Infinity, damage: 10, range: 3, type: 'melee' },
{ name: 'Pistol', ammo: 60, damage: 25, range: 100, type: 'shoot', fireRate: 300 },
{ name: 'Shotgun', ammo: 20, damage: 60, range: 50, type: 'shoot', fireRate: 800 },
{ name: 'Rifle', ammo: 30, damage: 45, range: 200, type: 'shoot', fireRate: 150 }
],
currentWeapon: 0,
lastFireTime: 0,
playerPos: new THREE.Vector3(0, 2, 50),
playerVel: new THREE.Vector3(),
cameraAngle: 0,
cameraPitch: 0.3,
keys: {},
mouseDown: false,
policeChasers: [],
npcs: [],
vehicles: [],
buildings: [],
bullets: [],
explosions: [],
missionMarkers: [],
trafficCars: [],
peds: [],
collectedItems: [],
gameTime: 0,
};

// ==================== THREE.JS SETUP ====================
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x88aacc, 0.0015);

const camera = new THREE.PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 2000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
document.body.appendChild(renderer.domElement);

// ==================== LIGHTING ====================
const ambientLight = new THREE.AmbientLight(0x404060, 0.4);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0xffeedd, 1.2);
sunLight.position.set(100, 100, 50);
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 4096;
sunLight.shadow.mapSize.height = 4096;
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 500;
sunLight.shadow.camera.left = -200;
sunLight.shadow.camera.right = 200;
sunLight.shadow.camera.top = 200;
sunLight.shadow.camera.bottom = -200;
scene.add(sunLight);

const hemiLight = new THREE.HemisphereLight(0x88aacc, 0x445522, 0.3);
scene.add(hemiLight);

// ==================== TEXTURES ====================
function createTexture(width, height, drawFn) {
const canvas = document.createElement('canvas');
canvas.width = width; canvas.height = height;
const ctx = canvas.getContext('2d');
drawFn(ctx, width, height);
const tex = new THREE.CanvasTexture(canvas);
tex.wrapS = THREE.RepeatWrapping;
tex.wrapT = THREE.RepeatWrapping;
return tex;
}

const roadTexture = createTexture(256, 256, (ctx, w, h) => {
ctx.fillStyle = '#333333';
ctx.fillRect(0, 0, w, h);
ctx.strokeStyle = '#ffff00';
ctx.lineWidth = 3;
ctx.setLineDash([20, 15]);
ctx.beginPath();
ctx.moveTo(w/2, 0); ctx.lineTo(w/2, h);
ctx.stroke();
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 2;
ctx.setLineDash([]);
ctx.beginPath(); ctx.moveTo(10, 0); ctx.lineTo(10, h); ctx.stroke();
ctx.beginPath(); ctx.moveTo(w-10, 0); ctx.lineTo(w-10, h); ctx.stroke();
});
roadTexture.repeat.set(10, 10);

const sidewalkTexture = createTexture(128, 128, (ctx, w, h) => {
ctx.fillStyle = '#999999';
ctx.fillRect(0, 0, w, h);
for (let i = 0; i < 20; i++) {
ctx.fillStyle = `rgba(${140+Math.random()*40}, ${140+Math.random()*40}, ${140+Math.random()*40}, 0.5)`;
ctx.fillRect(Math.random()*w, Math.random()*h, 20+Math.random()*20, 20+Math.random()*20);
}
});
sidewalkTexture.repeat.set(5, 5);

const grassTexture = createTexture(128, 128, (ctx, w, h) => {
ctx.fillStyle = '#44aa33';
ctx.fillRect(0, 0, w, h);
for (let i = 0; i < 500; i++) {
ctx.fillStyle = `rgba(${50+Math.random()*40}, ${150+Math.random()*60}, ${30+Math.random()*30}, 0.6)`;
ctx.fillRect(Math.random()*w, Math.random()*h, 2, 4);
}
});
grassTexture.repeat.set(20, 20);

const waterTexture = createTexture(256, 256, (ctx, w, h) => {
ctx.fillStyle = '#2266aa';
ctx.fillRect(0, 0, w, h);
for (let i = 0; i < 100; i++) {
ctx.fillStyle = `rgba(${40+Math.random()*30}, ${100+Math.random()*40}, ${180+Math.random()*40}, 0.3)`;
ctx.fillRect(Math.random()*w, Math.random()*h, 30+Math.random()*40, 3);
}
});
waterTexture.repeat.set(30, 30);

// ==================== GROUND ====================
function createGround() {
// Main ground
const groundGeo = new THREE.PlaneGeometry(CONFIG.WORLD_SIZE, CONFIG.WORLD_SIZE);
const groundMat = new THREE.MeshStandardMaterial({ map: grassTexture, roughness: 0.9 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Roads
const roadMat = new THREE.MeshStandardMaterial({ map: roadTexture, roughness: 0.8 });

// Main roads (grid pattern)
const roadWidth = 16;
const roadPositions = [];
for (let i = -3; i <= 3; i++) {
// Horizontal roads
const hRoad = new THREE.Mesh(
new THREE.PlaneGeometry(CONFIG.WORLD_SIZE, roadWidth),
roadMat
);
hRoad.rotation.x = -Math.PI / 2;
hRoad.position.set(0, 0.02, i * 120);
hRoad.receiveShadow = true;
scene.add(hRoad);
roadPositions.push({ x: 0, z: i * 120 });

// Vertical roads
const vRoad = new THREE.Mesh(
new THREE.PlaneGeometry(roadWidth, CONFIG.WORLD_SIZE),
roadMat
);
vRoad.rotation.x = -Math.PI / 2;
vRoad.position.set(i * 120, 0.02, 0);
vRoad.receiveShadow = true;
scene.add(vRoad);
roadPositions.push({ x: i * 120, z: 0 });
}

// Sidewalks
const sidewalkMat = new THREE.MeshStandardMaterial({ map: sidewalkTexture, roughness: 0.85 });
roadPositions.forEach(pos => {
const sw1 = new THREE.Mesh(new THREE.BoxGeometry(CONFIG.WORLD_SIZE, 0.15, 2), sidewalkMat);
sw1.position.set(pos.x, 0.075, pos.z + 9);
sw1.receiveShadow = true;
scene.add(sw1);
const sw2 = new THREE.Mesh(new THREE.BoxGeometry(CONFIG.WORLD_SIZE, 0.15, 2), sidewalkMat);
sw2.position.set(pos.x, 0.075, pos.z - 9);
sw2.receiveShadow = true;
scene.add(sw2);
const sw3 = new THREE.Mesh(new THREE.BoxGeometry(2, 0.15, CONFIG.WORLD_SIZE), sidewalkMat);
sw3.position.set(pos.x + 9, 0.075, pos.z);
sw3.receiveShadow = true;
scene.add(sw3);
const sw4 = new THREE.Mesh(new THREE.BoxGeometry(2, 0.15, CONFIG.WORLD_SIZE), sidewalkMat);
sw4.position.set(pos.x - 9, 0.075, pos.z);
sw4.receiveShadow = true;
scene.add(sw4);
});

// Beach area
const beachGeo = new THREE.PlaneGeometry(400, 150);
const beachMat = new THREE.MeshStandardMaterial({ color: 0xddcc88, roughness: 1 });
const beach = new THREE.Mesh(beachGeo, beachMat);
beach.rotation.x = -Math.PI / 2;
beach.position.set(0, 0.03, -280);
beach.receiveShadow = true;
scene.add(beach);

// Water (ocean)
const waterGeo = new THREE.PlaneGeometry(CONFIG.WORLD_SIZE, 300);
const waterMat = new THREE.MeshStandardMaterial({
map: waterTexture, color: 0x2266aa, transparent: true, opacity: 0.8,
roughness: 0.1, metalness: 0.3
});
const water = new THREE.Mesh(waterGeo, waterMat);
water.rotation.x = -Math.PI / 2;
water.position.set(0, -0.5, -450);
scene.add(water);

// Park area
const parkGeo = new THREE.PlaneGeometry(100, 100);
const parkMat = new THREE.MeshStandardMaterial({ color: 0x33aa22, roughness: 1 });
const park = new THREE.Mesh(parkGeo, parkMat);
park.rotation.x = -Math.PI / 2;
park.position.set(-150, 0.03, 150);
park.receiveShadow = true;
scene.add(park);
}

// ==================== BUILDINGS ====================
function createBuilding(x, z, w, d, h, district) {
const colors = {
downtown: [0x667788, 0x778899, 0x556677, 0x8899aa, 0x445566],
suburbs: [0xcc9966, 0xddaa77, 0xbb8855, 0xaa7744, 0xddbb88],
industrial: [0x777777, 0x888888, 0x666666, 0x999999, 0x555555],
beach: [0xeeccaa, 0xddbb99, 0xffddbb, 0xccaa88, 0xeebb99],
countryside: [0x88aa66, 0x779955, 0x99bb77, 0x668844, 0xaaCC88]
};
const colorList = colors[district] || colors.downtown;
const color = colorList[Math.floor(Math.random() * colorList.length)];

const geo = new THREE.BoxGeometry(w, h, d);
const mat = new THREE.MeshStandardMaterial({
color: color, roughness: 0.7, metalness: 0.1
});
const building = new THREE.Mesh(geo, mat);
building.position.set(x, h / 2, z);
building.castShadow = true;
building.receiveShadow = true;
scene.add(building);

// Windows
const windowMat = new THREE.MeshStandardMaterial({
color: 0xffffcc, emissive: 0xffffaa, emissiveIntensity: 0.1,
roughness: 0.3, metalness: 0.5
});
const windowSize = 1.5;
const windowGap = 4;
for (let wy = 3; wy < h - 2; wy += windowGap) {
for (let wx = -w/2 + 2; wx < w/2 - 1; wx += windowGap) {
// Front
const win = new THREE.Mesh(new THREE.PlaneGeometry(windowSize, windowSize * 1.3), windowMat);
win.position.set(x + wx, wy, z + d/2 + 0.05);
scene.add(win);
// Back
const win2 = win.clone();
win2.position.z = z - d/2 - 0.05;
win2.rotation.y = Math.PI;
scene.add(win2);
}
for (let wz = -d/2 + 2; wz < d/2 - 1; wz += windowGap) {
const win = new THREE.Mesh(new THREE.PlaneGeometry(windowSize, windowSize * 1.3), windowMat);
win.position.set(x + w/2 + 0.05, wy, z + wz);
win.rotation.y = Math.PI / 2;
scene.add(win);
const win2 = win.clone();
win2.position.x = x - w/2 - 0.05;
win2.rotation.y = -Math.PI / 2;
scene.add(win2);
}
}

// Roof detail
const roofGeo = new THREE.BoxGeometry(w * 0.3, 2, d * 0.3);
const roofMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.9 });
const roof = new THREE.Mesh(roofGeo, roofMat);
roof.position.set(x, h + 1, z);
roof.castShadow = true;
scene.add(roof);

state.buildings.push({
mesh: building, x, z, w, d, h,
centerX: x, centerZ: z,
halfW: w/2 + 1, halfD: d/2 + 1
});
}

function generateCity() {
CONFIG.DISTRICTS.forEach(district => {
const count = Math.floor(CONFIG.BUILDING_COUNT * district.density / 5);
for (let i = 0; i < count; i++) {
const angle = Math.random() * Math.PI * 2;
const dist = Math.random() * 100;
const bx = district.x + Math.cos(angle) * dist;
const bz = district.z + Math.sin(angle) * dist;

// Check if on road
let onRoad = false;
for (let r = -3; r <= 3; r++) {
if (Math.abs(bx - r * 120) < 10 || Math.abs(bz - r * 120) < 10) {
onRoad = true; break;
}
}
if (onRoad) continue;

const bw = 8 + Math.random() * 15;
const bd = 8 + Math.random() * 15;
const bh = district.buildingHeight * (0.3 + Math.random() * 0.7);

createBuilding(bx, bz, bw, bd, bh, district.name.toLowerCase());
}
});

// Street lights
const poleMat = new THREE.MeshStandardMaterial({ color: 0x555555, metalness: 0.8 });
const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffcc, emissive: 0xffffaa, emissiveIntensity: 0.5 });
for (let i = -4; i <= 4; i++) {
for (let j = -4; j <= 4; j++) {
if (Math.random() > 0.6) continue;
// Horizontal road lights
const pole1 = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 6), poleMat);
pole1.position.set(i * 120 + 10, 3, j * 120 + 8);
scene.add(pole1);
const bulb1 = new THREE.Mesh(new THREE.SphereGeometry(0.3), lightMat);
bulb1.position.set(i * 120 + 10, 6.2, j * 120 + 8);
scene.add(bulb1);
const pl1 = new THREE.PointLight(0xffddaa, 0.5, 20);
pl1.position.copy(bulb1.position);
scene.add(pl1);

// Vertical road lights
const pole2 = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 6), poleMat);
pole2.position.set(j * 120 + 8, 3, i * 120 + 10);
scene.add(pole2);
const bulb2 = new THREE.Mesh(new THREE.SphereGeometry(0.3), lightMat);
bulb2.position.set(j * 120 + 8, 6.2, i * 120 + 10);
scene.add(bulb2);
const pl2 = new THREE.PointLight(0xffddaa, 0.5, 20);
pl2.position.copy(bulb2.position);
scene.add(pl2);
}
}
}

// ==================== TREES ====================
function createTree(x, z) {
const trunkGeo = new THREE.CylinderGeometry(0.3, 0.4, 4, 6);
const trunkMat = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.9 });
const trunk = new THREE.Mesh(trunkGeo, trunkMat);
trunk.position.set(x, 2, z);
trunk.castShadow = true;
scene.add(trunk);

const leavesGeo = new THREE.SphereGeometry(2.5, 8, 6);
const leavesMat = new THREE.MeshStandardMaterial({ color: 0x228B22, roughness: 0.8 });
const leaves = new THREE.Mesh(leavesGeo, leavesMat);
leaves.position.set(x, 5.5, z);
leaves.castShadow = true;
scene.add(leaves);
}

function generateTrees() {
for (let i = 0; i < CONFIG.TREE_COUNT; i++) {
const x = (Math.random() - 0.5) * CONFIG.WORLD_SIZE * 0.8;
const z = (Math.random() - 0.5) * CONFIG.WORLD_SIZE * 0.8;

let onRoad = false;
for (let r = -3; r <= 3; r++) {
if (Math.abs(x - r * 120) < 12 || Math.abs(z - r * 120) < 12) {
onRoad = true; break;
}
}
if (onRoad) continue;

let inBuilding = false;
for (const b of state.buildings) {
if (Math.abs(x - b.centerX) < b.halfW && Math.abs(z - b.centerZ) < b.halfD) {
inBuilding = true; break;
}
}
if (inBuilding) continue;

if (z > -250 && z < -200) continue; // Beach area

createTree(x, z);
}
}

// ==================== PLAYER ====================
let playerGroup, playerBody;

function createPlayer() {
playerGroup = new THREE.Group();

// Body
const bodyGeo = new THREE.CylinderGeometry(0.3, 0.35, 1.2, 8);
const bodyMat = new THREE.MeshStandardMaterial({ color: 0x3366cc });
const body = new THREE.Mesh(bodyGeo, bodyMat);
body.position.y = 1.2;
body.castShadow = true;
playerGroup.add(body);

// Head
const headGeo = new THREE.SphereGeometry(0.25, 8, 8);
const headMat = new THREE.MeshStandardMaterial({ color: 0xffcc99 });
const head = new THREE.Mesh(headGeo, headMat);
head.position.y = 2.1;
head.castShadow = true;
playerGroup.add(head);

// Hair
const hairGeo = new THREE.SphereGeometry(0.27, 8, 6, 0, Math.PI * 2, 0, Math.PI / 2);
const hairMat = new THREE.MeshStandardMaterial({ color: 0x332211 });
const hair = new THREE.Mesh(hairGeo, hairMat);
hair.position.y = 2.15;
playerGroup.add(hair);

// Arms
const armGeo = new THREE.CylinderGeometry(0.08, 0.1, 0.7, 6);
const armMat = new THREE.MeshStandardMaterial({ color: 0x3366cc });
const leftArm = new THREE.Mesh(armGeo, armMat);
leftArm.position.set(-0.45, 1.3, 0);
leftArm.rotation.z = 0.2;
playerGroup.add(leftArm);
const rightArm = new THREE.Mesh(armGeo, armMat);
rightArm.position.set(0.45, 1.3, 0);
rightArm.rotation.z = -0.2;
playerGroup.add(rightArm);

// Legs
const legGeo = new THREE.CylinderGeometry(0.1, 0.12, 0.8, 6);
const legMat = new THREE.MeshStandardMaterial({ color: 0x333355 });
const leftLeg = new THREE.Mesh(legGeo, legMat);
leftLeg.position.set(-0.15, 0.4, 0);
playerGroup.add(leftLeg);
const rightLeg = new THREE.Mesh(legGeo, legMat);
rightLeg.position.set(0.15, 0.4, 0);
playerGroup.add(rightLeg);

playerGroup.position.copy(state.playerPos);
scene.add(playerGroup);

playerBody = body;
}

// ==================== VEHICLES ====================
function createVehicleMesh(type) {
const group = new THREE.Group();
let bodyColor, wheelColor;

switch(type) {
case 'sedan':
bodyColor = [0xcc3333, 0x3333cc, 0x33cc33, 0xcccc33, 0xffffff, 0x333333][Math.floor(Math.random()*6)];
break;
case 'sports':
bodyColor = [0xff4400, 0xffaa00, 0x00aaff, 0xff00aa, 0x00ff88][Math.floor(Math.random()*5)];
break;
case 'truck':
bodyColor = [0x888888, 0x666666, 0x999999, 0x446644][Math.floor(Math.random()*4)];
break;
case 'suv':
bodyColor = [0x224466, 0x442244, 0x224422, 0x664422][Math.floor(Math.random()*4)];
break;
}

const bodyMat = new THREE.MeshStandardMaterial({ color: bodyColor, roughness: 0.3, metalness: 0.6 });

if (type === 'sedan') {
const body = new THREE.Mesh(new THREE.BoxGeometry(2, 0.8, 4.2), bodyMat);
body.position.y = 0.6; body.castShadow = true;
group.add(body);
const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.7, 2), bodyMat);
cabin.position.set(0, 1.25, -0.2); cabin.castShadow = true;
group.add(cabin);
// Windshield
const glassMat = new THREE.MeshStandardMaterial({ color: 0x88aacc, transparent: true, opacity: 0.5, roughness: 0.1, metalness: 0.8 });
const windshield = new THREE.Mesh(new THREE.PlaneGeometry(1.7, 0.65), glassMat);
windshield.position.set(0, 1.2, 0.8); windshield.rotation.x = -0.3;
group.add(windshield);
} else if (type === 'sports') {
const body = new THREE.Mesh(new THREE.BoxGeometry(2.1, 0.6, 4.5), bodyMat);
body.position.y = 0.5; body.castShadow = true;
group.add(body);
const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.55, 1.8), bodyMat);
cabin.position.set(0, 1.05, -0.1); cabin.castShadow = true;
group.add(cabin);
} else if (type === 'truck') {
const cab = new THREE.Mesh(new THREE.BoxGeometry(2.5, 1.5, 2.5), bodyMat);
cab.position.set(0, 1.0, 1.2); cab.castShadow = true;
group.add(cab);
const trailer = new THREE.Mesh(new THREE.BoxGeometry(2.5, 1.8, 3),
new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.8 }));
trailer.position.set(0, 1.1, -1.5); trailer.castShadow = true;
group.add(trailer);
} else if (type === 'suv') {
const body = new THREE.Mesh(new THREE.BoxGeometry(2.3, 1.2, 4.5), bodyMat);
body.position.y = 0.8; body.castShadow = true;
group.add(body);
const cabin = new THREE.Mesh(new THREE.BoxGeometry(2.1, 0.8, 2.5), bodyMat);
cabin.position.set(0, 1.7, -0.2); cabin.castShadow = true;
group.add(cabin);
}

// Wheels
