// ==================== COLLISION DETECTION ====================
function checkBuildingCollision(x, z, radius) {
for (const b of state.buildings) {
if (x + radius > b.centerX - b.halfW && x - radius < b.centerX + b.halfW &&
z + radius > b.centerZ - b.halfD && z - radius < b.centerZ + b.halfD) {
return b;
}
}
return null;
}

function resolveCollision(entity, newX, newZ, radius) {
const blocked = checkBuildingCollision(newX, newZ, radius);
if (blocked) {
// Slide along walls
const dx = newX - blocked.centerX;
const dz = newZ - blocked.centerZ;
const overlapX = blocked.halfW - Math.abs(dx);
const overlapZ = blocked.halfD - Math.abs(dz);

if (overlapX < overlapZ) {
newX = blocked.centerX + Math.sign(dx) * blocked.halfW;
} else {
newZ = blocked.centerZ + Math.sign(dz) * blocked.halfD;
}
}
return { x: newX, z: newZ };
}

// ==================== INPUT HANDLING ====================
document.addEventListener('keydown', e => {
state.keys[e.code] = true;
if (e.code === 'Escape') togglePause();
if (e.code === 'KeyF' && !state.inVehicle) toggleSprint();
if (e.code === 'KeyE') interact();
if (e.code === 'KeyQ') exitVehicle();
if (e.code === 'Digit1') switchWeapon(0);
if (e.code === 'Digit2') switchWeapon(1);
if (e.code === 'Digit3') switchWeapon(2);
if (e.code === 'Digit4') switchWeapon(3);
});

document.addEventListener('keyup', e => {
state.keys[e.code] = false;
if (e.code === 'KeyF') state.isSprinting = false;
});

document.addEventListener('mousedown', e => {
if (e.button === 0) {
state.mouseDown = true;
if (!state.inVehicle) shoot();
}
});

document.addEventListener('mouseup', e => {
if (e.button === 0) state.mouseDown = false;
});

document.addEventListener('mousemove', e => {
if (document.pointerLockElement) {
state.cameraAngle -= e.movementX * 0.003;
state.cameraPitch = Math.max(-0.5, Math.min(1.2, state.cameraPitch + e.movementY * 0.003));
}
});

renderer.domElement.addEventListener('click', () => {
if (!state.isPaused) renderer.domElement.requestPointerLock();
});

function togglePause() {
state.isPaused = !state.isPaused;
document.getElementById('pause-menu').style.display = state.isPaused ? 'flex' : 'none';
if (state.isPaused) document.exitPointerLock();
else renderer.domElement.requestPointerLock();
}

function resumeGame() {
state.isPaused = false;
document.getElementById('pause-menu').style.display = 'none';
renderer.domElement.requestPointerLock();
}

function restartGame() {
location.reload();
}

function toggleSprint() {
state.isSprinting = !state.isSprinting;
}

function switchWeapon(idx) {
if (idx < state.weapons.length) {
state.currentWeapon = idx;
updateWeaponUI();
}
}

function updateWeaponUI() {
const w = state.weapons[state.currentWeapon];
document.getElementById('weapon-name').textContent = w.name;
document.getElementById('ammo-display').textContent = w.ammo === Infinity ? '∞' : w.ammo;
}

function interact() {
if (state.inVehicle) {
exitVehicle();
return;
}

// Check for vehicle entry
let closestVehicle = null;
let closestDist = 5;
state.vehicles.forEach(v => {
if (v.isPlayer) return;
const dist = playerGroup.position.distanceTo(v.mesh.position);
if (dist < closestDist) {
closestDist = dist;
closestVehicle = v;
}
});

if (closestVehicle) {
enterVehicle(closestVehicle);
return;
}

// Check mission markers
state.missionMarkers.forEach((marker, i) => {
if (marker.completed) return;
const dist = playerGroup.position.distanceTo(marker.group.position);
if (dist < 5) {
startMission(i);
}
});
}

function enterVehicle(vehicle) {
state.inVehicle = vehicle;
vehicle.isPlayer = true;
vehicle.driver = 'player';
playerGroup.visible = false;

const weapon = state.weapons[state.currentWeapon];
if (weapon.name !== 'Fist') {
vehicle.hasWeapon = true;
}
}

function exitVehicle() {
if (!state.inVehicle) return;
const v = state.inVehicle;
v.isPlayer = false;
v.driver = null;

playerGroup.visible = true;
playerGroup.position.copy(v.mesh.position);
playerGroup.position.x += 2.5;
state.playerPos.copy(playerGroup.position);

state.inVehicle = null;
}

// ==================== SHOOTING ====================
function shoot() {
const weapon = state.weapons[state.currentWeapon];
const now = Date.now();
if (now - state.lastFireTime < weapon.fireRate) return;
if (weapon.ammo <= 0 && weapon.ammo !== Infinity) return;

state.lastFireTime = now;
if (weapon.ammo !== Infinity) weapon.ammo--;
updateWeaponUI();

// Muzzle flash
const flash = new THREE.PointLight(0xffaa00, 3, 15);
flash.position.copy(playerGroup.position);
flash.position.y += 1.5;
scene.add(flash);
setTimeout(() => scene.remove(flash), 50);

if (weapon.type === 'melee') {
// Melee attack
state.peds.forEach(ped => {
if (ped.isDead) return;
const dist = playerGroup.position.distanceTo(ped.mesh.position);
if (dist < 3) {
ped.health -= weapon.damage;
if (ped.health <= 0) {
ped.isDead = true;
ped.mesh.rotation.x = Math.PI / 2;
ped.mesh.position.y = 0.3;
}
}
});
} else {
// Bullet
const dir = new THREE.Vector3(0, 0, -1);
dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), state.cameraAngle);
dir.applyAxisAngle(new THREE.Vector3(1, 0, 0), state.cameraPitch);

const bulletGeo = new THREE.SphereGeometry(0.1);
const bulletMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });
const bullet = new THREE.Mesh(bulletGeo, bulletMat);
bullet.position.copy(playerGroup.position);
bullet.position.y += 1.5;
scene.add(bullet);

const bulletVel = dir.multiplyScalar(200);
state.bullets.push({
mesh: bullet,
velocity: bulletVel,
life: 2,
damage: weapon.damage,
isPlayer: true
});

// Increase wanted level
if (weapon.name !== 'Fist') {
increaseWanted(0.5);
}
}
}

function increaseWanted(amount) {
state.wantedLevel = Math.min(5, state.wantedLevel + amount);
updateWantedUI();
}

function updateWantedUI() {
for (let i = 1; i <= 5; i++) {
document.getElementById('s' + i).className = i <= Math.floor(state.wantedLevel) ? 'star active' : 'star';
}
}

