// ==================== DAY/NIGHT CYCLE ====================
function updateDayNight(dt) {
state.dayTime += dt * 0.005;
if (state.dayTime > 1) state.dayTime -= 1;

const sunAngle = state.dayTime * Math.PI * 2 - Math.PI / 2;
const sunY = Math.sin(sunAngle);
const sunX = Math.cos(sunAngle) * 100;

sunLight.position.set(sunX, Math.max(sunY * 100, 5), 50);

const dayFactor = Math.max(0, Math.min(1, sunY * 2 + 0.5));
sunLight.intensity = dayFactor * 1.5;
ambientLight.intensity = 0.15 + dayFactor * 0.35;

const skyR = Math.floor(20 + dayFactor * 100);
const skyG = Math.floor(20 + dayFactor * 120);
const skyB = Math.floor(40 + dayFactor * 140);
scene.background = new THREE.Color(`rgb(${skyR},${skyG},${skyB})`);
scene.fog.color = new THREE.Color(`rgb(${skyR},${skyG},${skyB})`);

renderer.toneMappingExposure = 0.5 + dayFactor * 0.8;

const indicator = document.getElementById('day-night-indicator');
if (dayFactor > 0.6) indicator.textContent = '☀️ Day';
else if (dayFactor > 0.3) indicator.textContent = '🌅 Dusk';
else indicator.textContent = '🌙 Night';

// Window lights at night
state.buildings.forEach(b => {
b.mesh.material.emissiveIntensity = dayFactor < 0.3 ? 0.05 : 0;
});
}

// ==================== MINIMAP ====================
const minimapCanvas = document.getElementById('minimap');
const minimapCtx = minimapCanvas.getContext('2d');

function updateMinimap() {
const ctx = minimapCtx;
const size = 180;
const scale = 0.3;

ctx.fillStyle = '#222';
ctx.fillRect(0, 0, size, size);

const px = playerGroup.position.x;
const pz = playerGroup.position.z;

// Draw roads
ctx.strokeStyle = '#444';
ctx.lineWidth = 2;
for (let i = -3; i <= 3; i++) {
const rx = (i * 120 - px) * scale + size / 2;
const rz = (i * 120 - pz) * scale + size / 2;
ctx.beginPath();
ctx.moveTo(rx, 0); ctx.lineTo(rx, size);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(0, rz); ctx.lineTo(size, rz);
ctx.stroke();
}

// Draw buildings
ctx.fillStyle = '#555';
state.buildings.forEach(b => {
const bx = (b.centerX - px) * scale + size / 2;
const bz = (b.centerZ - pz) * scale + size / 2;
const bw = b.w * scale;
const bd = b.d * scale;
if (bx > -20 && bx < size + 20 && bz > -20 && bz < size + 20) {
ctx.fillRect(bx - bw/2, bz - bd/2, bw, bd);
}
});

// Draw mission markers
state.missionMarkers.forEach(m => {
const mx = (m.mission.pos.x - px) * scale + size / 2;
const mz = (m.mission.pos.z - pz) * scale + size / 2;
if (mx > 0 && mx < size && mz > 0 && mz < size) {
ctx.fillStyle = m.completed ? '#444' : '#ff6600';
ctx.beginPath();
ctx.arc(mx, mz, 4, 0, Math.PI * 2);
ctx.fill();
}
});

// Draw vehicles
ctx.fillStyle = '#6666ff';
state.vehicles.forEach(v => {
if (v.isPlayer) return;
const vx = (v.mesh.position.x - px) * scale + size / 2;
const vz = (v.mesh.position.z - pz) * scale + size / 2;
if (vx > 0 && vx < size && vz > 0 && vz < size) {
ctx.fillRect(vx - 2, vz - 2, 4, 4);
}
});

// Draw police
ctx.fillStyle = '#ff3333';
state.policeChasers.forEach(p => {
const ppx = (p.mesh.position.x - px) * scale + size / 2;
const ppz = (p.mesh.position.z - pz) * scale + size / 2;
if (ppx > 0 && ppx < size && ppz > 0 && ppz < size) {
ctx.fillRect(ppx - 2, ppz - 2, 4, 4);
}
});

// Draw player (center)
ctx.fillStyle = '#00ff00';
ctx.beginPath();
ctx.arc(size / 2, size / 2, 4, 0, Math.PI * 2);
ctx.fill();

// Player direction
const dirX = Math.sin(state.cameraAngle) * 10;
const dirZ = Math.cos(state.cameraAngle) * 10;
ctx.strokeStyle = '#00ff00';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(size / 2, size / 2);
ctx.lineTo(size / 2 + dirX, size / 2 + dirZ);
ctx.stroke();

// Circular mask
ctx.globalCompositeOperation = 'destination-in';
ctx.beginPath();
ctx.arc(size / 2, size / 2, size / 2, 0, Math.PI * 2);
ctx.fill();
ctx.globalCompositeOperation = 'source-over';
}

// ==================== UPDATE FUNCTIONS ====================
function updatePlayer(dt) {
if (state.inVehicle) return;

const speed = state.isSprinting ? 12 : 6;
const moveX = Math.sin(state.cameraAngle);
const moveZ = Math.cos(state.cameraAngle);

let moveDirX = 0, moveDirZ = 0;

if (state.keys['KeyW']) { moveDirX += moveX; moveDirZ += moveZ; }
if (state.keys['KeyS']) { moveDirX -= moveX; moveDirZ -= moveZ; }
if (state.keys['KeyA']) { moveDirX -= moveZ; moveDirZ += moveX; }
if (state.keys['KeyD']) { moveDirX += moveZ; moveDirZ -= moveX; }

if (moveDirX !== 0 || moveDirZ !== 0) {
const len = Math.sqrt(moveDirX * moveDirX + moveDirZ * moveDirZ);
moveDirX /= len;
moveDirZ /= len;

let newX = playerGroup.position.x + moveDirX * speed * dt;
let newZ = playerGroup.position.z + moveDirZ * speed * dt;

const resolved = resolveCollision(playerGroup, newX, newZ, 0.5);
playerGroup.position.x = resolved.x;
playerGroup.position.z = resolved.z;

playerGroup.rotation.y = Math.atan2(moveDirX, moveDirZ);

// Walking animation
state.gameTime += dt * (state.isSprinting ? 12 : 8);
const walkCycle = Math.sin(state.gameTime);
if (playerGroup.children[3]) playerGroup.children[3].rotation.x = walkCycle * 0.5;
if (playerGroup.children[4]) playerGroup.children[4].rotation.x = -walkCycle * 0.5;
if (playerGroup.children[2]) playerGroup.children[2].rotation.x = -walkCycle * 0.3;
if (playerGroup.children[5]) playerGroup.children[5].rotation.x = walkCycle * 0.3;
}

// Jump
if (state.keys['Space'] && state.isGrounded) {
state.playerVel.y = 8;
state.isGrounded = false;
}

// Gravity
state.playerVel.y -= 20 * dt;
playerGroup.position.y += state.playerVel.y * dt;

if (playerGroup.position.y <= 0) {
playerGroup.position.y = 0;
state.playerVel.y = 0;
state.isGrounded = true;
}

state.playerPos.copy(playerGroup.position);
}

function updateCamera() {
let camTarget, camDist, camHeight;

if (state.inVehicle) {
camTarget = state.inVehicle.mesh.position;
camDist = 12;
camHeight = 5;
} else {
camTarget = playerGroup.position.clone();
camTarget.y += 1.5;
camDist = 8;
camHeight = 4;
}

const camX = camTarget.x - Math.sin(state.cameraAngle) * camDist * Math.cos(state.cameraPitch);
const camY = camTarget.y + camHeight * Math.cos(state.cameraPitch) + camDist * Math.sin(state.cameraPitch);
const camZ = camTarget.z - Math.cos(state.cameraAngle) * camDist * Math.cos(state.cameraPitch);

camera.position.lerp(new THREE.Vector3(camX, camY, camZ), 0.1);
camera.lookAt(camTarget);
}

function updateVehicles(dt) {
state.vehicles.forEach(v => {
if (v.isPlayer) {
// Player driving
if (state.keys['KeyW'] || state.keys['ArrowUp']) {
v.speed = Math.min(v.maxSpeed, v.speed + v.acceleration * dt);
} else if (state.keys['KeyS'] || state.keys['ArrowDown']) {
v.speed = Math.max(-v.maxSpeed * 0.4, v.speed - v.acceleration * dt * 1.5);
} else {
v.speed *= (1 - 2 * dt);
}

if (Math.abs(v.speed) > 0.5) {
const steerAmount = 2.5 * dt * (v.speed / v.maxSpeed);
if (state.keys['KeyA'] || state.keys['ArrowLeft']) {
v.mesh.rotation.y += steerAmount * Math.sign(v.speed);
}
if (state.keys['KeyD'] || state.keys['ArrowRight']) {
v.mesh.rotation.y -= steerAmount * Math.sign(v.speed);
}
}

const dir = new THREE.Vector3(0, 0, 1);
dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), v.mesh.rotation.y);
const newX = v.mesh.position.x + dir.x * v.speed * dt;
const newZ = v.mesh.position.z + dir.z * v.speed * dt;

const resolved = resolveCollision(v.mesh, newX, newZ, 2);
v.mesh.position.x = resolved.x;
v.mesh.position.z = resolved.z;

// Hit pedestrians
state.peds.forEach(ped => {
if (ped.isDead) return;
const dist = v.mesh.position.distanceTo(ped.mesh.position);
if (dist < 2.5 && Math.abs(v.speed) > 5) {
ped.health -= Math.abs(v.speed) * 5;
if (ped.health <= 0) {
ped.isDead = true;
ped.mesh.rotation.x = Math.PI / 2;
ped.mesh.position.y = 0.3;
increaseWanted(1);
}
}
});

state.speed = Math.abs(v.speed);
document.getElementById('speed-display').style.display = 'block';
document.getElementById('speed-display').textContent = Math.floor(state.speed * 3) + ' km/h';

} else if (v.isTraffic) {
// Traffic AI
const dir = new THREE.Vector3(0, 0, 1);
dir.applyAxisAngle(new THREE.Vector3(0, 1, 0), v.mesh.rotation.y);

const newX = v.mesh.position.x + dir.x * v.trafficSpeed * dt;
const newZ = v.mesh.position.z + dir.z * v.trafficSpeed * dt;

// Wrap around world
if (newX > CONFIG.WORLD_SIZE / 2 || newX < -CONFIG.WORLD_SIZE / 2 ||
newZ > CONFIG.WORLD_SIZE / 2 || newZ < -CONFIG.WORLD_SIZE / 2) {
v.mesh.position.x = -newX;
v.mesh.position.z = -newZ;
} else {
v.mesh.position.x = newX;
v.mesh.position.z = newZ;
}

// Avoid player
if (state.inVehicle && state.inVehicle === v) return;
const playerDist = v.mesh.position.distanceTo(state.playerPos);
if (playerDist < 15) {
const awayDir = new THREE.Vector3().subVectors(v.mesh.position, state.playerPos).normalize();
v.mesh.position.x += awayDir.x * dt * 5;
v.mesh.position.z += awayDir.z * dt * 5;
}
}
});

if (!state.inVehicle) {
document.getElementById('speed-display').style.display = 'none';
}
}

function updatePeds(dt) {
state.peds.forEach(ped => {
if (ped.isDead) return;

ped.changeTimer -= dt;
if (ped.changeTimer <= 0) {
ped.changeTimer = 2 + Math.random() * 4;
ped.velocity.set(
(Math.random() - 0.5) * 4,
0,
(Math.random() - 0.5) * 4
);
ped.mesh.rotation.y = Math.atan2(ped.velocity.x, ped.velocity.z);
}

let newX = ped.mesh.position.x + ped.velocity.x * dt;
let newZ = ped.mesh.position.z + ped.velocity.z * dt;

// Keep in bounds
const halfWorld = CONFIG.WORLD_SIZE * 0.4;
if (newX < -halfWorld || newX > halfWorld || newZ < -halfWorld || newZ > halfWorld) {
ped.velocity.x *= -1;
ped.velocity.z *= -1;
ped.mesh.rotation.y = Math.atan2(ped.velocity.x, ped.velocity.z);
}

const resolved = resolveCollision(ped.mesh, newX, newZ, 0.5);
ped.mesh.position.x = resolved.x;
ped.mesh.position.z = resolved.z;

// Walking animation
ped.animPhase += dt * 6;
if (ped.mesh.children[3]) ped.mesh.children[3].rotation.x = Math.sin(ped.animPhase) * 0.5;
if (ped.mesh.children[4]) ped.mesh.children[4].rotation.x = -Math.sin(ped.animPhase) * 0.5;

// Flee from player if wanted
if (state.wantedLevel > 0) {
const distToPlayer = ped.mesh.position.distanceTo(state.playerPos);
if (distToPlayer < 15) {
const fleeDir = new THREE.Vector3().subVectors(ped.mesh.position, state.playerPos).normalize();
ped.velocity.x = fleeDir.x * 6;
ped.velocity.z = fleeDir.z * 6;
ped.changeTimer = 0.5;
}
}

// Enemies attack player
if (ped.isEnemy && state.wantedLevel > 0) {
const distToPlayer = ped.mesh.position.distanceTo(state.playerPos);
if (distToPlayer < 30 && distToPlayer > 3) {
const dir = new THREE.Vector3().subVectors(state.playerPos, ped.mesh.position).normalize();
ped.velocity.x = dir.x * 5;
ped.velocity.z = dir.z * 5;
ped.changeTimer = 0.1;
}
if (distToPlayer < 3) {
// Attack player
state.health -= 0.5;
updateHealthUI();
}
}
});
}

function updatePolice(dt) {
state.policeChasers.forEach(cop => {
if (state.wantedLevel <= 0) {
// Patrol
cop.changeTimer = (cop.changeTimer || 0) - dt;
if (cop.changeTimer <= 0) {
cop.changeTimer = 3 + Math.random() * 5;
cop.patrolTarget = new THREE.Vector3(
playerGroup.position.x + (Math.random() - 0.5) * 100,
0,
playerGroup.position.z + (Math.random() - 0.5) * 100
);
}
if (cop.patrolTarget) {
const dir = new THREE.Vector3().subVectors(cop.patrolTarget, cop.mesh.position).normalize();
cop.mesh.position.x += dir.x * cop.speed * 0.3 * dt;
cop.mesh.position.z += dir.z * cop.speed * 0.3 * dt;
cop.mesh.rotation.y = Math.atan2(dir.x, dir.z);
}

// Walking animation
cop.animPhase += dt * 4;
if (cop.mesh.children[2]) cop.mesh.children[2].rotation.x = Math.sin(cop.animPhase) * 0.4;
if (cop.mesh.children[3]) cop.mesh.children[3].rotation.x = -Math.sin(cop.animPhase) * 0.4;
return;
}

// Chase player
const dir = new THREE.Vector3().subVectors(state.playerPos, cop.mesh.position);
dir.y = 0;
const dist = dir.length();
dir.normalize();

const chaseSpeed = cop.speed * (1 + state.wantedLevel * 0.2);
cop.mesh.position.x += dir.x * chaseSpeed * dt;
cop.mesh.position.z += dir.z * chaseSpeed * dt;
cop.mesh.rotation.y = Math.atan2(dir.x, dir.z);

// Walking animation
cop.animPhase += dt * 8;
if (cop.mesh.children[2]) cop.mesh.children[2].rotation.x = Math.sin(cop.animPhase) * 0.5;
if (cop.mesh.children[3]) cop.mesh.children[3].rotation.x = -Math.sin(cop.animPhase) * 0.5;

// Attack player
if (dist < 3) {
state.health -= 10 * dt;
updateHealthUI();
}

// Shooting at player (wanted level 3+)
if (state.wantedLevel >= 3 && dist < 30 && Math.random() < 0.02) {
state.health -= 5;
updateHealthUI();
// Bullet tracer
const tracer = new THREE.Mesh(
new THREE.SphereGeometry(0.05),
new THREE.MeshBasicMaterial({ color: 0xff4400 })
);
tracer.position.copy(cop.mesh.position);
tracer.position.y += 1.5;
scene.add(tracer);
const bulletDir = new THREE.Vector3().subVectors(state.playerPos, cop.mesh.position).normalize();
tracer.userData = { vel: bulletDir.multiplyScalar(50), life: 1 };
state.bullets.push({ mesh: tracer, velocity: bulletDir.multiplyScalar(50), life: 1, damage: 5, isPlayer: false });
}

// Flee if player has high wanted level (revenge)
if (state.wantedLevel >= 4 && dist < 5) {
const fleeDir = dir.clone().negate();
cop.mesh.position.x += fleeDir.x * chaseSpeed * dt * 2;
cop.mesh.position.z += fleeDir.z * chaseSpeed * dt * 2;
}
});
}

function updateBullets(dt) {
for (let i = state.bullets.length - 1; i >= 0; i--) {
const b = state.bullets[i];
b.life -= dt;

b.mesh.position.add(b.velocity.clone().multiplyScalar(dt));

if (b.isPlayer) {
// Check hit peds
state.peds.forEach(ped => {
if (ped.isDead) return;
const dist = b.mesh.position.distanceTo(ped.mesh.position);
if (dist < 1.5) {
ped.health -= b.damage;
if (ped.health <= 0) {
ped.isDead = true;
ped.mesh.rotation.x = Math.PI / 2;
ped.mesh.position.y = 0.3;
state.money += 100;
document.getElementById('money-display').textContent = '$' + state.money.toLocaleString();
}
state.bullets.splice(i, 1);
return;
}
});

// Check hit police
state.policeChasers.forEach(cop => {
const dist = b.mesh.position.distanceTo(cop.mesh.position);
if (dist < 1.5) {
cop.health -= b.damage;
if (cop.health <= 0) {
// Remove cop
scene.remove(cop.mesh);
const idx = state.policeChasers.indexOf(cop);
if (idx > -1) state.policeChasers.splice(idx, 1);
}
state.bullets.splice(i, 1);
return;
}
});

} else {
// Enemy bullet hitting player
const dist = b.mesh.position.distanceTo(playerGroup.position);
if (dist < 1) {
state.health -= b.damage;
updateHealthUI();
state.bullets.splice(i, 1);
return;
}
}

// Check building collision
if (checkBuildingCollision(b.mesh.position.x, b.mesh.position.z, 0.2)) {
scene.remove(b.mesh);
state.bullets.splice(i, 1);
continue;
}

if (b.life <= 0 || b.mesh.position.y < 0) {
scene.remove(b.mesh);
state.bullets.splice(i, 1);
}
}
}

function updateMissionMarkers(dt) {
state.missionMarkers.forEach((marker, i) => {
marker.group.rotation.y += dt * 2;
marker.group.children[2].rotation.z += dt * 3;
marker.group.children[2].position.y = 2 + Math.sin(Date.now() * 0.003) * 0.5;

// Check if player collected delivery items
state.collectedItems.forEach(item => {
if (item.missionIndex === i) {
const dist = playerGroup.position.distanceTo(item.mesh.position);
if (dist < 3) {
scene.remove(item.mesh);
const idx = state.collectedItems.indexOf(item);
if (idx > -1) state.collectedItems.splice(idx, 1);
completeMission(i);
}
}
});

// Check combat/bounty mission completion
if ((CONFIG.MISSIONS[i].type === 'combat' || CONFIG.MISSIONS[i].type === 'bounty') && !marker.completed) {
const enemies = state.peds.filter(p => p.isEnemy && !p.isDead);
if (enemies.length === 0 && state.peds.some(p => p.isEnemy)) {
completeMission(i);
}
}
});
}

function updateHealthUI() {
state.health = Math.max(0, Math.min(100, state.health));
document.getElementById('health-bar').style.width = state.health + '%';

if (state.health <= 30) {
document.getElementById('health-bar').style.background = 'linear-gradient(90deg, #ff0000, #ff3333)';
} else {
document.getElementById('health-bar').style.background = 'linear-gradient(90deg, #ff3333, #ff6666)';
}

if (state.health <= 0) {
showNotification('WASTED - Press R to restart');
if (state.keys['KeyR']) {
state.health = 100;
state.money = Math.max(0, state.money - 500);
state.wantedLevel = 0;
updateHealthUI();
updateWantedUI();
playerGroup.position.set(0, 2, 50);
document.getElementById('money-display').textContent = '$' + state.money.toLocaleString();
}
}
}

function updateInteractionPrompt() {
const prompt = document.getElementById('interaction-prompt');
let showPrompt = false;

if (!state.inVehicle) {
// Check vehicles
let closestVehicle = null;
let closestDist = 5;
state.vehicles.forEach(v => {
if (v.isPlayer) return;
const dist = playerGroup.position.distanceTo(v.mesh.position);
if (dist < closestDist) {
closestDist = dist;
closestVehicle = v;
}
});
if (closestVehicle) {
prompt.textContent = 'Press E to enter vehicle';
prompt.style.display = 'block';
showPrompt = true;
}

// Check mission markers
state.missionMarkers.forEach(m => {
if (m.completed) return;
const dist = playerGroup.position.distanceTo(m.group.position);
if (dist < 5) {
prompt.textContent = `Press E to start: ${m.mission.name}`;
prompt.style.display = 'block';
showPrompt = true;
}
});
} else {
prompt.textContent = 'Press Q to exit vehicle';
prompt.style.display = 'block';
showPrompt = true;
}

if (!showPrompt) prompt.style.display = 'none';
}

// ==================== SPAWN PICKUPS ====================
function createPickups() {
const pickupTypes = [
{ color: 0x44ff44, name: 'Health', effect: () => { state.health = Math.min(100, state.health + 25); } },
{ color: 0x4488ff, name: 'Armor', effect: () => { state.armor = Math.min(100, state.armor + 25); } },
{ color: 0xffaa00, name: 'Ammo', effect: () => { state.weapons[1].ammo += 30; state.weapons[2].ammo += 10; state.weapons[3].ammo += 10; updateWeaponUI(); } },
{ color: 0xff44ff, name: 'Money', effect: () => { state.money += 1000; document.getElementById('money-display').textContent = '$' + state.money.toLocaleString(); } },
];

for (let i = 0; i < 30; i++) {
const type = pickupTypes[Math.floor(Math.random() * pickupTypes.length)];
const mesh = new THREE.Mesh(
new THREE.OctahedronGeometry(0.5),
new THREE.MeshStandardMaterial({
color: type.color, emissive: type.color, emissiveIntensity: 0.5,
transparent: true, opacity: 0.8
})
);
mesh.position.set(
(Math.random() - 0.5) * CONFIG.WORLD_SIZE * 0.6,
1,
(Math.random() - 0.5) * CONFIG.WORLD_SIZE * 0.6
);
scene.add(mesh);

state.collectedItems.push({
mesh: mesh,
type: type,
isPickup: true
});
}
}

function updatePickups(dt) {
for (let i = state.collectedItems.length - 1; i >= 0; i--) {
const item = state.collectedItems[i];
if (item.isPickup) {
item.mesh.rotation.y += dt * 3;
item.mesh.position.y = 1 + Math.sin(Date.now() * 0.003 + i) * 0.3;

const dist = playerGroup.position.distanceTo(item.mesh.position);
if (dist < 2) {
item.type.effect();
scene.remove(item.mesh);
state.collectedItems.splice(i, 1);
showNotification(`Collected: ${item.type.name}`);
}
}
}
}

// ==================== TRAFFIC COLLISION WITH PLAYER ====================
function updateTrafficPlayerCollision() {
if (state.inVehicle) return;

state.trafficCars.forEach(v => {
const dist = v.mesh.position.distanceTo(playerGroup.position);
if (dist < 3 && Math.abs(v.speed || v.trafficSpeed) > 3) {
state.health -= 15;
updateHealthUI();
increaseWanted(0.5);

// Knockback
const dir = new THREE.Vector3().subVectors(playerGroup.position, v.mesh.position).normalize();
playerGroup.position.x += dir.x * 3;
playerGroup.position.z += dir.z * 3;
state.playerVel.y = 5;
}
});
}

// ==================== MAIN GAME LOOP ====================
let lastTime = 0;

function gameLoop(time) {
requestAnimationFrame(gameLoop);

const dt = Math.min((time - lastTime) / 1000, 0.05);
lastTime = time;

if (state.isPaused) {
renderer.render(scene, camera);
return;
}

state.gameTime += dt;

updatePlayer(dt);
updateCamera();
updateVehicles(dt);
updatePeds(dt);
updatePolice(dt);
updateBullets(dt);
updateMissionMarkers(dt);
updateWeather(dt);
updateDayNight(dt);
updatePickups(dt);
updateTrafficPlayerCollision();
updateInteractionPrompt();

// Minimap update (throttled)
if (Math.floor(time / 100) % 2 === 0) {
updateMinimap();
}

renderer.render(scene, camera);
}

// ==================== INITIALIZATION ====================
function init() {
const loadBar = document.getElementById('loading-bar-inner');
const loadText = document.getElementById('loading-text');

loadText.textContent = 'Generating world...';
loadBar.style.width = '10%';

setTimeout(() => {
createGround();
loadBar.style.width = '30%';
loadText.textContent = 'Building city...';
}, 100);

setTimeout(() => {
generateCity();
loadBar.style.width = '50%';
loadText.textContent = 'Adding details...';
}, 200);

setTimeout(() => {
generateTrees();
loadBar.style.width = '65%';
loadText.textContent = 'Spawning vehicles...';
}, 300);

setTimeout(() => {
spawnVehicles();
loadBar.style.width = '75%';
loadText.textContent = 'Populating streets...';
}, 400);

setTimeout(() => {
spawnPeds();
loadBar.style.width = '85%';
loadText.textContent = 'Setting up police...';
}, 500);

setTimeout(() => {
spawnPolice();
createMissionMarkers();
loadBar.style.width = '95%';
loadText.textContent = 'Almost ready...';
}, 600);

setTimeout(() => {
createPlayer();
createRain();
createPickups();
loadBar.style.width = '100%';
loadText.textContent = 'Welcome to Crime City!';
}, 700);

setTimeout(() => {
document.getElementById('loading-screen').style.display = 'none';
renderer.domElement.requestPointerLock();
updateHealthUI();
updateWeaponUI();
showNotification('Welcome to Crime City! Use WASD to move, E to interact, Q to exit vehicles.');
requestAnimationFrame(gameLoop);
}, 1200);
}

window.addEventListener('resize', () => {
camera.aspect = window.innerWidth / window.innerHeight;
camera.updateProjectionMatrix();
renderer.setSize(window.innerWidth, window.innerHeight);
});

init();
</script>
</body>
