  background: rgba(0,0,0,0.85); display: none; flex-direction: column;
  align-items: center; justify-content: center; z-index: 200;
}
#game-over-screen h1 { color: #c41e1e; font-family: 'Georgia', serif; font-size: 48px; margin-bottom: 10px; }
#game-over-screen p { color: #ccc; font-family: 'Georgia', serif; font-size: 20px; margin-bottom: 30px; }
#restart-btn {
  font-family: 'Georgia', serif; background: linear-gradient(180deg, #8b4513, #5c2d0e);
  color: #f4c542; border: 2px solid #f4c542; padding: 12px 40px;
  font-size: 20px; cursor: pointer; border-radius: 4px; pointer-events: all;
}
#minimap {
  position: absolute; top: 10px; right: 10px; width: 110px; height: 110px;
  border-radius: 50%; border: 2px solid rgba(255,255,255,0.3);
  overflow: hidden; z-index: 15; pointer-events: none;
}
#minimap-canvas { width: 110px; height: 110px; }
#hud {
  position: absolute; top: 10px; left: 10px; z-index: 15; pointer-events: none;
}
