  width: 150px; height: 12px; background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2); border-radius: 6px;
  margin-bottom: 4px; overflow: hidden;
}
#health-bar {
  width: 100%; height: 100%; background: linear-gradient(90deg, #c41e1e, #ff4444);
  border-radius: 6px; transition: width 0.3s;
}
#ammo-display {
  color: #f4c542; font-family: 'Georgia', serif; font-size: 16px;
  text-shadow: 1px 1px 3px #000;
}
#wanted-display {
  color: #f4c542; font-family: 'Georgia', serif; font-size: 20px;
  text-shadow: 1px 1px 3px #000; margin-top: 2px;
}
