  color: var(--neon-blue);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.water-add-btn:hover {
  background: rgba(0, 212, 255, 0.2);
}

/* Meditation */
.meditation-card {
  background: linear-gradient(135deg, rgba(180, 77, 255, 0.1), rgba(0, 212, 255, 0.1));
  border: 1px solid rgba(180, 77, 255, 0.2);
