  gap: 12px;
  justify-content: center;
}

.meditation-btn {
  padding: 10px 24px;
  border-radius: 24px;
  border: none;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.meditation-btn.start {
  background: linear-gradient(135deg, var(--neon-purple), var(--neon-blue));
  color: white;
}

.meditation-btn.reset {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
}

/* ==================== MODAL ==================== */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(10px);
  z-index: 200;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.modal-overlay.active {
  display: flex;
}

.modal-content {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 20px;
  padding: 24px;
  width: 100%;
  max-width: 360px;
  animation: modalIn 0.3s ease-out;
}

@keyframes modalIn {
  from { opacity: 0; transform: scale(0.9) translateY(20px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.modal-title {
  font-family: 'Orbitron', sans-serif;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 16px;
  text-align: center;
}

.modal-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 16px;
}

/* Food detection result */
.food-detection-result {
  background: var(--bg-card);
  border: 1px solid var(--neon-green);
  border-radius: 12px;
  padding: 16px;
  margin-top: 12px;
  display: none;
}

.food-detection-result .detected-food {
  font-size: 16px;
  font-weight: 700;
  color: var(--neon-green);
  margin-bottom: 8px;
}

.food-detection-result .nutrition-info {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  text-align: center;
}

.food-detection-result .nutri-item {
  padding: 8px;
  background: var(--bg-primary);
  border-radius: 8px;
}

.food-detection-result .nutri-value {
  font-family: 'Orbitron', sans-serif;
  font-size: 14px;
  font-weight: 700;
}

.food-detection-result .nutri-label {
  font-size: 10px;
  color: var(--text-secondary);
  text-transform: uppercase;
}

/* Loading spinner */
.spinner {
  width: 24px;
  height: 24px;
  border: 3px solid var(--border-color);
  border-top-color: var(--neon-blue);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin: 20px auto;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Animations */
.fade-in {
  animation: fadeIn 0.5s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Responsive */
@media (min-width: 500px) {
  .app-container {
    max-width: 430px;
    margin: 0 auto;
    border-left: 1px solid var(--border-color);
    border-right: 1px solid var(--border-color);
  }
}

/* Scrollbar for chat */
.chat-messages {
  scrollbar-width: thin;
  scrollbar-color: var(--border-color) transparent;
}

/* Welcome message styling */
.welcome-message {
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.05), rgba(180, 77, 255, 0.05));
  border: 1px solid rgba(0, 212, 255, 0.15);
  border-radius: 16px;
  padding: 20px;
  margin: 0 20px 16px;
  text-align: center;
}

.welcome-message h3 {
  font-family: 'Orbitron', sans-serif;
  font-size: 14px;
