  margin-bottom: 8px;
}

.welcome-message p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* Workout plan cards */
.workout-cards {
  display: grid;
  gap: 12px;
  padding: 0 20px 20px;
}

.workout-card {
  background: var(--bg-card);
