function getRockResponse(message) {
  const msg = message.toLowerCase();

  if (msg.match(/\b(hi|hey|hello|sup|what'?s up|howdy)\b/)) {
    return randomFrom(rockResponses.greetings);
  }
  if (msg.match(/\b(workout|exercise|training|plan|routine|gym)\b/)) {
    if (msg.match(/\b(beginner|start|new|first|newbie)\b/)) {
      return randomFrom(rockResponses.beginners);
    }
    return randomFrom(rockResponses.workout_plan);
  }
  if (msg.match(/\b(food|eat|nutrition|pre.?workout|post.?workout|diet|meal)\b/)) {
    if (msg.match(/\b(pre|before|before workout)\b/)) {
      return randomFrom(rockResponses.pre_workout_food);
    }
    if (msg.match(/\b(protein)\b/)) {
      return randomFrom(rockResponses.protein);
    }
    return randomFrom(rockResponses.pre_workout_food);
  }
  if (msg.match(/\b(motivat|inspir|quote|encourage|push)\b/)) {
    return randomFrom(rockResponses.motivation);
  }
  if (msg.match(/\b(belly|abs|core|midsection|love handle)\b/)) {
    return randomFrom(rockResponses.belly_fat);
  }
  if (msg.match(/\b(recovery|rest|sore|muscle|repair)\b/)) {
    return randomFrom(rockResponses.recovery);
  }
  if (msg.match(/\b(stretch|flexibility|mobility|warm.?up|cool.?down)\b/)) {
    return randomFrom(rockResponses.stretching);
  }
  if (msg.match(/\b(weight|lose|fat|burn|calorie|diet)\b/)) {
    return randomFrom(rockResponses.belly_fat);
  }
  if (msg.match(/\b(water|hydrate|hydration)\b/)) {
    return "💧 Hydration is crucial for performance! Aim for at least 2-3 liters per day. More if you're training hard. Dehydration of just 2% can reduce your strength by up to 20%. Keep a water bottle with you at all times!";
  }
  if (msg.match(/\b(sleep|rest|tired|exhausted)\b/)) {
    return "😴 Sleep is your secret weapon for fitness gains! During deep sleep, your body releases growth hormone which repairs muscle tissue. Aim for 7-9 hours. Tips: cool room (65-68°F), no screens 1 hour before bed, consistent sleep schedule. Quality sleep = quality gains! 💪";
  }
  if (msg.match(/\b(supplement|vitamin|powder|creatine|whey)\b/)) {
    return "🧪 Supplements can help but aren't magic:\n\n**Essential:**\n• Protein powder (convenience)\n• Vitamin D (if deficient)\n• Omega-3 (if low fish intake)\n\n**Optional but effective:**\n• Creatine monohydrate (5g/day) — most researched supplement\n• Caffeine (pre-workout)\n\n**Skip the hype:**\n• Fat burners\n• Testosterone boosters\n• BCAAs (if eating enough protein)\n\nFood first, supplements second! 🥗";
  }
  if (msg.match(/\b(injur|pain|hurt|knee|back|shoulder)\b/)) {
    return "⚠️ Important: I'm an AI, not a doctor. Always consult a healthcare professional for injuries!\n\n**General advice:**\n• RICE method: Rest, Ice, Compression, Elevation\n• Don't train through sharp pain\n• Focus on mobility and warm-ups\n• Strengthen supporting muscles\n• Consider physical therapy if persistent\n\nPrevention is better than cure — proper form and gradual progression are key! 🛡️";
  }

  return randomFrom(rockResponses.default);
}

function randomFrom(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

