  .simulator-title { font-size: 13px; color: var(--text-muted); }

  .simulator-body {
    display: flex;
    gap: 0;
    min-height: 500px;
  }

  .sim-device {
    flex: 1;
    padding: 20px;
    position: relative;
  }

  .sim-device.mobile-device {
    background: linear-gradient(135deg, #0f172a, #1e1b4b);
    border-right: 1px solid var(--border-color);
  }

  .sim-device.tv-device {
    background: linear-gradient(135deg, #0f172a, #064e3b);
  }

  .sim-device-label {
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .sim-device-label .dot {
    width: 8px; height: 8px;
    border-radius: 50%;
    background: var(--accent-green);
  }

  .sim-screen {
    width: 100%;
    height: 300px;
    background: #000;
    border-radius: 12px;
    border: 2px solid #333;
    overflow: hidden;
    position: relative;
  }

  .sim-screen-content {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 20px;
  }

  .sim-app-icon {
    width: 56px; height: 56px;
    border-radius: 14px;
    display: flex; align-items: center; justify-content: center;
    font-size: 28px;
  }

  .sim-app-name { font-size: 13px; color: var(--text-secondary); }

  .sim-stream-overlay {
    position: absolute;
    top: 8px; right: 8px;
    background: rgba(0,0,0,0.7);
    padding: 4px 8px;
    border-radius: 6px;
    font-size: 10px;
    color: var(--accent-green);
    font-family: monospace;
  }

  .sim-controls {
    display: flex;
    gap: 8px;
    margin-top: 16px;
    flex-wrap: wrap;
  }

  .sim-btn {
    padding: 8px 16px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    border: 1px solid var(--border-color);
    background: var(--bg-secondary);
    color: var(--text-primary);
    transition: all 0.2s;
    font-family: inherit;
  }

  .sim-btn:hover { background: var(--accent-blue); border-color: var(--accent-blue); }
  .sim-btn.active { background: var(--accent-green); border-color: var(--accent-green); color: white; }
  .sim-btn.danger { border-color: var(--accent-red); color: var(--accent-red); }
  .sim-btn.danger:hover { background: var(--accent-red); color: white; }

  .connection-line {
    position: absolute;
    top: 50%;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(90deg, var(--accent-blue), var(--accent-cyan));
    z-index: 10;
    opacity: 0;
    transition: opacity 0.5s;
  }

  .connection-line.active { opacity: 1; }

  .connection-line::after {
    content: '';
    position: absolute;
    top: -3px;
    width: 8px; height: 8px;
    background: var(--accent-cyan);
    border-radius: 50%;
    animation: dataFlow 2s infinite linear;
    box-shadow: 0 0 10px var(--accent-cyan);
  }

  @keyframes dataFlow {
    0% { left: 0; }
    100% { left: 100%; }
  }

  .connection-line.reverse::after {
    animation-direction: reverse;
    background: var(--accent-purple);
    box-shadow: 0 0 10px var(--accent-purple);
  }

  .log-panel {
    background: #0d1117;
    border: 1px solid #21262d;
    border-radius: 12px;
    padding: 16px;
    max-height: 200px;
    overflow-y: auto;
    font-family: 'Cascadia Code', 'Fira Code', monospace;
    font-size: 12px;
    line-height: 1.8;
    margin-top: 16px;
  }

  .log-entry { display: flex; gap: 12px; }
  .log-time { color: var(--text-muted); min-width: 80px; }
  .log-level { min-width: 50px; font-weight: 600; }
  .log-level.info { color: var(--accent-blue); }
  .log-level.success { color: var(--accent-green); }
  .log-level.warn { color: var(--accent-yellow); }
  .log-level.error { color: var(--accent-red); }
  .log-msg { color: var(--text-secondary); }

  .tab-content-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }

  .full-width { grid-column: 1 / -1; }

  .setup-steps { counter-reset: step; }
  .setup-step {
    position: relative;
    padding: 20px 20px 20px 60px;
    margin-bottom: 16px;
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    counter-increment: step;
  }

  .setup-step::before {
    content: counter(step);
    position: absolute;
    left: 20px;
    top: 20px;
    width: 28px; height: 28px;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-cyan));
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 700;
    color: white;
  }

  .setup-step h4 { font-size: 15px; margin-bottom: 6px; }
  .setup-step p { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }

  .toggle-switch {
    position: relative;
    width: 48px; height: 26px;
    cursor: pointer;
  }

  .toggle-switch input { display: none; }

  .toggle-slider {
    position: absolute;
    inset: 0;
    background: #374151;
    border-radius: 13px;
    transition: 0.3s;
  }

  .toggle-slider::before {
    content: '';
    position: absolute;
    width: 20px; height: 20px;
    left: 3px; top: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.3s;
  }

  .toggle-switch input:checked + .toggle-slider { background: var(--accent-green); }
  .toggle-switch input:checked + .toggle-slider::before { transform: translateX(22px); }

  .config-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 0;
    border-bottom: 1px solid var(--border-color);
  }

  .config-row:last-child { border-bottom: none; }
  .config-label { font-size: 14px; color: var(--text-secondary); }
  .config-value {
    font-size: 13px;
    color: var(--accent-cyan);
    font-family: monospace;
    background: var(--bg-secondary);
    padding: 4px 10px;
    border-radius: 6px;
  }

  .expandable { cursor: pointer; }
  .expandable-content { max-height: 0; overflow: hidden; transition: max-height 0.5s ease; }
  .expandable.open .expandable-content { max-height: 3000px; }
  .expandable-arrow { transition: transform 0.3s; display: inline-block; }
  .expandable.open .expandable-arrow { transform: rotate(90deg); }

  .tooltip {
    position: relative;
    display: inline-block;
    border-bottom: 1px dotted var(--text-muted);
    cursor: help;
  }

  .tooltip .tooltip-text {
    visibility: hidden;
    background: #1e293b;
    color: var(--text-primary);
    text-align: center;
    padding: 8px 12px;
    border-radius: 8px;
    font-size: 12px;
    position: absolute;
    z-index: 10;
    bottom: 125%;
    left: 50%;
    transform: translateX(-50%);
    white-space: nowrap;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5);
    border: 1px solid var(--border-color);
  }

  .tooltip:hover .tooltip-text { visibility: visible; }

  .progress-ring {
    width: 120px; height: 120px;
    margin: 0 auto;
  }

  .progress-ring circle {
    fill: none;
    stroke-width: 8;
    stroke-linecap: round;
  }

  .progress-ring .bg { stroke: #1e293b; }
  .progress-ring .fill {
    stroke: url(#gradient);
    stroke-dasharray: 339.292;
    stroke-dashoffset: 339.292;
    transition: stroke-dashoffset 1s ease;
  }

  .progress-ring .text {
    font-size: 24px;
    font-weight: 700;
    fill: var(--text-primary);
    text-anchor: middle;
    dominant-baseline: central;
  }

  .progress-ring .label {
    font-size: 11px;
    fill: var(--text-muted);
    text-anchor: middle;
  }

  @media (max-width: 1024px) {
    .grid-2, .tab-content-grid { grid-template-columns: 1fr; }
    .grid-3 { grid-template-columns: 1fr 1fr; }
    .grid-4 { grid-template-columns: 1fr 1fr; }
    .simulator-body { flex-direction: column; }
    .main-content { padding: 20px; }
    .header { padding: 16px 20px; }
    .nav-tabs { padding: 0 20px; }
  }

  @media (max-width: 640px) {
    .grid-3, .grid-4 { grid-template-columns: 1fr; }
    .arch-flow { flex-direction: column; }
    .arch-arrow { transform: rotate(90deg); }
    .header-status { display: none; }
  }

  .highlight-line {
    background: rgba(59, 130, 246, 0.1);
    display: block;
    margin: 0 -16px;
    padding: 0 16px;
    border-left: 3px solid var(--accent-blue);
  }

  .inline-code {
    background: var(--bg-secondary);
    padding: 2px 6px;
    border-radius: 4px;
    font-family: 'Cascadia Code', 'Fira Code', monospace;
    font-size: 12px;
    color: var(--accent-cyan);
    border: 1px solid var(--border-color);
  }

  .network-visual {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 16px;
    background: var(--bg-secondary);
    border-radius: 12px;
    margin: 16px 0;
  }

  .network-packet {
    width: 12px; height: 12px;
    border-radius: 3px;
    animation: packetBounce 1.5s infinite;
  }

  .network-packet:nth-child(1) { background: var(--accent-blue); animation-delay: 0s; }
  .network-packet:nth-child(2) { background: var(--accent-cyan); animation-delay: 0.1s; }
  .network-packet:nth-child(3) { background: var(--accent-green); animation-delay: 0.2s; }
  .network-packet:nth-child(4) { background: var(--accent-purple); animation-delay: 0.3s; }
  .network-packet:nth-child(5) { background: var(--accent-yellow); animation-delay: 0.4s; }

  @keyframes packetBounce {
    0%, 100% { transform: translateY(0); opacity: 0.5; }
    50% { transform: translateY(-12px); opacity: 1; }
  }

  .device-frame {
    border: 3px solid #333;
    border-radius: 20px;
    padding: 12px;
    background: #1a1a1a;
    max-width: 280px;
    margin: 0 auto;
  }

  .device-frame.tv-frame {
    max-width: 400px;
    border-radius: 8px;
    border-width: 4px;
  }

  .device-frame-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 4px 0;
    margin-bottom: 8px;
  }

  .device-frame-title { font-size: 11px; color: var(--text-muted); }
  .device-frame-indicator { width: 6px; height: 6px; border-radius: 50%; background: var(--accent-green); }

  .scrollable-code {
    max-height: 500px;
    overflow-y: auto;
  }
</style>
</head>
<body>

<header class="header">
  <div class="header-left">
    <div class="logo">📱</div>
    <div>
      <h1>ScreenMirror Pro</h1>
      <div class="header-subtitle">Dual-App Remote Desktop System • Mobile → Android TV</div>
    </div>
  </div>
  <div class="header-status">
    <div class="status-badge">
      <span class="status-dot" id="globalStatusDot"></span>
      <span id="globalStatusText">System Ready</span>
    </div>
    <div class="status-badge">
      🖥️ Mobile: <span id="mobileCpuDisplay">0%</span>
    </div>
    <div class="status-badge">
      📺 TV: <span id="tvCpuDisplay">0%</span>
    </div>
  </div>
</header>

<nav class="nav-tabs">
  <button class="nav-tab active" onclick="switchTab('architecture')">🏗️ Architecture</button>
  <button class="nav-tab" onclick="switchTab('mobile-app')">📱 Mobile App Code</button>
  <button class="nav-tab" onclick="switchTab('tv-app')">📺 TV App Code</button>
  <button class="nav-tab" onclick="switchTab('layouts')">🎨 Layout XMLs</button>
  <button class="nav-tab" onclick="switchTab('communication')">🔌 Communication Protocol</button>
  <button class="nav-tab" onclick="switchTab('simulator')">🎮 Live Simulator</button>
  <button class="nav-tab" onclick="switchTab('setup')">📋 Setup Guide</button>
</nav>

<main class="main-content">

  <!-- ==================== ARCHITECTURE TAB ==================== -->
  <div class="tab-content active" id="tab-architecture">
    <h2 class="section-title">
      <span class="icon" style="background:rgba(59,130,246,0.15);color:var(--accent-blue);">🏗️</span>
      System Architecture
    </h2>

    <div class="arch-diagram">
      <h3 style="text-align:center;margin-bottom:20px;color:var(--text-secondary);font-size:14px;text-transform:uppercase;letter-spacing:2px;">Data Flow Diagram</h3>
      <div class="arch-flow">
        <div class="arch-node mobile">
          <div class="arch-node-icon">📱</div>
          <div class="arch-node-title">Mobile Device</div>
          <div class="arch-node-desc">90-95% Processing<br>H.264/H.265 Encoder<br>MediaProjection API</div>
        </div>
        <div class="arch-arrow">→</div>
        <div class="arch-node network">
          <div class="arch-node-icon">🌐</div>
          <div class="arch-node-title">Local Network</div>
          <div class="arch-node-desc">TCP/UDP Socket<br>Hotspot ↔ Wi-Fi<br>~1-5ms Latency</div>
        </div>
        <div class="arch-arrow">→</div>
        <div class="arch-node tv">
          <div class="arch-node-icon">📺</div>
          <div class="arch-node-title">Android TV</div>
          <div class="arch-node-desc">4-5% Processing<br>H.264/H.265 Decoder<br>Thin Client</div>
        </div>
      </div>
      <div style="text-align:center;margin-top:20px;">
        <div class="arch-arrow reverse" style="display:inline-block;">←</div>
        <div class="arch-arrow reverse" style="display:inline-block;">←</div>
        <div class="arch-arrow reverse" style="display:inline-block;">←</div>
        <div style="margin-top:8px;">
          <span class="arch-node input" style="display:inline-block;padding:12px 20px;border-radius:12px;">
            🎮 TV Input → Mobile Execution
          </span>
        </div>
      </div>
    </div>

    <div class="grid-4">
      <div class="metric-card">
        <div class="metric-label">Mobile CPU</div>
        <div class="metric-value" style="color:var(--accent-blue);" id="metricMobileCpu">92%</div>
        <div class="metric-bar"><div class="metric-bar-fill cpu-bar" style="width:92%"></div></div>
      </div>
      <div class="metric-card">
        <div class="metric-label">TV CPU</div>
        <div class="metric-value" style="color:var(--accent-cyan);" id="metricTvCpu">4%</div>
        <div class="metric-bar"><div class="metric-bar-fill cpu-bar" style="width:4%;background:linear-gradient(90deg,var(--accent-green),var(--accent-cyan));"></div></div>
      </div>
      <div class="metric-card">
        <div class="metric-label">Latency</div>
        <div class="metric-value" style="color:var(--accent-green);" id="metricLatency">3ms</div>
        <div class="metric-bar"><div class="metric-bar-fill latency-bar" style="width:15%"></div></div>
      </div>
      <div class="metric-card">
        <div class="metric-label">Frame Rate</div>
        <div class="metric-value" style="color:var(--accent-purple);" id="metricFps">60 FPS</div>
        <div class="metric-bar"><div class="metric-bar-fill fps-bar" style="width:100%"></div></div>
      </div>
    </div>

    <div class="grid-2">
      <div class="card">
        <div class="card-header">
          <span class="card-title">📱 Mobile App Components</span>
          <span class="card-badge badge-blue">Server</span>
        </div>
        <ul class="feature-list">
          <li><span class="check">✓</span> MediaProjection API (Screen Capture)</li>
          <li><span class="check">✓</span> MediaCodec H.264/H.265 Hardware Encoder</li>
          <li><span class="check">✓</span> TCP/UDP Socket Server (Port 8080)</li>
          <li><span class="check">✓</span> Accessibility Service (Input Execution)</li>
          <li><span class="check">✓</span> DisplayManager (Screen Off while streaming)</li>
          <li><span class="check">✓</span> WakeLock (Keep CPU active)</li>
          <li><span class="check">✓</span> NetworkManager (Hotspot detection)</li>
          <li><span class="check">✓</span> Real-time CPU/GPU Monitoring</li>
        </ul>
      </div>
      <div class="card">
        <div class="card-header">
          <span class="card-title">📺 Android TV App Components</span>
          <span class="card-badge badge-cyan">Thin Client</span>
        </div>
        <ul class="feature-list">
          <li><span class="check">✓</span> TCP/UDP Socket Client</li>
          <li><span class="check">✓</span> MediaCodec Hardware Decoder</li>
          <li><span class="check">✓</span> SurfaceView / OpenGL ES Renderer</li>
          <li><span class="check">✓</span> Input Event Capture (Remote/Mouse/KB)</li>
          <li><span class="check">✓</span> Input Event Relay to Mobile</li>
          <li><span class="check">✓</span> Low-latency Frame Buffer</li>
          <li><span class="check">✓</span> Auto-reconnect Logic</li>
          <li><span class="check">✓</span> TV-specific UI (Leanback)</li>
        </ul>
      </div>
    </div>

    <div class="card">
      <div class="card-header">
        <span class="card-title">⚙️ Optimization Strategy</span>
        <span class="card-badge badge-green">Performance</span>
      </div>
      <div class="grid-3" style="margin-top:16px;">
        <div>
          <h4 style="color:var(--accent-cyan);margin-bottom:8px;font-size:14px;">Encoding (Mobile)</h4>
          <p style="font-size:13px;color:var(--text-secondary);line-height:1.6;">
            <span class="inline-code">MediaCodec</span> with 
            <span class="inline-code">OMX.qcom.video.encoder.avc</span> (Qualcomm) or 
            <span class="inline-code">c2.android.avc.encoder</span> fallback. 
            Bitrate: 8-20 Mbps. Keyframe interval: 60 frames. 
            Profile: High. Level: 4.2.
          </p>
        </div>
        <div>
          <h4 style="color:var(--accent-cyan);margin-bottom:8px;font-size:14px;">Decoding (TV)</h4>
          <p style="font-size:13px;color:var(--text-secondary);line-height:1.6;">
            <span class="inline-code">MediaCodec</span> hardware decoder with 
            <span class="inline-code">Surface</span> output for direct GPU compositing. 
            Zero-copy pipeline. Decoder buffer pool: 4 frames.
          </p>
        </div>
        <div>
          <h4 style="color:var(--accent-cyan);margin-bottom:8px;font-size:14px;">Network</h4>
          <p style="font-size:13px;color:var(--text-secondary);line-height:1.6;">
            TCP for reliable control channel. UDP for video stream (optional). 
            Nagle's algorithm disabled. Keep-alive: 10s. 
            Buffer size: 64KB. QoS: Real-time.
          </p>
        </div>
      </div>
    </div>
