  <!-- ==================== MOBILE APP TAB ==================== -->
  <div class="tab-content" id="tab-mobile-app">
    <h2 class="section-title">
      <span class="icon" style="background:rgba(59,130,246,0.15);color:var(--accent-blue);">📱</span>
