    <div class="setup-steps">
      <div class="setup-step">
        <h4>Project Setup & Dependencies</h4>
        <p>Gradle dependencies for MediaCodec, Network, and UI components.</p>
        <div class="code-block">
          <div class="code-header">
            <span class="code-filename">app/build.gradle.kts</span>
            <button class="code-copy" onclick="copyCode(this)">📋 Copy</button>
          </div>
          <div class="code-body"><span class="comment">// build.gradle.kts - Mobile App Dependencies</span>
<span class="keyword">plugins</span> {
    <span class="function">id</span>(<span class="string">"com.android.application"</span>)
    <span class="function">id</span>(<span class="string">"org.jetbrains.kotlin.android"</span>)
}

<span class="keyword">android</span> {
    namespace = <span class="string">"com.screenmirror.mobile"</span>
    compileSdk = <span class="number">34</span>

    defaultConfig {
        applicationId = <span class="string">"com.screenmirror.mobile"</span>
        minSdk = <span class="number">26</span>  <span class="comment">// Android 8.0+ for MediaProjection</span>
        targetSdk = <span class="number">34</span>
        versionCode = <span class="number">1</span>
        versionName = <span class="string">"1.0.0"</span>
    }

    buildFeatures {
        viewBinding = <span class="keyword">true</span>
    }
}

<span class="keyword">dependencies</span> {
    implementation(<span class="string">"androidx.core:core-ktx:1.12.0"</span>)
    implementation(<span class="string">"androidx.appcompat:appcompat:1.6.1"</span>)
    implementation(<span class="string">"com.google.android.material:material:1.11.0"</span>)
    implementation(<span class="string">"androidx.constraintlayout:constraintlayout:2.1.4"</span>)

    <span class="comment">// Coroutines for async operations</span>
    implementation(<span class="string">"org.jetbrains.kotlinx:kotlinx-coroutines-android:1.7.3"</span>)

    <span class="comment">// Networking</span>
    implementation(<span class="string">"com.squareup.okhttp3:okhttp:4.12.0"</span>)

    <span class="comment">// JSON serialization</span>
    implementation(<span class="string">"com.google.code.gson:gson:2.10.1"</span>)

    <span class="comment">// Lifecycle components</span>
    implementation(<span class="string">"androidx.lifecycle:lifecycle-viewmodel-ktx:2.7.0"</span>)
    implementation(<span class="string">"androidx.lifecycle:lifecycle-runtime-ktx:2.7.0"</span>)
}</div>
        </div>
      </div>

      <div class="setup-step">
        <h4>AndroidManifest.xml - Permissions & Services</h4>
        <p>All required permissions for screen capture, network, and accessibility.</p>
        <div class="code-block">
          <div class="code-header">
            <span class="code-filename">AndroidManifest.xml</span>
            <button class="code-copy" onclick="copyCode(this)">📋 Copy</button>
          </div>
          <div class="code-body"><span class="tag">&lt;manifest</span> <span class="attr">xmlns:android</span>=<span class="string">"http://schemas.android.com/apk/res/android"</span>
    <span class="attr">package</span>=<span class="string">"com.screenmirror.mobile"</span><span class="tag">&gt;</span>

    <span class="comment">&lt;!-- Network Permissions --&gt;</span>
