        <h4>Main Activity - Connection UI</h4>
        <p>The primary activity with Connect button, status indicators, and CPU monitoring.</p>
        <div class="code-block">
          <div class="code-header">
            <span class="code-filename">MainActivity.kt</span>
            <button class="code-copy" onclick="copyCode(this)">📋 Copy</button>
          </div>
          <div class="code-body scrollable-code"><span class="keyword">package</span> com.screenmirror.mobile

<span class="keyword">import</span> android.Manifest
<span class="keyword">import</span> android.content.Intent
<span class="keyword">import</span> android.content.pm.PackageManager
<span class="keyword">import</span> android.os.Build
<span class="keyword">import</span> android.os.Bundle
<span class="keyword">import</span> android.util.Log
<span class="keyword">import</span> android.widget.Toast
<span class="keyword">import</span> androidx.activity.result.contract.ActivityResultContracts
<span class="keyword">import</span> androidx.appcompat.app.AppCompatActivity
<span class="keyword">import</span> androidx.core.content.ContextCompat
<span class="keyword">import</span> androidx.lifecycle.lifecycleScope
<span class="keyword">import</span> com.screenmirror.mobile.databinding.ActivityMainBinding
<span class="keyword">import</span> kotlinx.coroutines.Dispatchers
<span class="keyword">import</span> kotlinx.coroutines.delay
<span class="keyword">import</span> kotlinx.coroutines.launch
<span class="keyword">import</span> kotlinx.coroutines.withContext

<span class="keyword">class</span> <span class="type">MainActivity</span> : <span class="type">AppCompatActivity</span>() {

    <span class="keyword">private</span> <span class="keyword">lateinit var</span> binding: <span class="type">ActivityMainBinding</span>
    <span class="keyword">private</span> <span class="keyword">var</span> isStreaming = <span class="keyword">false</span>
    <span class="keyword">private</span> <span class="keyword">var</span> tvIpAddress = <span class="string">""</span>
    <span class="keyword">private</span> <span class="keyword">val</span> TAG = <span class="string">"ScreenMirror"</span>

    <span class="comment">// MediaProjection permission request</span>
    <span class="keyword">private</span> <span class="keyword">val</span> projectionLauncher = <span class="function">registerForActivityResult</span>(
        <span class="type">ActivityResultContracts.StartActivityForResult</span>()
    ) { result ->
        <span class="keyword">if</span> (result.resultCode == RESULT_OK) {
            <span class="function">startScreenStream</span>(result.data!!)
        } <span class="keyword">else</span> {
            <span class="function">showToast</span>(<span class="string">"Screen capture permission denied"</span>)
        }
    }

    <span class="comment">// Accessibility service intent</span>
    <span class="keyword">private</span> <span class="keyword">val</span> accessibilityLauncher = <span class="function">registerForActivityResult</span>(
        <span class="type">ActivityResultContracts.StartActivityForResult</span>()
    ) {
        <span class="function">checkAccessibilityStatus</span>()
    }

    <span class="keyword">override fun</span> <span class="function">onCreate</span>(savedInstanceState: <span class="type">Bundle</span>?) {
        <span class="keyword">super</span>.<span class="function">onCreate</span>(savedInstanceState)
        binding = <span class="type">ActivityMainBinding</span>.<span class="function">inflate</span>(layoutInflater)
        <span class="function">setContentView</span>(binding.root)

        <span class="function">setupUI</span>()
        <span class="function">checkPermissions</span>()
        <span class="function">startCpuMonitoring</span>()
    }

    <span class="keyword">private fun</span> <span class="function">setupUI</span>() {
        <span class="comment">// Connect Button Handler</span>
        binding.btnConnect.<span class="function">setOnClickListener</span> {
            <span class="keyword">if</span> (isStreaming) {
                <span class="function">stopStreaming</span>()
            } <span class="keyword">else</span> {
                <span class="function">initiateConnection</span>()
            }
        }

        <span class="comment">// Screen Off Toggle</span>
        binding.toggleScreenOff.<span class="function">setOnCheckedChangeListener</span> { _, isChecked ->
            <span class="keyword">if</span> (isChecked) {
                <span class="function">enableScreenOffStreaming</span>()
            } <span class="keyword">else</span> {
                <span class="function">disableScreenOffStreaming</span>()
            }
        }

        <span class="comment">// Quality Selector</span>
        binding.spinnerQuality.<span class="function">onItemSelectedListener</span> = <span class="keyword">object</span> : <span class="type">AdapterView.OnItemSelectedListener</span> {
            <span class="keyword">override fun</span> <span class="function">onItemSelected</span>(parent: <span class="type">AdapterView</span>&lt;*&gt;, view: <span class="type">View</span>?, position: <span class="type">Int</span>, id: <span class="type">Long</span>) {
                <span class="keyword">val</span> quality = <span class="keyword">when</span> (position) {
                    <span class="number">0</span> -> <span class="type">StreamQuality</span>.LOW      <span class="comment">// 720p, 5Mbps</span>
                    <span class="number">1</span> -> <span class="type">StreamQuality</span>.MEDIUM   <span class="comment">// 1080p, 10Mbps</span>
                    <span class="number">2</span> -> <span class="type">StreamQuality</span>.HIGH      <span class="comment">// 1080p, 20Mbps</span>
                    <span class="number">3</span> -> <span class="type">StreamQuality</span>.ULTRA     <span class="comment">// 4K, 40Mbps</span>
                    <span class="keyword">else</span> -> <span class="type">StreamQuality</span>.MEDIUM
                }
                <span class="type">StreamConfig</span>.current = quality
            }
            <span class="keyword">override fun</span> <span class="function">onNothingSelected</span>(parent: <span class="type">AdapterView</span>&lt;*&gt;) {}
        }
    }

    <span class="keyword">private fun</span> <span class="function">checkPermissions</span>() {
        <span class="keyword">val</span> permissions = <span class="keyword">if</span> (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            <span class="keyword">listOf</span>(
                Manifest.permission.FOREGROUND_SERVICE_MEDIA_PROJECTION,
                Manifest.permission.POST_NOTIFICATIONS
            )
        } <span class="keyword">else</span> {
            <span class="keyword">listOf</span>(Manifest.permission.FOREGROUND_SERVICE)
        }

        permissions.<span class="function">forEach</span> { perm ->
            <span class="keyword">if</span> (<span class="type">ContextCompat</span>.<span class="function">checkSelfPermission</span>(<span class="this</span>, perm) != PackageManager.PERMISSION_GRANTED) {
                <span class="function">requestPermissions</span>(<span class="keyword">arrayOf</span>(perm), <span class="number">1001</span>)
            }
        }
    }

    <span class="keyword">private fun</span> <span class="function">initiateConnection</span>() {
        <span class="comment">// Step 1: Get TV IP address</span>
        tvIpAddress = binding.etIpAddress.<span class="function">text</span>.<span class="function">toString</span>().<span class="function">trim</span>()
        <span class="keyword">if</span> (tvIpAddress.<span class="function">isEmpty</span>()) {
            <span class="function">showToast</span>(<span class="string">"Please enter TV IP address"</span>)
            <span class="keyword">return</span>
        }

        <span class="comment">// Step 2: Check network connectivity</span>
        <span class="keyword">val</span> networkManager = <span class="type">NetworkManager</span>.<span class="function">getInstance</span>(<span class="this</span>)
        <span class="keyword">if</span> (!networkManager.<span class="function">isConnectedToHotspot</span>()) {
            <span class="function">showToast</span>(<span class="string">"Please ensure TV is connected to your mobile hotspot"</span>)
            <span class="keyword">return</span>
        }

        <span class="comment">// Step 3: Request MediaProjection permission</span>
        <span class="keyword">val</span> intent = <span class="type">MediaProjectionManager</span>.<span class="function">from</span>(<span class="this</span>)
            .<span class="function">createScreenCaptureIntent</span>()
        projectionLauncher.<span class="function">launch</span>(intent)
    }

    <span class="keyword">private fun</span> <span class="function">startScreenStream</span>(data: <span class="type">Intent</span>) {
        <span class="comment">// Start foreground service with MediaProjection</span>
        <span class="keyword">val</span> serviceIntent = <span class="type">Intent</span>(<span class="this</span>, <span class="type">ScreenStreamService</span>::<span class="keyword">class</span>)
        serviceIntent.<span class="function">putExtra</span>(<span class="string">"media_projection_data"</span>, data)
        serviceIntent.<span class="function">putExtra</span>(<span class="string">"tv_ip"</span>, tvIpAddress)

        <span class="keyword">if</span> (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            <span class="type">ContextCompat</span>.<span class="function">startForegroundService</span>(<span class="this</span>, serviceIntent)
        } <span class="keyword">else</span> {
            <span class="type">ContextCompat</span>.<span class="function">startService</span>(<span class="this</span>, serviceIntent)
        }

        <span class="function">enableAccessibilityService</span>()
        <span class="function">updateUI</span>(streaming = <span class="keyword">true</span>)
        <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"Screen streaming started to $tvIpAddress"</span>)
    }

    <span class="keyword">private fun</span> <span class="function">enableAccessibilityService</span>() {
        <span class="keyword">val</span> intent = <span class="type">Intent</span>(<span class="type">Settings</span>.<span class="type">ACTION_ACCESSIBILITY_SETTINGS</span>)
        accessibilityLauncher.<span class="function">launch</span>(intent)
    }

    <span class="keyword">private fun</span> <span class="function">checkAccessibilityStatus</span>() {
        <span class="keyword">val</span> enabled = <span class="type">Settings</span>.<span class="type">Secure</span>.<span class="function">getString</span>(
            contentResolver,
            <span class="type">Settings</span>.<span class="type">Secure</span>.ENABLED_ACCESSIBILITY_SERVICES
        )?.<span class="function">contains</span>(<span class="string">"com.screenmirror.mobile/InputExecutionService"</span>) == <span class="keyword">true</span>

        <span class="keyword">if</span> (!enabled) {
            <span class="function">showToast</span>(<span class="string">"Please enable Accessibility Service for reverse control"</span>)
        }
    }

    <span class="keyword">private fun</span> <span class="function">stopStreaming</span>() {
        <span class="keyword">val</span> intent = <span class="type">Intent</span>(<span class="this</span>, <span class="type">ScreenStreamService</span>::<span class="keyword">class</span>)
        <span class="function">stopService</span>(intent)
        <span class="function">updateUI</span>(streaming = <span class="keyword">false</span>)
        <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"Streaming stopped"</span>)
    }

    <span class="keyword">private fun</span> <span class="function">enableScreenOffStreaming</span>() {
        <span class="comment">// Acquire partial wake lock to keep CPU running</span>
        <span class="keyword">val</span> pm = <span class="function">getSystemService</span>(<span class="type">POWER_SERVICE</span>) <span class="keyword">as</span> <span class="type">PowerManager</span>
        <span class="type">ScreenStreamService</span>.wakeLock = pm.<span class="function">newWakeLock</span>(
            PowerManager.PARTIAL_WAKE_LOCK,
            <span class="string">"ScreenMirror::WakeLock"</span>
        )
        <span class="type">ScreenStreamService</span>.wakeLock?.<span class="function">acquire</span>()

        <span class="comment">// Turn off display while keeping processor active</span>
        <span class="type">ScreenStreamService</span>.screenOff = <span class="keyword">true</span>
        <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"Screen-off streaming enabled - battery saving mode"</span>)
    }

    <span class="keyword">private fun</span> <span class="function">disableScreenOffStreaming</span>() {
        <span class="type">ScreenStreamService</span>.screenOff = <span class="keyword">false</span>
        <span class="type">ScreenStreamService</span>.wakeLock?.<span class="function">release</span>()
    }

    <span class="keyword">private fun</span> <span class="function">startCpuMonitoring</span>() {
        lifecycleScope.<span class="function">launch</span> {
            <span class="keyword">while</span> (<span class="keyword">true</span>) {
                <span class="keyword">val</span> cpuUsage = <span class="type">CpuMonitor</span>.<span class="function">getCpuUsage</span>()
                <span class="function">withContext</span>(Dispatchers.Main) {
                    binding.tvCpuUsage.<span class="function">text</span> = <span class="string">"CPU: </span><span class="function">${cpuUsage.toInt()}%</span><span class="string">"</span>
                    binding.progressCpu.<span class="function">setProgress</span>(cpuUsage.<span class="function">toInt</span>(), <span class="keyword">true</span>)
                }
                <span class="function">delay</span>(<span class="number">1000</span>)
            }
        }
    }

    <span class="keyword">private fun</span> <span class="function">updateUI</span>(streaming: <span class="type">Boolean</span>) {
        isStreaming = streaming
        binding.btnConnect.<span class="function">text</span> = <span class="keyword">if</span> (streaming) <span class="string">"⏹ Stop"</span> <span class="keyword">else</span> <span class="string">"▶ Connect"</span>
        binding.statusIndicator.<span class="function">setBackgroundColor</span>(
            <span class="keyword">if</span> (streaming) <span class="type">ContextCompat</span>.<span class="function">getColor</span>(<span class="this</span>, R.color.green)
            <span class="keyword">else</span> <span class="type">ContextCompat</span>.<span class="function">getColor</span>(<span class="this</span>, R.color.red)
        )
        binding.tvStatus.<span class="function">text</span> = <span class="keyword">if</span> (streaming) <span class="string">"● Streaming to TV"</span> <span class="keyword">else</span> <span class="string">"○ Disconnected"</span>
    }

    <span class="keyword">private fun</span> <span class="function">showToast</span>(message: <span class="type">String</span>) {
        <span class="type">Toast</span>.<span class="function">makeText</span>(<span class="this</span>, message, <span class="type">Toast</span>.LENGTH_SHORT).<span class="function">show</span>()
    }
}

<span class="comment">// Stream Quality Configuration</span>
<span class="keyword">enum class</span> <span class="type">StreamQuality</span>(
