        <span class="function">startForeground</span>(<span class="number">1</span>, <span class="function">createNotification</span>())
    }

    <span class="keyword">override fun</span> <span class="function">onBind</span>(intent: <span class="type">Intent</span>): <span class="type">IBinder</span> = binder

    <span class="keyword">override fun</span> <span class="function">onStartCommand</span>(intent: <span class="type">Intent</span>?, flags: <span class="type">Int</span>, startId: <span class="type">Int</span>): <span class="type">Int</span> {
        <span class="keyword">val</span> projectionData = intent?.<span class="function">getParcelableExtra</span>&lt;<span class="type">Intent</span>&gt;(<span class="string">"media_projection_data"</span>)
        tvIpAddress = intent?.<span class="function">getStringExtra</span>(<span class="string">"tv_ip"</span>) ?: <span class="string">""</span>

        <span class="keyword">if</span> (projectionData != <span class="keyword">null</span>) {
            <span class="keyword">val</span> manager = <span class="function">getSystemService</span>(<span class="type">MEDIA_PROJECTION_SERVICE</span>) <span class="keyword">as</span> <span class="type">MediaProjectionManager</span>
            mediaProjection = manager.<span class="function">getMediaProjection</span>(<span class="type">Activity</span>.RESULT_OK, projectionData)

            <span class="comment">// Start the streaming pipeline</span>
            <span class="function">startStreamingPipeline</span>()
        }

        <span class="keyword">return</span> START_STICKY
    }

    <span class="keyword">private fun</span> <span class="function">startStreamingPipeline</span>() {
        streamingJob = lifecycleScope.<span class="function">launch</span>(Dispatchers.IO) {
            <span class="keyword">try</span> {
                <span class="comment">// Phase 1: Initialize Hardware Encoder</span>
                <span class="function">initEncoder</span>()

                <span class="comment">// Phase 2: Start TCP Server for Control Channel</span>
                <span class="function">startTcpServer</span>()

                <span class="comment">// Phase 3: Start UDP Socket for Video Stream (optional)</span>
                <span class="keyword">if</span> (StreamConfig.current == <span class="type">StreamQuality</span>.ULTRA) {
                    <span class="function">startUdpStream</span>()
                }

                <span class="comment">// Phase 4: Start Encoding Loop</span>
                <span class="function">startEncodingLoop</span>()

                <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"Streaming pipeline started"</span>)

            } <span class="keyword">catch</span> (e: <span class="type">Exception</span>) {
                <span class="type">Log</span>.<span class="function">e</span>(TAG, <span class="string">"Streaming error: </span><span class="function">${e.message}</span><span class="string">"</span>, e)
                <span class="function">stopSelf</span>()
            }
        }
    }

    <span class="comment">// ============================================</span>
    <span class="comment">// PHASE 1: HARDWARE ENCODER INITIALIZATION</span>
    <span class="comment">// ============================================</span>

    <span class="keyword">private fun</span> <span class="function">initEncoder</span>() {
        <span class="keyword">val</span> quality = StreamConfig.current
        <span class="keyword">val</span> (width, height) = quality.resolution

        <span class="comment">// Create MediaFormat for H.264/H.265 encoding</span>
        <span class="keyword">val</span> format = <span class="type">MediaFormat</span>.<span class="function">createVideoFormat</span>(quality.codec, width, height).<span class="function">apply</span> {
            <span class="function">setInteger</span>(<span class="type">MediaFormat</span>.KEY_COLOR_FORMAT,
                <span class="type">MediaCodecInfo.CodecCapabilities</span>.COLOR_FormatSurface)
            <span class="function">setInteger</span>(<span class="type">MediaFormat</span>.KEY_BIT_RATE, quality.bitrate)
            <span class="function">setInteger</span>(<span class="type">MediaFormat</span>.KEY_FRAME_RATE, quality.fps)
            <span class="function">setInteger</span>(<span class="type">MediaFormat</span>.KEY_I_FRAME_INTERVAL, <span class="number">2</span>)  <span class="comment">// 2 seconds keyframes</span>
            <span class="function">setInteger</span>(<span class="type">MediaFormat</span>.KEY_CAPTURE_RATE, quality.fps)
            <span class="function">setInteger</span>(<span class="type">MediaFormat</span>.KEY_REPEAT_PREVIOUS_FRAME_BEFORE_DECODE, <span class="number">0</span>)

            <span class="comment">// H.264 Profile and Level settings</span>
            <span class="keyword">if</span> (quality.codec == <span class="string">"video/avc"</span>) {
                <span class="function">setInteger</span>(<span class="string">"profile"</span>,
                    <span class="type">MediaCodecInfo.CodecProfileLevel</span>.AVCProfileHigh)
                <span class="function">setInteger</span>(<span class="string">"level"</span>,
                    <span class="type">MediaCodecInfo.CodecProfileLevel</span>.AVCLevel42)
            }
        }

        <span class="comment">// Create hardware encoder</span>
        encoder = <span class="type">MediaCodec</span>.<span class="function">createEncoderByType</span>(quality.codec).<span class="function">apply</span> {
            <span class="function">configure</span>(format, <span class="keyword">null</span>, <span class="keyword">null</span>, <span class="type">MediaCodec</span>.CONFIGURE_FLAG_ENCODE)

            <span class="comment">// Get input surface for MediaProjection</span>
            inputSurface = <span class="function">createInputSurface</span>()
            <span class="function">start</span>()
        }

        <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"Encoder initialized: </span><span class="function">${quality.codec}</span><span class="string"> @ </span><span class="function">${width}x${height}</span><span class="string">"</span>)
    }

    <span class="comment">// ============================================</span>
    <span class="comment">// PHASE 2: TCP SERVER (Control + Video)</span>
    <span class="comment">// ============================================</span>

    <span class="keyword">private fun</span> <span class="function">startTcpServer</span>() {
        lifecycleScope.<span class="function">launch</span>(Dispatchers.IO) {
            <span class="keyword">try</span> {
                serverSocket = <span class="type">ServerSocket</span>(StreamConfig.serverPort).<span class="function">apply</span> {
                    <span class="function">soTimeout</span> = <span class="number">0</span>  <span class="comment">// Non-blocking</span>
                }

                <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"TCP Server listening on port </span><span class="function">${StreamConfig.serverPort}</span><span class="string">"</span>)

                <span class="comment">// Accept TV client connection</span>
                clientSocket = serverSocket?.<span class="function">accept</span>()
                clientSocket?.<span class="function">apply</span> {
                    <span class="function">setTcpNoDelay</span>(<span class="keyword">true</span>)     <span class="comment">// Disable Nagle's algorithm</span>
                    <span class="function">setKeepAlive</span>(<span class="keyword">true</span>)      <span class="comment">// Keep-alive enabled</span>
                    <span class="function">soTimeout</span> = <span class="number">5000</span>       <span class="comment">// 5s timeout</span>
                }

                <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"TV client connected: </span><span class="function">${clientSocket?.remoteSocketAddress}</span><span class="string">"</span>)

                <span class="comment">// Send handshake and config</span>
                <span class="function">sendHandshake</span>()

            } <span class="keyword">catch</span> (e: <span class="type">Exception</span>) {
                <span class="type">Log</span>.<span class="function">e</span>(TAG, <span class="string">"Server error: </span><span class="function">${e.message}</span><span class="string">"</span>, e)
            }
        }
    }

    <span class="keyword">private fun</span> <span class="function">sendHandshake</span>() {
        <span class="keyword">val</span> quality = StreamConfig.current
        <span class="keyword">val</span> handshake = <span class="type">ByteArray</span>(<span class="number">16</span>).<span class="function">apply</span> {
            <span class="function">set</span>(<span class="number">0</span>, <span class="number">0x01</span>)  <span class="comment">// Magic byte</span>
            <span class="function">set</span>(<span class="number">1</span>, <span class="number">0x02</span>)  <span class="comment">// Protocol version</span>
            <span class="function">putInt</span>(<span class="number">2</span>, quality.resolution.first)   <span class="comment">// Width</span>
            <span class="function">putInt</span>(<span class="number">6</span>, quality.resolution.second)  <span class="comment">// Height</span>
            <span class="function">putInt</span>(<span class="number">10</span>, quality.bitrate)           <span class="comment">// Bitrate</span>
            <span class="function">putByte</span>(<span class="number">14</span>, quality.fps.<span class="function">toByte</span>())   <span class="comment">// FPS</span>
            <span class="function">set</span>(<span class="number">15</span>, <span class="keyword">if</span> (quality.codec == <span class="string">"video/hevc"</span>) <span class="number">1</span> <span class="keyword">else</span> <span class="number">0</span>) <span class="comment">// Codec type</span>
        }
        clientSocket?.<span class="function">getOutputStream</span>()?.<span class="function">write</span>(handshake)
    }

    <span class="comment">// ============================================</span>
    <span class="comment">// PHASE 3: UDP STREAM (Optional for Ultra)</span>
    <span class="comment">// ============================================</span>

    <span class="keyword">private fun</span> <span class="function">startUdpStream</span>() {
        lifecycleScope.<span class="function">launch</span>(Dispatchers.IO) {
            <span class="keyword">try</span> {
                udpSocket = <span class="type">java.net.DatagramSocket</span>().<span class="function">apply</span> {
                    <span class="function">sendBufferSize</span> = <span class="number">65536</span>
                    <span class="function">receiveBufferSize</span> = <span class="number">65536</span>
                }

                <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"UDP stream started on port </span><span class="function">${StreamConfig.udpPort}</span><span class="string">"</span>)
            } <span class="keyword">catch</span> (e: <span class="type">Exception</span>) {
                <span class="type">Log</span>.<span class="function">e</span>(TAG, <span class="string">"UDP error: </span><span class="function">${e.message}</span><span class="string">"</span>, e)
            }
        }
    }

    <span class="comment">// ============================================</span>
    <span class="comment">// PHASE 4: ENCODING LOOP</span>
    <span class="comment">// ============================================</span>

    <span class="keyword">private fun</span> <span class="function">startEncodingLoop</span>() {
        lifecycleScope.<span class="function">launch</span>(Dispatchers.Default) {
            <span class="keyword">val</span> outputStream = clientSocket?.<span class="function">getOutputStream</span>()
            <span class="keyword">val</span> codec = encoder!!

            <span class="keyword">while</span> (isActive && codec.<span class="function">isAlive</span>) {
                <span class="keyword">val</span> inputBufId = codec.<span class="function">dequeueInputBuffer</span>(<span class="number">0</span>)

                <span class="keyword">if</span> (inputBufId >= <span class="number">0</span>) {
                    <span class="comment">// Fill input buffer with screen frame</span>
                    <span class="keyword">val</span> inputBuf = codec.<span class="function">getInputBuffer</span>(inputBufId)!!
                    inputBuf.<span class="function">clear</span>()

                    <span class="comment">// MediaProjection delivers frames to inputSurface</span>
                    <span class="comment">// We just signal the encoder that new data is available</span>
                    codec.<span class="function">queueInputBuffer</span>(
                        inputBufId, <span class="number">0</span>, <span class="number">0</span>,
                        <span class="type">System.nanoTime</span>() / <span class="number">1000</span>,
                        <span class="number">0</span>
                    )
                }

                <span class="comment">// Dequeue encoded output buffer</span>
                <span class="keyword">val</span> outputBufId = codec.<span class="function">dequeueOutputBuffer</span>(info, <span class="number">0</span>)

                <span class="keyword">if</span> (outputBufId >= <span class="number">0</span>) {
                    <span class="keyword">val</span> outputBuf = codec.<span class="function">getOutputBuffer</span>(outputBufId)!!

                    <span class="comment">// Send encoded frame over TCP</span>
                    <span class="keyword">val</span> frameData = <span class="type">ByteArray</span>(info.size).<span class="function">apply</span> {
                        outputBuf.<span class="function">get</span>(<span class="keyword">this</span>, <span class="number">0</span>, info.size)
                    }

                    <span class="comment">// Frame header: [4 bytes length][1 byte flags][data]</span>
                    <span class="keyword">val</span> header = <span class="type">ByteArray</span>(<span class="number">5</span>).<span class="function">apply</span> {
                        <span class="function">putInt</span>(<span class="number">0</span>, info.size)
                        <span class="function">set</span>(<span class="number">4</span>, <span class="keyword">if</span> (info.flags and <span class="type">MediaCodec</span>.BUFFER_FLAG_KEY_FRAME != <span class="number">0</span>) <span class="number">1</span> <span class="keyword">else</span> <span class="number">0</span>)
                    }

                    outputStream?.<span class="function">write</span>(header)
                    outputStream?.<span class="function">write</span>(frameData)
                    outputStream?.<span class="function">flush</span>()

                    bytesSent += info.size
                    frameCount++

                    <span class="comment">// Update metrics every 30 frames</span>
                    <span class="keyword">if</span> (frameCount % <span class="number">30</span> == <span class="number">0</span>) {
                        <span class="keyword">val</span> now = <span class="type">System.currentTimeMillis</span>()
                        <span class="keyword">val</span> elapsed = now - lastFrameTime
                        <span class="keyword">val</span> fps = (<span class="number">30000</span> / elapsed).<span class="function">toDouble</span>()
                        <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"FPS: </span><span class="function">${"%.1f".format(fps)}</span><span class="string"> | Sent: </span><span class="function">${bytesSent / 1024 / 1024}MB</span><span class="string">"</span>)
                        lastFrameTime = now
                        bytesSent = <span class="number">0</span>
                    }

                    codec.<span class="function">releaseOutputBuffer</span>(outputBufId, <span class="keyword">false</span>)
                } <span class="keyword">else if</span> (outputBufId == <span class="type">MediaCodec</span>.INFO_OUTPUT_FORMAT_CHANGED) {
                    <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"Encoder output format changed"</span>)
                }
            }
        }
    }

    <span class="comment">// ============================================</span>
    <span class="comment">// INPUT COMMAND HANDLER (from TV)</span>
    <span class="comment">// ============================================</span>

    <span class="keyword">private fun</span> <span class="function">handleInputCommand</span>(command: <span class="type">String</span>) {
        <span class="comment">// Parse and execute input commands from TV</span>
        <span class="keyword">val</span> parts = command.<span class="function">split</span>(<span class="string">":"</span>)
        <span class="keyword">val</span> type = parts[<span class="number">0</span>]

        <span class="keyword">when</span> (type) {
            <span class="string">"KEY"</span> -> <span class="function">executeKeyEvent</span>(parts[<span class="number">1</span>].<span class="function">toInt</span>())
            <span class="string">"TOUCH"</span> -> <span class="function">executeTouchEvent</span>(parts[<span class="number">1</span>].<span class="function">toInt</span>(), parts[<span class="number">2</span>].<span class="function">toInt</span>())
            <span class="string">"SCROLL"</span> -> <span class="function">executeScroll</span>(parts[<span class="number">1</span>].<span class="function">toInt</span>(), parts[<span class="number">2</span>].<span class="function">toInt</span>())
            <span class="string">"NAV"</span> -> <span class="function">executeNavigation</span>(parts[<span class="number">1</span>])
        }
    }

    <span class="keyword">private fun</span> <span class="function">executeKeyEvent</span>(keyCode: <span class="type">Int</span>) {
        <span class="comment">// Use Accessibility Service to simulate key events</span>
        <span class="type">InputExecutionService</span>.<span class="function">dispatchKeyEvent</span>(keyCode)
    }

    <span class="keyword">private fun</span> <span class="function">executeTouchEvent</span>(x: <span class="type">Int</span>, y: <span class="type">Int</span>) {
        <span class="type">InputExecutionService</span>.<span class="function">dispatchTouchEvent</span>(x, y)
    }

    <span class="keyword">private fun</span> <span class="function">executeScroll</span>(dx: <span class="type">Int</span>, dy: <span class="type">Int</span>) {
        <span class="type">InputExecutionService</span>.<span class="function">dispatchScroll</span>(dx, dy)
    }

    <span class="keyword">private fun</span> <span class="function">executeNavigation</span>(action: <span class="type">String</span>) {
        <span class="keyword">val</span> keyCodes = <span class="keyword">mapOf</span>(
            <span class="string">"BACK"</span> to <span class="type">KeyEvent</span>.KEYCODE_BACK,
            <span class="string">"HOME"</span> to <span class="type">KeyEvent</span>.KEYCODE_HOME,
            <span class="string">"RECENT"</span> to <span class="type">KeyEvent</span>.KEYCODE_APP_SWITCH,
            <span class="string">"UP"</span> to <span class="type">KeyEvent</span>.KEYCODE_DPAD_UP,
            <span class="string">"DOWN"</span> to <span class="type">KeyEvent</span>.KEYCODE_DPAD_DOWN,
            <span class="string">"LEFT"</span> to <span class="type">KeyEvent</span>.KEYCODE_DPAD_LEFT,
            <span class="string">"RIGHT"</span> to <span class="type">KeyEvent</span>.KEYCODE_DPAD_RIGHT,
            <span class="string">"ENTER"</span> to <span class="type">KeyEvent</span>.KEYCODE_ENTER
        )
        <span class="type">InputExecutionService</span>.<span class="function">dispatchKeyEvent</span>(keyCodes[action] ?: <span class="number">0</span>)
    }

    <span class="comment">// ============================================</span>
    <span class="comment">// NOTIFICATION (Foreground Service)</span>
    <span class="comment">// ============================================</span>

    <span class="keyword">private fun</span> <span class="function">createNotificationChannel</span>() {
        <span class="keyword">if</span> (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            <span class="keyword">val</span> channel = <span class="type">NotificationChannel</span>(
                CHANNEL_ID, <span class="string">"Screen Mirror"</span>,
                <span class="type">NotificationManager</span>.IMPORTANCE_LOW
            ).<span class="function">apply</span> {
                description = <span class="string">"Screen mirroring in progress"</span>
                setShowBadge(<span class="keyword">false</span>)
            }
            (<span class="function">getSystemService</span>(<span class="type">NOTIFICATION_SERVICE</span>) <span class="keyword">as</span> <span class="type">NotificationManager</span>)
                .<span class="function">createNotificationChannel</span>(channel)
        }
    }

    <span class="keyword">private fun</span> <span class="function">createNotification</span>(): <span class="type">Notification</span> {
        <span class="keyword">val</span> intent = <span class="function">PackageManager</span>.<span class="function">getLaunchIntentForPackage</span>(packageName)
        <span class="keyword">val</span> pendingIntent = <span class="type">PendingIntent</span>.<span class="function">getActivity</span>(
            <span class="this</span>, <span class="number">0</span>, intent,
            <span class="type">PendingIntent</span>.FLAG_IMMUTABLE
        )

        <span class="keyword">return</span> <span class="type">Notification</span>.<span class="type">Builder</span>(<span class="this</span>, CHANNEL_ID)
            .<span class="function">setContentTitle</span>(<span class="string">"ScreenMirror Pro"</span>)
            .<span class="function">setContentText</span>(<span class="string">"Streaming to TV"</span>)
            .<span class="function">setSmallIcon</span>(R.drawable.ic_notification)
            .<span class="function">setContentIntent</span>(pendingIntent)
            .<span class="function">setOngoing</span>(<span class="keyword">true</span>)
            .<span class="function">build</span>()
    }

    <span class="keyword">override fun</span> <span class="function">onDestroy</span>() {
        <span class="keyword">super</span>.<span class="function">onDestroy</span>()
        streamingJob?.<span class="function">cancel</span>()
        encoder?.<span class="function">stop</span>()
        encoder?.<span class="function">release</span>()
        inputSurface?.<span class="function">release</span>()
        mediaProjection?.<span class="function">stop</span>()
        serverSocket?.<span class="function">close</span>()
        clientSocket?.<span class="function">close</span>()
        udpSocket?.<span class="function">close</span>()
        wakeLock?.<span class="function">release</span>()
        <span class="type">Log</span>.<span class="function">d</span>(TAG, <span class="string">"Service destroyed"</span>)
    }
}</div>
