      <div class="setup-step">
        <h4>InputExecutionService - Accessibility Service</h4>
        <p>Executes input commands received from the TV on the mobile device.</p>
        <div class="code-block">
          <div class="code-header">
            <span class="code-filename">InputExecutionService.kt</span>
            <button class="code-copy" onclick="copyCode(this)">📋 Copy</button>
          </div>
          <div class="code-body"><span class="keyword">package</span> com.screenmirror.mobile

<span class="keyword">import</span> android.accessibilityservice.AccessibilityService
<span class="keyword">import</span> android.accessibilityservice.GestureDescription
<span class="keyword">import</span> android.graphics.Path
<span class="keyword">import</span> android.os.Build
<span class="keyword">import</span> android.os.Bundle
<span class="keyword">import</span> android.os.Handler
<span class="keyword">import</span> android.os.Looper
<span class="keyword">import</span> android.view.KeyEvent
<span class="keyword">import</span> android.view.accessibility.AccessibilityEvent
<span class="keyword">import</span> android.view.accessibility.AccessibilityNodeInfo

<span class="keyword">class</span> <span class="type">InputExecutionService</span> : <span class="type">AccessibilityService</span>() {

    <span class="keyword">companion object</span> {
        <span class="keyword">private var</span> instance: <span class="type">InputExecutionService</span>? = <span class="keyword">null</span>
        <span class="keyword">private val</span> handler = <span class="type">Handler</span>(<span class="type">Looper</span>.<span class="function">getMainLooper</span>())

        <span class="keyword">fun</span> <span class="function">dispatchKeyEvent</span>(keyCode: <span class="type">Int</span>) {
            instance?.<span class="function">_dispatchKeyEvent</span>(keyCode)
        }

        <span class="keyword">fun</span> <span class="function">dispatchTouchEvent</span>(x: <span class="type">Int</span>, y: <span class="type">Int</span>) {
            instance?.<span class="function">_dispatchTouch</span>(x, y)
        }

        <span class="keyword">fun</span> <span class="function">dispatchScroll</span>(dx: <span class="type">Int</span>, dy: <span class="type">Int</span>) {
            instance?.<span class="function">_dispatchScroll</span>(dx, dy)
        }
    }

    <span class="keyword">override fun</span> <span class="function">onServiceConnected</span>() {
        instance = <span class="keyword">this</span>
    }

    <span class="keyword">override fun</span> <span class="function">onAccessibilityEvent</span>(event: <span class="type">AccessibilityEvent</span>) {
        <span class="comment">// Track UI changes for debugging / state sync</span>
    }

    <span class="keyword">override fun</span> <span class="function">onInterrupt</span>() {
        instance = <span class="keyword">null</span>
    }

    <span class="comment">// Key Event Dispatch (Root or Accessibility)</span>
    <span class="keyword">private fun</span> <span class="function">_dispatchKeyEvent</span>(keyCode: <span class="type">Int</span>) {
        <span class="comment">// Method 1: Using Accessibility Service (non-root)</span>
        <span class="keyword">val</span> root = <span class="function">getRootInActiveWindow</span>()
        <span class="keyword">if</span> (root != <span class="keyword">null</span>) {
            <span class="comment">// Try to find and click the target node</span>
            <span class="keyword">val</span> node = <span class="function">findNodeByKey</span>(root, keyCode)
            <span class="keyword">if</span> (node != <span class="keyword">null</span>) {
                node.<span class="function">performAction</span>(<span class="type">AccessibilityNodeInfo</span>.ACTION_CLICK)
                node.<span class="function">recycle</span>()
            }
        }

        <span class="comment">// Method 2: Direct key event injection (requires root)</span>
        <span class="comment">// Runtime.getRuntime().exec("su -c \"input keyevent $keyCode\"")</span>

        <span class="comment">// Method 3: Using input command via shell</span>
        <span class="keyword">try</span> {
            <span class="type">Runtime</span>.<span class="function">getRuntime</span>().<span class="function">exec</span>(
                <span class="keyword">arrayOf</span>(<span class="string">"input"</span>, <span class="string">"keyevent"</span>, keyCode.<span class="function">toString</span>())
            )
        } <span class="keyword">catch</span> (e: <span class="type">Exception</span>) {
            e.<span class="function">printStackTrace</span>()
        }
    }

    <span class="comment">// Touch Event Dispatch</span>
    <span class="keyword">private fun</span> <span class="function">_dispatchTouch</span>(x: <span class="type">Int</span>, y: <span class="type">Int</span>) {
        <span class="keyword">if</span> (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
            <span class="comment">// Use GestureDescription for precise touch</span>
            <span class="keyword">val</span> path = <span class="type">Path</span>().<span class="function">apply</span> {
