      <div class="setup-step">
        <h4>CpuMonitor - System Resource Tracker</h4>
        <p>Monitors CPU usage for display in the UI.</p>
        <div class="code-block">
          <div class="code-header">
            <span class="code-filename">CpuMonitor.kt</span>
            <button class="code-copy" onclick="copyCode(this)">📋 Copy</button>
          </div>
          <div class="code-body"><span class="keyword">package</span> com.screenmirror.mobile

<span class="keyword">import</span> android.os.Build
<span class="keyword">import</span> java.io.BufferedReader
<span class="keyword">import</span> java.io.FileReader

<span class="keyword">object</span> <span class="type">CpuMonitor</span> {

    <span class="keyword">fun</span> <span class="function">getCpuUsage</span>(): <span class="type">Float</span> {
        <span class="keyword">return</span> <span class="keyword">try</span> {
            <span class="keyword">val</span> values = <span class="function">readCpuStats</span>()
            <span class="keyword">val</span> total1 = values[<span class="number">0</span>] + values[<span class="number">1</span>] + values[<span class="number">2</span>] + values[<span class="number">3</span>] + values[<span class="number">4</span>] + values[<span class="number">5</span>] + values[<span class="number">6</span>]
            <span class="keyword">val</span> idle1 = values[<span class="number">4</span>]

            <span class="type">Thread</span>.<span class="function">sleep</span>(<span class="number">500</span>)

            <span class="keyword">val</span> values2 = <span class="function">readCpuStats</span>()
            <span class="keyword">val</span> total2 = values2[<span class="number">0</span>] + values2[<span class="number">1</span>] + values2[<span class="number">2</span>] + values2[<span class="number">3</span>] + values2[<span class="number">4</span>] + values2[<span class="number">5</span>] + values2[<span class="number">6</span>]
            <span class="keyword">val</span> idle2 = values2[<span class="number">4</span>]

            <span class="keyword">val</span> totalDiff = total2 - total1
            <span class="keyword">val</span> idleDiff = idle2 - idle1

            <span class="keyword">if</span> (totalDiff == <span class="number">0</span>) <span class="number">0f</span>
            <span class="keyword">else</span> ((totalDiff - idleDiff) / totalDiff) * <span class="number">100f</span>
        } <span class="keyword">catch</span> (e: <span class="type">Exception</span>) {
            <span class="number">0f</span>
        }
    }

    <span class="keyword">private fun</span> <span class="function">readCpuStats</span>(): <span class="type">FloatArray</span> {
        <span class="keyword">val</span> reader = <span class="type">BufferedReader</span>(<span class="type">FileReader</span>(<span class="string">"/proc/stat"</span>))
        <span class="keyword">val</span> line = reader.<span class="function">readLine</span>()
        reader.<span class="function">close</span>()

        <span class="keyword">val</span> parts = line?.<span class="function">split</span>(<span class="string">"\\s+"</span>) ?: <span class="keyword">emptyList</span>()
        <span class="keyword">return</span> <span class="type">FloatArray</span>(<span class="number">7</span>) { index ->
            parts.<span class="function">getOrNull</span>(index + <span class="number">1</span>)?.<span class="function">toFloatOrNull</span>() ?: <span class="number">0f</span>
        }
    }
}</div>
