function getVal(id) { return document.getElementById(id).value; }
function getNum(id) { return parseFloat(document.getElementById(id).value) || 0; }
function getBool(id) { return document.getElementById(id).checked; }

function gatherAll() {
  return {
    string: getVal('v_string'),
    int: parseInt(getVal('v_int'), 10),
    float: parseFloat(getVal('v_float')),
    bool: getBool('v_bool'),
