    matrix: getVal('v_matrix').split(',').map(v => parseFloat(v.trim())),
    object: JSON.parse(getVal('v_object')),
    nested: JSON.parse(getVal('v_nested')),
    colorRaw: getVal('v_color'),
    timestamp: Date.now()
  };
