function parseVector2(s) { const p = s.split(',').map(Number); return { x: p[0], y: p[1] }; }
function parseVector3(s) { const p = s.split(',').map(Number); return { x: p[0], y: p[1], z: p[2] }; }
function parseVector4(s) { const p = s.split(',').map(Number); return { x: p[0], y: p[1], z: p[2], w: p[3] }; }
function parseColor(s) { const p = s.split(',').map(Number); return { r: p[0], g: p[1], b: p[2], a: p[3] }; }
function parseRect(s) { const p = s.split(',').map(Number); return { x: p[0], y: p[1], w: p[2], h: p[3] }; }

// ── Actions ──────────────────────────────────────────────
function saveAll() {
