  const settings = save.load('settings');
  const scores = save.load('scores');
  if (player) {
    document.getElementById('v_string').value = player.string || '';
    document.getElementById('v_int').value = player.int ?? 0;
    document.getElementById('v_float').value = player.float ?? 0;
    document.getElementById('v_bool').checked = player.bool ?? false;
    document.getElementById('v_enum').value = player.enum ?? 0;
    if (player.vector2) document.getElementById('v_vector2').value = `${player.vector2.x}, ${player.vector2.y}`;
    if (player.vector3) document.getElementById('v_vector3').value = `${player.vector3.x}, ${player.vector3.y}, ${player.vector3.z}`;
    if (player.vector4) document.getElementById('v_vector4').value = `${player.vector4.x}, ${player.vector4.y}, ${player.vector4.z}, ${player.vector4.w}`;
    if (player.color) document.getElementById('v_color_text').value = `${player.color.r}, ${player.color.g}, ${player.color.b}, ${player.color.a}`;
    if (player.rect) document.getElementById('v_rect').value = `${player.rect.x}, ${player.rect.y}, ${player.rect.w}, ${player.rect.h}`;
    if (player.range !== undefined) { document.getElementById('v_range').value = player.range; document.getElementById('v_range_val').textContent = player.range; }
    document.getElementById('v_nullable').value = player.nullable || '';
    if (player.array) document.getElementById('v_array').value = player.array.join(', ');
    if (player.matrix) document.getElementById('v_matrix').value = player.matrix.join(', ');
    if (player.object) document.getElementById('v_object').value = JSON.stringify(player.object);
    if (player.nested) document.getElementById('v_nested').value = JSON.stringify(player.nested);
    if (player.colorRaw) document.getElementById('v_color').value = player.colorRaw;
  }
  updateUI();
}

