};

// ===== CARD DATABASE =====
const CARD_DB = [
  // Common cards
  { id: 'strike', name: 'Strike', cost: 1, type: 'Attack', rarity: 'common', art: '⚔️', desc: 'Deal 6 damage.', effect: { type: 'damage', value: 6 } },
