  { id: 'fire_attack', name: 'Fire Bolt', cost: 1, type: 'Attack', rarity: 'common', art: '🔥', desc: 'Deal 4 damage. Apply 2 Poison.', effect: { type: 'damage', value: 4, apply: { type: 'poison', value: 2, turns: 3 } } },
  { id: 'war_cry', name: 'War Cry', cost: 0, type: 'Skill', rarity: 'common', art: '📯', desc: 'Gain 2 Energy.', effect: { type: 'energy', value: 2 } },
  { id: 'dagger_strike', name: 'Dagger Strike', cost: 0, type: 'Attack', rarity: 'common', art: '🗡️', desc: 'Deal 3 damage.', effect: { type: 'damage', value: 3 } },
  { id: 'meditate', name: 'Meditate', cost: 0, type: 'Skill', rarity: 'common', art: '🧘', desc: 'Draw 2 cards.', effect: { type: 'draw', value: 2 } },
