  // Uncommon cards
  { id: 'flame_blade', name: 'Flame Blade', cost: 2, type: 'Attack', rarity: 'uncommon', art: '⚔️', desc: 'Deal 12 damage.', effect: { type: 'damage', value: 12 } },
  { id: 'fortify', name: 'Fortify', cost: 1, type: 'Skill', rarity: 'uncommon', art: '🏰', desc: 'Gain 10 Block.', effect: { type: 'block', value: 10 } },
  { id: 'vampiric', name: 'Vampiric Touch', cost: 1, type: 'Attack', rarity: 'uncommon', art: '🧛', desc: 'Deal 7 damage. Heal 3 HP.', effect: { type: 'damage', value: 7, heal: 3 } },
  { id: 'berserk', name: 'Berserk', cost: 1, type: 'Skill', rarity: 'uncommon', art: '😤', desc: 'Gain 3 Strength. Lose 3 HP.', effect: { type: 'buff', stat: 'strength', value: 3, selfDmg: 3 } },
  { id: 'siphon', name: 'Siphon Life', cost: 2, type: 'Attack', rarity: 'uncommon', art: '💀', desc: 'Deal 6 damage. Heal 6 HP.', effect: { type: 'damage', value: 6, heal: 6 } },
  { id: 'iron_form', name: 'Iron Form', cost: 2, type: 'Skill', rarity: 'uncommon', art: '🗿', desc: 'Gain 8 Block. Apply 1 Weak to enemy.', effect: { type: 'block', value: 8, apply: { type: 'weak', value: 1, turns: 3 } } },
  { id: 'double_strike', name: 'Double Strike', cost: 1, type: 'Attack', rarity: 'uncommon', art: '⚔️', desc: 'Deal 5 damage twice.', effect: { type: 'damage', value: 5, multi: 2 } },
  { id: 'blood_ritual', name: 'Blood Ritual', cost: 1, type: 'Skill', rarity: 'uncommon', art: '🩸', desc: 'Lose 5 HP. Gain 8 Block.', effect: { type: 'block', value: 8, selfDmg: 5 } },

  // Rare cards
  { id: 'annihilate', name: 'Annihilate', cost: 3, type: 'Attack', rarity: 'rare', art: '💥', desc: 'Deal 20 damage.', effect: { type: 'damage', value: 20 } },
  { id: 'phantom_guard', name: 'Phantom Guard', cost: 1, type: 'Skill', rarity: 'rare', art: '👻', desc: 'Gain 15 Block.', effect: { type: 'block', value: 15 } },
  { id: 'blood_lust', name: 'Blood Lust', cost: 1, type: 'Attack', rarity: 'rare', art: '🔴', desc: 'Deal 8 damage. Gain 2 Strength.', effect: { type: 'damage', value: 8, buff: { stat: 'strength', value: 2 } } },
  { id: 'time_warp', name: 'Time Warp', cost: 0, type: 'Skill', rarity: 'rare', art: '⏳', desc: 'Draw 4 cards. Gain 1 Energy.', effect: { type: 'draw', value: 4, energy: 1 } },
  { id: 'abyssal_gaze', name: 'Abyssal Gaze', cost: 2, type: 'Attack', rarity: 'rare', art: '👁️', desc: 'Deal 10 damage. Apply 4 Poison.', effect: { type: 'damage', value: 10, apply: { type: 'poison', value: 4, turns: 4 } } },
  { id: 'soul_rend', name: 'Soul Rend', cost: 2, type: 'Attack', rarity: 'rare', art: '💜', desc: 'Deal 8 damage. Draw 2 cards.', effect: { type: 'damage', value: 8, draw: 2 } },

  // Boss card
  { id: 'dark_ritual', name: 'Dark Ritual', cost: 2, type: 'Attack', rarity: 'boss', art: '🔮', desc: 'Deal 15 damage. Apply 3 Weak & 3 Vulnerable.', effect: { type: 'damage', value: 15, apply: [{ type: 'weak', value: 3, turns: 3 }, { type: 'vulnerable', value: 3, turns: 3 }] } },
];

// ===== ENEMY DATABASE =====
const ENEMY_DB = [
  { name: 'Cursed Wretch', art: '🧟', hp: 28, atk: 6, def: 0, gold: 8, behavior: 'attack', desc: 'A mindless undead brute.' },
  { name: 'Shadow Fiend', art: '👤', hp: 22, atk: 8, def: 0, gold: 10, behavior: 'attack', desc: 'A creature of pure shadow.' },
  { name: 'Poison Spider', art: '🕷️', hp: 18, atk: 5, def: 0, gold: 7, behavior: 'poison', desc: 'Its bite injects venom.' },
  { name: 'Skeleton Warrior', art: '💀', hp: 35, atk: 7, def: 2, gold: 12, behavior: 'defend', desc: 'An armored undead soldier.' },
