  { name: 'Wraith', art: '👻', hp: 30, atk: 10, def: 1, gold: 14, behavior: 'attack', desc: 'A spectral horror.' },
  { name: 'Venom Serpent', art: '🐍', hp: 20, atk: 7, def: 0, gold: 9, behavior: 'poison', desc: 'Its fangs carry deadly poison.' },
