  // Boss
  { name: 'Lich King', art: '👑', hp: 80, atk: 12, def: 4, gold: 40, behavior: 'boss', desc: 'The undead sovereign of the abyss.', isBoss: true },
  { name: 'Abyssal Titan', art: '🌋', hp: 120, atk: 15, def: 6, gold: 60, behavior: 'boss', desc: 'An ancient entity of pure destruction.', isBoss: true },
];

// ===== UTILITY =====
function rand(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function pick(arr) { return arr[rand(0, arr.length - 1)]; }
function shuffle(arr) { for (let i = arr.length - 1; i > 0; i--) { const j = rand(0, i); [arr[i], arr[j]] = [arr[j], arr[i]]; } return arr; }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

function getCardById(id) { return CARD_DB.find(c => c.id === id); }

// ===== GAME INIT =====
function startGame() {
  document.getElementById('title-screen').style.display = 'none';
  document.getElementById('map-screen').style.display = 'flex';

  // Starting deck
  for (let i = 0; i < 4; i++) G.deck.push({ ...getCardById('strike') });
  for (let i = 0; i < 4; i++) G.deck.push({ ...getCardById('defend') });
  G.deck.push({ ...getCardById('heal') });
  G.deck.push({ ...getCardById('dagger_strike') });

  generateMap();
  updateMapUI();
  initMapCanvas();
}

// ===== MAP GENERATION =====
function generateMap() {
  G.mapNodes = [];
  const cols = 4;
  const rows = G.maxFloor + 2;
  let nodeId = 0;

  for (let row = 0; row < rows; row++) {
    const nodesInRow = row === 0 ? 1 : (row === rows - 1 ? 1 : rand(1, cols));
    for (let col = 0; col < nodesInRow; col++) {
      const type = row === 0 ? 'start' : (row === rows - 1 ? 'boss' : pickNodeType(row));
      G.mapNodes.push({
        id: nodeId++,
        row, col,
        type,
        x: 0, y: 0,
        visited: false,
        connected: false,
        cleared: false
      });
    }
  }

  // Connect nodes
  for (let i = 0; i < G.mapNodes.length; i++) {
    const node = G.mapNodes[i];
    const nextRow = G.mapNodes.filter(n => n.row === node.row + 1);
    if (nextRow.length > 0) {
      const target = pick(nextRow);
      node.target = target;
      target.parent = node;
    }
  }

  G.currentNode = G.mapNodes[0];
}

function pickNodeType(row) {
  const r = Math.random();
  if (r < 0.45) return 'combat';
  if (r < 0.60) return 'rest';
  if (r < 0.75) return 'shop';
  if (r < 0.85) return 'draft';
  if (r < 0.92) return 'elite';
  return 'event';
}

// ===== MAP RENDERING =====
let mapCanvas, mapCtx;

function initMapCanvas() {
  mapCanvas = document.getElementById('map-canvas');
  mapCtx = mapCanvas.getContext('2d');
  resizeMapCanvas();
  window.addEventListener('resize', resizeMapCanvas);
  mapCanvas.addEventListener('click', onMapClick);
  mapCanvas.addEventListener('mousemove', onMapHover);
  renderMap();
}

function resizeMapCanvas() {
  const container = document.getElementById('map-canvas-container');
  mapCanvas.width = container.clientWidth;
  mapCanvas.height = container.clientHeight;
  renderMap();
}

function renderMap() {
  if (!mapCtx) return;
  const w = mapCanvas.width;
  const h = mapCanvas.height;
  mapCtx.clearRect(0, 0, w, h);

  // Background
  const bgGrad = mapCtx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w*0.6);
  bgGrad.addColorStop(0, '#15101a');
  bgGrad.addColorStop(1, '#0a0a0f');
  mapCtx.fillStyle = bgGrad;
  mapCtx.fillRect(0, 0, w, h);

  // Calculate node positions
  const rows = Math.max(...G.mapNodes.map(n => n.row)) + 1;
  const nodeH = h / (rows + 1);
  const nodeW = w / 5;

  G.mapNodes.forEach(node => {
    node.x = nodeW * (node.col + 1.5);
    node.y = nodeH * (node.row + 1);
  });

  // Draw connections
  G.mapNodes.forEach(node => {
    if (node.target && node.cleared) {
      mapCtx.beginPath();
      mapCtx.moveTo(node.x, node.y);
      mapCtx.lineTo(node.target.x, node.target.y);
      mapCtx.strokeStyle = '#3a2a2a';
      mapCtx.lineWidth = 2;
      mapCtx.stroke();
    }
  });

  // Draw nodes
  G.mapNodes.forEach(node => {
    const cx = node.x;
    const cy = node.y;
    const r = 22;

    // Node glow
    if (node === G.currentNode) {
      mapCtx.beginPath();
      mapCtx.arc(cx, cy, r + 8, 0, Math.PI * 2);
      const glow = mapCtx.createRadialGradient(cx, cy, r, cx, cy, r + 8);
      glow.addColorStop(0, 'rgba(139,0,0,0.3)');
      glow.addColorStop(1, 'rgba(139,0,0,0)');
      mapCtx.fillStyle = glow;
      mapCtx.fill();
    }

    // Node circle
    mapCtx.beginPath();
    mapCtx.arc(cx, cy, r, 0, Math.PI * 2);

    let fillColor, strokeColor;
    if (node.cleared) {
      fillColor = '#1a1a1a';
      strokeColor = '#2a2a2a';
    } else if (node === G.currentNode) {
      fillColor = '#2a1010';
      strokeColor = '#8b0000';
    } else {
      fillColor = '#15101a';
      strokeColor = '#3a2a3a';
    }

    mapCtx.fillStyle = fillColor;
    mapCtx.fill();
    mapCtx.lineWidth = 2;
    mapCtx.strokeStyle = strokeColor;
    mapCtx.stroke();

    // Node icon
    mapCtx.font = '18px serif';
    mapCtx.textAlign = 'center';
    mapCtx.textBaseline = 'middle';
    let icon = '❓';
    if (node.cleared) icon = '✓';
    else if (node.type === 'combat') icon = '⚔️';
    else if (node.type === 'elite') icon = '💀';
    else if (node.type === 'rest') icon = '🔥';
    else if (node.type === 'shop') icon = '🏪';
    else if (node.type === 'draft') icon = '🃏';
    else if (node.type === 'event') icon = '✨';
    else if (node.type === 'boss') icon = '👑';
    else if (node.type === 'start') icon = '🚪';

    mapCtx.fillText(icon, cx, cy);

    // Node label
    mapCtx.font = '10px Cinzel, serif';
    mapCtx.fillStyle = '#6a5a4a';
    mapCtx.fillText(node.type.charAt(0).toUpperCase() + node.type.slice(1), cx, cy + r + 14);
  });

  // Draw ambient particles
  drawMapParticles();
}

let mapParticles = [];
function drawMapParticles() {
  if (Math.random() < 0.05) {
    mapParticles.push({
      x: rand(0, mapCanvas.width),
      y: rand(0, mapCanvas.height),
      vx: rand(-0.3, 0.3),
      vy: rand(-0.5, -0.1),
      life: rand(60, 180),
      size: rand(1, 3),
      color: Math.random() < 0.5 ? 'rgba(139,0,0,0.4)' : 'rgba(106,74,106,0.3)'
    });
  }

  mapParticles = mapParticles.filter(p => {
    p.x += p.vx;
    p.y += p.vy;
    p.life--;
    mapCtx.beginPath();
    mapCtx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    mapCtx.fillStyle = p.color.replace(/[\d.]+\)$/, (p.life / 180) + ')');
    mapCtx.fill();
    return p.life > 0;
  });

  if (document.getElementById('map-screen').style.display !== 'none') {
    requestAnimationFrame(drawMapParticles);
  }
}

function onMapClick(e) {
  if (!G.currentNode || G.currentNode.cleared) return;
  const rect = mapCanvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  // Check if clicking current node
  const cx = G.currentNode.x;
  const cy = G.currentNode.y;
  const dist = Math.sqrt((mx - cx) ** 2 + (my - cy) ** 2);

  if (dist < 30) {
    enterNode(G.currentNode);
    return;
  }

  // Check if clicking a connected node
  if (G.currentNode.target) {
    const t = G.currentNode.target;
    const tDist = Math.sqrt((mx - t.x) ** 2 + (my - t.y) ** 2);
    if (tDist < 30) {
      G.currentNode = t;
      renderMap();
      updateMapUI();
    }
  }
}

function onMapHover(e) {
  const rect = mapCanvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  mapCanvas.style.cursor = 'default';
  G.mapNodes.forEach(node => {
    const dist = Math.sqrt((mx - node.x) ** 2 + (my - node.y) ** 2);
    if (dist < 30 && (!node.cleared || node === G.currentNode)) {
      mapCanvas.style.cursor = 'pointer';
    }
  });
}

function updateMapUI() {
  document.getElementById('map-hp').textContent = `${G.player.hp}/${G.player.maxHp}`;
  document.getElementById('map-gold').textContent = G.player.gold;
  document.getElementById('map-deck-size').textContent = G.deck.length;
  document.getElementById('map-floor').textContent = G.floor;
}

// ===== NODE ENTRY =====
function enterNode(node) {
  if (node.type === 'combat' || node.type === 'elite') {
    startCombat(node.type === 'elite');
  } else if (node.type === 'rest') {
    showRest();
  } else if (node.type === 'shop') {
    showShop();
  } else if (node.type === 'draft') {
    startDraft();
  } else if (node.type === 'event') {
    triggerEvent();
  } else if (node.type === 'boss') {
    startCombat(true, true);
  } else if (node.type === 'start') {
    startCombat(false);
  }

  node.cleared = true;
  renderMap();
}

// ===== COMBAT =====
function startCombat(isElite, isBoss = false) {
  document.getElementById('map-screen').style.display = 'none';
  document.getElementById('combat-screen').style.display = 'flex';

  G.player.block = 0;
  G.player.energy = G.player.maxEnergy;
  G.combatTurn = 0;
  G.isPlayerTurn = true;
  G.combatActive = true;

  // Select enemy
  let pool = ENEMY_DB.filter(e => !e.isBoss);
  if (isBoss) pool = ENEMY_DB.filter(e => e.isBoss);
  else if (isElite) pool = ENEMY_DB.filter(e => e.hp > 25);

  const template = pick(pool);
  const scale = 1 + (G.floor - 1) * 0.15;

  G.currentEnemy = {
    ...template,
    hp: Math.floor(template.hp * scale),
    maxHp: Math.floor(template.hp * scale),
    atk: Math.floor(template.atk * scale),
    def: Math.floor(template.def * scale),
    effects: [],
    nextMove: null
  };

  if (isElite) {
    G.currentEnemy.hp = Math.floor(G.currentEnemy.hp * 1.5);
    G.currentEnemy.maxHp = G.currentEnemy.hp;
    G.currentEnemy.atk = Math.floor(G.currentEnemy.atk * 1.3);
  }

  // Reset player buffs/debuffs
  G.player.strength = 0;
  G.player.vulnerable = 0;

  // Setup draw pile
  G.drawPile = shuffle(G.deck.map(c => ({ ...c })));
  G.hand = [];
  G.discard = [];

  updateCombatUI();
  drawCards(5);
  computeEnemyMove();
}

function updateCombatUI() {
  const e = G.currentEnemy;
  document.getElementById('combat-hp').textContent = `${G.player.hp}/${G.player.maxHp}`;
  document.getElementById('combat-gold').textContent = G.player.gold;
  document.getElementById('combat-block').textContent = G.player.block;
  document.getElementById('energy-val').textContent = G.player.energy;
  document.getElementById('deck-count').textContent = G.drawPile.length;
  document.getElementById('discard-count').textContent = G.discard.length;

  document.getElementById('enemy-art').textContent = e.art;
  document.getElementById('enemy-name').textContent = e.name;
  document.getElementById('enemy-hp-text').textContent = `${e.hp}/${e.maxHp}`;
  document.getElementById('enemy-hp-fill').style.width = `${(e.hp / e.maxHp) * 100}%`;

  // Enemy effects
  const effectsDiv = document.getElementById('enemy-effects');
  effectsDiv.innerHTML = '';
  e.effects.forEach(fx => {
    const badge = document.createElement('span');
    badge.className = `effect-badge ${fx.type}`;
    badge.textContent = `${fx.type.charAt(0).toUpperCase() + fx.type.slice(1)} ${fx.value}`;
    effectsDiv.appendChild(badge);
  });

  // Player effects
  if (G.player.strength > 0) {
    const badge = document.createElement('span');
    badge.className = 'effect-badge buff';
    badge.textContent = `STR +${G.player.strength}`;
    effectsDiv.appendChild(badge);
  }
  if (G.player.vulnerable > 0) {
    const badge = document.createElement('span');
    badge.className = 'effect-badge vulnerable';
    badge.textContent = `VULN ${G.player.vulnerable}`;
    effectsDiv.appendChild(badge);
  }

  renderHand();
}

function renderHand() {
  const container = document.getElementById('hand-cards');
  container.innerHTML = '';

  G.hand.forEach((card, idx) => {
    const el = document.createElement('div');
    el.className = `card rarity-${card.rarity}`;
    if (card.cost > G.player.energy) el.classList.add('unplayable');

    el.innerHTML = `
      <div class="card-cost">${card.cost}</div>
      <div class="card-type">${card.type}</div>
      <div class="card-name">${card.name}</div>
      <div class="card-art">${card.art}</div>
      <div class="card-desc">${card.desc}</div>
    `;

    if (card.cost <= G.player.energy) {
      el.onclick = () => playCard(idx);
    }

    container.appendChild(el);
  });
}

function drawCards(count) {
  for (let i = 0; i < count; i++) {
    if (G.drawPile.length === 0) {
      if (G.discard.length === 0) break;
      G.drawPile = shuffle(G.discard.slice());
      G.discard = [];
    }
    if (G.drawPile.length > 0) {
      G.hand.push(G.drawPile.pop());
    }
  }
}

function playCard(idx) {
  if (!G.isPlayerTurn || !G.combatActive) return;

  const card = G.hand[idx];
  if (card.cost > G.player.energy) return;

  G.player.energy -= card.cost;
  G.hand.splice(idx, 1);
  G.discard.push(card);

  // Apply card effect
  applyCardEffect(card);

  updateCombatUI();
  checkCombatEnd();
}

function applyCardEffect(card) {
  const e = G.currentEnemy;
  const eff = card.effect;

  if (eff.type === 'damage') {
    let dmg = eff.value;
    if (eff.multi) {
      for (let i = 0; i < eff.multi; i++) {
        let d = dmg;
        if (e.def > 0) {
          const blocked = Math.min(e.def, d);
          e.def -= blocked;
          d -= blocked;
        }
        e.hp -= d;
        addLog(`You deal ${d} damage!`);
      }
    } else {
      let d = dmg;
      if (e.def > 0) {
        const blocked = Math.min(e.def, d);
        e.def -= blocked;
        d -= blocked;
      }
      e.hp -= d;
      addLog(`You deal ${d} damage!`);
    }
    flashEnemy();

    if (eff.block) {
      G.player.block += eff.block;
      addLog(`You gain ${eff.block} Block.`);
    }
    if (eff.heal) {
      G.player.hp = Math.min(G.player.maxHp, G.player.hp + eff.heal);
      addLog(`You heal ${eff.heal} HP.`);
    }
    if (eff.draw) {
      drawCards(eff.draw);
      addLog(`You draw ${eff.draw} cards.`);
    }
    if (eff.apply) {
      applyToEnemy(eff.apply);
    }
    if (eff.buff) {
      G.player[eff.buff.stat] = (G.player[eff.buff.stat] || 0) + eff.buff.value;
      addLog(`You gain ${eff.buff.value} ${eff.buff.stat}!`);
    }
    if (eff.selfDmg) {
      G.player.hp -= eff.selfDmg;
      addLog(`You lose ${eff.selfDmg} HP.`);
    }
  } else if (eff.type === 'block') {
    G.player.block += eff.value;
    addLog(`You gain ${eff.value} Block.`);
    if (eff.apply) applyToEnemy(eff.apply);
  } else if (eff.type === 'heal') {
    G.player.hp = Math.min(G.player.maxHp, G.player.hp + eff.value);
    addLog(`You heal ${eff.value} HP.`);
  } else if (eff.type === 'energy') {
    G.player.energy += eff.value;
    addLog(`You gain ${eff.value} Energy!`);
  } else if (eff.type === 'draw') {
    drawCards(eff.value);
    addLog(`You draw ${eff.value} cards.`);
    if (eff.energy) {
      G.player.energy += eff.energy;
      addLog(`You gain ${eff.energy} Energy!`);
    }
  } else if (eff.type === 'apply') {
    applyToEnemy(eff.effect);
  } else if (eff.type === 'buff') {
    G.player[eff.stat] = (G.player[eff.stat] || 0) + eff.value;
    addLog(`You gain ${eff.value} ${eff.stat}!`);
    if (eff.selfDmg) {
      G.player.hp -= eff.selfDmg;
      addLog(`You lose ${eff.selfDmg} HP.`);
    }
  }
}

function applyToEnemy(fx) {
  const e = G.currentEnemy;
  if (Array.isArray(fx)) {
    fx.forEach(f => applyToEnemy(f));
    return;
  }
  const existing = e.effects.find(f => f.type === fx.type);
  if (existing) {
    existing.value += fx.value;
    existing.turns = Math.max(existing.turns, fx.turns);
  } else {
    e.effects.push({ type: fx.type, value: fx.value, turns: fx.turns });
  }
  addLog(`${e.name} is affected by ${fx.type}!`);
}

function addLog(msg) {
  const log = document.getElementById('combat-log');
  const entry = document.createElement('div');
  entry.className = 'log-entry';
  entry.textContent = msg;
  log.appendChild(entry);
  setTimeout(() => entry.remove(), 2500);
}

function flashEnemy() {
  const sprite = document.getElementById('enemy-sprite');
  sprite.classList.remove('hit');
  void sprite.offsetWidth;
  sprite.classList.add('hit');
}

function computeEnemyMove() {
  const e = G.currentEnemy;
  const behaviors = {
    attack: () => {
      const dmg = e.atk + rand(-1, 2);
      e.nextMove = { type: 'attack', value: Math.max(1, dmg) };
    },
    defend: () => {
      const block = e.def + rand(2, 5);
      e.nextMove = { type: 'defend', value: block };
    },
    poison: () => {
      if (Math.random() < 0.4) {
        e.nextMove = { type: 'attack', value: e.atk };
      } else {
        e.nextMove = { type: 'poison', value: rand(3, 5) };
      }
    },
    debuff: () => {
      const r = Math.random();
      if (r < 0.33) {
        e.nextMove = { type: 'attack', value: e.atk };
      } else if (r < 0.66) {
        e.nextMove = { type: 'debuff_weak', value: rand(1, 3) };
      } else {
        e.nextMove = { type: 'debuff_vuln', value: rand(1, 3) };
      }
    },
    boss: () => {
      const r = Math.random();
      if (r < 0.4) {
        e.nextMove = { type: 'attack', value: e.atk + rand(0, 3) };
      } else if (r < 0.6) {
        e.nextMove = { type: 'defend', value: e.def + rand(2, 4) };
      } else if (r < 0.8) {
        e.nextMove = { type: 'debuff_weak', value: rand(1, 2) };
      } else {
        e.nextMove = { type: 'attack', value: e.atk + rand(2, 5) };
      }
    }
  };

  (behaviors[e.behavior] || behaviors.attack)();
}

function endTurn() {
  if (!G.isPlayerTurn || !G.combatActive) return;
  G.isPlayerTurn = false;
  document.getElementById('end-turn-btn').disabled = true;
  document.getElementById('end-turn-btn').style.opacity = '0.5';

  // Discard excess hand
  while (G.hand.length > 10) {
    G.discard.push(G.hand.pop());
  }

  // Enemy turn
  setTimeout(() => enemyTurn(), 600);
}

function enemyTurn() {
  const e = G.currentEnemy;

  // Process enemy effects (poison ticks)
  e.effects = e.effects.filter(fx => {
    if (fx.type === 'poison') {
      e.hp -= fx.value;
      addLog(`${e.name} takes ${fx.value} poison damage!`);
      fx.turns--;
      flashEnemy();
    }
    return fx.turns > 0;
  });

  if (e.hp <= 0) {
    updateCombatUI();
    checkCombatEnd();
    return;
  }

  // Process enemy move
  if (e.nextMove) {
    const move = e.nextMove;
    if (move.type === 'attack') {
      let dmg = move.value;
      // Apply vulnerable
      if (G.player.vulnerable > 0) {
        dmg = Math.floor(dmg * 1.5);
      }
      // Apply strength
      if (G.player.strength > 0) {
        dmg = Math.max(0, dmg - G.player.strength); // strength reduces incoming? No, strength increases damage dealt
      }
      // Player strength increases damage dealt by player, not reduces incoming
      // Let me fix: strength should increase player damage, not reduce enemy damage

      // Block
      let blocked = Math.min(G.player.block, dmg);
      G.player.block -= blocked;
      let actualDmg = dmg - blocked;
      G.player.hp -= actualDmg;
      addLog(`${e.name} deals ${actualDmg} damage!${blocked > 0 ? ` (${blocked} blocked)` : ''}`);
      flashScreen();

      if (G.player.block <= 0) G.player.block = 0;
    } else if (move.type === 'defend') {
      e.def += move.value;
      addLog(`${e.name} gains ${move.value} Block.`);
    } else if (move.type === 'poison') {
      const existing = e.effects.find(f => f.type === 'poison');
      if (existing) {
        existing.value += move.value;
        existing.turns = Math.max(existing.turns, move.value + 2);
      } else {
        e.effects.push({ type: 'poison', value: move.value, turns: move.value + 2 });
      }
      addLog(`${e.name} applies poison!`);
    } else if (move.type === 'debuff_weak') {
      const existing = e.effects.find(f => f.type === 'weak');
      if (existing) {
        existing.value += move.value;
        existing.turns = Math.max(existing.turns, move.value + 2);
      } else {
        e.effects.push({ type: 'weak', value: move.value, turns: move.value + 2 });
      }
      addLog(`${e.name} applies Weak!`);
    } else if (move.type === 'debuff_vuln') {
      const existing = e.effects.find(f => f.type === 'vulnerable');
      if (existing) {
        existing.value += move.value;
        existing.turns = Math.max(existing.turns, move.value + 2);
      } else {
        e.effects.push({ type: 'vulnerable', value: move.value, turns: move.value + 2 });
      }
      addLog(`${e.name} applies Vulnerable!`);
    }
  }

  // Process player effects (weak, vulnerable tick down)
  if (G.player.vulnerable > 0) G.player.vulnerable--;

  updateCombatUI();

  if (checkCombatEnd()) return;

  // Start player turn
  setTimeout(() => {
    G.combatTurn++;
    G.player.energy = G.player.maxEnergy;
    G.player.block = 0; // Block resets each turn
    G.isPlayerTurn = true;
    document.getElementById('end-turn-btn').disabled = false;
    document.getElementById('end-turn-btn').style.opacity = '1';
    drawCards(5);
    computeEnemyMove();
    updateCombatUI();
  }, 800);
}

function flashScreen() {
  const flash = document.createElement('div');
  flash.className = 'damage-flash';
  document.body.appendChild(flash);
  setTimeout(() => flash.remove(), 400);
}

function checkCombatEnd() {
  const e = G.currentEnemy;

  if (e.hp <= 0) {
    G.combatActive = false;
    G.totalKills++;
    G.player.gold += e.gold;
    G.totalGold += e.gold;

    addLog(`${e.name} is defeated!`);

    setTimeout(() => {
      document.getElementById('combat-screen').style.display = 'none';
      document.getElementById('map-screen').style.display = 'flex';

      if (e.isBoss) {
        showVictory();
        return;
      }

      G.floor++;
      updateMapUI();
      renderMap();

      // Auto draft after combat
      setTimeout(() => startDraft(), 300);
    }, 1500);

    return true;
  }

  if (G.player.hp <= 0) {
    G.combatActive = false;
    setTimeout(() => showGameOver(), 1000);
    return true;
  }

  return false;
}

// ===== DRAFT =====
function startDraft(fromShop = false) {
  document.getElementById('combat-screen').style.display = 'none';
  document.getElementById('map-screen').style.display = 'none';
  document.getElementById('draft-screen').style.display = 'flex';

  // Pick 3 random cards
  const options = [];
  const pool = [...CARD_DB];
  shuffle(pool);

  for (let i = 0; i < 3 && i < pool.length; i++) {
    // Weight by rarity
    const r = Math.random();
    let card;
    if (r < 0.6) {
      card = pool.find(c => c.rarity === 'common');
    } else if (r < 0.85) {
      card = pool.find(c => c.rarity === 'uncommon');
    } else if (r < 0.95) {
