        let sy = (i * 97 + 30) % 200;
        let brightness = 0.3 + Math.sin(Date.now()/1000 + i) * 0.3;
        ctx.globalAlpha = brightness;
        ctx.fillRect(sx, sy, 2, 2);
    }
    ctx.globalAlpha = 1;

    // Background mountains (parallax)
    ctx.fillStyle = '#1a1a3e';
    for (let i = 0; i < 10; i++) {
        let mx = i * 200 - (cameraX * 0.2) % 200;
        ctx.beginPath();
        ctx.moveTo(mx, 460);
        ctx.lineTo(mx + 100, 250 + Math.sin(i*2)*50);
        ctx.lineTo(mx + 200, 460);
        ctx.fill();
    }

    // Mid-ground hills (parallax)
    ctx.fillStyle = '#16213e';
    for (let i = 0; i < 15; i++) {
        let hx = i * 150 - (cameraX * 0.4) % 150;
        ctx.beginPath();
        ctx.moveTo(hx, 460);
        ctx.quadraticCurveTo(hx + 75, 350 + Math.sin(i*3)*30, hx + 150, 460);
        ctx.fill();
    }

    ctx.save();
    ctx.translate(-cameraX, 0);

    // Decorations
    decorations.forEach(d => {
        if (d.type === 'cloud') {
            ctx.fillStyle = 'rgba(255,255,255,0.15)';
            ctx.beginPath();
            ctx.ellipse(d.x + d.w/2, d.y + d.h/2, d.w/2, d.h/2, 0, 0, Math.PI*2);
            ctx.fill();
            ctx.beginPath();
            ctx.ellipse(d.x + d.w*0.3, d.y + d.h*0.4, d.w*0.3, d.h*0.4, 0, 0, Math.PI*2);
            ctx.fill();
            ctx.beginPath();
            ctx.ellipse(d.x + d.w*0.7, d.y + d.h*0.5, d.w*0.35, d.h*0.35, 0, 0, Math.PI*2);
            ctx.fill();
        } else if (d.type === 'tree') {
            // Trunk
            ctx.fillStyle = '#4a3728';
            ctx.fillRect(d.x + d.w/2 - 4, d.y - d.h, 8, d.h);
            // Leaves
            ctx.fillStyle = '#2d5a3d';
            ctx.beginPath();
            ctx.arc(d.x + d.w/2, d.y - d.h, d.w, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = '#3a7a4d';
            ctx.beginPath();
            ctx.arc(d.x + d.w/2 - 5, d.y - d.h - 5, d.w*0.7, 0, Math.PI*2);
            ctx.fill();
        }
    });

    // Platforms
    platforms.forEach(p => {
        if (p.type === 'ground') {
            // Ground
            let grd = ctx.createLinearGradient(p.x, p.y, p.x, p.y + p.h);
            grd.addColorStop(0, '#4a7c59');
            grd.addColorStop(0.3, '#3d6b4e');
            grd.addColorStop(1, '#2d4a35');
            ctx.fillStyle = grd;
            ctx.fillRect(p.x, p.y, p.w, p.h);

            // Grass top
            ctx.fillStyle = '#5cb85c';
            ctx.fillRect(p.x, p.y, p.w, 4);

            // Grass blades
            ctx.fillStyle = '#6dd66d';
            for (let gx = p.x; gx < p.x + p.w; gx += 8) {
                ctx.fillRect(gx, p.y - 3, 2, 5);
            }
        } else {
            // Floating platform
            let grd = ctx.createLinearGradient(p.x, p.y, p.x, p.y + p.h);
            grd.addColorStop(0, '#8b7355');
            grd.addColorStop(1, '#6b5340');
            ctx.fillStyle = grd;

            // Rounded platform
            let r = 4;
            ctx.beginPath();
            ctx.moveTo(p.x + r, p.y);
            ctx.lineTo(p.x + p.w - r, p.y);
            ctx.quadraticCurveTo(p.x + p.w, p.y, p.x + p.w, p.y + r);
            ctx.lineTo(p.x + p.w, p.y + p.h - r);
            ctx.quadraticCurveTo(p.x + p.w, p.y + p.h, p.x + p.w - r, p.y + p.h);
            ctx.lineTo(p.x + r, p.y + p.h);
            ctx.quadraticCurveTo(p.x, p.y + p.h, p.x, p.y + p.h - r);
            ctx.lineTo(p.x, p.y + r);
            ctx.quadraticCurveTo(p.x, p.y, p.x + r, p.y);
            ctx.fill();

            // Top highlight
            ctx.fillStyle = '#a0896b';
            ctx.fillRect(p.x + 2, p.y, p.w - 4, 3);

            if (p.type === 'moving') {
                ctx.fillStyle = '#4ecca3';
                ctx.fillRect(p.x + 4, p.y + 2, p.w - 8, 2);
            }
        }
    });

