        ctx.fill();

        // Coin body
        let coinGrad = ctx.createRadialGradient(cx - 2, cy - 2, 1, cx, cy, 8);
        coinGrad.addColorStop(0, '#fff700');
        coinGrad.addColorStop(0.5, '#ffd700');
        coinGrad.addColorStop(1, '#cc9900');
        ctx.fillStyle = coinGrad;
        ctx.beginPath();
