        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(ex - 8, ey - 8);
        ctx.lineTo(ex - 2, ey - 6);
        ctx.moveTo(ex + 8, ey - 8);
        ctx.lineTo(ex + 2, ey - 6);
        ctx.stroke();

