        let footOffset = Math.sin(Date.now()/150) * 3;
        ctx.fillStyle = '#c0392b';
        ctx.fillRect(ex - 10, ey + 12, 8, 4 + footOffset);
        ctx.fillRect(ex + 2, ey + 12, 8, 4 - footOffset);
    });

    // Flag
    if (flag) {
