        ctx.fillStyle = '#2c3e50';
        ctx.fillRect(-8, 8, 6, 14 + legAnim);
        ctx.fillRect(2, 8, 6, 14 - legAnim);

        // Shoes
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(-9, 20 + legAnim, 8, 4);
        ctx.fillRect(1, 20 - legAnim, 8, 4);

        // Body (suit)
        ctx.fillStyle = '#2c3e50';
        ctx.fillRect(-10, -8, 20, 18);

