        ctx.fillRect(-10, -22, 20, 5);

        // Eyes
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(-4, -16, 2, 0, Math.PI*2);
        ctx.arc(4, -16, 2, 0, Math.PI*2);
