        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(-4, -16, 4, 0, Math.PI*2);
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(4, -16, 4, 0, Math.PI*2);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(0, -16);
        ctx.lineTo(0, -16);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(-8, -16);
        ctx.lineTo(-11, -17);
        ctx.moveTo(8, -16);
        ctx.lineTo(11, -17);
        ctx.stroke();

