    ctx.strokeRect(canvas.width - 120, 10, 110, 40);

    ctx.fillStyle = '#e94560';
    ctx.font = 'bold 18px Arial';
    ctx.textAlign = 'right';
    let heartsStr = '';
    for (let i = 0; i < lives; i++) heartsStr += '❤️ ';
