function reload() {
    const w = player.weapons[player.currentWeapon];
    if (w.ammo < w.maxAmmo && w.reserve > 0) {
        const needed = w.maxAmmo - w.ammo;
        const available = Math.min(needed, w.reserve);
        w.ammo += available;
        w.reserve -= available;
        playSound(400, 0.1, 'sine', 0.1);
    }
}

function meleeAttack() {
    if (player.meleeCooldown > 0) return;
    player.meleeCooldown = 400;
    playSound(300, 0.15, 'square', 0.1);

    const meleeRange = 40;
    const mx = player.x + Math.cos(player.angle) * meleeRange;
    const my = player.y + Math.sin(player.angle) * meleeRange;

    enemies.forEach(e => {
        if (!e.alive) return;
        const dx = e.x - mx, dy = e.y - my;
        if (Math.sqrt(dx*dx + dy*dy) < 30) {
            e.health -= 30;
            spawnParticles(e.x, e.y, '#ff0000', 5);
            if (e.health <= 0) {
                e.alive = false;
                score += 100;
                wantedLevel = Math.min(5, wantedLevel + 0.5);
                wantedTimer = 600;
                checkMissionProgress('kill');
                spawnParticles(e.x, e.y, '#ff4444', 15);
            }
        }
    });
}

function shoot() {
    const now = Date.now();
    const w = player.weapons[player.currentWeapon];
    if (w.ammo <= 0) {
        if (w.reserve > 0) reload();
        return;
    }
    if (now - player.lastShot < w.fireRate) return;
    if (player.currentWeapon === 1) shotgunSound();
    else if (player.currentWeapon === 2) smgSound();
    else shootSound();

    player.lastShot = now;
    w.ammo--;
    muzzleFlash = 5;
    screenShake = player.currentWeapon === 1 ? 8 : player.currentWeapon === 2 ? 3 : 4;

    const pellets = w.pellets || 1;
    for (let i = 0; i < pellets; i++) {
        const spread = pellets > 1 ? (Math.random() - 0.5) * 0.4 : 0;
        const angle = player.angle + spread;
        bullets.push({
            x: player.x + Math.cos(player.angle) * 15,
            y: player.y + Math.sin(player.angle) * 15,
            vx: Math.cos(angle) * 12,
            vy: Math.sin(angle) * 12,
            damage: w.damage,
            life: 60,
            fromPlayer: true
        });
    }
}

function interact() {
    const interactRange = 50;
    let interacted = false;

    // Check NPCs
    npcs.forEach(npc => {
        const dx = player.x - npc.x, dy = player.y - npc.y;
        if (Math.sqrt(dx*dx + dy*dy) < interactRange) {
            showDialogBox(npc.speaker || npcDialogs[npc.type].speaker, npc.dialog);
            interacted = true;
            dialogSound();
        }
    });

    // Check location interactions
    Object.keys(locations).forEach(key => {
        const loc = locations[key];
        if (player.x > loc.x - 50 && player.x < loc.x + loc.w + 50 &&
            player.y > loc.y - 50 && player.y < loc.y + loc.h + 50) {
            if (key === 'hospital' && player.health < player.maxHealth) {
                player.health = Math.min(player.maxHealth, player.health + 50);
                score -= 100;
                showDialogBox('Doctor', 'I patched you up. That\'ll be 100 bucks.');
                interacted = true;
                pickupSound();
            }
            if (key === 'bar') {
                if (currentMission === 0 && !missions[0].done) {
                    missions[0].done = true;
                    score += missions[0].reward;
                    showDialogBox('Eda', 'Good work. The docks are crawling with rats. Clear them out!');
                    currentMission = 1;
                    pickupSound();
                } else {
                    showDialogBox('Eda', 'Welcome to the bar. Rest up, then get back out there.');
                    interacted = true;
                    dialogSound();
                }
            }
            if (key === 'warehouse' && currentMission === 2 && !missions[2].done) {
                missions[2].done = true;
                score += missions[2].reward;
                player.weapons[0].reserve += 24;
                player.weapons[1].reserve += 12;
                player.weapons[2].reserve += 30;
                showDialogBox('Rock', 'Found some supplies! Ammo is restocked.');
                currentMission = 3;
                interacted = true;
                pickupSound();
            }
        }
    });

    // Check pickups
    pickups.forEach(p => {
        if (!p.alive) return;
        const dx = player.x - p.x, dy = player.y - p.y;
        if (Math.sqrt(dx*dx + dy*dy) < interactRange) {
            if (p.type === 'health') {
                player.health = Math.min(player.maxHealth, player.health + p.amount);
                showDialogBox('System', `+${p.amount} Health`);
            } else if (p.type === 'ammo') {
                player.weapons[player.currentWeapon].reserve += p.amount;
                showDialogBox('System', `+${p.amount} Ammo`);
            }
            p.alive = false;
            interacted = true;
            pickupSound();
        }
    });
}

function showDialogBox(speaker, text) {
    const box = document.getElementById('dialog-box');
    document.getElementById('dialog-speaker').textContent = speaker;
    document.getElementById('dialog-text').textContent = text;
    box.style.display = 'block';
    setTimeout(() => { box.style.display = 'none'; }, 3000);
}

function spawnParticles(x, y, color, count) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x, y,
            vx: (Math.random() - 0.5) * 6,
            vy: (Math.random() - 0.5) * 6,
            life: 30 + Math.random() * 20,
            color,
            size: 2 + Math.random() * 3
        });
    }
}

function checkMissionProgress(type) {
    const m = missions[currentMission];
    if (!m || m.done) return;

    if (m.enemiesNeeded) {
        if (type === 'kill') {
            m.enemiesKilled = (m.enemiesKilled || 0) + 1;
            if (m.enemiesKilled >= m.enemiesNeeded) {
                m.done = true;
                score += m.reward;
                showDialogBox('Mission Complete', `${m.title} - Earned $${m.reward}`);
                if (currentMission < missions.length - 1) {
                    currentMission++;
                }
            }
        }
    }
}

function updatePlayer() {
    const spd = keys['shift'] ? player.sprintSpeed : player.speed;
    let dx = 0, dy = 0;
    if (keys['w'] || keys['arrowup']) dy = -1;
    if (keys['s'] || keys['arrowdown']) dy = 1;
    if (keys['a'] || keys['arrowleft']) dx = -1;
    if (keys['d'] || keys['arrowright']) dx = 1;

    if (dx !== 0 && dy !== 0) {
        dx *= 0.707;
        dy *= 0.707;
    }

    const newX = player.x + dx * spd;
    const newY = player.y + dy * spd;

    // Collision with buildings
    let canMoveX = true, canMoveY = true;
    buildings.forEach(b => {
        if (newX > b.x - player.w/2 && newX < b.x + b.w + player.w/2 &&
            player.y > b.y - player.h/2 && player.y < b.y + b.h + player.h/2) {
            canMoveX = false;
        }
        if (player.x > b.x - player.w/2 && player.x < b.x + b.w + player.w/2 &&
            newY > b.y - player.h/2 && newY < b.y + b.h + player.h/2) {
            canMoveY = false;
        }
    });

    if (canMoveX) player.x = Math.max(player.w/2, Math.min(WORLD_W - player.w/2, newX));
    if (canMoveY) player.y = Math.max(player.h/2, Math.min(WORLD_H - player.h/2, newY));

    // Aim
    const worldMouseX = mouse.x + camera.x;
    const worldMouseY = mouse.y + camera.y;
    player.angle = Math.atan2(worldMouseY - player.y, worldMouseX - player.x);

    // Shoot
    const w = player.weapons[player.currentWeapon];
    if (mouse.down && (w.auto || Date.now() - player.lastShot >= w.fireRate)) {
        shoot();
    }

    if (player.meleeCooldown > 0) player.meleeCooldown -= 16;
    if (muzzleFlash > 0) muzzleFlash--;
    if (screenShake > 0) screenShake *= 0.8;

    // Wanted timer
    if (wantedTimer > 0) {
        wantedTimer--;
        if (wantedTimer <= 0) wantedLevel = Math.max(0, wantedLevel - 0.5);
    }

    // Time
    gameTime += 0.5;
    if (gameTime >= 1440) { gameTime = 0; day++; }
}

function updateEnemies() {
    enemies.forEach(e => {
        if (!e.alive) return;

        const dx = player.x - e.x, dy = player.y - e.y;
        const dist = Math.sqrt(dx*dx + dy*dy);

        // Alert range
        if (dist < 300) {
            e.alert = true;
            e.angle = Math.atan2(dy, dx);
        }

        if (e.alert) {
            // Chase player
            if (dist > 80) {
                e.x += Math.cos(e.angle) * e.speed;
                e.y += Math.sin(e.angle) * e.speed;
            }

            // Shoot at player
            const now = Date.now();
            if (dist < 350 && now - e.lastShot > e.fireRate) {
                e.lastShot = now;
                const spread = (Math.random() - 0.5) * 0.3;
                bullets.push({
                    x: e.x + Math.cos(e.angle) * 12,
                    y: e.y + Math.sin(e.angle) * 12,
                    vx: Math.cos(e.angle + spread) * 8,
                    vy: Math.sin(e.angle + spread) * 8,
                    damage: e.damage,
                    life: 40,
                    fromPlayer: false
                });
                playSound(200 + Math.random()*100, 0.08, 'sawtooth', 0.08);
            }
        } else {
            // Patrol
            e.patrolTimer--;
            if (e.patrolTimer <= 0) {
                e.patrolAngle = Math.random() * Math.PI * 2;
                e.patrolTimer = 100 + Math.random() * 200;
            }
            e.x += Math.cos(e.patrolAngle) * e.speed * 0.3;
            e.y += Math.sin(e.patrolAngle) * e.speed * 0.3;
            e.angle = e.patrolAngle;
        }

        // Keep in bounds
        e.x = Math.max(10, Math.min(WORLD_W - 10, e.x));
        e.y = Math.max(10, Math.min(WORLD_H - 10, e.y));
    });
}

function updateNPCs() {
    npcs.forEach(npc => {
        npc.moveTimer--;
        if (npc.moveTimer <= 0) {
            npc.angle = Math.random() * Math.PI * 2;
            npc.moveTimer = 100 + Math.random() * 200;
        }
        npc.x += Math.cos(npc.angle) * 0.5;
        npc.y += Math.sin(npc.angle) * 0.5;

        // Keep near their location
        const locKey = npc.type === 'bar_owner' || npc.type === 'revy' || npc.type === 'dennis' || npc.type === 'benny' || npc.type === 'rock' ? 'bar' :
                       npc.type === 'cop' ? 'police' : 'market';
        const loc = locations[locKey];
        if (loc) {
            const dx = npc.x - (loc.x + loc.w/2);
            const dy = npc.y - (loc.y + loc.h/2);
            if (Math.abs(dx) > loc.w/2 + 50 || Math.abs(dy) > loc.h/2 + 50) {
                npc.angle = Math.atan2(loc.y + loc.h/2 - npc.y, loc.x + loc.w/2 - npc.x);
            }
        }
    });
}

function updateBullets() {
    for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.x += b.vx;
        b.y += b.vy;
        b.life--;

        if (b.life <= 0 || b.x < 0 || b.x > WORLD_W || b.y < 0 || b.y > WORLD_H) {
            bullets.splice(i, 1);
            continue;
        }

        // Hit buildings
        let hitBuilding = false;
        buildings.forEach(bld => {
            if (b.x > bld.x && b.x < bld.x + bld.w && b.y > bld.y && b.y < bld.y + bld.h) {
                hitBuilding = true;
                spawnParticles(b.x, b.y, '#aaaaaa', 3);
            }
        });
        if (hitBuilding) { bullets.splice(i, 1); continue; }

        if (b.fromPlayer) {
            // Hit enemies
            enemies.forEach(e => {
                if (!e.alive) return;
                const dx = b.x - e.x, dy = b.y - e.y;
                if (Math.sqrt(dx*dx + dy*dy) < 15) {
                    e.health -= b.damage;
                    spawnParticles(b.x, b.y, '#ff0000', 5);
                    hitSound();
                    bullets.splice(i, 1);

                    if (e.health <= 0) {
                        e.alive = false;
                        score += 100;
                        wantedLevel = Math.min(5, wantedLevel + 0.5);
                        wantedTimer = 600;
                        checkMissionProgress('kill');
                        spawnParticles(e.x, e.y, '#ff4444', 15);
                        // Drop ammo
                        if (Math.random() > 0.5) {
                            pickups.push({ x: e.x, y: e.y, type: 'ammo', amount: 6, alive: true });
                        }
                    }
                    return;
                }
            });
        } else {
            // Hit player
            const dx = b.x - player.x, dy = b.y - player.y;
            if (Math.sqrt(dx*dx + dy*dy) < 12) {
                player.health -= b.damage;
                spawnParticles(b.x, b.y, '#ff0000', 8);
                screenShake = 5;
                bullets.splice(i, 1);

                if (player.health <= 0) {
                    document.getElementById('death-screen').style.display = 'flex';
                }
            }
        }
    }
}

function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vx *= 0.95;
        p.vy *= 0.95;
        p.life--;
        if (p.life <= 0) particles.splice(i, 1);
    }
}

function updateCamera() {
    camera.x = player.x - canvas.width / 2;
    camera.y = player.y - canvas.height / 2;
    camera.x = Math.max(0, Math.min(WORLD_W - canvas.width, camera.x));
    camera.y = Math.max(0, Math.min(WORLD_H - canvas.height, camera.y));
}

function drawWorld() {
    // Background - tropical ground
    const startCol = Math.floor(camera.x / 40);
    const startRow = Math.floor(camera.y / 40);
    const endCol = startCol + Math.ceil(canvas.width / 40) + 2;
    const endRow = startRow + Math.ceil(canvas.height / 40) + 2;

    for (let col = startCol; col < endCol; col++) {
        for (let row = startRow; row < endRow; row++) {
            const x = col * 40 - camera.x;
            const y = row * 40 - camera.y;
            const hash = (col * 73856093 ^ row * 19349663) & 0xFFFFFF;
            const r = 40 + (hash % 30);
            const g = 80 + (hash % 40);
            const b = 30 + (hash % 20);
            ctx.fillStyle = `rgb(${r},${g},${b})`;
            ctx.fillRect(x, y, 40, 40);
        }
    }

    // Draw roads
    roadSegments.forEach(r => {
        const sx = r.x - camera.x, sy = r.y - camera.y;
        if (sx > -100 && sx < canvas.width + 100 && sy > -100 && sy < canvas.height + 100) {
            ctx.fillStyle = '#555555';
            ctx.fillRect(sx, sy, r.w, r.h);
            // Road markings
            ctx.strokeStyle = '#777744';
            ctx.lineWidth = 1;
            if (r.dir === 'h') {
                for (let mx = sx; mx < sx + r.w; mx += 20) {
                    ctx.beginPath();
                    ctx.moveTo(mx, sy + r.h/2 - 1);
                    ctx.lineTo(mx + 10, sy + r.h/2 - 1);
                    ctx.stroke();
                }
            } else {
                for (let my = sy; my < sy + r.h; my += 20) {
                    ctx.beginPath();
                    ctx.moveTo(sx + r.w/2 - 1, my);
                    ctx.lineTo(sx + r.w/2 - 1, my + 10);
                    ctx.stroke();
                }
            }
        }
    });

    // Draw water (ocean at edges)
    ctx.fillStyle = '#1a5276';
    ctx.fillRect(0, Math.max(0, camera.y), canvas.width, Math.min(WORLD_H, canvas.height) - camera.y);

    // Draw beach
    const beach = locations.beach;
    if (beach) {
        const bx = beach.x - camera.x, by = beach.y - camera.y;
        ctx.fillStyle = '#F4A460';
        ctx.fillRect(bx, by, beach.w, beach.h);
        ctx.fillStyle = '#87CEEB';
        ctx.fillRect(bx, by + beach.h - 20, beach.w, 20);
        // Waves
        ctx.strokeStyle = '#5dade2';
        ctx.lineWidth = 2;
        for (let i = 0; i < 5; i++) {
            ctx.beginPath();
            for (let wx = bx; wx < bx + beach.w; wx += 5) {
                ctx.lineTo(wx, by + beach.h - 15 + Math.sin(wx * 0.05 + gameTime * 0.02 + i) * 5);
            }
            ctx.stroke();
        }
    }

    // Draw buildings
    buildings.forEach(b => {
        const bx = b.x - camera.x, by = b.y - camera.y;
        if (bx > -b.w - 10 && bx < canvas.width + 10 && by > -b.h - 10 && by < canvas.height + 10) {
            // Shadow
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.fillRect(bx + 5, by + 5, b.w, b.h);

            // Building
            ctx.fillStyle = b.color;
            ctx.fillRect(bx, by, b.w, b.h);
            ctx.fillStyle = b.color2;
            ctx.fillRect(bx + 3, by + 3, b.w - 6, b.h - 6);

            // Roof detail
            ctx.fillStyle = b.roofColor || b.color;
            ctx.fillRect(bx + 8, by + 8, b.w - 16, b.h - 16);

            // Windows
            ctx.fillStyle = 'rgba(255,255,150,0.6)';
            const winSize = 12;
            for (let wx = bx + 15; wx < bx + b.w - 15; wx += 25) {
                for (let wy = by + 15; wy < by + b.h - 15; wy += 25) {
                    ctx.fillRect(wx, wy, winSize, winSize);
                }
            }

            // Door
            ctx.fillStyle = '#333';
            ctx.fillRect(bx + b.w/2 - 8, by + b.h - 15, 16, 15);

            // Name sign
            ctx.fillStyle = '#fff';
            ctx.font = '10px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText(b.name, bx + b.w/2, by - 5);
        }
    });

    // Draw pickups
    pickups.forEach(p => {
        if (!p.alive) return;
        const px = p.x - camera.x, py = p.y - camera.y;
        if (px > -20 && px < canvas.width + 20 && py > -20 && py < canvas.height + 20) {
            const pulse = Math.sin(Date.now() * 0.005) * 3;
            ctx.fillStyle = p.type === 'health' ? '#00ff00' : '#ffaa00';
            ctx.beginPath();
            ctx.arc(px, py, 8 + pulse, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#fff';
            ctx.font = '10px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText(p.type === 'health' ? '+' : '•', px, py + 4);
        }
    });

    // Draw NPCs
    npcs.forEach(npc => {
        const nx = npc.x - camera.x, ny = npc.y - camera.y;
        if (nx > -30 && nx < canvas.width + 30 && ny > -30 && ny < canvas.height + 30) {
            // Body
            ctx.fillStyle = '#4488ff';
            ctx.beginPath();
            ctx.arc(nx, ny, 9, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#2266cc';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Direction indicator
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.arc(nx + Math.cos(npc.angle) * 5, ny + Math.sin(npc.angle) * 5, 3, 0, Math.PI * 2);
            ctx.fill();

            // Name
            ctx.fillStyle = '#aaddff';
            ctx.font = '10px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText(npcDialogs[npc.type].speaker, nx, ny - 15);
        }
    });

    // Draw enemies
    enemies.forEach(e => {
        if (!e.alive) return;
        const ex = e.x - camera.x, ey = e.y - camera.y;
        if (ex > -30 && ex < canvas.width + 30 && ey > -30 && ey < canvas.height + 30) {
            // Alert indicator
            if (e.alert) {
                ctx.fillStyle = '#ff0000';
                ctx.font = '14px Courier New';
                ctx.textAlign = 'center';
                ctx.fillText('!', ex, ey - 20);
            }

            // Body
            ctx.fillStyle = e.color;
            ctx.beginPath();
            ctx.arc(ex, ey, 10, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1.5;
            ctx.stroke();

            // Gun direction
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(ex + Math.cos(e.angle) * 8, ey + Math.sin(e.angle) * 8);
            ctx.lineTo(ex + Math.cos(e.angle) * 18, ey + Math.sin(e.angle) * 18);
            ctx.stroke();

            // Health bar
            const barW = 24;
            const barH = 4;
            ctx.fillStyle = '#333';
            ctx.fillRect(ex - barW/2, ey - 18, barW, barH);
            ctx.fillStyle = e.health > e.maxHealth * 0.5 ? '#00ff00' : e.health > e.maxHealth * 0.25 ? '#ffaa00' : '#ff0000';
            ctx.fillRect(ex - barW/2, ey - 18, barW * (e.health / e.maxHealth), barH);

            // Type label
            ctx.fillStyle = '#ff8888';
            ctx.font = '9px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText(e.type, ex, ey - 22);
        }
    });

    // Draw bullets
    bullets.forEach(b => {
        const bx = b.x - camera.x, by = b.y - camera.y;
        ctx.fillStyle = b.fromPlayer ? '#ffff00' : '#ff4444';
        ctx.beginPath();
        ctx.arc(bx, by, 3, 0, Math.PI * 2);
        ctx.fill();
        // Trail
        ctx.strokeStyle = b.fromPlayer ? 'rgba(255,255,0,0.3)' : 'rgba(255,68,68,0.3)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(bx, by);
        ctx.lineTo(bx - b.vx * 2, by - b.vy * 2);
        ctx.stroke();
    });

    // Draw player
    const px = player.x - camera.x, py = player.y - camera.y;

    // Muzzle flash
    if (muzzleFlash > 0) {
        ctx.fillStyle = '#ffff00';
        ctx.beginPath();
        ctx.arc(px + Math.cos(player.angle) * 20, py + Math.sin(player.angle) * 20, 8, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(px + Math.cos(player.angle) * 20, py + Math.sin(player.angle) * 20, 4, 0, Math.PI * 2);
        ctx.fill();
    }

    // Player body
    ctx.fillStyle = '#228B22';
    ctx.beginPath();
    ctx.arc(px, py, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#006400';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Gun
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(px + Math.cos(player.angle) * 10, py + Math.sin(player.angle) * 10);
    ctx.lineTo(px + Math.cos(player.angle) * 22, py + Math.sin(player.angle) * 22);
    ctx.stroke();

    // Player direction indicator
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(px + Math.cos(player.angle) * 6, py + Math.sin(player.angle) * 6, 4, 0, Math.PI * 2);
    ctx.fill();

    // Particles
    particles.forEach(p => {
        const ppx = p.x - camera.x, ppy = p.y - camera.y;
        ctx.globalAlpha = p.life / 50;
        ctx.fillStyle = p.color;
        ctx.fillRect(ppx - p.size/2, ppy - p.size/2, p.size, p.size);
    });
    ctx.globalAlpha = 1;

    // Night overlay
    const hour = Math.floor(gameTime / 60);
    if (hour >= 19 || hour < 6) {
        const nightAlpha = hour >= 20 && hour < 5 ? 0.4 : 0.2;
        ctx.fillStyle = `rgba(0,0,30,${nightAlpha})`;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Street lights glow
        roadSegments.forEach(r => {
            if (r.w === 60 && r.dir === 'v') {
                const sx = r.x - camera.x + r.w/2;
                const sy = r.y - camera.y;
                if (sx > -50 && sx < canvas.width + 50 && sy > -50 && sy < canvas.height + 50) {
                    const grad = ctx.createRadialGradient(sx, sy, 0, sx, sy, 60);
                    grad.addColorStop(0, 'rgba(255,200,100,0.15)');
                    grad.addColorStop(1, 'rgba(255,200,100,0)');
                    ctx.fillStyle = grad;
                    ctx.fillRect(sx - 60, sy - 60, 120, 120);
                }
            }
        });
    }

    // Interaction prompt
    let nearInteractable = false;
    const interactRange = 50;
    npcs.forEach(npc => {
        const dx = player.x - npc.x, dy = player.y - npc.y;
        if (Math.sqrt(dx*dx + dy*dy) < interactRange) nearInteractable = true;
    });
    Object.keys(locations).forEach(key => {
        const loc = locations[key];
        if (player.x > loc.x - 50 && player.x < loc.x + loc.w + 50 &&
            player.y > loc.y - 50 && player.y < loc.y + loc.h + 50) nearInteractable = true;
    });
    pickups.forEach(p => {
        if (!p.alive) return;
        const dx = player.x - p.x, dy = player.y - p.y;
        if (Math.sqrt(dx*dx + dy*dy) < interactRange) nearInteractable = true;
    });
    document.getElementById('interaction-prompt').style.display = nearInteractable ? 'block' : 'none';
}

function drawMinimap() {
    mctx.fillStyle = '#1a3a1a';
    mctx.fillRect(0, 0, 200, 200);

    const scaleX = 200 / WORLD_W;
    const scaleY = 200 / WORLD_H;

    // Roads on minimap
    mctx.fillStyle = '#444';
    roadSegments.forEach(r => {
        mctx.fillRect(r.x * scaleX, r.y * scaleY, Math.max(r.w * scaleX, 1), Math.max(r.h * scaleY, 1));
    });

    // Buildings on minimap
    buildings.forEach(b => {
        mctx.fillStyle = b.color;
        mctx.fillRect(b.x * scaleX, b.y * scaleY, Math.max(b.w * scaleX, 2), Math.max(b.h * scaleY, 2));
    });

    // Beach
    const beach = locations.beach;
    if (beach) {
        mctx.fillStyle = '#F4A460';
        mctx.fillRect(beach.x * scaleX, beach.y * scaleY, beach.w * scaleX, beach.h * scaleY);
    }

    // Enemies on minimap
    enemies.forEach(e => {
        if (!e.alive) return;
        mctx.fillStyle = '#ff0000';
        mctx.fillRect(e.x * scaleX - 1, e.y * scaleY - 1, 3, 3);
    });

    // NPCs on minimap
    npcs.forEach(npc => {
        mctx.fillStyle = '#4488ff';
        mctx.fillRect(npc.x * scaleX - 1, npc.y * scaleY - 1, 3, 3);
    });

    // Pickups on minimap
    pickups.forEach(p => {
        if (!p.alive) return;
        mctx.fillStyle = p.type === 'health' ? '#00ff00' : '#ffaa00';
        mctx.fillRect(p.x * scaleX - 1, p.y * scaleY - 1, 3, 3);
    });

    // Player on minimap
    mctx.fillStyle = '#00ff00';
    mctx.beginPath();
    mctx.arc(player.x * scaleX, player.y * scaleY, 4, 0, Math.PI * 2);
    mctx.fill();
    mctx.strokeStyle = '#fff';
    mctx.lineWidth = 1;
    mctx.stroke();

    // Camera view
    mctx.strokeStyle = 'rgba(255,255,255,0.3)';
    mctx.lineWidth = 1;
    mctx.strokeRect(camera.x * scaleX, camera.y * scaleY, canvas.width * scaleX, canvas.height * scaleY);

    // Border
    mctx.strokeStyle = '#ff4444';
    mctx.lineWidth = 2;
    mctx.strokeRect(0, 0, 200, 200);
}

function updateHUD() {
    const w = player.weapons[player.currentWeapon];
    document.getElementById('health-fill').style.width = (player.health / player.maxHealth * 100) + '%';
    document.getElementById('ammo-display').textContent = `🔫 ${w.name}: ${w.ammo}/${w.reserve}`;
    document.getElementById('score-display').textContent = `💰 $${score}`;

    const hours = Math.floor(gameTime / 60);
    const minutes = Math.floor(gameTime % 60);
    const timeStr = `${hours.toString().padStart(2,'0')}:${minutes.toString().padStart(2,'0')}`;
    const icon = (hours >= 6 && hours < 19) ? '☀️' : '🌙';
    document.getElementById('day-display').textContent = `${icon} DAY ${day} - ${timeStr}`;

    // Mission
    const m = missions[currentMission];
    document.getElementById('mission-title').textContent = m ? m.title : 'ALL MISSIONS COMPLETE';
    document.getElementById('mission-desc').textContent = m ? m.desc : 'Welcome to Roanapur. Survive.';

    // Wanted level
    let wantedHTML = '';
    for (let i = 0; i < 5; i++) {
        wantedHTML += `<span class="wanted-star ${i < Math.ceil(wantedLevel) ? 'active' : ''}">★</span> `;
    }
    document.getElementById('wanted-level').innerHTML = wantedHTML;
}

function gameLoop() {
    if (!gameStarted) return;

    // Screen shake
    ctx.save();
    if (screenShake > 0.5) {
        ctx.translate(
            (Math.random() - 0.5) * screenShake,
            (Math.random() - 0.5) * screenShake
        );
    }

    updatePlayer();
    updateEnemies();
    updateNPCs();
    updateBullets();
    updateParticles();
    updateCamera();

    drawWorld();
    ctx.restore();

    drawMinimap();
    updateHUD();

    requestAnimationFrame(gameLoop);
}

// Start
document.getElementById('start-btn').addEventListener('click', () => {
    document.getElementById('start-screen').style.display = 'none';
    gameStarted = true;
    audioCtx.resume();
    initWorld();
    gameLoop();
});

// Ambient sounds
setInterval(() => {
    if (!gameStarted) return;
    if (Math.random() > 0.7) {
        playSound(100 + Math.random() * 200, 0.3, 'sine', 0.02);
    }
}, 2000);
</script>
</body>
</html>
