.form-group{margin-bottom:15px;}
.form-group label{display:block;color:var(--text-dim);margin-bottom:5px;font-size:0.9em;}
.form-group input,.form-group select{width:100%;padding:10px 12px;background:var(--bg-dark);border:1px solid var(--border);border-radius:6px;color:var(--text);font-size:1em;outline:none;}
.form-group input:focus,.form-group select:focus{border-color:var(--gold);}
.btn{padding:10px 24px;border:none;border-radius:6px;cursor:pointer;font-size:1em;font-weight:600;transition:all 0.2s;font-family:'Noto Sans',sans-serif;}
.btn-gold{background:linear-gradient(135deg,var(--gold),var(--gold-dark));color:#000;}
.btn-gold:hover{transform:translateY(-2px);box-shadow:0 4px 15px rgba(240,192,64,0.4);}
.btn-red{background:linear-gradient(135deg,var(--red),#a02020);color:#fff;}
.btn-red:hover{box-shadow:0 4px 15px rgba(224,64,64,0.4);}
.btn-blue{background:linear-gradient(135deg,var(--blue),#2060c0);color:#fff;}
.btn-blue:hover{box-shadow:0 4px 15px rgba(64,128,240,0.4);}
.btn-green{background:linear-gradient(135deg,var(--green),#208040);color:#fff;}
.btn-green:hover{box-shadow:0 4px 15px rgba(64,192,96,0.4);}
.btn-purple{background:linear-gradient(135deg,var(--purple),#7020a0);color:#fff;}
.btn-sm{padding:6px 14px;font-size:0.85em;}
.btn-full{width:100%;}
.btn:disabled{opacity:0.5;cursor:not-allowed;transform:none!important;box-shadow:none!important;}

/* MAIN LAYOUT */
#main-game{display:none;grid-template-columns:220px 1fr 260px;grid-template-rows:auto 1fr;gap:10px;min-height:calc(100vh - 20px);}
#header{grid-column:1/-1;background:var(--bg-panel);border:1px solid var(--border);border-radius:8px;padding:10px 20px;display:flex;align-items:center;justify-content:space-between;}
#header .game-title{font-family:'Cinzel',serif;color:var(--gold);font-size:1.3em;}
#header .player-info{display:flex;align-items:center;gap:15px;}
#header .player-name{color:var(--text-bright);font-weight:600;}
#header .player-level{color:var(--gold);font-size:0.9em;}
.header-bars{display:flex;gap:15px;align-items:center;}
.mini-bar{width:120px;height:14px;background:var(--bg-dark);border-radius:7px;overflow:hidden;position:relative;}
.mini-bar .fill{height:100%;border-radius:7px;transition:width 0.3s;}
.mini-bar .label{position:absolute;top:0;left:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;font-size:0.65em;font-weight:700;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,0.8);}
.hp-fill{background:linear-gradient(90deg,#c02020,#e04040);}
.cp-fill{background:linear-gradient(90deg,#2060c0,#4080f0);}
.exp-fill{background:linear-gradient(90deg,#208040,#40c060);}

/* SIDEBAR */
#sidebar{background:var(--bg-panel);border:1px solid var(--border);border-radius:8px;padding:10px;overflow-y:auto;max-height:calc(100vh - 80px);}
.nav-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:6px;cursor:pointer;transition:all 0.2s;color:var(--text-dim);font-size:0.95em;margin-bottom:2px;}
.nav-item:hover{background:var(--bg-hover);color:var(--text);}
.nav-item.active{background:var(--bg-hover);color:var(--gold);border-left:3px solid var(--gold);}
.nav-item .icon{font-size:1.2em;width:24px;text-align:center;}
.nav-section{color:var(--text-dim);font-size:0.75em;text-transform:uppercase;letter-spacing:1px;padding:15px 12px 5px;font-weight:700;}

/* MAIN CONTENT */
#main-content{background:var(--bg-panel);border:1px solid var(--border);border-radius:8px;padding:20px;overflow-y:auto;max-height:calc(100vh - 80px);}
#right-panel{background:var(--bg-panel);border:1px solid var(--border);border-radius:8px;padding:15px;overflow-y:auto;max-height:calc(100vh - 80px);}

/* PANELS */
.panel{display:none;}
.panel.active{display:block;}
.panel-title{font-family:'Cinzel',serif;color:var(--gold);font-size:1.4em;margin-bottom:15px;padding-bottom:10px;border-bottom:1px solid var(--border);}

/* CHARACTER PANEL */
.char-header{display:flex;gap:20px;align-items:flex-start;margin-bottom:20px;}
.char-avatar{width:100px;height:100px;border-radius:10px;background:var(--bg-card);border:2px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:3em;}
.char-info h3{color:var(--text-bright);font-size:1.2em;}
.char-info .village{color:var(--gold);font-size:0.9em;}
.char-info .element{color:var(--cyan);font-size:0.85em;}
.char-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:15px 0;}
.stat-row{display:flex;justify-content:space-between;padding:6px 10px;background:var(--bg-card);border-radius:5px;font-size:0.9em;}
.stat-row .stat-name{color:var(--text-dim);}
.stat-row .stat-val{color:var(--text-bright);font-weight:600;}
.stat-row .stat-btn{background:var(--gold);color:#000;border:none;border-radius:3px;width:20px;height:20px;cursor:pointer;font-size:0.8em;font-weight:700;margin-left:5px;display:none;}
.stat-row.has-points .stat-btn{display:inline-flex;align-items:center;justify-content:center;}
.points-available{color:var(--gold);font-size:0.9em;margin:10px 0;}

/* COMBAT */
.combat-arena{display:flex;gap:20px;align-items:center;justify-content:center;min-height:200px;margin:20px 0;}
.combatant{text-align:center;padding:20px;background:var(--bg-card);border-radius:10px;border:1px solid var(--border);min-width:180px;}
.combatant .sprite{font-size:4em;margin-bottom:10px;}
.combatant .name{color:var(--text-bright);font-weight:700;margin-bottom:5px;}
.combatant .bar{width:150px;height:12px;background:var(--bg-dark);border-radius:6px;overflow:hidden;margin:4px auto;}
.combatant .bar .fill{height:100%;transition:width 0.5s;border-radius:6px;}
.combatant .bar-label{font-size:0.75em;color:var(--text-dim);}
.vs-text{font-family:'Cinzel',serif;font-size:2em;color:var(--red);text-shadow:0 0 20px rgba(224,64,64,0.5);}
.combat-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:15px 0;}
.combat-log{background:var(--bg-dark);border:1px solid var(--border);border-radius:8px;padding:12px;max-height:200px;overflow-y:auto;font-size:0.85em;line-height:1.6;}
.combat-log .log-entry{padding:2px 0;border-bottom:1px solid rgba(42,42,69,0.5);}
.log-damage{color:var(--red);}
.log-heal{color:var(--green);}
.log-info{color:var(--blue);}
.log-gold{color:var(--gold);}

/* AREAS */
.area-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;}
.area-card{background:var(--bg-card);border:1px solid var(--border);border-radius:8px;padding:15px;cursor:pointer;transition:all 0.2s;}
.area-card:hover{border-color:var(--gold);transform:translateY(-2px);}
.area-card.locked{opacity:0.5;cursor:not-allowed;}
.area-card .area-icon{font-size:2em;margin-bottom:8px;}
.area-card .area-name{color:var(--text-bright);font-weight:700;margin-bottom:4px;}
.area-card .area-level{color:var(--text-dim);font-size:0.85em;}
.area-card .area-desc{color:var(--text-dim);font-size:0.8em;margin-top:5px;}

/* INVENTORY */
.inv-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(80px,1fr));gap:8px;}
.inv-item{background:var(--bg-card);border:1px solid var(--border);border-radius:6px;padding:8px;text-align:center;cursor:pointer;transition:all 0.2s;position:relative;}
.inv-item:hover{border-color:var(--gold);}
.inv-item .item-icon{font-size:1.8em;margin-bottom:4px;}
.inv-item .item-name{font-size:0.7em;color:var(--text-dim);line-height:1.2;}
.inv-item .item-count{position:absolute;top:4px;right:4px;background:var(--bg-dark);color:var(--text-bright);font-size:0.7em;padding:1px 5px;border-radius:8px;font-weight:700;}
.inv-item.rarity-common{border-color:#555;}
.inv-item.rarity-uncommon{border-color:var(--green);}
.inv-item.rarity-rare{border-color:var(--blue);}
.inv-item.rarity-epic{border-color:var(--purple);}
.inv-item.rarity-legendary{border-color:var(--gold);box-shadow:0 0 10px rgba(240,192,64,0.2);}

/* EQUIPMENT */
.equip-slots{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:15px 0;}
.equip-slot{background:var(--bg-card);border:2px dashed var(--border);border-radius:8px;padding:15px;text-align:center;min-height:80px;display:flex;flex-direction:column;align-items:center;justify-content:center;}
.equip-slot.filled{border-style:solid;border-color:var(--gold);}
.equip-slot .slot-label{font-size:0.75em;color:var(--text-dim);margin-bottom:5px;}
.equip-slot .slot-icon{font-size:2em;}
.equip-slot .slot-item-name{font-size:0.8em;color:var(--text-bright);}

/* SHOP */
.shop-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;}
.shop-item{background:var(--bg-card);border:1px solid var(--border);border-radius:8px;padding:15px;text-align:center;transition:all 0.2s;}
.shop-item:hover{border-color:var(--gold);}
.shop-item .item-icon{font-size:2.5em;margin-bottom:8px;}
.shop-item .item-name{color:var(--text-bright);font-weight:600;margin-bottom:4px;}
.shop-item .item-price{color:var(--gold);font-size:0.9em;margin:5px 0;}
.shop-item .item-desc{color:var(--text-dim);font-size:0.75em;margin-bottom:8px;}

/* QUESTS */
.quest-list{display:flex;flex-direction:column;gap:10px;}
.quest-item{background:var(--bg-card);border:1px solid var(--border);border-radius:8px;padding:12px 15px;display:flex;align-items:center;gap:12px;}
.quest-item .quest-icon{font-size:1.5em;}
.quest-item .quest-info{flex:1;}
.quest-item .quest-name{color:var(--text-bright);font-weight:600;font-size:0.95em;}
.quest-item .quest-desc{color:var(--text-dim);font-size:0.8em;margin-top:2px;}
.quest-item .quest-progress{color:var(--gold);font-size:0.85em;margin-top:4px;}
.quest-item .quest-reward{color:var(--green);font-size:0.8em;}
.quest-item .quest-btn{margin-left:auto;}

/* MISSIONS */
.mission-card{background:var(--bg-card);border:1px solid var(--border);border-radius:8px;padding:15px;margin-bottom:10px;}
.mission-card .mission-title{color:var(--text-bright);font-weight:700;margin-bottom:5px;}
.mission-card .mission-desc{color:var(--text-dim);font-size:0.85em;margin-bottom:8px;}
.mission-card .mission-reward{color:var(--gold);font-size:0.85em;}

/* ARENA */
.arena-match{display:flex;gap:15px;align-items:center;justify-content:center;margin:20px 0;}
.arena-card{background:var(--bg-card);border:1px solid var(--border);border-radius:8px;padding:15px;text-align:center;min-width:150px;}
.arena-card .opp-name{color:var(--text-bright);font-weight:700;}
.arena-card .opp-level{color:var(--text-dim);font-size:0.85em;}
.arena-card .opp-rank{color:var(--gold);font-size:0.8em;}

/* TRAINING */
.training-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;}
.training-card{background:var(--bg-card);border:1px solid var(--border);border-radius:8px;padding:15px;text-align:center;cursor:pointer;transition:all 0.2s;}
.training-card:hover{border-color:var(--gold);}
.training-card.locked{opacity:0.5;cursor:not-allowed;}
.training-card .train-icon{font-size:2.5em;margin-bottom:8px;}
.training-card .train-name{color:var(--text-bright);font-weight:600;}
.training-card .train-desc{color:var(--text-dim);font-size:0.8em;margin-top:4px;}
.training-card .train-cost{color:var(--gold);font-size:0.85em;margin-top:8px;}

/* NOTIFICATIONS */
#notifications{position:fixed;top:10px;right:10px;z-index:1000;display:flex;flex-direction:column;gap:8px;max-width:350px;}
.notif{background:var(--bg-panel);border:1px solid var(--border);border-radius:8px;padding:12px 16px;animation:slideIn 0.3s ease;box-shadow:0 4px 20px rgba(0,0,0,0.5);}
.notif.success{border-left:3px solid var(--green);}
.notif.error{border-left:3px solid var(--red);}
.notif.info{border-left:3px solid var(--blue);}
.notif.reward{border-left:3px solid var(--gold);}
@keyframes slideIn{from{transform:translateX(100%);opacity:0;}to{transform:translateX(0);opacity:1;}}
@keyframes slideOut{from{transform:translateX(0);opacity:1;}to{transform:translateX(100%);opacity:0;}}

/* MODAL */
.modal-overlay{display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.7);z-index:999;align-items:center;justify-content:center;}
.modal-overlay.active{display:flex;}
.modal{background:var(--bg-panel);border:1px solid var(--border);border-radius:12px;padding:25px;max-width:500px;width:95%;max-height:80vh;overflow-y:auto;}
.modal h3{color:var(--gold);font-family:'Cinzel',serif;margin-bottom:15px;}
.modal-close{float:right;background:none;border:none;color:var(--text-dim);font-size:1.5em;cursor:pointer;}
.modal-close:hover{color:var(--text-bright);}

/* CHAT */
.chat-box{background:var(--bg-dark);border:1px solid var(--border);border-radius:8px;padding:10px;margin-top:15px;}
.chat-messages{max-height:150px;overflow-y:auto;margin-bottom:8px;font-size:0.85em;}
.chat-msg{padding:2px 0;}
.chat-msg .chat-name{color:var(--gold);font-weight:600;}
.chat-msg .chat-text{color:var(--text);}
.chat-input{display:flex;gap:5px;}
.chat-input input{flex:1;padding:6px 10px;background:var(--bg-card);border:1px solid var(--border);border-radius:4px;color:var(--text);font-size:0.85em;outline:none;}

/* LEVEL UP ANIMATION */
.level-up-anim{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:1001;text-align:center;pointer-events:none;}
.level-up-anim .text{font-family:'Cinzel',serif;font-size:3em;color:var(--gold);text-shadow:0 0 40px rgba(240,192,64,0.8);animation:lvlUp 2s ease forwards;}
@keyframes lvlUp{0%{opacity:0;transform:scale(0.5);}20%{opacity:1;transform:scale(1.2);}40%{transform:scale(1);}100%{opacity:0;transform:translateY(-50px);}}

/* RESPONSIVE */
@media(max-width:900px){
#main-game{grid-template-columns:1fr;}
#sidebar{display:none;}
#right-panel{display:none;}
}

/* JUTSU SELECT */
.jutsu-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;margin:10px 0;}
.jutsu-card{background:var(--bg-card);border:1px solid var(--border);border-radius:6px;padding:10px;text-align:center;cursor:pointer;transition:all 0.2s;}
.jutsu-card:hover{border-color:var(--gold);}
.jutsu-card .jutsu-icon{font-size:1.5em;margin-bottom:4px;}
.jutsu-card .jutsu-name{color:var(--text-bright);font-size:0.85em;font-weight:600;}
.jutsu-card .jutsu-cost{color:var(--cyan);font-size:0.75em;}
.jutsu-card .jutsu-dmg{color:var(--red);font-size:0.75em;}
.jutsu-card.disabled{opacity:0.4;cursor:not-allowed;}

/* BOSS */
.boss-hp-bar{width:100%;height:20px;background:var(--bg-dark);border-radius:10px;overflow:hidden;margin:10px 0;border:1px solid var(--border);}
.boss-hp-bar .fill{height:100%;background:linear-gradient(90deg,#800020,#e04040);transition:width 0.5s;border-radius:10px;}

/* TABS */
.tab-bar{display:flex;gap:5px;margin-bottom:15px;border-bottom:1px solid var(--border);padding-bottom:5px;}
.tab-btn{padding:8px 16px;background:none;border:none;color:var(--text-dim);cursor:pointer;font-size:0.9em;border-bottom:2px solid transparent;transition:all 0.2s;}
.tab-btn:hover{color:var(--text);}
.tab-btn.active{color:var(--gold);border-bottom-color:var(--gold);}

/* DAMAGE NUMBER */
.damage-number{position:absolute;font-weight:900;font-size:1.5em;pointer-events:none;animation:dmgFloat 1s ease forwards;z-index:100;}
@keyframes dmgFloat{0%{opacity:1;transform:translateY(0);}100%{opacity:0;transform:translateY(-60px);}}

/* RANK BADGE */
.rank-badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:0.75em;font-weight:700;}
.rank-bronze{background:#cd7f32;color:#000;}
.rank-silver{background:#c0c0c0;color:#000;}
.rank-gold{background:var(--gold);color:#000;}
.rank-platinum{background:#e5e4e2;color:#000;}
.rank-diamond{background:linear-gradient(135deg,#b9f2ff,#00bfff);color:#000;}

/* TOOLTIP */
.tooltip{position:relative;}
.tooltip:hover::after{content:attr(data-tip);position:absolute;bottom:100%;left:50%;transform:translateX(-50%);background:var(--bg-dark);border:1px solid var(--border);color:var(--text);padding:5px 10px;border-radius:4px;font-size:0.75em;white-space:nowrap;z-index:100;pointer-events:none;}

/* EXP BAR */
.exp-section{margin:10px 0;}
.exp-bar{width:100%;height:10px;background:var(--bg-dark);border-radius:5px;overflow:hidden;}
.exp-bar .fill{height:100%;background:linear-gradient(90deg,#208040,#40c060);transition:width 0.3s;border-radius:5px;}
.exp-text{font-size:0.75em;color:var(--text-dim);margin-top:2px;text-align:center;}

/* KIRIGAKURE SPECIAL */
.special-anim{animation:pulse 0.5s ease infinite;}
@keyframes pulse{0%,100%{box-shadow:0 0 5px var(--gold);}50%{box-shadow:0 0 25px var(--gold);}}

/* AUTO BATTLE */
.auto-indicator{display:inline-flex;align-items:center;gap:5px;color:var(--green);font-size:0.85em;}
.auto-indicator .dot{width:8px;height:8px;background:var(--green);border-radius:50%;animation:blink 1s infinite;}
@keyframes blink{0%,100%{opacity:1;}50%{opacity:0.3;}}

/* SAKURA HIDE */
.sakura{position:fixed;pointer-events:none;z-index:0;opacity:0.6;}
</style>
</head>
<body>

