// ============ UTILITY ============
function saveGame(){localStorage.setItem('ninjaSagaSave',JSON.stringify(game));}
function loadGame(){const s=localStorage.getItem('ninjaSagaSave');if(s){game=JSON.parse(s);return true;}return false;}
function notify(msg,type='info'){
const n=document.getElementById('notifications');
const d=document.createElement('div');
d.className='notif '+type;
d.innerHTML=msg;
n.appendChild(d);
setTimeout(()=>{d.style.animation='slideOut 0.3s ease forwards';setTimeout(()=>d.remove(),300);},3000);
}
function rand(min,max){return Math.floor(Math.random()*(max-min+1))+min;}
function clamp(v,min,max){return Math.max(min,Math.min(max,v));}
function getRank(lvl){let r=RANKS[0];for(const rk of RANKS)if(lvl>=rk.minLvl)r=rk;return r;}
function getElementBonus(atk,type){const e=ELEMENTS[game.element];if(e.strong===type)return Math.floor(atk*1.3);if(e.weak===type)return Math.floor(atk*0.7);return atk;}
function getEffectiveStats(){
const s={...game.stats};
for(const slot of ['weapon','armor','accessory']){
const eq=game.equipment[slot];
if(eq&&eq.stats){for(const[k,v]of Object.entries(eq.stats))s[k]=(s[k]||0)+v;}
}
return s;
}
function calcDamage(atk,def,type){
const base=Math.max(1,atk-def*0.5);
const variance=0.8+Math.random()*0.4;
return Math.floor(base*variance);
}
function getInvCount(){return game.inventory.reduce((a,i)=>a+i.count,0);}

// ============ ACCOUNT ============
function createAccount(){
const name=document.getElementById('login-name').value.trim();
if(!name){notify('Masukkan nama ninja!','error');return;}
const village=document.getElementById('login-village').value;
const element=document.getElementById('login-element').value;
const pass=document.getElementById('login-pass').value;

const key='ninjaSaga_'+name.toLowerCase();
const saved=localStorage.getItem(key);
if(saved){
const acc=JSON.parse(saved);
if(acc.password!==pass&&pass){notify('Password salah!','error');return;}
game.name=name;game.village=village;game.element=element;
if(!loadGame()){
// New game with this name
}
startGame();
}else{
localStorage.setItem(key,JSON.stringify({name,password:pass||'123'}));
notify('Akun berhasil dibuat! Selamat datang, '+name,'success');
startGame();
}
}
function logout(){
saveGame();
document.getElementById('login-screen').style.display='flex';
document.getElementById('main-game').style.display='none';
}

// ============ GAME START ============
function startGame(){
document.getElementById('login-screen').style.display='none';
document.getElementById('main-game').style.display='grid';
updateAllUI();
if(!game.dailyClaimed){
game.dailyClaimed=true;
game.gold+=50;
game.inventory.push({id:'daily_hp',name:'Daily HP Potion',icon:'❤️',price:0,type:'consumable',effect:{hp:100},count:1,rarity:'common'});
notify('🎁 Daily Bonus: +50 Gold & HP Potion!','reward');
saveGame();
}
// Add some chat messages
if(game.chatMessages.length===0){
game.chatMessages=[
{name:'Sasuke',text:'Siapa yang mau PvP?',time:'10:30'},
{name:'Naruto',text:'Aku siap! Datang saja!',time:'10:31'},
{name:'Sakura',text:'Jangan lupa bawa potion ya','time:'10:32'},
{name:'Kakashi',text:'Latihan dulu sebelum bertarung','time:'10:33'},
{name:'Itachi',text:'Genjutsu adalah segalanya','time:'10:34'}
];
}
}

