function allocStat(stat){
if(game.statPoints<=0)return;
game.stats[stat]++;
game.statPoints--;
if(stat==='maxHp'){game.maxHp+=5;game.hp=Math.min(game.hp+5,game.maxHp);}
if(stat==='maxCp'){game.maxCp+=2;game.cp=Math.min(game.cp+2,game.maxCp);}
saveGame();updateAllUI();
}

// ============ PANELS ============
function showPanel(panel){
document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));
document.getElementById('panel-'+panel).classList.add('active');
document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
event.target.closest('.nav-item')?.classList.add('active');
if(panel==='areas')updateAreas();
if(panel==='inventory')updateInventory();
if(panel==='shop')updateShop();
if(panel==='training')updateTraining();
if(panel==='jutsu')updateJutsuPanel();
if(panel==='quests')updateQuests();
if(panel==='missions')updateMissions();
if(panel==='arena')updateArena();
if(panel==='character')updateCharacter();
}

// ============ AREAS ============
function updateAreas(){
const grid=document.getElementById('area-grid');
let html='';
for(const area of AREAS){
const locked=game.level<area.level;
const visited=game.areasVisited.includes(area.id);
html+=`<div class="area-card ${locked?'locked':''}" onclick="${locked?'':'goToArea('+area.id+')'}">
<div class="area-icon">${area.icon}</div>
<div class="area-name">${area.name}</div>
<div class="area-level">${locked?'🔒 Lv.'+area.level:'⚔️ Lv.'+area.level+' Required'}</div>
<div class="area-desc">${area.desc}</div>
${visited?'<div style="color:var(--green);font-size:0.8em;margin-top:5px;">✅ Visited</div>':''}
${area.boss?'<div style="color:var(--red);font-size:0.8em;margin-top:5px;">💀 BOSS AREA</div>':''}
</div>`;
}
grid.innerHTML=html;
}

function goToArea(areaId){
const area=AREAS.find(a=>a.id===areaId);
if(!area||game.level<area.level)return;
if(!game.areasVisited.includes(areaId))game.areasVisited.push(areaId);
game.currentArea=area;
notify('🗺️ Masuk ke '+area.name,'info');
saveGame();
showPanel('combat');
document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
document.querySelectorAll('.nav-item')[3].classList.add('active');
updateAreas();
}

// ============ COMBAT ============
let combatState={active:false,enemy:null,turn:0,auto:false};

function startManualBattle(){
if(!game.currentArea){notify('Pilih area dulu!','error');return;}
startCombat(game.currentArea);
}

function startAutoBattle(){
if(game.autoBattle){
stopAutoBattle();
return;
}
if(!game.currentArea){
// Auto find best area
let bestArea=AREAS[0];
for(const a of AREAS){
if(game.level>=a.level&&a.xp>bestArea.xp)bestArea=a;
}
game.currentArea=bestArea;
}
game.autoBattle=true;
document.getElementById('auto-status').innerHTML='<div class="auto-indicator"><span class="dot"></span> Auto Battle Active - '+game.currentArea.name+'</div>';
notify('⚡ Auto Battle dimulai di '+game.currentArea.name,'info');
combatState.auto=true;
gameAutoBattle();
}

function stopAutoBattle(){
game.autoBattle=false;
if(game.autoBattleInterval)clearInterval(game.autoBattleInterval);
document.getElementById('auto-status').innerHTML='';
notify('⏹️ Auto Battle dihentikan','info');
}

function gameAutoBattle(){
if(!game.autoBattle)return;
if(!combatState.active){
startCombat(game.currentArea);
}
game.autoBattleInterval=setTimeout(()=>{
if(game.autoBattle)gameAutoBattle();
},3000);
}

function startCombat(area){
if(game.hp<=0){notify('HP habis! Beli potion dulu','error');return;}
if(game.cp<=0){notify('CP habis! Istirahat dulu','info');return;}

const isBoss=area.boss;
let enemy;
if(isBoss){
const bossIdx=Math.min(Math.floor((game.level-20)/10),BOSSES.length-1);
const boss=BOSSES[Math.max(0,bossIdx)];
enemy={name:boss.name,icon:boss.icon,hp:boss.hp,maxHp:boss.hp,atk:boss.atk,def:boss.def,xp:boss.xp,gold:boss.gold,level:boss.level,isBoss:true};
}else{
const monsterName=area.monsters[rand(0,area.monsters.length-1)];
const lvlMod=1+(game.level-area.level)*0.1;
enemy={
name:monsterName,icon:'👾',
hp:Math.floor(30*lvlMod),maxHp:Math.floor(30*lvlMod),
atk:Math.floor(8*lvlMod),def:Math.floor(3*lvlMod),
xp:Math.floor(area.xp*lvlMod),gold:Math.floor(area.gold*lvlMod),
level:area.level,isBoss:false
};
}

combatState={active:true,enemy,turn:0,auto:combatState.auto};
document.getElementById('combat-area').style.display='none';
document.getElementById('combat-active').style.display='block';
document.getElementById('combat-log').innerHTML='';
renderCombat();
combatLog('⚔️ Battle dimulai melawan <strong>'+enemy.name+'</strong>!','info');
}

function renderCombat(){
const arena=document.getElementById('combat-arena');
const e=combatState.enemy;
const hpPct=e.hp/e.maxHp*100;
const playerHpPct=game.hp/game.maxHp*100;
const playerCpPct=game.cp/game.maxCp*100;

arena.innerHTML=`
<div class="combatant">
<div class="sprite">${VILLAGES[game.village].icon}</div>
<div class="name">${game.name}</div>
<div class="bar"><div class="fill hp-fill" style="width:${playerHpPct}%"></div></div>
<div class="bar-label">HP: ${game.hp}/${game.maxHp}</div>
<div class="bar"><div class="fill cp-fill" style="width:${playerCpPct}%"></div></div>
<div class="bar-label">CP: ${game.cp}/${game.maxCp}</div>
</div>
<div class="vs-text">VS</div>
<div class="combatant ${e.isBoss?'special-anim':''}">
<div class="sprite">${e.icon}</div>
<div class="name">${e.name} ${e.isBoss?'💀':''}</div>
<div class="bar"><div class="fill hp-fill" style="width:${hpPct}%"></div></div>
<div class="bar-label">HP: ${e.hp}/${e.maxHp}</div>
</div>`;

// Actions
const actions=document.getElementById('combat-actions');
let html=`<button class="btn btn-red" onclick="combatAction('attack')">👊 Attack</button>`;
html+=`<button class="btn btn-blue" onclick="combatAction('defend')">🛡️ Defend</button>`;
html+=`<button class="btn btn-green" onclick="combatAction('potion_hp')">❤️ HP Potion</button>`;
html+=`<button class="btn btn-blue" onclick="combatAction('potion_cp')">💙 CP Potion</button>`;
html+=`<button class="btn btn-purple" onclick="showJutsuSelect()">🌀 Jutsu</button>`;
if(!combatState.auto)html+=`<button class="btn btn-sm btn-red" onclick="fleeCombat()">🏃 Flee</button>`;
actions.innerHTML=html;
}

function combatAction(action){
if(!combatState.active)return;
const e=combatState.enemy;
const es=getEffectiveStats();
let log='';

switch(action){
case 'attack':{
const dmg=calcDamage(es.taijutsu+es.str*0.5,e.def,'taijutsu');
e.hp=Math.max(0,e.hp-dmg);
log=`👊 Kamu menyerang ${e.name} sebesar <span class="log-damage">${dmg}</span> damage!`;
break;
}
case 'defend':{
const heal=Math.floor(game.maxHp*0.05);
game.hp=Math.min(game.maxHp,game.hp+heal);
log=`🛡️ Kamu bertahan! <span class="log-heal">+${heal} HP</span> restored.`;
break;
}
case 'potion_hp':{
const pot=game.inventory.find(i=>i.id==='hp_pot'&&i.count>0)||game.inventory.find(i=>i.id==='big_hp'&&i.count>0)||game.inventory.find(i=>i.effect&&i.effect.hp&&i.count>0);
if(pot){
pot.count--;
if(pot.count<=0){const idx=game.inventory.indexOf(pot);game.inventory.splice(idx,1);}
const heal=pot.effect.hp||50;
game.hp=Math.min(game.maxHp,game.hp+heal);
log=`❤️ Menggunakan Potion! <span class="log-heal">+${heal} HP</span>`;
}else{
log=`❌ Tidak ada HP Potion!`;
}
break;
}
case 'potion_cp':{
const pot=game.inventory.find(i=>i.id==='cp_pot'&&i.count>0)||game.inventory.find(i=>i.id==='big_cp'&&i.count>0)||game.inventory.find(i=>i.effect&&i.effect.cp&&i.count>0);
if(pot){
pot.count--;
if(pot.count<=0){const idx=game.inventory.indexOf(pot);game.inventory.splice(idx,1);}
const heal=pot.effect.cp||30;
game.cp=Math.min(game.maxCp,game.cp+heal);
log=`💙 Menggunakan Chakra Potion! <span class="log-heal">+${heal} CP</span>`;
}else{
log=`❌ Tidak ada CP Potion!`;
}
break;
}
}

combatLog(log);
renderCombat();

if(e.hp<=0){
combatVictory();
return;
}

// Enemy turn
setTimeout(()=>{
enemyTurn();
},500);
}

function showJutsuSelect(){
const es=getEffectiveStats();
let html='<button class="modal-close" onclick="closeModal()">✕</button><h3>🌀 Pilih Jutsu</h3><div class="jutsu-grid">';
for(const j of JUTSU){
if(!game.unlockedJutsu.includes(j.id))continue;
const canUse=game.cp>=j.cost;
html+=`<div class="jutsu-card ${canUse?'':'disabled'}" onclick="${canUse?`useJutsu('${j.id}')`:''}">
<div class="jutsu-icon">${j.icon}</div>
<div class="jutsu-name">${j.name}</div>
<div class="jutsu-cost">CP: ${j.cost}</div>
<div class="jutsu-dmg">${j.dmg>0?'DMG: '+j.dmg+'x':''}</div>
${j.heal?'<div style="color:var(--green);font-size:0.75em;">Heal: '+j.heal*100+'%</div>':''}
</div>`;
}
html+='</div>';
openModal(html);
}

function useJutsu(jutsuId){
if(!combatState.active)return;
const jutsu=JUTSU.find(j=>j.id===jutsuId);
if(!jutsu||game.cp<jutsu.cost){notify('CP tidak cukup!','error');closeModal();return;}

game.cp-=jutsu.cost;
const e=combatState.enemy;
const es=getEffectiveStats();
const logDiv=document.getElementById('combat-log');
let log='';

if(jutsu.dmg>0){
let baseDmg=es.ninjutsu*jutsu.dmg+es.int*0.5;
baseDmg=getElementBonus(baseDmg,jutsu.type);
const dmg=calcDamage(baseDmg,e.def,jutsu.type);
e.hp=Math.max(0,e.hp-dmg);
log=`🌀 <strong>${jutsu.name}!</strong> ${e.name} terkena <span class="log-damage">${dmg}</span> damage!`;
}
if(jutsu.heal){
const heal=Math.floor(game.maxHp*jutsu.heal);
game.hp=Math.min(game.maxHp,game.hp+heal);
log+=` 💚 <span class="log-heal">+${heal} HP</span> restored!`;
}

combatLog(log);
closeModal();
renderCombat();

if(e.hp<=0){combatVictory();return;}
setTimeout(()=>{enemyTurn();},500);
}

function enemyTurn(){
if(!combatState.active)return;
const e=combatState.enemy;
const es=getEffectiveStats();
const dmg=calcDamage(e.atk,es.def*0.5+es.vit*0.3,'physical');
game.hp=Math.max(0,game.hp-dmg);
combatLog(`💥 ${e.name} menyerang! <span class="log-damage">${dmg}</span> damage!`);
renderCombat();

if(game.hp<=0){
combatDefeat();
}
}

function combatVictory(){
const e=combatState.enemy;
combatLog(`🎉 <span class="log-gold">${e.name} dikalahkan!</span>`);
game.xp+=e.xp;
game.gold+=e.gold;
game.kills++;
game.battlesWon++;

// Drop chance
const area=game.currentArea;
if(Math.random()<area.dropChance){
const drops=['hp_pot','cp_pot','str_scroll','vit_scroll','big_hp','big_cp'];
const dropId=drops[rand(0,drops.length-1)];
const shopItem=SHOP_ITEMS.potion.concat(SHOP_ITEMS.weapon.concat(SHOP_ITEMS.armor.concat(SHOP_ITEMS.scroll))).find(i=>i.id===dropId);
if(shopItem){
const existing=game.inventory.find(i=>i.id===dropId);
if(existing){existing.count++;}
else{game.inventory.push({...shopItem,count:1,rarity:shopItem.rarity||'common'});}
game.itemsCollected++;
combatLog(`🎁 Mendapatkan <span class="log-gold">${shopItem.name}</span>!`);
}
}

// Quest progress
updateQuestProgress('kill');
updateQuestProgress('battleWin');
updateQuestProgress('train');

// Check level up
checkLevelUp();
saveGame();
updateAllUI();

setTimeout(()=>{
if(combatState.auto){
combatState.active=false;
startCombat(game.currentArea);
}else{
endCombat();
}
},1500);
