function combatDefeat(){
combatLog(`💀 <span class="log-damage">Kamu kalah!</span>`);
game.hp=Math.max(1,Math.floor(game.maxHp*0.2));
game.cp=Math.max(1,Math.floor(game.maxCp*0.2));
saveGame();
updateAllUI();
setTimeout(()=>{endCombat();},1500);
}

function endCombat(){
combatState.active=false;
document.getElementById('combat-area').style.display='block';
document.getElementById('combat-active').style.display='none';
if(!game.autoBattle)document.getElementById('auto-status').innerHTML='';
}

function fleeCombat(){
if(!combatState.active)return;
combatLog('🏃 Kamu kabur dari pertempuran!');
saveGame();
setTimeout(()=>{endCombat();},500);
}

function combatLog(msg){
const log=document.getElementById('combat-log');
log.innerHTML+=`<div class="log-entry">${msg}</div>`;
log.scrollTop=log.scrollHeight;
}

function checkLevelUp(){
while(game.xp>=game.xpNeeded){
game.xp-=game.xpNeeded;
game.level++;
game.statPoints+=3;
game.maxHp+=10;
game.maxCp+=5;
game.hp=game.maxHp;
game.cp=game.maxCp;
game.xpNeeded=Math.floor(100*Math.pow(1.3,game.level-1));

// Check jutsu unlocks
for(const j of JUTSU){
if(j.unlockLvl<=game.level&&!game.unlockedJutsu.includes(j.id)){
game.unlockedJutsu.push(j.id);
notify('🌀 Jutsu baru: '+j.name+'!', 'reward');
}
}

notify('🎉 Level Up! Sekarang Level '+game.level+'! +3 Stat Points','reward');

// Show level up animation
const div=document.createElement('div');
div.className='level-up-anim';
div.innerHTML='<div class="text">⬆️ LEVEL '+game.level+'!</div>';
document.body.appendChild(div);
setTimeout(()=>div.remove(),2500);

// Update quests
updateQuestProgress('level');
}
}

function updateQuestProgress(type){
for(const cat of ['daily','main','side']){
for(const q of game.quests[cat]){
if(q.completed)continue;
const questData=findQuestData(q.id);
if(!questData)continue;
if(questData.type===type){
q.progress++;
if(q.progress>=questData.target){
q.completed=true;
game.xp+=questData.reward.xp;
game.gold+=questData.reward.gold;
notify('✅ Quest selesai: '+questData.name+' (+'+questData.reward.xp+' XP, +'+questData.reward.gold+' Gold)','reward');
checkLevelUp();
}
}
}
}
}

