function useItem(itemId){
const item=game.inventory.find(i=>i.id===itemId);
if(!item)return;
if(item.type==='consumable'){
if(item.effect.hp){
game.hp=Math.min(game.maxHp,game.hp+item.effect.hp);
notify('❤️ HP +'+item.effect.hp,'success');
}
if(item.effect.cp){
game.cp=Math.min(game.maxCp,game.cp+item.effect.cp);
notify('💙 CP +'+item.effect.cp,'success');
}
if(item.effect.revive){
game.hp=game.maxHp;
game.cp=game.maxCp;
notify('💎 Full Restore!','success');
}
item.count--;
if(item.count<=0){const idx=game.inventory.indexOf(item);game.inventory.splice(idx,1);}
saveGame();updateAllUI();
}else if(item.type==='scroll'){
if(item.effect.str){game.stats.str+=item.effect.str;game.statPoints++;notify('📜 STR +'+item.effect.str,'success');}
if(item.effect.vit){game.stats.vit+=item.effect.vit;game.statPoints++;notify('📜 VIT +'+item.effect.vit,'success');}
if(item.effect.agi){game.stats.agi+=item.effect.agi;game.statPoints++;notify('📜 AGI +'+item.effect.agi,'success');}
if(item.effect.int){game.stats.int+=item.effect.int;game.statPoints++;notify('📜 INT +'+item.effect.int,'success');}
const idx=game.inventory.indexOf(item);
game.inventory.splice(idx,1);
saveGame();updateAllUI();
}else if(item.type==='weapon'||item.type==='armor'){
const slot=item.type==='weapon'?'weapon':'armor';
if(game.equipment[slot]){
// Unequip
game.inventory.push({...game.equipment[slot],count:1});
}
game.equipment[slot]=item;
const idx=game.inventory.indexOf(item);
game.inventory.splice(idx,1);
notify('🔧 '+item.name+' equipped!','success');
saveGame();updateAllUI();
}
}

