function doTraining(trainId){
const train=TRAINING.find(t=>t.id===trainId);
if(!train||game.gold<train.cost){notify('Gold tidak cukup!','error');return;}
if(game.level<train.unlockLvl){notify('Butuh level '+train.unlockLvl,'error');return;}
game.gold-=train.cost;
if(train.stat==='maxHp'){game.maxHp+=train.amount;game.hp=Math.min(game.hp+train.amount,game.maxHp);}
else if(train.stat==='maxCp'){game.maxCp+=train.amount;game.cp=Math.min(game.cp+train.amount,game.maxCp);}
else if(train.stat==='str'){game.stats.str+=train.amount;game.statPoints++;}
else if(train.stat==='vit'){game.stats.vit+=train.amount;game.statPoints++;}
else if(train.stat==='agi'){game.stats.agi+=train.amount;game.statPoints++;}
else if(train.stat==='int'){game.stats.int+=train.amount;game.statPoints++;}
else if(train.stat==='ninjutsu'){game.stats.ninjutsu+=train.amount;}
else if(train.stat==='taijutsu'){game.stats.taijutsu+=train.amount;}
else if(train.stat==='genjutsu'){game.stats.genjutsu+=train.amount;}
game.trains++;
updateQuestProgress('train');
notify('🧠 '+train.name+' selesai!','success');
saveGame();updateAllUI();
}

