function enterArena(){
if(game.hp<=0){notify('HP habis!','error');return;}
// Generate random opponent
const oppLevel=rand(Math.max(1,game.level-5),game.level+5);
const oppHp=Math.floor(80+oppLevel*12);
const oppAtk=Math.floor(10+oppLevel*3);
const oppDef=Math.floor(5+oppLevel*2);
const oppName=['Rogue Ninja','Akatsuki Member','Hidden Ninja','Chunin','Jonin','ANBU Agent'][rand(0,5)];
const oppIcon=['🥷','👤','💀','⚔️','🗡️','👹'][rand(0,5)];

const opponent={name:oppName,icon:oppIcon,hp:oppHp,maxHp:oppHp,atk:oppAtk,def:oppDef,xp:Math.floor(oppLevel*20),gold:Math.floor(oppLevel*10),level:oppLevel,isBoss:false};

// Arena combat (simplified)
const arenaContent=document.getElementById('arena-content');
arenaContent.innerHTML=`
<div style="text-align:center;padding:20px 0;">
<h3 style="color:var(--text-bright);margin-bottom:15px;">⚔️ PvP Battle!</h3>
<div class="arena-match">
<div class="arena-card">
<div style="font-size:2.5em;">${VILLAGES[game.village].icon}</div>
<div class="opp-name">${game.name}</div>
<div class="opp-level">Lv.${game.level}</div>
<div style="margin-top:5px;">HP: <span style="color:var(--red);" id="arena-player-hp">${game.hp}/${game.maxHp}</span></div>
</div>
<div class="vs-text">VS</div>
<div class="arena-card">
<div style="font-size:2.5em;">${oppIcon}</div>
<div class="opp-name">${oppName}</div>
<div class="opp-level">Lv.${oppLevel}</div>
<div style="margin-top:5px;">HP: <span style="color:var(--red);" id="arena-opp-hp">${opponent.hp}/${opponent.maxHp}</span></div>
</div>
</div>
<div class="combat-actions" style="margin-top:15px;">
<button class="btn btn-red" onclick="arenaAction('attack')">👊 Attack</button>
<button class="btn btn-blue" onclick="arenaAction('defend')">🛡️ Defend</button>
<button class="btn btn-green" onclick="arenaAction('potion_hp')">❤️ HP Potion</button>
<button class="btn btn-purple" onclick="showJutsuSelect()">🌀 Jutsu</button>
</div>
<div class="combat-log" id="arena-log" style="margin-top:10px;"></div>
</div>`;

window._arenaOpponent=opponent;
window._arenaLog=document.getElementById('arena-log');
}

function arenaAction(action){
const opp=window._arenaOpponent;
if(!opp)return;
const es=getEffectiveStats();
const log=window._arenaLog;

switch(action){
case 'attack':{
const dmg=calcDamage(es.taijutsu+es.str*0.5,opp.def,'taijutsu');
opp.hp=Math.max(0,opp.hp-dmg);
log.innerHTML+=`<div class="log-entry">👊 Kamu menyerang ${opp.name}! <span class="log-damage">${dmg}</span> damage!</div>`;
break;
}
case 'defend':{
const heal=Math.floor(game.maxHp*0.05);
game.hp=Math.min(game.maxHp,game.hp+heal);
log.innerHTML+=`<div class="log-entry">🛡️ Kamu bertahan! <span class="log-heal">+${heal} HP</span></div>`;
break;
}
case 'potion_hp':{
const pot=game.inventory.find(i=>i.id==='hp_pot'&&i.count>0)||game.inventory.find(i=>i.effect&&i.effect.hp&&i.count>0);
if(pot){
pot.count--;
if(pot.count<=0){const idx=game.inventory.indexOf(pot);game.inventory.splice(idx,1);}
const heal=pot.effect.hp||50;
game.hp=Math.min(game.maxHp,game.hp+heal);
log.innerHTML+=`<div class="log-entry">❤️ HP +${heal}</div>`;
}else{
log.innerHTML+=`<div class="log-entry">❌ Tidak ada potion!</div>`;
}
break;
}
}

document.getElementById('arena-opp-hp').textContent=opp.hp+'/'+opp.maxHp;
document.getElementById('arena-player-hp').textContent=game.hp+'/'+game.maxHp;

if(opp.hp<=0){
log.innerHTML+=`<div class="log-entry" style="color:var(--gold);">🎉 <strong>${opp.name} dikalahkan!</strong></div>`;
game.arena.wins++;
game.arena.points+=20;
game.xp+=opp.xp;
game.gold+=opp.gold;
game.battlesWon++;
updateQuestProgress('pvpWin');
checkLevelUp();
saveGame();updateAllUI();
setTimeout(()=>{
document.getElementById('arena-content').innerHTML=`
<div style="text-align:center;padding:30px 0;">
<div style="font-size:3em;margin-bottom:10px;">🏆</div>
<h3 style="color:var(--gold);">Victory!</h3>
<p style="color:var(--text-dim);margin:10px 0;">+${opp.xp} XP, +${opp.gold} Gold, +20 Arena Points</p>
<button class="btn btn-gold" onclick="enterArena()">⚔️ Battle Lagi</button>
<button class="btn btn-blue" style="margin-left:10px;" onclick="showPanel('home')">🏠 Home</button>
</div>`;
},1500);
return;
}

// Opponent turn
setTimeout(()=>{
const dmg=calcDamage(opp.atk,es.def*0.5+es.vit*0.3,'physical');
game.hp=Math.max(0,game.hp-dmg);
log.innerHTML+=`<div class="log-entry">💥 ${opp.name} menyerang! <span class="log-damage">${dmg}</span> damage!</div>`;
document.getElementById('arena-player-hp').textContent=game.hp+'/'+game.maxHp;

if(game.hp<=0){
log.innerHTML+=`<div class="log-entry" style="color:var(--red);">💀 <strong>Kamu kalah!</strong></div>`;
game.arena.losses++;
game.arena.points=Math.max(0,game.arena.points-10);
saveGame();updateAllUI();
setTimeout(()=>{
document.getElementById('arena-content').innerHTML=`
<div style="text-align:center;padding:30px 0;">
<div style="font-size:3em;margin-bottom:10px;">💀</div>
<h3 style="color:var(--red);">Defeat!</h3>
<p style="color:var(--text-dim);margin:10px 0;">-10 Arena Points</p>
<button class="btn btn-red" onclick="enterArena()">⚔️ Retry</button>
<button class="btn btn-blue" style="margin-left:10px;" onclick="showPanel('home')">🏠 Home</button>
</div>`;
},1500);
}
},500);
}

