    if(this.type==='coin')return true;
    if(this.type==='powerup')return true;
    if(this.type==='overhead'&&player.slideTimer>0)return false;
    if(this.type==='train'&&player.jumpY>80)return false;
    return true;
  }
}

// Particles
class Particle{
  constructor(x,y,vx,vy,life,color){Object.assign(this,{x,y,vx,vy,life,maxLife:life,color})}
  update(dt){this.x+=this.vx*dt;this.y+=this.vy*dt;this.life-=dt}
  draw(){
    const a=this.life/this.maxLife;
    ctx.globalAlpha=a;ctx.fillStyle=this.color;
    ctx.beginPath();ctx.arc(this.x,this.y,3*a,0,Math.PI*2);ctx.fill();
    ctx.globalAlpha=1;
  }
}

function spawnParticles(x,y,count,color){
  for(let i=0;i<count;i++)game.particles.push(new Particle(x,y,(Math.random()-0.5)*200,(Math.random()-0.5)*200,0.5+Math.random()*0.5,color));
}

// Spawning
function updateSpawner(dt){
  game.spawnTimer-=dt;
  if(game.spawnTimer<=0){
    game.spawnTimer=0.8+Math.random()*0.6;
    const lane=Math.floor(Math.random()*3)-1;
    const r=Math.random();
    if(r<0.4)game.entities.push(new Entity('barrier',lane,0));
    else if(r<0.6)game.entities.push(new Entity('train',lane,0));
    else if(r<0.75)game.entities.push(new Entity('overhead',lane,0));
    else{
      const type=Math.random()<0.5?'coin':'powerup';
      const sub=Math.random()<0.5?'magnet':'jump';
      if(type==='coin'){
        for(let i=0;i<5;i++)game.entities.push(new Entity('coin',lane,0.1*i));
      }else{
        const pu=new Entity('powerup',lane,0);
        pu.sub=['magnet','jump','shield','hover'][Math.floor(Math.random()*4)];
        game.entities.push(pu);
      }
    }
  }
}

// Update
function update(dt){
  if(game.state!=='PLAYING')return;
  game.speed+=dt*0.000005;
  game.score+=dt*10;
  player.anim+=dt;
  player.z=0.9;
  player.targetLane+=(player.lane-player.targetLane)*Math.min(1,dt*12);
  player.lane=Math.round(player.targetLane);
  if(player.jumpVel!==0){player.jumpY+=player.jumpVel*dt*60;player.jumpVel+=0.6*dt*60;if(player.jumpY>=0){player.jumpY=0;player.jumpVel=0;player.state='run'}}
  if(player.slideTimer>0){player.slideTimer-=dt;if(player.slideTimer<=0)player.state='run'}
  if(player.invincible>0)player.invincible-=dt;
  if(player.stumbleTimer>0){player.stumbleTimer-=dt;if(player.stumbleTimer<=0)player.state='run'}

  updateSpawner(dt);
  game.entities.forEach(e=>e.update(dt));
  game.entities=game.entities.filter(e=>e.active);

  for(let e of game.entities){
    if(e.collides()){
      if(e.type==='coin'){
        game.coins++;e.active=false;playCoin();
        spawnParticles(W/2+e.lane*laneW*0.9,playerY,8,'#ffdd00');
      }else if(e.type==='powerup'){
        game.powerups[e.sub]=5;e.active=false;playPowerup();
        spawnParticles(W/2+e.lane*laneW*0.9,playerY,12,'#00ffcc');
      }else{
        if(player.invincible>0||game.powerups.shield>0){player.invincible=0;game.powerups.shield=0;spawnParticles(W/2,playerY,15,'#3366ff')}
        else{
          player.state='stumble';player.stumbleTimer=1.5;
          playCrash();spawnParticles(W/2,playerY,20,'#ff4444');
          setTimeout(()=>{game.state='GAMEOVER';document.getElementById('finalScore').textContent=Math.floor(game.score);document.getElementById('finalCoins').textContent=game.coins;document.getElementById('hud').classList.add('hidden');document.getElementById('gameOver').classList.remove('hidden');stopBGM()},1500);
        }
      }
    }
  }

  game.particles.forEach(p=>p.update(dt));
  game.particles=game.particles.filter(p=>p.life>0);

  for(let k in game.powerups){if(game.powerups[k]>0)game.powerups[k]-=dt}
  if(game.powerups.magnet<0)game.powerups.magnet=0;
  if(game.powerups.jump<0)game.powerups.jump=0;
  if(game.powerups.shield<0)game.powerups.shield=0;
  if(game.powerups.hover<0)game.powerups.hover=0;

  document.getElementById('scoreVal').textContent=Math.floor(game.score);
  document.getElementById('coinCount').textContent=game.coins;
  updatePowerupUI();
}

function updatePowerupUI(){
  const bar=document.getElementById('powerupBar');
  bar.innerHTML='';
  const icons={magnet:'🧲',jump:'👟',shield:'🛡️',hover:'🛹'};
  for(let k in game.powerups){
    if(game.powerups[k]>0){
      const div=document.createElement('div');div.className='powerup-icon';div.textContent=icons[k];
      const pct=(game.powerups[k]/5)*100;
      div.style.setProperty('--pct',pct+'%');
      div.innerHTML+=`<div style="position:absolute;bottom:0;left:0;width:100%;height:${pct}%;background:rgba(255,255,255,0.4);transition:height 0.1s"></div>`;
      bar.appendChild(div);
    }
  }
}

// Draw
function draw(){
  ctx.clearRect(0,0,W,H);
  // Sky
  const skyGrad=ctx.createLinearGradient(0,0,0,horizonY);
  skyGrad.addColorStop(0,'#1a1a40');skyGrad.addColorStop(1,'#ff6b35');
  ctx.fillStyle=skyGrad;ctx.fillRect(0,0,W,horizonY);
  // City silhouette
  ctx.fillStyle='#0d0d20';
  for(let i=0;i<10;i++){const x=(i*W/10)+Math.sin(Date.now()*0.001+i)*10;ctx.fillRect(x,horizonY-50-Math.random()*40,40,50+Math.random()*40)}
  // Ground
  const groundGrad=ctx.createLinearGradient(0,horizonY,0,H);
  groundGrad.addColorStop(0,'#2a2a3a');groundGrad.addColorStop(1,'#1a1a2e');
  ctx.fillStyle=groundGrad;ctx.fillRect(0,horizonY,W,H-horizonY);
  // Tracks
  ctx.strokeStyle='#555';ctx.lineWidth=2;
  for(let l=-1;l<=1;l+=2){
    ctx.beginPath();ctx.moveTo(W/2+l*10,horizonY);ctx.lineTo(W/2+l*laneW*2.5,playerY+20);ctx.stroke();
    ctx.beginPath();ctx.moveTo(W/2+l*20,horizonY);ctx.lineTo(W/2+l*laneW*2.5+15,playerY+20);ctx.stroke();
  }
  // Sleepers
  const sleeperCount=15;
  for(let i=0;i<sleeperCount;i++){
    const t=i/sleeperCount;const y=horizonY+(playerY-horizonY)*t;
    const w=laneW*2.5*t;
    ctx.fillStyle=`rgba(100,80,60,${0.3+t*0.5})`;
    ctx.fillRect(W/2-w/2,y,2,4*t);
  }

  // Entities
  game.entities.sort((a,b)=>a.z-b.z);
  game.entities.forEach(e=>e.draw());

  // Player
  drawPlayer();

  // Particles
  game.particles.forEach(p=>p.draw());

  // Inspector/Dog on stumble
  if(player.state==='stumble'){
    ctx.save();ctx.translate(W/2-60,playerY-40);
    ctx.fillStyle='#333';ctx.fillRect(0,0,30,50);ctx.fillStyle='#ffcc00';ctx.beginPath();ctx.arc(15,10,12,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#222';ctx.beginPath();ctx.arc(15,10,8,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='10px sans-serif';ctx.fillText('🐕',25,30);
    ctx.restore();
  }
}

function drawPlayer(){
  const cx=W/2+player.lane*laneW*0.9;
  const cy=playerY-player.jumpY;
  const scale=1;
  ctx.save();ctx.translate(cx,cy);ctx.scale(scale,scale);

  const bounce=Math.sin(player.anim*15)*5;
  const lean=player.state==='jump'?-0.2:player.state==='slide'?0.4:Math.sin(player.anim*12)*0.1;
  ctx.rotate(lean);

  // Shadow
  ctx.fillStyle='rgba(0,0,0,0.3)';ctx.beginPath();ctx.ellipse(0,20,25,8,0,0,Math.PI*2);ctx.fill();

  // Legs
  const legSwing=Math.sin(player.anim*15)*15;
  ctx.strokeStyle='#222';ctx.lineWidth=8;ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(-8,0);ctx.lineTo(-8+legSwing,20);ctx.stroke();
  ctx.beginPath();ctx.moveTo(8,0);ctx.lineTo(8-legSwing,20);ctx.stroke();

  // Shoes
  ctx.fillStyle=game.powerups.hover>0?'#ff00ff':'#ff3333';
  ctx.beginPath();ctx.ellipse(-8+legSwing,22,8,4,0,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.ellipse(8-legSwing,22,8,4,0,0,Math.PI*2);ctx.fill();

  // Body
  ctx.fillStyle='#3366ff';ctx.strokeStyle='#fff';ctx.lineWidth=3;
  ctx.beginPath();ctx.roundRect(-15,-35+bounce,30,40,10);ctx.fill();ctx.stroke();
  // Hoodie strings
  ctx.strokeStyle='#fff';ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(-5,-30+bounce);ctx.lineTo(-5,-15+bounce);ctx.stroke();
  ctx.beginPath();ctx.moveTo(5,-30+bounce);ctx.lineTo(5,-15+bounce);ctx.stroke();

  // Arms
  const armSwing=Math.sin(player.anim*15)*20;
  ctx.strokeStyle='#3366ff';ctx.lineWidth=7;
  ctx.beginPath();ctx.moveTo(-15,-25+bounce);ctx.lineTo(-25+armSwing,-5+bounce);ctx.stroke();
  ctx.beginPath();ctx.moveTo(15,-25+bounce);ctx.lineTo(25-armSwing,-5+bounce);ctx.stroke();

  // Head
  ctx.fillStyle='#ffcc99';ctx.strokeStyle='#fff';ctx.lineWidth=3;
  ctx.beginPath();ctx.arc(0,-55+bounce,20,0,Math.PI*2);ctx.fill();ctx.stroke();
  // Face
  ctx.fillStyle='#222';ctx.beginPath();ctx.arc(-6,-58+bounce,3,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(6,-58+bounce,3,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(0,-50+bounce,5,0,Math.PI);ctx.stroke();
  // Hat
  ctx.fillStyle='#ffcc00';ctx.beginPath();ctx.arc(0,-65+bounce,22,Math.PI,0);ctx.fill();
  ctx.fillRect(-25,-65+bounce,50,5);

  // Hoverboard trail
  if(game.powerups.hover>0){
    ctx.strokeStyle='#ff00ff';ctx.lineWidth=4;ctx.globalAlpha=0.6;
    ctx.beginPath();ctx.moveTo(-10,20);ctx.lineTo(-30,30);ctx.stroke();
    ctx.beginPath();ctx.moveTo(10,20);ctx.lineTo(30,30);ctx.stroke();
    ctx.globalAlpha=1;
  }

  ctx.restore();
}

// Loop
let lastTime=0;
function loop(time){
  const dt=Math.min((time-lastTime)/1000,0.05);lastTime=time;
  update(dt);draw();
  requestAnimationFrame(loop);
}

// UI Events
document.getElementById('playBtn').addEventListener('click',()=>{
  audioCtx.resume();
  game.state='PLAYING';game.score=0;game.coins=0;game.speed=0.008;game.entities=[];game.particles=[];
  Object.keys(game.powerups).forEach(k=>game.powerups[k]=0);
  player.lane=0;player.targetLane=0;player.jumpY=0;player.jumpVel=0;player.state='run';player.stumbleTimer=0;player.invincible=0;
  document.getElementById('mainMenu').classList.add('hidden');
  document.getElementById('gameOver').classList.add('hidden');
  document.getElementById('hud').classList.remove('hidden');
  document.getElementById('powerupBar').classList.remove('hidden');
  startBGM();
});
document.getElementById('restartBtn').addEventListener('click',()=>document.getElementById('playBtn').click());
document.getElementById('pauseBtn').addEventListener('click',()=>{
  if(game.state==='PLAYING'){game.state='PAUSED';document.getElementById('pauseBtn').textContent='▶'}
  else if(game.state==='PAUSED'){game.state='PLAYING';document.getElementById('pauseBtn').textContent='⏸'}
});

requestAnimationFrame(loop);
</script>
</body>
</html>

