<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// ============================================================
// TEMPLE RUNNER 3D - Complete Game Implementation
// ============================================================

// --- Audio System ---
const AudioCtx = window.AudioContext || window.webkitAudioContext;
let audioCtx;
function initAudio() {
    if (!audioCtx) audioCtx = new AudioCtx();
}

function playSound(type) {
    if (!audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    const t = audioCtx.currentTime;

    switch(type) {
        case 'coin':
            osc.type = 'sine';
            osc.frequency.setValueAtTime(880, t);
            osc.frequency.exponentialRampToValueAtTime(1760, t + 0.1);
            gain.gain.setValueAtTime(0.15, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
            osc.start(t); osc.stop(t + 0.15);
            break;
        case 'jump':
            osc.type = 'sine';
            osc.frequency.setValueAtTime(300, t);
            osc.frequency.exponentialRampToValueAtTime(600, t + 0.15);
            gain.gain.setValueAtTime(0.12, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
            osc.start(t); osc.stop(t + 0.2);
            break;
        case 'slide':
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(200, t);
            osc.frequency.exponentialRampToValueAtTime(80, t + 0.2);
            gain.gain.setValueAtTime(0.08, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.25);
            osc.start(t); osc.stop(t + 0.25);
            break;
        case 'hit':
            osc.type = 'square';
            osc.frequency.setValueAtTime(150, t);
            osc.frequency.exponentialRampToValueAtTime(50, t + 0.3);
            gain.gain.setValueAtTime(0.2, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
            osc.start(t); osc.stop(t + 0.4);
            break;
        case 'powerup':
            osc.type = 'sine';
            osc.frequency.setValueAtTime(523, t);
            osc.frequency.setValueAtTime(659, t + 0.1);
            osc.frequency.setValueAtTime(784, t + 0.2);
            osc.frequency.setValueAtTime(1047, t + 0.3);
            gain.gain.setValueAtTime(0.15, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
            osc.start(t); osc.stop(t + 0.5);
            break;
        case 'switch':
            osc.type = 'sine';
            osc.frequency.setValueAtTime(440, t);
            osc.frequency.exponentialRampToValueAtTime(660, t + 0.08);
            gain.gain.setValueAtTime(0.1, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
            osc.start(t); osc.stop(t + 0.1);
            break;
        case 'corner':
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(220, t);
            osc.frequency.setValueAtTime(330, t + 0.1);
            osc.frequency.setValueAtTime(440, t + 0.2);
            gain.gain.setValueAtTime(0.12, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
            osc.start(t); osc.stop(t + 0.35);
            break;
    }
}

// --- Background Music ---
let bgMusicPlaying = false;
let bgMusicNodes = [];
function startBackgroundMusic() {
    if (!audioCtx || bgMusicPlaying) return;
    bgMusicPlaying = true;
    const bpm = 140;
    const beatLen = 60 / bpm;

    function playBeat() {
        if (!bgMusicPlaying) return;
        const now = audioCtx.currentTime;
        // Bass line
        const bass = audioCtx.createOscillator();
        const bassGain = audioCtx.createGain();
        bass.type = 'sine';
        bass.frequency.setValueAtTime(65, now);
        bassGain.gain.setValueAtTime(0.08, now);
        bassGain.gain.exponentialRampToValueAtTime(0.001, now + beatLen * 0.8);
        bass.connect(bassGain); bassGain.connect(audioCtx.destination);
        bass.start(now); bass.stop(now + beatLen);
        bgMusicNodes.push(bass);

        // Hi-hat
        const noise = audioCtx.createBufferSource();
        const noiseBuffer = audioCtx.createBuffer(1, audioCtx.sampleRate * 0.05, audioCtx.sampleRate);
        const data = noiseBuffer.getChannelData(0);
        for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * 0.3;
        noise.buffer = noiseBuffer;
        const noiseGain = audioCtx.createGain();
        noiseGain.gain.setValueAtTime(0.04, now + beatLen * 0.5);
        noiseGain.gain.exponentialRampToValueAtTime(0.001, now + beatLen * 0.6);
        noise.connect(noiseGain); noiseGain.connect(audioCtx.destination);
        noise.start(now + beatLen * 0.5); noise.stop(now + beatLen * 0.6);
        bgMusicNodes.push(noise);

        // Melody note
        const melody = audioCtx.createOscillator();
        const melodyGain = audioCtx.createGain();
        melody.type = 'triangle';
        const notes = [220, 261, 293, 329, 349, 392, 440, 392];
        const noteIdx = Math.floor(Math.random() * notes.length);
        melody.frequency.setValueAtTime(notes[noteIdx], now);
        melodyGain.gain.setValueAtTime(0.06, now);
        melodyGain.gain.exponentialRampToValueAtTime(0.001, now + beatLen * 0.6);
        melody.connect(melodyGain); melodyGain.connect(audioCtx.destination);
        melody.start(now); melody.stop(now + beatLen * 0.7);
        bgMusicNodes.push(melody);

        setTimeout(playBeat, beatLen * 1000);
    }
    playBeat();
}

function stopBackgroundMusic() {
    bgMusicPlaying = false;
    bgMusicNodes.forEach(n => { try { n.stop(); } catch(e) {} });
    bgMusicNodes = [];
}

// --- Game State ---
let gameState = 'menu'; // menu, playing, paused, gameover
let selectedChar = 0;
let score = 0;
let coinCount = 0;
let distance = 0;
let speed = 0.3;
let baseSpeed = 0.3;
let maxSpeed = 1.2;
let streak = 0;
let highScore = parseInt(localStorage.getItem('templeRunnerHighScore')) || 0;
let settings = { sound: true, music: true, particles: true };

// --- Three.js Setup ---
let scene, camera, renderer;
let player, playerMixer, playerActions = {};
let pathSegments = [];
let obstacles = [];
let coins = [];
let powerups = [];
let decorations = [];
let fireParticles = [];
let dustParticles = [];

const LANE_WIDTH = 3;
const PATH_LENGTH = 200;
const RENDER_DISTANCE = 120;
const SEGMENT_LENGTH = 10;

// Player state
let currentLane = 1; // 0=left, 1=center, 2=right
let targetLane = 1;
let isJumping = false;
let isSliding = false;
let jumpVelocity = 0;
let jumpTime = 0;
let slideTime = 0;
let playerY = 0;
let targetY = 0;
let playerX = 0;
let targetX = 0;
let isInvincible = false;
let shieldTimer = 0;
let magnetTimer = 0;
let speedBoostTimer = 0;
let invincibleVisual = null;

// Path generation
let pathDirection = 0; // 0=straight, 1=left turn, 2=right turn
let pathCornerAngle = 0;
let pathCornerProgress = 0;
let totalPathLength = 0;
let pathSegmentsGenerated = 0;
let nextSpawnZ = 0;

// Touch handling
let touchStartX = 0, touchStartY = 0;
let touchStartTime = 0;

// --- Initialization ---
function init() {
    scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x1a0a00, 0.012);

    camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 200);
    camera.position.set(0, 5, -8);
    camera.lookAt(0, 2, 10);

    renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.8;
    document.body.insertBefore(renderer.domElement, document.getElementById('ui-overlay'));

    // Lighting
    const ambientLight = new THREE.AmbientLight(0x404060, 0.4);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffeedd, 0.6);
    dirLight.position.set(5, 15, 10);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.set(1024, 1024);
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // Torch lights along path
    const torchLight1 = new THREE.PointLight(0xff6600, 1.5, 20);
    torchLight1.position.set(2, 3, 5);
    scene.add(torchLight1);
    const torchLight2 = new THREE.PointLight(0xff6600, 1.5, 20);
    torchLight2.position.set(-2, 3, 5);
    scene.add(torchLight2);

    // Create player
    createPlayer();

    // Generate initial path
    generatePath(30);

    // Event listeners
    window.addEventListener('resize', onWindowResize, false);
    document.addEventListener('keydown', onKeyDown, false);
    document.addEventListener('touchstart', onTouchStart, { passive: false });
    document.addEventListener('touchend', onTouchEnd, { passive: false });

    // Start render loop
    animate();
}

function createPlayer() {
    player = new THREE.Group();

    const charColors = [
        { body: 0x8B4513, skin: 0xDEB887, hat: 0x654321 },
        { body: 0x2F4F4F, skin: 0xDEB887, hat: 0x1a1a1a },
        { body: 4B0082, skin: 0xDEB887, hat: 4B0082 }
    ];

    const colors = charColors[selectedChar];

    // Body
    const bodyGeo = new THREE.BoxGeometry(0.8, 1.2, 0.5);
    const bodyMat = new THREE.MeshStandardMaterial({ color: colors.body, roughness: 0.7 });
    const body = new THREE.Mesh(bodyGeo, bodyMat);
    body.position.y = 1.4;
    body.castShadow = true;
    player.add(body);

    // Head
    const headGeo = new THREE.BoxGeometry(0.6, 0.6, 0.6);
    const headMat = new THREE.MeshStandardMaterial({ color: colors.skin, roughness: 0.8 });
    const head = new THREE.Mesh(headGeo, headMat);
    head.position.y = 2.3;
    head.castShadow = true;
    player.add(head);

    // Hat/Helmet
    const hatGeo = new THREE.BoxGeometry(0.7, 0.3, 0.7);
    const hatMat = new THREE.MeshStandardMaterial({ color: colors.hat, roughness: 0.6 });
    const hat = new THREE.Mesh(hatGeo, hatMat);
    hat.position.y = 2.7;
    hat.castShadow = true;
    player.add(hat);

    // Eyes
    const eyeGeo = new THREE.BoxGeometry(0.1, 0.1, 0.05);
    const eyeMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
    const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
    leftEye.position.set(-0.15, 2.35, 0.3);
    player.add(leftEye);
    const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
    rightEye.position.set(0.15, 2.35, 0.3);
    player.add(rightEye);

    // Arms
    const armGeo = new THREE.BoxGeometry(0.25, 0.9, 0.25);
    const armMat = new THREE.MeshStandardMaterial({ color: colors.body, roughness: 0.7 });
    const leftArm = new THREE.Mesh(armGeo, armMat);
    leftArm.position.set(-0.55, 1.4, 0);
    leftArm.castShadow = true;
    player.add(leftArm);
    const rightArm = new THREE.Mesh(armGeo, armMat);
    rightArm.position.set(0.55, 1.4, 0);
    rightArm.castShadow = true;
    player.add(rightArm);

    // Legs
    const legGeo = new THREE.BoxGeometry(0.3, 0.8, 0.3);
    const legMat = new THREE.MeshStandardMaterial({ color: 0x4a3728, roughness: 0.8 });
    const leftLeg = new THREE.Mesh(legGeo, legMat);
    leftLeg.position.set(-0.2, 0.4, 0);
    leftLeg.castShadow = true;
    player.add(leftLeg);
    const rightLeg = new THREE.Mesh(legGeo, legMat);
    rightLeg.position.set(0.2, 0.4, 0);
    rightLeg.castShadow = true;
    player.add(rightLeg);

    // Backpack
    const packGeo = new THREE.BoxGeometry(0.5, 0.6, 0.3);
    const packMat = new THREE.MeshStandardMaterial({ color: 0x8B6914, roughness: 0.8 });
    const pack = new THREE.Mesh(packGeo, packMat);
    pack.position.set(0, 1.5, -0.35);
    pack.castShadow = true;
    player.add(pack);

    player.position.set(0, 0, 0);
    scene.add(player);

    // Store references for animation
    player.userData = { leftArm, rightArm, leftLeg, rightLeg, body, head };
}

// --- Path Generation ---
function generatePath(count) {
    for (let i = 0; i < count; i++) {
        addPathSegment();
    }
}

function addPathSegment() {
    const z = nextSpawnZ;
    const segment = new THREE.Group();
    segment.userData = { z: z, type: 'path', obstacles: [], coins: [], powerups: [] };

    // Determine path direction
    if (z > 30 && Math.random() < 0.15) {
        const r = Math.random();
        if (r < 0.5) pathDirection = 1; // left turn
        else pathDirection = 2; // right turn
        pathCornerAngle = Math.PI / 6;
        pathCornerProgress = 0;
    } else {
        pathDirection = 0;
    }

    // Calculate offset for turns
    const offsetX = pathDirection === 1 ? -LANE_WIDTH : pathDirection === 2 ? LANE_WIDTH : 0;

    // Floor
    const floorGeo = new THREE.BoxGeometry(LANE_WIDTH * 3 + 2, 0.3, SEGMENT_LENGTH);
    const floorMat = new THREE.MeshStandardMaterial({
        color: 0x6B5B4F, roughness: 0.9, metalness: 0.1
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.position.set(offsetX, -0.15, z);
    floor.receiveShadow = true;
    segment.add(floor);

    // Floor tiles pattern
    for (let tx = -1; tx <= 1; tx++) {
        for (let tz = 0; tz < 2; tz++) {
            const tileGeo = new THREE.BoxGeometry(LANE_WIDTH - 0.1, 0.05, SEGMENT_LENGTH / 2 - 0.1);
            const tileColor = (tx + tz) % 2 === 0 ? 0x7B6B5F : 0x5B4B3F;
            const tileMat = new THREE.MeshStandardMaterial({ color: tileColor, roughness: 0.85 });
            const tile = new THREE.Mesh(tileGeo, tileMat);
            tile.position.set(offsetX + tx * LANE_WIDTH, 0.02, z - SEGMENT_LENGTH/4 + tz * SEGMENT_LENGTH/2);
            tile.receiveShadow = true;
            segment.add(tile);
        }
    }

    // Walls
    const wallGeo = new THREE.BoxGeometry(0.5, 5, SEGMENT_LENGTH);
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x5A4A3A, roughness: 0.9 });

    const leftWall = new THREE.Mesh(wallGeo, wallMat);
    leftWall.position.set(offsetX - LANE_WIDTH * 1.5 - 1, 2.5, z);
    leftWall.castShadow = true;
    leftWall.receiveShadow = true;
    segment.add(leftWall);

    const rightWall = new THREE.Mesh(wallGeo, wallMat);
    rightWall.position.set(offsetX + LANE_WIDTH * 1.5 + 1, 2.5, z);
    rightWall.castShadow = true;
    rightWall.receiveShadow = true;
    segment.add(rightWall);

    // Wall decorations (carvings)
    for (let d = 0; d < 2; d++) {
        const carvingGeo = new THREE.BoxGeometry(0.1, 1.5, 1.5);
        const carvingMat = new THREE.MeshStandardMaterial({ color: 0x4A3A2A, roughness: 0.8 });
        const carving = new THREE.Mesh(carvingGeo, carvingMat);
        carving.position.set(offsetX - LANE_WIDTH * 1.5 - 0.7, 2, z - 2 + d * 4);
        segment.add(carving);
        const carving2 = carving.clone();
        carving2.position.x = offsetX + LANE_WIDTH * 1.5 + 0.7;
        segment.add(carving2);
    }

    // Pillars
    if (Math.random() < 0.6) {
        const pillarGeo = new THREE.CylinderGeometry(0.3, 0.35, 5, 8);
        const pillarMat = new THREE.MeshStandardMaterial({ color: 0x7B6B5F, roughness: 0.7 });
        const pillarL = new THREE.Mesh(pillarGeo, pillarMat);
        pillarL.position.set(offsetX - LANE_WIDTH * 1.5 - 0.3, 2.5, z);
        pillarL.castShadow = true;
        segment.add(pillarL);
        const pillarR = pillarL.clone();
        pillarR.position.x = offsetX + LANE_WIDTH * 1.5 + 0.3;
        segment.add(pillarR);

        // Pillar capitals
        const capGeo = new THREE.BoxGeometry(1, 0.3, 1);
        const capMat = new THREE.MeshStandardMaterial({ color: 0x8B7B6F, roughness: 0.6 });
        const capL = new THREE.Mesh(capGeo, capMat);
        capL.position.set(offsetX - LANE_WIDTH * 1.5 - 0.3, 5.1, z);
        segment.add(capL);
        const capR = capL.clone();
        capR.position.x = offsetX + LANE_WIDTH * 1.5 + 0.3;
        segment.add(capR);
    }

    // Torch on pillars
    if (Math.random() < 0.5) {
        const torchGeo = new THREE.SphereGeometry(0.15, 6, 6);
        const torchMat = new THREE.MeshStandardMaterial({ color: 0xff6600, emissive: 0xff4400, emissiveIntensity: 2 });
        const torch = new THREE.Mesh(torchGeo, torchMat);
        torch.position.set(offsetX + LANE_WIDTH * 1.5 + 0.3, 4.8, z);
        segment.add(torch);

        const torchLight = new THREE.PointLight(0xff6600, 1, 12);
        torchLight.position.copy(torch.position);
        segment.add(torchLight);
    }

    // Ceiling beams
    if (Math.random() < 0.7) {
        const beamGeo = new THREE.BoxGeometry(LANE_WIDTH * 3 + 2, 0.3, 0.5);
        const beamMat = new THREE.MeshStandardMaterial({ color: 0x3A2A1A, roughness: 0.9 });
        const beam = new THREE.Mesh(beamGeo, beamMat);
        beam.position.set(offsetX, 5.5, z);
        segment.add(beam);
    }

    // Ceiling
    const ceilGeo = new THREE.BoxGeometry(LANE_WIDTH * 3 + 2, 0.2, SEGMENT_LENGTH);
    const ceilMat = new THREE.MeshStandardMaterial({ color: 0x2A1A0A, roughness: 0.95 });
    const ceil = new THREE.Mesh(ceilGeo, ceilMat);
    ceil.position.set(offsetX, 5.8, z);
    ceil.receiveShadow = true;
    segment.add(ceil);

    // Spawn obstacles
    if (z > 25) {
        spawnObstacles(segment, offsetX, z);
    }

    // Spawn coins
    if (z > 10) {
        spawnCoins(segment, offsetX, z);
    }

    // Spawn power-ups
    if (z > 40 && Math.random() < 0.05) {
        spawnPowerup(segment, offsetX, z);
    }

    scene.add(segment);
    pathSegments.push(segment);
    nextSpawnZ += SEGMENT_LENGTH;
    pathSegmentsGenerated++;
}

function spawnObstacles(segment, offsetX, z) {
    const lane = Math.floor(Math.random() * 3) - 1; // -1, 0, 1
    const obstacleType = Math.random();

    if (obstacleType < 0.3) {
        // Tall obstacle (must switch lane)
        const obsGeo = new THREE.BoxGeometry(2, 3, 1);
        const obsMat = new THREE.MeshStandardMaterial({ color: 0x8B0000, roughness: 0.6 });
        const obs = new THREE.Mesh(obsGeo, obsMat);
        obs.position.set(offsetX + lane * LANE_WIDTH, 1.5, z);
        obs.castShadow = true;
        segment.add(obs);

        // Warning stripes
        const stripeGeo = new THREE.BoxGeometry(2.1, 0.2, 1.1);
        const stripeMat = new THREE.MeshStandardMaterial({ color: 0xFFD700, emissive: 0x886600, emissiveIntensity: 0.3 });
        const stripe = new THREE.Mesh(stripeGeo, stripeMat);
        stripe.position.set(offsetX + lane * LANE_WIDTH, 2.5, z);
        segment.add(stripe);

        segment.userData.obstacles.push({
            type: 'tall', lane: lane, z: z, mesh: obs
        });
    } else if (obstacleType < 0.55) {
        // Low obstacle (must jump)
        const obsGeo = new THREE.BoxGeometry(2.5, 0.8, 1);
        const obsMat = new THREE.MeshStandardMaterial({ color: 0x654321, roughness: 0.8 });
        const obs = new THREE.Mesh(obsGeo, obsMat);
        obs.position.set(offsetX + lane * LANE_WIDTH, 0.4, z);
        obs.castShadow = true;
        segment.add(obs);

        // Fire on top
        const fireGeo = new THREE.SphereGeometry(0.3, 6, 6);
        const fireMat = new THREE.MeshStandardMaterial({ color: 0xff4400, emissive: 0xff2200, emissiveIntensity: 3 });
        const fire = new THREE.Mesh(fireGeo, fireMat);
        fire.position.set(offsetX + lane * LANE_WIDTH, 1.2, z);
        segment.add(fire);

        const fireLight = new THREE.PointLight(0xff4400, 2, 8);
        fireLight.position.copy(fire.position);
        segment.add(fireLight);

        segment.userData.obstacles.push({
            type: 'low', lane: lane, z: z, mesh: obs, fire: fire
        });
    } else if (obstacleType < 0.75) {
        // High obstacle (must slide)
        const obsGeo = new THREE.BoxGeometry(2.5, 0.6, 0.8);
        const obsMat = new THREE.MeshStandardMaterial({ color: 0x4A4A4A, roughness: 0.5, metalness: 0.5 });
        const obs = new THREE.Mesh(obsGeo, obsMat);
        obs.position.set(offsetX + lane * LANE_WIDTH, 2.2, z);
        obs.castShadow = true;
        segment.add(obs);

        // Chain decoration
        const chainGeo = new THREE.CylinderGeometry(0.05, 0.05, 1.5, 6);
        const chainMat = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.8 });
        const chainL = new THREE.Mesh(chainGeo, chainMat);
        chainL.position.set(offsetX + lane * LANE_WIDTH - 0.8, 2.8, z);
        segment.add(chainL);
        const chainR = chainL.clone();
        chainR.position.x = offsetX + lane * LANE_WIDTH + 0.8;
        segment.add(chainR);

        segment.userData.obstacles.push({
            type: 'high', lane: lane, z: z, mesh: obs
        });
    } else if (obstacleType < 0.9) {
        // Gap in path
        const gapGeo = new THREE.BoxGeometry(LANE_WIDTH, 0.5, SEGMENT_LENGTH * 0.6);
        const gapMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
        const gap = new THREE.Mesh(gapGeo, gapMat);
        gap.position.set(offsetX + lane * LANE_WIDTH, -0.3, z);
        segment.add(gap);

        // Edge markers
        const markerGeo = new THREE.BoxGeometry(0.2, 0.5, SEGMENT_LENGTH * 0.6);
        const markerMat = new THREE.MeshStandardMaterial({ color: 0xFF4400, emissive: 0x882200, emissiveIntensity: 0.5 });
        const markerL = new THREE.Mesh(markerGeo, markerMat);
        markerL.position.set(offsetX + lane * LANE_WIDTH - LANE_WIDTH/2, 0, z);
        segment.add(markerL);
        const markerR = markerL.clone();
        markerR.position.x = offsetX + lane * LANE_WIDTH + LANE_WIDTH/2;
        segment.add(markerR);

        segment.userData.obstacles.push({
            type: 'gap', lane: lane, z: z, mesh: gap
        });
    } else {
        // Double obstacle (two lanes blocked)
        const lane1 = Math.floor(Math.random() * 3) - 1;
        let lane2 = lane1;
        while (lane2 === lane1) lane2 = Math.floor(Math.random() * 3) - 1;

        [lane1, lane2].forEach(l => {
            const obsGeo = new THREE.BoxGeometry(2, 2.5, 1);
            const obsMat = new THREE.MeshStandardMaterial({ color: 0x8B0000, roughness: 0.6 });
            const obs = new THREE.Mesh(obsGeo, obsMat);
            obs.position.set(offsetX + l * LANE_WIDTH, 1.25, z);
            obs.castShadow = true;
            segment.add(obs);
            segment.userData.obstacles.push({
                type: 'tall', lane: l, z: z, mesh: obs
            });
        });
    }
}

function spawnCoins(segment, offsetX, z) {
    const lane = Math.floor(Math.random() * 3) - 1;
    const count = 3 + Math.floor(Math.random() * 5);

    for (let i = 0; i < count; i++) {
        const coinGeo = new THREE.CylinderGeometry(0.25, 0.25, 0.08, 12);
        const coinMat = new THREE.MeshStandardMaterial({
            color: 0xFFD700, emissive: 0xAA8800, emissiveIntensity: 0.5,
            roughness: 0.3, metalness: 0.8
        });
        const coin = new THREE.Mesh(coinGeo, coinMat);
        coin.rotation.x = Math.PI / 2;
        coin.position.set(offsetX + lane * LANE_WIDTH, 1.2, z - i * 1.5);
        coin.castShadow = true;
        segment.add(coin);

        segment.userData.coins.push({
            lane: lane, z: z - i * 1.5, mesh: coin, collected: false
        });
    }

    // Arc of coins
    if (Math.random() < 0.3) {
        for (let i = 0; i < 5; i++) {
            const coinGeo = new THREE.CylinderGeometry(0.25, 0.25, 0.08, 12);
            const coinMat = new THREE.MeshStandardMaterial({
                color: 0xFFD700, emissive: 0xAA8800, emissiveIntensity: 0.5,
                roughness: 0.3, metalness: 0.8
            });
            const coin = new THREE.Mesh(coinGeo, coinMat);
            coin.rotation.x = Math.PI / 2;
            const arcLane = Math.floor(Math.random() * 3) - 1;
            const arcY = 1.2 + Math.sin(i * 0.5) * 1.5;
            coin.position.set(offsetX + arcLane * LANE_WIDTH, arcY, z - i * 1.5);
            segment.add(coin);
            segment.userData.coins.push({
                lane: arcLane, z: z - i * 1.5, mesh: coin, collected: false
            });
        }
    }
}

function spawnPowerup(segment, offsetX, z) {
    const lane = Math.floor(Math.random() * 3) - 1;
    const types = ['shield', 'magnet', 'speed'];
    const type = types[Math.floor(Math.random() * types.length)];

    let color, emissive;
    switch(type) {
        case 'shield': color = 0x00BFFF; emissive = 0x0066FF; break;
        case 'magnet': color = 0xFF69B4; emissive = 0xFF1493; break;
        case 'speed': color = 0x00FF00; emissive = 0x00AA00; break;
    }

    const puGeo = new THREE.OctahedronGeometry(0.4, 0);
    const puMat = new THREE.MeshStandardMaterial({
        color: color, emissive: emissive, emissiveIntensity: 1,
        roughness: 0.2, metalness: 0.5, transparent: true, opacity: 0.8
    });
    const pu = new THREE.Mesh(puGeo, puMat);
    pu.position.set(offsetX + lane * LANE_WIDTH, 1.5, z);
    pu.castShadow = true;
    segment.add(pu);

    // Glow ring
    const ringGeo = new THREE.TorusGeometry(0.6, 0.05, 8, 16);
    const ringMat = new THREE.MeshStandardMaterial({ color: color, emissive: emissive, emissiveIntensity: 2 });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.position.copy(pu.position);
    segment.add(ring);

    segment.userData.powerups.push({
        lane: lane, z: z, type: type, mesh: pu, ring: ring
    });
}

// --- Input Handling ---
function onKeyDown(e) {
    if (gameState !== 'playing') return;

    switch(e.key) {
        case 'ArrowLeft':
        case 'a':
        case 'A':
            moveLeft();
            break;
        case 'ArrowRight':
        case 'd':
        case 'D':
            moveRight();
            break;
        case 'ArrowUp':
        case 'w':
        case 'W':
        case ' ':
            jump();
            break;
        case 'ArrowDown':
        case 's':
        case 'S':
            slide();
            break;
        case 'Escape':
        case 'p':
        case 'P':
            togglePause();
            break;
    }
}

function onTouchStart(e) {
    e.preventDefault();
    if (gameState !== 'playing') return;
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
    touchStartTime = Date.now();
}

function onTouchEnd(e) {
    e.preventDefault();
    if (gameState !== 'playing') return;

    const dx = e.changedTouches[0].clientX - touchStartX;
    const dy = e.changedTouches[0].clientY - touchStartY;
    const dt = Date.now() - touchStartTime;

    if (dt > 500) return;

    const absDx = Math.abs(dx);
    const absDy = Math.abs(dy);

    if (Math.max(absDx, absDy) < 30) return; // Too small

    if (absDx > absDy) {
        if (dx > 0) moveRight();
        else moveLeft();
    } else {
        if (dy < 0) jump();
        else slide();
    }
}

function moveLeft() {
    if (targetLane > 0) {
        targetLane--;
        playSound('switch');
    }
}

function moveRight() {
    if (targetLane < 2) {
        targetLane++;
        playSound('switch');
    }
}

function jump() {
    if (!isJumping && !isSliding) {
        isJumping = true;
        jumpVelocity = 0.25;
        jumpTime = 0;
        playSound('jump');
    }
}

function slide() {
    if (!isJumping && !isSliding) {
        isSliding = true;
        slideTime = 0;
        playSound('slide');
    }
}

// --- Game Logic ---
function startGame() {
    initAudio();
    gameState = 'playing';
    score = 0;
    coinCount = 0;
    distance = 0;
    speed = baseSpeed;
    streak = 0;
    currentLane = 1;
    targetLane = 1;
    playerX = 0;
    targetX = 0;
    isJumping = false;
    isSliding = false;
    jumpVelocity = 0;
    jumpTime = 0;
    slideTime = 0;
    playerY = 0;
    targetY = 0;
    isInvincible = false;
    shieldTimer = 0;
    magnetTimer = 0;
    speedBoostTimer = 0;

    // Clear old path
    pathSegments.forEach(s => scene.remove(s));
    pathSegments = [];
    nextSpawnZ = 0;
    pathSegmentsGenerated = 0;
    pathDirection = 0;

    // Reset player
    player.position.set(0, 0, 0);
    player.rotation.set(0, 0, 0);
    player.scale.set(1, 1, 1);

    // Regenerate initial path
    generatePath(30);

    // UI
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('gameover-screen').style.display = 'none';
    document.getElementById('pause-screen').style.display = 'none';
    document.getElementById('hud').style.display = 'block';
    document.getElementById('pause-btn').style.display = 'flex';
    document.getElementById('powerup-bar').innerHTML = '';
    document.getElementById('streak-display').style.display = 'none';

    if (settings.music) startBackgroundMusic();

    updateHUD();
}

function gameOver() {
    gameState = 'gameover';
    stopBackgroundMusic();

    if (score > highScore) {
        highScore = score;
        localStorage.setItem('templeRunnerHighScore', highScore);
    }

    document.getElementById('final-score').textContent = score;
    document.getElementById('final-coins').textContent = '🪙 ' + coinCount;

    if (score >= highScore && score > 0) {
        document.getElementById('high-score-text').textContent = '🏆 NEW HIGH SCORE! 🏆';
    } else {
        document.getElementById('high-score-text').textContent = 'Best: ' + highScore;
    }

    document.getElementById('gameover-screen').style.display = 'flex';
    document.getElementById('hud').style.display = 'none';
    document.getElementById('pause-btn').style.display = 'none';

    playSound('hit');
}

function togglePause() {
    if (gameState === 'playing') {
        gameState = 'paused';
        document.getElementById('pause-screen').style.display = 'flex';
        document.getElementById('pause-btn').style.display = 'none';
    } else if (gameState === 'paused') {
        gameState = 'playing';
        document.getElementById('pause-screen').style.display = 'none';
        document.getElementById('pause-btn').style.display = 'flex';
    }
}

function restartGame() {
    startGame();
}

function goToMenu() {
    gameState = 'menu';
    stopBackgroundMusic();
    document.getElementById('start-screen').style.display = 'flex';
    document.getElementById('gameover-screen').style.display = 'none';
    document.getElementById('pause-screen').style.display = 'none';
    document.getElementById('hud').style.display = 'none';
    document.getElementById('pause-btn').style.display = 'none';
}

