// --- Collision Detection ---
function checkCollisions() {
    const playerWorldZ = player.position.z;
    const playerWorldX = player.position.x;
    const playerWorldY = player.position.y;

    // Check each segment
    for (let seg of pathSegments) {
        const segZ = seg.userData.z;

        // Check obstacles
        for (let obs of seg.userData.obstacles) {
            const obsZ = segZ + obs.z;
            const obsLane = obs.lane;

            // Distance check
            const dz = Math.abs(playerWorldZ - obsZ);
            const dx = Math.abs(playerWorldX - obsLane * LANE_WIDTH);

            if (dz < 1.5 && dx < 1.2) {
                let collision = false;

                switch(obs.type) {
                    case 'tall':
                        collision = true;
                        break;
                    case 'low':
                        collision = !isJumping || playerWorldY < 1.0;
                        break;
                    case 'high':
                        collision = !isSliding || playerWorldY > 1.0;
                        break;
                    case 'gap':
                        collision = !isJumping || playerWorldY < 0.5;
                        break;
                }

                if (collision && !isInvincible) {
                    gameOver();
                    return;
                }
            }
        }

        // Check coins
        for (let coin of seg.userData.coins) {
            if (coin.collected) continue;
            const coinZ = segZ + coin.z;
            const coinLane = coin.lane;

            const dz = Math.abs(playerWorldZ - coinZ);
            const dx = Math.abs(playerWorldX - coinLane * LANE_WIDTH);
            const dy = Math.abs(playerWorldY - 1.2);

            let collectDist = 1.5;
            if (magnetTimer > 0) collectDist = 5;

            if (dz < collectDist && dx < 1.5 && dy < 2) {
                coin.collected = true;
                coinCount++;
                score += 10;
                streak++;
                playSound('coin');

                // Coin collection effect
                if (settings.particles) {
                    createCoinEffect(coin.mesh.position.clone());
                }

                if (streak > 0 && streak % 10 === 0) {
                    showCombo('x' + streak + ' STREAK!');
                }

                if (coin.mesh.parent) {
                    coin.mesh.parent.remove(coin.mesh);
                }
            }
        }

        // Check power-ups
        for (let pu of seg.userData.powerups) {
            const puZ = segZ + pu.z;
            const puLane = pu.lane;

            const dz = Math.abs(playerWorldZ - puZ);
            const dx = Math.abs(playerWorldX - puLane * LANE_WIDTH);
            const dy = Math.abs(playerWorldY - 1.5);

            if (dz < 1.5 && dx < 1.5 && dy < 2) {
                activatePowerup(pu.type);
                pu.lane = -999; // Mark as collected

                if (pu.mesh.parent) pu.mesh.parent.remove(pu.mesh);
                if (pu.ring && pu.ring.parent) pu.ring.parent.remove(pu.ring);
            }
        }
    }
}

function activatePowerup(type) {
    playSound('powerup');
    switch(type) {
        case 'shield':
            isInvincible = true;
            shieldTimer = 8;
            showCombo('🛡️ SHIELD!');
            break;
        case 'magnet':
            magnetTimer = 10;
            showCombo('🧲 MAGNET!');
            break;
        case 'speed':
            speedBoostTimer = 5;
            showCombo('⚡ SPEED BOOST!');
            break;
    }
    updatePowerupBar();
}

function updatePowerupBar() {
    const bar = document.getElementById('powerup-bar');
    bar.innerHTML = '';

    if (isInvincible && shieldTimer > 0) {
        bar.innerHTML += `<div class="powerup-indicator" style="border-color:#00BFFF;">🛡️<div class="timer-bar" style="width:${(shieldTimer/8)*100}%;background:#00BFFF;"></div></div>`;
    }
    if (magnetTimer > 0) {
        bar.innerHTML += `<div class="powerup-indicator" style="border-color:#FF69B4;">🧲<div class="timer-bar" style="width:${(magnetTimer/10)*100}%;background:#FF69B4;"></div></div>`;
    }
    if (speedBoostTimer > 0) {
        bar.innerHTML += `<div class="powerup-indicator" style="border-color:#00FF00;">⚡<div class="timer-bar" style="width:${(speedBoostTimer/5)*100}%;background:#00FF00;"></div></div>`;
    }
}

function showCombo(text) {
    const el = document.createElement('div');
    el.className = 'combo-text';
    el.textContent = text;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 1000);
}

function updateHUD() {
    document.getElementById('score').textContent = Math.floor(score);
    document.getElementById('coins').textContent = coinCount;

    if (streak > 5) {
        document.getElementById('streak-display').style.display = 'block';
        document.getElementById('streak-count').textContent = streak;
    } else {
        document.getElementById('streak-display').style.display = 'none';
    }
}

// --- Coin Effect ---
function createCoinEffect(position) {
    if (!settings.particles) return;
    const geo = new THREE.SphereGeometry(0.08, 4, 4);
    const mat = new THREE.MeshBasicMaterial({ color: 0xFFD700 });
    for (let i = 0; i < 5; i++) {
        const p = new THREE.Mesh(geo, mat);
        p.position.copy(position);
        p.userData.velocity = new THREE.Vector3(
            (Math.random() - 0.5) * 0.1,
            Math.random() * 0.1,
            (Math.random() - 0.5) * 0.1
        );
        p.userData.life = 0.5;
        scene.add(p);
        fireParticles.push(p);
    }
}

// --- Animation ---
let animTime = 0;
let lastTime = 0;

function animate(time = 0) {
    requestAnimationFrame(animate);

    const delta = Math.min((time - lastTime) / 1000, 0.05);
    lastTime = time;

    if (gameState === 'playing') {
        updateGame(delta);
    }

    // Always animate particles and decorations
    updateParticles(delta);
    updateDecorations(delta);

    renderer.render(scene, camera);
}

function updateGame(delta) {
    animTime += delta;

    // Increase speed over time
    const speedIncrease = 0.00005;
    speed = Math.min(baseSpeed + distance * speedIncrease, maxSpeed);

    if (speedBoostTimer > 0) {
        speedBoostTimer -= delta;
        speed = Math.min(speed * 1.5, maxSpeed * 1.3);
    }

    // Move player forward
    const moveAmount = speed * delta * 60;
    player.position.z += moveAmount;
    distance += moveAmount;
    score += moveAmount * 2;

    // Lane switching (smooth)
    targetX = (targetLane - 1) * LANE_WIDTH;
    playerX += (targetX - playerX) * 12 * delta;
    player.position.x = playerX;

    // Jump physics
    if (isJumping) {
        jumpTime += delta;
        playerY = jumpVelocity * 100 * delta - 0.5 * 15 * delta * delta;
        if (playerY <= 0) {
            playerY = 0;
            isJumping = false;
            jumpVelocity = 0;
        }
        player.position.y = playerY;
    }

    // Slide
    if (isSliding) {
        slideTime += delta;
        player.scale.y = 1 - (slideTime / 0.6) * 0.5;
        player.position.y = -0.3;
        if (slideTime >= 0.6) {
            isSliding = false;
            player.scale.y = 1;
            player.position.y = 0;
        }
    }

    // Running animation
    const runSpeed = 10;
    const { leftArm, rightArm, leftLeg, rightLeg } = player.userData;
    if (!isJumping && !isSliding) {
        leftArm.rotation.x = Math.sin(animTime * runSpeed) * 0.8;
        rightArm.rotation.x = -Math.sin(animTime * runSpeed) * 0.8;
        leftLeg.rotation.x = -Math.sin(animTime * runSpeed) * 0.6;
        rightLeg.rotation.x = Math.sin(animTime * runSpeed) * 0.6;
    } else if (isJumping) {
        leftArm.rotation.x = -0.5;
        rightArm.rotation.x = -0.5;
        leftLeg.rotation.x = 0.3;
        rightLeg.rotation.x = -0.3;
    }

    // Camera follow
    const camTargetX = player.position.x * 0.3;
    const camTargetY = 4 + player.position.y * 0.3;
    camera.position.x += (camTargetX - camera.position.x) * 5 * delta;
    camera.position.y += (camTargetY - camera.position.y) * 5 * delta;
    camera.position.z = player.position.z - 8;
    camera.lookAt(player.position.x * 0.5, 2 + player.position.y * 0.2, player.position.z + 15);

    // Generate new path segments
    while (nextSpawnZ < player.position.z + RENDER_DISTANCE) {
        addPathSegment();
    }

    // Remove old segments
    while (pathSegments.length > 0 && pathSegments[0].userData.z < player.position.z - 30) {
        const seg = pathSegments.shift();
        scene.remove(seg);
    }

    // Check collisions
    checkCollisions();

    // Update timers
    if (shieldTimer > 0) {
        shieldTimer -= delta;
        if (shieldTimer <= 0) {
            isInvincible = false;
            if (invincibleVisual) {
                scene.remove(invincibleVisual);
                invincibleVisual = null;
            }
        }
    }
    if (magnetTimer > 0) magnetTimer -= delta;
    if (speedBoostTimer > 0) speedBoostTimer -= delta;

    // Shield visual
    if (isInvincible && !invincibleVisual) {
        const shieldGeo = new THREE.SphereGeometry(1.2, 16, 16);
        const shieldMat = new THREE.MeshStandardMaterial({
            color: 0x00BFFF, transparent: true, opacity: 0.2,
            emissive: 0x0066FF, emissiveIntensity: 0.5
        });
        invincibleVisual = new THREE.Mesh(shieldGeo, shieldMat);
        invincibleVisual.position.copy(player.position);
        invincibleVisual.position.y += 1.5;
        scene.add(invincibleVisual);
    }

    // Magnet effect - attract nearby coins
    if (magnetTimer > 0) {
        for (let seg of pathSegments) {
            for (let coin of seg.userData.coins) {
                if (coin.collected) continue;
                const coinZ = seg.userData.z + coin.z;
                const coinX = coin.lane * LANE_WIDTH;
                const dx = player.position.x - coinX;
                const dz = player.position.z - coinZ;
                const dist = Math.sqrt(dx * dx + dz * dz);
                if (dist < 5 && dist > 0.5) {
                    coin.mesh.position.x += dx * 0.05;
                    coin.mesh.position.z += dz * 0.05;
                    coin.mesh.position.y += (player.position.y + 1.5 - coin.mesh.position.y) * 0.05;
                }
            }
        }
    }

    // Update HUD
    updateHUD();
    if (shieldTimer > 0 || magnetTimer > 0 || speedBoostTimer > 0) {
        updatePowerupBar();
    }
}

function updateParticles(delta) {
    // Dust particles behind player
    if (settings.particles && !isJumping && !isSliding && Math.random() < 0.3) {
        const geo = new THREE.SphereGeometry(0.05, 4, 4);
        const mat = new THREE.MeshBasicMaterial({ color: 0x8B7355, transparent: true, opacity: 0.5 });
        const p = new THREE.Mesh(geo, mat);
        p.position.set(
            player.position.x + (Math.random() - 0.5) * 0.5,
            0.1,
            player.position.z - 0.5
        );
        p.userData.velocity = new THREE.Vector3(
            (Math.random() - 0.5) * 0.05,
            Math.random() * 0.02,
            -0.05 - Math.random() * 0.05
        );
        p.userData.life = 0.5;
        scene.add(p);
        dustParticles.push(p);
    }

    // Update all particles
    const allParticles = [...fireParticles, ...dustParticles];
    for (let i = allParticles.length - 1; i >= 0; i--) {
        const p = allParticles[i];
        p.userData.life -= delta;
        if (p.userData.life <= 0) {
            scene.remove(p);
            const idx = fireParticles.indexOf(p);
            if (idx >= 0) fireParticles.splice(idx, 1);
            const idx2 = dustParticles.indexOf(p);
            if (idx2 >= 0) dustParticles.splice(idx2, 1);
            continue;
        }
        p.position.add(p.userData.velocity);
        p.material.opacity = p.userData.life;
        p.scale.setScalar(p.userData.life);
    }
}

function updateDecorations(delta) {
    // Animate coins rotation
    for (let seg of pathSegments) {
        for (let coin of seg.userData.coins) {
            if (coin.mesh && coin.mesh.parent) {
                coin.mesh.rotation.z += delta * 3;
                coin.mesh.position.y = 1.2 + Math.sin(animTime * 2 + coin.z) * 0.15;
            }
        }
        for (let pu of seg.userData.powerups) {
            if (pu.mesh && pu.mesh.parent) {
                pu.mesh.rotation.y += delta * 2;
                pu.mesh.rotation.x += delta;
                pu.mesh.position.y = 1.5 + Math.sin(animTime * 3) * 0.3;
            }
            if (pu.ring && pu.ring.parent) {
                pu.ring.rotation.x = Math.sin(animTime * 2) * 0.5;
                pu.ring.rotation.z = Math.cos(animTime * 2) * 0.5;
            }
        }
        // Animate fire obstacles
        for (let obs of seg.userData.obstacles) {
            if (obs.fire && obs.fire.parent) {
                obs.fire.scale.setScalar(0.8 + Math.sin(animTime * 8) * 0.3);
            }
        }
    }
}

function onWindowResize() {
