  { id: 'auto1', name: '자동 급식기', icon: '🤖', desc: '자동으로 먹이 주기 시작', cost: 500, costType: 'carrots', effect: () => { state.autoFeed = true; } },
  { id: 'coin1', name: '코인 거래소', icon: '🏦', desc: '코인 획득 2배', cost: 2000, costType: 'carrots', effect: () => { state.coinMultiplier = (state.coinMultiplier||1) * 2; } }
];

let selectedSlot = null;
let mergeSelected = [false, false, false, false];
let coinMultiplier = 1;

// ==================== INIT ====================
function init() {
  loadGame();
  initRabbitGrid();
  initShop();
  initUpgrades();
  updateUI();
  gameLoop();
  autoSave();
}

function initRabbitGrid() {
  const grid = document.getElementById('rabbitGrid');
  grid.innerHTML = '';
  for (let i = 0; i < state.maxRabbits; i++) {
    const slot = document.createElement('div');
    slot.className = 'farm-slot empty';
    slot.id = `rabbitSlot${i}`;
    slot.onclick = () => handleRabbitClick(i);
    grid.appendChild(slot);
  }
  renderRabbits();
}

function initShop() {
  const grid = document.getElementById('shopGrid');
  grid.innerHTML = '';
  SHOP_ITEMS.forEach(item => {
    const div = document.createElement('div');
    div.className = 'shop-item';
    div.id = `shop_${item.id}`;
    div.innerHTML = `
      <div class="icon">${item.icon}</div>
      <div class="name">${item.name}</div>
      <div class="cost">${item.costType === 'carrots' ? '🥕' : '💰'} ${formatNum(item.cost)}</div>
      <div class="desc">${item.desc}</div>
    `;
    div.onclick = () => shopBuy(item);
    grid.appendChild(div);
  });
}

function initUpgrades() {
  renderUpgrades();
}

// ==================== CORE ACTIONS ====================
function handleClick(event) {
  state.carrots += state.clickPower;
  state.totalCarrots += state.clickPower;
  state.totalClicks++;
  spawnFloatText(event.clientX, event.clientY, `+${state.clickPower} 🥕`);
  spawnParticles(event.clientX, event.clientY, 3, '#FF6B6B');
  updateUI();
}

function handleRabbitClick(index) {
  const rabbit = state.rabbits[index];
  if (!rabbit) {
    // Empty slot - try to auto-place a baby rabbit if we have enough carrots
    if (state.carrots >= RABBIT_TYPES[0].cost) {
      addRabbit(0, index);
    }
    return;
  }

  // Auto-feed rabbit
  if (state.foodInventory.carrot > 0) {
    state.foodInventory.carrot--;
    rabbit.lastFed = Date.now();
    spawnFloatText(
      event ? event.clientX : window.innerWidth / 2,
      event ? event.clientY : 300,
      '🥕 먹이주기!'
    );
  }

  // Merge: if same type rabbit exists elsewhere, merge
  const sameTypeRabbits = state.rabbits
    .map((r, i) => ({ ...r, idx: i }))
    .filter(r => r && r.typeId === rabbit.typeId && r.idx !== index);

  if (sameTypeRabbits.length > 0) {
    const otherIdx = sameTypeRabbits[0].idx;
    if (rabbit.typeId < RABBIT_TYPES.length - 1) {
      // Merge up!
      const newType = rabbit.typeId + 1;
      state.rabbits[index] = null;
      state.rabbits[otherIdx] = {
        typeId: newType,
        lastFed: Date.now(),
        fedCount: (state.rabbits[otherIdx]?.fedCount || 0) + 1
      };
      showNotification(`${RABBIT_TYPES[newType].icon} ${RABBIT_TYPES[newType].name}로 진화!`);
      spawnFloatText(window.innerWidth / 2, 250, `${RABBIT_TYPES[newType].icon} 진화!`);
    } else {
      showNotification('이미 최고 레벨 토끼입니다! ✨');
    }
  }

  renderRabbits();
  updateUI();
}

function addRabbit(typeIndex, slotIndex) {
  const cost = RABBIT_TYPES[typeIndex].cost;
  if (state.carrots < cost) return;
  state.carrots -= cost;
  state.rabbits[slotIndex] = {
    typeId: typeIndex,
    lastFed: Date.now(),
    fedCount: 0
  };
  renderRabbits();
  updateUI();
}

// ==================== MERGE SYSTEM ====================
function mergeSelect(index) {
  if (mergeSelected[index]) {
    mergeSelected[index] = false;
    document.getElementById(`mSlot${index}`).classList.remove('selected');
  } else {
    const filled = mergeSelected.filter(s => s).length;
    if (filled < 2) {
      mergeSelected[index] = true;
      document.getElementById(`mSlot${index}`).classList.add('selected');
    }
  }
  updateMergeUI();
}

function doMerge() {
  const indices = mergeSelected.map((s, i) => s ? i : -1).filter(i => i >= 0);
  if (indices.length !== 2) return;

  const item1 = state.mergeSlots[indices[0]];
  const item2 = state.mergeSlots[indices[1]];

  if (!item1 || !item2 || item1 !== item2) {
    showNotification('같은 종류의 먹이만 머지할 수 있어요!');
    return;
  }

  const foodData = FOOD_TYPES.find(f => f.id === item1);
  if (!foodData || foodData.level >= FOOD_TYPES.length) {
    showNotification('이미 최고 레벨 먹이입니다!');
    return;
  }

  // Remove items from merge slots
  state.mergeSlots[indices[0]] = null;
  state.mergeSlots[indices[1]] = null;
  mergeSelected = [false, false, false, false];

  // Add upgraded food to inventory
  const newFoodId = FOOD_TYPES[foodData.level].id;
  state.foodInventory[newFoodId] = (state.foodInventory[newFoodId] || 0) + 1;

  showNotification(`${FOOD_TYPES[foodData.level].icon} ${FOOD_TYPES[foodData.level].name}로 진화!`);
  updateMergeUI();
  updateUI();
}

function mergeAddToSlot(foodId) {
  const emptyIdx = state.mergeSlots.indexOf(null);
  if (emptyIdx === -1) {
    showNotification('머지 슬롯이 가득 찼어요!');
    return;
  }
  if (!state.foodInventory[foodId] || state.foodInventory[foodId] <= 0) {
    showNotification('먹이가 부족해요!');
    return;
  }
  state.foodInventory[foodId]--;
  state.mergeSlots[emptyIdx] = foodId;
  updateMergeUI();
  updateUI();
}

function updateMergeUI() {
  for (let i = 0; i < 4; i++) {
    const slot = document.getElementById(`mSlot${i}`);
    const foodId = state.mergeSlots[i];
    if (foodId) {
      const food = FOOD_TYPES.find(f => f.id === foodId);
      slot.className = `merge-slot filled ${mergeSelected[i] ? 'selected' : ''}`;
      slot.innerHTML = `${food.icon}<div class="slot-label">${food.name}</div>`;
    } else {
      slot.className = 'merge-slot';
      slot.innerHTML = '';
    }
  }

  const filledCount = mergeSelected.filter(s => s).length;
  document.getElementById('mergeBtn').disabled = filledCount !== 2;

  // Show food buttons
  let existingBtns = document.querySelectorAll('.merge-food-btn');
  existingBtns.forEach(b => b.remove());

  const mergeSection = document.querySelector('.merge-section');
  FOOD_TYPES.forEach(food => {
    if ((state.foodInventory[food.id] || 0) > 0) {
      const btn = document.createElement('button');
      btn.className = 'merge-food-btn';
      btn.textContent = `${food.icon} ×${state.foodInventory[food.id]}`;
      btn.style.cssText = 'margin:3px;padding:5px 10px;border:2px solid #8BC34A;border-radius:10px;background:rgba(139,195,74,0.2);cursor:pointer;font-size:0.85em;';
      btn.onclick = () => mergeAddToSlot(food.id);
      mergeSection.appendChild(btn);
    }
  });
}

// ==================== SHOP ====================
function shopBuy(item) {
  if (state.carrots < item.cost) {
    showNotification('당근이 부족해요! 🥕');
    return;
  }

  if (item.type === 'rabbit') {
    const emptySlot = state.rabbits.indexOf(null);
    if (emptySlot === -1) {
      showNotification('토끼 우리에 자리가 없어요!');
      return;
    }
    state.carrots -= item.cost;
    state.rabbits[emptySlot] = {
      typeId: RABBIT_TYPES.findIndex(r => r.id === item.id),
      lastFed: Date.now(),
      fedCount: 0
    };
    renderRabbits();
  } else if (item.type === 'food') {
    state.carrots -= item.cost;
    state.foodInventory[item.id] = (state.foodInventory[item.id] || 0) + 1;
  }

  updateUI();
}

// ==================== UPGRADES ====================
function renderUpgrades() {
  const list = document.getElementById('upgradeList');
  list.innerHTML = '';
  UPGRADES.forEach(upg => {
    if (state.upgrades[upg.id]) return; // Already purchased
    const div = document.createElement('div');
    div.className = `upgrade-item ${state.carrots < upg.cost ? 'disabled' : ''}`;
    div.id = `upg_${upg.id}`;
    div.innerHTML = `
      <div class="up-icon">${upg.icon}</div>
      <div class="up-info">
        <div class="up-name">${upg.name}</div>
        <div class="up-desc">${upg.desc}</div>
      </div>
      <div class="up-cost">🥕 ${formatNum(upg.cost)}</div>
    `;
    div.onclick = () => buyUpgrade(upg);
    list.appendChild(div);
  });

  if (list.children.length === 0) {
    list.innerHTML = '<div style="text-align:center;color:#888;padding:20px;">모든 업그레이드를 구매했어요! 🎉</div>';
  }
}

function buyUpgrade(upg) {
  if (state.carrots < upg.cost || state.upgrades[upg.id]) return;
  state.carrots -= upg.cost;
  state.upgrades[upg.id] = true;
  upg.effect();
  showNotification(`${upg.icon} ${upg.name} 업그레이드 완료!`);
  renderUpgrades();
  updateUI();
}

// ==================== RENDERING ====================
function renderRabbits() {
  for (let i = 0; i < state.maxRabbits; i++) {
    const slot = document.getElementById(`rabbitSlot${i}`);
    const rabbit = state.rabbits[i];
    if (rabbit) {
      const type = RABBIT_TYPES[rabbit.typeId];
      slot.className = 'farm-slot';
      slot.innerHTML = `
        ${type.icon}
        <div class="level-badge">Lv.${type.level}</div>
        <div class="slot-label">${type.name}</div>
      `;
    } else {
      slot.className = 'farm-slot empty';
      slot.innerHTML = '';
    }
  }
}

function updateUI() {
  document.getElementById('carrots').textContent = formatNum(Math.floor(state.carrots));
  document.getElementById('coins').textContent = formatNum(Math.floor(state.coins));
  document.getElementById('cps').textContent = formatNum(calcCPS());
  document.getElementById('clickPower').textContent = state.clickPower;

  // Update shop items
  SHOP_ITEMS.forEach(item => {
    const el = document.getElementById(`shop_${item.id}`);
    if (el) {
      el.className = `shop-item ${state.carrots < item.cost ? 'disabled' : ''}`;
    }
  });

  // Update merge UI
  updateMergeUI();

  // Update upgrades
  renderUpgrades();

  // Update stats
  updateStats();
}

function calcCPS() {
  let totalCPS = 0;
  state.rabbits.forEach(rabbit => {
    if (rabbit) {
      const type = RABBIT_TYPES[rabbit.typeId];
      let foodBonus = 0;
      // Calculate food bonuses
      FOOD_TYPES.forEach(food => {
        const count = state.foodInventory[food.id] || 0;
        if (count > 0) {
          foodBonus += food.cpsBonus * count * state.foodMultiplier;
        }
      });
      totalCPS += (type.baseCps + foodBonus) * state.rabbitMultiplier;
    }
  });
  return totalCPS;
}

function calcCoinRate() {
  let total = 0;
  state.rabbits.forEach(rabbit => {
    if (rabbit) {
      const type = RABBIT_TYPES[rabbit.typeId];
      total += type.baseCoins * state.rabbitMultiplier;
    }
  });
  return total * (coinMultiplier || 1);
}

// ==================== GAME LOOP ====================
let lastTick = Date.now();
function gameLoop() {
  const now = Date.now();
  const dt = (now - lastTick) / 1000;
  lastTick = now;

  // Auto production
  const cps = calcCPS();
  const earned = cps * dt;
  state.carrots += earned;
  state.totalCarrots += earned;

  // Auto coin generation from rabbits
  const coinRate = calcCoinRate();
  const coinEarned = coinRate * dt;
  state.coins += coinEarned;
  state.totalCoins += coinEarned;

  // Auto feed
  if (state.autoFeed) {
    const now2 = Date.now();
    state.rabbits.forEach((rabbit, i) => {
      if (rabbit && now2 - rabbit.lastFed > 5000) { // Feed every 5 seconds
        if (state.foodInventory.carrot > 0) {
          state.foodInventory.carrot--;
          rabbit.lastFed = now2;
        } else if (state.foodInventory.premium_carrot > 0) {
          state.foodInventory.premium_carrot--;
          rabbit.lastFed = now2;
        }
      }
    });
  }

  updateUI();
  requestAnimationFrame(gameLoop);
}

// ==================== STATS ====================
function updateStats() {
  const panel = document.getElementById('statsPanel');
  const playTime = Math.floor((Date.now() - state.startTime) / 1000);
  const hours = Math.floor(playTime / 3600);
  const minutes = Math.floor((playTime % 3600) / 60);
  const seconds = playTime % 60;

  panel.innerHTML = `
    <div class="stat-card">
      <div class="stat-value">${formatNum(Math.floor(state.totalCarrots))}</div>
      <div class="stat-label">총 당근 획득</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${formatNum(Math.floor(state.totalCoins))}</div>
      <div class="stat-label">총 코인 획득</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${state.totalClicks}</div>
      <div class="stat-label">총 클릭 수</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${formatNum(calcCPS())}</div>
      <div class="stat-label">초당 당근 생산</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${state.rabbits.filter(r => r).length}</div>
      <div class="stat-label">현재 토끼 수</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">+${state.clickPower}</div>
      <div class="stat-label">클릭 당근</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">×${state.rabbitMultiplier}</div>
      <div class="stat-label">토끼 생산 배율</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">×${state.foodMultiplier}</div>
      <div class="stat-label">먹이 효과 배율</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${hours}시간 ${minutes}분 ${seconds}초</div>
      <div class="stat-label">플레이 시간</div>
    </div>
    <div class="stat-card">
      <div class="stat-value">${Object.keys(state.upgrades).length}/${UPGRADES.length}</div>
      <div class="stat-label">업그레이드 완료</div>
    </div>
  `;
}

// ==================== TAB SWITCHING ====================
function switchTab(tabName) {
  document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  document.getElementById(`tab-${tabName}`).classList.add('active');
  event.target.classList.add('active');

  if (tabName === 'stats') updateStats();
  if (tabName === 'upgrades') renderUpgrades();
}

// ==================== VISUAL EFFECTS ====================
function spawnFloatText(x, y, text) {
  const el = document.createElement('div');
  el.className = 'float-text';
  el.textContent = text;
  el.style.left = x + 'px';
  el.style.top = y + 'px';
  el.style.color = '#FF6B6B';
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 1200);
}

function spawnParticles(x, y, count, color) {
  for (let i = 0; i < count; i++) {
    const p = document.createElement('div');
    p.className = 'particle';
    p.style.left = (x + (Math.random() - 0.5) * 40) + 'px';
    p.style.top = (y + (Math.random() - 0.5) * 40) + 'px';
    p.style.width = p.style.height = (4 + Math.random() * 6) + 'px';
    p.style.background = color;
    document.body.appendChild(p);
    setTimeout(() => p.remove(), 800);
  }
}

function showNotification(text) {
  const existing = document.querySelector('.notification');
  if (existing) existing.remove();

  const el = document.createElement('div');
  el.className = 'notification';
  el.textContent = text;
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 3000);
}

// ==================== UTILITIES ====================
function formatNum(n) {
  if (n >= 1e12) return (n / 1e12).toFixed(1) + 'T';
  if (n >= 1e9) return (n / 1e9).toFixed(1) + 'B';
  if (n >= 1e6) return (n / 1e6).toFixed(1) + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(1) + 'K';
  return Math.floor(n).toString();
}

// ==================== SAVE/LOAD ====================
function saveGame() {
  const saveData = {
    carrots: state.carrots,
    coins: state.coins,
    totalCarrots: state.totalCarrots,
    totalCoins: state.totalCoins,
    totalClicks: state.totalClicks,
    clickPower: state.clickPower,
    rabbits: state.rabbits,
    foodInventory: state.foodInventory,
    mergeSlots: state.mergeSlots,
    upgrades: state.upgrades,
    maxRabbits: state.maxRabbits,
    foodMultiplier: state.foodMultiplier,
    rabbitMultiplier: state.rabbitMultiplier,
    autoFeed: state.autoFeed,
    coinMultiplier: coinMultiplier,
    startTime: state.startTime
  };
  localStorage.setItem('rabbitFarmSave', JSON.stringify(saveData));
}

function loadGame() {
  const data = localStorage.getItem('rabbitFarmSave');
  if (data) {
    try {
      const save = JSON.parse(data);
      Object.assign(state, save);
      if (save.coinMultiplier) coinMultiplier = save.coinMultiplier;
    } catch (e) {
      console.log('Save file corrupted, starting fresh');
    }
  }
}

function autoSave() {
  setInterval(saveGame, 10000);
}

// ==================== START ====================
init();
</script>
</body>
</html>

