.terrain-champ { background: linear-gradient(135deg, #c4a835, #d4b845); border: 2px solid #a48825; }
.terrain-ruines { background: linear-gradient(135deg, #5a3a5a, #7a5a7a); border: 2px solid #4a2a4a; }
.exit-cell { border: 3px solid #ffd700 !important; box-shadow: 0 0 15px rgba(255,215,0,0.5); }
.start-cell { border: 3px solid #00ff88 !important; box-shadow: 0 0 15px rgba(0,255,136,0.5); }
.player-marker {
  position: absolute;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8em;
  font-weight: bold;
  color: #fff;
  text-shadow: 0 1px 2px rgba(0,0,0,0.8);
  z-index: 5;
  transition: all 0.3s ease;
  box-shadow: 0 2px 8px rgba(0,0,0,0.5);
}
.player1-marker { background: radial-gradient(circle, #ff4444, #cc0000); border: 2px solid #ff8888; }
.player2-marker { background: radial-gradient(circle, #4488ff, #0044cc); border: 2px solid #88bbff; }
#sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 280px;
  max-width: 350px;
}
.panel {
  background: rgba(255,255,255,0.05);
  border-radius: 10px;
  padding: 15px;
  border: 1px solid rgba(255,255,255,0.1);
}
.panel h3 {
  margin-bottom: 10px;
  font-size: 1.1em;
  color: #ffd700;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  padding-bottom: 5px;
}
.player-info {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  border-radius: 8px;
  margin-bottom: 6px;
  transition: background 0.3s;
}
.player-info.active { background: rgba(255,255,255,0.1); }
.player-info .p-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2em;
  font-weight: bold;
  color: #fff;
  flex-shrink: 0;
}
.player-info .p-details { flex: 1; }
.player-info .p-name { font-weight: bold; font-size: 0.95em; }
.player-info .p-stats { font-size: 0.8em; color: #aaa; }
.health-bar {
  width: 100%;
  height: 8px;
  background: rgba(0,0,0,0.4);
  border-radius: 4px;
  margin-top: 4px;
  overflow: hidden;
}
.health-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.5s ease;
}
.health-bar-fill.p1 { background: linear-gradient(90deg, #ff4444, #ff8888); }
.health-bar-fill.p2 { background: linear-gradient(90deg, #4488ff, #88bbff); }
#dice-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
#dice-display {
  display: flex;
  gap: 10px;
}
.die {
  width: 56px;
  height: 56px;
  background: linear-gradient(145deg, #f0f0f0, #d0d0d0);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8em;
  font-weight: bold;
  color: #333;
  box-shadow: 0 3px 8px rgba(0,0,0,0.3);
  transition: transform 0.3s;
}
.die.rolling { animation: diceRoll 0.5s ease; }
@keyframes diceRoll {
  0% { transform: rotate(0deg) scale(1); }
  25% { transform: rotate(90deg) scale(1.2); }
  50% { transform: rotate(180deg) scale(1); }
  75% { transform: rotate(270deg) scale(1.2); }
  100% { transform: rotate(360deg) scale(1); }
}
#roll-btn {
  padding: 12px 30px;
  font-size: 1.1em;
  font-weight: bold;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: linear-gradient(135deg, #ff6b35, #ff4500);
  color: #fff;
  box-shadow: 0 4px 15px rgba(255,69,0,0.4);
  transition: all 0.2s;
  letter-spacing: 1px;
}
#roll-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(255,69,0,0.6); }
#roll-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }
#move-btn {
  padding: 10px 25px;
  font-size: 1em;
  font-weight: bold;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: linear-gradient(135deg, #4CAF50, #45a049);
  color: #fff;
  box-shadow: 0 4px 15px rgba(76,175,80,0.4);
  transition: all 0.2s;
  display: none;
}
#move-btn:hover { transform: translateY(-2px); }
#direction-btns {
  display: none;
  grid-template-columns: repeat(3, 50px);
  grid-template-rows: repeat(3, 50px);
  gap: 4px;
  justify-content: center;
  margin-top: 5px;
}
.dir-btn {
  width: 50px;
  height: 50px;
  border: none;
  border-radius: 8px;
  font-size: 1.3em;
  cursor: pointer;
  background: rgba(255,255,255,0.15);
  color: #fff;
  transition: all 0.2s;
}
.dir-btn:hover { background: rgba(255,255,255,0.3); transform: scale(1.1); }
.dir-btn:disabled { opacity: 0.3; cursor: not-allowed; }
.dir-btn.empty { visibility: hidden; }
#log {
  max-height: 180px;
  overflow-y: auto;
  font-size: 0.8em;
  line-height: 1.5;
}
#log::-webkit-scrollbar { width: 6px; }
#log::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 3px; }
.log-entry { padding: 3px 0; border-bottom: 1px solid rgba(255,255,255,0.05); }
.log-entry.danger { color: #ff6b6b; }
.log-entry.heal { color: #6bff6b; }
.log-entry.info { color: #6bb5ff; }
.log-entry.win { color: #ffd700; font-weight: bold; }
#legend {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  font-size: 0.75em;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 5px;
  border-radius: 4px;
  background: rgba(0,0,0,0.2);
}
.legend-item .li-icon { font-size: 1.2em; }
#start-screen {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.9);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 100;
}
#start-screen h1 { font-size: 3em; margin-bottom: 10px; }
#start-screen p { max-width: 500px; text-align: center; line-height: 1.6; color: #ccc; margin-bottom: 20px; }
#start-btn {
  padding: 15px 50px;
  font-size: 1.3em;
  font-weight: bold;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  background: linear-gradient(135deg, #ff6b35, #ff4500);
  color: #fff;
  box-shadow: 0 4px 20px rgba(255,69,0,0.5);
  transition: all 0.3s;
  letter-spacing: 2px;
}
#start-btn:hover { transform: scale(1.05); }
#game-over {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.85);
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 100;
}
#game-over h2 { font-size: 2.5em; margin-bottom: 10px; }
#game-over p { color: #ccc; font-size: 1.1em; margin-bottom: 20px; }
#restart-btn {
  padding: 12px 40px;
  font-size: 1.1em;
  font-weight: bold;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: linear-gradient(135deg, #4CAF50, #45a049);
  color: #fff;
  transition: all 0.3s;
}
#restart-btn:hover { transform: scale(1.05); }
.cell.highlight {
  animation: pulse 1s infinite;
  cursor: pointer;
}
@keyframes pulse {
  0%, 100% { box-shadow: 0 0 5px rgba(255,215,0,0.5); }
  50% { box-shadow: 0 0 20px rgba(255,215,0,0.8); }
}
.cell.trail {
  box-shadow: inset 0 0 15px rgba(255,215,0,0.3);
}
#turn-indicator {
  text-align: center;
  font-size: 1em;
  padding: 8px;
  border-radius: 6px;
  background: rgba(255,255,255,0.05);
}
</style>
</head>
<body>

<div id="start-screen">
  <h1>🏔️ Le Survivant</h1>
  <p>
    Vous êtes un survivant coincé dans une zone dangereuse. 
    Traversez le terrain hostile pour atteindre la sortie ! 
    Chaque terrain présente un risque différent. Gérez vos points de survie 
    et atteignez l'issue avant que la santé ne vous fasse défaut.
  </p>
  <p style="font-size:0.85em; color:#aaa;">
    🛤️ Route (0) — 🏘️ Village (soin) — 🌲 Forêt (2) — ⛰️ Montagne (3)<br>
    🌊 Rivière (2) — 🌾 Champ (1) — 🏚️ Ruines (4) — 🚪 Sortie
  </p>
  <button id="start-btn" onclick="startGame()">🎲 COMMENCER</button>
</div>

<div id="game-over">
  <h2 id="go-title"></h2>
  <p id="go-message"></p>
  <button id="restart-btn" onclick="restartGame()">🔄 Rejouer</button>
</div>

<h1>🏔️ Le Survivant</h1>
<p class="subtitle">Jeu de plateau — Traversez le danger pour survivre</p>

<div id="game-container">
  <div id="board-wrapper">
    <div id="board"></div>
  </div>
  <div id="sidebar">
    <div id="turn-indicator"></div>
    <div class="panel">
      <h3>👤 Joueurs</h3>
      <div id="players-info"></div>
    </div>
    <div class="panel" id="dice-area">
      <h3>🎲 Dés</h3>
      <div id="dice-display">
        <div class="die" id="die1">?</div>
        <div class="die" id="die2">?</div>
      </div>
      <button id="roll-btn" onclick="rollDice()">🎲 Lancer les dés</button>
      <button id="move-btn" onclick="enterMovePhase()">✅ Se déplacer</button>
      <div id="direction-btns">
        <div class="dir-btn empty"></div>
        <button class="dir-btn" onclick="movePlayer(0,-1)">⬆️</button>
        <div class="dir-btn empty"></div>
        <button class="dir-btn" onclick="movePlayer(-1,0)">⬅️</button>
        <div class="dir-btn empty"></div>
        <button class="dir-btn" onclick="movePlayer(1,0)">➡️</button>
        <div class="dir-btn empty"></div>
        <button class="dir-btn" onclick="movePlayer(0,1)">⬇️</button>
        <div class="dir-btn empty"></div>
      </div>
    </div>
    <div class="panel">
      <h3>📜 Journal</h3>
      <div id="log"></div>
    </div>
    <div class="panel">
      <h3>🗺️ Légende</h3>
      <div id="legend">
        <div class="legend-item"><span class="li-icon">🛤️</span> Route (0)</div>
        <div class="legend-item"><span class="li-icon">🌾</span> Champ (1)</div>
        <div class="legend-item"><span class="li-icon">🌊</span> Rivière (2)</div>
        <div class="legend-item"><span class="li-icon">🌲</span> Forêt (2)</div>
        <div class="legend-item"><span class="li-icon">⛰️</span> Montagne (3)</div>
        <div class="legend-item"><span class="li-icon">🏚️</span> Ruines (4)</div>
        <div class="legend-item"><span class="li-icon">🏘️</span> Village (soin)</div>
        <div class="legend-item"><span class="li-icon">🚪</span> Sortie</div>
      </div>
    </div>
  </div>
</div>

<script>
const BOARD_SIZE = 7;
const TERRAINS = {
  route:   { name: 'Route',   icon: '🛤️', danger: 0, cls: 'terrain-route' },
  champ:   { name: 'Champ',   icon: '🌾', danger: 1, cls: 'terrain-champ' },
  riviere: { name: 'Rivière', icon: '🌊', danger: 2, cls: 'terrain-riviere' },
  foret:   { name: 'Forêt',   icon: '🌲', danger: 2, cls: 'terrain-foret' },
  montagne:{ name: 'Montagne',icon: '⛰️', danger: 3, cls: 'terrain-montagne' },
  ruines:  { name: 'Ruines',  icon: '🏚️', danger: 4, cls: 'terrain-ruines' },
  village: { name: 'Village', icon: '🏘️', danger: 0, cls: 'terrain-village', heal: true },
  exit:    { name: 'Sortie',  icon: '🚪', danger: 0, cls: 'terrain-route', isExit: true },
  start:   { name: 'Départ',  icon: '🏁', danger: 0, cls: 'terrain-route', isStart: true }
};

const TERRAIN_POOL = ['route','champ','riviere','foret','montagne','ruines','champ','riviere','foret','champ'];

let board = [];
let players = [];
let currentPlayer = 0;
let diceValues = [0, 0];
let gameState = 'waiting'; // waiting, rolled, moving, gameOver
let moveCount = 0;
let maxMoves = 0;

function generateBoard() {
  board = [];
  for (let r = 0; r < BOARD_SIZE; r++) {
    board[r] = [];
    for (let c = 0; c < BOARD_SIZE; c++) {
      if (r === 0 && c === 0) {
        board[r][c] = { ...TERRAINS.start };
      } else if (r === BOARD_SIZE - 1 && c === BOARD_SIZE - 1) {
        board[r][c] = { ...TERRAINS.exit };
      } else {
        const t = TERRAIN_POOL[Math.floor(Math.random() * TERRAIN_POOL.length)];
        board[r][c] = { ...TERRAINS[t] };
      }
    }
  }
  // Ensure some variety - make sure there are paths
  // Add a guaranteed path from start to exit
  let r = 0, c = 0;
  const pathSteps = [];
  while (r < BOARD_SIZE - 1 || c < BOARD_SIZE - 1) {
    if (r === BOARD_SIZE - 1) c++;
    else if (c === BOARD_SIZE - 1) r++;
    else {
      r += Math.random() < 0.5 ? 1 : 0;
      c += r === 0 && c < BOARD_SIZE - 1 ? 1 : (c < BOARD_SIZE - 1 ? 1 : 0);
      if (r > 0 && c > 0 && Math.random() < 0.3) {
        // slight randomness
      }
    }
    if (r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE) {
      pathSteps.push([r, c]);
    }
  }
  // Make some path cells routes for playability
  for (const [pr, pc] of pathSteps) {
    if (board[pr][pc].danger > 0 && Math.random() < 0.5) {
      board[pr][pc] = { ...TERRAINS.route };
    }
  }
}

function initPlayers() {
  players = [
    { name: 'Survivant 1', color: '#ff4444', cls: 'player1-marker', health: 15, maxHealth: 15, pos: { r: 0, c: 0 }, alive: true },
    { name: 'Survivant 2', color: '#4488ff', cls: 'player2-marker', health: 15, maxHealth: 15, pos: { r: 0, c: 0 }, alive: true }
  ];
}

function renderBoard() {
  const boardEl = document.getElementById('board');
  boardEl.innerHTML = '';
  for (let r = 0; r < BOARD_SIZE; r++) {
    for (let c = 0; c < BOARD_SIZE; c++) {
      const cell = document.createElement('div');
      const t = board[r][c];
      cell.className = `cell ${t.cls}`;
      if (t.isExit) cell.classList.add('exit-cell');
      if (t.isStart) cell.classList.add('start-cell');
      cell.dataset.r = r;
      cell.dataset.c = c;

      let extra = '';
      if (t.danger > 0) {
        extra += `<div class="danger-badge">${t.danger}</div>`;
      }
      if (t.heal) {
        extra += `<div style="font-size:0.6em;position:absolute;bottom:2px;left:50%;transform:translateX(-50%);color:#fff;">❤️</div>`;
      }

      cell.innerHTML = `
        <span class="terrain-icon">${t.icon}</span>
        ${extra}
        <span class="cell-name">${t.name}</span>
      `;
      cell.addEventListener('click', () => onCellClick(r, c));
      boardEl.appendChild(cell);
    }
  }
  renderPlayers();
}

function renderPlayers() {
  // Remove existing markers
  document.querySelectorAll('.player-marker').forEach(m => m.remove());

  players.forEach((p, i) => {
    if (!p.alive) return;
    const cell = getCell(p.pos.r, p.pos.c);
    if (!cell) return;
    const marker = document.createElement('div');
    marker.className = `player-marker ${p.cls}`;
    marker.textContent = i + 1;
    if (players.length > 1 && players[1 - i].alive && players[1 - i].pos.r === p.pos.r && players[1 - i].pos.c === p.pos.c) {
      marker.style.transform = `translate(${i === 0 ? -8 : 8}px, ${i === 0 ? -8 : 8}px)`;
    }
    cell.appendChild(marker);
  });
}

function getCell(r, c) {
  return document.querySelector(`.cell[data-r="${r}"][data-c="${c}"]`);
}

function renderPlayersInfo() {
  const container = document.getElementById('players-info');
  container.innerHTML = '';
  players.forEach((p, i) => {
    const div = document.createElement('div');
    div.className = `player-info ${i === currentPlayer ? 'active' : ''}`;
    const healthPct = (p.health / p.maxHealth * 100);
    div.innerHTML = `
      <div class="p-avatar" style="background:${p.color}">${i + 1}</div>
      <div class="p-details">
        <div class="p-name">${p.name}</div>
        <div class="p-stats">❤️ ${p.health}/${p.maxHealth} | 📍 Ligne ${p.pos.r + 1}, Col ${p.pos.c + 1}</div>
        <div class="health-bar"><div class="health-bar-fill ${p.cls === 'player1-marker' ? 'p1' : 'p2'}" style="width:${healthPct}%"></div></div>
      </div>
    `;
    container.appendChild(div);
  });
}

function renderTurnIndicator() {
  const el = document.getElementById('turn-indicator');
  if (gameState === 'gameOver') {
    el.textContent = '🏁 Partie terminée';
    el.style.color = '#ffd700';
  } else {
    const p = players[currentPlayer];
    el.textContent = `🎯 Tour de ${p.name}`;
    el.style.color = p.color;
  }
}

function addLog(msg, type = 'info') {
  const log = document.getElementById('log');
  const entry = document.createElement('div');
  entry.className = `log-entry ${type}`;
  entry.textContent = msg;
  log.appendChild(entry);
  log.scrollTop = log.scrollHeight;
}

function rollDice() {
  if (gameState !== 'waiting') return;
  gameState = 'rolled';
  moveCount = 0;

  const die1El = document.getElementById('die1');
  const die2El = document.getElementById('die2');
  die1El.classList.add('rolling');
  die2El.classList.add('rolling');

  let rolls = 0;
  const interval = setInterval(() => {
    die1El.textContent = Math.floor(Math.random() * 6) + 1;
    die2El.textContent = Math.floor(Math.random() * 6) + 1;
    rolls++;
    if (rolls > 10) {
      clearInterval(interval);
      diceValues[0] = Math.floor(Math.random() * 6) + 1;
      diceValues[1] = Math.floor(Math.random() * 6) + 1;
      die1El.textContent = diceValues[0];
      die2El.textContent = diceValues[1];
      die1El.classList.remove('rolling');
      die2El.classList.remove('rolling');
      maxMoves = diceValues[0] + diceValues[1];
      moveCount = 0;
      addLog(`${players[currentPlayer].name} a fait ${diceValues[0]} + ${diceValues[1]} = ${maxMoves} points de mouvement`, 'info');
      document.getElementById('roll-btn').style.display = 'none';
      document.getElementById('move-btn').style.display = 'inline-block';
      highlightValidMoves();
    }
  }, 80);
}

function highlightValidMoves() {
  clearHighlights();
  const p = players[currentPlayer];
  const moves = getValidMoves(p.pos.r, p.pos.c, maxMoves - moveCount);
  moves.forEach(([r, c]) => {
    const cell = getCell(r, c);
    if (cell) cell.classList.add('highlight');
  });
}

function getValidMoves(r, c, remaining) {
  if (remaining <= 0) return [[r, c]];
  const moves = [[r, c]];
  const dirs = [[0, -1], [0, 1], [-1, 0], [1, 0]];
  for (const [dr, dc] of dirs) {
    const nr = r + dr, nc = c + dc;
    if (nr >= 0 && nr < BOARD_SIZE && nc >= 0 && nc < BOARD_SIZE) {
      moves.push([nr, nc]);
    }
  }
  return moves;
}

function clearHighlights() {
  document.querySelectorAll('.cell.highlight, .cell.trail').forEach(c => {
    c.classList.remove('highlight', 'trail');
  });
}

function enterMovePhase() {
  if (gameState !== 'rolled') return;
  gameState = 'moving';
  document.getElementById('move-btn').style.display = 'none';
  document.getElementById('direction-btns').style.display = 'grid';
  highlightValidMoves();
}

function onCellClick(r, c) {
  if (gameState !== 'moving') return;
  const p = players[currentPlayer];
  const validMoves = getValidMoves(p.pos.r, p.pos.c, maxMoves - moveCount);
  const isValid = validMoves.some(([vr, vc]) => vr === r && vc === c);
  if (!isValid) return;

  // Move to cell
  movePlayerTo(r, c);
}

function movePlayer(dr, dc) {
  if (gameState !== 'moving') return;
  const p = players[currentPlayer];
  const nr = p.pos.r + dr;
  const nc = p.pos.c + dc;
  if (nr < 0 || nr >= BOARD_SIZE || nc < 0 || nc >= BOARD_SIZE) return;
  const validMoves = getValidMoves(p.pos.r, p.pos.c, maxMoves - moveCount);
  const isValid = validMoves.some(([vr, vc]) => vr === nr && vc === nc);
  if (!isValid) return;

  movePlayerTo(nr, nc);
}

function movePlayerTo(r, c) {
  const p = players[currentPlayer];
  const t = board[r][c];

  // Mark trail
  const prevCell = getCell(p.pos.r, p.pos.c);
  if (prevCell) prevCell.classList.add('trail');

  p.pos = { r, c };
  moveCount++;
  renderPlayers();
  clearHighlights();

  addLog(`${p.name} se déplace sur ${t.icon} ${t.name}`, 'info');

  // Apply terrain effects
  if (t.heal) {
    const healAmt = Math.min(3, p.maxHealth - p.health);
    if (healAmt > 0) {
      p.health += healAmt;
      addLog(`${p.name} soigne ${healAmt} ❤️ au village !`, 'heal');
    } else {
      addLog(`${p.name} est déjà à pleine santé.`, 'info');
    }
  }

  if (t.danger > 0) {
    const dmg = t.danger;
    p.health -= dmg;
    addLog(`${p.name} perd ${dmg} ❤️ (${t.name} dangereux)`, 'danger');
  }

  // Check death
  if (p.health <= 0) {
    p.health = 0;
    p.alive = false;
    addLog(`${p.name} est mort(e) ! 💀`, 'danger');
    renderPlayersInfo();
    renderBoard();
    endGame(p);
    return;
  }

  // Check exit
  if (t.isExit) {
    addLog(`${p.name} a atteint la sortie ! 🎉`, 'win');
    renderPlayersInfo();
    renderBoard();
    endGame(p, true);
    return;
  }

  renderPlayersInfo();

  // Check if more moves possible
  const validMoves = getValidMoves(r, c, maxMoves - moveCount);
  if (validMoves.length <= 1) {
    // No more moves, end turn
    endTurn();
  } else {
    // Show direction buttons still, highlight new valid moves
    document.getElementById('direction-btns').style.display = 'grid';
    highlightValidMoves();
  }
}

function endTurn() {
  document.getElementById('direction-btns').style.display = 'none';
  clearHighlights();

  // Check if other player is still alive
  const otherIdx = 1 - currentPlayer;
  if (!players[otherIdx].alive) {
    // Only one player alive, they win if they can reach exit
    // Check if current player can still move
    const p = players[currentPlayer];
    const validMoves = getValidMoves(p.pos.r, p.pos.c, maxMoves - moveCount);
    if (validMoves.length <= 1) {
      // Current player stuck, other player wins
      endGame(players[otherIdx], true);
      return;
    }
  }

  // Switch player
  currentPlayer = 1 - currentPlayer;
  gameState = 'waiting';
  document.getElementById('roll-btn').style.display = 'inline-block';
  document.getElementById('roll-btn').disabled = false;
  document.getElementById('die1').textContent = '?';
  document.getElementById('die2').textContent = '?';
  renderTurnIndicator();
