    goTitle.style.color = '#ffd700';
    goMsg.textContent = `${winner.name} a atteint la sortie et survécu !`;
  } else {
    const loser = winner;
    const survivor = players.find(p => p.alive);
    goTitle.textContent = '💀 Game Over';
    goTitle.style.color = '#ff4444';
    goMsg.textContent = `${loser.name} est mort(e). ${survivor ? survivor.name + ' est le dernier survivant !' : 'Personne n\'a survécu.'}`;
