// Particles
function spawnParticles(x, y, z, count, color, speed, life, size) {
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * speed;
        particles.push({
            x, y: y + z, z,
            vx: Math.cos(angle) * spd,
            vy: Math.random() * spd * 0.5,
            vz: Math.sin(angle) * spd,
            life: life + Math.random() * life * 0.5,
            maxLife: life + Math.random() * life * 0.5,
            color,
            size: size + Math.random() * size * 0.5,
            gravity: 0.1
        });
    }
}

function spawnExplosion(x, y, z, radius, damage) {
    explosions.push({ x, y, z, radius, maxRadius: radius, damage, timer: 30, maxTimer: 30 });
    spawnParticles(x, y, z, 50, '#ff4400', 8, 40, 4);
    spawnParticles(x, y, z, 30, '#ffaa00', 6, 30, 3);
    spawnParticles(x, y, z, 20, '#ffffff', 4, 20, 2);
    camera.shakeIntensity = Math.min(radius / 20, 15);
    playExplosion();

    // Damage buildings
    buildings.forEach(b => {
        if (b.destroyed) return;
        const dx = b.x - x, dz = b.z - z;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist < radius + b.w) {
            const dmg = damage * (1 - dist / (radius + b.w));
            b.health -= dmg;
            if (b.health <= 0) {
                b.destroyed = true;
                b.debrisTimer = 60;
                spawnParticles(b.x, b.y, b.z, 80, '#888888', 10, 60, 5);
                spawnParticles(b.x, b.y, b.z, 40, '#ff6600', 6, 40, 3);
                score += 50;
            }
        }
    });

    // Damage villains
    villains.forEach(v => {
        if (!v.alive) return;
        const dx = v.x - x, dz = v.z - z;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist < radius) {
            v.health -= damage * (1 - dist / radius);
            v.stunned = 30;
            if (v.health <= 0) {
                v.alive = false;
                score += 100;
                spawnParticles(v.x, v.y, v.z, 40, v.glowColor, 8, 40, 4);
                playExplosion();
            }
        }
    });

    // Damage NPCs
    npcs.forEach(n => {
        if (!n.alive) return;
        const dx = n.x - x, dz = n.z - z;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist < radius) {
            n.health -= damage * (1 - dist / radius) * 0.5;
            if (n.health <= 0) {
                n.alive = false;
                score -= 200;
            }
        }
    });

    // Damage player
    const pdx = player.x - x, pdz = player.z - z;
    const pdist = Math.sqrt(pdx * pdx + pdz * pdz);
    if (pdist < radius) {
        player.health -= player.invincible > 0 ? 0 : 20 * (1 - pdist / radius);
        player.invincible = 30;
        showDamage();
    }
}

function showDamage() {
    const overlay = document.getElementById('damageOverlay');
    overlay.style.opacity = '1';
    setTimeout(() => overlay.style.opacity = '0', 200);
}

function showNotification(text) {
    const el = document.getElementById('notification');
    el.textContent = text;
    el.style.opacity = '1';
    setTimeout(() => el.style.opacity = '0', 2000);
}

// 3D Projection
function project(x, y, z) {
    const camX = x - camera.x;
    const camY = y - camera.y;
    const camZ = z - camera.z;

    const rotX = Math.cos(player.angle);
    const rotZ = Math.sin(player.angle);

    const dx = camX;
    const dz = camZ;
    const rx = dx * rotX + dz * rotZ;
    const rz = -dx * rotZ + dz * rotX;

    const scale = (800 * camera.zoom) / (800 + rz);
    const sx = W / 2 + rx * scale;
    const sy = H / 2 - (camY) * scale * 0.5 + rz * scale * 0.1;

    return { x: sx, y: sy, scale, visible: rz > -700 };
}

// Draw functions
function drawGround() {
    const gridSize = 200;
    const startX = Math.floor((camera.x - W / camera.zoom) / gridSize) * gridSize;
    const endX = Math.floor((camera.x + W / camera.zoom) / gridSize) * gridSize;
    const startZ = Math.floor((camera.z - H / camera.zoom) / gridSize) * gridSize;
    const endZ = Math.floor((camera.z + H / camera.zoom) / gridSize) * gridSize;

    const isNight = dayTime < 0.25 || dayTime > 0.75;
    const groundColor = isNight ? '#111122' : '#2a2a2a';
    const lineColor = isNight ? '#1a1a33' : '#3a3a3a';

    ctx.strokeStyle = lineColor;
    ctx.lineWidth = 1;

    for (let x = startX; x <= endX; x += gridSize) {
        const p1 = project(x, 0, startZ);
        const p2 = project(x, 0, endZ);
        if (p1.visible && p2.visible) {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
        }
    }
    for (let z = startZ; z <= endZ; z += gridSize) {
        const p1 = project(startX, 0, z);
        const p2 = project(endX, 0, z);
        if (p1.visible && p2.visible) {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
        }
    }
}

function drawBuilding(b) {
    if (b.destroyed) {
        if (b.debrisTimer > 0) {
            b.debrisTimer--;
            spawnParticles(b.x, 0, b.z, 2, '#666666', 3, 20, 3);
        }
        return;
    }

    const cx = b.x, cz = b.z;
    const hw = b.w / 2, hd = b.h / 2;
    const top = b.d;

    const corners = [
        project(cx - hw, 0, cz - hd),
        project(cx + hw, 0, cz - hd),
        project(cx + hw, 0, cz + hd),
        project(cx - hw, 0, cz + hd),
        project(cx - hw, top, cz - hd),
        project(cx + hw, top, cz - hd),
        project(cx + hw, top, cz + hd),
        project(cx - hw, top, cz + hd)
    ];

    if (!corners[0].visible && !corners[5].visible) return;

    const isNight = dayTime < 0.25 || dayTime > 0.75;
    const dmgRatio = b.health / b.maxHealth;

    // Front face
    ctx.fillStyle = b.color;
    ctx.globalAlpha = 0.9;
    ctx.beginPath();
    ctx.moveTo(corners[0].x, corners[0].y);
    ctx.lineTo(corners[1].x, corners[1].y);
    ctx.lineTo(corners[5].x, corners[5].y);
    ctx.lineTo(corners[4].x, corners[4].y);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Right face
    ctx.fillStyle = shadeColor(b.color, -20);
    ctx.beginPath();
    ctx.moveTo(corners[1].x, corners[1].y);
    ctx.lineTo(corners[2].x, corners[2].y);
    ctx.lineTo(corners[6].x, corners[6].y);
    ctx.lineTo(corners[5].x, corners[5].y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Top face
    ctx.fillStyle = b.roofColor;
    ctx.beginPath();
    ctx.moveTo(corners[4].x, corners[4].y);
    ctx.lineTo(corners[5].x, corners[5].y);
    ctx.lineTo(corners[6].x, corners[6].y);
    ctx.lineTo(corners[7].x, corners[7].y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Windows
    if (dmgRatio > 0.3) {
        const winW = (b.w * 0.7) / b.windows;
        const winH = (top * 0.8) / b.windowRows;
        const winStartY = top * 0.1;

        for (let row = 0; row < b.windowRows; row++) {
            for (let col = 0; col < b.windows; col++) {
                const wx = corners[0].x + (corners[1].x - corners[0].x) * (0.15 + col * 0.7 / b.windows);
                const wy = corners[0].y + (corners[4].y - corners[0].y) * (0.1 + row * 0.8 / b.windowRows);
                const wSize = winW * corners[0].scale * 0.8;
                const hSize = winH * corners[0].scale * 0.8;

                if (wSize < 2 || hSize < 2) continue;

                const lit = isNight ? Math.random() > 0.4 : Math.random() > 0.7;
                ctx.fillStyle = lit ? '#ffdd88' : '#223344';
                ctx.globalAlpha = lit ? 0.8 : 0.5;
                ctx.fillRect(wx - wSize / 2, wy - hSize / 2, wSize, hSize);
            }
        }
    }

    // Damage cracks
    if (dmgRatio < 0.7) {
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 2;
        ctx.globalAlpha = 1 - dmgRatio;
        for (let i = 0; i < 3; i++) {
            const sx = corners[0].x + (corners[1].x - corners[0].x) * Math.random();
            const sy = corners[0].y + (corners[4].y - corners[0].y) * Math.random();
            ctx.beginPath();
            ctx.moveTo(sx, sy);
            ctx.lineTo(sx + (Math.random() - 0.5) * 20, sy + Math.random() * 20);
            ctx.stroke();
        }
    }

    ctx.globalAlpha = 1;
}

function shadeColor(color, percent) {
    return color; // Simplified
}

function drawVehicle(v) {
    if (!v.moving && v.health <= 0) return;
    const p = project(v.x, 0, v.z);
    if (!p.visible) return;

    const s = p.scale;
    const w = v.w * s;
    const h = v.h * s;

    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(v.angle);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(-w / 2 + 3, -h / 2 + 3, w, h);

    // Body
    ctx.fillStyle = v.color;
    ctx.fillRect(-w / 2, -h / 2, w, h);

    // Windshield
    ctx.fillStyle = '#88bbff';
    ctx.fillRect(w / 4, -h / 2 + 1, w / 5, h - 2);

    // Wheels
    ctx.fillStyle = '#222';
    ctx.fillRect(-w / 2 - 2, -h / 2 - 2, 4, 4);
    ctx.fillRect(w / 2 - 2, -h / 2 - 2, 4, 4);
    ctx.fillRect(-w / 2 - 2, h / 2 - 2, 4, 4);
    ctx.fillRect(w / 2 - 2, h / 2 - 2, 4, 4);

    ctx.restore();
}

function drawNPC(n) {
    if (!n.alive) return;
    const p = project(n.x, 0, n.z);
    if (!p.visible) return;

    const s = p.scale;
    const w = n.w * s;
    const h = n.h * s;

    ctx.save();
    ctx.translate(p.x, p.y);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(0, 0, w / 2, w / 4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = n.shirtColor;
    ctx.fillRect(-w / 2, -h, w, h * 0.6);

    // Head
    ctx.fillStyle = n.color;
    ctx.beginPath();
    ctx.arc(0, -h - w / 3, w / 3, 0, Math.PI * 2);
    ctx.fill();

    // Legs
    ctx.fillStyle = '#333';
    ctx.fillRect(-w / 3, -h * 0.4, w / 4, h * 0.4);
    ctx.fillRect(w / 12, -h * 0.4, w / 4, h * 0.4);

    // Fleeing indicator
    if (n.fleeing) {
        ctx.fillStyle = '#ff0000';
        ctx.font = `${Math.max(10, 14 * s)}px Arial`;
        ctx.textAlign = 'center';
        ctx.fillText('!', 0, -h - w / 3 - 5);
    }

    ctx.restore();
}

function drawVillain(v) {
    if (!v.alive) return;
    const p = project(v.x, 0, v.z);
    if (!p.visible) return;

    const s = p.scale;
    const w = v.w * s;
    const h = v.h * s;

    ctx.save();
    ctx.translate(p.x, p.y);

    // Glow
    if (v.frozen) {
        ctx.shadowColor = '#00aaff';
        ctx.shadowBlur = 20;
    } else {
        ctx.shadowColor = v.glowColor;
        ctx.shadowBlur = 15;
    }

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(0, 0, w / 2, w / 3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = v.color;
    ctx.fillRect(-w / 2, -h, w, h * 0.65);

    // Head
    ctx.fillStyle = v.type === 'robot' ? '#888' : v.type === 'kryptonite' ? '#00ff00' : '#cc8888';
    ctx.beginPath();
    ctx.arc(0, -h - w / 3, w / 3, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = v.glowColor;
    ctx.beginPath();
    ctx.arc(-w / 6, -h - w / 3, w / 8, 0, Math.PI * 2);
    ctx.arc(w / 6, -h - w / 3, w / 8, 0, Math.PI * 2);
    ctx.fill();

    // Legs
    ctx.fillStyle = shadeColor(v.color, -30);
    ctx.fillRect(-w / 3, -h * 0.35, w / 4, h * 0.35);
    ctx.fillRect(w / 12, -h * 0.35, w / 4, h * 0.35);

    // Health bar
    if (v.health < v.maxHealth) {
        const barW = w * 1.5;
        const barH = 4 * s;
        ctx.fillStyle = '#333';
        ctx.fillRect(-barW / 2, -h - w / 3 - 15, barW, barH);
        ctx.fillStyle = v.health > v.maxHealth * 0.5 ? '#00ff00' : v.health > v.maxHealth * 0.25 ? '#ffaa00' : '#ff0000';
        ctx.fillRect(-barW / 2, -h - w / 3 - 15, barW * (v.health / v.maxHealth), barH);
    }

    // Frozen overlay
    if (v.frozen) {
        ctx.fillStyle = 'rgba(100,200,255,0.3)';
        ctx.fillRect(-w / 2, -h, w, h);
    }

    ctx.shadowBlur = 0;
    ctx.restore();
}

function drawPlayer() {
    const p = project(player.x, player.z, player.z);
    if (!p.visible) return;

    const s = p.scale;
    const w = player.width * s;
    const h = player.height * s;

    ctx.save();
    ctx.translate(p.x, p.y);

    // Cape
    player.capeAngle += 0.1;
    const capeWave = Math.sin(player.capeAngle) * 5 * s;
    ctx.fillStyle = '#cc0000';
    ctx.beginPath();
    ctx.moveTo(-w / 4, -h * 0.3);
    ctx.quadraticCurveTo(-w / 3 + capeWave, -h * 0.1, -w / 4 + capeWave * 0.5, h * 0.1);
    ctx.lineTo(w / 4 - capeWave * 0.5, h * 0.1);
    ctx.quadraticCurveTo(w / 3 - capeWave, -h * 0.1, w / 4, -h * 0.3);
    ctx.closePath();
    ctx.fill();

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(0, 0, w / 2, w / 3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Legs
    ctx.fillStyle = '#0044cc';
    const legSpread = Math.sin(player.animFrame * 0.3) * 5 * s;
    ctx.fillRect(-w / 3 - legSpread, -h * 0.35, w / 4, h * 0.35);
    ctx.fillRect(w / 12 + legSpread, -h * 0.35, w / 4, h * 0.35);

    // Boots
    ctx.fillStyle = '#cc0000';
    ctx.fillRect(-w / 3 - legSpread - 2, -h * 0.05, w / 4 + 4, h * 0.05);
    ctx.fillRect(w / 12 + legSpread - 2, -h * 0.05, w / 4 + 4, h * 0.05);

    // Body
    ctx.fillStyle = '#0044cc';
    ctx.fillRect(-w / 2, -h * 0.85, w, h * 0.55);

    // S shield
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.moveTo(0, -h * 0.8);
    ctx.lineTo(-w / 4, -h * 0.65);
    ctx.lineTo(w / 4, -h * 0.65);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#cc0000';
    ctx.font = `bold ${Math.max(8, 14 * s)}px Arial`;
    ctx.textAlign = 'center';
    ctx.fillText('S', 0, -h * 0.68);

    // Arms
    const armAngle = player.heatVision ? -0.5 : Math.sin(player.animFrame * 0.3) * 0.3;
    ctx.fillStyle = '#0044cc';
    ctx.save();
    ctx.translate(-w / 2, -h * 0.8);
    ctx.rotate(-armAngle);
    ctx.fillRect(-4 * s, 0, 8 * s, h * 0.35);
    ctx.restore();
    ctx.save();
    ctx.translate(w / 2, -h * 0.8);
    ctx.rotate(armAngle);
    ctx.fillRect(-4 * s, 0, 8 * s, h * 0.35);
    ctx.restore();

    // Hands
    ctx.fillStyle = '#ffcc88';
    ctx.beginPath();
    ctx.arc(-w / 2 + Math.sin(armAngle) * h * 0.35, -h * 0.8 + h * 0.35, 5 * s, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(w / 2 - Math.sin(armAngle) * h * 0.35, -h * 0.8 + h * 0.35, 5 * s, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = '#ffcc88';
    ctx.beginPath();
    ctx.arc(0, -h * 0.92, w / 3, 0, Math.PI * 2);
    ctx.fill();

    // Hair
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(0, -h * 0.97, w / 3, Math.PI, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-w / 3, -h * 0.97);
    ctx.lineTo(-w / 3 - 3 * s, -h * 0.85);
    ctx.lineTo(-w / 6, -h * 0.92);
    ctx.closePath();
    ctx.fill();

    // Eyes
    ctx.fillStyle = player.superSpeed ? '#FFD700' : '#ffffff';
    ctx.beginPath();
    ctx.ellipse(-w / 7, -h * 0.93, w / 8, h * 0.04, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(w / 7, -h * 0.93, w / 8, h * 0.04, 0, 0, Math.PI * 2);
    ctx.fill();

    // Pupils
    ctx.fillStyle = '#0066cc';
    const pupilOff = Math.cos(player.angle) * 2 * s;
    ctx.beginPath();
    ctx.arc(-w / 7 + pupilOff, -h * 0.93, w / 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(w / 7 + pupilOff, -h * 0.93, w / 14, 0, Math.PI * 2);
    ctx.fill();

    // Invincibility flash
    if (player.invincible > 0 && Math.floor(player.invincible / 3) % 2 === 0) {
        ctx.fillStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath();
        ctx.arc(0, -h / 2, w, 0, Math.PI * 2);
        ctx.fill();
    }

    // Super speed aura
    if (player.superSpeed) {
        ctx.strokeStyle = '#FFD700';
        ctx.lineWidth = 3 * s;
        ctx.globalAlpha = 0.5 + Math.sin(player.animFrame * 0.5) * 0.3;
        ctx.beginPath();
        ctx.arc(0, -h / 2, w * 1.5, 0, Math.PI * 2);
        ctx.stroke();
        ctx.globalAlpha = 1;
    }

    // Freeze breath effect
    if (player.freezeBreath) {
        ctx.fillStyle = 'rgba(100,200,255,0.3)';
        ctx.beginPath();
        ctx.arc(0, -h * 0.92, w / 2, 0, Math.PI * 2);
        ctx.fill();
    }

    ctx.restore();

    // Trail
    if (player.flying || player.superSpeed) {
        player.trail.push({ x: player.x, z: player.z, life: 20 });
    }
    player.trail = player.trail.filter(t => {
        t.life--;
        const tp = project(t.x, t.z, t.z);
        if (tp.visible) {
            ctx.fillStyle = player.superSpeed ? `rgba(255,215,0,${t.life / 20 * 0.5})` : `rgba(255,100,0,${t.life / 20 * 0.3})`;
            ctx.beginPath();
            ctx.arc(tp.x, tp.y, 5 * tp.scale * (t.life / 20), 0, Math.PI * 2);
            ctx.fill();
        }
        return t.life > 0;
    });
}

function drawHeatVision() {
    if (!player.heatVision) return;

    const worldMouseX = mouseX;
    const worldMouseY = mouseY;

    // Convert screen to world
    const dx = worldMouseX - W / 2;
    const dy = worldMouseY - H / 2;
    const dist = Math.sqrt(dx * dx + dy * dy);
    const aimAngle = Math.atan2(dy, dx);

    const range = 300;
    const endX = player.x + Math.cos(aimAngle) * range;
    const endZ = player.z + Math.sin(aimAngle) * range;

    // Laser beam
    const p1 = project(player.x, 0, player.z);
    const p2 = project(endX, 0, endZ);

    if (p1.visible && p2.visible) {
        const gradient = ctx.createLinearGradient(p1.x, p1.y, p2.x, p2.y);
        gradient.addColorStop(0, 'rgba(255,100,0,0.8)');
        gradient.addColorStop(0.5, 'rgba(255,200,0,0.9)');
        gradient.addColorStop(1, 'rgba(255,50,0,0.6)');

        ctx.strokeStyle = gradient;
        ctx.lineWidth = 8 * p1.scale;
        ctx.shadowColor = '#ff4400';
        ctx.shadowBlur = 30;
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();

        // Inner beam
        ctx.strokeStyle = 'rgba(255,255,200,0.9)';
        ctx.lineWidth = 3 * p1.scale;
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();

        ctx.shadowBlur = 0;

        // Damage things in beam
        if (player.heatVisionCooldown <= 0) {
            villains.forEach(v => {
                if (!v.alive) return;
                const vdx = v.x - player.x, vdZ = v.z - player.z;
                const vDist = Math.sqrt(vdx * vdx + vdZ * vdZ);
                const vAngle = Math.atan2(vdZ, vdx);
                let angleDiff = Math.abs(vAngle - aimAngle);
                if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;
                if (vDist < range && angleDiff < 0.15 && vDist < vDist) {
                    v.health -= 2;
                    v.stunned = 10;
                    spawnParticles(v.x, 0, v.z, 3, '#ff4400', 3, 15, 2);
                    if (v.health <= 0) {
                        v.alive = false;
                        score += 100;
                        spawnExplosion(v.x, 0, v.z, 50, 50);
                    }
                }
            });

            npcs.forEach(n => {
                if (!n.alive) return;
                const ndx = n.x - player.x, ndZ = n.z - player.z;
                const nDist = Math.sqrt(ndx * ndx + ndZ * ndZ);
                const nAngle = Math.atan2(ndZ, ndx);
                let angleDiff = Math.abs(nAngle - aimAngle);
                if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;
                if (nDist < range && angleDiff < 0.15) {
                    n.health -= 1;
                    if (n.health <= 0) {
                        n.alive = false;
                        score -= 200;
                    }
                }
            });

            buildings.forEach(b => {
                if (b.destroyed) return;
                const bdx = b.x - player.x, bdZ = b.z - player.z;
                const bDist = Math.sqrt(bdx * bdx + bdZ * bdZ);
                const bAngle = Math.atan2(bdZ, bdx);
                let angleDiff = Math.abs(bAngle - aimAngle);
                if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;
                if (bDist < range && angleDiff < 0.15) {
                    b.health -= 1;
                    if (b.health <= 0) {
                        b.destroyed = true;
                        b.debrisTimer = 60;
                        spawnExplosion(b.x, 0, b.z, 60, 60);
                    }
                }
            });

            player.energy -= 0.3;
            player.heatVisionCooldown = 2;
            playLaser();
        }
    }
}

function drawFreezeBreath() {
    if (!player.freezeBreath) return;

    const aimAngle = player.angle;
    const range = 250;
    const spread = 0.4;

    const p1 = project(player.x, 0, player.z);
    const p2 = project(player.x + Math.cos(aimAngle) * range, 0, player.z + Math.sin(aimAngle) * range);

    if (p1.visible && p2.visible) {
        ctx.save();
        ctx.globalAlpha = 0.4;
        const gradient = ctx.createLinearGradient(p1.x, p1.y, p2.x, p2.y);
        gradient.addColorStop(0, 'rgba(100,200,255,0.8)');
        gradient.addColorStop(1, 'rgba(200,240,255,0.1)');
        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x + Math.sin(aimAngle) * range * spread, p2.y);
        ctx.lineTo(p2.x - Math.sin(aimAngle) * range * spread, p2.y);
        ctx.closePath();
        ctx.fill();

        // Freeze damage
        if (player.freezeCooldown <= 0) {
            villains.forEach(v => {
                if (!v.alive) return;
                const vdx = v.x - player.x, vdZ = v.z - player.z;
                const vDist = Math.sqrt(vdx * vdx + vdZ * vdZ);
                const vAngle = Math.atan2(vdZ, vdx);
                let angleDiff = Math.abs(vAngle - aimAngle);
                if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;
                if (vDist < range && angleDiff < spread) {
                    v.health -= 1;
                    v.frozen = true;
                    v.frozenTimer = 180;
                    spawnParticles(v.x, 0, v.z, 3, '#88ccff', 2, 20, 3);
                    if (v.health <= 0) {
                        v.alive = false;
                        score += 100;
                        spawnExplosion(v.x, 0, v.z, 40, 30);
                    }
                }
            });
            player.energy -= 0.4;
            player.freezeCooldown = 3;
            playFreeze();
        }
        ctx.restore();
    }
}

function drawExplosions() {
    explosions.forEach(e => {
        if (e.timer <= 0) return;
        const p = project(e.x, e.y, e.z);
        if (!p.visible) return;

        const progress = 1 - e.timer / e.maxTimer;
        const radius = e.maxRadius * p.scale * progress;

        ctx.globalAlpha = (1 - progress) * 0.6;
        const gradient = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, radius);
        gradient.addColorStop(0, '#ffffff');
        gradient.addColorStop(0.3, '#ffaa00');
        gradient.addColorStop(0.7, '#ff4400');
        gradient.addColorStop(1, 'rgba(255,0,0,0)');
        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
    });
}

function drawParticles() {
    particles.forEach(p => {
        if (p.life <= 0) return;
        const pp = project(p.x, p.y, p.z);
        if (!pp.visible) return;

        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(pp.x, pp.y, p.size * pp.scale, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1;
}

function drawClouds() {
    const isNight = dayTime < 0.25 || dayTime > 0.75;
    clouds.forEach(c => {
        const p = project(c.x, c.y, c.z);
        if (!p.visible) return;

        ctx.globalAlpha = c.opacity * (isNight ? 0.3 : 1);
        ctx.fillStyle = isNight ? '#334466' : '#ffffff';
        ctx.beginPath();
        ctx.ellipse(p.x, p.y, c.w * p.scale, c.h * p.scale, 0, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1;
}

function drawSky() {
    const isNight = dayTime < 0.25 || dayTime > 0.75;
    const isDawn = dayTime < 0.35 && dayTime > 0.2;
    const isDusk = dayTime > 0.65 && dayTime < 0.75;

    let skyTop, skyBot;
    if (isNight) {
        skyTop = '#000011';
        skyBot = '#000022';
    } else if (isDawn || isDusk) {
        skyTop = '#1a0a33';
        skyBot = '#ff6633';
    } else {
        skyTop = '#1a3366';
        skyBot = '#6699cc';
    }

    const gradient = ctx.createLinearGradient(0, 0, 0, H);
    gradient.addColorStop(0, skyTop);
    gradient.addColorStop(1, skyBot);
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, W, H);

    // Stars at night
    if (isNight) {
        stars.forEach(s => {
            const sp = project(s.x, 0, s.y);
            if (sp.visible) {
                ctx.globalAlpha = s.brightness * (0.5 + Math.sin(Date.now() * 0.003 + s.x) * 0.5);
                ctx.fillStyle = '#ffffff';
                ctx.beginPath();
                ctx.arc(sp.x, sp.y, s.size * sp.scale, 0, Math.PI * 2);
                ctx.fill();
            }
        });
        ctx.globalAlpha = 1;
    }

    // Sun/Moon
    if (!isNight) {
        const sunAngle = (dayTime - 0.25) * Math.PI * 2;
        const sunX = W / 2 + Math.cos(sunAngle) * W * 0.4;
        const sunY = H * 0.3 - Math.sin(sunAngle) * H * 0.3;
        const sunGrad = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, 60);
        sunGrad.addColorStop(0, 'rgba(255,255,200,1)');
        sunGrad.addColorStop(0.3, 'rgba(255,200,100,0.5)');
        sunGrad.addColorStop(1, 'rgba(255,150,50,0)');
        ctx.fillStyle = sunGrad;
        ctx.beginPath();
        ctx.arc(sunX, sunY, 60, 0, Math.PI * 2);
        ctx.fill();
    }
}

function drawMinimap() {
    miniCtx.fillStyle = '#111122';
    miniCtx.fillRect(0, 0, 200, 200);

    const scale = 200 / WORLD_SIZE;
    const cx = 100, cy = 100;

    // Buildings
    buildings.forEach(b => {
        if (b.destroyed) return;
        const bx = cx + (b.x - player.x) * scale;
        const bz = cy + (b.z - player.z) * scale;
        if (bx > -10 && bx < 210 && bz > -10 && bz < 210) {
            miniCtx.fillStyle = b.destroyed ? '#333' : '#445566';
            miniCtx.fillRect(bx - b.w * scale / 2, bz - b.h * scale / 2, b.w * scale, b.h * scale);
        }
    });

    // Villains
    villains.forEach(v => {
        if (!v.alive) return;
        const vx = cx + (v.x - player.x) * scale;
        const vz = cy + (v.z - player.z) * scale;
        if (vx > 0 && vx < 200 && vz > 0 && vz < 200) {
            miniCtx.fillStyle = v.glowColor;
            miniCtx.beginPath();
            miniCtx.arc(vx, vz, 3, 0, Math.PI * 2);
            miniCtx.fill();
        }
    });

    // NPCs
    npcs.forEach(n => {
        if (!n.alive) return;
        const nx = cx + (n.x - player.x) * scale;
        const nz = cy + (n.z - player.z) * scale;
        if (nx > 0 && nx < 200 && nz > 0 && nz < 200) {
            miniCtx.fillStyle = '#00ff00';
            miniCtx.fillRect(nx - 1, nz - 1, 2, 2);
        }
    });

    // Player
    miniCtx.fillStyle = '#FFD700';
    miniCtx.beginPath();
    miniCtx.arc(cx, cy, 4, 0, Math.PI * 2);
    miniCtx.fill();

    // Player direction
    miniCtx.strokeStyle = '#FFD700';
    miniCtx.lineWidth = 2;
    miniCtx.beginPath();
    miniCtx.moveTo(cx, cy);
    miniCtx.lineTo(cx + Math.cos(player.angle) * 12, cy + Math.sin(player.angle) * 12);
    miniCtx.stroke();

    // Circle border
    miniCtx.strokeStyle = 'rgba(255,255,255,0.3)';
    miniCtx.lineWidth = 1;
    miniCtx.beginPath();
    miniCtx.arc(100, 100, 98, 0, Math.PI * 2);
    miniCtx.stroke();
}

function update() {
    if (!gameStarted) return;

    const speed = player.superSpeed ? 8 : 4;
    const flySpeed = player.flying ? 3 : 1;

    // Movement
    let moveX = 0, moveZ = 0;
    if (keys['w'] || keys['arrowup']) moveZ -= 1;
    if (keys['s'] || keys['arrowdown']) moveZ += 1;
    if (keys['a'] || keys['arrowleft']) moveX -= 1;
    if (keys['d'] || keys['arrowright']) moveX += 1;

    if (moveX !== 0 || moveZ !== 0) {
        const moveAngle = Math.atan2(moveZ, moveX);
        player.x += Math.cos(moveAngle) * speed;
        player.z += Math.sin(moveAngle) * speed;
        player.animFrame++;
    }

    // Flying
    player.flying = keys[' '] && player.energy > 0;
    if (player.flying) {
        player.z += flySpeed;
        player.energy -= 0.1;
        if (player.animFrame % 10 === 0) playFly();
    }

    // Descend
    if (keys['shift']) {
        player.z -= flySpeed;
    }

    // Keep on ground if not flying
    if (!player.flying) {
        player.z = 0;
    }

    // Clamp to world
    player.x = Math.max(-WORLD_SIZE, Math.min(WORLD_SIZE, player.x));
    player.z = Math.max(-WORLD_SIZE, Math.min(WORLD_SIZE, player.z));

    // Camera follow
    camera.x += (player.x - camera.x) * 0.1;
    camera.y += (player.z - camera.y) * 0.1;

    // Camera shake
    if (camera.shakeIntensity > 0) {
        camera.shakeX = (Math.random() - 0.5) * camera.shakeIntensity;
        camera.shakeY = (Math.random() - 0.5) * camera.shakeIntensity;
        camera.shakeIntensity *= 0.9;
        if (camera.shakeIntensity < 0.5) camera.shakeIntensity = 0;
    } else {
        camera.shakeX = 0;
        camera.shakeY = 0;
    }

    // Aim angle
    const aimDx = mouseX - W / 2;
    const aimDy = mouseY - H / 2;
    player.angle = Math.atan2(aimDy, aimDx);

    // Heat vision
    player.heatVision = mouseDown && player.energy > 0 && player.heatVisionCooldown <= 0;

    // Super punch
    if (rightMouseDown && player.punchCooldown <= 0) {
        rightMouseDown = false;
        const punchRange = 80;
        const punchAngle = player.angle;
        const punchX = player.x + Math.cos(punchAngle) * punchRange;
        const punchZ = player.z + Math.sin(punchAngle) * punchRange;

        spawnExplosion(punchX, 0, punchZ, 60, 80);
        player.punchCooldown = 20;

        // Push nearby objects
        villains.forEach(v => {
            if (!v.alive) return;
            const dx = v.x - punchX, dz = v.z - punchZ;
            const dist = Math.sqrt(dx * dx + dz * dz);
            if (dist < 60) {
                v.health -= 50;
                v.stunned = 40;
                v.x += Math.cos(punchAngle) * 100;
                v.z += Math.sin(punchAngle) * 100;
                if (v.health <= 0) {
                    v.alive = false;
                    score += 100;
                    spawnExplosion(v.x, 0, v.z, 50, 50);
                }
            }
        });

        buildings.forEach(b => {
            if (b.destroyed) return;
            const dx = b.x - punchX, dz = b.z - punchZ;
            const dist = Math.sqrt(dx * dx + dz * dz);
            if (dist < 60) {
                b.health -= 50;
                if (b.health <= 0) {
                    b.destroyed = true;
                    b.debrisTimer = 60;
                    spawnExplosion(b.x, 0, b.z, 60, 60);
                }
            }
        });

        playPunch();
    }

    // X-Ray
    player.xrayActive = keys['v'] && player.xrayEnergy > 0;
    if (player.xrayActive) {
        player.xrayEnergy -= 0.3;
    }

    // Super Speed
    player.superSpeed = keys['q'] && player.energy > 10;
    if (player.superSpeed) {
        player.energy -= 0.5;
    }

    // Freeze Breath
    player.freezeBreath = keys['f'] && player.energy > 0 && player.freezeCooldown <= 0;

    // Regenerate
    player.regenActive = keys['r'] && player.energy > 5;
    if (player.regenActive) {
        player.health = Math.min(player.maxHealth, player.health + 0.2);
        player.energy -= 0.2;
    }

    // Energy regen
    if (!player.heatVision && !player.flying && !player.superSpeed && !player.freezeBreath && !player.regenActive) {
        player.energy = Math.min(player.maxEnergy, player.energy + 0.1);
    }
    if (!player.xrayActive) {
        player.xrayEnergy = Math.min(100, player.xrayEnergy + 0.05);
    }

    // Cooldowns
    player.punchCooldown = Math.max(0, player.punchCooldown - 1);
    player.heatVisionCooldown = Math.max(0, player.heatVisionCooldown - 1);
    player.freezeCooldown = Math.max(0, player.freezeCooldown - 1);
    player.invincible = Math.max(0, player.invincible - 1);

    // Villain AI
    villains.forEach(v => {
        if (!v.alive) return;

        if (v.frozen) {
            v.frozenTimer--;
            if (v.frozenTimer <= 0) v.frozen = false;
            return;
        }

        if (v.stunned > 0) {
            v.stunned--;
            return;
        }

        const dx = player.x - v.x, dz = player.z - v.z;
        const dist = Math.sqrt(dx * dx + dz * dz);

        if (dist < 500) {
            v.aiState = 'chase';
            const angle = Math.atan2(dz, dx);
            v.x += Math.cos(angle) * v.speed;
            v.z += Math.sin(angle) * v.speed;
            v.angle = angle;

            // Attack
            if (dist < 100) {
                v.attackTimer++;
                if (v.attackTimer >= v.attackCooldown) {
                    v.attackTimer = 0;
                    if (player.invincible <= 0) {
                        player.health -= v.damage;
                        player.invincible = 30;
                        showDamage();
                        spawnParticles(player.x, 0, player.z, 10, '#ff0000', 5, 20, 3);
                    }
                }
            }
        } else {
            v.aiState = 'patrol';
            v.patrolAngle += 0.01;
            v.x += Math.cos(v.patrolAngle) * v.speed * 0.3;
            v.z += Math.sin(v.patrolAngle) * v.speed * 0.3;
        }
    });

    // Respawn villains
    const aliveVillains = villains.filter(v => v.alive).length;
    if (aliveVillains < 5 + Math.floor(score / 500)) {
        if (Math.random() < 0.005) spawnVillain();
    }

    // NPC AI
    npcs.forEach(n => {
        if (!n.alive) return;

        // Flee from nearby villains
        villains.forEach(v => {
            if (!v.alive) return;
            const dx = n.x - v.x, dz = n.z - v.z;
            const dist = Math.sqrt(dx * dx + dz * dz);
            if (dist < 200) {
                n.fleeing = true;
                n.fleeTimer = 120;
                const angle = Math.atan2(n.z - v.z, n.x - v.x);
                n.x += Math.cos(angle) * 2;
                n.z += Math.sin(angle) * 2;
            }
        });

        // Flee from player if close
        const pdx = n.x - player.x, pdz = n.z - player.z;
        const pDist = Math.sqrt(pdx * pdx + pdz * pdz);
        if (pDist < 150 && !n.fleeing) {
            n.fleeing = true;
            n.fleeTimer = 60;
            const angle = Math.atan2(n.z - player.z, n.x - player.x);
            n.x += Math.cos(angle) * 2;
            n.z += Math.sin(angle) * 2;
        }

        if (n.fleeing) {
            n.fleeTimer--;
            if (n.fleeTimer <= 0) n.fleeing = false;
        } else {
            n.pathTimer--;
            if (n.pathTimer <= 0) {
                n.pathAngle = Math.random() * Math.PI * 2;
                n.pathTimer = 100 + Math.random() * 200;
            }
            n.x += Math.cos(n.pathAngle) * 0.5;
            n.z += Math.sin(n.pathAngle) * 0.5;
        }
    });

    // Vehicle AI
    vehicles.forEach(v => {
        if (!v.moving) return;
        v.x += Math.cos(v.angle) * v.speed;
        v.z += Math.sin(v.angle) * v.speed;

        // Collision with buildings
        buildings.forEach(b => {
            if (b.destroyed) return;
            const dx = v.x - b.x, dz = v.z - b.z;
            const dist = Math.sqrt(dx * dx + dz * dz);
            if (dist < b.w / 2 + v.w / 2) {
                v.angle += Math.PI;
                v.health -= 10;
                if (v.health <= 0) {
                    spawnExplosion(v.x, 0, v.z, 30, 20);
                    v.moving = false;
                }
            }
        });
    });

    // Update particles
    particles.forEach(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.z += p.vz;
        p.vy -= p.gravity;
        p.life--;
    });

    // Update explosions
    explosions.forEach(e => e.timer--);

    // Day/night cycle
    dayTime += daySpeed;
    if (dayTime > 1) dayTime -= 1;

    // Health check
    if (player.health <= 0) {
        player.health = player.maxHealth;
        player.energy = player.maxEnergy;
        player.x = 0;
        player.z = 0;
        score = Math.max(0, score - 500);
        showNotification('DEFEATED! Respawning...');
    }

    // Update HUD
    document.getElementById('healthFill').style.width = (player.health / player.maxHealth * 100) + '%';
    document.getElementById('energyFill').style.width = (player.energy / player.maxEnergy * 100) + '%';
    document.getElementById('xrayFill').style.width = (player.xrayEnergy) + '%';
    document.getElementById('score').textContent = 'SCORE: ' + score;
    document.getElementById('villainCounter').textContent = 'VILLAINS: ' + aliveVillains;
}

function render() {
    ctx.save();
    ctx.translate(camera.shakeX, camera.shakeY);

    drawSky();
    drawClouds();
    drawGround();

    // Sort all objects by distance for proper rendering
    const renderables = [];

    buildings.forEach(b => {
        if (b.destroyed && b.debrisTimer <= 0) return;
        const dx = b.x - player.x, dz = b.z - player.z;
        renderables.push({ type: 'building', obj: b, dist: dx * dx + dz * dz });
    });

    vehicles.forEach(v => {
        if (!v.moving && v.health <= 0) return;
        const dx = v.x - player.x, dz = v.z - player.z;
        renderables.push({ type: 'vehicle', obj: v, dist: dx * dx + dz * dz });
    });

    npcs.forEach(n => {
        if (!n.alive) return;
        const dx = n.x - player.x, dz = n.z - player.z;
        renderables.push({ type: 'npc', obj: n, dist: dx * dx + dz * dz });
    });

    villains.forEach(v => {
        if (!v.alive) return;
        const dx = v.x - player.x, dz = v.z - player.z;
        renderables.push({ type: 'villain', obj: v, dist: dx * dx + dz * dz });
    });

    renderables.sort((a, b) => b.dist - a.dist);

    renderables.forEach(r => {
        switch (r.type) {
            case 'building': drawBuilding(r.obj); break;
            case 'vehicle': drawVehicle(r.obj); break;
            case 'npc': drawNPC(r.obj); break;
            case 'villain': drawVillain(r.obj); break;
        }
    });

    drawPlayer();
    drawHeatVision();
    drawFreezeBreath();
    drawExplosions();
    drawParticles();

    // X-Ray overlay
    if (player.xrayActive) {
        ctx.fillStyle = 'rgba(0,0,50,0.5)';
        ctx.fillRect(0, 0, W, H);

        // Show hidden objects through buildings
        buildings.forEach(b => {
            if (b.destroyed) return;
            const p = project(b.x, 0, b.z);
            if (!p.visible) return;
            ctx.strokeStyle = 'rgba(0,255,255,0.3)';
            ctx.lineWidth = 1;
            ctx.strokeRect(p.x - b.w * p.scale / 2, p.y - b.d * p.scale, b.w * p.scale, b.d * p.scale);
        });

        // Highlight villains
        villains.forEach(v => {
            if (!v.alive) return;
            const p = project(v.x, 0, v.z);
            if (!p.visible) return;
            ctx.strokeStyle = '#ff00ff';
            ctx.lineWidth = 2;
            ctx.strokeRect(p.x - v.w * p.scale / 2, p.y - v.h * p.scale, v.w * p.scale, v.h * p.scale);
        });

        // Highlight NPCs
        npcs.forEach(n => {
            if (!n.alive) return;
            const p = project(n.x, 0, n.z);
            if (!p.visible) return;
            ctx.strokeStyle = '#00ff00';
            ctx.lineWidth = 1;
            ctx.strokeRect(p.x - n.w * p.scale / 2, p.y - n.h * p.scale, n.w * p.scale, n.h * p.scale);
        });
    }

    // Super speed lines
    if (player.superSpeed) {
        speedCtx.clearRect(0, 0, W, H);
        speedCtx.strokeStyle = 'rgba(255,255,0,0.3)';
        speedCtx.lineWidth = 2;
        for (let i = 0; i < 20; i++) {
            const angle = Math.random() * Math.PI * 2;
            const len = 100 + Math.random() * 200;
            speedCtx.beginPath();
            speedCtx.moveTo(W / 2 + Math.cos(angle) * 50, H / 2 + Math.sin(angle) * 50);
            speedCtx.lineTo(W / 2 + Math.cos(angle) * len, H / 2 + Math.sin(angle) * len);
            speedCtx.stroke();
        }
    } else {
        speedCtx.clearRect(0, 0, W, H);
    }

    ctx.restore();

    // Crosshair
    const ch = document.getElementById('crosshair');
    ch.style.left = mouseX + 'px';
    ch.style.top = mouseY + 'px';
    if (player.heatVision) {
        ch.querySelector('.dot').style.background = '#ff4400';
        ch.style.width = '40px';
        ch.style.height = '40px';
    } else if (player.freezeBreath) {
        ch.querySelector('.dot').style.background = '#00ccff';
        ch.style.width = '35px';
        ch.style.height = '35px';
    } else {
        ch.querySelector('.dot').style.background = '#ff0000';
        ch.style.width = '30px';
        ch.style.height = '30px';
    }

    drawMinimap();
}

function gameLoop() {
    update();
    render();
    requestAnimationFrame(gameLoop);
}

function startGame() {
    document.getElementById('titleScreen').style.display = 'none';
    gameStarted = true;
    audioCtx.resume();
    showNotification('SUPERMAN ASSEMBLES!');
    playSound(440, 'sine', 0.5, 0.2);
    setTimeout(() => playSound(550, 'sine', 0.5, 0.2), 200);
    setTimeout(() => playSound(660, 'sine', 0.5, 0.2), 400);
}

gameLoop();
</script>
</body>
