function createEnvironment() {
// Distant structures
for (let i = 0; i < 30; i++) {
const h = Math.random() * 40 + 10;
const geo = new THREE.BoxGeometry(
Math.random() * 10 + 5, h, Math.random() * 10 + 5
);
const mat = new THREE.MeshStandardMaterial({
color: 0x111133, roughness: 0.7, metalness: 0.5,
emissive: 0x000022, emissiveIntensity: 0.2
});
const building = new THREE.Mesh(geo, mat);
const angle = Math.random() * Math.PI * 2;
const dist = Math.random() * 400 + 200;
building.position.set(Math.cos(angle) * dist, h/2 - 10, Math.sin(angle) * dist - 200);
building.castShadow = true;
scene.add(building);

// Glowing windows
for (let w = 0; w < 5; w++) {
const winGeo = new THREE.PlaneGeometry(1, 1.5);
const winMat = new THREE.MeshBasicMaterial({
color: Math.random() > 0.5 ? 0x00ffff : 0xff8800,
transparent: true, opacity: 0.5 + Math.random() * 0.5,
blending: THREE.AdditiveBlending
});
const win = new THREE.Mesh(winGeo, winMat);
win.position.set(
building.position.x + (Math.random() - 0.5) * 8,
Math.random() * h - 5,
building.position.z + 3
);
scene.add(win);
}
}

// Floating debris
for (let i = 0; i < 50; i++) {
const geo = new THREE.DodecahedronGeometry(Math.random() * 2 + 0.5);
const mat = new THREE.MeshStandardMaterial({
color: 0x334455, roughness: 0.6, metalness: 0.4,
emissive: 0x112233, emissiveIntensity: 0.2
});
const debris = new THREE.Mesh(geo, mat);
debris.position.set(
(Math.random() - 0.5) * 300,
Math.random() * 30 + 5,
(Math.random() - 0.5) * 300 - 100
);
debris.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);
debris.userData = {
rotSpeed: { x: (Math.random()-0.5)*0.02, y: (Math.random()-0.5)*0.02 },
floatSpeed: Math.random() * 0.01 + 0.005,
floatOffset: Math.random() * Math.PI * 2
};
