Game.asteroids.push(debris);
}
}

// ==================== ENEMY CREATION ====================
function createEnemy(type) {
let enemy;
const x = (Math.random() - 0.5) * 120;
const z = -100 - Math.random() * 200;

if (type === 0) {
// Basic fighter
const group = new THREE.Group();
const bodyGeo = new THREE.OctahedronGeometry(2, 0);
const bodyMat = new THREE.MeshStandardMaterial({
color: 0xff2200, roughness: 0.3, metalness: 0.7,
emissive: 0x440000, emissiveIntensity: 0.5
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
body.castShadow = true;
group.add(body);

const wingGeo = new THREE.BoxGeometry(6, 0.2, 1.5);
const wingMat = new THREE.MeshStandardMaterial({
color: 0xcc1100, roughness: 0.4, metalness: 0.6
});
const wings = new THREE.Mesh(wingGeo, wingMat);
wings.position.z = 0.5;
group.add(wings);

const light = new THREE.PointLight(0xff2200, 1, 15);
group.add(light);

enemy = group;
enemy.userData = { type: 'fighter', health: 30, maxHealth: 30, speed: 0.3 + Game.difficulty * 0.05, score: 100, shootTimer: 0, shootRate: 120 };

} else if (type === 1) {
// Heavy tank
const group = new THREE.Group();
const bodyGeo = new THREE.BoxGeometry(4, 3, 5);
const bodyMat = new THREE.MeshStandardMaterial({
color: 0xff8800, roughness: 0.4, metalness: 0.8,
emissive: 0x442200, emissiveIntensity: 0.4
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
body.castShadow = true;
group.add(body);

const turretGeo = new THREE.CylinderGeometry(0.8, 1, 2, 8);
const turretMat = new THREE.MeshStandardMaterial({
color: 0xff6600, roughness: 0.3, metalness: 0.7
});
const turret = new THREE.Mesh(turretGeo, turretMat);
turret.position.y = 2;
group.add(turret);

const light = new THREE.PointLight(0xff8800, 1, 20);
group.add(light);

enemy = group;
enemy.userData = { type: 'tank', health: 80, maxHealth: 80, speed: 0.15 + Game.difficulty * 0.02, score: 250, shootTimer: 0, shootRate: 80 };

} else if (type === 2) {
// Fast scout
const group = new THREE.Group();
const bodyGeo = new THREE.TetrahedronGeometry(1.5, 0);
const bodyMat = new THREE.MeshStandardMaterial({
color: 0x00ff44, roughness: 0.2, metalness: 0.9,
emissive: 0x004411, emissiveIntensity: 0.5
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
body.castShadow = true;
group.add(body);

const light = new THREE.PointLight(0x00ff44, 1, 10);
group.add(light);

enemy = group;
enemy.userData = { type: 'scout', health: 15, maxHealth: 15, speed: 0.6 + Game.difficulty * 0.08, score: 150, shootTimer: 0, shootRate: 60 };

} else if (type === 3) {
// Boss
const group = new THREE.Group();
const bodyGeo = new THREE.IcosahedronGeometry(5, 1);
const bodyMat = new THREE.MeshStandardMaterial({
color: 0xff00ff, roughness: 0.2, metalness: 0.9,
emissive: 0x440044, emissiveIntensity: 0.8
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
body.castShadow = true;
group.add(body);

const ringGeo = new THREE.TorusGeometry(7, 0.5, 8, 16);
const ringMat = new THREE.MeshStandardMaterial({
color: 0xff00ff, emissive: 0xff00ff, emissiveIntensity: 0.5,
transparent: true, opacity: 0.7
});
const ring = new THREE.Mesh(ringGeo, ringMat);
group.add(ring);

const light = new THREE.PointLight(0xff00ff, 3, 40);
group.add(light);

enemy = group;
enemy.userData = { type: 'boss', health: 500, maxHealth: 500, speed: 0.1, score: 2000, shootTimer: 0, shootRate: 30, isBoss: true };
}

enemy.position.set(x, Math.random() * 10 + 8, z);
scene.add(enemy);
Game.enemies.push(enemy);
}

// ==================== BULLET CREATION ====================
function createBullet(startPos, direction, isEnemy = false) {
const bulletGeo = new THREE.SphereGeometry(isEnemy ? 0.4 : 0.3, 6, 6);
const bulletMat = new THREE.MeshBasicMaterial({
color: isEnemy ? 0xff4400 : 0x00ffff,
transparent: true, opacity: 0.9,
blending: THREE.AdditiveBlending
});
const bullet = new THREE.Mesh(bulletGeo, bulletMat);
bullet.position.copy(startPos);

const light = new THREE.PointLight(
isEnemy ? 0xff4400 : 0x00ffff, 1, 10
);
bullet.add(light);

bullet.userData = {
velocity: direction.clone().multiplyScalar(isEnemy ? 1.5 : 3),
life: 200, isEnemy: isEnemy
};

scene.add(bullet);
if (isEnemy) Game.enemyBullets.push(bullet);
else Game.bullets.push(bullet);
}

function createExplosion(position, color = 0xff8800, size = 1) {
const particleCount = Math.floor(20 * size);
for (let i = 0; i < particleCount; i++) {
const geo = new THREE.SphereGeometry(0.2 * size, 4, 4);
const mat = new THREE.MeshBasicMaterial({
color: color, transparent: true, opacity: 1,
blending: THREE.AdditiveBlending
});
const particle = new THREE.Mesh(geo, mat);
particle.position.copy(position);

const dir = new THREE.Vector3(
(Math.random() - 0.5) * 2,
(Math.random() - 0.5) * 2,
(Math.random() - 0.5) * 2
).normalize().multiplyScalar(Math.random() * 0.5 + 0.2);

particle.userData = {
velocity: dir, life: 40 + Math.random() * 30,
maxLife: 40 + Math.random() * 30, size: size
};

scene.add(particle);
Game.particles.push(particle);
}

// Shockwave ring
const ringGeo = new THREE.RingGeometry(0.5, 1, 16);
const ringMat = new THREE.MeshBasicMaterial({
color: color, transparent: true, opacity: 0.8,
side: THREE.DoubleSide, blending: THREE.AdditiveBlending
});
const ring = new THREE.Mesh(ringGeo, ringMat);
ring.position.copy(position);
ring.lookAt(camera.position);
ring.userData = { life: 20, maxLife: 20, isRing: true, scale: 1 };
scene.add(ring);
Game.particles.push(ring);
}

function createPowerup(position, type) {
const group = new THREE.Group();
let color, label;

switch(type) {
case 'health': color = 0x00ff00; label = '+HP'; break;
case 'shield': color = 0x0088ff; label = '+SHIELD'; break;
case 'triple': color = 0xff8800; label = 'TRIPLE'; break;
case 'rapid': color = 0xffff00; label = 'RAPID'; break;
case 'invincible': color = 0xffffff; label = 'SHIELD'; break;
}

const geo = new THREE.OctahedronGeometry(1.5, 0);
const mat = new THREE.MeshStandardMaterial({
color: color, emissive: color, emissiveIntensity: 0.8,
transparent: true, opacity: 0.8, roughness: 0.2, metalness: 0.8
});
const mesh = new THREE.Mesh(geo, mat);
group.add(mesh);

const light = new THREE.PointLight(color, 2, 15);
group.add(light);

// Orbiting ring
const ringGeo = new THREE.TorusGeometry(2.2, 0.1, 8, 16);
const ringMat = new THREE.MeshBasicMaterial({
color: color, transparent: true, opacity: 0.5,
blending: THREE.AdditiveBlending
});
const ring = new THREE.Mesh(ringGeo, ringMat);
group.add(ring);

group.position.copy(position);
group.userData = { type: type, life: 600, bobOffset: Math.random() * Math.PI * 2 };
scene.add(group);
Game.powerups.push(group);
}

// ==================== GAME LOGIC ====================
function startGame() {
document.getElementById('startScreen').style.display = 'none';
document.getElementById('gameOverScreen').style.display = 'none';
document.getElementById('hud').style.display = 'flex';
document.getElementById('crosshair').style.display = 'block';
document.getElementById('minimap').style.display = 'block';

Game.score = 0;
Game.health = 100;
Game.shield = 100;
Game.wave = 1;
Game.kills = 0;
Game.combo = 0;
Game.maxCombo = 0;
Game.difficulty = 1;
Game.gameSpeed = 1;
Game.enemies = [];
Game.bullets = [];
Game.particles = [];
Game.powerups = [];
Game.enemyBullets = [];
Game.spawnTimer = 0;
Game.spawnRate = 120;
Game.waveTimer = 0;
Game.paused = false;
Game.running = true;
Game.invincible = false;
Game.tripleShot = false;
Game.rapidFire = false;
Game.powerupActive = null;
Game.powerupTimer = 0;

player.position.set(0, 5, 0);
player.rotation.set(0, 0, 0);
camera.position.set(0, 30, 60);

updateHUD();
announceWave(1);
}

function gameOver() {
Game.running = false;
document.getElementById('gameOverScreen').style.display = 'flex';
document.getElementById('hud').style.display = 'none';
document.getElementById('crosshair').style.display = 'none';
document.getElementById('minimap').style.display = 'none';
document.getElementById('finalScore').textContent = Game.score;
document.getElementById('finalKills').textContent = Game.kills;
document.getElementById('finalWaves').textContent = Game.wave;
document.getElementById('finalCombo').textContent = Game.maxCombo;
}

function togglePause() {
if (!Game.running) return;
Game.paused = !Game.paused;
document.getElementById('pauseScreen').style.display = Game.paused ? 'flex' : 'none';
}

function announceWave(wave) {
const el = document.getElementById('waveAnnounce');
el.textContent = `WAVE ${wave}`;
el.style.opacity = 1;
setTimeout(() => el.style.opacity = 0, 2000);
}

function updateHUD() {
document.getElementById('scoreDisplay').textContent = Game.score.toLocaleString();
document.getElementById('waveDisplay').textContent = Game.wave;
document.getElementById('healthFill').style.width = (Game.health / Game.maxHealth * 100) + '%';
document.getElementById('shieldFill').style.width = (Game.shield / Game.maxShield * 100) + '%';
}

function showDamageFlash() {
const el = document.getElementById('damageFlash');
el.style.opacity = 1;
setTimeout(() => el.style.opacity = 0, 150);
}

function showCombo(combo) {
const el = document.getElementById('comboDisplay');
el.textContent = `${combo}x COMBO!`;
el.style.opacity = 1;
el.style.color = combo > 10 ? '#ff00ff' : combo > 5 ? '#ff8800' : '#ffff00';
}

function showPowerupIndicator(text) {
const el = document.getElementById('powerupIndicator');
el.textContent = text;
el.style.opacity = 1;
setTimeout(() => el.style.opacity = 0, 2000);
}

// ==================== UPDATE ====================
function update() {
if (Game.paused || !Game.running) return;

Game.deltaTime = 1; // simplified
Game.screenShake *= 0.9;

// Player movement
const moveSpeed = Game.boost ? Game.playerSpeed * 2 : Game.playerSpeed;
let moveX = 0, moveZ = 0;

if (keys['KeyW'] || keys['ArrowUp']) moveZ -= moveSpeed;
if (keys['KeyS'] || keys['ArrowDown']) moveZ += moveSpeed;
if (keys['KeyA'] || keys['ArrowLeft']) moveX -= moveSpeed;
if (keys['KeyD'] || keys['ArrowRight']) moveX += moveSpeed;
if (keys['KeyQ']) moveX -= moveSpeed * 0.7;
if (keys['KeyE']) moveX += moveSpeed * 0.7;
if (keys['ShiftLeft'] || keys['ShiftRight']) Game.boost = true;
else Game.boost = false;

player.position.x += moveX;
player.position.z += moveZ;
player.position.y += (5 - player.position.y) * 0.05;

// Clamp player position
player.position.x = Math.max(-80, Math.min(80, player.position.x));
player.position.z = Math.max(-50, Math.min(50, player.position.z));

// Player tilt
player.rotation.z = -moveX * 0.15;
player.rotation.x = moveZ * 0.05;

// Engine particles
if (Math.random() > 0.5) {
const pGeo = new THREE.SphereGeometry(0.15, 4, 4);
const pMat = new THREE.MeshBasicMaterial({
color: 0x00aaff, transparent: true, opacity: 0.6,
blending: THREE.AdditiveBlending
});
const p = new THREE.Mesh(pGeo, pMat);
p.position.copy(player.position);
p.position.z += 4;
p.position.x += (Math.random() - 0.5) * 1;
p.userData = {
velocity: new THREE.Vector3((Math.random()-0.5)*0.1, (Math.random()-0.5)*0.1, 0.5),
life: 20, maxLife: 20
};
scene.add(p);
Game.particles.push(p);
}

// Shooting
const fireRate = Game.rapidFire ? 5 : 12;
Game.spawnTimer--;
if (keys['Space'] && Game.spawnTimer <= 0) {
Game.spawnTimer = fireRate;

const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(player.quaternion);

if (Game.tripleShot) {
for (let i = -1; i <= 1; i++) {
const d = dir.clone();
d.x += i * 0.15;
d.normalize();
createBullet(player.position.clone().add(new THREE.Vector3(0, 0, -3)), d);
}
} else {
createBullet(player.position.clone().add(new THREE.Vector3(0, 0, -3)), dir);
}
}

// Update bullets
for (let i = Game.bullets.length - 1; i >= 0; i--) {
const b = Game.bullets[i];
b.position.add(b.userData.velocity);
b.userData.life--;

if (b.userData.life <= 0) {
scene.remove(b);
Game.bullets.splice(i, 1);
continue;
}

// Check enemy hits
for (let j = Game.enemies.length - 1; j >= 0; j--) {
const e = Game.enemies[j];
if (b.position.distanceTo(e.position) < 4) {
e.userData.health -= 10;
scene.remove(b);
Game.bullets.splice(i, 1);

createExplosion(b.position, 0x00ffff, 0.5);

if (e.userData.health <= 0) {
destroyEnemy(e, j);
}
break;
}
}
}

// Update enemy bullets
for (let i = Game.enemyBullets.length - 1; i >= 0; i--) {
const b = Game.enemyBullets[i];
b.position.add(b.userData.velocity);
b.userData.life--;

if (b.userData.life <= 0) {
scene.remove(b);
Game.enemyBullets.splice(i, 1);
continue;
}

if (b.position.distanceTo(player.position) < 4) {
takeDamage(10);
scene.remove(b);
Game.enemyBullets.splice(i, 1);
createExplosion(b.position, 0xff4400, 0.5);
}
}

// Update enemies
for (let i = Game.enemies.length - 1; i >= 0; i--) {
const e = Game.enemies[i];
const dir = player.position.clone().sub(e.position).normalize();

e.position.x += dir.x * e.userData.speed;
e.position.z += dir.z * e.userData.speed;
e.position.y += Math.sin(Date.now() * 0.001 + i) * 0.05;

// Rotate towards player
e.lookAt(player.position);

// Enemy shooting
e.userData.shootTimer--;
if (e.userData.shootTimer <= 0) {
e.userData.shootTimer = e.userData.shootRate;
const shootDir = player.position.clone().sub(e.position).normalize();

if (e.userData.isBoss) {
// Boss shoots spread
for (let a = -2; a <= 2; a++) {
const d = shootDir.clone();
d.x += a * 0.3;
d.normalize();
createBullet(e.position.clone(), d, true);
}
} else {
createBullet(e.position.clone(), shootDir, true);
}
}

// Collision with player
if (e.position.distanceTo(player.position) < 5) {
takeDamage(e.userData.isBoss ? 30 : 15);
createExplosion(e.position, 0xff4400, 1);
e.userData.health = 0;
destroyEnemy(e, i);
}
}

// Update particles
for (let i = Game.particles.length - 1; i >= 0; i--) {
const p = Game.particles[i];
p.position.add(p.userData.velocity);
p.userData.life--;

if (p.userData.isRing) {
p.userData.scale += 0.15;
p.scale.set(p.userData.scale, p.userData.scale, p.userData.scale);
} else {
p.material.opacity = p.userData.life / p.userData.maxLife;
p.scale.multiplyScalar(0.97);
}

if (p.userData.life <= 0) {
scene.remove(p);
Game.particles.splice(i, 1);
}
}

// Update powerups
for (let i = Game.powerups.length - 1; i >= 0; i--) {
const p = Game.powerups[i];
p.userData.life--;

const bob = Math.sin(Date.now() * 0.003 + p.userData.bobOffset) * 0.5;
p.position.y = p.position.y + bob * 0.02;
p.rotation.y += 0.02;
p.rotation.x += 0.01;

if (p.userData.life <= 0) {
scene.remove(p);
Game.powerups.splice(i, 1);
continue;
}

if (p.position.distanceTo(player.position) < 5) {
applyPowerup(p.userData.type);
scene.remove(p);
Game.powerups.splice(i, 1);
}
}

// Combo timer
if (Game.combo > 0) {
Game.comboTimer--;
if (Game.comboTimer <= 0) {
Game.combo = 0;
document.getElementById('comboDisplay').style.opacity = 0;
}
}

// Powerup timers
if (Game.powerupTimer > 0) {
Game.powerupTimer--;
if (Game.powerupTimer <= 0) {
Game.tripleShot = false;
Game.rapidFire = false;
Game.invincible = false;
showPowerupIndicator('POWERUP EXPIRED');
}
}

// Wave management
Game.waveTimer++;
if (Game.waveTimer >= Game.waveDuration) {
Game.waveTimer = 0;
Game.wave++;
Game.difficulty = 1 + (Game.wave - 1) * 0.2;
Game.spawnRate = Math.max(30, 120 - Game.wave * 8);
announceWave(Game.wave);
}

// Spawn enemies
Game.spawnTimer--;
if (Game.spawnTimer <= 0) {
Game.spawnTimer = Game.spawnRate;
const rand = Math.random();
let type = 0;
if (Game.wave >= 3 && rand > 0.8) type = 2;
if (Game.wave >= 5 && rand > 0.65) type = 1;
if (Game.wave % 5 === 0 && Game.enemies.filter(e => e.userData.isBoss).length === 0) type = 3;

createEnemy(type);
}

// Update floating debris
Game.asteroids.forEach(a => {
a.rotation.x += a.userData.rotSpeed.x;
a.rotation.y += a.userData.rotSpeed.y;
a.position.y += Math.sin(Date.now() * a.userData.floatSpeed + a.userData.floatOffset) * 0.02;
});

// Camera follow
const targetCamPos = new THREE.Vector3(
player.position.x * 0.3,
player.position.y + 25,
player.position.z + 55
);
camera.position.lerp(targetCamPos, 0.03);
camera.lookAt(player.position.x * 0.5, player.position.y, player.position.z - 10);

// Screen shake
if (Game.screenShake > 0.5) {
camera.position.x += (Math.random() - 0.5) * Game.screenShake;
camera.position.y += (Math.random() - 0.5) * Game.screenShake;
}

// Minimap
updateMinimap();
updateHUD();
}

function destroyEnemy(enemy, index) {
const e = enemy.userData;
const pos = enemy.position.clone();

createExplosion(pos, e.isBoss ? 0xff00ff : 0xff4400, e.isBoss ? 3 : 1);
Game.screenShake = e.isBoss ? 8 : 3;

Game.score += e.score * (1 + Game.combo * 0.1);
Game.kills++;
Game.combo++;
Game.comboTimer = 180;
Game.maxCombo = Math.max(Game.maxCombo, Game.combo);

if (Game.combo > 1) showCombo(Game.combo);

// Drop powerup chance
if (Math.random() < (e.isBoss ? 1 : 0.15)) {
const types = ['health', 'shield', 'triple', 'rapid', 'invincible'];
const type = types[Math.floor(Math.random() * types.length)];
createPowerup(pos, type);
}

scene.remove(enemy);
Game.enemies.splice(index, 1);
}

function takeDamage(amount) {
if (Game.invincible) return;

if (Game.shield > 0) {
const shieldAbsorb = Math.min(Game.shield, amount * 0.7);
Game.shield -= shieldAbsorb;
amount -= shieldAbsorb;
}

Game.health -= amount;
showDamageFlash();
Game.screenShake = 4;

if (Game.health <= 0) {
Game.health = 0;
createExplosion(player.position.clone(), 0x00ffff, 2);
gameOver();
}
}

function applyPowerup(type) {
switch(type) {
case 'health':
Game.health = Math.min(Game.maxHealth, Game.health + 30);
showPowerupIndicator('HEALTH RESTORED!');
break;
case 'shield':
Game.shield = Math.min(Game.maxShield, Game.shield + 50);
showPowerupIndicator('SHIELD RECHARGED!');
break;
case 'triple':
Game.tripleShot = true;
Game.powerupTimer = 600;
showPowerupIndicator('TRIPLE SHOT ACTIVATED!');
break;
case 'rapid':
Game.rapidFire = true;
Game.powerupTimer = 600;
showPowerupIndicator('RAPID FIRE ACTIVATED!');
break;
case 'invincible':
Game.invincible = true;
Game.powerupTimer = 300;
showPowerupIndicator('INVINCIBILITY ACTIVATED!');
break;
}
}

function updateMinimap() {
const canvas = document.getElementById('minimapCanvas');
const ctx = canvas.getContext('2d');
ctx.clearRect(0, 0, 150, 150);

// Background
ctx.fillStyle = 'rgba(0,10,30,0.8)';
ctx.beginPath();
ctx.arc(75, 75, 73, 0, Math.PI * 2);
ctx.fill();

// Grid
ctx.strokeStyle = 'rgba(0,255,255,0.1)';
ctx.lineWidth = 0.5;
for (let i = 0; i < 150; i += 25) {
ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 150); ctx.stroke();
ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(150, i); ctx.stroke();
}

// Scale factor
const scale = 0.15;
const cx = 75, cy = 75;

// Enemies
Game.enemies.forEach(e => {
const dx = (e.position.x - player.position.x) * scale + cx;
const dy = (e.position.z - player.position.z) * scale + cy;
if (dx > 0 && dx < 150 && dy > 0 && dy < 150) {
ctx.fillStyle = e.userData.isBoss ? '#ff00ff' : e.userData.type === 'tank' ? '#ff8800' : '#ff2200';
ctx.beginPath();
ctx.arc(dx, dy, e.userData.isBoss ? 4 : 2, 0, Math.PI * 2);
ctx.fill();
}
});

// Powerups
Game.powerups.forEach(p => {
const dx = (p.position.x - player.position.x) * scale + cx;
const dy = (p.position.z - player.position.z) * scale + cy;
if (dx > 0 && dx < 150 && dy > 0 && dy < 150) {
ctx.fillStyle = '#00ff00';
ctx.beginPath();
ctx.arc(dx, dy, 3, 0, Math.PI * 2);
ctx.fill();
}
});

// Player
ctx.fillStyle = '#00ffff';
ctx.beginPath();
ctx.arc(cx, cy, 3, 0, Math.PI * 2);
ctx.fill();

// Player direction
const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(player.quaternion);
ctx.strokeStyle = '#00ffff';
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + dir.x * 10, cy + dir.z * 10);
ctx.stroke();
}

// ==================== RENDER LOOP ====================
function animate() {
update();
renderer.render(scene, camera);
}

// ==================== START ====================
init();
</script>
