  score = 0;
  level = 1;
  lines = 0;
  gameOver = false;
  paused = false;
  dropInterval = 1000;
  dropCounter = 0;
  updateUI();
  spawnPiece();
  setupCamera();
  gameLoop();
}

function restartGame() {
  document.getElementById('overlay').style.display = 'none';
  createBoard();
  score = 0;
  level = 1;
  lines = 0;
  gameOver = false;
  paused = false;
  dropInterval = 1000;
  dropCounter = 0;
  updateUI();
  spawnPiece();
  gameLoop();
}

