    let modeText = game.state === 'DRAFT' ? 'DRAFT' : game.state === 'DRAFT_MATCH' ? 'DRAFT MATCH' :
                   game.state === 'RANKED' ? 'RANKED' : 'QUICK';
    ctx.fillText(modeText, 10, 25);

    // Rank
    ctx.fillStyle = '#FFD700';
    ctx.textAlign = 'center';
    ctx.fillText(game.rankName, W/2, 25);

    // W/L/D
    ctx.fillStyle = '#4CAF50';
    ctx.textAlign = 'right';
    ctx.fillText('W:' + game.wins, W - 10, 18);
    ctx.fillStyle = '#F44336';
    ctx.fillText('L:' + game.losses, W - 10, 32);

    // Timer
    if(game.state === 'PLAYING' || game.state === 'COMBAT') {
        let timerColor = game.turnTimer > 30 ? '#4CAF50' : game.turnTimer > 10 ? '#FF9800' : '#F44336';
        ctx.fillStyle = timerColor;
        ctx.font = 'bold 14px Arial';
