        ctx.fillText('⏱ ' + game.turnTimer + 's', W/2, 55);
    }

    // Phase text
    if(game.phaseTimer > 0) {
        game.phaseTimer--;
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        drawRoundedRect(W/2 - 80, 45, 160, 28, 8);
        ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(game.phaseText, W/2, 63);
    }
}

function drawParticles() {
    game.particles.forEach((p, i) => {
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.1;
        p.life -= 0.02;

        if(p.life > 0) {
            ctx.globalAlpha = p.life;
            if(p.type === 'goal') {
                ctx.fillStyle = '#FFD700';
                ctx.font = p.size * 3 + 'px Arial';
                ctx.fillText('⚽', p.x, p.y);
            } else if(p.type === 'win') {
                ctx.fillStyle = '#4CAF50';
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI*2);
                ctx.fill();
            } else if(p.type === 'lose') {
                ctx.fillStyle = '#F44336';
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI*2);
                ctx.fill();
            }
            ctx.globalAlpha = 1;
        }
    });
    game.particles = game.particles.filter(p => p.life > 0);
}

function drawNotifications() {
    game.notifications.forEach((n, i) => {
        n.y -= 0.5;
        n.life--;
        if(n.life < 30) n.alpha = n.life / 30;

        ctx.globalAlpha = n.alpha;
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        drawRoundedRect(W/2 - 120, n.y - 15, 240, 30, 8);
        ctx.fill();
        ctx.fillStyle = n.color;
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(n.text, W/2, n.y + 3);
        ctx.globalAlpha = 1;
    });
    game.notifications = game.notifications.filter(n => n.life > 0);
}

function drawMenu() {
    // Background
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, W, H);

    // Animated background
    game.animFrame++;
    for(let i=0; i<20; i++) {
        ctx.fillStyle = `rgba(33,150,243,${0.02 + Math.sin(game.animFrame*0.02+i)*0.01})`;
        ctx.fillRect(
            Math.sin(game.animFrame*0.01+i*0.5)*W/2 + W/2,
            Math.cos(game.animFrame*0.008+i*0.3)*H/2 + H/2,
            3, 3
        );
    }

    // Logo
    ctx.fillStyle = '#FFD700';
    ctx.font = 'bold 36px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('⚽ FIFA CARD', W/2, 120);
    ctx.fillStyle = '#fff';
    ctx.fillText('DUEL', W/2, 160);

    // Subtitle
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.font = '12px Arial';
    ctx.fillText('Build Your Dream Team', W/2, 185);

    // Menu tabs
    let tabs = ['PLAY', 'DECK', 'DRAFT', 'SHOP', 'PROFILE'];
    let tabW = W / tabs.length;

    tabs.forEach((tab, i) => {
        let tx = i * tabW;
        let isActive = game.menuTab === i;

        ctx.fillStyle = isActive ? 'rgba(33,150,243,0.3)' : 'rgba(255,255,255,0.05)';
        drawRoundedRect(tx, 200, tabW, 35, 8);
        ctx.fill();

        if(isActive) {
            ctx.strokeStyle = '#2196F3';
            ctx.lineWidth = 2;
            drawRoundedRect(tx, 200, tabW, 35, 8);
            ctx.stroke();
        }

        ctx.fillStyle = isActive ? '#2196F3' : 'rgba(255,255,255,0.6)';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(tab, tx + tabW/2, 222);
    });

    // Tab content
    switch(game.menuTab) {
        case 0: drawMenuPlay(); break;
        case 1: drawMenuDeck(); break;
        case 2: drawMenuDraft(); break;
        case 3: drawMenuShop(); break;
        case 4: drawMenuProfile(); break;
    }

    // Footer
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.font = '10px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('FIFA Card Duel v1.0 | No P2W', W/2, H - 15);
}

