// ============ MAIN GAME LOOP ============
function gameLoop() {
    ctx.clearRect(0, 0, W, H);

    // Screen shake
    if(game.shakeTimer > 0) {
        game.shakeTimer--;
        let sx = (Math.random()-0.5) * game.shakeIntensity;
        let sy = (Math.random()-0.5) * game.shakeIntensity;
        ctx.save();
        ctx.translate(sx, sy);
    }

    switch(game.state) {
        case 'MENU':
            drawMenu();
            break;
        case 'PLAYING':
            drawField();
            drawTopBar();
            drawHand();
            drawParticles();
            drawNotifications();
            break;
        case 'COMBAT':
            drawField();
            drawTopBar();
            drawHand();
            drawCombatScreen();
            drawParticles();
            drawNotifications();
            break;
        case 'GAME_OVER':
            drawField();
            drawTopBar();
            drawHand();
            drawGameOver();
            drawParticles();
            break;
        case 'DRAFT':
            drawDraftScreen();
            drawNotifications();
            break;
        case 'DRAFT_MATCH':
            drawDraftMatchUI();
            drawField();
            drawHand();
            drawParticles();
            drawNotifications();
            break;
    }

    // Flash effect
    if(game.flashTimer > 0) {
        game.flashTimer--;
        ctx.fillStyle = game.flashColor;
        ctx.fillRect(0, 0, W, H);
    }

    // Goal animation
    if(game.goalAnim > 0) {
        game.goalAnim--;
        let alpha = game.goalAnim / 90;
        ctx.fillStyle = game.goalTeam === 'player' ?
            `rgba(33,150,243,${alpha * 0.3})` :
            `rgba(244,67,54,${alpha * 0.3})`;
        ctx.fillRect(0, 0, W, H);

        ctx.fillStyle = `rgba(255,255,255,${alpha})`;
        ctx.font = 'bold 36px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('⚽ GOAL! ⚽', W/2, H/2);
    }

    if(game.shakeTimer > 0) {
        ctx.restore();
    }

    // Update energy
    updateEnergy();

    requestAnimationFrame(gameLoop);
}

// ============ INITIALIZATION ============
function init() {
    game.lastEnergyUpdate = Date.now();
    game.energy = 10;
    game.coins = 5000;
    game.gems = 100;
    game.rank = 0;
    game.rankName = 'Division 10';

    // Load saved data
    try {
        let saved = localStorage.getItem('fifaCardDuel');
        if(saved) {
            let data = JSON.parse(saved);
            game.coins = data.coins || 5000;
            game.gems = data.gems || 100;
            game.wins = data.wins || 0;
            game.losses = data.losses || 0;
            game.draws = data.draws || 0;
            game.rank = data.rank || 0;
            game.bestStreak = data.bestStreak || 0;
            game.totalGoals = data.totalGoals || 0;
            game.totalConceded = data.totalConceded || 0;
            game.energy = data.energy || 10;
            game.matchHistory = data.matchHistory || [];
        }
    } catch(e) {}

    // Auto-save
    setInterval(() => {
        try {
            localStorage.setItem('fifaCardDuel', JSON.stringify({
                coins: game.coins,
                gems: game.gems,
                wins: game.wins,
                losses: game.losses,
                draws: game.draws,
                rank: game.rank,
                bestStreak: game.bestStreak,
                totalGoals: game.totalGoals,
                totalConceded: game.totalConceded,
                energy: game.energy,
                matchHistory: game.matchHistory
            }));
        } catch(e) {}
    }, 5000);

    gameLoop();
}

init();
