  { text: "Respiração profunda", sub: "Parassimpático ativado" }
];

// Background particles
function initBgParticles() {
  bgParticles = [];
  for (let i = 0; i < 60; i++) {
    bgParticles.push({
      x: Math.random() * W,
      y: Math.random() * H,
      r: Math.random() * 2 + 0.5,
      vx: (Math.random() - 0.5) * 0.3,
      vy: (Math.random() - 0.5) * 0.3,
      alpha: Math.random() * 0.3 + 0.05
    });
  }
}
initBgParticles();

function drawBg() {
  bgCtx.fillStyle = '#0a0a0a';
  bgCtx.fillRect(0, 0, W, H);

  // Gradient overlay based on tension
  const tensionRatio = tension / 100;
  const r = Math.floor(20 + tensionRatio * 40);
  const g = Math.floor(10 - tensionRatio * 5);
  const b = Math.floor(20 + (1 - tensionRatio) * 10);
  bgCtx.fillStyle = `rgba(${r},${g},${b},0.3)`;
  bgCtx.fillRect(0, 0, W, H);

  // Background particles
  bgParticles.forEach(p => {
    p.x += p.vx;
    p.y += p.vy;
    if (p.x < 0) p.x = W;
    if (p.x > W) p.x = 0;
    if (p.y < 0) p.y = H;
    if (p.y > H) p.y = 0;

    bgCtx.beginPath();
    bgCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    bgCtx.fillStyle = `rgba(0, 245, 160, ${p.alpha})`;
    bgCtx.fill();
  });

  // Tension lines
  if (tension > 30) {
    const intensity = (tension - 30) / 70;
    for (let i = 0; i < Math.floor(intensity * 15); i++) {
      bgCtx.beginPath();
      const x = Math.random() * W;
      const y = Math.random() * H;
      bgCtx.moveTo(x, y);
      bgCtx.lineTo(x + (Math.random() - 0.5) * 100, y + (Math.random() - 0.5) * 100);
      bgCtx.strokeStyle = `rgba(255, ${Math.floor(50 + Math.random() * 50)}, ${Math.floor(50 + Math.random() * 50)}, ${intensity * 0.15})`;
      bgCtx.lineWidth = 0.5;
      bgCtx.stroke();
    }
  }
}

// Game particles
function spawnParticle(x, y, color, count = 5) {
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = Math.random() * 4 + 2;
    particles.push({
      x, y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      r: Math.random() * 4 + 2,
      color,
      life: 1,
      decay: Math.random() * 0.02 + 0.015
    });
  }
}

function spawnFloatingText(x, y, text, color = '#00f5a0') {
  floatingTexts.push({
