function updateHUD() {
  document.getElementById('energy-val').textContent = Math.round(energy);
  document.getElementById('score-val').textContent = Math.round(score);
  document.getElementById('energy-bar').style.width = energy + '%';
  document.getElementById('tension-fill').style.height = tension + '%';

  // Color energy bar
  const bar = document.getElementById('energy-bar');
  if (energy > 60) {
    bar.style.background = 'linear-gradient(90deg, #00f5a0, #00d9f5)';
  } else if (energy > 30) {
    bar.style.background = 'linear-gradient(90deg, #ffaa00, #ffaa00)';
  } else {
    bar.style.background = 'linear-gradient(90deg, #ff4444, #ff0000)';
  }

  // Tension color
  const tensionFill = document.getElementById('tension-fill');
  if (tension > 70) {
    tensionFill.style.background = 'linear-gradient(to top, #ff0000, #ff0000)';
  } else {
    tensionFill.style.background = 'linear-gradient(to top, #ff4444, #ff0000)';
  }
}

function showMessage(key) {
  const msg = phaseMessages[key];
  if (!msg) return;
  gameState = 'message';
  msgText.textContent = msg.text;
  msgSub.textContent = msg.sub;
  messageOverlay.classList.add('visible');
  messageTimer = msg.duration;
}

function hideMessage() {
  messageOverlay.classList.remove('visible');
  gameState = 'playing';
}

// Click handler
function handleClick(e) {
  if (gameState !== 'playing') return;

  const rect = clickZone.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;

  totalClicks++;
  combo++;
  if (combo > maxCombo) maxCombo = combo;

  // Energy gain (less as tension increases)
  const tensionPenalty = tension / 100;
  const energyGain = (3 + combo * 0.5) * (1 - tensionPenalty * 0.7);
  energy = Math.min(100, energy + energyGain);

  // Score
  const comboMultiplier = 1 + Math.floor(combo / 5) * 0.5;
  const scoreGain = Math.round((10 + combo * 2) * comboMultiplier);
  score += scoreGain;

  // Tension increases with each click
  tension = Math.min(100, tension + 2.5 + combo * 0.3);

  // Visual feedback
  spawnParticle(cx, cy, '#00f5a0', 8 + combo);
  spawnFloatingText(cx + (Math.random() - 0.5) * 60, cy - 30, '+' + scoreGain);

  // Streak dots
  updateStreakBar();

  // Combo display
  if (combo >= 5) {
    comboDisplay.textContent = `🔥 ${combo}x COMBO`;
    comboDisplay.classList.add('visible');
  }

  // Shake at high tension
  if (tension > 70) {
    shakeAmount = (tension - 70) / 30 * 5;
  }

  // Pulse
  pulseIntensity = Math.min(1, combo / 20);

  // Phase transitions
  if (phase === 1 && tension > 40) {
    phase = 2;
    phaseIndicator.textContent = 'Fase 2 — Acúmulo';
    showMessage(2);
  } else if (phase === 2 && tension > 65) {
    phase = 3;
    phaseIndicator.textContent = 'Fase 3 — Consequência';
    showMessage(3);
  }

  // Recovery button appears when tension is high
  if (tension > 50) {
    recoveryBtn.classList.add('visible');
  }

  updateHUD();
}

function doRecovery() {
  if (gameState !== 'playing' || recoveryCooldown || tension < 30) return;

  recoveryCooldown = true;
  recoveryCount++;

  // Recovery effects
  const tensionReduce = 25 + Math.random() * 15;
  tension = Math.max(0, tension - tensionReduce);
  energy = Math.min(100, energy + 15);
  combo = 0;
  comboDisplay.classList.remove('visible');

  // Score bonus for recovering
  const bonus = Math.round(tensionReduce * 5);
  score += bonus;

  // Visual
  const rect = recoveryBtn.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  spawnParticle(cx, cy, '#00d9f5', 20);
  spawnFloatingText(cx, cy - 40, `+${bonus} BÔNUS`, '#00d9f5');

  // Recovery message
  const rm = recoveryMessages[Math.floor(Math.random() * recoveryMessages.length)];
  msgText.textContent = rm.text;
  msgSub.textContent = rm.sub;
  messageOverlay.classList.add('visible');
  messageTimer = 2000;

  // Phase transition to 4
  if (phase < 4) {
    phase = 4;
    phaseIndicator.textContent = 'Fase 4 — Recuperação';
  }

  // Cooldown
  recoveryBtn.classList.add('cooldown');
  setTimeout(() => {
    recoveryBtn.classList.remove('cooldown');
    recoveryCooldown = false;
  }, 3000);

  updateHUD();
}

function updateStreakBar() {
  streakBar.innerHTML = '';
  const dots = Math.min(10, Math.floor(combo / 3));
  for (let i = 0; i < 10; i++) {
    const dot = document.createElement('div');
    dot.className = 'streak-dot' + (i < dots ? ' active' : '');
    streakBar.appendChild(dot);
  }
  if (combo >= 3) {
    streakBar.classList.add('visible');
  } else {
    streakBar.classList.remove('visible');
  }
}

// Game loop
function gameLoop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;

  if (dt > 100) {
    requestAnimationFrame(gameLoop);
    return;
  }

  drawBg();

  if (gameState === 'playing') {
    // Natural tension decay (very slow)
    tension = Math.max(0, tension - 0.01);

    // Natural energy decay
    energy = Math.max(0, energy - 0.03);

    // Phase 1 intro message
    if (phase === 1 && totalClicks === 0 && score === 0) {
      showMessage(1);
    }

    // End condition: energy hits 0
    if (energy <= 0) {
      endGame();
    }

    // Update particles
    particles = particles.filter(p => {
      p.x += p.vx;
      p.y += p.vy;
      p.vx *= 0.96;
      p.vy *= 0.96;
      p.life -= p.decay;
      return p.life > 0;
    });

    floatingTexts = floatingTexts.filter(ft => {
      ft.y += ft.vy;
      ft.life -= 0.02;
      return ft.life > 0;
    });

    // Shake decay
    shakeAmount *= 0.9;
    pulseIntensity *= 0.95;

    updateHUD();
  }

  if (gameState === 'message') {
    messageTimer -= dt;
    if (messageTimer <= 0) {
      hideMessage();
    }
  }

  // Draw game particles
  particles.forEach(p => {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r * p.life, 0, Math.PI * 2);
    ctx.fillStyle = p.color;
    ctx.globalAlpha = p.life;
    ctx.fill();
    ctx.globalAlpha = 1;
  });

  // Draw floating texts
  floatingTexts.forEach(ft => {
    ctx.font = `bold ${14 + (1 - ft.life) * 10}px Inter`;
    ctx.fillStyle = ft.color;
    ctx.globalAlpha = ft.life;
    ctx.textAlign = 'center';
    ctx.fillText(ft.text, ft.x, ft.y);
    ctx.globalAlpha = 1;
  });

  // Screen shake
  if (shakeAmount > 0.5) {
    const sx = (Math.random() - 0.5) * shakeAmount;
    const sy = (Math.random() - 0.5) * shakeAmount;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.restore();
  }

  // Pulse effect
  if (pulseIntensity > 0.05) {
    const cx = W / 2;
    const cy = H / 2;
    const radius = 90 + pulseIntensity * 30;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(0, 245, 160, ${pulseIntensity * 0.3})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  requestAnimationFrame(gameLoop);
}

function startGame() {
  document.getElementById('start-screen').classList.add('hidden');
  document.getElementById('end-screen').classList.add('hidden');
  hud.style.display = 'flex';
  energyBarContainer.style.display = 'block';
  tensionMeter.style.display = 'block';
  tensionLabel.style.display = 'block';
  phaseIndicator.style.display = 'block';
  clickZone.style.display = 'flex';
  recoveryBtn.classList.remove('visible');

  energy = 100;
  score = 0;
  tension = 0;
  combo = 0;
  maxCombo = 0;
  recoveryCount = 0;
  totalClicks = 0;
  phase = 1;
  particles = [];
  floatingTexts = [];
  shakeAmount = 0;
  pulseIntensity = 0;
  recoveryCooldown = false;

  phaseIndicator.textContent = 'Fase 1 — Tensão';
  updateHUD();
  gameState = 'playing';

  setTimeout(() => showMessage(1), 500);
}

function endGame() {
  gameState = 'end';
  clickZone.style.display = 'none';
  recoveryBtn.classList.remove('visible');
  messageOverlay.classList.remove('visible');

  const efficiency = totalClicks > 0 ? Math.round((score / (totalClicks * 10)) * 100) : 0;
  const cappedEff = Math.min(99, Math.max(5, efficiency));

  document.getElementById('final-score').textContent = Math.round(score);
  document.getElementById('final-recovery').textContent = recoveryCount;
  document.getElementById('final-combo').textContent = maxCombo + 'x';
  document.getElementById('final-efficiency').textContent = cappedEff + '%';

  setTimeout(() => {
    document.getElementById('end-screen').classList.remove('hidden');
  }, 500);
}

// Event listeners
document.getElementById('start-btn').addEventListener('click', startGame);
document.getElementById('restart-btn').addEventListener('click', startGame);
clickZone.addEventListener('click', handleClick);
clickZone.addEventListener('touchstart', (e) => { e.preventDefault(); handleClick(e); });
recoveryBtn.addEventListener('click', doRecovery);

// Start loop
requestAnimationFrame(gameLoop);
</script>
</body>
</html>
