    project(point) {
        let dir = point.sub(this.pos);
        let forward = this.target.sub(this.pos).norm();
        let right = forward.cross(new Vec3(0,1,0)).norm();
        let up = right.cross(forward).norm();
        let x = dir.dot(right);
        let y = dir.dot(up);
        let z = dir.dot(forward);
        if(z <= 0.1) return null;
        let fovRad = this.fov * Math.PI / 180;
        let f = W / (2 * Math.tan(fovRad/2));
        let sx = W/2 + x * f / z;
        let sy = H/2 - y * f / z;
        return {x: sx, y: sy, z: z};
    }
