            {x:1,y:6,z:-5,w:2.5,h:0.3,d:2.5,color:'#6a3a6a'},
            {x:-3,y:5,z:-4,w:3,h:0.3,d:3,color:'#5a2a5a'},
            {x:-5,y:3.5,z:-1,w:2.5,h:0.3,d:2.5,color:'#6a3a6a'},
            {x:-3,y:2,z:2,w:3,h:0.3,d:3,color:'#5a2a5a'},
            {x:0,y:1,z:5,w:2.5,h:0.3,d:2.5,color:'#6a3a6a'},
            {x:3,y:7,z:0,w:3,h:0.3,d:3,color:'#7a4a7a'},
            {x:0,y:8,z:-3,w:2.5,h:0.3,d:2.5,color:'#6a3a6a'},
            {x:-2,y:7,z:-6,w:2.5,h:0.3,d:2.5,color:'#7a4a7a'},
        ], coins: [
            {x:4,y:2.5,z:3},{x:7,y:4,z:0},{x:5,y:5.5,z:-3},
            {x:1,y:7,z:-5},{x:-3,y:6,z:-4},{x:-5,y:4.5,z:-1},
            {x:-3,y:3,z:2},{x:0,y:2,z:5},{x:3,y:8,z:0},
            {x:0,y:9,z:-3},{x:-2,y:8,z:-6},{x:0,y:1,z:0},
            {x:2,y:1,z:2},{x:-1,y:1,z:-1},
        ], enemies: [
            {x:5,y:4.5,z:-3,range:1,speed:2.5},
            {x:-3,y:5,z:-4,range:1.2,speed:2},
            {x:0,y:8,z:-3,range:1,speed:2.8},
            {x:-2,y:7,z:-6,range:1,speed:2.2},
        ]}
    ];

    let cfg = configs[(lvl-1) % configs.length];
    document.getElementById('zone').textContent = cfg.name;
    game.skyColor = cfg.sky;
    game.fogColor = cfg.fog;

    cfg.platforms.forEach(p => {
        game.platforms.push(new Platform(p.x, p.y, p.z, p.w, p.h, p.d, p.color));
    });
    cfg.coins.forEach(c => {
        game.coins.push(new Coin(c.x, c.y, c.z));
    });
    cfg.enemies.forEach(e => {
        game.enemies.push(new Enemy(e.x, e.y, e.z, e.range, e.speed));
    });

    // Add some floating decorative platforms
    for(let i = 0; i < 5; i++) {
        let px = (Math.random()-0.5)*20;
        let pz = (Math.random()-0.5)*20;
        let py = Math.random()*8+2;
        game.platforms.push(new Platform(px, py, pz, 1+Math.random()*2, 0.2, 1+Math.random()*2, '#333344', 'decoration'));
    }
}

function spawnParticles(x,y,z,count,color,speed,life) {
    for(let i=0;i<count;i++){
        game.particles.push(new Particle(
            x,y,z,
            (Math.random()-0.5)*speed,
            Math.random()*speed,
            (Math.random()-0.5)*speed,
            life*(0.5+Math.random()*0.5),
            color,
            2+Math.random()*3
        ));
    }
}

function showMessage(text, duration=2000) {
    let el = document.getElementById('message');
    el.textContent = text;
    el.style.opacity = 1;
    game.messageTimer = duration;
}

// Input
document.addEventListener('keydown', e => {
    game.keys[e.code] = true;
    if(e.code === 'Space') e.preventDefault();
});
document.addEventListener('keyup', e => { game.keys[e.code] = false; });
document.addEventListener('mousemove', e => {
    if(document.pointerLockElement === canvas) {
        game.cameraAngleX -= e.movementX * 0.003;
        game.cameraAngleY = Math.max(-0.5, Math.min(1.2, game.cameraAngleY + e.movementY * 0.003));
    }
});
canvas.addEventListener('click', () => {
    if(game.running) canvas.requestPointerLock();
});

document.getElementById('start-btn').addEventListener('click', () => {
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('hud').style.display = 'flex';
    document.getElementById('minimap').style.display = 'block';
