    game.camera.pos = new Vec3(0, 5, 10);
    createLevel(game.level);
    showMessage('LEVEL ' + game.level, 2000);
    canvas.requestPointerLock();
});

function checkCollision(player, platform) {
    let b = player;
    let p = platform;
    let pb = p.getBounds();

    let playerMinX = b.pos.x - b.width/2;
    let playerMaxX = b.pos.x + b.width/2;
    let playerMinY = b.pos.y - b.height/2;
    let playerMaxY = b.pos.y + b.height/2;
    let playerMinZ = b.pos.z - b.width/2;
    let playerMaxZ = b.pos.z + b.width/2;

    if(playerMaxX < pb.minX || playerMinX > pb.maxX) return false;
    if(playerMaxY < pb.minY || playerMinY > pb.maxY) return false;
    if(playerMaxZ < pb.minZ || playerMinZ > pb.maxZ) return false;
    return true;
}

function update(dt) {
    if(!game.running) return;
    game.time += dt;

    let p = game.player;
    let speed = p.sprinting ? 8 : 5;
    let moveDir = new Vec3(0,0,0);

    if(game.keys['KeyW'] || game.keys['ArrowUp']) moveDir.z -= 1;
    if(game.keys['KeyS'] || game.keys['ArrowDown']) moveDir.z += 1;
    if(game.keys['KeyA'] || game.keys['ArrowLeft']) moveDir.x -= 1;
    if(game.keys['KeyD'] || game.keys['ArrowRight']) moveDir.x += 1;
    p.sprinting = game.keys['ShiftLeft'] || game.keys['ShiftRight'];

    if(moveDir.len() > 0) moveDir = moveDir.norm();

    // Rotate movement by camera angle
    let cos = Math.cos(game.cameraAngleX);
    let sin = Math.sin(game.cameraAngleX);
    let rx = moveDir.x * cos - moveDir.z * sin;
    let rz = moveDir.x * sin + moveDir.z * cos;

    p.vel.x = rx * speed;
    p.vel.z = rz * speed;

    // Jump
    if((game.keys['Space']) && p.onGround && p.jumpTimer <= 0) {
        p.vel.y = 10;
        p.onGround = false;
        p.jumpTimer = 0.3;
        spawnParticles(p.pos.x, p.pos.y - p.height/2, p.pos.z, 8, '#88ccff', 3, 0.5);
    }
    if(p.jumpTimer > 0) p.jumpTimer -= dt;

    // Gravity
    p.vel.y -= 25 * dt;

    // Move
    let oldPos = p.pos;
    p.pos.x += p.vel.x * dt;
    p.pos.y += p.vel.y * dt;
    p.pos.z += p.vel.z * dt;

    // Platform collision
    p.onGround = false;
    for(let plat of game.platforms) {
        if(plat.type === 'decoration') continue;
        if(checkCollision(p, plat)) {
            let pb = plat.getBounds();

            // Landing on top
            if(oldPos.y - p.height/2 >= pb.maxY - 0.1 && p.vel.y <= 0) {
                p.pos.y = pb.maxY + p.height/2;
                p.vel.y = 0;
                p.onGround = true;
            }
            // Hitting from below
            else if(oldPos.y + p.height/2 <= pb.minY + 0.1 && p.vel.y > 0) {
                p.pos.y = pb.minY - p.height/2;
                p.vel.y = 0;
            }
            // Side collision
            else {
                if(oldPos.x + p.width/2 < pb.minX + 0.1) p.pos.x = pb.minX - p.width/2;
                else if(oldPos.x - p.width/2 > pb.maxX - 0.1) p.pos.x = pb.maxX + p.width/2;
                if(oldPos.z + p.width/2 < pb.minZ + 0.1) p.pos.z = pb.minZ - p.width/2;
                else if(oldPos.z - p.width/2 > pb.maxZ - 0.1) p.pos.z = pb.maxZ + p.width/2;
                p.vel.x = 0;
                p.vel.z = 0;
            }
        }
    }

    // Fall death
    if(p.pos.y < -10) {
        p.health -= 30;
        p.pos.y = 5;
        p.pos.x = 0;
        p.pos.z = 0;
        p.vel = new Vec3(0,0,0);
        spawnParticles(0,5,0,15,'#ff3333',5,1);
        showMessage('FELL! -30 HP', 1500);
    }

    // Invincibility
    if(p.invincible > 0) p.invincible -= dt;

    // Coin collection
    for(let coin of game.coins) {
        if(coin.collected) continue;
        let dist = p.pos.sub(coin.pos).len();
        if(dist < 1) {
            coin.collected = true;
            p.coins++;
            p.score += 100;
            spawnParticles(coin.pos.x, coin.pos.y, coin.pos.z, 12, '#ffd700', 4, 0.8);
        }
    }

    // Enemy collision
    for(let enemy of game.enemies) {
        if(!enemy.alive) continue;
        enemy.update(dt);
        let dist = p.pos.sub(enemy.pos).len();
        if(dist < 1.2 && p.invincible <= 0) {
            p.health -= 20;
            p.invincible = 1.5;
            p.vel = p.pos.sub(enemy.pos).norm().mul(8);
            p.vel.y = 5;
            spawnParticles(p.pos.x, p.pos.y, p.pos.z, 10, '#ff3366', 4, 0.6);
        }
        // Stomp enemy
        if(p.vel.y < -2 && p.pos.y - p.height/2 < enemy.pos.y + 0.3 && dist < 1) {
            enemy.alive = false;
            p.score += 200;
            p.vel.y = 8;
            spawnParticles(enemy.pos.x, enemy.pos.y, enemy.pos.z, 20, enemy.color, 5, 1);
        }
    }

    // Check level complete
    let allCoinsCollected = game.coins.every(c => c.collected);
    if(allCoinsCollected && game.coins.length > 0) {
        game.level++;
        p.score += 500;
        showMessage('LEVEL COMPLETE! +500 BONUS', 2500);
        spawnParticles(p.pos.x, p.pos.y+2, p.pos.z, 30, '#00ff88', 6, 1.5);
        createLevel(game.level);
        p.pos = new Vec3(0, 2, 0);
        p.vel = new Vec3(0,0,0);
    }

    // Health check
    if(p.health <= 0) {
        game.running = false;
        document.getElementById('final-score').textContent = 'Score: ' + p.score + ' | Coins: ' + p.coins;
        document.getElementById('death-screen').style.display = 'flex';
        document.exitPointerLock();
        return;
    }

    // Trail
    if(game.time % 0.02 < dt) {
        p.trail.push({x: p.pos.x, y: p.pos.y, z: p.pos.z, life: 0.5});
    }
    p.trail = p.trail.filter(t => { t.life -= dt; return t.life > 0; });

    // Particles
    game.particles = game.particles.filter(part => {
        part.pos.x += part.vel.x * dt;
        part.pos.y += part.vel.y * dt;
        part.pos.z += part.vel.z * dt;
        part.vel.y -= 10 * dt;
        part.life -= dt;
        return part.life > 0;
    });

    // Camera
    let camTarget = p.pos.add(new Vec3(0, 2, 0));
    game.camera.pos.x = camTarget.x + Math.sin(game.cameraAngleX) * game.cameraDist * Math.cos(game.cameraAngleY);
    game.camera.pos.y = camTarget.y + Math.sin(game.cameraAngleY) * game.cameraDist;
    game.camera.pos.z = camTarget.z + Math.cos(game.cameraAngleX) * game.cameraDist * Math.cos(game.cameraAngleY);
    game.camera.lookAt(camTarget);

    // Message timer
    if(game.messageTimer > 0) {
        game.messageTimer -= dt * 1000;
        if(game.messageTimer <= 0) {
            document.getElementById('message').style.opacity = 0;
        }
    }

    // Update HUD
    document.getElementById('score').textContent = p.score;
    document.getElementById('coins').textContent = p.coins;
    document.getElementById('level').textContent = game.level;
    document.getElementById('health-fill').style.width = Math.max(0, p.health) + '%';
}

function render() {
    ctx.clearRect(0, 0, W, H);

    // Sky gradient
    let skyGrad = ctx.createLinearGradient(0, 0, 0, H);
    skyGrad.addColorStop(0, game.skyColor);
    skyGrad.addColorStop(1, '#000005');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, W, H);

    let cam = game.camera;
    let p = game.player;

    // Stars
    for(let star of game.stars) {
        let sp = cam.project(new Vec3(star.x, star.y, star.z));
        if(sp && sp.z > 0) {
            let alpha = star.brightness * (0.5 + 0.5 * Math.sin(game.time * 2 + star.x));
            ctx.fillStyle = `rgba(255,255,255,${alpha})`;
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, star.size, 0, Math.PI*2);
            ctx.fill();
        }
    }

    // Collect all renderable objects with depth
    let renderList = [];

    // Platforms
    for(let plat of game.platforms) {
        let corners = [
            new Vec3(-plat.w/2, -plat.h/2, -plat.d/2),
            new Vec3(plat.w/2, -plat.h/2, -plat.d/2),
            new Vec3(plat.w/2, -plat.h/2, plat.d/2),
            new Vec3(-plat.w/2, -plat.h/2, plat.d/2),
            new Vec3(-plat.w/2, plat.h/2, -plat.d/2),
            new Vec3(plat.w/2, plat.h/2, -plat.d/2),
            new Vec3(plat.w/2, plat.h/2, plat.d/2),
            new Vec3(-plat.w/2, plat.h/2, plat.d/2),
        ];
        let worldCorners = corners.map(c => c.add(plat.pos));
        let screenCorners = worldCorners.map(c => cam.project(c));

        if(screenCorners.some(s => s === null)) continue;

        let avgZ = worldCorners.reduce((s,c) => s + c.sub(cam.pos).dot(cam.target.sub(cam.pos).norm()), 0) / 8;

        // Draw faces
        let faces = [
            {verts: [0,1,2,3], normal: new Vec3(0,-1,0)}, // bottom
            {verts: [4,5,6,7], normal: new Vec3(0,1,0)},  // top
            {verts: [0,1,5,4], normal: new Vec3(0,0,-1)}, // back
            {verts: [3,2,6,7], normal: new Vec3(0,0,1)},  // front
            {verts: [0,3,7,4], normal: new Vec3(-1,0,0)}, // left
            {verts: [1,2,6,5], normal: new Vec3(1,0,0)},  // right
        ];

        let lightDir = new Vec3(0.5, 1, 0.3).norm();

        for(let face of faces) {
            let projected = face.verts.map(v => screenCorners[v]);
            if(projected.some(s => s === null)) continue;

            let worldNormal = face.normal;
            let brightness = Math.max(0.15, worldNormal.dot(lightDir) * 0.6 + 0.4);

            // Parse base color
            let r = parseInt(plat.color.slice(1,3),16);
            let g = parseInt(plat.color.slice(3,5),16);
            let b = parseInt(plat.color.slice(5,7),16);

            // Glow effect for normal platforms
            if(plat.type !== 'decoration') {
                plat.glow += plat.glowDir * 0.02;
                if(plat.glow > 1 || plat.glow < 0) plat.glowDir *= -1;
                r = Math.min(255, r + 20 * plat.glow);
                g = Math.min(255, g + 20 * plat.glow);
                b = Math.min(255, b + 30 * plat.glow);
            }

            r = Math.floor(r * brightness);
            g = Math.floor(g * brightness);
            b = Math.floor(b * brightness);

            // Fog
            let fogDist = Math.min(1, avgZ / 60);
            let fr = Math.floor(r + (parseInt(game.fogColor.slice(1,3),16)-r)*fogDist);
            let fg = Math.floor(g + (parseInt(game.fogColor.slice(3,5),16)-g)*fogDist);
            let fb = Math.floor(b + (parseInt(game.fogColor.slice(5,7),16)-b)*fogDist);

            ctx.fillStyle = `rgb(${fr},${fg},${fb})`;
            ctx.strokeStyle = `rgba(${Math.min(255,fr+30)},${Math.min(255,fg+30)},${Math.min(255,fb+30)},0.3)`;
            ctx.lineWidth = 0.5;

            ctx.beginPath();
            ctx.moveTo(projected[0].x, projected[0].y);
            for(let i=1;i<projected.length;i++) {
                ctx.lineTo(projected[i].x, projected[i].y);
            }
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
        }

        renderList.push({z: avgZ, type: 'plat', plat: plat});
    }

    // Coins
    for(let coin of game.coins) {
        if(coin.collected) continue;
        let bobY = Math.sin(game.time * 3 + coin.bobOffset) * 0.2;
        let coinPos = coin.pos.add(new Vec3(0, bobY, 0));
        let sp = cam.project(coinPos);
        if(sp && sp.z > 0) {
            let dist = coinPos.sub(cam.pos).len();
            let fogDist = Math.min(1, dist / 60);
            let size = Math.max(2, (coin.size * 80 / sp.z) * (1 - fogDist * 0.5));

            let glow = 0.5 + 0.5 * Math.sin(game.time * 5 + coin.bobOffset);

            // Glow
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, size * 2, 0, Math.PI*2);
            ctx.fillStyle = `rgba(255,215,0,${0.15 * glow})`;
            ctx.fill();

            // Coin body
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, size, 0, Math.PI*2);
            ctx.fillStyle = `rgb(${200+55*glow},${180+35*glow},${0})`;
            ctx.fill();
            ctx.strokeStyle = `rgba(255,255,200,${0.5+0.3*glow})`;
            ctx.lineWidth = 1;
            ctx.stroke();

            // Dollar sign
            if(size > 5) {
                ctx.fillStyle = `rgba(255,255,200,${0.6+0.3*glow})`;
                ctx.font = `${size}px Arial`;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText('$', sp.x, sp.y+1);
            }

            renderList.push({z: dist, type: 'coin', sp: sp});
        }
    }

    // Enemies
    for(let enemy of game.enemies) {
        if(!enemy.alive) continue;
        let sp = cam.project(enemy.pos);
        if(sp && sp.z > 0) {
            let dist = enemy.pos.sub(cam.pos).len();
            let fogDist = Math.min(1, dist / 60);
            let size = Math.max(3, (0.6 * 80 / sp.z) * (1 - fogDist * 0.5));

            // Glow
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, size * 2.5, 0, Math.PI*2);
            ctx.fillStyle = `rgba(255,50,100,${0.1 + 0.05*Math.sin(game.time*4)})`;
            ctx.fill();

            // Body
            let r = parseInt(enemy.color.slice(1,3),16);
            let g = parseInt(enemy.color.slice(3,5),16);
            let b = parseInt(enemy.color.slice(5,7),16);

            ctx.fillStyle = `rgb(${r},${g},${b})`;
            ctx.beginPath();
            // Spiky shape
            for(let i = 0; i < 8; i++) {
                let angle = (i / 8) * Math.PI * 2 + game.time * 2;
                let r2 = i % 2 === 0 ? size * 1.2 : size * 0.6;
                let px = sp.x + Math.cos(angle) * r2;
                let py = sp.y + Math.sin(angle) * r2;
                if(i === 0) ctx.moveTo(px, py);
                else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.fill();

            // Eyes
            let eyeSize = size * 0.25;
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.arc(sp.x - size*0.25, sp.y - size*0.1, eyeSize, 0, Math.PI*2);
            ctx.arc(sp.x + size*0.25, sp.y - size*0.1, eyeSize, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.arc(sp.x - size*0.2, sp.y - size*0.1, eyeSize*0.5, 0, Math.PI*2);
            ctx.arc(sp.x + size*0.3, sp.y - size*0.1, eyeSize*0.5, 0, Math.PI*2);
            ctx.fill();

            renderList.push({z: dist, type: 'enemy'});
        }
    }

    // Player trail
    for(let t of p.trail) {
        let sp = cam.project(new Vec3(t.x, t.y, t.z));
        if(sp && sp.z > 0) {
            let alpha = t.life * 0.3;
            let size = Math.max(1, 3 * sp.z / 10);
            ctx.fillStyle = `rgba(0,200,255,${alpha})`;
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, size, 0, Math.PI*2);
            ctx.fill();
        }
    }

    // Player
    if(p.invincible <= 0 || Math.floor(game.time * 10) % 2 === 0) {
        let sp = cam.project(p.pos);
        if(sp && sp.z > 0) {
            let dist = p.pos.sub(cam.pos).len();
            let fogDist = Math.min(1, dist / 60);
            let pw = Math.max(3, (p.width * 80 / sp.z) * (1 - fogDist * 0.5));
            let ph = Math.max(5, (p.height * 80 / sp.z) * (1 - fogDist * 0.5));

            // Shadow
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath();
            ctx.ellipse(sp.x, sp.y + ph*0.5, pw*0.8, pw*0.3, 0, 0, Math.PI*2);
            ctx.fill();

            // Body glow
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, pw*2, 0, Math.PI*2);
            ctx.fillStyle = 'rgba(0,200,255,0.1)';
            ctx.fill();

            // Body
            ctx.fillStyle = '#00ccff';
            ctx.fillRect(sp.x - pw/2, sp.y - ph/2, pw, ph);

            // Head
            ctx.fillStyle = '#00eeff';
            let headSize = pw * 0.7;
            ctx.beginPath();
            ctx.arc(sp.x, sp.y - ph/2 - headSize/2, headSize/2, 0, Math.PI*2);
            ctx.fill();

            // Visor
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(sp.x - pw*0.3, sp.y - ph/2 - headSize*0.6, pw*0.6, headSize*0.25);

            // Legs
            let legAnim = Math.sin(game.time * 10) * (p.vel.x !== 0 || p.vel.z !== 0 ? pw*0.3 : 0);
            ctx.fillStyle = '#0099cc';
            ctx.fillRect(sp.x - pw/2 + 2, sp.y + ph/2, pw*0.35, ph*0.3 + legAnim);
            ctx.fillRect(sp.x + pw*0.15, sp.y + ph/2, pw*0.35, ph*0.3 - legAnim);
        }
    }

    // Particles
    for(let part of game.particles) {
        let sp = cam.project(part.pos);
        if(sp && sp.z > 0) {
            let alpha = part.life / part.maxLife;
            let size = Math.max(1, part.size * alpha * 80 / sp.z);
            ctx.fillStyle = part.color.replace(')', `,${alpha})`).replace('rgb', 'rgba');
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, size, 0, Math.PI*2);
            ctx.fill();
        }
    }

    // Sort and draw by depth (painter's algorithm for transparent objects)
    renderList.sort((a,b) => b.z - a.z);

    // Minimap
    minimapCtx.clearRect(0, 0, 160, 160);
    minimapCtx.fillStyle = 'rgba(0,0,0,0.3)';
    minimapCtx.fillRect(0, 0, 160, 160);

    let mmScale = 4;
    let mmCx = 80, mmCy = 80;

    // Platforms on minimap
    for(let plat of game.platforms) {
        if(plat.type === 'decoration') continue;
        let px = mmCx + (plat.pos.x - p.pos.x) * mmScale;
        let pz = mmCy + (plat.pos.z - p.pos.z) * mmScale;
        let pw = plat.w * mmScale;
        let pd = plat.d * mmScale;
        minimapCtx.fillStyle = 'rgba(100,150,200,0.4)';
        minimapCtx.fillRect(px - pw/2, pz - pd/2, pw, pd);
    }

    // Coins on minimap
    for(let coin of game.coins) {
        if(coin.collected) continue;
        let cx = mmCx + (coin.pos.x - p.pos.x) * mmScale;
        let cz = mmCy + (coin.pos.z - p.pos.z) * mmScale;
        minimapCtx.fillStyle = '#ffd700';
        minimapCtx.beginPath();
        minimapCtx.arc(cx, cz, 2, 0, Math.PI*2);
        minimapCtx.fill();
    }

    // Enemies on minimap
    for(let enemy of game.enemies) {
        if(!enemy.alive) continue;
        let ex = mmCx + (enemy.pos.x - p.pos.x) * mmScale;
        let ez = mmCy + (enemy.pos.z - p.pos.z) * mmScale;
        minimapCtx.fillStyle = '#ff3366';
        minimapCtx.beginPath();
        minimapCtx.arc(ex, ez, 3, 0, Math.PI*2);
        minimapCtx.fill();
    }

    // Player on minimap
    minimapCtx.fillStyle = '#00ff88';
    minimapCtx.beginPath();
    minimapCtx.arc(mmCx, mmCy, 4, 0, Math.PI*2);
    minimapCtx.fill();
    minimapCtx.strokeStyle = '#fff';
    minimapCtx.lineWidth = 1;
    minimapCtx.stroke();

    // Direction indicator
    let dirX = Math.sin(game.cameraAngleX) * 10;
    let dirZ = Math.cos(game.cameraAngleX) * 10;
    minimapCtx.strokeStyle = '#00ff88';
    minimapCtx.lineWidth = 2;
    minimapCtx.beginPath();
    minimapCtx.moveTo(mmCx, mmCy);
    minimapCtx.lineTo(mmCx + dirX, mmCy + dirZ);
    minimapCtx.stroke();

    // Fog overlay at edges
    let fogGrad = ctx.createRadialGradient(W/2, H/2, W*0.3, W/2, H/2, W*0.7);
    fogGrad.addColorStop(0, 'rgba(0,0,0,0)');
    fogGrad.addColorStop(1, 'rgba(0,0,0,0.4)');
    ctx.fillStyle = fogGrad;
    ctx.fillRect(0, 0, W, H);

    // Vignette
    let vigGrad = ctx.createRadialGradient(W/2, H/2, W*0.2, W/2, H/2, W*0.6);
    vigGrad.addColorStop(0, 'rgba(0,0,0,0)');
    vigGrad.addColorStop(1, 'rgba(0,0,0,0.3)');
    ctx.fillStyle = vigGrad;
    ctx.fillRect(0, 0, W, H);
}

let lastTime = 0;
function gameLoop(timestamp) {
    let dt = Math.min(0.05, (timestamp - lastTime) / 1000);
    lastTime = timestamp;

    update(dt);
    render();
    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
