        ctx.arc(sx + 5 + sway, sy - 90, 18, 0, Math.PI * 2);
        ctx.fill();
    } else if (d.type === 'bush') {
        const sway = Math.sin(gameTime * 0.03 + d.x) * 1.5;
        ctx.fillStyle = '#3a8a3a';
        ctx.beginPath();
        ctx.arc(sx + sway, sy - 10, 18, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#4aaa4a';
        ctx.beginPath();
        ctx.arc(sx - 10 + sway, sy - 8, 14, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(sx + 12 + sway, sy - 12, 13, 0, Math.PI * 2);
        ctx.fill();
        // Flowers
        ctx.fillStyle = '#ff6b9d';
        for (let i = 0; i < 3; i++) {
            ctx.beginPath();
            ctx.arc(sx - 8 + i * 10 + sway, sy - 15, 3, 0, Math.PI * 2);
            ctx.fill();
        }
    }
}

// Draw coins
function drawCoin(coin) {
    if (coin.collected) return;
    const sx = coin.x - camera.x, sy = coin.y - camera.y;
    if (sx < -30 || sx > canvas.width + 30) return;

    const bob = Math.sin(gameTime * 0.05 + coin.x) * 4;
    const scale = Math.abs(Math.cos(gameTime * 0.04 + coin.x * 0.1));

    ctx.save();
    ctx.translate(sx, sy + bob);
    ctx.scale(scale, 1);

    // Glow
    const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 18);
    glow.addColorStop(0, 'rgba(255, 215, 0, 0.4)');
    glow.addColorStop(1, 'transparent');
    ctx.fillStyle = glow;
    ctx.fillRect(-18, -18, 36, 36);

    // Coin body
    const grad = ctx.createRadialGradient(-3, -3, 0, 0, 0, 10);
    grad.addColorStop(0, '#ffe066');
    grad.addColorStop(0.5, '#ffd700');
    grad.addColorStop(1, '#cc9900');
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = '#aa8800';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Star on coin
    ctx.fillStyle = '#fff8dc';
    ctx.font = 'bold 10px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('★', 0, 0);

    ctx.restore();
}

// Draw enemies
function drawEnemy(enemy) {
    if (enemy.dead) return;
    const sx = enemy.x - camera.x, sy = enemy.y - camera.y;
    if (sx < -50 || sx > canvas.width + 50) return;

    ctx.save();
    ctx.translate(sx, sy);

    if (enemy.type === 'walker') {
        // Body
        const squish = Math.sin(gameTime * 0.1) * 0.1;
        ctx.scale(1 + squish, 1 - squish);

        // Shadow
        ctx.fillStyle = 'rgba(0,0,0,0.2)';
        ctx.beginPath();
        ctx.ellipse(0, enemy.height / 2 + 2, 14, 4, 0, 0, Math.PI * 2);
        ctx.fill();

        // Body
        const grad = ctx.createRadialGradient(-3, -5, 0, 0, 0, 16);
        grad.addColorStop(0, '#e85d75');
        grad.addColorStop(1, '#c0392b');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(0, 0, 14, 0, Math.PI * 2);
        ctx.fill();

        // Eyes
        const eyeOffX = player.x > enemy.x ? 3 : -3;
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(-5 + eyeOffX, -3, 5, 0, Math.PI * 2);
        ctx.arc(5 + eyeOffX, -3, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#222';
        ctx.beginPath();
        ctx.arc(-4 + eyeOffX, -2, 2.5, 0, Math.PI * 2);
        ctx.arc(6 + eyeOffX, -2, 2.5, 0, Math.PI * 2);
        ctx.fill();

        // Angry eyebrows
        ctx.strokeStyle = '#222';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-9, -9);
        ctx.lineTo(-2, -7);
        ctx.moveTo(9, -9);
        ctx.lineTo(2, -7);
        ctx.stroke();

        // Mouth
        ctx.beginPath();
        ctx.arc(0, 5, 4, 0, Math.PI);
        ctx.strokeStyle = '#222';
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // Feet
        const walk = Math.sin(gameTime * 0.15) * 3;
        ctx.fillStyle = '#a0302a';
        ctx.beginPath();
        ctx.ellipse(-6, 12 + walk, 5, 3, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.ellipse(6, 12 - walk, 5, 3, 0, 0, Math.PI * 2);
        ctx.fill();

    } else if (enemy.type === 'flyer') {
        const bob = Math.sin(gameTime * 0.08) * 8;
        ctx.translate(0, bob);

        // Wings
        const wingAngle = Math.sin(gameTime * 0.3) * 0.5;
        ctx.fillStyle = 'rgba(150, 100, 255, 0.6)';
        ctx.save();
        ctx.rotate(wingAngle);
        ctx.beginPath();
        ctx.ellipse(-12, -5, 14, 6, -0.3, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
        ctx.save();
        ctx.rotate(-wingAngle);
        ctx.beginPath();
        ctx.ellipse(12, -5, 14, 6, 0.3, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        // Body
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 12);
        grad.addColorStop(0, '#9b59b6');
        grad.addColorStop(1, '#6c3483');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(0, 0, 12, 0, Math.PI * 2);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#ff0';
        ctx.beginPath();
        ctx.arc(-4, -2, 3, 0, Math.PI * 2);
        ctx.arc(4, -2, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#222';
        ctx.beginPath();
        ctx.arc(-4, -2, 1.5, 0, Math.PI * 2);
        ctx.arc(4, -2, 1.5, 0, Math.PI * 2);
        ctx.fill();

        // Stinger
        ctx.fillStyle = '#ff6600';
        ctx.beginPath();
        ctx.moveTo(-3, 10);
        ctx.lineTo(0, 18);
        ctx.lineTo(3, 10);
        ctx.fill();
    }

    ctx.restore();
}

// Draw player
function drawPlayer() {
    if (player.invincible > 0 && Math.floor(player.invincible / 3) % 2 === 0) return;

    const sx = player.x - camera.x, sy = player.y - camera.y;

    ctx.save();
    ctx.translate(sx + player.width / 2, sy + player.height);
    ctx.scale(player.facing, 1);
    ctx.scale(player.squash, player.stretch);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.beginPath();
    ctx.ellipse(0, 0, 14, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    const bodyGrad = ctx.createLinearGradient(-12, -player.height, 12, 0);
    bodyGrad.addColorStop(0, '#7c5cbf');
    bodyGrad.addColorStop(0.5, '#6a4cad');
    bodyGrad.addColorStop(1, '#5a3d99');
    ctx.fillStyle = bodyGrad;

    // Body shape
    ctx.beginPath();
    ctx.moveTo(-10, -4);
    ctx.quadraticCurveTo(-12, -player.height + 10, -8, -player.height + 2);
    ctx.quadraticCurveTo(0, -player.height - 4, 8, -player.height + 2);
    ctx.quadraticCurveTo(12, -player.height + 10, 10, -4);
    ctx.quadraticCurveTo(6, -2, 0, -2);
    ctx.quadraticCurveTo(-6, -2, -10, -4);
    ctx.fill();

    // Belt
    ctx.fillStyle = '#ffd700';
    ctx.fillRect(-9, -14, 18, 3);

    // Head
    const headGrad = ctx.createRadialGradient(0, -player.height + 8, 0, 0, -player.height + 8, 12);
    headGrad.addColorStop(0, '#c9a0dc');
    headGrad.addColorStop(1, '#a070c0');
    ctx.fillStyle = headGrad;
    ctx.beginPath();
    ctx.arc(0, -player.height + 8, 11, 0, Math.PI * 2);
    ctx.fill();

    // Hair
    ctx.fillStyle = '#8b5fbf';
    ctx.beginPath();
    ctx.arc(0, -player.height + 2, 11, Math.PI, Math.PI * 2);
    ctx.fill();
    // Hair tuft
    ctx.beginPath();
    ctx.moveTo(-4, -player.height - 2);
    ctx.quadraticCurveTo(0, -player.height - 10, 6, -player.height - 4);
    ctx.quadraticCurveTo(2, -player.height - 2, -4, -player.height - 2);
    ctx.fill();

    // Eyes
    const blink = Math.sin(gameTime * 0.05) > 0.95;
    if (!blink) {
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.ellipse(-4, -player.height + 7, 4, 4.5, 0, 0, Math.PI * 2);
        ctx.ellipse(4, -player.height + 7, 4, 4.5, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#2d1b69';
        ctx.beginPath();
        ctx.arc(-3, -player.height + 7.5, 2.5, 0, Math.PI * 2);
        ctx.arc(5, -player.height + 7.5, 2.5, 0, Math.PI * 2);
        ctx.fill();

        // Eye shine
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(-2, -player.height + 6, 1, 0, Math.PI * 2);
        ctx.arc(6, -player.height + 6, 1, 0, Math.PI * 2);
        ctx.fill();
    } else {
        ctx.strokeStyle = '#2d1b69';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-7, -player.height + 7);
        ctx.lineTo(-1, -player.height + 7);
        ctx.moveTo(1, -player.height + 7);
        ctx.lineTo(7, -player.height + 7);
        ctx.stroke();
    }

    // Mouth
    ctx.fillStyle = '#2d1b69';
    if (player.vy < -2) {
        // Surprised mouth when jumping
        ctx.beginPath();
        ctx.arc(0, -player.height + 14, 3, 0, Math.PI * 2);
        ctx.fill();
    } else {
        ctx.beginPath();
        ctx.arc(0, -player.height + 13, 2.5, 0.1, Math.PI - 0.1);
        ctx.strokeStyle = '#2d1b69';
        ctx.lineWidth = 1.5;
        ctx.stroke();
    }

    // Legs animation
    const legAnim = player.onGround ? Math.sin(gameTime * 0.2) * (Math.abs(player.vx) > 0.5 ? 6 : 0) : 3;
    ctx.fillStyle = '#5a3d99';
    ctx.beginPath();
    ctx.ellipse(-5, -2 + legAnim, 5, 4, 0.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(5, -2 - legAnim, 5, 4, -0.2, 0, Math.PI * 2);
    ctx.fill();

    // Shoes
    ctx.fillStyle = '#ffd700';
    ctx.beginPath();
    ctx.ellipse(-5, 1 + legAnim, 6, 3, 0.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(5, 1 - legAnim, 6, 3, -0.2, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();

    // Trail effect
    if (Math.abs(player.vx) > 2 || !player.onGround) {
        player.trail.push({ x: player.x + player.width / 2, y: player.y + player.height / 2, life: 10 });
    }
    player.trail = player.trail.filter(t => { t.life--; return t.life > 0; });
    player.trail.forEach(t => {
        const alpha = t.life / 10;
        ctx.fillStyle = `rgba(150, 100, 255, ${alpha * 0.3})`;
        ctx.beginPath();
        ctx.arc(t.x - camera.x, t.y - camera.y, 8 * alpha, 0, Math.PI * 2);
        ctx.fill();
    });
}

// Draw flag
function drawFlag(flagX, flagY) {
    const sx = flagX - camera.x, sy = flagY - camera.y;
    if (sx < -50 || sx > canvas.width + 50) return;

    // Pole
    ctx.fillStyle = '#ddd';
    ctx.fillRect(sx - 2, sy - 80, 4, 80);

    // Flag
    const wave = Math.sin(gameTime * 0.08) * 5;
    ctx.fillStyle = '#ff6b9d';
    ctx.beginPath();
    ctx.moveTo(sx + 2, sy - 80);
    ctx.quadraticCurveTo(sx + 25 + wave, sy - 70, sx + 2, sy - 55);
    ctx.fill();

    // Star on flag
    ctx.fillStyle = '#ffd700';
    ctx.font = '12px Arial';
    ctx.fillText('★', sx + 6 + wave * 0.5, sy - 62);

    // Glow
    const glow = ctx.createRadialGradient(sx, sy - 60, 0, sx, sy - 60, 40);
    glow.addColorStop(0, 'rgba(255, 107, 157, 0.2)');
    glow.addColorStop(1, 'transparent');
    ctx.fillStyle = glow;
    ctx.fillRect(sx - 40, sy - 100, 80, 80);
}

// Background rendering
function drawBackground(level) {
    const bg = level.bgType || 'sunset';

    // Sky gradient
    let skyTop, skyMid, skyBot;
    if (bg === 'sunset') {
        skyTop = '#1a0a3e'; skyMid = '#4a1942'; skyBot = '#c84b31';
    } else if (bg === 'night') {
        skyTop = '#0a0a2e'; skyMid = '#1a1a4e'; skyBot = '#2a2a6e';
    } else if (bg === 'aurora') {
        skyTop = '#0a1a2e'; skyMid = '#1a3a4e'; skyBot = '#2a5a5e';
    }

    const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
    skyGrad.addColorStop(0, skyTop);
    skyGrad.addColorStop(0.5, skyMid);
    skyGrad.addColorStop(1, skyBot);
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Stars (more visible in night/aurora)
    const starAlpha = bg === 'night' ? 1 : bg === 'aurora' ? 0.8 : 0.4;
    stars.forEach(s => {
        const sx = ((s.x - camera.x * 0.1) % (canvas.width + 100) + canvas.width + 100) % (canvas.width + 100);
        const twinkle = Math.sin(s.twinkle + gameTime * s.speed) * 0.5 + 0.5;
        ctx.fillStyle = `rgba(255, 255, 255, ${starAlpha * twinkle})`;
        ctx.beginPath();
        ctx.arc(sx, s.y, s.size * twinkle, 0, Math.PI * 2);
        ctx.fill();
    });

    // Moon/Sun
    if (bg === 'sunset') {
        const sunX = canvas.width * 0.75 - camera.x * 0.05;
        const sunGrad = ctx.createRadialGradient(sunX, 150, 0, sunX, 150, 60);
        sunGrad.addColorStop(0, 'rgba(255, 200, 50, 0.8)');
        sunGrad.addColorStop(0.5, 'rgba(255, 150, 50, 0.3)');
        sunGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = sunGrad;
        ctx.fillRect(sunX - 80, 70, 160, 160);
        ctx.fillStyle = '#ffe080';
        ctx.beginPath();
        ctx.arc(sunX, 150, 25, 0, Math.PI * 2);
        ctx.fill();
    } else {
        const moonX = canvas.width * 0.8 - camera.x * 0.05;
        ctx.fillStyle = '#e8e8f0';
        ctx.beginPath();
        ctx.arc(moonX, 100, 22, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = skyTop;
        ctx.beginPath();
        ctx.arc(moonX + 8, 95, 18, 0, Math.PI * 2);
        ctx.fill();
    }

    // Aurora effect
    if (bg === 'aurora') {
        for (let i = 0; i < 3; i++) {
            ctx.beginPath();
            ctx.strokeStyle = `rgba(${100 + i * 50}, ${200 + i * 20}, ${150 + i * 30}, 0.15)`;
            ctx.lineWidth = 30;
            ctx.moveTo(0, 100 + i * 40);
            for (let x = 0; x < canvas.width; x += 20) {
                const y = 100 + i * 40 + Math.sin(x * 0.01 + gameTime * 0.01 + i) * 30 + Math.sin(x * 0.005 + gameTime * 0.005) * 20;
                ctx.lineTo(x, y);
            }
            ctx.stroke();
        }
    }

    // Far mountains (parallax 0.2)
    ctx.fillStyle = bg === 'night' ? '#0d0d2d' : bg === 'aurora' ? '#0d1d2d' : '#2a1a3e';
    ctx.beginPath();
    ctx.moveTo(0, canvas.height);
    for (let x = 0; x <= canvas.width; x += 60) {
        const wx = x + camera.x * 0.2;
        const h = 200 + Math.sin(wx * 0.005) * 80 + Math.sin(wx * 0.012) * 40;
        ctx.lineTo(x, canvas.height - h);
    }
    ctx.lineTo(canvas.width, canvas.height);
    ctx.fill();

    // Near mountains (parallax 0.4)
    ctx.fillStyle = bg === 'night' ? '#12123a' : bg === 'aurora' ? '#122a3a' : '#3a2a4e';
    ctx.beginPath();
    ctx.moveTo(0, canvas.height);
    for (let x = 0; x <= canvas.width; x += 40) {
        const wx = x + camera.x * 0.4;
        const h = 150 + Math.sin(wx * 0.008 + 1) * 60 + Math.sin(wx * 0.02) * 30;
        ctx.lineTo(x, canvas.height - h);
    }
    ctx.lineTo(canvas.width, canvas.height);
    ctx.fill();

    // Clouds (parallax 0.15)
    clouds.forEach(c => {
        c.x += c.speed;
        if (c.x > 3200) c.x = -200;
        const cx = ((c.x - camera.x * 0.15) % (canvas.width + 300) + canvas.width + 300) % (canvas.width + 300) - 150;
        ctx.fillStyle = `rgba(255, 255, 255, ${c.opacity})`;
        ctx.beginPath();
        ctx.ellipse(cx, c.y, c.w / 2, c.h / 2, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.ellipse(cx - c.w * 0.25, c.y + 5, c.w * 0.3, c.h * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.ellipse(cx + c.w * 0.25, c.y + 3, c.w * 0.35, c.h * 0.45, 0, 0, Math.PI * 2);
        ctx.fill();
    });

    // Mid-ground trees (parallax 0.6)
    ctx.fillStyle = bg === 'night' ? '#0a0a20' : bg === 'aurora' ? '#0a1a20' : '#1a2a1a';
    for (let i = 0; i < 20; i++) {
        const tx = ((i * 180 - camera.x * 0.6) % (canvas.width + 200) + canvas.width + 200) % (canvas.width + 200) - 100;
        const th = 60 + Math.sin(i * 2.5) * 30;
        ctx.beginPath();
        ctx.moveTo(tx, canvas.height);
        ctx.lineTo(tx - 15, canvas.height);
        ctx.lineTo(tx - 8, canvas.height - th);
        ctx.lineTo(tx, canvas.height - th - 15);
        ctx.lineTo(tx + 8, canvas.height - th);
        ctx.lineTo(tx + 15, canvas.height);
        ctx.fill();
    }
}

// HUD
function drawHUD() {
    // Score
    ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
    ctx.beginPath();
    ctx.roundRect(10, 10, 160, 40, 10);
    ctx.fill();
    ctx.fillStyle = '#ffd700';
    ctx.font = 'bold 18px "Segoe UI", sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(`✦ ${score}`, 25, 30);

    // Lives
    ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
    ctx.beginPath();
    ctx.roundRect(canvas.width - 130, 10, 120, 40, 10);
    ctx.fill();
    for (let i = 0; i < lives; i++) {
        ctx.fillStyle = '#ff6b9d';
        ctx.beginPath();
        const hx = canvas.width - 115 + i * 35;
        const hy = 30;
        ctx.moveTo(hx, hy + 4);
        ctx.bezierCurveTo(hx, hy, hx - 6, hy, hx - 6, hy + 4);
        ctx.bezierCurveTo(hx - 6, hy + 10, hx, hy + 14, hx, hy + 16);
        ctx.bezierCurveTo(hx, hy + 14, hx + 6, hy + 10, hx + 6, hy + 4);
        ctx.bezierCurveTo(hx + 6, hy, hx, hy, hx, hy + 4);
        ctx.fill();
    }

    // Level indicator
    ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
    ctx.beginPath();
    ctx.roundRect(canvas.width / 2 - 60, 10, 120, 30, 8);
    ctx.fill();
    ctx.fillStyle = '#c9a0dc';
    ctx.font = '14px "Segoe UI", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(`Level ${currentLevel + 1}`, canvas.width / 2, 26);
}

// Menu screen
function drawMenu() {
    drawBackground(levels[0]);

    // Title
    ctx.save();
    const titleY = 180 + Math.sin(gameTime * 0.03) * 10;

    // Title glow
    ctx.shadowColor = '#ff6b9d';
    ctx.shadowBlur = 30;
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 56px "Segoe UI", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Starlight', canvas.width / 2, titleY);
    ctx.shadowColor = '#7c5cbf';
    ctx.fillStyle = '#c9a0dc';
    ctx.fillText('Adventures', canvas.width / 2, titleY + 60);
    ctx.shadowBlur = 0;

    // Subtitle
    ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
    ctx.font = '18px "Segoe UI", sans-serif';
    ctx.fillText('A Journey Through the Stars', canvas.width / 2, titleY + 100);

    // Start prompt
    const pulse = Math.sin(gameTime * 0.06) * 0.3 + 0.7;
    ctx.fillStyle = `rgba(255, 215, 0, ${pulse})`;
    ctx.font = 'bold 22px "Segoe UI", sans-serif';
    ctx.fillText('Press SPACE or ENTER to Start', canvas.width / 2, titleY + 170);

    // Controls
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    ctx.font = '14px "Segoe UI", sans-serif';
    ctx.fillText('← → or A D to Move  |  SPACE or W or ↑ to Jump', canvas.width / 2, titleY + 220);
    ctx.fillText('Collect stars ★ and reach the flag 🚩!', canvas.width / 2, titleY + 245);

    ctx.restore();
}

// Game Over screen
function drawGameOver() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#ff6b6b';
    ctx.font = 'bold 48px "Segoe UI", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 40);

    ctx.fillStyle = '#ffd700';
    ctx.font = '24px "Segoe UI", sans-serif';
    ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 20);

    const pulse = Math.sin(gameTime * 0.06) * 0.3 + 0.7;
    ctx.fillStyle = `rgba(255, 255, 255, ${pulse})`;
    ctx.font = '18px "Segoe UI", sans-serif';
    ctx.fillText('Press SPACE or ENTER to Retry', canvas.width / 2, canvas.height / 2 + 70);
}

// Win screen
function drawWinScreen() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.shadowColor = '#ffd700';
    ctx.shadowBlur = 20;
    ctx.fillStyle = '#ffd700';
    ctx.font = 'bold 48px "Segoe UI", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('🎉 Victory! 🎉', canvas.width / 2, canvas.height / 2 - 60);
    ctx.shadowBlur = 0;

    ctx.fillStyle = '#fff';
    ctx.font = '28px "Segoe UI", sans-serif';
    ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2);

    ctx.fillStyle = '#c9a0dc';
    ctx.font = '18px "Segoe UI", sans-serif';
    ctx.fillText('You completed all levels!', canvas.width / 2, canvas.height / 2 + 40);

    const pulse = Math.sin(gameTime * 0.06) * 0.3 + 0.7;
    ctx.fillStyle = `rgba(255, 255, 255, ${pulse})`;
    ctx.font = '18px "Segoe UI", sans-serif';
    ctx.fillText('Press SPACE or ENTER to Play Again', canvas.width / 2, canvas.height / 2 + 90);
}

// Level transition
function drawLevelTransition() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#c9a0dc';
    ctx.font = 'bold 36px "Segoe UI", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(`Level ${currentLevel + 1}`, canvas.width / 2, canvas.height / 2);
}

// Game logic
let level = null;
let coins = [];
let enemies = [];
let decorations = [];

function loadLevel(index) {
    if (index >= levels.length) {
        gameState = STATE.WIN;
        return;
    }
    const data = levels[index];
    level = data;
    coins = data.coins.map(c => ({ ...c, collected: false, bobOffset: Math.random() * Math.PI * 2 }));
    enemies = data.enemies.map(e => ({
        ...e,
        startX: e.x, startY: e.y,
        alive: true, dead: false,
        vx: 1, vy: 0,
        height: e.type === 'walker' ? 28 : 24,
        width: 28,
        animTimer: 0
    }));
    decorations = data.decorations || [];
    resetPlayer(data.spawnX, data.spawnY);
    camera.x = player.x - canvas.width / 3;
    camera.y = player.y - canvas.height / 2;
    particles = [];
}

function update() {
    gameTime++;

    if (gameState === STATE.MENU) {
        if (keysPressed['Space'] || keysPressed['Enter']) {
            score = 0; lives = 3; currentLevel = 0;
            loadLevel(0);
            gameState = STATE.LEVEL_TRANS;
            levelTransitionTimer = 90;
        }
        return;
    }

    if (gameState === STATE.LEVEL_TRANS) {
        levelTransitionTimer--;
        if (levelTransitionTimer <= 0) gameState = STATE.PLAYING;
        return;
    }

    if (gameState === STATE.GAMEOVER) {
        if (keysPressed['Space'] || keysPressed['Enter']) {
            score = 0; lives = 3; currentLevel = 0;
            loadLevel(0);
            gameState = STATE.LEVEL_TRANS;
            levelTransitionTimer = 90;
        }
        return;
    }

    if (gameState === STATE.WIN) {
        if (keysPressed['Space'] || keysPressed['Enter']) {
            gameState = STATE.MENU;
        }
        // Win particles
        if (gameTime % 5 === 0) {
            spawnParticles(
                Math.random() * canvas.width + camera.x,
                Math.random() * canvas.height * 0.5 + camera.y,
                3,
                { colors: ['#ffd700', '#ff6b9d', '#7c5cbf', '#fff'], speed: 4, size: 4, life: 40, type: 'star' }
            );
        }
        particles.forEach(p => p.update());
        particles = particles.filter(p => p.life > 0);
        return;
    }

    // Player movement
    const moveLeft = keys['ArrowLeft'] || keys['KeyA'];
    const moveRight = keys['ArrowRight'] || keys['KeyD'];
    const jumpKey = keys['Space'] || keys['ArrowUp'] || keys['KeyW'];

    const accel = player.onGround ? 0.8 : 0.5;
    const friction = player.onGround ? 0.82 : 0.92;
    const maxSpeed = 5.5;

    if (moveLeft) { player.vx -= accel; player.facing = -1; }
    if (moveRight) { player.vx += accel; player.facing = 1; }
    player.vx *= friction;
    if (Math.abs(player.vx) > maxSpeed) player.vx = maxSpeed * Math.sign(player.vx);
    if (Math.abs(player.vx) < 0.1) player.vx = 0;

    // Jump
    if (jumpKey) {
        player.jumpBuffer = 8;
    } else {
        player.jumpBuffer = Math.max(0, player.jumpBuffer - 1);
    }

    if (player.jumpBuffer > 0) {
        if (player.coyoteTime > 0) {
            player.vy = -11;
            player.onGround = false;
            player.coyoteTime = 0;
            player.jumpBuffer = 0;
            player.squash = 0.7;
            player.stretch = 1.3;
            spawnParticles(player.x + player.width / 2, player.y + player.height, 8, {
                colors: ['#c9a0dc', '#fff', '#a070c0'], speed: 2, size: 3, life: 20, type: 'circle'
            });
        } else if (!player.onGround && player.canDoubleJump) {
            player.vy = -10;
            player.canDoubleJump = false;
            player.jumpBuffer = 0;
            player.squash = 0.7;
            player.stretch = 1.3;
            spawnParticles(player.x + player.width / 2, player.y + player.height, 12, {
                colors: ['#7c5cbf', '#c9a0dc', '#fff'], speed: 3, size: 3, life: 25, type: 'spark'
            });
        }
    }

    // Variable jump height
    if (!jumpKey && player.vy < -4) {
        player.vy *= 0.85;
    }

    // Gravity
    player.vy += 0.55;
    if (player.vy > 12) player.vy = 12;

    // Move X
    player.x += player.vx;

    // Collide X with platforms
    const allPlatforms = level.platforms;
    player.onGround = false;

    for (const p of allPlatforms) {
        if (rectCollision(player, p)) {
            if (player.vx > 0) {
                player.x = p.x - player.width;
            } else if (player.vx < 0) {
                player.x = p.x + p.w;
            }
            player.vx = 0;
        }
    }

    // Move Y
    player.y += player.vy;

    for (const p of allPlatforms) {
        if (rectCollision(player, p)) {
            if (player.vy > 0) {
                player.y = p.y - player.height;
                if (player.vy > 5) {
                    player.squash = 1.3;
                    player.stretch = 0.7;
                    spawnParticles(player.x + player.width / 2, player.y + player.height, 5, {
                        colors: ['#c9a0dc', '#fff'], speed: 1.5, size: 2, life: 15, type: 'circle'
                    });
                }
                player.vy = 0;
                player.onGround = true;
                player.coyoteTime = 6;
                player.canDoubleJump = true;
            } else if (player.vy < 0) {
                player.y = p.y + p.h;
                player.vy = 0;
            }
        }
    }

    // Coyote time
    if (!player.onGround) {
        player.coyoteTime = Math.max(0, player.coyoteTime - 1);
    }

    // Fall death
    if (player.y > 700) {
        playerDie();
    }

    // Squash and stretch recovery
    player.squash += (1 - player.squash) * 0.15;
    player.stretch += (1 - player.stretch) * 0.15;

    // Invincibility
    if (player.invincible > 0) player.invincible--;

    // Collect coins
    coins.forEach(coin => {
        if (coin.collected) return;
        const dx = (player.x + player.width / 2) - coin.x;
        const dy = (player.y + player.height / 2) - coin.y;
        if (Math.sqrt(dx * dx + dy * dy) < 20) {
            coin.collected = true;
            score += 10;
            spawnParticles(coin.x, coin.y, 15, {
                colors: ['#ffd700', '#fff', '#ffe066'], speed: 4, size: 4, life: 30, type: 'star'
            });
            screenShake = 3;
        }
    });

    // Update enemies
    enemies.forEach(enemy => {
        if (enemy.dead) return;
        enemy.animTimer++;

        if (enemy.type === 'walker') {
            enemy.x += enemy.vx;
            if (Math.abs(enemy.x - enemy.startX) > enemy.range) {
                enemy.vx *= -1;
            }
            // Simple gravity for walkers
            enemy.vy = (enemy.vy || 0) + 0.5;
            enemy.y += enemy.vy;
            // Platform collision for walker
            for (const p of allPlatforms) {
                if (enemy.x + 14 > p.x && enemy.x - 14 < p.x + p.w &&
                    enemy.y + 14 > p.y && enemy.y + 14 < p.y + p.h + 10) {
                    enemy.y = p.y - 14;
                    enemy.vy = 0;
                }
            }
        } else if (enemy.type === 'flyer') {
            enemy.x += enemy.vx;
            if (Math.abs(enemy.x - enemy.startX) > enemy.range) {
                enemy.vx *= -1;
            }
        }

        // Player collision with enemy
        if (player.invincible <= 0) {
            const dx = (player.x + player.width / 2) - enemy.x;
            const dy = (player.y + player.height / 2) - enemy.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < 22) {
                // Stomp from above
                if (player.vy > 0 && player.y + player.height - 8 < enemy.y) {
                    enemy.dead = true;
                    player.vy = -8;
                    score += 25;
                    spawnParticles(enemy.x, enemy.y, 20, {
                        colors: ['#ff6b6b', '#ff9999', '#fff'], speed: 5, size: 5, life: 35, type: 'spark'
                    });
                    screenShake = 5;
                } else {
                    playerDie();
                }
            }
        }
    });

    // Flag collision (level complete)
    const flagX = level.flagX, flagY = level.flagY;
    const fdx = (player.x + player.width / 2) - flagX;
    const fdy = (player.y + player.height / 2) - flagY;
    if (Math.sqrt(fdx * fdx + fdy * fdy) < 35) {
        if (currentLevel < levels.length - 1) {
            currentLevel++;
            score += 50;
            loadLevel(currentLevel);
            gameState = STATE.LEVEL_TRANS;
            levelTransitionTimer = 90;
        } else {
            score += 100;
            gameState = STATE.WIN;
        }
        spawnParticles(flagX, flagY, 30, {
            colors: ['#ffd700', '#ff6b9d', '#c9a0dc', '#fff'], speed: 6, size: 5, life: 50, type: 'star'
        });
    }

    // Camera
    camera.targetX = player.x - canvas.width / 3;
    camera.targetY = player.y - canvas.height / 2 + 50;
    camera.x += (camera.targetX - camera.x) * 0.08;
    camera.y += (camera.targetY - camera.y) * 0.06;
    camera.y = Math.min(camera.y, 100);

    // Screen shake
    if (screenShake > 0) {
        camera.x += (Math.random() - 0.5) * screenShake * 2;
        camera.y += (Math.random() - 0.5) * screenShake * 2;
        screenShake *= 0.85;
        if (screenShake < 0.5) screenShake = 0;
    }

    // Ambient particles
    if (gameTime % 20 === 0) {
        spawnParticles(
            camera.x + Math.random() * canvas.width,
            camera.y - 10,
            1,
            { colors: ['#c9a0dc', '#7c5cbf', '#a070c0'], speed: 0.5, size: 2, life: 80, type: 'leaf' }
        );
    }

    // Update particles
    particles.forEach(p => p.update());
    particles = particles.filter(p => p.life > 0);

    // Clear pressed keys
    for (const key in keysPressed) keysPressed[key] = false;
}

function playerDie() {
    if (player.invincible > 0) return;
    lives--;
    screenShake = 10;
    spawnParticles(player.x + player.width / 2, player.y + player.height / 2, 30, {
        colors: ['#ff6b6b', '#ff9999', '#c9a0dc', '#fff'], speed: 6, size: 5, life: 40, type: 'spark'
    });

    if (lives <= 0) {
        gameState = STATE.GAMEOVER;
    } else {
        player.invincible = 90;
        resetPlayer(level.spawnX, level.spawnY);
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (gameState === STATE.MENU) {
        drawMenu();
        return;
    }

    if (!level) return;

    // Background
    drawBackground(level);

    // Decorations (behind platforms)
    decorations.forEach(d => drawDecoration(d));

    // Platforms
    level.platforms.forEach(p => drawPlatform(p));

    // Coins
    coins.forEach(c => drawCoin(c));

    // Flag
    drawFlag(level.flagX, level.flagY);

    // Enemies
    enemies.forEach(e => drawEnemy(e));

    // Player
    if (gameState === STATE.PLAYING || gameState === STATE.LEVEL_TRANS) {
        drawPlayer();
    }

    // Particles
    particles.forEach(p => p.draw());

    // HUD
    drawHUD();

    // Overlays
    if (gameState === STATE.LEVEL_TRANS) drawLevelTransition();
    if (gameState === STATE.GAMEOVER) drawGameOver();
    if (gameState === STATE.WIN) drawWinScreen();
}

// Game loop
function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Polyfill roundRect
if (!ctx.roundRect) {
    CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
        if (typeof r === 'number') r = [r, r, r, r];
        this.moveTo(x + r[0], y);
        this.lineTo(x + w - r[1], y);
        this.quadraticCurveTo(x + w, y, x + w, y + r[1]);
        this.lineTo(x + w, y + h - r[2]);
        this.quadraticCurveTo(x + w, y + h, x + w - r[2], y + h);
        this.lineTo(x + r[3], y + h);
        this.quadraticCurveTo(x, y + h, x, y + h - r[3]);
        this.lineTo(x, y + r[0]);
        this.quadraticCurveTo(x, y, x + r[0], y);
        this.closePath();
    };
}

gameLoop();
</script>
