function createFlyover(zStart, zEnd) {
const group = new THREE.Group();

// Bridge deck
const deckGeo = new THREE.BoxGeometry(14, 0.5, zEnd - zStart);
const deckMat = new THREE.MeshStandardMaterial({ color: 0x666666, roughness: 0.8 });
const deck = new THREE.Mesh(deckGeo, deckMat);
deck.position.set(0, 6, (zStart + zEnd) / 2);
deck.castShadow = true;
deck.receiveShadow = true;
group.add(deck);

// Railings
const railGeo = new THREE.BoxGeometry(0.1, 1.2, zEnd - zStart);
const railMat = new THREE.MeshStandardMaterial({ color: 0xcccccc });
[-1, 1].forEach(s => {
const rail = new THREE.Mesh(railGeo, railMat);
rail.position.set(s * 6.8, 6.8, (zStart + zEnd) / 2);
group.add(rail);
});

// Top rail
const topRailGeo = new THREE.BoxGeometry(0.08, 0.08, zEnd - zStart);
[-1, 1].forEach(s => {
const topRail = new THREE.Mesh(topRailGeo, railMat);
topRail.position.set(s * 6.8, 7.4, (zStart + zEnd) / 2);
group.add(topRail);
});

// Pillars
for (let z = zStart; z <= zEnd; z += 30) {
for (let x of [-5, 5]) {
const pillarGeo = new THREE.BoxGeometry(1, 6, 1);
const pillar = new THREE.Mesh(pillarGeo, deckMat);
pillar.position.set(x, 3, z);
pillar.castShadow = true;
group.add(pillar);
}
}

// Ramp
if (zStart > -ROAD_LENGTH / 2) {
const rampGeo = new THREE.BoxGeometry(8, 0.4, 40);
