// ============================================================
//  CITY PARAMETERS
// ============================================================
const BLOCK_SIZE = 16;
const STREET_WIDTH = 8;
const SIDEWALK_WIDTH = 1;
const CELL_SIZE = BLOCK_SIZE + STREET_WIDTH; // 24
const GRID_BLOCKS = 3;
const GRID_CELLS = GRID_BLOCKS * 2 + 1; // 7

// ============================================================
//  MATERIALS
// ============================================================
const matAsphalt = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.9 });
const matSidewalk = new THREE.MeshStandardMaterial({ color: 0x999999, roughness: 0.7 });
const matGrass = new THREE.MeshStandardMaterial({ color: 0x4a8c3f, roughness: 0.8 });
const matRoadLine = new THREE.MeshStandardMaterial({ color: 0xffff00, roughness: 0.5 });
const matBuilding = new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.6 });
const matPlayer = new THREE.MeshStandardMaterial({ color: 0xff4444, roughness: 0.3, metalness: 0.5 });
const matCar1 = new THREE.MeshStandardMaterial({ color: 0x2196F3, roughness: 0.3, metalness: 0.4 });
const matCar2 = new THREE.MeshStandardMaterial({ color: 0xFF9800, roughness: 0.3, metalness: 0.4 });
const matCar3 = new THREE.MeshStandardMaterial({ color: 0x4CAF50, roughness: 0.3, metalness: 0.4 });
const matCar4 = new THREE.MeshStandardMaterial({ color: 0xE91E63, roughness: 0.3, metalness: 0.4 });
const matCar5 = new THREE.MeshStandardMaterial({ color: 0x9C27B0, roughness: 0.3, metalness: 0.4 });
const matCar6 = new THREE.MeshStandardMaterial({ color: 0xFFEB3B, roughness: 0.3, metalness: 0.4 });
const matCar7 = new THREE.MeshStandardMaterial({ color: 0x00BCD4, roughness: 0.3, metalness: 0.4 });
const matCar8 = new THREE.MeshStandardMaterial({ color: 0x795548, roughness: 0.3, metalness: 0.4 });
const matWaypoint = new THREE.MeshStandardMaterial({ color: 0x00ff00, emissive: 0x00ff00, emissiveIntensity: 0.3 });
const matIntersection = new THREE.MeshStandardMaterial({ color: 0xff00ff, emissive: 0xff00ff, emissiveIntensity: 0.2 });

const carMaterials = [matCar1, matCar2, matCar3, matCar4, matCar5, matCar6, matCar7, matCar8];

// ============================================================
//  BUILD CITY
// ============================================================
const cityGroup = new THREE.Group();
scene.add(cityGroup);

// Determine which cells are blocks vs streets
// Cell index 0,2,4,6 = blocks; 1,3,5 = streets (for a 7-cell grid)
function isBlockCell(idx) { return idx % 2 === 0; }
function isStreetCell(idx) { return idx % 2 === 1; }

function cellToWorld(cellIdx) {
  return (cellIdx - (GRID_CELLS - 1) / 2) * CELL_SIZE;
}

// Build blocks with sidewalks and grass
for (let row = 0; row < GRID_CELLS; row++) {
  for (let col = 0; col < GRID_CELLS; col++) {
    if (!isBlockCell(row) || !isBlockCell(col)) continue;

    const cx = cellToWorld(col);
    const cz = cellToWorld(row);

    // Sidewalk (border around block)
    const swGeo = new THREE.BoxGeometry(BLOCK_SIZE + SIDEWALK_WIDTH * 2, 0.15, BLOCK_SIZE + SIDEWALK_WIDTH * 2);
    const sw = new THREE.Mesh(swGeo, matSidewalk);
    sw.position.set(cx, 0.075, cz);
    sw.receiveShadow = true;
    cityGroup.add(sw);

    // Grass / empty terrain in middle
    const grassGeo = new THREE.BoxGeometry(BLOCK_SIZE, 0.1, BLOCK_SIZE);
    const grass = new THREE.Mesh(grassGeo, matGrass);
    grass.position.set(cx, 0.16, cz);
    grass.receiveShadow = true;
    cityGroup.add(grass);

    // Random buildings on the block
    const numBuildings = 1 + Math.floor(Math.random() * 3);
    for (let b = 0; b < numBuildings; b++) {
      const bw = 2 + Math.random() * 4;
      const bh = 3 + Math.random() * 12;
      const bd = 2 + Math.random() * 4;
      const bx = cx + (Math.random() - 0.5) * (BLOCK_SIZE - bw - 2);
      const bz = cz + (Math.random() - 0.5) * (BLOCK_SIZE - bd - 2);

      const bGeo = new THREE.BoxGeometry(bw, bh, bd);
      const bMat = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(0, 0, 0.4 + Math.random() * 0.3),
        roughness: 0.7
      });
      const building = new THREE.Mesh(bGeo, bMat);
      building.position.set(bx, bh / 2 + 0.15, bz);
      building.castShadow = true;
      building.receiveShadow = true;
      cityGroup.add(building);

      // Windows
      const windowMat = new THREE.MeshStandardMaterial({
        color: 0xffffcc, emissive: 0xffffaa, emissiveIntensity: 0.1,
        roughness: 0.1, metalness: 0.8
      });
      for (let wy = 1; wy < bh - 1; wy += 2) {
        for (let wx = -bw/2 + 1; wx < bw/2 - 0.5; wx += 1.5) {
          // Front
          const wGeo = new THREE.PlaneGeometry(0.6, 0.8);
          const w1 = new THREE.Mesh(wGeo, windowMat);
          w1.position.set(bx + wx, wy + 0.15, bz + bd / 2 + 0.01);
          cityGroup.add(w1);
          // Back
          const w2 = w1.clone();
          w2.position.z = bz - bd / 2 - 0.01;
          w2.rotation.y = Math.PI;
          cityGroup.add(w2);
        }
      }
    }

    // Trees
    const numTrees = Math.floor(Math.random() * 3);
    for (let t = 0; t < numTrees; t++) {
      const tx = cx + (Math.random() - 0.5) * (BLOCK_SIZE - 4);
      const tz = cz + (Math.random() - 0.5) * (BLOCK_SIZE - 4);
      const trunkGeo = new THREE.CylinderGeometry(0.15, 0.2, 2, 6);
      const trunkMat = new THREE.MeshStandardMaterial({ color: 0x8B4513 });
      const trunk = new THREE.Mesh(trunkGeo, trunkMat);
      trunk.position.set(tx, 1.15, tz);
      trunk.castShadow = true;
      cityGroup.add(trunk);

      const leavesGeo = new THREE.SphereGeometry(1.2, 8, 6);
      const leavesMat = new THREE.MeshStandardMaterial({ color: 0x2d7d2d });
      const leaves = new THREE.Mesh(leavesGeo, leavesMat);
      leaves.position.set(tx, 2.8, tz);
      leaves.castShadow = true;
      cityGroup.add(leaves);
    }
  }
}

// Build streets
for (let row = 0; row < GRID_CELLS; row++) {
  for (let col = 0; col < GRID_CELLS; col++) {
    if (!isStreetCell(row) && !isStreetCell(col)) continue;

    const cx = cellToWorld(col);
    const cz = cellToWorld(row);

    if (isStreetCell(row) && isStreetCell(col)) {
      // Intersection
      const intSize = STREET_WIDTH;
      const intGeo = new THREE.BoxGeometry(intSize, 0.12, intSize);
      const intersection = new THREE.Mesh(intGeo, matAsphalt);
      intersection.position.set(cx, 0.06, cz);
      intersection.receiveShadow = true;
      cityGroup.add(intersection);

      // Crosswalk stripes
      const stripeMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
      for (let s = -3; s <= 3; s += 1.2) {
        const stripeGeo = new THREE.PlaneGeometry(0.4, 0.15);
        // Horizontal crosswalk
        const hs = new THREE.Mesh(stripeGeo, stripeMat);
        hs.rotation.x = -Math.PI / 2;
        hs.position.set(cx + s, 0.13, cz + intSize / 2 + 0.5);
        cityGroup.add(hs);
        const hs2 = hs.clone();
        hs2.position.z = cz - intSize / 2 - 0.5;
        cityGroup.add(hs2);
        // Vertical crosswalk
        const vs = new THREE.Mesh(stripeGeo, stripeMat);
        vs.rotation.x = -Math.PI / 2;
        vs.rotation.z = Math.PI / 2;
        vs.position.set(cx + intSize / 2 + 0.5, 0.13, cz + s);
        cityGroup.add(vs);
        const vs2 = vs.clone();
        vs2.position.x = cx - intSize / 2 - 0.5;
        cityGroup.add(vs2);
      }
    } else if (isStreetCell(row)) {
      // Horizontal street
      const hGeo = new THREE.BoxGeometry(GRID_CELLS * CELL_SIZE, 0.12, STREET_WIDTH);
      const hStreet = new THREE.Mesh(hGeo, matAsphalt);
      hStreet.position.set(0, 0.06, cz);
      hStreet.receiveShadow = true;
      cityGroup.add(hStreet);

      // Center line (dashed)
      const dashLen = 1.5;
      const gapLen = 1.5;
      const totalLen = GRID_CELLS * CELL_SIZE;
      for (let d = -totalLen / 2; d < totalLen / 2; d += dashLen + gapLen) {
        const dashGeo = new THREE.PlaneGeometry(dashLen, 0.1);
        const dash = new THREE.Mesh(dashGeo, matRoadLine);
        dash.rotation.x = -Math.PI / 2;
        dash.position.set(d, 0.13, cz);
        cityGroup.add(dash);
      }
    } else if (isStreetCell(col)) {
      // Vertical street
      const vGeo = new THREE.BoxGeometry(STREET_WIDTH, 0.12, GRID_CELLS * CELL_SIZE);
      const vStreet = new THREE.Mesh(vGeo, matAsphalt);
      vStreet.position.set(cx, 0.06, 0);
      vStreet.receiveShadow = true;
      cityGroup.add(vStreet);

      // Center line
      for (let d = -totalLen / 2; d < totalLen / 2; d += dashLen + gapLen) {
        const dashGeo = new THREE.PlaneGeometry(0.1, dashLen);
        const dash = new THREE.Mesh(dashGeo, matRoadLine);
        dash.rotation.x = -Math.PI / 2;
        dash.position.set(cx, 0.13, d);
        cityGroup.add(dash);
      }
    }
  }
}

// ============================================================
//  WAYPOINT SYSTEM
// ============================================================
const waypoints = [];
const waypointMap = {};
let waypointIdCounter = 0;

function createWaypoint(x, z, lane, type, data) {
  const wp = {
    id: waypointIdCounter++,
    position: new THREE.Vector3(x, 0.15, z),
    targets: [],
    lane: lane, // 'left' or 'right'
    type: type, // 'straight', 'intersection'
    data: data || {},
    mesh: null
  };

  // Visual marker
  const markerGeo = type === 'intersection'
    ? new THREE.SphereGeometry(0.3, 8, 6)
    : new THREE.SphereGeometry(0.15, 6, 4);
  const markerMat = type === 'intersection'
    ? matIntersection.clone()
    : matWaypoint.clone();
  const marker = new THREE.Mesh(markerGeo, markerMat);
  marker.position.copy(wp.position);
  marker.position.y = 0.3;
  cityGroup.add(marker);
  wp.mesh = marker;

  waypoints.push(wp);
  waypointMap[wp.id] = wp;
  return wp;
}

function generateWaypoints() {
  const halfGrid = (GRID_CELLS - 1) / 2; // 3

  // Horizontal streets (row cells: 1, 3, 5)
  const hStreetRows = [1, 3, 5];
  // Vertical streets (col cells: 1, 3, 5)
  const vStreetCols = [1, 3, 5];

  // For each horizontal street row, create waypoints along columns
  for (const row of hStreetRows) {
    const z = cellToWorld(row);
    for (let col = 0; col < GRID_CELLS; col++) {
      const isIntersection = isStreetCell(col);
      const x = cellToWorld(col);

      if (isIntersection) {
        // Intersection waypoint - middle of intersection
        // Left lane: moves right (positive x)
        const wpLeft = createWaypoint(x, z, 'left', 'intersection', { dir: 'east' });
        // Right lane: moves left (negative x)
        const wpRight = createWaypoint(x, z, 'right', 'intersection', { dir: 'west' });

        // Connect to adjacent street segments
        // Left lane targets: right neighbor in same lane
        if (col + 1 < GRID_CELLS) {
          const nextX = cellToWorld(col + 1);
          if (isStreetCell(col + 1)) {
            // Next intersection
            const nextWp = findWaypoint(nextX, z, 'left');
            if (nextWp) wpLeft.targets.push(nextWp);
          } else {
            // Next block - place waypoint at edge of street
            const edgeX = x + STREET_WIDTH / 2 + 0.5;
            const wpNext = createWaypoint(edgeX, z, 'left', 'straight', { dir: 'east' });
            wpLeft.targets.push(wpNext);
          }
        }
        // Right lane targets: left neighbor
        if (col - 1 >= 0) {
          const prevX = cellToWorld(col - 1);
          if (isStreetCell(col - 1)) {
            const prevWp = findWaypoint(prevX, z, 'right');
            if (prevWp) wpRight.targets.push(prevWp);
          } else {
            const edgeX = x - STREET_WIDTH / 2 - 0.5;
            const wpPrev = createWaypoint(edgeX, z, 'right', 'straight', { dir: 'west' });
            wpRight.targets.push(wpPrev);
          }
        }
      } else {
        // Street segment between intersections
        const x = cellToWorld(col);
        const wpLeft = createWaypoint(x, z, 'left', 'straight', { dir: 'east' });
        const wpRight = createWaypoint(x, z, 'right', 'straight', { dir: 'west' });

        // Connect to neighbors
        if (col > 0 && isStreetCell(col - 1)) {
          const prevWp = findWaypoint(cellToWorld(col - 1), z, 'left');
          if (prevWp) wpLeft.targets.push(prevWp);
        }
        if (col < GRID_CELLS - 1 && isStreetCell(col + 1)) {
          const nextWp = findWaypoint(cellToWorld(col + 1), z, 'left');
          if (nextWp) wpLeft.targets.push(nextWp);
        }
        if (col > 0 && isStreetCell(col - 1)) {
          const prevWp = findWaypoint(cellToWorld(col - 1), z, 'right');
          if (prevWp) wpRight.targets.push(prevWp);
        }
        if (col < GRID_CELLS - 1 && isStreetCell(col + 1)) {
          const nextWp = findWaypoint(cellToWorld(col + 1), z, 'right');
          if (nextWp) wpRight.targets.push(nextWp);
        }
      }
    }
  }

  // For vertical streets, create waypoints
  for (const col of vStreetCols) {
    const x = cellToWorld(col);
    for (let row = 0; row < GRID_CELLS; row++) {
      const isIntersection = isStreetCell(row);
      const z = cellToWorld(row);

      if (isIntersection) {
        // Already created intersection waypoints from horizontal pass
        // Add vertical connections to them
        const wpLeft = findWaypoint(x, z, 'left');
        const wpRight = findWaypoint(x, z, 'right');

        // Left lane (moving north/up = negative z)
        if (row - 1 >= 0) {
          const prevZ = cellToWorld(row - 1);
          if (isStreetCell(row - 1)) {
            const prevWp = findWaypoint(x, prevZ, 'left');
            if (prevWp) wpLeft.targets.push(prevWp);
          } else {
            const edgeZ = z - STREET_WIDTH / 2 - 0.5;
            const wpPrev = createWaypoint(x, edgeZ, 'left', 'straight', { dir: 'north' });
            wpLeft.targets.push(wpPrev);
          }
        }
        if (row + 1 < GRID_CELLS) {
          const nextZ = cellToWorld(row + 1);
          if (isStreetCell(row + 1)) {
            const nextWp = findWaypoint(x, nextZ, 'left');
            if (nextWp) wpLeft.targets.push(nextWp);
          } else {
            const edgeZ = z + STREET_WIDTH / 2 + 0.5;
            const wpNext = createWaypoint(x, edgeZ, 'left', 'straight', { dir: 'south' });
            wpLeft.targets.push(wpNext);
          }
        }

        // Right lane (moving south/down = positive z)
        if (row - 1 >= 0) {
          const prevZ = cellToWorld(row - 1);
          if (isStreetCell(row - 1)) {
            const prevWp = findWaypoint(x, prevZ, 'right');
            if (prevWp) wpRight.targets.push(prevWp);
          } else {
            const edgeZ = z - STREET_WIDTH / 2 - 0.5;
            const wpPrev = createWaypoint(x, edgeZ, 'right', 'straight', { dir: 'south' });
            wpRight.targets.push(wpPrev);
          }
        }
        if (row + 1 < GRID_CELLS) {
          const nextZ = cellToWorld(row + 1);
          if (isStreetCell(row + 1)) {
            const nextWp = findWaypoint(x, nextZ, 'right');
            if (nextWp) wpRight.targets.push(nextWp);
          } else {
            const edgeZ = z + STREET_WIDTH / 2 + 0.5;
            const wpNext = createWaypoint(x, edgeZ, 'right', 'straight', { dir: 'north' });
            wpRight.targets.push(wpNext);
          }
        }
      }
    }
  }

  // Clean up duplicate waypoints at intersections
  // Merge waypoints that are at the same position with same lane
  const merged = mergeDuplicateWaypoints();
  return merged;
}

function findWaypoint(x, z, lane) {
  for (const wp of waypoints) {
    if (wp.position.x === x && wp.position.z === z && wp.lane === lane) {
      return wp;
    }
  }
  return null;
}

function mergeDuplicateWaypoints() {
  // Remove waypoints that are duplicates (same position and lane)
  // Keep only the intersection ones at intersections
  const toRemove = new Set();
  const seen = {};

  for (const wp of waypoints) {
    const key = `${wp.position.x},${wp.position.z},${wp.lane}`;
    if (seen[key]) {
      toRemove.add(wp.id);
    } else {
      seen[key] = wp;
    }
  }

  // Remove duplicates
  for (const id of toRemove) {
    const idx = waypoints.findIndex(w => w.id === id);
    if (idx !== -1) {
      if (waypoints[idx].mesh) cityGroup.remove(waypoints[idx].mesh);
      waypoints.splice(idx, 1);
      delete waypointMap[id];
    }
  }

  return waypoints;
}

// Regenerate with cleaner approach
function rebuildWaypoints() {
  // Clear existing
  for (const wp of waypoints) {
    if (wp.mesh) cityGroup.remove(wp.mesh);
  }
  waypoints.length = 0;
  Object.keys(waypointMap).forEach(k => delete waypointMap[k]);
  waypointIdCounter = 0;

  const halfGrid = (GRID_CELLS - 1) / 2;

  // Generate waypoints for horizontal streets
  const hRows = [1, 3, 5];
  const vCols = [1, 3, 5];

  // First pass: create all waypoints
  for (const row of hRows) {
    const z = cellToWorld(row);
    for (let col = 0; col < GRID_CELLS; col++) {
      const x = cellToWorld(col);
      const isInt = isStreetCell(col);

      // Left lane waypoint
      createWaypoint(x, z, 'left', isInt ? 'intersection' : 'straight', {
        axis: 'x', dir: col < halfGrid ? 1 : -1
      });
      // Right lane waypoint
      createWaypoint(x, z, 'right', isInt ? 'intersection' : 'straight', {
        axis: 'x', dir: col < halfGrid ? -1 : 1
      });
    }
  }

  for (const col of vCols) {
    const x = cellToWorld(col);
    for (let row = 0; row < GRID_CELLS; row++) {
      const z = cellToWorld(row);
      const isInt = isStreetCell(row);

      // For vertical streets, left lane = going up (negative z), right lane = going down (positive z)
      createWaypoint(x, z, 'left', isInt ? 'intersection' : 'straight', {
        axis: 'z', dir: row < halfGrid ? -1 : 1
      });
      createWaypoint(x, z, 'right', isInt ? 'intersection' : 'straight', {
        axis: 'z', dir: row < halfGrid ? 1 : -1
      });
    }
  }

  // Second pass: connect waypoints
  for (const wp of waypoints) {
    if (wp.type === 'intersection') {
      // Intersection: connect to all reachable waypoints
      const { x, z } = wp.position;
      const { axis, dir } = wp.data;

      if (axis === 'x') {
        // Horizontal intersection - connect to left and right along x
        // Find neighbors in same lane along x
        const sameLane = waypoints.filter(w =>
          w.lane === wp.lane && w.type === 'intersection' &&
          Math.abs(w.position.z - z) < 0.1 && w.id !== wp.id
        );
        // Sort by distance
        sameLane.sort((a, b) => Math.abs(a.position.x - x) - Math.abs(b.position.x - x));

        // Connect to nearest neighbors
        for (const neighbor of sameLane) {
          if (!wp.targets.includes(neighbor)) {
            wp.targets.push(neighbor);
          }
        }

        // Also connect to vertical street segments at this intersection
        // (already handled by vertical pass)
      } else {
        // Vertical intersection
        const sameLane = waypoints.filter(w =>
          w.lane === wp.lane && w.type === 'intersection' &&
          Math.abs(w.position.x - x) < 0.1 && w.id !== wp.id
        );
        sameLane.sort((a, b) => Math.abs(a.position.z - z) - Math.abs(b.position.z - z));

        for (const neighbor of sameLane) {
          if (!wp.targets.includes(neighbor)) {
            wp.targets.push(neighbor);
          }
        }
      }
    } else {
      // Straight segment: connect to nearest same-lane waypoint
      const sameLane = waypoints.filter(w =>
        w.lane === wp.lane && w.id !== wp.id
      );

      // Find closest neighbor(s)
      const dists = sameLane.map(w => ({
        wp: w,
        dist: wp.position.distanceTo(w.position)
      }));
      dists.sort((a, b) => a.dist - b.dist);

      // Connect to up to 2 nearest (one in each direction along the street)
      const maxDist = 30; // max connection distance
      for (const d of dists) {
        if (d.dist > maxDist) break;
        if (!wp.targets.includes(d.wp)) {
          wp.targets.push(d.wp);
        }
      }
    }
  }

  return waypoints;
}

const allWaypoints = rebuildWaypoints();

console.log(`Generated ${allWaypoints.length} waypoints`);

// ============================================================
//  CAR TRAFFIC SYSTEM
// ============================================================
const cars = [];

function createCar(startWp) {
  const carGroup = new THREE.Group();

  // Car body
  const bodyGeo = new THREE.BoxGeometry(1.8, 0.8, 3.5);
  const bodyMat = carMaterials[Math.floor(Math.random() * carMaterials.length)];
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.position.y = 0.6;
  body.castShadow = true;
  carGroup.add(body);

  // Car roof
  const roofGeo = new THREE.BoxGeometry(1.4, 0.6, 1.8);
  const roof = new THREE.Mesh(roofGeo, bodyMat);
  roof.position.set(0, 1.3, -0.2);
  roof.castShadow = true;
  carGroup.add(roof);

  // Windshield
  const windGeo = new THREE.PlaneGeometry(1.3, 0.55);
  const windMat = new THREE.MeshStandardMaterial({
    color: 0x88ccff, transparent: true, opacity: 0.6,
    roughness: 0.1, metalness: 0.9
  });
  const windshield = new THREE.Mesh(windGeo, windMat);
  windshield.position.set(0, 1.25, 0.71);
  windshield.rotation.x = -0.2;
  carGroup.add(windshield);

  // Wheels
  const wheelGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.2, 8);
  const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
  const wheelPositions = [
    [-0.9, 0.3, 1.1], [0.9, 0.3, 1.1],
    [-0.9, 0.3, -1.1], [0.9, 0.3, -1.1]
  ];
  for (const pos of wheelPositions) {
    const wheel = new THREE.Mesh(wheelGeo, wheelMat);
    wheel.rotation.z = Math.PI / 2;
    wheel.position.set(...pos);
    wheel.castShadow = true;
    carGroup.add(wheel);
  }

  // Headlights
  const lightGeo = new THREE.SphereGeometry(0.15, 6, 4);
  const lightMat = new THREE.MeshStandardMaterial({
    color: 0xffffcc, emissive: 0xffffcc, emissiveIntensity: 0.8
  });
  const hl1 = new THREE.Mesh(lightGeo, lightMat);
  hl1.position.set(-0.6, 0.6, 1.76);
  carGroup.add(hl1);
  const hl2 = hl1.clone();
  hl2.position.x = 0.6;
  carGroup.add(hl2);

  // Tail lights
  const tailMat = new THREE.MeshStandardMaterial({
    color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.5
  });
  const tl1 = new THREE.Mesh(lightGeo, tailMat);
  tl1.position.set(-0.6, 0.6, -1.76);
  carGroup.add(tl1);
  const tl2 = tl1.clone();
  tl2.position.x = 0.6;
  carGroup.add(tl2);

  carGroup.position.copy(startWp.position);
  carGroup.position.y = 0.15;

  scene.add(carGroup);

  const car = {
    mesh: carGroup,
    currentWaypoint: startWp,
    targetWaypoint: null,
    speed: 3 + Math.random() * 3,
    progress: 0,
    stopped: false,
    stopTimer: 0,
    lane: startWp.lane
  };

  // Set initial direction
  if (startWp.targets.length > 0) {
    car.targetWaypoint = startWp.targets[0];
  }

  cars.push(car);
  return car;
}

// Spawn cars at random waypoints
function spawnCars(count) {
  const intersectionWps = allWaypoints.filter(w => w.type === 'intersection');
  for (let i = 0; i < count; i++) {
    const startWp = intersectionWps[Math.floor(Math.random() * intersectionWps.length)];
    createCar(startWp);
  }
}

spawnCars(20);

function updateCars(dt) {
  for (const car of cars) {
    if (car.stopped) {
      car.stopTimer -= dt;
      if (car.stopTimer <= 0) {
        car.stopped = false;
      }
      continue;
    }

    if (!car.targetWaypoint) {
      // Pick a random target
      if (car.currentWaypoint.targets.length > 0) {
        car.targetWaypoint = car.currentWaypoint.targets[
          Math.floor(Math.random() * car.currentWaypoint.targets.length)
        ];
      } else {
        car.stopped = true;
        car.stopTimer = 2;
        continue;
      }
    }

    const from = car.currentWaypoint.position;
    const to = car.targetWaypoint.position;
    const dist = from.distanceTo(to);

    if (dist < 0.1) {
      // Reached target
      car.currentWaypoint = car.targetWaypoint;
      car.targetWaypoint = null;
      continue;
    }

    // Move toward target
    const moveAmount = car.speed * dt;
    car.progress += moveAmount / dist;

    if (car.progress >= 1) {
      car.progress = 0;
      car.currentWaypoint = car.targetWaypoint;
      car.targetWaypoint = null;
    } else {
      car.mesh.position.lerpVectors(from, to, car.progress);
      car.mesh.position.y = 0.15;

      // Orient car toward target
      const dir = new THREE.Vector3().subVectors(to, from).normalize();
      const angle = Math.atan2(dir.x, dir.z);
      car.mesh.rotation.y = angle;
    }
  }
}

