document.addEventListener('keyup', (e) => { keys[e.code] = false; });

// ============================================================
//  MINIMAP
// ============================================================
const minimapCanvas = document.getElementById('minimap');
const minimapCtx = minimapCanvas.getContext('2d');
minimapCanvas.width = 180;
minimapCanvas.height = 180;

function drawMinimap() {
  const ctx = minimapCtx;
  const w = minimapCanvas.width;
  const h = minimapCanvas.height;
  const scale = w / (GRID_CELLS * CELL_SIZE);

  ctx.fillStyle = '#222';
  ctx.fillRect(0, 0, w, h);

  // Draw streets
  ctx.fillStyle = '#444';
  for (let row = 0; row < GRID_CELLS; row++) {
    for (let col = 0; col < GRID_CELLS; col++) {
      if (!isBlockCell(row) || !isBlockCell(col)) {
        const x = (cellToWorld(col) + GRID_CELLS * CELL_SIZE / 2) * scale;
        const y = (cellToWorld(row) + GRID_CELLS * CELL_SIZE / 2) * scale;
        const size = (isBlockCell(row) ? STREET_WIDTH : BLOCK_SIZE + STREET_WIDTH) * scale;
        const size2 = (isBlockCell(col) ? STREET_WIDTH : BLOCK_SIZE + STREET_WIDTH) * scale;
        ctx.fillRect(x - size / 2, y - size2 / 2, size, size2);
      }
    }
  }

  // Draw blocks
  ctx.fillStyle = '#3a5a3a';
  for (let row = 0; row < GRID_CELLS; row++) {
    for (let col = 0; col < GRID_CELLS; col++) {
      if (isBlockCell(row) && isBlockCell(col)) {
        const x = (cellToWorld(col) + GRID_CELLS * CELL_SIZE / 2) * scale;
        const y = (cellToWorld(row) + GRID_CELLS * CELL_SIZE / 2) * scale;
        ctx.fillRect(x - BLOCK_SIZE * scale / 2, y - BLOCK_SIZE * scale / 2,
                     BLOCK_SIZE * scale, BLOCK_SIZE * scale);
      }
    }
  }

  // Draw cars
  for (const car of cars) {
    const x = (car.mesh.position.x + GRID_CELLS * CELL_SIZE / 2) * scale;
    const y = (car.mesh.position.z + GRID_CELLS * CELL_SIZE / 2) * scale;
    ctx.fillStyle = '#ff4444';
    ctx.fillRect(x - 2, y - 2, 4, 4);
  }

  // Draw player
  const px = (player.position.x + GRID_CELLS * CELL_SIZE / 2) * scale;
  const py = (player.position.z + GRID_CELLS * CELL_SIZE / 2) * scale;
  ctx.fillStyle = '#00ff00';
  ctx.beginPath();
  ctx.arc(px, py, 4, 0, Math.PI * 2);
  ctx.fill();

  // Camera direction indicator
  ctx.strokeStyle = '#00ff00';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(px, py);
  ctx.lineTo(px + Math.sin(cameraYaw) * 10, py - Math.cos(cameraYaw) * 10);
  ctx.stroke();
}

// ============================================================
//  GAME LOOP
// ============================================================
const clock = new THREE.Clock();
let playerVelocity = new THREE.Vector3();
let isJumping = false;
let jumpVelocity = 0;

function updatePlayer(dt) {
  const moveSpeed = 12;
  const friction = 8;

  // Get camera direction (horizontal only)
  const camDirX = Math.sin(cameraYaw);
  const camDirZ = Math.cos(cameraYaw);

  // Camera-right vector
  const camRightX = Math.cos(cameraYaw);
  const camRightZ = -Math.sin(cameraYaw);

  let moveX = 0;
  let moveZ = 0;

  if (keys['KeyW'] || keys['ArrowUp']) {
    moveX += camDirX;
    moveZ += camDirZ;
  }
  if (keys['KeyS'] || keys['ArrowDown']) {
    moveX -= camDirX;
    moveZ -= camDirZ;
  }
  if (keys['KeyA'] || keys['ArrowLeft']) {
    moveX -= camRightX;
    moveZ -= camRightZ;
  }
  if (keys['KeyD'] || keys['ArrowRight']) {
    moveX += camRightX;
    moveZ += camRightZ;
  }

  // Normalize
  if (moveX !== 0 || moveZ !== 0) {
    const len = Math.sqrt(moveX * moveX + moveZ * moveZ);
    moveX /= len;
    moveZ /= len;
  }

  // Apply acceleration
  playerVelocity.x += moveX * moveSpeed * dt;
  playerVelocity.z += moveZ * moveSpeed * dt;

  // Apply friction
  playerVelocity.x -= playerVelocity.x * friction * dt;
  playerVelocity.z -= playerVelocity.z * friction * dt;

  // Jump
  if (keys['Space'] && !isJumping) {
    isJumping = true;
    jumpVelocity = 8;
  }

  if (isJumping) {
    jumpVelocity -= 20 * dt;
    player.position.y += jumpVelocity * dt;
    if (player.position.y <= 0.75) {
      player.position.y = 0.75;
      isJumping = false;
      jumpVelocity = 0;
    }
  }

  // Apply velocity
  player.position.x += playerVelocity.x * dt;
  player.position.z += playerVelocity.z * dt;

  // Keep player on ground (y = 0.75)
  player.position.y = 0.75;

  // Update player mesh
  player.position.y = player.position.y;
  player.rotation.y = cameraYaw + Math.PI;

  // Clamp to city bounds
  const bound = (GRID_CELLS * CELL_SIZE) / 2 + 5;
  player.position.x = Math.max(-bound, Math.min(bound, player.position.x));
  player.position.z = Math.max(-bound, Math.min(bound, player.position.z));
}

function updateCamera() {
  const targetPos = player.position.clone();
  targetPos.y += 1;

  // Camera position based on spherical coordinates
  const camX = targetPos.x + cameraDistance * Math.sin(cameraYaw) * Math.cos(cameraPitch);
  const camY = targetPos.y + cameraDistance * Math.sin(cameraPitch);
  const camZ = targetPos.z + cameraDistance * Math.cos(cameraYaw) * Math.cos(cameraPitch);

  camera.position.set(camX, camY, camZ);
  camera.lookAt(targetPos);
}

function animate() {
  requestAnimationFrame(animate);

  const dt = Math.min(clock.getDelta(), 0.05);

  updatePlayer(dt);
  updateCamera();
  updateCars(dt);
  drawMinimap();

  // Animate waypoint markers
  const time = clock.elapsedTime;
  for (const wp of waypoints) {
    if (wp.mesh) {
      wp.mesh.position.y = 0.3 + Math.sin(time * 2 + wp.id) * 0.1;
      wp.mesh.rotation.y = time;
    }
  }

  renderer.render(scene, camera);
}

// ============================================================
//  RESIZE
// ============================================================
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ============================================================
//  START
// ============================================================
animate();
</script>
