    transform: translateY(-2px);
  }

  .vuln-piece.selected {
    border-color: var(--cyan);
    background: rgba(0,255,255,0.1);
    color: var(--cyan);
  }

  .vuln-piece.used {
    opacity: 0.3;
    pointer-events: none;
  }

  /* Exploitation Terminal */
  .exploit-terminal {
    background: #000;
    border: 1px solid var(--bg4);
    border-radius: 8px;
    padding: 20px;
    font-family: 'Share Tech Mono', monospace;
    font-size: 0.85em;
    line-height: 1.8;
    margin: 15px 0;
    position: relative;
  }

  .exploit-terminal .line {
    margin-bottom: 2px;
  }

  .exploit-terminal .cursor {
    display: inline-block;
    width: 8px;
    height: 16px;
    background: var(--green);
    animation: blink 1s step-end infinite;
    vertical-align: middle;
  }

  @keyframes blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
  }

  /* Typing effect */
  .typing-text {
    overflow: hidden;
    white-space: nowrap;
    border-right: 2px solid var(--green);
    animation: typing 2s steps(40) forwards, blink-caret 0.75s step-end infinite;
  }

  @keyframes typing {
    from { width: 0; }
    to { width: 100%; }
  }

  @keyframes blink-caret {
    50% { border-color: transparent; }
  }

  /* Stats */
  .stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: 12px;
    margin: 15px 0;
  }

  .stat-item {
    background: var(--bg3);
    border: 1px solid var(--bg4);
    border-radius: 8px;
    padding: 15px;
    text-align: center;
  }

  .stat-value {
    font-size: 1.5em;
    font-weight: 700;
    color: var(--green);
    font-family: 'Share Tech Mono', monospace;
  }

  .stat-label {
    font-size: 0.7em;
    color: #666;
    margin-top: 4px;
  }

  /* Tooltip */
  .tooltip {
    position: relative;
    display: inline-block;
    border-bottom: 1px dashed var(--green);
    cursor: help;
    color: var(--green);
  }

  .tooltip .tooltip-text {
    visibility: hidden;
    background: var(--bg3);
    color: var(--text);
    padding: 10px 14px;
    border-radius: 6px;
    border: 1px solid var(--bg4);
    font-size: 0.8em;
    position: absolute;
    z-index: 10;
    bottom: 125%;
    left: 50%;
    transform: translateX(-50%);
    width: 250px;
    text-align: center;
    opacity: 0;
    transition: all 0.3s;
    pointer-events: none;
    line-height: 1.5;
  }

  .tooltip:hover .tooltip-text {
    visibility: visible;
    opacity: 1;
  }

  /* Scanner animation */
  .scanner-line {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 2px;
    background: linear-gradient(90deg, transparent, var(--green), transparent);
    animation: scan 2s linear infinite;
    pointer-events: none;
  }

  @keyframes scan {
    0% { top: 0; }
    100% { top: 100%; }
  }

  /* Glitch effect */
  .glitch {
    animation: glitch 0.3s ease;
  }

  @keyframes glitch {
    0% { transform: translate(0); }
    20% { transform: translate(-2px, 2px); }
    40% { transform: translate(2px, -2px); }
    60% { transform: translate(-1px, -1px); }
    80% { transform: translate(1px, 1px); }
    100% { transform: translate(0); }
  }

  /* Score popup */
  .score-popup {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 2em;
    font-weight: 700;
    color: var(--green);
    text-shadow: 0 0 30px rgba(0,255,65,0.5);
    z-index: 100;
    pointer-events: none;
    animation: scorePop 1s ease forwards;
  }

  @keyframes scorePop {
    0% { opacity: 0; transform: translate(-50%, -50%) scale(0.5); }
    30% { opacity: 1; transform: translate(-50%, -50%) scale(1.2); }
    70% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
    100% { opacity: 0; transform: translate(-50%, -60%) scale(0.8); }
  }

  /* Final screen */
  .final-screen {
    text-align: center;
    padding: 40px 20px;
  }

  .final-screen h2 {
    font-size: 1.5em;
    color: var(--green);
    margin-bottom: 20px;
  }

  .final-screen .rank {
    font-size: 3em;
    margin: 20px 0;
    font-family: 'Share Tech Mono', monospace;
  }

  .rank-bronze { color: #cd7f32; }
  .rank-silver { color: #c0c0c0; }
  .rank-gold { color: #ffd700; }
  .rank-master { color: var(--green); text-shadow: 0 0 30px rgba(0,255,65,0.5); }

  /* Responsive */
  @media (max-width: 600px) {
    .header h1 { font-size: 1.3em; }
    .network-grid { grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); }
    .phase-indicator { font-size: 0.65em; padding: 4px 8px; }
    .edu-card { padding: 18px; }
    .terminal-body { padding: 15px; font-size: 0.8em; }
  }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 6px; }
  ::-webkit-scrollbar-track { background: var(--bg); }
  ::-webkit-scrollbar-thumb { background: var(--bg4); border-radius: 3px; }
  ::-webkit-scrollbar-thumb:hover { background: var(--dim-green); }

  .section-title {
    color: var(--green);
    font-size: 1.2em;
    margin-bottom: 15px;
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .section-title::before {
    content: '>';
    color: var(--dim-green);
  }

  .hint-box {
    background: rgba(0,170,255,0.08);
    border: 1px solid rgba(0,170,255,0.2);
    border-radius: 8px;
    padding: 12px 16px;
    margin: 15px 0;
    font-size: 0.82em;
    color: var(--blue);
    line-height: 1.6;
  }

  .hint-box strong {
    color: var(--cyan);
  }

  .password-input {
    background: var(--bg);
    border: 1px solid var(--bg4);
    border-radius: 6px;
    padding: 10px 14px;
    color: var(--green);
    font-family: 'Fira Code', monospace;
    font-size: 0.9em;
    width: 100%;
    max-width: 300px;
    outline: none;
    transition: border-color 0.3s;
  }

  .password-input:focus {
    border-color: var(--green);
    box-shadow: 0 0 10px rgba(0,255,65,0.1);
  }

  .password-input::placeholder {
    color: #444;
  }

  .input-group {
    display: flex;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
    margin: 15px 0;
  }

  .progress-ring {
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }

  .flag-display {
    background: var(--bg3);
    border: 1px solid var(--bg4);
    border-radius: 6px;
    padding: 8px 14px;
    font-family: 'Share Tech Mono', monospace;
    color: var(--cyan);
    font-size: 0.85em;
    display: inline-block;
    margin: 5px;
  }

  .flag-display.earned {
    border-color: var(--green);
    background: rgba(0,255,65,0.08);
    color: var(--green);
  }

  .flags-container {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 10px 0;
  }
</style>
</head>
<body>

<canvas id="matrix-bg"></canvas>

<div class="game-container">
  <div class="header">
    <h1>⟨ HOW A HACKER THINKS ⟩</h1>
    <div class="subtitle">Mindset • Reconnaissance • Exploitation — An Educational Cybersecurity Game</div>
  </div>

  <div class="progress-container">
    <div class="phase-indicator active" id="phase1-ind">
      <div class="phase-dot"></div>
      <span>MINDSET</span>
    </div>
    <div class="progress-bar-track">
      <div class="progress-bar-fill" id="progress-fill"></div>
    </div>
    <div class="phase-indicator locked" id="phase2-ind">
      <div class="phase-dot"></div>
      <span>RECON</span>
    </div>
    <div class="phase-indicator locked" id="phase3-ind">
      <div class="phase-dot"></div>
      <span>EXPLOIT</span>
    </div>
    <div class="score-display" id="score-display">SCORE: 0</div>
  </div>

  <!-- ==================== INTRO SCREEN ==================== -->
  <div class="screen active" id="screen-intro">
    <div class="terminal">
      <div class="terminal-header">
        <div class="terminal-dot red"></div>
        <div class="terminal-dot yellow"></div>
        <div class="terminal-dot green"></div>
        <span class="terminal-title">welcome — hacker-mindset.exe</span>
      </div>
      <div class="terminal-body">
        <div class="output"><span class="prompt">root@cyber-academy:~$</span> <span class="cmd">cat welcome.txt</span></div>
        <div class="output" style="margin-top:12px;">
          <span class="highlight">╔══════════════════════════════════════════╗</span><br>
          <span class="highlight">║</span>  Welcome, Recruit. Today you learn to    <span class="highlight">║</span><br>
          <span class="highlight">║</span>  think like a hacker.                    <span class="highlight">║</span><br>
          <span class="highlight">║</span>                                          <span class="highlight">║</span><br>
          <span class="highlight">║</span>  A hacker doesn't just break in — they   <span class="highlight">║</span><br>
          <span class="highlight">║</span>  <span class="success">understand</span> the system first.           <span class="highlight">║</span><br>
          <span class="highlight">║</span>  They observe, they plan, they adapt.    <span class="highlight">║</span><br>
          <span class="highlight">║</span>                                          <span class="highlight">║</span><br>
          <span class="highlight">║</span>  This game has <span class="warning">3 phases</span>:               <span class="highlight">║</span><br>
          <span class="highlight">║</span>  1. <span class="success">MINDSET</span> — Learn how hackers think  <span class="highlight">║</span><br>
          <span class="highlight">║</span>  2. <span class="success">RECON</span> — Gather intelligence        <span class="highlight">║</span><br>
          <span class="highlight">║</span>  3. <span class="success">EXPLOITATION</span> — Chain vulnerabilities<span class="highlight">║</span><br>
          <span class="highlight">║</span>                                          <span class="highlight">║</span><br>
          <span class="highlight">║</span>  Earn <span class="cyan">flags</span> and <span class="cyan">points</span> at each stage.  <span class="highlight">║</span><br>
          <span class="highlight">╚══════════════════════════════════════════╝</span>
        </div>
        <div class="output" style="margin-top:15px;">
          <span class="info">ℹ</span> This is an <span class="success">educational</span> simulation. All targets are fictional.
        </div>
        <div class="output"><span class="prompt">root@cyber-academy:~$</span> <span class="cursor"></span></div>
      </div>
    </div>

    <div class="edu-card">
      <h3>🎯 What You'll Learn</h3>
      <p><strong>The Hacker Mindset:</strong> Understanding that hacking is fundamentally about <span class="tooltip">creative problem-solving<span class="tooltip-text">Hackers see systems not as rigid structures but as puzzles with hidden paths. They ask "what if?" and "why not?" constantly.</span></span> — asking questions others don't think to ask.</p>
      <p><strong>Reconnaissance:</strong> 80-90% of a real engagement is gathering information. Learning to collect data about targets without being detected.</p>
      <p><strong>Exploitation:</strong> Understanding how vulnerabilities chain together. One weak link can compromise an entire system.</p>
      <div style="margin-top:12px;">
        <span class="concept-tag">Ethical Hacking</span>
        <span class="concept-tag">Penetration Testing</span>
        <span class="concept-tag">OSINT</span>
        <span class="concept-tag">Vulnerability Assessment</span>
        <span class="concept-tag">Defense in Depth</span>
      </div>
    </div>

    <div class="btn-group" style="justify-content:center;">
      <button class="btn" onclick="startGame()">[ INITIALIZE TRAINING ]</button>
    </div>
  </div>

  <!-- ==================== PHASE 1: MINDSET ==================== -->
  <div class="screen" id="screen-phase1">
    <div class="section-title">PHASE 1: THE HACKER MINDSET</div>

    <div class="edu-card">
      <h3>🧠 Thinking Like a Hacker</h3>
      <p>Before any tool is launched, a hacker develops a <strong>mental model</strong> of the target. They think about:</p>
      <p>• <span class="success">Trust boundaries</span> — Where does the system trust input?</p>
      <p>• <span class="success">Attack surface</span> — What can be reached from the outside?</p>
      <p>• <span class="success">Assumptions</span> — What does the system assume is true that might be false?</p>
      <p>• <span class="success">Chain of trust</span> — What happens if one component is compromised?</p>
    </div>

    <div class="terminal">
      <div class="terminal-header">
        <div class="terminal-dot red"></div>
        <div class="terminal-dot yellow"></div>
        <div class="terminal-dot green"></div>
        <span class="terminal-title">mindset — scenario-01.txt</span>
      </div>
      <div class="terminal-body">
        <div class="output"><span class="prompt">scenario@mindset:~$</span> <span class="cmd">load scenario --id=web-app-auth</span></div>
        <div class="output" style="margin-top:10px;">
          <span class="info">[SCENARIO]</span> You're analyzing a web application's login page.<br>
          <span class="info">[OBSERVATION]</span> The login form has username/password fields.<br>
          <span class="info">[OBSERVATION]</span> After 5 failed attempts, you get a "lockout" message.<br>
          <span class="info">[OBSERVATION]</span> The error message says: <span class="warning">"Username not found"</span> vs <span class="warning">"Invalid password"</span><br>
          <span class="info">[QUESTION]</span> What vulnerability does this reveal?
        </div>
      </div>
    </div>

    <div id="quiz1-container">
      <p style="color:var(--white); margin-bottom:12px; font-size:0.9em;"><strong>Q1:</strong> The different error messages for "user not found" vs "wrong password" allow an attacker to:</p>
      <button class="quiz-option" onclick="checkQuiz1(this, false)">A) Brute force the password faster</button>
      <button class="quiz-option" onclick="checkQuiz1(this, true)">B) Enumerate valid usernames (user enumeration)</button>
      <button class="quiz-option" onclick="checkQuiz1(this, false)">C) Bypass the login entirely</button>
      <button class="quiz-option" onclick="checkQuiz1(this, false)">D) Crash the authentication server</button>
      <div class="quiz-feedback" id="quiz1-feedback"></div>
    </div>

    <div id="quiz2-container" style="display:none; margin-top:25px;">
      <div class="edu-card">
        <h3>✅ Correct! User Enumeration</h3>
        <p>Different error messages reveal whether a username exists in the system. An attacker can iterate through common usernames, then focus brute-force attacks on confirmed accounts. This is why systems should return <span class="highlight">generic error messages</span> like "Invalid username or password."</p>
      </div>

      <div class="terminal">
        <div class="terminal-header">
          <div class="terminal-dot red"></div>
          <div class="terminal-dot yellow"></div>
          <div class="terminal-dot green"></div>
          <span class="terminal-title">mindset — scenario-02.txt</span>
        </div>
        <div class="terminal-body">
          <div class="output"><span class="prompt">scenario@mindset:~$</span> <span class="cmd">load scenario --id=developer-assumption</span></div>
          <div class="output" style="margin-top:10px;">
            <span class="info">[SCENARIO]</span> A developer wrote this validation rule:<br>
            <span class="highlight">if (user.role === "admin") { grantAccess(); }</span><br><br>
            <span class="info">[QUESTION]</span> What's the fundamental flaw in this approach?
          </div>
        </div>
      </div>

      <p style="color:var(--white); margin:12px 0; font-size:0.9em;"><strong>Q2:</strong> This code assumes that:</p>
      <button class="quiz-option" onclick="checkQuiz2(this, false)">A) All users have a role field</button>
      <button class="quiz-option" onclick="checkQuiz2(this, false)">B) The admin role is assigned by the system</button>
      <button class="quiz-option" onclick="checkQuiz2(this, true)">C) The role cannot be tampered with by the user</button>
      <button class="quiz-option" onclick="checkQuiz2(this, false)">D) Admin users exist in the database</button>
      <div class="quiz-feedback" id="quiz2-feedback"></div>
    </div>

    <div id="quiz3-container" style="display:none; margin-top:25px;">
      <div class="edu-card">
        <h3>✅ Correct! Trust Boundary Violation</h3>
        <p>This is a classic <span class="tooltip">client-side trust<span class="tooltip-text">Never trust data from the client. If role checking happens in JavaScript on the user's browser, an attacker can modify the role field in browser dev tools before sending the request.</span></span> problem. If role validation happens on the client (browser), an attacker can modify the role in browser developer tools. Server-side validation is essential — <span class="highlight">never trust user input</span>.</p>
      </div>

      <div class="terminal">
        <div class="terminal-header">
          <div class="terminal-dot red"></div>
          <div class="terminal-dot yellow"></div>
          <div class="terminal-dot green"></div>
          <span class="terminal-title">mindset — scenario-03.txt</span>
        </div>
        <div class="terminal-body">
          <div class="output"><span class="prompt">scenario@mindset:~$</span> <span class="cmd">load scenario --id=security-by-obscurity</span></div>
          <div class="output" style="margin-top:10px;">
            <span class="info">[SCENARIO]</span> A company hides their admin panel at <span class="highlight">/admin/secret-panel-x9z2</span><br>
            <span class="info">[OBSERVATION]</span> They have no firewall, no authentication,<br>
            <span class="info">[OBSERVATION]</span> and use the default password "admin123"<br>
            <span class="info">[QUESTION]</span> What security principle are they violating?
          </div>
        </div>
      </div>

      <p style="color:var(--white); margin:12px 0; font-size:0.9em;"><strong>Q3:</strong> Hiding the admin URL instead of securing it violates:</p>
      <button class="quiz-option" onclick="checkQuiz3(this, false)">A) The principle of least privilege</button>
      <button class="quiz-option" onclick="checkQuiz3(this, true)">B) Security by obscurity (Kerckhoffs's principle)</button>
      <button class="quiz-option" onclick="checkQuiz3(this, false)">C) Defense in depth</button>
      <button class="quiz-option" onclick="checkQuiz3(this, false)">D) Zero trust architecture</button>
      <div class="quiz-feedback" id="quiz3-feedback"></div>
    </div>

    <div id="quiz4-container" style="display:none; margin-top:25px;">
      <div class="edu-card">
        <h3>✅ Correct! Security by Obscurity</h3>
        <p><span class="tooltip">Kerckhoffs's principle<span class="tooltip-text">Named after cryptographer Auguste Kerckhoffs: a system should remain secure even if everything about the system, except the key, is public knowledge. Hiding the URL is not security — it's just making it harder to find.</span></span> states that a system should remain secure even if everything about it is known except the key. Hiding an admin URL provides <span class="warning">no real protection</span> — anyone who discovers the URL has full access. Real security requires <span class="highlight">authentication, authorization, and encryption</span>.</p>
      </div>

      <div class="edu-card">
        <h3>🧠 Mindset Summary</h3>
        <p>The hacker's mindset is built on three pillars:</p>
        <p>1. <span class="success">Curiosity</span> — Question every assumption the system makes</p>
        <p>2. <span class="success">Persistence</span> — If one path is blocked, find another</p>
        <p>3. <span class="success">Systematic thinking</span> — Map the attack surface before acting</p>
        <p style="margin-top:10px;">Now that you think like a hacker, it's time to <span class="highlight">gather intelligence</span>.</p>
      </div>

      <div class="btn-group" style="justify-content:center;">
        <button class="btn" onclick="goToPhase(2)">[ PROCEED TO RECONNAISSANCE ]</button>
      </div>
    </div>
  </div>

  <!-- ==================== PHASE 2: RECONNAISSANCE ==================== -->
  <div class="screen" id="screen-phase2">
    <div class="section-title">PHASE 2: RECONNAISSANCE</div>

    <div class="edu-card">
      <h3>🔍 Gathering Intelligence</h3>
      <p>Reconnaissance is the most critical phase. A hacker collects information about the target to identify potential entry points. This includes:</p>
      <p>• <span class="success">Network mapping</span> — Finding live hosts and open ports</p>
      <p>• <span class="success">Service enumeration</span> — What's running on each port?</p>
      <p>• <span class="success">Technology fingerprinting</span> — What software and versions?</p>
      <p>• <span class="success">OSINT</span> — Open Source Intelligence from public sources</p>
    </div>

    <div class="terminal">
      <div class="terminal-header">
        <div class="terminal-dot red"></div>
        <div class="terminal-dot yellow"></div>
        <div class="terminal-dot green"></div>
        <span class="terminal-title">recon — network-scan.sh</span>
      </div>
      <div class="terminal-body">
        <div class="output"><span class="prompt">recon@target:~$</span> <span class="cmd">nmap -sV --script=vuln 10.0.0.0/24</span></div>
        <div class="output" style="margin-top:10px;">
          <span class="info">[SCANNING]</span> Network 10.0.0.0/24 — 256 hosts<br>
          <span class="success">[ALERT]</span> 8 hosts found with open ports.<br>
          <span class="info">[INSTRUCTION]</span> Click on each node to scan it. Identify vulnerabilities.
        </div>
      </div>
    </div>

    <div class="hint-box">
      <strong>💡 Hint:</strong> Focus on nodes with open ports. Each node reveals different services. Look for outdated software versions and misconfigurations. You need to find at least <span style="color:var(--orange);">3 vulnerabilities</span> to proceed.
    </div>

    <div class="network-grid" id="network-grid">
      <!-- Nodes generated by JS -->
    </div>

    <div id="recon-summary" style="display:none; margin-top:20px;">
      <div class="edu-card">
        <h3>📋 Reconnaissance Report</h3>
        <div id="recon-details"></div>
      </div>

      <div class="btn-group" style="justify-content:center;">
        <button class="btn" onclick="goToPhase(3)">[ PROCEED TO EXPLOITATION ]</button>
      </div>
    </div>
  </div>

  <!-- ==================== PHASE 3: EXPLOITATION ==================== -->
  <div class="screen" id="screen-phase3">
    <div class="section-title">PHASE 3: EXPLOITATION — CHAINING VULNERABILITIES</div>

    <div class="edu-card">
      <h3>⛓️ The Exploit Chain</h3>
      <p>Real-world breaches rarely exploit a single vulnerability. Hackers <span class="tooltip">chain multiple weaknesses<span class="tooltip-text">An exploit chain connects multiple vulnerabilities to achieve a goal. For example: XSS → Session Hijack → Privilege Escalation → Data Exfiltration.</span></span> to move from initial access to full compromise.</p>
      <p>Build the correct exploit chain by selecting vulnerabilities in the right order.</p>
    </div>

    <div class="terminal">
      <div class="terminal-header">
        <div class="terminal-dot red"></div>
        <div class="terminal-dot yellow"></div>
        <div class="terminal-dot green"></div>
        <span class="terminal-title">exploit — chain-builder.py</span>
      </div>
      <div class="terminal-body">
        <div class="output"><span class="prompt">exploit@target:~$</span> <span class="cmd">python3 chain-builder.py --target=corp-server</span></div>
        <div class="output" style="margin-top:10px;">
          <span class="info">[TARGET]</span> corp-server.internal (10.0.0.5)<br>
          <span class="info">[OBJECTIVE]</span> Achieve <span class="warning">root access</span><br>
          <span class="info">[AVAILABLE]</span> Select vulnerabilities from the list below and chain them in the correct order.
        </div>
      </div>
