// ==================== MATRIX BACKGROUND ====================
function initMatrix() {
  const canvas = document.getElementById('matrix-bg');
  const ctx = canvas.getContext('2d');
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%^&*()アイウエオカキクケコ';
  const fontSize = 14;
  const columns = Math.floor(canvas.width / fontSize);
  const drops = Array(columns).fill(1);

  function draw() {
    ctx.fillStyle = 'rgba(10, 10, 10, 0.05)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#00ff41';
    ctx.font = fontSize + 'px monospace';

    for (let i = 0; i < drops.length; i++) {
      const text = chars[Math.floor(Math.random() * chars.length)];
      ctx.fillText(text, i * fontSize, drops[i] * fontSize);
      if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
        drops[i] = 0;
      }
      drops[i]++;
    }
  }

  setInterval(draw, 50);

  window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });
}

// ==================== SCREEN MANAGEMENT ====================
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
}

function updateProgress() {
  const fill = document.getElementById('progress-fill');
  const pct = (state.currentPhase / 4) * 100;
  fill.style.width = pct + '%';

  document.getElementById('score-display').textContent = 'SCORE: ' + state.score;

  for (let i = 1; i <= 3; i++) {
    const ind = document.getElementById('phase' + i + '-ind');
    ind.classList.remove('active', 'completed', 'locked');
    if (i < state.currentPhase) ind.classList.add('completed');
    else if (i === state.currentPhase) ind.classList.add('active');
    else ind.classList.add('locked');
  }
}

// ==================== GAME FLOW ====================
function startGame() {
  state.currentPhase = 1;
  updateProgress();
  showScreen('screen-phase1');
}

function goToPhase(phase) {
  state.currentPhase = phase;
  updateProgress();

  if (phase === 2) initRecon();
  if (phase === 3) initExploitation();
  if (phase === 4) showFinal();

  showScreen('screen-phase' + phase);
}

// ==================== PHASE 1: QUIZZES ====================
