  options.forEach(o => {
    o.classList.add('disabled');
    if (o === btn) o.classList.add(correct ? 'correct' : 'incorrect');
  });

  if (correct) {
    state.score += 100;
    state.phase1Score += 100;
    state.flags.push('enum');
