    : '❌ Not quite. The different messages allow <strong>user enumeration</strong> — confirming valid usernames.';

  setTimeout(() => {
    document.getElementById('quiz2-container').style.display = 'block';
    document.getElementById('quiz2-container').scrollIntoView({ behavior: 'smooth' });
  }, 1500);
}

