// ==================== PHASE 2: RECON ====================
function initRecon() {
  const grid = document.getElementById('network-grid');
  grid.innerHTML = '';

  networkNodes.forEach(node => {
    const div = document.createElement('div');
    div.className = 'network-node';
    div.id = 'node-' + node.id;
    div.innerHTML = `
      <div class="node-icon">${node.icon}</div>
      <div class="node-ip">${node.ip}</div>
      <div class="node-label">${node.label}</div>
      <div class="node-status closed" id="status-${node.id}">SCANNING...</div>
    `;
    div.onclick = () => scanNode(node.id);
    grid.appendChild(div);
  });
}

function scanNode(id) {
  if (state.scannedNodes.has(id)) return;
  state.scannedNodes.add(id);

  const node = networkNodes.find(n => n.id === id);
  const el = document.getElementById('node-' + id);
  const statusEl = document.getElementById('status-' + id);

  el.classList.add('scanned');
  el.innerHTML = `
    <div class="node-icon">${node.icon}</div>
    <div class="node-ip">${node.ip}</div>
    <div class="node-label">${node.label}</div>
    <div style="font-size:0.65em; color:var(--cyan); margin-top:4px;">Port: ${node.port}</div>
    <div style="font-size:0.65em; color:var(--text); margin-top:2px;">${node.service}</div>
    <div class="node-status open" id="status-${id}">PORT OPEN</div>
  `;

  // Simulate scanning delay
  setTimeout(() => {
    node.found = true;
    state.foundVulns.add(id);
    state.score += 50;
    state.phase2Score += 50;

    el.classList.add('vulnerable');
    statusEl.className = 'node-status vuln';
    statusEl.textContent = 'VULN FOUND';
    el.innerHTML += `<div style="font-size:0.6em; color:var(--orange); margin-top:4px;">⚠ ${node.vuln}</div>`;

    showScorePopup('+50');

    // Check if all found
    if (state.foundVulns.size >= 3) {
      setTimeout(showReconSummary, 1000);
    }
  }, 800);
}

function showReconSummary() {
  const summary = document.getElementById('recon-summary');
  summary.style.display = 'block';

  const details = document.getElementById('recon-details');
  let html = '<div style="margin-top:10px;">';
  state.foundVulns.forEach(id => {
    const node = networkNodes.find(n => n.id === id);
    html += `<div style="padding:8px 0; border-bottom:1px solid var(--bg4);">
      <span style="color:var(--orange);">⚠</span> <span style="color:var(--cyan);">${node.ip}</span> — ${node.label}<br>
      <span style="color:var(--text); font-size:0.85em;">${node.vuln}</span>
    </div>`;
  });
  html += '</div>';
  details.innerHTML = html;

  state.flags.push('recon');
}

// ==================== PHASE 3: EXPLOITATION ====================
function initExploitation() {
  state.chain = [];
  state.chainComplete = false;
  state.selectedVuln = null;

  renderChain();
  renderVulnPieces();

  document.getElementById('exploit-feedback').style.display = 'none';
  document.getElementById('exploitation-complete').style.display = 'none';
}

function renderChain() {
  for (let i = 0; i < 4; i++) {
    const slot = document.getElementById('slot-' + i);
    if (state.chain[i]) {
      slot.textContent = state.chain[i].name.substring(0, 12) + '...';
      slot.classList.add('filled');
      slot.classList.remove('current');
    } else {
      slot.textContent = (i + 1);
      slot.classList.remove('filled');
      if (i === state.chain.length) slot.classList.add('current');
      else slot.classList.remove('current');
    }
  }

  const statusEl = document.getElementById('chain-status');
  if (state.chain.length === 0) {
    statusEl.textContent = 'empty — select vulnerabilities below';
  } else {
    statusEl.textContent = state.chain.map(v => v.name).join(' → ');
  }
}

function renderVulnPieces() {
  const container = document.getElementById('vuln-pieces');
  container.innerHTML = '';

  // Shuffle the pool
  const shuffled = [...vulnPool].sort(() => Math.random() - 0.5);

  shuffled.forEach(v => {
    const div = document.createElement('div');
    div.className = 'vuln-piece';
    div.textContent = v.name;
    div.title = v.desc;

    if (state.chain.find(c => c.id === v.id)) {
      div.classList.add('used');
    }

    div.onclick = () => selectVuln(v);
    container.appendChild(div);
  });
}

function selectVuln(v) {
  if (state.chain.find(c => c.id === v.id)) return;

  state.chain.push(v);
  renderChain();
  renderVulnPieces();

  // Check if chain is complete
  if (state.chain.length === 4) {
    document.getElementById('exploit-feedback').style.display = 'block';
  }
}

function resetChain() {
  state.chain = [];
  state.selectedVuln = null;
  renderChain();
  renderVulnPieces();
  document.getElementById('exploit-feedback').style.display = 'none';
}

function submitChain() {
  if (state.chain.length < 4) {
    const fb = document.getElementById('exploit-feedback');
    fb.style.display = 'block';
    fb.innerHTML = `<div class="quiz-feedback show incorrect">⚠️ You need to select all 4 vulnerabilities in the chain.</div>`;
    return;
  }

  // Check if chain is correct
  const isCorrect = state.chain.every((v, i) => v.order === i);

  const fb = document.getElementById('exploit-feedback');
  fb.style.display = 'block';

  if (isCorrect) {
    state.score += 200;
    state.phase3Score += 200;
    state.flags.push('chain');
    state.chainComplete = true;
    showScorePopup('+200');

    fb.innerHTML = `<div class="quiz-feedback show correct">
      ✅ <strong>Perfect chain!</strong> You've successfully compromised the target.<br><br>
      <span style="color:var(--cyan);">Chain executed:</span><br>
      ${state.chain.map((v, i) => `<span style="color:var(--green);">${i+1}.</span> ${v.name} — ${v.desc}`).join('<br>')}
    </div>`;

    // Show final chain display
    const finalDisplay = document.getElementById('final-chain-display');
    finalDisplay.innerHTML = state.chain.map((v, i) =>
      `<div style="display:flex; align-items:center; gap:8px; margin:8px 0; padding:10px; background:var(--bg3); border-radius:6px; border:1px solid var(--bg4);">
        <span style="color:var(--green); font-weight:bold;">${i+1}.</span>
        <div>
          <div style="color:var(--cyan); font-weight:600;">${v.name}</div>
          <div style="color:var(--text); font-size:0.85em;">${v.desc}</div>
        </div>
      </div>`
    ).join('<span style="color:var(--dim-green);">→</span>');

    setTimeout(() => {
      document.getElementById('exploitation-complete').style.display = 'block';
      document.getElementById('exploitation-complete').scrollIntoView({ behavior: 'smooth' });
    }, 2000);
  } else {
    fb.innerHTML = `<div class="quiz-feedback show incorrect">
      ❌ <strong>Chain failed.</strong> The order doesn't make logical sense.<br><br>
      <span style="color:var(--text);">Hint: Think about the progression from external access → internal access → privilege escalation → objective.<br>
      Try: XSS → Session Hijack → Privilege Escalation → Root Access</span>
    </div>`;

    // Reset chain after delay
    setTimeout(() => {
      state.chain = [];
      renderChain();
      renderVulnPieces();
    }, 3000);
  }
}

