    rankTitle.innerHTML = '<span style="color:#ffd700;">ELITE HACKER</span>';
  } else if (state.score >= 200) {
    rankEl.textContent = '🥈';
    rankEl.className = 'rank rank-silver';
    rankTitle.innerHTML = '<span style="color:#c0c0c0;">PROMISING RECRUIT</span>';
  } else {
    rankEl.textContent = '🥉';
    rankEl.className = 'rank rank-bronze';
    rankTitle.innerHTML = '<span style="color:#cd7f32;">BEGINNER</span>';
  }
}

