}

// ==================== LIGHTS ====================
function createLights() {
  const ambientLight = new THREE.AmbientLight(0x405060, 0.5);
  scene.add(ambientLight);

  const sunLight = new THREE.DirectionalLight(0xffeedd, 1.2);
