#mode-screen{position:fixed;top:0;left:0;width:100%;height:100%;background:linear-gradient(135deg,#0a0a2e,#1a0a3e);display:none;flex-direction:column;align-items:center;justify-content:center;z-index:850}
.mode-title{font-size:48px;font-weight:900;letter-spacing:5px;margin-bottom:40px;color:#ffd700}
