.plane-info span{color:#ffd700}
#minimap-overlay{position:absolute;top:20px;right:20px;width:200px;height:200px;border:2px solid rgba(255,255,255,0.3);border-radius:8px;overflow:hidden;background:rgba(0,0,0,0.5)}
#minimap-canvas{width:100%;height:100%}
#game-hud{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;display:none;z-index:700}
.hud-health{position:absolute;bottom:30px;left:30px;display:flex;flex-direction:column;gap:8px}
.hud-bar{width:250px;height:20px;background:rgba(0,0,0,0.7);border-radius:10px;overflow:hidden;position:relative}
.hud-bar-fill{height:100%;border-radius:10px;transition:width 0.3s}
.hud-bar-text{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:12px;font-weight:700;text-shadow:1px 1px 2px #000}
