.armor-fill{background:linear-gradient(90deg,#4488ff,#66aaff)}
.hud-weapon{position:absolute;bottom:30px;right:30px;text-align:right}
.hud-weapon-name{font-size:24px;font-weight:700;color:#ffd700}
.hud-ammo{font-size:36px;font-weight:900;color:#fff}
.hud-ammo span{font-size:20px;color:#888}
.hud-slots{position:absolute;bottom:30px;left:50%;transform:translateX(-50%);display:flex;gap:5px}
.hud-slot{width:60px;height:60px;background:rgba(0,0,0,0.7);border:2px solid rgba(255,255,255,0.2);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:12px;color:#888;position:relative}
.hud-slot.active{border-color:#ffd700;background:rgba(255,215,0,0.1)}
.hud-slot .slot-num{position:absolute;top:2px;left:5px;font-size:10px;color:#666}
.hud-slot .slot-icon{font-size:24px}
.hud-kill{position:absolute;top:20px;right:20px;background:rgba(0,0,0,0.7);padding:10px 20px;border-radius:8px;font-size:18px}
.hud-kill span{color:#ff4444;font-weight:900}
.hud-timer{position:absolute;top:20px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.7);padding:10px 20px;border-radius:8px;font-size:16px;text-align:center}
.hud-timer .zone-timer{color:#ffd700;font-size:24px;font-weight:900}
.hud-players{position:absolute;top:20px;left:20px;background:rgba(0,0,0,0.7);padding:10px 20px;border-radius:8px}
.hud-players span{color:#44ff44;font-weight:900}
.hud-crosshair{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:20px;height:20px}
.hud-crosshair::before,.hud-crosshair::after{content:'';position:absolute;background:rgba(255,255,255,0.8)}
.hud-crosshair::before{width:2px;height:20px;left:9px;top:0}
.hud-crosshair::after{width:20px;height:2px;top:9px;left:0}
.hud-chat{position:absolute;bottom:120px;left:30px;width:350px;max-height:200px;overflow-y:auto}
.hud-chat-msg{padding:4px 8px;background:rgba(0,0,0,0.5);margin:2px 0;border-radius:4px;font-size:13px}
.hud-chat-msg .name{color:#ffd700;font-weight:700}
.hud-chat-input{width:350px;padding:8px;background:rgba(0,0,0,0.7);border:1px solid rgba(255,255,255,0.2);border-radius:4px;color:#fff;font-size:13px;pointer-events:auto;margin-top:5px}
.hud-zone-warning{position:absolute;top:60px;left:50%;transform:translateX(-50%);background:rgba(255,0,0,0.3);padding:10px 30px;border-radius:8px;font-size:16px;color:#ff4444;font-weight:700;display:none;animation:warningPulse 1s ease-in-out infinite}
@keyframes warningPulse{0%,100%{opacity:1}50%{opacity:0.5}}
.hud-damage{position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;opacity:0;transition:opacity 0.1s}
.hud-damage.active{opacity:1;background:radial-gradient(ellipse at center,transparent 50%,rgba(255,0,0,0.4) 100%)}
.hud-map-full{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.9);display:none;z-index:750;pointer-events:auto}
