#game-over-screen{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.9);display:none;flex-direction:column;align-items:center;justify-content:center;z-index:950}
.game-over-title{font-size:72px;font-weight:900;letter-spacing:10px;margin-bottom:30px}
.victory{background:linear-gradient(45deg,#ffd700,#ff6b35);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.defeat{color:#ff4444}
.stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:20px 0}
.stat-item{background:rgba(255,255,255,0.05);padding:15px 25px;border-radius:8px;text-align:center}
.stat-item .label{font-size:12px;color:#888;margin-bottom:5px}
.stat-item .value{font-size:24px;font-weight:700;color:#ffd700}
.rating{font-size:20px;color:#44ff44;margin:20px 0}
.back-btn{padding:15px 40px;background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.2);color:#fff;font-size:16px;cursor:pointer;border-radius:8px;margin-top:20px;transition:all 0.3s;pointer-events:auto}
.back-btn:hover{background:rgba(255,107,53,0.3);border-color:#ff6b35}
#settings-screen{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.95);display:none;flex-direction:column;align-items:center;justify-content:center;z-index:860}
.settings-title{font-size:48px;font-weight:900;margin-bottom:40px;color:#ffd700}
.setting-row{display:flex;align-items:center;gap:20px;margin:10px 0;width:400px}
.setting-row label{width:150px;text-align:right;color:#888}
.setting-row input[type=range]{flex:1;accent-color:#ff6b35}
.setting-row .val{width:50px;text-align:center;color:#ffd700}
#stats-screen{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.95);display:none;flex-direction:column;align-items:center;justify-content:center;z-index:860}
.stats-title{font-size:48px;font-weight:900;margin-bottom:30px;color:#ffd700}
#pickup-notification{position:fixed;bottom:120px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.8);padding:10px 20px;border-radius:8px;font-size:16px;display:none;z-index:710;border:1px solid rgba(255,215,0,0.3)}
#scope-overlay{position:fixed;top:0;left:0;width:100%;height:100%;display:none;z-index:690;pointer-events:none}
#scope-overlay::before{content:'';position:absolute;top:0;left:0;width:100%;height:100%;background:radial-gradient(circle,transparent 150px,rgba(0,0,0,0.95) 151px)}
#scope-overlay::after{content:'';position:absolute;top:50%;left:50%;width:100%;height:2px;background:rgba(255,255,255,0.5);transform:translate(-50%,-50%)}
</style>
</head>
<body>

<div id="loading-screen">
  <canvas id="particles-canvas"></canvas>
  <div class="logo">REG2</div>
  <div class="logo-sub">BATTLE ROYALE</div>
  <div id="progress-container"><div id="progress-bar"></div></div>
  <div id="progress-text">0%</div>
</div>

<div id="menu-screen">
  <div class="menu-bg"></div>
  <div class="menu-title">REG2</div>
  <div class="menu-level">УРОВЕНЬ <span id="player-level">1</span></div>
  <button class="menu-btn" onclick="showModeSelect()">▶ ИГРАТЬ</button>
  <button class="menu-btn" onclick="showSettings()">⚙ НАСТРОЙКИ</button>
  <button class="menu-btn" onclick="showStats()">📊 СТАТИСТИКА</button>
  <button class="menu-btn" onclick="window.close()">✕ ВЫХОД</button>
</div>

<div id="mode-screen">
  <div class="mode-title">ВЫБОР РЕЖИМА</div>
  <div class="mode-grid">
    <div class="mode-card" onclick="startGame('solo')">
      <div class="icon">👤</div>
      <h3>СОЛО</h3>
      <p>Один против всех</p>
      <div class="players">100 игроков</div>
    </div>
    <div class="mode-card" onclick="startGame('duo')">
      <div class="icon">👥</div>
      <h3>ДУО</h3>
      <p>Пары выживают вместе</p>
      <div class="players">50 команд (100 игроков)</div>
    </div>
    <div class="mode-card" onclick="startGame('squad')">
      <div class="icon">👊</div>
      <h3>ОТРЯД</h3>
      <p>Командная игра</p>
      <div class="players">25 отрядов (100 игроков)</div>
    </div>
  </div>
  <button class="back-btn" onclick="showMenu()">← НАЗАД</button>
</div>

<div id="settings-screen">
  <div class="settings-title">НАСТРОЙКИ</div>
  <div class="setting-row"><label>Громкость</label><input type="range" min="0" max="100" value="70" id="vol-slider"><span class="val" id="vol-val">70%</span></div>
  <div class="setting-row"><label>Чувствительность</label><input type="range" min="1" max="100" value="50" id="sens-slider"><span class="val" id="sens-val">50%</span></div>
  <div class="setting-row"><label>Качество</label><input type="range" min="1" max="3" value="2" id="qual-slider"><span class="val" id="qual-val">Среднее</span></div>
  <button class="back-btn" onclick="showMenu()">← НАЗАД</button>
</div>

<div id="stats-screen">
  <div class="stats-title">СТАТИСТИКА</div>
  <div class="stats-grid" id="stats-grid"></div>
  <button class="back-btn" onclick="showMenu()">← НАЗАД</button>
</div>

<div id="plane-screen">
  <canvas id="plane-canvas"></canvas>
  <div class="plane-info">
    <div>Скорость: <span id="plane-speed">150</span> м/с</div>
    <div>Высота: <span id="plane-alt">400</span> м</div>
    <div>Игроков: <span id="plane-players">100</span></div>
    <div>Путь: <span id="plane-path">A → B</span></div>
  </div>
  <div id="minimap-overlay"><canvas id="minimap-canvas" width="200" height="200"></canvas></div>
  <div class="plane-ui">
    <button class="jump-btn" onclick="jumpFromPlane()">ПРЫЖОК [SPACE]</button>
  </div>
</div>

<div id="game-hud">
  <div class="hud-damage" id="damage-overlay"></div>
  <div class="hud-players">Игроки: <span id="alive-count">100</span></div>
  <div class="hud-timer">
    <div>Зона сжимается через</div>
    <div class="zone-timer" id="zone-timer">5:00</div>
    <div style="font-size:12px;color:#888" id="zone-phase">Фаза 1</div>
  </div>
  <div class="hud-kill">Убийства: <span id="kill-count">0</span></div>
  <div class="hud-crosshair"></div>
  <div class="hud-health">
    <div class="hud-bar"><div class="hud-bar-fill health-fill" id="health-bar" style="width:100%"></div><div class="hud-bar-text" id="health-text">100/100</div></div>
    <div class="hud-bar"><div class="hud-bar-fill armor-fill" id="armor-bar" style="width:0%"></div><div class="hud-bar-text" id="armor-text">0/100</div></div>
  </div>
  <div class="hud-weapon">
    <div class="hud-weapon-name" id="weapon-name">Пистолет</div>
    <div class="hud-ammo"><span id="ammo-current">15</span> / <span id="ammo-reserve">90</span></div>
  </div>
  <div class="hud-slots">
    <div class="hud-slot active"><span class="slot-num">1</span><span class="slot-icon" id="slot-1">🔫</span></div>
    <div class="hud-slot"><span class="slot-num">2</span><span class="slot-icon" id="slot-2">🔫</span></div>
    <div class="hud-slot"><span class="slot-num">3</span><span class="slot-icon" id="slot-3">🔫</span></div>
    <div class="hud-slot"><span class="slot-num">4</span><span class="slot-icon" id="slot-4">💣</span></div>
    <div class="hud-slot"><span class="slot-num">5</span><span class="slot-icon" id="slot-5">🏥</span></div>
  </div>
  <div class="hud-chat" id="chat-box"></div>
  <div class="hud-zone-warning" id="zone-warning">⚠ ВЫ ПОКИНУЛИ БЕЗОПАСНУЮ ЗОНУ!</div>
  <div id="pickup-notification"></div>
</div>

<div id="scope-overlay"></div>

<div class="hud-map-full" id="map-full">
  <canvas id="map-full-canvas"></canvas>
  <button class="back-btn" onclick="toggleMap()" style="position:absolute;top:20px;right:20px">← ЗАКРЫТЬ</button>
</div>

<div id="game-over-screen">
  <div class="game-over-title" id="go-title"></div>
  <div class="stats-grid" id="go-stats"></div>
  <div class="rating" id="go-rating"></div>
  <button class="back-btn" onclick="showMenu()">В МЕНЮ</button>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// ============ GAME STATE ============
const G = {
  state: 'loading', mode: 'solo',
  player: { hp:100, maxHp:100, armor:0, maxArmor:100, x:0, y:500, z:0, vx:0, vy:0, vz:0,
    speed:8, sprintSpeed:14, crouchSpeed:4, proneSpeed:2, isSprinting:false, isCrouching:false, isProne:false,
    isAiming:false, isParachuting:false, isAlive:true, kills:0, damageDealt:0,
    weapons:[], currentWeapon:0, inventory:[], grenades:3, medkits:2,
    level:1, rating:0, totalKills:0, totalWins:0, totalGames:0, totalDamage:0, totalDistance:0, totalTime:0 },
  zone: { x:500, z:500, radius:500, targetRadius:500, phase:0, timer:300, phases:[
    {r:500,tr:450,t:300},{r:450,tr:380,t:300},{r:380,tr:300,t:300},{r:300,tr:220,t:300},{r:220,tr:150,t:300},{r:150,tr:100,t:300},{r:100,tr:50,t:120}
  ]},
  enemies: [], loot: [], buildings: [], trees: [],
  aliveCount:100, gameTime:0, started:false,
  settings: { volume:70, sensitivity:50, quality:2 }
};

// ============ WEAPONS DATA ============
const WEAPONS = {
  pistol:{name:'Пистолет',icon:'🔫',damage:15,fireRate:400,spread:0.03,magSize:15,reserve:90,range:200,penetration:1,auto:false,slot:1},
  smg:{name:'ПП',icon:'🔫',damage:12,fireRate:80,spread:0.05,magSize:30,reserve:120,range:150,penetration:1,auto:true,slot:1},
  ar:{name:'Штурмовая',icon:'🔫',damage:25,fireRate:100,spread:0.03,magSize:30,reserve:120,range:350,penetration:2,auto:true,slot:2},
  sniper:{name:'Снайперская',icon:'🎯',damage:80,fireRate:1500,spread:0.005,magSize:5,reserve:20,range:600,penetration:4,auto:false,slot:2},
  shotgun:{name:'Дробовик',icon:'💥',damage:20,fireRate:800,spread:0.15,magSize:8,reserve:30,range:50,penetration:1,auto:false,pellets:8,slot:3},
  lmg:{name:'Пулемет',icon:'🔫',damage:22,fireRate:60,spread:0.06,magSize:100,reserve:300,range:300,penetration:2,auto:true,slot:3},
  bow:{name:'Лук',icon:'🏹',damage:35,fireRate:1200,spread:0.02,magSize:1,reserve:10,range:250,penetration:2,auto:false,slot:1}
};

const RARITIES = {Common:'#888',Uncommon:'#44ff44',Rare:'#4488ff',Epic:'#aa44ff',Legendary:'#ffaa00'};

// ============ LOADING ============
let loadProgress = 0;
function updateLoading(p) {
  loadProgress = Math.min(100, p);
  document.getElementById('progress-bar').style.width = loadProgress + '%';
  document.getElementById('progress-text').textContent = Math.floor(loadProgress) + '%';
}

// Particles
const pCanvas = document.getElementById('particles-canvas');
const pCtx = pCanvas.getContext('2d');
let particles = [];
function initParticles() {
  pCanvas.width = window.innerWidth;
  pCanvas.height = window.innerHeight;
  particles = [];
  for(let i=0;i<80;i++){
    particles.push({x:Math.random()*pCanvas.width,y:Math.random()*pCanvas.height,
      vx:(Math.random()-0.5)*0.5,vy:(Math.random()-0.5)*0.5,
      size:Math.random()*3+1,opacity:Math.random()*0.5+0.1});
  }
}
function animateParticles() {
  pCtx.clearRect(0,0,pCanvas.width,pCanvas.height);
  particles.forEach(p=>{
    p.x+=p.vx;p.y+=p.vy;
    if(p.x<0)p.x=pCanvas.width;if(p.x>pCanvas.width)p.x=0;
    if(p.y<0)p.y=pCanvas.height;if(p.y>pCanvas.height)p.y=0;
    pCtx.beginPath();pCtx.arc(p.x,p.y,p.size,0,Math.PI*2);
    pCtx.fillStyle=`rgba(255,107,53,${p.opacity})`;pCtx.fill();
  });
  if(G.state==='loading')requestAnimationFrame(animateParticles);
}

// Loading sequence
function startLoading() {
  initParticles();
  animateParticles();
  const steps = [10,25,40,55,70,85,95,100];
  let i=0;
  const iv=setInterval(()=>{
    if(i<steps.length){updateLoading(steps[i]);i++;}
    else{clearInterval(iv);setTimeout(()=>{hideLoading();},500);}
  },400);
}

function hideLoading() {
  document.getElementById('loading-screen').classList.add('hidden');
  showMenu();
}

// ============ NAVIGATION ============
function showMenu() {
  hideAll();
  document.getElementById('menu-screen').style.display='flex';
  document.getElementById('player-level').textContent=G.player.level;
  G.state='menu';
}
function showModeSelect() { hideAll(); document.getElementById('mode-screen').style.display='flex'; G.state='mode'; }
function showSettings() { hideAll(); document.getElementById('settings-screen').style.display='flex'; G.state='settings'; }
function showStats() {
  hideAll();
  document.getElementById('stats-screen').style.display='flex';
  G.state='stats';
  const s=G.player;
  document.getElementById('stats-grid').innerHTML=`
    <div class="stat-item"><div class="label">Всего игр</div><div class="value">${s.totalGames}</div></div>
    <div class="stat-item"><div class="label">Побед</div><div class="value">${s.totalWins}</div></div>
    <div class="stat-item"><div class="label">Убийств</div><div class="value">${s.totalKills}</div></div>
    <div class="stat-item"><div class="label">Урона нанесено</div><div class="value">${s.totalDamage}</div></div>
    <div class="stat-item"><div class="label">Дистанция (м)</div><div class="value">${Math.floor(s.totalDistance)}</div></div>
    <div class="stat-item"><div class="label">Время (мин)</div><div class="value">${(s.totalTime/60).toFixed(1)}</div></div>
    <div class="stat-item"><div class="label">Рейтинг</div><div class="value">${s.rating}</div></div>
    <div class="stat-item"><div class="label">Уровень</div><div class="value">${s.level}</div></div>`;
}
function hideAll() {
  ['menu-screen','mode-screen','settings-screen','stats-screen','plane-screen','game-hud','game-over-screen','map-full','scope-overlay'].forEach(id=>{
    const el=document.getElementById(id);if(el)el.style.display='none';
  });
}

// Settings
document.getElementById('vol-slider').oninput=function(){G.settings.volume=this.value;document.getElementById('vol-val').textContent=this.value+'%';};
document.getElementById('sens-slider').oninput=function(){G.settings.sensitivity=this.value;document.getElementById('sens-val').textContent=this.value+'%';};
document.getElementById('qual-slider').oninput=function(){
  const v=parseInt(this.value);G.settings.quality=v;
  document.getElementById('qual-val').textContent=['Низкое','Среднее','Высокое'][v-1];
};

// ============ THREE.JS SETUP ============
let scene, camera, renderer, clock;
let terrain, playerMesh, planeMesh;
let keys={}, mouseDown=false, rightMouseDown=false;
let yaw=0, pitch=0;
let gameWorld = {};

function initThree() {
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x87CEEB);
  scene.fog = new THREE.FogExp2(0x87CEEB, 0.002);

  camera = new THREE.PerspectiveCamera(70, window.innerWidth/window.innerHeight, 0.1, 2000);
  camera.position.set(0, 500, 0);

  renderer = new THREE.WebGLRenderer({antialias: true});
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  document.body.appendChild(renderer.domElement);

  clock = new THREE.Clock();

  // Lighting
  const ambient = new THREE.AmbientLight(0x404060, 0.6);
  scene.add(ambient);
  const sun = new THREE.DirectionalLight(0xffeedd, 1.0);
  sun.position.set(200, 400, 100);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -500;
  sun.shadow.camera.right = 500;
  sun.shadow.camera.top = 500;
  sun.shadow.camera.bottom = -500;
  scene.add(sun);

  const hemi = new THREE.HemisphereLight(0x87CEEB, 0x3a5f0b, 0.4);
  scene.add(hemi);

  window.addEventListener('resize', ()=>{
    camera.aspect=window.innerWidth/window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });
}

// ============ TERRAIN GENERATION ============
function generateTerrain() {
  const size = 1000, segments = 100;
  const geo = new THREE.PlaneGeometry(size, size, segments, segments);
  geo.rotateX(-Math.PI/2);
  const verts = geo.attributes.position;

  // Simple noise
  function noise(x, z) {
    return Math.sin(x*0.01)*Math.cos(z*0.01)*20 +
           Math.sin(x*0.03+1)*Math.cos(z*0.02+2)*10 +
           Math.sin(x*0.005)*Math.cos(z*0.005)*40;
  }

  const colors = new Float32Array(verts.count * 3);
  const biomeColors = {
    city: new THREE.Color(0x666666),
    suburb: new THREE.Color(0x5a7a3a),
    forest: new THREE.Color(0x2d5a1e),
    field: new THREE.Color(0x8a7a3a),
    mountain: new THREE.Color(0x888888),
    water: new THREE.Color(0x2266aa)
  };

  for(let i=0; i<verts.count; i++) {
    const x = verts.getX(i);
    const z = verts.getZ(i);
    let h = noise(x, z);

    // Mountains
    const dist = Math.sqrt((x-500)*(x-500)+(z-500)*(z-500));
    if(dist < 100) h += (100-dist)*0.5;

    // Water areas
    if((x>700 && z>700) || (x<100 && z<100)) {
      h = -5;
    }

    verts.setY(i, h);

    // Color based on biome
    let color;
    if(h < -2) color = biomeColors.water;
    else if(h > 30) color = biomeColors.mountain;
    else if((x>200 && x<400 && z>200 && z<400)) color = biomeColors.city;
    else if(Math.sin(x*0.02)*Math.cos(z*0.02) > 0.3) color = biomeColors.forest;
    else if((x>600 && z>600) || (x<200 && z>600)) color = biomeColors.field;
    else color = biomeColors.suburb;

    colors[i*3] = color.r;
    colors[i*3+1] = color.g;
    colors[i*3+2] = color.b;
  }

  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();

  const mat = new THREE.MeshStandardMaterial({vertexColors:true, roughness:0.8, metalness:0.1});
  terrain = new THREE.Mesh(geo, mat);
  terrain.receiveShadow = true;
  scene.add(terrain);
}

function getTerrainHeight(x, z) {
  function noise(x, z) {
    return Math.sin(x*0.01)*Math.cos(z*0.01)*20 +
           Math.sin(x*0.03+1)*Math.cos(z*0.02+2)*10 +
           Math.sin(x*0.005)*Math.cos(z*0.005)*40;
  }
  let h = noise(x, z);
  const dist = Math.sqrt((x-500)*(x-500)+(z-500)*(z-500));
  if(dist < 100) h += (100-dist)*0.5;
  if((x>700 && z>700) || (x<100 && z<100)) h = -5;
  return h;
}

// ============ BUILDINGS ============
function generateBuildings() {
  G.buildings = [];
  const buildingTemplates = [];

  // Create building templates
  for(let i=0; i<8; i++) {
    const w = 15 + Math.random()*25;
    const d = 15 + Math.random()*25;
    const h = 10 + Math.random()*30;
    buildingTemplates.push({w, d, h});
  }

  // City buildings
  for(let i=0; i<40; i++) {
    const x = 200 + Math.random()*200;
    const z = 200 + Math.random()*200;
    const t = buildingTemplates[Math.floor(Math.random()*buildingTemplates.length)];
    createBuilding(x, getTerrainHeight(x,z), z, t.w, t.h, t.d, 'city');
  }

  // Suburb buildings
  for(let i=0; i<50; i++) {
    const x = Math.random()*1000;
    const z = Math.random()*1000;
    const t = buildingTemplates[Math.floor(Math.random()*buildingTemplates.length)];
    createBuilding(x, getTerrainHeight(x,z), z, t.w*0.7, t.h*0.6, t.d*0.7, 'suburb');
  }
}

function createBuilding(x, y, z, w, h, d, type) {
  const geo = new THREE.BoxGeometry(w, h, d);
  let color;
  if(type==='city') color = 0x777777;
  else color = 0x8a7a5a;
  const mat = new THREE.MeshStandardMaterial({color, roughness:0.9});
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y + h/2, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);

  // Windows
  const windowMat = new THREE.MeshStandardMaterial({color:0x334455, emissive:0x112233, emissiveIntensity:0.3});
  for(let wy=3; wy<h-2; wy+=5) {
    for(let wx=-w/2+3; wx<w/2-2; wx+=5) {
      const wg = new THREE.PlaneGeometry(2, 3);
      const wf = new THREE.Mesh(wg, windowMat);
      wf.position.set(x+wx, y+wy, z+d/2+0.1);
      scene.add(wf);
      const wb = new THREE.Mesh(wg, windowMat);
      wb.position.set(x+wx, y+wy, z-d/2-0.1);
      wb.rotation.y = Math.PI;
      scene.add(wb);
    }
  }

  G.buildings.push({x, y, z, w, h, d, mesh, type});
}

// ============ TREES ============
function generateTrees() {
  G.trees = [];
  for(let i=0; i<600; i++) {
    const x = Math.random()*1000;
    const z = Math.random()*1000;
    const y = getTerrainHeight(x, z);
    if(y < 0) continue;

    const trunkH = 3 + Math.random()*4;
    const trunkGeo = new THREE.CylinderGeometry(0.3, 0.5, trunkH, 6);
    const trunkMat = new THREE.MeshStandardMaterial({color:0x5a3a1a});
    const trunk = new THREE.Mesh(trunkGeo, trunkMat);
    trunk.position.set(x, y + trunkH/2, z);
    trunk.castShadow = true;
    scene.add(trunk);

    const leafR = 2 + Math.random()*3;
    const leafGeo = new THREE.SphereGeometry(leafR, 6, 6);
    const leafMat = new THREE.MeshStandardMaterial({color: new THREE.Color().setHSL(0.25+Math.random()*0.1, 0.6, 0.3+Math.random()*0.15)});
    const leaves = new THREE.Mesh(leafGeo, leafMat);
    leaves.position.set(x, y + trunkH + leafR*0.5, z);
    leaves.castShadow = true;
    scene.add(leaves);

    G.trees.push({x, y, z, trunk, leaves, health:100});
  }
}

// ============ LOOT ============
function generateLoot() {
  G.loot = [];
  const weaponTypes = Object.keys(WEAPONS);
  const rarities = ['Common','Common','Common','Uncommon','Uncommon','Rare','Epic','Legendary'];

  for(let i=0; i<200; i++) {
    const x = Math.random()*1000;
    const z = Math.random()*1000;
    const y = getTerrainHeight(x, z) + 1;

    const isWeapon = Math.random() > 0.4;
    let item;

    if(isWeapon) {
      const wt = weaponTypes[Math.floor(Math.random()*weaponTypes.length)];
      const rarity = rarities[Math.floor(Math.random()*rarities.length)];
      item = {type:'weapon', weaponType:wt, rarity, x, y, z, mesh:null};
    } else {
      const roll = Math.random();
      if(roll < 0.3) item = {type:'armor', level:Math.floor(Math.random()*3)+1, x, y, z, mesh:null};
      else if(roll < 0.6) item = {type:'medkit', x, y, z, mesh:null};
      else if(roll < 0.8) item = {type:'ammo', x, y, z, mesh:null};
      else item = {type:'grenade', x, y, z, mesh:null};
    }

    // Visual
    const geo = new THREE.BoxGeometry(0.8, 0.8, 0.8);
    let color;
    if(item.type==='weapon') color = RARITIES[item.rarity] || '#888';
    else if(item.type==='armor') color = '#4488ff';
    else if(item.type==='medkit') color = '#ff4444';
    else if(item.type==='ammo') color = '#ffaa00';
    else color = '#44ff44';

    const mat = new THREE.MeshStandardMaterial({color, emissive:color, emissiveIntensity:0.3});
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(x, y, z);
    scene.add(mesh);
    item.mesh = mesh;

    G.loot.push(item);
  }
}

// ============ ENEMIES (AI) ============
function generateEnemies() {
  G.enemies = [];
  const difficulties = ['Easy','Easy','Easy','Medium','Medium','Medium','Medium','Hard','Hard','Hard'];

  for(let i=0; i<99; i++) {
    let x, z;
    do {
      x = 50 + Math.random()*900;
      z = 50 + Math.random()*900;
    } while(Math.sqrt((x-500)*(x-500)+(z-500)*(z-500)) < 50);

    const y = getTerrainHeight(x, z);
    const diff = difficulties[Math.floor(Math.random()*difficulties.length)];

    const enemy = {
      id: i, x, y, z, vx:0, vy:0, vz:0,
      hp:100, maxHp:100, armor:Math.random()*50,
      difficulty: diff,
      state: 'patrol', // patrol, search, combat, loot, flee, heal
      targetX: x + (Math.random()-0.5)*200,
      targetZ: z + (Math.random()-0.5)*200,
      weapon: weaponTypes[Math.floor(Math.random()*weaponTypes.length)],
      ammo: 30,
      lastShot: 0,
      alertRange: diff==='Easy'?30:diff==='Medium'?50:80,
      accuracy: diff==='Easy'?0.3:diff==='Medium'?0.6:0.85,
      reactionTime: diff==='Easy'?2000:diff==='Medium'?1000:500,
      lastReaction: 0,
      isAlive: true,
      mesh: null,
      patrolTimer: 0,
      lootTimer: 0,
      healTimer: 0,
      team: Math.floor(Math.random()*25) // for squad/duo
    };

    // Create enemy mesh (simple capsule)
    const eGeo = new THREE.CapsuleGeometry(0.5, 1.5, 4, 8);
    const eMat = new THREE.MeshStandardMaterial({
      color: diff==='Easy'?0x44aa44:diff==='Medium'?0xaaaa44:0xaa4444
    });
    enemy.mesh = new THREE.Mesh(eGeo, eMat);
    enemy.mesh.position.set(x, y+1.25, z);
    enemy.mesh.castShadow = true;
    scene.add(enemy.mesh);

    G.enemies.push(enemy);
  }
}

const weaponTypes = Object.keys(WEAPONS);

// ============ PLANE ============
let planePos = {x:-200, y:400, z:0};
let planeAngle = 0;
let planeJumped = false;

function initPlane() {
  // Create plane
  const planeGroup = new THREE.Group();

  // Fuselage
  const fuselageGeo = new THREE.CylinderGeometry(1.5, 1.5, 12, 8);
  fuselageGeo.rotateZ(Math.PI/2);
  const fuselageMat = new THREE.MeshStandardMaterial({color:0xcccccc});
  const fuselage = new THREE.Mesh(fuselageGeo, fuselageMat);
  planeGroup.add(fuselage);

  // Wings
  const wingGeo = new THREE.BoxGeometry(3, 0.2, 14);
  const wingMat = new THREE.MeshStandardMaterial({color:0xaaaaaa});
  const wings = new THREE.Mesh(wingGeo, wingMat);
  planeGroup.add(wings);

  // Tail
  const tailGeo = new THREE.BoxGeometry(2, 3, 0.3);
  const tail = new THREE.Mesh(tailGeo, wingMat);
  tail.position.set(-5, 1.5, 0);
  planeGroup.add(tail);

  planeMesh = planeGroup;
  planeMesh.position.set(planePos.x, planePos.y, planePos.z);
  scene.add(planeMesh);

  // Draw minimap
  drawPlaneMinimap();
}

function drawPlaneMinimap() {
  const mc = document.getElementById('minimap-canvas');
  const mctx = mc.getContext('2d');
  mctx.fillStyle = '#1a3a1a';
  mctx.fillRect(0,0,200,200);

  // Safe zone circle
  mctx.strokeStyle = '#4488ff';
  mctx.lineWidth = 2;
  mctx.beginPath();
  mctx.arc(100, 100, 100, 0, Math.PI*2);
  mctx.stroke();

  // Plane path
  mctx.strokeStyle = '#ff6b35';
  mctx.lineWidth = 1;
  mctx.setLineDash([5,5]);
  mctx.beginPath();
  mctx.moveTo(10, 100);
  mctx.lineTo(190, 100);
  mctx.stroke();
  mctx.setLineDash([]);

  // Plane icon
  mctx.fillStyle = '#ff6b35';
  mctx.beginPath();
  const px = 10 + (planePos.x + 200) / 1000 * 180;
  mctx.arc(px, 100, 4, 0, Math.PI*2);
  mctx.fill();

  // Buildings
  mctx.fillStyle = '#666';
  G.buildings.forEach(b => {
    const bx = b.x / 1000 * 200;
    const bz = b.z / 1000 * 200;
    mctx.fillRect(bx-2, bz-2, 4, 4);
  });
}

// ============ GAME START ============
function startGame(mode) {
  G.mode = mode;
  hideAll();
  document.getElementById('plane-screen').style.display='flex';
  G.state='plane';
  planeJumped = false;
  planePos = {x:-200, y:400, z:0};
  planeAngle = 0;

  // Reset player
  G.player.hp = 100;
  G.player.armor = 0;
  G.player.x = 0;
  G.player.y = 500;
  G.player.z = 0;
  G.player.vx = 0;
  G.player.vy = 0;
  G.player.vz = 0;
  G.player.isAlive = true;
  G.player.kills = 0;
  G.player.damageDealt = 0;
  G.player.weapons = [];
  G.player.currentWeapon = -1;
  G.player.inventory = [];
  G.player.grenades = 3;
  G.player.medkits = 2;
  G.player.isSprinting = false;
  G.player.isCrouching = false;
  G.player.isProne = false;
  G.player.isAiming = false;
  G.player.isParachuting = false;
  G.player.totalDistance = 0;

  G.aliveCount = mode==='solo'?100:mode==='duo'?100:100;
  G.gameTime = 0;
  G.zone.phase = 0;
  G.zone.radius = 500;
  G.zone.targetRadius = 500;
  G.zone.timer = 300;

  // Init Three.js if not done
  if(!renderer) initThree();

  // Generate world
  generateTerrain();
  generateBuildings();
  generateTrees();
  generateLoot();
  generateEnemies();
  initPlane();

  // Player start position on plane
  camera.position.set(planePos.x, planePos.y-2, planePos.z+5);
  yaw = 0; pitch = 0;

  addChatMessage('Система', `Режим: ${mode.toUpperCase()}. 100 игроков в игре!`);
}

function jumpFromPlane() {
  if(planeJumped) return;
  planeJumped = true;
  hideAll();
  document.getElementById('game-hud').style.display='block';
  G.state='game';
  G.started = true;

  G.player.x = planePos.x;
  G.player.y = planePos.y;
  G.player.z = planePos.z;
  G.player.vx = 3; // forward velocity
  G.player.vy = 0;
  G.player.vz = 0;

  // Give starting pistol
  G.player.weapons.push({...WEAPONS.pistol, currentAmmo:15, reserveAmmo:90});
  G.player.currentWeapon = 0;

  // Remove plane
  scene.remove(planeMesh);

  // Camera setup for FPS
  camera.position.set(G.player.x, G.player.y+1.7, G.player.z);
  yaw = 0; pitch = 0;

  // Lock pointer
  renderer.domElement.requestPointerLock();
}

// ============ INPUT ============
document.addEventListener('keydown', e => {
  keys[e.code] = true;

  if(G.state==='plane' && e.code==='Space') { e.preventDefault(); jumpFromPlane(); }
  if(G.state==='game') {
    if(e.code==='KeyM') toggleMap();
    if(e.code==='KeyC') toggleCrouch();
    if(e.code==='ControlLeft' || e.code==='ControlRight') toggleProne();
    if(e.code==='ShiftLeft' || e.code==='ShiftRight') G.player.isSprinting = true;
    if(e.code==='Digit1') switchWeapon(0);
    if(e.code==='Digit2') switchWeapon(1);
    if(e.code==='Digit3') switchWeapon(2);
    if(e.code==='Digit4') switchWeapon(3);
    if(e.code==='Digit5') switchWeapon(4);
    if(e.code==='KeyR') reloadWeapon();
    if(e.code==='KeyG') throwGrenade();
    if(e.code==='KeyF') interact();
    if(e.code==='Space') { e.preventDefault(); if(!G.player.isCrouching && !G.player.isProne) G.player.vy = 8; }
  }
});

document.addEventListener('keyup', e => {
  keys[e.code] = false;
  if(e.code==='ShiftLeft' || e.code==='ShiftRight') G.player.isSprinting = false;
});

document.addEventListener('mousedown', e => {
  if(G.state==='game') {
    if(e.button===0) mouseDown=true;
    if(e.button===2) { rightMouseDown=true; G.player.isAiming=true; document.getElementById('scope-overlay').style.display='block'; }
  }
});

document.addEventListener('mouseup', e => {
  if(e.button===0) mouseDown=false;
  if(e.button===2) { rightMouseDown=false; G.player.isAiming=false; document.getElementById('scope-overlay').style.display='none'; }
});

document.addEventListener('mousemove', e => {
  if(G.state==='game' && document.pointerLockElement===renderer.domElement) {
    const sens = G.settings.sensitivity / 1000;
    yaw -= e.movementX * sens;
    pitch -= e.movementY * sens;
    pitch = Math.max(-Math.PI/2.5, Math.min(Math.PI/2.5, pitch));
  }
});

document.addEventListener('contextmenu', e => e.preventDefault());

function toggleCrouch() {
  if(G.player.isProne) { G.player.isProne=false; G.player.isCrouching=true; }
  else if(G.player.isCrouching) { G.player.isCrouching=false; }
}
function toggleProne() {
  if(G.player.isCrouching) { G.player.isCrouching=false; G.player.isProne=true; }
  else if(!G.player.isProne) { G.player.isProne=true; }
}
function switchWeapon(idx) {
  if(idx < G.player.weapons.length) {
    G.player.currentWeapon = idx;
    updateHUD();
  }
}
function reloadWeapon() {
  const w = G.player.weapons[G.player.currentWeapon];
  if(!w || w.currentAmmo >= w.magSize) return;
  const needed = w.magSize - w.currentAmmo;
  const available = Math.min(needed, w.reserveAmmo);
  w.currentAmmo += available;
  w.reserveAmmo -= available;
  updateHUD();
}
function throwGrenade() {
  if(G.player.grenades <= 0) return;
  G.player.grenades--;
  // Simple grenade: damage in area
  G.enemies.forEach(e => {
    if(!e.isAlive) return;
    const dx = e.x - G.player.x, dz = e.z - G.player.z;
    const dist = Math.sqrt(dx*dx+dz*dz);
    if(dist < 15) {
      const dmg = Math.floor(80 * (1 - dist/15));
      damageEnemy(e, dmg);
    }
  });
  addChatMessage('Система', 'Граната брошена!');
  updateHUD();
}
function interact() {
  // Pick up nearby loot
  G.loot = G.loot.filter(item => {
    const dx = item.x - G.player.x, dz = item.z - G.player.z;
    if(Math.sqrt(dx*dx+dz*dz) < 5) {
      pickupItem(item);
      scene.remove(item.mesh);
      return false;
    }
    return true;
  });
}
function pickupItem(item) {
  const notif = document.getElementById('pickup-notification');
  if(item.type === 'weapon') {
    const w = WEAPONS[item.weaponType];
    if(G.player.currentWeapon < 2) {
      G.player.weapons[G.player.currentWeapon+1] = {...w, currentAmmo:w.magSize, reserveAmmo:w.reserveAmmo};
      G.player.currentWeapon = G.player.currentWeapon+1;
      notif.textContent = `${w.name} [${item.rarity}]`;
    } else {
      G.player.weapons[G.player.currentWeapon] = {...w, currentAmmo:w.magSize, reserveAmmo:w.reserveAmmo};
      notif.textContent = `${w.name} [${item.rarity}]`;
    }
  } else if(item.type === 'armor') {
    G.player.armor = Math.min(G.player.maxArmor, G.player.armor + item.level * 34);
    notif.textContent = `Броня ур.${item.level} (+${item.level*34})`;
  } else if(item.type === 'medkit') {
    G.player.medkits++;
    notif.textContent = 'Аптечка получена!';
  } else if(item.type === 'ammo') {
    if(G.player.currentWeapon >= 0) {
      G.player.weapons[G.player.currentWeapon].reserveAmmo += 60;
      notif.textContent = 'Патроны +60';
    }
  } else if(item.type === 'grenade') {
    G.player.grenades += 2;
    notif.textContent = 'Гранаты +2';
  }
  notif.style.display='block';
  setTimeout(()=>notif.style.display='none', 2000);
  updateHUD();
}

function toggleMap() {
  const map = document.getElementById('map-full');
  if(map.style.display === 'block') {
    map.style.display = 'none';
  } else {
    map.style.display = 'block';
    drawFullMap();
  }
}

function drawFullMap() {
  const mc = document.getElementById('map-full-canvas');
  mc.width = window.innerWidth;
  mc.height = window.innerHeight;
  const mctx = mc.getContext('2d');

  // Background
  mctx.fillStyle = '#2a4a2a';
  mctx.fillRect(0,0,mc.width,mc.height);

  const scale = mc.width / 1000;

  // Biome colors
  mctx.fillStyle = '#3a5a2a'; // suburb
  mctx.fillRect(0,0,mc.width,mc.height);

  // Forest areas
  mctx.fillStyle = '#1a3a1a';
  for(let i=0;i<100;i++){
    const fx=Math.random()*mc.width, fz=Math.random()*mc.height;
    mctx.beginPath();mctx.arc(fx,fz,10+Math.random()*20,0,Math.PI*2);mctx.fill();
  }

  // Water
  mctx.fillStyle = '#2266aa';
  mctx.fillRect(mc.width*0.7, mc.height*0.7, mc.width*0.3, mc.height*0.3);
  mctx.fillRect(0, 0, mc.width*0.1, mc.height*0.1);

  // Buildings
  mctx.fillStyle = '#666';
  G.buildings.forEach(b => {
    mctx.fillRect(b.x*scale-3, b.z*scale-3, 6, 6);
  });

  // Safe zone
  mctx.strokeStyle = '#4488ff';
  mctx.lineWidth = 3;
  mctx.beginPath();
  mctx.arc(G.zone.x*scale, G.zone.z*scale, G.zone.radius*scale, 0, Math.PI*2);
  mctx.stroke();

  // Zone warning (red)
  if(G.zone.targetRadius < G.zone.radius) {
    mctx.strokeStyle = '#ff4444';
    mctx.lineWidth = 2;
    mctx.setLineDash([10,5]);
    mctx.beginPath();
    mctx.arc(G.zone.x*scale, G.zone.z*scale, G.zone.targetRadius*scale, 0, Math.PI*2);
    mctx.stroke();
    mctx.setLineDash([]);
  }

  // Enemies (red dots)
  mctx.fillStyle = '#ff4444';
  G.enemies.forEach(e => {
    if(!e.isAlive) return;
    const dx = e.x - G.player.x, dz = e.z - G.player.z;
    const dist = Math.sqrt(dx*dx+dz*dz);
    if(dist < 100) { // Only show nearby enemies
      mctx.beginPath();
      mctx.arc(e.x*scale, e.z*scale, 3, 0, Math.PI*2);
      mctx.fill();
    }
  });

  // Player (green dot)
  mctx.fillStyle = '#44ff44';
  mctx.beginPath();
  mctx.arc(G.player.x*scale, G.player.z*scale, 5, 0, Math.PI*2);
  mctx.fill();
  mctx.strokeStyle = '#fff';
  mctx.lineWidth = 2;
  mctx.stroke();

  // Player direction
  mctx.strokeStyle = '#44ff44';
  mctx.lineWidth = 2;
  mctx.beginPath();
  mctx.moveTo(G.player.x*scale, G.player.z*scale);
  mctx.lineTo(G.player.x*scale + Math.sin(yaw)*20, G.player.z*scale + Math.cos(yaw)*20);
  mctx.stroke();

  // Title
  mctx.fillStyle = '#fff';
  mctx.font = 'bold 24px Segoe UI';
  mctx.fillText('КАРТА - REG2', 20, 40);
  mctx.font = '14px Segoe UI';
  mctx.fillStyle = '#888';
  mctx.fillText(`Игроков: ${G.aliveCount} | Фаза зоны: ${G.zone.phase+1}/7`, 20, 65);
}

// ============ COMBAT ============
function damageEnemy(enemy, damage) {
  if(!enemy.isAlive) return;

  // Armor reduction
  const armorReduction = enemy.armor / (enemy.armor + 100);
  damage *= (1 - armorReduction * 0.5);
  enemy.armor = Math.max(0, enemy.armor - damage * 0.3);

  enemy.hp -= damage;
  G.player.damageDealt += damage;
  G.player.totalDamage += damage;

  if(enemy.hp <= 0) {
    enemy.isAlive = false;
    G.player.kills++;
    G.aliveCount--;
    G.player.rating += 10;
    scene.remove(enemy.mesh);
    addChatMessage('Система', `Вы убили игрока! (${G.player.kills} убийств)`);
    updateHUD();

    if(G.aliveCount <= 1) {
      endGame(true);
    }
  }
}

function damagePlayer(damage) {
  if(!G.player.isAlive) return;

  // Armor absorbs first
  if(G.player.armor > 0) {
    const armorAbsorb = Math.min(G.player.armor, damage * 0.6);
    G.player.armor -= armorAbsorb;
    damage -= armorAbsorb;
  }

  G.player.hp -= damage;

  // Damage flash
  const overlay = document.getElementById('damage-overlay');
  overlay.classList.add('active');
  setTimeout(()=>overlay.classList.remove('active'), 200);

  if(G.player.hp <= 0) {
    G.player.hp = 0;
    G.player.isAlive = false;
    endGame(false);
  }
  updateHUD();
}

function shoot() {
  const w = G.player.weapons[G.player.currentWeapon];
  if(!w || w.currentAmmo <= 0) return;

  w.currentAmmo--;
  updateHUD();

  const spread = w.spread * (G.player.isAiming ? 0.3 : 1) * (G.player.isSprinting ? 2 : 1);
  const dir = new THREE.Vector3(
    Math.sin(yaw) * Math.cos(pitch) + (Math.random()-0.5)*spread,
    -Math.sin(pitch) + (Math.random()-0.5)*spread,
    Math.cos(yaw) * Math.cos(pitch) + (Math.random()-0.5)*spread
  ).normalize();

  // Raycast
  const raycaster = new THREE.Raycaster();
  raycaster.set(camera.position.clone(), dir);

  // Check enemy hits
  let hitEnemy = false;
  G.enemies.forEach(enemy => {
    if(!enemy.isAlive) return;
    const ePos = new THREE.Vector3(enemy.x, enemy.y+1.5, enemy.z);
    const toEnemy = ePos.clone().sub(camera.position);
    const proj = toEnemy.dot(dir);
    if(proj < 0 || proj > w.range) return;

    const closest = dir.clone().multiplyScalar(proj).add(camera.position);
    const dist = closest.distanceTo(ePos);

    if(dist < 1.5) {
      let dmg = w.damage;
      // Headshot bonus
      if(Math.random() < 0.2) { dmg *= 2; }
      // Limb penalty
      if(Math.random() < 0.3) { dmg *= 0.5; }

      damageEnemy(enemy, dmg);
      hitEnemy = true;

      // Alert nearby enemies
      G.enemies.forEach(other => {
        if(!other.isAlive || other === enemy) return;
        const d = Math.sqrt((other.x-enemy.x)**2 + (other.z-enemy.z)**2);
        if(d < 100) {
          other.state = 'combat';
          other.targetX = G.player.x;
          other.targetZ = G.player.z;
        }
      });
    }
  });

  // Muzzle flash effect
  const flash = new THREE.PointLight(0xffaa00, 2, 10);
  flash.position.copy(camera.position);
  scene.add(flash);
  setTimeout(()=>scene.remove(flash), 50);
}

// ============ AI UPDATE ============
function updateAI(dt) {
  G.enemies.forEach(enemy => {
    if(!enemy.isAlive) return;

    const dx = G.player.x - enemy.x;
    const dz = G.player.z - enemy.z;
    const distToPlayer = Math.sqrt(dx*dx + dz*dz);

    // Zone damage
    const dzDist = Math.sqrt((enemy.x-G.zone.x)**2 + (enemy.z-G.zone.z)**2);
    if(dzDist > G.zone.radius) {
      enemy.hp -= 5 * dt;
      if(enemy.hp <= 0) {
        enemy.isAlive = false;
        G.aliveCount--;
        scene.remove(enemy.mesh);
        if(G.aliveCount <= 1 && G.player.isAlive) endGame(true);
      }
      return;
    }

    // State machine
    switch(enemy.state) {
      case 'patrol':
        enemy.patrolTimer -= dt;
        if(enemy.patrolTimer <= 0) {
          enemy.targetX = enemy.x + (Math.random()-0.5)*200;
          enemy.targetZ = enemy.z + (Math.random()-0.5)*200;
          enemy.patrolTimer = 5 + Math.random()*10;
        }
        moveTowards(enemy, enemy.targetX, enemy.targetZ, 3);
        // Check for player
        if(distToPlayer < enemy.alertRange) {
          enemy.state = 'combat';
          enemy.lastReaction = Date.now();
        }
        // Check for loot
        if(enemy.lootTimer <= 0) {
          G.loot.forEach(item => {
            const id = Math.sqrt((item.x-enemy.x)**2+(item.z-enemy.z)**2);
            if(id < 5) {
              enemy.lootTimer = 3;
              // Enemy picks up loot (simplified)
            }
          });
        }
        break;

      case 'combat':
        if(distToPlayer > enemy.alertRange * 1.5) {
          enemy.state = 'patrol';
          break;
        }
        if(distToPlayer < 5) {
          // Too close, try to reposition
          moveTowards(enemy, enemy.x + (Math.random()-0.5)*20, enemy.z + (Math.random()-0.5)*20, 4);
        } else {
          // Face player and shoot
          const angle = Math.atan2(dx, dz);
          enemy.mesh.rotation.y = angle;
          moveTowards(enemy, G.player.x, G.player.z, 2);

          const now = Date.now();
          if(now - enemy.lastShot > 500 && distToPlayer < enemy.alertRange) {
            enemy.lastShot = now;
            // Enemy shoots
            if(Math.random() < enemy.accuracy * 0.3) {
              const dmg = 8 + Math.random()*12;
              damagePlayer(dmg);
            }
          }
        }
        break;

      case 'loot':
        enemy.lootTimer -= dt;
        if(enemy.lootTimer <= 0) enemy.state = 'patrol';
        break;

      case 'heal':
        enemy.healTimer -= dt;
        if(enemy.hp >= 80) { enemy.state = 'patrol'; break; }
        enemy.hp += 10 * dt;
        if(enemy.healTimer <= 0) enemy.state = 'patrol';
        break;
    }

    // Heal if low
    if(enemy.hp < 30 && enemy.state === 'patrol' && Math.random() < 0.01) {
      enemy.state = 'heal';
      enemy.healTimer = 3;
    }

    // Update mesh position
    enemy.mesh.position.set(enemy.x, getTerrainHeight(enemy.x, enemy.z) + 1.25, enemy.z);

    // Gravity
    enemy.vy = (enemy.vy || 0) - 20 * dt;
    enemy.y += enemy.vy * dt;
    const groundY = getTerrainHeight(enemy.x, enemy.z);
    if(enemy.y < groundY) { enemy.y = groundY; enemy.vy = 0; }
  });
}

function moveTowards(entity, tx, tz, speed) {
  const dx = tx - entity.x;
  const dz = tz - entity.z;
  const dist = Math.sqrt(dx*dx + dz*dz);
  if(dist > 1) {
    entity.x += (dx/dist) * speed * dt;
    entity.z += (dz/dist) * speed * dt;
  }
}

// ============ PLAYER UPDATE ============
function updatePlayer(dt) {
  if(!G.player.isAlive) return;

  const p = G.player;

  // Movement speed
  let speed = p.speed;
  if(p.isSprinting) speed = p.sprintSpeed;
  if(p.isCrouching) speed = p.crouchSpeed;
  if(p.isProne) speed = p.proneSpeed;

  const forward = new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));
  const right = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));

  let moveX = 0, moveZ = 0;
  if(keys['KeyW']) { moveX += forward.x; moveZ += forward.z; }
  if(keys['KeyS']) { moveX -= forward.x; moveZ -= forward.z; }
  if(keys['KeyA']) { moveX -= right.x; moveZ -= right.z; }
  if(keys['KeyD']) { moveX += right.x; moveZ += right.z; }

  const moveLen = Math.sqrt(moveX*moveX + moveZ*moveZ);
  if(moveLen > 0) {
    moveX /= moveLen; moveZ /= moveLen;
    p.x += moveX * speed * dt;
    p.z += moveZ * speed * dt;
    p.totalDistance += speed * dt;
  }

  // Boundaries
  p.x = Math.max(0, Math.min(1000, p.x));
  p.z = Math.max(0, Math.min(1000, p.z));

  // Gravity & Parachute
  if(!p.isParachuting) {
    p.vy = (p.vy || 0) - 20 * dt;
  } else {
    p.vy = (p.vy || 0) - 2 * dt; // Slow fall
  }

  p.y += p.vy * dt;
  const groundY = getTerrainHeight(p.x, p.z);

  if(p.y <= groundY + 1.7) {
    p.y = groundY + 1.7;
    p.vy = 0;

    // Parachute auto-deploy at 200m
    if(p.y > 200 && !p.isParachuting) {
      // Don't auto-deploy near ground
    }
    if(p.y > 200 && p.vy < -5) {
      p.isParachuting = true;
      addChatMessage('Система', 'Парашют развернут!');
    }
  }

  // Camera
  const camHeight = p.isProne ? 0.8 : p.isCrouching ? 1.2 : 1.7;
  camera.position.set(p.x, p.y + camHeight, p.z);

  // Camera rotation
  const euler = new THREE.Euler(pitch, yaw, 0, 'YXZ');
  camera.quaternion.setFromEuler(euler);

  // Shooting
  if(mouseDown && G.player.currentWeapon >= 0) {
    const w = G.player.weapons[G.player.currentWeapon];
    if(w && w.auto) {
      const now = Date.now();
      if(now - (p.lastShot || 0) > w.fireRate) {
        p.lastShot = now;
        shoot();
      }
    }
  }
  if(mouseDown && G.player.currentWeapon >= 0 && !w?.auto) {
    // Semi-auto: shoot on press (handled by mousedown)
  }

  // Zone damage
  const dzDist = Math.sqrt((p.x-G.zone.x)**2 + (p.z-G.zone.z)**2);
  if(dzDist > G.zone.radius) {
    damagePlayer(5 * dt);
    document.getElementById('zone-warning').style.display = 'block';
  } else {
    document.getElementById('zone-warning').style.display = 'none';
  }

  // Update enemy meshes
  G.enemies.forEach(e => {
    if(e.isAlive) {
      e.mesh.position.set(e.x, getTerrainHeight(e.x, e.z) + 1.25, e.z);
      // Face direction of movement
      if(e.state === 'patrol' || e.state === 'combat') {
        const angle = Math.atan2(e.targetX - e.x, e.targetZ - e.z);
        e.mesh.rotation.y = angle;
      }
    }
  });

  // Animate loot
  G.loot.forEach(item => {
    if(item.mesh) {
      item.mesh.rotation.y += dt * 2;
      item.mesh.position.y = item.y + Math.sin(Date.now()*0.003) * 0.3;
    }
  });

  // Auto-pickup nearby items
  G.loot = G.loot.filter(item => {
    const dx = item.x - p.x, dz = item.z - p.z;
    if(Math.sqrt(dx*dx+dz*dz) < 3 && item.type !== 'weapon') {
      pickupItem(item);
      scene.remove(item.mesh);
      return false;
    }
    return true;
  });
}

// ============ ZONE UPDATE ============
function updateZone(dt) {
  G.zone.timer -= dt;

  if(G.zone.timer <= 0 && G.zone.phase < G.zone.phases.length) {
    G.zone.phase++;
    if(G.zone.phase < G.zone.phases.length) {
      G.zone.targetRadius = G.zone.phases[G.zone.phase].tr;
      G.zone.timer = G.zone.phases[G.zone.phase].t;
      addChatMessage('Система', `Зона сжимается! Фаза ${G.zone.phase+1}`);
    }
  }

  // Smooth zone shrink
  if(G.zone.radius > G.zone.targetRadius) {
    G.zone.radius -= (G.zone.radius - G.zone.targetRadius) * dt * 0.1;
  }

  // Update zone timer display
  const mins = Math.floor(G.zone.timer / 60);
  const secs = Math.floor(G.zone.timer % 60);
  document.getElementById('zone-timer').textContent = `${mins}:${secs.toString().padStart(2,'0')}`;
  document.getElementById('zone-phase').textContent = `Фаза ${G.zone.phase+1}/7`;
  document.getElementById('alive-count').textContent = G.aliveCount;
}

// ============ HUD UPDATE ============
function updateHUD() {
  const p = G.player;
  document.getElementById('health-bar').style.width = (p.hp/p.maxHp*100) + '%';
  document.getElementById('health-text').textContent = `${Math.ceil(p.hp)}/${p.maxHp}`;
  document.getElementById('armor-bar').style.width = (p.armor/p.maxArmor*100) + '%';
  document.getElementById('armor-text').textContent = `${Math.ceil(p.armor)}/${p.maxArmor}`;

  const w = p.weapons[p.currentWeapon];
  if(w) {
    document.getElementById('weapon-name').textContent = w.name;
    document.getElementById('ammo-current').textContent = w.currentAmmo;
    document.getElementById('ammo-reserve').textContent = w.reserveAmmo;
  }

  document.getElementById('kill-count').textContent = p.kills;

  // Update slots
  for(let i=0; i<5; i++) {
    const slotEl = document.getElementById('slot-'+(i+1));
    const slotDiv = slotEl.parentElement;
    slotDiv.classList.toggle('active', i === p.currentWeapon);
    if(i < p.weapons.length) {
      slotEl.textContent = p.weapons[i].icon;
    } else if(i === 3) {
      slotEl.textContent = '💣' + p.grenades;
    } else if(i === 4) {
      slotEl.textContent = '🏥' + p.medkits;
    } else {
      slotEl.textContent = '';
    }
  }
}

// ============ CHAT ============
function addChatMessage(name, text) {
  const box = document.getElementById('chat-box');
  const msg = document.createElement('div');
  msg.className = 'hud-chat-msg';
  msg.innerHTML = `<span class="name">${name}:</span> ${text}`;
  box.appendChild(msg);
  box.scrollTop = box.scrollHeight;

  // Limit messages
  while(box.children.length > 20) box.removeChild(box.firstChild);
}

// ============ GAME OVER ============
function endGame(victory) {
  G.state = 'gameover';
  G.started = false;

  const p = G.player;
  p.totalGames++;
  p.totalKills += p.kills;
  p.totalTime += G.gameTime;

  if(victory) {
    p.rating += 500;
    p.totalWins++;
  }

  // Level up check
  const newLevel = Math.floor(p.rating / 100) + 1;
  if(newLevel > p.level) p.level = newLevel;

  // Save to localStorage
  saveStats();

  const goScreen = document.getElementById('game-over-screen');
  goScreen.style.display = 'flex';

  const title = document.getElementById('go-title');
  if(victory) {
    title.textContent = 'ПОБЕДА!';
    title.className = 'game-over-title victory';
  } else {
    title.textContent = 'ВЫБЫЛ';
    title.className = 'game-over-title defeat';
  }

  document.getElementById('go-stats').innerHTML = `
    <div class="stat-item"><div class="label">Позиция</div><div class="value">${victory?'#1':(G.aliveCount+1)+'-е'}</div></div>
    <div class="stat-item"><div class="label">Убийства</div><div class="value">${p.kills}</div></div>
    <div class="stat-item"><div class="label">Урон</div><div class="value">${Math.floor(p.damageDealt)}</div></div>
    <div class="stat-item"><div class="label">Время</div><div class="value">${(G.gameTime/60).toFixed(1)} мин</div></div>
    <div class="stat-item"><div class="label">Дистанция</div><div class="value">${Math.floor(p.totalDistance)} м</div></div>
    <div class="stat-item"><div class="label">Предметов</div><div class="value">${p.weapons.length + p.grenades + p.medkits}</div></div>`;

  const ratingChange = victory ? '+500' : (p.kills > 0 ? '+'+p.kills*10 : '-10');
  document.getElementById('go-rating').textContent = `Рейтинг: ${p.rating} (${ratingChange})`;
}

function saveStats() {
  localStorage.setItem('reg2_stats', JSON.stringify({
    totalKills: G.player.totalKills,
    totalWins: G.player.totalWins,
    totalGames: G.player.totalGames,
    totalDamage: G.player.totalDamage,
    totalDistance: G.player.totalDistance,
    totalTime: G.player.totalTime,
    rating: G.player.rating,
    level: G.player.level
  }));
}

function loadStats() {
  const data = localStorage.getItem('reg2_stats');
  if(data) {
    const s = JSON.parse(data);
    G.player.totalKills = s.totalKills || 0;
    G.player.totalWins = s.totalWins || 0;
    G.player.totalGames = s.totalGames || 0;
    G.player.totalDamage = s.totalDamage || 0;
    G.player.totalDistance = s.totalDistance || 0;
    G.player.totalTime = s.totalTime || 0;
    G.player.rating = s.rating || 0;
    G.player.level = s.level || 1;
  }
}

// ============ MAIN LOOP ============
let dt = 0;
function gameLoop() {
  requestAnimationFrame(gameLoop);
  dt = Math.min(clock.getDelta(), 0.05);
  G.gameTime += dt;

  if(G.state === 'plane') {
    // Animate plane
    planePos.x += 3 * dt;
    planeAngle += dt * 0.1;
    if(planeMesh) {
      planeMesh.position.set(planePos.x, planePos.y + Math.sin(planeAngle)*5, planePos.z);
      planeMesh.rotation.y = Math.sin(planeAngle*0.5)*0.1;
    }
    camera.position.set(planePos.x, planePos.y-2, planePos.z+5);
    yaw = Math.PI; // Face forward

    // Update plane info
    document.getElementById('plane-speed').textContent = '150';
    document.getElementById('plane-alt').textContent = Math.floor(400 + Math.sin(planeAngle)*10);
    document.getElementById('plane-players').textContent = G.aliveCount;

    drawPlaneMinimap();
  }

  if(G.state === 'game' && G.started) {
    updatePlayer(dt);
    updateAI(dt);
    updateZone(dt);
    updateHUD();

    // Camera follows player
    camera.position.set(G.player.x, G.player.y + (G.player.isProne?0.8:G.player.isCrouching?1.2:1.7), G.player.z);
    const euler = new THREE.Euler(pitch, yaw, 0, 'YXZ');
    camera.quaternion.setFromEuler(euler);
  }

  renderer.render(scene, camera);
}

// ============ INIT ============
loadStats();
startLoading();
gameLoop();
</script>
